-- WAKILISHA APPLICATION EXTENSION AUTHORITY --
-- These extensions are part of the production schema contract but are not
-- reconstructed by a custom-schema-only pg_dump.
--
-- WAKILISHA-owned extension namespaces:
--   fuzzystrmatch -> public
--   pg_trgm       -> public
--   vector        -> public
--
-- pg_net is Supabase platform authority. Production currently records its
-- extension namespace as public, while local Supabase may preinstall the same
-- extension under different extension metadata. WAKILISHA's actual contract is
-- the stable net.http_get / net.http_post API, so replay verifies that surface.
--
CREATE EXTENSION IF NOT EXISTS "fuzzystrmatch" WITH SCHEMA "public";
CREATE EXTENSION IF NOT EXISTS "pg_net";
CREATE EXTENSION IF NOT EXISTS "pg_trgm" WITH SCHEMA "public";
CREATE EXTENSION IF NOT EXISTS "vector" WITH SCHEMA "public";

DO $wk_extension_authority$
DECLARE
  v_record record;
BEGIN
  FOR v_record IN
    SELECT *
    FROM (
      VALUES
        ('fuzzystrmatch'::text, 'public'::text),
        ('pg_trgm'::text,       'public'::text),
        ('vector'::text,        'public'::text)
    ) expected(extension_name, schema_name)
  LOOP
    IF NOT EXISTS (
      SELECT 1
      FROM pg_extension e
      JOIN pg_namespace n
        ON n.oid = e.extnamespace
      WHERE e.extname = v_record.extension_name
        AND n.nspname = v_record.schema_name
    ) THEN
      RAISE EXCEPTION
        'WAKILISHA baseline extension % is not installed in schema %',
        v_record.extension_name,
        v_record.schema_name;
    END IF;
  END LOOP;

  IF to_regprocedure('net.http_get(text,jsonb,jsonb,integer)') IS NULL THEN
    RAISE EXCEPTION
      'WAKILISHA baseline requires net.http_get(text,jsonb,jsonb,integer)';
  END IF;

  IF to_regprocedure(
       'net.http_post(text,jsonb,jsonb,jsonb,integer)'
     ) IS NULL THEN
    RAISE EXCEPTION
      'WAKILISHA baseline requires net.http_post(text,jsonb,jsonb,jsonb,integer)';
  END IF;
END;
$wk_extension_authority$;




SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;


