CREATE OR REPLACE FUNCTION "editorial"."allocate_person_path"("p_seed" "text", "p_person_resource_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'editorial'
    AS $$
declare
  v_slug text;
  v_path text;
  v_suffix text;
begin
  if p_person_resource_id is null then
    raise exception
      'Person Resource id is required.';
  end if;

  v_slug := coalesce(
    editorial.normalize_person_slug(p_seed),
    'person'
  );

  v_path := '/people/' || v_slug;

  if exists (
    select 1
    from editorial.resource_aliases alias
    where alias.path = v_path
  ) then
    v_suffix := substr(
      replace(
        p_person_resource_id::text,
        '-',
        ''
      ),
      1,
      8
    );

    v_path :=
      '/people/'
      || v_slug
      || '-'
      || v_suffix;
  end if;

  if exists (
    select 1
    from editorial.resource_aliases alias
    where alias.path = v_path
  ) then
    v_path :=
      '/people/person-'
      || replace(
           p_person_resource_id::text,
           '-',
           ''
         );
  end if;

  if exists (
    select 1
    from editorial.resource_aliases alias
    where alias.path = v_path
  ) then
    raise exception
      'Could not allocate a unique Person path.';
  end if;

  return v_path;
end;
$$;


ALTER FUNCTION "editorial"."allocate_person_path"("p_seed" "text", "p_person_resource_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."append_playlist_lifecycle_event"("p_resource_id" "uuid", "p_playlist_id" "uuid", "p_version_id" "uuid", "p_action" "text", "p_prior_status" "text", "p_resulting_status" "text", "p_note" "text", "p_actor_id" "uuid", "p_command_receipt_id" "uuid", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'editorial'
    AS $$
declare
  v_existing_id uuid;
  v_event_number bigint;
  v_event_id uuid;
begin
  select event.id
  into v_existing_id
  from editorial.playlist_lifecycle_events event
  where event.command_receipt_id =
          p_command_receipt_id
    and event.action = p_action;

  if v_existing_id is not null then
    return v_existing_id;
  end if;

  select coalesce(
    max(event.event_number),
    0
  ) + 1
  into v_event_number
  from editorial.playlist_lifecycle_events event
  where event.resource_id = p_resource_id;

  insert into editorial.playlist_lifecycle_events (
    resource_id,
    playlist_id,
    event_number,
    version_id,
    action,
    prior_status,
    resulting_status,
    note,
    metadata,
    actor_id,
    command_receipt_id
  )
  values (
    p_resource_id,
    p_playlist_id,
    v_event_number,
    p_version_id,
    p_action,
    p_prior_status,
    p_resulting_status,
    nullif(btrim(p_note), ''),
    coalesce(p_metadata, '{}'::jsonb),
    p_actor_id,
    p_command_receipt_id
  )
  returning id
  into v_event_id;

  return v_event_id;
end;
$$;


ALTER FUNCTION "editorial"."append_playlist_lifecycle_event"("p_resource_id" "uuid", "p_playlist_id" "uuid", "p_version_id" "uuid", "p_action" "text", "p_prior_status" "text", "p_resulting_status" "text", "p_note" "text", "p_actor_id" "uuid", "p_command_receipt_id" "uuid", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."apply_article_review_snapshot"("p_article_id" "uuid", "p_resource_id" "uuid", "p_expected_draft_version" bigint, "p_content_html" "text") RETURNS TABLE("article_id" "uuid", "article_slug" "text", "draft_version" bigint, "version_id" "uuid", "version_number" bigint)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  current_article public.wk_articles%rowtype;
  current_resource editorial.resources%rowtype;

  new_version_id uuid;
  new_version_number bigint;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  if not editorial.current_user_can_review_article() then
    raise exception 'Permission denied';
  end if;

  if p_content_html is null then
    raise exception
      'Proposed Article content is required';
  end if;

  select article.*
  into current_article
  from public.wk_articles article
  where article.id = p_article_id
  for update;

  if not found then
    raise exception 'Article not found';
  end if;

  select resource.*
  into current_resource
  from editorial.resources resource
  where resource.id = p_resource_id
  for update;

  if not found then
    raise exception 'Article resource identity not found';
  end if;

  if not exists (
    select 1
    from editorial.article_resources binding
    where binding.article_id = p_article_id
      and binding.resource_id = p_resource_id
  ) then
    raise exception
      'Article and resource identity do not match';
  end if;

  if current_article.wp_status <> 'pending' then
    raise exception
      'Review acceptance requires an Article that is pending review';
  end if;

  if p_expected_draft_version is null
     or current_article.draft_version
       <> p_expected_draft_version
  then
    raise exception
      'STALE_ARTICLE_VERSION: expected %, current %',
      p_expected_draft_version,
      current_article.draft_version;
  end if;

  update public.wk_articles as article
  set
    content_html = p_content_html,
    wp_status = 'draft',
    draft_version = article.draft_version + 1,
    modified_at = now(),
    updated_at = now()
  where article.id = p_article_id
  returning article.*
  into current_article;

  new_version_number :=
    editorial.next_article_version_number(
      current_resource.id
    );

  insert into editorial.article_versions (
    resource_id,
    article_id,
    version_number,
    version_kind,
    source_draft_version,
    title,
    slug,
    excerpt,
    content_html,
    author_display,
    owner_id,
    hero_image_id,
    hero_image_url,
    seo,
    lifecycle_state,
    wp_status,
    published_at,
    category_snapshot,
    tag_snapshot,
    created_by,
    content_fingerprint
  )
  values (
    current_resource.id,
    current_article.id,
    new_version_number,
    'review_applied',
    current_article.draft_version,
    current_article.title,
    current_article.slug,
    current_article.excerpt,
    current_article.content_html,
    current_article.author,
    current_resource.owner_id,
    current_article.hero_image_id,
    current_article.hero_image_url,
    current_article.seo,
    'draft',
    current_article.wp_status,
    current_article.published_at,
    current_article.categories,
    current_article.tags,
    auth.uid(),
    editorial.article_snapshot_fingerprint(
      current_article.title,
      current_article.slug,
      current_article.excerpt,
      current_article.content_html,
      current_article.author,
      current_article.hero_image_id,
      current_article.hero_image_url,
      current_article.seo,
      current_article.wp_status,
      current_article.published_at,
      current_article.categories,
      current_article.tags
    )
  )
  returning id
  into new_version_id;

  update editorial.resources
  set
    current_working_version_id =
      new_version_id,
    lifecycle_state = 'draft',
    visibility = 'private',
    updated_at = now()
  where id = current_resource.id;

  article_id := current_article.id;
  article_slug := current_article.slug;
  draft_version :=
    current_article.draft_version;
  version_id := new_version_id;
  version_number := new_version_number;

  return next;
end;
$$;


ALTER FUNCTION "editorial"."apply_article_review_snapshot"("p_article_id" "uuid", "p_resource_id" "uuid", "p_expected_draft_version" bigint, "p_content_html" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "editorial"."apply_article_review_snapshot"("p_article_id" "uuid", "p_resource_id" "uuid", "p_expected_draft_version" bigint, "p_content_html" "text") IS 'Private command authority for applying one accepted suggestion as a durable review-applied Article version.';



CREATE OR REPLACE FUNCTION "editorial"."article_snapshot_fingerprint"("p_title" "text", "p_slug" "text", "p_excerpt" "text", "p_content_html" "text", "p_author_display" "text", "p_hero_image_id" "uuid", "p_hero_image_url" "text", "p_seo" "jsonb", "p_wp_status" "text", "p_published_at" timestamp with time zone, "p_categories" "jsonb", "p_tags" "jsonb") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO 'pg_catalog'
    AS $$
  select encode(
    extensions.digest(
      concat_ws(
        chr(31),
        coalesce(p_title, ''),
        coalesce(p_slug, ''),
        coalesce(p_excerpt, ''),
        coalesce(p_content_html, ''),
        coalesce(p_author_display, ''),
        coalesce(p_hero_image_id::text, ''),
        coalesce(p_hero_image_url, ''),
        coalesce(p_seo, '{}'::jsonb)::text,
        coalesce(p_wp_status, ''),
        coalesce(p_published_at::text, ''),
        coalesce(p_categories, '[]'::jsonb)::text,
        coalesce(p_tags, '[]'::jsonb)::text
      ),
      'sha256'
    ),
    'hex'
  );
$$;


ALTER FUNCTION "editorial"."article_snapshot_fingerprint"("p_title" "text", "p_slug" "text", "p_excerpt" "text", "p_content_html" "text", "p_author_display" "text", "p_hero_image_id" "uuid", "p_hero_image_url" "text", "p_seo" "jsonb", "p_wp_status" "text", "p_published_at" timestamp with time zone, "p_categories" "jsonb", "p_tags" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."artist_music_submission_review_due_at"("p_submitted_at" timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_due timestamptz := p_submitted_at;
  v_business_days integer := 0;
begin
  if p_submitted_at is null then
    return null;
  end if;

  while v_business_days < 3 loop
    v_due := v_due + interval '1 day';

    if extract(
      isodow
      from v_due at time zone 'Africa/Nairobi'
    ) between 1 and 5
    then
      v_business_days := v_business_days + 1;
    end if;
  end loop;

  return v_due;
end;
$$;


ALTER FUNCTION "editorial"."artist_music_submission_review_due_at"("p_submitted_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."artist_representation_defaults"("p_role" "text") RETURNS TABLE("can_manage_profile" boolean, "can_submit_releases" boolean, "can_post_updates" boolean, "can_manage_team" boolean)
    LANGUAGE "sql" IMMUTABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
  select
    case
      when p_role in (
        'artist',
        'manager'
      ) then true
      when p_role = 'publicist' then true
      else false
    end,
    case
      when p_role in (
        'artist',
        'manager',
        'label'
      ) then true
      else false
    end,
    case
      when p_role in (
        'artist',
        'manager',
        'label',
        'publicist',
        'team_member'
      ) then true
      else false
    end,
    case
      when p_role in (
        'artist',
        'manager'
      ) then true
      else false
    end;
$$;


ALTER FUNCTION "editorial"."artist_representation_defaults"("p_role" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."assert_article_review_thread_integrity"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'editorial'
    AS $$
declare
  target_version editorial.article_versions%rowtype;
  target_resource editorial.resources%rowtype;
begin
  select version.*
  into target_version
  from editorial.article_versions version
  where version.id = new.target_version_id;

  if not found then
    raise exception 'Article review target version not found';
  end if;

  if target_version.resource_id <> new.resource_id
     or target_version.article_id <> new.article_id
  then
    raise exception
      'Article review target version must belong to the same Article resource';
  end if;

  select resource.*
  into target_resource
  from editorial.resources resource
  where resource.id = new.resource_id;

  if not found then
    raise exception 'Article review resource not found';
  end if;

  if new.thread_kind = 'suggestion'
     and target_resource.current_submitted_version_id
       is distinct from new.target_version_id
  then
    raise exception
      'Suggestions must target the current submitted Article version';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "editorial"."assert_article_review_thread_integrity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."assert_article_suggestion_integrity"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'editorial'
    AS $$
declare
  target_thread editorial.article_review_threads%rowtype;
  target_version editorial.article_versions%rowtype;
begin
  select thread.*
  into target_thread
  from editorial.article_review_threads thread
  where thread.id = new.thread_id;

  if not found then
    raise exception 'Article suggestion thread not found';
  end if;

  if target_thread.thread_kind <> 'suggestion' then
    raise exception
      'Article suggestion must belong to a suggestion thread';
  end if;

  if target_thread.target_field <> 'content_html' then
    raise exception
      'Initial Article suggestions may target content_html only';
  end if;

  if target_thread.anchor_kind <> 'text_range' then
    raise exception
      'Initial Article suggestions require a text-range anchor';
  end if;

  select version.*
  into target_version
  from editorial.article_versions version
  where version.id = target_thread.target_version_id;

  if not found then
    raise exception 'Article suggestion target version not found';
  end if;

  if target_version.content_fingerprint
     <> new.target_version_fingerprint
  then
    raise exception
      'Article suggestion fingerprint does not match its target version';
  end if;

  if coalesce(target_version.content_html, '')
     = new.proposed_content_html
  then
    raise exception
      'Article suggestion must change the submitted Article content';
  end if;

  if new.operation_kind = 'insert' then
    if target_thread.anchor_from is null
       or target_thread.anchor_to is null
       or target_thread.anchor_from
          <> target_thread.anchor_to
       or new.original_text <> ''
       or new.replacement_text = ''
    then
      raise exception
        'Insert suggestions require a collapsed anchor and replacement text';
    end if;
  elsif new.operation_kind = 'replace' then
    if target_thread.anchor_from is null
       or target_thread.anchor_to is null
       or target_thread.anchor_to
          <= target_thread.anchor_from
       or new.original_text = ''
       or new.replacement_text = ''
       or coalesce(target_thread.anchor_quote, '')
          <> new.original_text
    then
      raise exception
        'Replace suggestions require a matching non-empty text-range anchor';
    end if;
  elsif new.operation_kind = 'delete' then
    if target_thread.anchor_from is null
       or target_thread.anchor_to is null
       or target_thread.anchor_to
          <= target_thread.anchor_from
       or new.original_text = ''
       or new.replacement_text <> ''
       or coalesce(target_thread.anchor_quote, '')
          <> new.original_text
    then
      raise exception
        'Delete suggestions require a matching non-empty text-range anchor';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "editorial"."assert_article_suggestion_integrity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."assert_article_version_pointer_integrity"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'editorial'
    AS $$
begin
  if new.current_working_version_id is not null
     and not exists (
       select 1
       from editorial.article_versions version
       where version.id = new.current_working_version_id
         and version.resource_id = new.id
     )
  then
    raise exception
      'Current working version must belong to the same resource';
  end if;

  if new.current_submitted_version_id is not null
     and not exists (
       select 1
       from editorial.article_versions version
       where version.id = new.current_submitted_version_id
         and version.resource_id = new.id
         and version.version_kind = 'submitted'
     )
  then
    raise exception
      'Current submitted version must be a submitted version belonging to the same resource';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "editorial"."assert_article_version_pointer_integrity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."assert_article_version_trust_attachment"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'editorial'
    AS $$
begin
  if new.resource_kind <> 'article'
     or new.target_version_type <> 'article_version'
  then
    raise exception
      'Trust attachments currently support Article versions only';
  end if;

  if not exists (
    select 1
    from editorial.article_versions version
    where version.id = new.target_version_id
      and version.resource_id = new.resource_id
  )
  then
    raise exception
      'Trust attachment Article version must belong to the supplied resource';
  end if;

  if not exists (
    select 1
    from editorial.article_resources binding
    where binding.resource_id = new.resource_id
      and binding.resource_kind = 'article'
      and exists (
        select 1
        from editorial.article_versions version
        where version.id = new.target_version_id
          and version.article_id = binding.article_id
      )
  )
  then
    raise exception
      'Trust attachment requires a valid Article resource binding';
  end if;

  insert into editorial.article_version_trust_revisions (
    article_version_id
  )
  values (
    new.target_version_id
  )
  on conflict (article_version_id) do nothing;

  perform 1
  from editorial.article_version_trust_revisions revision
  where revision.article_version_id = new.target_version_id
  for update;

  if tg_table_name = 'resource_citations' then
    perform editorial.validate_citation_target_anchor(
      new.target_anchor_type,
      new.target_anchor_data
    );

    if new.public_safe
       and not exists (
         select 1
         from editorial.citations citation
         where citation.id = new.citation_id
           and citation.public_safe
           and citation.citation_state = 'active'
       )
    then
      raise exception
        'Public-safe Citation attachment requires an active public-safe Citation';
    end if;
  elsif tg_table_name = 'resource_credits' then
    if new.public_safe
       and not exists (
         select 1
         from editorial.credit_governance governance
         where governance.credit_id = new.credit_id
           and governance.public_safe
           and governance.credit_state = 'active'
       )
    then
      raise exception
        'Public-safe Credit attachment requires active public-safe governance';
    end if;
  else
    raise exception
      'Unsupported trust attachment table: %',
      tg_table_name;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "editorial"."assert_article_version_trust_attachment"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."assert_citation_command_actor"() RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_actor_id uuid;
begin
  v_actor_id := auth.uid();

  if auth.role() = 'service_role' then
    return v_actor_id;
  end if;

  if v_actor_id is null then
    raise exception
      'Authentication is required';
  end if;

  if not (
    coalesce(
      public.current_user_is_administrator(),
      false
    )
    or coalesce(
      public.current_user_has_capability(
        'manage_citations'
      ),
      false
    )
  ) then
    raise exception
      'You do not have Citation management authority';
  end if;

  return v_actor_id;
end;
$$;


ALTER FUNCTION "editorial"."assert_citation_command_actor"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."assert_citation_integrity"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'editorial'
    AS $$
declare
  v_source editorial.sources%rowtype;
begin
  perform editorial.validate_citation_locator(
    new.locator_type,
    new.locator_data
  );

  if not exists (
    select 1
    from editorial.source_versions version
    where version.id = new.source_version_id
      and version.source_id = new.source_id
  )
  then
    raise exception
      'Citation Source version must belong to the supplied Source';
  end if;

  select source.*
  into v_source
  from editorial.sources source
  where source.id = new.source_id;

  if not found then
    raise exception 'Citation Source does not exist';
  end if;

  if new.public_safe then
    if v_source.review_status <> 'approved'
       or v_source.current_approved_version_id
            is distinct from new.source_version_id
    then
      raise exception
        'Public-safe Citation requires the approved Source version';
    end if;

    if v_source.exposure_class not in (
      'public',
      'public_redacted'
    )
    then
      raise exception
        'Public-safe Citation requires public or public-redacted exposure';
    end if;

    if v_source.source_state = 'withdrawn'
       or v_source.withdrawn_at is not null
    then
      raise exception
        'Public-safe Citation cannot use a withdrawn Source';
    end if;
  end if;

  return new;
end;
$$;


