CREATE OR REPLACE FUNCTION "editorial"."assert_correction_evidence_integrity"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'editorial'
    AS $$
declare
  v_source editorial.sources%rowtype;
  v_version_source_id uuid;
  v_citation_source_id uuid;
  v_citation_source_version_id uuid;
  v_citation_state text;
begin
  select source.*
  into v_source
  from editorial.sources source
  where source.id = new.source_id;

  if not found then
    raise exception
      'Correction evidence Source does not exist';
  end if;

  if v_source.source_state <> 'active'
     or v_source.review_status <> 'approved'
     or v_source.current_approved_version_id
       is distinct from new.source_version_id
  then
    raise exception
      'Correction evidence requires the active approved Source version';
  end if;

  select version.source_id
  into v_version_source_id
  from editorial.source_versions version
  where version.id = new.source_version_id;

  if not found
     or v_version_source_id is distinct from new.source_id
  then
    raise exception
      'Correction evidence Source version must belong to the Source';
  end if;

  if new.citation_id is not null then
    select
      citation.source_id,
      citation.source_version_id,
      citation.citation_state
    into
      v_citation_source_id,
      v_citation_source_version_id,
      v_citation_state
    from editorial.citations citation
    where citation.id = new.citation_id;

    if not found
       or v_citation_source_id is distinct from new.source_id
       or v_citation_source_version_id
         is distinct from new.source_version_id
       or v_citation_state <> 'active'
    then
      raise exception
        'Correction evidence Citation must be active and match the Source and Source version';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "editorial"."assert_correction_evidence_integrity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."assert_correction_public_note_integrity"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'editorial'
    AS $$
declare
  v_case editorial.correction_cases%rowtype;
  v_application editorial.correction_applications%rowtype;
  v_decision_outcome text;
  v_proof record;
  v_superseded editorial.correction_public_notes%rowtype;
  v_expected_fingerprint text;
begin
  v_expected_fingerprint :=
    editorial.correction_public_note_fingerprint(
      new.case_resource_id,
      new.application_id,
      new.affected_resource_id,
      new.challenged_version_id,
      new.corrected_version_id,
      new.note_text
    );

  if new.note_fingerprint <>
     v_expected_fingerprint
  then
    raise exception
      'Correction public-note fingerprint is invalid';
  end if;

  select correction_case.*
  into v_case
  from editorial.correction_cases correction_case
  where correction_case.resource_id =
    new.case_resource_id;

  if not found
     or v_case.case_state
       is distinct from 'applied'
     or v_case.current_application_id
       is distinct from new.application_id
     or v_case.public_note_disposition
       is distinct from 'published'
  then
    raise exception
      'Correction public note must bind to the current published-note application state';
  end if;

  select application.*
  into v_application
  from editorial.correction_applications application
  where application.id =
    new.application_id;

  if not found
     or v_application.case_resource_id
       is distinct from new.case_resource_id
     or v_application.target_resource_id
       is distinct from new.affected_resource_id
     or v_application.challenged_version_id
       is distinct from new.challenged_version_id
  then
    raise exception
      'Correction public-note application identity is invalid';
  end if;

  select decision.outcome
  into v_decision_outcome
  from editorial.correction_decisions decision
  where decision.id =
      v_application.decision_id
    and decision.case_resource_id =
      new.case_resource_id;

  if not found
     or v_decision_outcome <>
       'correction_required'
  then
    raise exception
      'Correction public note requires a correction-required decision';
  end if;

  select *
  into v_proof
  from editorial.correction_article_publication_proof(
    new.application_id
  );

  if not found
     or v_proof.corrected_version_id
       is distinct from new.corrected_version_id
     or v_proof.affected_resource_id
       is distinct from new.affected_resource_id
     or v_proof.challenged_version_id
       is distinct from new.challenged_version_id
  then
    raise exception
      'Correction public note lacks exact corrected publication proof';
  end if;

  if new.supersedes_note_id is null then
    if exists (
      select 1
      from editorial.correction_public_notes note
      where note.case_resource_id =
          new.case_resource_id
        and note.application_id =
          new.application_id
        and note.id <> new.id
        and not exists (
          select 1
          from editorial.correction_public_notes later_note
          where later_note.supersedes_note_id =
            note.id
        )
    ) then
      raise exception
        'A later public note must supersede the current note explicitly';
    end if;
  else
    select note.*
    into v_superseded
    from editorial.correction_public_notes note
    where note.id =
      new.supersedes_note_id;

    if not found
       or v_superseded.case_resource_id
         is distinct from new.case_resource_id
       or v_superseded.application_id
         is distinct from new.application_id
       or v_superseded.affected_resource_id
         is distinct from new.affected_resource_id
       or v_superseded.challenged_version_id
         is distinct from new.challenged_version_id
       or v_superseded.corrected_version_id
         is distinct from new.corrected_version_id
       or exists (
         select 1
         from editorial.correction_public_notes later_note
         where later_note.supersedes_note_id =
           v_superseded.id
           and later_note.id <> new.id
       )
    then
      raise exception
        'Correction public-note supersession identity is invalid';
    end if;
  end if;

  perform editorial.validate_correction_case_history(
    new.case_resource_id
  );

  return new;
end;
$$;


