CREATE OR REPLACE FUNCTION "editorial"."assert_person_identity_integrity"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'editorial'
    AS $$
declare
  v_person_resource_id uuid;
  v_preferred_identity_link_id uuid;
begin
  if tg_table_name = 'people' then
    v_person_resource_id := new.resource_id;
  elsif tg_op = 'DELETE' then
    v_person_resource_id := old.person_resource_id;
  else
    v_person_resource_id := new.person_resource_id;
  end if;

  select person.preferred_identity_link_id
  into v_preferred_identity_link_id
  from editorial.people person
  where person.resource_id = v_person_resource_id;

  if not found then
    return null;
  end if;

  if v_preferred_identity_link_id is not null
     and not exists (
       select 1
       from editorial.person_identity_links link
       where link.id = v_preferred_identity_link_id
         and link.person_resource_id = v_person_resource_id
         and link.link_state = 'active'
     )
  then
    raise exception
      'Preferred Person identity link must be active and belong to the same Person.';
  end if;

  return null;
end;
$$;


ALTER FUNCTION "editorial"."assert_person_identity_integrity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."assert_person_merge_cycle_integrity"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'editorial'
    AS $$
declare
  v_next uuid;
  v_seen uuid[];
  v_depth integer;
begin
  if new.person_state <> 'merged' then
    return null;
  end if;

  v_next :=
    new.merged_into_person_resource_id;
  v_seen :=
    array[new.resource_id];

  for v_depth in 1..64
  loop
    if v_next is null then
      return null;
    end if;

    if v_next = any(v_seen) then
      raise exception
        'Person merge cycle is not permitted.';
    end if;

    v_seen :=
      array_append(
        v_seen,
        v_next
      );

    select
      case
        when person.person_state = 'merged'
          then person.merged_into_person_resource_id
        else null
      end
    into v_next
    from editorial.people person
    where person.resource_id =
          v_next;

    if not found then
      return null;
    end if;
  end loop;

  raise exception
    'Person merge chain exceeds the supported safety depth.';
end;
$$;


ALTER FUNCTION "editorial"."assert_person_merge_cycle_integrity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."assert_playlist_curator_credit"("p_credit_id" "uuid") RETURNS TABLE("credit_id" "uuid", "display_name" "text", "registry_author_slug" "text", "user_username" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
begin
  return query
  select
    credit.id,
    credit.display_name_snapshot,
    credit.registry_author_slug_snapshot,
    credit.user_username_snapshot
  from editorial.credits credit
  join editorial.credit_governance governance
    on governance.credit_id = credit.id
  where credit.id = p_credit_id
    and credit.credit_role = 'curator'
    and credit.external_contributor_id is null
    and num_nonnulls(
          credit.user_id,
          credit.registry_author_id
        ) = 1
    and governance.credit_state = 'active'
    and governance.public_safe
    and nullif(
          btrim(credit.display_name_snapshot),
          ''
        ) is not null;

  if not found then
    raise exception
      'Choose an active public Curator linked to a WAKILISHA user or Registry Author';
  end if;
end;
$$;


