CREATE OR REPLACE FUNCTION "editorial"."assert_publishing_item_integrity"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'editorial'
    AS $$
declare
  v_expected_resource_kind text;
  v_actual_resource_kind text;
begin
  if tg_op = 'UPDATE' then
    if new.id is distinct from old.id
       or new.created_by is distinct from old.created_by
       or new.created_at is distinct from old.created_at
    then
      raise exception
        'Publishing item identity and creation metadata are immutable';
    end if;

    if old.resource_id is not null
       and new.resource_id is distinct from old.resource_id
    then
      raise exception
        'A linked Publishing item cannot be unlinked or retargeted';
    end if;

    if new.record_version <> old.record_version + 1 then
      raise exception
        'Publishing item record_version must advance by exactly one';
    end if;
  end if;

  select kind.canonical_resource_kind
  into v_expected_resource_kind
  from editorial.publishing_content_kinds kind
  where kind.kind = new.content_kind
    and kind.enabled = true;

  if not found then
    raise exception
      'Publishing content kind is missing or disabled';
  end if;

  if new.resource_id is not null then
    if v_expected_resource_kind is null then
      raise exception
        'This Publishing content kind cannot link a canonical resource';
    end if;

    select resource.resource_kind
    into v_actual_resource_kind
    from editorial.resources resource
    where resource.id = new.resource_id;

    if not found then
      raise exception
        'Publishing canonical resource does not exist';
    end if;

    if v_actual_resource_kind
       <> v_expected_resource_kind
    then
      raise exception
        'Publishing content kind % requires resource kind %, received %',
        new.content_kind,
        v_expected_resource_kind,
        v_actual_resource_kind;
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "editorial"."assert_publishing_item_integrity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."assert_resource_binding_integrity"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'editorial'
    AS $$
declare
  target_resource_id uuid;
  target_kind text;
  binding_count integer;
begin
  if tg_table_name = 'resources' then
    if tg_op = 'DELETE' then
      return null;
    end if;

    target_resource_id := new.id;
  else
    if tg_op = 'DELETE' then
      target_resource_id := old.resource_id;
    else
      target_resource_id := new.resource_id;
    end if;
  end if;

  select resource_kind
  into target_kind
  from editorial.resources
  where id = target_resource_id;

  if not found then
    return null;
  end if;

  case target_kind
    when 'article' then
      select count(*)
      into binding_count
      from editorial.article_resources
      where resource_id = target_resource_id;

    when 'playlist' then
      select count(*)
      into binding_count
      from editorial.playlist_resources
      where resource_id = target_resource_id;

    when 'playlist_item' then
      select count(*)
      into binding_count
      from editorial.playlist_item_resources
      where resource_id = target_resource_id;

    when 'registry_artist' then
      select count(*)
      into binding_count
      from editorial.registry_artist_resources
      where resource_id = target_resource_id;

    when 'correction_case' then
      select count(*)
      into binding_count
      from editorial.correction_cases
      where resource_id = target_resource_id;

    when 'media_asset' then
      select count(*)
      into binding_count
      from editorial.media_asset_resources
      where resource_id = target_resource_id;

    when 'person' then
      select count(*)
      into binding_count
      from editorial.people
      where resource_id = target_resource_id;

    else
      raise exception
        'Unsupported resource kind: %',
        target_kind;
  end case;

  if binding_count <> 1 then
    raise exception
      'Resource % with kind % must have exactly one typed binding.',
      target_resource_id,
      target_kind;
  end if;

  return null;
end;
$$;


ALTER FUNCTION "editorial"."assert_resource_binding_integrity"() OWNER TO "postgres";


COMMENT ON FUNCTION "editorial"."assert_resource_binding_integrity"() IS 'Deferred integrity check requiring exactly one typed binding for every supported WAKILISHA Resource kind, including Person.';



CREATE OR REPLACE FUNCTION "editorial"."assert_resource_version_trust_attachment"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'editorial'
    AS $$
declare
  v_playlist_version
    editorial.playlist_versions%rowtype;
begin
  if new.resource_kind = 'article' then
    if new.target_version_type <> 'article_version'
    then
      raise exception
        'Article Trust attachments require article_version targets';
    end if;

    if not exists (
      select 1
      from editorial.article_versions version
      where version.id = new.target_version_id
        and version.resource_id = new.resource_id
    ) then
      raise exception
        'Trust attachment Article version must belong to the supplied resource';
    end if;

    if not exists (
      select 1
      from editorial.article_resources binding
      where binding.resource_id = new.resource_id
        and binding.resource_kind = 'article'
        and exists (
          select 1
          from editorial.article_versions version
          where version.id = new.target_version_id
            and version.article_id =
                  binding.article_id
        )
    ) then
      raise exception
        'Trust attachment requires a valid Article resource binding';
    end if;

    insert into editorial.article_version_trust_revisions (
      article_version_id
    )
    values (
      new.target_version_id
    )
    on conflict (article_version_id)
    do nothing;

    perform 1
    from editorial.article_version_trust_revisions revision
    where revision.article_version_id =
            new.target_version_id
    for update;

  elsif new.resource_kind in (
    'playlist',
    'playlist_item'
  ) then
    if new.target_version_type <> 'playlist_version'
    then
      raise exception
        'Playlist Trust attachments require playlist_version targets';
    end if;

    select version.*
    into v_playlist_version
    from editorial.playlist_versions version
    where version.id = new.target_version_id;

    if not found then
      raise exception
        'Playlist Trust attachment version was not found';
    end if;

    if new.resource_kind = 'playlist' then
      if v_playlist_version.resource_id <>
           new.resource_id
      then
        raise exception
          'Playlist Trust attachment must target the Playlist Resource belonging to the version';
      end if;

    elsif not exists (
      select 1
      from editorial.playlist_version_items item
      where item.playlist_version_id =
              new.target_version_id
        and item.playlist_item_resource_id =
              new.resource_id
    ) then
      raise exception
        'Playlist-item Trust attachment must target an item present in the Playlist version';
    end if;

    insert into editorial.playlist_version_trust_revisions (
      playlist_version_id
    )
    values (
      new.target_version_id
    )
    on conflict (playlist_version_id)
    do nothing;

    perform 1
    from editorial.playlist_version_trust_revisions revision
    where revision.playlist_version_id =
            new.target_version_id
    for update;

  else
    raise exception
      'Unsupported Trust attachment Resource kind: %',
      new.resource_kind;
  end if;

  if tg_table_name = 'resource_citations' then
    perform editorial.validate_citation_target_anchor(
      new.target_anchor_type,
      new.target_anchor_data
    );

    if new.public_safe
       and not exists (
         select 1
         from editorial.citations citation
         where citation.id = new.citation_id
           and citation.public_safe
           and citation.citation_state = 'active'
       )
    then
      raise exception
        'Public-safe Citation attachment requires an active public-safe Citation';
    end if;

  elsif tg_table_name = 'resource_credits' then
    if new.public_safe
       and not exists (
         select 1
         from editorial.credit_governance governance
         where governance.credit_id = new.credit_id
           and governance.public_safe
           and governance.credit_state = 'active'
       )
    then
      raise exception
        'Public-safe Credit attachment requires active public-safe governance';
    end if;

  else
    raise exception
      'Unsupported Trust attachment table: %',
      tg_table_name;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "editorial"."assert_resource_version_trust_attachment"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."assert_source_command_actor"("p_capability" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_actor_id uuid;
begin
  v_actor_id := auth.uid();

  if auth.role() = 'service_role' then
    return v_actor_id;
  end if;

  if v_actor_id is null then
    raise exception
      'Authentication is required';
  end if;

  if not (
    coalesce(
      public.current_user_is_administrator(),
      false
    )
    or coalesce(
      public.current_user_has_capability(p_capability),
      false
    )
  ) then
    raise exception
      'You do not have the required Source capability: %',
      p_capability;
  end if;

  return v_actor_id;
end;
$$;


ALTER FUNCTION "editorial"."assert_source_command_actor"("p_capability" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."assert_source_registry_link_integrity"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'editorial', 'public'
    AS $$
begin
  if not exists (
    select 1
    from editorial.source_versions version
    where version.id = new.source_version_id
      and version.source_id = new.source_id
  )
  then
    raise exception
      'Source Registry link version must belong to the supplied Source';
  end if;

  case new.registry_entity_type
    when 'artist' then
      if not exists (
        select 1
        from public.registry_artists entity
        where entity.id = new.registry_entity_id
          and entity.status = 'active'
      )
      then
        raise exception
          'Source Registry artist must exist and be active';
      end if;

    when 'author' then
      if not exists (
        select 1
        from public.registry_authors entity
        where entity.id = new.registry_entity_id
      )
      then
        raise exception 'Source Registry author does not exist';
      end if;

    when 'genre' then
      if not exists (
        select 1
        from public.registry_genres entity
        where entity.id = new.registry_entity_id
          and entity.status = 'active'
      )
      then
        raise exception
          'Source Registry genre must exist and be active';
      end if;

    when 'label' then
      if not exists (
        select 1
        from public.registry_labels entity
        where entity.id = new.registry_entity_id
          and entity.status = 'active'
      )
      then
        raise exception
          'Source Registry label must exist and be active';
      end if;

    when 'release' then
      if not exists (
        select 1
        from public.registry_releases entity
        where entity.id = new.registry_entity_id
          and entity.status = 'active'
      )
      then
        raise exception
          'Source Registry release must exist and be active';
      end if;

    when 'track' then
      if not exists (
        select 1
        from public.registry_tracks entity
        where entity.id = new.registry_entity_id
          and entity.status = 'active'
      )
      then
        raise exception
          'Source Registry track must exist and be active';
      end if;

    else
      raise exception
        'Unsupported Source Registry entity type: %',
        new.registry_entity_type;
  end case;

  return new;
end;
$$;


ALTER FUNCTION "editorial"."assert_source_registry_link_integrity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."assert_source_version_pointer_integrity"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'editorial'
    AS $$
begin
  if new.current_working_version_id is not null
     and not exists (
       select 1
       from editorial.source_versions version
       where version.id = new.current_working_version_id
         and version.source_id = new.id
     )
  then
    raise exception
      'Current working Source version must belong to the same Source';
  end if;

  if new.current_submitted_version_id is not null
     and not exists (
       select 1
       from editorial.source_versions version
       where version.id = new.current_submitted_version_id
         and version.source_id = new.id
     )
  then
    raise exception
      'Current submitted Source version must belong to the same Source';
  end if;

  if new.current_approved_version_id is not null
     and not exists (
       select 1
       from editorial.source_versions version
       where version.id = new.current_approved_version_id
         and version.source_id = new.id
     )
  then
    raise exception
      'Current approved Source version must belong to the same Source';
  end if;

  if new.review_status in ('ready_for_review', 'in_review')
     and new.current_submitted_version_id is null
  then
    raise exception
      'Ready-for-review and in-review Sources require a submitted Source version';
  end if;

  if new.review_status = 'approved'
     and (
       new.current_approved_version_id is null
       or new.reviewed_by is null
       or new.reviewed_at is null
     )
  then
    raise exception
      'Approved Sources require an approved version, reviewer, and review time';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "editorial"."assert_source_version_pointer_integrity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."attach_playlist_curator_to_working_snapshot"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_version editorial.playlist_versions%rowtype;
  v_playlist public.wk_playlists%rowtype;
  v_curator record;
begin
  select version.*
  into v_version
  from editorial.playlist_versions version
  where version.id = new.playlist_version_id;

  if not found
     or v_version.version_kind <> 'working'
  then
    return new;
  end if;

  select playlist.*
  into v_playlist
  from public.wk_playlists playlist
  where playlist.id = v_version.playlist_id;

  if v_playlist.curator_credit_id is null then
    return new;
  end if;

  select *
  into v_curator
  from editorial.assert_playlist_curator_credit(
    v_playlist.curator_credit_id
  );

  insert into editorial.resource_credits (
    resource_id,
    resource_kind,
    target_version_type,
    target_version_id,
    credit_id,
    display_order,
    is_primary,
    public_safe,
    created_by
  )
  values (
    v_version.resource_id,
    'playlist',
    'playlist_version',
    v_version.id,
    v_curator.credit_id,
    0,
    true,
    true,
    new.updated_by
  )
  on conflict (
    target_version_id,
    resource_id,
    credit_id
  )
  do nothing;

  return new;
end;
$$;


ALTER FUNCTION "editorial"."attach_playlist_curator_to_working_snapshot"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."carry_playlist_registry_intake_note_to_item"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if new.source_playlist_item_id is not null
     and (
       new.source_playlist_item_id is distinct from old.source_playlist_item_id
       or new.playlist_note is distinct from old.playlist_note
     )
  then
    update public.wk_playlist_items item
    set notes = new.playlist_note
    where item.id = new.source_playlist_item_id
      and item.playlist_id = new.source_playlist_id;
  end if;

  return new;
end;
$$;


