CREATE OR REPLACE FUNCTION "editorial"."copy_article_lifecycle_version"("p_source_version_id" "uuid", "p_version_kind" "text", "p_lifecycle_state" "text", "p_wp_status" "text", "p_published_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("version_id" "uuid", "version_number" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_source editorial.article_versions%rowtype;
  v_version_id uuid;
  v_version_number bigint;
begin
  select version.*
  into v_source
  from editorial.article_versions version
  where version.id = p_source_version_id;

  if not found then
    raise exception 'Article version not found';
  end if;

  v_version_number :=
    editorial.next_article_version_number(
      v_source.resource_id
    );

  insert into editorial.article_versions (
    resource_id,
    article_id,
    version_number,
    version_kind,
    source_draft_version,
    title,
    slug,
    excerpt,
    content_html,
    author_display,
    owner_id,
    hero_image_id,
    hero_image_url,
    seo,
    lifecycle_state,
    wp_status,
    published_at,
    category_snapshot,
    tag_snapshot,
    created_by,
    content_fingerprint
  )
  values (
    v_source.resource_id,
    v_source.article_id,
    v_version_number,
    p_version_kind,
    v_source.source_draft_version,
    v_source.title,
    v_source.slug,
    v_source.excerpt,
    v_source.content_html,
    v_source.author_display,
    v_source.owner_id,
    v_source.hero_image_id,
    v_source.hero_image_url,
    v_source.seo,
    p_lifecycle_state,
    p_wp_status,
    coalesce(p_published_at, v_source.published_at),
    v_source.category_snapshot,
    v_source.tag_snapshot,
    auth.uid(),
    v_source.content_fingerprint
  )
  returning id
  into v_version_id;

  version_id := v_version_id;
  version_number := v_version_number;
  return next;
end;
$$;


ALTER FUNCTION "editorial"."copy_article_lifecycle_version"("p_source_version_id" "uuid", "p_version_kind" "text", "p_lifecycle_state" "text", "p_wp_status" "text", "p_published_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."copy_playlist_lifecycle_version"("p_source_version_id" "uuid", "p_target_version_kind" "text", "p_actor_id" "uuid") RETURNS TABLE("version_id" "uuid", "version_number" bigint, "content_fingerprint" "text", "item_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial', 'platform_private'
    AS $$
declare
  v_source editorial.playlist_versions%rowtype;
  v_version_id uuid;
  v_version_number bigint;
  v_copy_authorization uuid;
begin
  select source.*
  into v_source
  from editorial.playlist_versions source
  where source.id = p_source_version_id;

  if not found then
    raise exception
      'Source Playlist version does not exist';
  end if;

  if not (
    (
      v_source.version_kind = 'approved'
      and p_target_version_kind = 'scheduled'
    )
    or
    (
      v_source.version_kind = 'scheduled'
      and p_target_version_kind = 'published'
    )
  ) then
    raise exception
      'Unsupported Playlist lifecycle copy: % to %',
      v_source.version_kind,
      p_target_version_kind;
  end if;

  perform 1
  from public.wk_playlists playlist
  where playlist.id = v_source.playlist_id
  for update;

  select coalesce(
    max(version.version_number),
    0
  ) + 1
  into v_version_number
  from editorial.playlist_versions version
  where version.resource_id =
          v_source.resource_id;

  v_version_id := gen_random_uuid();

  insert into editorial.playlist_versions (
    id,
    resource_id,
    playlist_id,
    version_number,
    version_kind,
    source_authority_revision,
    title,
    slug,
    description,
    curator_label,
    status,
    metadata,
    item_count,
    content_fingerprint,
    cover_asset_id,
    cover_asset_revision_id,
    cover_placement_data,
    cover_display_order,
    cover_alt_text_snapshot,
    cover_caption_snapshot,
    cover_credit_snapshot,
    created_by
  )
  values (
    v_version_id,
    v_source.resource_id,
    v_source.playlist_id,
    v_version_number,
    p_target_version_kind,
    v_source.source_authority_revision,
    v_source.title,
    v_source.slug,
    v_source.description,
    v_source.curator_label,
    p_target_version_kind,
    v_source.metadata,
    v_source.item_count,
    v_source.content_fingerprint,
    v_source.cover_asset_id,
    v_source.cover_asset_revision_id,
    v_source.cover_placement_data,
    v_source.cover_display_order,
    v_source.cover_alt_text_snapshot,
    v_source.cover_caption_snapshot,
    v_source.cover_credit_snapshot,
    p_actor_id
  );

  insert into editorial.playlist_version_trust_revisions (
    playlist_version_id,
    citation_revision,
    credit_revision,
    updated_by,
    updated_at
  )
  values (
    v_version_id,
    1,
    1,
    p_actor_id,
