CREATE OR REPLACE FUNCTION "editorial"."copy_playlist_working_trust_to_version"("p_resource_id" "uuid", "p_source_working_version_id" "uuid", "p_target_version_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'editorial'
    AS $$
declare
  v_copy_authorization uuid;
  v_target_curator_credit_id uuid;
  v_root_offset integer := 0;
begin
  if p_source_working_version_id is null then
    return;
  end if;

  select attachment.credit_id
  into v_target_curator_credit_id
  from editorial.resource_credits attachment
  join editorial.credits credit
    on credit.id = attachment.credit_id
  where attachment.target_version_type =
          'playlist_version'
    and attachment.target_version_id =
          p_target_version_id
    and attachment.resource_id =
          p_resource_id
    and attachment.resource_kind = 'playlist'
    and credit.credit_role = 'curator'
  order by attachment.display_order, attachment.id
  limit 1;

  if v_target_curator_credit_id is not null then
    v_root_offset := 1;
  end if;

  v_copy_authorization :=
    platform_private.begin_playlist_trust_copy_authorization(
      p_source_working_version_id,
      p_target_version_id
    );

  insert into editorial.resource_citations (
    resource_id,
    resource_kind,
    target_version_type,
    target_version_id,
    citation_id,
    citation_purpose,
    target_anchor_type,
    target_anchor_data,
    display_order,
    public_safe,
    created_by
  )
  select
    citation.resource_id,
    citation.resource_kind,
    'playlist_version',
    p_target_version_id,
    citation.citation_id,
    citation.citation_purpose,
    citation.target_anchor_type,
    citation.target_anchor_data,
    citation.display_order,
    citation.public_safe,
    citation.created_by
  from editorial.resource_citations citation
  where citation.target_version_type =
          'playlist_version'
    and citation.target_version_id =
          p_source_working_version_id
    and (
      (
        citation.resource_kind = 'playlist'
        and citation.resource_id = p_resource_id
      )
      or (
        citation.resource_kind = 'playlist_item'
        and exists (
          select 1
          from editorial.playlist_version_items item
          where item.playlist_version_id =
                  p_target_version_id
            and item.playlist_item_resource_id =
                  citation.resource_id
        )
      )
    );

  insert into editorial.resource_credits (
    resource_id,
    resource_kind,
    target_version_type,
    target_version_id,
    credit_id,
    display_order,
    is_primary,
    public_safe,
    created_by
  )
  select
    root_credit.resource_id,
    root_credit.resource_kind,
    'playlist_version',
    p_target_version_id,
    root_credit.credit_id,
    v_root_offset
      + (
          row_number() over (
            order by
              root_credit.display_order,
              root_credit.id
          )
        )::integer
      - 1,
    root_credit.is_primary,
    root_credit.public_safe,
    root_credit.created_by
  from editorial.resource_credits root_credit
  where root_credit.target_version_type =
          'playlist_version'
    and root_credit.target_version_id =
          p_source_working_version_id
    and root_credit.resource_kind = 'playlist'
    and root_credit.resource_id = p_resource_id
    and (
      v_target_curator_credit_id is null
      or root_credit.credit_id <>
           v_target_curator_credit_id
    )
  order by
    root_credit.display_order,
    root_credit.id;

  insert into editorial.resource_credits (
    resource_id,
    resource_kind,
    target_version_type,
    target_version_id,
    credit_id,
    display_order,
    is_primary,
    public_safe,
    created_by
  )
  select
    item_credit.resource_id,
    item_credit.resource_kind,
    'playlist_version',
    p_target_version_id,
    item_credit.credit_id,
    item_credit.display_order,
    item_credit.is_primary,
    item_credit.public_safe,
    item_credit.created_by
  from editorial.resource_credits item_credit
  where item_credit.target_version_type =
          'playlist_version'
    and item_credit.target_version_id =
          p_source_working_version_id
    and item_credit.resource_kind =
          'playlist_item'
    and exists (
      select 1
      from editorial.playlist_version_items item
      where item.playlist_version_id =
              p_target_version_id
        and item.playlist_item_resource_id =
              item_credit.resource_id
    );

  perform
    platform_private.end_playlist_trust_copy_authorization(
      v_copy_authorization
    );
end;
$$;


ALTER FUNCTION "editorial"."copy_playlist_working_trust_to_version"("p_resource_id" "uuid", "p_source_working_version_id" "uuid", "p_target_version_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."correction_article_publication_proof"("p_application_id" "uuid") RETURNS TABLE("case_resource_id" "uuid", "application_id" "uuid", "affected_resource_id" "uuid", "article_id" "uuid", "challenged_version_id" "uuid", "application_resulting_version_id" "uuid", "corrected_version_id" "uuid", "content_fingerprint" "text", "article_slug" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
  select
    application.case_resource_id,
    application.id,
    application.target_resource_id,
    application_version.article_id,
    application.challenged_version_id,
    application.resulting_version_id,
    published_version.id,
    published_version.content_fingerprint,
    article.slug
  from editorial.correction_applications application
  join editorial.article_versions application_version
    on application_version.id =
      application.resulting_version_id
   and application_version.resource_id =
      application.target_resource_id
   and application_version.version_kind =
      'correction'
  join editorial.resources resource
    on resource.id =
      application.target_resource_id
   and resource.resource_kind = 'article'
  join editorial.article_versions published_version
    on published_version.id =
      resource.current_published_version_id
   and published_version.resource_id =
      application.target_resource_id
   and published_version.article_id =
      application_version.article_id
   and published_version.version_kind =
      'published'
   and published_version.content_fingerprint =
      application_version.content_fingerprint
  join editorial.article_resources binding
    on binding.resource_id =
      application.target_resource_id
   and binding.resource_kind = 'article'
   and binding.article_id =
      application_version.article_id
  join public.wk_articles article
    on article.id =
      application_version.article_id
  join public.wk_article_publication_snapshots snapshot
    on snapshot.article_id =
      application_version.article_id
   and snapshot.resource_id =
      application.target_resource_id
   and snapshot.version_id =
      published_version.id
   and snapshot.is_active
  where application.id =
      p_application_id
    and exists (
      select 1
      from editorial.article_lifecycle_events lifecycle_event
      where lifecycle_event.resource_id =
          application.target_resource_id
        and lifecycle_event.article_id =
          application_version.article_id
        and lifecycle_event.version_id =
          published_version.id
        and lifecycle_event.action =
          'published'
    )
    and editorial.article_snapshot_fingerprint(
      article.title,
      article.slug,
      article.excerpt,
      article.content_html,
      article.author,
      article.hero_image_id,
      article.hero_image_url,
      article.seo,
      article.wp_status,
      article.published_at,
      article.categories,
      article.tags
    ) = published_version.content_fingerprint;
$$;


ALTER FUNCTION "editorial"."correction_article_publication_proof"("p_application_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."correction_public_note_fingerprint"("p_case_resource_id" "uuid", "p_application_id" "uuid", "p_affected_resource_id" "uuid", "p_challenged_version_id" "uuid", "p_corrected_version_id" "uuid", "p_note_text" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'extensions'
    AS $$
  select encode(
    extensions.digest(
      convert_to(
        jsonb_build_object(
          'case_resource_id',
          p_case_resource_id,
          'application_id',
          p_application_id,
          'affected_resource_id',
          p_affected_resource_id,
          'challenged_version_id',
          p_challenged_version_id,
          'corrected_version_id',
          p_corrected_version_id,
          'note_text',
          btrim(p_note_text)
        )::text,
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );
$$;


ALTER FUNCTION "editorial"."correction_public_note_fingerprint"("p_case_resource_id" "uuid", "p_application_id" "uuid", "p_affected_resource_id" "uuid", "p_challenged_version_id" "uuid", "p_corrected_version_id" "uuid", "p_note_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."create_person_for_identity"("p_user_id" "uuid", "p_registry_author_id" "uuid", "p_external_contributor_id" "uuid", "p_link_method" "text", "p_link_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'auth', 'public', 'editorial'
    AS $$
declare
  v_person_resource_id uuid;
  v_existing_person_resource_id uuid;
  v_identity_link_id uuid;
  v_seed text;
  v_owner_id uuid;
  v_actor_id uuid := auth.uid();
  v_path text;
begin
  if num_nonnulls(
       p_user_id,
       p_registry_author_id,
       p_external_contributor_id
     ) <> 1
  then
    raise exception
      'Exactly one Person source identity is required.';
  end if;

  if p_link_method not in (
    'migration_seed',
    'account_provisioning',
    'registry_author_provisioning',
    'external_contributor_provisioning',
    'admin_reconciliation',
    'claim_approved',
    'person_merge',
    'person_split'
  ) then
    raise exception
      'Unsupported Person identity link method.';
  end if;

  if nullif(
       btrim(
         coalesce(
           p_link_reason,
           ''
         )
       ),
       ''
     ) is null
  then
    raise exception
      'Person identity link reason is required.';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      case
        when p_user_id is not null
          then 'person-source|user|' || p_user_id::text
        when p_registry_author_id is not null
          then 'person-source|registry-author|' || p_registry_author_id::text
        else 'person-source|external-contributor|' || p_external_contributor_id::text
      end,
      0
    )
  );

  if p_user_id is not null then
    select link.person_resource_id
    into v_existing_person_resource_id
    from editorial.person_identity_links link
    where link.user_id = p_user_id
      and link.link_state = 'active';

    if found then
      return v_existing_person_resource_id;
    end if;

    select
      coalesce(
        profile.username_normalized,
        profile.display_name
      ),
      profile.user_id
    into
      v_seed,
      v_owner_id
    from public.user_profiles profile
    where profile.user_id = p_user_id;

    if not found then
      raise exception
        'WAKILISHA account profile does not exist.';
    end if;

  elsif p_registry_author_id is not null then
    select link.person_resource_id
    into v_existing_person_resource_id
    from editorial.person_identity_links link
    where link.registry_author_id =
          p_registry_author_id
      and link.link_state = 'active';

    if found then
      return v_existing_person_resource_id;
    end if;

    select author.slug
    into v_seed
    from public.registry_authors author
    where author.id =
          p_registry_author_id;

    if not found then
      raise exception
        'Registry Author does not exist.';
    end if;

  else
    select link.person_resource_id
    into v_existing_person_resource_id
    from editorial.person_identity_links link
    where link.external_contributor_id =
          p_external_contributor_id
      and link.link_state = 'active';

    if found then
      return v_existing_person_resource_id;
    end if;

    select contributor.display_name
    into v_seed
    from editorial.external_contributors contributor
    where contributor.id =
          p_external_contributor_id;

    if not found then
      raise exception
        'External contributor does not exist.';
    end if;
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'person-path|'
      || coalesce(
           editorial.normalize_person_slug(v_seed),
           'person'
         ),
      0
    )
  );

  v_person_resource_id := gen_random_uuid();

  insert into editorial.resources (
    id,
    resource_kind,
    owner_id,
    visibility,
    lifecycle_state,
    created_by
  )
  values (
    v_person_resource_id,
    'person',
    v_owner_id,
    'internal',
    'active',
    v_actor_id
  );

  insert into editorial.people (
    resource_id,
    resource_kind,
    person_state,
    identity_revision,
    created_by,
    updated_by
  )
  values (
    v_person_resource_id,
    'person',
    'active',
    1,
    v_actor_id,
    v_actor_id
  );

  v_identity_link_id := gen_random_uuid();

  insert into editorial.person_identity_links (
    id,
    person_resource_id,
    person_resource_kind,
    user_id,
    registry_author_id,
    external_contributor_id,
    link_state,
    link_method,
    link_reason,
    created_by
  )
  values (
    v_identity_link_id,
    v_person_resource_id,
    'person',
    p_user_id,
    p_registry_author_id,
    p_external_contributor_id,
    'active',
    p_link_method,
    p_link_reason,
    v_actor_id
  );

  update editorial.people
  set
    preferred_identity_link_id =
      v_identity_link_id,
    updated_by = v_actor_id,
    updated_at = now()
  where resource_id =
        v_person_resource_id;

  v_path :=
    editorial.allocate_person_path(
      v_seed,
      v_person_resource_id
    );

  insert into editorial.resource_aliases (
    resource_id,
    path,
    is_canonical,
    created_by
  )
  values (
    v_person_resource_id,
    v_path,
    true,
    v_actor_id
  );

  insert into editorial.person_identity_events (
    person_resource_id,
    actor_id,
    event_type,
    identity_link_id,
    prior_identity_revision,
    resulting_identity_revision,
    reason
  )
  values (
    v_person_resource_id,
    v_actor_id,
    'person_created',
    v_identity_link_id,
    null,
    1,
    p_link_reason
  );

  perform editorial.refresh_person_visibility(
    v_person_resource_id
  );

  return v_person_resource_id;
end;
$$;


ALTER FUNCTION "editorial"."create_person_for_identity"("p_user_id" "uuid", "p_registry_author_id" "uuid", "p_external_contributor_id" "uuid", "p_link_method" "text", "p_link_reason" "text") OWNER TO "postgres";

