CREATE TABLE IF NOT EXISTS "public"."artist_representations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "artist_id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "representation_role" "text" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "source_claim_id" "uuid",
    "can_manage_profile" boolean DEFAULT false NOT NULL,
    "can_submit_releases" boolean DEFAULT false NOT NULL,
    "can_post_updates" boolean DEFAULT false NOT NULL,
    "can_manage_team" boolean DEFAULT false NOT NULL,
    "invited_by" "uuid",
    "invited_at" timestamp with time zone,
    "accepted_at" timestamp with time zone,
    "verified_by" "uuid",
    "verified_at" timestamp with time zone,
    "revoked_by" "uuid",
    "revoked_at" timestamp with time zone,
    "revocation_reason" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "artist_representation_activation_consistency" CHECK (((("status" = 'pending'::"text") AND ("accepted_at" IS NULL) AND ("revoked_at" IS NULL)) OR (("status" = 'active'::"text") AND ("revoked_at" IS NULL)) OR (("status" = 'revoked'::"text") AND ("revoked_at" IS NOT NULL) AND ("revocation_reason" IS NOT NULL)))),
    CONSTRAINT "artist_representations_representation_role_check" CHECK (("representation_role" = ANY (ARRAY['artist'::"text", 'manager'::"text", 'label'::"text", 'publicist'::"text", 'team_member'::"text", 'other'::"text"]))),
    CONSTRAINT "artist_representations_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'active'::"text", 'revoked'::"text"])))
);


