CREATE OR REPLACE FUNCTION "editorial"."derive_publishing_editorial_state"("p_resource_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'editorial'
    AS $$
declare
  v_resource editorial.resources%rowtype;
  v_latest_article_action text;
begin
  if p_resource_id is null then
    return 'not_linked';
  end if;

  if not exists (
    select 1
    from editorial.publishing_items item
    where item.resource_id = p_resource_id
      and editorial.current_user_can_view_publishing_item(
        item.id
      )
  ) then
    raise exception
      using
        errcode = '42501',
        message = 'Permission denied';
  end if;

  select resource.*
  into v_resource
  from editorial.resources resource
  where resource.id = p_resource_id;

  if not found then
    return 'not_linked';
  end if;

  if v_resource.resource_kind = 'article' then
    select event.action
    into v_latest_article_action
    from editorial.article_lifecycle_events event
    where event.resource_id = p_resource_id
      and event.action in (
        'submitted',
        'changes_requested',
        'approved',
        'scheduled',
        'published',
        'unpublished',
        'archived',
        'restored'
      )
    order by
      event.created_at desc,
      event.id desc
    limit 1;

    if v_latest_article_action =
       'changes_requested'
    then
      return 'changes_requested';
    end if;
  end if;

  if v_resource.lifecycle_state = 'published'
     and (
       v_resource.resource_kind <> 'article'
       or v_resource.current_published_version_id
          is not null
     )
  then
    return 'published';
  end if;

  if v_resource.current_approved_version_id
     is not null
  then
    return 'approved';
  end if;

  if v_resource.current_submitted_version_id
     is not null
  then
    return 'submitted';
  end if;

  return 'draft';
end;
$$;


ALTER FUNCTION "editorial"."derive_publishing_editorial_state"("p_resource_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."derive_publishing_publication_state"("p_item_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'editorial'
    AS $$
declare
  v_item editorial.publishing_items%rowtype;
  v_resource editorial.resources%rowtype;
begin
  if not editorial.current_user_can_view_publishing_item(
    p_item_id
  ) then
    raise exception
      using
        errcode = '42501',
        message = 'Permission denied';
  end if;

  select item.*
  into v_item
  from editorial.publishing_items item
  where item.id = p_item_id;

  if not found then
    return 'unscheduled';
  end if;

  if v_item.planning_state = 'archived' then
    return 'archived';
  end if;

  if v_item.planning_state = 'dropped' then
    return 'dropped';
  end if;

  if v_item.planning_state = 'paused' then
    return 'paused';
  end if;

  if v_item.resource_id is null then
    if v_item.planned_publish_at is not null then
      return 'scheduled';
    end if;

    return 'unscheduled';
  end if;

  select resource.*
  into v_resource
  from editorial.resources resource
  where resource.id = v_item.resource_id;

  if not found then
    return 'unscheduled';
  end if;

  if v_resource.lifecycle_state = 'published'
     and (
       v_resource.resource_kind <> 'article'
       or v_resource.current_published_version_id
          is not null
     )
  then
    return 'published';
  end if;

  if v_resource.resource_kind = 'article' then
    if exists (
      select 1
      from editorial.article_scheduled_publications schedule
      where schedule.resource_id = v_resource.id
        and schedule.status = 'scheduled'
    ) then
      return 'scheduled';
    end if;

    return 'unscheduled';
  end if;

  if v_item.planned_publish_at is not null then
    return 'scheduled';
  end if;

  return 'unscheduled';
end;
$$;


ALTER FUNCTION "editorial"."derive_publishing_publication_state"("p_item_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."enforce_playlist_curator_attachment_authority"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_target_version_type text;
  v_resource_kind text;
  v_target_version_id uuid;
  v_resource_id uuid;
  v_credit_id uuid;
  v_credit_role text;
  v_playlist_id uuid;
  v_version_kind text;
  v_curator_credit_id uuid;
begin
  if tg_op = 'DELETE' then
    v_target_version_type := old.target_version_type;
    v_resource_kind := old.resource_kind;
    v_target_version_id := old.target_version_id;
    v_resource_id := old.resource_id;
    v_credit_id := old.credit_id;
  else
    v_target_version_type := new.target_version_type;
    v_resource_kind := new.resource_kind;
    v_target_version_id := new.target_version_id;
    v_resource_id := new.resource_id;
    v_credit_id := new.credit_id;
  end if;

  if v_target_version_type <> 'playlist_version'
     or v_resource_kind <> 'playlist'
  then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;

  select
    version.playlist_id,
    version.version_kind
  into
    v_playlist_id,
    v_version_kind
  from editorial.playlist_versions version
  where version.id = v_target_version_id
    and version.resource_id = v_resource_id;

  if v_playlist_id is null then
    raise exception
      'Playlist Curator attachment requires a valid Playlist version';
  end if;

  select playlist.curator_credit_id
  into v_curator_credit_id
  from public.wk_playlists playlist
  where playlist.id = v_playlist_id;

  select credit.credit_role
  into v_credit_role
  from editorial.credits credit
  where credit.id = v_credit_id;

  if v_credit_role is distinct from 'curator' then
    if tg_op = 'DELETE' then
      return old;
    end if;

    if tg_op = 'INSERT'
       and v_version_kind = 'working'
       and v_curator_credit_id is not null
    then
      new.display_order := new.display_order + 1;
    end if;

    return new;
  end if;

  if tg_op = 'DELETE' then
    if v_curator_credit_id is not null
       and v_credit_id = v_curator_credit_id
    then
      -- Generic Credit replacement deletes the requested target set before
      -- reinserting it. Preserve the durable Curator row so ordinary Credit
      -- editing can coexist with Playlist attribution.
      return null;
    end if;

    return old;
  end if;

  if v_curator_credit_id is null
     or v_credit_id is distinct from v_curator_credit_id
  then
    raise exception
      'Use the Playlist Curator picker before attaching Curator credit';
  end if;

  new.display_order := 0;
  new.is_primary := true;
  new.public_safe := true;

  return new;
end;
$$;


ALTER FUNCTION "editorial"."enforce_playlist_curator_attachment_authority"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."enforce_playlist_curator_credit_identity"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'editorial'
    AS $$
declare
  v_curator record;
begin
  if new.curator_credit_id is null then
    return new;
  end if;

  select
    credit.id as credit_id,
    credit.display_name_snapshot as display_name
  into v_curator
  from editorial.credits credit
  where credit.id = new.curator_credit_id;

  if not found then
    raise exception
      'Playlist Curator Credit no longer exists';
  end if;

  if tg_op = 'INSERT'
     or new.curator_credit_id
          is distinct from old.curator_credit_id
  then
    perform 1
    from editorial.assert_playlist_curator_credit(
      new.curator_credit_id
    );
  elsif new.curator_label
          is distinct from old.curator_label
        and new.curator_label
          is distinct from v_curator.display_name
  then
    raise exception
      'Use the Curator picker to change Playlist attribution';
  end if;

  new.curator_label := v_curator.display_name;
  return new;
end;
$$;


