CREATE OR REPLACE FUNCTION "editorial"."insert_article_lifecycle_version_from_article"("p_resource" "editorial"."resources", "p_article" "public"."wk_articles", "p_version_kind" "text", "p_lifecycle_state" "text") RETURNS TABLE("version_id" "uuid", "version_number" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_version_id uuid;
  v_version_number bigint;
begin
  v_version_number :=
    editorial.next_article_version_number(
      p_resource.id
    );

  insert into editorial.article_versions (
    resource_id,
    article_id,
    version_number,
    version_kind,
    source_draft_version,
    title,
    slug,
    excerpt,
    content_html,
    author_display,
    owner_id,
    hero_image_id,
    hero_image_url,
    seo,
    lifecycle_state,
    wp_status,
    published_at,
    category_snapshot,
    tag_snapshot,
    created_by,
    content_fingerprint
  )
  values (
    p_resource.id,
    p_article.id,
    v_version_number,
    p_version_kind,
    p_article.draft_version,
    p_article.title,
    p_article.slug,
    p_article.excerpt,
    p_article.content_html,
    p_article.author,
    p_resource.owner_id,
    p_article.hero_image_id,
    p_article.hero_image_url,
    p_article.seo,
    p_lifecycle_state,
    p_article.wp_status,
    p_article.published_at,
    p_article.categories,
    p_article.tags,
    auth.uid(),
    editorial.article_snapshot_fingerprint(
      p_article.title,
      p_article.slug,
      p_article.excerpt,
      p_article.content_html,
      p_article.author,
      p_article.hero_image_id,
      p_article.hero_image_url,
      p_article.seo,
      p_article.wp_status,
      p_article.published_at,
      p_article.categories,
      p_article.tags
    )
  )
  returning id
  into v_version_id;

  version_id := v_version_id;
  version_number := v_version_number;
  return next;
end;
$$;


ALTER FUNCTION "editorial"."insert_article_lifecycle_version_from_article"("p_resource" "editorial"."resources", "p_article" "public"."wk_articles", "p_version_kind" "text", "p_lifecycle_state" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."insert_playlist_current_snapshot"("p_playlist_id" "uuid", "p_expected_authority_revision" bigint, "p_version_kind" "text", "p_snapshot_status" "text", "p_actor_id" "uuid") RETURNS TABLE("version_id" "uuid", "version_number" bigint, "content_fingerprint" "text", "item_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial', 'media'
    AS $$
declare
  v_playlist public.wk_playlists%rowtype;
  v_resource_id uuid;
  v_version_id uuid;
  v_version_number bigint;
  v_fingerprint text;
  v_item_count integer;
  v_cover media.usage_links%rowtype;
begin
  if p_version_kind not in (
    'working',
    'submitted'
  ) then
    raise exception
      'Current Playlist snapshot kind must be working or submitted';
  end if;

  select playlist.*
  into v_playlist
  from public.wk_playlists playlist
  where playlist.id = p_playlist_id
  for update;

  if not found then
    raise exception 'Playlist does not exist';
  end if;

  if p_expected_authority_revision is null
     or p_expected_authority_revision < 1
     or v_playlist.authority_revision
          <> p_expected_authority_revision
  then
    raise exception
      'Playlist authority revision conflict. Expected %, found %',
      p_expected_authority_revision,
      v_playlist.authority_revision;
  end if;

  select binding.resource_id
  into v_resource_id
  from editorial.playlist_resources binding
  where binding.playlist_id = p_playlist_id;

  if v_resource_id is null then
    raise exception
      'Playlist Resource binding does not exist';
  end if;

  v_fingerprint :=
    editorial.playlist_current_content_fingerprint(
      p_playlist_id
    );

  select count(*)::integer
  into v_item_count
  from public.wk_playlist_items item
  where item.playlist_id = p_playlist_id
    and item.lifecycle_state = 'active';

  select coalesce(
    max(version.version_number),
    0
  ) + 1
  into v_version_number
  from editorial.playlist_versions version
  where version.resource_id = v_resource_id;

  v_version_id := gen_random_uuid();

  select usage.*
  into v_cover
  from media.usage_links usage
  where usage.target_authority = 'editorial'
    and usage.target_kind = 'playlist'
    and usage.target_id = p_playlist_id
    and usage.target_version_id is null
    and usage.usage_role = 'playlist_cover'
    and usage.usage_state = 'active';

  if found
     and (
       v_cover.resolution_mode <> 'exact_revision'
       or v_cover.asset_revision_id is null
     )
  then
    raise exception
      'Playlist cover must resolve to an exact Media revision before snapshotting';
  end if;

  insert into editorial.playlist_versions (
    id,
    resource_id,
    playlist_id,
    version_number,
    version_kind,
    source_authority_revision,
    title,
    slug,
    description,
    curator_label,
    status,
    metadata,
    item_count,
    content_fingerprint,
    cover_asset_id,
    cover_asset_revision_id,
    cover_placement_data,
    cover_display_order,
    cover_alt_text_snapshot,
    cover_caption_snapshot,
    cover_credit_snapshot,
    created_by
  )
  values (
    v_version_id,
    v_resource_id,
    p_playlist_id,
    v_version_number,
    p_version_kind,
    v_playlist.authority_revision,
    v_playlist.title,
    v_playlist.slug,
    v_playlist.description,
    v_playlist.curator_label,
    p_snapshot_status,
    v_playlist.metadata,
    v_item_count,
    v_fingerprint,
    v_cover.asset_id,
    v_cover.asset_revision_id,
    coalesce(v_cover.placement_data, '{}'::jsonb),
    coalesce(v_cover.display_order, 0),
    v_cover.alt_text_snapshot,
    v_cover.caption_snapshot,
    v_cover.credit_snapshot,
    p_actor_id
  );

  insert into editorial.playlist_version_trust_revisions (
    playlist_version_id,
    citation_revision,
    credit_revision,
    updated_by,
    updated_at
  )
  values (
    v_version_id,
    1,
    1,
    p_actor_id,
    now()
  );

  insert into editorial.playlist_version_items (
    playlist_version_id,
    playlist_item_resource_id,
    playlist_item_id,
    position,
    registry_track_id,
    registry_release_id,
    provider_key,
    provider_track_id,
    provider_url,
    title,
    artist_names,
    release_title,
    artwork_url,
    preview_url,
    duration_ms,
    isrc,
    match_status,
    match_confidence,
    normalization_payload,
    notes
  )
  select
    v_version_id,
    binding.resource_id,
    item.id,
    item.position,
    item.registry_track_id,
    item.registry_release_id,
    item.provider_key,
    item.provider_track_id,
    item.provider_url,
    item.title,
    item.artist_names,
    item.release_title,
    item.artwork_url,
    item.preview_url,
    item.duration_ms,
    item.isrc,
    item.match_status,
    item.match_confidence,
    item.normalization_payload,
    item.notes
  from public.wk_playlist_items item
  join editorial.playlist_item_resources binding
    on binding.playlist_item_id = item.id
  where item.playlist_id = p_playlist_id
    and item.lifecycle_state = 'active'
  order by item.position;

  version_id := v_version_id;
  version_number := v_version_number;
  content_fingerprint := v_fingerprint;
  item_count := v_item_count;
  return next;
end;
$$;


ALTER FUNCTION "editorial"."insert_playlist_current_snapshot"("p_playlist_id" "uuid", "p_expected_authority_revision" bigint, "p_version_kind" "text", "p_snapshot_status" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."insert_source_registry_links"("p_source_id" "uuid", "p_source_version_id" "uuid", "p_registry_links" "jsonb", "p_actor_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_links jsonb;
begin
  v_links :=
    editorial.normalize_source_registry_links(p_registry_links);

  insert into editorial.source_registry_links (
    source_id,
    source_version_id,
    registry_entity_type,
    registry_entity_id,
    relationship_role,
    created_by
  )
  select
    p_source_id,
    p_source_version_id,
    link.registry_entity_type,
    link.registry_entity_id::uuid,
    link.relationship_role,
    p_actor_id
  from jsonb_to_recordset(v_links) as link(
    registry_entity_type text,
    registry_entity_id text,
    relationship_role text
  );
end;
$$;


ALTER FUNCTION "editorial"."insert_source_registry_links"("p_source_id" "uuid", "p_source_version_id" "uuid", "p_registry_links" "jsonb", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."list_current_public_person_work"("p_person_resource_id" "uuid") RETURNS TABLE("resource_id" "uuid", "resource_kind" "text", "canonical_path" "text", "title" "text", "summary" "text", "image_url" "text", "published_at" timestamp with time zone, "roles" "jsonb", "is_primary" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
  with eligible_person as (
    select person.resource_id
    from editorial.people person
    join editorial.resources person_resource
      on person_resource.id =
         person.resource_id
     and person_resource.resource_kind =
         'person'
    where person.resource_id =
          p_person_resource_id
      and person.person_state = 'active'
      and person_resource.visibility =
          'public'
      and person_resource.lifecycle_state =
          'active'
  ),
  article_work as (
    select
      resource.id as resource_id,
      'article'::text as resource_kind,
      coalesce(
        canonical_alias.path,
        '/magazine/' || version.slug
      ) as canonical_path,
      version.title,
      version.excerpt as summary,
      version.hero_image_url as image_url,
      version.published_at,
      jsonb_agg(
        jsonb_build_object(
          'role',
            credit.credit_role,
          'role_label',
            coalesce(
              nullif(
                btrim(
                  credit.role_label_snapshot
                ),
                ''
              ),
              credit.credit_role
            ),
          'display_order',
            attachment.display_order,
          'is_primary',
            attachment.is_primary
        )
        order by
          attachment.display_order,
          credit.id
      ) as roles,
      bool_or(
        attachment.is_primary
      ) as is_primary
    from eligible_person person
    join editorial.resources resource
      on resource.resource_kind = 'article'
     and resource.visibility = 'public'
     and resource.lifecycle_state =
         'published'
     and resource.current_published_version_id
         is not null
    join editorial.article_versions version
      on version.id =
         resource.current_published_version_id
     and version.resource_id =
         resource.id
     and version.published_at is not null
    join editorial.resource_credits attachment
      on attachment.resource_id =
         resource.id
     and attachment.resource_kind =
         'article'
     and attachment.target_version_type =
         'article_version'
     and attachment.target_version_id =
         version.id
     and attachment.public_safe
    join editorial.credits credit
      on credit.id =
         attachment.credit_id
    join editorial.credit_governance governance
      on governance.credit_id =
         credit.id
     and governance.public_safe
     and governance.credit_state =
         'active'
    left join editorial.external_contributors contributor
      on contributor.id =
         credit.external_contributor_id
    left join lateral (
      select alias.path
      from editorial.resource_aliases alias
      where alias.resource_id =
            resource.id
        and alias.is_canonical
        and alias.retired_at is null
      limit 1
    ) canonical_alias
      on true
    where editorial.resolve_credit_person(
            credit.id
          ) = person.resource_id
      and (
        credit.external_contributor_id is null
        or (
          contributor.contributor_state =
            'active'
          and contributor.public_safe
          and contributor.consent_status in (
            'granted',
            'not_required'
          )
        )
      )
    group by
      resource.id,
      canonical_alias.path,
      version.title,
      version.excerpt,
      version.hero_image_url,
      version.published_at,
      version.slug
  ),
  playlist_work as (
    select
      resource.id as resource_id,
      'playlist'::text as resource_kind,
      coalesce(
        canonical_alias.path,
        '/playlists/' || snapshot.slug
      ) as canonical_path,
      snapshot.title,
      snapshot.description as summary,
      snapshot.cover_url as image_url,
      snapshot.published_at,
      jsonb_agg(
        jsonb_build_object(
          'role',
            credit.credit_role,
          'role_label',
            coalesce(
              nullif(
                btrim(
                  credit.role_label_snapshot
                ),
                ''
              ),
              credit.credit_role
            ),
          'display_order',
            attachment.display_order,
          'is_primary',
            attachment.is_primary
        )
        order by
          attachment.display_order,
          credit.id
      ) as roles,
      bool_or(
        attachment.is_primary
      ) as is_primary
    from eligible_person person
    join editorial.resources resource
      on resource.resource_kind =
         'playlist'
     and resource.visibility = 'public'
     and resource.lifecycle_state =
         'published'
    join editorial.playlist_resources binding
      on binding.resource_id =
         resource.id
     and binding.current_published_version_id
         is not null
    join editorial.playlist_publication_snapshots snapshot
      on snapshot.resource_id =
         binding.resource_id
     and snapshot.playlist_id =
         binding.playlist_id
     and snapshot.version_id =
         binding.current_published_version_id
    join editorial.resource_credits attachment
      on attachment.resource_id =
         resource.id
     and attachment.resource_kind =
         'playlist'
     and attachment.target_version_type =
         'playlist_version'
     and attachment.target_version_id =
         snapshot.version_id
     and attachment.public_safe
    join editorial.credits credit
      on credit.id =
         attachment.credit_id
    join editorial.credit_governance governance
      on governance.credit_id =
         credit.id
     and governance.public_safe
     and governance.credit_state =
         'active'
    left join editorial.external_contributors contributor
      on contributor.id =
         credit.external_contributor_id
    left join lateral (
      select alias.path
      from editorial.resource_aliases alias
      where alias.resource_id =
            resource.id
        and alias.is_canonical
        and alias.retired_at is null
      limit 1
    ) canonical_alias
      on true
    where editorial.resolve_credit_person(
            credit.id
          ) = person.resource_id
      and (
        credit.external_contributor_id is null
        or (
          contributor.contributor_state =
            'active'
          and contributor.public_safe
          and contributor.consent_status in (
            'granted',
            'not_required'
          )
        )
      )
    group by
      resource.id,
      canonical_alias.path,
      snapshot.title,
      snapshot.description,
      snapshot.cover_url,
      snapshot.published_at,
      snapshot.slug
  )
  select *
  from article_work

  union all

  select *
  from playlist_work;
$$;


ALTER FUNCTION "editorial"."list_current_public_person_work"("p_person_resource_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."materialize_canonicalized_playlist_registry_intake"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'auth', 'public', 'editorial'
    AS $$
declare
  v_playlist public.wk_playlists%rowtype;
  v_playlist_resource editorial.resources%rowtype;
  v_item_id uuid;
  v_title text;
  v_release_id uuid;
  v_release_title text;
  v_artwork_url text;
  v_preview_url text;
  v_duration_ms integer;
  v_isrc text;
  v_artist_names text[];
  v_actor uuid;
begin
  if new.status <> 'canonicalized'
     or new.canonicalized_track_id is null
  then
    return new;
  end if;

  select playlist.*
  into v_playlist
  from public.wk_playlists playlist
  where playlist.id = new.source_playlist_id
  for update of playlist;

  if not found then
    raise exception
      'Canonicalized Registry intake lost its source Playlist.';
  end if;

  select
    track.title,
    track.release_id,
    release.title,
    coalesce(
      track.artwork_url,
      new.validation_snapshot ->> 'artwork_url'
    ),
    coalesce(
      track.preview_url,
      new.validation_snapshot ->> 'preview_url'
    ),
    track.duration_ms,
    track.isrc,
    coalesce(
      array_agg(
        coalesce(
          artist.display_name,
          link.artist_name_text
        )
        order by link.credit_order, link.id
      ) filter (
        where coalesce(
          artist.display_name,
          link.artist_name_text
        ) is not null
      ),
      '{}'::text[]
    )
  into
    v_title,
    v_release_id,
    v_release_title,
    v_artwork_url,
    v_preview_url,
    v_duration_ms,
    v_isrc,
    v_artist_names
  from public.registry_tracks track
  left join public.registry_releases release
    on release.id = track.release_id
  left join public.registry_track_artists link
    on link.track_id = track.id
    and link.status = 'active'
  left join public.registry_artists artist
    on artist.id = link.artist_id
  where track.id = new.canonicalized_track_id
    and track.status = 'active'
  group by
    track.id,
    track.title,
    track.release_id,
    release.title,
    track.artwork_url,
    track.preview_url,
    track.duration_ms,
    track.isrc;

  if not found then
    raise exception
      'Canonicalized Registry intake points to an unavailable track.';
  end if;

  v_actor := coalesce(
    new.reviewed_by,
    new.requested_by,
    auth.uid(),
    v_playlist.created_by
  );

  if new.source_playlist_item_id is not null then
    update public.wk_playlist_items item
    set
      registry_track_id = new.canonicalized_track_id,
      registry_release_id = v_release_id,
      provider_key = new.provider_key,
      provider_track_id = new.provider_object_id,
      provider_url = new.provider_url,
      title = v_title,
      artist_names = v_artist_names,
      release_title = v_release_title,
      artwork_url = v_artwork_url,
      preview_url = v_preview_url,
      duration_ms = v_duration_ms,
      isrc = v_isrc,
      match_status = 'matched',
      match_confidence = 1.0000,
      normalization_payload =
        coalesce(item.normalization_payload, '{}'::jsonb)
        || jsonb_build_object(
          'registry_intake_suggestion_id', new.id,
          'registry_intake_status', 'canonicalized',
          'playlist_position_authority', 'playlist_item',
          'playback', new.validation_snapshot
        ),
      notes = coalesce(item.notes, new.playlist_note)
    where item.id = new.source_playlist_item_id
      and item.playlist_id = new.source_playlist_id
      and item.lifecycle_state = 'active';

    if not found then
      raise exception
        'Canonicalized Registry intake lost its Playlist item.';
    end if;

    update public.wk_playlists playlist
    set authority_revision = playlist.authority_revision + 1
    where playlist.id = new.source_playlist_id;

    return new;
  end if;

  if new.reserved_position is null then
    raise exception
      'Legacy canonicalized Registry intake has no Playlist position.';
  end if;

  if exists (
    select 1
    from public.wk_playlist_items item
    where item.playlist_id = new.source_playlist_id
      and item.lifecycle_state = 'active'
      and item.position = new.reserved_position
  ) then
    raise exception
      'Reserved Playlist intake position is already occupied.';
  end if;

  select resource_row.*
  into v_playlist_resource
  from editorial.resources resource_row
  where resource_row.id = new.source_playlist_id;

  v_item_id := gen_random_uuid();

  insert into editorial.resources (
    id,
    resource_kind,
    owner_id,
    visibility,
    lifecycle_state,
    created_by
  )
  values (
    v_item_id,
    'playlist_item',
    v_playlist_resource.owner_id,
    'internal',
    'active',
    v_actor
  );

  insert into public.wk_playlist_items (
    id,
    playlist_id,
    position,
    registry_track_id,
    registry_release_id,
    provider_key,
    provider_track_id,
    provider_url,
    title,
    artist_names,
    release_title,
    artwork_url,
    preview_url,
    duration_ms,
    isrc,
    match_status,
    match_confidence,
    normalization_payload,
    notes,
    created_by,
    lifecycle_state
  )
  values (
    v_item_id,
    new.source_playlist_id,
    new.reserved_position,
    new.canonicalized_track_id,
    v_release_id,
    new.provider_key,
    new.provider_object_id,
    new.provider_url,
    v_title,
    v_artist_names,
    v_release_title,
    v_artwork_url,
    v_preview_url,
    v_duration_ms,
    v_isrc,
    'matched',
    1.0000,
    jsonb_build_object(
      'registry_intake_suggestion_id', new.id,
      'registry_intake_status', 'canonicalized',
      'playlist_position_authority', 'playlist_item',
      'playback', new.validation_snapshot
    ),
    new.playlist_note,
    v_actor,
    'active'
  );

  insert into editorial.playlist_item_resources (
    resource_id,
    resource_kind,
    playlist_item_id
  )
  values (
    v_item_id,
    'playlist_item',
    v_item_id
  );

  update public.registry_provider_track_suggestions suggestion
  set
    source_playlist_item_id = v_item_id,
    reserved_position = null
  where suggestion.id = new.id;

  update public.wk_playlists playlist
  set authority_revision = playlist.authority_revision + 1
  where playlist.id = new.source_playlist_id;

  return new;
end;
$$;


ALTER FUNCTION "editorial"."materialize_canonicalized_playlist_registry_intake"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."materialize_playlist_publication_snapshot"("p_version_id" "uuid", "p_published_at" timestamp with time zone, "p_published_by" "uuid", "p_command_receipt_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_version editorial.playlist_versions%rowtype;
  v_cover record;
  v_tracks jsonb;
  v_first_published_at timestamptz;
  v_snapshot_id uuid := gen_random_uuid();
  v_payload jsonb;
begin
  select version.*
  into v_version
  from editorial.playlist_versions version
  where version.id = p_version_id
    and version.version_kind = 'published';

  if not found then
    raise exception
      'Public Playlist snapshot requires a published Playlist version';
  end if;

  if exists (
    select 1
    from editorial.playlist_publication_snapshots snapshot
    where snapshot.version_id = p_version_id
  ) then
    select snapshot.id
    into v_snapshot_id
    from editorial.playlist_publication_snapshots snapshot
    where snapshot.version_id = p_version_id;

    return v_snapshot_id;
  end if;

  select
    null::uuid as logical_asset_id,
    null::text as resolved_mode,
    null::uuid as resolved_asset_revision_id,
    null::uuid as resolved_file_object_id,
    null::text as safe_delivery_url,
    null::text as resolved_mime_type,
    null::integer as width,
    null::integer as height,
    null::numeric as duration_seconds,
    null::text as approved_alt_text,
    null::text as approved_caption,
    null::text as approved_credit
  into v_cover;

  if v_version.cover_asset_id is not null then
    select *
    into v_cover
    from public.resolve_media_asset_delivery(
      v_version.cover_asset_id,
      null,
      v_version.cover_asset_revision_id,
      null
    );
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'playlist_item_resource_id',
          item.playlist_item_resource_id,
        'playlist_item_id',
          item.playlist_item_id,
        'position',
          item.position,
        'title',
          item.title,
        'artist_names',
          to_jsonb(item.artist_names),
        'artists',
          artist_credits.artists,
        'release_title',
          item.release_title,
        'artwork_url',
          item.artwork_url,
        'duration_ms',
          item.duration_ms,
        'notes',
          item.notes,
        'match_status',
          item.match_status,
        'registry',
          case
            when registry_track.id is null then null
            else jsonb_build_object(
              'track_id',
                registry_track.id,
              'track_slug',
                registry_track.slug,
              'track_path',
                case
                  when primary_artist.slug is not null
                    then
                      '/tracks/'
                      || primary_artist.slug
                      || '/'
                      || registry_track.slug
                  else null
                end,
              'release_id',
                registry_release.id,
              'release_slug',
                registry_release.slug,
              'release_path',
                case
                  when registry_release.id is not null
                       and primary_artist.slug is not null
                    then
                      '/releases/'
                      || primary_artist.slug
                      || '/'
                      || registry_release.slug
                  else null
                end,
              'primary_artist_id',
                primary_artist.id,
              'primary_artist_slug',
                primary_artist.slug,
              'primary_artist_name',
                primary_artist.display_name
            )
          end,
        'playback',
          jsonb_build_object(
            'playable',
              playback.playable,
            'engine',
              playback.engine,
            'provider_key',
              normalized.provider_key,
            'provider_object_id',
              normalized.provider_object_id,
            'provider_url',
              normalized.provider_url,
            'embed_url',
              normalized.embed_url,
            'preview_url',
              normalized.preview_url,
            'fallback_preview_url',
              item.preview_url,
            'apple_music_catalog_id',
              apple_music.apple_music_catalog_id
          )
      )
      order by item.position
    ),
    '[]'::jsonb
  )
  into v_tracks
  from editorial.playlist_version_items item

  left join public.registry_tracks registry_track
    on registry_track.id = item.registry_track_id
   and registry_track.status = 'active'

  left join public.registry_releases registry_release
    on registry_release.id =
         coalesce(
           item.registry_release_id,
           registry_track.release_id
         )
   and registry_release.status = 'active'

  left join lateral (
    select
      artist.id,
      artist.slug,
      artist.display_name
    from public.registry_track_artists credit
    join public.registry_artists artist
      on artist.id = credit.artist_id
    where credit.track_id = item.registry_track_id
      and credit.status = 'active'
      and artist.status = 'active'
    order by
      credit.is_primary desc,
      credit.id
    limit 1
  ) primary_artist on true

  left join lateral (
    select
      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'artist_id',
              artist.id,
            'artist_slug',
              artist.slug,
            'name',
              artist.display_name,
            'image_url',
              artist.public_image_url,
            'role',
              credit.role,
            'is_primary',
              credit.is_primary,
            'is_featured',
              credit.is_featured,
            'credit_order',
              credit.credit_order,
            'display_credit',
              credit.display_credit
          )
          order by
            coalesce(
              credit.credit_order,
              2147483647
            ),
            credit.is_primary desc,
            credit.is_featured desc,
            credit.id
        ),
        '[]'::jsonb
      ) as artists
    from public.registry_track_artists credit
    join public.registry_artists artist
      on artist.id =
           credit.artist_id
    where credit.track_id =
          item.registry_track_id
      and credit.status =
          'active'
      and artist.status =
          'active'
  ) artist_credits on true

  left join lateral (
    select
      coalesce(
        nullif(btrim(item.provider_key), ''),
        nullif(
          btrim(
            item.normalization_payload
              #>> '{playback,provider_key}'
          ),
          ''
        ),
        case
          when lower(
            coalesce(item.provider_url, '')
          ) like '%youtube.com/%'
            or lower(
              coalesce(item.provider_url, '')
            ) like '%youtu.be/%'
            then 'youtube'

          when lower(
            coalesce(item.provider_url, '')
          ) like '%soundcloud.com/%'
            then 'soundcloud'

          when lower(
            coalesce(item.provider_url, '')
          ) like '%music.apple.com/%'
            then 'apple_music'

          when lower(
            coalesce(item.provider_url, '')
          ) like '%open.spotify.com/%'
            then 'spotify'

          else null
        end
      ) as provider_key,

      coalesce(
        nullif(btrim(item.provider_track_id), ''),
        nullif(
          btrim(
            item.normalization_payload
              #>> '{playback,provider_object_id}'
          ),
          ''
        )
      ) as provider_object_id,

      coalesce(
        nullif(btrim(item.provider_url), ''),
        nullif(
          btrim(
            item.normalization_payload
              #>> '{playback,provider_url}'
          ),
          ''
        )
      ) as provider_url,

      nullif(
        btrim(
          item.normalization_payload
            #>> '{playback,embed_url}'
        ),
        ''
      ) as embed_url,

      coalesce(
        nullif(btrim(item.preview_url), ''),
        nullif(
          btrim(
            item.normalization_payload
              #>> '{playback,preview_url}'
          ),
          ''
        )
      ) as preview_url
  ) normalized on true

  left join lateral (
    select
      coalesce(
        case
          when normalized.provider_key = 'apple_music'
            then normalized.provider_object_id
          else null
        end,

        (
          select
            nullif(
              btrim(
                link.provider_track_id
              ),
              ''
            )
          from public.registry_track_provider_links link
          where link.track_id =
                item.registry_track_id
            and link.provider_key =
                'apple_music'
            and link.match_status =
                'matched'
          order by
            link.match_confidence desc,
            link.last_checked_at desc,
            link.created_at desc
          limit 1
        ),

        nullif(
          btrim(
            registry_track.metadata
              ->> 'apple_music_track_id'
          ),
          ''
        ),

        nullif(
          btrim(
            registry_track.metadata
              ->> 'apple_music_id'
          ),
          ''
        ),

        nullif(
          btrim(
            registry_track.metadata
              ->> 'appleMusicId'
          ),
          ''
        ),

        nullif(
          btrim(
            registry_track.metadata
              ->> 'apple_music_catalog_id'
          ),
          ''
        ),

        nullif(
          btrim(
            registry_track.metadata
              ->> 'appleMusicCatalogId'
          ),
          ''
        ),

        nullif(
          btrim(
            registry_track.metadata
              #>> '{apple_music,id}'
          ),
          ''
        ),

        nullif(
          btrim(
            registry_track.metadata
              #>> '{apple_music,catalog_id}'
          ),
          ''
        ),

        nullif(
          btrim(
            registry_track.metadata
              #>> '{appleMusic,id}'
          ),
          ''
        ),

        nullif(
          btrim(
            registry_track.metadata
              #>> '{appleMusic,catalogId}'
          ),
          ''
        ),

        nullif(
          btrim(
            registry_track.metadata
              #>> '{providers,apple_music,id}'
          ),
          ''
        ),

        nullif(
          btrim(
            registry_track.metadata
              #>> '{providers,apple_music,catalog_id}'
          ),
          ''
        ),

        nullif(
          btrim(
            registry_track.metadata
              #>> '{provider_ids,apple_music}'
          ),
          ''
        ),

        nullif(
          btrim(
            registry_track.metadata
              #>> '{source_ids,apple_music}'
          ),
          ''
        )
      ) as apple_music_catalog_id
  ) apple_music on true

  left join lateral (
    select
      case
        when normalized.provider_key = 'youtube'
             and normalized.provider_object_id is not null
          then 'youtube'

        when normalized.provider_key = 'soundcloud'
             and normalized.provider_url is not null
          then 'soundcloud'

        when normalized.provider_key = 'apple_music'
             and normalized.provider_object_id is not null
          then 'apple_music'

        when normalized.preview_url is not null
          then 'audio'

        else 'unavailable'
      end as engine,

      case
        when normalized.provider_key = 'youtube'
             and normalized.provider_object_id is not null
          then true

        when normalized.provider_key = 'soundcloud'
             and normalized.provider_url is not null
          then true

        when normalized.provider_key = 'apple_music'
             and normalized.provider_object_id is not null
          then true

        when normalized.preview_url is not null
          then true

        else false
      end as playable
  ) playback on true

  where item.playlist_version_id = p_version_id;

  select coalesce(
    min(snapshot.first_published_at),
    p_published_at
  )
  into v_first_published_at
  from editorial.playlist_publication_snapshots snapshot
  where snapshot.playlist_id = v_version.playlist_id;

  v_payload := jsonb_build_object(
    'playlist_id',
      v_version.playlist_id,
    'resource_id',
      v_version.resource_id,
    'version_id',
      v_version.id,
    'version_number',
      v_version.version_number,
    'slug',
      v_version.slug,
    'title',
      v_version.title,
    'description',
      v_version.description,
    'curator_label',
      v_version.curator_label,
    'cover',
      case
        when v_version.cover_asset_id is null
          then null
        else jsonb_build_object(
          'asset_id',
            v_version.cover_asset_id,
          'asset_revision_id',
            v_version.cover_asset_revision_id,
          'url',
            v_cover.safe_delivery_url,
          'mime_type',
            v_cover.resolved_mime_type,
          'width',
            v_cover.width,
          'height',
            v_cover.height,
          'alt_text',
            coalesce(
              v_version.cover_alt_text_snapshot,
              v_cover.approved_alt_text
            ),
          'caption',
            coalesce(
              v_version.cover_caption_snapshot,
              v_cover.approved_caption
            ),
          'credit',
            coalesce(
              v_version.cover_credit_snapshot,
              v_cover.approved_credit
            )
        )
      end,
    'item_count',
      v_version.item_count,
    'tracks',
      v_tracks,
    'provenance',
      jsonb_build_object(
        'version_number',
          v_version.version_number,
        'content_fingerprint',
          v_version.content_fingerprint,
        'source_authority_revision',
          v_version.source_authority_revision,
        'published_at',
          p_published_at,
        'first_published_at',
          v_first_published_at,
        'published_by',
          p_published_by,
        'command_receipt_id',
          p_command_receipt_id
      )
  );

  insert into editorial.playlist_publication_snapshots (
    id,
    resource_id,
    playlist_id,
    version_id,
    command_receipt_id,
    slug,
    title,
    description,
    curator_label,
    cover_url,
    cover_alt_text,
    cover_caption,
    cover_credit,
    item_count,
    content_fingerprint,
    payload,
    published_at,
    first_published_at,
    published_by
  )
  values (
    v_snapshot_id,
    v_version.resource_id,
    v_version.playlist_id,
    v_version.id,
    p_command_receipt_id,
    v_version.slug,
    v_version.title,
    v_version.description,
    v_version.curator_label,
    case
      when v_version.cover_asset_id is null
        then null
      else v_cover.safe_delivery_url
    end,
    case
      when v_version.cover_asset_id is null
        then null
      else coalesce(
        v_version.cover_alt_text_snapshot,
        v_cover.approved_alt_text
      )
    end,
    case
      when v_version.cover_asset_id is null
        then null
      else coalesce(
        v_version.cover_caption_snapshot,
        v_cover.approved_caption
      )
    end,
    case
      when v_version.cover_asset_id is null
        then null
      else coalesce(
        v_version.cover_credit_snapshot,
        v_cover.approved_credit
      )
    end,
    v_version.item_count,
    v_version.content_fingerprint,
    v_payload,
    p_published_at,
    v_first_published_at,
    p_published_by
  );

  return v_snapshot_id;
end;
$$;


ALTER FUNCTION "editorial"."materialize_playlist_publication_snapshot"("p_version_id" "uuid", "p_published_at" timestamp with time zone, "p_published_by" "uuid", "p_command_receipt_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."next_article_version_number"("p_resource_id" "uuid") RETURNS bigint
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'editorial'
    AS $$
  select coalesce(
    max(version.version_number),
    0
  ) + 1
  from editorial.article_versions version
  where version.resource_id = p_resource_id;
$$;


ALTER FUNCTION "editorial"."next_article_version_number"("p_resource_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."next_playlist_position_with_registry_intake"("p_playlist_id" "uuid", "p_exclude_item_id" "uuid" DEFAULT NULL::"uuid") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select greatest(
    coalesce(
      (
        select max(item.position)
        from public.wk_playlist_items item
        where item.playlist_id = p_playlist_id
          and item.lifecycle_state = 'active'
          and (
            p_exclude_item_id is null
            or item.id <> p_exclude_item_id
          )
      ),
      0
    ),
    coalesce(
      (
        select max(suggestion.reserved_position)
        from public.registry_provider_track_suggestions suggestion
        where suggestion.source_playlist_id = p_playlist_id
          and suggestion.status = 'needs_review'
          and suggestion.source_playlist_item_id is null
          and suggestion.canonical_track_id is null
      ),
      0
    )
  ) + 1;
$$;


ALTER FUNCTION "editorial"."next_playlist_position_with_registry_intake"("p_playlist_id" "uuid", "p_exclude_item_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."normalize_person_slug"("p_seed" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare
  v_slug text;
begin
  v_slug := lower(
    regexp_replace(
      btrim(
        coalesce(
          p_seed,
          ''
        )
      ),
      '[^[:alnum:]]+',
      '-',
      'g'
    )
  );

  v_slug := regexp_replace(
    v_slug,
    '(^-+|-+$)',
    '',
    'g'
  );

  return nullif(v_slug, '');
end;
$_$;


ALTER FUNCTION "editorial"."normalize_person_slug"("p_seed" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."normalize_playlist_status_after_content_change"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog'
    AS $$
begin
  if new.authority_revision > old.authority_revision
     and new.status = old.status
     and old.status in (
       'ready_for_review',
       'in_review',
       'approved'
     )
  then
    new.status := 'draft';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "editorial"."normalize_playlist_status_after_content_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."normalize_source_metadata"("p_metadata" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_metadata jsonb;
begin
  if p_metadata is null
     or jsonb_typeof(p_metadata) <> 'object' then
    raise exception
      'Source metadata must be a JSON object';
  end if;

  if nullif(btrim(p_metadata ->> 'source_type'), '') is null then
    raise exception
      'Source metadata requires source_type';
  end if;

  if nullif(btrim(p_metadata ->> 'title'), '') is null then
    raise exception
      'Source metadata requires title';
  end if;

  v_metadata := jsonb_build_object(
    'source_type',
      btrim(p_metadata ->> 'source_type'),
    'title',
      btrim(p_metadata ->> 'title'),
    'creator_display',
      nullif(btrim(p_metadata ->> 'creator_display'), ''),
    'publisher_display',
      nullif(btrim(p_metadata ->> 'publisher_display'), ''),
    'source_url',
      nullif(btrim(p_metadata ->> 'source_url'), ''),
    'media_asset_id',
      nullif(btrim(p_metadata ->> 'media_asset_id'), ''),
    'archive_identifier',
      nullif(btrim(p_metadata ->> 'archive_identifier'), ''),
    'publication_date',
      nullif(btrim(p_metadata ->> 'publication_date'), ''),
    'capture_date',
      nullif(btrim(p_metadata ->> 'capture_date'), ''),
    'retrieval_date',
      nullif(btrim(p_metadata ->> 'retrieval_date'), ''),
    'language_code',
      nullif(lower(btrim(p_metadata ->> 'language_code')), ''),
    'country_code',
      nullif(upper(btrim(p_metadata ->> 'country_code')), ''),
    'place_text',
      nullif(btrim(p_metadata ->> 'place_text'), ''),
    'rights_status',
      coalesce(
        nullif(btrim(p_metadata ->> 'rights_status'), ''),
        'unknown'
      ),
    'consent_status',
      coalesce(
        nullif(btrim(p_metadata ->> 'consent_status'), ''),
        'unknown'
      ),
    'sensitivity',
      coalesce(
        nullif(btrim(p_metadata ->> 'sensitivity'), ''),
        'none'
      ),
    'reliability_note',
      nullif(btrim(p_metadata ->> 'reliability_note'), ''),
    'credit_line',
      nullif(btrim(p_metadata ->> 'credit_line'), ''),
    'internal_notes',
      nullif(btrim(p_metadata ->> 'internal_notes'), '')
  );

  return jsonb_strip_nulls(v_metadata);
end;
$$;


ALTER FUNCTION "editorial"."normalize_source_metadata"("p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."normalize_source_registry_links"("p_registry_links" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $_$
declare
  v_normalized jsonb;
begin
  if p_registry_links is null then
    return '[]'::jsonb;
  end if;

  if jsonb_typeof(p_registry_links) <> 'array' then
    raise exception
      'Source Registry links must be a JSON array';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_registry_links) as item(value)
    where jsonb_typeof(item.value) <> 'object'
       or nullif(
            btrim(item.value ->> 'registry_entity_type'),
            ''
          ) is null
       or nullif(
            btrim(item.value ->> 'registry_entity_id'),
            ''
          ) is null
  ) then
    raise exception
      'Every Source Registry link requires registry_entity_type and registry_entity_id';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(p_registry_links) as link(
      registry_entity_type text,
      registry_entity_id text,
      relationship_role text
    )
    where link.registry_entity_type not in (
      'artist',
      'author',
      'genre',
      'label',
      'release',
      'track'
    )
       or coalesce(
            nullif(btrim(link.relationship_role), ''),
            'context'
          ) not in (
            'subject',
            'creator',
            'publisher',
            'custodian',
            'mentioned',
            'context'
          )
       or link.registry_entity_id !~
            '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
  ) then
    raise exception
      'Source Registry link contains an invalid entity type, UUID, or relationship role';
  end if;

  if exists (
    select 1
    from (
      select
        link.registry_entity_type,
        link.registry_entity_id,
        coalesce(
          nullif(btrim(link.relationship_role), ''),
          'context'
        ) as relationship_role,
        count(*) as duplicate_count
      from jsonb_to_recordset(p_registry_links) as link(
        registry_entity_type text,
        registry_entity_id text,
        relationship_role text
      )
      group by
        link.registry_entity_type,
        link.registry_entity_id,
        coalesce(
          nullif(btrim(link.relationship_role), ''),
          'context'
        )
      having count(*) > 1
    ) duplicates
  ) then
    raise exception
      'Source Registry links contain duplicate identities';
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'registry_entity_type',
          link.registry_entity_type,
        'registry_entity_id',
          lower(link.registry_entity_id),
        'relationship_role',
          coalesce(
            nullif(btrim(link.relationship_role), ''),
            'context'
          )
      )
      order by
        link.registry_entity_type,
        lower(link.registry_entity_id),
        coalesce(
          nullif(btrim(link.relationship_role), ''),
          'context'
        )
    ),
    '[]'::jsonb
  )
  into v_normalized
  from jsonb_to_recordset(p_registry_links) as link(
    registry_entity_type text,
    registry_entity_id text,
    relationship_role text
  );

  return v_normalized;
end;
$_$;


ALTER FUNCTION "editorial"."normalize_source_registry_links"("p_registry_links" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."playlist_current_content_fingerprint"("p_playlist_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial', 'media', 'extensions'
    AS $$
declare
  v_playlist public.wk_playlists%rowtype;
  v_resource_id uuid;
  v_items jsonb;
  v_cover_count integer;
  v_cover jsonb := null;
begin
  select playlist.*
  into v_playlist
  from public.wk_playlists playlist
  where playlist.id = p_playlist_id;

  if not found then
    raise exception 'Playlist does not exist';
  end if;

  select binding.resource_id
  into v_resource_id
  from editorial.playlist_resources binding
  where binding.playlist_id = p_playlist_id;

  if v_resource_id is null then
    raise exception
      'Playlist Resource binding does not exist';
  end if;

  select count(*)
  into v_cover_count
  from media.usage_links usage
  where usage.target_authority = 'editorial'
    and usage.target_kind = 'playlist'
    and usage.target_id = p_playlist_id
    and usage.target_version_id is null
    and usage.usage_role = 'playlist_cover'
    and usage.usage_state = 'active';

  if v_cover_count > 1 then
    raise exception
      'Playlist has more than one active canonical cover';
  end if;

  if v_cover_count = 1 then
    select jsonb_build_object(
      'asset_id', usage.asset_id,
      'asset_revision_id', usage.asset_revision_id,
      'resolution_mode', usage.resolution_mode,
      'placement_data', usage.placement_data,
      'alt_text_snapshot', usage.alt_text_snapshot,
      'caption_snapshot', usage.caption_snapshot,
      'credit_snapshot', usage.credit_snapshot
    )
    into v_cover
    from media.usage_links usage
    where usage.target_authority = 'editorial'
      and usage.target_kind = 'playlist'
      and usage.target_id = p_playlist_id
      and usage.target_version_id is null
      and usage.usage_role = 'playlist_cover'
      and usage.usage_state = 'active';

    if v_cover ->> 'resolution_mode'
         <> 'exact_revision'
       or nullif(
            v_cover ->> 'asset_revision_id',
            ''
          ) is null
    then
      raise exception
        'Playlist cover must resolve to an exact Media revision before snapshotting';
    end if;
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'playlist_item_resource_id',
          binding.resource_id,
        'playlist_item_id',
          item.id,
        'position',
          item.position,
        'registry_track_id',
          item.registry_track_id,
        'registry_release_id',
          item.registry_release_id,
        'provider_key',
          item.provider_key,
        'provider_track_id',
          item.provider_track_id,
        'provider_url',
          item.provider_url,
        'title',
          item.title,
        'artist_names',
          to_jsonb(item.artist_names),
        'release_title',
          item.release_title,
        'artwork_url',
          item.artwork_url,
        'preview_url',
          item.preview_url,
        'duration_ms',
          item.duration_ms,
        'isrc',
          item.isrc,
        'match_status',
          item.match_status,
        'match_confidence',
          item.match_confidence,
        'normalization_payload',
          item.normalization_payload,
        'notes',
          item.notes
      )
      order by item.position
    ),
    '[]'::jsonb
  )
  into v_items
  from public.wk_playlist_items item
  join editorial.playlist_item_resources binding
    on binding.playlist_item_id = item.id
  where item.playlist_id = p_playlist_id
    and item.lifecycle_state = 'active';

  return encode(
    extensions.digest(
      convert_to(
        jsonb_build_object(
          'playlist_id', p_playlist_id,
          'title', v_playlist.title,
          'slug', v_playlist.slug,
          'description', v_playlist.description,
          'curator_label', v_playlist.curator_label,
          'metadata', v_playlist.metadata,
          'cover', v_cover,
          'items', v_items
        )::text,
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );
end;
$$;


ALTER FUNCTION "editorial"."playlist_current_content_fingerprint"("p_playlist_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."playlist_duplicate_item_ids"("p_playlist_id" "uuid", "p_exclude_item_id" "uuid", "p_registry_track_id" "uuid", "p_provider_key" "text", "p_provider_track_id" "text", "p_title" "text", "p_artist_names" "text"[]) RETURNS "uuid"[]
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select coalesce(
    array_agg(item.id order by item.position),
    '{}'::uuid[]
  )
  from public.wk_playlist_items item
  where item.playlist_id = p_playlist_id
    and item.lifecycle_state = 'active'
    and (
      p_exclude_item_id is null
      or item.id <> p_exclude_item_id
    )
    and (
      (
        p_registry_track_id is not null
        and item.registry_track_id = p_registry_track_id
      )
      or (
        p_provider_key is not null
        and p_provider_track_id is not null
        and item.provider_key = p_provider_key
        and item.provider_track_id = p_provider_track_id
      )
      or (
        nullif(btrim(p_title), '') is not null
        and lower(btrim(coalesce(item.title, ''))) =
          lower(btrim(p_title))
        and lower(btrim(coalesce(item.artist_names[1], ''))) =
          lower(btrim(coalesce(p_artist_names[1], '')))
        and nullif(
          btrim(coalesce(p_artist_names[1], '')),
          ''
        ) is not null
      )
    );
$$;


ALTER FUNCTION "editorial"."playlist_duplicate_item_ids"("p_playlist_id" "uuid", "p_exclude_item_id" "uuid", "p_registry_track_id" "uuid", "p_provider_key" "text", "p_provider_track_id" "text", "p_title" "text", "p_artist_names" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."playlist_version_public_presentation_json"("p_version_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_version editorial.playlist_versions%rowtype;
  v_cover record;
  v_tracks jsonb;
  v_first_published_at timestamptz;
  v_credits jsonb;
  v_citations jsonb;
  v_corrections jsonb;
  v_payload jsonb;
begin
  select version.*
  into v_version
  from editorial.playlist_versions version
  where version.id = p_version_id;

  if not found then
    return null;
  end if;

  select
    null::uuid as logical_asset_id,
    null::text as resolved_mode,
    null::uuid as resolved_asset_revision_id,
    null::uuid as resolved_file_object_id,
    null::text as safe_delivery_url,
    null::text as resolved_mime_type,
    null::integer as width,
    null::integer as height,
    null::numeric as duration_seconds,
    null::text as approved_alt_text,
    null::text as approved_caption,
    null::text as approved_credit
  into v_cover;

  if v_version.cover_asset_id is not null then
    select *
    into v_cover
    from public.resolve_media_asset_delivery(
      v_version.cover_asset_id,
      null,
      v_version.cover_asset_revision_id,
      null
    );
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'playlist_item_resource_id', item.playlist_item_resource_id,
        'playlist_item_id', item.playlist_item_id,
        'position', item.position,
        'title', item.title,
        'artist_names', to_jsonb(item.artist_names),
        'artists', artist_credits.artists,
        'release_title', item.release_title,
        'artwork_url', item.artwork_url,
        'duration_ms', item.duration_ms,
        'notes', item.notes,
        'match_status', item.match_status,
        'registry',
          case
            when registry_track.id is null then null
            else jsonb_build_object(
              'track_id', registry_track.id,
              'track_slug', registry_track.slug,
              'track_path',
                case
                  when primary_artist.slug is not null
                    then '/tracks/' || primary_artist.slug || '/' || registry_track.slug
                  else null
                end,
              'release_id', registry_release.id,
              'release_slug', registry_release.slug,
              'release_path',
                case
                  when registry_release.id is not null
                       and primary_artist.slug is not null
                    then '/releases/' || primary_artist.slug || '/' || registry_release.slug
                  else null
                end,
              'primary_artist_id', primary_artist.id,
              'primary_artist_slug', primary_artist.slug,
              'primary_artist_name', primary_artist.display_name
            )
          end,
        'playback',
          jsonb_build_object(
            'playable', playback.playable,
            'engine', playback.engine,
            'provider_key', normalized.provider_key,
            'provider_object_id', normalized.provider_object_id,
            'provider_url', normalized.provider_url,
            'embed_url', normalized.embed_url,
            'preview_url', normalized.preview_url,
            'fallback_preview_url', item.preview_url,
            'apple_music_catalog_id', apple_music.apple_music_catalog_id
          )
      )
      order by item.position
    ),
    '[]'::jsonb
  )
  into v_tracks
  from editorial.playlist_version_items item

  left join public.registry_tracks registry_track
    on registry_track.id = item.registry_track_id
   and registry_track.status = 'active'

  left join public.registry_releases registry_release
    on registry_release.id =
         coalesce(
           item.registry_release_id,
           registry_track.release_id
         )
   and registry_release.status = 'active'

  left join lateral (
    select
      artist.id,
      artist.slug,
      artist.display_name
    from public.registry_track_artists credit
    join public.registry_artists artist
      on artist.id = credit.artist_id
    where credit.track_id = item.registry_track_id
      and credit.status = 'active'
      and artist.status = 'active'
    order by
      credit.is_primary desc,
      credit.id
    limit 1
  ) primary_artist on true

  left join lateral (
    select
      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'artist_id', artist.id,
            'artist_slug', artist.slug,
            'name', artist.display_name,
            'image_url', artist.public_image_url,
            'role', credit.role,
            'is_primary', credit.is_primary,
            'is_featured', credit.is_featured,
            'credit_order', credit.credit_order,
            'display_credit', credit.display_credit
          )
          order by
            coalesce(credit.credit_order, 2147483647),
            credit.is_primary desc,
            credit.is_featured desc,
            credit.id
        ),
        '[]'::jsonb
      ) as artists
    from public.registry_track_artists credit
    join public.registry_artists artist
      on artist.id = credit.artist_id
    where credit.track_id = item.registry_track_id
      and credit.status = 'active'
      and artist.status = 'active'
  ) artist_credits on true

  left join lateral (
    select
      coalesce(
        nullif(btrim(item.provider_key), ''),
        nullif(
          btrim(item.normalization_payload #>> '{playback,provider_key}'),
          ''
        ),
        case
          when lower(coalesce(item.provider_url, '')) like '%youtube.com/%'
            or lower(coalesce(item.provider_url, '')) like '%youtu.be/%'
            then 'youtube'
          when lower(coalesce(item.provider_url, '')) like '%soundcloud.com/%'
            then 'soundcloud'
          when lower(coalesce(item.provider_url, '')) like '%music.apple.com/%'
            then 'apple_music'
          when lower(coalesce(item.provider_url, '')) like '%open.spotify.com/%'
            then 'spotify'
          else null
        end
      ) as provider_key,

      coalesce(
        nullif(btrim(item.provider_track_id), ''),
        nullif(
          btrim(item.normalization_payload #>> '{playback,provider_object_id}'),
          ''
        )
      ) as provider_object_id,

      coalesce(
        nullif(btrim(item.provider_url), ''),
        nullif(
          btrim(item.normalization_payload #>> '{playback,provider_url}'),
          ''
        )
      ) as provider_url,

      nullif(
        btrim(item.normalization_payload #>> '{playback,embed_url}'),
        ''
      ) as embed_url,

      coalesce(
        nullif(btrim(item.preview_url), ''),
        nullif(
          btrim(item.normalization_payload #>> '{playback,preview_url}'),
          ''
        )
      ) as preview_url
  ) normalized on true

  left join lateral (
    select
      coalesce(
        case
          when normalized.provider_key = 'apple_music'
            then normalized.provider_object_id
          else null
        end,

        (
          select nullif(btrim(link.provider_track_id), '')
          from public.registry_track_provider_links link
          where link.track_id = item.registry_track_id
            and link.provider_key = 'apple_music'
            and link.match_status = 'matched'
          order by
            link.match_confidence desc,
            link.last_checked_at desc,
            link.created_at desc
          limit 1
        ),

        nullif(btrim(registry_track.metadata ->> 'apple_music_track_id'), ''),
        nullif(btrim(registry_track.metadata ->> 'apple_music_id'), ''),
        nullif(btrim(registry_track.metadata ->> 'appleMusicId'), ''),
        nullif(btrim(registry_track.metadata ->> 'apple_music_catalog_id'), ''),
        nullif(btrim(registry_track.metadata ->> 'appleMusicCatalogId'), ''),
        nullif(btrim(registry_track.metadata #>> '{apple_music,id}'), ''),
        nullif(btrim(registry_track.metadata #>> '{apple_music,catalog_id}'), ''),
        nullif(btrim(registry_track.metadata #>> '{appleMusic,id}'), ''),
        nullif(btrim(registry_track.metadata #>> '{appleMusic,catalogId}'), ''),
        nullif(btrim(registry_track.metadata #>> '{providers,apple_music,id}'), ''),
        nullif(btrim(registry_track.metadata #>> '{providers,apple_music,catalog_id}'), ''),
        nullif(btrim(registry_track.metadata #>> '{provider_ids,apple_music}'), ''),
        nullif(btrim(registry_track.metadata #>> '{source_ids,apple_music}'), '')
      ) as apple_music_catalog_id
  ) apple_music on true

  left join lateral (
    select
      case
        when normalized.provider_key = 'youtube'
             and normalized.provider_object_id is not null
          then 'youtube'
        when normalized.provider_key = 'soundcloud'
             and normalized.provider_url is not null
          then 'soundcloud'
        when normalized.provider_key = 'apple_music'
             and normalized.provider_object_id is not null
          then 'apple_music'
        when normalized.preview_url is not null
          then 'audio'
        else 'unavailable'
      end as engine,

      case
        when normalized.provider_key = 'youtube'
             and normalized.provider_object_id is not null
          then true
        when normalized.provider_key = 'soundcloud'
             and normalized.provider_url is not null
          then true
        when normalized.provider_key = 'apple_music'
             and normalized.provider_object_id is not null
          then true
        when normalized.preview_url is not null
          then true
        else false
      end as playable
  ) playback on true

  where item.playlist_version_id = p_version_id;

  select min(snapshot.first_published_at)
  into v_first_published_at
  from editorial.playlist_publication_snapshots snapshot
  where snapshot.playlist_id = v_version.playlist_id;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'resource_id', attachment.resource_id,
        'resource_kind', attachment.resource_kind,
        'display_order', attachment.display_order,
        'is_primary', attachment.is_primary,
        'credit_id', credit.id,
        'role', credit.credit_role,
        'role_label', credit.role_label_snapshot,
        'display_name', credit.display_name_snapshot,
        'note', credit.credit_note,
        'author_slug', credit.registry_author_slug_snapshot,
        'username', credit.user_username_snapshot
      )
      order by
        attachment.resource_kind,
        attachment.resource_id,
        attachment.display_order
    ),
    '[]'::jsonb
  )
  into v_credits
  from editorial.resource_credits attachment
  join editorial.credits credit
    on credit.id = attachment.credit_id
  join editorial.credit_governance governance
    on governance.credit_id = credit.id
  left join editorial.external_contributors contributor
    on contributor.id = credit.external_contributor_id
  where attachment.target_version_type = 'playlist_version'
    and attachment.target_version_id = v_version.id
    and attachment.public_safe
    and governance.public_safe
    and governance.credit_state = 'active'
    and (
      credit.external_contributor_id is null
      or (
        contributor.contributor_state = 'active'
        and contributor.public_safe
        and contributor.consent_status in (
          'granted',
          'not_required'
        )
      )
    );

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'resource_id', attachment.resource_id,
        'resource_kind', attachment.resource_kind,
        'display_order', attachment.display_order,
        'purpose', attachment.citation_purpose,
        'anchor_type', attachment.target_anchor_type,
        'anchor', attachment.target_anchor_data,
        'citation_id', citation.id,
        'public_label', citation.public_label,
        'locator_type', citation.locator_type,
        'locator', citation.locator_data,
        'source',
          jsonb_build_object(
            'source_id', source.id,
            'source_version_id', source_version.id,
            'type', source_version.source_type,
            'title', source_version.title,
            'creator', source_version.creator_display,
            'publisher', source_version.publisher_display,
            'url',
              case
                when source.exposure_class = 'public'
                  then source_version.source_url
                else null
              end,
            'publication_date', source_version.publication_date,
            'credit_line', source_version.credit_line
          )
      )
      order by
        attachment.resource_kind,
        attachment.resource_id,
        attachment.display_order
    ),
    '[]'::jsonb
  )
  into v_citations
  from editorial.resource_citations attachment
  join editorial.citations citation
    on citation.id = attachment.citation_id
  join editorial.source_versions source_version
    on source_version.id = citation.source_version_id
  join editorial.sources source
    on source.id = citation.source_id
  where attachment.target_version_type = 'playlist_version'
    and attachment.target_version_id = v_version.id
    and attachment.public_safe
    and citation.public_safe
    and citation.citation_state = 'active'
    and source.source_state = 'active'
    and source.withdrawn_at is null
    and source.exposure_class in (
      'public',
      'public_redacted'
    )
    and source.current_approved_version_id =
          citation.source_version_id;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', note.id,
        'resource_id', note.affected_resource_id,
        'resource_kind', note.affected_resource_kind,
        'note', note.note_text,
        'published_at', note.published_at
      )
      order by note.published_at
    ),
    '[]'::jsonb
  )
  into v_corrections
  from editorial.correction_public_notes note
  where (
    note.affected_resource_id = v_version.resource_id
    or note.affected_resource_id in (
      select
        nullif(
          track ->> 'playlist_item_resource_id',
          ''
        )::uuid
      from jsonb_array_elements(v_tracks) track
    )
  )
  and not exists (
    select 1
    from editorial.correction_public_notes newer
    where newer.supersedes_note_id = note.id
  );

  v_payload := jsonb_build_object(
    'playlist_id', v_version.playlist_id,
    'resource_id', v_version.resource_id,
    'version_id', v_version.id,
    'version_number', v_version.version_number,
    'slug', v_version.slug,
    'title', v_version.title,
    'description', v_version.description,
    'curator_label', v_version.curator_label,
    'cover',
      case
        when v_version.cover_asset_id is null
          then null
        else jsonb_build_object(
          'asset_id', v_version.cover_asset_id,
          'asset_revision_id', v_version.cover_asset_revision_id,
          'url', v_cover.safe_delivery_url,
          'mime_type', v_cover.resolved_mime_type,
          'width', v_cover.width,
          'height', v_cover.height,
          'alt_text',
            coalesce(
              v_version.cover_alt_text_snapshot,
              v_cover.approved_alt_text
            ),
          'caption',
            coalesce(
              v_version.cover_caption_snapshot,
              v_cover.approved_caption
            ),
          'credit',
            coalesce(
              v_version.cover_credit_snapshot,
              v_cover.approved_credit
            )
        )
      end,
    'item_count', v_version.item_count,
    'tracks', v_tracks,
    'provenance',
      jsonb_build_object(
        'version_number', v_version.version_number,
        'content_fingerprint', v_version.content_fingerprint,
        'source_authority_revision', v_version.source_authority_revision,
        'published_at', null,
        'first_published_at', v_first_published_at,
        'published_by', null,
        'command_receipt_id', null
      ),
    'credits', v_credits,
    'citations', v_citations,
    'corrections', v_corrections
  );

  return v_payload;
end;
$$;


ALTER FUNCTION "editorial"."playlist_version_public_presentation_json"("p_version_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."playlist_version_snapshot_json"("p_version_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'editorial'
    AS $$
  select case
    when version.id is null then null
    else jsonb_build_object(
      'id', version.id,
      'resource_id', version.resource_id,
      'playlist_id', version.playlist_id,
      'version_number', version.version_number,
      'version_kind', version.version_kind,
      'source_authority_revision', version.source_authority_revision,
      'title', version.title,
      'slug', version.slug,
      'description', version.description,
      'curator_label', version.curator_label,
      'status', version.status,
      'metadata', version.metadata,
      'item_count', version.item_count,
      'content_fingerprint', version.content_fingerprint,
      'cover', case
        when version.cover_asset_id is null then null
        else jsonb_build_object(
          'asset_id', version.cover_asset_id,
          'asset_revision_id', version.cover_asset_revision_id,
          'placement_data', version.cover_placement_data,
          'display_order', version.cover_display_order,
          'alt_text_snapshot', version.cover_alt_text_snapshot,
          'caption_snapshot', version.cover_caption_snapshot,
          'credit_snapshot', version.cover_credit_snapshot
        )
      end,
      'created_by', version.created_by,
      'created_at', version.created_at,
      'trust_revisions', coalesce(
        (
          select jsonb_build_object(
            'citation_revision', revision.citation_revision,
            'credit_revision', revision.credit_revision,
            'updated_by', revision.updated_by,
            'updated_at', revision.updated_at
          )
          from editorial.playlist_version_trust_revisions revision
          where revision.playlist_version_id = version.id
        ),
        jsonb_build_object(
          'citation_revision', 1,
          'credit_revision', 1
        )
      ),
      'citations', coalesce(
        (
          select jsonb_agg(
            jsonb_build_object(
              'id', attachment.id,
              'resource_id', attachment.resource_id,
              'resource_kind', attachment.resource_kind,
              'citation_id', attachment.citation_id,
              'citation_purpose', attachment.citation_purpose,
              'target_anchor_type', attachment.target_anchor_type,
              'target_anchor_data', attachment.target_anchor_data,
              'display_order', attachment.display_order,
              'public_safe', attachment.public_safe,
              'created_by', attachment.created_by,
              'created_at', attachment.created_at
            )
            order by
              attachment.resource_kind,
              attachment.resource_id,
              attachment.display_order
          )
          from editorial.resource_citations attachment
          where attachment.target_version_type = 'playlist_version'
            and attachment.target_version_id = version.id
        ),
        '[]'::jsonb
      ),
      'credits', coalesce(
        (
          select jsonb_agg(
            jsonb_build_object(
              'id', attachment.id,
              'resource_id', attachment.resource_id,
              'resource_kind', attachment.resource_kind,
              'credit_id', attachment.credit_id,
              'display_order', attachment.display_order,
              'is_primary', attachment.is_primary,
              'public_safe', attachment.public_safe,
              'created_by', attachment.created_by,
              'created_at', attachment.created_at
            )
            order by
              attachment.resource_kind,
              attachment.resource_id,
              attachment.display_order
          )
          from editorial.resource_credits attachment
          where attachment.target_version_type = 'playlist_version'
            and attachment.target_version_id = version.id
        ),
        '[]'::jsonb
      ),
      'items', coalesce(
        (
          select jsonb_agg(
            jsonb_build_object(
              'playlist_item_resource_id', item.playlist_item_resource_id,
              'playlist_item_id', item.playlist_item_id,
              'position', item.position,
              'registry_track_id', item.registry_track_id,
              'registry_release_id', item.registry_release_id,
              'provider_key', item.provider_key,
              'provider_track_id', item.provider_track_id,
              'provider_url', item.provider_url,
              'title', item.title,
              'artist_names', to_jsonb(item.artist_names),
              'release_title', item.release_title,
              'artwork_url', item.artwork_url,
              'preview_url', item.preview_url,
              'duration_ms', item.duration_ms,
              'isrc', item.isrc,
              'match_status', item.match_status,
              'match_confidence', item.match_confidence,
              'normalization_payload', item.normalization_payload,
              'notes', item.notes
            )
            order by item.position
          )
          from editorial.playlist_version_items item
          where item.playlist_version_id = version.id
        ),
        '[]'::jsonb
      )
    )
  end
  from (
    select candidate.*
    from editorial.playlist_versions candidate
    where candidate.id = p_version_id
  ) version;
$$;


ALTER FUNCTION "editorial"."playlist_version_snapshot_json"("p_version_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."playlist_working_trust_target"("p_playlist_version_id" "uuid", "p_target_resource_id" "uuid") RETURNS TABLE("root_resource_id" "uuid", "target_resource_kind" "text", "playlist_id" "uuid")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_version editorial.playlist_versions%rowtype;
  v_current_fingerprint text;
begin
  select version.*
  into v_version
  from editorial.playlist_versions version
  where version.id = p_playlist_version_id
    and version.version_kind = 'working';

  if not found then
    raise exception
      'Playlist Trust can be edited only on a working Playlist version';
  end if;

  if not exists (
    select 1
    from editorial.playlist_resources binding
    where binding.resource_id = v_version.resource_id
      and binding.playlist_id = v_version.playlist_id
      and binding.current_working_version_id =
            p_playlist_version_id
  ) then
    raise exception
      'Playlist Trust target must be the current working version';
  end if;

  v_current_fingerprint :=
    editorial.playlist_current_content_fingerprint(
      v_version.playlist_id
    );

  if v_version.content_fingerprint <>
       v_current_fingerprint
  then
    raise exception
      'Create a fresh working Playlist snapshot before changing version-bound Trust';
  end if;

  if p_target_resource_id = v_version.resource_id
  then
    root_resource_id := v_version.resource_id;
    target_resource_kind := 'playlist';
    playlist_id := v_version.playlist_id;
    return next;
    return;
  end if;

  if exists (
    select 1
    from editorial.playlist_version_items item
    where item.playlist_version_id =
            p_playlist_version_id
      and item.playlist_item_resource_id =
            p_target_resource_id
  ) then
    root_resource_id := v_version.resource_id;
    target_resource_kind := 'playlist_item';
    playlist_id := v_version.playlist_id;
    return next;
    return;
  end if;

  raise exception
    'Trust target Resource is not part of the working Playlist version';
end;
$$;


ALTER FUNCTION "editorial"."playlist_working_trust_target"("p_playlist_version_id" "uuid", "p_target_resource_id" "uuid") OWNER TO "postgres";


