CREATE OR REPLACE FUNCTION "editorial"."provision_person_for_user_profile_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_username text;
  v_email text;
  v_display_name text;
begin
  select
    profile.username_normalized,
    profile.email,
    profile.display_name
  into
    v_username,
    v_email,
    v_display_name
  from public.user_profiles profile
  where profile.user_id = new.user_id;

  if not found then
    return null;
  end if;

  if v_username is null then
    v_username :=
      public.community_generate_username(
        new.user_id,
        v_email,
        v_display_name
      );

    update public.user_profiles profile
    set
      username = v_username,
      username_normalized = v_username,
      username_updated_at =
        coalesce(
          profile.username_updated_at,
          now()
        ),
      updated_at = now()
    where profile.user_id = new.user_id;
  end if;

  perform editorial.ensure_person_for_user(
    new.user_id
  );

  perform editorial.sync_account_person_handle(
    new.user_id
  );

  return null;
end;
$$;


ALTER FUNCTION "editorial"."provision_person_for_user_profile_insert"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."publish_article_snapshot"("p_version_id" "uuid", "p_published_at" timestamp with time zone, "p_material_update" boolean DEFAULT true) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_version editorial.article_versions%rowtype;
  v_article public.wk_articles%rowtype;
  v_previous public.wk_article_publication_snapshots%rowtype;
  v_snapshot_id uuid;
  v_first_published_at timestamptz;
begin
  select version.*
  into v_version
  from editorial.article_versions version
  where version.id = p_version_id;

  if not found then
    raise exception 'Article version not found';
  end if;

  select article.*
  into v_article
  from public.wk_articles article
  where article.id = v_version.article_id;

  if not found then
    raise exception 'Article not found';
  end if;

  select snapshot.*
  into v_previous
  from public.wk_article_publication_snapshots snapshot
  where snapshot.article_id = v_version.article_id
    and snapshot.is_active = true
  order by snapshot.created_at desc
  limit 1;

  v_first_published_at :=
    coalesce(
      v_previous.first_published_at,
      p_published_at,
      now()
    );

  update public.wk_article_publication_snapshots snapshot
  set
    is_active = false,
    updated_at = now()
  where snapshot.article_id = v_version.article_id
    and snapshot.is_active = true;

  insert into public.wk_article_publication_snapshots (
    article_id,
    resource_id,
    version_id,
    slug,
    title,
    excerpt,
    content_html,
    author,
    published_at,
    modified_at,
    categories,
    tags,
    seo,
    hero_image_id,
    hero_image_url,
    raw_meta,
    wp_status,
    first_published_at,
    last_materially_updated_at,
    published_by,
    is_active
  )
  values (
    v_version.article_id,
    v_version.resource_id,
    v_version.id,
    v_version.slug,
    v_version.title,
    v_version.excerpt,
    v_version.content_html,
    v_version.author_display,
    coalesce(p_published_at, now()),
    now(),
    v_version.category_snapshot,
    v_version.tag_snapshot,
    v_version.seo,
    v_version.hero_image_id,
    v_version.hero_image_url,
    coalesce(v_article.raw_meta, '{}'::jsonb),
    'publish',
    v_first_published_at,
    case
      when p_material_update
        then now()
      else coalesce(v_previous.last_materially_updated_at, now())
    end,
    auth.uid(),
    true
  )
  returning id
  into v_snapshot_id;

  return v_snapshot_id;
end;
$$;


ALTER FUNCTION "editorial"."publish_article_snapshot"("p_version_id" "uuid", "p_published_at" timestamp with time zone, "p_material_update" boolean) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "editorial"."publishing_items" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "resource_id" "uuid",
    "title" "text" NOT NULL,
    "content_kind" "text" NOT NULL,
    "brief" "text",
    "production_stage" "text" DEFAULT 'idea'::"text" NOT NULL,
    "planning_state" "text" DEFAULT 'active'::"text" NOT NULL,
    "priority" "text" DEFAULT 'normal'::"text" NOT NULL,
    "owner_id" "uuid",
    "production_deadline" timestamp with time zone,
    "planned_publish_at" timestamp with time zone,
    "record_version" bigint DEFAULT 1 NOT NULL,
    "created_by" "uuid" DEFAULT "auth"."uid"(),
    "updated_by" "uuid" DEFAULT "auth"."uid"(),
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "publishing_items_planning_state_check" CHECK (("planning_state" = ANY (ARRAY['active'::"text", 'paused'::"text", 'dropped'::"text", 'archived'::"text"]))),
    CONSTRAINT "publishing_items_priority_check" CHECK (("priority" = ANY (ARRAY['low'::"text", 'normal'::"text", 'high'::"text", 'urgent'::"text"]))),
    CONSTRAINT "publishing_items_production_stage_check" CHECK (("production_stage" = ANY (ARRAY['idea'::"text", 'assigned'::"text", 'producing'::"text", 'production_review'::"text", 'revisions'::"text", 'ready'::"text"]))),
    CONSTRAINT "publishing_items_record_version_check" CHECK (("record_version" > 0)),
    CONSTRAINT "publishing_items_title_check" CHECK ((NULLIF("btrim"("title"), ''::"text") IS NOT NULL))
);


