CREATE OR REPLACE FUNCTION "editorial"."record_playlist_publication_lifecycle_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'editorial'
    AS $$
declare
  v_schedule_id uuid;
  v_prior_status text;
begin
  select scheduled.id
  into v_schedule_id
  from editorial.playlist_scheduled_publications scheduled
  where scheduled.command_receipt_id =
          new.command_receipt_id
  order by scheduled.created_at desc
  limit 1;

  v_prior_status :=
    case
      when v_schedule_id is null
        then 'approved'
      else 'scheduled'
    end;

  perform editorial.append_playlist_lifecycle_event(
    new.resource_id,
    new.playlist_id,
    new.version_id,
    'published',
    v_prior_status,
    'published',
    null,
    new.published_by,
    new.command_receipt_id,
    jsonb_strip_nulls(
      jsonb_build_object(
        'publication_snapshot_id',
          new.id,
        'scheduled_publication_id',
          v_schedule_id,
        'published_at',
          new.published_at
      )
    )
  );

  return new;
end;
$$;


