CREATE OR REPLACE FUNCTION "editorial"."refresh_person_visibility"("p_person_resource_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_person editorial.people%rowtype;
  v_public_eligible boolean := false;
  v_owner_id uuid;
  v_visibility text;
  v_lifecycle text;
begin
  select person.*
  into v_person
  from editorial.people person
  where person.resource_id =
        p_person_resource_id;

  if not found then
    return;
  end if;

  select link.user_id
  into v_owner_id
  from editorial.person_identity_links link
  where link.person_resource_id =
        p_person_resource_id
    and link.link_state = 'active'
    and link.user_id is not null
  limit 1;

  if v_person.person_state = 'active' then
    select exists (
      select 1
      from editorial.person_identity_links link
      join public.user_profiles profile
        on profile.user_id = link.user_id
      where link.person_resource_id =
            p_person_resource_id
        and link.link_state = 'active'
        and link.user_id is not null
        and profile.status = 'active'
        and profile.is_public

      union all

      select 1
      from editorial.person_identity_links link
      join public.registry_authors author
        on author.id =
           link.registry_author_id
      where link.person_resource_id =
            p_person_resource_id
        and link.link_state = 'active'
        and link.registry_author_id is not null

      union all

      select 1
      from editorial.person_identity_links link
      join editorial.external_contributors contributor
        on contributor.id =
           link.external_contributor_id
      where link.person_resource_id =
            p_person_resource_id
        and link.link_state = 'active'
        and link.external_contributor_id is not null
        and contributor.contributor_state = 'active'
        and contributor.public_safe
        and contributor.consent_status in (
          'granted',
          'not_required'
        )
    )
    into v_public_eligible;
  end if;

  if v_person.person_state = 'archived' then
    v_visibility := 'internal';
    v_lifecycle := 'archived';
  elsif v_person.person_state = 'merged' then
    v_visibility := 'internal';
    v_lifecycle := 'active';
  else
    v_visibility :=
      case
        when v_public_eligible then 'public'
        else 'internal'
      end;
    v_lifecycle := 'active';
  end if;

  update editorial.resources resource
  set
    owner_id = v_owner_id,
    visibility = v_visibility,
    lifecycle_state = v_lifecycle,
    updated_at = now()
  where resource.id =
        p_person_resource_id
    and resource.resource_kind = 'person'
    and (
      resource.owner_id
        is distinct from v_owner_id
      or resource.visibility
        is distinct from v_visibility
      or resource.lifecycle_state
        is distinct from v_lifecycle
    );
end;
$$;


ALTER FUNCTION "editorial"."refresh_person_visibility"("p_person_resource_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."refresh_registry_artist_username_reservations"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial', 'pg_temp'
    AS $$
declare
  v_mapping_count integer;
  v_handle_count integer;
  v_ambiguous_count integer;
  v_current_user_collision_count integer;
begin
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'community-artist-username-reservation',
      0
    )
  );

  drop table if exists
    pg_temp.wk_artist_username_candidate_refresh;

  create temporary table
    wk_artist_username_candidate_refresh (
      username text not null,
      artist_id uuid not null,
      source text not null,
      primary key (
        username,
        artist_id
      )
    )
  on commit drop;

  insert into
    wk_artist_username_candidate_refresh (
      username,
      artist_id,
      source
    )
  with raw_candidates as (
    select
      artist.id as artist_id,
      candidate.source,
      candidate.priority,
      candidate.username
    from public.registry_artists artist
    cross join lateral (
      values
        (
          'slug_exact'::text,
          1,
          case
            when public.community_username_is_valid(
              public.community_normalize_username(
                artist.slug
              )
            )
            then public.community_normalize_username(
              artist.slug
            )
            else null
          end
        ),
        (
          'slug_seed'::text,
          2,
          case
            when public.community_username_is_valid(
              public.community_username_seed(
                artist.slug
              )
            )
            then public.community_username_seed(
              artist.slug
            )
            else null
          end
        ),
        (
          'name_seed'::text,
          3,
          case
            when public.community_username_is_valid(
              public.community_username_seed(
                artist.display_name
              )
            )
            then public.community_username_seed(
              artist.display_name
            )
            else null
          end
        )
    ) candidate(
      source,
      priority,
      username
    )
    where artist.status = 'active'
      and candidate.username is not null
  ),

  ranked as (
    select
      raw.artist_id,
      raw.username,
      raw.source,
      row_number() over (
        partition by
          raw.artist_id,
          raw.username
        order by
          raw.priority,
          raw.source
      ) as row_number
    from raw_candidates raw
  )

  select
    ranked.username,
    ranked.artist_id,
    ranked.source
  from ranked
  where ranked.row_number = 1
    and not exists (
      select 1
      from public.user_profiles profile
      where profile.username_normalized =
            ranked.username
    );

  delete from
    public.community_artist_username_reservations reservation
  where not exists (
    select 1
    from pg_temp.wk_artist_username_candidate_refresh candidate
    where candidate.username =
          reservation.username
      and candidate.artist_id =
          reservation.artist_id
  );

  insert into
    public.community_artist_username_reservations (
      username,
      artist_id,
      source
    )
  select
    candidate.username,
    candidate.artist_id,
    candidate.source
  from pg_temp.wk_artist_username_candidate_refresh candidate
  on conflict (
    username,
    artist_id
  ) do update
    set
      source = excluded.source,
      updated_at = case
        when public.community_artist_username_reservations.source
               is distinct from excluded.source
        then now()
        else public.community_artist_username_reservations.updated_at
      end;

  select
    count(*)::integer,
    count(distinct reservation.username)::integer
  into
    v_mapping_count,
    v_handle_count
  from public.community_artist_username_reservations reservation;

  select count(*)::integer
  into v_ambiguous_count
  from (
    select reservation.username
    from public.community_artist_username_reservations reservation
    group by reservation.username
    having count(distinct reservation.artist_id) > 1
  ) ambiguous;

  select count(*)::integer
  into v_current_user_collision_count
  from public.community_artist_username_reservations reservation
  join public.user_profiles profile
    on profile.username_normalized =
       reservation.username;

  return jsonb_build_object(
    'mapping_count',
      v_mapping_count,
    'protected_handle_count',
      v_handle_count,
    'ambiguous_handle_count',
      v_ambiguous_count,
    'current_user_collision_count',
      v_current_user_collision_count
  );
end;
$$;


ALTER FUNCTION "editorial"."refresh_registry_artist_username_reservations"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."require_exact_working_snapshot_for_curated_submission"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_curator_credit_id uuid;
begin
  if new.version_kind <> 'submitted' then
    return new;
  end if;

  select playlist.curator_credit_id
  into v_curator_credit_id
  from public.wk_playlists playlist
  where playlist.id = new.playlist_id;

  if v_curator_credit_id is null then
    return new;
  end if;

  if not exists (
    select 1
    from editorial.playlist_resources binding
    join editorial.playlist_versions working
      on working.id = binding.current_working_version_id
    join editorial.resource_credits attachment
      on attachment.target_version_type = 'playlist_version'
     and attachment.target_version_id = working.id
     and attachment.resource_id = working.resource_id
     and attachment.resource_kind = 'playlist'
     and attachment.credit_id = v_curator_credit_id
     and attachment.display_order = 0
     and attachment.is_primary
     and attachment.public_safe
    where binding.playlist_id = new.playlist_id
      and binding.resource_id = new.resource_id
      and working.version_kind = 'working'
      and working.content_fingerprint = new.content_fingerprint
      and working.item_count = new.item_count
      and working.source_authority_revision = new.source_authority_revision
  ) then
    raise exception
      'Save the Playlist before submitting for Review so Curator identity can be frozen';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "editorial"."require_exact_working_snapshot_for_curated_submission"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."resequence_playlist_with_registry_intake"("p_playlist_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_offset integer;
  v_next integer := 0;
  v_entry record;
begin
  select greatest(
    coalesce(
      (
        select max(item.position)
        from public.wk_playlist_items item
        where item.playlist_id = p_playlist_id
          and item.lifecycle_state = 'active'
      ),
      0
    ),
    coalesce(
      (
        select max(suggestion.reserved_position)
        from public.registry_provider_track_suggestions suggestion
        where suggestion.source_playlist_id = p_playlist_id
          and suggestion.status = 'needs_review'
          and suggestion.source_playlist_item_id is null
          and suggestion.canonical_track_id is null
      ),
      0
    )
  )
  + (
      select count(*)::integer
      from public.wk_playlist_items item
      where item.playlist_id = p_playlist_id
        and item.lifecycle_state = 'active'
    )
  + (
      select count(*)::integer
      from public.registry_provider_track_suggestions suggestion
      where suggestion.source_playlist_id = p_playlist_id
        and suggestion.status = 'needs_review'
        and suggestion.source_playlist_item_id is null
        and suggestion.canonical_track_id is null
    )
  + 100
  into v_offset;

  update public.wk_playlist_items item
  set position = item.position + v_offset
  where item.playlist_id = p_playlist_id
    and item.lifecycle_state = 'active';

  update public.registry_provider_track_suggestions suggestion
  set reserved_position = suggestion.reserved_position + v_offset
  where suggestion.source_playlist_id = p_playlist_id
    and suggestion.status = 'needs_review'
    and suggestion.source_playlist_item_id is null
    and suggestion.canonical_track_id is null;

  for v_entry in
    select combined.entry_kind, combined.entry_id
    from (
      select
        'item'::text as entry_kind,
        item.id as entry_id,
        item.position as sort_position,
        item.created_at as created_at
      from public.wk_playlist_items item
      where item.playlist_id = p_playlist_id
        and item.lifecycle_state = 'active'

      union all

      select
        'registry_intake'::text,
        suggestion.id,
        suggestion.reserved_position,
        suggestion.created_at
      from public.registry_provider_track_suggestions suggestion
      where suggestion.source_playlist_id = p_playlist_id
        and suggestion.status = 'needs_review'
        and suggestion.source_playlist_item_id is null
        and suggestion.canonical_track_id is null
    ) combined
    order by
      combined.sort_position,
      combined.created_at,
      combined.entry_id
  loop
    v_next := v_next + 1;

    if v_entry.entry_kind = 'item' then
      update public.wk_playlist_items item
      set position = v_next
      where item.id = v_entry.entry_id;
    else
      update public.registry_provider_track_suggestions suggestion
      set reserved_position = v_next
      where suggestion.id = v_entry.entry_id;
    end if;
  end loop;
end;
$$;


ALTER FUNCTION "editorial"."resequence_playlist_with_registry_intake"("p_playlist_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."resolve_credit_person"("p_credit_id" "uuid") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'editorial'
    AS $$
  select person.resource_id
  from editorial.credits credit
  join editorial.person_identity_links link
    on link.link_state = 'active'
   and (
     (
       credit.user_id is not null
       and link.user_id = credit.user_id
     )
     or
     (
       credit.registry_author_id is not null
       and link.registry_author_id =
           credit.registry_author_id
     )
     or
     (
       credit.external_contributor_id is not null
       and link.external_contributor_id =
           credit.external_contributor_id
     )
   )
  join editorial.people person
    on person.resource_id =
       link.person_resource_id
   and person.person_state = 'active'
  where credit.id = p_credit_id
  limit 1;
$$;


ALTER FUNCTION "editorial"."resolve_credit_person"("p_credit_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."resolve_person_follow_target"("p_person_resource_id" "uuid") RETURNS TABLE("person_resource_id" "uuid", "canonical_path" "text", "followable" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $_$
declare
  v_person_id uuid :=
    p_person_resource_id;
  v_person editorial.people%rowtype;
  v_resource editorial.resources%rowtype;
  v_path text;
  v_seen uuid[] :=
    array[]::uuid[];
  v_depth integer := 0;
begin
  if v_person_id is null then
    raise exception
      using
        errcode = '22023',
        message =
          'Person target is required.';
  end if;

  loop
    v_depth :=
      v_depth + 1;

    if v_depth > 8 then
      raise exception
        using
          errcode = '22023',
          message =
            'Person merge chain exceeds the supported Follow safety depth.';
    end if;

    if v_person_id = any(v_seen) then
      raise exception
        using
          errcode = '22023',
          message =
            'Person merge cycle is not a valid Follow target.';
    end if;

    v_seen :=
      array_append(
        v_seen,
        v_person_id
      );

    select person.*
    into v_person
    from editorial.people person
    where person.resource_id =
          v_person_id;

    if not found then
      raise exception
        using
          errcode = 'P0002',
          message =
            'Person Follow target does not exist.';
    end if;

    exit when
      v_person.person_state <>
      'merged';

    if v_person.merged_into_person_resource_id
         is null
    then
      raise exception
        using
          errcode = '22023',
          message =
            'Merged Person Follow target has no survivor.';
    end if;

    v_person_id :=
      v_person.merged_into_person_resource_id;
  end loop;

  select resource.*
  into v_resource
  from editorial.resources resource
  where resource.id =
        v_person_id
    and resource.resource_kind =
        'person';

  if not found then
    raise exception
      using
        errcode = 'P0002',
        message =
          'Person Resource binding does not exist.';
  end if;

  select alias.path
  into v_path
  from editorial.resource_aliases alias
  where alias.resource_id =
        v_person_id
    and alias.is_canonical
    and alias.retired_at is null
  order by
    alias.created_at,
    alias.path
  limit 1;

  person_resource_id :=
    v_person_id;
  canonical_path :=
    v_path;
  followable :=
    (
      v_person.person_state = 'active'
      and v_resource.visibility = 'public'
      and v_resource.lifecycle_state = 'active'
      and v_path ~ '^/people/[^/]+$'
    );

  return next;
end;
$_$;


ALTER FUNCTION "editorial"."resolve_person_follow_target"("p_person_resource_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."resolve_person_presentation"("p_person_resource_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
  with person as (
    select
      row.resource_id,
      row.preferred_identity_link_id
    from editorial.people row
    where row.resource_id = p_person_resource_id
      and row.person_state = 'active'
  ),
  candidates as (
    select
      link.id as identity_link_id,
      case
        when link.id = person.preferred_identity_link_id
          then 0
        else 10
      end as presentation_order,
      jsonb_strip_nulls(
        jsonb_build_object(
          'identity_kind', 'registry_author',
          'display_name', author.name,
          'bio', author.bio,
          'avatar_url', author.avatar_url,
          'cover_url', author.cover_url,
          'location', author.location,
          'registry_author_slug', author.slug
        )
      ) as presentation
    from person
    join editorial.person_identity_links link
      on link.person_resource_id = person.resource_id
     and link.link_state = 'active'
     and link.registry_author_id is not null
    join public.registry_authors author
      on author.id = link.registry_author_id

    union all

    select
      link.id,
      case
        when link.id = person.preferred_identity_link_id
          then 0
        else 20
      end,
      jsonb_strip_nulls(
        jsonb_build_object(
          'identity_kind', 'user',
          'display_name',
            coalesce(
              nullif(
                btrim(profile.display_name),
                ''
              ),
              profile.username_normalized
            ),
          'bio', profile.bio,
          'avatar_url', profile.avatar_url,
          'cover_url', profile.cover_url,
          'location',
            nullif(
              concat_ws(
                ', ',
                nullif(
                  btrim(profile.city),
                  ''
                ),
                nullif(
                  btrim(profile.country),
                  ''
                )
              ),
              ''
            ),
          'username', profile.username_normalized
        )
      )
    from person
    join editorial.person_identity_links link
      on link.person_resource_id = person.resource_id
     and link.link_state = 'active'
     and link.user_id is not null
    join public.user_profiles profile
      on profile.user_id = link.user_id
     and profile.status = 'active'
     and profile.is_public
     and profile.username_normalized is not null

    union all

    select
      link.id,
      case
        when link.id = person.preferred_identity_link_id
          then 0
        else 30
      end,
      jsonb_strip_nulls(
        jsonb_build_object(
          'identity_kind', 'external_contributor',
          'display_name', contributor.display_name,
          'location', contributor.location_text
        )
      )
    from person
    join editorial.person_identity_links link
      on link.person_resource_id = person.resource_id
     and link.link_state = 'active'
     and link.external_contributor_id is not null
    join editorial.external_contributors contributor
      on contributor.id =
         link.external_contributor_id
     and contributor.contributor_state = 'active'
     and contributor.public_safe
     and contributor.consent_status in (
       'granted',
       'not_required'
     )
  )
  select candidate.presentation
  from candidates candidate
  order by
    candidate.presentation_order,
    candidate.identity_link_id
  limit 1;
$$;


ALTER FUNCTION "editorial"."resolve_person_presentation"("p_person_resource_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."resolve_playlist_curator_credit"("p_registry_author_id" "uuid", "p_user_id" "uuid", "p_actor_id" "uuid") RETURNS TABLE("credit_id" "uuid", "display_name" "text", "registry_author_slug" "text", "user_username" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_display_name text;
  v_registry_author_slug text;
  v_user_username text;
  v_credit_id uuid;
begin
  if num_nonnulls(
       p_registry_author_id,
       p_user_id
     ) <> 1
  then
    raise exception
      'Choose exactly one Curator identity';
  end if;

  if p_registry_author_id is not null then
    select
      nullif(btrim(author_record.name), ''),
      nullif(btrim(author_record.slug), '')
    into
      v_display_name,
      v_registry_author_slug
    from public.registry_authors author_record
    where author_record.id = p_registry_author_id;

    if not found
       or v_display_name is null
       or v_registry_author_slug is null
    then
      raise exception
        'Registry Author is missing or incomplete';
    end if;

    select credit.id
    into v_credit_id
    from editorial.credits credit
    join editorial.credit_governance governance
      on governance.credit_id = credit.id
    where credit.credit_role = 'curator'
      and credit.registry_author_id =
            p_registry_author_id
      and credit.registry_author_slug_snapshot =
            v_registry_author_slug
      and credit.display_name_snapshot =
            v_display_name
      and governance.credit_state = 'active'
      and governance.public_safe
    order by credit.created_at, credit.id
    limit 1;

  else
    select
      nullif(btrim(profile.display_name), ''),
      nullif(btrim(profile.username), '')
    into
      v_display_name,
      v_user_username
    from public.user_profiles profile
    where profile.user_id = p_user_id
      and profile.status = 'active'
      and profile.is_public;

    if not found
       or v_display_name is null
    then
      raise exception
        'Active WAKILISHA user profile with a display name was not found';
    end if;

    select credit.id
    into v_credit_id
    from editorial.credits credit
    join editorial.credit_governance governance
      on governance.credit_id = credit.id
    where credit.credit_role = 'curator'
      and credit.user_id = p_user_id
      and credit.user_username_snapshot
            is not distinct from
            v_user_username
      and credit.display_name_snapshot =
            v_display_name
      and governance.credit_state = 'active'
      and governance.public_safe
    order by credit.created_at, credit.id
    limit 1;
  end if;

  if v_credit_id is null then
    insert into editorial.credits (
      credit_role,
      user_id,
      registry_author_id,
      external_contributor_id,
      display_name_snapshot,
      role_label_snapshot,
      registry_author_slug_snapshot,
      user_username_snapshot,
      credit_note,
      created_by
    )
    values (
      'curator',
      p_user_id,
      p_registry_author_id,
      null,
      v_display_name,
      'Curator',
      v_registry_author_slug,
      v_user_username,
      null,
      p_actor_id
    )
    returning id
    into v_credit_id;

    insert into editorial.credit_governance (
      credit_id,
      public_safe,
      credit_state,
      governance_revision,
      reason,
      updated_by,
      updated_at
    )
    values (
      v_credit_id,
      true,
      'active',
      1,
      null,
      p_actor_id,
      now()
    );
  end if;

  credit_id := v_credit_id;
  display_name := v_display_name;
  registry_author_slug := v_registry_author_slug;
  user_username := v_user_username;
  return next;
end;
$$;


ALTER FUNCTION "editorial"."resolve_playlist_curator_credit"("p_registry_author_id" "uuid", "p_user_id" "uuid", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."seed_registry_track_intake_provider_observations"("p_suggestion_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_suggestion public.registry_provider_track_suggestions%rowtype;
  v_metadata jsonb;
begin
  select suggestion.*
  into v_suggestion
  from public.registry_provider_track_suggestions suggestion
  where suggestion.id = p_suggestion_id;

  if not found then
    return;
  end if;

  v_metadata :=
    coalesce(
      v_suggestion.validation_snapshot -> 'provider_metadata',
      '{}'::jsonb
    );

  insert into public.provider_field_observations (
    provider_item_id,
    entity_type,
    field_name,
    field_value,
    provider,
    confidence_score,
    source_path,
    raw_payload,
    created_at
  )
  select
    v_suggestion.id::text,
    'track',
    observed.field_name,
    observed.field_value,
    v_suggestion.provider_key,
    observed.confidence_score,
    observed.source_path,
    v_suggestion.validation_snapshot,
    now()
  from (
    values
      (
        'title'::text,
        nullif(btrim(v_suggestion.provider_title), ''),
        0.85::numeric,
        'playlist_validation.provider_title'::text
      ),
      (
        'release_title',
        nullif(btrim(v_suggestion.provider_release_title), ''),
        0.80::numeric,
        'playlist_validation.provider_release_title'
      ),
      (
        'track_artwork_url',
        nullif(
          btrim(v_suggestion.validation_snapshot ->> 'artwork_url'),
          ''
        ),
        0.85::numeric,
        'playlist_validation.artwork_url'
      ),
      (
        'preview_url',
        nullif(
          btrim(v_suggestion.validation_snapshot ->> 'preview_url'),
          ''
        ),
        0.85::numeric,
        'playlist_validation.preview_url'
      ),
      (
        'duration_ms',
        nullif(btrim(v_metadata ->> 'track_time_millis'), ''),
        0.90::numeric,
        'playlist_validation.provider_metadata.track_time_millis'
      ),
      (
        'release_date',
        nullif(btrim(v_metadata ->> 'release_date'), ''),
        0.80::numeric,
        'playlist_validation.provider_metadata.release_date'
      ),
      (
        'genre',
        nullif(btrim(v_metadata ->> 'primary_genre_name'), ''),
        0.65::numeric,
        'playlist_validation.provider_metadata.primary_genre_name'
      ),
      (
        'provider_url',
        nullif(btrim(v_suggestion.provider_url), ''),
        1.00::numeric,
        'playlist_validation.provider_url'
      ),
      (
        'video_published_at',
        case
          when v_suggestion.provider_key = 'youtube'
          then nullif(btrim(v_metadata ->> 'published_at'), '')
          else null
        end,
        0.65::numeric,
        'playlist_validation.provider_metadata.published_at'
      )
  ) observed(
    field_name,
    field_value,
    confidence_score,
    source_path
  )
  where observed.field_value is not null
    and not exists (
      select 1
      from public.provider_field_observations existing
      where existing.provider_item_id = v_suggestion.id::text
        and existing.entity_type = 'track'
        and existing.provider = v_suggestion.provider_key
        and existing.field_name = observed.field_name
        and existing.field_value = observed.field_value
        and existing.source_path = observed.source_path
    );

  if nullif(btrim(v_suggestion.provider_object_id), '') is not null
     and not exists (
       select 1
       from public.provider_entity_links link
       where link.registry_entity_type = 'track'
         and link.registry_entity_id = v_suggestion.id::text
         and link.provider = v_suggestion.provider_key
         and link.provider_entity_id =
           v_suggestion.provider_object_id
     )
  then
    insert into public.provider_entity_links (
      registry_entity_type,
      registry_entity_id,
      provider,
      provider_entity_id,
      provider_url,
      match_status,
      confidence_score,
      created_at,
      updated_at
    )
    values (
      'track',
      v_suggestion.id::text,
      v_suggestion.provider_key,
      v_suggestion.provider_object_id,
      v_suggestion.provider_url,
      'confirmed',
      1.0000,
      now(),
      now()
    );
  end if;
end;
$$;


ALTER FUNCTION "editorial"."seed_registry_track_intake_provider_observations"("p_suggestion_id" "uuid") OWNER TO "postgres";


