CREATE OR REPLACE FUNCTION "editorial"."sync_account_person_handle"("p_user_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_username text;
  v_person_resource_id uuid;
  v_resolved_person_resource_id uuid;
  v_desired_path text;
  v_desired_alias_id uuid;
  v_desired_alias_resource_id uuid;
  v_current_alias_id uuid;
  v_current_path text;
  v_actor_id uuid := auth.uid();
begin
  if p_user_id is null then
    raise exception
      'Account user id is required for Person handle synchronization.';
  end if;

  select profile.username_normalized
  into v_username
  from public.user_profiles profile
  where profile.user_id = p_user_id;

  if not found then
    raise exception
      'Account profile % does not exist.',
      p_user_id;
  end if;

  if v_username is null
     or not public.community_username_is_valid(v_username)
  then
    raise exception
      'Account profile % does not have a valid normalized username.',
      p_user_id;
  end if;

  select link.person_resource_id
  into v_person_resource_id
  from editorial.person_identity_links link
  where link.user_id = p_user_id
    and link.link_state = 'active'
  limit 1;

  if not found then
    return null;
  end if;

  select resolved.person_resource_id
  into v_resolved_person_resource_id
  from editorial.resolve_person_follow_target(
    v_person_resource_id
  ) resolved;

  if v_resolved_person_resource_id is null then
    raise exception
      'Linked Person % could not resolve to a stable Person survivor.',
      v_person_resource_id;
  end if;

  v_person_resource_id :=
    v_resolved_person_resource_id;

  v_desired_path :=
    '/people/' || v_username;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'person-handle-user|' || p_user_id::text,
      0
    )
  );

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'person-path|' || v_username,
      0
    )
  );

  select
    alias.id,
    alias.resource_id
  into
    v_desired_alias_id,
    v_desired_alias_resource_id
  from editorial.resource_aliases alias
  where alias.path = v_desired_path
  for update;

  if found
     and v_desired_alias_resource_id <>
         v_person_resource_id
  then
    raise exception
      using
        errcode = '23505',
        message = format(
          'Handle %s is permanently reserved by another Person route.',
          v_username
        );
  end if;

  select
    alias.id,
    alias.path
  into
    v_current_alias_id,
    v_current_path
  from editorial.resource_aliases alias
  where alias.resource_id = v_person_resource_id
    and alias.is_canonical
    and alias.retired_at is null
  order by alias.created_at, alias.id
  limit 1
  for update;

  if not found then
    raise exception
      'Linked Person % has no active canonical route.',
      v_person_resource_id;
  end if;

  if v_current_path = v_desired_path then
    return v_desired_path;
  end if;

  if v_desired_alias_id is null then
    insert into editorial.resource_aliases (
      resource_id,
      path,
      is_canonical,
      redirect_status,
      created_by
    )
    values (
      v_person_resource_id,
      v_desired_path,
      false,
      308,
      v_actor_id
    )
    returning id
    into v_desired_alias_id;
  end if;

  update editorial.resource_aliases alias
  set
    is_canonical = false,
    redirect_status = 308,
    retired_at = now(),
    replacement_alias_id = v_desired_alias_id
  where alias.id = v_current_alias_id;

  update editorial.resource_aliases alias
  set
    is_canonical = true,
    redirect_status = 308,
    retired_at = null,
    replacement_alias_id = null
  where alias.id = v_desired_alias_id
    and alias.resource_id = v_person_resource_id;

  if not found then
    raise exception
      'Could not promote % as the canonical route for Person %.',
      v_desired_path,
      v_person_resource_id;
  end if;

  update editorial.people person
  set
    updated_by = coalesce(v_actor_id, person.updated_by),
    updated_at = now()
  where person.resource_id = v_person_resource_id;

  return v_desired_path;
end;
$$;


ALTER FUNCTION "editorial"."sync_account_person_handle"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."sync_artist_portal_roles"("p_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_has_pending_claim boolean;
  v_has_active_representation boolean;
  v_note constant text :=
    'Managed by Artist representation authority';
begin
  if p_user_id is null then
    return;
  end if;

  select exists (
    select 1
    from public.artist_claim_requests claim
    where claim.claimant_user_id = p_user_id
      and claim.status = 'pending'
  )
  into v_has_pending_claim;

  select exists (
    select 1
    from public.artist_representations representation
    where representation.user_id = p_user_id
      and representation.status = 'active'
  )
  into v_has_active_representation;

  if v_has_pending_claim then
    insert into public.user_role_assignments (
      user_id,
      role_key,
      status,
      assigned_by,
      assigned_at,
      notes
    )
    values (
      p_user_id,
      'artist_claimant',
      'active',
      auth.uid(),
      now(),
      v_note
    )
    on conflict (
      user_id,
      role_key
    )
    do update
      set
        status = 'active',
        assigned_by = excluded.assigned_by,
        assigned_at = now(),
        notes = excluded.notes,
        updated_at = now()
      where public.user_role_assignments.notes =
            v_note;
  else
    update public.user_role_assignments
    set
      status = 'revoked',
      updated_at = now()
    where user_id = p_user_id
      and role_key = 'artist_claimant'
      and notes = v_note
      and status is distinct from 'revoked';
  end if;

  if v_has_active_representation then
    insert into public.user_role_assignments (
      user_id,
      role_key,
      status,
      assigned_by,
      assigned_at,
      notes
    )
    values (
      p_user_id,
      'artist_manager',
      'active',
      auth.uid(),
      now(),
      v_note
    )
    on conflict (
      user_id,
      role_key
    )
    do update
      set
        status = 'active',
        assigned_by = excluded.assigned_by,
        assigned_at = now(),
        notes = excluded.notes,
        updated_at = now()
      where public.user_role_assignments.notes =
            v_note;
  else
    update public.user_role_assignments
    set
      status = 'revoked',
      updated_at = now()
    where user_id = p_user_id
      and role_key = 'artist_manager'
      and notes = v_note
      and status is distinct from 'revoked';
  end if;
end;
$$;


