CREATE OR REPLACE FUNCTION "editorial"."sync_playlist_registry_intake_item_artists"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_suggestion_id uuid;
  v_intake_origin text;
  v_item_id uuid;
  v_artist_names text[];
begin
  v_suggestion_id :=
    coalesce(
      new.suggestion_id,
      old.suggestion_id
    );

  select suggestion.intake_origin
  into v_intake_origin
  from public.registry_provider_track_suggestions suggestion
  where suggestion.id = v_suggestion_id;

  if not found
     or v_intake_origin <> 'playlist_editor'
  then
    if tg_op = 'DELETE' then
      return old;
    end if;

    return new;
  end if;

  v_item_id :=
    editorial.ensure_playlist_registry_intake_item(
      v_suggestion_id
    );

  if v_item_id is null then
    if tg_op = 'DELETE' then
      return old;
    end if;

    return new;
  end if;

  select coalesce(
    array_agg(
      coalesce(
        artist.display_name,
        credit.observed_name
      )
      order by credit.credit_order
    ) filter (
      where coalesce(
        artist.display_name,
        credit.observed_name
      ) is not null
    ),
    '{}'::text[]
  )
  into v_artist_names
  from public.registry_provider_track_suggestion_artists credit
  left join public.registry_artists artist
    on artist.id = credit.registry_artist_id
  where credit.suggestion_id = v_suggestion_id;

  update public.wk_playlist_items item
  set artist_names =
    coalesce(
      v_artist_names,
      '{}'::text[]
    )
  where item.id = v_item_id
    and item.lifecycle_state = 'active';

  if tg_op = 'DELETE' then
    return old;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "editorial"."sync_playlist_registry_intake_item_artists"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."sync_public_registry_intake_contribution_status"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_contribution_status text;
begin
  if new.source_contribution_id is null
     or new.intake_origin <> 'public_contribution'
     or new.status is not distinct from old.status
  then
    return new;
  end if;

  v_contribution_status :=
    case
      when new.status in (
        'accepted',
        'canonicalized'
      )
      then 'accepted'
      when new.status = 'rejected'
      then 'rejected'
      else null
    end;

  if v_contribution_status is null then
    return new;
  end if;

  update public.community_contributions contribution
  set
    status = v_contribution_status,
    reviewed_by = new.reviewed_by,
    reviewed_at =
      coalesce(
        new.reviewed_at,
        now()
      ),
    updated_at = now(),
    payload =
      coalesce(
        contribution.payload,
        '{}'::jsonb
      )
      || jsonb_strip_nulls(
           jsonb_build_object(
             'registry_status',
               new.status,
             'registry_track_id',
               coalesce(
                 new.canonicalized_track_id,
                 new.canonical_track_id
               )
           )
         )
  where contribution.id =
    new.source_contribution_id;

  return new;
end;
$$;


