CREATE OR REPLACE FUNCTION "editorial"."validate_citation_locator"("p_locator_type" "text", "p_locator_data" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare
  v_keys text[];
  v_value_text text;
begin
  if p_locator_data is null
     or jsonb_typeof(p_locator_data) <> 'object'
  then
    raise exception 'Citation locator data must be a JSON object';
  end if;

  select coalesce(array_agg(key order by key), array[]::text[])
  into v_keys
  from jsonb_object_keys(p_locator_data) key;

  case p_locator_type
    when 'page' then
      if v_keys <> array['page']::text[]
         or jsonb_typeof(p_locator_data -> 'page') <> 'number'
         or (p_locator_data ->> 'page') !~ '^[0-9]+$'
         or (p_locator_data ->> 'page')::bigint < 1
      then
        raise exception 'Page locator requires one integer page of at least 1';
      end if;

    when 'page_range' then
      if v_keys <> array['endPage', 'startPage']::text[]
         or jsonb_typeof(p_locator_data -> 'startPage') <> 'number'
         or jsonb_typeof(p_locator_data -> 'endPage') <> 'number'
         or (p_locator_data ->> 'startPage') !~ '^[0-9]+$'
         or (p_locator_data ->> 'endPage') !~ '^[0-9]+$'
         or (p_locator_data ->> 'startPage')::bigint < 1
         or (p_locator_data ->> 'endPage')::bigint
              < (p_locator_data ->> 'startPage')::bigint
      then
        raise exception
          'Page-range locator requires valid startPage and endPage integers';
      end if;

    when 'paragraph' then
      if v_keys <> array['paragraph']::text[]
         or jsonb_typeof(p_locator_data -> 'paragraph') <> 'number'
         or (p_locator_data ->> 'paragraph') !~ '^[0-9]+$'
         or (p_locator_data ->> 'paragraph')::bigint < 1
      then
        raise exception
          'Paragraph locator requires one integer paragraph of at least 1';
      end if;

    when 'quotation' then
      if v_keys <> array['quotation']::text[]
         or jsonb_typeof(p_locator_data -> 'quotation') <> 'string'
         or btrim(p_locator_data ->> 'quotation') = ''
      then
        raise exception
          'Quotation locator requires one non-blank quotation';
      end if;

    when 'timestamp' then
      if v_keys <> array['milliseconds']::text[]
         or jsonb_typeof(p_locator_data -> 'milliseconds') <> 'number'
         or (p_locator_data ->> 'milliseconds') !~ '^[0-9]+$'
      then
        raise exception
          'Timestamp locator requires non-negative integer milliseconds';
      end if;

    when 'timestamp_range', 'transcript_range' then
      if v_keys <> array[
           'endMilliseconds',
           'startMilliseconds'
         ]::text[]
         or jsonb_typeof(
              p_locator_data -> 'startMilliseconds'
            ) <> 'number'
         or jsonb_typeof(
              p_locator_data -> 'endMilliseconds'
            ) <> 'number'
         or (p_locator_data ->> 'startMilliseconds') !~ '^[0-9]+$'
         or (p_locator_data ->> 'endMilliseconds') !~ '^[0-9]+$'
         or (p_locator_data ->> 'endMilliseconds')::bigint
              < (p_locator_data ->> 'startMilliseconds')::bigint
      then
        raise exception
          'Range locator requires valid non-negative millisecond bounds';
      end if;

    when 'chapter' then
      if v_keys <> array['chapter']::text[]
         or jsonb_typeof(p_locator_data -> 'chapter') <> 'string'
         or btrim(p_locator_data ->> 'chapter') = ''
      then
        raise exception 'Chapter locator requires one non-blank chapter';
      end if;

    when 'image_frame' then
      if v_keys <> array['frame']::text[]
         or jsonb_typeof(p_locator_data -> 'frame') <> 'number'
         or (p_locator_data ->> 'frame') !~ '^[0-9]+$'
      then
        raise exception
          'Image-frame locator requires one non-negative integer frame';
      end if;

    when 'spreadsheet_row' then
      if v_keys <> array['row', 'sheet']::text[]
         or jsonb_typeof(p_locator_data -> 'sheet') <> 'string'
         or btrim(p_locator_data ->> 'sheet') = ''
         or jsonb_typeof(p_locator_data -> 'row') <> 'number'
         or (p_locator_data ->> 'row') !~ '^[0-9]+$'
         or (p_locator_data ->> 'row')::bigint < 1
      then
        raise exception
          'Spreadsheet-row locator requires a sheet and row of at least 1';
      end if;

    when 'spreadsheet_cell' then
      v_value_text := p_locator_data ->> 'cell';

      if v_keys <> array['cell', 'sheet']::text[]
         or jsonb_typeof(p_locator_data -> 'sheet') <> 'string'
         or btrim(p_locator_data ->> 'sheet') = ''
         or jsonb_typeof(p_locator_data -> 'cell') <> 'string'
         or v_value_text !~ '^[A-Za-z]+[1-9][0-9]*$'
      then
        raise exception
          'Spreadsheet-cell locator requires a sheet and A1-style cell';
      end if;

    when 'archive_identifier' then
      if v_keys <> array['identifier']::text[]
         or jsonb_typeof(p_locator_data -> 'identifier') <> 'string'
         or btrim(p_locator_data ->> 'identifier') = ''
      then
        raise exception
          'Archive locator requires one non-blank identifier';
      end if;

    when 'section_heading' then
      if v_keys <> array['heading']::text[]
         or jsonb_typeof(p_locator_data -> 'heading') <> 'string'
         or btrim(p_locator_data ->> 'heading') = ''
      then
        raise exception
          'Section-heading locator requires one non-blank heading';
      end if;

    when 'whole_source' then
      if p_locator_data <> '{}'::jsonb then
        raise exception 'Whole-source locator requires an empty object';
      end if;

    when 'other' then
      if v_keys <> array['label']::text[]
         or jsonb_typeof(p_locator_data -> 'label') <> 'string'
         or btrim(p_locator_data ->> 'label') = ''
      then
        raise exception 'Other locator requires one non-blank label';
      end if;

    else
      raise exception 'Unsupported Citation locator type: %', p_locator_type;
  end case;
end;
$_$;


ALTER FUNCTION "editorial"."validate_citation_locator"("p_locator_type" "text", "p_locator_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."validate_citation_target_anchor"("p_anchor_type" "text", "p_anchor_data" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare
  v_keys text[];
begin
  if p_anchor_data is null
     or jsonb_typeof(p_anchor_data) <> 'object'
  then
    raise exception 'Citation target anchor data must be a JSON object';
  end if;

  select coalesce(array_agg(key order by key), array[]::text[])
  into v_keys
  from jsonb_object_keys(p_anchor_data) key;

  case p_anchor_type
    when 'whole_version' then
      if p_anchor_data <> '{}'::jsonb then
        raise exception 'Whole-version anchor requires an empty object';
      end if;

    when 'block_id' then
      if v_keys <> array['blockId']::text[]
         or jsonb_typeof(p_anchor_data -> 'blockId') <> 'string'
         or btrim(p_anchor_data ->> 'blockId') = ''
      then
        raise exception 'Block anchor requires one non-blank blockId';
      end if;

    when 'heading_id' then
      if v_keys <> array['headingId']::text[]
         or jsonb_typeof(p_anchor_data -> 'headingId') <> 'string'
         or btrim(p_anchor_data ->> 'headingId') = ''
      then
        raise exception 'Heading anchor requires one non-blank headingId';
      end if;

    when 'paragraph_id' then
      if v_keys <> array['paragraphId']::text[]
         or jsonb_typeof(p_anchor_data -> 'paragraphId') <> 'string'
         or btrim(p_anchor_data ->> 'paragraphId') = ''
      then
        raise exception
          'Paragraph anchor requires one non-blank paragraphId';
      end if;

    when 'character_range' then
      if v_keys <> array['end', 'start']::text[]
         or jsonb_typeof(p_anchor_data -> 'start') <> 'number'
         or jsonb_typeof(p_anchor_data -> 'end') <> 'number'
         or (p_anchor_data ->> 'start') !~ '^[0-9]+$'
         or (p_anchor_data ->> 'end') !~ '^[0-9]+$'
         or (p_anchor_data ->> 'end')::bigint
              < (p_anchor_data ->> 'start')::bigint
      then
        raise exception
          'Character-range anchor requires valid non-negative bounds';
      end if;

    when 'structured_node' then
      if v_keys <> array['nodeId']::text[]
         or jsonb_typeof(p_anchor_data -> 'nodeId') <> 'string'
         or btrim(p_anchor_data ->> 'nodeId') = ''
      then
        raise exception
          'Structured-node anchor requires one non-blank nodeId';
      end if;

    else
      raise exception
        'Unsupported Citation target anchor type: %',
        p_anchor_type;
  end case;
end;
$_$;


ALTER FUNCTION "editorial"."validate_citation_target_anchor"("p_anchor_type" "text", "p_anchor_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "editorial"."validate_correction_case_history"("p_case_resource_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'editorial'
    AS $$
declare
  v_case editorial.correction_cases%rowtype;
  v_resource_kind text;
  v_resource_visibility text;
  v_event_count bigint;
  v_min_event_number bigint;
  v_max_event_number bigint;
  v_first_event editorial.correction_events%rowtype;
  v_latest_event editorial.correction_events%rowtype;
  v_decision_case_id uuid;
  v_decision_outcome text;
  v_application_case_id uuid;
  v_application_decision_id uuid;
  v_application_target_resource_id uuid;
  v_application_resulting_version_id uuid;
  v_current_note_count bigint;
  v_job_status text;
begin
  select correction_case.*
  into v_case
  from editorial.correction_cases correction_case
  where correction_case.resource_id =
    p_case_resource_id;

  if not found then
    raise exception
      'Correction case not found';
  end if;

  select
    resource.resource_kind,
    resource.visibility
  into
    v_resource_kind,
    v_resource_visibility
  from editorial.resources resource
  where resource.id = p_case_resource_id;

  if not found
     or v_resource_kind <> 'correction_case'
  then
    raise exception
      'Correction case must use correction_case resource identity';
  end if;

  if v_resource_visibility <> 'internal' then
    raise exception
      'Correction case resources must remain internal';
  end if;

  if v_case.case_state = 'submitted' then
    if v_case.triage_reason is not null
       or v_case.triaged_by is not null
       or v_case.triaged_at is not null
       or v_case.assigned_investigator_id is not null
       or v_case.assignment_reason is not null
       or v_case.assigned_at is not null
       or v_case.investigation_summary is not null
       or v_case.investigator_recommendation is not null
       or v_case.evidence_ready
       or v_case.submitted_for_decision_by is not null
       or v_case.submitted_for_decision_at is not null
       or v_case.current_decision_id is not null
       or v_case.current_application_id is not null
       or v_case.public_note_disposition is not null
       or v_case.public_note_no_note_reason is not null
       or v_case.contributor_follow_up_disposition is not null
       or v_case.contributor_follow_up_reason is not null
       or v_case.contributor_follow_up_job_id is not null
       or v_case.contributor_follow_up_requested_at is not null
    then
      raise exception
        'Submitted correction case contains later-state metadata';
    end if;
  else
    if nullif(btrim(v_case.triage_reason), '') is null
       or v_case.triaged_by is null
       or v_case.triaged_at is null
    then
      raise exception
        'Triaged correction case requires complete triage metadata';
    end if;

    if not exists (
      select 1
      from editorial.correction_targets target
      where target.case_resource_id =
        p_case_resource_id
        and target.target_role = 'primary'
    ) then
      raise exception
        'Triaged correction case requires one primary target';
    end if;
  end if;

  if v_case.case_state in (
    'investigating',
    'awaiting_decision',
    'decided',
    'applied',
    'closed'
  ) then
    if v_case.assigned_investigator_id is null
       or nullif(
         btrim(v_case.assignment_reason),
         ''
       ) is null
       or v_case.assigned_at is null
    then
      raise exception
        'Active correction case requires complete assignment metadata';
    end if;
  end if;

  if v_case.case_state in (
    'awaiting_decision',
    'decided',
    'applied',
    'closed'
  ) then
    if nullif(
         btrim(v_case.investigation_summary),
         ''
       ) is null
       or nullif(
         btrim(v_case.investigator_recommendation),
         ''
       ) is null
       or not v_case.evidence_ready
       or v_case.submitted_for_decision_by is null
       or v_case.submitted_for_decision_at is null
    then
      raise exception
        'Decision-ready correction case requires complete investigation submission metadata';
    end if;
  elsif v_case.submitted_for_decision_by is not null
        or v_case.submitted_for_decision_at is not null
  then
    raise exception
      'Decision-submission metadata requires awaiting_decision, decided, applied, or closed state';
  end if;

  if v_case.current_decision_id is not null then
    select
      decision.case_resource_id,
      decision.outcome
    into
      v_decision_case_id,
      v_decision_outcome
    from editorial.correction_decisions decision
    where decision.id =
      v_case.current_decision_id;

    if not found
       or v_decision_case_id is distinct from
         p_case_resource_id
    then
      raise exception
        'Current correction decision must belong to the same case';
    end if;
  end if;

  if v_case.current_application_id is not null then
    select
      application.case_resource_id,
      application.decision_id,
      application.target_resource_id,
      application.resulting_version_id
    into
      v_application_case_id,
      v_application_decision_id,
      v_application_target_resource_id,
      v_application_resulting_version_id
    from editorial.correction_applications application
    where application.id =
      v_case.current_application_id;

    if not found
       or v_application_case_id is distinct from
         p_case_resource_id
       or v_application_decision_id is distinct from
         v_case.current_decision_id
    then
      raise exception
        'Current correction application must belong to the same case and current decision';
    end if;
  end if;

  if v_case.case_state in (
    'decided',
    'applied',
    'closed'
  )
     and v_case.current_decision_id is null
  then
    raise exception
      'Decided, applied, or closed correction case requires a current decision';
  end if;

  if v_case.case_state = 'applied'
     and v_case.current_application_id is null
  then
    raise exception
      'Applied correction case requires a current application';
  end if;

  if v_case.case_state = 'closed'
     and v_decision_outcome = 'correction_required'
     and v_case.current_application_id is null
  then
    raise exception
      'Closed correction-required case requires a current application';
  end if;

  if v_case.current_application_id is not null
     and v_case.case_state not in (
       'applied',
       'closed'
     )
  then
    raise exception
      'Current correction application requires applied or closed state';
  end if;

  if v_case.current_application_id is not null
     and v_decision_outcome is distinct from
       'correction_required'
  then
    raise exception
      'Current correction application requires a correction-required decision';
  end if;

  if v_decision_outcome is distinct from
     'correction_required'
  then
    if v_case.public_note_disposition is not null
       or v_case.public_note_no_note_reason is not null
       or v_case.contributor_follow_up_disposition is not null
       or v_case.contributor_follow_up_reason is not null
       or v_case.contributor_follow_up_job_id is not null
       or v_case.contributor_follow_up_requested_at is not null
    then
      raise exception
        'Non-correction outcomes cannot retain public-note or contributor follow-up state';
    end if;
  else
    if v_case.public_note_disposition is null then
      if v_case.public_note_no_note_reason is not null then
        raise exception
          'A public-note reason requires a public-note disposition';
      end if;
    elsif v_case.public_note_disposition = 'published' then
      if v_case.public_note_no_note_reason is not null
         or v_case.current_application_id is null
      then
        raise exception
          'Published public-note disposition requires a current application and no no-note reason';
      end if;

      select count(*)
      into v_current_note_count
      from editorial.correction_public_notes note
      where note.case_resource_id =
          p_case_resource_id
        and note.application_id =
          v_case.current_application_id
        and exists (
          select 1
          from editorial.correction_article_publication_proof(
            v_case.current_application_id
          ) proof
          where proof.corrected_version_id =
            note.corrected_version_id
        )
        and not exists (
          select 1
          from editorial.correction_public_notes later_note
          where later_note.supersedes_note_id =
            note.id
        );

      if v_current_note_count <> 1 then
        raise exception
          'Published public-note disposition requires exactly one current note';
      end if;
    elsif v_case.public_note_disposition = 'not_required' then
      if v_case.current_application_id is null
         or nullif(
           btrim(
             v_case.public_note_no_note_reason
           ),
           ''
         ) is null
         or length(
           v_case.public_note_no_note_reason
         ) > 2000
      then
        raise exception
          'No-note disposition requires a current application and bounded reason';
      end if;

      if exists (
        select 1
        from editorial.correction_public_notes note
        where note.case_resource_id =
            p_case_resource_id
          and note.application_id =
            v_case.current_application_id
      ) then
        raise exception
          'No-note disposition cannot coexist with a public note for the current application';
      end if;
    else
      raise exception
        'Public-note disposition is invalid';
    end if;

    if v_case.origin_type = 'internal_editorial' then
      if v_case.contributor_follow_up_disposition is not null
         or v_case.contributor_follow_up_reason is not null
         or v_case.contributor_follow_up_job_id is not null
         or v_case.contributor_follow_up_requested_at is not null
      then
        raise exception
          'Internal correction cases cannot retain contributor follow-up state';
      end if;
    elsif v_case.origin_type = 'community_contribution' then
      if v_case.contributor_follow_up_disposition is null then
        if v_case.contributor_follow_up_reason is not null
           or v_case.contributor_follow_up_job_id is not null
           or v_case.contributor_follow_up_requested_at is not null
        then
          raise exception
            'Contributor follow-up metadata requires a disposition';
        end if;
      elsif v_case.contributor_follow_up_disposition = 'requested' then
        if v_case.contributor_follow_up_reason is not null
           or v_case.contributor_follow_up_job_id is null
           or v_case.contributor_follow_up_requested_at is null
        then
          raise exception
            'Requested contributor follow-up requires a durable job and request time';
        end if;

        select job.status
        into v_job_status
        from platform_private.jobs job
        join platform_private.command_receipts receipt
          on receipt.id =
            job.command_receipt_id
        where job.id =
            v_case.contributor_follow_up_job_id
          and job.resource_id =
            p_case_resource_id
          and job.command_type =
            'correction.contributor_notification.request'
          and job.job_type =
            'correction.contributor_notification'
          and receipt.command_type =
            'correction.contributor_notification.request'
          and receipt.resource_id =
            p_case_resource_id
          and receipt.status in (
            'accepted',
            'succeeded'
          );

        if not found
           or v_job_status not in (
             'queued',
             'running',
             'retry_wait',
             'succeeded',
             'dead_letter'
           )
        then
          raise exception
            'Requested contributor follow-up requires a durable queued or later-state job';
        end if;
      elsif v_case.contributor_follow_up_disposition in (
        'unavailable',
        'unsafe'
      ) then
        if nullif(
             btrim(
               v_case.contributor_follow_up_reason
             ),
             ''
           ) is null
           or length(
             v_case.contributor_follow_up_reason
           ) > 2000
           or v_case.contributor_follow_up_job_id is not null
           or v_case.contributor_follow_up_requested_at is not null
        then
          raise exception
            'Contributor follow-up exception requires a bounded reason and no job';
        end if;
      else
        raise exception
          'Contributor follow-up disposition is invalid';
      end if;
    end if;
  end if;

  if v_case.case_state = 'closed' then
    if nullif(btrim(v_case.closed_reason), '') is null
       or v_case.closed_by is null
       or v_case.closed_at is null
    then
      raise exception
        'Closed correction case requires complete closure metadata';
    end if;

    if exists (
      select 1
      from editorial.correction_related_resource_reviews review
      where review.case_resource_id =
        p_case_resource_id
        and review.review_state = 'pending'
    ) then
      raise exception
        'Closed correction case cannot retain pending related-resource reviews';
    end if;

    if v_decision_outcome = 'correction_required' then
      if v_case.public_note_disposition is null then
        raise exception
          'Closed correction-required case requires a public-note disposition';
      end if;

      if v_case.origin_type = 'community_contribution'
         and v_case.contributor_follow_up_disposition is null
      then
        raise exception
          'Closed community-origin correction requires contributor follow-up disposition';
      end if;

      if not exists (
        select 1
        from editorial.correction_article_publication_proof(
          v_case.current_application_id
        ) proof
      ) then
        raise exception
          'Closed correction-required case lacks corrected publication proof';
      end if;
    elsif v_case.current_application_id is not null then
      raise exception
        'Non-correction closure cannot retain a current application';
    end if;
  elsif v_case.closed_reason is not null
        or v_case.closed_by is not null
        or v_case.closed_at is not null
  then
    raise exception
      'Closure metadata requires closed state';
  end if;

  select
    count(*),
    min(event.event_number),
    max(event.event_number)
  into
    v_event_count,
    v_min_event_number,
    v_max_event_number
  from editorial.correction_events event
  where event.case_resource_id =
    p_case_resource_id;

  if v_event_count < 1 then
    raise exception
      'Correction case requires an append-only case-created event';
  end if;

  if v_min_event_number <> 1
     or v_max_event_number <> v_event_count
  then
    raise exception
      'Correction event numbers must be contiguous from 1';
  end if;

  select event.*
  into v_first_event
  from editorial.correction_events event
  where event.case_resource_id =
    p_case_resource_id
  order by event.event_number
  limit 1;

  if v_first_event.event_type <> 'case_created'
     or v_first_event.case_revision_before <> 1
     or v_first_event.case_revision_after <> 1
     or v_first_event.prior_state is not null
     or v_first_event.resulting_state <> 'submitted'
  then
    raise exception
      'Correction history must begin with case_created at revision 1';
  end if;

  if exists (
    select 1
    from (
      select
        event.event_number,
        event.case_revision_before,
        event.case_revision_after,
        lag(event.case_revision_before) over (
          order by event.event_number
        ) as prior_revision_before,
        lag(event.case_revision_after) over (
          order by event.event_number
        ) as prior_revision_after
      from editorial.correction_events event
      where event.case_resource_id =
        p_case_resource_id
    ) ordered_event
    where ordered_event.event_number > 1
      and not (
        ordered_event.case_revision_before =
          ordered_event.prior_revision_after
        or (
          ordered_event.case_revision_before =
            ordered_event.prior_revision_before
          and ordered_event.case_revision_after =
            ordered_event.prior_revision_after
        )
      )
  ) then
    raise exception
      'Correction event revision chain is discontinuous';
  end if;

  select event.*
  into v_latest_event
  from editorial.correction_events event
  where event.case_resource_id =
    p_case_resource_id
  order by event.event_number desc
  limit 1;

  if v_latest_event.case_revision_after <>
       v_case.current_revision
     or v_latest_event.resulting_state <>
       v_case.case_state
  then
    raise exception
      'Correction case state and revision must match the latest event';
  end if;
end;
$$;


ALTER FUNCTION "editorial"."validate_correction_case_history"("p_case_resource_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "media"."enforce_asset_pointer_integrity"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'media'
    AS $$
declare
  v_revision_asset_id uuid;
  v_revision_number bigint;
  v_verification_state text;
  v_highest_revision bigint;
  v_governance_asset_id uuid;
begin
  if new.current_revision_id is not null then
    select
      revision.asset_id,
      revision.revision_number,
      file_object.verification_state
    into
      v_revision_asset_id,
      v_revision_number,
      v_verification_state
    from media.asset_revisions revision
    join media.file_objects file_object
      on file_object.id = revision.original_file_object_id
    where revision.id = new.current_revision_id;

    if not found
       or v_revision_asset_id <> new.id
       or v_verification_state <> 'verified'
    then
      raise exception
        'Current Media revision must belong to the asset and use a verified file object';
    end if;

    select max(revision.revision_number)
    into v_highest_revision
    from media.asset_revisions revision
    where revision.asset_id = new.id;

    if v_revision_number <> v_highest_revision then
      raise exception
        'Current Media revision must be the highest asset revision';
    end if;
  end if;

  if new.current_governance_version_id is not null then
    select governance.asset_id
    into v_governance_asset_id
    from media.asset_governance_versions governance
    where governance.id = new.current_governance_version_id;

    if not found
       or v_governance_asset_id <> new.id
    then
      raise exception
        'Current Media governance version must belong to the asset';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "media"."enforce_asset_pointer_integrity"() OWNER TO "postgres";


COMMENT ON FUNCTION "media"."enforce_asset_pointer_integrity"() IS 'Deferred Media pointer-integrity constraint trigger. Runs with postgres owner authority at transaction commit so authenticated command callers do not receive direct canonical table access.';



CREATE OR REPLACE FUNCTION "media"."enforce_asset_revision_integrity"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'media'
    AS $$
declare
  v_previous_asset_id uuid;
  v_previous_number bigint;
begin
  if new.revision_number = 1 then
    if new.previous_revision_id is not null then
      raise exception
        'Media revision 1 must not have a previous revision';
    end if;
  else
    select
      revision.asset_id,
      revision.revision_number
    into
      v_previous_asset_id,
      v_previous_number
    from media.asset_revisions revision
    where revision.id = new.previous_revision_id;

    if not found
       or v_previous_asset_id <> new.asset_id
       or v_previous_number <> new.revision_number - 1
    then
      raise exception
        'Media revision must reference the immediately previous revision for the same asset';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "media"."enforce_asset_revision_integrity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "media"."enforce_governance_integrity"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog'
    AS $$
begin
  if new.retention_state = 'purged' then
    raise exception
      'Purged Media governance requires the future governed physical-purge command';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "media"."enforce_governance_integrity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "media"."enforce_legacy_asset_link_integrity"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog'
    AS $$
begin
  if new.legacy_asset_id is null
     or new.asset_id is null
     or nullif(btrim(new.mapping_reason), '') is null
     or jsonb_typeof(new.legacy_snapshot) <> 'object'
  then
    raise exception
      'Media legacy bridge identity, reason, and snapshot are required';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "media"."enforce_legacy_asset_link_integrity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "media"."enforce_media_event_integrity"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog'
    AS $$
begin
  if num_nonnulls(
       new.asset_id,
       new.file_object_id,
       new.asset_revision_id,
       new.variant_id,
       new.usage_link_id,
       new.governance_version_id
     ) < 1
  then
    raise exception
      'Media event requires at least one canonical object identity';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "media"."enforce_media_event_integrity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "media"."enforce_usage_link_integrity"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'media'
    AS $$
declare
  v_revision_asset_id uuid;
begin
  if new.asset_revision_id is not null then
    select revision.asset_id
    into v_revision_asset_id
    from media.asset_revisions revision
    where revision.id = new.asset_revision_id;

    if not found
       or v_revision_asset_id <> new.asset_id
    then
      raise exception
        'Media usage revision must belong to the same asset';
    end if;
  end if;

  if new.resolution_mode = 'legacy_snapshot'
     and not exists (
       select 1
       from media.legacy_asset_links link
       where link.asset_id = new.asset_id
     )
  then
    raise exception
      'Legacy-snapshot Media usage requires an immutable legacy bridge';
  end if;

  if tg_op = 'UPDATE' then
    if new.usage_state = old.usage_state then
      raise exception
        'Media usage lifecycle update must change usage state';
    end if;

    if new.usage_revision <> old.usage_revision + 1 then
      raise exception
        'Media usage lifecycle update must increment usage revision exactly once';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "media"."enforce_usage_link_integrity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "media"."enforce_variant_integrity"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'media'
    AS $$
declare
  v_revision_asset_id uuid;
  v_revision_original_file_id uuid;
  v_source_state text;
  v_derived_state text;
begin
  select
    revision.asset_id,
    revision.original_file_object_id
  into
    v_revision_asset_id,
    v_revision_original_file_id
  from media.asset_revisions revision
  where revision.id = new.asset_revision_id;

  if not found
     or v_revision_asset_id <> new.asset_id
  then
    raise exception
      'Media variant revision must belong to the same asset';
  end if;

  select file_object.verification_state
  into v_source_state
  from media.file_objects file_object
  where file_object.id = new.source_file_object_id;

  select file_object.verification_state
  into v_derived_state
  from media.file_objects file_object
  where file_object.id = new.derived_file_object_id;

  if v_source_state <> 'verified'
     or v_derived_state <> 'verified'
  then
    raise exception
      'Media variant source and derived file objects must be verified';
  end if;

  if new.source_file_object_id <> v_revision_original_file_id
     and not exists (
       select 1
       from media.variants source_variant
       where source_variant.asset_revision_id = new.asset_revision_id
         and source_variant.derived_file_object_id =
           new.source_file_object_id
     )
  then
    raise exception
      'Media variant source must be the revision original or an existing supported source variant';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "media"."enforce_variant_integrity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "media"."enforce_variant_selection_integrity"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'media'
    AS $$
declare
  v_variant_revision_id uuid;
  v_variant_role text;
  v_derived_state text;
begin
  select
    variant.asset_revision_id,
    variant.variant_role,
    file_object.verification_state
  into
    v_variant_revision_id,
    v_variant_role,
    v_derived_state
  from media.variants variant
  join media.file_objects file_object
    on file_object.id = variant.derived_file_object_id
  where variant.id = new.variant_id;

  if not found
     or v_variant_revision_id <> new.asset_revision_id
     or v_variant_role <> new.variant_role
     or v_derived_state <> 'verified'
  then
    raise exception
      'Selected Media variant must match the revision and role and use a verified derived file';
  end if;

  if tg_op = 'UPDATE' then
    if new.asset_revision_id is distinct from old.asset_revision_id
       or new.variant_role is distinct from old.variant_role
    then
      raise exception
        'Media variant-selection identity is immutable';
    end if;

    if new.variant_id is not distinct from old.variant_id then
      raise exception
        'Media variant activation must select a different immutable variant';
    end if;

    if new.selection_revision <> old.selection_revision + 1 then
      raise exception
        'Media variant activation must increment selection revision exactly once';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "media"."enforce_variant_selection_integrity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "media"."insert_verified_file_object_v2"("p_file" "jsonb", "p_actor_id" "uuid", "p_correlation_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'media'
    AS $_$
declare
  v_file_object_id uuid := gen_random_uuid();
  v_storage_provider text;
  v_storage_namespace text;
  v_storage_path text;
  v_delivery_url text;
  v_original_filename text;
  v_mime_type text;
  v_sha256 text;
  v_byte_size bigint;
  v_file_extension text;
  v_technical_metadata jsonb;
begin
  if p_actor_id is null then
    raise exception 'Media file registration requires an actor';
  end if;

  if p_file is null or jsonb_typeof(p_file) <> 'object' then
    raise exception 'Media file payload must be an object';
  end if;

  v_storage_provider := nullif(btrim(p_file ->> 'storage_provider'), '');
  v_storage_namespace := nullif(btrim(p_file ->> 'storage_namespace'), '');
  v_storage_path := nullif(btrim(p_file ->> 'storage_path'), '');
  v_delivery_url := nullif(btrim(p_file ->> 'delivery_url'), '');
  v_original_filename := nullif(btrim(p_file ->> 'original_filename'), '');
  v_mime_type := nullif(btrim(p_file ->> 'mime_type'), '');
  v_sha256 := lower(nullif(btrim(p_file ->> 'sha256'), ''));
  v_byte_size := nullif(p_file ->> 'byte_size', '')::bigint;
  v_technical_metadata := coalesce(p_file -> 'technical_metadata', '{}'::jsonb);

  if v_storage_provider is null
     or not exists (
       select 1
       from media.storage_providers provider_row
       where provider_row.storage_provider = v_storage_provider
         and provider_row.enabled
     )
  then
    raise exception 'Unknown or disabled Media storage provider';
  end if;

  if v_storage_path is null or v_delivery_url is null then
    raise exception 'Verified Media requires an immutable path and delivery URL';
  end if;

  if v_sha256 is null or v_sha256 !~ '^[0-9a-f]{64}$'
     or v_byte_size is null or v_byte_size < 0
     or v_mime_type is null
  then
    raise exception 'Verified Media requires checksum, byte size, and MIME type';
  end if;

  if jsonb_typeof(v_technical_metadata) <> 'object' then
    raise exception 'Media technical metadata must be an object';
  end if;

  if exists (
    select 1
    from media.file_objects object_row
    where object_row.storage_provider = v_storage_provider
      and coalesce(object_row.storage_namespace, '') = coalesce(v_storage_namespace, '')
      and object_row.storage_path = v_storage_path
  ) then
    raise exception 'Media storage locator is already registered';
  end if;

  v_file_extension :=
    case
      when v_original_filename is not null
       and strpos(reverse(v_original_filename), '.') > 0
      then lower(reverse(split_part(reverse(v_original_filename), '.', 1)))
      else null
    end;

  insert into media.file_objects (
    id,
    sha256,
    byte_size,
    mime_type,
    original_filename,
    file_extension,
    storage_provider,
    storage_namespace,
    storage_path,
    delivery_url,
    technical_metadata,
    verification_state,
    verified_by,
    verified_at,
    verification_error,
    ingested_by
  )
  values (
    v_file_object_id,
    v_sha256,
    v_byte_size,
    v_mime_type,
    v_original_filename,
    v_file_extension,
    v_storage_provider,
    v_storage_namespace,
    v_storage_path,
    v_delivery_url,
    v_technical_metadata,
    'verified',
    p_actor_id,
    now(),
    null,
    p_actor_id
  );

  insert into media.events (
    file_object_id,
    event_type,
    actor_id,
    reason,
    resulting_state,
    correlation_id
  )
  values
    (
      v_file_object_id,
      'file_object_registered',
      p_actor_id,
      'Immutable Media file object registered by operational write authority',
      jsonb_build_object(
        'storage_provider', v_storage_provider,
        'storage_namespace', v_storage_namespace,
        'storage_path', v_storage_path,
        'verification_state', 'verified'
      ),
      p_correlation_id
    ),
    (
      v_file_object_id,
      'file_object_verified',
      p_actor_id,
      'Uploaded Media bytes accepted with checksum evidence',
      jsonb_build_object(
        'sha256', v_sha256,
        'byte_size', v_byte_size,
        'mime_type', v_mime_type,
        'verification_state', 'verified'
      ),
      p_correlation_id
    );

  return v_file_object_id;
end;
$_$;


ALTER FUNCTION "media"."insert_verified_file_object_v2"("p_file" "jsonb", "p_actor_id" "uuid", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "media"."protect_immutable_row"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_guard text;
begin
  if tg_table_schema = 'media'
     and tg_table_name = 'file_objects'
     and tg_op = 'UPDATE'
  then
    v_guard :=
      current_setting(
        'media.verifying_file_object_id',
        true
      );

    if v_guard = old.id::text
       and old.verification_state = 'unverified'
       and new.verification_state in (
         'verified',
         'failed',
         'unreachable'
       )
       and new.id is not distinct from old.id
       and new.storage_provider is not distinct from old.storage_provider
       and new.storage_namespace is not distinct from old.storage_namespace
       and new.storage_path is not distinct from old.storage_path
       and new.delivery_url is not distinct from old.delivery_url
       and new.original_filename is not distinct from old.original_filename
       and new.file_extension is not distinct from old.file_extension
       and new.ingested_by is not distinct from old.ingested_by
       and new.created_at is not distinct from old.created_at
    then
      return new;
    end if;
  end if;

  raise exception
    'Media row in %.% is immutable',
    tg_table_schema,
    tg_table_name;
end;
$$;


ALTER FUNCTION "media"."protect_immutable_row"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "media"."protect_usage_link_identity"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog'
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception
      'Media usage links cannot be deleted';
  end if;

  if new.id is distinct from old.id
     or new.asset_id is distinct from old.asset_id
     or new.asset_revision_id is distinct from old.asset_revision_id
     or new.resolution_mode is distinct from old.resolution_mode
     or new.target_authority is distinct from old.target_authority
     or new.target_kind is distinct from old.target_kind
     or new.target_id is distinct from old.target_id
     or new.target_version_kind is distinct from old.target_version_kind
     or new.target_version_id is distinct from old.target_version_id
     or new.usage_role is distinct from old.usage_role
     or new.placement_data is distinct from old.placement_data
     or new.display_order is distinct from old.display_order
     or new.alt_text_snapshot is distinct from old.alt_text_snapshot
     or new.caption_snapshot is distinct from old.caption_snapshot
     or new.credit_snapshot is distinct from old.credit_snapshot
     or new.created_by is distinct from old.created_by
     or new.created_at is distinct from old.created_at
  then
    raise exception
      'Media usage identity and placement are immutable';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "media"."protect_usage_link_identity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "media"."read_media_assets_admin_phase4a_v2"("p_query" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'media', 'auth'
    AS $_$
declare
  v_query jsonb := coalesce(
    p_query,
    '{}'::jsonb
  );
  v_limit integer;
  v_offset integer;
  v_order_by text;
  v_ascending boolean;
  v_include_references boolean;
  v_result jsonb;
begin
  perform media.require_media_read_actor();

  if jsonb_typeof(v_query) <> 'object' then
    raise exception
      'Administrative Media query must be a JSON object';
  end if;

  if v_query ? 'asset_ids'
     and jsonb_typeof(v_query -> 'asset_ids') <> 'array'
  then
    raise exception
      'Administrative Media asset_ids must be an array';
  end if;

  if v_query ? 'urls'
     and jsonb_typeof(v_query -> 'urls') <> 'array'
  then
    raise exception
      'Administrative Media urls must be an array';
  end if;

  if v_query ? 'source_keys'
     and jsonb_typeof(v_query -> 'source_keys') <> 'array'
  then
    raise exception
      'Administrative Media source_keys must be an array';
  end if;

  v_limit := coalesce(
    nullif(v_query ->> 'limit', '')::integer,
    50
  );
  v_offset := coalesce(
    nullif(v_query ->> 'offset', '')::integer,
    0
  );
  v_order_by := coalesce(
    nullif(btrim(v_query ->> 'order_by'), ''),
    'created_at'
  );
  v_ascending := coalesce(
    nullif(v_query ->> 'ascending', '')::boolean,
    false
  );
  v_include_references := coalesce(
    nullif(
      v_query ->> 'include_references',
      ''
    )::boolean,
    false
  );

  if v_limit < 1 or v_limit > 200 then
    raise exception
      'Administrative Media limit must be between 1 and 200';
  end if;

  if v_offset < 0 then
    raise exception
      'Administrative Media offset cannot be negative';
  end if;

  if v_order_by not in (
    'created_at',
    'updated_at',
    'title',
    'content_date'
  ) then
    raise exception
      'Unsupported administrative Media order';
  end if;

  with asset_ids as (
    select value::uuid as asset_id
    from jsonb_array_elements_text(
      coalesce(
        v_query -> 'asset_ids',
        '[]'::jsonb
      )
    )
  ),
  urls as (
    select value as asset_url
    from jsonb_array_elements_text(
      coalesce(
        v_query -> 'urls',
        '[]'::jsonb
      )
    )
  ),
  source_keys as (
    select value as source_key
    from jsonb_array_elements_text(
      coalesce(
        v_query -> 'source_keys',
        '[]'::jsonb
      )
    )
  ),
  filtered as (
    select
      compatibility.id,
      compatibility.slug,
      compatibility.title,
      compatibility.url,
      compatibility.mime_type,
      compatibility.media_kind,
      compatibility.status,
      compatibility.source_kind,
      compatibility.source_entity,
      compatibility.source_record_id,
      compatibility.source_staging_record_id,
      compatibility.storage_bucket,
      compatibility.storage_path,
      compatibility.folder_id,
      compatibility.file_kind,
      compatibility.asset_purpose,
      compatibility.display_filename,
      compatibility.original_filename,
      compatibility.file_extension,
      compatibility.file_size_bytes,
      compatibility.content_date,
      compatibility.rights_status,
      compatibility.credit_text,
      compatibility.country_code,
      compatibility.language_code,
      compatibility.tags,
      compatibility.internal_notes,
      compatibility.metadata,
      compatibility.created_at,
      compatibility.updated_at,
      bridge.asset_id as canonical_asset_id,
      asset.lifecycle_state as canonical_lifecycle_state,
      asset.authority_revision,
      asset.current_revision_id,
      asset.current_governance_version_id,
      governance.consent_status,
      governance.sensitivity,
      governance.public_safety_state,
      coalesce(
        usage_count.active_usage_count,
        0
      ) as active_usage_count
    from public.registry_media_assets compatibility
    left join media.legacy_asset_links bridge
      on bridge.legacy_asset_id = compatibility.id
    left join media.assets asset
      on asset.id = bridge.asset_id
    left join media.asset_governance_versions governance
      on governance.id =
        asset.current_governance_version_id
    left join lateral (
      select count(*)::bigint as active_usage_count
      from media.usage_links usage
      where usage.asset_id = bridge.asset_id
        and usage.usage_state = 'active'
    ) usage_count
      on true
    where (
      not (v_query ? 'asset_ids')
      or compatibility.id in (
        select asset_id
        from asset_ids
      )
    )
    and (
      not (v_query ? 'urls')
      or compatibility.url in (
        select asset_url
        from urls
      )
    )
    and (
      not (v_query ? 'source_keys')
      or compatibility.source_entity in (
        select source_key
        from source_keys
      )
      or compatibility.source_record_id::text in (
        select source_key
        from source_keys
      )
    )
    and (
      nullif(
        btrim(v_query ->> 'search'),
        ''
      ) is null
      or compatibility.title ilike
        '%' || btrim(v_query ->> 'search') || '%'
      or compatibility.slug ilike
        '%' || btrim(v_query ->> 'search') || '%'
      or compatibility.url ilike
        '%' || btrim(v_query ->> 'search') || '%'
      or compatibility.source_record_id::text ilike
        '%' || btrim(v_query ->> 'search') || '%'
      or compatibility.display_filename ilike
        '%' || btrim(v_query ->> 'search') || '%'
      or compatibility.original_filename ilike
        '%' || btrim(v_query ->> 'search') || '%'
      or compatibility.file_extension ilike
        '%' || btrim(v_query ->> 'search') || '%'
    )
    and (
      nullif(
        btrim(v_query ->> 'media_kind'),
        ''
      ) is null
      or compatibility.media_kind =
        v_query ->> 'media_kind'
    )
    and (
      nullif(
        btrim(v_query ->> 'file_kind'),
        ''
      ) is null
      or compatibility.file_kind =
        v_query ->> 'file_kind'
    )
    and (
      nullif(
        btrim(v_query ->> 'asset_purpose'),
        ''
      ) is null
      or compatibility.asset_purpose =
        v_query ->> 'asset_purpose'
    )
    and (
      nullif(
        btrim(v_query ->> 'folder_id'),
        ''
      ) is null
      or case
        when v_query ->> 'folder_id' = 'none'
          then compatibility.folder_id is null
        when v_query ->> 'folder_id' ~
          '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
          then compatibility.folder_id =
            (v_query ->> 'folder_id')::uuid
        else false
      end
    )
    and (
      nullif(
        btrim(v_query ->> 'rights_status'),
        ''
      ) is null
      or compatibility.rights_status =
        v_query ->> 'rights_status'
    )
    and (
      nullif(
        btrim(v_query ->> 'source_kind'),
        ''
      ) is null
      or compatibility.source_kind =
        v_query ->> 'source_kind'
    )
    and (
      nullif(
        btrim(v_query ->> 'status'),
        ''
      ) is null
      or compatibility.status =
        v_query ->> 'status'
    )
    and (
      not coalesce(
        nullif(
          v_query ->> 'missing_alt_only',
          ''
        )::boolean,
        false
      )
      or nullif(
        btrim(
          compatibility.metadata ->> 'alt_text'
        ),
        ''
      ) is null
    )
    and (
      nullif(
        v_query ->> 'uploaded_from',
        ''
      ) is null
      or compatibility.created_at >=
        (v_query ->> 'uploaded_from')::timestamptz
    )
    and (
      nullif(
        v_query ->> 'uploaded_to',
        ''
      ) is null
      or compatibility.created_at <=
        (v_query ->> 'uploaded_to')::timestamptz
    )
    and (
      nullif(
        v_query ->> 'content_from',
        ''
      ) is null
      or compatibility.content_date >=
        (v_query ->> 'content_from')::date
    )
    and (
      nullif(
        v_query ->> 'content_to',
        ''
      ) is null
      or compatibility.content_date <=
        (v_query ->> 'content_to')::date
    )
  ),
  ordered as (
    select
      filtered.*,
      row_number() over (
        order by
          case
            when v_order_by = 'created_at'
             and v_ascending
              then filtered.created_at
          end asc nulls last,
          case
            when v_order_by = 'created_at'
             and not v_ascending
              then filtered.created_at
          end desc nulls last,
          case
            when v_order_by = 'updated_at'
             and v_ascending
              then filtered.updated_at
          end asc nulls last,
          case
            when v_order_by = 'updated_at'
             and not v_ascending
              then filtered.updated_at
          end desc nulls last,
          case
            when v_order_by = 'title'
             and v_ascending
              then lower(
                coalesce(filtered.title, '')
              )
          end asc nulls last,
          case
            when v_order_by = 'title'
             and not v_ascending
              then lower(
                coalesce(filtered.title, '')
              )
          end desc nulls last,
          case
            when v_order_by = 'content_date'
             and v_ascending
              then filtered.content_date
          end asc nulls last,
          case
            when v_order_by = 'content_date'
             and not v_ascending
              then filtered.content_date
          end desc nulls last,
          filtered.id
      ) as page_order
    from filtered
  ),
  paged as (
    select *
    from ordered
    order by page_order
    limit v_limit
    offset v_offset
  )
  select jsonb_build_object(
    'items',
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id', page_row.id,
          'slug', page_row.slug,
          'title', page_row.title,
          'url', page_row.url,
          'mime_type', page_row.mime_type,
          'media_kind', page_row.media_kind,
          'status', page_row.status,
          'source_kind', page_row.source_kind,
          'source_entity', page_row.source_entity,
          'source_record_id',
            page_row.source_record_id,
          'source_staging_record_id',
            page_row.source_staging_record_id,
          'storage_bucket',
            page_row.storage_bucket,
          'storage_path', page_row.storage_path,
          'folder_id', page_row.folder_id,
          'file_kind', page_row.file_kind,
          'asset_purpose',
            page_row.asset_purpose,
          'display_filename',
            page_row.display_filename,
          'original_filename',
            page_row.original_filename,
          'file_extension',
            page_row.file_extension,
          'file_size_bytes',
            page_row.file_size_bytes,
          'content_date', page_row.content_date,
          'rights_status',
            page_row.rights_status,
          'credit_text', page_row.credit_text,
          'country_code', page_row.country_code,
          'language_code',
            page_row.language_code,
          'tags', page_row.tags,
          'internal_notes',
            page_row.internal_notes,
          'metadata', page_row.metadata,
          'created_at', page_row.created_at,
          'updated_at', page_row.updated_at,
          'canonical_asset_id',
            page_row.canonical_asset_id,
          'canonical_lifecycle_state',
            page_row.canonical_lifecycle_state,
          'authority_revision',
            page_row.authority_revision,
          'current_revision_id',
            page_row.current_revision_id,
          'current_governance_version_id',
            page_row.current_governance_version_id,
          'consent_status',
            page_row.consent_status,
          'sensitivity', page_row.sensitivity,
          'public_safety_state',
            page_row.public_safety_state,
          'active_usage_count',
            page_row.active_usage_count,
          'references',
            case
              when v_include_references
                then (
                  select coalesce(
                    jsonb_agg(
                      jsonb_build_object(
                        'table',
                          reference_row.table_name,
                        'column',
                          reference_row.column_name,
                        'entity_id',
                          reference_row.entity_id,
                        'label',
                          reference_row.label
                      )
                      order by
                        reference_row.table_name,
                        reference_row.entity_id
                    ),
                    '[]'::jsonb
                  )
                  from (
                    select
                      'wk_articles'::text as table_name,
                      'hero_image_id'::text as column_name,
                      article_row.id::text as entity_id,
                      coalesce(
                        nullif(
                          btrim(
                            to_jsonb(article_row)
                              ->> 'title'
                          ),
                          ''
                        ),
                        article_row.id::text
                      ) as label
                    from public.wk_articles article_row
                    where article_row.hero_image_id =
                      page_row.id

                    union all

                    select
                      'registry_artists',
                      'public_image_id',
                      artist_row.id::text,
                      coalesce(
                        nullif(
                          btrim(
                            to_jsonb(artist_row)
                              ->> 'display_name'
                          ),
                          ''
                        ),
                        artist_row.id::text
                      )
                    from public.registry_artists artist_row
                    where artist_row.public_image_id =
                      page_row.id

                    union all

                    select
                      'registry_releases',
                      'artwork_image_id',
                      release_row.id::text,
                      coalesce(
                        nullif(
                          btrim(
                            to_jsonb(release_row)
                              ->> 'title'
                          ),
                          ''
                        ),
                        release_row.id::text
                      )
                    from public.registry_releases release_row
                    where release_row.artwork_image_id =
                      page_row.id

                    union all

                    select
                      'registry_tracks',
                      'artwork_image_id',
                      track_row.id::text,
                      coalesce(
                        nullif(
                          btrim(
                            to_jsonb(track_row)
                              ->> 'title'
                          ),
                          ''
                        ),
                        track_row.id::text
                      )
                    from public.registry_tracks track_row
                    where track_row.artwork_image_id =
                      page_row.id

                    union all

                    select
                      'registry_authors',
                      'cover_image_id',
                      author_row.id::text,
                      coalesce(
                        nullif(
                          btrim(
                            to_jsonb(author_row)
                              ->> 'name'
                          ),
                          ''
                        ),
                        author_row.id::text
                      )
                    from public.registry_authors author_row
                    where author_row.cover_image_id =
                      page_row.id

                    union all

                    select
                      'registry_authors',
                      'avatar_image_id',
                      author_row.id::text,
                      coalesce(
                        nullif(
                          btrim(
                            to_jsonb(author_row)
                              ->> 'name'
                          ),
                          ''
                        ),
                        author_row.id::text
                      )
                    from public.registry_authors author_row
                    where author_row.avatar_image_id =
                      page_row.id

                    union all

                    select
                      'guide_pages',
                      'hero_image_id',
                      guide_page_row.id::text,
                      coalesce(
                        nullif(
                          btrim(
                            to_jsonb(guide_page_row)
                              ->> 'title'
                          ),
                          ''
                        ),
                        guide_page_row.id::text
                      )
                    from public.guide_pages guide_page_row
                    where guide_page_row.hero_image_id =
                      page_row.id

                    union all

                    select
                      'guides',
                      'hero_image_id',
                      guide_row.id::text,
                      coalesce(
                        nullif(
                          btrim(
                            to_jsonb(guide_row)
                              ->> 'title'
                          ),
                          ''
                        ),
                        guide_row.id::text
                      )
                    from public.guides guide_row
                    where guide_row.hero_image_id =
                      page_row.id

                    union all

                    select
                      'registry_artist_highlights',
                      'artwork_image_id',
                      highlight_row.id::text,
                      coalesce(
                        nullif(
                          btrim(
                            to_jsonb(highlight_row)
                              ->> 'title'
                          ),
                          ''
                        ),
                        highlight_row.id::text
                      )
                    from public.registry_artist_highlights
                      highlight_row
                    where highlight_row.artwork_image_id =
                      page_row.id

                    union all

                    select
                      'chart_entries',
                      'artwork_image_id',
                      chart_row.id::text,
                      coalesce(
                        nullif(
                          btrim(
                            to_jsonb(chart_row)
                              ->> 'track_title'
                          ),
                          ''
                        ),
                        chart_row.id::text
                      )
                    from public.chart_entries chart_row
                    where chart_row.artwork_image_id =
                      page_row.id

                    union all

                    select
                      'wk_chart_entries_v2',
                      'artwork_image_id',
                      chart_v2_row.id::text,
                      coalesce(
                        nullif(
                          btrim(
                            to_jsonb(chart_v2_row)
                              ->> 'track_title'
                          ),
                          ''
                        ),
                        chart_v2_row.id::text
                      )
                    from public.wk_chart_entries_v2
                      chart_v2_row
                    where chart_v2_row.artwork_image_id =
                      page_row.id
                  ) reference_row
                )
              else '[]'::jsonb
            end
        )
        order by page_row.page_order
      ),
      '[]'::jsonb
    ),
    'total',
      (select count(*) from filtered)
  )
  into v_result
  from paged page_row;

  return coalesce(
    v_result,
    jsonb_build_object(
      'items',
      '[]'::jsonb,
      'total',
      0
    )
  );
end;
$_$;


ALTER FUNCTION "media"."read_media_assets_admin_phase4a_v2"("p_query" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "media"."register_optional_variant_v2"("p_asset_id" "uuid", "p_asset_revision_id" "uuid", "p_original_file_object_id" "uuid", "p_variant" "jsonb", "p_actor_id" "uuid", "p_correlation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'media'
    AS $$
declare
  v_derived_file_object_id uuid;
  v_variant record;
  v_selection record;
  v_variant_role text;
begin
  if p_variant is null or p_variant = 'null'::jsonb then
    return null;
  end if;

  if jsonb_typeof(p_variant) <> 'object'
     or jsonb_typeof(p_variant -> 'file') <> 'object'
  then
    raise exception 'Media variant payload must include a file object';
  end if;

  v_variant_role := nullif(btrim(p_variant ->> 'variant_role'), '');

  if v_variant_role is null then
    raise exception 'Media variant role is required';
  end if;

  v_derived_file_object_id := media.insert_verified_file_object_v2(
    p_variant -> 'file',
    p_actor_id,
    p_correlation_id
  );

  select *
  into v_variant
  from public.register_media_variant(
    p_asset_id,
    p_asset_revision_id,
    p_original_file_object_id,
    v_derived_file_object_id,
    v_variant_role,
    coalesce(p_variant -> 'transformation_spec', '{}'::jsonb),
    coalesce(p_variant -> 'technical_metadata', '{}'::jsonb),
    nullif(btrim(p_variant ->> 'generator_name'), ''),
    nullif(btrim(p_variant ->> 'generator_version'), ''),
    p_correlation_id
  );

  select *
  into v_selection
  from public.activate_media_variant(
    p_asset_revision_id,
    v_variant_role,
    v_variant.variant_id,
    0,
    'Activate immutable derivative for the current Media revision',
    p_correlation_id
  );

  return jsonb_build_object(
    'derived_file_object_id', v_derived_file_object_id,
    'variant_id', v_variant.variant_id,
    'variant_role', v_variant_role,
    'selection_revision', v_selection.selection_revision
  );
end;
$$;


ALTER FUNCTION "media"."register_optional_variant_v2"("p_asset_id" "uuid", "p_asset_revision_id" "uuid", "p_original_file_object_id" "uuid", "p_variant" "jsonb", "p_actor_id" "uuid", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "media"."require_command_actor"("p_capability" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_actor_id uuid;
begin
  v_actor_id := auth.uid();

  if v_actor_id is null then
    raise exception 'Authenticated Media command actor is required';
  end if;

  if not (
    public.current_user_has_capability(p_capability)
    or public.current_user_is_administrator()
  ) then
    raise exception
      'Media capability % is required',
      p_capability;
  end if;

  return v_actor_id;
end;
$$;


ALTER FUNCTION "media"."require_command_actor"("p_capability" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "media"."require_media_read_actor"() RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_actor_id uuid;
begin
  v_actor_id := auth.uid();

  if v_actor_id is null then
    raise exception
      'Authenticated Media read actor is required';
  end if;

  if not (
    public.current_user_has_capability(
      'view_media_records'
    )
    or public.current_user_has_capability(
      'manage_media_assets'
    )
    or public.current_user_has_capability(
      'manage_media_usage'
    )
    or public.current_user_has_capability(
      'review_media_governance'
    )
    or public.current_user_is_administrator()
  ) then
    raise exception
      'Media read authority is required';
  end if;

  return v_actor_id;
end;
$$;


ALTER FUNCTION "media"."require_media_read_actor"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "media"."usage_role_matches_target"("p_usage_role" "text", "p_target_authority" "text", "p_target_kind" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO 'pg_catalog'
    AS $$
  select case p_usage_role
    when 'article_hero' then
      p_target_authority = 'editorial'
      and p_target_kind = 'article'
    when 'article_inline' then
      p_target_authority = 'editorial'
      and p_target_kind = 'article'
    when 'playlist_cover' then
      p_target_authority = 'editorial'
      and p_target_kind = 'playlist'
    when 'chart_artwork' then
      p_target_authority = 'charts'
      and p_target_kind = 'chart_entry'
    when 'artist_portrait' then
      p_target_authority = 'registry'
      and p_target_kind = 'artist'
    when 'author_avatar' then
      p_target_authority = 'registry'
      and p_target_kind = 'author'
    when 'author_cover' then
      p_target_authority = 'registry'
      and p_target_kind = 'author'
    when 'release_artwork' then
      p_target_authority = 'registry'
      and p_target_kind = 'release'
    when 'track_artwork' then
      p_target_authority = 'registry'
      and p_target_kind = 'track'
    when 'guide_hero' then
      p_target_authority = 'guides'
      and p_target_kind in ('guide', 'guide_page')
    when 'highlight_artwork' then
      p_target_authority = 'registry'
      and p_target_kind = 'highlight'
    when 'source_attachment' then
      p_target_authority = 'sources'
      and p_target_kind = 'source'
    when 'other' then
      true
    else
      false
  end;
$$;


ALTER FUNCTION "media"."usage_role_matches_target"("p_usage_role" "text", "p_target_authority" "text", "p_target_kind" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "media"."usage_role_requires_stability"("p_usage_role" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO 'pg_catalog'
    AS $$
  select p_usage_role <> 'other';
$$;


ALTER FUNCTION "media"."usage_role_requires_stability"("p_usage_role" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "media"."usage_target_snapshot_is_attachable"("p_target_snapshot" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO 'pg_catalog'
    AS $$
  select
    p_target_snapshot is not null
    and jsonb_typeof(p_target_snapshot) = 'object'
    and nullif(
      btrim(
        coalesce(
          p_target_snapshot ->> 'archived_at',
          ''
        )
      ),
      ''
    ) is null
    and nullif(
      btrim(
        coalesce(
          p_target_snapshot ->> 'deleted_at',
          ''
        )
      ),
      ''
    ) is null
    and lower(
      coalesce(
        p_target_snapshot ->> 'status',
        ''
      )
    ) not in (
      'archived',
      'deleted',
      'trash',
      'withdrawn',
      'rejected',
      'unresolved',
      'superseded',
      'inactive',
      'disabled'
    )
    and lower(
      coalesce(
        p_target_snapshot ->> 'lifecycle_state',
        ''
      )
    ) not in (
      'archived',
      'deleted',
      'trash',
      'withdrawn',
      'rejected',
      'unresolved',
      'superseded',
      'inactive',
      'disabled'
    )
    and lower(
      coalesce(
        p_target_snapshot ->> 'wp_status',
        ''
      )
    ) <> 'trash'
    and lower(
      coalesce(
        p_target_snapshot ->> 'source_state',
        ''
      )
    ) not in (
      'archived',
      'deleted',
      'withdrawn',
      'rejected',
      'unresolved',
      'superseded',
      'inactive',
      'disabled'
    )
    and lower(
      coalesce(
        p_target_snapshot ->> 'resolution_state',
        ''
      )
    ) not in (
      'rejected',
      'unresolved',
      'superseded'
    )
    and lower(
      coalesce(
        p_target_snapshot ->> 'review_status',
        ''
      )
    ) not in (
      'rejected',
      'withdrawn',
      'unresolved'
    )
    and lower(
      coalesce(
        p_target_snapshot ->> 'is_active',
        'true'
      )
    ) <> 'false';
$$;


ALTER FUNCTION "media"."usage_target_snapshot_is_attachable"("p_target_snapshot" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "media"."validate_usage_target"("p_actor_id" "uuid", "p_target_authority" "text", "p_target_kind" "text", "p_target_id" "uuid", "p_target_version_kind" "text" DEFAULT NULL::"text", "p_target_version_id" "uuid" DEFAULT NULL::"uuid", "p_require_edit_authority" boolean DEFAULT true, "p_require_attachable_target" boolean DEFAULT true) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial', 'auth'
    AS $$
declare
  v_exists boolean := false;
  v_authorized boolean := false;
  v_version_kind text;
  v_target_snapshot jsonb;
begin
  if p_actor_id is null then
    raise exception 'Media target validation requires an actor';
  end if;

  if p_target_id is null then
    raise exception 'Media usage target identity is required';
  end if;

  if not (
    (
      p_target_authority = 'editorial'
      and p_target_kind in ('article', 'playlist')
    )
    or (
      p_target_authority = 'registry'
      and p_target_kind in (
        'artist',
        'author',
        'release',
        'track',
        'highlight'
      )
    )
    or (
      p_target_authority = 'charts'
      and p_target_kind = 'chart_entry'
    )
    or (
      p_target_authority = 'guides'
      and p_target_kind in ('guide', 'guide_page')
    )
    or (
      p_target_authority = 'sources'
      and p_target_kind = 'source'
    )
  ) then
    raise exception 'Unsupported Media usage target authority and kind';
  end if;

  case
    when p_target_authority = 'editorial'
      and p_target_kind = 'article'
    then
      select to_jsonb(article_row)
      into v_target_snapshot
      from public.wk_articles article_row
      where article_row.id = p_target_id;

    when p_target_authority = 'editorial'
      and p_target_kind = 'playlist'
    then
      select to_jsonb(playlist_row)
      into v_target_snapshot
      from public.wk_playlists playlist_row
      where playlist_row.id = p_target_id;

    when p_target_authority = 'registry'
      and p_target_kind = 'artist'
    then
      select to_jsonb(artist_row)
      into v_target_snapshot
      from public.registry_artists artist_row
      where artist_row.id = p_target_id;

    when p_target_authority = 'registry'
      and p_target_kind = 'author'
    then
      select to_jsonb(author_row)
      into v_target_snapshot
      from public.registry_authors author_row
      where author_row.id = p_target_id;

    when p_target_authority = 'registry'
      and p_target_kind = 'release'
    then
      select to_jsonb(release_row)
      into v_target_snapshot
      from public.registry_releases release_row
      where release_row.id = p_target_id;

    when p_target_authority = 'registry'
      and p_target_kind = 'track'
    then
      select to_jsonb(track_row)
      into v_target_snapshot
      from public.registry_tracks track_row
      where track_row.id = p_target_id;

    when p_target_authority = 'registry'
      and p_target_kind = 'highlight'
    then
      select to_jsonb(highlight_row)
      into v_target_snapshot
      from public.registry_artist_highlights highlight_row
      where highlight_row.id = p_target_id;

    when p_target_authority = 'charts'
      and p_target_kind = 'chart_entry'
    then
      select to_jsonb(entry_row)
      into v_target_snapshot
      from public.chart_entries entry_row
      where entry_row.id = p_target_id;

    when p_target_authority = 'guides'
      and p_target_kind = 'guide'
    then
      select to_jsonb(guide_row)
      into v_target_snapshot
      from public.guides guide_row
      where guide_row.id = p_target_id;

    when p_target_authority = 'guides'
      and p_target_kind = 'guide_page'
    then
      select to_jsonb(page_row)
      into v_target_snapshot
      from public.guide_pages page_row
      where page_row.id = p_target_id;

    when p_target_authority = 'sources'
      and p_target_kind = 'source'
    then
      select to_jsonb(source_row)
      into v_target_snapshot
      from editorial.sources source_row
      where source_row.id = p_target_id;
  end case;

  v_exists := v_target_snapshot is not null;

  if not v_exists then
    raise exception 'Media usage target does not exist';
  end if;

  if p_require_attachable_target
    and not media.usage_target_snapshot_is_attachable(v_target_snapshot)
  then
    raise exception 'Media usage target is archived or unresolved';
  end if;

  if (
    p_target_version_kind is null
    and p_target_version_id is not null
  ) or (
    p_target_version_kind is not null
    and p_target_version_id is null
  ) then
    raise exception 'Media target-version kind and identity must be supplied together';
  end if;

  if p_target_version_id is not null then
    if p_target_authority = 'editorial'
      and p_target_kind = 'article'
    then
      select version_row.version_kind
      into v_version_kind
      from editorial.article_versions version_row
      where version_row.id = p_target_version_id
        and version_row.article_id = p_target_id;

      if not found
        or v_version_kind is distinct from p_target_version_kind
      then
        raise exception 'Media Article target version is invalid';
      end if;

    elsif p_target_authority = 'editorial'
      and p_target_kind = 'playlist'
    then
      select version_row.version_kind
      into v_version_kind
      from editorial.playlist_versions version_row
      where version_row.id = p_target_version_id
        and version_row.playlist_id = p_target_id;

      if not found
        or v_version_kind is distinct from p_target_version_kind
      then
        raise exception 'Media Playlist target version is invalid';
      end if;

    elsif p_target_authority = 'sources'
      and p_target_kind = 'source'
    then
      if p_target_version_kind <> 'source_version'
        or not exists (
          select 1
          from editorial.source_versions version_row
          where version_row.id = p_target_version_id
            and version_row.source_id = p_target_id
        )
      then
        raise exception 'Media Source target version is invalid';
      end if;

    else
      raise exception 'This Media usage target does not support version identity';
    end if;
  end if;

  if not p_require_edit_authority then
    return;
  end if;

  if public.current_user_is_administrator() then
    return;
  end if;

  case p_target_authority
    when 'editorial' then
      if p_target_kind = 'article' then
        v_authorized :=
          public.current_user_has_capability('edit_others_articles')
          or public.current_user_has_capability('publish_articles')
          or (
            public.current_user_has_capability('edit_own_articles')
            and exists (
              select 1
              from editorial.article_resources binding
              join editorial.resources resource_row
                on resource_row.id = binding.resource_id
              where binding.article_id = p_target_id
                and resource_row.owner_id = p_actor_id
            )
          );
      elsif p_target_kind = 'playlist' then
        v_authorized :=
          public.current_user_has_capability('edit_others_playlists')
          or public.current_user_has_capability('publish_playlists')
          or (
            public.current_user_has_capability('edit_own_playlists')
            and exists (
              select 1
              from editorial.playlist_resources binding
              join editorial.resources resource_row
                on resource_row.id = binding.resource_id
              where binding.playlist_id = p_target_id
                and resource_row.owner_id = p_actor_id
            )
          );
      end if;

    when 'registry' then
      v_authorized := public.current_user_has_capability('manage_registry');

    when 'charts' then
      v_authorized := public.current_user_has_capability('manage_charts');

    when 'guides' then
      v_authorized := public.current_user_has_capability('edit_guides');

    when 'sources' then
      v_authorized := public.current_user_has_capability('manage_sources');
  end case;

  if not coalesce(v_authorized, false) then
    raise exception 'Edit authority for the Media usage target is required';
  end if;
end;
$$;


ALTER FUNCTION "media"."validate_usage_target"("p_actor_id" "uuid", "p_target_authority" "text", "p_target_kind" "text", "p_target_id" "uuid", "p_target_version_kind" "text", "p_target_version_id" "uuid", "p_require_edit_authority" boolean, "p_require_attachable_target" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "platform_private"."append_correction_application_event"("p_case_resource_id" "uuid", "p_event_type" "text", "p_case_revision_before" bigint, "p_case_revision_after" bigint, "p_prior_state" "text", "p_resulting_state" "text", "p_actor_id" "uuid", "p_reason" "text", "p_decision_id" "uuid", "p_application_id" "uuid", "p_target_id" "uuid", "p_command_receipt_id" "uuid", "p_correlation_id" "uuid", "p_metadata" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'editorial'
    AS $$
declare
  v_event_number bigint;
  v_event_id uuid;
begin
  if p_metadata is null
     or jsonb_typeof(p_metadata) <> 'object'
     or octet_length(p_metadata::text) > 32768
  then
    raise exception
      using errcode = '22023',
      message = 'Correction application event metadata must be a JSON object no larger than 32 KB.';
  end if;

  perform 1
  from editorial.correction_cases correction_case
  where correction_case.resource_id =
    p_case_resource_id
  for update;

  if not found then
    raise exception
      'Correction case does not exist.';
  end if;

  select coalesce(
    max(event.event_number),
    0
  ) + 1
  into v_event_number
  from editorial.correction_events event
  where event.case_resource_id =
    p_case_resource_id;

  insert into editorial.correction_events (
    case_resource_id,
    event_number,
    event_type,
    case_revision_before,
    case_revision_after,
    prior_state,
    resulting_state,
    actor_id,
    reason,
    decision_id,
    application_id,
    target_id,
    command_receipt_id,
    correlation_id,
    metadata
  )
  values (
    p_case_resource_id,
    v_event_number,
    p_event_type,
    p_case_revision_before,
    p_case_revision_after,
    p_prior_state,
    p_resulting_state,
    p_actor_id,
    p_reason,
    p_decision_id,
    p_application_id,
    p_target_id,
    p_command_receipt_id,
    p_correlation_id,
    p_metadata
  )
  returning id
  into v_event_id;

  return v_event_id;
end;
$$;


ALTER FUNCTION "platform_private"."append_correction_application_event"("p_case_resource_id" "uuid", "p_event_type" "text", "p_case_revision_before" bigint, "p_case_revision_after" bigint, "p_prior_state" "text", "p_resulting_state" "text", "p_actor_id" "uuid", "p_reason" "text", "p_decision_id" "uuid", "p_application_id" "uuid", "p_target_id" "uuid", "p_command_receipt_id" "uuid", "p_correlation_id" "uuid", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "platform_private"."append_correction_event"("p_case_resource_id" "uuid", "p_event_type" "text", "p_case_revision_before" bigint, "p_case_revision_after" bigint, "p_prior_state" "text", "p_resulting_state" "text", "p_actor_id" "uuid", "p_reason" "text", "p_decision_id" "uuid" DEFAULT NULL::"uuid", "p_target_id" "uuid" DEFAULT NULL::"uuid", "p_evidence_link_id" "uuid" DEFAULT NULL::"uuid", "p_related_resource_review_id" "uuid" DEFAULT NULL::"uuid", "p_command_receipt_id" "uuid" DEFAULT NULL::"uuid", "p_correlation_id" "uuid" DEFAULT NULL::"uuid", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'editorial'
    AS $$
declare
  v_event_number bigint;
  v_event_id uuid;
begin
  if p_metadata is null
     or jsonb_typeof(p_metadata) <> 'object'
     or octet_length(p_metadata::text) > 32768
  then
    raise exception
      using errcode = '22023',
      message = 'Correction event metadata must be a JSON object no larger than 32 KB.';
  end if;

  perform 1
  from editorial.correction_cases correction_case
  where correction_case.resource_id =
    p_case_resource_id
  for update;

  if not found then
    raise exception
