    case_resource_id,
    event_number,
    event_type,
    case_revision_before,
    case_revision_after,
    prior_state,
    resulting_state,
    actor_id,
    reason,
    decision_id,
    target_id,
    evidence_link_id,
    related_resource_review_id,
    command_receipt_id,
    correlation_id,
    metadata
  )
  values (
    p_case_resource_id,
    v_event_number,
    p_event_type,
    p_case_revision_before,
    p_case_revision_after,
    p_prior_state,
    p_resulting_state,
    p_actor_id,
    p_reason,
    p_decision_id,
    p_target_id,
    p_evidence_link_id,
    p_related_resource_review_id,
    p_command_receipt_id,
    p_correlation_id,
    p_metadata
  )
  returning id
  into v_event_id;

  return v_event_id;
end;
$$;


