CREATE OR REPLACE FUNCTION "platform_private"."assert_correction_capability"("p_capability" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'platform_private'
    AS $$
declare
  v_context record;
begin
  select *
  into v_context
  from platform_private.correction_actor_context();

  if v_context.auth_role <> 'service_role'
     and not coalesce(
       public.current_user_is_administrator(),
       false
     )
     and not coalesce(
       public.current_user_has_capability(
         p_capability
       ),
       false
     )
  then
    raise exception
      using
        errcode = '42501',
        message = 'The caller does not hold the required correction capability.';
  end if;

  return v_context.actor_user_id;
end;
$$;


ALTER FUNCTION "platform_private"."assert_correction_capability"("p_capability" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "platform_private"."assert_outbox_event_type"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'platform_private'
    AS $$
declare
  allowed boolean;
begin
  select new.event_type in (
    command_types.accepted_event_type,
    command_types.success_event_type,
    command_types.failure_event_type,
    command_types.retry_event_type
  )
  into allowed
  from platform_private.command_types
  where command_types.command_type = new.command_type
    and command_types.enabled;

  if coalesce(allowed, false) is not true then
    raise exception
      'Unsupported event type % for command type %.',
      new.event_type,
      new.command_type;
  end if;

  return new;
end
$$;


