CREATE OR REPLACE FUNCTION "platform_private"."begin_authenticated_resource_command"("p_command_type" "text", "p_resource_id" "uuid", "p_idempotency_key" "text", "p_request_payload" "jsonb") RETURNS TABLE("command_receipt_id" "uuid", "receipt_status" "text", "result_payload" "jsonb", "idempotent_replay" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'auth', 'editorial', 'platform_private'
    AS $_$
declare
  v_context record;
  v_fingerprint text;
  v_receipt platform_private.command_receipts%rowtype;
  v_created boolean;
begin
  if p_resource_id is null then
    raise exception
      using errcode = '22023', message = 'resource_id is required.';
  end if;

  if p_idempotency_key is null
     or p_idempotency_key !~
       '^[A-Za-z0-9][A-Za-z0-9._:-]{7,127}$'
  then
    raise exception
      using
        errcode = '22023',
        message = 'idempotency_key must contain 8 to 128 permitted characters.';
  end if;

  if p_request_payload is null
     or jsonb_typeof(p_request_payload) <> 'object'
     or octet_length(p_request_payload::text) > 32768
  then
    raise exception
      using
        errcode = '22023',
        message = 'request_payload must be a JSON object no larger than 32 KB.';
  end if;

  if not exists (
    select 1
    from platform_private.command_types command_type
    where command_type.command_type = p_command_type
      and command_type.enabled
  ) then
    raise exception
      using
        errcode = '22023',
        message = 'The command type is missing or disabled.';
  end if;

  if not exists (
    select 1
    from editorial.resources resource_row
    where resource_row.id = p_resource_id
  ) then
    raise exception
      using
        errcode = 'P0002',
        message = 'The command resource does not exist.';
  end if;

  select *
  into v_context
  from platform_private.command_actor_context();

  v_fingerprint :=
    platform_private.command_request_fingerprint(
      p_command_type,
      p_resource_id,
      p_request_payload
    );

  insert into platform_private.command_receipts (
    command_type,
    resource_id,
    principal_key,
    actor_user_id,
    idempotency_key,
    request_fingerprint,
    request_payload
  )
  values (
    p_command_type,
    p_resource_id,
    v_context.principal_key,
    v_context.actor_user_id,
    p_idempotency_key,
    v_fingerprint,
    p_request_payload
  )
  on conflict (
    principal_key,
    command_type,
    idempotency_key
  )
  do nothing
  returning *
  into v_receipt;

  v_created := found;

  if not v_created then
    select receipt.*
    into v_receipt
    from platform_private.command_receipts receipt
    where receipt.principal_key = v_context.principal_key
      and receipt.command_type = p_command_type
      and receipt.idempotency_key = p_idempotency_key
    for update;

    if not found then
      raise exception 'The idempotency receipt disappeared.';
    end if;

    if v_receipt.request_fingerprint <> v_fingerprint then
      raise exception
        using
          errcode = '23505',
          message = 'The idempotency key was already used for a different request.';
    end if;

    return query
    select
      v_receipt.id,
      v_receipt.status,
      v_receipt.result_payload,
      true;
    return;
  end if;

  insert into platform_private.outbox_events (
    event_key,
    command_receipt_id,
    command_type,
    aggregate_id,
    event_type,
    payload
  )
  select
    'command:' || v_receipt.id::text || ':accepted',
    v_receipt.id,
    command_type.command_type,
    p_resource_id,
    command_type.accepted_event_type,
    jsonb_build_object(
      'command_receipt_id', v_receipt.id,
      'command_type', p_command_type,
      'resource_id', p_resource_id,
      'principal_key', v_context.principal_key,
      'correlation_id', p_request_payload ->> 'correlation_id',
      'accepted_at', now()
    )
  from platform_private.command_types command_type
  where command_type.command_type = p_command_type;

  return query
  select
    v_receipt.id,
    v_receipt.status,
    v_receipt.result_payload,
    false;
end;
$_$;


ALTER FUNCTION "platform_private"."begin_authenticated_resource_command"("p_command_type" "text", "p_resource_id" "uuid", "p_idempotency_key" "text", "p_request_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "platform_private"."begin_correction_create_command"("p_command_type" "text", "p_idempotency_key" "text", "p_request_payload" "jsonb") RETURNS TABLE("case_resource_id" "uuid", "command_receipt_id" "uuid", "receipt_status" "text", "result_payload" "jsonb", "idempotent_replay" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'auth', 'editorial', 'platform_private'
    AS $_$
declare
  v_context record;
  v_fingerprint text;
  v_receipt platform_private.command_receipts%rowtype;
  v_resource_id uuid := gen_random_uuid();
begin
  if p_idempotency_key is null
     or p_idempotency_key !~
       '^[A-Za-z0-9][A-Za-z0-9._:-]{7,127}$'
  then
    raise exception
      using errcode = '22023',
      message = 'idempotency_key must contain 8 to 128 permitted characters.';
  end if;

  if p_request_payload is null
     or jsonb_typeof(p_request_payload) <> 'object'
     or octet_length(p_request_payload::text) > 32768
  then
    raise exception
      using errcode = '22023',
      message = 'request_payload must be a JSON object no larger than 32 KB.';
  end if;

  if p_command_type not in (
    'correction.case.create_from_contribution',
    'correction.case.create_internal'
  ) then
    raise exception
      using errcode = '22023',
      message = 'Unsupported correction case creation command.';
  end if;

  select *
  into v_context
  from platform_private.correction_actor_context();

  v_fingerprint :=
    platform_private.correction_request_fingerprint(
      p_command_type,
      null,
      p_request_payload
    );

  select receipt.*
  into v_receipt
  from platform_private.command_receipts receipt
  where receipt.principal_key =
      v_context.principal_key
    and receipt.command_type =
      p_command_type
    and receipt.idempotency_key =
      p_idempotency_key
  for update;

  if found then
    if v_receipt.request_fingerprint <>
       v_fingerprint
    then
      raise exception
        using
          errcode = '23505',
          message = 'The idempotency key was already used for a different request.';
    end if;

    return query
    select
      v_receipt.resource_id,
      v_receipt.id,
      v_receipt.status,
      v_receipt.result_payload,
      true;
    return;
  end if;

  insert into editorial.resources (
    id,
    resource_kind,
    visibility,
    lifecycle_state,
    created_by
  )
  values (
    v_resource_id,
    'correction_case',
    'internal',
    'active',
    v_context.actor_user_id
  );

  begin
    insert into platform_private.command_receipts (
      command_type,
      resource_id,
      principal_key,
      actor_user_id,
      idempotency_key,
      request_fingerprint,
      request_payload
    )
    values (
      p_command_type,
      v_resource_id,
      v_context.principal_key,
      v_context.actor_user_id,
      p_idempotency_key,
      v_fingerprint,
      p_request_payload
    )
    returning *
    into v_receipt;
  exception
    when unique_violation then
      delete from editorial.resources
      where id = v_resource_id;

      select receipt.*
      into v_receipt
      from platform_private.command_receipts receipt
      where receipt.principal_key =
          v_context.principal_key
        and receipt.command_type =
          p_command_type
        and receipt.idempotency_key =
          p_idempotency_key
      for update;

      if not found then
        raise;
      end if;

      if v_receipt.request_fingerprint <>
         v_fingerprint
      then
        raise exception
          using
            errcode = '23505',
            message = 'The idempotency key was already used for a different request.';
      end if;

      return query
      select
        v_receipt.resource_id,
        v_receipt.id,
        v_receipt.status,
        v_receipt.result_payload,
        true;
      return;
  end;

  insert into platform_private.outbox_events (
    event_key,
    command_receipt_id,
    command_type,
    aggregate_id,
    event_type,
    payload
  )
  select
    'command:' ||
      v_receipt.id::text ||
      ':accepted',
    v_receipt.id,
    command_type.command_type,
    v_resource_id,
    command_type.accepted_event_type,
    jsonb_build_object(
      'command_receipt_id', v_receipt.id,
      'command_type', p_command_type,
      'resource_id', v_resource_id,
      'principal_key', v_context.principal_key,
      'accepted_at', now()
    )
  from platform_private.command_types command_type
  where command_type.command_type =
    p_command_type;

  return query
  select
    v_resource_id,
    v_receipt.id,
    v_receipt.status,
    v_receipt.result_payload,
    false;
end;
$_$;


