CREATE OR REPLACE FUNCTION "platform_private"."claim_jobs"("p_worker_id" "text", "p_limit" integer DEFAULT 1, "p_lease_seconds" integer DEFAULT 300) RETURNS TABLE("job_id" "uuid", "command_receipt_id" "uuid", "resource_id" "uuid", "command_type" "text", "job_type" "text", "attempt_count" integer, "max_attempts" integer, "input_payload" "jsonb", "lease_expires_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'auth', 'platform_private'
    AS $_$
begin
  if coalesce(auth.role(), '') <>
    'service_role'
  then
    raise exception
      using
        errcode = '42501',
        message = 'Service-role access is required.';
  end if;

  if p_worker_id is null
    or p_worker_id !~
      '^[A-Za-z0-9][A-Za-z0-9._:-]{2,127}$'
  then
    raise exception
      using
        errcode = '22023',
        message = 'worker_id is invalid.';
  end if;

  if p_limit not between 1 and 100 then
    raise exception
      using
        errcode = '22023',
        message = 'limit must be between 1 and 100.';
  end if;

  if p_lease_seconds not between 30 and 3600 then
    raise exception
      using
        errcode = '22023',
        message =
          'lease_seconds must be between 30 and 3600.';
  end if;

  return query
  with candidates as (
    select jobs.id
    from platform_private.jobs
    where jobs.status in (
        'queued',
        'retry_wait'
      )
      and jobs.available_at <= now()
      and jobs.attempt_count <
        jobs.max_attempts
      and jobs.locked_by is null
    order by
      jobs.priority,
      jobs.available_at,
      jobs.created_at
    for update skip locked
    limit p_limit
  ),
  claimed as (
    update platform_private.jobs
    set
      status = 'running',
      attempt_count =
        platform_private.jobs.attempt_count + 1,
      locked_by = p_worker_id,
      locked_at = now(),
      lease_expires_at =
        now() +
        make_interval(
          secs => p_lease_seconds
        ),
      started_at = coalesce(
        platform_private.jobs.started_at,
        now()
      )
    from candidates
    where platform_private.jobs.id =
      candidates.id
    returning platform_private.jobs.*
  )
  select
    claimed.id,
    claimed.command_receipt_id,
    claimed.resource_id,
    claimed.command_type,
    claimed.job_type,
    claimed.attempt_count,
    claimed.max_attempts,
    claimed.input_payload,
    claimed.lease_expires_at
  from claimed;
end
$_$;


ALTER FUNCTION "platform_private"."claim_jobs"("p_worker_id" "text", "p_limit" integer, "p_lease_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "platform_private"."claim_outbox_events"("p_dispatcher_id" "text", "p_limit" integer DEFAULT 10, "p_lease_seconds" integer DEFAULT 300) RETURNS TABLE("event_id" "uuid", "event_key" "text", "event_type" "text", "aggregate_type" "text", "aggregate_id" "uuid", "event_version" integer, "payload" "jsonb", "headers" "jsonb", "attempt_count" integer, "max_attempts" integer, "lease_expires_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'auth', 'platform_private'
    AS $_$
begin
  if coalesce(auth.role(), '') <>
    'service_role'
  then
    raise exception
      using
        errcode = '42501',
        message = 'Service-role access is required.';
  end if;

  if p_dispatcher_id is null
    or p_dispatcher_id !~
      '^[A-Za-z0-9][A-Za-z0-9._:-]{2,127}$'
  then
    raise exception
      using
        errcode = '22023',
        message = 'dispatcher_id is invalid.';
  end if;

  if p_limit not between 1 and 100 then
    raise exception
      using
        errcode = '22023',
        message = 'limit must be between 1 and 100.';
  end if;

  if p_lease_seconds not between 30 and 3600 then
    raise exception
      using
        errcode = '22023',
        message =
          'lease_seconds must be between 30 and 3600.';
  end if;

  return query
  with candidates as (
    select outbox_events.id
    from platform_private.outbox_events
    where outbox_events.status in (
        'pending',
        'retry_wait'
      )
      and outbox_events.available_at <= now()
      and outbox_events.attempt_count <
        outbox_events.max_attempts
      and outbox_events.claimed_by is null
    order by
      outbox_events.available_at,
      outbox_events.created_at
    for update skip locked
    limit p_limit
  ),
  claimed as (
    update platform_private.outbox_events
    set
      status = 'claimed',
      attempt_count =
        platform_private.outbox_events.attempt_count + 1,
      claimed_by = p_dispatcher_id,
      claimed_at = now(),
      lease_expires_at =
        now() +
        make_interval(
          secs => p_lease_seconds
        )
    from candidates
    where platform_private.outbox_events.id =
      candidates.id
    returning platform_private.outbox_events.*
  )
  select
    claimed.id,
    claimed.event_key,
    claimed.event_type,
    claimed.aggregate_type,
    claimed.aggregate_id,
    claimed.event_version,
    claimed.payload,
    claimed.headers,
    claimed.attempt_count,
    claimed.max_attempts,
    claimed.lease_expires_at
  from claimed;
end
$_$;


ALTER FUNCTION "platform_private"."claim_outbox_events"("p_dispatcher_id" "text", "p_limit" integer, "p_lease_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "platform_private"."command_actor_context"() RETURNS TABLE("actor_user_id" "uuid", "principal_key" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'auth'
    AS $$
declare
  v_actor uuid;
begin
  if coalesce(auth.role(), '') <> 'authenticated' then
    raise exception
      using
        errcode = '42501',
        message = 'An authenticated editor is required.';
  end if;

  v_actor := auth.uid();

  if v_actor is null then
    raise exception
      using
        errcode = '42501',
        message = 'An authenticated editor identity is required.';
  end if;

  return query
  select
    v_actor,
    'user:' || v_actor::text;
end;
$$;


ALTER FUNCTION "platform_private"."command_actor_context"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "platform_private"."command_request_fingerprint"("p_command_type" "text", "p_resource_id" "uuid", "p_request_payload" "jsonb") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'extensions'
    AS $$
  select encode(
    extensions.digest(
      convert_to(
        jsonb_build_object(
          'command_type', p_command_type,
          'resource_id', p_resource_id,
          'request_payload',
          p_request_payload - 'correlation_id'
        )::text,
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );
$$;


