CREATE OR REPLACE FUNCTION "platform_private"."complete_job"("p_job_id" "uuid", "p_worker_id" "text", "p_result" "jsonb" DEFAULT '{}'::"jsonb") RETURNS TABLE("command_receipt_id" "uuid", "success_event_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'auth', 'platform_private'
    AS $$
declare
  v_job platform_private.jobs%rowtype;
  v_event_id uuid;
  v_event_type text;
begin
  if coalesce(auth.role(), '') <>
    'service_role'
  then
    raise exception
      using
        errcode = '42501',
        message = 'Service-role access is required.';
  end if;

  if p_result is null
    or jsonb_typeof(p_result) <> 'object'
    or octet_length(p_result::text) > 65536
  then
    raise exception
      using
        errcode = '22023',
        message =
          'result must be a JSON object no larger than 64 KB.';
  end if;

  select jobs.*
  into v_job
  from platform_private.jobs
  where jobs.id = p_job_id
  for update;

  if not found then
    raise exception
      using
        errcode = 'P0002',
        message = 'The requested job does not exist.';
  end if;

  if v_job.status <> 'running'
    or v_job.locked_by is distinct from
      p_worker_id
    or v_job.lease_expires_at is null
    or v_job.lease_expires_at <= now()
  then
    raise exception
      using
        errcode = '55000',
        message =
          'The job is not actively leased to this worker.';
  end if;

  update platform_private.jobs
  set
    status = 'succeeded',
    result_payload = p_result,
    locked_by = null,
    locked_at = null,
    lease_expires_at = null,
    finished_at = now(),
    last_error = null
  where id = v_job.id;

  update platform_private.command_receipts
  set
    status = 'succeeded',
    result_payload = p_result,
    error_code = null,
    error_message = null,
    completed_at = now()
  where id = v_job.command_receipt_id;

  select command_types.success_event_type
  into v_event_type
  from platform_private.command_types
  where command_types.command_type =
    v_job.command_type;

  insert into platform_private.outbox_events (
    event_key,
    command_receipt_id,
    job_id,
    command_type,
    aggregate_id,
    event_type,
    payload
  )
  values (
    'command:' ||
      v_job.command_receipt_id::text ||
      ':succeeded',
    v_job.command_receipt_id,
    v_job.id,
    v_job.command_type,
    v_job.resource_id,
    v_event_type,
    jsonb_build_object(
      'command_receipt_id',
      v_job.command_receipt_id,
      'job_id',
      v_job.id,
      'resource_id',
      v_job.resource_id,
      'result',
      p_result,
      'completed_at',
      now()
    )
  )
  returning id
  into v_event_id;

  return query
  select
    v_job.command_receipt_id,
    v_event_id;
end
$$;


ALTER FUNCTION "platform_private"."complete_job"("p_job_id" "uuid", "p_worker_id" "text", "p_result" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "platform_private"."complete_resource_command"("p_command_receipt_id" "uuid", "p_result_payload" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'platform_private'
    AS $$
declare
  v_receipt platform_private.command_receipts%rowtype;
begin
  if p_result_payload is null
     or jsonb_typeof(p_result_payload) <> 'object'
     or octet_length(p_result_payload::text) > 32768
  then
    raise exception
      using errcode = '22023',
      message = 'result_payload must be a JSON object no larger than 32 KB.';
  end if;

  select receipt.*
  into v_receipt
  from platform_private.command_receipts receipt
  where receipt.id = p_command_receipt_id
  for update;

  if not found then
    raise exception
      'Command receipt does not exist.';
  end if;

  if v_receipt.status <> 'accepted' then
    raise exception
      'Only accepted command receipts may complete.';
  end if;

  update platform_private.command_receipts
  set
    status = 'succeeded',
    result_payload = p_result_payload,
    error_code = null,
    error_message = null,
    completed_at = now()
  where id = p_command_receipt_id;

  insert into platform_private.outbox_events (
    event_key,
    command_receipt_id,
    command_type,
    aggregate_id,
    event_type,
    payload
  )
  select
    'command:' ||
      v_receipt.id::text ||
      ':succeeded',
    v_receipt.id,
    command_type.command_type,
    v_receipt.resource_id,
    command_type.success_event_type,
    jsonb_build_object(
      'command_receipt_id', v_receipt.id,
      'command_type', v_receipt.command_type,
      'resource_id', v_receipt.resource_id,
      'result', p_result_payload,
      'completed_at', now()
    )
  from platform_private.command_types command_type
  where command_type.command_type =
    v_receipt.command_type;
end;
$$;


ALTER FUNCTION "platform_private"."complete_resource_command"("p_command_receipt_id" "uuid", "p_result_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "platform_private"."correction_actor_context"() RETURNS TABLE("actor_user_id" "uuid", "auth_role" "text", "principal_key" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'auth'
    AS $$
declare
  v_role text;
  v_actor uuid;
begin
  v_role := coalesce(auth.role(), '');
  v_actor := auth.uid();

  if v_role not in ('authenticated', 'service_role') then
    raise exception
      using
        errcode = '42501',
        message = 'Authentication is required.';
  end if;

  if v_actor is null then
    raise exception
      using
        errcode = '42501',
        message = 'An authenticated actor identity is required.';
  end if;

  return query
  select
    v_actor,
    v_role,
    case
      when v_role = 'service_role'
        then 'service:service_role'
      else 'user:' || v_actor::text
    end;
end;
$$;


