CREATE OR REPLACE FUNCTION "platform_private"."end_playlist_trust_copy_authorization"("p_authorization_token" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'platform_private'
    AS $$
begin
  delete from
    platform_private.playlist_trust_copy_authorizations copy_auth
  where copy_auth.authorization_token =
          p_authorization_token
    and copy_auth.backend_pid =
          pg_backend_pid()
    and copy_auth.transaction_id =
          txid_current();

  if not found then
    raise exception
      'Playlist Trust copy authorization is missing or no longer valid';
