CREATE OR REPLACE FUNCTION "platform_private"."fail_job"("p_job_id" "uuid", "p_worker_id" "text", "p_error" "text", "p_retryable" boolean DEFAULT true, "p_retry_delay_seconds" integer DEFAULT 60) RETURNS TABLE("job_status" "text", "command_receipt_status" "text", "outbox_event_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'auth', 'platform_private'
    AS $$
declare
  v_job platform_private.jobs%rowtype;
  v_terminal boolean;
  v_event_id uuid;
  v_event_type text;
  v_receipt_status text;
begin
  if coalesce(auth.role(), '') <>
    'service_role'
  then
    raise exception
      using
        errcode = '42501',
        message = 'Service-role access is required.';
  end if;

  if nullif(btrim(p_error), '') is null then
    raise exception
      using
        errcode = '22023',
        message = 'error is required.';
  end if;

  if p_retry_delay_seconds not between
    1 and 86400
  then
    raise exception
      using
        errcode = '22023',
        message =
          'retry_delay_seconds must be between 1 and 86400.';
  end if;

  select jobs.*
  into v_job
  from platform_private.jobs
  where jobs.id = p_job_id
  for update;

  if not found then
    raise exception
      using
        errcode = 'P0002',
        message = 'The requested job does not exist.';
  end if;

  if v_job.status <> 'running'
    or v_job.locked_by is distinct from
      p_worker_id
    or v_job.lease_expires_at is null
    or v_job.lease_expires_at <= now()
  then
    raise exception
      using
        errcode = '55000',
        message =
          'The job is not actively leased to this worker.';
  end if;

  v_terminal :=
    not p_retryable
    or v_job.attempt_count >=
      v_job.max_attempts;

  if v_terminal then
    update platform_private.jobs
    set
      status = 'dead_letter',
      locked_by = null,
      locked_at = null,
      lease_expires_at = null,
      finished_at = now(),
      last_error = p_error
    where id = v_job.id;

    update platform_private.command_receipts
    set
      status = 'failed',
      error_code = 'job_failed',
      error_message = p_error,
      completed_at = now()
    where id = v_job.command_receipt_id;

    v_receipt_status := 'failed';

    select command_types.failure_event_type
    into v_event_type
    from platform_private.command_types
    where command_types.command_type =
      v_job.command_type;

    insert into platform_private.outbox_events (
      event_key,
      command_receipt_id,
      job_id,
      command_type,
      aggregate_id,
      event_type,
      payload
    )
    values (
      'command:' ||
        v_job.command_receipt_id::text ||
        ':failed',
      v_job.command_receipt_id,
      v_job.id,
      v_job.command_type,
      v_job.resource_id,
      v_event_type,
      jsonb_build_object(
        'command_receipt_id',
        v_job.command_receipt_id,
        'job_id',
        v_job.id,
        'resource_id',
        v_job.resource_id,
        'error',
        p_error,
        'failed_at',
        now()
      )
    )
    returning id
    into v_event_id;

    return query
    select
      'dead_letter'::text,
      v_receipt_status,
      v_event_id;

    return;
  end if;

  update platform_private.jobs
  set
    status = 'retry_wait',
    available_at =
      now() +
      make_interval(
        secs => p_retry_delay_seconds
      ),
    locked_by = null,
    locked_at = null,
    lease_expires_at = null,
    last_error = p_error
  where id = v_job.id;

  v_receipt_status := 'accepted';

  select command_types.retry_event_type
  into v_event_type
  from platform_private.command_types
  where command_types.command_type =
    v_job.command_type;

  insert into platform_private.outbox_events (
    event_key,
    command_receipt_id,
    job_id,
    command_type,
    aggregate_id,
    event_type,
    payload
  )
  values (
    'job:' ||
      v_job.id::text ||
      ':retry:' ||
      v_job.attempt_count::text,
    v_job.command_receipt_id,
    v_job.id,
    v_job.command_type,
    v_job.resource_id,
    v_event_type,
    jsonb_build_object(
      'command_receipt_id',
      v_job.command_receipt_id,
      'job_id',
      v_job.id,
      'resource_id',
      v_job.resource_id,
      'attempt_count',
      v_job.attempt_count,
      'error',
      p_error,
      'available_at',
      now() +
      make_interval(
        secs => p_retry_delay_seconds
      )
    )
  )
  returning id
  into v_event_id;

  return query
  select
    'retry_wait'::text,
    v_receipt_status,
    v_event_id;
end
$$;


ALTER FUNCTION "platform_private"."fail_job"("p_job_id" "uuid", "p_worker_id" "text", "p_error" "text", "p_retryable" boolean, "p_retry_delay_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "platform_private"."fail_outbox_event"("p_event_id" "uuid", "p_dispatcher_id" "text", "p_error" "text", "p_retryable" boolean DEFAULT true, "p_retry_delay_seconds" integer DEFAULT 60) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'auth', 'platform_private'
    AS $$
declare
  v_event platform_private.outbox_events%rowtype;
  v_terminal boolean;
begin
  if coalesce(auth.role(), '') <>
    'service_role'
  then
    raise exception
      using
        errcode = '42501',
        message = 'Service-role access is required.';
  end if;

  if nullif(btrim(p_error), '') is null then
    raise exception
      using
        errcode = '22023',
        message = 'error is required.';
  end if;

  if p_retry_delay_seconds not between
    1 and 86400
  then
    raise exception
      using
        errcode = '22023',
        message =
          'retry_delay_seconds must be between 1 and 86400.';
  end if;

  select outbox_events.*
  into v_event
  from platform_private.outbox_events
  where outbox_events.id = p_event_id
  for update;

  if not found then
    raise exception
      using
        errcode = 'P0002',
        message = 'The requested outbox event does not exist.';
  end if;

  if v_event.status <> 'claimed'
    or v_event.claimed_by is distinct from
      p_dispatcher_id
    or v_event.lease_expires_at is null
    or v_event.lease_expires_at <= now()
  then
    raise exception
      using
        errcode = '55000',
        message =
          'The event is not actively leased to this dispatcher.';
  end if;

  v_terminal :=
    not p_retryable
    or v_event.attempt_count >=
      v_event.max_attempts;

  if v_terminal then
    update platform_private.outbox_events
    set
      status = 'dead_letter',
      claimed_by = null,
      claimed_at = null,
      lease_expires_at = null,
      last_error = p_error
    where id = v_event.id;

    return 'dead_letter';
  end if;

  update platform_private.outbox_events
  set
    status = 'retry_wait',
    available_at =
      now() +
      make_interval(
        secs => p_retry_delay_seconds
      ),
    claimed_by = null,
    claimed_at = null,
    lease_expires_at = null,
    last_error = p_error
  where id = v_event.id;

  return 'retry_wait';
end
$$;


ALTER FUNCTION "platform_private"."fail_outbox_event"("p_event_id" "uuid", "p_dispatcher_id" "text", "p_error" "text", "p_retryable" boolean, "p_retry_delay_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "platform_private"."get_correction_case_workspace_application_base"("p_case_resource_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'editorial', 'platform_private'
    AS $$
declare
  v_workspace jsonb;
  v_current_application_id uuid;
  v_applications jsonb;
begin
  v_workspace :=
    platform_private.get_correction_case_workspace_base(
      p_case_resource_id
    );

  select correction_case.current_application_id
  into v_current_application_id
  from editorial.correction_cases correction_case
  where correction_case.resource_id =
    p_case_resource_id;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id',
        application.id,
        'decision_id',
        application.decision_id,
        'command_receipt_id',
        application.command_receipt_id,
        'command_type',
        application.command_type,
        'adapter_type',
        application.adapter_type,
        'target_id',
        application.target_id,
        'target_resource_id',
        application.target_resource_id,
        'challenged_version_id',
        application.challenged_version_id,
        'expected_published_version_id',
        application.expected_published_version_id,
        'expected_working_version_id',
        application.expected_working_version_id,
        'expected_working_fingerprint',
        application.expected_working_fingerprint,
        'resulting_version_id',
        application.resulting_version_id,
        'application_summary',
        application.application_summary,
        'applied_by',
        application.applied_by,
        'correlation_id',
        application.correlation_id,
        'applied_at',
        application.applied_at,
        'is_current',
        application.id =
          v_current_application_id
      )
      order by
        application.applied_at,
        application.id
    ),
    '[]'::jsonb
  )
  into v_applications
  from editorial.correction_applications application
  where application.case_resource_id =
    p_case_resource_id;

  v_workspace := jsonb_set(
    v_workspace,
    '{case,current_application_id}',
    coalesce(
      to_jsonb(v_current_application_id),
      'null'::jsonb
    ),
    true
  );

  v_workspace := jsonb_set(
    v_workspace,
    '{applications}',
    v_applications,
    true
  );

  return v_workspace;
end;
$$;


ALTER FUNCTION "platform_private"."get_correction_case_workspace_application_base"("p_case_resource_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "platform_private"."get_correction_case_workspace_base"("p_case_resource_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'editorial', 'platform_private'
    AS $$
declare
  v_workspace jsonb;
  v_can_view_restricted_source boolean;
begin
  if p_case_resource_id is null then
    raise exception
      using
        errcode = '22023',
        message = 'case_resource_id is required.';
  end if;

  if coalesce(auth.role(), '') <> 'service_role'
     and not coalesce(
       public.current_user_is_administrator(),
       false
     )
     and not coalesce(
       public.current_user_has_capability(
         'view_corrections'
       ),
       false
     )
  then
    raise exception
      using
        errcode = '42501',
        message = 'The caller cannot view correction cases.';
  end if;

  v_can_view_restricted_source :=
    coalesce(auth.role(), '') = 'service_role'
    or coalesce(
      public.current_user_is_administrator(),
      false
    )
    or coalesce(
      public.current_user_has_capability(
        'view_trust_records'
      ),
      false
    )
    or coalesce(
      public.current_user_has_capability(
        'manage_sources'
      ),
      false
    )
    or coalesce(
      public.current_user_has_capability(
        'review_sources'
      ),
      false
    );

  select jsonb_build_object(
    'case',
    jsonb_build_object(
      'resource_id', correction_case.resource_id,
      'case_reference',
      'COR-' ||
        lpad(
          correction_case.case_number::text,
          8,
          '0'
        ),
      'origin_type', correction_case.origin_type,
      'origin_contribution_id',
      correction_case.origin_contribution_id,
      'origin_submitter_user_id',
      correction_case.origin_submitter_user_id,
      'origin_submitted_at',
      correction_case.origin_submitted_at,
      'origin_type_snapshot',
      correction_case.origin_type_snapshot,
      'origin_summary_snapshot',
      correction_case.origin_summary_snapshot,
      'correction_kind',
      correction_case.correction_kind,
      'priority', correction_case.priority,
      'case_state', correction_case.case_state,
      'current_revision',
      correction_case.current_revision,
      'assigned_investigator_id',
      correction_case.assigned_investigator_id,
      'assignment_reason',
      correction_case.assignment_reason,
      'assigned_at', correction_case.assigned_at,
      'triage_reason',
      correction_case.triage_reason,
      'triaged_by', correction_case.triaged_by,
      'triaged_at', correction_case.triaged_at,
      'investigation_summary',
      correction_case.investigation_summary,
      'investigator_recommendation',
      correction_case.investigator_recommendation,
      'evidence_ready',
      correction_case.evidence_ready,
      'submitted_for_decision_by',
      correction_case.submitted_for_decision_by,
      'submitted_for_decision_at',
      correction_case.submitted_for_decision_at,
      'current_decision_id',
      correction_case.current_decision_id,
      'closed_reason',
      correction_case.closed_reason,
      'closed_by', correction_case.closed_by,
      'closed_at', correction_case.closed_at,
      'created_by', correction_case.created_by,
      'updated_by', correction_case.updated_by,
      'created_at', correction_case.created_at,
      'updated_at', correction_case.updated_at
    ),
    'targets',
    coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'id', target.id,
            'target_resource_id',
            target.target_resource_id,
            'target_resource_kind',
            target.target_resource_kind,
            'target_version_type',
            target.target_version_type,
            'target_version_id',
            target.target_version_id,
            'target_role', target.target_role,
            'target_summary',
            target.target_summary,
            'observed_resource_revision',
            target.observed_resource_revision,
            'observed_content_fingerprint',
            target.observed_content_fingerprint,
            'created_by', target.created_by,
            'created_at', target.created_at
          )
          order by
            case
              when target.target_role = 'primary'
                then 0
              else 1
            end,
            target.created_at,
            target.id
        )
        from editorial.correction_targets target
        where target.case_resource_id =
          correction_case.resource_id
      ),
      '[]'::jsonb
    ),
    'evidence',
    coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'id', evidence.id,
            'source_id', evidence.source_id,
            'source_version_id',
            evidence.source_version_id,
            'citation_id',
            evidence.citation_id,
            'evidence_role',
            evidence.evidence_role,
            'internal_note',
            evidence.internal_note,
            'source_restricted',
            source.exposure_class in (
              'restricted',
              'confidential'
            ),
            'source_title',
            case
              when source.exposure_class in (
                'restricted',
                'confidential'
              )
              and not v_can_view_restricted_source
                then null
              else source.title
            end,
            'citation_public_label',
            case
              when source.exposure_class in (
                'restricted',
                'confidential'
              )
              and not v_can_view_restricted_source
                then null
              else citation.public_label
            end,
            'created_by', evidence.created_by,
            'created_at', evidence.created_at
          )
          order by evidence.created_at, evidence.id
        )
        from editorial.correction_evidence_links evidence
        join editorial.sources source
          on source.id = evidence.source_id
        left join editorial.citations citation
          on citation.id = evidence.citation_id
        where evidence.case_resource_id =
          correction_case.resource_id
      ),
      '[]'::jsonb
    ),
    'decisions',
    coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'id', decision.id,
            'decision_number',
            decision.decision_number,
            'outcome', decision.outcome,
            'reason', decision.reason,
            'private_analysis',
            decision.private_analysis,
            'public_safe_explanation',
            decision.public_safe_explanation,
            'case_revision_observed',
            decision.case_revision_observed,
            'target_state_observed',
            decision.target_state_observed,
            'duplicate_of_case_resource_id',
            decision.duplicate_of_case_resource_id,
            'supersedes_decision_id',
            decision.supersedes_decision_id,
            'decided_by',
            decision.decided_by,
            'correlation_id',
            decision.correlation_id,
            'created_at', decision.created_at,
            'is_current',
            decision.id =
              correction_case.current_decision_id
          )
          order by
            decision.decision_number,
            decision.id
        )
        from editorial.correction_decisions decision
        where decision.case_resource_id =
          correction_case.resource_id
      ),
      '[]'::jsonb
    ),
    'related_resource_reviews',
    coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'id', review.id,
            'related_resource_id',
            review.related_resource_id,
            'related_resource_kind',
            review.related_resource_kind,
            'review_state',
            review.review_state,
            'disposition',
            review.disposition,
            'reason', review.reason,
            'linked_correction_case_resource_id',
            review.linked_correction_case_resource_id,
            'review_revision',
            review.review_revision,
            'created_by', review.created_by,
            'updated_by', review.updated_by,
            'resolved_by', review.resolved_by,
            'resolved_at', review.resolved_at,
            'created_at', review.created_at,
            'updated_at', review.updated_at
          )
          order by review.created_at, review.id
        )
        from editorial.correction_related_resource_reviews review
        where review.case_resource_id =
          correction_case.resource_id
      ),
      '[]'::jsonb
    ),
    'events',
    coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'id', event.id,
            'event_number',
            event.event_number,
            'event_type', event.event_type,
            'case_revision_before',
            event.case_revision_before,
            'case_revision_after',
            event.case_revision_after,
            'prior_state', event.prior_state,
            'resulting_state',
            event.resulting_state,
            'actor_id', event.actor_id,
            'reason', event.reason,
            'decision_id',
            event.decision_id,
            'target_id', event.target_id,
            'evidence_link_id',
            event.evidence_link_id,
            'related_resource_review_id',
            event.related_resource_review_id,
            'command_receipt_id',
            event.command_receipt_id,
            'correlation_id',
            event.correlation_id,
            'metadata', event.metadata,
            'created_at', event.created_at
          )
          order by event.event_number
        )
        from editorial.correction_events event
        where event.case_resource_id =
          correction_case.resource_id
      ),
      '[]'::jsonb
    ),
    'command_receipts',
    coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'id', receipt.id,
            'command_type',
            receipt.command_type,
            'status', receipt.status,
            'error_code',
            receipt.error_code,
            'error_message',
            receipt.error_message,
            'accepted_at',
            receipt.accepted_at,
            'completed_at',
            receipt.completed_at
          )
          order by receipt.accepted_at, receipt.id
        )
        from platform_private.command_receipts receipt
        where receipt.resource_id =
          correction_case.resource_id
          and receipt.command_type like
            'correction.%'
      ),
      '[]'::jsonb
    )
  )
  into v_workspace
  from editorial.correction_cases correction_case
  where correction_case.resource_id =
    p_case_resource_id;

  if v_workspace is null then
    raise exception
      using
        errcode = 'P0002',
        message = 'The correction case does not exist.';
  end if;

  return v_workspace;
end;
$$;


ALTER FUNCTION "platform_private"."get_correction_case_workspace_base"("p_case_resource_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "platform_private"."get_correction_case_workspace_base"("p_case_resource_id" "uuid") IS 'Governed internal correction workspace with private and restricted evidence separation.';



CREATE OR REPLACE FUNCTION "platform_private"."guard_playlist_cover_usage_mutation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'auth', 'platform_private'
    AS $$
declare
  v_token uuid;
  v_target_id uuid;
  v_actor_id uuid;
  v_is_playlist_cover boolean;
begin
  v_is_playlist_cover :=
    (
      tg_op <> 'DELETE'
      and new.target_authority = 'editorial'
      and new.target_kind = 'playlist'
      and new.usage_role = 'playlist_cover'
    )
    or
    (
      tg_op <> 'INSERT'
      and old.target_authority = 'editorial'
      and old.target_kind = 'playlist'
      and old.usage_role = 'playlist_cover'
    );

  if not v_is_playlist_cover then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;

  v_target_id :=
    case
      when tg_op = 'DELETE' then old.target_id
      else new.target_id
    end;

  begin
    v_token :=
      nullif(
        current_setting(
          'wakilisha.playlist_cover_mutation_token',
          true
        ),
        ''
      )::uuid;
  exception
    when others then
      v_token := null;
  end;

  v_actor_id := auth.uid();

  if v_token is null
     or v_actor_id is null
     or not exists (
       select 1
       from platform_private.playlist_cover_mutation_authorizations authorization_row
       where authorization_row.token = v_token
         and authorization_row.actor_id = v_actor_id
         and authorization_row.playlist_id = v_target_id
     )
  then
    raise exception
      using
        errcode = '42501',
        message =
          'Playlist cover usage must be changed through the governed Playlist cover command.';
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "platform_private"."guard_playlist_cover_usage_mutation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "platform_private"."mark_outbox_published"("p_event_id" "uuid", "p_dispatcher_id" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'auth', 'platform_private'
    AS $$
declare
  v_event platform_private.outbox_events%rowtype;
begin
  if coalesce(auth.role(), '') <>
    'service_role'
  then
    raise exception
      using
        errcode = '42501',
        message = 'Service-role access is required.';
  end if;

  select outbox_events.*
  into v_event
  from platform_private.outbox_events
  where outbox_events.id = p_event_id
  for update;

  if not found then
    raise exception
      using
        errcode = 'P0002',
        message = 'The requested outbox event does not exist.';
  end if;

  if v_event.status <> 'claimed'
    or v_event.claimed_by is distinct from
      p_dispatcher_id
    or v_event.lease_expires_at is null
    or v_event.lease_expires_at <= now()
  then
    raise exception
      using
        errcode = '55000',
        message =
          'The event is not actively leased to this dispatcher.';
  end if;

  update platform_private.outbox_events
  set
    status = 'published',
    claimed_by = null,
    claimed_at = null,
    lease_expires_at = null,
    published_at = now(),
    last_error = null
  where id = v_event.id;

  return v_event.id;
end
$$;


ALTER FUNCTION "platform_private"."mark_outbox_published"("p_event_id" "uuid", "p_dispatcher_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "platform_private"."prevent_command_receipt_retarget"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog'
    AS $$
begin
  if new.id is distinct from old.id
    or new.command_type is distinct from old.command_type
    or new.resource_id is distinct from old.resource_id
    or new.principal_key is distinct from old.principal_key
    or new.actor_user_id is distinct from old.actor_user_id
    or new.idempotency_key is distinct from old.idempotency_key
    or new.request_fingerprint is distinct from old.request_fingerprint
    or new.request_payload is distinct from old.request_payload
    or new.accepted_at is distinct from old.accepted_at
    or new.created_at is distinct from old.created_at
  then
    raise exception
      'Command receipt identity and accepted request are immutable.';
  end if;

  return new;
end
$$;


