CREATE OR REPLACE FUNCTION "platform_private"."read_authenticated_resource_command_result"("p_command_receipt_id" "uuid", "p_idempotent_replay" boolean) RETURNS TABLE("command_receipt_id" "uuid", "receipt_status" "text", "resource_id" "uuid", "result_payload" "jsonb", "error_code" "text", "error_message" "text", "idempotent_replay" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'platform_private'
    AS $$
declare
  v_context record;
  v_receipt platform_private.command_receipts%rowtype;
begin
  select *
  into v_context
  from platform_private.command_actor_context();

  select receipt.*
  into v_receipt
  from platform_private.command_receipts receipt
  where receipt.id = p_command_receipt_id
    and receipt.principal_key = v_context.principal_key;

  if not found then
    raise exception
      using
        errcode = 'P0002',
        message = 'The command receipt does not exist for this editor.';
  end if;

  return query
  select
    v_receipt.id,
    v_receipt.status,
    v_receipt.resource_id,
    v_receipt.result_payload,
    v_receipt.error_code,
    v_receipt.error_message,
    p_idempotent_replay;
end;
$$;


ALTER FUNCTION "platform_private"."read_authenticated_resource_command_result"("p_command_receipt_id" "uuid", "p_idempotent_replay" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "platform_private"."read_correction_command_result"("p_command_receipt_id" "uuid", "p_idempotent_replay" boolean) RETURNS TABLE("command_receipt_id" "uuid", "receipt_status" "text", "case_resource_id" "uuid", "case_revision" bigint, "result_payload" "jsonb", "idempotent_replay" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'editorial', 'platform_private'
    AS $$
  select
    receipt.id,
    receipt.status,
    receipt.resource_id,
    coalesce(
      nullif(
        receipt.result_payload ->> 'case_revision',
        ''
      )::bigint,
      correction_case.current_revision
    ),
    receipt.result_payload,
    p_idempotent_replay
  from platform_private.command_receipts receipt
  left join editorial.correction_cases correction_case
    on correction_case.resource_id =
      receipt.resource_id
  where receipt.id =
    p_command_receipt_id;
$$;


ALTER FUNCTION "platform_private"."read_correction_command_result"("p_command_receipt_id" "uuid", "p_idempotent_replay" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "platform_private"."reject_resource_command"("p_command_receipt_id" "uuid", "p_error_code" "text", "p_error_message" "text", "p_result_payload" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'platform_private'
    AS $$
declare
  v_receipt platform_private.command_receipts%rowtype;
begin
  if nullif(btrim(p_error_code), '') is null
     or nullif(btrim(p_error_message), '') is null
  then
    raise exception
      using errcode = '22023',
      message = 'error_code and error_message are required.';
  end if;

  if p_result_payload is null
     or jsonb_typeof(p_result_payload) <> 'object'
     or octet_length(p_result_payload::text) > 32768
  then
    raise exception
      using errcode = '22023',
      message = 'result_payload must be a JSON object no larger than 32 KB.';
  end if;

  select receipt.*
  into v_receipt
  from platform_private.command_receipts receipt
  where receipt.id = p_command_receipt_id
  for update;

  if not found then
    raise exception
      'Command receipt does not exist.';
  end if;

  if v_receipt.status <> 'accepted' then
    raise exception
      'Only accepted command receipts may be rejected.';
  end if;

  update platform_private.command_receipts
  set
    status = 'rejected',
    result_payload = p_result_payload,
    error_code = p_error_code,
    error_message = p_error_message,
    completed_at = now()
  where id = p_command_receipt_id;

  insert into platform_private.outbox_events (
    event_key,
    command_receipt_id,
    command_type,
    aggregate_id,
    event_type,
    payload
  )
  select
    'command:' ||
      v_receipt.id::text ||
      ':failed',
    v_receipt.id,
    command_type.command_type,
    v_receipt.resource_id,
    command_type.failure_event_type,
    jsonb_build_object(
      'command_receipt_id', v_receipt.id,
      'command_type', v_receipt.command_type,
      'resource_id', v_receipt.resource_id,
      'error_code', p_error_code,
      'error_message', p_error_message,
      'result', p_result_payload,
      'completed_at', now()
    )
  from platform_private.command_types command_type
  where command_type.command_type =
    v_receipt.command_type;
end;
$$;


ALTER FUNCTION "platform_private"."reject_resource_command"("p_command_receipt_id" "uuid", "p_error_code" "text", "p_error_message" "text", "p_result_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "platform_private"."request_correction_contributor_notification"("p_case_resource_id" "uuid", "p_origin_contribution_id" "uuid", "p_contributor_user_id" "uuid", "p_current_decision_id" "uuid", "p_current_application_id" "uuid", "p_public_note_id" "uuid", "p_public_safe_outcome" "text", "p_notification_reason" "text", "p_parent_command_receipt_id" "uuid", "p_actor_id" "uuid", "p_case_revision" bigint, "p_case_state" "text", "p_correlation_id" "uuid") RETURNS TABLE("child_command_receipt_id" "uuid", "contributor_job_id" "uuid", "idempotent_replay" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'auth', 'editorial', 'platform_private', 'extensions'
    AS $$
declare
  v_case editorial.correction_cases%rowtype;
  v_begin record;
  v_request_payload jsonb;
  v_idempotency_key text;
  v_job_id uuid;
  v_target_id uuid;
begin
  if p_case_resource_id is null
     or p_origin_contribution_id is null
     or p_contributor_user_id is null
     or p_current_decision_id is null
     or p_current_application_id is null
     or p_parent_command_receipt_id is null
     or p_actor_id is null
     or p_case_revision < 1
     or p_correlation_id is null
     or nullif(
       btrim(p_public_safe_outcome),
       ''
     ) is null
     or length(p_public_safe_outcome) > 200
     or nullif(
       btrim(p_notification_reason),
       ''
     ) is null
     or length(p_notification_reason) > 2000
  then
    raise exception
      using
        errcode = '22023',
        message = 'Contributor follow-up identity, public-safe outcome, reason, revision, and correlation are required.';
  end if;

  select correction_case.*
  into v_case
  from editorial.correction_cases correction_case
  where correction_case.resource_id =
    p_case_resource_id
  for update;

  if not found
     or v_case.origin_type <>
       'community_contribution'
     or v_case.origin_contribution_id
       is distinct from
         p_origin_contribution_id
     or v_case.origin_submitter_user_id
       is distinct from
         p_contributor_user_id
     or v_case.current_decision_id
       is distinct from
         p_current_decision_id
     or v_case.current_application_id
       is distinct from
         p_current_application_id
     or v_case.current_revision <>
       p_case_revision
     or v_case.case_state <>
       p_case_state
  then
    raise exception
      'Contributor follow-up must use the exact immutable community-origin case state';
  end if;

  if not exists (
    select 1
    from platform_private.command_receipts parent_receipt
    where parent_receipt.id =
        p_parent_command_receipt_id
      and parent_receipt.resource_id =
        p_case_resource_id
      and parent_receipt.status =
        'accepted'
      and parent_receipt.command_type in (
        'correction.note.publish',
        'correction.case.close'
      )
  ) then
    raise exception
      'Contributor follow-up requires an accepted governing parent command';
  end if;

  select application.target_id
  into v_target_id
  from editorial.correction_applications application
  where application.id =
      p_current_application_id
    and application.case_resource_id =
      p_case_resource_id
    and application.decision_id =
      p_current_decision_id;

  if not found then
    raise exception
      'Contributor follow-up requires the current successful correction application';
  end if;

  v_request_payload := jsonb_build_object(
    'case_resource_id',
    p_case_resource_id,
    'origin_contribution_id',
    p_origin_contribution_id,
    'contributor_user_id',
    p_contributor_user_id,
    'current_decision_id',
    p_current_decision_id,
    'current_application_id',
    p_current_application_id,
    'public_note_id',
    p_public_note_id,
    'public_safe_outcome',
    btrim(p_public_safe_outcome),
    'notification_reason',
    btrim(p_notification_reason),
    'parent_command_receipt_id',
    p_parent_command_receipt_id,
    'correlation_id',
    p_correlation_id
  );

  v_idempotency_key :=
    'm4-follow-up:' ||
    encode(
      extensions.digest(
        convert_to(
          jsonb_build_object(
            'case_resource_id',
            p_case_resource_id,
            'origin_contribution_id',
            p_origin_contribution_id,
            'current_application_id',
            p_current_application_id,
            'public_note_id',
            p_public_note_id,
            'parent_command_receipt_id',
            p_parent_command_receipt_id
          )::text,
          'UTF8'
        ),
        'sha256'
      ),
      'hex'
    );

  select *
  into v_begin
  from platform_private.begin_resource_command(
    'correction.contributor_notification.request',
    p_case_resource_id,
    v_idempotency_key,
    v_request_payload
  );

  if v_begin.idempotent_replay then
    select job.id
    into v_job_id
    from platform_private.jobs job
    where job.command_receipt_id =
      v_begin.command_receipt_id
      and job.job_key =
        'contributor-notification';

    if not found then
      raise exception
        'Contributor follow-up receipt exists without its durable job';
    end if;

    return query
    select
      v_begin.command_receipt_id,
      v_job_id,
      true;
    return;
  end if;

  insert into platform_private.jobs (
    command_receipt_id,
    resource_id,
    command_type,
    job_key,
    job_type,
    status,
    priority,
    input_payload
  )
  values (
    v_begin.command_receipt_id,
    p_case_resource_id,
    'correction.contributor_notification.request',
    'contributor-notification',
    'correction.contributor_notification',
    'queued',
    100,
    v_request_payload
  )
  returning id
  into v_job_id;

  perform platform_private.append_correction_public_event(
    p_case_resource_id,
    'contributor_notification_requested',
    p_case_revision,
    p_case_revision,
    p_case_state,
    p_case_state,
    p_actor_id,
    btrim(p_notification_reason),
    p_current_decision_id,
    p_current_application_id,
    v_target_id,
    p_public_note_id,
    v_begin.command_receipt_id,
    p_correlation_id,
    jsonb_build_object(
      'origin_contribution_id',
      p_origin_contribution_id,
      'contributor_job_id',
      v_job_id,
      'public_safe_outcome',
      btrim(p_public_safe_outcome),
      'parent_command_receipt_id',
      p_parent_command_receipt_id
    )
  );

  return query
  select
    v_begin.command_receipt_id,
    v_job_id,
    false;
end;
$$;


ALTER FUNCTION "platform_private"."request_correction_contributor_notification"("p_case_resource_id" "uuid", "p_origin_contribution_id" "uuid", "p_contributor_user_id" "uuid", "p_current_decision_id" "uuid", "p_current_application_id" "uuid", "p_public_note_id" "uuid", "p_public_safe_outcome" "text", "p_notification_reason" "text", "p_parent_command_receipt_id" "uuid", "p_actor_id" "uuid", "p_case_revision" bigint, "p_case_state" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "platform_private"."touch_updated_at"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog'
    AS $$
begin
  new.updated_at = now();
  return new;
end
$$;


ALTER FUNCTION "platform_private"."touch_updated_at"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."community_resolve_follow_target"("p_target_type" "text", "p_target_id" "text", "p_target_slug" "text") RETURNS TABLE("canonical_type" "text", "canonical_id" "text", "canonical_slug" "text", "followable" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial', 'private'
    AS $_$
declare
  v_type text :=
    nullif(
      btrim(
        coalesce(
          p_target_type,
          ''
        )
      ),
      ''
    );
  v_id text :=
    nullif(
      btrim(
        coalesce(
          p_target_id,
          ''
        )
      ),
      ''
    );
  v_slug text :=
    nullif(
      btrim(
        coalesce(
          p_target_slug,
          ''
        )
      ),
      ''
    );
  v_person_id uuid;
  v_person record;
  v_status text;
begin
  if v_type not in (
    'person',
    'artist',
    'genre',
    'label',
    'chart_program'
  ) then
    raise exception
      'Unsupported Follow target type'
      using errcode = '22023';
  end if;

  if v_id is null then
    raise exception
      'Stable Follow target identity is required'
      using errcode = '22023';
  end if;

  canonical_type :=
    v_type;

  if v_type = 'person' then
    begin
      v_person_id :=
        v_id::uuid;
    exception
      when invalid_text_representation then
        raise exception
          'Person Follow target must be a UUID'
          using errcode = '22023';
    end;

    select *
    into v_person
    from editorial.resolve_person_follow_target(
      v_person_id
    );

    canonical_id :=
      v_person.person_resource_id::text;

    canonical_slug :=
      case
        when v_person.canonical_path
               ~ '^/people/[^/]+$'
          then split_part(
            v_person.canonical_path,
            '/',
            3
          )
        else null
      end;

    followable :=
      coalesce(
        v_person.followable,
        false
      );

    return next;
    return;
  end if;

  if v_type = 'artist' then
    select
      artist.id::text,
      artist.slug,
      artist.status
    into
      canonical_id,
      canonical_slug,
      v_status
    from public.registry_artists artist
    where artist.id::text =
          v_id
    limit 1;

    if canonical_id is null then
      select
        resolved.canonical_artist_id::text,
        resolved.canonical_slug,
        'active'::text
      into
        canonical_id,
        canonical_slug,
        v_status
      from public.registry_resolve_artist_slug_for_public(
        coalesce(
          v_slug,
          v_id
        )
      ) resolved
      limit 1;
    end if;

    if canonical_id is null then
      raise exception
        'Artist Follow target does not exist'
        using errcode = 'P0002';
    end if;

    followable :=
      v_status = 'active';

    return next;
    return;
  end if;

  if v_type = 'genre' then
    select
      genre.id::text,
      genre.slug,
      genre.status
    into
      canonical_id,
      canonical_slug,
      v_status
    from public.registry_genres genre
    where genre.id::text =
          v_id
       or lower(
            genre.slug
          ) =
          lower(
            coalesce(
              v_slug,
              v_id
            )
          )
    order by
      case
        when genre.id::text =
             v_id
          then 0
        else 1
      end
    limit 1;

    if canonical_id is null then
      raise exception
        'Genre Follow target does not exist'
        using errcode = 'P0002';
    end if;

    followable :=
      v_status = 'active';

    return next;
    return;
  end if;

  if v_type = 'label' then
    select
      label.id::text,
      label.slug,
      label.status
    into
      canonical_id,
      canonical_slug,
      v_status
    from public.registry_labels label
    where label.id::text =
          v_id
       or lower(
            label.slug
          ) =
          lower(
            coalesce(
              v_slug,
              v_id
            )
          )
    order by
      case
        when label.id::text =
             v_id
          then 0
        else 1
      end
    limit 1;

    if canonical_id is null then
      raise exception
        'Label Follow target does not exist'
        using errcode = 'P0002';
    end if;

    followable :=
      v_status = 'active';

    return next;
    return;
  end if;

  select
    program.id,
    program.public_slug
  into
    canonical_id,
    canonical_slug
  from public.wk_chart_programs_v2 program
  where program.id =
        v_id
     or lower(
          program.public_slug
        ) =
        lower(
          coalesce(
            v_slug,
            v_id
          )
        )
  order by
    case
      when program.id =
           v_id
        then 0
      else 1
    end
  limit 1;

  if canonical_id is null then
    raise exception
      'Chart programme Follow target does not exist'
      using errcode = 'P0002';
  end if;

  followable :=
    true;

  return next;
end;
$_$;


ALTER FUNCTION "private"."community_resolve_follow_target"("p_target_type" "text", "p_target_id" "text", "p_target_slug" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."community_resolve_save_target"("p_entity_type" "text", "p_entity_id" "text", "p_entity_slug" "text", "p_entity_url" "text") RETURNS TABLE("canonical_type" "text", "canonical_id" "text", "canonical_slug" "text", "canonical_url" "text", "saveable" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial', 'private'
    AS $$
declare
  v_type text :=
    nullif(
      btrim(
        coalesce(
          p_entity_type,
          ''
        )
      ),
      ''
    );
  v_id text :=
    nullif(
      btrim(
        coalesce(
          p_entity_id,
          ''
        )
      ),
      ''
    );
  v_slug text :=
    nullif(
      btrim(
        coalesce(
          p_entity_slug,
          ''
        )
      ),
      ''
    );
  v_url text :=
    nullif(
      btrim(
        coalesce(
          p_entity_url,
          ''
        )
      ),
      ''
    );
  v_status text;
  v_visibility text;
  v_lifecycle text;
  v_published_version uuid;
  v_primary_artist_slug text;
  v_primary_artist_count integer;
begin
  if v_type not in (
    'article',
    'playlist',
    'track',
    'release',
    'chart_edition'
  ) then
    raise exception
      'Unsupported Save entity type'
      using errcode = '22023';
  end if;

  canonical_type :=
    v_type;

  if v_type = 'article' then
    select
      article.id::text,
      article.slug,
      coalesce(
        alias.path,
        '/magazine/' || article.slug
      ),
      resource.visibility,
      resource.lifecycle_state,
      resource.current_published_version_id
    into
      canonical_id,
      canonical_slug,
      canonical_url,
      v_visibility,
      v_lifecycle,
      v_published_version
    from editorial.article_resources
      article_resource
    join public.wk_articles article
      on article.id =
         article_resource.article_id
    join editorial.resources resource
      on resource.id =
         article_resource.resource_id
     and resource.resource_kind =
         'article'
    left join lateral (
      select
        resource_alias.path
      from editorial.resource_aliases
        resource_alias
      where resource_alias.resource_id =
            article_resource.resource_id
        and resource_alias.is_canonical
        and resource_alias.retired_at
            is null
      order by
        resource_alias.created_at,
        resource_alias.path
      limit 1
    ) alias
      on true
    where article.id::text =
          v_id
       or article_resource.resource_id::text =
          v_id
       or lower(
            article.slug
          ) =
          lower(
            coalesce(
              v_slug,
              v_id
            )
          )
    order by
      case
        when article.id::text =
             v_id
          then 0
        when article_resource.resource_id::text =
             v_id
          then 1
        else 2
      end
    limit 1;

    if canonical_id is null then
      raise exception
        'Article Save target does not exist'
        using errcode = 'P0002';
    end if;

    saveable :=
      (
        v_visibility = 'public'
        and v_lifecycle = 'published'
        and v_published_version is not null
      );

    return next;
    return;
  end if;

  if v_type = 'playlist' then
    select
      playlist.id::text,
      playlist.slug,
      coalesce(
        alias.path,
        '/playlists/' || playlist.slug
      ),
      resource.visibility,
      resource.lifecycle_state,
      playlist_resource.current_published_version_id
    into
      canonical_id,
      canonical_slug,
      canonical_url,
      v_visibility,
      v_lifecycle,
      v_published_version
    from editorial.playlist_resources
      playlist_resource
    join public.wk_playlists playlist
      on playlist.id =
         playlist_resource.playlist_id
    join editorial.resources resource
      on resource.id =
         playlist_resource.resource_id
     and resource.resource_kind =
         'playlist'
    left join lateral (
      select
        resource_alias.path
      from editorial.resource_aliases
        resource_alias
      where resource_alias.resource_id =
            playlist_resource.resource_id
        and resource_alias.is_canonical
        and resource_alias.retired_at
            is null
      order by
        resource_alias.created_at,
        resource_alias.path
      limit 1
    ) alias
      on true
    where playlist.id::text =
          v_id
       or playlist_resource.resource_id::text =
          v_id
       or lower(
            playlist.slug
          ) =
          lower(
            coalesce(
              v_slug,
              v_id
            )
          )
    order by
      case
        when playlist.id::text =
             v_id
          then 0
        when playlist_resource.resource_id::text =
             v_id
          then 1
        else 2
      end
    limit 1;

    if canonical_id is null then
      raise exception
        'Playlist Save target does not exist'
        using errcode = 'P0002';
    end if;

    saveable :=
      (
        v_visibility = 'public'
        and v_lifecycle = 'published'
        and v_published_version is not null
      );

    return next;
    return;
  end if;

  if v_type = 'track' then
    -- Track Saveability mirrors the public Track read contract. The public
    -- gateway intentionally serves Registry Tracks and Track/Artist links in
    -- active, needs_review, or draft state. Stable Registry UUID remains the
    -- only accepted identity; artist-scoped route is derived server-side.
    select
      track.id::text,
      track.slug,
      case
        when primary_artist.routable_primary_count = 1
         and track.slug is not null
          then '/tracks/'
               || primary_artist.artist_slug
               || '/'
               || track.slug
        else null
      end,
      track.status,
      primary_artist.artist_slug,
      primary_artist.routable_primary_count
    into
      canonical_id,
      canonical_slug,
      canonical_url,
      v_status,
      v_primary_artist_slug,
      v_primary_artist_count
    from public.registry_tracks track
    left join lateral (
      select
        count(*)::integer as routable_primary_count,
        min(link.artist_slug) as artist_slug
      from public.registry_track_artists link
      where link.track_id = track.id
        and link.status in (
          'active',
          'needs_review',
          'draft'
        )
        and link.is_primary is true
        and nullif(
              btrim(
                coalesce(
                  link.artist_slug,
                  ''
                )
              ),
              ''
            ) is not null
    ) primary_artist
      on true
    where track.id::text =
          v_id
    limit 1;

    if canonical_id is null then
      raise exception
        'Track Save target requires stable Registry Track identity'
        using errcode = 'P0002';
    end if;

    saveable :=
      (
        v_status in (
          'active',
          'needs_review',
          'draft'
        )
        and canonical_slug is not null
        and v_primary_artist_count = 1
        and v_primary_artist_slug is not null
        and canonical_url is not null
      );

    return next;
    return;
  end if;

  if v_type = 'release' then
    -- Release Saveability mirrors the public Release read contract: active
    -- Artist links may expose active or draft Registry Releases publicly.
    select
      release.id::text,
      release.slug,
      case
        when primary_artist.active_primary_count = 1
         and release.slug is not null
          then '/releases/'
               || primary_artist.artist_slug
               || '/'
               || release.slug
        else null
      end,
      release.status,
      primary_artist.artist_slug,
      primary_artist.active_primary_count
    into
      canonical_id,
      canonical_slug,
      canonical_url,
      v_status,
      v_primary_artist_slug,
      v_primary_artist_count
    from public.registry_releases release
    left join lateral (
      select
        count(*)::integer as active_primary_count,
        min(link.artist_slug) as artist_slug
      from public.registry_release_artists link
      where link.release_id = release.id
        and link.status = 'active'
        and link.is_primary is true
        and nullif(
              btrim(
                coalesce(
                  link.artist_slug,
                  ''
                )
              ),
              ''
            ) is not null
    ) primary_artist
      on true
    where release.id::text =
          v_id
    limit 1;

    if canonical_id is null then
      raise exception
        'Release Save target requires stable Registry Release identity'
        using errcode = 'P0002';
    end if;

    saveable :=
      (
        v_status in (
          'active',
          'draft'
        )
        and canonical_slug is not null
        and v_primary_artist_count = 1
        and v_primary_artist_slug is not null
        and canonical_url is not null
      );

    return next;
    return;
  end if;

  select
    edition.id,
    edition.edition_slug,
    '/charts/'
      || program.public_slug
      || '/'
      || edition.edition_slug,
    edition.status
  into
    canonical_id,
    canonical_slug,
    canonical_url,
    v_status
  from public.wk_chart_editions_v2 edition
  join public.wk_chart_programs_v2 program
    on program.id =
       edition.program_id
  where edition.id =
        v_id
  limit 1;

  if canonical_id is null then
    raise exception
      'Chart edition Save target does not exist'
      using errcode = 'P0002';
  end if;

  saveable :=
    v_status = 'published';

  return next;
end;
$$;


ALTER FUNCTION "private"."community_resolve_save_target"("p_entity_type" "text", "p_entity_id" "text", "p_entity_slug" "text", "p_entity_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."accept_article_suggestion"("p_suggestion_id" "uuid", "p_expected_draft_version" bigint, "p_note" "text" DEFAULT NULL::"text") RETURNS TABLE("suggestion_id" "uuid", "decision_status" "text", "article_id" "uuid", "article_slug" "text", "draft_version" bigint, "applied_version_id" "uuid", "applied_version_number" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_suggestion editorial.article_suggestions%rowtype;
  v_thread editorial.article_review_threads%rowtype;
  v_resource editorial.resources%rowtype;
  v_article public.wk_articles%rowtype;
  v_target editorial.article_versions%rowtype;

  v_new_version_id uuid;
  v_new_version_number bigint;
  v_decided_at timestamptz := now();
  v_prior_status text;

  v_stale record;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  if not editorial.current_user_can_review_article() then
    raise exception 'Permission denied';
  end if;

  select suggestion.*
  into v_suggestion
  from editorial.article_suggestions suggestion
  where suggestion.id = p_suggestion_id
  for update;

  if not found then
    raise exception 'Article suggestion not found';
  end if;

  if v_suggestion.status <> 'open' then
    raise exception 'Only open suggestions can be accepted';
  end if;

  select thread.*
  into v_thread
  from editorial.article_review_threads thread
  where thread.id = v_suggestion.thread_id
  for update;

  select resource.*
  into v_resource
  from editorial.resources resource
  where resource.id = v_thread.resource_id
  for update;

  select article.*
  into v_article
  from public.wk_articles article
  where article.id = v_thread.article_id
  for update;

  select version.*
  into v_target
  from editorial.article_versions version
  where version.id = v_thread.target_version_id;

  if not found then
    raise exception 'Suggestion target version not found';
  end if;

  if v_resource.current_submitted_version_id
       is distinct from v_thread.target_version_id
     or v_article.wp_status <> 'pending'
     or v_target.content_fingerprint
       <> v_suggestion.target_version_fingerprint
  then
    update editorial.article_suggestions
    set
      status = 'stale',
      decided_by = auth.uid(),
      decided_at = v_decided_at,
      decision_note =
        'Suggestion no longer targets the active submitted version'
    where id = p_suggestion_id;

    update editorial.article_review_threads
    set
      status = 'resolved',
      resolved_by = auth.uid(),
      resolved_at = v_decided_at
    where id = v_thread.id;

    insert into editorial.article_suggestion_events (
      suggestion_id,
      action,
      note
    )
    values (
      p_suggestion_id,
      'marked_stale',
      'Suggestion no longer targets the active submitted version'
    );

    suggestion_id := p_suggestion_id;
    decision_status := 'stale';
    article_id := v_article.id;
    article_slug := v_article.slug;
    draft_version := v_article.draft_version;
    applied_version_id := null;
    applied_version_number := null;
    return next;
    return;
  end if;

  v_prior_status := v_article.wp_status;

  select
    persisted.version_id,
    persisted.version_number
  into
    v_new_version_id,
    v_new_version_number
  from editorial.apply_article_review_snapshot(
    v_article.id,
    v_resource.id,
    p_expected_draft_version,
    v_suggestion.proposed_content_html
  ) persisted;

  select article.*
  into v_article
  from public.wk_articles article
  where article.id = v_thread.article_id;

  update editorial.article_suggestions
  set
    status = 'accepted',
    decided_by = auth.uid(),
    decided_at = v_decided_at,
    decision_note = nullif(btrim(coalesce(p_note, '')), ''),
    applied_version_id = v_new_version_id
  where id = p_suggestion_id;

  update editorial.article_review_threads
  set
    status = 'resolved',
    resolved_by = auth.uid(),
    resolved_at = v_decided_at
  where id = v_thread.id;

  insert into editorial.article_suggestion_events (
    suggestion_id,
    action,
    note,
    applied_version_id
  )
  values (
    p_suggestion_id,
    'accepted',
    nullif(btrim(coalesce(p_note, '')), ''),
    v_new_version_id
  );

  insert into editorial.article_lifecycle_events (
    resource_id,
    article_id,
    version_id,
    action,
    prior_status,
    resulting_status,
    note,
    metadata
  )
  values (
    v_resource.id,
    v_article.id,
    v_thread.target_version_id,
    'changes_requested',
    v_prior_status,
    'draft',
    coalesce(
      nullif(btrim(coalesce(p_note, '')), ''),
      'Accepted editorial suggestion'
    ),
    jsonb_build_object(
      'suggestion_id',
      p_suggestion_id,
      'applied_version_id',
      v_new_version_id,
      'decision',
      'accepted',
      'review_round_closed',
      true,
      'remaining_open_suggestions_marked_stale',
      true
    )
  );

  -- Quality PR 2 deliberately accepts at most one
  -- suggestion from a submitted review round. Every suggestion stores
  -- a complete proposed document snapshot. Remaining suggestions cannot
  -- be silently rebased after the Article returns to draft.
  for v_stale in
    update editorial.article_suggestions suggestion
    set
      status = 'stale',
      decided_by = auth.uid(),
      decided_at = v_decided_at,
      decision_note =
        'Review round closed after another suggestion was accepted; resubmission is required before reconsideration'
    from editorial.article_review_threads competing_thread
    where competing_thread.id = suggestion.thread_id
      and competing_thread.target_version_id =
        v_thread.target_version_id
      and suggestion.id <> p_suggestion_id
      and suggestion.status = 'open'
    returning
      suggestion.id,
      suggestion.thread_id
  loop
    update editorial.article_review_threads
    set
      status = 'resolved',
      resolved_by = auth.uid(),
      resolved_at = v_decided_at
    where id = v_stale.thread_id;

    insert into editorial.article_suggestion_events (
      suggestion_id,
      action,
      note
    )
    values (
      v_stale.id,
      'marked_stale',
      'Review round closed after another suggestion was accepted; resubmission is required before reconsideration'
    );
  end loop;

  suggestion_id := p_suggestion_id;
  decision_status := 'accepted';
  article_id := v_article.id;
  article_slug := v_article.slug;
  draft_version := v_article.draft_version;
  applied_version_id := v_new_version_id;
  applied_version_number := v_new_version_number;
  return next;
end;
$$;


ALTER FUNCTION "public"."accept_article_suggestion"("p_suggestion_id" "uuid", "p_expected_draft_version" bigint, "p_note" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."accept_article_suggestion"("p_suggestion_id" "uuid", "p_expected_draft_version" bigint, "p_note" "text") IS 'Applies one open suggestion as a durable review_applied Article version, closes the submitted review round, and returns the Article to draft work.';



CREATE OR REPLACE FUNCTION "public"."accept_registry_missing_artist_intake"("p_submission_id" "uuid", "p_review_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare s public.contributor_submissions; slug text; artist_id uuid; src_count int:=0; tgt_count int:=0; r record;
begin
if not (auth.role()='service_role' or public.current_user_has_capability('manage_registry') or public.current_user_has_capability('manage_review_queue') or public.current_user_is_administrator()) then raise exception 'You do not have permission to accept Registry artist intake submissions.'; end if;
if nullif(btrim(p_review_reason),'') is null then raise exception 'A review reason is required.'; end if;
select * into s from public.contributor_submissions where id=p_submission_id for update;
if not found then raise exception 'Contributor submission not found.'; end if;
if s.submission_type<>'context_note' then raise exception 'This submission is not a missing-artist intake record.'; end if;
slug:=substring(s.source_note from '^missing_artist_slug:([^[:space:]]+)');
if nullif(slug,'') is null then raise exception 'The submission does not contain a missing artist slug.'; end if;
if s.review_status not in ('submitted','triaged','needs_source','needs_clarification') then raise exception 'This intake submission is not in an acceptable review state.'; end if;
if not exists(select 1 from public.registry_relationship_endpoint_work_queue q where q.endpoint_work_state='missing_entity' and q.missing_entity_type='artist' and q.legacy_slug=slug) then raise exception 'This artist is no longer required by the missing endpoint queue.'; end if;
if exists(select 1 from public.registry_artists a where lower(a.slug)=lower(slug)) then raise exception 'A Registry artist already exists for this slug.'; end if;
insert into public.registry_artists(slug,display_name,normalized_name,sort_name,artist_type,status,metadata)
values(slug,btrim(s.title),lower(regexp_replace(btrim(s.title),'\s+',' ','g')),btrim(s.title),'unknown','needs_review',jsonb_build_object('created_from','missing_artist_intake','source_submission_id',s.id::text,'source_url',s.source_url,'intake_reason',s.body,'acceptance_reason',btrim(p_review_reason),'created_at',now())) returning id into artist_id;
update public.registry_artist_aliases set canonical_artist_id=artist_id,alias_display_name=btrim(s.title),confidence=100,source='manual_intake',notes=btrim(p_review_reason),status='active' where lower(alias_slug)=lower(slug);
if not found then insert into public.registry_artist_aliases(alias_slug,canonical_artist_id,alias_display_name,confidence,source,notes,status) values(slug,artist_id,btrim(s.title),100,'manual_intake',btrim(p_review_reason),'active'); end if;
for r in select id from public.registry_entity_relationships where relationship_status<>'archived' and source_entity_id is null and source_entity_type='artist' and source_slug=slug loop perform public.resolve_registry_relationship_endpoint(r.id,'source','artist',artist_id,btrim(p_review_reason)); src_count:=src_count+1; end loop;
for r in select id from public.registry_entity_relationships where relationship_status<>'archived' and target_entity_id is null and target_entity_type='artist' and target_slug=slug loop perform public.resolve_registry_relationship_endpoint(r.id,'target','artist',artist_id,btrim(p_review_reason)); tgt_count:=tgt_count+1; end loop;
update public.contributor_submissions set entity_id=artist_id,review_status='merged',reviewed_by=auth.uid(),reviewed_at=now(),review_note=btrim(p_review_reason),updated_at=now() where id=p_submission_id;
insert into public.review_decisions(subject_type,subject_id,decision,reason,reviewer_id) values('contributor_submission',p_submission_id,'approved',btrim(p_review_reason),auth.uid());
return jsonb_build_object('submissionId',p_submission_id,'artistId',artist_id,'artistSlug',slug,'artistStatus','needs_review','sourceEndpointsResolved',src_count,'targetEndpointsResolved',tgt_count,'relationshipsResolved',src_count+tgt_count,'publicSafe',false);
end;$$;


ALTER FUNCTION "public"."accept_registry_missing_artist_intake"("p_submission_id" "uuid", "p_review_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."accept_registry_missing_artist_intake"("p_submission_id" "uuid", "p_review_reason" "text") IS 'Accepts one reviewed missing-artist intake, creates a needs-review Registry artist, resolves exact legacy relationship endpoints, and keeps all affected relationships non-public.';



CREATE OR REPLACE FUNCTION "public"."activate_media_variant"("p_asset_revision_id" "uuid", "p_variant_role" "text", "p_variant_id" "uuid", "p_expected_selection_revision" bigint, "p_reason" "text", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("variant_id" "uuid", "selection_revision" bigint, "correlation_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'media', 'auth'
    AS $$
declare
  v_actor_id uuid;
  v_asset_id uuid;
  v_existing media.variant_selections%rowtype;
  v_new_revision bigint;
  v_correlation_id uuid := coalesce(
    p_correlation_id,
    gen_random_uuid()
  );
begin
  v_actor_id :=
    media.require_command_actor('manage_media_assets');

  if nullif(btrim(p_reason), '') is null then
    raise exception 'Media variant activation reason is required';
  end if;

  select variant.asset_id
  into v_asset_id
  from media.variants variant
  join media.file_objects file_object
    on file_object.id = variant.derived_file_object_id
  where variant.id = p_variant_id
    and variant.asset_revision_id = p_asset_revision_id
    and variant.variant_role = p_variant_role
    and file_object.verification_state = 'verified';

  if not found then
    raise exception
      'Media variant does not match revision, role, and verified delivery';
  end if;

  select *
  into v_existing
  from media.variant_selections
  where asset_revision_id = p_asset_revision_id
    and variant_role = p_variant_role
  for update;

  if found then
    if v_existing.selection_revision <>
       p_expected_selection_revision
    then
      raise exception
        'Stale Media selection revision: expected %, current %',
        p_expected_selection_revision,
        v_existing.selection_revision;
    end if;

    update media.variant_selections as selection_row
    set
      variant_id = p_variant_id,
      selection_revision =
        selection_row.selection_revision + 1,
      selected_by = v_actor_id,
      selected_at = now(),
      updated_at = now()
    where selection_row.asset_revision_id =
        p_asset_revision_id
      and selection_row.variant_role = p_variant_role
    returning selection_row.selection_revision
    into v_new_revision;
  else
    if p_expected_selection_revision <> 0 then
      raise exception
        'First Media variant activation expects selection revision 0';
    end if;

    insert into media.variant_selections (
      asset_revision_id,
      variant_role,
      variant_id,
      selection_revision,
      selected_by
    )
    values (
      p_asset_revision_id,
      p_variant_role,
      p_variant_id,
      1,
      v_actor_id
    );

    v_new_revision := 1;
  end if;

  insert into media.events (
    asset_id,
    asset_revision_id,
    variant_id,
    event_type,
    actor_id,
    reason,
    prior_state,
    resulting_state,
    correlation_id
  )
  values (
    v_asset_id,
    p_asset_revision_id,
    p_variant_id,
    'variant_activated',
    v_actor_id,
    btrim(p_reason),
    case
      when v_existing.variant_id is null
        then null
      else jsonb_build_object(
        'variant_id', v_existing.variant_id,
        'selection_revision',
          v_existing.selection_revision
      )
    end,
    jsonb_build_object(
      'variant_id', p_variant_id,
      'selection_revision', v_new_revision
    ),
    v_correlation_id
  );

  return query
  select
    p_variant_id,
    v_new_revision,
    v_correlation_id;
end;
$$;


ALTER FUNCTION "public"."activate_media_variant"("p_asset_revision_id" "uuid", "p_variant_role" "text", "p_variant_id" "uuid", "p_expected_selection_revision" bigint, "p_reason" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_article_review_comment"("p_thread_id" "uuid", "p_body_text" "text") RETURNS TABLE("created_comment_id" "uuid", "thread_id" "uuid", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_thread editorial.article_review_threads%rowtype;
  v_comment_id uuid;
  v_created_at timestamptz;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  if nullif(btrim(coalesce(p_body_text, '')), '') is null then
    raise exception 'Comment cannot be blank';
  end if;

  select thread.*
  into v_thread
  from editorial.article_review_threads thread
  where thread.id = p_thread_id;

  if not found then
    raise exception 'Article review thread not found';
  end if;

  if not editorial.current_user_can_participate_article_review(
    v_thread.resource_id
  ) then
    raise exception 'Permission denied';
  end if;

  if v_thread.status <> 'open' then
    raise exception 'Resolved review threads cannot receive comments';
  end if;

  insert into editorial.article_review_comments (
    thread_id,
    body_text
  )
  values (
    p_thread_id,
    btrim(p_body_text)
  )
  returning
    id,
    article_review_comments.created_at
  into
    v_comment_id,
    v_created_at;

  created_comment_id := v_comment_id;
  thread_id := p_thread_id;
  created_at := v_created_at;
  return next;
end;
$$;


ALTER FUNCTION "public"."add_article_review_comment"("p_thread_id" "uuid", "p_body_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_playlist_item"("p_playlist_id" "uuid", "p_expected_authority_revision" bigint, "p_idempotency_key" "text", "p_registry_track_id" "uuid" DEFAULT NULL::"uuid", "p_provider_key" "text" DEFAULT NULL::"text", "p_provider_track_id" "text" DEFAULT NULL::"text", "p_provider_url" "text" DEFAULT NULL::"text", "p_title" "text" DEFAULT NULL::"text", "p_artist_names" "text"[] DEFAULT '{}'::"text"[], "p_release_title" "text" DEFAULT NULL::"text", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("command_receipt_id" "uuid", "receipt_status" "text", "playlist_id" "uuid", "resource_id" "uuid", "playlist_item_id" "uuid", "authority_revision" bigint, "result_payload" "jsonb", "idempotent_replay" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'editorial', 'platform_private'
    AS $_$
declare
  v_playlist public.wk_playlists%rowtype;
  v_playlist_resource editorial.resources%rowtype;
  v_resource_id uuid;
  v_item_id uuid;
  v_position integer;
  v_provider_key text := nullif(btrim(lower(p_provider_key)), '');
  v_provider_track_id text := nullif(btrim(p_provider_track_id), '');
  v_provider_url text := nullif(btrim(p_provider_url), '');
  v_registry_track_id uuid := p_registry_track_id;
  v_registry_release_id uuid;
  v_title text := nullif(btrim(p_title), '');
  v_artist_names text[] := coalesce(p_artist_names, '{}'::text[]);
  v_release_title text := nullif(btrim(p_release_title), '');
  v_artwork_url text;
  v_preview_url text;
  v_duration_ms integer;
  v_isrc text;
  v_match_status text;
  v_match_confidence numeric(5,4);
  v_normalization jsonb := '{}'::jsonb;
  v_provider_link public.registry_track_provider_links%rowtype;
  v_duplicate_ids uuid[];
  v_begin record;
  v_read record;
  v_request jsonb;
  v_result jsonb;
  v_correlation_id uuid := coalesce(p_correlation_id, gen_random_uuid());
begin
  if p_playlist_id is null
     or p_expected_authority_revision is null
     or p_expected_authority_revision < 1
  then
    raise exception
      using errcode = '22023', message = 'Playlist and expected authority revision are required.';
  end if;

  if (v_provider_key is null) <> (v_provider_track_id is null) then
    raise exception
      using errcode = '22023', message = 'Provider key and provider track identity must be supplied together.';
  end if;

  if v_provider_key is not null
     and v_provider_key !~ '^[a-z0-9_]+$'
  then
    raise exception
      using errcode = '22023', message = 'Provider key is invalid.';
  end if;

  if v_registry_track_id is null
     and v_provider_key is null
     and (
       v_title is null
       or cardinality(v_artist_names) = 0
       or nullif(btrim(coalesce(v_artist_names[1], '')), '') is null
     )
  then
    raise exception
      using
        errcode = '22023',
        message = 'A Registry track, provider identity, or external title and artist are required.';
  end if;

  select playlist.*
  into v_playlist
  from public.wk_playlists playlist
  where playlist.id = p_playlist_id
  for update of playlist;

  select binding.resource_id
  into v_resource_id
  from editorial.playlist_resources binding
  where binding.playlist_id = p_playlist_id;

  if not found then
    raise exception
      using errcode = 'P0002', message = 'Playlist does not exist.';
  end if;

  select resource_row.*
  into v_playlist_resource
  from editorial.resources resource_row
  where resource_row.id = v_resource_id;

  if not editorial.current_user_can_edit_playlist(v_resource_id) then
    raise exception
      using errcode = '42501', message = 'Playlist edit permission is required.';
  end if;

  v_request := jsonb_build_object(
    'playlist_id', p_playlist_id,
    'expected_authority_revision', p_expected_authority_revision,
    'registry_track_id', p_registry_track_id,
    'provider_key', v_provider_key,
    'provider_track_id', v_provider_track_id,
    'provider_url', v_provider_url,
    'title', v_title,
    'artist_names', to_jsonb(v_artist_names),
    'release_title', v_release_title,
    'correlation_id', v_correlation_id
  );

  select *
  into v_begin
  from platform_private.begin_authenticated_resource_command(
    'playlist.item.add',
    v_resource_id,
    p_idempotency_key,
    v_request
  );

  if v_begin.idempotent_replay then
    select *
    into v_read
    from platform_private.read_authenticated_resource_command_result(
      v_begin.command_receipt_id,
      true
    );

    command_receipt_id := v_read.command_receipt_id;
    receipt_status := v_read.receipt_status;
    playlist_id := p_playlist_id;
    resource_id := v_read.resource_id;
    playlist_item_id := nullif(
      v_read.result_payload ->> 'playlist_item_id',
      ''
    )::uuid;
    authority_revision := nullif(
      v_read.result_payload ->> 'authority_revision',
      ''
    )::bigint;
    result_payload := v_read.result_payload;
    idempotent_replay := true;
    return next;
    return;
  end if;

  if v_playlist.authority_revision <> p_expected_authority_revision then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'playlist_revision_changed',
      'The Playlist changed before this track could be added.',
      jsonb_build_object(
        'playlist_id', p_playlist_id,
        'authority_revision', v_playlist.authority_revision
      )
    );
  else
    if v_provider_key is not null then
      select provider_link.*
      into v_provider_link
      from public.registry_track_provider_links provider_link
      where provider_link.provider_key = v_provider_key
        and provider_link.provider_track_id = v_provider_track_id;

      if found then
        if p_registry_track_id is not null
           and v_provider_link.match_status = 'matched'
           and v_provider_link.track_id <> p_registry_track_id
        then
          raise exception
            using
              errcode = '22023',
              message = 'Provider identity is matched to a different Registry track.';
        end if;

        if p_registry_track_id is null
           and v_provider_link.match_status = 'matched'
        then
          v_registry_track_id := v_provider_link.track_id;
        elsif p_registry_track_id is null
              and v_provider_link.match_status = 'needs_review'
        then
          v_normalization := jsonb_build_object(
            'suggested_registry_track_id', v_provider_link.track_id,
            'provider_match_status', v_provider_link.match_status,
            'provider_match_method', v_provider_link.match_method
          );
        end if;

        v_match_confidence := v_provider_link.match_confidence;
        v_preview_url := v_provider_link.preview_url;
        v_artwork_url := v_provider_link.artwork_url;
        v_duration_ms := v_provider_link.duration_ms;
        v_isrc := v_provider_link.isrc;
      end if;
    end if;

    if v_registry_track_id is not null then
      select
        track.title,
        track.release_id,
        release.title,
        coalesce(track.artwork_url, v_artwork_url),
        coalesce(track.preview_url, v_preview_url),
        coalesce(track.duration_ms, v_duration_ms),
        coalesce(track.isrc, v_isrc),
        coalesce(
          array_agg(
            coalesce(artist.display_name, link.artist_name_text)
            order by link.credit_order, link.id
          ) filter (
            where coalesce(artist.display_name, link.artist_name_text) is not null
          ),
          '{}'::text[]
        )
      into
        v_title,
        v_registry_release_id,
        v_release_title,
        v_artwork_url,
        v_preview_url,
        v_duration_ms,
        v_isrc,
        v_artist_names
      from public.registry_tracks track
      left join public.registry_releases release
        on release.id = track.release_id
      left join public.registry_track_artists link
        on link.track_id = track.id
        and link.status = 'active'
      left join public.registry_artists artist
        on artist.id = link.artist_id
      where track.id = v_registry_track_id
        and track.status = 'active'
      group by
        track.id,
        track.title,
        track.release_id,
        release.title,
        track.artwork_url,
        track.preview_url,
        track.duration_ms,
        track.isrc;

      if not found then
        perform platform_private.reject_resource_command(
          v_begin.command_receipt_id,
          'registry_track_unavailable',
          'The selected Registry track is not active.',
          jsonb_build_object(
            'playlist_id', p_playlist_id,
            'authority_revision', v_playlist.authority_revision
          )
        );
      else
        v_match_status := 'matched';
        v_match_confidence := coalesce(v_match_confidence, 1.0000);
      end if;
    elsif v_provider_key is not null then
      if v_normalization ? 'suggested_registry_track_id' then
        v_match_status := 'needs_review';
      else
        v_match_status := 'pending';
      end if;
    else
      v_match_status := 'external_only';
    end if;

    if v_begin.command_receipt_id is not null
       and exists (
         select 1
         from platform_private.command_receipts receipt
         where receipt.id = v_begin.command_receipt_id
           and receipt.status = 'accepted'
       )
    then
      select coalesce(max(item.position), 0) + 1
      into v_position
      from public.wk_playlist_items item
      where item.playlist_id = p_playlist_id
        and item.lifecycle_state = 'active';

      v_item_id := gen_random_uuid();

      insert into editorial.resources (
        id,
        resource_kind,
        owner_id,
        visibility,
        lifecycle_state,
        created_by
      )
      values (
        v_item_id,
        'playlist_item',
        v_playlist_resource.owner_id,
        'internal',
        'active',
        auth.uid()
      );

      insert into public.wk_playlist_items (
        id,
        playlist_id,
        position,
        registry_track_id,
        registry_release_id,
        provider_key,
        provider_track_id,
        provider_url,
        title,
        artist_names,
        release_title,
        artwork_url,
        preview_url,
        duration_ms,
        isrc,
        match_status,
        match_confidence,
        normalization_payload,
        notes,
        created_by,
        lifecycle_state
      )
      values (
        v_item_id,
        p_playlist_id,
        v_position,
        v_registry_track_id,
        v_registry_release_id,
        v_provider_key,
        v_provider_track_id,
        v_provider_url,
        v_title,
        v_artist_names,
        v_release_title,
        v_artwork_url,
        v_preview_url,
        v_duration_ms,
        v_isrc,
        v_match_status,
        v_match_confidence,
        v_normalization,
        null,
        auth.uid(),
        'active'
      );

      insert into editorial.playlist_item_resources (
        resource_id,
        resource_kind,
        playlist_item_id
      )
      values (
        v_item_id,
        'playlist_item',
        v_item_id
      );

      v_duplicate_ids := editorial.playlist_duplicate_item_ids(
        p_playlist_id,
        v_item_id,
        v_registry_track_id,
        v_provider_key,
        v_provider_track_id,
        v_title,
        v_artist_names
      );

      update public.wk_playlists playlist
      set authority_revision = playlist.authority_revision + 1
      where playlist.id = p_playlist_id
      returning playlist.authority_revision
      into v_playlist.authority_revision;

      v_result := jsonb_build_object(
        'playlist_id', p_playlist_id,
        'resource_id', v_resource_id,
        'playlist_item_id', v_item_id,
        'playlist_item_resource_id', v_item_id,
        'position', v_position,
        'match_status', v_match_status,
        'registry_track_id', v_registry_track_id,
        'duplicate_warning', cardinality(v_duplicate_ids) > 0,
        'duplicate_item_ids', to_jsonb(v_duplicate_ids),
        'authority_revision', v_playlist.authority_revision,
        'correlation_id', v_correlation_id
      );

      perform platform_private.complete_resource_command(
        v_begin.command_receipt_id,
        v_result
      );
    end if;
  end if;

  select *
  into v_read
  from platform_private.read_authenticated_resource_command_result(
    v_begin.command_receipt_id,
    false
  );

  command_receipt_id := v_read.command_receipt_id;
  receipt_status := v_read.receipt_status;
  playlist_id := p_playlist_id;
  resource_id := v_read.resource_id;
  playlist_item_id := nullif(
    v_read.result_payload ->> 'playlist_item_id',
    ''
  )::uuid;
  authority_revision := nullif(
    v_read.result_payload ->> 'authority_revision',
    ''
  )::bigint;
  result_payload := v_read.result_payload;
  idempotent_replay := false;
  return next;
end;
$_$;


ALTER FUNCTION "public"."add_playlist_item"("p_playlist_id" "uuid", "p_expected_authority_revision" bigint, "p_idempotency_key" "text", "p_registry_track_id" "uuid", "p_provider_key" "text", "p_provider_track_id" "text", "p_provider_url" "text", "p_title" "text", "p_artist_names" "text"[], "p_release_title" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_playlist_registry_track_with_intake_slots"("p_playlist_id" "uuid", "p_expected_authority_revision" bigint, "p_registry_track_id" "uuid", "p_idempotency_key" "text", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_added record;
  v_item_id uuid;
  v_position integer;
  v_payload jsonb;
  v_marker text;
begin
  select *
  into v_added
  from public.add_playlist_item(
    p_playlist_id => p_playlist_id,
    p_expected_authority_revision =>
      p_expected_authority_revision,
    p_idempotency_key => p_idempotency_key,
    p_registry_track_id => p_registry_track_id,
    p_correlation_id => p_correlation_id
  );

  v_item_id := v_added.playlist_item_id;
  v_payload := coalesce(
    v_added.result_payload,
    '{}'::jsonb
  );

  if v_added.receipt_status = 'succeeded'
     and v_item_id is not null
  then
    select
      item.normalization_payload
        ->> 'playlist_position_authority'
    into v_marker
    from public.wk_playlist_items item
    where item.id = v_item_id;

    if coalesce(v_marker, '') <>
       'registry_intake_slots'
    then
      v_position :=
        editorial.next_playlist_position_with_registry_intake(
          p_playlist_id,
          v_item_id
        );

      update public.wk_playlist_items item
      set
        position = v_position,
        normalization_payload =
          coalesce(
            item.normalization_payload,
            '{}'::jsonb
          )
          || jsonb_build_object(
            'playlist_position_authority',
            'registry_intake_slots'
          )
      where item.id = v_item_id;
    else
      select item.position
      into v_position
      from public.wk_playlist_items item
      where item.id = v_item_id;
    end if;
  end if;

  return jsonb_build_object(
    'command_receipt_id', v_added.command_receipt_id,
    'receipt_status', v_added.receipt_status,
    'playlist_id', p_playlist_id,
    'playlist_item_id', v_item_id,
    'authority_revision', v_added.authority_revision,
    'result_payload',
      v_payload
      || jsonb_build_object(
        'position', v_position
      )
  );
end;
$$;


ALTER FUNCTION "public"."add_playlist_registry_track_with_intake_slots"("p_playlist_id" "uuid", "p_expected_authority_revision" bigint, "p_registry_track_id" "uuid", "p_idempotency_key" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_playlist_validated_provider_track"("p_playlist_id" "uuid", "p_expected_authority_revision" bigint, "p_registry_track_id" "uuid", "p_validation_id" "uuid", "p_idempotency_key" "text", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'auth', 'public', 'editorial', 'platform_private'
    AS $$
declare
  v_validation platform_private.playlist_playback_validations%rowtype;
  v_added record;
  v_item public.wk_playlist_items%rowtype;
  v_correlation_id uuid := coalesce(
    p_correlation_id,
    gen_random_uuid()
  );
begin
  if auth.uid() is null then
    raise exception
      using errcode = '42501', message = 'Authentication is required.';
  end if;

  if not public.current_user_can_edit_playlist_id(p_playlist_id) then
    raise exception
      using errcode = '42501', message = 'Playlist edit permission is required.';
  end if;

  select validation.*
  into v_validation
  from platform_private.playlist_playback_validations validation
  where validation.id = p_validation_id
    and validation.requested_by = auth.uid()
    and validation.playlist_id = p_playlist_id
    and validation.playable
    and validation.validation_status = 'playable'
    and validation.expires_at > now();

  if not found then
    raise exception
      using
        errcode = '22023',
        message =
          'Playback validation is missing, expired, or not playable. Check the link again.';
  end if;

  if not exists (
    select 1
    from public.registry_tracks track
    where track.id = p_registry_track_id
      and track.status = 'active'
  ) then
    raise exception
      using
        errcode = '22023',
        message = 'Select an active Music Registry track.';
  end if;

  select *
  into v_added
  from public.add_playlist_item(
    p_playlist_id => p_playlist_id,
    p_expected_authority_revision => p_expected_authority_revision,
    p_idempotency_key => p_idempotency_key,
    p_registry_track_id => p_registry_track_id,
    p_provider_key => v_validation.provider_key,
    p_provider_track_id => v_validation.provider_object_id,
    p_provider_url => v_validation.canonical_url,
    p_title => null,
    p_artist_names => '{}'::text[],
    p_release_title => null,
    p_correlation_id => v_correlation_id
  );

  if v_added.playlist_item_id is not null then
    update public.wk_playlist_items item
    set
      normalization_payload =
        coalesce(item.normalization_payload, '{}'::jsonb)
        || jsonb_build_object(
          'playback',
          jsonb_build_object(
            'validation_id', v_validation.id,
            'validation_status', 'playable',
            'playback_kind', v_validation.playback_kind,
            'provider_key', v_validation.provider_key,
            'provider_object_id', v_validation.provider_object_id,
            'provider_url', v_validation.canonical_url,
            'embed_url', v_validation.embed_url,
            'preview_url', v_validation.preview_url,
            'validated_at', v_validation.checked_at,
            'validation_expires_at', v_validation.expires_at
          )
        ),
      artwork_url = coalesce(item.artwork_url, v_validation.artwork_url)
    where item.id = v_added.playlist_item_id
    returning item.*
    into v_item;

    if not exists (
      select 1
      from public.registry_provider_track_suggestions suggestion
      where suggestion.canonical_track_id = p_registry_track_id
        and suggestion.provider_key = v_validation.provider_key
        and suggestion.provider_object_id = v_validation.provider_object_id
        and suggestion.status = 'needs_review'
    ) then
      insert into public.registry_provider_track_suggestions (
        source_playlist_id,
        source_playlist_item_id,
        requested_by,
        canonical_track_id,
        artist_resolution_mode,
        provider_key,
        provider_object_id,
        provider_url,
        provider_title,
        provider_artist_names,
        provider_release_title,
        playback_kind,
        validation_snapshot,
        status
      )
      values (
        p_playlist_id,
        v_added.playlist_item_id,
        auth.uid(),
        p_registry_track_id,
        'existing_track',
        v_validation.provider_key,
        v_validation.provider_object_id,
        v_validation.canonical_url,
        v_validation.title_hint,
        v_validation.artist_names_hint,
        v_validation.release_title_hint,
        v_validation.playback_kind,
        jsonb_build_object(
          'validation_id', v_validation.id,
          'embed_url', v_validation.embed_url,
          'preview_url', v_validation.preview_url,
          'artwork_url', v_validation.artwork_url,
          'provider_metadata', v_validation.provider_metadata,
          'checked_at', v_validation.checked_at
        ),
        'needs_review'
      );
    end if;
  end if;

  return jsonb_build_object(
    'command_receipt_id', v_added.command_receipt_id,
    'receipt_status', v_added.receipt_status,
    'playlist_id', p_playlist_id,
    'playlist_item_id', v_added.playlist_item_id,
    'authority_revision', v_added.authority_revision,
    'duplicate_warning',
      coalesce(
        (v_added.result_payload ->> 'duplicate_warning')::boolean,
        false
      ),
    'duplicate_item_ids',
      coalesce(
        v_added.result_payload -> 'duplicate_item_ids',
        '[]'::jsonb
      ),
    'playback_kind', v_validation.playback_kind,
    'validation_id', v_validation.id
  );
end;
$$;


ALTER FUNCTION "public"."add_playlist_validated_provider_track"("p_playlist_id" "uuid", "p_expected_authority_revision" bigint, "p_registry_track_id" "uuid", "p_validation_id" "uuid", "p_idempotency_key" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


