ALTER FUNCTION "public"."add_playlist_validated_provider_track_with_intake_slots"("p_playlist_id" "uuid", "p_expected_authority_revision" bigint, "p_registry_track_id" "uuid", "p_validation_id" "uuid", "p_idempotency_key" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_publishing_item_assignee"("p_item_id" "uuid", "p_expected_record_version" bigint, "p_user_id" "uuid", "p_assignment_role" "text", "p_note" "text" DEFAULT NULL::"text") RETURNS TABLE("item_id" "uuid", "record_version" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial', 'auth'
    AS $$
declare
  v_item editorial.publishing_items%rowtype;
  v_updated editorial.publishing_items%rowtype;
begin
  if auth.uid() is null
     or not editorial.current_user_can_manage_publishing()
  then
    raise exception
      using
        errcode = '42501',
        message = 'Permission denied';
  end if;

  select item.*
  into v_item
  from editorial.publishing_items item
  where item.id = p_item_id
  for update;

  if not found then
    raise exception 'Publishing item not found';
  end if;

  if v_item.record_version
     <> p_expected_record_version
  then
    raise exception
      'STALE_PUBLISHING_ITEM_VERSION: expected %, current %',
      p_expected_record_version,
      v_item.record_version;
  end if;

  if not exists (
    select 1
    from auth.users target_user
    where target_user.id = p_user_id
  ) then
    raise exception 'Publishing assignee does not exist';
  end if;

  if exists (
    select 1
    from editorial.publishing_item_assignees assignee
    where assignee.item_id = p_item_id
      and assignee.user_id = p_user_id
      and assignee.assignment_role =
        p_assignment_role
  ) then
    raise exception
      'Publishing assignment already exists';
  end if;

  insert into editorial.publishing_item_assignees (
    item_id,
    user_id,
    assignment_role,
    assigned_by
  )
  values (
    p_item_id,
    p_user_id,
    p_assignment_role,
    auth.uid()
  );

  update editorial.publishing_items item
  set
    record_version = item.record_version + 1,
    updated_by = auth.uid(),
    updated_at = now()
  where item.id = p_item_id
  returning item.*
  into v_updated;

  insert into editorial.publishing_item_events (
    item_id,
    action,
    prior_record_version,
    resulting_record_version,
    prior_values,
    resulting_values,
    note,
    metadata,
    actor_id
  )
  values (
    p_item_id,
    'assignee_added',
    v_item.record_version,
    v_updated.record_version,
    editorial.publishing_item_snapshot(v_item),
    editorial.publishing_item_snapshot(v_updated),
    nullif(btrim(p_note), ''),
    jsonb_build_object(
      'userId',
      p_user_id,
      'assignmentRole',
      p_assignment_role
    ),
    auth.uid()
  );

  item_id := v_updated.id;
  record_version := v_updated.record_version;
  return next;
end;
$$;


ALTER FUNCTION "public"."add_publishing_item_assignee"("p_item_id" "uuid", "p_expected_record_version" bigint, "p_user_id" "uuid", "p_assignment_role" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_publishing_item_channel"("p_item_id" "uuid", "p_expected_record_version" bigint, "p_channel_key" "text", "p_is_primary" boolean DEFAULT false, "p_note" "text" DEFAULT NULL::"text") RETURNS TABLE("item_id" "uuid", "record_version" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_item editorial.publishing_items%rowtype;
  v_updated editorial.publishing_items%rowtype;
begin
  if auth.uid() is null
     or not editorial.current_user_can_manage_publishing()
  then
    raise exception
      using
        errcode = '42501',
        message = 'Permission denied';
  end if;

  select item.*
  into v_item
  from editorial.publishing_items item
  where item.id = p_item_id
  for update;

  if not found then
    raise exception 'Publishing item not found';
  end if;

  if v_item.record_version
     <> p_expected_record_version
  then
    raise exception
      'STALE_PUBLISHING_ITEM_VERSION: expected %, current %',
      p_expected_record_version,
      v_item.record_version;
  end if;

  if not exists (
    select 1
    from editorial.publishing_channels channel
    where channel.channel_key = p_channel_key
      and channel.enabled = true
  ) then
    raise exception
      'Publishing channel is missing or disabled';
  end if;

  if exists (
    select 1
    from editorial.publishing_item_channels item_channel
    where item_channel.item_id = p_item_id
      and item_channel.channel_key = p_channel_key
  ) then
    raise exception
      'Publishing channel is already attached';
  end if;

  if p_is_primary then
    update editorial.publishing_item_channels
      as item_channel
    set is_primary = false
    where item_channel.item_id = p_item_id
      and item_channel.is_primary = true;
  end if;

  insert into editorial.publishing_item_channels (
    item_id,
    channel_key,
    is_primary,
    created_by
  )
  values (
    p_item_id,
    p_channel_key,
    p_is_primary,
    auth.uid()
  );

  update editorial.publishing_items item
  set
    record_version =
      item.record_version + 1,
    updated_by = auth.uid(),
    updated_at = now()
  where item.id = p_item_id
  returning item.*
  into v_updated;

  insert into editorial.publishing_item_events (
    item_id,
    action,
    prior_record_version,
    resulting_record_version,
    prior_values,
    resulting_values,
    note,
    metadata,
    actor_id
  )
  values (
    p_item_id,
    'channel_added',
    v_item.record_version,
    v_updated.record_version,
    editorial.publishing_item_snapshot(
      v_item
    ),
    editorial.publishing_item_snapshot(
      v_updated
    ),
    nullif(btrim(p_note), ''),
    jsonb_build_object(
      'channelKey',
      p_channel_key,
      'isPrimary',
      p_is_primary
    ),
    auth.uid()
  );

  item_id := v_updated.id;
  record_version :=
    v_updated.record_version;

  return next;
end;
$$;


ALTER FUNCTION "public"."add_publishing_item_channel"("p_item_id" "uuid", "p_expected_record_version" bigint, "p_channel_key" "text", "p_is_primary" boolean, "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_related_resource_review"("p_case_resource_id" "uuid", "p_expected_case_revision" bigint, "p_related_resource_id" "uuid", "p_reason" "text", "p_idempotency_key" "text", "p_correlation_id" "uuid") RETURNS TABLE("command_receipt_id" "uuid", "receipt_status" "text", "case_resource_id" "uuid", "case_revision" bigint, "result_payload" "jsonb", "idempotent_replay" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'editorial', 'platform_private'
    AS $$
declare
  v_actor uuid;
  v_begin record;
  v_case editorial.correction_cases%rowtype;
  v_related_kind text;
  v_review_id uuid;
  v_result jsonb;
begin
  v_actor :=
    platform_private.assert_correction_capability(
      'investigate_corrections'
    );

  if p_case_resource_id is null
     or p_expected_case_revision < 1
     or p_related_resource_id is null
     or p_correlation_id is null
     or nullif(btrim(p_reason), '') is null
  then
    raise exception
      using errcode = '22023',
      message = 'Case, revision, related resource, reason, and correlation identity are required.';
  end if;

  select resource.resource_kind
  into v_related_kind
  from editorial.resources resource
  where resource.id = p_related_resource_id;

  if not found then
    raise exception
      using errcode = 'P0002',
      message = 'The related resource does not exist.';
  end if;

  select *
  into v_begin
  from platform_private.begin_resource_command(
    'correction.related_resource.add',
    p_case_resource_id,
    p_idempotency_key,
    jsonb_build_object(
      'expected_case_revision', p_expected_case_revision,
      'related_resource_id', p_related_resource_id,
      'related_resource_kind', v_related_kind,
      'reason', btrim(p_reason),
      'correlation_id', p_correlation_id
    )
  );

  if v_begin.idempotent_replay then
    return query
    select *
    from platform_private.read_correction_command_result(
      v_begin.command_receipt_id,
      true
    );
    return;
  end if;

  select correction_case.*
  into v_case
  from editorial.correction_cases correction_case
  where correction_case.resource_id =
    p_case_resource_id
  for update;

  if not found then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'case_not_found',
      'The correction case does not exist.',
      jsonb_build_object('case_revision', null)
    );
  elsif v_case.current_revision <>
        p_expected_case_revision
  then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'case_revision_changed',
      'The correction case revision changed.',
      jsonb_build_object(
        'case_revision', v_case.current_revision,
        'case_state', v_case.case_state
      )
    );
  elsif v_case.case_state not in (
    'investigating',
    'awaiting_decision',
    'decided'
  ) then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'invalid_transition',
      'Related-resource reviews require an active investigated case.',
      jsonb_build_object(
        'case_revision', v_case.current_revision,
        'case_state', v_case.case_state
      )
    );
  elsif p_related_resource_id =
        p_case_resource_id
  then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'invalid_related_resource',
      'A correction case cannot be its own related resource.',
      jsonb_build_object(
        'case_revision', v_case.current_revision,
        'case_state', v_case.case_state
      )
    );
  else
    insert into editorial.correction_related_resource_reviews (
      case_resource_id,
      related_resource_id,
      related_resource_kind,
      created_by,
      updated_by
    )
    values (
      p_case_resource_id,
      p_related_resource_id,
      v_related_kind,
      v_actor,
      v_actor
    )
    returning id
    into v_review_id;

    update editorial.correction_cases
    set
      current_revision =
        v_case.current_revision + 1,
      updated_by = v_actor,
      updated_at = now()
    where resource_id = p_case_resource_id;

    perform platform_private.append_correction_event(
      p_case_resource_id,
      'related_resource_added',
      v_case.current_revision,
      v_case.current_revision + 1,
      v_case.case_state,
      v_case.case_state,
      v_actor,
      btrim(p_reason),
      null,
      null,
      null,
      v_review_id,
      v_begin.command_receipt_id,
      p_correlation_id,
      jsonb_build_object(
        'related_resource_review_id',
        v_review_id,
        'related_resource_id',
        p_related_resource_id,
        'related_resource_kind',
        v_related_kind
      )
    );

    v_result := jsonb_build_object(
      'case_resource_id', p_case_resource_id,
      'case_revision', v_case.current_revision + 1,
      'case_state', v_case.case_state,
      'related_resource_review_id',
      v_review_id,
      'review_revision', 1
    );

    perform platform_private.complete_resource_command(
      v_begin.command_receipt_id,
      v_result
    );
  end if;

  return query
  select *
  from platform_private.read_correction_command_result(
    v_begin.command_receipt_id,
    false
  );
end;
$$;


ALTER FUNCTION "public"."add_related_resource_review"("p_case_resource_id" "uuid", "p_expected_case_revision" bigint, "p_related_resource_id" "uuid", "p_reason" "text", "p_idempotency_key" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_apply_artist_decouple_decision"("p_decision_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_decision record;
  v_selected_count integer := 0;
  v_result jsonb;
begin
  if not coalesce(public.current_user_has_capability('manage_registry'), false) then
    raise exception 'insufficient_privilege';
  end if;

  if p_decision_id is null then
    raise exception 'decision_id_required';
  end if;

  select *
  into v_decision
  from public.registry_artist_decouple_decisions
  where id = p_decision_id
  for update;

  if v_decision.id is null then
    raise exception 'decouple_decision_not_found';
  end if;

  if v_decision.decision_status = 'applied' then
    return coalesce(v_decision.apply_result_json, '{}'::jsonb);
  end if;

  if v_decision.decision_status <> 'ready' then
    raise exception 'decouple_decision_not_ready';
  end if;

  if v_decision.decision_type not in ('split_combined_artist', 'split_raw_credit') then
    raise exception 'decouple_decision_type_not_applyable';
  end if;

  if v_decision.source_artist_id is null then
    raise exception 'source_artist_required';
  end if;

  if jsonb_typeof(coalesce(v_decision.selected_artists, '[]'::jsonb)) <> 'array' then
    raise exception 'selected_artists_must_be_array';
  end if;

  select count(*)
  into v_selected_count
  from jsonb_array_elements(coalesce(v_decision.selected_artists, '[]'::jsonb)) item(value)
  where nullif(item.value ->> 'artist_id', '') is not null;

  if v_selected_count < 2 then
    raise exception 'at_least_two_selected_artists_required';
  end if;

  v_result := public.admin_decouple_registry_artist(
    v_decision.source_artist_id,
    v_decision.selected_artists,
    v_decision.note,
    true,
    v_decision.chart_primary_artist_id
  );

  update public.registry_artist_decouple_decisions
  set
    decision_status = 'applied',
    applied_at = now(),
    apply_result_json = v_result,
    updated_at = now()
  where id = v_decision.id;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."admin_apply_artist_decouple_decision"("p_decision_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_apply_chart_artist_resolution_decision"("p_decision_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_decision record;
  v_entry record;
  v_primary_artist record;
  v_selected_count integer := 0;
  v_track_inserted integer := 0;
  v_track_existing integer := 0;
  v_result jsonb;
begin
  if not (
    coalesce(public.current_user_has_capability('manage_charts'), false)
    or coalesce(public.current_user_has_capability('manage_registry'), false)
    or coalesce(public.current_user_is_administrator(), false)
  ) then
    raise exception 'insufficient_privilege';
  end if;

  select *
  into v_decision
  from public.chart_artist_resolution_decisions
  where id = p_decision_id
  limit 1;

  if v_decision.id is null then
    raise exception 'decision_not_found';
  end if;

  select *
  into v_entry
  from public.wk_chart_entries_v2
  where id::text = v_decision.chart_entry_id
  limit 1;

  if v_entry.id is null then
    raise exception 'chart_entry_not_found';
  end if;

  if v_decision.decision_status = 'resolved' then
    return coalesce(v_decision.apply_result_json, jsonb_build_object(
      'decisionId', v_decision.id,
      'alreadyResolved', true
    ));
  end if;

  if v_decision.decision_type = 'accepted_as_group' then
    v_result := jsonb_build_object(
      'decisionId', v_decision.id,
      'chartEntryId', v_decision.chart_entry_id,
      'decisionType', v_decision.decision_type,
      'trackCreditsInserted', 0,
      'trackCreditsExisting', 0,
      'message', 'Accepted as group/collab. No registry credits were changed.'
    );

    update public.chart_artist_resolution_decisions
    set
      decision_status = 'resolved',
      applied_at = now(),
      apply_result_json = v_result,
      updated_at = now()
    where id = v_decision.id;

    return v_result;
  end if;

  if v_decision.decision_type not in ('split_plan', 'alias_plan') then
    raise exception 'decision_type_not_applyable';
  end if;

  if jsonb_typeof(coalesce(v_decision.selected_artists, 'null'::jsonb)) <> 'array'
     or jsonb_array_length(v_decision.selected_artists) = 0 then
    raise exception 'selected_artists_required';
  end if;

  if v_entry.canonical_track_id is null or btrim(v_entry.canonical_track_id::text) = '' then
    raise exception 'canonical_track_required';
  end if;

  create temporary table if not exists pg_temp.chart_artist_resolution_selected_artists (
    artist_id uuid primary key,
    role text not null,
    credit_order integer not null,
    display_credit text
  ) on commit drop;

  truncate table pg_temp.chart_artist_resolution_selected_artists;

  insert into pg_temp.chart_artist_resolution_selected_artists (
    artist_id,
    role,
    credit_order,
    display_credit
  )
  select distinct on ((item.value->>'artist_id')::uuid)
    (item.value->>'artist_id')::uuid,
    coalesce(nullif(item.value->>'role', ''), case when item.ordinality = 1 then 'primary_artist' else 'featured_artist' end),
    coalesce(nullif(item.value->>'credit_order', '')::integer, item.ordinality::integer),
    nullif(item.value->>'display_name', '')
  from jsonb_array_elements(v_decision.selected_artists) with ordinality as item(value, ordinality)
  where nullif(item.value->>'artist_id', '') is not null
  order by (item.value->>'artist_id')::uuid, item.ordinality;

  select count(*)
  into v_selected_count
  from pg_temp.chart_artist_resolution_selected_artists;

  if v_selected_count = 0 then
    raise exception 'selected_artists_required';
  end if;

  if exists (
    select 1
    from pg_temp.chart_artist_resolution_selected_artists s
    left join public.registry_artists a
      on a.id = s.artist_id
     and a.status in ('active', 'draft', 'needs_review', 'archived')
    where a.id is null
  ) then
    raise exception 'selected_artist_not_found';
  end if;

  if exists (
    select 1
    from pg_temp.chart_artist_resolution_selected_artists s
    where s.role not in ('primary_artist', 'featured_artist', 'collaborator', 'producer', 'composer', 'remixer', 'group_member', 'unknown')
  ) then
    raise exception 'invalid_artist_role';
  end if;

  select a.id, a.slug, a.display_name
  into v_primary_artist
  from pg_temp.chart_artist_resolution_selected_artists s
  join public.registry_artists a on a.id = s.artist_id
  order by
    case when s.role = 'primary_artist' then 0 else 1 end,
    s.credit_order asc,
    a.display_name asc
  limit 1;

  select count(*)
  into v_track_existing
  from pg_temp.chart_artist_resolution_selected_artists s
  join public.registry_track_artists rta
    on rta.track_id = v_entry.canonical_track_id::uuid
   and rta.artist_id = s.artist_id
   and coalesce(rta.status, 'active') <> 'archived';

  with selected as (
    select
      s.artist_id,
      s.role,
      s.credit_order,
      s.display_credit,
      a.slug,
      a.display_name
    from pg_temp.chart_artist_resolution_selected_artists s
    join public.registry_artists a on a.id = s.artist_id
  ),
  inserted as (
    insert into public.registry_track_artists (
      track_id,
      artist_id,
      artist_slug,
      artist_name_text,
      role,
      is_primary,
      is_featured,
      credit_order,
      display_credit,
      source,
      confidence,
      status,
      metadata,
      created_at,
      updated_at
    )
    select
      v_entry.canonical_track_id::uuid,
      selected.artist_id,
      selected.slug,
      selected.display_name,
      selected.role,
      selected.role = 'primary_artist' or selected.credit_order = 1,
      selected.role = 'featured_artist' or selected.credit_order > 1,
      selected.credit_order,
      coalesce(selected.display_credit, selected.display_name),
      'chart_artist_resolution',
      100,
      'active',
      jsonb_build_object(
        'chart_artist_resolution_decision_id', v_decision.id::text,
        'chart_entry_id', v_decision.chart_entry_id,
        'edition_id', v_decision.edition_id,
        'raw_artist_name', v_decision.raw_artist_name,
        'decision_type', v_decision.decision_type,
        'applied_at', now()
      ),
      now(),
      now()
    from selected
    where not exists (
      select 1
      from public.registry_track_artists existing
      where existing.track_id = v_entry.canonical_track_id::uuid
        and existing.artist_id = selected.artist_id
        and coalesce(existing.status, 'active') <> 'archived'
    )
    returning id
  )
  select count(*)
  into v_track_inserted
  from inserted;

  update public.wk_chart_entries_v2
  set
    canonical_artist_id = v_primary_artist.id::text,
    artist_slug = coalesce(nullif(artist_slug, ''), v_primary_artist.slug),
    updated_at = now()
  where id = v_entry.id;

  v_result := jsonb_build_object(
    'decisionId', v_decision.id,
    'chartEntryId', v_decision.chart_entry_id,
    'trackId', v_entry.canonical_track_id,
    'primaryArtistId', v_primary_artist.id,
    'primaryArtistSlug', v_primary_artist.slug,
    'selectedArtistCount', v_selected_count,
    'trackCreditsInserted', v_track_inserted,
    'trackCreditsExisting', v_track_existing,
    'decisionType', v_decision.decision_type,
    'message', 'Resolution decision applied to registry track credits.'
  );

  update public.chart_artist_resolution_decisions
  set
    decision_status = 'resolved',
    applied_at = now(),
    apply_result_json = v_result,
    updated_at = now()
  where id = v_decision.id;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."admin_apply_chart_artist_resolution_decision"("p_decision_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_apply_registry_track_duplicate_repair"("p_canonical_track_id" "uuid", "p_duplicate_track_ids" "uuid"[], "p_note" "text" DEFAULT NULL::"text", "p_allow_medium_confidence" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_duplicate_ids uuid[];
  v_canonical record;
  v_preview jsonb;
  v_confidence_bucket text;
  v_blocker_count integer := 0;
  v_chart_rows integer := 0;
  v_provider_rows integer := 0;
  v_release_rows_archived integer := 0;
  v_release_rows_moved integer := 0;
  v_track_artist_rows_archived integer := 0;
  v_track_artist_rows_moved integer := 0;
  v_tracks_archived integer := 0;
  v_event_id uuid;
  v_result jsonb;
begin
  if not coalesce(public.current_user_has_capability('manage_registry'), false) then
    raise exception 'insufficient_privilege';
  end if;

  v_duplicate_ids := array(
    select distinct x
    from unnest(coalesce(p_duplicate_track_ids, '{}'::uuid[])) as x
    where x is not null
      and x <> p_canonical_track_id
  );

  select id, slug, title, status
  into v_canonical
  from public.registry_tracks
  where id = p_canonical_track_id
    and status in ('active', 'draft', 'needs_review')
  limit 1;

  if v_canonical.id is null then
    raise exception 'canonical_track_not_found_or_not_repairable';
  end if;

  v_preview := public.admin_preview_registry_track_duplicate_repair(
    p_canonical_track_id,
    v_duplicate_ids
  );

  v_confidence_bucket := coalesce(v_preview->>'confidenceBucket', 'blocked');

  select jsonb_array_length(coalesce(v_preview->'blockers', '[]'::jsonb))
  into v_blocker_count;

  if v_blocker_count > 0 or v_confidence_bucket = 'blocked' then
    raise exception 'repair_blocked: %', coalesce(v_preview->'blockers', '[]'::jsonb)::text;
  end if;

  if v_confidence_bucket = 'medium' and not coalesce(p_allow_medium_confidence, false) then
    raise exception 'medium_confidence_requires_explicit_allow';
  end if;

  update public.wk_chart_entries_v2 ce
  set
    canonical_track_id = v_canonical.id::text,
    track_slug = v_canonical.slug,
    updated_at = now()
  from public.registry_tracks d
  where d.id = any(v_duplicate_ids)
    and (
      ce.canonical_track_id::text = d.id::text
      or ce.track_slug = d.slug
    );

  get diagnostics v_chart_rows = row_count;

  update public.registry_track_provider_links l
  set
    track_id = v_canonical.id,
    raw_payload = coalesce(l.raw_payload, '{}'::jsonb) || jsonb_build_object(
      'moved_from_track_id', l.track_id::text,
      'moved_from_track_slug', d.slug,
      'moved_to_track_id', v_canonical.id::text,
      'moved_to_track_slug', v_canonical.slug,
      'track_duplicate_repair_at', now()
    ),
    updated_at = now()
  from public.registry_tracks d
  where l.track_id = d.id
    and d.id = any(v_duplicate_ids);

  get diagnostics v_provider_rows = row_count;

  with ranked_bad as (
    select
      bad.id,
      row_number() over (
        partition by coalesce(lower(nullif(bad.artist_slug, '')), 'artist:' || coalesce(bad.artist_id::text, bad.id::text))
        order by
          coalesce(bad.is_primary, false) desc,
          coalesce(bad.is_featured, false) asc,
          bad.credit_order asc,
          bad.updated_at desc nulls last,
          bad.id asc
      ) as duplicate_rank,
      exists (
        select 1
        from public.registry_track_artists good
        where good.track_id = v_canonical.id
          and coalesce(good.status, 'active') <> 'archived'
          and (
            (
              nullif(bad.artist_slug, '') is not null
              and lower(coalesce(good.artist_slug, '')) = lower(bad.artist_slug)
            )
            or (
              nullif(bad.artist_slug, '') is null
              and bad.artist_id is not null
              and good.artist_id = bad.artist_id
            )
          )
      ) as canonical_already_has_credit
    from public.registry_track_artists bad
    where bad.track_id = any(v_duplicate_ids)
      and coalesce(bad.status, 'active') <> 'archived'
  ),
  to_archive as (
    select id
    from ranked_bad
    where canonical_already_has_credit
       or duplicate_rank > 1
  )
  update public.registry_track_artists bad
  set
    status = 'archived',
    metadata = coalesce(bad.metadata, '{}'::jsonb) || jsonb_build_object(
      'archived_reason', 'track_duplicate_repair_duplicate_track_credit',
      'merged_into_track_id', v_canonical.id::text,
      'merged_into_track_slug', v_canonical.slug,
      'archived_at', now(),
      'repair_note', p_note
    ),
    updated_at = now()
  where bad.id in (select id from to_archive);

  get diagnostics v_track_artist_rows_archived = row_count;

  update public.registry_track_artists rta
  set
    track_id = v_canonical.id,
    metadata = coalesce(rta.metadata, '{}'::jsonb) || jsonb_build_object(
      'moved_from_track_id', rta.track_id::text,
      'moved_to_track_id', v_canonical.id::text,
      'moved_to_track_slug', v_canonical.slug,
      'track_duplicate_repair_at', now(),
      'repair_note', p_note
    ),
    updated_at = now()
  where rta.track_id = any(v_duplicate_ids)
    and coalesce(rta.status, 'active') <> 'archived';

  get diagnostics v_track_artist_rows_moved = row_count;

  update public.registry_release_tracks bad
  set
    status = 'archived',
    metadata = coalesce(bad.metadata, '{}'::jsonb) || jsonb_build_object(
      'archived_reason', 'track_duplicate_repair_duplicate_release_track',
      'merged_into_track_id', v_canonical.id::text,
      'merged_into_track_slug', v_canonical.slug,
      'archived_at', now(),
      'repair_note', p_note
    ),
    updated_at = now()
  where bad.track_id = any(v_duplicate_ids)
    and coalesce(bad.status, 'active') <> 'archived'
    and exists (
      select 1
      from public.registry_release_tracks good
      where good.release_id = bad.release_id
        and good.track_id = v_canonical.id
        and good.disc_number = bad.disc_number
        and coalesce(good.track_number, -1) = coalesce(bad.track_number, -1)
        and coalesce(good.status, 'active') <> 'archived'
    );

  get diagnostics v_release_rows_archived = row_count;

  update public.registry_release_tracks rrt
  set
    track_id = v_canonical.id,
    metadata = coalesce(rrt.metadata, '{}'::jsonb) || jsonb_build_object(
      'moved_from_track_id', rrt.track_id::text,
      'moved_to_track_id', v_canonical.id::text,
      'moved_to_track_slug', v_canonical.slug,
      'track_duplicate_repair_at', now(),
      'repair_note', p_note
    ),
    updated_at = now()
  where rrt.track_id = any(v_duplicate_ids)
    and coalesce(rrt.status, 'active') <> 'archived';

  get diagnostics v_release_rows_moved = row_count;

  update public.registry_tracks c
  set
    isrc = coalesce(c.isrc, (
      select nullif(d.isrc, '')
      from public.registry_tracks d
      where d.id = any(v_duplicate_ids)
        and nullif(d.isrc, '') is not null
      order by d.updated_at desc nulls last
      limit 1
    )),
    artwork_url = coalesce(c.artwork_url, (
      select nullif(d.artwork_url, '')
      from public.registry_tracks d
      where d.id = any(v_duplicate_ids)
        and nullif(d.artwork_url, '') is not null
      order by d.updated_at desc nulls last
      limit 1
    )),
    preview_url = coalesce(c.preview_url, (
      select nullif(d.preview_url, '')
      from public.registry_tracks d
      where d.id = any(v_duplicate_ids)
        and nullif(d.preview_url, '') is not null
      order by d.updated_at desc nulls last
      limit 1
    )),
    metadata = coalesce(c.metadata, '{}'::jsonb) || jsonb_build_object(
      'track_duplicate_repair_last_applied_at', now(),
      'track_duplicate_repair_absorbed_ids', (
        select jsonb_agg(d.id::text order by d.slug)
        from public.registry_tracks d
        where d.id = any(v_duplicate_ids)
      ),
      'track_duplicate_repair_absorbed_slugs', (
        select jsonb_agg(d.slug order by d.slug)
        from public.registry_tracks d
        where d.id = any(v_duplicate_ids)
      )
    ),
    updated_at = now()
  where c.id = v_canonical.id;

  update public.registry_tracks d
  set
    status = 'archived',
    metadata = coalesce(d.metadata, '{}'::jsonb) || jsonb_build_object(
      'superseded_by_track_id', v_canonical.id::text,
      'superseded_by_slug', v_canonical.slug,
      'dedupe_note', coalesce(nullif(p_note, ''), 'Track duplicate repair applied.'),
      'deduped_at', now(),
      'dedupe_confidence_bucket', v_confidence_bucket
    ),
    updated_at = now()
  where d.id = any(v_duplicate_ids)
    and d.status in ('active', 'draft', 'needs_review');

  get diagnostics v_tracks_archived = row_count;

  v_result := jsonb_build_object(
    'canonicalTrackId', v_canonical.id,
    'canonicalTrackSlug', v_canonical.slug,
    'duplicateTrackIds', to_jsonb(v_duplicate_ids),
    'confidenceBucket', v_confidence_bucket,
    'chartRowsMoved', v_chart_rows,
    'providerLinksMoved', v_provider_rows,
    'releaseTrackRowsMoved', v_release_rows_moved,
    'releaseTrackRowsArchived', v_release_rows_archived,
    'trackArtistCreditsMoved', v_track_artist_rows_moved,
    'trackArtistCreditsArchived', v_track_artist_rows_archived,
    'duplicateTracksArchived', v_tracks_archived
  );

  insert into public.registry_track_resolution_events (
    action,
    status,
    canonical_track_id,
    canonical_track_slug,
    duplicate_track_ids,
    duplicate_track_slugs,
    confidence_bucket,
    preview,
    result,
    note
  )
  select
    'track_duplicate_repair',
    'success',
    v_canonical.id,
    v_canonical.slug,
    v_duplicate_ids,
    coalesce(array_agg(d.slug order by d.slug), '{}'::text[]),
    v_confidence_bucket,
    v_preview,
    v_result,
    nullif(p_note, '')
  from public.registry_tracks d
  where d.id = any(v_duplicate_ids)
  returning id into v_event_id;

  return v_result || jsonb_build_object('eventId', v_event_id);
end;
$$;


ALTER FUNCTION "public"."admin_apply_registry_track_duplicate_repair"("p_canonical_track_id" "uuid", "p_duplicate_track_ids" "uuid"[], "p_note" "text", "p_allow_medium_confidence" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_create_registry_artist_for_decouple"("p_display_name" "text", "p_slug" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT 'needs_review'::"text", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_display_name text;
  v_slug text;
  v_status text;
  v_artist record;
  v_created boolean := false;
begin
  if not coalesce(public.current_user_has_capability('manage_registry'), false) then
    raise exception 'insufficient_privilege';
  end if;

  v_display_name := nullif(trim(coalesce(p_display_name, '')), '');
  if v_display_name is null then
    raise exception 'display_name_required';
  end if;

  v_slug := public.wk_slugify_text(coalesce(nullif(trim(p_slug), ''), v_display_name));
  if v_slug = '' then
    raise exception 'artist_slug_required';
  end if;

  v_status := coalesce(nullif(trim(p_status), ''), 'needs_review');
  if v_status not in ('active', 'draft', 'needs_review') then
    raise exception 'invalid_artist_status';
  end if;

  select id, slug, display_name, status, origin_iso2, public_image_url
  into v_artist
  from public.registry_artists
  where lower(slug) = lower(v_slug)
  limit 1;

  if v_artist.id is null then
    insert into public.registry_artists (
      slug,
      display_name,
      normalized_name,
      sort_name,
      status,
      metadata
    )
    values (
      v_slug,
      v_display_name,
      lower(regexp_replace(v_display_name, '\s+', ' ', 'g')),
      v_display_name,
      v_status,
      jsonb_build_object(
        'created_for', 'artist_decouple',
        'created_from_admin_decouple', true,
        'decouple_note', p_note,
        'created_at', now()
      )
    )
    returning id, slug, display_name, status, origin_iso2, public_image_url
    into v_artist;

    v_created := true;
  end if;

  return jsonb_build_object(
    'created', v_created,
    'artist', jsonb_build_object(
      'artist_id', v_artist.id,
      'artist_slug', v_artist.slug,
      'display_name', v_artist.display_name,
      'status', v_artist.status,
      'origin_iso2', v_artist.origin_iso2,
      'public_image_url', v_artist.public_image_url,
      'track_credit_count', 0,
      'release_credit_count', 0
    )
  );
end;
$$;


ALTER FUNCTION "public"."admin_create_registry_artist_for_decouple"("p_display_name" "text", "p_slug" "text", "p_status" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_create_registry_track_from_intake_enriched"("p_suggestion_id" "uuid", "p_title" "text", "p_review_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'auth', 'public'
    AS $$
declare
  v_suggestion public.registry_provider_track_suggestions%rowtype;
  v_title text;
  v_title_slug text;
  v_normalized_title text;
  v_track_id uuid := gen_random_uuid();
  v_slug text;
  v_primary_artist_id uuid;
  v_primary_artist_slug text;
  v_existing_track_id uuid;
  v_artist_count integer := 0;
  v_unresolved_artist_count integer := 0;
  v_fields jsonb := '{}'::jsonb;
  v_isrc text;
  v_result jsonb;
  v_after jsonb;
begin
  if auth.uid() is null then
    raise exception
      using
        errcode = '42501',
        message = 'Authentication is required.';
  end if;

  if not (
    public.current_user_is_administrator()
    or public.current_user_has_capability('manage_registry')
  ) then
    raise exception
      using
        errcode = '42501',
        message = 'Registry management permission is required.';
  end if;

  select suggestion.*
  into v_suggestion
  from public.registry_provider_track_suggestions suggestion
  where suggestion.id = p_suggestion_id
  for update;

  if not found then
    raise exception
      using
        errcode = 'P0002',
        message = 'Track Intake item does not exist.';
  end if;

  if v_suggestion.status <> 'needs_review' then
    raise exception
      'Only Track Intake items awaiting review can create a canonical track.';
  end if;

  if v_suggestion.canonical_track_id is not null
     or v_suggestion.canonicalized_track_id is not null
  then
    raise exception
      'This Track Intake item already has canonical Registry identity.';
  end if;

  v_title := nullif(btrim(p_title), '');

  if v_title is null then
    raise exception
      'Confirm the canonical track title before creating the Registry track.';
  end if;

  v_title_slug := public.wk_slugify_text(v_title);

  if nullif(v_title_slug, '') is null then
    raise exception
      'Canonical track title cannot produce a valid Registry slug.';
  end if;

  v_normalized_title := trim(
    regexp_replace(
      lower(v_title),
      '[^[:alnum:]]+',
      ' ',
      'g'
    )
  );

  select
    count(*)::integer,
    count(*) filter (
      where artist_credit.resolution_mode <> 'existing_artist'
         or artist_credit.registry_artist_id is null
         or artist.id is null
         or artist.status <> 'active'
    )::integer
  into
    v_artist_count,
    v_unresolved_artist_count
  from public.registry_provider_track_suggestion_artists artist_credit
  left join public.registry_artists artist
    on artist.id = artist_credit.registry_artist_id
  where artist_credit.suggestion_id = p_suggestion_id;

  if v_artist_count = 0 then
    raise exception
      'A canonical Registry track requires at least one reviewed artist credit.';
  end if;

  if v_unresolved_artist_count > 0 then
    raise exception
      'Resolve every artist credit to an active existing Registry artist before creating the canonical track.';
  end if;

  select
    artist_credit.registry_artist_id,
    artist.slug
  into
    v_primary_artist_id,
    v_primary_artist_slug
  from public.registry_provider_track_suggestion_artists artist_credit
  join public.registry_artists artist
    on artist.id = artist_credit.registry_artist_id
  where artist_credit.suggestion_id = p_suggestion_id
    and artist_credit.credit_role = 'primary'
    and artist_credit.resolution_mode = 'existing_artist'
    and artist.status = 'active'
  order by artist_credit.credit_order, artist_credit.id
  limit 1;

  if v_primary_artist_id is null then
    raise exception
      'A canonical Registry track requires a reviewed primary artist.';
  end if;

  select coalesce(
    jsonb_object_agg(
      suggestion.field_name,
      suggestion.suggested_value
    ),
    '{}'::jsonb
  )
  into v_fields
  from public.registry_enrichment_suggestions suggestion
  where suggestion.registry_entity_type = 'track'
    and suggestion.registry_entity_id = p_suggestion_id::text
    and suggestion.decision_status = 'approved';

  v_isrc := nullif(btrim(v_fields ->> 'isrc'), '');

  if v_isrc is not null then
    select track.id
    into v_existing_track_id
    from public.registry_tracks track
    where track.isrc = v_isrc
      and track.status <> 'archived'
    order by track.created_at
    limit 1;

    if v_existing_track_id is not null then
      raise exception
        'A Registry track with accepted ISRC % already exists (%). Select that canonical track instead.',
        v_isrc,
        v_existing_track_id;
    end if;
  end if;

  v_existing_track_id := null;

  select track.id
  into v_existing_track_id
  from public.registry_tracks track
  join public.registry_track_artists track_artist
    on track_artist.track_id = track.id
   and track_artist.artist_id = v_primary_artist_id
   and track_artist.status = 'active'
  where track.normalized_title = v_normalized_title
    and track.status <> 'archived'
  order by track.created_at
  limit 1;

  if v_existing_track_id is not null then
    raise exception
      'A Registry track with this reviewed title and primary artist already exists (%). Select that canonical track instead.',
      v_existing_track_id;
  end if;

  v_slug :=
    coalesce(
      nullif(btrim(v_primary_artist_slug), ''),
      'track'
    )
    || '--'
    || v_title_slug;

  if exists (
    select 1
    from public.registry_tracks track
    where track.slug = v_slug
      and track.status <> 'archived'
  ) then
    v_slug :=
      v_slug
      || '--'
      || left(replace(v_track_id::text, '-', ''), 8);
  end if;

  insert into public.registry_tracks (
    id,
    slug,
    title,
    normalized_title,
    release_id,
    status,
    metadata,
    created_at,
    updated_at
  )
  values (
    v_track_id,
    v_slug,
    v_title,
    v_normalized_title,
    null,
    'active',
    jsonb_strip_nulls(
      jsonb_build_object(
        'track_intake_source_suggestion_id',
          p_suggestion_id::text,
        'track_intake_created_at',
          now(),
        'release_evidence',
          jsonb_strip_nulls(
            jsonb_build_object(
              'title',
                nullif(
                  btrim(v_fields ->> 'release_title'),
                  ''
                ),
              'release_date',
                nullif(
                  btrim(v_fields ->> 'release_date'),
                  ''
                ),
              'release_date_precision',
                nullif(
                  btrim(
                    v_fields ->> 'release_date_precision'
                  ),
                  ''
                ),
              'artwork_url',
                nullif(
                  btrim(
                    v_fields ->> 'release_artwork_url'
                  ),
                  ''
                ),
              'label_name',
                nullif(
                  btrim(v_fields ->> 'label_name'),
                  ''
                ),
              'imprint_name',
                nullif(
                  btrim(v_fields ->> 'imprint_name'),
                  ''
                ),
              'upc',
                nullif(btrim(v_fields ->> 'upc'), ''),
              'copyright_text',
                nullif(
                  btrim(v_fields ->> 'copyright_text'),
                  ''
                )
            )
          )
      )
    ),
    now(),
    now()
  );

  insert into public.registry_track_artists (
    track_id,
    artist_id,
    artist_slug,
    artist_name_text,
    role,
    is_primary,
    is_featured,
    credit_order,
    display_credit,
    source,
    confidence,
    status,
    metadata,
    created_at,
    updated_at
  )
  select
    v_track_id,
    artist.id,
    artist.slug,
    artist.display_name,
    case
      when artist_credit.credit_role = 'featured'
        then 'featured_artist'
      else 'primary_artist'
    end,
    artist_credit.credit_role = 'primary',
    artist_credit.credit_role = 'featured',
    artist_credit.credit_order,
    artist.display_name,
    'track_intake_review',
    100,
    'active',
    jsonb_build_object(
      'source_suggestion_id',
        p_suggestion_id::text,
      'observed_name',
        artist_credit.observed_name
    ),
    now(),
    now()
  from public.registry_provider_track_suggestion_artists artist_credit
  join public.registry_artists artist
    on artist.id = artist_credit.registry_artist_id
  where artist_credit.suggestion_id = p_suggestion_id
    and artist_credit.resolution_mode = 'existing_artist'
    and artist.status = 'active'
  order by artist_credit.credit_order, artist_credit.id;

  select public.admin_resolve_registry_track_intake_enriched(
    p_suggestion_id,
    v_track_id,
    p_review_note,
    false
  )
  into v_result;

  select to_jsonb(track)
  into v_after
  from public.registry_tracks track
  where track.id = v_track_id;

  insert into public.registry_canonical_write_events (
    registry_entity_type,
    registry_entity_id,
    source_suggestion_id,
    source_table,
    field_name,
    target_path,
    before_value,
    after_value,
    action,
    status,
    error_message,
    actor,
    created_at
  )
  values (
    'track',
    v_track_id::text,
    p_suggestion_id::text,
    'registry_provider_track_suggestions',
    'canonical_identity',
    'registry_tracks',
    null,
    v_after,
    'create_from_track_intake',
    'applied',
    null,
    auth.uid()::text,
    now()
  );

  return coalesce(v_result, '{}'::jsonb)
    || jsonb_build_object(
      'created_registry_track_id',
        v_track_id,
      'created_registry_track_title',
        v_title,
      'created_registry_track_slug',
        v_slug,
      'created',
        true
    );
end;
$$;


ALTER FUNCTION "public"."admin_create_registry_track_from_intake_enriched"("p_suggestion_id" "uuid", "p_title" "text", "p_review_note" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_create_registry_track_from_intake_enriched"("p_suggestion_id" "uuid", "p_title" "text", "p_review_note" "text") IS 'Creates one canonical Registry track from reviewed Track Intake evidence using only pre-resolved existing artist identities, then atomically applies accepted enrichment and resolves the same Playlist item.';



CREATE OR REPLACE FUNCTION "public"."admin_decouple_registry_artist"("p_source_artist_id" "uuid", "p_replacements" "jsonb", "p_note" "text" DEFAULT NULL::"text", "p_archive_source" boolean DEFAULT true, "p_chart_primary_artist_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_source record;
  v_chart_artist record;
  v_replacement_count integer := 0;
  v_track_inserted integer := 0;
  v_track_archived integer := 0;
  v_release_inserted integer := 0;
  v_release_archived integer := 0;
  v_chart_rows_v2 integer := 0;
  v_chart_rows_runtime integer := 0;
  v_track_meta_rows integer := 0;
  v_alias_blocked_rows integer := 0;
  v_source_archived boolean := false;
begin
  if not coalesce(public.current_user_has_capability('manage_registry'), false) then
    raise exception 'insufficient_privilege';
  end if;

  if p_source_artist_id is null then
    raise exception 'source_artist_required';
  end if;

  if jsonb_typeof(coalesce(p_replacements, 'null'::jsonb)) <> 'array' then
    raise exception 'replacement_artists_required';
  end if;

  select id, slug, display_name, status, origin_iso2, public_image_url, metadata
  into v_source
  from public.registry_artists
  where id = p_source_artist_id
    and status in ('active', 'draft', 'needs_review', 'archived')
  limit 1;

  if v_source.id is null then
    raise exception 'source_artist_not_found';
  end if;

  create temporary table if not exists pg_temp.admin_artist_decouple_replacements (
    artist_id uuid primary key,
    role text not null,
    is_primary boolean not null,
    is_featured boolean not null,
    credit_order integer not null,
    display_credit text
  ) on commit drop;

  truncate table pg_temp.admin_artist_decouple_replacements;

  insert into pg_temp.admin_artist_decouple_replacements (
    artist_id,
    role,
    is_primary,
    is_featured,
    credit_order,
    display_credit
  )
  select distinct on ((item.value->>'artist_id')::uuid)
    (item.value->>'artist_id')::uuid,
    coalesce(
      nullif(item.value->>'role', ''),
      case
        when lower(coalesce(item.value->>'is_featured', 'false')) in ('true', '1', 'yes') then 'featured_artist'
        else 'primary_artist'
      end
    ) as role,
    lower(coalesce(item.value->>'is_primary', 'false')) in ('true', '1', 'yes') as is_primary,
    lower(coalesce(item.value->>'is_featured', 'false')) in ('true', '1', 'yes') as is_featured,
    coalesce(nullif(item.value->>'credit_order', '')::integer, item.ordinality::integer) as credit_order,
    nullif(item.value->>'display_credit', '') as display_credit
  from jsonb_array_elements(p_replacements) with ordinality as item(value, ordinality)
  where nullif(item.value->>'artist_id', '') is not null
  order by (item.value->>'artist_id')::uuid, item.ordinality;

  select count(*) into v_replacement_count from pg_temp.admin_artist_decouple_replacements;

  if v_replacement_count < 2 then
    raise exception 'at_least_two_replacement_artists_required';
  end if;

  if exists (
    select 1
    from pg_temp.admin_artist_decouple_replacements r
    where r.artist_id = v_source.id
  ) then
    raise exception 'source_artist_cannot_be_a_replacement';
  end if;

  if exists (
    select 1
    from pg_temp.admin_artist_decouple_replacements r
    left join public.registry_artists a
      on a.id = r.artist_id
     and a.status in ('active', 'draft', 'needs_review')
    where a.id is null
  ) then
    raise exception 'replacement_artist_not_found';
  end if;

  if exists (
    select 1
    from pg_temp.admin_artist_decouple_replacements r
    where r.role not in ('primary_artist', 'featured_artist', 'collaborator', 'producer', 'composer', 'remixer', 'group_member', 'unknown')
  ) then
    raise exception 'invalid_replacement_artist_role';
  end if;

  if p_chart_primary_artist_id is not null and not exists (
    select 1
    from pg_temp.admin_artist_decouple_replacements r
    where r.artist_id = p_chart_primary_artist_id
  ) then
    raise exception 'chart_primary_artist_must_be_one_of_the_replacements';
  end if;

  select a.id, a.slug, a.display_name
  into v_chart_artist
  from pg_temp.admin_artist_decouple_replacements r
  join public.registry_artists a on a.id = r.artist_id
  where r.artist_id = coalesce(
    p_chart_primary_artist_id,
    (
      select r2.artist_id
      from pg_temp.admin_artist_decouple_replacements r2
      order by r2.is_primary desc, r2.credit_order asc, r2.artist_id asc
      limit 1
    )
  )
  limit 1;

  if v_chart_artist.id is null then
    raise exception 'chart_primary_artist_not_found';
  end if;

  with source_links as (
    select rta.*
    from public.registry_track_artists rta
    where (
        rta.artist_id = v_source.id
        or lower(coalesce(rta.artist_slug, '')) = lower(v_source.slug)
      )
      and coalesce(rta.status, 'shadow') in ('shadow', 'active', 'needs_review')
  ), replacement_rows as (
    select
      r.artist_id,
      a.slug,
      a.display_name,
      r.role,
      r.is_primary,
      r.is_featured,
      r.credit_order,
      r.display_credit
    from pg_temp.admin_artist_decouple_replacements r
    join public.registry_artists a on a.id = r.artist_id
  ), inserted as (
    insert into public.registry_track_artists (
      track_id,
      artist_id,
      artist_slug,
      artist_name_text,
      role,
      is_primary,
      is_featured,
      credit_order,
      display_credit,
      source,
      confidence,
      status,
      metadata,
      created_at,
      updated_at
    )
    select
      sl.track_id,
      rr.artist_id,
      rr.slug,
      coalesce(rr.display_credit, rr.display_name),
      rr.role,
      rr.is_primary,
      rr.is_featured,
      rr.credit_order,
      coalesce(rr.display_credit, rr.display_name),
      'admin_artist_decouple',
      greatest(coalesce(sl.confidence, 0), 100),
      'active',
      coalesce(sl.metadata, '{}'::jsonb)
        || jsonb_build_object(
          'decoupled_from_artist_id', v_source.id::text,
          'decoupled_from_artist_slug', v_source.slug,
          'decoupled_from_artist_name', v_source.display_name,
          'source_credit_id', sl.id::text,
          'decouple_note', p_note,
          'decoupled_at', now()
        ),
      now(),
      now()
    from source_links sl
    cross join replacement_rows rr
    where sl.track_id is not null
      and not exists (
        select 1
        from public.registry_track_artists existing
        where existing.track_id = sl.track_id
          and existing.artist_id = rr.artist_id
          and existing.role = rr.role
          and existing.credit_order = rr.credit_order
          and coalesce(existing.status, 'shadow') in ('shadow', 'active', 'needs_review')
      )
    returning 1
  )
  select count(*) into v_track_inserted from inserted;

  update public.registry_track_artists rta
  set
    status = 'archived',
    metadata = coalesce(rta.metadata, '{}'::jsonb)
      || jsonb_build_object(
        'archived_by_artist_decouple', true,
        'decoupled_to_artist_ids', (
          select jsonb_agg(r.artist_id::text order by r.credit_order, r.artist_id)
          from pg_temp.admin_artist_decouple_replacements r
        ),
        'decouple_note', p_note,
        'decoupled_at', now()
      ),
    updated_at = now()
  where (
      rta.artist_id = v_source.id
      or lower(coalesce(rta.artist_slug, '')) = lower(v_source.slug)
    )
    and coalesce(rta.status, 'shadow') in ('shadow', 'active', 'needs_review');

  get diagnostics v_track_archived = row_count;

  with source_links as (
    select rra.*
    from public.registry_release_artists rra
    where (
        rra.artist_id = v_source.id
        or lower(coalesce(rra.artist_slug, '')) = lower(v_source.slug)
      )
      and coalesce(rra.status, 'shadow') in ('shadow', 'active', 'needs_review')
  ), replacement_rows as (
    select
      r.artist_id,
      a.slug,
      a.display_name,
      r.role,
      r.is_primary,
      r.is_featured,
      r.credit_order,
      r.display_credit
    from pg_temp.admin_artist_decouple_replacements r
    join public.registry_artists a on a.id = r.artist_id
  ), inserted as (
    insert into public.registry_release_artists (
      release_id,
      artist_id,
      artist_slug,
      artist_name_text,
      role,
      is_primary,
      is_featured,
      credit_order,
      display_credit,
      source,
      confidence,
      status,
      metadata,
      created_at,
      updated_at
    )
    select
      sl.release_id,
      rr.artist_id,
      rr.slug,
      coalesce(rr.display_credit, rr.display_name),
      rr.role,
      rr.is_primary,
      rr.is_featured,
      rr.credit_order,
      coalesce(rr.display_credit, rr.display_name),
      'admin_artist_decouple',
      greatest(coalesce(sl.confidence, 0), 100),
      'active',
      coalesce(sl.metadata, '{}'::jsonb)
        || jsonb_build_object(
          'decoupled_from_artist_id', v_source.id::text,
          'decoupled_from_artist_slug', v_source.slug,
          'decoupled_from_artist_name', v_source.display_name,
          'source_credit_id', sl.id::text,
          'decouple_note', p_note,
          'decoupled_at', now()
        ),
      now(),
      now()
    from source_links sl
    cross join replacement_rows rr
    where sl.release_id is not null
      and not exists (
        select 1
        from public.registry_release_artists existing
        where existing.release_id = sl.release_id
          and existing.artist_id = rr.artist_id
          and existing.role = rr.role
          and existing.credit_order = rr.credit_order
          and coalesce(existing.status, 'shadow') in ('shadow', 'active', 'needs_review')
      )
    returning 1
  )
  select count(*) into v_release_inserted from inserted;

  update public.registry_release_artists rra
  set
    status = 'archived',
    metadata = coalesce(rra.metadata, '{}'::jsonb)
      || jsonb_build_object(
        'archived_by_artist_decouple', true,
        'decoupled_to_artist_ids', (
          select jsonb_agg(r.artist_id::text order by r.credit_order, r.artist_id)
          from pg_temp.admin_artist_decouple_replacements r
        ),
        'decouple_note', p_note,
        'decoupled_at', now()
      ),
    updated_at = now()
  where (
      rra.artist_id = v_source.id
      or lower(coalesce(rra.artist_slug, '')) = lower(v_source.slug)
    )
    and coalesce(rra.status, 'shadow') in ('shadow', 'active', 'needs_review');

  get diagnostics v_release_archived = row_count;

  update public.wk_chart_entries_v2 ce
  set
    artist_slug = v_chart_artist.slug,
    artist_name = v_chart_artist.display_name,
    updated_at = now()
  where public.wk_slugify_text(coalesce(ce.artist_slug, '')) = public.wk_slugify_text(v_source.slug)
     or public.wk_slugify_text(coalesce(ce.artist_name, '')) = public.wk_slugify_text(v_source.display_name);

  get diagnostics v_chart_rows_v2 = row_count;

  update public.chart_entries ce
  set
    artist_slug = v_chart_artist.slug,
    artist_name = v_chart_artist.display_name
  where public.wk_slugify_text(coalesce(ce.artist_slug, '')) = public.wk_slugify_text(v_source.slug)
     or public.wk_slugify_text(coalesce(ce.artist_name, '')) = public.wk_slugify_text(v_source.display_name);

  get diagnostics v_chart_rows_runtime = row_count;

  update public.registry_tracks rt
  set
    metadata = jsonb_set(
      coalesce(rt.metadata, '{}'::jsonb)
        || jsonb_build_object(
          'decoupled_artist_slugs', (
            select jsonb_agg(a.slug order by r.credit_order, a.slug)
            from pg_temp.admin_artist_decouple_replacements r
            join public.registry_artists a on a.id = r.artist_id
          ),
          'decoupled_from_artist_slug', v_source.slug,
          'decouple_note', p_note,
          'decoupled_at', now()
        ),
      '{primary_artist_slug}',
      to_jsonb(v_chart_artist.slug),
      true
    ),
    updated_at = now()
  where exists (
      select 1
      from public.registry_track_artists archived_source
      where archived_source.track_id = rt.id
        and (
          archived_source.artist_id = v_source.id
          or lower(coalesce(archived_source.artist_slug, '')) = lower(v_source.slug)
        )
        and coalesce(archived_source.metadata->>'archived_by_artist_decouple', 'false') = 'true'
    )
    and (
      public.wk_slugify_text(coalesce(rt.metadata->>'primary_artist_slug', '')) = public.wk_slugify_text(v_source.slug)
      or public.wk_slugify_text(coalesce(rt.metadata->>'artist_slug', '')) = public.wk_slugify_text(v_source.slug)
    );

  get diagnostics v_track_meta_rows = row_count;

  update public.registry_artist_aliases a
  set
    status = 'blocked',
    notes = coalesce(nullif(p_note, ''), notes, 'Blocked because this alias slug represents a split artist credit, not one canonical artist.')
  where lower(a.alias_slug) = lower(v_source.slug)
    and coalesce(a.status, 'active') = 'active';

  get diagnostics v_alias_blocked_rows = row_count;

  update public.registry_artists a
  set
    metadata = coalesce(a.metadata, '{}'::jsonb)
      || jsonb_build_object(
        'decoupled_from_combined_artist_id', v_source.id::text,
        'decoupled_from_combined_artist_slug', v_source.slug,
        'decoupled_from_combined_artist_name', v_source.display_name,
        'decoupled_at', now(),
        'decouple_note', p_note
      ),
    updated_at = now()
  from pg_temp.admin_artist_decouple_replacements r
  where a.id = r.artist_id;

  if p_archive_source then
    update public.registry_artists
    set
      status = 'archived',
      metadata = coalesce(metadata, '{}'::jsonb)
        || jsonb_build_object(
          'archived_by_artist_decouple', true,
          'decoupled_to_artist_ids', (
            select jsonb_agg(r.artist_id::text order by r.credit_order, r.artist_id)
            from pg_temp.admin_artist_decouple_replacements r
          ),
          'chart_primary_artist_id', v_chart_artist.id::text,
          'chart_primary_artist_slug', v_chart_artist.slug,
          'decouple_note', p_note,
          'decoupled_at', now()
        ),
      updated_at = now()
    where id = v_source.id;

    v_source_archived := true;
  else
    update public.registry_artists
    set
      metadata = coalesce(metadata, '{}'::jsonb)
        || jsonb_build_object(
          'decoupled_but_not_archived', true,
          'decoupled_to_artist_ids', (
            select jsonb_agg(r.artist_id::text order by r.credit_order, r.artist_id)
            from pg_temp.admin_artist_decouple_replacements r
          ),
          'chart_primary_artist_id', v_chart_artist.id::text,
          'chart_primary_artist_slug', v_chart_artist.slug,
          'decouple_note', p_note,
          'decoupled_at', now()
        ),
      updated_at = now()
    where id = v_source.id;
  end if;

  insert into public.registry_audit_log (
    actor_label,
    action,
    entity_type,
    entity_id,
    before_value,
    after_value,
    metadata
  )
  values (
    'admin',
    'artist_credit_decoupled',
    'registry_artist',
    v_source.id,
    jsonb_build_object(
      'source_artist_id', v_source.id,
      'source_artist_slug', v_source.slug,
      'source_artist_name', v_source.display_name
    ),
    jsonb_build_object(
      'replacement_artist_ids', (
        select jsonb_agg(r.artist_id::text order by r.credit_order, r.artist_id)
        from pg_temp.admin_artist_decouple_replacements r
      ),
      'chart_primary_artist_id', v_chart_artist.id,
      'chart_primary_artist_slug', v_chart_artist.slug
    ),
    jsonb_build_object(
      'note', p_note,
      'trackCreditsInserted', v_track_inserted,
      'trackCreditsArchived', v_track_archived,
      'releaseCreditsInserted', v_release_inserted,
      'releaseCreditsArchived', v_release_archived,
      'chartEntriesV2Updated', v_chart_rows_v2,
      'chartEntriesRuntimeUpdated', v_chart_rows_runtime,
      'sourceArchived', v_source_archived
    )
  );

  return jsonb_build_object(
    'sourceArtistId', v_source.id,
    'sourceSlug', v_source.slug,
    'sourceName', v_source.display_name,
    'replacementCount', v_replacement_count,
    'chartPrimaryArtistId', v_chart_artist.id,
    'chartPrimarySlug', v_chart_artist.slug,
    'chartPrimaryName', v_chart_artist.display_name,
    'trackCreditsInserted', v_track_inserted,
    'trackCreditsArchived', v_track_archived,
    'releaseCreditsInserted', v_release_inserted,
    'releaseCreditsArchived', v_release_archived,
    'chartEntriesV2Updated', v_chart_rows_v2,
    'chartEntriesRuntimeUpdated', v_chart_rows_runtime,
    'trackMetadataRowsUpdated', v_track_meta_rows,
    'aliasRowsBlocked', v_alias_blocked_rows,
    'sourceArchived', v_source_archived
  );
end;
$$;


ALTER FUNCTION "public"."admin_decouple_registry_artist"("p_source_artist_id" "uuid", "p_replacements" "jsonb", "p_note" "text", "p_archive_source" boolean, "p_chart_primary_artist_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_get_artist_decouple_decisions"("p_source_type" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_items jsonb;
begin
  if not coalesce(public.current_user_has_capability('manage_registry'), false) then
    raise exception 'insufficient_privilege';
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', d.id,
        'source_key', d.source_key,
        'source_type', d.source_type,
        'source_table', d.source_table,
        'source_id', d.source_id,
        'source_label', d.source_label,
        'source_snapshot', d.source_snapshot,
        'source_artist_id', d.source_artist_id,
        'raw_credit_text', d.raw_credit_text,
        'parsed_tokens', d.parsed_tokens,
        'selected_artists', d.selected_artists,
        'chart_primary_artist_id', d.chart_primary_artist_id,
        'decision_type', d.decision_type,
        'decision_status', d.decision_status,
        'note', d.note,
        'actor_id', d.actor_id,
        'applied_at', d.applied_at,
        'apply_result_json', d.apply_result_json,
        'created_at', d.created_at,
        'updated_at', d.updated_at
      )
      order by d.updated_at desc
    ),
    '[]'::jsonb
  )
  into v_items
  from public.registry_artist_decouple_decisions d
  where p_source_type is null
     or d.source_type = p_source_type;

  return v_items;
end;
$$;


ALTER FUNCTION "public"."admin_get_artist_decouple_decisions"("p_source_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_get_artist_decouple_preview"("p_source_artist_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_source record;
begin
  if not coalesce(public.current_user_has_capability('manage_registry'), false) then
    raise exception 'insufficient_privilege';
  end if;

  if p_source_artist_id is null then
    raise exception 'source_artist_required';
  end if;

  select
    a.id as artist_id,
    a.slug as artist_slug,
    a.display_name,
    a.status,
    a.origin_iso2,
    a.public_image_url,
    a.metadata,
    coalesce((
      select count(*)
      from public.registry_track_artists rta
      where (
          rta.artist_id = a.id
          or lower(coalesce(rta.artist_slug, '')) = lower(a.slug)
        )
    ), 0) as track_credit_count,
    coalesce((
      select count(*)
      from public.registry_release_artists rra
      where (
          rra.artist_id = a.id
          or lower(coalesce(rra.artist_slug, '')) = lower(a.slug)
        )
    ), 0) as release_credit_count,
    coalesce((
      select count(*)
      from public.registry_track_artists rta
      where (
          rta.artist_id = a.id
          or lower(coalesce(rta.artist_slug, '')) = lower(a.slug)
        )
        and coalesce(rta.status, 'shadow') in ('shadow', 'active', 'needs_review')
    ), 0) as actionable_track_credit_count,
    coalesce((
      select count(*)
      from public.registry_release_artists rra
      where (
          rra.artist_id = a.id
          or lower(coalesce(rra.artist_slug, '')) = lower(a.slug)
        )
        and coalesce(rra.status, 'shadow') in ('shadow', 'active', 'needs_review')
    ), 0) as actionable_release_credit_count
  into v_source
  from public.registry_artists a
  where a.id = p_source_artist_id
    and a.status in ('active', 'draft', 'needs_review', 'archived')
  limit 1;

  if v_source.artist_id is null then
    raise exception 'source_artist_not_found';
  end if;

  return jsonb_build_object(
    'sourceArtist', jsonb_build_object(
      'artist_id', v_source.artist_id,
      'artist_slug', v_source.artist_slug,
      'display_name', v_source.display_name,
      'status', v_source.status,
      'origin_iso2', v_source.origin_iso2,
      'public_image_url', v_source.public_image_url,
      'track_credit_count', v_source.track_credit_count,
      'release_credit_count', v_source.release_credit_count,
      'actionable_track_credit_count', v_source.actionable_track_credit_count,
      'actionable_release_credit_count', v_source.actionable_release_credit_count
    ),
    'trackCredits', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'credit_id', rta.id,
          'track_id', rta.track_id,
          'track_slug', rt.slug,
          'track_title', rt.title,
          'release_id', rt.release_id,
          'release_title', rr.title,
          'role', rta.role,
          'is_primary', rta.is_primary,
          'is_featured', rta.is_featured,
          'credit_order', rta.credit_order,
          'display_credit', rta.display_credit,
          'status', coalesce(rta.status, 'shadow'),
          'is_actionable', coalesce(rta.status, 'shadow') in ('shadow', 'active', 'needs_review')
        )
        order by
          case when coalesce(rta.status, 'shadow') in ('shadow', 'active', 'needs_review') then 0 else 1 end,
          rt.title asc,
          rta.credit_order asc,
          rta.id asc
      )
      from public.registry_track_artists rta
      left join public.registry_tracks rt on rt.id = rta.track_id
      left join public.registry_releases rr on rr.id = rt.release_id
      where (
          rta.artist_id = v_source.artist_id
          or lower(coalesce(rta.artist_slug, '')) = lower(v_source.artist_slug)
        )
    ), '[]'::jsonb),
    'releaseCredits', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'credit_id', rra.id,
          'release_id', rra.release_id,
          'release_slug', rr.slug,
          'release_title', rr.title,
          'role', rra.role,
          'is_primary', rra.is_primary,
          'is_featured', rra.is_featured,
          'credit_order', rra.credit_order,
          'display_credit', rra.display_credit,
          'status', coalesce(rra.status, 'shadow'),
          'is_actionable', coalesce(rra.status, 'shadow') in ('shadow', 'active', 'needs_review')
        )
        order by
          case when coalesce(rra.status, 'shadow') in ('shadow', 'active', 'needs_review') then 0 else 1 end,
          rr.title asc,
          rra.credit_order asc,
          rra.id asc
      )
      from public.registry_release_artists rra
      left join public.registry_releases rr on rr.id = rra.release_id
      where (
          rra.artist_id = v_source.artist_id
          or lower(coalesce(rra.artist_slug, '')) = lower(v_source.artist_slug)
        )
    ), '[]'::jsonb),
    'chartEntries', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'entry_id', ce.id,
          'track_id', ce.track_id,
          'track_slug', ce.track_slug,
          'track_title', ce.track_title,
          'artist_name', ce.artist_name,
          'artist_slug', ce.artist_slug,
          'rank', ce.rank,
          'canonical_artist_id', ce.canonical_artist_id
        )
        order by ce.track_title asc, ce.rank asc, ce.id asc
      )
      from public.wk_chart_entries_v2 ce
      where ce.canonical_artist_id = v_source.artist_id::text
         or public.wk_slugify_text(coalesce(ce.artist_slug, '')) = public.wk_slugify_text(v_source.artist_slug)
         or public.wk_slugify_text(coalesce(ce.artist_name, '')) = public.wk_slugify_text(v_source.display_name)
    ), '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."admin_get_artist_decouple_preview"("p_source_artist_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_get_artist_resolution_history"("p_limit" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_limit integer;
  v_events jsonb;
begin
  if not coalesce(public.current_user_has_capability('manage_registry'), false) then
    raise exception 'insufficient_privilege';
  end if;

  v_limit := least(greatest(coalesce(p_limit, 100), 1), 300);

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', e.id,
        'action', e.action,
        'status', e.status,
        'source_artist_id', e.source_artist_id,
        'source_artist_slug', e.source_artist_slug,
        'source_artist_name', e.source_artist_name,
        'source_snapshot', e.source_snapshot,
        'replacement_artists', e.replacement_artists,
        'track_links', e.track_links,
        'release_links', e.release_links,
        'chart_entries', e.chart_entries,
        'note', e.note,
        'error_message', e.error_message,
        'result', e.result,
        'actor_id', e.actor_id,
        'actor_label', e.actor_label,
        'created_at', e.created_at
      )
      order by e.created_at desc
    ),
    '[]'::jsonb
  )
  into v_events
  from (
    select *
    from public.registry_artist_resolution_events
    order by created_at desc
    limit v_limit
  ) e;

  return v_events;
end;
$$;


ALTER FUNCTION "public"."admin_get_artist_resolution_history"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_get_chart_artist_resolution_decisions"("p_edition_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_rows jsonb;
begin
  if not (
    coalesce(public.current_user_has_capability('view_charts_admin'), false)
    or coalesce(public.current_user_has_capability('manage_charts'), false)
    or coalesce(public.current_user_has_capability('manage_registry'), false)
    or coalesce(public.current_user_is_administrator(), false)
  ) then
    raise exception 'insufficient_privilege';
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', d.id,
        'chart_entry_id', d.chart_entry_id,
        'edition_id', d.edition_id,
        'program_id', d.program_id,
        'decision_type', d.decision_type,
        'decision_status', d.decision_status,
        'parsed_tokens', d.parsed_tokens,
        'selected_artists', d.selected_artists,
        'note', d.note,
        'actor_id', d.actor_id,
        'created_at', d.created_at,
        'updated_at', d.updated_at
      )
      order by d.updated_at desc
    ),
    '[]'::jsonb
  )
  into v_rows
  from public.chart_artist_resolution_decisions d
  where d.edition_id = p_edition_id;

  return v_rows;
end;
$$;


ALTER FUNCTION "public"."admin_get_chart_artist_resolution_decisions"("p_edition_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_get_registry_artist_merge_preview"("p_source_artist_id" "uuid", "p_canonical_artist_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_source record;
  v_canonical record;
begin
  if not coalesce(public.current_user_has_capability('manage_registry'), false) then
    raise exception 'insufficient_privilege';
  end if;

  if p_source_artist_id is null or p_canonical_artist_id is null then
    raise exception 'source_and_canonical_required';
  end if;

  if p_source_artist_id = p_canonical_artist_id then
    raise exception 'cannot_merge_artist_into_itself';
  end if;

  select id, slug, display_name, status, origin_iso2, public_image_url, metadata
  into v_source
  from public.registry_artists
  where id = p_source_artist_id
    and status in ('active', 'draft', 'needs_review', 'archived')
  limit 1;

  if v_source.id is null then
    raise exception 'source_artist_not_found';
  end if;

  select id, slug, display_name, status, origin_iso2, public_image_url, metadata
  into v_canonical
  from public.registry_artists
  where id = p_canonical_artist_id
    and status in ('active', 'draft', 'needs_review')
  limit 1;

  if v_canonical.id is null then
    raise exception 'canonical_artist_not_found';
  end if;

  return jsonb_build_object(
    'sourceArtist', jsonb_build_object(
      'artist_id', v_source.id,
      'artist_slug', v_source.slug,
      'display_name', v_source.display_name,
      'status', v_source.status,
      'origin_iso2', v_source.origin_iso2,
      'public_image_url', v_source.public_image_url
    ),
    'canonicalArtist', jsonb_build_object(
      'artist_id', v_canonical.id,
      'artist_slug', v_canonical.slug,
      'display_name', v_canonical.display_name,
      'status', v_canonical.status,
      'origin_iso2', v_canonical.origin_iso2,
      'public_image_url', v_canonical.public_image_url
    ),
    'trackCredits', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'credit_id', rta.id,
          'track_id', rta.track_id,
          'track_slug', rt.slug,
          'track_title', rt.title,
          'release_title', rr.title,
          'role', rta.role,
          'is_primary', rta.is_primary,
          'is_featured', rta.is_featured,
          'credit_order', rta.credit_order,
          'display_credit', rta.display_credit,
          'status', rta.status,
          'will_archive_duplicate', exists (
            select 1
            from public.registry_track_artists good
            where good.track_id = rta.track_id
              and good.artist_id = v_canonical.id
              and coalesce(good.status, 'active') <> 'archived'
          )
        )
        order by rt.title asc, rta.credit_order asc, rta.id asc
      )
      from public.registry_track_artists rta
      left join public.registry_tracks rt on rt.id = rta.track_id
      left join public.registry_releases rr on rr.id = rt.release_id
      where (
          rta.artist_id = v_source.id
          or lower(coalesce(rta.artist_slug, '')) = lower(v_source.slug)
        )
        and coalesce(rta.status, 'active') <> 'archived'
    ), '[]'::jsonb),
    'releaseCredits', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'credit_id', rra.id,
          'release_id', rra.release_id,
          'release_slug', rr.slug,
          'release_title', rr.title,
          'role', rra.role,
          'is_primary', rra.is_primary,
          'is_featured', rra.is_featured,
          'credit_order', rra.credit_order,
          'display_credit', rra.display_credit,
          'status', rra.status,
          'will_archive_duplicate', exists (
            select 1
            from public.registry_release_artists good
            where good.release_id = rra.release_id
              and good.artist_id = v_canonical.id
              and coalesce(good.status, 'active') <> 'archived'
          )
        )
        order by rr.title asc, rra.credit_order asc, rra.id asc
      )
      from public.registry_release_artists rra
      left join public.registry_releases rr on rr.id = rra.release_id
      where (
          rra.artist_id = v_source.id
          or lower(coalesce(rra.artist_slug, '')) = lower(v_source.slug)
        )
        and coalesce(rra.status, 'active') <> 'archived'
    ), '[]'::jsonb),
    'chartEntries', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'entry_id', ce.id,
          'edition_id', ce.edition_id,
          'track_slug', ce.track_slug,
          'track_title', ce.track_title,
          'artist_name', ce.artist_name,
          'artist_slug', ce.artist_slug,
          'canonical_artist_id', ce.canonical_artist_id,
          'rank', ce.rank
        )
        order by ce.track_title asc, ce.rank asc, ce.id asc
      )
      from public.wk_chart_entries_v2 ce
      where ce.canonical_artist_id = v_source.id::text
         or public.wk_slugify_text(coalesce(ce.artist_slug, '')) = public.wk_slugify_text(v_source.slug)
         or public.wk_slugify_text(coalesce(ce.artist_name, '')) = public.wk_slugify_text(v_source.display_name)
    ), '[]'::jsonb),
    'aliases', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', a.id,
          'alias_slug', a.alias_slug,
          'canonical_artist_id', a.canonical_artist_id,
          'alias_display_name', a.alias_display_name,
          'status', a.status,
          'source', a.source,
          'notes', a.notes
        )
        order by a.created_at desc, a.id asc
      )
      from public.registry_artist_aliases a
      where lower(a.alias_slug) = lower(v_source.slug)
         or a.canonical_artist_id = v_source.id
    ), '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."admin_get_registry_artist_merge_preview"("p_source_artist_id" "uuid", "p_canonical_artist_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_get_registry_track_duplicate_audit"("p_limit" integer DEFAULT 200, "p_include_low_confidence" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
with track_base as (
  select
    t.id,
    t.slug,
    t.title,
    t.status,
    t.isrc,
    t.release_id,
    t.artwork_url,
    t.preview_url,
    t.created_at,
    t.updated_at,
    coalesce(t.metadata, '{}'::jsonb) as metadata,
    nullif(t.metadata->>'apple_music_catalog_id', '') as apple_music_catalog_id,
    public.wk_slugify_text(coalesce(t.title, '')) as title_key
  from public.registry_tracks t
  where t.status in ('active', 'draft', 'needs_review')
),
primary_artists as (
  select
    rta.track_id,
    string_agg(rta.artist_slug, ', ' order by rta.credit_order, rta.artist_slug)
      filter (where coalesce(rta.is_primary, false) = true) as primary_artist_slugs,
    string_agg(coalesce(rta.artist_name_text, rta.artist_slug), ', ' order by rta.credit_order, rta.artist_slug)
      filter (where coalesce(rta.is_primary, false) = true) as primary_artist_names,
    string_agg(rta.artist_slug, ', ' order by rta.credit_order, rta.artist_slug) as all_artist_slugs
  from public.registry_track_artists rta
  where coalesce(rta.status, 'active') <> 'archived'
  group by rta.track_id
),
provider_summary as (
  select
    l.track_id,
    count(*) as provider_link_count,
    string_agg(
      l.provider_key || ':' || l.provider_track_id,
      ', ' order by l.provider_key, l.provider_track_id
    ) as providers
  from public.registry_track_provider_links l
  where l.provider_track_id is not null
  group by l.track_id
),
chart_refs as (
  select
    ce.canonical_track_id::text as track_id,
    count(*) as chart_ref_count
  from public.wk_chart_entries_v2 ce
  where ce.canonical_track_id is not null
  group by ce.canonical_track_id::text
),
track_enriched as (
  select
    tb.*,
    pa.primary_artist_slugs,
    pa.primary_artist_names,
    pa.all_artist_slugs,
    coalesce(ps.provider_link_count, 0) as provider_link_count,
    ps.providers,
    coalesce(cr.chart_ref_count, 0) as chart_ref_count
  from track_base tb
  left join primary_artists pa on pa.track_id = tb.id
  left join provider_summary ps on ps.track_id = tb.id
  left join chart_refs cr on cr.track_id = tb.id::text
),
provider_duplicate_keys as (
  select
    l.provider_key,
    l.provider_track_id
  from public.registry_track_provider_links l
  join track_base tb on tb.id = l.track_id
  where l.provider_track_id is not null
  group by l.provider_key, l.provider_track_id
  having count(distinct l.track_id) > 1
),
apple_duplicate_keys as (
  select
    apple_music_catalog_id
  from track_base
  where apple_music_catalog_id is not null
  group by apple_music_catalog_id
  having count(distinct id) > 1
),
isrc_duplicate_keys as (
  select
    isrc
  from track_base
  where nullif(isrc, '') is not null
  group by isrc
  having count(distinct id) > 1
),
title_artist_numeric_keys as (
  select
    title_key,
    coalesce(primary_artist_slugs, '') as primary_artist_slugs
  from track_enriched
  where title_key <> ''
    and coalesce(primary_artist_slugs, '') <> ''
  group by title_key, coalesce(primary_artist_slugs, '')
  having count(distinct id) > 1
     and bool_or(slug ~ '-[0-9]+$')
),
candidate_members as (
  select
    'provider_identity'::text as audit_type,
    p.provider_key || ':' || p.provider_track_id as audit_key,
    'high'::text as risk_bucket,
    0.99::numeric as confidence,
    'Same provider identity is attached to multiple registry tracks.'::text as reason,
    'Review canonical track and prepare safe provider/chart remap.'::text as recommended_action,
    l.track_id
  from provider_duplicate_keys p
  join public.registry_track_provider_links l
    on l.provider_key = p.provider_key
   and l.provider_track_id = p.provider_track_id

  union all

  select
    'apple_catalog_id'::text as audit_type,
    a.apple_music_catalog_id as audit_key,
    'high'::text as risk_bucket,
    0.97::numeric as confidence,
    'Same Apple Music catalog ID appears on multiple registry tracks.'::text as reason,
    'Review canonical track and prepare safe Apple Music duplicate repair.'::text as recommended_action,
    tb.id as track_id
  from apple_duplicate_keys a
  join track_base tb
    on tb.apple_music_catalog_id = a.apple_music_catalog_id

  union all

  select
    'isrc'::text as audit_type,
    i.isrc as audit_key,
    'high'::text as risk_bucket,
    0.95::numeric as confidence,
    'Same ISRC appears on multiple registry tracks.'::text as reason,
    'Review recording identity, then remap relationships if this is the same track.'::text as recommended_action,
    tb.id as track_id
  from isrc_duplicate_keys i
  join track_base tb
    on tb.isrc = i.isrc

  union all

  select
    'title_artist_numeric'::text as audit_type,
    t.title_key || ':' || t.primary_artist_slugs as audit_key,
    'medium'::text as risk_bucket,
    0.66::numeric as confidence,
    'Same normalized title and primary artist with at least one numeric-suffix slug.'::text as reason,
    'Manual review only. Numeric suffix alone is not enough evidence to merge.'::text as recommended_action,
    te.id as track_id
  from title_artist_numeric_keys t
  join track_enriched te
    on te.title_key = t.title_key
   and coalesce(te.primary_artist_slugs, '') = t.primary_artist_slugs
),
candidate_rollup as (
  select
    cm.audit_type,
    cm.audit_key,
    max(cm.risk_bucket) as risk_bucket,
    max(cm.confidence) as confidence,
    max(cm.reason) as reason,
    max(cm.recommended_action) as recommended_action,
    count(distinct cm.track_id) as track_count,
    sum(coalesce(te.chart_ref_count, 0)) as public_ref_count,
    jsonb_agg(
      jsonb_build_object(
        'id', te.id,
        'slug', te.slug,
        'title', te.title,
        'status', te.status,
        'isrc', te.isrc,
        'releaseId', te.release_id,
        'artworkUrl', te.artwork_url,
        'previewUrl', te.preview_url,
        'appleMusicCatalogId', te.apple_music_catalog_id,
        'primaryArtistSlugs', te.primary_artist_slugs,
        'primaryArtistNames', te.primary_artist_names,
        'allArtistSlugs', te.all_artist_slugs,
        'providerLinkCount', te.provider_link_count,
        'providers', te.providers,
        'chartRefCount', te.chart_ref_count,
        'createdAt', te.created_at,
        'updatedAt', te.updated_at
      )
      order by
        te.chart_ref_count desc,
        case te.status
          when 'active' then 1
          when 'needs_review' then 2
          when 'draft' then 3
          else 4
        end,
        te.updated_at desc nulls last,
        te.slug asc
    ) as tracks
  from candidate_members cm
  join track_enriched te on te.id = cm.track_id
  group by cm.audit_type, cm.audit_key
),
filtered as (
  select *
  from candidate_rollup
  where p_include_low_confidence
     or audit_type in ('provider_identity', 'apple_catalog_id', 'isrc')
     or public_ref_count > 0
  order by confidence desc, public_ref_count desc, track_count desc, audit_type asc, audit_key asc
  limit greatest(1, least(coalesce(p_limit, 200), 500))
)
select jsonb_build_object(
  'generatedAt', now(),
  'stats', jsonb_build_object(
    'totalCandidates', coalesce((select count(*) from filtered), 0),
    'highConfidence', coalesce((select count(*) from filtered where confidence >= 0.9), 0),
    'mediumConfidence', coalesce((select count(*) from filtered where confidence >= 0.6 and confidence < 0.9), 0),
    'publicRefs', coalesce((select sum(public_ref_count) from filtered), 0)
  ),
  'candidates', coalesce((
    select jsonb_agg(
      jsonb_build_object(
        'candidateId', md5(audit_type || ':' || audit_key),
        'entityKind', 'track',
        'auditType', audit_type,
        'auditKey', audit_key,
        'riskBucket', risk_bucket,
        'confidence', confidence,
        'reason', reason,
        'recommendedAction', recommended_action,
        'trackCount', track_count,
        'publicRefCount', public_ref_count,
        'tracks', tracks
      )
      order by confidence desc, public_ref_count desc, track_count desc, audit_type asc, audit_key asc
    )
    from filtered
  ), '[]'::jsonb)
)
where coalesce(public.current_user_has_capability('manage_registry'), false);
$_$;


ALTER FUNCTION "public"."admin_get_registry_track_duplicate_audit"("p_limit" integer, "p_include_low_confidence" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_get_registry_track_intake_enrichment"("p_suggestion_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'auth', 'public'
    AS $$
begin
  if auth.uid() is null then
    raise exception
      using errcode = '42501', message = 'Authentication is required.';
  end if;

  if not (
    public.current_user_is_administrator()
    or public.current_user_has_capability('manage_registry')
  ) then
    raise exception
      using errcode = '42501',
        message = 'Registry management permission is required.';
  end if;

  if not exists (
    select 1
    from public.registry_provider_track_suggestions suggestion
    where suggestion.id = p_suggestion_id
  ) then
    raise exception
      using errcode = 'P0002',
        message = 'Track Intake item does not exist.';
  end if;

  return jsonb_build_object(
    'suggestion_id', p_suggestion_id,
    'observations',
      coalesce(
        (
          select jsonb_agg(
            jsonb_build_object(
              'id', observation.id,
              'field_name', observation.field_name,
              'field_value', observation.field_value,
              'provider', observation.provider,
              'confidence_score', observation.confidence_score,
              'source_path', observation.source_path,
              'created_at', observation.created_at
            )
            order by
              observation.field_name,
              observation.created_at desc
          )
          from public.provider_field_observations observation
          where observation.provider_item_id =
              p_suggestion_id::text
            and observation.entity_type = 'track'
        ),
        '[]'::jsonb
      ),
    'accepted',
      coalesce(
        (
          select jsonb_object_agg(
            suggestion.field_name,
            suggestion.suggested_value
          )
          from public.registry_enrichment_suggestions suggestion
          where suggestion.registry_entity_type = 'track'
            and suggestion.registry_entity_id =
              p_suggestion_id::text
            and suggestion.decision_status = 'approved'
        ),
        '{}'::jsonb
      ),
    'provider_links',
      coalesce(
        (
          select jsonb_agg(
            jsonb_build_object(
              'provider', link.provider,
              'provider_entity_id', link.provider_entity_id,
              'provider_url', link.provider_url,
              'match_status', link.match_status,
              'confidence_score', link.confidence_score,
              'created_at', link.created_at
            )
            order by link.created_at desc
          )
          from public.provider_entity_links link
          where link.registry_entity_type = 'track'
            and link.registry_entity_id =
              p_suggestion_id::text
        ),
        '[]'::jsonb
      )
  );
end;
$$;


ALTER FUNCTION "public"."admin_get_registry_track_intake_enrichment"("p_suggestion_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_get_registry_track_intake_queue"("p_status" "text" DEFAULT 'needs_review'::"text", "p_limit" integer DEFAULT 100, "p_offset" integer DEFAULT 0, "p_suggestion_id" "uuid" DEFAULT NULL::"uuid", "p_playlist_item_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'auth', 'public', 'editorial'
    AS $$
declare
  v_status text :=
    lower(
      btrim(
        coalesce(
          p_status,
          'needs_review'
        )
      )
    );
  v_limit integer :=
    greatest(
      1,
      least(
        coalesce(
          p_limit,
          100
        ),
        250
      )
    );
  v_offset integer :=
    greatest(
      0,
      coalesce(
        p_offset,
        0
      )
    );
  v_total integer;
  v_rows jsonb;
begin
  if auth.uid() is null then
    raise exception
      using
        errcode = '42501',
        message = 'Authentication is required.';
  end if;

  if not (
    public.current_user_is_administrator()
    or public.current_user_has_capability(
      'manage_registry'
    )
  ) then
    raise exception
      using
        errcode = '42501',
        message = 'Registry management permission is required.';
  end if;

  if v_status not in (
    'needs_review',
    'rejected',
    'canonicalized',
    'all'
  ) then
    raise exception
      'Track Intake status filter is invalid.';
  end if;

  select count(*)::integer
  into v_total
  from public.registry_provider_track_suggestions suggestion
  where (
      v_status = 'all'
      or suggestion.status = v_status
    )
    and (
      p_suggestion_id is null
      or suggestion.id = p_suggestion_id
    )
    and (
      p_playlist_item_id is null
      or suggestion.source_playlist_item_id =
           p_playlist_item_id
    );

  select coalesce(
    jsonb_agg(
      queue_row.payload
      order by queue_row.created_at desc
    ),
    '[]'::jsonb
  )
  into v_rows
  from (
    select
      suggestion.created_at,
      jsonb_build_object(
        'suggestion_id',
          suggestion.id,
        'status',
          suggestion.status,
        'intake_origin',
          suggestion.intake_origin,
        'source_contribution_id',
          suggestion.source_contribution_id,
        'contribution_status',
          contribution.status,
        'contribution_payload',
          coalesce(
            contribution.payload,
            '{}'::jsonb
          ),
        'submitted_track_title',
          suggestion.submitted_track_title,
        'playlist_id',
          suggestion.source_playlist_id,
        'playlist_title',
          playlist.title,
        'playlist_item_id',
          suggestion.source_playlist_item_id,
        'playlist_position',
          item.position,
        'playlist_note',
          item.notes,
        'provider_key',
          suggestion.provider_key,
        'provider_object_id',
          suggestion.provider_object_id,
        'provider_url',
          suggestion.provider_url,
        'provider_title',
          suggestion.provider_title,
        'provider_release_title',
          suggestion.provider_release_title,
        'provider_artist_names',
          suggestion.provider_artist_names,
        'playback_kind',
          suggestion.playback_kind,
        'artwork_url',
          suggestion.validation_snapshot
            ->> 'artwork_url',
        'preview_url',
          suggestion.validation_snapshot
            ->> 'preview_url',
        'requested_by',
          suggestion.requested_by,
        'requested_by_name',
          requester.display_name,
        'created_at',
          suggestion.created_at,
        'reviewed_at',
          suggestion.reviewed_at,
        'review_note',
          suggestion.review_note,
        'canonical_track_id',
          suggestion.canonical_track_id,
        'canonical_track_title',
          canonical_track.title,
        'canonicalized_track_id',
          suggestion.canonicalized_track_id,
        'canonicalized_track_title',
          canonical_track.title,
        'artist_credits',
          coalesce(
            (
              select jsonb_agg(
                jsonb_build_object(
                  'credit_order',
                    credit.credit_order,
                  'credit_role',
                    credit.credit_role,
                  'resolution_mode',
                    credit.resolution_mode,
                  'registry_artist_id',
                    credit.registry_artist_id,
                  'observed_name',
                    credit.observed_name,
                  'display_name',
                    coalesce(
                      artist.display_name,
                      credit.observed_name
                    )
                )
                order by credit.credit_order
              )
              from public.registry_provider_track_suggestion_artists credit
              left join public.registry_artists artist
                on artist.id =
                     credit.registry_artist_id
              where credit.suggestion_id =
                    suggestion.id
            ),
            '[]'::jsonb
          )
      ) as payload
    from public.registry_provider_track_suggestions suggestion
    left join public.wk_playlists playlist
      on playlist.id =
           suggestion.source_playlist_id
    left join public.wk_playlist_items item
      on item.id =
           suggestion.source_playlist_item_id
    left join public.user_profiles requester
      on requester.user_id =
           suggestion.requested_by
    left join public.registry_tracks canonical_track
      on canonical_track.id =
           coalesce(
             suggestion.canonicalized_track_id,
             suggestion.canonical_track_id
           )
    left join public.community_contributions contribution
      on contribution.id =
           suggestion.source_contribution_id
    where (
        v_status = 'all'
        or suggestion.status = v_status
      )
      and (
        p_suggestion_id is null
        or suggestion.id = p_suggestion_id
      )
      and (
        p_playlist_item_id is null
        or suggestion.source_playlist_item_id =
             p_playlist_item_id
      )
    order by suggestion.created_at desc
    limit v_limit
    offset v_offset
  ) queue_row;

  return jsonb_build_object(
    'status',
      v_status,
    'total',
      v_total,
    'limit',
      v_limit,
    'offset',
      v_offset,
    'rows',
      v_rows
  );
end;
$$;


ALTER FUNCTION "public"."admin_get_registry_track_intake_queue"("p_status" "text", "p_limit" integer, "p_offset" integer, "p_suggestion_id" "uuid", "p_playlist_item_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_log_artist_resolution_event"("p_action" "text", "p_status" "text", "p_source_artist_id" "uuid" DEFAULT NULL::"uuid", "p_source_snapshot" "jsonb" DEFAULT '{}'::"jsonb", "p_replacement_artists" "jsonb" DEFAULT '[]'::"jsonb", "p_track_links" "jsonb" DEFAULT '[]'::"jsonb", "p_release_links" "jsonb" DEFAULT '[]'::"jsonb", "p_chart_entries" "jsonb" DEFAULT '[]'::"jsonb", "p_note" "text" DEFAULT NULL::"text", "p_error_message" "text" DEFAULT NULL::"text", "p_result" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_action text;
  v_status text;
  v_source_snapshot jsonb;
  v_event_id uuid;
  v_source_artist_id uuid;
  v_source_artist_slug text;
  v_source_artist_name text;
begin
  if not coalesce(public.current_user_has_capability('manage_registry'), false) then
    raise exception 'insufficient_privilege';
  end if;

  v_action := nullif(trim(coalesce(p_action, '')), '');
  v_status := nullif(trim(coalesce(p_status, '')), '');

  if v_action not in ('alias_merge', 'artist_merge', 'artist_decouple') then
    raise exception 'invalid_resolution_action';
  end if;

  if v_status not in ('success', 'failed', 'cancelled') then
    raise exception 'invalid_resolution_status';
  end if;

  v_source_snapshot := coalesce(p_source_snapshot, '{}'::jsonb);
  v_source_artist_id := coalesce(
    p_source_artist_id,
    nullif(v_source_snapshot->>'artist_id', '')::uuid
  );
  v_source_artist_slug := nullif(coalesce(
    v_source_snapshot->>'artist_slug',
    v_source_snapshot->>'slug'
  ), '');
  v_source_artist_name := nullif(coalesce(
    v_source_snapshot->>'display_name',
    v_source_snapshot->>'name'
  ), '');

  if v_source_artist_id is not null then
    select
      coalesce(v_source_artist_slug, a.slug),
      coalesce(v_source_artist_name, a.display_name)
    into v_source_artist_slug, v_source_artist_name
    from public.registry_artists a
    where a.id = v_source_artist_id
    limit 1;
  end if;

  insert into public.registry_artist_resolution_events (
    action,
    status,
    source_artist_id,
    source_artist_slug,
    source_artist_name,
    source_snapshot,
    replacement_artists,
    track_links,
    release_links,
    chart_entries,
    note,
    error_message,
    result
  )
  values (
    v_action,
    v_status,
    v_source_artist_id,
    v_source_artist_slug,
    v_source_artist_name,
    v_source_snapshot,
    coalesce(p_replacement_artists, '[]'::jsonb),
    coalesce(p_track_links, '[]'::jsonb),
    coalesce(p_release_links, '[]'::jsonb),
    coalesce(p_chart_entries, '[]'::jsonb),
    nullif(p_note, ''),
    nullif(p_error_message, ''),
    coalesce(p_result, '{}'::jsonb)
  )
  returning id into v_event_id;

  return jsonb_build_object('eventId', v_event_id);
end;
$$;


ALTER FUNCTION "public"."admin_log_artist_resolution_event"("p_action" "text", "p_status" "text", "p_source_artist_id" "uuid", "p_source_snapshot" "jsonb", "p_replacement_artists" "jsonb", "p_track_links" "jsonb", "p_release_links" "jsonb", "p_chart_entries" "jsonb", "p_note" "text", "p_error_message" "text", "p_result" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_merge_registry_artists"("p_source_artist_id" "uuid", "p_canonical_artist_id" "uuid", "p_note" "text" DEFAULT NULL::"text", "p_archive_source" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_source record;
  v_canonical record;
  v_alias_rows integer := 0;
  v_chart_rows integer := 0;
  v_track_rows integer := 0;
  v_release_rows integer := 0;
  v_track_meta_rows integer := 0;
  v_existing_alias_rows integer := 0;
begin
  if not coalesce(public.current_user_has_capability('manage_registry'), false) then
    raise exception 'insufficient_privilege';
  end if;

  if p_source_artist_id is null or p_canonical_artist_id is null then
    raise exception 'source_and_canonical_required';
  end if;

  if p_source_artist_id = p_canonical_artist_id then
    raise exception 'cannot_merge_artist_into_itself';
  end if;

  select id, slug, display_name, status, origin_iso2, public_image_url, metadata
  into v_source
  from public.registry_artists
  where id = p_source_artist_id
    and status in ('active', 'draft', 'needs_review', 'archived')
  limit 1;

  if v_source.id is null then
    raise exception 'source_artist_not_found';
  end if;

  select id, slug, display_name, status, origin_iso2, public_image_url, metadata
  into v_canonical
  from public.registry_artists
  where id = p_canonical_artist_id
    and status in ('active', 'draft', 'needs_review')
  limit 1;

  if v_canonical.id is null then
    raise exception 'canonical_artist_not_found';
  end if;

  update public.registry_artist_aliases
  set
    canonical_artist_id = v_canonical.id,
    alias_display_name = v_source.display_name,
    confidence = 100,
    source = 'similarity_match',
    notes = coalesce(nullif(p_note, ''), 'Manual registry artist merge.'),
    status = 'active'
  where lower(alias_slug) = lower(v_source.slug);

  get diagnostics v_alias_rows = row_count;

  if v_alias_rows = 0 then
    insert into public.registry_artist_aliases (
      alias_slug,
      canonical_artist_id,
      alias_display_name,
      confidence,
      source,
      notes,
      status
    )
    values (
      v_source.slug,
      v_canonical.id,
      v_source.display_name,
      100,
      'similarity_match',
      coalesce(nullif(p_note, ''), 'Manual registry artist merge.'),
      'active'
    );
    v_alias_rows := 1;
  end if;

  update public.registry_artist_aliases
  set
    canonical_artist_id = v_canonical.id,
    notes = coalesce(nullif(p_note, ''), notes, 'Manual registry artist merge.')
  where canonical_artist_id = v_source.id;

  get diagnostics v_existing_alias_rows = row_count;

  delete from public.registry_track_artists source_link
  using public.registry_track_artists canonical_link
  where source_link.artist_id = v_source.id
    and canonical_link.artist_id = v_canonical.id
    and canonical_link.track_id = source_link.track_id;

  update public.registry_track_artists
  set
    artist_id = v_canonical.id,
    artist_slug = v_canonical.slug,
    artist_name_text = coalesce(nullif(artist_name_text, ''), v_canonical.display_name),
    display_credit = coalesce(nullif(display_credit, ''), v_canonical.display_name),
    updated_at = now()
  where artist_id = v_source.id
     or lower(artist_slug) = lower(v_source.slug);

  get diagnostics v_track_rows = row_count;

  delete from public.registry_release_artists source_link
  using public.registry_release_artists canonical_link
  where source_link.artist_id = v_source.id
    and canonical_link.artist_id = v_canonical.id
    and canonical_link.release_id = source_link.release_id;

  update public.registry_release_artists
  set
    artist_id = v_canonical.id,
    artist_slug = v_canonical.slug,
    artist_name_text = coalesce(nullif(artist_name_text, ''), v_canonical.display_name),
    display_credit = coalesce(nullif(display_credit, ''), v_canonical.display_name),
    updated_at = now()
  where artist_id = v_source.id
     or lower(artist_slug) = lower(v_source.slug);

  get diagnostics v_release_rows = row_count;

  update public.wk_chart_entries_v2
  set
    artist_slug = v_canonical.slug,
    updated_at = now()
  where lower(artist_slug) = lower(v_source.slug);

  get diagnostics v_chart_rows = row_count;

  update public.registry_tracks
  set
    metadata = jsonb_set(
      coalesce(metadata, '{}'::jsonb),
      '{primary_artist_slug}',
      to_jsonb(v_canonical.slug),
      true
    ),
    updated_at = now()
  where metadata->>'primary_artist_slug' = v_source.slug;

  get diagnostics v_track_meta_rows = row_count;

  update public.registry_artists
  set
    origin_iso2 = coalesce(origin_iso2, v_source.origin_iso2),
    public_image_url = coalesce(public_image_url, v_source.public_image_url),
    metadata = coalesce(metadata, '{}'::jsonb)
      || jsonb_build_object(
        'merged_source_artist_id', v_source.id::text,
        'merged_source_artist_slug', v_source.slug,
        'merged_source_artist_name', v_source.display_name,
        'merged_at', now()
      ),
    updated_at = now()
  where id = v_canonical.id;

  if p_archive_source then
    update public.registry_artists
    set
      status = 'archived',
      metadata = coalesce(metadata, '{}'::jsonb)
        || jsonb_build_object(
          'merged_into_artist_id', v_canonical.id::text,
          'merged_into_artist_slug', v_canonical.slug,
          'merged_into_artist_name', v_canonical.display_name,
          'merged_at', now(),
          'merge_note', p_note
        ),
      updated_at = now()
    where id = v_source.id;
  else
    update public.registry_artists
    set
      metadata = coalesce(metadata, '{}'::jsonb)
        || jsonb_build_object(
          'merged_into_artist_id', v_canonical.id::text,
          'merged_into_artist_slug', v_canonical.slug,
          'merged_into_artist_name', v_canonical.display_name,
          'merged_at', now(),
          'merge_note', p_note
        ),
      updated_at = now()
    where id = v_source.id;
  end if;

  return jsonb_build_object(
    'sourceArtistId', v_source.id,
    'sourceSlug', v_source.slug,
    'sourceName', v_source.display_name,
    'canonicalArtistId', v_canonical.id,
    'canonicalSlug', v_canonical.slug,
    'canonicalName', v_canonical.display_name,
    'aliasRowsTouched', v_alias_rows,
    'existingAliasesRetargeted', v_existing_alias_rows,
    'trackArtistRowsUpdated', v_track_rows,
    'releaseArtistRowsUpdated', v_release_rows,
    'chartEntriesUpdated', v_chart_rows,
    'trackMetadataRowsUpdated', v_track_meta_rows,
    'sourceArchived', p_archive_source
  );
end;
$$;


ALTER FUNCTION "public"."admin_merge_registry_artists"("p_source_artist_id" "uuid", "p_canonical_artist_id" "uuid", "p_note" "text", "p_archive_source" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_preview_registry_track_duplicate_repair"("p_canonical_track_id" "uuid", "p_duplicate_track_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  v_duplicate_ids uuid[];
  v_canonical record;
  v_duplicate_count integer := 0;
  v_high_signal_count integer := 0;
  v_medium_signal_count integer := 0;
  v_chart_rows integer := 0;
  v_provider_rows integer := 0;
  v_release_rows integer := 0;
  v_release_rows_to_archive integer := 0;
  v_track_artist_rows integer := 0;
  v_track_artist_rows_to_archive integer := 0;
  v_confidence_bucket text := 'blocked';
  v_blockers text[] := '{}'::text[];
  v_preview jsonb;
begin
  if not coalesce(public.current_user_has_capability('manage_registry'), false) then
    raise exception 'insufficient_privilege';
  end if;

  if p_canonical_track_id is null then
    raise exception 'canonical_track_required';
  end if;

  v_duplicate_ids := array(
    select distinct x
    from unnest(coalesce(p_duplicate_track_ids, '{}'::uuid[])) as x
    where x is not null
      and x <> p_canonical_track_id
  );

  if coalesce(array_length(v_duplicate_ids, 1), 0) = 0 then
    raise exception 'duplicate_tracks_required';
  end if;

  select
    t.id,
    t.slug,
    t.title,
    t.status,
    t.isrc,
    t.release_id,
    t.artwork_url,
    t.preview_url,
    t.metadata,
    nullif(t.metadata->>'apple_music_catalog_id', '') as apple_music_catalog_id,
    public.wk_slugify_text(coalesce(t.title, '')) as title_key,
    (
      select string_agg(rta.artist_slug, ', ' order by rta.credit_order, rta.artist_slug)
      from public.registry_track_artists rta
      where rta.track_id = t.id
        and coalesce(rta.status, 'active') <> 'archived'
        and coalesce(rta.is_primary, false) = true
    ) as primary_artist_slugs
  into v_canonical
  from public.registry_tracks t
  where t.id = p_canonical_track_id
    and t.status in ('active', 'draft', 'needs_review')
  limit 1;

  if v_canonical.id is null then
    raise exception 'canonical_track_not_found_or_not_repairable';
  end if;

  select count(*)
  into v_duplicate_count
  from public.registry_tracks t
  where t.id = any(v_duplicate_ids)
    and t.status in ('active', 'draft', 'needs_review');

  if v_duplicate_count <> coalesce(array_length(v_duplicate_ids, 1), 0) then
    v_blockers := array_append(v_blockers, 'one_or_more_duplicate_tracks_not_found_or_not_repairable');
  end if;

  with duplicate_tracks as (
    select
      t.id,
      t.slug,
      t.title,
      t.status,
      t.isrc,
      t.metadata,
      nullif(t.metadata->>'apple_music_catalog_id', '') as apple_music_catalog_id,
      public.wk_slugify_text(coalesce(t.title, '')) as title_key,
      (
        select string_agg(rta.artist_slug, ', ' order by rta.credit_order, rta.artist_slug)
        from public.registry_track_artists rta
        where rta.track_id = t.id
          and coalesce(rta.status, 'active') <> 'archived'
          and coalesce(rta.is_primary, false) = true
      ) as primary_artist_slugs
    from public.registry_tracks t
    where t.id = any(v_duplicate_ids)
  )
  select
    count(*) filter (
      where (
        nullif(v_canonical.isrc, '') is not null
        and nullif(duplicate_tracks.isrc, '') is not null
        and v_canonical.isrc = duplicate_tracks.isrc
      )
      or (
        v_canonical.apple_music_catalog_id is not null
        and duplicate_tracks.apple_music_catalog_id is not null
        and v_canonical.apple_music_catalog_id = duplicate_tracks.apple_music_catalog_id
      )
      or exists (
        select 1
        from public.registry_track_provider_links cpl
        join public.registry_track_provider_links dpl
          on dpl.provider_key = cpl.provider_key
         and dpl.provider_track_id = cpl.provider_track_id
        where cpl.track_id = v_canonical.id
          and dpl.track_id = duplicate_tracks.id
      )
    ),
    count(*) filter (
      where public.wk_slugify_text(coalesce(v_canonical.title, '')) = duplicate_tracks.title_key
        and coalesce(v_canonical.primary_artist_slugs, '') = coalesce(duplicate_tracks.primary_artist_slugs, '')
        and (
          duplicate_tracks.slug ~ '-[0-9]+$'
          or v_canonical.slug ~ '-[0-9]+$'
        )
    )
  into v_high_signal_count, v_medium_signal_count
  from duplicate_tracks;

  if v_high_signal_count >= v_duplicate_count and v_duplicate_count > 0 then
    v_confidence_bucket := 'high';
  elsif (v_high_signal_count + v_medium_signal_count) >= v_duplicate_count and v_duplicate_count > 0 then
    v_confidence_bucket := 'medium';
  else
    v_confidence_bucket := 'blocked';
    v_blockers := array_append(v_blockers, 'not_enough_identity_evidence');
  end if;

  select count(*)
  into v_chart_rows
  from public.wk_chart_entries_v2 ce
  join public.registry_tracks d
    on d.id = any(v_duplicate_ids)
  where ce.canonical_track_id::text = d.id::text
     or ce.track_slug = d.slug;

  select count(*)
  into v_provider_rows
  from public.registry_track_provider_links l
  where l.track_id = any(v_duplicate_ids);

  select count(*)
  into v_release_rows
  from public.registry_release_tracks rrt
  where rrt.track_id = any(v_duplicate_ids)
    and coalesce(rrt.status, 'active') <> 'archived';

  select count(*)
  into v_release_rows_to_archive
  from public.registry_release_tracks bad
  where bad.track_id = any(v_duplicate_ids)
    and coalesce(bad.status, 'active') <> 'archived'
    and exists (
      select 1
      from public.registry_release_tracks good
      where good.release_id = bad.release_id
        and good.track_id = v_canonical.id
        and good.disc_number = bad.disc_number
        and coalesce(good.track_number, -1) = coalesce(bad.track_number, -1)
        and coalesce(good.status, 'active') <> 'archived'
    );

  select count(*)
  into v_track_artist_rows
  from public.registry_track_artists rta
  where rta.track_id = any(v_duplicate_ids)
    and coalesce(rta.status, 'active') <> 'archived';

  with ranked_bad as (
    select
      bad.id,
      row_number() over (
        partition by coalesce(lower(nullif(bad.artist_slug, '')), 'artist:' || coalesce(bad.artist_id::text, bad.id::text))
        order by
          coalesce(bad.is_primary, false) desc,
          coalesce(bad.is_featured, false) asc,
          bad.credit_order asc,
          bad.updated_at desc nulls last,
          bad.id asc
      ) as duplicate_rank,
      exists (
        select 1
        from public.registry_track_artists good
        where good.track_id = v_canonical.id
          and coalesce(good.status, 'active') <> 'archived'
          and (
            (
              nullif(bad.artist_slug, '') is not null
              and lower(coalesce(good.artist_slug, '')) = lower(bad.artist_slug)
            )
            or (
              nullif(bad.artist_slug, '') is null
              and bad.artist_id is not null
              and good.artist_id = bad.artist_id
            )
          )
      ) as canonical_already_has_credit
    from public.registry_track_artists bad
    where bad.track_id = any(v_duplicate_ids)
      and coalesce(bad.status, 'active') <> 'archived'
  )
  select count(*)
  into v_track_artist_rows_to_archive
  from ranked_bad
  where canonical_already_has_credit
     or duplicate_rank > 1;

  with duplicate_tracks as (
    select
      t.id,
      t.slug,
      t.title,
      t.status,
      t.isrc,
      t.release_id,
      t.artwork_url,
      t.preview_url,
      nullif(t.metadata->>'apple_music_catalog_id', '') as apple_music_catalog_id,
      (
        select string_agg(rta.artist_slug, ', ' order by rta.credit_order, rta.artist_slug)
        from public.registry_track_artists rta
        where rta.track_id = t.id
          and coalesce(rta.status, 'active') <> 'archived'
          and coalesce(rta.is_primary, false) = true
      ) as primary_artist_slugs
    from public.registry_tracks t
    where t.id = any(v_duplicate_ids)
  ),
  chart_rows as (
    select
      ce.id,
      ce.edition_id,
      ce.rank,
      ce.track_slug,
      ce.track_title,
      ce.artist_slug,
      ce.artist_name,
      ce.canonical_track_id
    from public.wk_chart_entries_v2 ce
    join duplicate_tracks d
      on ce.canonical_track_id::text = d.id::text
      or ce.track_slug = d.slug
    order by ce.edition_id, ce.rank nulls last, ce.id
    limit 50
  ),
  provider_rows as (
    select
      l.id,
      l.track_id,
      d.slug as duplicate_slug,
      l.provider_key,
      l.provider_track_id,
      l.provider_release_id,
      l.isrc,
      l.match_status,
      l.match_confidence
    from public.registry_track_provider_links l
    join duplicate_tracks d on d.id = l.track_id
    order by l.provider_key, l.provider_track_id
    limit 50
  ),
  release_rows as (
    select
      rrt.id,
      rrt.release_id,
      rr.slug as release_slug,
      rr.title as release_title,
      rrt.track_id,
      d.slug as duplicate_slug,
      rrt.disc_number,
      rrt.track_number,
      rrt.status,
      exists (
        select 1
        from public.registry_release_tracks good
        where good.release_id = rrt.release_id
          and good.track_id = v_canonical.id
          and good.disc_number = rrt.disc_number
          and coalesce(good.track_number, -1) = coalesce(rrt.track_number, -1)
          and coalesce(good.status, 'active') <> 'archived'
      ) as will_archive_instead_of_move
    from public.registry_release_tracks rrt
    join duplicate_tracks d on d.id = rrt.track_id
    left join public.registry_releases rr on rr.id = rrt.release_id
    where coalesce(rrt.status, 'active') <> 'archived'
    order by rr.title, rrt.disc_number, rrt.track_number
    limit 50
  )
  select jsonb_build_object(
    'canonicalTrack', jsonb_build_object(
      'id', v_canonical.id,
      'slug', v_canonical.slug,
      'title', v_canonical.title,
      'status', v_canonical.status,
      'isrc', v_canonical.isrc,
      'releaseId', v_canonical.release_id,
      'artworkUrl', v_canonical.artwork_url,
      'previewUrl', v_canonical.preview_url,
      'appleMusicCatalogId', v_canonical.apple_music_catalog_id,
      'primaryArtistSlugs', v_canonical.primary_artist_slugs
    ),
    'duplicateTracks', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', id,
          'slug', slug,
          'title', title,
          'status', status,
          'isrc', isrc,
          'releaseId', release_id,
          'artworkUrl', artwork_url,
          'previewUrl', preview_url,
          'appleMusicCatalogId', apple_music_catalog_id,
          'primaryArtistSlugs', primary_artist_slugs
        )
        order by slug
      )
      from duplicate_tracks
    ), '[]'::jsonb),
    'confidenceBucket', v_confidence_bucket,
    'blockers', to_jsonb(v_blockers),
    'counts', jsonb_build_object(
      'duplicateTracks', v_duplicate_count,
      'highIdentityMatches', v_high_signal_count,
      'mediumIdentityMatches', v_medium_signal_count,
      'chartRowsToMove', v_chart_rows,
      'providerLinksToMove', v_provider_rows,
      'releaseTrackRowsTouched', v_release_rows,
      'releaseTrackRowsToArchive', v_release_rows_to_archive,
      'trackArtistCreditsToMove', greatest(v_track_artist_rows - v_track_artist_rows_to_archive, 0),
      'trackArtistCreditsToArchive', v_track_artist_rows_to_archive
    ),
    'chartRows', coalesce((select jsonb_agg(to_jsonb(chart_rows)) from chart_rows), '[]'::jsonb),
    'providerLinks', coalesce((select jsonb_agg(to_jsonb(provider_rows)) from provider_rows), '[]'::jsonb),
    'releaseTrackRows', coalesce((select jsonb_agg(to_jsonb(release_rows)) from release_rows), '[]'::jsonb)
  )
  into v_preview;

  return v_preview;
end;
$_$;


ALTER FUNCTION "public"."admin_preview_registry_track_duplicate_repair"("p_canonical_track_id" "uuid", "p_duplicate_track_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_record_registry_track_intake_provider_evidence"("p_suggestion_id" "uuid", "p_provider" "text", "p_provider_entity_id" "text", "p_provider_url" "text", "p_fields" "jsonb", "p_raw_payload" "jsonb" DEFAULT '{}'::"jsonb", "p_confidence" numeric DEFAULT 0.9000) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'auth', 'public'
    AS $$
declare
  v_provider text := lower(btrim(coalesce(p_provider, '')));
  v_confidence numeric := greatest(
    0,
    least(coalesce(p_confidence, 0.9000), 1)
  );
  v_field record;
  v_field_value text;
  v_count integer := 0;
  v_allowed constant text[] := array[
    'title',
    'artist_names',
    'release_title',
    'isrc',
    'duration_ms',
    'track_artwork_url',
    'release_artwork_url',
    'preview_url',
    'release_date',
    'release_date_precision',
    'label_name',
    'imprint_name',
    'genre',
    'track_number',
    'disc_number',
    'explicit',
    'provider_url',
    'upc',
    'copyright_text'
  ];
begin
  if auth.uid() is null then
    raise exception
      using errcode = '42501', message = 'Authentication is required.';
  end if;

  if not (
    public.current_user_is_administrator()
    or public.current_user_has_capability('manage_registry')
  ) then
    raise exception
      using errcode = '42501',
        message = 'Registry management permission is required.';
  end if;

  if not exists (
    select 1
    from public.registry_provider_track_suggestions suggestion
    where suggestion.id = p_suggestion_id
  ) then
    raise exception
      using errcode = 'P0002',
        message = 'Track Intake item does not exist.';
  end if;

  if not exists (
    select 1
    from public.registry_provider_track_suggestions suggestion
    where suggestion.id = p_suggestion_id
      and suggestion.status = 'needs_review'
  ) then
    raise exception
      'Only Track Intake items awaiting review can add provider evidence.';
  end if;

  if v_provider = ''
     or nullif(btrim(p_provider_entity_id), '') is null
  then
    raise exception
      'Provider and provider entity ID are required.';
  end if;

  if p_fields is null or jsonb_typeof(p_fields) <> 'object' then
    raise exception
      'Provider enrichment fields must be a JSON object.';
  end if;

  if not exists (
    select 1
    from public.provider_entity_links link
    where link.registry_entity_type = 'track'
      and link.registry_entity_id = p_suggestion_id::text
      and link.provider = v_provider
      and link.provider_entity_id = btrim(p_provider_entity_id)
  ) then
    insert into public.provider_entity_links (
      registry_entity_type,
      registry_entity_id,
      provider,
      provider_entity_id,
      provider_url,
      match_status,
      confidence_score,
      created_at,
      updated_at
    )
    values (
      'track',
      p_suggestion_id::text,
      v_provider,
      btrim(p_provider_entity_id),
      nullif(btrim(p_provider_url), ''),
      'candidate',
      v_confidence,
      now(),
      now()
    );
  end if;

  for v_field in
    select entry.key, entry.value
    from jsonb_each(p_fields) entry
  loop
    if not (v_field.key = any(v_allowed)) then
      raise exception
        'Unsupported Track Intake enrichment field: %',
        v_field.key;
    end if;

    if v_field.value = 'null'::jsonb then
      continue;
    end if;

    v_field_value :=
      case jsonb_typeof(v_field.value)
        when 'string' then v_field.value #>> '{}'
        else v_field.value::text
      end;

    if nullif(btrim(v_field_value), '') is null then
      continue;
    end if;

    insert into public.provider_field_observations (
      provider_item_id,
      entity_type,
      field_name,
      field_value,
      provider,
      confidence_score,
      source_path,
      raw_payload,
      created_at
    )
    values (
      p_suggestion_id::text,
      'track',
      v_field.key,
      v_field_value,
      v_provider,
      v_confidence,
      'track_intake.provider_inspect',
      coalesce(p_raw_payload, '{}'::jsonb),
      now()
    );

    v_count := v_count + 1;
  end loop;

  return jsonb_build_object(
    'suggestion_id', p_suggestion_id,
    'provider', v_provider,
    'provider_entity_id', btrim(p_provider_entity_id),
    'observation_count', v_count
  );
end;
$$;


ALTER FUNCTION "public"."admin_record_registry_track_intake_provider_evidence"("p_suggestion_id" "uuid", "p_provider" "text", "p_provider_entity_id" "text", "p_provider_url" "text", "p_fields" "jsonb", "p_raw_payload" "jsonb", "p_confidence" numeric) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_record_registry_track_intake_provider_evidence"("p_suggestion_id" "uuid", "p_provider" "text", "p_provider_entity_id" "text", "p_provider_url" "text", "p_fields" "jsonb", "p_raw_payload" "jsonb", "p_confidence" numeric) IS 'Stages provider inspection as evidence. New provider identities are candidates until an editor explicitly selects one.';



CREATE OR REPLACE FUNCTION "public"."admin_refresh_signal_os_rollups"("p_start_date" "date" DEFAULT (CURRENT_DATE - 30), "p_end_date" "date" DEFAULT CURRENT_DATE) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  v_start date := p_start_date;
  v_end date := p_end_date;
  v_entity_rows integer := 0;
  v_score_rows integer := 0;
  v_search_rows integer := 0;
  v_journey_rows integer := 0;
  v_opportunity_rows integer := 0;
  v_jwt_role text := coalesce(
    current_setting('request.jwt.claim.role', true),
    current_setting('role', true),
    ''
  );
begin
  if session_user not in ('postgres', 'service_role', 'supabase_admin')
    and v_jwt_role <> 'service_role'
    and not public.current_user_has_capability('manage_analytics')
    and not public.current_user_has_capability('manage_registry') then
    raise exception 'insufficient_privilege';
  end if;

  delete from public.signal_os_entity_daily_metrics
  where metric_date between v_start and v_end;

  delete from public.signal_os_entity_signal_scores
  where score_date between v_start and v_end;

  delete from public.signal_os_journey_edges_daily
  where metric_date between v_start and v_end;

  delete from public.signal_os_search_demand_gaps
  where metric_date between v_start and v_end;

  delete from public.signal_os_content_opportunities
  where opportunity_date between v_start and v_end
    and status = 'open'
    and opportunity_type in ('rising_entity', 'search_gap', 'page_fix');

  insert into public.signal_os_entity_daily_metrics (
    metric_date,
    entity_type,
    entity_slug,
    entity_title,
    page_path,
    page_views,
    unique_sessions,
    share_events,
    share_copy_events,
    share_click_events,
    newsletter_events,
    playback_events,
    video_events,
    scroll_events,
    search_mentions,
    referrer_domains,
    first_seen_at,
    last_seen_at,
    sample_context,
    updated_at
  )
  with normalized as (
    select
      date(created_at) as metric_date,
      coalesce(
        nullif(entity_type, ''),
        nullif(context->>'entity_type', ''),
        nullif(context->>'entityType', ''),
        nullif(page_type, ''),
        'page'
      ) as entity_type,
      coalesce(
        nullif(entity_slug, ''),
        nullif(context->>'entity_slug', ''),
        nullif(context->>'entitySlug', ''),
        nullif(context->>'target_slug', ''),
        public.signal_os_slug_from_path(coalesce(context->>'target_url', page_url))
      ) as entity_slug,
      coalesce(
        nullif(context->>'target_title', ''),
        nullif(context->>'entity_title', ''),
        nullif(context->>'entityTitle', ''),
        nullif(context->>'share_title', '')
      ) as entity_title,
      public.signal_os_path_from_url(coalesce(context->>'target_url', page_url)) as page_path,
      event_name,
      session_id,
      referrer,
      created_at,
      coalesce(context, '{}'::jsonb) as context
    from public.analytics_events
    where created_at >= v_start
      and created_at < (v_end + 1)
  ),
  filtered as (
    select *
    from normalized
    where entity_slug is not null
      and entity_slug <> ''
      and entity_type not in ('admin', 'auth', 'settings', 'profile')
      and page_path not like '/admin%'
      and page_path not like '/auth%'
      and page_path not like '/settings%'
      and page_path not like '/profile%'
      and page_path not like '/preview%'
  )
  select
    metric_date,
    entity_type,
    entity_slug,
    max(entity_title) filter (where entity_title is not null) as entity_title,
    max(page_path) as page_path,
    count(*) filter (where event_name = 'page_view')::integer as page_views,
    count(distinct session_id)::integer as unique_sessions,
    count(*) filter (where event_name in ('share_click', 'share_copy'))::integer as share_events,
    count(*) filter (where event_name = 'share_copy')::integer as share_copy_events,
    count(*) filter (where event_name = 'share_click')::integer as share_click_events,
    count(*) filter (where event_name in ('newsletter_signup', 'briefing_subscribe'))::integer as newsletter_events,
    count(*) filter (where event_name = 'player_play')::integer as playback_events,
    count(*) filter (where event_name = 'video_play')::integer as video_events,
    count(*) filter (where event_name = 'scroll_depth')::integer as scroll_events,
    count(*) filter (where event_name = 'search_query')::integer as search_mentions,
    count(distinct nullif(regexp_replace(coalesce(referrer, ''), '^https?://([^/]+).*$', '\1'), ''))::integer as referrer_domains,
    min(created_at) as first_seen_at,
    max(created_at) as last_seen_at,
    coalesce((array_agg(context order by created_at desc))[1], '{}'::jsonb) as sample_context,
    now()
  from filtered
  group by metric_date, entity_type, entity_slug;

  get diagnostics v_entity_rows = row_count;

  delete from public.signal_os_entity_daily_metrics
  where metric_date between v_start and v_end
    and (
      entity_type not in ('artist', 'track', 'release', 'article', 'guide', 'chart', 'chart_edition', 'genre', 'label', 'author')
      or entity_slug ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      or page_path = '/'
      or page_path like '/admin%'
      or page_path like '/auth%'
      or page_path like '/settings%'
      or page_path like '/profile%'
      or page_path like '/preview%'
      or page_path like '/search%'
      or page_path like '/contact%'
      or page_path like '/about%'
      or page_path like '/privacy%'
      or page_path like '/terms%'
      or page_path like '/faqs%'
    );

  select count(*)::integer
  into v_entity_rows
  from public.signal_os_entity_daily_metrics
  where metric_date between v_start and v_end;

  insert into public.signal_os_entity_signal_scores (
    score_date,
    entity_type,
    entity_slug,
    entity_title,
    page_path,
    signal_score,
    signal_label,
    page_views,
    unique_sessions,
    share_events,
    search_mentions,
    newsletter_events,
    playback_events,
    referrer_domains,
    explanation,
    recommended_action,
    evidence,
    updated_at
  )
  select
    metric_date as score_date,
    entity_type,
    entity_slug,
    entity_title,
    page_path,
    least(100, greatest(0,
      page_views * 4
      + unique_sessions * 7
      + share_events * 16
      + search_mentions * 10
      + newsletter_events * 20
      + playback_events * 12
      + video_events * 8
      + referrer_domains * 6
    ))::integer as signal_score,
    public.signal_os_label_for_score(least(100, greatest(0,
      page_views * 4
      + unique_sessions * 7
      + share_events * 16
      + search_mentions * 10
      + newsletter_events * 20
      + playback_events * 12
      + video_events * 8
      + referrer_domains * 6
    ))::integer) as signal_label,
    page_views,
    unique_sessions,
    share_events,
    search_mentions,
    newsletter_events,
    playback_events,
    referrer_domains,
    concat_ws(
      ', ',
      case when page_views > 0 then page_views || ' page views' end,
      case when unique_sessions > 0 then unique_sessions || ' sessions' end,
      case when share_events > 0 then share_events || ' shares' end,
      case when search_mentions > 0 then search_mentions || ' search mentions' end,
      case when newsletter_events > 0 then newsletter_events || ' newsletter events' end,
      case when playback_events > 0 then playback_events || ' plays' end
    ) as explanation,
    case
      when share_events > 0 then 'Create or boost a tracked campaign around this signal.'
      when search_mentions > 0 then 'Turn this demand into search-friendly content.'
      when playback_events > 0 then 'Check track context, chart movement, and artist page links.'
      when newsletter_events > 0 then 'Feature this in the next relevant briefing.'
      else 'Open the entity and decide the next editorial move.'
    end as recommended_action,
    jsonb_build_array(
      jsonb_build_object('label', 'Page views', 'value', page_views),
      jsonb_build_object('label', 'Sessions', 'value', unique_sessions),
      jsonb_build_object('label', 'Shares', 'value', share_events),
      jsonb_build_object('label', 'Search mentions', 'value', search_mentions),
      jsonb_build_object('label', 'Newsletter events', 'value', newsletter_events),
      jsonb_build_object('label', 'Playback events', 'value', playback_events)
    ) as evidence,
    now()
  from public.signal_os_entity_daily_metrics
  where metric_date between v_start and v_end;

  get diagnostics v_score_rows = row_count;

  delete from public.signal_os_entity_signal_scores
  where score_date between v_start and v_end
    and (
      entity_type not in ('artist', 'track', 'release', 'article', 'guide', 'chart', 'chart_edition', 'genre', 'label', 'author')
      or entity_slug ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      or page_path = '/'
      or page_path like '/admin%'
      or page_path like '/auth%'
      or page_path like '/settings%'
      or page_path like '/profile%'
      or page_path like '/preview%'
      or page_path like '/search%'
      or page_path like '/contact%'
      or page_path like '/about%'
      or page_path like '/privacy%'
      or page_path like '/terms%'
      or page_path like '/faqs%'
    );

  select count(*)::integer
  into v_score_rows
  from public.signal_os_entity_signal_scores
  where score_date between v_start and v_end;

  insert into public.signal_os_search_demand_gaps (
    metric_date,
    query,
    searches,
    unique_sessions,
    zero_result_events,
    matched_entity_type,
    matched_entity_slug,
    opportunity_score,
    recommended_action,
    sample_context,
    updated_at
  )
  with search_events as (
    select
      date(created_at) as metric_date,
      lower(trim(coalesce(context->>'search_query', context->>'query', ''))) as query,
      session_id,
      coalesce((context->>'results_count')::integer, null) as results_count,
      coalesce(context->>'entity_type', entity_type) as matched_entity_type,
      coalesce(context->>'entity_slug', entity_slug) as matched_entity_slug,
      coalesce(context, '{}'::jsonb) as context,
      created_at
    from public.analytics_events
    where created_at >= v_start
      and created_at < (v_end + 1)
      and event_name = 'search_query'
  )
  select
    metric_date,
    query,
    count(*)::integer as searches,
    count(distinct session_id)::integer as unique_sessions,
    count(*) filter (where results_count = 0)::integer as zero_result_events,
    max(matched_entity_type) filter (where matched_entity_type is not null),
    max(matched_entity_slug) filter (where matched_entity_slug is not null),
    least(100, count(*) * 12 + count(*) filter (where results_count = 0) * 20)::integer as opportunity_score,
    case
      when count(*) filter (where results_count = 0) > 0 then 'Fix this demand gap: ingest entity, add alias, write content, or improve search mapping.'
      else 'Refresh the best answer and add stronger entity links.'
    end,
    coalesce((array_agg(context order by created_at desc))[1], '{}'::jsonb),
    now()
  from search_events
  where query <> ''
  group by metric_date, query;

  get diagnostics v_search_rows = row_count;

  insert into public.signal_os_journey_edges_daily (
    metric_date,
    from_type,
    from_slug,
    from_title,
    from_path,
    to_type,
    to_slug,
    to_title,
    to_path,
    sessions,
    transitions,
    updated_at
  )
  with page_events as (
    select
      date(created_at) as metric_date,
      session_id,
      created_at,
      coalesce(nullif(entity_type, ''), nullif(context->>'entity_type', ''), nullif(context->>'entityType', ''), nullif(page_type, ''), 'page') as entity_type,
      coalesce(nullif(entity_slug, ''), nullif(context->>'entity_slug', ''), nullif(context->>'entitySlug', ''), public.signal_os_slug_from_path(page_url)) as entity_slug,
      coalesce(nullif(context->>'target_title', ''), nullif(context->>'entity_title', ''), nullif(context->>'share_title', '')) as entity_title,
      public.signal_os_path_from_url(page_url) as page_path,
      lead(coalesce(nullif(entity_type, ''), nullif(context->>'entity_type', ''), nullif(context->>'entityType', ''), nullif(page_type, ''), 'page')) over (partition by session_id, date(created_at) order by created_at) as next_type,
      lead(coalesce(nullif(entity_slug, ''), nullif(context->>'entity_slug', ''), nullif(context->>'entitySlug', ''), public.signal_os_slug_from_path(page_url))) over (partition by session_id, date(created_at) order by created_at) as next_slug,
      lead(coalesce(nullif(context->>'target_title', ''), nullif(context->>'entity_title', ''), nullif(context->>'share_title', ''))) over (partition by session_id, date(created_at) order by created_at) as next_title,
      lead(public.signal_os_path_from_url(page_url)) over (partition by session_id, date(created_at) order by created_at) as next_path
    from public.analytics_events
    where created_at >= v_start
      and created_at < (v_end + 1)
      and event_name = 'page_view'
      and session_id is not null
  )
  select
    metric_date,
    entity_type as from_type,
    entity_slug as from_slug,
    max(entity_title) as from_title,
    max(page_path) as from_path,
    next_type as to_type,
    next_slug as to_slug,
    max(next_title) as to_title,
    max(next_path) as to_path,
    count(distinct session_id)::integer as sessions,
    count(*)::integer as transitions,
    now()
  from page_events
  where entity_slug is not null
    and next_slug is not null
    and entity_slug <> next_slug
    and page_path not like '/admin%'
    and page_path not like '/preview%'
    and next_path not like '/admin%'
    and next_path not like '/preview%'
  group by metric_date, entity_type, entity_slug, next_type, next_slug;

  get diagnostics v_journey_rows = row_count;

  delete from public.signal_os_journey_edges_daily
  where metric_date between v_start and v_end
    and (
      from_type not in ('artist', 'track', 'release', 'article', 'guide', 'chart', 'chart_edition', 'genre', 'label', 'author')
      or to_type not in ('artist', 'track', 'release', 'article', 'guide', 'chart', 'chart_edition', 'genre', 'label', 'author')
      or from_slug ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      or to_slug ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      or from_path = '/'
      or to_path = '/'
      or from_path like '/admin%'
      or to_path like '/admin%'
      or from_path like '/auth%'
      or to_path like '/auth%'
      or from_path like '/settings%'
      or to_path like '/settings%'
      or from_path like '/profile%'
      or to_path like '/profile%'
      or from_path like '/preview%'
      or to_path like '/preview%'
      or from_path like '/search%'
      or to_path like '/search%'
      or from_path like '/contact%'
      or to_path like '/contact%'
      or from_path like '/about%'
      or to_path like '/about%'
      or from_path like '/privacy%'
      or to_path like '/privacy%'
      or from_path like '/terms%'
      or to_path like '/terms%'
      or from_path like '/faqs%'
      or to_path like '/faqs%'
    );

  select count(*)::integer
  into v_journey_rows
  from public.signal_os_journey_edges_daily
  where metric_date between v_start and v_end;

  insert into public.signal_os_content_opportunities (
    opportunity_date,
    opportunity_type,
    entity_type,
    entity_slug,
    entity_title,
    query,
    page_path,
    opportunity_score,
    title,
    reason,
    recommended_action,
    evidence,
    status,
    updated_at
  )
  select
    score_date,
    'rising_entity',
    entity_type,
    entity_slug,
    entity_title,
    null,
    page_path,
    signal_score,
    'Lean into ' || coalesce(entity_title, replace(entity_slug, '-', ' ')),
    signal_label || ' signal: ' || coalesce(explanation, 'activity is moving.'),
    recommended_action,
    evidence,
    'open',
    now()
  from public.signal_os_entity_signal_scores
  where score_date between v_start and v_end
    and signal_score >= 50
  order by signal_score desc
  limit 50;

  insert into public.signal_os_content_opportunities (
    opportunity_date,
    opportunity_type,
    query,
    opportunity_score,
    title,
    reason,
    recommended_action,
    evidence,
    status,
    updated_at
  )
  select
    metric_date,
    'search_gap',
    query,
    opportunity_score,
    'Fix search demand for "' || query || '"',
    searches || ' searches' || case when zero_result_events > 0 then ', including zero-result events.' else '.' end,
    recommended_action,
    jsonb_build_array(
      jsonb_build_object('label', 'Searches', 'value', searches),
      jsonb_build_object('label', 'Sessions', 'value', unique_sessions),
      jsonb_build_object('label', 'Zero-result events', 'value', zero_result_events)
    ),
    'open',
    now()
  from public.signal_os_search_demand_gaps
  where metric_date between v_start and v_end
    and opportunity_score >= 25
  order by opportunity_score desc
  limit 50;

  select count(*)::integer
  into v_opportunity_rows
  from public.signal_os_content_opportunities
  where opportunity_date between v_start and v_end
    and status = 'open';

  return jsonb_build_object(
    'ok', true,
    'startDate', v_start,
    'endDate', v_end,
    'entityMetricRows', v_entity_rows,
    'scoreRows', v_score_rows,
    'searchGapRows', v_search_rows,
    'journeyRows', v_journey_rows,
    'opportunityRows', v_opportunity_rows
  );
end;
$_$;


ALTER FUNCTION "public"."admin_refresh_signal_os_rollups"("p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_reject_registry_track_intake"("p_suggestion_id" "uuid", "p_review_note" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'auth', 'public'
    AS $$
declare
  v_suggestion public.registry_provider_track_suggestions%rowtype;
begin
  if auth.uid() is null then
    raise exception
      using errcode = '42501', message = 'Authentication is required.';
  end if;

  if not (
    public.current_user_is_administrator()
    or public.current_user_has_capability('manage_registry')
  ) then
    raise exception
      using errcode = '42501', message = 'Registry management permission is required.';
  end if;

  if nullif(btrim(p_review_note), '') is null then
    raise exception
      'A rejection reason is required.';
  end if;

  select suggestion.*
  into v_suggestion
  from public.registry_provider_track_suggestions suggestion
  where suggestion.id = p_suggestion_id
  for update;

  if not found then
    raise exception
      using errcode = 'P0002', message = 'Track Intake item does not exist.';
  end if;

  if v_suggestion.status <> 'needs_review' then
    raise exception
      'Only Track Intake items awaiting review can be rejected.';
  end if;

  update public.registry_provider_track_suggestions suggestion
  set
    status = 'rejected',
    reviewed_by = auth.uid(),
    reviewed_at = now(),
    review_note = btrim(p_review_note)
  where suggestion.id = p_suggestion_id;

  if v_suggestion.source_playlist_item_id is not null then
    update public.wk_playlist_items item
    set
      match_status = 'rejected',
      normalization_payload =
        coalesce(item.normalization_payload, '{}'::jsonb)
        || jsonb_build_object(
          'registry_intake_status', 'rejected'
        )
    where item.id = v_suggestion.source_playlist_item_id
      and item.lifecycle_state = 'active';

    update public.wk_playlists playlist
    set authority_revision = playlist.authority_revision + 1
    where playlist.id = v_suggestion.source_playlist_id;
  end if;

  return jsonb_build_object(
    'suggestion_id', p_suggestion_id,
    'playlist_id', v_suggestion.source_playlist_id,
    'playlist_item_id', v_suggestion.source_playlist_item_id,
    'status', 'rejected',
    'review_note', btrim(p_review_note)
  );
end;
$$;


ALTER FUNCTION "public"."admin_reject_registry_track_intake"("p_suggestion_id" "uuid", "p_review_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_resolve_chart_artist_alias"("p_alias_slug" "text", "p_canonical_artist_id" "uuid", "p_alias_display_name" "text" DEFAULT NULL::"text", "p_apply_to_existing" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_alias_slug text;
  v_canonical record;
  v_alias_rows integer := 0;
  v_chart_rows integer := 0;
  v_track_artist_rows integer := 0;
  v_duplicate_artist_rows integer := 0;
begin
  if not (
    coalesce(auth.role(), '') = 'service_role'
    or coalesce(public.current_user_has_capability('manage_registry'), false)
    or coalesce(public.current_user_has_capability('publish_charts'), false)
  ) then
    raise exception 'insufficient_privilege';
  end if;

  v_alias_slug := public.wk_slugify_text(p_alias_slug);

  if v_alias_slug = '' then
    raise exception 'alias_slug_required';
  end if;

  select id, slug, display_name
  into v_canonical
  from public.registry_artists
  where id = p_canonical_artist_id
    and status = 'active'
  limit 1;

  if v_canonical.id is null then
    raise exception 'canonical_active_artist_not_found';
  end if;

  update public.registry_artist_aliases a
  set
    canonical_artist_id = v_canonical.id,
    alias_display_name = coalesce(nullif(p_alias_display_name, ''), p_alias_slug),
    confidence = 100,
    source = 'similarity_match',
    notes = 'Chart registry reconciliation: alias resolves to canonical active artist.',
    status = 'active'
  where lower(a.alias_slug) = v_alias_slug;

  get diagnostics v_alias_rows = row_count;

  if v_alias_rows = 0 then
    insert into public.registry_artist_aliases (
      alias_slug,
      canonical_artist_id,
      alias_display_name,
      confidence,
      source,
      notes,
      status
    )
    values (
      v_alias_slug,
      v_canonical.id,
      coalesce(nullif(p_alias_display_name, ''), p_alias_slug),
      100,
      'similarity_match',
      'Chart registry reconciliation: alias resolves to canonical active artist.',
      'active'
    );
    v_alias_rows := 1;
  end if;

  if p_apply_to_existing then
    update public.wk_chart_entries_v2
    set artist_slug = v_canonical.slug
    where public.wk_slugify_text(artist_slug) = v_alias_slug;

    get diagnostics v_chart_rows = row_count;

    update public.registry_track_artists
    set
      artist_id = v_canonical.id,
      artist_slug = v_canonical.slug,
      artist_name_text = coalesce(nullif(artist_name_text, ''), v_canonical.display_name),
      display_credit = coalesce(nullif(display_credit, ''), v_canonical.display_name)
    where public.wk_slugify_text(artist_slug) = v_alias_slug;

    get diagnostics v_track_artist_rows = row_count;
  end if;

  update public.registry_artists
  set metadata = coalesce(metadata, '{}'::jsonb)
    || jsonb_build_object(
      'duplicate_of_artist_id', v_canonical.id::text,
      'duplicate_of_artist_slug', v_canonical.slug,
      'resolved_alias_slug', v_alias_slug,
      'resolved_alias_at', now()
    )
  where lower(slug) = v_alias_slug
    and id <> v_canonical.id
    and status <> 'active';

  get diagnostics v_duplicate_artist_rows = row_count;

  return jsonb_build_object(
    'aliasSlug', v_alias_slug,
    'canonicalArtistId', v_canonical.id,
    'canonicalSlug', v_canonical.slug,
    'canonicalDisplayName', v_canonical.display_name,
    'aliasRowsTouched', v_alias_rows,
    'chartEntriesUpdated', v_chart_rows,
    'trackArtistRowsUpdated', v_track_artist_rows,
    'duplicateDraftArtistsMarked', v_duplicate_artist_rows
  );
end;
$$;


ALTER FUNCTION "public"."admin_resolve_chart_artist_alias"("p_alias_slug" "text", "p_canonical_artist_id" "uuid", "p_alias_display_name" "text", "p_apply_to_existing" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_resolve_registry_track_intake"("p_suggestion_id" "uuid", "p_registry_track_id" "uuid", "p_review_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'auth', 'public'
    AS $$
declare
  v_suggestion public.registry_provider_track_suggestions%rowtype;
  v_track public.registry_tracks%rowtype;
  v_artist_sync jsonb;
begin
  if auth.uid() is null then
    raise exception
      using
        errcode = '42501',
        message = 'Authentication is required.';
  end if;

  if not (
    public.current_user_is_administrator()
    or public.current_user_has_capability('manage_registry')
  ) then
    raise exception
      using
        errcode = '42501',
        message = 'Registry management permission is required.';
  end if;

  select suggestion.*
  into v_suggestion
  from public.registry_provider_track_suggestions suggestion
  where suggestion.id = p_suggestion_id
  for update;

  if not found then
    raise exception
      using
        errcode = 'P0002',
        message = 'Track Intake item does not exist.';
  end if;

  if v_suggestion.status <> 'needs_review' then
    raise exception
      'Only Track Intake items awaiting review can be resolved.';
  end if;

  if v_suggestion.source_playlist_item_id is null
     and v_suggestion.intake_origin not in (
       'public_contribution',
       'artist_submission'
     )
  then
    raise exception
      'Track Intake item has not been materialized into its Playlist.';
  end if;

  select track.*
  into v_track
  from public.registry_tracks track
  where track.id = p_registry_track_id
    and track.status = 'active';

  if not found then
    raise exception 'Selected Music Registry track is unavailable.';
  end if;

  select public.sync_registry_track_intake_artist_credits(
    p_suggestion_id,
    p_registry_track_id
  )
  into v_artist_sync;

  update public.registry_provider_track_suggestions suggestion
  set
    status = 'canonicalized',
    canonical_track_id = p_registry_track_id,
    canonicalized_track_id = p_registry_track_id,
    reviewed_by = auth.uid(),
    reviewed_at = now(),
    review_note = nullif(btrim(p_review_note), '')
  where suggestion.id = p_suggestion_id;

  return jsonb_build_object(
    'suggestion_id', p_suggestion_id,
    'playlist_id', v_suggestion.source_playlist_id,
    'playlist_item_id', v_suggestion.source_playlist_item_id,
    'intake_origin', v_suggestion.intake_origin,
    'source_contribution_id', v_suggestion.source_contribution_id,
    'status', 'canonicalized',
    'registry_track_id', p_registry_track_id,
    'registry_track_title', v_track.title,
    'artist_sync', v_artist_sync
  );
end;
$$;


ALTER FUNCTION "public"."admin_resolve_registry_track_intake"("p_suggestion_id" "uuid", "p_registry_track_id" "uuid", "p_review_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_resolve_registry_track_intake_enriched"("p_suggestion_id" "uuid", "p_registry_track_id" "uuid", "p_review_note" "text" DEFAULT NULL::"text", "p_allow_overwrite" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'auth', 'public'
    AS $$
declare
  v_suggestion public.registry_provider_track_suggestions%rowtype;
  v_track public.registry_tracks%rowtype;
  v_release public.registry_releases%rowtype;
  v_fields jsonb := '{}'::jsonb;
  v_result jsonb;
  v_label_id uuid;
  v_label_name text;
  v_before jsonb;
  v_after jsonb;
begin
  if auth.uid() is null then
    raise exception
      using errcode = '42501', message = 'Authentication is required.';
  end if;

  if not (
    public.current_user_is_administrator()
    or public.current_user_has_capability('manage_registry')
  ) then
    raise exception
      using errcode = '42501',
        message = 'Registry management permission is required.';
  end if;

  select suggestion.*
  into v_suggestion
  from public.registry_provider_track_suggestions suggestion
  where suggestion.id = p_suggestion_id
  for update;

  if not found then
    raise exception
      using
        errcode = 'P0002',
        message = 'Track Intake item does not exist.';
  end if;

  if v_suggestion.status <> 'needs_review' then
    raise exception
      'Only Track Intake items awaiting review can be resolved.';
  end if;

  if v_suggestion.canonical_track_id is not null
     and v_suggestion.canonical_track_id <> p_registry_track_id
  then
    raise exception
      'This Track Intake item already has canonical Registry identity. Enrichment review cannot silently remap it to another track.';
  end if;

  select track.*
  into v_track
  from public.registry_tracks track
  where track.id = p_registry_track_id
    and track.status = 'active'
  for update;

  if not found then
    raise exception
      'Selected Music Registry track is unavailable.';
  end if;

  select coalesce(
    jsonb_object_agg(
      suggestion.field_name,
      suggestion.suggested_value
    ),
    '{}'::jsonb
  )
  into v_fields
  from public.registry_enrichment_suggestions suggestion
  where suggestion.registry_entity_type = 'track'
    and suggestion.registry_entity_id =
      p_suggestion_id::text
    and suggestion.decision_status = 'approved';

  if not p_allow_overwrite then
    if v_fields ? 'isrc'
       and v_track.isrc is not null
       and v_track.isrc is distinct from
         nullif(btrim(v_fields ->> 'isrc'), '')
    then
      raise exception
        'Accepted ISRC conflicts with the canonical track. Review the conflict before replacing it.';
    end if;

    if v_fields ? 'duration_ms'
       and v_track.duration_ms is not null
       and v_track.duration_ms is distinct from
         nullif(v_fields ->> 'duration_ms', '')::integer
    then
      raise exception
        'Accepted duration conflicts with the canonical track. Review the conflict before replacing it.';
    end if;

    if v_fields ? 'track_artwork_url'
       and v_track.artwork_url is not null
       and v_track.artwork_url is distinct from
         nullif(btrim(v_fields ->> 'track_artwork_url'), '')
    then
      raise exception
        'Accepted artwork conflicts with the canonical track. Review the conflict before replacing it.';
    end if;
  end if;

  v_before := jsonb_build_object(
    'track',
      jsonb_build_object(
        'isrc', v_track.isrc,
        'duration_ms', v_track.duration_ms,
        'artwork_url', v_track.artwork_url,
        'preview_url', v_track.preview_url,
        'track_number', v_track.track_number,
        'disc_number', v_track.disc_number,
        'explicit', v_track.explicit,
        'metadata', v_track.metadata
      )
  );

  update public.registry_tracks track
  set
    isrc =
      case
        when v_fields ? 'isrc'
        then nullif(btrim(v_fields ->> 'isrc'), '')
        else track.isrc
      end,
    duration_ms =
      case
        when v_fields ? 'duration_ms'
        then nullif(v_fields ->> 'duration_ms', '')::integer
        else track.duration_ms
      end,
    artwork_url =
      case
        when v_fields ? 'track_artwork_url'
        then nullif(
          btrim(v_fields ->> 'track_artwork_url'),
          ''
        )
        else track.artwork_url
      end,
    preview_url =
      case
        when v_fields ? 'preview_url'
        then nullif(btrim(v_fields ->> 'preview_url'), '')
        else track.preview_url
      end,
    track_number =
      case
        when v_fields ? 'track_number'
        then nullif(v_fields ->> 'track_number', '')::integer
        else track.track_number
      end,
    disc_number =
      case
        when v_fields ? 'disc_number'
        then nullif(v_fields ->> 'disc_number', '')::integer
        else track.disc_number
      end,
    explicit =
      case
        when v_fields ? 'explicit'
        then nullif(v_fields ->> 'explicit', '')::boolean
        else track.explicit
      end,
    metadata =
      coalesce(track.metadata, '{}'::jsonb)
      || jsonb_strip_nulls(
        jsonb_build_object(
          'provider_genre',
            nullif(btrim(v_fields ->> 'genre'), ''),
          'track_intake_enriched_at',
            now()
        )
      ),
    updated_at = now()
  where track.id = p_registry_track_id
  returning track.*
  into v_track;

  if v_track.release_id is not null then
    select release.*
    into v_release
    from public.registry_releases release
    where release.id = v_track.release_id
    for update;

    if found then
      if not p_allow_overwrite then
        if v_fields ? 'release_date'
           and v_release.release_date is not null
           and v_release.release_date is distinct from
             (v_fields ->> 'release_date')::date
        then
          raise exception
            'Accepted release date conflicts with the canonical release. Review the conflict before replacing it.';
        end if;

        if v_fields ? 'release_title'
           and nullif(btrim(v_release.title), '') is not null
           and v_release.title is distinct from
             nullif(btrim(v_fields ->> 'release_title'), '')
        then
          raise exception
            'Accepted release title conflicts with the canonical release. Review the conflict before replacing it.';
        end if;
      end if;

      v_label_name :=
        nullif(btrim(v_fields ->> 'label_name'), '');

      if v_label_name is not null
         and v_release.label_id is null
      then
        select label.id
        into v_label_id
        from public.registry_labels label
        where label.status in ('active', 'draft')
          and (
            lower(btrim(label.name)) =
              lower(v_label_name)
            or lower(btrim(label.normalized_name)) =
              lower(v_label_name)
          )
        order by
          case when label.status = 'active' then 0 else 1 end,
          label.created_at
        limit 1;
      end if;

      update public.registry_releases release
      set
        title =
          case
            when v_fields ? 'release_title'
            then nullif(
              btrim(v_fields ->> 'release_title'),
              ''
            )
            else release.title
          end,
        normalized_title =
          case
            when v_fields ? 'release_title'
            then trim(
              regexp_replace(
                lower(
                  nullif(
                    btrim(v_fields ->> 'release_title'),
                    ''
                  )
                ),
                '[^[:alnum:]]+',
                ' ',
                'g'
              )
            )
            else release.normalized_title
          end,
        release_date =
          case
            when v_fields ? 'release_date'
            then (v_fields ->> 'release_date')::date
            else release.release_date
          end,
        release_date_precision =
          case
            when v_fields ? 'release_date_precision'
            then nullif(
              btrim(v_fields ->> 'release_date_precision'),
              ''
            )
            else release.release_date_precision
          end,
        artwork_url =
          case
            when v_fields ? 'release_artwork_url'
            then nullif(
              btrim(v_fields ->> 'release_artwork_url'),
              ''
            )
            else release.artwork_url
          end,
        upc =
          case
            when v_fields ? 'upc'
            then nullif(btrim(v_fields ->> 'upc'), '')
            else release.upc
          end,
        label_id =
          coalesce(v_label_id, release.label_id),
        metadata =
          coalesce(release.metadata, '{}'::jsonb)
          || jsonb_strip_nulls(
            jsonb_build_object(
              'label_name_observation',
                case
                  when v_label_name is not null
                       and v_label_id is null
                  then v_label_name
                  else null
                end,
              'imprint_name',
                nullif(
                  btrim(v_fields ->> 'imprint_name'),
                  ''
                ),
              'copyright_text',
                nullif(
                  btrim(v_fields ->> 'copyright_text'),
                  ''
                ),
              'provider_genre',
                nullif(btrim(v_fields ->> 'genre'), ''),
              'track_intake_enriched_at',
                now()
            )
          ),
        updated_at = now()
      where release.id = v_track.release_id;
    end if;
  end if;

  select public.admin_resolve_registry_track_intake(
    p_suggestion_id,
    p_registry_track_id,
    p_review_note
  )
  into v_result;

  insert into public.provider_entity_links (
    registry_entity_type,
    registry_entity_id,
    provider,
    provider_entity_id,
    provider_url,
    match_status,
    confidence_score,
    created_at,
    updated_at
  )
  select
    'track',
    p_registry_track_id::text,
    link.provider,
    link.provider_entity_id,
    link.provider_url,
    'confirmed',
    link.confidence_score,
    now(),
    now()
  from public.provider_entity_links link
  where link.registry_entity_type = 'track'
    and link.registry_entity_id =
      p_suggestion_id::text
    and link.match_status = 'confirmed'
    and not exists (
      select 1
      from public.provider_entity_links canonical_link
      where canonical_link.registry_entity_type = 'track'
        and canonical_link.registry_entity_id =
          p_registry_track_id::text
        and canonical_link.provider = link.provider
        and canonical_link.provider_entity_id =
          link.provider_entity_id
    );

  select jsonb_build_object(
    'track',
      jsonb_build_object(
        'isrc', track.isrc,
        'duration_ms', track.duration_ms,
        'artwork_url', track.artwork_url,
        'preview_url', track.preview_url,
        'track_number', track.track_number,
        'disc_number', track.disc_number,
        'explicit', track.explicit,
        'metadata', track.metadata
      )
  )
  into v_after
  from public.registry_tracks track
  where track.id = p_registry_track_id;

  insert into public.registry_canonical_write_events (
    registry_entity_type,
    registry_entity_id,
    source_suggestion_id,
    source_table,
    field_name,
    target_path,
    before_value,
    after_value,
    action,
    status,
    error_message,
    actor,
    created_at
  )
  values (
    'track',
    p_registry_track_id::text,
    p_suggestion_id::text,
    'registry_provider_track_suggestions',
    'track_intake_enrichment',
    'registry_tracks',
    v_before,
    v_after,
    'apply_enrichment',
    'applied',
    null,
    auth.uid()::text,
    now()
  );

  return coalesce(v_result, '{}'::jsonb)
    || jsonb_build_object(
      'enrichment_applied', v_fields,
      'label_linked', v_label_id is not null
    );
end;
$$;


ALTER FUNCTION "public"."admin_resolve_registry_track_intake_enriched"("p_suggestion_id" "uuid", "p_registry_track_id" "uuid", "p_review_note" "text", "p_allow_overwrite" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_safe_merge_registry_artists"("p_source_artist_id" "uuid", "p_canonical_artist_id" "uuid", "p_note" "text" DEFAULT NULL::"text", "p_archive_source" boolean DEFAULT true, "p_merge_reason" "text" DEFAULT 'same_person'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_source record;
  v_canonical record;
  v_preview jsonb;
  v_alias_rows integer := 0;
  v_existing_alias_rows integer := 0;
  v_chart_rows integer := 0;
  v_track_rows_moved integer := 0;
  v_track_rows_archived integer := 0;
  v_release_rows_moved integer := 0;
  v_release_rows_archived integer := 0;
  v_track_meta_rows integer := 0;
  v_source_archived boolean := false;
  v_merge_reason text;
  v_result jsonb;
begin
  if not coalesce(public.current_user_has_capability('manage_registry'), false) then
    raise exception 'insufficient_privilege';
  end if;

  if p_source_artist_id is null or p_canonical_artist_id is null then
    raise exception 'source_and_canonical_required';
  end if;

  if p_source_artist_id = p_canonical_artist_id then
    raise exception 'cannot_merge_artist_into_itself';
  end if;

  v_merge_reason := coalesce(nullif(trim(p_merge_reason), ''), 'same_person');

  if v_merge_reason not in ('same_person', 'name_change', 'stage_name_change', 'duplicate_record', 'manual_correction') then
    raise exception 'invalid_merge_reason';
  end if;

  select id, slug, display_name, status, origin_iso2, public_image_url, metadata
  into v_source
  from public.registry_artists
  where id = p_source_artist_id
    and status in ('active', 'draft', 'needs_review', 'archived')
  limit 1;

  if v_source.id is null then
    raise exception 'source_artist_not_found';
  end if;

  select id, slug, display_name, status, origin_iso2, public_image_url, metadata
  into v_canonical
  from public.registry_artists
  where id = p_canonical_artist_id
    and status in ('active', 'draft', 'needs_review')
  limit 1;

  if v_canonical.id is null then
    raise exception 'canonical_artist_not_found';
  end if;

  v_preview := public.admin_get_registry_artist_merge_preview(p_source_artist_id, p_canonical_artist_id);

  update public.registry_artist_aliases
  set
    canonical_artist_id = v_canonical.id,
    alias_display_name = v_source.display_name,
    confidence = 100,
    source = 'similarity_match',
    notes = coalesce(nullif(p_note, ''), 'Manual safe artist merge.'),
    status = 'active'
  where lower(alias_slug) = lower(v_source.slug);

  get diagnostics v_alias_rows = row_count;

  if v_alias_rows = 0 then
    insert into public.registry_artist_aliases (
      alias_slug,
      canonical_artist_id,
      alias_display_name,
      confidence,
      source,
      notes,
      status
    )
    values (
      v_source.slug,
      v_canonical.id,
      v_source.display_name,
      100,
      'similarity_match',
      coalesce(nullif(p_note, ''), 'Manual safe artist merge.'),
      'active'
    );

    v_alias_rows := 1;
  end if;

  update public.registry_artist_aliases
  set
    canonical_artist_id = v_canonical.id,
    notes = coalesce(nullif(p_note, ''), notes, 'Retargeted during manual safe artist merge.')
  where canonical_artist_id = v_source.id;

  get diagnostics v_existing_alias_rows = row_count;

  update public.registry_track_artists bad
  set
    status = 'archived',
    metadata = coalesce(bad.metadata, '{}'::jsonb)
      || jsonb_build_object(
        'archived_reason', 'safe_artist_merge_duplicate_track_credit',
        'merged_into_artist_id', v_canonical.id::text,
        'merged_into_artist_slug', v_canonical.slug,
        'merged_at', now(),
        'merge_reason', v_merge_reason,
        'merge_note', p_note
      ),
    updated_at = now()
  where (
      bad.artist_id = v_source.id
      or lower(coalesce(bad.artist_slug, '')) = lower(v_source.slug)
    )
    and coalesce(bad.status, 'active') <> 'archived'
    and exists (
      select 1
      from public.registry_track_artists good
      where good.track_id = bad.track_id
        and good.artist_id = v_canonical.id
        and coalesce(good.status, 'active') <> 'archived'
    );

  get diagnostics v_track_rows_archived = row_count;

  update public.registry_track_artists rta
  set
    artist_id = v_canonical.id,
    artist_slug = v_canonical.slug,
    artist_name_text = coalesce(nullif(rta.artist_name_text, ''), v_canonical.display_name),
    display_credit = coalesce(nullif(rta.display_credit, ''), v_canonical.display_name),
    metadata = coalesce(rta.metadata, '{}'::jsonb)
      || jsonb_build_object(
        'merged_from_artist_id', v_source.id::text,
        'merged_from_artist_slug', v_source.slug,
        'merged_from_artist_name', v_source.display_name,
        'merged_at', now(),
        'merge_reason', v_merge_reason,
        'merge_note', p_note
      ),
    updated_at = now()
  where (
      rta.artist_id = v_source.id
      or lower(coalesce(rta.artist_slug, '')) = lower(v_source.slug)
    )
    and coalesce(rta.status, 'active') <> 'archived';

  get diagnostics v_track_rows_moved = row_count;

  update public.registry_release_artists bad
  set
    status = 'archived',
    metadata = coalesce(bad.metadata, '{}'::jsonb)
      || jsonb_build_object(
        'archived_reason', 'safe_artist_merge_duplicate_release_credit',
        'merged_into_artist_id', v_canonical.id::text,
        'merged_into_artist_slug', v_canonical.slug,
        'merged_at', now(),
        'merge_reason', v_merge_reason,
        'merge_note', p_note
      ),
    updated_at = now()
  where (
      bad.artist_id = v_source.id
      or lower(coalesce(bad.artist_slug, '')) = lower(v_source.slug)
    )
    and coalesce(bad.status, 'active') <> 'archived'
    and exists (
      select 1
      from public.registry_release_artists good
      where good.release_id = bad.release_id
        and good.artist_id = v_canonical.id
        and coalesce(good.status, 'active') <> 'archived'
    );

  get diagnostics v_release_rows_archived = row_count;

  update public.registry_release_artists rra
  set
    artist_id = v_canonical.id,
    artist_slug = v_canonical.slug,
    artist_name_text = coalesce(nullif(rra.artist_name_text, ''), v_canonical.display_name),
    display_credit = coalesce(nullif(rra.display_credit, ''), v_canonical.display_name),
    metadata = coalesce(rra.metadata, '{}'::jsonb)
      || jsonb_build_object(
        'merged_from_artist_id', v_source.id::text,
        'merged_from_artist_slug', v_source.slug,
        'merged_from_artist_name', v_source.display_name,
        'merged_at', now(),
        'merge_reason', v_merge_reason,
        'merge_note', p_note
      ),
    updated_at = now()
  where (
      rra.artist_id = v_source.id
      or lower(coalesce(rra.artist_slug, '')) = lower(v_source.slug)
    )
    and coalesce(rra.status, 'active') <> 'archived';

  get diagnostics v_release_rows_moved = row_count;

  update public.wk_chart_entries_v2 ce
  set
    canonical_artist_id = v_canonical.id::text,
    artist_slug = v_canonical.slug,
    artist_name = v_canonical.display_name,
    updated_at = now()
  where ce.canonical_artist_id = v_source.id::text
     or public.wk_slugify_text(coalesce(ce.artist_slug, '')) = public.wk_slugify_text(v_source.slug)
     or public.wk_slugify_text(coalesce(ce.artist_name, '')) = public.wk_slugify_text(v_source.display_name);

  get diagnostics v_chart_rows = row_count;

  update public.registry_tracks
  set
    metadata = jsonb_set(
      coalesce(metadata, '{}'::jsonb)
        || jsonb_build_object(
          'artist_merged_from_slug', v_source.slug,
          'artist_merged_from_name', v_source.display_name,
          'artist_merge_note', p_note,
          'artist_merged_at', now()
        ),
      '{primary_artist_slug}',
      to_jsonb(v_canonical.slug),
      true
    ),
    updated_at = now()
  where metadata->>'primary_artist_slug' = v_source.slug
     or metadata->>'artist_slug' = v_source.slug;

  get diagnostics v_track_meta_rows = row_count;

  update public.registry_artists
  set
    origin_iso2 = coalesce(origin_iso2, v_source.origin_iso2),
    public_image_url = coalesce(public_image_url, v_source.public_image_url),
    metadata = coalesce(metadata, '{}'::jsonb)
      || jsonb_build_object(
        'safe_merge_source_artist_id', v_source.id::text,
        'safe_merge_source_artist_slug', v_source.slug,
        'safe_merge_source_artist_name', v_source.display_name,
        'safe_merge_reason', v_merge_reason,
        'safe_merge_note', p_note,
        'safe_merged_at', now()
      ),
    updated_at = now()
  where id = v_canonical.id;

  if p_archive_source then
    update public.registry_artists
    set
      status = 'archived',
      metadata = coalesce(metadata, '{}'::jsonb)
        || jsonb_build_object(
          'archived_by_safe_artist_merge', true,
          'merged_into_artist_id', v_canonical.id::text,
          'merged_into_artist_slug', v_canonical.slug,
          'merged_into_artist_name', v_canonical.display_name,
          'merge_reason', v_merge_reason,
          'merge_note', p_note,
          'merged_at', now()
        ),
      updated_at = now()
    where id = v_source.id;

    v_source_archived := true;
  else
    update public.registry_artists
    set
      metadata = coalesce(metadata, '{}'::jsonb)
        || jsonb_build_object(
          'safe_merge_without_archive', true,
          'merged_into_artist_id', v_canonical.id::text,
          'merged_into_artist_slug', v_canonical.slug,
          'merged_into_artist_name', v_canonical.display_name,
          'merge_reason', v_merge_reason,
          'merge_note', p_note,
          'merged_at', now()
        ),
      updated_at = now()
    where id = v_source.id;
  end if;

  v_result := jsonb_build_object(
    'sourceArtistId', v_source.id,
    'sourceSlug', v_source.slug,
    'sourceName', v_source.display_name,
    'canonicalArtistId', v_canonical.id,
    'canonicalSlug', v_canonical.slug,
    'canonicalName', v_canonical.display_name,
    'aliasRowsTouched', v_alias_rows,
    'existingAliasesRetargeted', v_existing_alias_rows,
    'trackArtistRowsMoved', v_track_rows_moved,
    'trackArtistRowsArchived', v_track_rows_archived,
    'releaseArtistRowsMoved', v_release_rows_moved,
    'releaseArtistRowsArchived', v_release_rows_archived,
    'chartEntriesUpdated', v_chart_rows,
    'trackMetadataRowsUpdated', v_track_meta_rows,
    'sourceArchived', v_source_archived,
    'mergeReason', v_merge_reason
  );

  insert into public.registry_artist_resolution_events (
    action,
    status,
    source_artist_id,
    source_artist_slug,
    source_artist_name,
    source_snapshot,
    replacement_artists,
    track_links,
    release_links,
    chart_entries,
    note,
    result
  )
  values (
    'artist_merge',
    'success',
    v_source.id,
    v_source.slug,
    v_source.display_name,
    v_preview -> 'sourceArtist',
    jsonb_build_array(v_preview -> 'canonicalArtist'),
    coalesce(v_preview -> 'trackCredits', '[]'::jsonb),
    coalesce(v_preview -> 'releaseCredits', '[]'::jsonb),
    coalesce(v_preview -> 'chartEntries', '[]'::jsonb),
    nullif(p_note, ''),
    v_result
  );

  return v_result;
end;
$$;


ALTER FUNCTION "public"."admin_safe_merge_registry_artists"("p_source_artist_id" "uuid", "p_canonical_artist_id" "uuid", "p_note" "text", "p_archive_source" boolean, "p_merge_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_save_registry_track_intake_enrichment"("p_suggestion_id" "uuid", "p_fields" "jsonb", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'auth', 'public'
    AS $$
declare
  v_field record;
  v_value text;
  v_count integer := 0;
  v_allowed constant text[] := array[
    'title',
    'isrc',
    'duration_ms',
    'track_artwork_url',
    'preview_url',
    'release_title',
    'release_artwork_url',
    'release_date',
    'release_date_precision',
    'label_name',
    'imprint_name',
    'genre',
    'track_number',
    'disc_number',
    'explicit',
    'upc',
    'copyright_text'
  ];
begin
  if auth.uid() is null then
    raise exception
      using
        errcode = '42501',
        message = 'Authentication is required.';
  end if;

  if not (
    public.current_user_is_administrator()
    or public.current_user_has_capability('manage_registry')
  ) then
    raise exception
      using
        errcode = '42501',
        message = 'Registry management permission is required.';
  end if;

  if not exists (
    select 1
    from public.registry_provider_track_suggestions suggestion
    where suggestion.id = p_suggestion_id
      and suggestion.status = 'needs_review'
  ) then
    raise exception
      'Only Track Intake items awaiting review can be enriched.';
  end if;

  if p_fields is null
     or jsonb_typeof(p_fields) <> 'object'
  then
    raise exception
      'Accepted enrichment fields must be a JSON object.';
  end if;

  delete from public.registry_enrichment_suggestions suggestion
  where suggestion.registry_entity_type = 'track'
    and suggestion.registry_entity_id = p_suggestion_id::text
    and suggestion.decision_status in ('draft', 'approved')
    and suggestion.field_name = any(v_allowed)
    and not (p_fields ? suggestion.field_name);

  for v_field in
    select entry.key, entry.value
    from jsonb_each(p_fields) entry
  loop
    if not (v_field.key = any(v_allowed)) then
      raise exception
        'Unsupported accepted Track Intake field: %',
        v_field.key;
    end if;

    if v_field.value = 'null'::jsonb then
      delete from public.registry_enrichment_suggestions suggestion
      where suggestion.registry_entity_type = 'track'
        and suggestion.registry_entity_id =
          p_suggestion_id::text
        and suggestion.field_name = v_field.key
        and suggestion.decision_status in (
          'draft',
          'approved'
        );

      continue;
    end if;

    v_value :=
      case jsonb_typeof(v_field.value)
        when 'string'
          then v_field.value #>> '{}'
        else v_field.value::text
      end;

    if nullif(btrim(v_value), '') is null then
      continue;
    end if;

    delete from public.registry_enrichment_suggestions suggestion
    where suggestion.registry_entity_type = 'track'
      and suggestion.registry_entity_id =
        p_suggestion_id::text
      and suggestion.field_name = v_field.key
      and suggestion.decision_status in (
        'draft',
        'approved'
      );

    insert into public.registry_enrichment_suggestions (
      registry_entity_type,
      registry_entity_id,
      field_name,
      current_value,
      suggested_value,
      provider_item_id,
      confidence_score,
      decision_status,
      decision_reason,
      created_at,
      updated_at
    )
    values (
      'track',
      p_suggestion_id::text,
      v_field.key,
      null,
      v_value,
      p_suggestion_id::text,
      1.0000,
      'approved',
      nullif(btrim(p_reason), ''),
      now(),
      now()
    );

    v_count := v_count + 1;
  end loop;

  return jsonb_build_object(
    'suggestion_id',
      p_suggestion_id,
    'accepted_field_count',
      v_count
  );
end;
$$;


ALTER FUNCTION "public"."admin_save_registry_track_intake_enrichment"("p_suggestion_id" "uuid", "p_fields" "jsonb", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_search_registry_artists"("p_query" "text", "p_limit" integer DEFAULT 20) RETURNS TABLE("artist_id" "uuid", "artist_slug" "text", "display_name" "text", "status" "text", "origin_iso2" "text", "public_image_url" "text", "track_credit_count" integer, "release_credit_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_query text;
  v_like text;
  v_limit integer;
begin
  if not coalesce(public.current_user_has_capability('manage_registry'), false) then
    raise exception 'insufficient_privilege';
  end if;

  v_query := nullif(trim(p_query), '');
  v_limit := least(greatest(coalesce(p_limit, 20), 1), 50);

  if v_query is null then
    return;
  end if;

  v_like := '%' || lower(v_query) || '%';

  return query
  select
    a.id,
    a.slug,
    a.display_name,
    a.status,
    a.origin_iso2,
    a.public_image_url,
    coalesce(t.track_credit_count, 0)::integer as track_credit_count,
    coalesce(r.release_credit_count, 0)::integer as release_credit_count
  from public.registry_artists a
  left join lateral (
    select count(*)::integer as track_credit_count
    from public.registry_track_artists ta
    where ta.artist_id = a.id
       or lower(ta.artist_slug) = lower(a.slug)
  ) t on true
  left join lateral (
    select count(*)::integer as release_credit_count
    from public.registry_release_artists ra
    where ra.artist_id = a.id
       or lower(ra.artist_slug) = lower(a.slug)
  ) r on true
  where a.status in ('active', 'draft', 'needs_review', 'archived')
    and (
      lower(a.slug) = lower(v_query)
      or lower(a.display_name) = lower(v_query)
      or lower(a.slug) like v_like
      or lower(a.display_name) like v_like
      or lower(coalesce(a.normalized_name, '')) like v_like
    )
  order by
    case
      when lower(a.slug) = lower(v_query) then 1
      when lower(a.display_name) = lower(v_query) then 2
      when lower(a.slug) like lower(v_query) || '%' then 3
      when lower(a.display_name) like lower(v_query) || '%' then 4
      else 5
    end,
    a.status = 'active' desc,
    a.display_name asc
  limit v_limit;
end;
$$;


ALTER FUNCTION "public"."admin_search_registry_artists"("p_query" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_select_registry_track_intake_provider_evidence"("p_suggestion_id" "uuid", "p_provider" "text", "p_provider_entity_id" "text", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'auth', 'public'
    AS $$
declare
  v_suggestion public.registry_provider_track_suggestions%rowtype;
  v_target public.provider_entity_links%rowtype;
  v_provider text := lower(btrim(coalesce(p_provider, '')));
  v_provider_entity_id text :=
    nullif(btrim(p_provider_entity_id), '');
  v_before_confirmed jsonb := '[]'::jsonb;
  v_after_target jsonb;
  v_superseded integer := 0;
  v_already_selected boolean := false;
begin
  if auth.uid() is null then
    raise exception
      using
        errcode = '42501',
        message = 'Authentication is required.';
  end if;

  if not (
    public.current_user_is_administrator()
    or public.current_user_has_capability('manage_registry')
  ) then
    raise exception
      using
        errcode = '42501',
        message = 'Registry management permission is required.';
  end if;

  if v_provider = ''
     or v_provider_entity_id is null
  then
    raise exception
      'Provider and provider entity ID are required.';
  end if;

  select suggestion.*
  into v_suggestion
  from public.registry_provider_track_suggestions suggestion
  where suggestion.id = p_suggestion_id
  for update;

  if not found then
    raise exception
      using
        errcode = 'P0002',
        message = 'Track Intake item does not exist.';
  end if;

  if v_suggestion.status <> 'needs_review' then
    raise exception
      'Only Track Intake items awaiting review can select provider identity.';
  end if;

  select link.*
  into v_target
  from public.provider_entity_links link
  where link.registry_entity_type = 'track'
    and link.registry_entity_id = p_suggestion_id::text
    and link.provider = v_provider
    and link.provider_entity_id = v_provider_entity_id
  for update;

  if not found then
    raise exception
      'Inspect this provider result before selecting it.';
  end if;

  select coalesce(
    jsonb_agg(
      to_jsonb(link)
      order by link.created_at, link.id
    ),
    '[]'::jsonb
  )
  into v_before_confirmed
  from public.provider_entity_links link
  where link.registry_entity_type = 'track'
    and link.registry_entity_id = p_suggestion_id::text
    and link.provider = v_provider
    and link.match_status = 'confirmed';

  select (
    v_target.match_status = 'confirmed'
    and not exists (
      select 1
      from public.provider_entity_links other
      where other.registry_entity_type = 'track'
        and other.registry_entity_id = p_suggestion_id::text
        and other.provider = v_provider
        and other.match_status = 'confirmed'
        and other.id <> v_target.id
    )
  )
  into v_already_selected;

  if v_already_selected then
    return jsonb_build_object(
      'suggestion_id', p_suggestion_id,
      'provider', v_provider,
      'provider_entity_id', v_provider_entity_id,
      'match_status', 'confirmed',
      'superseded_count', 0,
      'changed', false
    );
  end if;

  update public.provider_entity_links link
  set
    match_status = 'superseded',
    updated_at = now()
  where link.registry_entity_type = 'track'
    and link.registry_entity_id = p_suggestion_id::text
    and link.provider = v_provider
    and link.match_status = 'confirmed'
    and link.id <> v_target.id;

  get diagnostics v_superseded = row_count;

  update public.provider_entity_links link
  set
    match_status = 'confirmed',
    updated_at = now()
  where link.id = v_target.id
  returning to_jsonb(link)
  into v_after_target;

  insert into public.registry_canonical_write_events (
    registry_entity_type,
    registry_entity_id,
    source_suggestion_id,
    source_table,
    field_name,
    target_path,
    before_value,
    after_value,
    action,
    status,
    error_message,
    actor,
    created_at
  )
  values (
    'track',
    p_suggestion_id::text,
    p_suggestion_id::text,
    'provider_entity_links',
    'provider_identity',
    'registry_provider_track_suggestions.provider_selection',
    jsonb_build_object(
      'confirmed_provider_links',
      v_before_confirmed
    ),
    jsonb_build_object(
      'selected_provider_link',
      v_after_target,
      'superseded_count',
      v_superseded,
      'reason',
      nullif(btrim(p_reason), '')
    ),
    'select_provider_identity',
    'applied',
    null,
    auth.uid()::text,
    now()
  );

  return jsonb_build_object(
    'suggestion_id', p_suggestion_id,
    'provider', v_provider,
    'provider_entity_id', v_provider_entity_id,
    'match_status', 'confirmed',
    'superseded_count', v_superseded,
    'changed', true
  );
end;
$$;


ALTER FUNCTION "public"."admin_select_registry_track_intake_provider_evidence"("p_suggestion_id" "uuid", "p_provider" "text", "p_provider_entity_id" "text", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_select_registry_track_intake_provider_evidence"("p_suggestion_id" "uuid", "p_provider" "text", "p_provider_entity_id" "text", "p_reason" "text") IS 'Selects one current provider identity for a Track Intake suggestion and supersedes any prior confirmed choice for the same provider without deleting evidence.';



CREATE OR REPLACE FUNCTION "public"."admin_update_registry_track_intake_artist_credit"("p_suggestion_id" "uuid", "p_credit_order" integer, "p_credit_role" "text", "p_resolution_mode" "text", "p_registry_artist_id" "uuid" DEFAULT NULL::"uuid", "p_observed_name" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'auth', 'public'
    AS $$
declare
  v_suggestion public.registry_provider_track_suggestions%rowtype;
  v_credit public.registry_provider_track_suggestion_artists%rowtype;
  v_role text :=
    lower(
      btrim(
        coalesce(
          p_credit_role,
          ''
        )
      )
    );
  v_mode text :=
    lower(
      btrim(
        coalesce(
          p_resolution_mode,
          ''
        )
      )
    );
  v_observed_name text :=
    nullif(
      btrim(p_observed_name),
      ''
    );
  v_artist_name text;
begin
  if auth.uid() is null then
    raise exception
      using
        errcode = '42501',
        message = 'Authentication is required.';
  end if;

  if not (
    public.current_user_is_administrator()
    or public.current_user_has_capability(
      'manage_registry'
    )
  ) then
    raise exception
      using
        errcode = '42501',
        message = 'Registry management permission is required.';
  end if;

  if p_suggestion_id is null
     or p_credit_order is null
     or p_credit_order < 1
  then
    raise exception
      'Track Intake artist credit is required.';
  end if;

  if v_role not in (
    'primary',
    'featured',
    'unresolved'
  ) then
    raise exception
      'Artist credit role must be Primary, Featured, or Unresolved.';
  end if;

  if v_mode not in (
    'existing_artist',
    'alias_candidate',
    'new_artist',
    'unresolved'
  ) then
    raise exception
      'Artist resolution is invalid.';
  end if;

  select suggestion.*
  into v_suggestion
  from public.registry_provider_track_suggestions suggestion
  where suggestion.id = p_suggestion_id
  for update;

  if not found then
    raise exception
      using
        errcode = 'P0002',
        message = 'Track Intake item does not exist.';
  end if;

  if v_suggestion.status <> 'needs_review' then
    raise exception
      'Only Track Intake items awaiting review can change artist credits.';
  end if;

  select credit.*
  into v_credit
  from public.registry_provider_track_suggestion_artists credit
  where credit.suggestion_id = p_suggestion_id
    and credit.credit_order = p_credit_order
  for update;

  if not found then
    raise exception
      using
        errcode = 'P0002',
        message = 'Track Intake artist credit does not exist.';
  end if;

  if v_mode in (
    'existing_artist',
    'alias_candidate'
  ) then
    if p_registry_artist_id is null then
      raise exception
        'Select a Music Registry artist for this credit.';
    end if;

    select artist.display_name
    into v_artist_name
    from public.registry_artists artist
    where artist.id = p_registry_artist_id
      and artist.status = 'active';

    if not found then
      raise exception
        'Selected Music Registry artist is unavailable.';
    end if;

    v_observed_name :=
      coalesce(
        v_observed_name,
        v_artist_name
      );
  else
    if p_registry_artist_id is not null then
      raise exception
        'Unresolved and new artist credits cannot claim Registry identity.';
    end if;

    if v_observed_name is null then
      raise exception
        'Artist name is required.';
    end if;
  end if;

  if p_registry_artist_id is not null
     and exists (
       select 1
       from public.registry_provider_track_suggestion_artists other_credit
       where other_credit.suggestion_id = p_suggestion_id
         and other_credit.credit_order <> p_credit_order
         and other_credit.registry_artist_id =
               p_registry_artist_id
     )
  then
    raise exception
      'The same Registry artist cannot appear twice in one Track Intake item.';
  end if;

  if p_registry_artist_id is null
     and exists (
       select 1
       from public.registry_provider_track_suggestion_artists other_credit
       where other_credit.suggestion_id = p_suggestion_id
         and other_credit.credit_order <> p_credit_order
         and other_credit.registry_artist_id is null
         and lower(
               btrim(
                 other_credit.observed_name
               )
             ) =
             lower(
               btrim(
                 v_observed_name
               )
             )
     )
  then
    raise exception
      'The same observed artist cannot appear twice in one Track Intake item.';
  end if;

  update public.registry_provider_track_suggestion_artists credit
  set
    credit_role = v_role,
    resolution_mode = v_mode,
    registry_artist_id =
      case
        when v_mode in (
          'existing_artist',
          'alias_candidate'
        )
        then p_registry_artist_id
        else null
      end,
    observed_name = v_observed_name
  where credit.suggestion_id = p_suggestion_id
    and credit.credit_order = p_credit_order
  returning credit.*
  into v_credit;

  return jsonb_build_object(
    'suggestion_id',
      p_suggestion_id,
    'credit_order',
      v_credit.credit_order,
    'credit_role',
      v_credit.credit_role,
    'resolution_mode',
      v_credit.resolution_mode,
    'registry_artist_id',
      v_credit.registry_artist_id,
    'observed_name',
      v_credit.observed_name,
    'display_name',
      coalesce(
        v_artist_name,
        v_credit.observed_name
      )
  );
end;
$$;


ALTER FUNCTION "public"."admin_update_registry_track_intake_artist_credit"("p_suggestion_id" "uuid", "p_credit_order" integer, "p_credit_role" "text", "p_resolution_mode" "text", "p_registry_artist_id" "uuid", "p_observed_name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_update_registry_track_intake_artist_credit"("p_suggestion_id" "uuid", "p_credit_order" integer, "p_credit_role" "text", "p_resolution_mode" "text", "p_registry_artist_id" "uuid", "p_observed_name" "text") IS 'Registry-review command for assigning submitted artist evidence to Primary, Featured, or unresolved roles and resolving canonical artist identity without automatic merging.';



CREATE OR REPLACE FUNCTION "public"."admin_upsert_artist_decouple_decision"("p_source_type" "text", "p_source_table" "text" DEFAULT NULL::"text", "p_source_id" "text" DEFAULT NULL::"text", "p_source_label" "text" DEFAULT NULL::"text", "p_source_artist_id" "uuid" DEFAULT NULL::"uuid", "p_raw_credit_text" "text" DEFAULT NULL::"text", "p_source_snapshot" "jsonb" DEFAULT '{}'::"jsonb", "p_parsed_tokens" "jsonb" DEFAULT '[]'::"jsonb", "p_selected_artists" "jsonb" DEFAULT '[]'::"jsonb", "p_chart_primary_artist_id" "uuid" DEFAULT NULL::"uuid", "p_decision_type" "text" DEFAULT 'split_combined_artist'::"text", "p_decision_status" "text" DEFAULT 'draft'::"text", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_source_type text;
  v_decision_type text;
  v_decision_status text;
  v_source_key text;
  v_source_label text;
  v_decision record;
begin
  if not coalesce(public.current_user_has_capability('manage_registry'), false) then
    raise exception 'insufficient_privilege';
  end if;

  v_source_type := nullif(trim(coalesce(p_source_type, '')), '');
  if v_source_type not in ('charts', 'registry', 'provider_intake', 'artist_intake', 'manual') then
    raise exception 'invalid_source_type';
  end if;

  v_decision_type := coalesce(nullif(trim(p_decision_type), ''), 'split_combined_artist');
  if v_decision_type not in ('split_combined_artist', 'split_raw_credit', 'block_alias', 'needs_follow_up', 'not_a_decouple') then
    raise exception 'invalid_decision_type';
  end if;

  v_decision_status := coalesce(nullif(trim(p_decision_status), ''), 'draft');
  if v_decision_status not in ('draft', 'ready', 'applied', 'blocked', 'failed', 'superseded') then
    raise exception 'invalid_decision_status';
  end if;

  if jsonb_typeof(coalesce(p_parsed_tokens, '[]'::jsonb)) <> 'array' then
    raise exception 'parsed_tokens_must_be_array';
  end if;

  if jsonb_typeof(coalesce(p_selected_artists, '[]'::jsonb)) <> 'array' then
    raise exception 'selected_artists_must_be_array';
  end if;

  v_source_label := nullif(trim(coalesce(p_source_label, p_raw_credit_text, '')), '');
  if v_source_label is null then
    raise exception 'source_label_required';
  end if;

  v_source_key := v_source_type || ':' || coalesce(
    nullif(trim(p_source_id), ''),
    p_source_artist_id::text,
    public.wk_slugify_text(v_source_label)
  );

  insert into public.registry_artist_decouple_decisions (
    source_key,
    source_type,
    source_table,
    source_id,
    source_label,
    source_snapshot,
    source_artist_id,
    raw_credit_text,
    parsed_tokens,
    selected_artists,
    chart_primary_artist_id,
    decision_type,
    decision_status,
    note,
    actor_id,
    updated_at
  )
  values (
    v_source_key,
    v_source_type,
    nullif(trim(coalesce(p_source_table, '')), ''),
    nullif(trim(coalesce(p_source_id, '')), ''),
    v_source_label,
    coalesce(p_source_snapshot, '{}'::jsonb),
    p_source_artist_id,
    nullif(trim(coalesce(p_raw_credit_text, '')), ''),
    coalesce(p_parsed_tokens, '[]'::jsonb),
    coalesce(p_selected_artists, '[]'::jsonb),
    p_chart_primary_artist_id,
    v_decision_type,
    v_decision_status,
    nullif(p_note, ''),
    auth.uid(),
    now()
  )
  on conflict (source_key) do update
  set
    source_table = excluded.source_table,
    source_id = excluded.source_id,
    source_label = excluded.source_label,
    source_snapshot = excluded.source_snapshot,
    source_artist_id = excluded.source_artist_id,
    raw_credit_text = excluded.raw_credit_text,
    parsed_tokens = excluded.parsed_tokens,
    selected_artists = excluded.selected_artists,
    chart_primary_artist_id = excluded.chart_primary_artist_id,
    decision_type = excluded.decision_type,
    decision_status = excluded.decision_status,
    note = excluded.note,
    actor_id = auth.uid(),
    updated_at = now()
  returning *
  into v_decision;

  return jsonb_build_object(
    'id', v_decision.id,
    'source_key', v_decision.source_key,
    'source_type', v_decision.source_type,
    'source_label', v_decision.source_label,
    'source_artist_id', v_decision.source_artist_id,
    'decision_type', v_decision.decision_type,
    'decision_status', v_decision.decision_status,
    'note', v_decision.note,
    'created_at', v_decision.created_at,
    'updated_at', v_decision.updated_at
  );
end;
$$;


ALTER FUNCTION "public"."admin_upsert_artist_decouple_decision"("p_source_type" "text", "p_source_table" "text", "p_source_id" "text", "p_source_label" "text", "p_source_artist_id" "uuid", "p_raw_credit_text" "text", "p_source_snapshot" "jsonb", "p_parsed_tokens" "jsonb", "p_selected_artists" "jsonb", "p_chart_primary_artist_id" "uuid", "p_decision_type" "text", "p_decision_status" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_upsert_chart_artist_resolution_decision"("p_chart_entry_id" "text", "p_decision_type" "text", "p_decision_status" "text" DEFAULT 'draft'::"text", "p_parsed_tokens" "jsonb" DEFAULT '[]'::"jsonb", "p_selected_artists" "jsonb" DEFAULT '[]'::"jsonb", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_entry record;
  v_decision_type text;
  v_decision_status text;
  v_decision_id uuid;
begin
  if not (
    coalesce(public.current_user_has_capability('manage_charts'), false)
    or coalesce(public.current_user_has_capability('manage_registry'), false)
    or coalesce(public.current_user_is_administrator(), false)
  ) then
    raise exception 'insufficient_privilege';
  end if;

  v_decision_type := nullif(trim(coalesce(p_decision_type, '')), '');
  v_decision_status := nullif(trim(coalesce(p_decision_status, '')), '');

  if v_decision_type not in ('accepted_as_group', 'split_plan', 'alias_plan', 'needs_follow_up') then
    raise exception 'invalid_decision_type';
  end if;

  if v_decision_status not in ('draft', 'ready', 'resolved', 'superseded') then
    raise exception 'invalid_decision_status';
  end if;

  select
    e.id::text as chart_entry_id,
    e.edition_id::text as edition_id,
    ed.program_id::text as program_id,
    ed.edition_date,
    e.rank,
    e.track_title,
    e.artist_name,
    e.artist_slug,
    e.canonical_artist_id
  into v_entry
  from public.wk_chart_entries_v2 e
  join public.wk_chart_editions_v2 ed on ed.id::text = e.edition_id::text
  where e.id::text = p_chart_entry_id
  limit 1;

  if v_entry.chart_entry_id is null then
    raise exception 'chart_entry_not_found';
  end if;

  insert into public.chart_artist_resolution_decisions (
    chart_entry_id,
    edition_id,
    program_id,
    edition_date,
    rank,
    track_title,
    raw_artist_name,
    artist_slug,
    canonical_artist_id,
    decision_type,
    decision_status,
    parsed_tokens,
    selected_artists,
    note,
    actor_id
  )
  values (
    v_entry.chart_entry_id,
    v_entry.edition_id,
    v_entry.program_id,
    v_entry.edition_date,
    v_entry.rank,
    v_entry.track_title,
    v_entry.artist_name,
    v_entry.artist_slug,
    v_entry.canonical_artist_id,
    v_decision_type,
    v_decision_status,
    coalesce(p_parsed_tokens, '[]'::jsonb),
    coalesce(p_selected_artists, '[]'::jsonb),
    nullif(p_note, ''),
    auth.uid()
  )
  on conflict (chart_entry_id) do update
  set
    program_id = excluded.program_id,
    edition_date = excluded.edition_date,
    rank = excluded.rank,
    track_title = excluded.track_title,
    raw_artist_name = excluded.raw_artist_name,
    artist_slug = excluded.artist_slug,
    canonical_artist_id = excluded.canonical_artist_id,
    decision_type = excluded.decision_type,
    decision_status = excluded.decision_status,
    parsed_tokens = excluded.parsed_tokens,
    selected_artists = excluded.selected_artists,
    note = excluded.note,
    actor_id = auth.uid(),
    updated_at = now()
  returning id into v_decision_id;

  return jsonb_build_object(
    'decisionId', v_decision_id,
    'chartEntryId', v_entry.chart_entry_id,
    'editionId', v_entry.edition_id,
    'decisionType', v_decision_type,
    'decisionStatus', v_decision_status
  );
end;
$$;


ALTER FUNCTION "public"."admin_upsert_chart_artist_resolution_decision"("p_chart_entry_id" "text", "p_decision_type" "text", "p_decision_status" "text", "p_parsed_tokens" "jsonb", "p_selected_artists" "jsonb", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."adopt_verified_media_upload_session_v1"("p_session_id" "uuid", "p_title" "text" DEFAULT NULL::"text", "p_asset_purpose" "text" DEFAULT 'general'::"text", "p_folder_id" "uuid" DEFAULT NULL::"uuid", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'media', 'auth'
    AS $_$
declare
  v_actor_id uuid;
  v_session media.upload_sessions%rowtype;
  v_file media.file_objects%rowtype;
  v_asset record;
  v_revision record;
  v_existing_asset media.assets%rowtype;
  v_existing_revision media.asset_revisions%rowtype;
  v_asset_kind text;
  v_title text;
  v_slug text;
  v_extension text;
  v_correlation_id uuid := coalesce(
    p_correlation_id,
    gen_random_uuid()
  );
  v_compatibility jsonb;
begin
  v_actor_id :=
    media.require_command_actor('manage_media_assets');

  select session_row.*
  into v_session
  from media.upload_sessions session_row
  where session_row.id = p_session_id
  for update;

  if not found then
    raise exception 'Upload session does not exist';
  end if;

  if v_session.actor_id <> v_actor_id then
    raise exception 'Upload session belongs to another actor';
  end if;

  if v_session.state <> 'verified'
     or v_session.file_object_id is null
  then
    raise exception 'Only a verified upload session may be adopted';
  end if;

  select file_row.*
  into v_file
  from media.file_objects file_row
  where file_row.id = v_session.file_object_id;

  if not found
     or v_file.verification_state <> 'verified'
     or v_file.storage_provider <> 'lightsail_media'
  then
    raise exception
      'Verified upload session is missing its canonical file object';
  end if;

  if v_session.mime_type like 'audio/%'
     and v_session.storage_path like 'masters/audio/%'
  then
    v_asset_kind := 'audio';
  elsif v_session.mime_type like 'video/%'
        and v_session.storage_path like 'masters/video/%'
  then
    v_asset_kind := 'video';
  else
    raise exception
      'Verified upload session is not an M3 audio or video master';
  end if;

  select canonical_asset.*
  into v_existing_asset
  from public.registry_media_assets compatibility
  join media.legacy_asset_links bridge
    on bridge.legacy_asset_id = compatibility.id
  join media.assets canonical_asset
    on canonical_asset.id = bridge.asset_id
  where compatibility.source_entity = 'media_upload_session'
    and compatibility.source_staging_record_id = p_session_id
  limit 1;

  if found then
    select revision_row.*
    into v_existing_revision
    from media.asset_revisions revision_row
    where revision_row.id = v_existing_asset.current_revision_id;

    if not found
       or v_existing_revision.original_file_object_id <> v_session.file_object_id
    then
      raise exception
        'Existing upload-session adoption does not match the verified master';
    end if;

    return jsonb_build_object(
      'asset_id', v_existing_asset.id,
      'asset_revision_id', v_existing_revision.id,
      'revision_number', v_existing_revision.revision_number,
      'file_object_id', v_session.file_object_id,
      'authority_revision', v_existing_asset.authority_revision,
      'idempotent_replay', true,
      'correlation_id', v_session.correlation_id
    );
  end if;

  v_title := coalesce(
    nullif(btrim(p_title), ''),
    nullif(
      regexp_replace(v_session.original_filename, '\.[^.]+$', ''),
      ''
    ),
    v_session.original_filename
  );

  select *
  into v_asset
  from public.create_media_asset(
    v_asset_kind,
    coalesce(nullif(btrim(p_asset_purpose), ''), 'general'),
    v_title,
    p_folder_id,
    v_correlation_id
  );

  select *
  into v_revision
  from public.create_media_asset_revision(
    v_asset.asset_id,
    1,
    v_session.file_object_id,
    'Adopt verified resumable Media master',
    v_correlation_id
  );

  v_extension := lower(
    reverse(
      split_part(reverse(v_session.original_filename), '.', 1)
    )
  );

  v_slug :=
    'media-' || replace(v_asset.asset_id::text, '-', '');

  insert into public.registry_media_assets (
    id,
    slug,
    title,
    url,
    mime_type,
    media_kind,
    status,
    source_kind,
    source_entity,
    source_record_id,
    source_staging_record_id,
    storage_bucket,
    storage_path,
    folder_id,
    file_kind,
    asset_purpose,
    display_filename,
    original_filename,
    file_extension,
    file_size_bytes,
    rights_status,
    tags,
    metadata,
    created_at,
    updated_at
  )
  values (
    v_asset.asset_id,
    v_slug,
    v_title,
    'https://media.wakilisha.africa/__private/media-asset/' ||
      v_asset.asset_id::text,
    v_session.mime_type,
    v_asset_kind,
    'active',
    'editor_upload',
    'media_upload_session',
    p_session_id::text,
    p_session_id,
    v_session.storage_namespace,
    v_session.storage_path,
    p_folder_id,
    v_asset_kind,
    coalesce(nullif(btrim(p_asset_purpose), ''), 'general'),
    v_title,
    v_session.original_filename,
    v_extension,
    v_session.expected_byte_size,
    'unknown',
    '{}'::text[],
    jsonb_build_object(
      'file_name', v_session.original_filename,
      'file_size', v_session.expected_byte_size,
      'upload_session_id', p_session_id,
      'protected_original', true,
      'transfer_kind', 'resumable_parts',
      'master_kind', v_asset_kind
    ),
    now(),
    now()
  )
  returning to_jsonb(registry_media_assets)
  into v_compatibility;

  insert into media.legacy_asset_links (
    legacy_asset_id,
    asset_id,
    mapping_reason,
    legacy_snapshot,
    created_by
  )
  values (
    v_asset.asset_id,
    v_asset.asset_id,
    'Phase 4B M3 verified resumable master compatibility bridge',
    v_compatibility,
    v_actor_id
  );

  insert into media.events (
    asset_id,
    asset_revision_id,
    file_object_id,
    event_type,
    actor_id,
    reason,
    resulting_state,
    correlation_id
  )
  values (
    v_asset.asset_id,
    v_revision.asset_revision_id,
    v_session.file_object_id,
    'resumable_master_adopted',
    v_actor_id,
    'Adopt verified resumable Media master',
    jsonb_build_object(
      'upload_session_id', p_session_id,
      'asset_kind', v_asset_kind,
      'revision_number', v_revision.revision_number,
      'authority_revision', v_revision.authority_revision
    ),
    v_correlation_id
  );

  return jsonb_build_object(
    'asset_id', v_asset.asset_id,
    'asset_revision_id', v_revision.asset_revision_id,
    'revision_number', v_revision.revision_number,
    'file_object_id', v_session.file_object_id,
    'authority_revision', v_revision.authority_revision,
    'idempotent_replay', false,
    'correlation_id', v_correlation_id
  );
end;
$_$;


ALTER FUNCTION "public"."adopt_verified_media_upload_session_v1"("p_session_id" "uuid", "p_title" "text", "p_asset_purpose" "text", "p_folder_id" "uuid", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_article_correction"("p_case_resource_id" "uuid", "p_expected_case_revision" bigint, "p_expected_current_decision_id" "uuid", "p_primary_target_id" "uuid", "p_challenged_article_version_id" "uuid", "p_expected_published_article_version_id" "uuid", "p_expected_working_article_version_id" "uuid", "p_expected_working_fingerprint" "text", "p_corrected_payload" "jsonb", "p_taxonomy_term_ids" "uuid"[], "p_application_summary" "text", "p_idempotency_key" "text", "p_correlation_id" "uuid") RETURNS TABLE("command_receipt_id" "uuid", "receipt_status" "text", "case_resource_id" "uuid", "case_revision" bigint, "result_payload" "jsonb", "idempotent_replay" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'editorial', 'platform_private', 'extensions'
    AS $_$
declare
  v_actor uuid;
  v_context record;
  v_begin record;
  v_case editorial.correction_cases%rowtype;
  v_decision editorial.correction_decisions%rowtype;
  v_target editorial.correction_targets%rowtype;
  v_case_resource editorial.resources%rowtype;
  v_article_resource editorial.resources%rowtype;
  v_article public.wk_articles%rowtype;
  v_working_version editorial.article_versions%rowtype;
  v_taxonomy_term_ids uuid[];
  v_taxonomy_count bigint;
  v_categories jsonb;
  v_tags jsonb;
  v_payload_hash text;
  v_request_payload jsonb;
  v_rejection_code text;
  v_rejection_message text;
  v_new_slug text;
  v_new_published_at timestamptz;
  v_new_hero_image_id uuid;
  v_new_version_id uuid;
  v_new_version_number bigint;
  v_new_fingerprint text;
  v_application_id uuid;
  v_result jsonb;
begin
  v_actor :=
    platform_private.assert_correction_capability(
      'apply_corrections'
    );

  select *
  into v_context
  from platform_private.correction_actor_context();

  if v_context.auth_role <> 'service_role'
     and not coalesce(
       public.current_user_is_administrator(),
       false
     )
     and not coalesce(
       public.current_user_has_capability(
         'edit_others_articles'
       ),
       false
     )
  then
    raise exception
      using
        errcode = '42501',
        message = 'The caller does not hold Article correction application authority.';
  end if;

  if p_case_resource_id is null
     or p_expected_case_revision < 1
     or p_expected_current_decision_id is null
     or p_primary_target_id is null
     or p_challenged_article_version_id is null
     or p_expected_published_article_version_id is null
     or p_correlation_id is null
     or nullif(
       btrim(p_application_summary),
       ''
     ) is null
     or length(p_application_summary) > 8000
     or p_corrected_payload is null
     or jsonb_typeof(p_corrected_payload) <>
       'object'
     or octet_length(
       p_corrected_payload::text
     ) > 4194304
  then
    raise exception
      using
        errcode = '22023',
        message = 'Case, revision, decision, target, Article state, corrected snapshot, summary, and correlation identity are required.';
  end if;

  if p_expected_working_article_version_id is null
     and p_expected_working_fingerprint is not null
  then
    raise exception
      using
        errcode = '22023',
        message = 'A working fingerprint requires an expected working Article version.';
  end if;

  if p_expected_working_article_version_id is not null
     and coalesce(
       p_expected_working_fingerprint,
       ''
     ) !~ '^[0-9a-f]{64}$'
  then
    raise exception
      using
        errcode = '22023',
        message = 'Expected working fingerprint must be a SHA-256 value.';
  end if;

  if not (
    p_corrected_payload ?& array[
      'title',
      'slug',
      'excerpt',
      'content_html',
      'author',
      'published_at',
      'seo',
      'hero_image_id',
      'hero_image_url'
    ]
  )
     or p_corrected_payload - array[
       'title',
       'slug',
       'excerpt',
       'content_html',
       'author',
       'published_at',
       'seo',
       'hero_image_id',
       'hero_image_url'
     ] <> '{}'::jsonb
  then
    raise exception
      using
        errcode = '22023',
        message = 'Corrected Article payload must contain exactly the complete supported snapshot fields.';
  end if;

  if nullif(
       btrim(
         p_corrected_payload ->> 'title'
       ),
       ''
     ) is null
     or nullif(
       btrim(
         p_corrected_payload ->> 'slug'
       ),
       ''
     ) is null
     or p_corrected_payload ->> 'content_html'
       is null
     or coalesce(
       jsonb_typeof(
         p_corrected_payload -> 'seo'
       ),
       ''
     ) <> 'object'
  then
    raise exception
      using
        errcode = '22023',
        message = 'Corrected Article title, slug, content, and SEO object are required.';
  end if;

  v_new_slug := btrim(
    p_corrected_payload ->> 'slug'
  );

  if v_new_slug !~
     '^[a-z0-9]+(?:-[a-z0-9]+)*$'
  then
    raise exception
      using
        errcode = '22023',
        message = 'Corrected Article slug is invalid.';
  end if;

  begin
    v_new_published_at :=
      nullif(
        p_corrected_payload ->>
          'published_at',
        ''
      )::timestamptz;

    v_new_hero_image_id :=
      nullif(
        p_corrected_payload ->>
          'hero_image_id',
        ''
      )::uuid;
  exception
    when invalid_text_representation
      or datetime_field_overflow
    then
      raise exception
        using
          errcode = '22023',
          message = 'Corrected Article publication or hero-image identity is invalid.';
  end;

  select coalesce(
    array_agg(
      distinct term_id
      order by term_id
    ),
    '{}'::uuid[]
  )
  into v_taxonomy_term_ids
  from unnest(
    coalesce(
      p_taxonomy_term_ids,
      '{}'::uuid[]
    )
  ) term_id;

  select count(*)
  into v_taxonomy_count
  from public.registry_taxonomy_terms term
  where term.id = any(
      v_taxonomy_term_ids
    )
    and term.taxonomy in (
      'category',
      'post_tag'
    )
    and term.status = 'active';

  if v_taxonomy_count <>
     cardinality(v_taxonomy_term_ids)
  then
    raise exception
      using
        errcode = '22023',
        message = 'Every corrected Article taxonomy identity must be active and supported.';
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'name',
        term.name,
        'slug',
        term.slug
      )
      order by term.name
    ),
    '[]'::jsonb
  )
  into v_categories
  from public.registry_taxonomy_terms term
  where term.id = any(
      v_taxonomy_term_ids
    )
    and term.taxonomy = 'category'
    and term.status = 'active';

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'name',
        term.name,
        'slug',
        term.slug
      )
      order by term.name
    ),
    '[]'::jsonb
  )
  into v_tags
  from public.registry_taxonomy_terms term
  where term.id = any(
      v_taxonomy_term_ids
    )
    and term.taxonomy = 'post_tag'
    and term.status = 'active';

  v_payload_hash := encode(
    extensions.digest(
      convert_to(
        jsonb_build_object(
          'corrected_payload',
          p_corrected_payload,
          'taxonomy_term_ids',
          to_jsonb(v_taxonomy_term_ids)
        )::text,
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );

  v_request_payload := jsonb_build_object(
    'expected_case_revision',
    p_expected_case_revision,
    'expected_current_decision_id',
    p_expected_current_decision_id,
    'primary_target_id',
    p_primary_target_id,
    'challenged_article_version_id',
    p_challenged_article_version_id,
    'expected_published_article_version_id',
    p_expected_published_article_version_id,
    'expected_working_article_version_id',
    p_expected_working_article_version_id,
    'expected_working_fingerprint',
    p_expected_working_fingerprint,
    'corrected_snapshot_request_fingerprint',
    v_payload_hash,
    'application_summary',
    btrim(p_application_summary),
    'correlation_id',
    p_correlation_id
  );

  select *
  into v_begin
  from platform_private.begin_resource_command(
    'correction.article.apply',
    p_case_resource_id,
    p_idempotency_key,
    v_request_payload
  );

  if v_begin.idempotent_replay then
    return query
    select *
    from platform_private.read_correction_command_result(
      v_begin.command_receipt_id,
      true
    );
    return;
  end if;

  select resource.*
  into v_case_resource
  from editorial.resources resource
  where resource.id =
    p_case_resource_id
    and resource.resource_kind =
      'correction_case'
  for update;

  select correction_case.*
  into v_case
  from editorial.correction_cases correction_case
  where correction_case.resource_id =
    p_case_resource_id
  for update;

  if not found
     or v_case_resource.id is null
  then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'case_not_found',
      'The correction case does not exist.',
      jsonb_build_object(
        'case_revision',
        null,
        'case_state',
        null
      )
    );

    return query
    select *
    from platform_private.read_correction_command_result(
      v_begin.command_receipt_id,
      false
    );
    return;
  end if;

  perform platform_private.append_correction_application_event(
    p_case_resource_id,
    'application_accepted',
    v_case.current_revision,
    v_case.current_revision,
    v_case.case_state,
    v_case.case_state,
    v_actor,
    'Article correction application command accepted.',
    v_case.current_decision_id,
    null,
    p_primary_target_id,
    v_begin.command_receipt_id,
    p_correlation_id,
    jsonb_build_object(
      'expected_case_revision',
      p_expected_case_revision,
      'expected_current_decision_id',
      p_expected_current_decision_id,
      'expected_published_article_version_id',
      p_expected_published_article_version_id,
      'expected_working_article_version_id',
      p_expected_working_article_version_id,
      'corrected_snapshot_request_fingerprint',
      v_payload_hash
    )
  );

  if v_case.current_revision <>
     p_expected_case_revision
  then
    v_rejection_code :=
      'case_revision_changed';
    v_rejection_message :=
      'The correction case revision changed.';
  elsif v_case.current_application_id is not null
        or exists (
          select 1
          from editorial.correction_applications application
          where application.decision_id =
            p_expected_current_decision_id
        )
  then
    v_rejection_code :=
      'application_already_succeeded';
    v_rejection_message :=
      'The current correction decision already has a successful application.';
  elsif v_case.case_state <> 'decided'
        or v_case.current_decision_id
          is distinct from
            p_expected_current_decision_id
  then
    v_rejection_code :=
      'decision_changed';
    v_rejection_message :=
      'The current correction decision or case state changed.';
  else
    select decision.*
    into v_decision
    from editorial.correction_decisions decision
    where decision.id =
      p_expected_current_decision_id;

    if not found
       or v_decision.case_resource_id
         is distinct from
           p_case_resource_id
    then
      v_rejection_code :=
        'decision_changed';
      v_rejection_message :=
        'The current correction decision changed.';
    elsif v_decision.outcome <>
          'correction_required'
    then
      v_rejection_code :=
        'decision_not_correction_required';
      v_rejection_message :=
        'The current correction decision does not require a correction.';
    end if;
  end if;

  if v_rejection_code is null then
    select target.*
    into v_target
    from editorial.correction_targets target
    where target.id =
      p_primary_target_id
    for update;

    if not found
       or v_target.case_resource_id
         is distinct from
           p_case_resource_id
       or v_target.target_role <> 'primary'
       or v_target.target_resource_kind <>
         'article'
       or v_target.target_version_type <>
         'article_version'
       or v_target.target_version_id
         is distinct from
           p_challenged_article_version_id
    then
      v_rejection_code :=
        'target_changed';
      v_rejection_message :=
        'The primary correction target changed.';
    end if;
  end if;

  if v_rejection_code is null then
    select resource.*
    into v_article_resource
    from editorial.resources resource
    where resource.id =
      v_target.target_resource_id
      and resource.resource_kind = 'article'
    for update;

    if not found then
      v_rejection_code :=
        'target_changed';
      v_rejection_message :=
        'The target Article resource changed.';
    end if;
  end if;

  if v_rejection_code is null then
    select article.*
    into v_article
    from editorial.article_resources binding
    join public.wk_articles article
      on article.id = binding.article_id
    where binding.resource_id =
      v_article_resource.id
      and binding.resource_kind = 'article'
    for update of article;

    if not found then
      v_rejection_code :=
        'target_changed';
      v_rejection_message :=
        'The target Article binding changed.';
    end if;
  end if;

  if v_rejection_code is null
     and (
       v_article_resource.current_published_version_id
         is distinct from
           p_expected_published_article_version_id
       or p_expected_published_article_version_id
         is distinct from
           p_challenged_article_version_id
       or v_target.target_resource_id
         is distinct from
           v_article_resource.id
     )
  then
    v_rejection_code :=
      'published_version_changed';
    v_rejection_message :=
      'The current published Article version changed.';
  end if;

  if v_rejection_code is null
     and v_article_resource.current_working_version_id
       is distinct from
         p_expected_working_article_version_id
  then
    v_rejection_code :=
      'working_version_changed';
    v_rejection_message :=
      'The current working Article version changed.';
  end if;

  if v_rejection_code is null
     and p_expected_working_article_version_id
       is not null
  then
    select version.*
    into v_working_version
    from editorial.article_versions version
    where version.id =
      p_expected_working_article_version_id;

    if not found
       or v_working_version.resource_id
         is distinct from
           v_article_resource.id
       or v_working_version.content_fingerprint
         is distinct from
           p_expected_working_fingerprint
    then
      v_rejection_code :=
        'working_fingerprint_changed';
      v_rejection_message :=
        'The current working Article fingerprint changed.';
    end if;
  end if;

  if v_rejection_code is null
     and (
       select count(*)
       from public.registry_taxonomy_terms term
       where term.id = any(
           v_taxonomy_term_ids
         )
         and term.taxonomy in (
           'category',
           'post_tag'
         )
         and term.status = 'active'
     ) <> cardinality(v_taxonomy_term_ids)
  then
    v_rejection_code :=
      'target_changed';
    v_rejection_message :=
      'The corrected Article taxonomy authority changed.';
  end if;

  if v_rejection_code is null
     and v_new_slug <> v_article.slug
     and exists (
       select 1
       from public.wk_articles other_article
       where other_article.slug =
           v_new_slug
         and other_article.id <>
           v_article.id
     )
  then
    v_rejection_code :=
      'target_changed';
    v_rejection_message :=
      'The corrected Article slug is no longer available.';
  end if;

  if v_rejection_code is not null then
    v_result := jsonb_build_object(
      'case_resource_id',
      p_case_resource_id,
      'case_revision',
      v_case.current_revision,
      'case_state',
      v_case.case_state,
      'rejection_code',
      v_rejection_code
    );

    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      v_rejection_code,
      v_rejection_message,
      v_result
    );

    perform platform_private.append_correction_application_event(
      p_case_resource_id,
      'application_rejected_stale',
      v_case.current_revision,
      v_case.current_revision,
      v_case.case_state,
      v_case.case_state,
      v_actor,
      v_rejection_message,
      v_case.current_decision_id,
      null,
      p_primary_target_id,
      v_begin.command_receipt_id,
      p_correlation_id,
      jsonb_build_object(
        'rejection_code',
        v_rejection_code,
        'expected_case_revision',
        p_expected_case_revision,
        'actual_case_revision',
        v_case.current_revision,
        'expected_current_decision_id',
        p_expected_current_decision_id,
        'actual_current_decision_id',
        v_case.current_decision_id,
        'expected_published_article_version_id',
        p_expected_published_article_version_id,
        'actual_published_article_version_id',
        v_article_resource.current_published_version_id,
        'expected_working_article_version_id',
        p_expected_working_article_version_id,
        'actual_working_article_version_id',
        v_article_resource.current_working_version_id
      )
    );

    return query
    select *
    from platform_private.read_correction_command_result(
      v_begin.command_receipt_id,
      false
    );
    return;
  end if;

  if v_new_slug <> v_article.slug then
    insert into public.wk_slug_redirects (
      old_slug,
      new_slug,
      entity_type,
      created_by,
      old_path,
      new_path,
      redirect_status,
      updated_at
    )
    values (
      v_article.slug,
      v_new_slug,
      'article',
      v_actor::text,
      '/magazine/' || v_article.slug,
      '/magazine/' || v_new_slug,
      308,
      now()
    );
  end if;

  update public.wk_articles as article
  set
    title =
      p_corrected_payload ->> 'title',
    slug = v_new_slug,
    excerpt =
      p_corrected_payload ->> 'excerpt',
    content_html =
      p_corrected_payload ->> 'content_html',
    author =
      p_corrected_payload ->> 'author',
    published_at =
      v_new_published_at,
    seo =
      p_corrected_payload -> 'seo',
    hero_image_id =
      v_new_hero_image_id,
    hero_image_url =
      p_corrected_payload ->>
        'hero_image_url',
    categories = v_categories,
    tags = v_tags,
    draft_version =
      article.draft_version + 1,
    modified_at = now(),
    updated_at = now()
  where article.id = v_article.id
  returning article.*
  into v_article;

  delete from editorial.article_taxonomy_terms
  where resource_id =
    v_article_resource.id;

  insert into editorial.article_taxonomy_terms (
    resource_id,
    term_id,
    taxonomy,
    created_by
  )
  select
    v_article_resource.id,
    term.id,
    term.taxonomy,
    v_actor
  from public.registry_taxonomy_terms term
  where term.id = any(
      v_taxonomy_term_ids
    )
    and term.taxonomy in (
      'category',
      'post_tag'
    )
    and term.status = 'active'
  on conflict do nothing;

  v_new_version_number :=
    editorial.next_article_version_number(
      v_article_resource.id
    );

  v_new_fingerprint :=
    editorial.article_snapshot_fingerprint(
      v_article.title,
      v_article.slug,
      v_article.excerpt,
      v_article.content_html,
      v_article.author,
      v_article.hero_image_id,
      v_article.hero_image_url,
      v_article.seo,
      v_article.wp_status,
      v_article.published_at,
      v_article.categories,
      v_article.tags
    );

  insert into editorial.article_versions (
    resource_id,
    article_id,
    version_number,
    version_kind,
    source_draft_version,
    title,
    slug,
    excerpt,
    content_html,
    author_display,
    owner_id,
    hero_image_id,
    hero_image_url,
    seo,
    lifecycle_state,
    wp_status,
    published_at,
    category_snapshot,
    tag_snapshot,
    created_by,
    content_fingerprint
  )
  values (
    v_article_resource.id,
    v_article.id,
    v_new_version_number,
    'correction',
    v_article.draft_version,
    v_article.title,
    v_article.slug,
    v_article.excerpt,
    v_article.content_html,
    v_article.author,
    v_article_resource.owner_id,
    v_article.hero_image_id,
    v_article.hero_image_url,
    v_article.seo,
    v_article_resource.lifecycle_state,
    v_article.wp_status,
    v_article.published_at,
    v_article.categories,
    v_article.tags,
    v_actor,
    v_new_fingerprint
  )
  returning id
  into v_new_version_id;

  update editorial.resources
  set
    current_working_version_id =
      v_new_version_id,
    updated_at = now()
  where id = v_article_resource.id;

  insert into editorial.correction_applications (
    case_resource_id,
    decision_id,
    command_receipt_id,
    target_id,
    target_resource_id,
    challenged_version_id,
    expected_published_version_id,
    expected_working_version_id,
    expected_working_fingerprint,
    resulting_version_id,
    application_summary,
    applied_by,
    correlation_id
  )
  values (
    p_case_resource_id,
    v_decision.id,
    v_begin.command_receipt_id,
    v_target.id,
    v_article_resource.id,
    p_challenged_article_version_id,
    p_expected_published_article_version_id,
    p_expected_working_article_version_id,
    p_expected_working_fingerprint,
    v_new_version_id,
    btrim(p_application_summary),
    v_actor,
    p_correlation_id
  )
  returning id
  into v_application_id;

  update editorial.correction_cases
  set
    case_state = 'applied',
    current_revision =
      v_case.current_revision + 1,
    current_application_id =
      v_application_id,
    updated_by = v_actor,
    updated_at = now()
  where resource_id =
    p_case_resource_id;

  perform platform_private.append_correction_application_event(
    p_case_resource_id,
    'application_succeeded',
    v_case.current_revision,
    v_case.current_revision + 1,
    v_case.case_state,
    'applied',
    v_actor,
    btrim(p_application_summary),
    v_decision.id,
    v_application_id,
    v_target.id,
    v_begin.command_receipt_id,
    p_correlation_id,
    jsonb_build_object(
      'application_id',
      v_application_id,
      'target_resource_id',
      v_article_resource.id,
      'challenged_version_id',
      p_challenged_article_version_id,
      'expected_published_version_id',
      p_expected_published_article_version_id,
      'expected_working_version_id',
      p_expected_working_article_version_id,
      'resulting_version_id',
      v_new_version_id,
      'resulting_version_number',
      v_new_version_number,
      'resulting_content_fingerprint',
      v_new_fingerprint,
      'published_pointer_changed',
      false
    )
  );

  v_result := jsonb_build_object(
    'case_resource_id',
    p_case_resource_id,
    'case_revision',
    v_case.current_revision + 1,
    'case_state',
    'applied',
    'application_id',
    v_application_id,
    'decision_id',
    v_decision.id,
    'target_id',
    v_target.id,
    'target_resource_id',
    v_article_resource.id,
    'resulting_version_id',
    v_new_version_id,
    'resulting_version_number',
    v_new_version_number,
    'resulting_content_fingerprint',
    v_new_fingerprint,
    'current_published_version_id',
    p_expected_published_article_version_id,
    'current_working_version_id',
    v_new_version_id
  );

  perform platform_private.complete_resource_command(
    v_begin.command_receipt_id,
    v_result
  );

  return query
  select *
  from platform_private.read_correction_command_result(
    v_begin.command_receipt_id,
    false
  );
end;
$_$;


ALTER FUNCTION "public"."apply_article_correction"("p_case_resource_id" "uuid", "p_expected_case_revision" bigint, "p_expected_current_decision_id" "uuid", "p_primary_target_id" "uuid", "p_challenged_article_version_id" "uuid", "p_expected_published_article_version_id" "uuid", "p_expected_working_article_version_id" "uuid", "p_expected_working_fingerprint" "text", "p_corrected_payload" "jsonb", "p_taxonomy_term_ids" "uuid"[], "p_application_summary" "text", "p_idempotency_key" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."apply_article_correction"("p_case_resource_id" "uuid", "p_expected_case_revision" bigint, "p_expected_current_decision_id" "uuid", "p_primary_target_id" "uuid", "p_challenged_article_version_id" "uuid", "p_expected_published_article_version_id" "uuid", "p_expected_working_article_version_id" "uuid", "p_expected_working_fingerprint" "text", "p_corrected_payload" "jsonb", "p_taxonomy_term_ids" "uuid"[], "p_application_summary" "text", "p_idempotency_key" "text", "p_correlation_id" "uuid") IS 'Creates one immutable correction Article version after exact case, decision, target, publication, working-version, and fingerprint verification. It never changes the current published pointer.';



CREATE OR REPLACE FUNCTION "public"."approve_article_version"("p_article_id" "uuid", "p_version_id" "uuid" DEFAULT NULL::"uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS TABLE("article_id" "uuid", "article_slug" "text", "draft_version" bigint, "version_id" "uuid", "version_number" bigint, "lifecycle_status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_article public.wk_articles%rowtype;
  v_resource editorial.resources%rowtype;
  v_source_version_id uuid;
  v_version_id uuid;
  v_version_number bigint;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  if not editorial.current_user_can_review_article() then
    raise exception 'Permission denied';
  end if;

  select article.*
  into v_article
  from public.wk_articles article
  where article.id = p_article_id
  for update;

  if not found then
    raise exception 'Article not found';
  end if;

  select resource.*
  into v_resource
  from editorial.article_resources binding
  join editorial.resources resource
    on resource.id = binding.resource_id
  where binding.article_id = p_article_id
  for update of resource;

  if not found then
    raise exception 'Article resource identity not found';
  end if;

  v_source_version_id :=
    coalesce(
      p_version_id,
      v_resource.current_submitted_version_id,
      v_resource.current_working_version_id
    );

  select copied.version_id, copied.version_number
  into v_version_id, v_version_number
  from editorial.copy_article_lifecycle_version(
    v_source_version_id,
    'approved',
    'approved',
    'pending',
    null
  ) copied;

  update editorial.resources
  set
    current_approved_version_id = v_version_id,
    lifecycle_state = 'active',
    visibility = 'private',
    updated_at = now()
  where id = v_resource.id;

  insert into editorial.article_lifecycle_events (
    resource_id,
    article_id,
    version_id,
    action,
    prior_status,
    resulting_status,
    note
  )
  values (
    v_resource.id,
    p_article_id,
    v_version_id,
    'approved',
    v_article.wp_status,
    'approved',
    p_note
  );

  article_id := p_article_id;
  article_slug := v_article.slug;
  draft_version := v_article.draft_version;
  version_id := v_version_id;
  version_number := v_version_number;
  lifecycle_status := 'approved';
  return next;
end;
$$;


ALTER FUNCTION "public"."approve_article_version"("p_article_id" "uuid", "p_version_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."archive_article"("p_article_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS TABLE("article_id" "uuid", "article_slug" "text", "draft_version" bigint, "version_id" "uuid", "version_number" bigint, "lifecycle_status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_article public.wk_articles%rowtype;
  v_resource editorial.resources%rowtype;
  v_prior_status text;
  v_target_version_id uuid;
  v_target_number bigint;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  if not editorial.current_user_can_publish_article() then
    raise exception 'Permission denied';
  end if;

  select article.*
  into v_article
  from public.wk_articles article
  where article.id = p_article_id
  for update;

  if not found then
    raise exception 'Article not found';
  end if;

  select resource.*
  into v_resource
  from editorial.article_resources binding
  join editorial.resources resource
    on resource.id = binding.resource_id
  where binding.article_id = p_article_id
  for update of resource;

  if not found then
    raise exception 'Article resource identity not found';
  end if;

  v_prior_status := v_article.wp_status;
  v_target_version_id :=
    coalesce(
      v_resource.current_published_version_id,
      v_resource.current_working_version_id
    );

  select version.version_number
  into v_target_number
  from editorial.article_versions version
  where version.id = v_target_version_id;

  update public.wk_articles as article
  set
    wp_status = 'trash',
    draft_version = article.draft_version + 1,
    updated_at = now(),
    modified_at = now()
  where article.id = p_article_id
  returning article.*
  into v_article;

  update public.wk_article_publication_snapshots snapshot
  set
    is_active = false,
    updated_at = now()
  where snapshot.article_id = p_article_id
    and snapshot.is_active = true;

  update editorial.resources
  set
    lifecycle_state = 'archived',
    visibility = 'private',
    updated_at = now()
  where id = v_resource.id;

  insert into editorial.article_lifecycle_events (
    resource_id,
    article_id,
    version_id,
    action,
    prior_status,
    resulting_status,
    note
  )
  values (
    v_resource.id,
    p_article_id,
    v_target_version_id,
    'archived',
    v_prior_status,
    'trash',
    p_note
  );

  article_id := p_article_id;
  article_slug := v_article.slug;
  draft_version := v_article.draft_version;
  version_id := v_target_version_id;
  version_number := coalesce(v_target_number, 0);
  lifecycle_status := 'archived';
  return next;
end;
$$;


ALTER FUNCTION "public"."archive_article"("p_article_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."archive_media_asset"("p_asset_id" "uuid", "p_expected_authority_revision" bigint, "p_reason" "text", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("asset_id" "uuid", "lifecycle_state" "text", "authority_revision" bigint, "correlation_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'media', 'auth'
    AS $$
declare
  v_actor_id uuid;
  v_asset media.assets%rowtype;
  v_correlation_id uuid := coalesce(
    p_correlation_id,
    gen_random_uuid()
  );
begin
  v_actor_id :=
    media.require_command_actor('archive_media_assets');

  if nullif(btrim(p_reason), '') is null then
    raise exception 'Media archive reason is required';
  end if;

  select *
  into v_asset
  from media.assets
  where id = p_asset_id
  for update;

  if not found then
    raise exception 'Media asset does not exist';
  end if;

  if v_asset.authority_revision <>
     p_expected_authority_revision
  then
    raise exception
      'Stale Media authority revision: expected %, current %',
      p_expected_authority_revision,
      v_asset.authority_revision;
  end if;

  if v_asset.lifecycle_state <> 'active' then
    raise exception 'Only active Media assets may be archived';
  end if;

  update media.assets as asset_row
  set
    lifecycle_state = 'archived',
    authority_revision = asset_row.authority_revision + 1,
    archived_by = v_actor_id,
    archived_at = now(),
    archive_reason = btrim(p_reason),
    updated_by = v_actor_id,
    updated_at = now()
  where asset_row.id = p_asset_id;

  insert into media.events (
    asset_id,
    event_type,
    actor_id,
    reason,
    prior_state,
    resulting_state,
    correlation_id
  )
  values (
    p_asset_id,
    'asset_archived',
    v_actor_id,
    btrim(p_reason),
    jsonb_build_object(
      'lifecycle_state', v_asset.lifecycle_state,
      'authority_revision', v_asset.authority_revision
    ),
    jsonb_build_object(
      'lifecycle_state', 'archived',
      'authority_revision',
      v_asset.authority_revision + 1
    ),
    v_correlation_id
  );

  return query
  select
    p_asset_id,
    'archived'::text,
    v_asset.authority_revision + 1,
    v_correlation_id;
end;
$$;


ALTER FUNCTION "public"."archive_media_asset"("p_asset_id" "uuid", "p_expected_authority_revision" bigint, "p_reason" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."archive_media_usage"("p_usage_link_id" "uuid", "p_expected_usage_revision" bigint, "p_reason" "text", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("usage_link_id" "uuid", "usage_state" "text", "usage_revision" bigint, "correlation_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'media', 'auth'
    AS $$
declare
  v_actor_id uuid;
  v_usage media.usage_links%rowtype;
  v_new_revision bigint;
  v_correlation_id uuid := coalesce(
    p_correlation_id,
    gen_random_uuid()
  );
begin
  v_actor_id :=
    media.require_command_actor('manage_media_usage');

  if nullif(btrim(p_reason), '') is null then
    raise exception
      'Media usage archive reason is required';
  end if;

  select usage_row.*
  into v_usage
  from media.usage_links usage_row
  where usage_row.id = p_usage_link_id
  for update;

  if not found then
    raise exception
      'Media usage does not exist';
  end if;

  if v_usage.usage_revision <>
     p_expected_usage_revision
  then
    raise exception
      'Stale Media usage revision';
  end if;

  perform media.validate_usage_target(
    v_actor_id,
    v_usage.target_authority,
    v_usage.target_kind,
    v_usage.target_id,
    v_usage.target_version_kind,
    v_usage.target_version_id,
    true,
    false
  );

  if v_usage.usage_state = 'archived' then
    raise exception
      'Media usage is already archived';
  end if;

  update media.usage_links as usage_row
  set
    usage_state = 'archived',
    usage_revision =
      usage_row.usage_revision + 1,
    state_reason = btrim(p_reason),
    state_changed_by = v_actor_id,
    state_changed_at = now(),
    updated_at = now()
  where usage_row.id = p_usage_link_id
  returning usage_row.usage_revision
  into v_new_revision;

  insert into media.events (
    asset_id,
    asset_revision_id,
    usage_link_id,
    event_type,
    actor_id,
    reason,
    prior_state,
    resulting_state,
    correlation_id
  )
  values (
    v_usage.asset_id,
    v_usage.asset_revision_id,
    v_usage.id,
    'usage_archived',
    v_actor_id,
    btrim(p_reason),
    jsonb_build_object(
      'usage_state', v_usage.usage_state,
      'usage_revision', v_usage.usage_revision
    ),
    jsonb_build_object(
      'usage_state', 'archived',
      'usage_revision', v_new_revision
    ),
    v_correlation_id
  );

  return query
  select
    p_usage_link_id,
    'archived'::text,
    v_new_revision,
    v_correlation_id;
end;
$$;


ALTER FUNCTION "public"."archive_media_usage"("p_usage_link_id" "uuid", "p_expected_usage_revision" bigint, "p_reason" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."archive_playlist"("p_playlist_id" "uuid", "p_expected_authority_revision" bigint, "p_idempotency_key" "text", "p_note" "text" DEFAULT NULL::"text", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("command_receipt_id" "uuid", "receipt_status" "text", "playlist_id" "uuid", "resource_id" "uuid", "authority_revision" bigint, "version_id" "uuid", "version_number" bigint, "lifecycle_status" "text", "result_payload" "jsonb", "idempotent_replay" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'editorial', 'platform_private'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_playlist public.wk_playlists%rowtype;
  v_binding editorial.playlist_resources%rowtype;
  v_target editorial.playlist_versions%rowtype;
  v_prior_status text;
  v_begin record;
  v_read record;
  v_result jsonb;
  v_correlation_id uuid :=
    coalesce(
      p_correlation_id,
      gen_random_uuid()
    );
begin
  if v_actor is null then
    raise exception 'Not authenticated';
  end if;

  if not (
    coalesce(
      public.current_user_is_administrator(),
      false
    )
    or coalesce(
      public.current_user_has_capability(
        'delete_playlists'
      ),
      false
    )
  ) then
    raise exception
      'Playlist archive permission is required';
  end if;

  select playlist.*
  into v_playlist
  from public.wk_playlists playlist
  where playlist.id = p_playlist_id
  for update;

  if not found then
    raise exception 'Playlist does not exist';
  end if;

  v_prior_status := v_playlist.status;

  select binding.*
  into v_binding
  from editorial.playlist_resources binding
  where binding.playlist_id = p_playlist_id
  for update;

  if not found then
    raise exception
      'Playlist Resource binding does not exist';
  end if;

  select version.*
  into v_target
  from editorial.playlist_versions version
  where version.id = coalesce(
    v_binding.current_working_version_id,
    v_binding.current_submitted_version_id,
    v_binding.current_approved_version_id,
    v_binding.current_published_version_id
  );

  select *
  into v_begin
  from platform_private.begin_authenticated_resource_command(
    'playlist.archive',
    v_binding.resource_id,
    p_idempotency_key,
    jsonb_build_object(
      'playlist_id',
        p_playlist_id,
      'expected_authority_revision',
        p_expected_authority_revision,
      'note',
        nullif(btrim(p_note), ''),
      'correlation_id',
        v_correlation_id
    )
  );

  if v_begin.idempotent_replay then
    select *
    into v_read
    from platform_private.read_authenticated_resource_command_result(
      v_begin.command_receipt_id,
      true
    );

    command_receipt_id := v_read.command_receipt_id;
    receipt_status := v_read.receipt_status;
    playlist_id := p_playlist_id;
    resource_id := v_read.resource_id;
    authority_revision :=
      nullif(
        v_read.result_payload ->> 'authority_revision',
        ''
      )::bigint;
    version_id :=
      nullif(
        v_read.result_payload ->> 'version_id',
        ''
      )::uuid;
    version_number :=
      nullif(
        v_read.result_payload ->> 'version_number',
        ''
      )::bigint;
    lifecycle_status :=
      v_read.result_payload ->> 'lifecycle_status';
    result_payload := v_read.result_payload;
    idempotent_replay := true;
    return next;
    return;
  end if;

  if p_expected_authority_revision is null
     or p_expected_authority_revision < 1
     or v_playlist.authority_revision <>
          p_expected_authority_revision
  then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'playlist_revision_changed',
      'The Playlist changed before it could be archived.',
      jsonb_build_object(
        'playlist_id',
          p_playlist_id,
        'authority_revision',
          v_playlist.authority_revision
      )
    );

  elsif v_playlist.status = 'archived'
  then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'playlist_already_archived',
      'This Playlist is already archived.',
      jsonb_build_object(
        'playlist_id',
          p_playlist_id
      )
    );

  else
    update editorial.playlist_scheduled_publications as scheduled
    set
      status = 'cancelled',
      updated_at = now()
    where scheduled.playlist_id = p_playlist_id
      and scheduled.status = 'scheduled';

    update editorial.playlist_resources as binding
    set current_published_version_id = null
    where binding.playlist_id = p_playlist_id;

    update editorial.resources resource
    set
      lifecycle_state = 'archived',
      visibility = 'private',
      updated_at = now()
    where resource.id =
            v_binding.resource_id;

    update public.wk_playlists playlist
    set
      status = 'archived',
      authority_revision =
        playlist.authority_revision + 1,
      updated_at = now()
    where playlist.id = p_playlist_id
    returning playlist.*
    into v_playlist;

    perform editorial.append_playlist_lifecycle_event(
      v_binding.resource_id,
      p_playlist_id,
      v_target.id,
      'archived',
      v_prior_status,
      'archived',
      p_note,
      v_actor,
      v_begin.command_receipt_id,
      jsonb_build_object(
        'correlation_id',
          v_correlation_id
      )
    );

    v_result := jsonb_build_object(
      'playlist_id',
        p_playlist_id,
      'resource_id',
        v_binding.resource_id,
      'authority_revision',
        v_playlist.authority_revision,
      'version_id',
        v_target.id,
      'version_number',
        v_target.version_number,
      'lifecycle_status',
        'archived',
      'correlation_id',
        v_correlation_id
    );

    perform platform_private.complete_resource_command(
      v_begin.command_receipt_id,
      v_result
    );
  end if;

  select *
  into v_read
  from platform_private.read_authenticated_resource_command_result(
    v_begin.command_receipt_id,
    false
  );

  command_receipt_id := v_read.command_receipt_id;
  receipt_status := v_read.receipt_status;
  playlist_id := p_playlist_id;
  resource_id := v_read.resource_id;
  authority_revision :=
    nullif(
      v_read.result_payload ->> 'authority_revision',
      ''
    )::bigint;
  version_id :=
    nullif(
      v_read.result_payload ->> 'version_id',
      ''
    )::uuid;
  version_number :=
    nullif(
      v_read.result_payload ->> 'version_number',
      ''
    )::bigint;
  lifecycle_status :=
    v_read.result_payload ->> 'lifecycle_status';
  result_payload := v_read.result_payload;
  idempotent_replay := false;
  return next;
end;
$$;


ALTER FUNCTION "public"."archive_playlist"("p_playlist_id" "uuid", "p_expected_authority_revision" bigint, "p_idempotency_key" "text", "p_note" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assign_correction_case"("p_case_resource_id" "uuid", "p_expected_case_revision" bigint, "p_investigator_id" "uuid", "p_reason" "text", "p_idempotency_key" "text", "p_correlation_id" "uuid") RETURNS TABLE("command_receipt_id" "uuid", "receipt_status" "text", "case_resource_id" "uuid", "case_revision" bigint, "result_payload" "jsonb", "idempotent_replay" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'editorial', 'platform_private'
    AS $$
declare
  v_actor uuid;
  v_begin record;
  v_case editorial.correction_cases%rowtype;
  v_event_type text;
  v_result jsonb;
begin
  v_actor :=
    platform_private.assert_correction_capability(
      'triage_corrections'
    );

  if p_case_resource_id is null
     or p_expected_case_revision < 1
     or p_investigator_id is null
     or p_correlation_id is null
     or nullif(btrim(p_reason), '') is null
  then
    raise exception
      using errcode = '22023',
      message = 'Case, revision, investigator, reason, and correlation identity are required.';
  end if;

  if not exists (
    select 1
    from auth.users user_row
    where user_row.id = p_investigator_id
  ) then
    raise exception
      using errcode = 'P0002',
      message = 'The investigator does not exist.';
  end if;

  select *
  into v_begin
  from platform_private.begin_resource_command(
    'correction.case.assign',
    p_case_resource_id,
    p_idempotency_key,
    jsonb_build_object(
      'expected_case_revision', p_expected_case_revision,
      'investigator_id', p_investigator_id,
      'reason', btrim(p_reason),
      'correlation_id', p_correlation_id
    )
  );

  if v_begin.idempotent_replay then
    return query
    select *
    from platform_private.read_correction_command_result(
      v_begin.command_receipt_id,
      true
    );
    return;
  end if;

  select correction_case.*
  into v_case
  from editorial.correction_cases correction_case
  where correction_case.resource_id =
    p_case_resource_id
  for update;

  if not found then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'case_not_found',
      'The correction case does not exist.',
      jsonb_build_object('case_revision', null)
    );
  elsif v_case.current_revision <>
        p_expected_case_revision
  then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'case_revision_changed',
      'The correction case revision changed.',
      jsonb_build_object(
        'case_revision', v_case.current_revision,
        'case_state', v_case.case_state
      )
    );
  elsif v_case.case_state not in (
    'triaged',
    'investigating'
  ) then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'invalid_transition',
      'Investigator assignment requires a triaged or investigating case.',
      jsonb_build_object(
        'case_revision', v_case.current_revision,
        'case_state', v_case.case_state
      )
    );
  else
    v_event_type :=
      case
        when v_case.assigned_investigator_id
          is null
          then 'investigator_assigned'
        else 'investigator_reassigned'
      end;

    update editorial.correction_cases
    set
      case_state = 'investigating',
      current_revision =
        v_case.current_revision + 1,
      assigned_investigator_id =
        p_investigator_id,
      assignment_reason = btrim(p_reason),
      assigned_at = now(),
      updated_by = v_actor,
      updated_at = now()
    where resource_id = p_case_resource_id;

    perform platform_private.append_correction_event(
      p_case_resource_id,
      v_event_type,
      v_case.current_revision,
      v_case.current_revision + 1,
      v_case.case_state,
      'investigating',
      v_actor,
      btrim(p_reason),
      null,
      null,
      null,
      null,
      v_begin.command_receipt_id,
      p_correlation_id,
      jsonb_build_object(
        'prior_investigator_id',
        v_case.assigned_investigator_id,
        'investigator_id',
        p_investigator_id
      )
    );

    v_result := jsonb_build_object(
      'case_resource_id', p_case_resource_id,
      'case_revision', v_case.current_revision + 1,
      'case_state', 'investigating',
      'investigator_id', p_investigator_id
    );

    perform platform_private.complete_resource_command(
      v_begin.command_receipt_id,
      v_result
    );
  end if;

  return query
  select *
  from platform_private.read_correction_command_result(
    v_begin.command_receipt_id,
    false
  );
end;
$$;


ALTER FUNCTION "public"."assign_correction_case"("p_case_resource_id" "uuid", "p_expected_case_revision" bigint, "p_investigator_id" "uuid", "p_reason" "text", "p_idempotency_key" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."user_role_assignments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "role_key" "text" NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "assigned_by" "uuid",
    "assigned_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "expires_at" timestamp with time zone,
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "user_role_assignments_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'pending'::"text", 'suspended'::"text", 'revoked'::"text"])))
);


ALTER TABLE "public"."user_role_assignments" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assign_user_role_admin"("target_user_id" "uuid", "target_role_key" "text", "target_display_name" "text" DEFAULT NULL::"text", "target_bio" "text" DEFAULT NULL::"text", "assignment_notes" "text" DEFAULT NULL::"text") RETURNS "public"."user_role_assignments"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  assigned public.user_role_assignments;
begin
  if not public.current_user_is_administrator() then
    raise exception 'Only administrators can assign roles.' using errcode = '42501';
  end if;

  insert into public.user_profiles (user_id, display_name, bio, status, created_at, updated_at)
  values (target_user_id, target_display_name, target_bio, 'active', now(), now())
  on conflict (user_id) do update set
    display_name = coalesce(excluded.display_name, user_profiles.display_name),
    bio = coalesce(excluded.bio, user_profiles.bio),
    status = 'active',
    updated_at = now();

  insert into public.user_role_assignments (user_id, role_key, status, assigned_by, assigned_at, notes, created_at, updated_at)
  values (target_user_id, target_role_key, 'active', auth.uid(), now(), assignment_notes, now(), now())
  on conflict (user_id, role_key) do update set
    status = 'active',
    assigned_by = auth.uid(),
    assigned_at = now(),
    notes = excluded.notes,
    updated_at = now()
  returning * into assigned;

  perform public.record_admin_audit('role_assigned', 'user_role_assignments', assigned.id::text, target_user_id, 'Role assigned from admin users console.', jsonb_build_object('role_key', target_role_key));
  return assigned;
end;
$$;


ALTER FUNCTION "public"."assign_user_role_admin"("target_user_id" "uuid", "target_role_key" "text", "target_display_name" "text", "target_bio" "text", "assignment_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."attach_article_version_citation"("p_article_version_id" "uuid", "p_citation_id" "uuid", "p_citation_purpose" "text", "p_target_anchor_type" "text", "p_target_anchor_data" "jsonb", "p_display_order" integer, "p_public_safe" boolean, "p_expected_citation_revision" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial', 'auth'
    AS $$
declare
  v_actor_id uuid;
  v_article_version editorial.article_versions%rowtype;
  v_resource editorial.resources%rowtype;
  v_citation editorial.citations%rowtype;
  v_source editorial.sources%rowtype;
  v_revision editorial.article_version_trust_revisions%rowtype;
  v_attachment_id uuid;
  v_public_safe boolean;
begin
  v_actor_id :=
    editorial.assert_citation_command_actor();

  if p_display_order is null
     or p_display_order < 0 then
    raise exception
      'Citation display order must be zero or greater';
  end if;

  if p_expected_citation_revision is null
     or p_expected_citation_revision < 1 then
    raise exception
      'Expected Citation revision must be one or greater';
  end if;

  if p_citation_purpose not in (
    'supports',
    'challenges',
    'contextualizes',
    'quotes',
    'documents',
    'methodology',
    'other'
  ) then
    raise exception
      'Choose a supported Citation purpose';
  end if;

  perform editorial.validate_citation_target_anchor(
    p_target_anchor_type,
    p_target_anchor_data
  );

  select *
  into v_article_version
  from editorial.article_versions article_version
  where article_version.id = p_article_version_id;

  if not found then
    raise exception
      'Article version was not found';
  end if;

  select *
  into v_resource
  from editorial.resources resource
  where resource.id = v_article_version.resource_id
    and resource.resource_kind = 'article';

  if not found then
    raise exception
      'Article resource was not found';
  end if;

  if auth.role() <> 'service_role'
     and not editorial.current_user_can_edit_article(
       v_resource.id
     ) then
    raise exception
      'You do not have authority to edit this Article';
  end if;

  insert into editorial.article_version_trust_revisions (
    article_version_id,
    citation_revision,
    credit_revision,
    updated_by,
    updated_at
  )
  values (
    p_article_version_id,
    1,
    1,
    v_actor_id,
    now()
  )
  on conflict (article_version_id) do nothing;

  select *
  into v_revision
  from editorial.article_version_trust_revisions revision
  where revision.article_version_id =
    p_article_version_id
  for update;

  if v_revision.citation_revision <>
       p_expected_citation_revision then
    raise exception
      'Citation revision conflict. Expected %, found %',
      p_expected_citation_revision,
      v_revision.citation_revision;
  end if;

  select *
  into v_citation
  from editorial.citations citation
  where citation.id = p_citation_id;

  if not found then
    raise exception
      'Citation was not found';
  end if;

  if v_citation.citation_state <> 'active' then
    raise exception
      'Only active Citations can be attached';
  end if;

  v_public_safe := coalesce(p_public_safe, false);

  if v_public_safe then
    if not v_citation.public_safe then
      raise exception
        'This Citation is not approved for public use';
    end if;

    select *
    into v_source
    from editorial.sources source
    where source.id = v_citation.source_id;

    if not found
       or v_source.source_state <> 'active'
       or v_source.review_status <> 'approved'
       or v_source.current_approved_version_id
            is distinct from
            v_citation.source_version_id
       or v_source.exposure_class not in (
            'public',
            'public_redacted'
          ) then
      raise exception
        'Citation Source is not currently eligible for public attachment';
    end if;
  end if;

  if exists (
    select 1
    from editorial.resource_citations attachment
    where attachment.target_version_id =
            p_article_version_id
      and attachment.citation_id = p_citation_id
  ) then
    raise exception
      'Citation is already attached to this Article version';
  end if;

  if exists (
    select 1
    from editorial.resource_citations attachment
    where attachment.target_version_id =
            p_article_version_id
      and attachment.display_order = p_display_order
  ) then
    raise exception
      'Citation display order is already in use';
  end if;

  insert into editorial.resource_citations (
    resource_id,
    resource_kind,
    target_version_type,
    target_version_id,
    citation_id,
    citation_purpose,
    target_anchor_type,
    target_anchor_data,
    display_order,
    public_safe,
    created_by
  )
  values (
    v_resource.id,
    'article',
    'article_version',
    p_article_version_id,
    p_citation_id,
    p_citation_purpose,
    p_target_anchor_type,
    p_target_anchor_data,
    p_display_order,
    v_public_safe,
    v_actor_id
  )
  returning id
  into v_attachment_id;

  update editorial.article_version_trust_revisions
  set
    citation_revision =
      v_revision.citation_revision + 1,
    updated_by = v_actor_id,
    updated_at = now()
  where article_version_id = p_article_version_id;

  return jsonb_build_object(
    'attachment_id',
      v_attachment_id,
    'article_version_id',
      p_article_version_id,
    'citation_revision',
      v_revision.citation_revision + 1
  );
end;
$$;


ALTER FUNCTION "public"."attach_article_version_citation"("p_article_version_id" "uuid", "p_citation_id" "uuid", "p_citation_purpose" "text", "p_target_anchor_type" "text", "p_target_anchor_data" "jsonb", "p_display_order" integer, "p_public_safe" boolean, "p_expected_citation_revision" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."attach_article_version_citation"("p_article_version_id" "uuid", "p_citation_id" "uuid", "p_citation_purpose" "text", "p_target_anchor_type" "text", "p_target_anchor_data" "jsonb", "p_display_order" integer, "p_public_safe" boolean, "p_expected_citation_revision" bigint) IS 'Attaches one Citation to one immutable Article version with revision control.';



CREATE OR REPLACE FUNCTION "public"."attach_article_version_credit"("p_article_version_id" "uuid", "p_credit_id" "uuid", "p_display_order" integer, "p_is_primary" boolean, "p_public_safe" boolean, "p_expected_credit_revision" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial', 'auth'
    AS $$
declare
  v_actor_id uuid;
  v_article_version editorial.article_versions%rowtype;
  v_resource editorial.resources%rowtype;
  v_credit editorial.credits%rowtype;
  v_governance editorial.credit_governance%rowtype;
  v_revision editorial.article_version_trust_revisions%rowtype;
  v_external_contributor editorial.external_contributors%rowtype;
  v_existing_count integer;
  v_attachment_id uuid;
  v_public_safe boolean;
begin
  v_actor_id :=
    editorial.assert_credit_command_actor();

  if p_display_order is null
     or p_display_order < 0 then
    raise exception
      'Credit display order must be zero or greater';
  end if;

  if p_expected_credit_revision is null
     or p_expected_credit_revision < 1 then
    raise exception
      'Expected Credit revision must be one or greater';
  end if;

  select *
  into v_article_version
  from editorial.article_versions article_version
  where article_version.id = p_article_version_id;

  if not found then
    raise exception
      'Article version was not found';
  end if;

  select *
  into v_resource
  from editorial.resources resource
  where resource.id = v_article_version.resource_id
    and resource.resource_kind = 'article';

  if not found then
    raise exception
      'Article resource was not found';
  end if;

  if auth.role() <> 'service_role'
     and not editorial.current_user_can_edit_article(
       v_resource.id
     ) then
    raise exception
      'You do not have authority to edit this Article';
  end if;

  insert into editorial.article_version_trust_revisions (
    article_version_id,
    citation_revision,
    credit_revision,
    updated_by,
    updated_at
  )
  values (
    p_article_version_id,
    1,
    1,
    v_actor_id,
    now()
  )
  on conflict (article_version_id) do nothing;

  select *
  into v_revision
  from editorial.article_version_trust_revisions revision
  where revision.article_version_id =
    p_article_version_id
  for update;

  if v_revision.credit_revision <>
       p_expected_credit_revision then
    raise exception
      'Credit revision conflict. Expected %, found %',
      p_expected_credit_revision,
      v_revision.credit_revision;
  end if;

  select *
  into v_credit
  from editorial.credits credit
  where credit.id = p_credit_id;

  if not found then
    raise exception
      'Credit was not found';
  end if;

  select *
  into v_governance
  from editorial.credit_governance governance
  where governance.credit_id = p_credit_id;

  if not found then
    raise exception
      'Credit governance was not found';
  end if;

  if v_governance.credit_state <> 'active' then
    raise exception
      'Only active Credits can be attached';
  end if;

  v_public_safe := coalesce(p_public_safe, false);

  if v_public_safe then
    if not v_governance.public_safe then
      raise exception
        'This Credit is not approved for public use';
    end if;

    if v_credit.external_contributor_id is not null then
      select *
      into v_external_contributor
      from editorial.external_contributors contributor
      where contributor.id =
        v_credit.external_contributor_id;

      if not found
         or v_external_contributor.contributor_state <> 'active'
         or not v_external_contributor.public_safe
         or v_external_contributor.consent_status
              not in (
                'granted',
                'not_required'
              ) then
        raise exception
          'External-contributor Credit is not currently eligible for public attachment';
      end if;
    end if;
  end if;

  if exists (
    select 1
    from editorial.resource_credits attachment
    where attachment.target_version_id =
            p_article_version_id
      and attachment.credit_id = p_credit_id
  ) then
    raise exception
      'Credit is already attached to this Article version';
  end if;

  select count(*)
  into v_existing_count
  from editorial.resource_credits attachment
  where attachment.target_version_id =
    p_article_version_id;

  if p_display_order <> v_existing_count then
    raise exception
      'Single Credit attachment must append at display order %',
      v_existing_count;
  end if;

  if coalesce(p_is_primary, false)
     and v_credit.credit_role = 'author'
     and exists (
       select 1
       from editorial.resource_credits attachment
       join editorial.credits existing_credit
         on existing_credit.id = attachment.credit_id
       where attachment.target_version_id =
               p_article_version_id
         and attachment.is_primary
         and existing_credit.credit_role = 'author'
     ) then
    raise exception
      'An Article version can have at most one primary author Credit';
  end if;

  insert into editorial.resource_credits (
    resource_id,
    resource_kind,
    target_version_type,
    target_version_id,
    credit_id,
    display_order,
    is_primary,
    public_safe,
    created_by
  )
  values (
    v_resource.id,
    'article',
    'article_version',
    p_article_version_id,
    p_credit_id,
    p_display_order,
    coalesce(p_is_primary, false),
    v_public_safe,
    v_actor_id
  )
  returning id
  into v_attachment_id;

  update editorial.article_version_trust_revisions
  set
    credit_revision =
      v_revision.credit_revision + 1,
    updated_by = v_actor_id,
    updated_at = now()
  where article_version_id = p_article_version_id;

  return jsonb_build_object(
    'attachment_id',
      v_attachment_id,
    'article_version_id',
      p_article_version_id,
    'credit_revision',
      v_revision.credit_revision + 1
  );
end;
$$;


ALTER FUNCTION "public"."attach_article_version_credit"("p_article_version_id" "uuid", "p_credit_id" "uuid", "p_display_order" integer, "p_is_primary" boolean, "p_public_safe" boolean, "p_expected_credit_revision" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."attach_article_version_credit"("p_article_version_id" "uuid", "p_credit_id" "uuid", "p_display_order" integer, "p_is_primary" boolean, "p_public_safe" boolean, "p_expected_credit_revision" bigint) IS 'Appends one Credit to one immutable Article version with revision control.';



CREATE OR REPLACE FUNCTION "public"."attach_media_usage"("p_asset_id" "uuid", "p_resolution_mode" "text", "p_target_authority" "text", "p_target_kind" "text", "p_target_id" "uuid", "p_usage_role" "text", "p_asset_revision_id" "uuid" DEFAULT NULL::"uuid", "p_target_version_kind" "text" DEFAULT NULL::"text", "p_target_version_id" "uuid" DEFAULT NULL::"uuid", "p_placement_data" "jsonb" DEFAULT '{}'::"jsonb", "p_display_order" integer DEFAULT 0, "p_alt_text_snapshot" "text" DEFAULT NULL::"text", "p_caption_snapshot" "text" DEFAULT NULL::"text", "p_credit_snapshot" "text" DEFAULT NULL::"text", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("usage_link_id" "uuid", "usage_revision" bigint, "correlation_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'media', 'auth'
    AS $$
declare
  v_actor_id uuid;
  v_usage_link_id uuid := gen_random_uuid();
  v_correlation_id uuid := coalesce(
    p_correlation_id,
    gen_random_uuid()
  );
  v_lifecycle_state text;
  v_current_revision_id uuid;
  v_rights_status text;
  v_consent_status text;
  v_embargo_state text;
  v_embargo_until timestamptz;
  v_source_protection_class text;
  v_retention_state text;
  v_public_safety_state text;
begin
  v_actor_id :=
    media.require_command_actor('manage_media_usage');

  if not exists (
    select 1
    from media.usage_roles role_row
    where role_row.usage_role = p_usage_role
      and role_row.enabled
  ) then
    raise exception
      'Unknown or disabled Media usage role';
  end if;

  if not media.usage_role_matches_target(
       p_usage_role,
       p_target_authority,
       p_target_kind
     )
  then
    raise exception
      'Media usage role does not match the target authority and kind';
  end if;

  if p_placement_data is null
     or jsonb_typeof(p_placement_data) <> 'object'
  then
    raise exception
      'Media usage placement data must be an object';
  end if;

  if p_display_order < 0 then
    raise exception
      'Media usage display order cannot be negative';
  end if;

  perform media.validate_usage_target(
    v_actor_id,
    p_target_authority,
    p_target_kind,
    p_target_id,
    p_target_version_kind,
    p_target_version_id,
    true,
    true
  );

  select
    asset_row.lifecycle_state,
    asset_row.current_revision_id,
    governance_row.rights_status,
    governance_row.consent_status,
    governance_row.embargo_state,
    governance_row.embargo_until,
    governance_row.source_protection_class,
    governance_row.retention_state,
    governance_row.public_safety_state
  into
    v_lifecycle_state,
    v_current_revision_id,
    v_rights_status,
    v_consent_status,
    v_embargo_state,
    v_embargo_until,
    v_source_protection_class,
    v_retention_state,
    v_public_safety_state
  from media.assets asset_row
  join media.asset_governance_versions governance_row
    on governance_row.id =
      asset_row.current_governance_version_id
  where asset_row.id = p_asset_id
  for share of asset_row;

  if not found then
    raise exception
      'Media asset does not exist or has no current governance';
  end if;

  if v_lifecycle_state <> 'active' then
    raise exception
      'Only an active Media asset may receive a new usage';
  end if;

  if v_public_safety_state not in (
       'approved_public',
       'approved_redacted'
     )
     or v_rights_status not in (
       'owned',
       'licensed',
       'public_domain',
       'fair_use'
     )
     or v_consent_status not in (
       'granted',
       'not_required'
     )
     or v_source_protection_class not in (
       'public',
       'public_redacted'
     )
     or v_retention_state not in (
       'retain',
       'review_required'
     )
     or v_embargo_state = 'active'
     or (
       v_embargo_state = 'scheduled'
       and v_embargo_until is not null
       and v_embargo_until > now()
     )
  then
    raise exception
      'Current Media governance does not permit a new usage';
  end if;

  case p_resolution_mode
    when 'exact_revision' then
      if p_asset_revision_id is null then
        raise exception
          'Exact Media usage requires an asset revision';
      end if;

      if not exists (
        select 1
        from media.asset_revisions revision_row
        join media.file_objects file_row
          on file_row.id =
            revision_row.original_file_object_id
        where revision_row.id = p_asset_revision_id
          and revision_row.asset_id = p_asset_id
          and file_row.verification_state = 'verified'
      ) then
        raise exception
          'Exact Media usage requires a verified revision for the same asset';
      end if;

    when 'current_revision' then
      if p_asset_revision_id is not null then
        raise exception
          'Current-revision Media usage cannot bind an exact revision';
      end if;

      if media.usage_role_requires_stability(
           p_usage_role
         )
      then
        raise exception
          'Publication-stable Media usage cannot use current revision';
      end if;

      if v_current_revision_id is null
         or not exists (
           select 1
           from media.asset_revisions revision_row
           join media.file_objects file_row
             on file_row.id =
               revision_row.original_file_object_id
           where revision_row.id =
             v_current_revision_id
             and revision_row.asset_id = p_asset_id
             and file_row.verification_state = 'verified'
         )
      then
        raise exception
          'Current-revision Media usage requires one verified current revision';
      end if;

    when 'legacy_snapshot' then
      if p_asset_revision_id is not null then
        raise exception
          'Legacy-snapshot Media usage cannot bind an asset revision';
      end if;

      if not exists (
        select 1
        from media.legacy_asset_links link_row
        where link_row.asset_id = p_asset_id
          and nullif(
            btrim(link_row.legacy_snapshot ->> 'url'),
            ''
          ) is not null
      )
         or exists (
           select 1
           from media.asset_revisions revision_row
           where revision_row.asset_id = p_asset_id
         )
      then
        raise exception
          'Legacy-snapshot Media usage requires one immutable bridge and no canonical revision';
      end if;

    else
      raise exception
        'Unsupported Media usage resolution mode';
  end case;

  if exists (
    select 1
    from media.usage_links usage_row
    where usage_row.asset_id = p_asset_id
      and usage_row.target_authority =
        p_target_authority
      and usage_row.target_kind = p_target_kind
      and usage_row.target_id = p_target_id
      and coalesce(
        usage_row.target_version_kind,
        ''
      ) = coalesce(p_target_version_kind, '')
      and coalesce(
        usage_row.target_version_id,
        '00000000-0000-0000-0000-000000000000'::uuid
      ) = coalesce(
        p_target_version_id,
        '00000000-0000-0000-0000-000000000000'::uuid
      )
      and usage_row.usage_role = p_usage_role
      and md5(usage_row.placement_data::text) =
        md5(p_placement_data::text)
      and usage_row.usage_state = 'active'
  ) then
    raise exception
      'Duplicate active Media usage';
  end if;

  insert into media.usage_links (
    id,
    asset_id,
    asset_revision_id,
    resolution_mode,
    target_authority,
    target_kind,
    target_id,
    target_version_kind,
    target_version_id,
    usage_role,
    placement_data,
    display_order,
    alt_text_snapshot,
    caption_snapshot,
    credit_snapshot,
    usage_state,
    usage_revision,
    created_by
  )
  values (
    v_usage_link_id,
    p_asset_id,
    p_asset_revision_id,
    p_resolution_mode,
    p_target_authority,
    p_target_kind,
    p_target_id,
    nullif(btrim(p_target_version_kind), ''),
    p_target_version_id,
    p_usage_role,
    p_placement_data,
    p_display_order,
    nullif(btrim(p_alt_text_snapshot), ''),
    nullif(btrim(p_caption_snapshot), ''),
    nullif(btrim(p_credit_snapshot), ''),
    'active',
    1,
    v_actor_id
  );

  insert into media.events (
    asset_id,
    asset_revision_id,
    usage_link_id,
    event_type,
    actor_id,
    reason,
    resulting_state,
    correlation_id
  )
  values (
    p_asset_id,
    p_asset_revision_id,
    v_usage_link_id,
    'usage_attached',
    v_actor_id,
    'Governed Media usage attached',
    jsonb_build_object(
      'usage_revision', 1,
      'resolution_mode', p_resolution_mode,
      'target_authority', p_target_authority,
      'target_kind', p_target_kind,
      'target_id', p_target_id,
      'target_version_kind',
        nullif(btrim(p_target_version_kind), ''),
      'target_version_id', p_target_version_id,
      'usage_role', p_usage_role
    ),
    v_correlation_id
  );

  return query
  select
    v_usage_link_id,
    1::bigint,
    v_correlation_id;
end;
$$;


ALTER FUNCTION "public"."attach_media_usage"("p_asset_id" "uuid", "p_resolution_mode" "text", "p_target_authority" "text", "p_target_kind" "text", "p_target_id" "uuid", "p_usage_role" "text", "p_asset_revision_id" "uuid", "p_target_version_kind" "text", "p_target_version_id" "uuid", "p_placement_data" "jsonb", "p_display_order" integer, "p_alt_text_snapshot" "text", "p_caption_snapshot" "text", "p_credit_snapshot" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."briefing_cron_generate"() RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  edge_url text := 'https://pgzizndxdyhqmtyywjmt.supabase.co/functions/v1/briefing-handler';
  cron_secret text := current_setting('app.briefing_cron_secret', true);
  body jsonb;
  result record;
BEGIN
  IF cron_secret IS NULL OR cron_secret = '' THEN
    RAISE NOTICE 'CRON_SECRET not configured. Skipping briefing generation.';
    RETURN;
  END IF;

  body := jsonb_build_object(
    'action', 'cron_generate',
    'cron_secret', cron_secret
  );

  SELECT * INTO result FROM net.http_post(
    url := edge_url,
    body := body::text,
    headers := '{"Content-Type": "application/json"}'::jsonb,
    timeout_milliseconds := 30000
  );

  RAISE NOTICE 'Briefing cron complete. Response: %', result;
END;
$$;


ALTER FUNCTION "public"."briefing_cron_generate"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bulk_delete_taxonomy_terms"("p_term_ids" "uuid"[]) RETURNS TABLE("deleted_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_user_id uuid;
BEGIN
  v_user_id := auth.uid();

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM user_role_assignments
    WHERE user_id = v_user_id
      AND status = 'active'
      AND (expires_at IS NULL OR expires_at > now())
      AND (role_key = 'administrator' OR role_key IN (
        SELECT role_key FROM role_capabilities WHERE capability_key = 'manage_categories'
      ))
  ) THEN
    RAISE EXCEPTION 'Permission denied: manage_categories capability required';
  END IF;

  WITH deleted AS (
    DELETE FROM registry_taxonomy_terms
    WHERE id = ANY(p_term_ids)
    RETURNING id
  )
  SELECT COUNT(*)::bigint INTO deleted_count FROM deleted;

  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."bulk_delete_taxonomy_terms"("p_term_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_media_upload_session_v1"("p_session_id" "uuid", "p_reason" "text" DEFAULT 'Cancel resumable Media upload session'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'media', 'auth'
    AS $$
declare
  v_actor_id uuid;
  v_session media.upload_sessions%rowtype;
begin
  v_actor_id := media.require_command_actor('manage_media_assets');

  if nullif(btrim(p_reason), '') is null then
    raise exception 'Upload cancellation reason is required';
  end if;

  select session_row.*
  into v_session
  from media.upload_sessions session_row
  where session_row.id = p_session_id
  for update;

  if not found then
    raise exception 'Upload session does not exist';
  end if;

  if v_session.actor_id <> v_actor_id then
    raise exception 'Upload session belongs to another actor';
  end if;

  if v_session.state = 'verified' then
    raise exception 'Verified upload session cannot be cancelled';
  end if;

  if v_session.state in ('failed', 'cancelled', 'expired') then
    return jsonb_build_object(
      'session_id', v_session.id,
      'state', v_session.state,
      'error', v_session.last_error,
      'cancelled_at', v_session.cancelled_at,
      'expired_at', v_session.expired_at
    );
  end if;

  if v_session.state <> 'created' then
    raise exception 'Upload session is not eligible for cancellation';
  end if;

  update media.upload_sessions
  set
    state = 'cancelled',
    last_error = btrim(p_reason),
    cancelled_at = now(),
    expired_at = null,
    updated_at = now()
  where id = v_session.id;

  return jsonb_build_object(
    'session_id', v_session.id,
    'state', 'cancelled'
  );
end;
$$;


ALTER FUNCTION "public"."cancel_media_upload_session_v1"("p_session_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."chart_apply_candidate_rule_gate_biu"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_decision jsonb;
begin
  v_decision := public.chart_candidate_rule_decision(new.run_id, new.release_date, new.explicit);

  new.eligibility_decision_json := coalesce(new.eligibility_decision_json, '{}'::jsonb)
    || jsonb_build_object('ruleDecision', v_decision);

  if coalesce((v_decision->>'eligible')::boolean, true) = false
     and coalesce(new.status, 'pending') in ('pending', 'eligible') then
    new.status := 'excluded';
  end if;

  return new;
end;
$$;


