CREATE OR REPLACE FUNCTION "public"."chart_assert_committable_run"("p_run_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_report jsonb;
  v_committable boolean;
begin
  select public.chart_get_run_integrity_report(p_run_id)
  into v_report;

  if v_report is null then
    raise exception 'commit_blocked_run_not_found';
  end if;

  v_committable := coalesce((v_report->>'committable')::boolean, false);

  if not v_committable then
    raise exception 'commit_blocked_chart_run_integrity: %', v_report->'blockers'
      using detail = v_report::text;
  end if;

  return v_report;
end;
$$;


ALTER FUNCTION "public"."chart_assert_committable_run"("p_run_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."chart_assert_publishable_edition"("p_edition_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_report jsonb;
  v_publishable boolean;
  v_blockers text;
begin
  select public.chart_get_edition_integrity_report(p_edition_id)
  into v_report;

  v_publishable := coalesce((v_report->>'publishable')::boolean, false);

  if not v_publishable then
    v_blockers := coalesce(v_report->>'blockers', '[]');
    raise exception 'publish_blocked_chart_integrity: %', v_report->'blockers'
      using detail = v_report::text;
  end if;

  return v_report;
end;
$$;


