CREATE OR REPLACE FUNCTION "public"."chart_assert_rule_clean_run"("p_run_id" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_bad record;
begin
  select c.id, c.title, c.artist_display, c.release_date, c.explicit,
         public.chart_candidate_rule_decision(c.run_id, c.release_date, c.explicit) as decision
  into v_bad
  from public.chart_ingest_candidates c
  where c.run_id = p_run_id
    and c.status = 'eligible'
    and coalesce((public.chart_candidate_rule_decision(c.run_id, c.release_date, c.explicit)->>'eligible')::boolean, true) = false
  limit 1;

  if v_bad.id is not null then
    raise exception 'chart_run_has_rule_ineligible_candidate: % by % (%; release_date=%; explicit=%)',
      coalesce(v_bad.title, 'Untitled'),
      coalesce(v_bad.artist_display, 'Unknown artist'),
      v_bad.decision #>> '{reasonCodes,0}',
      v_bad.release_date,
      v_bad.explicit
      using errcode = '23514';
  end if;
end;
$$;


ALTER FUNCTION "public"."chart_assert_rule_clean_run"("p_run_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."chart_candidate_rule_decision"("p_run_id" "text", "p_release_date" "date", "p_explicit" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_run record;
  v_snapshot jsonb;
  v_start date;
  v_end date;
  v_start_text text;
  v_end_text text;
  v_window_active boolean := false;
  v_explicit_allowed boolean := true;
begin
  select id, edition_date, rule_snapshot_json
  into v_run
  from public.chart_ingest_runs
  where id = p_run_id
  limit 1;

  if v_run.id is null then
    return jsonb_build_object('eligible', true, 'reasonCodes', '[]'::jsonb, 'reasonMessages', '[]'::jsonb);
  end if;

  v_snapshot := coalesce(v_run.rule_snapshot_json, '{}'::jsonb);
  v_start_text := public.chart_rule_snapshot_text(v_snapshot, 'releaseWindowStart');
  v_end_text := public.chart_rule_snapshot_text(v_snapshot, 'releaseWindowEnd');

  if v_start_text is not null then v_start := v_start_text::date; end if;
  if v_end_text is not null then v_end := v_end_text::date; end if;

  v_window_active := v_start is not null or v_end is not null;
  v_end := coalesce(v_end, v_run.edition_date);
  v_explicit_allowed := public.chart_rule_explicit_allowed(v_snapshot);

  if v_window_active and p_release_date is null then
    return jsonb_build_object(
      'eligible', false,
      'reasonCodes', jsonb_build_array('missing_release_date'),
      'reasonMessages', jsonb_build_array('Release date is required because this chart has a release-window rule.'),
      'severity', 'hard',
      'ruleSnapshot', jsonb_build_object('releaseWindowStart', v_start, 'releaseWindowEnd', v_end, 'editionDate', v_run.edition_date)
    );
  end if;

  if p_release_date is not null and p_release_date > v_run.edition_date then
    return jsonb_build_object(
      'eligible', false,
      'reasonCodes', jsonb_build_array('future_release_date'),
      'reasonMessages', jsonb_build_array(format('Release date %s is after chart edition date %s.', p_release_date, v_run.edition_date)),
      'severity', 'hard',
      'ruleSnapshot', jsonb_build_object('releaseWindowStart', v_start, 'releaseWindowEnd', v_end, 'editionDate', v_run.edition_date)
    );
  end if;

  if p_release_date is not null and v_start is not null and p_release_date < v_start then
    return jsonb_build_object(
      'eligible', false,
      'reasonCodes', jsonb_build_array('release_window_mismatch'),
      'reasonMessages', jsonb_build_array(format('Release date %s is before release window start %s.', p_release_date, v_start)),
      'severity', 'hard',
      'ruleSnapshot', jsonb_build_object('releaseWindowStart', v_start, 'releaseWindowEnd', v_end, 'editionDate', v_run.edition_date)
    );
  end if;

  if p_release_date is not null and v_end is not null and p_release_date > v_end then
    return jsonb_build_object(
      'eligible', false,
      'reasonCodes', jsonb_build_array('release_window_mismatch'),
      'reasonMessages', jsonb_build_array(format('Release date %s is after release window end %s.', p_release_date, v_end)),
      'severity', 'hard',
      'ruleSnapshot', jsonb_build_object('releaseWindowStart', v_start, 'releaseWindowEnd', v_end, 'editionDate', v_run.edition_date)
    );
  end if;

  if v_explicit_allowed = false and p_explicit is true then
    return jsonb_build_object(
      'eligible', false,
      'reasonCodes', jsonb_build_array('explicit_track_not_allowed'),
      'reasonMessages', jsonb_build_array('Explicit tracks are not allowed by this eligibility profile.'),
      'severity', 'hard',
      'ruleSnapshot', jsonb_build_object('explicitAllowed', false)
    );
  end if;

  return jsonb_build_object(
    'eligible', true,
    'reasonCodes', '[]'::jsonb,
    'reasonMessages', '[]'::jsonb,
    'severity', 'none',
    'ruleSnapshot', jsonb_build_object('releaseWindowStart', v_start, 'releaseWindowEnd', v_end, 'editionDate', v_run.edition_date, 'explicitAllowed', v_explicit_allowed)
  );
end;
$$;


ALTER FUNCTION "public"."chart_candidate_rule_decision"("p_run_id" "text", "p_release_date" "date", "p_explicit" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."chart_create_artist_origin_shell"("p_artist_name" "text", "p_origin_iso2" "text", "p_run_id" "text" DEFAULT NULL::"text", "p_candidate_id" "text" DEFAULT NULL::"text", "p_actor_user_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_name text;
  v_slug text;
  v_origin text;
  v_artist record;
  v_previous_origin text;
  v_previous_status text;
begin
  v_name := nullif(trim(p_artist_name), '');
  v_origin := upper(nullif(trim(p_origin_iso2), ''));

  if v_name is null then
    raise exception 'artist_name_required';
  end if;

  if v_origin is null or length(v_origin) <> 2 then
    raise exception 'invalid_origin_iso2';
  end if;

  v_slug := public.wk_slugify_text(v_name);

  select id, slug, display_name, origin_iso2, status
  into v_artist
  from public.registry_artists
  where lower(slug) = v_slug
  limit 1;

  if v_artist.id is null then
    insert into public.registry_artists (
      slug,
      display_name,
      normalized_name,
      sort_name,
      artist_type,
      origin_iso2,
      origin_confidence,
      status,
      metadata
    )
    values (
      v_slug,
      v_name,
      lower(v_name),
      v_name,
      'unknown',
      v_origin,
      1,
      'active',
      jsonb_build_object(
        'created_from', 'chart_origin_queue',
        'origin_resolution_run_id', p_run_id,
        'origin_resolution_at', now()
      )
    )
    returning id, slug, display_name, origin_iso2, status
    into v_artist;

    v_previous_origin := null;
    v_previous_status := null;
  else
    v_previous_origin := v_artist.origin_iso2;
    v_previous_status := v_artist.status;

    update public.registry_artists
    set
      origin_iso2 = v_origin,
      origin_confidence = 1,
      status = 'active',
      metadata = coalesce(metadata, '{}'::jsonb)
        || jsonb_build_object(
          'origin_resolution_source', 'chart_origin_queue',
          'origin_resolution_run_id', p_run_id,
          'origin_resolution_previous_status', v_previous_status,
          'origin_resolution_at', now()
        ),
      updated_at = now()
    where id = v_artist.id
    returning id, slug, display_name, origin_iso2, status
    into v_artist;
  end if;

  insert into public.chart_origin_resolution_audit (
    run_id,
    candidate_id,
    artist_id,
    source_slug,
    previous_origin_iso2,
    new_origin_iso2,
    action,
    note,
    actor_user_id
  )
  values (
    p_run_id,
    p_candidate_id,
    v_artist.id,
    v_artist.slug,
    v_previous_origin,
    v_origin,
    'create_artist_shell',
    'Created, updated, or activated from chart origin queue.',
    p_actor_user_id
  );

  return jsonb_build_object(
    'artistId', v_artist.id,
    'artistSlug', v_artist.slug,
    'artistName', v_artist.display_name,
    'originIso2', v_artist.origin_iso2,
    'previousOriginIso2', v_previous_origin,
    'previousStatus', v_previous_status,
    'status', v_artist.status
  );
end;
$$;


ALTER FUNCTION "public"."chart_create_artist_origin_shell"("p_artist_name" "text", "p_origin_iso2" "text", "p_run_id" "text", "p_candidate_id" "text", "p_actor_user_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."chart_entry_artist_token_slugs"("p_artist_slug" "text", "p_artist_name" "text") RETURNS TABLE("token_slug" "text")
    LANGUAGE "sql" STABLE
    AS $$
  with raw_tokens as (
    select unnest(string_to_array(coalesce(p_artist_slug, ''), ',')) as token
    union all
    select regexp_split_to_table(
      coalesce(p_artist_name, ''),
      '\s*(,|&|\bx\b|\bfeat\.?\b|\bft\.?\b|\bfeaturing\b|\bwith\b)\s*'
    ) as token
  ),
  normalized as (
    select public.wk_slugify_text(token) as token_slug
    from raw_tokens
  )
  select distinct token_slug
  from normalized
  where token_slug <> '';
$$;


ALTER FUNCTION "public"."chart_entry_artist_token_slugs"("p_artist_slug" "text", "p_artist_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."chart_get_edition_integrity_report"("p_edition_id" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with edition as (
    select
      e.id,
      e.program_id,
      e.edition_slug,
      e.status,
      e.entry_count,
      upper(coalesce(nullif(p.market_slug, ''), '')) as target_iso2,
      p.public_slug,
      p.source_family_slug,
      p.market_slug
    from public.wk_chart_editions_v2 e
    join public.wk_chart_programs_v2 p on p.id = e.program_id
    where e.id = p_edition_id
    limit 1
  ),
  entries as (
    select
      ce.id,
      ce.rank,
      ce.track_title,
      ce.artist_name,
      ce.artist_slug,
      ce.track_slug,
      coalesce(ce.total_score, 0)::numeric as total_score
    from public.wk_chart_entries_v2 ce
    join edition e on e.id = ce.edition_id
  ),
  entry_tokens as (
    select
      en.id as entry_id,
      t.token_slug
    from entries en
    cross join lateral public.chart_entry_artist_token_slugs(en.artist_slug, en.artist_name) t
  ),
  token_resolution as (
    select
      et.entry_id,
      et.token_slug,
      coalesce(alias_artist.id, direct_artist.id) as artist_id,
      coalesce(alias_artist.slug, direct_artist.slug) as canonical_slug,
      coalesce(alias_artist.display_name, direct_artist.display_name) as canonical_name,
      coalesce(alias_artist.origin_iso2, direct_artist.origin_iso2) as origin_iso2,
      case
        when alias_artist.id is not null then 'alias'
        when direct_artist.id is not null then 'direct'
        else 'unresolved'
      end as resolved_via
    from entry_tokens et
    left join public.registry_artist_aliases a
      on lower(a.alias_slug) = et.token_slug
     and coalesce(a.status, 'active') = 'active'
    left join public.registry_artists alias_artist
      on alias_artist.id = a.canonical_artist_id
     and alias_artist.status = 'active'
    left join public.registry_artists direct_artist
      on lower(direct_artist.slug) = et.token_slug
     and direct_artist.status = 'active'
  ),
  entry_origin_state as (
    select
      en.id,
      en.rank,
      en.track_title,
      en.artist_name,
      en.artist_slug,
      en.track_slug,
      en.total_score,
      coalesce(count(tr.artist_id) filter (where tr.artist_id is not null), 0) as resolved_artist_count,
      coalesce(count(*) filter (where tr.artist_id is null), 0) as unresolved_artist_count,
      coalesce(count(*) filter (where upper(coalesce(tr.origin_iso2, '')) = ed.target_iso2), 0) as matching_origin_count,
      coalesce(jsonb_agg(
        distinct jsonb_build_object(
          'sourceSlug', tr.token_slug,
          'canonicalSlug', tr.canonical_slug,
          'canonicalName', tr.canonical_name,
          'originIso2', tr.origin_iso2,
          'resolvedVia', tr.resolved_via
        )
      ) filter (where tr.token_slug is not null), '[]'::jsonb) as artists
    from entries en
    cross join edition ed
    left join token_resolution tr on tr.entry_id = en.id
    group by en.id, en.rank, en.track_title, en.artist_name, en.artist_slug, en.track_slug, en.total_score
  ),
  summary as (
    select
      ed.*,
      count(eos.id)::integer as total_entries,
      count(eos.id) filter (where eos.total_score > 0)::integer as scored_entries,
      coalesce(max(eos.total_score), 0)::numeric as max_score,
      count(eos.id) filter (where eos.resolved_artist_count = 0)::integer as unresolved_origin_entries,
      count(eos.id) filter (
        where eos.resolved_artist_count > 0
          and eos.matching_origin_count = 0
      )::integer as country_ineligible_entries
    from edition ed
    left join entry_origin_state eos on true
    group by ed.id, ed.program_id, ed.edition_slug, ed.status, ed.entry_count, ed.target_iso2, ed.public_slug, ed.source_family_slug, ed.market_slug
  ),
  blockers as (
    select
      s.*,
      array_remove(array[
        case when s.total_entries = 0 then 'empty_edition' end,
        case when s.scored_entries = 0 or s.max_score = 0 then 'unscored_edition' end,
        case when s.unresolved_origin_entries > 0 then 'unresolved_artist_origins' end,
        case when s.country_ineligible_entries > 0 then 'country_ineligible_entries' end
      ], null) as blocker_codes
    from summary s
  ),
  invalid_rows as (
    select coalesce(jsonb_agg(
      jsonb_build_object(
        'id', eos.id,
        'rank', eos.rank,
        'trackTitle', eos.track_title,
        'artistName', eos.artist_name,
        'artistSlug', eos.artist_slug,
        'trackSlug', eos.track_slug,
        'totalScore', eos.total_score,
        'resolvedArtistCount', eos.resolved_artist_count,
        'matchingOriginCount', eos.matching_origin_count,
        'artists', eos.artists,
        'reason',
          case
            when eos.total_score <= 0 then 'unscored'
            when eos.resolved_artist_count = 0 then 'unresolved_artist_origin'
            when eos.matching_origin_count = 0 then 'no_artist_matches_target_country'
            else 'ok'
          end
      )
      order by eos.rank
    ) filter (
      where eos.total_score <= 0
         or eos.resolved_artist_count = 0
         or eos.matching_origin_count = 0
    ), '[]'::jsonb) as rows
    from entry_origin_state eos
  )
  select jsonb_build_object(
    'editionId', p_edition_id,
    'programSlug', b.public_slug,
    'familySlug', coalesce(b.source_family_slug, b.public_slug),
    'marketSlug', b.market_slug,
    'targetIso2', b.target_iso2,
    'totalEntries', coalesce(b.total_entries, 0),
    'entryCount', coalesce(b.entry_count, 0),
    'scoredEntries', coalesce(b.scored_entries, 0),
    'maxScore', coalesce(b.max_score, 0),
    'unresolvedOriginEntries', coalesce(b.unresolved_origin_entries, 0),
    'countryIneligibleEntries', coalesce(b.country_ineligible_entries, 0),
    'blockers', to_jsonb(coalesce(b.blocker_codes, array[]::text[])),
    'publishable', coalesce(array_length(b.blocker_codes, 1), 0) = 0,
    'invalidRows', invalid_rows.rows
  )
  from blockers b, invalid_rows;
$$;


ALTER FUNCTION "public"."chart_get_edition_integrity_report"("p_edition_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."chart_get_family_ingest_presets"() RETURNS TABLE("family_id" "text", "config_json" "jsonb", "updated_at" timestamp with time zone, "updated_by" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    family_id,
    config_json,
    updated_at,
    updated_by
  from public.chart_ingest_family_presets
  order by family_id;
$$;


ALTER FUNCTION "public"."chart_get_family_ingest_presets"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."chart_get_run_candidate_origin_report"("p_run_id" "text") RETURNS TABLE("candidate_id" "text", "normalized_key" "text", "title" "text", "artist_display" "text", "final_score" numeric, "resolved_artist_count" integer, "unresolved_artist_count" integer, "matching_origin_count" integer, "is_country_eligible" boolean, "reason_code" "text", "reason_label" "text", "artists" "jsonb")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with run_row as (
    select
      r.id,
      upper(coalesce(
        nullif((r.market_scope_snapshot_json->'artistOriginCountries'->>0), ''),
        nullif((r.market_scope_snapshot_json->'includedMarkets'->0->>'countryCode'), ''),
        nullif(r.market_slug, ''),
        'KE'
      )) as target_iso2
    from public.chart_ingest_runs r
    where r.id::text = p_run_id
    limit 1
  ),
  eligible_candidates as (
    select
      c.id,
      c.run_id,
      c.normalized_key,
      c.title,
      c.artist_display
    from public.chart_ingest_candidates c
    join run_row rr on rr.id::text = c.run_id::text
    where c.status = 'eligible'
  ),
  scored as (
    select
      ec.id,
      ec.run_id,
      ec.normalized_key,
      ec.title,
      ec.artist_display,
      coalesce(cs.final_score, 0)::numeric as final_score
    from eligible_candidates ec
    left join public.chart_ingest_candidate_scores cs
      on cs.run_id::text = ec.run_id::text
     and cs.candidate_id::text = ec.id::text
  ),
  tokens as (
    select
      s.id as candidate_id,
      t.token_slug
    from scored s
    cross join lateral public.chart_entry_artist_token_slugs(null, s.artist_display) t
  ),
  resolved as (
    select
      t.candidate_id,
      t.token_slug,
      coalesce(alias_artist.id, direct_artist.id) as artist_id,
      coalesce(alias_artist.slug, direct_artist.slug) as canonical_slug,
      coalesce(alias_artist.display_name, direct_artist.display_name) as canonical_name,
      coalesce(alias_artist.origin_iso2, direct_artist.origin_iso2) as origin_iso2,
      case
        when alias_artist.id is not null then 'alias'
        when direct_artist.id is not null then 'direct'
        else 'unresolved'
      end as resolved_via
    from tokens t
    left join public.registry_artist_aliases a
      on lower(a.alias_slug) = t.token_slug
     and coalesce(a.status, 'active') = 'active'
    left join public.registry_artists alias_artist
      on alias_artist.id = a.canonical_artist_id
     and alias_artist.status = 'active'
    left join public.registry_artists direct_artist
      on lower(direct_artist.slug) = t.token_slug
     and direct_artist.status = 'active'
  ),
  row_state as (
    select
      s.id,
      s.normalized_key,
      s.title,
      s.artist_display,
      s.final_score,
      coalesce(count(r.artist_id) filter (where r.artist_id is not null), 0)::integer as resolved_artist_count,
      coalesce(count(*) filter (where r.artist_id is null), 0)::integer as unresolved_artist_count,
      coalesce(count(*) filter (
        where upper(coalesce(r.origin_iso2, '')) = rr.target_iso2
      ), 0)::integer as matching_origin_count,
      coalesce(jsonb_agg(
        distinct jsonb_build_object(
          'sourceSlug', r.token_slug,
          'canonicalSlug', r.canonical_slug,
          'canonicalName', r.canonical_name,
          'originIso2', r.origin_iso2,
          'resolvedVia', r.resolved_via
        )
      ) filter (where r.token_slug is not null), '[]'::jsonb) as artists
    from scored s
    cross join run_row rr
    left join resolved r on r.candidate_id = s.id
    group by s.id, s.normalized_key, s.title, s.artist_display, s.final_score
  )
  select
    rs.id as candidate_id,
    rs.normalized_key,
    rs.title,
    rs.artist_display,
    rs.final_score,
    rs.resolved_artist_count,
    rs.unresolved_artist_count,
    rs.matching_origin_count,
    rs.matching_origin_count > 0 as is_country_eligible,
    case
      when rs.matching_origin_count > 0 then null
      when rs.resolved_artist_count = 0 then 'missing_artist_country'
      else 'country_mismatch'
    end as reason_code,
    case
      when rs.matching_origin_count > 0 then null
      when rs.resolved_artist_count = 0 then 'No resolved chart artist has a known matching origin.'
      else 'Resolved artists do not match the chart target country.'
    end as reason_label,
    rs.artists
  from row_state rs
  order by rs.final_score desc, rs.normalized_key;
$$;


ALTER FUNCTION "public"."chart_get_run_candidate_origin_report"("p_run_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."chart_get_run_integrity_report"("p_run_id" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with run_row as (
    select
      r.id,
      r.status,
      r.chart_size,
      upper(coalesce(
        nullif((r.market_scope_snapshot_json->'artistOriginCountries'->>0), ''),
        nullif((r.market_scope_snapshot_json->'includedMarkets'->0->>'countryCode'), ''),
        nullif(r.market_slug, ''),
        'KE'
      )) as target_iso2
    from public.chart_ingest_runs r
    where r.id::text = p_run_id
    limit 1
  ),
  stage_state as (
    select
      rr.id,
      coalesce(bool_or(se.stage = 'eligibility_execution' and se.status = 'done'), false) as eligibility_done,
      coalesce(bool_or(se.stage = 'methodology_scoring' and se.status = 'done'), false) as scoring_done,
      coalesce(bool_or(se.stage = 'shortlist' and se.status = 'done'), false) as shortlist_done
    from run_row rr
    left join public.chart_ingest_stage_events se
      on se.run_id::text = rr.id::text
    group by rr.id
  ),
  candidates as (
    select
      c.id,
      c.run_id,
      c.normalized_key,
      c.title,
      c.artist_display,
      c.status
    from public.chart_ingest_candidates c
    join run_row rr on c.run_id::text = rr.id::text
  ),
  shortlisted as (
    select *
    from candidates
    where status = 'eligible'
  ),
  scored_shortlist as (
    select
      s.id,
      s.normalized_key,
      s.title,
      s.artist_display,
      coalesce(cs.final_score, 0)::numeric as final_score
    from shortlisted s
    left join public.chart_ingest_candidate_scores cs
      on cs.candidate_id::text = s.id::text
     and cs.run_id::text = s.run_id::text
  ),
  tokens as (
    select
      ss.id as candidate_id,
      t.token_slug
    from scored_shortlist ss
    cross join lateral public.chart_entry_artist_token_slugs(null, ss.artist_display) t
  ),
  resolved as (
    select
      t.candidate_id,
      t.token_slug,
      coalesce(alias_artist.id, direct_artist.id) as artist_id,
      coalesce(alias_artist.slug, direct_artist.slug) as canonical_slug,
      coalesce(alias_artist.display_name, direct_artist.display_name) as canonical_name,
      coalesce(alias_artist.origin_iso2, direct_artist.origin_iso2) as origin_iso2,
      case
        when alias_artist.id is not null then 'alias'
        when direct_artist.id is not null then 'direct'
        else 'unresolved'
      end as resolved_via
    from tokens t
    left join public.registry_artist_aliases a
      on lower(a.alias_slug) = t.token_slug
     and coalesce(a.status, 'active') = 'active'
    left join public.registry_artists alias_artist
      on alias_artist.id = a.canonical_artist_id
     and alias_artist.status = 'active'
    left join public.registry_artists direct_artist
      on lower(direct_artist.slug) = t.token_slug
     and direct_artist.status = 'active'
  ),
  row_state as (
    select
      ss.id,
      ss.normalized_key,
      ss.title,
      ss.artist_display,
      ss.final_score,
      coalesce(count(r.artist_id) filter (where r.artist_id is not null), 0) as resolved_artist_count,
      coalesce(count(*) filter (where r.artist_id is null), 0) as unresolved_artist_count,
      coalesce(count(*) filter (
        where upper(coalesce(r.origin_iso2, '')) = rr.target_iso2
      ), 0) as matching_origin_count,
      coalesce(jsonb_agg(
        distinct jsonb_build_object(
          'sourceSlug', r.token_slug,
          'canonicalSlug', r.canonical_slug,
          'canonicalName', r.canonical_name,
          'originIso2', r.origin_iso2,
          'resolvedVia', r.resolved_via
        )
      ) filter (where r.token_slug is not null), '[]'::jsonb) as artists
    from scored_shortlist ss
    cross join run_row rr
    left join resolved r on r.candidate_id = ss.id
    group by ss.id, ss.normalized_key, ss.title, ss.artist_display, ss.final_score
  ),
  summary as (
    select
      rr.id,
      rr.status,
      rr.chart_size,
      rr.target_iso2,
      ss.eligibility_done,
      ss.scoring_done,
      ss.shortlist_done,
      (select count(*) from candidates)::integer as total_candidates,
      (select count(*) from shortlisted)::integer as shortlisted_count,
      (select count(*) from scored_shortlist where final_score > 0)::integer as nonzero_score_count,
      coalesce((select max(final_score) from scored_shortlist), 0)::numeric as max_score,
      (select count(*) from row_state where matching_origin_count = 0 and resolved_artist_count > 0)::integer as country_ineligible_count,
      (select count(*) from row_state where matching_origin_count = 0 and resolved_artist_count = 0)::integer as unresolved_origin_count
    from run_row rr
    join stage_state ss on ss.id = rr.id
  ),
  blockers as (
    select
      s.*,
      array_remove(array[
        case when not s.eligibility_done then 'eligibility_not_done' end,
        case when not s.scoring_done then 'scoring_not_done' end,
        case when not s.shortlist_done then 'shortlist_not_done' end,
        case when s.total_candidates = 0 then 'no_candidates' end,
        case when s.shortlisted_count < coalesce(s.chart_size, 0) then 'shortlist_incomplete' end,
        case when s.nonzero_score_count < s.shortlisted_count then 'missing_or_zero_scores' end,
        case when s.max_score <= 0 then 'zero_score_shortlist' end,
        case when s.unresolved_origin_count > 0 then 'unresolved_artist_origins' end,
        case when s.country_ineligible_count > 0 then 'country_ineligible_candidates' end
      ], null) as blocker_codes
    from summary s
  ),
  invalid_rows as (
    select coalesce(jsonb_agg(
      jsonb_build_object(
        'candidateId', rs.id,
        'normalizedKey', rs.normalized_key,
        'title', rs.title,
        'artistDisplay', rs.artist_display,
        'finalScore', rs.final_score,
        'resolvedArtistCount', rs.resolved_artist_count,
        'matchingOriginCount', rs.matching_origin_count,
        'artists', rs.artists,
        'reason',
          case
            when rs.final_score <= 0 then 'missing_or_zero_score'
            when rs.matching_origin_count = 0 and rs.resolved_artist_count = 0 then 'unresolved_artist_origin'
            when rs.matching_origin_count = 0 then 'no_artist_matches_target_country'
            else 'ok'
          end
      )
      order by rs.final_score desc, rs.normalized_key
    ) filter (
      where rs.final_score <= 0
         or rs.matching_origin_count = 0
    ), '[]'::jsonb) as rows
    from row_state rs
  )
  select jsonb_build_object(
    'runId', b.id,
    'status', b.status,
    'chartSize', b.chart_size,
    'targetIso2', b.target_iso2,
    'totalCandidates', b.total_candidates,
    'shortlistedCount', b.shortlisted_count,
    'nonzeroScoreCount', b.nonzero_score_count,
    'maxScore', b.max_score,
    'eligibilityDone', b.eligibility_done,
    'scoringDone', b.scoring_done,
    'shortlistDone', b.shortlist_done,
    'countryIneligibleCount', b.country_ineligible_count,
    'unresolvedOriginCount', b.unresolved_origin_count,
    'blockers', to_jsonb(coalesce(b.blocker_codes, array[]::text[])),
    'committable', coalesce(array_length(b.blocker_codes, 1), 0) = 0,
    'invalidRows', invalid_rows.rows
  )
  from blockers b, invalid_rows;
$$;


ALTER FUNCTION "public"."chart_get_run_integrity_report"("p_run_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."chart_get_run_origin_review_queue"("p_run_id" "text") RETURNS TABLE("review_key" "text", "issue_type" "text", "source_slug" "text", "source_name" "text", "canonical_artist_id" "uuid", "canonical_slug" "text", "canonical_name" "text", "current_origin_iso2" "text", "target_iso2" "text", "impacted_candidate_count" integer, "top_score" numeric, "examples" "jsonb")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with run_row as (
    select
      r.id,
      upper(coalesce(
        nullif((r.market_scope_snapshot_json->'artistOriginCountries'->>0), ''),
        nullif((r.market_scope_snapshot_json->'includedMarkets'->0->>'countryCode'), ''),
        nullif(r.market_slug, ''),
        'KE'
      )) as target_iso2
    from public.chart_ingest_runs r
    where r.id::text = p_run_id
    limit 1
  ),
  candidate_scope as (
    select
      c.id,
      c.run_id,
      c.title,
      c.artist_display,
      c.status,
      coalesce(cs.final_score, 0)::numeric as final_score,
      e.reason_code,
      e.reason_label
    from public.chart_ingest_candidates c
    join run_row rr on rr.id::text = c.run_id::text
    left join public.chart_ingest_candidate_scores cs
      on cs.run_id::text = c.run_id::text
     and cs.candidate_id::text = c.id::text
    left join public.chart_ingest_exclusions e
      on e.candidate_id::text = c.id::text
     and e.run_id::text = c.run_id::text
     and e.reason_code in ('country_mismatch', 'missing_artist_country')
    where c.run_id::text = p_run_id
      and (
        c.status in ('eligible', 'excluded', 'needs_review')
        or e.id is not null
      )
  ),
  tokens as (
    select
      c.id as candidate_id,
      c.title,
      c.artist_display,
      c.status,
      c.final_score,
      c.reason_code,
      c.reason_label,
      t.token_slug
    from candidate_scope c
    cross join lateral public.chart_entry_artist_token_slugs(null, c.artist_display) t
  ),
  resolved as (
    select
      t.*,
      coalesce(alias_artist.id, direct_artist.id) as artist_id,
      coalesce(alias_artist.slug, direct_artist.slug) as canonical_slug,
      coalesce(alias_artist.display_name, direct_artist.display_name) as canonical_name,
      coalesce(alias_artist.origin_iso2, direct_artist.origin_iso2) as origin_iso2,
      case
        when alias_artist.id is not null then 'alias'
        when direct_artist.id is not null then 'direct'
        else 'unresolved'
      end as resolved_via
    from tokens t
    left join public.registry_artist_aliases a
      on lower(a.alias_slug) = t.token_slug
     and coalesce(a.status, 'active') = 'active'
    left join public.registry_artists alias_artist
      on alias_artist.id = a.canonical_artist_id
     and alias_artist.status = 'active'
    left join public.registry_artists direct_artist
      on lower(direct_artist.slug) = t.token_slug
     and direct_artist.status = 'active'
  ),
  actionable_artists as (
    select
      r.*,
      rr.target_iso2,
      case
        when r.artist_id is null then 'unresolved_artist'
        when nullif(r.origin_iso2, '') is null then 'missing_origin'
        else null
      end as issue_type
    from resolved r
    cross join run_row rr
    where r.artist_id is null
       or nullif(r.origin_iso2, '') is null
  ),
  grouped as (
    select
      case
        when artist_id is not null then 'artist:' || artist_id::text
        else 'token:' || token_slug
      end as review_key,
      issue_type,
      token_slug as source_slug,
      initcap(replace(token_slug, '-', ' ')) as source_name,
      artist_id as canonical_artist_id,
      canonical_slug,
      canonical_name,
      origin_iso2 as current_origin_iso2,
      target_iso2,
      count(distinct candidate_id)::integer as impacted_candidate_count,
      max(final_score) as top_score,
      jsonb_agg(
        distinct jsonb_build_object(
          'candidateId', candidate_id,
          'title', title,
          'artistDisplay', artist_display,
          'finalScore', final_score,
          'candidateStatus', status,
          'reasonCode', reason_code,
          'reasonLabel', reason_label,
          'resolvedVia', resolved_via
        )
      ) as examples
    from actionable_artists
    where issue_type in ('unresolved_artist', 'missing_origin')
    group by
      review_key,
      issue_type,
      token_slug,
      artist_id,
      canonical_slug,
      canonical_name,
      origin_iso2,
      target_iso2
  )
  select *
  from grouped
  order by
    case issue_type
      when 'missing_origin' then 1
      when 'unresolved_artist' then 2
      else 9
    end,
    top_score desc nulls last,
    impacted_candidate_count desc;
$$;


ALTER FUNCTION "public"."chart_get_run_origin_review_queue"("p_run_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."chart_get_run_playback_readiness"("p_run_id" "text", "p_provider_key" "text" DEFAULT 'apple_music'::"text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
  with eligible as (
    select
      c.id,
      row_number() over (
        order by
          coalesce(cs.final_score, 0) desc,
          c.normalized_key asc,
          c.id asc
      ) as rank,
      coalesce(cs.final_score, 0) as final_score,
      c.title,
      c.artist_display,
      c.normalized_key,
      regexp_replace(
        regexp_replace(
          lower(coalesce(nullif(split_part(c.normalized_key, '::', 1), ''), c.title, 'untitled')),
          '[^a-z0-9]+',
          '-',
          'g'
        ),
        '(^-|-$)',
        '',
        'g'
      ) as candidate_track_slug,
      regexp_replace(
        regexp_replace(
          lower(coalesce(nullif(split_part(c.normalized_key, '::', 2), ''), split_part(c.artist_display, ',', 1), 'unknown-artist')),
          '[^a-z0-9]+',
          '-',
          'g'
        ),
        '(^-|-$)',
        '',
        'g'
      ) as candidate_artist_slug
    from public.chart_ingest_candidates c
    left join public.chart_ingest_candidate_scores cs
      on cs.run_id::text = c.run_id::text
     and cs.candidate_id::text = c.id::text
    where c.run_id::text = p_run_id
      and c.status = 'eligible'
  ),
  resolved as (
    select
      e.*,
      scoped_track.track_id,
      scoped_track.registry_track_slug,
      scoped_track.registry_artist_slug,
      l.provider_track_id,
      l.match_method,
      l.match_confidence,
      l.match_status,
      ex.id as exception_id,
      ex.exception_type,
      ex.note as exception_note
    from eligible e
    left join lateral (
      select
        rt.id as track_id,
        rt.slug as registry_track_slug,
        coalesce(rta.artist_slug, rt.metadata->>'primary_artist_slug') as registry_artist_slug
      from public.registry_tracks rt
      left join public.registry_track_artists rta
        on rta.track_id = rt.id
      where rt.metadata->>'chart_entry_id' = e.id::text
         or (
          rt.slug = e.candidate_track_slug
          and (
            rta.artist_slug = e.candidate_artist_slug
            or rt.metadata->>'primary_artist_slug' = e.candidate_artist_slug
          )
        )
      order by
        case
          when rt.metadata->>'chart_entry_id' = e.id::text then 1
          when rta.artist_slug = e.candidate_artist_slug then 2
          when rt.metadata->>'primary_artist_slug' = e.candidate_artist_slug then 3
          else 4
        end,
        rt.updated_at desc nulls last,
        rt.created_at desc
      limit 1
    ) scoped_track on true
    left join lateral (
      select
        link.provider_track_id,
        link.match_method,
        link.match_confidence,
        link.match_status
      from public.registry_track_provider_links link
      where link.track_id = scoped_track.track_id
        and link.provider_key = lower(coalesce(nullif(trim(p_provider_key), ''), 'apple_music'))
        and link.match_status = 'matched'
      order by link.match_confidence desc, link.last_checked_at desc
      limit 1
    ) l on true
    left join lateral (
      select
        exception.id,
        exception.exception_type,
        exception.note
      from public.chart_playback_provider_exceptions exception
      where exception.run_id::text = p_run_id
        and exception.candidate_id::text = e.id::text
        and exception.provider_key = lower(coalesce(nullif(trim(p_provider_key), ''), 'apple_music'))
      order by exception.created_at desc
      limit 1
    ) ex on true
  ),
  summary as (
    select
      count(*)::integer as total_entries,
      count(*) filter (where rank <= 10)::integer as top10_entries,
      count(*) filter (where provider_track_id is not null or exception_id is not null)::integer as playable_entries,
      count(*) filter (where rank <= 10 and (provider_track_id is not null or exception_id is not null))::integer as top10_playable,
      count(*) filter (where exception_id is not null)::integer as exception_entries,
      count(*) filter (where rank <= 10 and exception_id is not null)::integer as top10_exception_entries,
      count(*) filter (where track_id is null)::integer as missing_registry_tracks,
      count(*) filter (where track_id is not null and provider_track_id is null and exception_id is null)::integer as missing_provider_links
    from resolved
  ),
  missing as (
    select coalesce(jsonb_agg(
      jsonb_build_object(
        'rank', rank,
        'finalScore', final_score,
        'title', title,
        'artist', artist_display,
        'artistSlug', candidate_artist_slug,
        'trackSlug', candidate_track_slug,
        'registryTrackId', track_id,
        'reason',
          case
            when track_id is null then 'missing_scoped_registry_track'
            when provider_track_id is null then 'missing_apple_music_provider_link'
            else 'ready'
          end
      )
      order by rank
    ), '[]'::jsonb) as rows
    from resolved
    where provider_track_id is null
      and exception_id is null
    limit 25
  )
  select jsonb_build_object(
    'runId', p_run_id,
    'providerKey', lower(coalesce(nullif(trim(p_provider_key), ''), 'apple_music')),
    'totalEntries', coalesce(summary.total_entries, 0),
    'top10Entries', coalesce(summary.top10_entries, 0),
    'playableEntries', coalesce(summary.playable_entries, 0),
    'top10Playable', coalesce(summary.top10_playable, 0),
    'exceptionEntries', coalesce(summary.exception_entries, 0),
    'top10ExceptionEntries', coalesce(summary.top10_exception_entries, 0),
    'missingRegistryTracks', coalesce(summary.missing_registry_tracks, 0),
    'missingProviderLinks', coalesce(summary.missing_provider_links, 0),
    'playbackRate',
      case
        when coalesce(summary.total_entries, 0) = 0 then 0
        else round((summary.playable_entries::numeric / summary.total_entries::numeric) * 100, 2)
      end,
    'top10PlaybackRate',
      case
        when coalesce(summary.top10_entries, 0) = 0 then 0
        else round((summary.top10_playable::numeric / summary.top10_entries::numeric) * 100, 2)
      end,
    'canPublish',
      coalesce(summary.top10_entries, 0) > 0
      and coalesce(summary.top10_playable, 0) = coalesce(summary.top10_entries, 0),
    'missingRows', missing.rows
  )
  from summary, missing;
$_$;


ALTER FUNCTION "public"."chart_get_run_playback_readiness"("p_run_id" "text", "p_provider_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."chart_get_weekly_backfill_plan"("p_family_id" "text", "p_start_date" "date", "p_end_date" "date") RETURNS TABLE("edition_date" "date", "release_window_start" "date", "release_window_end" "date", "existing_edition_id" "text", "existing_edition_status" "text", "existing_entry_count" integer, "latest_run_id" "text", "latest_run_status" "text", "latest_run_updated_at" timestamp with time zone, "recommended_action" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with preset as (
    select
      family_id,
      config_json,
      coalesce(
        nullif(config_json->>'releaseWindowStart', '')::date,
        '2024-01-01'::date
      ) as release_window_start
    from public.chart_ingest_family_presets
    where family_id = p_family_id
  ),
  mondays as (
    select generate_series(
      date_trunc('week', p_start_date::timestamp)::date,
      date_trunc('week', p_end_date::timestamp)::date,
      interval '7 days'
    )::date as edition_date
  ),
  latest_runs as (
    select distinct on (r.edition_date)
      r.edition_date::date as edition_date,
      r.id::text as run_id,
      r.status as run_status,
      r.updated_at
    from public.chart_ingest_runs r
    where r.program_id::text = p_family_id
      and r.edition_date::date between p_start_date and p_end_date
    order by r.edition_date, r.updated_at desc
  ),
  editions as (
    select distinct on (e.edition_date)
      e.edition_date::date as edition_date,
      e.id::text as edition_id,
      e.status,
      e.entry_count
    from public.wk_chart_editions_v2 e
    where e.program_id::text = p_family_id
      and e.edition_date::date between p_start_date and p_end_date
    order by e.edition_date, e.updated_at desc
  )
  select
    m.edition_date,
    coalesce(p.release_window_start, '2024-01-01'::date) as release_window_start,
    (m.edition_date - interval '1 day')::date as release_window_end,
    e.edition_id as existing_edition_id,
    e.status as existing_edition_status,
    e.entry_count as existing_entry_count,
    lr.run_id as latest_run_id,
    lr.run_status as latest_run_status,
    lr.updated_at as latest_run_updated_at,
    case
      when e.status = 'published' then 'published'
      when e.status is not null then 'edition_exists'
      when lr.run_status in ('dry_run_complete', 'ready_to_commit') then 'open_run'
      when lr.run_status in ('running', 'queued') then 'wait_for_run'
      when lr.run_status in ('failed', 'cancelled') then 'rerun'
      else 'create_run'
    end as recommended_action
  from mondays m
  left join preset p on true
  left join editions e on e.edition_date = m.edition_date
  left join latest_runs lr on lr.edition_date = m.edition_date
  order by m.edition_date;
$$;


ALTER FUNCTION "public"."chart_get_weekly_backfill_plan"("p_family_id" "text", "p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."chart_reset_run_after_origin_resolution"("p_run_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_candidate_rows integer := 0;
  v_score_rows integer := 0;
  v_exclusion_rows integer := 0;
  v_stage_rows integer := 0;
begin
  update public.chart_ingest_candidates
  set
    status = 'eligible',
    updated_at = now()
  where run_id::text = p_run_id;

  get diagnostics v_candidate_rows = row_count;

  delete from public.chart_ingest_candidate_scores
  where run_id::text = p_run_id;

  get diagnostics v_score_rows = row_count;

  delete from public.chart_ingest_exclusions
  where run_id::text = p_run_id
    and source_stage in ('eligibility', 'shortlist');

  get diagnostics v_exclusion_rows = row_count;

  update public.chart_ingest_stage_events
  set
    status = 'idle',
    message = null,
    error_code = null,
    error_message = null,
    metrics_json = '{}'::jsonb,
    started_at = null,
    finished_at = null,
    duration_ms = null
  where run_id::text = p_run_id
    and stage in (
      'eligibility_execution',
      'methodology_scoring',
      'anti_gaming',
      'shortlist',
      'review_gate',
      'commit_validate',
      'commit_write',
      'public_verify'
    );

  get diagnostics v_stage_rows = row_count;

  update public.chart_ingest_runs
  set
    status = 'dry_run_complete',
    error_code = null,
    error_message = null,
    updated_at = now()
  where id::text = p_run_id;

  return jsonb_build_object(
    'runId', p_run_id,
    'candidateRowsReset', v_candidate_rows,
    'scoreRowsDeleted', v_score_rows,
    'exclusionRowsDeleted', v_exclusion_rows,
    'stageRowsReset', v_stage_rows
  );
end;
$$;


ALTER FUNCTION "public"."chart_reset_run_after_origin_resolution"("p_run_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."chart_rule_explicit_allowed"("p_snapshot" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select coalesce(
    (p_snapshot #>> '{eligibilityProfileSnapshot,trackEligibility,explicitAllowed}')::boolean,
    (p_snapshot #>> '{eligibilityProfile,trackEligibility,explicitAllowed}')::boolean,
    (p_snapshot #>> '{trackEligibility,explicitAllowed}')::boolean,
    true
  );
$$;


ALTER FUNCTION "public"."chart_rule_explicit_allowed"("p_snapshot" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."chart_rule_snapshot_text"("p_snapshot" "jsonb", "p_key" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select nullif(coalesce(
    p_snapshot ->> p_key,
    p_snapshot #>> array['backfill', p_key],
    case p_key
      when 'releaseWindowStart' then p_snapshot #>> '{eligibilityProfileSnapshot,releaseEligibility,releaseWindowFrom}'
      when 'releaseWindowEnd' then p_snapshot #>> '{eligibilityProfileSnapshot,releaseEligibility,releaseWindowTo}'
      else null
    end,
    case p_key
      when 'releaseWindowStart' then p_snapshot #>> '{eligibilityProfile,releaseEligibility,releaseWindowFrom}'
      when 'releaseWindowEnd' then p_snapshot #>> '{eligibilityProfile,releaseEligibility,releaseWindowTo}'
      else null
    end
  ), '');
$$;


ALTER FUNCTION "public"."chart_rule_snapshot_text"("p_snapshot" "jsonb", "p_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."chart_set_artist_origin_for_charts"("p_artist_id" "uuid", "p_origin_iso2" "text", "p_run_id" "text" DEFAULT NULL::"text", "p_candidate_id" "text" DEFAULT NULL::"text", "p_note" "text" DEFAULT NULL::"text", "p_actor_user_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_artist record;
  v_origin text;
begin
  v_origin := upper(nullif(trim(p_origin_iso2), ''));

  if v_origin is null or length(v_origin) <> 2 then
    raise exception 'invalid_origin_iso2';
  end if;

  select id, slug, display_name, origin_iso2
  into v_artist
  from public.registry_artists
  where id = p_artist_id
  limit 1;

  if v_artist.id is null then
    raise exception 'artist_not_found';
  end if;

  update public.registry_artists
  set
    origin_iso2 = v_origin,
    origin_confidence = 1,
    metadata = coalesce(metadata, '{}'::jsonb)
      || jsonb_build_object(
        'origin_resolution_source', 'chart_origin_queue',
        'origin_resolution_run_id', p_run_id,
        'origin_resolution_note', p_note,
        'origin_resolution_at', now()
      ),
    updated_at = now()
  where id = p_artist_id;

  insert into public.chart_origin_resolution_audit (
    run_id,
    candidate_id,
    artist_id,
    source_slug,
    previous_origin_iso2,
    new_origin_iso2,
    action,
    note,
    actor_user_id
  )
  values (
    p_run_id,
    p_candidate_id,
    p_artist_id,
    v_artist.slug,
    v_artist.origin_iso2,
    v_origin,
    'set_origin',
    p_note,
    p_actor_user_id
  );

  return jsonb_build_object(
    'artistId', p_artist_id,
    'artistSlug', v_artist.slug,
    'artistName', v_artist.display_name,
    'previousOriginIso2', v_artist.origin_iso2,
    'newOriginIso2', v_origin
  );
end;
$$;


ALTER FUNCTION "public"."chart_set_artist_origin_for_charts"("p_artist_id" "uuid", "p_origin_iso2" "text", "p_run_id" "text", "p_candidate_id" "text", "p_note" "text", "p_actor_user_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."chart_upsert_family_ingest_preset"("p_family_id" "text", "p_config_json" "jsonb", "p_actor_user_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_row public.chart_ingest_family_presets%rowtype;
begin
  if nullif(trim(p_family_id), '') is null then
    raise exception 'family_id_required';
  end if;

  insert into public.chart_ingest_family_presets (
    family_id,
    config_json,
    created_by,
    updated_by,
    created_at,
    updated_at
  )
  values (
    p_family_id,
    coalesce(p_config_json, '{}'::jsonb),
    p_actor_user_id,
    p_actor_user_id,
    now(),
    now()
  )
  on conflict (family_id) do update
  set
    config_json = excluded.config_json,
    updated_by = excluded.updated_by,
    updated_at = now()
  returning *
  into v_row;

  return jsonb_build_object(
    'familyId', v_row.family_id,
    'config', v_row.config_json,
    'updatedAt', v_row.updated_at
  );
end;
$$;


ALTER FUNCTION "public"."chart_upsert_family_ingest_preset"("p_family_id" "text", "p_config_json" "jsonb", "p_actor_user_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."chart_write_candidate_rule_exclusion_aiu"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_decision jsonb;
  v_code text;
  v_label text;
begin
  v_decision := coalesce(new.eligibility_decision_json->'ruleDecision', '{}'::jsonb);
  v_code := v_decision #>> '{reasonCodes,0}';
  v_label := v_decision #>> '{reasonMessages,0}';

  delete from public.chart_ingest_exclusions
  where run_id = new.run_id
    and candidate_id = new.id
    and source_stage = 'eligibility_rules';

  if new.status = 'excluded' and v_code is not null then
    insert into public.chart_ingest_exclusions (
      id,
      run_id,
      candidate_id,
      reason_code,
      reason_label,
      severity,
      source_stage,
      details_json,
      created_at
    ) values (
      gen_random_uuid()::text,
      new.run_id,
      new.id,
      v_code,
      coalesce(v_label, v_code),
      coalesce(v_decision->>'severity', 'hard'),
      'eligibility_rules',
      jsonb_build_object(
        'title', new.title,
        'artistDisplay', new.artist_display,
        'releaseDate', new.release_date,
        'explicit', new.explicit,
        'decision', v_decision
      ),
      now()
    );
  end if;

  return null;
end;
$$;


ALTER FUNCTION "public"."chart_write_candidate_rule_exclusion_aiu"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_media_processing_jobs_v1"("p_worker_id" "text", "p_limit" integer DEFAULT 1, "p_lease_seconds" integer DEFAULT 3600) RETURNS TABLE("job_id" "uuid", "command_receipt_id" "uuid", "resource_id" "uuid", "command_type" "text", "job_type" "text", "attempt_count" integer, "max_attempts" integer, "input_payload" "jsonb", "lease_expires_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'auth', 'platform_private'
    AS $_$
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception
      using
        errcode = '42501',
        message = 'Service-role access is required.';
  end if;

  if p_worker_id is null
     or p_worker_id !~
       '^[A-Za-z0-9][A-Za-z0-9._:-]{2,127}$'
  then
    raise exception
      using
        errcode = '22023',
        message = 'worker_id is invalid.';
  end if;

  if p_limit not between 1 and 10 then
    raise exception
      using
        errcode = '22023',
        message = 'limit must be between 1 and 10.';
  end if;

  if p_lease_seconds not between 60 and 3600 then
    raise exception
      using
        errcode = '22023',
        message = 'lease_seconds must be between 60 and 3600.';
  end if;

  return query
  with candidates as (
    select job.id
    from platform_private.jobs job
    where job.command_type = 'media.process_revision'
      and job.job_type = 'media.process_revision'
      and job.status in ('queued', 'retry_wait')
      and job.available_at <= now()
      and job.attempt_count < job.max_attempts
      and job.locked_by is null
    order by
      job.priority,
      job.available_at,
      job.created_at
    for update skip locked
    limit p_limit
  ),
  claimed as (
    update platform_private.jobs job
    set
      status = 'running',
      attempt_count = job.attempt_count + 1,
      locked_by = p_worker_id,
      locked_at = now(),
      lease_expires_at =
        now() +
        make_interval(secs => p_lease_seconds),
      started_at = coalesce(job.started_at, now())
    from candidates
    where job.id = candidates.id
    returning job.*
  )
  select
    claimed.id,
    claimed.command_receipt_id,
    claimed.resource_id,
    claimed.command_type,
    claimed.job_type,
    claimed.attempt_count,
    claimed.max_attempts,
    claimed.input_payload,
    claimed.lease_expires_at
  from claimed;
end;
$_$;


ALTER FUNCTION "public"."claim_media_processing_jobs_v1"("p_worker_id" "text", "p_limit" integer, "p_lease_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_correction_case"("p_case_resource_id" "uuid", "p_expected_case_revision" bigint, "p_reason" "text", "p_idempotency_key" "text", "p_correlation_id" "uuid", "p_public_note_disposition" "text" DEFAULT NULL::"text", "p_public_note_no_note_reason" "text" DEFAULT NULL::"text", "p_contributor_follow_up_disposition" "text" DEFAULT NULL::"text", "p_contributor_follow_up_reason" "text" DEFAULT NULL::"text") RETURNS TABLE("command_receipt_id" "uuid", "receipt_status" "text", "case_resource_id" "uuid", "case_revision" bigint, "result_payload" "jsonb", "idempotent_replay" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'editorial', 'platform_private'
    AS $$
declare
  v_actor uuid;
  v_begin record;
  v_case editorial.correction_cases%rowtype;
  v_application editorial.correction_applications%rowtype;
  v_outcome text;
  v_proof record;
  v_current_note_id uuid;
  v_effective_note_disposition text;
  v_effective_note_reason text;
  v_effective_follow_up_disposition text;
  v_effective_follow_up_reason text;
  v_effective_follow_up_job_id uuid;
  v_effective_follow_up_requested_at timestamptz;
  v_child_receipt_id uuid;
  v_new_job_id uuid;
  v_job_status text;
  v_rejection_code text;
  v_rejection_message text;
  v_result jsonb;
begin
  v_actor :=
    platform_private.assert_correction_capability(
      'decide_corrections'
    );

  if p_case_resource_id is null
     or p_expected_case_revision < 1
     or p_correlation_id is null
     or nullif(
       btrim(p_reason),
       ''
     ) is null
  then
    raise exception
      using
        errcode = '22023',
        message = 'Case, revision, reason, and correlation identity are required.';
  end if;

  if p_public_note_disposition is not null
     and p_public_note_disposition not in (
       'published',
       'not_required'
     )
  then
    raise exception
      using
        errcode = '22023',
        message = 'Public-note disposition is invalid.';
  end if;

  if p_public_note_disposition is null
     and p_public_note_no_note_reason is not null
  then
    raise exception
      using
        errcode = '22023',
        message = 'A no-note reason requires the not_required disposition.';
  end if;

  if p_public_note_disposition = 'published'
     and p_public_note_no_note_reason is not null
  then
    raise exception
      using
        errcode = '22023',
        message = 'Published public-note disposition cannot use a no-note reason.';
  end if;

  if p_public_note_disposition = 'not_required'
     and (
       nullif(
         btrim(p_public_note_no_note_reason),
         ''
       ) is null
       or length(
         p_public_note_no_note_reason
       ) > 2000
     )
  then
    raise exception
      using
        errcode = '22023',
        message = 'No-note disposition requires a bounded reason.';
  end if;

  if p_contributor_follow_up_disposition is not null
     and p_contributor_follow_up_disposition not in (
       'requested',
       'unavailable',
       'unsafe'
     )
  then
    raise exception
      using
        errcode = '22023',
        message = 'Contributor follow-up disposition is invalid.';
  end if;

  if p_contributor_follow_up_disposition is null
     and p_contributor_follow_up_reason is not null
  then
    raise exception
      using
        errcode = '22023',
        message = 'A contributor follow-up reason requires a contributor follow-up disposition.';
  end if;

  if p_contributor_follow_up_disposition = 'requested'
     and p_contributor_follow_up_reason is not null
  then
    raise exception
      using
        errcode = '22023',
        message = 'Requested contributor follow-up cannot use an exception reason.';
  end if;

  if p_contributor_follow_up_disposition in (
       'unavailable',
       'unsafe'
     )
     and (
       nullif(
         btrim(p_contributor_follow_up_reason),
         ''
       ) is null
       or length(
         p_contributor_follow_up_reason
       ) > 2000
     )
  then
    raise exception
      using
        errcode = '22023',
        message = 'Contributor follow-up exception requires a bounded reason.';
  end if;

  select *
  into v_begin
  from platform_private.begin_resource_command(
    'correction.case.close',
    p_case_resource_id,
    p_idempotency_key,
    jsonb_build_object(
      'expected_case_revision',
      p_expected_case_revision,
      'reason',
      btrim(p_reason),
      'public_note_disposition',
      p_public_note_disposition,
      'public_note_no_note_reason',
      p_public_note_no_note_reason,
      'contributor_follow_up_disposition',
      p_contributor_follow_up_disposition,
      'contributor_follow_up_reason',
      p_contributor_follow_up_reason,
      'correlation_id',
      p_correlation_id
    )
  );

  if v_begin.idempotent_replay then
    return query
    select *
    from platform_private.read_correction_command_result(
      v_begin.command_receipt_id,
      true
    );
    return;
  end if;

  select correction_case.*
  into v_case
  from editorial.correction_cases correction_case
  where correction_case.resource_id =
    p_case_resource_id
  for update;

  if not found then
    v_rejection_code :=
      'case_not_found';
    v_rejection_message :=
      'The correction case does not exist.';
  elsif v_case.current_revision <>
        p_expected_case_revision
  then
    v_rejection_code :=
      'case_revision_changed';
    v_rejection_message :=
      'The correction case revision changed.';
  elsif v_case.current_decision_id is null then
    v_rejection_code :=
      'decision_required';
    v_rejection_message :=
      'A correction decision is required before closure.';
  end if;

  if v_rejection_code is null then
    select decision.outcome
    into v_outcome
    from editorial.correction_decisions decision
    where decision.id =
        v_case.current_decision_id
      and decision.case_resource_id =
        p_case_resource_id;

    if not found then
      v_rejection_code :=
        'decision_changed';
      v_rejection_message :=
        'The current correction decision changed.';
    end if;
  end if;

  if v_rejection_code is null
     and v_outcome <>
       'correction_required'
  then
    if v_case.case_state <> 'decided' then
      v_rejection_code :=
        'invalid_transition';
      v_rejection_message :=
        'Only decided non-correction cases may close.';
    elsif p_public_note_disposition is not null
          or p_public_note_no_note_reason is not null
          or p_contributor_follow_up_disposition is not null
          or p_contributor_follow_up_reason is not null
    then
      v_rejection_code :=
        'follow_up_not_applicable';
      v_rejection_message :=
        'Non-correction closure cannot set public-note or contributor follow-up state.';
    elsif exists (
      select 1
      from editorial.correction_related_resource_reviews review
      where review.case_resource_id =
        p_case_resource_id
        and review.review_state =
          'pending'
    ) then
      v_rejection_code :=
        'related_reviews_pending';
      v_rejection_message :=
        'All related-resource reviews must be resolved before closure.';
    end if;
  end if;

  if v_rejection_code is null
     and v_outcome =
       'correction_required'
  then
    if v_case.case_state <> 'applied'
       or v_case.current_application_id is null
    then
      v_rejection_code :=
        'application_required';
      v_rejection_message :=
        'Correction-required closure requires the current applied correction.';
    else
      select application.*
      into v_application
      from editorial.correction_applications application
      where application.id =
          v_case.current_application_id
        and application.case_resource_id =
          p_case_resource_id
        and application.decision_id =
          v_case.current_decision_id;

      if not found then
        v_rejection_code :=
          'application_changed';
        v_rejection_message :=
          'The current correction application changed.';
      end if;
    end if;
  end if;

  if v_rejection_code is null
     and v_outcome =
       'correction_required'
  then
    select *
    into v_proof
    from editorial.correction_article_publication_proof(
      v_case.current_application_id
    );

    if not found then
      v_rejection_code :=
        'publication_proof_missing';
      v_rejection_message :=
        'The corrected Article has not completed governed publication.';
    elsif exists (
      select 1
      from editorial.correction_related_resource_reviews review
      where review.case_resource_id =
        p_case_resource_id
        and review.review_state =
          'pending'
    ) then
      v_rejection_code :=
        'related_reviews_pending';
      v_rejection_message :=
        'All related-resource reviews must be resolved before closure.';
    end if;
  end if;

  if v_rejection_code is null
     and v_outcome =
       'correction_required'
  then
    v_effective_note_disposition :=
      v_case.public_note_disposition;
    v_effective_note_reason :=
      v_case.public_note_no_note_reason;

    if v_effective_note_disposition is null then
      if p_public_note_disposition is distinct from
           'not_required'
         or nullif(
           btrim(
             p_public_note_no_note_reason
           ),
           ''
         ) is null
      then
        v_rejection_code :=
          'public_note_disposition_required';
        v_rejection_message :=
          'Closure requires a published public note or governed no-note disposition.';
      else
        v_effective_note_disposition :=
          'not_required';
        v_effective_note_reason :=
          btrim(
            p_public_note_no_note_reason
          );
      end if;
    elsif v_effective_note_disposition =
          'published'
    then
      if p_public_note_disposition is not null
         and p_public_note_disposition <>
           'published'
      then
        v_rejection_code :=
          'public_note_disposition_changed';
        v_rejection_message :=
          'The public-note disposition changed.';
      elsif p_public_note_no_note_reason is not null then
        v_rejection_code :=
          'public_note_disposition_invalid';
        v_rejection_message :=
          'Published public-note disposition cannot use a no-note reason.';
      else
        select note.id
        into v_current_note_id
        from editorial.correction_public_notes note
        where note.case_resource_id =
            p_case_resource_id
          and note.application_id =
            v_case.current_application_id
          and note.corrected_version_id =
            v_proof.corrected_version_id
          and not exists (
            select 1
            from editorial.correction_public_notes later_note
            where later_note.supersedes_note_id =
              note.id
          )
        order by
          note.published_at desc,
          note.id desc
        limit 1;

        if not found then
          v_rejection_code :=
            'public_note_missing';
          v_rejection_message :=
            'The current published public note is missing.';
        end if;
      end if;
    elsif v_effective_note_disposition =
          'not_required'
    then
      if p_public_note_disposition is not null
         and p_public_note_disposition <>
           'not_required'
      then
        v_rejection_code :=
          'public_note_disposition_changed';
        v_rejection_message :=
          'The public-note disposition changed.';
      elsif p_public_note_no_note_reason is not null
            and btrim(
              p_public_note_no_note_reason
            ) <>
              v_effective_note_reason
      then
        v_rejection_code :=
          'public_note_reason_changed';
        v_rejection_message :=
          'The governed no-note reason changed.';
      elsif exists (
        select 1
        from editorial.correction_public_notes note
        where note.case_resource_id =
            p_case_resource_id
          and note.application_id =
            v_case.current_application_id
      ) then
        v_rejection_code :=
          'public_note_conflict';
        v_rejection_message :=
          'No-note disposition cannot coexist with a public note for the current application.';
      end if;
    end if;
  end if;

  if v_rejection_code is null
     and v_outcome =
       'correction_required'
  then
    v_effective_follow_up_disposition :=
      v_case.contributor_follow_up_disposition;
    v_effective_follow_up_reason :=
      v_case.contributor_follow_up_reason;
    v_effective_follow_up_job_id :=
      v_case.contributor_follow_up_job_id;
    v_effective_follow_up_requested_at :=
      v_case.contributor_follow_up_requested_at;

    if v_case.origin_type =
       'internal_editorial'
    then
      if v_effective_follow_up_disposition is not null
         or v_effective_follow_up_reason is not null
         or v_effective_follow_up_job_id is not null
         or v_effective_follow_up_requested_at is not null
         or p_contributor_follow_up_disposition is not null
         or p_contributor_follow_up_reason is not null
      then
        v_rejection_code :=
          'contributor_follow_up_not_applicable';
        v_rejection_message :=
          'Internal correction closure cannot use contributor follow-up.';
      end if;
    elsif v_case.origin_type =
          'community_contribution'
    then
      if v_effective_follow_up_disposition is null then
        if p_contributor_follow_up_disposition is null then
          v_rejection_code :=
            'contributor_follow_up_required';
          v_rejection_message :=
            'Community-origin correction closure requires contributor follow-up disposition.';
        elsif p_contributor_follow_up_disposition =
              'requested'
        then
          v_effective_follow_up_disposition :=
            'requested';
          v_effective_follow_up_reason :=
            null;
        else
          v_effective_follow_up_disposition :=
            p_contributor_follow_up_disposition;
          v_effective_follow_up_reason :=
            btrim(
              p_contributor_follow_up_reason
            );
        end if;
      elsif p_contributor_follow_up_disposition is not null
            and p_contributor_follow_up_disposition <>
              v_effective_follow_up_disposition
      then
        v_rejection_code :=
          'contributor_follow_up_changed';
        v_rejection_message :=
          'The contributor follow-up disposition changed.';
      elsif v_effective_follow_up_disposition in (
              'unavailable',
              'unsafe'
            )
            and p_contributor_follow_up_reason is not null
            and btrim(
              p_contributor_follow_up_reason
            ) <>
              v_effective_follow_up_reason
      then
        v_rejection_code :=
          'contributor_follow_up_changed';
        v_rejection_message :=
          'The contributor follow-up reason changed.';
      end if;

      if v_rejection_code is null
         and v_effective_follow_up_disposition =
           'requested'
         and v_effective_follow_up_job_id is not null
      then
        select job.status
        into v_job_status
        from platform_private.jobs job
        join platform_private.command_receipts receipt
          on receipt.id =
            job.command_receipt_id
        where job.id =
            v_effective_follow_up_job_id
          and job.resource_id =
            p_case_resource_id
          and job.command_type =
            'correction.contributor_notification.request'
          and job.job_type =
            'correction.contributor_notification'
          and receipt.command_type =
            'correction.contributor_notification.request'
          and receipt.resource_id =
            p_case_resource_id
          and receipt.status in (
            'accepted',
            'succeeded'
          );

        if not found
           or v_job_status not in (
             'queued',
             'running',
             'retry_wait',
             'succeeded',
             'dead_letter'
           )
        then
          v_rejection_code :=
            'contributor_follow_up_job_invalid';
          v_rejection_message :=
            'The contributor follow-up job is missing or invalid.';
        end if;
      elsif v_rejection_code is null
            and v_effective_follow_up_disposition in (
              'unavailable',
              'unsafe'
            )
            and (
              nullif(
                btrim(
                  v_effective_follow_up_reason
                ),
                ''
              ) is null
              or length(
                v_effective_follow_up_reason
              ) > 2000
            )
      then
        v_rejection_code :=
          'contributor_follow_up_invalid';
        v_rejection_message :=
          'Contributor follow-up exception requires a bounded reason.';
      end if;
    end if;
  end if;

  if v_rejection_code is not null then
    v_result := jsonb_build_object(
      'case_resource_id',
      p_case_resource_id,
      'case_revision',
      v_case.current_revision,
      'case_state',
      v_case.case_state,
      'decision_outcome',
      v_outcome,
      'rejection_code',
      v_rejection_code
    );

    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      v_rejection_code,
      v_rejection_message,
      v_result
    );

    return query
    select *
    from platform_private.read_correction_command_result(
      v_begin.command_receipt_id,
      false
    );
    return;
  end if;

  if v_outcome <>
     'correction_required'
  then
    update editorial.correction_cases
    set
      case_state = 'closed',
      current_revision =
        v_case.current_revision + 1,
      closed_reason =
        btrim(p_reason),
      closed_by = v_actor,
      closed_at = now(),
      updated_by = v_actor,
      updated_at = now()
    where resource_id =
      p_case_resource_id;

    perform platform_private.append_correction_event(
      p_case_resource_id,
      'case_closed',
      v_case.current_revision,
      v_case.current_revision + 1,
      v_case.case_state,
      'closed',
      v_actor,
      btrim(p_reason),
      v_case.current_decision_id,
      null,
      null,
      null,
      v_begin.command_receipt_id,
      p_correlation_id,
      jsonb_build_object(
        'decision_outcome',
        v_outcome
      )
    );
  else
    if v_case.origin_type =
         'community_contribution'
       and v_effective_follow_up_disposition =
         'requested'
       and v_effective_follow_up_job_id is null
    then
      select
        notification.child_command_receipt_id,
        notification.contributor_job_id
      into
        v_child_receipt_id,
        v_new_job_id
      from platform_private.request_correction_contributor_notification(
        p_case_resource_id,
        v_case.origin_contribution_id,
        v_case.origin_submitter_user_id,
        v_case.current_decision_id,
        v_case.current_application_id,
        null,
        case
          when v_effective_note_disposition =
            'published'
          then 'correction_published'
          else 'correction_closed_without_public_note'
        end,
        case
          when v_effective_note_disposition =
            'published'
          then 'The submitted correction was applied and the corrected Article was published.'
          else 'The submitted correction was resolved after the corrected Article was published.'
        end,
        v_begin.command_receipt_id,
        v_actor,
        v_case.current_revision,
        v_case.case_state,
        p_correlation_id
      ) notification;

      v_effective_follow_up_job_id :=
        v_new_job_id;
      v_effective_follow_up_requested_at :=
        now();
    end if;

    update editorial.correction_cases
    set
      case_state = 'closed',
      current_revision =
        v_case.current_revision + 1,
      public_note_disposition =
        v_effective_note_disposition,
      public_note_no_note_reason =
        v_effective_note_reason,
      contributor_follow_up_disposition =
        case
          when origin_type =
            'community_contribution'
          then v_effective_follow_up_disposition
          else null
        end,
      contributor_follow_up_reason =
        case
          when origin_type =
            'community_contribution'
          then v_effective_follow_up_reason
          else null
        end,
      contributor_follow_up_job_id =
        case
          when origin_type =
            'community_contribution'
          then v_effective_follow_up_job_id
          else null
        end,
      contributor_follow_up_requested_at =
        case
          when origin_type =
            'community_contribution'
          then v_effective_follow_up_requested_at
          else null
        end,
      closed_reason =
        btrim(p_reason),
      closed_by = v_actor,
      closed_at = now(),
      updated_by = v_actor,
      updated_at = now()
    where resource_id =
      p_case_resource_id;

    perform platform_private.append_correction_public_event(
      p_case_resource_id,
      'case_closed',
      v_case.current_revision,
      v_case.current_revision + 1,
      v_case.case_state,
      'closed',
      v_actor,
      btrim(p_reason),
      v_case.current_decision_id,
      v_case.current_application_id,
      v_application.target_id,
      v_current_note_id,
      v_begin.command_receipt_id,
      p_correlation_id,
      jsonb_build_object(
        'decision_outcome',
        v_outcome,
        'corrected_version_id',
        v_proof.corrected_version_id,
        'public_note_disposition',
        v_effective_note_disposition,
        'public_note_id',
        v_current_note_id,
        'contributor_follow_up_disposition',
        v_effective_follow_up_disposition,
        'contributor_follow_up_job_id',
        v_effective_follow_up_job_id
      )
    );
  end if;

  v_result := jsonb_build_object(
    'case_resource_id',
    p_case_resource_id,
    'case_revision',
    v_case.current_revision + 1,
    'case_state',
    'closed',
    'decision_outcome',
    v_outcome,
    'application_id',
    v_case.current_application_id,
    'corrected_version_id',
    case
      when v_outcome =
        'correction_required'
      then v_proof.corrected_version_id
      else null
    end,
    'public_note_disposition',
    v_effective_note_disposition,
    'public_note_id',
    v_current_note_id,
    'contributor_follow_up_disposition',
    v_effective_follow_up_disposition,
    'contributor_follow_up_job_id',
    v_effective_follow_up_job_id,
    'contributor_follow_up_command_receipt_id',
    v_child_receipt_id
  );

  perform platform_private.complete_resource_command(
    v_begin.command_receipt_id,
    v_result
  );

  return query
  select *
  from platform_private.read_correction_command_result(
    v_begin.command_receipt_id,
    false
  );
end;
$$;


ALTER FUNCTION "public"."close_correction_case"("p_case_resource_id" "uuid", "p_expected_case_revision" bigint, "p_reason" "text", "p_idempotency_key" "text", "p_correlation_id" "uuid", "p_public_note_disposition" "text", "p_public_note_no_note_reason" "text", "p_contributor_follow_up_disposition" "text", "p_contributor_follow_up_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."close_correction_case"("p_case_resource_id" "uuid", "p_expected_case_revision" bigint, "p_reason" "text", "p_idempotency_key" "text", "p_correlation_id" "uuid", "p_public_note_disposition" "text", "p_public_note_no_note_reason" "text", "p_contributor_follow_up_disposition" "text", "p_contributor_follow_up_reason" "text") IS 'Closes non-correction cases compatibly and correction-required cases only after application, publication, note disposition, related-review, and contributor follow-up gates.';



CREATE OR REPLACE FUNCTION "public"."community_activity_on_follow"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  INSERT INTO community_activity (user_id, activity_type, entity_type, entity_id, entity_slug, comment_id, metadata, visibility)
  VALUES (
    NEW.user_id,
    'follow',
    NEW.target_type,
    NEW.target_id,
    NEW.target_slug,
    NULL,
    jsonb_build_object('target_type', NEW.target_type, 'target_slug', NEW.target_slug),
    'public'
  );
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."community_activity_on_follow"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_activity_on_reaction"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  INSERT INTO community_activity (user_id, activity_type, entity_type, entity_id, entity_slug, comment_id, metadata, visibility)
  VALUES (
    NEW.user_id,
    'reaction',
    NEW.target_type,
    NEW.target_id,
    NULL,
    CASE WHEN NEW.target_type = 'comment' THEN NEW.target_id ELSE NULL END,
    jsonb_build_object('reaction_type', NEW.reaction_type),
    'public'
  );
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."community_activity_on_reaction"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_activity_on_save"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  INSERT INTO community_activity (user_id, activity_type, entity_type, entity_id, entity_slug, comment_id, metadata, visibility)
  VALUES (
    NEW.user_id,
    'save',
    NEW.entity_type,
    NEW.entity_id,
    NEW.entity_slug,
    NULL,
    jsonb_build_object('title', NEW.title, 'entity_slug', NEW.entity_slug),
    'public'
  );
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."community_activity_on_save"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_activity_on_vote"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  INSERT INTO community_activity (user_id, activity_type, entity_type, entity_id, entity_slug, comment_id, metadata, visibility)
  VALUES (
    NEW.user_id,
    CASE WHEN NEW.vote_value > 0 THEN 'upvote' ELSE 'downvote' END,
    'comment',
    NEW.comment_id,
    NULL,
    NEW.comment_id,
    jsonb_build_object('vote_value', NEW.vote_value),
    'public'
  );
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."community_activity_on_vote"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_admin_decide_artist_claim"("p_claim_id" "uuid", "p_decision" "text", "p_reason" "text", "p_can_manage_profile" boolean DEFAULT NULL::boolean, "p_can_submit_releases" boolean DEFAULT NULL::boolean, "p_can_post_updates" boolean DEFAULT NULL::boolean, "p_can_manage_team" boolean DEFAULT NULL::boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_decision text :=
    lower(
      trim(
        coalesce(
          p_decision,
          ''
        )
      )
    );
  v_reason text :=
    trim(
      coalesce(
        p_reason,
        ''
      )
    );
  v_claim public.artist_claim_requests%rowtype;
  v_defaults record;
  v_representation_id uuid;
  v_profile boolean;
  v_releases boolean;
  v_updates boolean;
  v_team boolean;
begin
  if v_actor is null then
    raise exception
      'authentication_required';
  end if;

  if not editorial.current_user_can_review_artist_claims() then
    raise exception
      'insufficient_privilege';
  end if;

  if v_decision not in (
    'verified',
    'rejected'
  ) then
    raise exception
      'invalid_claim_decision';
  end if;

  if char_length(v_reason) < 3
     or char_length(v_reason) > 4000
  then
    raise exception
      'invalid_claim_decision_reason';
  end if;

  select *
  into v_claim
  from public.artist_claim_requests
  where id = p_claim_id
  for update;

  if not found then
    raise exception
      'claim_not_found';
  end if;

  if v_claim.status <> 'pending' then
    raise exception
      'claim_not_pending';
  end if;

  if v_claim.claimant_user_id is null then
    raise exception
      'claimant_account_missing';
  end if;

  if v_decision = 'rejected' then
    update public.artist_claim_requests
    set
      status = 'rejected',
      decided_at = now(),
      decided_by = v_actor,
      decision_reason = v_reason,
      updated_at = now()
    where id = v_claim.id;

    perform editorial.record_artist_representation_event(
      v_claim.artist_id,
      'claim_rejected',
      v_claim.id,
      null,
      v_claim.claimant_user_id,
      jsonb_build_object(
        'reason',
          v_reason
      )
    );

    insert into public.admin_audit_events (
      actor_user_id,
      target_user_id,
      event_type,
      target_table,
      target_record_id,
      message,
      metadata
    )
    values (
      v_actor,
      v_claim.claimant_user_id,
      'artist_claim_rejected',
      'artist_claim_requests',
      v_claim.id::text,
      v_reason,
      jsonb_build_object(
        'artist_id',
          v_claim.artist_id
      )
    );

    perform editorial.sync_artist_portal_roles(
      v_claim.claimant_user_id
    );

    return jsonb_build_object(
      'claim_id',
        v_claim.id,
      'status',
        'rejected'
    );
  end if;

  select *
  into v_defaults
  from editorial.artist_representation_defaults(
    v_claim.claimant_role
  );

  v_profile :=
    coalesce(
      p_can_manage_profile,
      v_defaults.can_manage_profile
    );

  v_releases :=
    coalesce(
      p_can_submit_releases,
      v_defaults.can_submit_releases
    );

  v_updates :=
    coalesce(
      p_can_post_updates,
      v_defaults.can_post_updates
    );

  v_team :=
    coalesce(
      p_can_manage_team,
      v_defaults.can_manage_team
    );

  select representation.id
  into v_representation_id
  from public.artist_representations representation
  where representation.artist_id =
        v_claim.artist_id
    and representation.user_id =
        v_claim.claimant_user_id
    and representation.status in (
      'pending',
      'active'
    )
  order by representation.created_at desc
  limit 1
  for update;

  if v_representation_id is null then
    insert into public.artist_representations (
      artist_id,
      user_id,
      representation_role,
      status,
      source_claim_id,
      can_manage_profile,
      can_submit_releases,
      can_post_updates,
      can_manage_team,
      accepted_at,
      verified_by,
      verified_at
    )
    values (
      v_claim.artist_id,
      v_claim.claimant_user_id,
      v_claim.claimant_role,
      'active',
      v_claim.id,
      v_profile,
      v_releases,
      v_updates,
      v_team,
      now(),
      v_actor,
      now()
    )
    returning id
    into v_representation_id;
  else
    update public.artist_representations
    set
      representation_role =
        v_claim.claimant_role,
      status = 'active',
      source_claim_id =
        v_claim.id,
      can_manage_profile =
        v_profile,
      can_submit_releases =
        v_releases,
      can_post_updates =
        v_updates,
      can_manage_team =
        v_team,
      accepted_at =
        coalesce(
          accepted_at,
          now()
        ),
      verified_by =
        v_actor,
      verified_at =
        now(),
      revoked_by =
        null,
      revoked_at =
        null,
      revocation_reason =
        null,
      updated_at =
        now()
    where id =
          v_representation_id;
  end if;

  update public.artist_claim_requests
  set
    status = 'verified',
    decided_at = now(),
    decided_by = v_actor,
    decision_reason = v_reason,
    updated_at = now()
  where id = v_claim.id;

  perform editorial.record_artist_representation_event(
    v_claim.artist_id,
    'claim_verified',
    v_claim.id,
    v_representation_id,
    v_claim.claimant_user_id,
    jsonb_build_object(
      'reason',
        v_reason,
      'role',
        v_claim.claimant_role,
      'permissions',
        jsonb_build_object(
          'profile',
            v_profile,
          'releases',
            v_releases,
          'updates',
            v_updates,
          'team',
            v_team
        )
    )
  );

  insert into public.admin_audit_events (
    actor_user_id,
    target_user_id,
    event_type,
    target_table,
    target_record_id,
    message,
    metadata
  )
  values (
    v_actor,
    v_claim.claimant_user_id,
    'artist_claim_verified',
    'artist_claim_requests',
    v_claim.id::text,
    v_reason,
    jsonb_build_object(
      'artist_id',
        v_claim.artist_id,
      'representation_id',
        v_representation_id,
      'role',
        v_claim.claimant_role,
      'permissions',
        jsonb_build_object(
          'profile',
            v_profile,
          'releases',
            v_releases,
          'updates',
            v_updates,
          'team',
            v_team
        )
    )
  );

  perform editorial.sync_artist_portal_roles(
    v_claim.claimant_user_id
  );

  return jsonb_build_object(
    'claim_id',
      v_claim.id,
    'status',
      'verified',
    'representation_id',
      v_representation_id,
    'permissions',
      jsonb_build_object(
        'profile',
          v_profile,
        'releases',
          v_releases,
        'updates',
          v_updates,
        'team',
          v_team
      )
  );
end;
$$;


ALTER FUNCTION "public"."community_admin_decide_artist_claim"("p_claim_id" "uuid", "p_decision" "text", "p_reason" "text", "p_can_manage_profile" boolean, "p_can_submit_releases" boolean, "p_can_post_updates" boolean, "p_can_manage_team" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_admin_get_artist_claims"("p_status" "text" DEFAULT 'pending'::"text", "p_limit" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_status text :=
    nullif(
      lower(
        trim(
          coalesce(
            p_status,
            ''
          )
        )
      ),
      ''
    );
  v_limit integer :=
    least(
      greatest(
        coalesce(
          p_limit,
          100
        ),
        1
      ),
      200
    );
  v_result jsonb;
begin
  if not editorial.current_user_can_review_artist_claims() then
    raise exception
      'insufficient_privilege';
  end if;

  if v_status is not null
     and v_status not in (
       'pending',
       'verified',
       'rejected',
       'withdrawn',
       'revoked'
     )
  then
    raise exception
      'invalid_claim_status';
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id',
          claim.id,
        'status',
          claim.status,
        'claimant_role',
          claim.claimant_role,
        'statement',
          claim.statement,
        'submitted_at',
          claim.submitted_at,
        'decided_at',
          claim.decided_at,
        'decision_reason',
          claim.decision_reason,
        'artist',
          jsonb_build_object(
            'id',
              artist.id,
            'slug',
              artist.slug,
            'display_name',
              artist.display_name
          ),
        'claimant',
          jsonb_build_object(
            'user_id',
              claim.claimant_user_id,
            'username',
              profile.username,
            'display_name',
              profile.display_name
          ),
        'evidence',
          (
            select coalesce(
              jsonb_agg(
                jsonb_build_object(
                  'id',
                    evidence.id,
                  'type',
                    evidence.evidence_type,
                  'reference',
                    evidence.reference,
                  'note',
                    evidence.note
                )
                order by evidence.created_at
              ),
              '[]'::jsonb
            )
            from public.artist_claim_evidence evidence
            where evidence.claim_id =
                  claim.id
          )
      )
      order by
        claim.submitted_at asc
    ),
    '[]'::jsonb
  )
  into v_result
  from (
    select *
    from public.artist_claim_requests claim
    where v_status is null
       or claim.status = v_status
    order by claim.submitted_at asc
    limit v_limit
  ) claim
  join public.registry_artists artist
    on artist.id = claim.artist_id
  left join public.user_profiles profile
    on profile.user_id =
       claim.claimant_user_id;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."community_admin_get_artist_claims"("p_status" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_admin_get_registry_onboarding_artists"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  v_fallback_enabled boolean;
  v_artists jsonb;
begin
  if auth.uid() is null
     or not public.current_user_is_administrator()
  then
    raise exception
      'Administrator access required'
      using errcode = '42501';
  end if;

  select
    config.fallback_enabled
  into
    v_fallback_enabled
  from private.registry_onboarding_config
    config
  where config.config_key =
        'default';

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'artist_id',
            artist.id,
          'artist_slug',
            artist.slug,
          'artist_name',
            artist.display_name,
          'artist_image',
            artist.public_image_url,
          'artist_status',
            artist.status,
          'display_order',
            editorial.display_order
        )
        order by
          editorial.display_order
      ),
      '[]'::jsonb
    )
  into
    v_artists
  from private.registry_onboarding_editorial_artists
    editorial
  join public.registry_artists
    artist
    on artist.id =
       editorial.artist_id;

  return jsonb_build_object(
    'fallback_enabled',
      coalesce(
        v_fallback_enabled,
        true
      ),
    'artists',
      v_artists
  );
end;
$$;


ALTER FUNCTION "public"."community_admin_get_registry_onboarding_artists"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_admin_revoke_artist_representation"("p_representation_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_target public.artist_representations%rowtype;
  v_reason text :=
    trim(
      coalesce(
        p_reason,
        ''
      )
    );
begin
  if v_actor is null then
    raise exception
      'authentication_required';
  end if;

  if not editorial.current_user_can_review_artist_claims() then
    raise exception
      'insufficient_privilege';
  end if;

  if char_length(v_reason) < 3
     or char_length(v_reason) > 4000
  then
    raise exception
      'invalid_revocation_reason';
  end if;

  select *
  into v_target
  from public.artist_representations
  where id = p_representation_id
  for update;

  if not found
     or v_target.status not in (
       'pending',
       'active'
     )
  then
    raise exception
      'representation_not_found';
  end if;

  update public.artist_representations
  set
    status = 'revoked',
    revoked_by = v_actor,
    revoked_at = now(),
    revocation_reason = v_reason,
    updated_at = now()
  where id = v_target.id;

  if v_target.source_claim_id is not null then
    update public.artist_claim_requests
    set
      status = 'revoked',
      decided_at =
        coalesce(
          decided_at,
          now()
        ),
      decided_by =
        coalesce(
          decided_by,
          v_actor
        ),
      decision_reason =
        v_reason,
      updated_at =
        now()
    where id =
          v_target.source_claim_id
      and status = 'verified';
  end if;

  perform editorial.record_artist_representation_event(
    v_target.artist_id,
    'representation_revoked',
    v_target.source_claim_id,
    v_target.id,
    v_target.user_id,
    jsonb_build_object(
      'reason',
        v_reason,
      'admin',
        true
    )
  );

  insert into public.admin_audit_events (
    actor_user_id,
    target_user_id,
    event_type,
    target_table,
    target_record_id,
    message,
    metadata
  )
  values (
    v_actor,
    v_target.user_id,
    'artist_representation_revoked',
    'artist_representations',
    v_target.id::text,
    v_reason,
    jsonb_build_object(
      'artist_id',
        v_target.artist_id,
      'representation_role',
        v_target.representation_role
    )
  );

  perform editorial.sync_artist_portal_roles(
    v_target.user_id
  );

  return jsonb_build_object(
    'representation_id',
      v_target.id,
    'status',
      'revoked'
  );
end;
$$;


ALTER FUNCTION "public"."community_admin_revoke_artist_representation"("p_representation_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_admin_set_registry_onboarding_artists"("p_artist_slugs" "text"[], "p_fallback_enabled" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  v_artist_slugs text[] :=
    coalesce(
      p_artist_slugs,
      array[]::text[]
    );

  v_count integer :=
    cardinality(
      coalesce(
        p_artist_slugs,
        array[]::text[]
      )
    );

  v_resolved_count integer;
begin
  if auth.uid() is null
     or not public.current_user_is_administrator()
  then
    raise exception
      'Administrator access required'
      using errcode = '42501';
  end if;

  if v_count > 24
  then
    raise exception
      'Onboarding opening field supports at most 24 Artists'
      using errcode = '22023';
  end if;

  if exists (
    select 1
    from unnest(
      v_artist_slugs
    ) requested(
      slug
    )
    where nullif(
            btrim(
              requested.slug
            ),
            ''
          ) is null
  ) then
    raise exception
      'Artist slugs must be non-empty'
      using errcode = '22023';
  end if;

  if (
    select
      count(*)
    from unnest(
      v_artist_slugs
    ) requested(
      slug
    )
  ) <>
  (
    select
      count(
        distinct btrim(
          requested.slug
        )
      )
    from unnest(
      v_artist_slugs
    ) requested(
      slug
    )
  ) then
    raise exception
      'Onboarding opening field cannot contain duplicate Artists'
      using errcode = '22023';
  end if;

  select
    count(*)
  into
    v_resolved_count
  from public.registry_artists
    artist
  where artist.status =
        'active'
    and nullif(
          btrim(
            coalesce(
              artist.display_name,
              ''
            )
          ),
          ''
        ) is not null
    and nullif(
          btrim(
            coalesce(
              artist.public_image_url,
              ''
            )
          ),
          ''
        ) is not null
    and artist.slug = any (
      select
        btrim(
          requested.slug
        )
      from unnest(
        v_artist_slugs
      ) requested(
        slug
      )
    );

  if v_resolved_count <>
     v_count
  then
    raise exception
      'Every onboarding Artist must resolve to one active Registry Artist'
      using errcode = '22023';
  end if;

  delete from
    private.registry_onboarding_editorial_artists;

  insert into
    private.registry_onboarding_editorial_artists (
      artist_id,
      display_order,
      created_by
    )
  select
    artist.id,
    requested.ordinality::integer - 1,
    auth.uid()
  from unnest(
    v_artist_slugs
  ) with ordinality
    requested(
      slug,
      ordinality
    )
  join public.registry_artists
    artist
    on artist.slug =
       btrim(
         requested.slug
       )
   and artist.status =
       'active'
   and nullif(
         btrim(
           coalesce(
             artist.display_name,
             ''
           )
         ),
         ''
       ) is not null
   and nullif(
         btrim(
           coalesce(
             artist.public_image_url,
             ''
           )
         ),
         ''
       ) is not null
  order by
    requested.ordinality;

  insert into
    private.registry_onboarding_config (
      config_key,
      fallback_enabled,
      updated_by,
      created_at,
      updated_at
    )
  values (
    'default',
    coalesce(
      p_fallback_enabled,
      true
    ),
    auth.uid(),
    now(),
    now()
  )
  on conflict (
    config_key
  )
  do update
  set
    fallback_enabled =
      excluded.fallback_enabled,
    updated_by =
      excluded.updated_by,
    updated_at =
      now();

  return jsonb_build_object(
    'updated',
      true,
    'artist_count',
      v_count,
    'fallback_enabled',
      coalesce(
        p_fallback_enabled,
        true
      )
  );
end;
$$;


ALTER FUNCTION "public"."community_admin_set_registry_onboarding_artists"("p_artist_slugs" "text"[], "p_fallback_enabled" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_artist_accept_representation"("p_representation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_rep public.artist_representations%rowtype;
begin
  if v_actor is null then
    raise exception
      'authentication_required';
  end if;

  select *
  into v_rep
  from public.artist_representations
  where id = p_representation_id
  for update;

  if not found
     or v_rep.user_id
        is distinct from v_actor
  then
    raise exception
      'representation_not_found';
  end if;

  if v_rep.status <> 'pending' then
    raise exception
      'representation_not_pending';
  end if;

  update public.artist_representations
  set
    status = 'active',
    accepted_at = now(),
    updated_at = now()
  where id = v_rep.id;

  perform editorial.record_artist_representation_event(
    v_rep.artist_id,
    'representation_accepted',
    v_rep.source_claim_id,
    v_rep.id,
    v_actor,
    '{}'::jsonb
  );

  perform editorial.sync_artist_portal_roles(
    v_actor
  );

  return jsonb_build_object(
    'representation_id',
      v_rep.id,
    'status',
      'active'
  );
end;
$$;


ALTER FUNCTION "public"."community_artist_accept_representation"("p_representation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_artist_get_team"("p_artist_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_result jsonb;
begin
  if v_actor is null then
    raise exception
      'authentication_required';
  end if;

  if not exists (
    select 1
    from public.artist_representations representation
    where representation.artist_id = p_artist_id
      and representation.user_id = v_actor
      and representation.status = 'active'
  )
     and not editorial.current_user_can_review_artist_claims()
  then
    raise exception
      'insufficient_privilege';
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id',
          representation.id,
        'user_id',
          representation.user_id,
        'username',
          profile.username,
        'display_name',
          profile.display_name,
        'role',
          representation.representation_role,
        'status',
          representation.status,
        'permissions',
          jsonb_build_object(
            'profile',
              representation.can_manage_profile,
            'releases',
              representation.can_submit_releases,
            'updates',
              representation.can_post_updates,
            'team',
              representation.can_manage_team
          ),
        'invited_at',
          representation.invited_at,
        'accepted_at',
          representation.accepted_at,
        'verified_at',
          representation.verified_at
      )
      order by
        case representation.status
          when 'active' then 0
          else 1
        end,
        representation.created_at
    ),
    '[]'::jsonb
  )
  into v_result
  from public.artist_representations representation
  left join public.user_profiles profile
    on profile.user_id =
       representation.user_id
  where representation.artist_id =
        p_artist_id
    and representation.status in (
      'pending',
      'active'
    );

  return v_result;
end;
$$;


ALTER FUNCTION "public"."community_artist_get_team"("p_artist_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_artist_invite_representative"("p_artist_id" "uuid", "p_username" "text", "p_representation_role" "text", "p_can_manage_profile" boolean DEFAULT NULL::boolean, "p_can_submit_releases" boolean DEFAULT NULL::boolean, "p_can_post_updates" boolean DEFAULT NULL::boolean, "p_can_manage_team" boolean DEFAULT NULL::boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_actor_rep public.artist_representations%rowtype;
  v_target_user uuid;
  v_role text :=
    lower(
      trim(
        coalesce(
          p_representation_role,
          ''
        )
      )
    );
  v_defaults record;
  v_profile boolean;
  v_releases boolean;
  v_updates boolean;
  v_team boolean;
  v_representation_id uuid;
begin
  if v_actor is null then
    raise exception
      'authentication_required';
  end if;

  if v_role not in (
    'manager',
    'label',
    'publicist',
    'team_member',
    'other'
  ) then
    raise exception
      'invalid_team_representation_role';
  end if;

  select *
  into v_actor_rep
  from public.artist_representations representation
  where representation.artist_id = p_artist_id
    and representation.user_id = v_actor
    and representation.status = 'active'
    and representation.can_manage_team = true
  order by representation.created_at desc
  limit 1;

  if not found then
    raise exception
      'insufficient_artist_team_privilege';
  end if;

  select profile.user_id
  into v_target_user
  from public.user_profiles profile
  where profile.username_normalized =
        public.community_normalize_username(
          p_username
        )
  limit 1;

  if v_target_user is null then
    raise exception
      'team_account_not_found';
  end if;

  if v_target_user = v_actor then
    raise exception
      'cannot_invite_self';
  end if;

  if exists (
    select 1
    from public.artist_representations representation
    where representation.artist_id = p_artist_id
      and representation.user_id =
          v_target_user
      and representation.status in (
        'pending',
        'active'
      )
  ) then
    raise exception
      'representation_already_exists';
  end if;

  select *
  into v_defaults
  from editorial.artist_representation_defaults(
    v_role
  );

  v_profile :=
    coalesce(
      p_can_manage_profile,
      v_defaults.can_manage_profile
    );

  v_releases :=
    coalesce(
      p_can_submit_releases,
      v_defaults.can_submit_releases
    );

  v_updates :=
    coalesce(
      p_can_post_updates,
      v_defaults.can_post_updates
    );

  v_team :=
    coalesce(
      p_can_manage_team,
      v_defaults.can_manage_team
    );

  if v_profile
     and not v_actor_rep.can_manage_profile
  then
    raise exception
      'cannot_delegate_profile_permission';
  end if;

  if v_releases
     and not v_actor_rep.can_submit_releases
  then
    raise exception
      'cannot_delegate_release_permission';
  end if;

  if v_updates
     and not v_actor_rep.can_post_updates
  then
    raise exception
      'cannot_delegate_update_permission';
  end if;

  if v_team
     and not v_actor_rep.can_manage_team
  then
    raise exception
      'cannot_delegate_team_permission';
  end if;

  insert into public.artist_representations (
    artist_id,
    user_id,
    representation_role,
    status,
    can_manage_profile,
    can_submit_releases,
    can_post_updates,
    can_manage_team,
    invited_by,
    invited_at
  )
  values (
    p_artist_id,
    v_target_user,
    v_role,
    'pending',
    v_profile,
    v_releases,
    v_updates,
    v_team,
    v_actor,
    now()
  )
  returning id
  into v_representation_id;

  perform editorial.record_artist_representation_event(
    p_artist_id,
    'representation_invited',
    null,
    v_representation_id,
    v_target_user,
    jsonb_build_object(
      'role',
        v_role,
      'permissions',
        jsonb_build_object(
          'profile',
            v_profile,
          'releases',
            v_releases,
          'updates',
            v_updates,
          'team',
            v_team
        )
    )
  );

  return jsonb_build_object(
    'representation_id',
      v_representation_id,
    'status',
      'pending',
    'user_id',
      v_target_user
  );
end;
$$;


ALTER FUNCTION "public"."community_artist_invite_representative"("p_artist_id" "uuid", "p_username" "text", "p_representation_role" "text", "p_can_manage_profile" boolean, "p_can_submit_releases" boolean, "p_can_post_updates" boolean, "p_can_manage_team" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_artist_revoke_representation"("p_representation_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_target public.artist_representations%rowtype;
  v_reason text :=
    trim(
      coalesce(
        p_reason,
        ''
      )
    );
  v_actor_can_manage boolean;
begin
  if v_actor is null then
    raise exception
      'authentication_required';
  end if;

  if char_length(v_reason) < 3
     or char_length(v_reason) > 4000
  then
    raise exception
      'invalid_revocation_reason';
  end if;

  select *
  into v_target
  from public.artist_representations
  where id = p_representation_id
  for update;

  if not found
     or v_target.status not in (
       'pending',
       'active'
     )
  then
    raise exception
      'representation_not_found';
  end if;

  if v_target.user_id = v_actor then
    v_actor_can_manage := true;
  else
    select exists (
      select 1
      from public.artist_representations representation
      where representation.artist_id =
            v_target.artist_id
        and representation.user_id =
            v_actor
        and representation.status =
            'active'
        and representation.can_manage_team =
            true
    )
    into v_actor_can_manage;
  end if;

  if not v_actor_can_manage then
    raise exception
      'insufficient_artist_team_privilege';
  end if;

  if v_target.representation_role = 'artist'
     and v_target.user_id <> v_actor
  then
    raise exception
      'artist_role_requires_admin_review';
  end if;

  update public.artist_representations
  set
    status = 'revoked',
    revoked_by = v_actor,
    revoked_at = now(),
    revocation_reason = v_reason,
    updated_at = now()
  where id = v_target.id;

  if v_target.source_claim_id is not null then
    update public.artist_claim_requests
    set
      status = 'revoked',
      decided_at =
        coalesce(
          decided_at,
          now()
        ),
      decision_reason =
        v_reason,
      updated_at =
        now()
    where id =
          v_target.source_claim_id
      and status = 'verified';
  end if;

  perform editorial.record_artist_representation_event(
    v_target.artist_id,
    'representation_revoked',
    v_target.source_claim_id,
    v_target.id,
    v_target.user_id,
    jsonb_build_object(
      'reason',
        v_reason
    )
  );

  perform editorial.sync_artist_portal_roles(
    v_target.user_id
  );

  return jsonb_build_object(
    'representation_id',
      v_target.id,
    'status',
      'revoked'
  );
end;
$$;


ALTER FUNCTION "public"."community_artist_revoke_representation"("p_representation_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_artist_update_representative"("p_representation_id" "uuid", "p_representation_role" "text", "p_can_manage_profile" boolean, "p_can_submit_releases" boolean, "p_can_post_updates" boolean, "p_can_manage_team" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_target public.artist_representations%rowtype;
  v_actor_rep public.artist_representations%rowtype;
  v_role text :=
    lower(
      trim(
        coalesce(
          p_representation_role,
          ''
        )
      )
    );
begin
  if v_actor is null then
    raise exception
      'authentication_required';
  end if;

  select *
  into v_target
  from public.artist_representations
  where id = p_representation_id
  for update;

  if not found
     or v_target.status not in (
       'pending',
       'active'
     )
  then
    raise exception
      'representation_not_found';
  end if;

  if v_target.representation_role = 'artist' then
    raise exception
      'artist_role_requires_admin_review';
  end if;

  if v_role not in (
    'manager',
    'label',
    'publicist',
    'team_member',
    'other'
  ) then
    raise exception
      'invalid_team_representation_role';
  end if;

  select *
  into v_actor_rep
  from public.artist_representations representation
  where representation.artist_id =
        v_target.artist_id
    and representation.user_id =
        v_actor
    and representation.status =
        'active'
    and representation.can_manage_team =
        true
  order by representation.created_at desc
  limit 1;

  if not found then
    raise exception
      'insufficient_artist_team_privilege';
  end if;

  if p_can_manage_profile
     and not v_actor_rep.can_manage_profile
  then
    raise exception
      'cannot_delegate_profile_permission';
  end if;

  if p_can_submit_releases
     and not v_actor_rep.can_submit_releases
  then
    raise exception
      'cannot_delegate_release_permission';
  end if;

  if p_can_post_updates
     and not v_actor_rep.can_post_updates
  then
    raise exception
      'cannot_delegate_update_permission';
  end if;

  if p_can_manage_team
     and not v_actor_rep.can_manage_team
  then
    raise exception
      'cannot_delegate_team_permission';
  end if;

  update public.artist_representations
  set
    representation_role =
      v_role,
    can_manage_profile =
      p_can_manage_profile,
    can_submit_releases =
      p_can_submit_releases,
    can_post_updates =
      p_can_post_updates,
    can_manage_team =
      p_can_manage_team,
    updated_at =
      now()
  where id =
        v_target.id;

  perform editorial.record_artist_representation_event(
    v_target.artist_id,
    'representation_updated',
    v_target.source_claim_id,
    v_target.id,
    v_target.user_id,
    jsonb_build_object(
      'role',
        v_role,
      'permissions',
        jsonb_build_object(
          'profile',
            p_can_manage_profile,
          'releases',
            p_can_submit_releases,
          'updates',
            p_can_post_updates,
          'team',
            p_can_manage_team
        )
    )
  );

  return jsonb_build_object(
    'representation_id',
      v_target.id,
    'status',
      v_target.status,
    'role',
      v_role
  );
end;
$$;


ALTER FUNCTION "public"."community_artist_update_representative"("p_representation_id" "uuid", "p_representation_role" "text", "p_can_manage_profile" boolean, "p_can_submit_releases" boolean, "p_can_post_updates" boolean, "p_can_manage_team" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_create_comment"("p_thread_id" "uuid", "p_parent_id" "uuid", "p_body_markdown" "text", "p_body_plain" "text", "p_body_html" "text", "p_status" "text" DEFAULT 'visible'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_comment jsonb;
  v_comment_id uuid;
  v_depth int;
  v_root_id uuid;
  v_thread_status text;
  v_thread_entity_type text;
  v_thread_entity_slug text;
  v_thread_entity_id text;
BEGIN
  -- Check thread is open
  SELECT status, entity_type, entity_slug, entity_id
  INTO v_thread_status, v_thread_entity_type, v_thread_entity_slug, v_thread_entity_id
  FROM community_threads WHERE id = p_thread_id;
  
  IF v_thread_status != 'open' THEN
    RAISE EXCEPTION 'Thread is locked or archived';
  END IF;

  -- Validate parent if replying
  IF p_parent_id IS NOT NULL THEN
    SELECT depth, root_id INTO v_depth, v_root_id
    FROM community_comments WHERE id = p_parent_id;
    IF v_depth IS NULL THEN
      RAISE EXCEPTION 'Parent comment not found';
    END IF;
    v_depth := v_depth + 1;
  ELSE
    v_depth := 0;
  END IF;

  -- Insert comment
  INSERT INTO community_comments (thread_id, parent_id, root_id, author_id, body_markdown, body_plain, body_html, depth, status)
  VALUES (p_thread_id, p_parent_id, v_root_id, auth.uid(), p_body_markdown, p_body_plain, p_body_html, v_depth, p_status)
  RETURNING id, to_jsonb(community_comments.*) INTO v_comment_id, v_comment;

  -- Update parent reply_count
  IF p_parent_id IS NOT NULL THEN
    UPDATE community_comments SET reply_count = reply_count + 1 WHERE id = p_parent_id;
  END IF;

  -- Update thread stats
  UPDATE community_threads
  SET comment_count = comment_count + 1,
      root_comment_count = root_comment_count + CASE WHEN p_parent_id IS NULL THEN 1 ELSE 0 END,
      last_comment_at = now()
  WHERE id = p_thread_id;

  -- Update author profile comment_count
  UPDATE community_profiles SET comment_count = comment_count + 1 WHERE user_id = auth.uid();

  -- Distribute notifications (non-blocking)
  BEGIN
    PERFORM community_distribute_notifications(p_thread_id, v_comment_id, auth.uid(), p_parent_id);
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  -- Write to activity feed
  INSERT INTO community_activity (user_id, activity_type, entity_type, entity_id, entity_slug, comment_id, metadata, visibility)
  VALUES (
    auth.uid(),
    CASE WHEN p_parent_id IS NOT NULL THEN 'reply' ELSE 'comment' END,
    v_thread_entity_type,
    v_thread_entity_id,
    v_thread_entity_slug,
    v_comment_id,
    jsonb_build_object(
      'thread_title', (SELECT title FROM community_threads WHERE id = p_thread_id),
      'is_reply', p_parent_id IS NOT NULL
    ),
    'public'
  );

  RETURN jsonb_build_object('comment', v_comment);
END;
$$;


ALTER FUNCTION "public"."community_create_comment"("p_thread_id" "uuid", "p_parent_id" "uuid", "p_body_markdown" "text", "p_body_plain" "text", "p_body_html" "text", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_create_context_anchor_comment"("p_thread_id" "uuid", "p_body_markdown" "text", "p_body_plain" "text" DEFAULT NULL::"text", "p_body_html" "text" DEFAULT NULL::"text", "p_anchor_type" "text" DEFAULT NULL::"text", "p_context_entity_type" "text" DEFAULT NULL::"text", "p_context_entity_id" "text" DEFAULT NULL::"text", "p_context_entity_slug" "text" DEFAULT NULL::"text", "p_context_label" "text" DEFAULT NULL::"text", "p_anchor_label" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_result jsonb;
  v_comment_id uuid;
  v_comment public.community_comments%rowtype;
  v_anchor_type text;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;

  if nullif(trim(coalesce(p_body_markdown, '')), '') is null then
    raise exception 'Comment body cannot be empty' using errcode = '22023';
  end if;

  v_anchor_type := nullif(trim(coalesce(p_anchor_type, '')), '');

  if v_anchor_type is null
    or v_anchor_type not in (
      'release_track',
      'chart_entry',
      'playlist_track'
    )
  then
    raise exception 'Unsupported context anchor type' using errcode = '22023';
  end if;

  if nullif(trim(coalesce(p_context_entity_type, '')), '') is null then
    raise exception 'Context entity type is required' using errcode = '22023';
  end if;

  if nullif(
    trim(
      coalesce(
        p_context_entity_id,
        p_context_entity_slug,
        ''
      )
    ),
    ''
  ) is null
  then
    raise exception 'Context entity id or slug is required' using errcode = '22023';
  end if;

  select public.community_create_comment(
    p_thread_id,
    null,
    p_body_markdown,
    p_body_plain,
    p_body_html,
    'visible'
  )
  into v_result;

  v_comment_id := (v_result->'comment'->>'id')::uuid;

  update public.community_comments
  set
    anchor_type = v_anchor_type,
    context_entity_type = nullif(
      trim(coalesce(p_context_entity_type, '')),
      ''
    ),
    context_entity_id = nullif(
      trim(coalesce(p_context_entity_id, '')),
      ''
    ),
    context_entity_slug = nullif(
      trim(coalesce(p_context_entity_slug, '')),
      ''
    ),
    context_label = nullif(
      trim(coalesce(p_context_label, '')),
      ''
    ),
    anchor_label = nullif(
      trim(
        coalesce(
          p_anchor_label,
          p_context_label,
          ''
        )
      ),
      ''
    ),
    updated_at = now()
  where id = v_comment_id
  returning * into v_comment;

  return jsonb_build_object(
    'comment',
    to_jsonb(v_comment)
  );
end;
$$;


ALTER FUNCTION "public"."community_create_context_anchor_comment"("p_thread_id" "uuid", "p_body_markdown" "text", "p_body_plain" "text", "p_body_html" "text", "p_anchor_type" "text", "p_context_entity_type" "text", "p_context_entity_id" "text", "p_context_entity_slug" "text", "p_context_label" "text", "p_anchor_label" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_create_contribution"("p_source_comment_id" "uuid", "p_entity_type" "text", "p_entity_id" "text", "p_entity_slug" "text", "p_contribution_type" "text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();

  v_entity_type text :=
    nullif(
      trim(
        coalesce(
          p_entity_type,
          ''
        )
      ),
      ''
    );

  v_entity_id text :=
    nullif(
      trim(
        coalesce(
          p_entity_id,
          ''
        )
      ),
      ''
    );

  v_entity_slug text :=
    nullif(
      trim(
        coalesce(
          p_entity_slug,
          ''
        )
      ),
      ''
    );

  v_contribution_type text :=
    nullif(
      trim(
        coalesce(
          p_contribution_type,
          ''
        )
      ),
      ''
    );

  v_payload jsonb :=
    coalesce(
      p_payload,
      '{}'::jsonb
    );

  v_contribution jsonb;
begin
  if v_user_id is null then
    raise exception
      'Not authenticated'
      using errcode = '42501';
  end if;

  if v_entity_type is null then
    raise exception
      'Entity type is required'
      using errcode = '22023';
  end if;

  if v_entity_id is null
     and v_entity_slug is null
  then
    raise exception
      'Entity identity is required'
      using errcode = '22023';
  end if;

  if v_contribution_type is null then
    raise exception
      'Contribution type is required'
      using errcode = '22023';
  end if;

  if p_source_comment_id is not null
     and not exists (
       select 1
       from public.community_comments comment
       where comment.id =
         p_source_comment_id
     )
  then
    raise exception
      'Source comment not found'
      using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      v_user_id::text
      || '|contribution|'
      || coalesce(
        p_source_comment_id::text,
        ''
      )
      || '|'
      || v_entity_type
      || '|'
      || coalesce(
        v_entity_id,
        ''
      )
      || '|'
      || coalesce(
        v_entity_slug,
        ''
      )
      || '|'
      || v_contribution_type
      || '|'
      || v_payload::text,
      0
    )
  );

  select to_jsonb(
    contribution.*
  )
  into v_contribution
  from public.community_contributions contribution
  where contribution.user_id =
          v_user_id
    and contribution.source_comment_id
          is not distinct from
          p_source_comment_id
    and contribution.entity_type =
          v_entity_type
    and contribution.entity_id
          is not distinct from
          v_entity_id
    and contribution.entity_slug
          is not distinct from
          v_entity_slug
    and contribution.contribution_type =
          v_contribution_type
    and contribution.payload =
          v_payload
    and contribution.status =
          'pending'
  order by contribution.created_at desc
  limit 1;

  if v_contribution is not null then
    return jsonb_build_object(
      'contribution',
        v_contribution,
      'created',
        false
    );
  end if;

  insert into public.community_contributions (
    user_id,
    source_comment_id,
    entity_type,
    entity_id,
    entity_slug,
    contribution_type,
    payload
  )
  values (
    v_user_id,
    p_source_comment_id,
    v_entity_type,
    v_entity_id,
    v_entity_slug,
    v_contribution_type,
    v_payload
  )
  returning to_jsonb(
    community_contributions.*
  )
  into v_contribution;

  return jsonb_build_object(
    'contribution',
      v_contribution,
    'created',
      true
  );
end;
$$;


ALTER FUNCTION "public"."community_create_contribution"("p_source_comment_id" "uuid", "p_entity_type" "text", "p_entity_id" "text", "p_entity_slug" "text", "p_contribution_type" "text", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_create_profile"("p_user_id" "uuid", "p_username" "text", "p_display_name" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_actor uuid;
  v_username text;
  v_profile public.user_profiles%rowtype;
  v_person_resource_id uuid;
  v_path_holder_resource_id uuid;
begin
  v_actor := auth.uid();

  if v_actor is null then
    raise exception
      'authentication required';
  end if;

  if p_user_id <> v_actor
     and not public.current_user_is_administrator()
  then
    raise exception
      'not allowed';
  end if;

  perform public.community_ensure_user_account(
    p_user_id
  );

  v_username :=
    public.community_normalize_username(
      p_username
    );

  if v_username is null
     or not public.community_username_is_valid(
       v_username
     )
  then
    raise exception
      'invalid handle: use 3-30 lowercase letters, numbers, and underscores; start and end with a letter or number';
  end if;

  if public.community_username_is_reserved(
       v_username
     )
  then
    raise exception
      'handle % is reserved',
      v_username;
  end if;

  if exists (
    select 1
    from public.user_profiles profile
    where profile.username_normalized =
          v_username
      and profile.user_id <> p_user_id
  )
  then
    raise exception
      'handle % is already taken',
      v_username;
  end if;

  select link.person_resource_id
  into v_person_resource_id
  from editorial.person_identity_links link
  where link.user_id = p_user_id
    and link.link_state = 'active'
  limit 1;

  if v_person_resource_id is not null then
    select resolved.person_resource_id
    into v_person_resource_id
    from editorial.resolve_person_follow_target(
      v_person_resource_id
    ) resolved;
  end if;

  select alias.resource_id
  into v_path_holder_resource_id
  from editorial.resource_aliases alias
  where alias.path =
        '/people/' || v_username;

  if found
     and (
       v_person_resource_id is null
       or v_path_holder_resource_id <>
          v_person_resource_id
     )
  then
    raise exception
      'handle % is permanently reserved by another Person route',
      v_username;
  end if;

  update public.user_profiles profile
  set
    username = v_username,
    username_normalized = v_username,
    display_name =
      coalesce(
        nullif(p_display_name, ''),
        profile.display_name
      ),
    username_updated_at =
      coalesce(
        profile.username_updated_at,
        now()
      ),
    updated_at = now()
  where profile.user_id = p_user_id
  returning profile.*
  into v_profile;

  return public.community_profile_json(
    v_profile
  );
end;
$$;


ALTER FUNCTION "public"."community_create_profile"("p_user_id" "uuid", "p_username" "text", "p_display_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_create_track_moment_comment"("p_thread_id" "uuid", "p_body_markdown" "text", "p_body_plain" "text" DEFAULT NULL::"text", "p_body_html" "text" DEFAULT NULL::"text", "p_anchor_time_ms" integer DEFAULT NULL::integer, "p_anchor_end_time_ms" integer DEFAULT NULL::integer, "p_anchor_label" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_result jsonb;
  v_comment_id uuid;
  v_comment public.community_comments%rowtype;
  v_anchor_type text;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;

  if nullif(trim(coalesce(p_body_markdown, '')), '') is null then
    raise exception 'Comment body cannot be empty' using errcode = '22023';
  end if;

  if p_anchor_time_ms is null or p_anchor_time_ms < 0 then
    raise exception 'Moment timestamp is required' using errcode = '22023';
  end if;

  v_anchor_type := case
    when p_anchor_end_time_ms is not null and p_anchor_end_time_ms > p_anchor_time_ms then 'time_range'
    else 'timestamp'
  end;

  select public.community_create_comment(
    p_thread_id,
    null,
    p_body_markdown,
    p_body_plain,
    p_body_html,
    'visible'
  )
  into v_result;

  v_comment_id := (v_result->'comment'->>'id')::uuid;

  update public.community_comments
  set
    anchor_type = v_anchor_type,
    anchor_time_ms = p_anchor_time_ms,
    anchor_end_time_ms = case
      when p_anchor_end_time_ms is not null and p_anchor_end_time_ms > p_anchor_time_ms
      then p_anchor_end_time_ms
      else null
    end,
    anchor_label = nullif(trim(coalesce(p_anchor_label, '')), ''),
    updated_at = now()
  where id = v_comment_id
  returning * into v_comment;

  return jsonb_build_object('comment', to_jsonb(v_comment));
end;
$$;


ALTER FUNCTION "public"."community_create_track_moment_comment"("p_thread_id" "uuid", "p_body_markdown" "text", "p_body_plain" "text", "p_body_html" "text", "p_anchor_time_ms" integer, "p_anchor_end_time_ms" integer, "p_anchor_label" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_distribute_notifications"("p_thread_id" "uuid", "p_comment_id" "uuid", "p_author_id" "uuid", "p_parent_id" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_thread_record record;
  v_parent_author_id uuid;
  v_follower record;
  v_actor_username text;
BEGIN
  -- Get the thread info
  SELECT entity_type, entity_slug, entity_id, title INTO v_thread_record
  FROM community_threads WHERE id = p_thread_id;

  -- Get actor username for metadata
  SELECT username INTO v_actor_username FROM community_profiles WHERE user_id = p_author_id;

  -- 1. Notify parent comment author (reply notification)
  IF p_parent_id IS NOT NULL THEN
    SELECT author_id INTO v_parent_author_id FROM community_comments WHERE id = p_parent_id;
    IF v_parent_author_id IS NOT NULL AND v_parent_author_id != p_author_id THEN
      INSERT INTO community_notifications (user_id, actor_id, notification_type, entity_type, entity_id, entity_slug, comment_id, metadata)
      VALUES (
        v_parent_author_id,
        p_author_id,
        'reply',
        v_thread_record.entity_type,
        v_thread_record.entity_id,
        v_thread_record.entity_slug,
        p_comment_id,
        jsonb_build_object(
          'thread_title', v_thread_record.title,
          'actor_username', v_actor_username
        )
      );
    END IF;
  END IF;

  -- 2. Notify thread followers (new comment notification)
  FOR v_follower IN
    SELECT cf.user_id FROM community_follows cf
    WHERE cf.target_type = 'thread'
      AND cf.target_id = p_thread_id::text
      AND cf.user_id != p_author_id
  LOOP
    INSERT INTO community_notifications (user_id, actor_id, notification_type, entity_type, entity_id, entity_slug, comment_id, metadata)
    VALUES (
      v_follower.user_id,
      p_author_id,
      'new_comment',
      v_thread_record.entity_type,
      v_thread_record.entity_id,
      v_thread_record.entity_slug,
      p_comment_id,
      jsonb_build_object(
        'thread_title', v_thread_record.title,
        'actor_username', v_actor_username
      )
    );
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."community_distribute_notifications"("p_thread_id" "uuid", "p_comment_id" "uuid", "p_author_id" "uuid", "p_parent_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_edit_artist_update"("p_update_id" "uuid", "p_body" "text", "p_image_url" "text" DEFAULT NULL::"text", "p_link_url" "text" DEFAULT NULL::"text", "p_link_label" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_rep public.artist_representations%rowtype;
  v_artist_slug text;
  v_body text := btrim(coalesce(p_body, ''));
  v_image_url text := nullif(btrim(coalesce(p_image_url, '')), '');
  v_link_url text := nullif(btrim(coalesce(p_link_url, '')), '');
  v_link_label text := nullif(btrim(coalesce(p_link_label, '')), '');
  v_update public.artist_updates%rowtype;
begin
  if v_actor is null then
    raise exception 'authentication_required';
  end if;

  select *
  into v_update
  from public.artist_updates
  where id = p_update_id
  for update;

  if not found then
    raise exception 'artist_update_not_found';
  end if;

  if v_update.status <> 'published' then
    raise exception 'artist_update_not_editable';
  end if;

  select *
  into v_rep
  from editorial.current_artist_representation(v_update.artist_id);

  if v_rep.id is null
     or not v_rep.can_post_updates
  then
    raise exception 'insufficient_artist_update_privilege';
  end if;

  if char_length(v_body) < 1
     or char_length(v_body) > 2000
  then
    raise exception 'invalid_artist_update_body';
  end if;

  if v_image_url is not null
     and (
       char_length(v_image_url) > 2048
       or v_image_url !~* '^https?://'
     )
  then
    raise exception 'invalid_artist_update_image_url';
  end if;

  if v_link_url is not null
     and (
       char_length(v_link_url) > 2048
       or v_link_url !~* '^https?://'
     )
  then
    raise exception 'invalid_artist_update_link_url';
  end if;

  if v_link_label is not null
     and (
       char_length(v_link_label) > 120
       or v_link_url is null
     )
  then
    raise exception 'invalid_artist_update_link_label';
  end if;

  update public.artist_updates
  set
    body = v_body,
    image_url = v_image_url,
    link_url = v_link_url,
    link_label = v_link_label,
    updated_at = now()
  where id = p_update_id
  returning *
  into v_update;

  select artist.slug
  into v_artist_slug
  from public.registry_artists artist
  where artist.id = v_update.artist_id;

  perform editorial.record_artist_representation_event(
    v_update.artist_id,
    'artist_update_edited',
    null,
    v_rep.id,
    v_actor,
    jsonb_build_object(
      'artist_update_id', v_update.id,
      'updated_at', v_update.updated_at
    )
  );

  return jsonb_build_object(
    'id', v_update.id,
    'artist_id', v_update.artist_id,
    'body', v_update.body,
    'image_url', v_update.image_url,
    'link_url', v_update.link_url,
    'link_label', v_update.link_label,
    'status', v_update.status,
    'published_at', v_update.published_at,
    'updated_at', v_update.updated_at,
    'canonical_path',
      '/artists/' || v_artist_slug || '/updates/' || v_update.id::text
  );
end;
$$;


ALTER FUNCTION "public"."community_edit_artist_update"("p_update_id" "uuid", "p_body" "text", "p_image_url" "text", "p_link_url" "text", "p_link_label" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_ensure_user_account"("p_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $_$
declare
  v_email text;
  v_display_name text;
  v_username text;
  v_cols text[];
  v_vals text[];
  v_updates text[];
begin
  if p_user_id is null then
    raise exception
      'user_id is required';
  end if;

  if auth.uid() is null then
    raise exception
      'authentication required';
  end if;

  if p_user_id <> auth.uid()
     and not public.current_user_is_administrator()
  then
    raise exception
      'not allowed';
  end if;

  select
    au.email,
    coalesce(
      au.raw_user_meta_data->>'full_name',
      au.raw_user_meta_data->>'name',
      split_part(
        coalesce(
          au.email,
          ''
        ),
        '@',
        1
      ),
      'WAKILISHA user'
    )
  into
    v_email,
    v_display_name
  from auth.users au
  where au.id =
        p_user_id;

  if not found then
    raise exception
      'auth user % not found',
      p_user_id;
  end if;

  v_username :=
    public.community_generate_username(
      p_user_id,
      v_email,
      v_display_name
    );

  insert into public.user_profiles (
    user_id,
    email,
    username,
    username_normalized,
    display_name,
    status,
    metadata,
    created_at,
    updated_at
  )
  values (
    p_user_id,
    v_email,
    v_username,
    v_username,
    v_display_name,
    'active',
    jsonb_build_object(
      'created_by',
      'community_ensure_user_account'
    ),
    now(),
    now()
  )
  on conflict (user_id)
  do update
  set
    email =
      coalesce(
        excluded.email,
        public.user_profiles.email
      ),
    username =
      coalesce(
        public.user_profiles.username,
        excluded.username
      ),
    username_normalized =
      coalesce(
        public.user_profiles.username_normalized,
        excluded.username_normalized
      ),
    display_name =
      coalesce(
        public.user_profiles.display_name,
        excluded.display_name
      ),
    status =
      coalesce(
        public.user_profiles.status,
        'active'
      ),
    updated_at =
      now();

  perform editorial.ensure_person_for_user(
    p_user_id
  );

  -- Keep legacy community_profiles environments hydrated without making it the
  -- canonical identity table.
  if to_regclass(
       'public.community_profiles'
     ) is not null
  then
    v_cols :=
      array['user_id'];
    v_vals :=
      array['$1'];
    v_updates :=
      array[]::text[];

    if exists (
      select 1
      from information_schema.columns
      where table_schema = 'public'
        and table_name =
            'community_profiles'
        and column_name =
            'username'
    ) then
      v_cols :=
        array_append(
          v_cols,
          'username'
        );
      v_vals :=
        array_append(
          v_vals,
          '$2'
        );
      v_updates :=
        array_append(
          v_updates,
          'username = coalesce(public.community_profiles.username, excluded.username)'
        );
    end if;

    if exists (
      select 1
      from information_schema.columns
      where table_schema = 'public'
        and table_name =
            'community_profiles'
        and column_name =
            'display_name'
    ) then
      v_cols :=
        array_append(
          v_cols,
          'display_name'
        );
      v_vals :=
        array_append(
          v_vals,
          '$3'
        );
      v_updates :=
        array_append(
          v_updates,
          'display_name = coalesce(public.community_profiles.display_name, excluded.display_name)'
        );
    end if;

    if exists (
      select 1
      from information_schema.columns
      where table_schema = 'public'
        and table_name =
            'community_profiles'
        and column_name =
            'email'
    ) then
      v_cols :=
        array_append(
          v_cols,
          'email'
        );
      v_vals :=
        array_append(
          v_vals,
          '$4'
        );
      v_updates :=
        array_append(
          v_updates,
          'email = coalesce(excluded.email, public.community_profiles.email)'
        );
    end if;

    if exists (
      select 1
      from information_schema.columns
      where table_schema = 'public'
        and table_name =
            'community_profiles'
        and column_name =
            'is_public'
    ) then
      v_cols :=
        array_append(
          v_cols,
          'is_public'
        );
      v_vals :=
        array_append(
          v_vals,
          'true'
        );
    end if;

    if exists (
      select 1
      from information_schema.columns
      where table_schema = 'public'
        and table_name =
            'community_profiles'
        and column_name =
            'created_at'
    ) then
      v_cols :=
        array_append(
          v_cols,
          'created_at'
        );
      v_vals :=
        array_append(
          v_vals,
          'now()'
        );
    end if;

    if exists (
      select 1
      from information_schema.columns
      where table_schema = 'public'
        and table_name =
            'community_profiles'
        and column_name =
            'updated_at'
    ) then
      v_cols :=
        array_append(
          v_cols,
          'updated_at'
        );
      v_vals :=
        array_append(
          v_vals,
          'now()'
        );
      v_updates :=
        array_append(
          v_updates,
          'updated_at = now()'
        );
    end if;

    execute format(
      'insert into public.community_profiles (%s) values (%s) on conflict (user_id) do update set %s',
      array_to_string(
        v_cols,
        ', '
      ),
      array_to_string(
        v_vals,
        ', '
      ),
      case
        when coalesce(
               array_length(
                 v_updates,
                 1
               ),
               0
             ) > 0
          then array_to_string(
            v_updates,
            ', '
          )
        else
          'user_id = excluded.user_id'
      end
    )
    using
      p_user_id,
      v_username,
      v_display_name,
      v_email;
  end if;
end;
$_$;


ALTER FUNCTION "public"."community_ensure_user_account"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_follow_target"("p_target_type" "text", "p_target_id" "text", "p_target_slug" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  v_user_id uuid :=
    auth.uid();
  v_target record;
  v_current boolean;
begin
  if v_user_id is null then
    raise exception
      'Not authenticated'
      using errcode = '42501';
  end if;

  select *
  into v_target
  from private.community_resolve_follow_target(
    p_target_type,
    p_target_id,
    p_target_slug
  );

  perform pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      v_user_id::text
      || '|follow|'
      || v_target.canonical_type
      || '|'
      || v_target.canonical_id,
      0
    )
  );

  select exists (
    select 1
    from public.community_follows follow
    where follow.user_id =
          v_user_id
      and follow.target_type =
          v_target.canonical_type
      and follow.target_id =
          v_target.canonical_id
  )
  into v_current;

  return public.community_set_follow_state(
    v_target.canonical_type,
    v_target.canonical_id,
    v_target.canonical_slug,
    not v_current
  );
end;
$$;


ALTER FUNCTION "public"."community_follow_target"("p_target_type" "text", "p_target_id" "text", "p_target_slug" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_generate_username"("p_user_id" "uuid", "p_email" "text", "p_display_name" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_base text;
  v_candidate text;
  v_suffix text;
  v_attempt integer := 0;
  v_person_resource_id uuid;
begin
  select link.person_resource_id
  into v_person_resource_id
  from editorial.person_identity_links link
  where link.user_id = p_user_id
    and link.link_state = 'active'
  limit 1;

  if v_person_resource_id is not null then
    select resolved.person_resource_id
    into v_person_resource_id
    from editorial.resolve_person_follow_target(
      v_person_resource_id
    ) resolved;
  end if;

  v_base := public.community_username_seed(
    coalesce(
      nullif(p_display_name, ''),
      nullif(split_part(coalesce(p_email, ''), '@', 1), ''),
      'user'
    )
  );

  v_candidate := v_base;

  if public.community_username_is_reserved(v_candidate)
     or exists (
       select 1
       from public.user_profiles profile
       where profile.username_normalized = v_candidate
         and profile.user_id <> p_user_id
     )
     or exists (
       select 1
       from editorial.resource_aliases alias
       where alias.path = '/people/' || v_candidate
         and (
           v_person_resource_id is null
           or alias.resource_id <> v_person_resource_id
         )
     )
  then
    v_suffix := '_' || left(
      replace(
        coalesce(p_user_id::text, gen_random_uuid()::text),
        '-',
        ''
      ),
      8
    );

    v_candidate :=
      left(v_base, 30 - length(v_suffix))
      || v_suffix;
  end if;

  while public.community_username_is_reserved(v_candidate)
     or exists (
       select 1
       from public.user_profiles profile
       where profile.username_normalized = v_candidate
         and profile.user_id <> p_user_id
     )
     or exists (
       select 1
       from editorial.resource_aliases alias
       where alias.path = '/people/' || v_candidate
         and (
           v_person_resource_id is null
           or alias.resource_id <> v_person_resource_id
         )
     )
  loop
    v_attempt := v_attempt + 1;

    v_suffix := '_' || left(
      replace(
        coalesce(p_user_id::text, gen_random_uuid()::text),
        '-',
        ''
      ),
      6
    ) || v_attempt::text;

    v_candidate :=
      left(v_base, 30 - length(v_suffix))
      || v_suffix;

    if v_attempt > 99 then
      raise exception
        'could not generate unique username for user %',
        p_user_id;
    end if;
  end loop;

  return v_candidate;
end;
$$;


ALTER FUNCTION "public"."community_generate_username"("p_user_id" "uuid", "p_email" "text", "p_display_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_get_artist_manage_updates"("p_artist_id" "uuid", "p_limit" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_rep public.artist_representations%rowtype;
  v_limit integer :=
    least(
      greatest(
        coalesce(p_limit, 30),
        1
      ),
      100
    );
  v_artist_slug text;
  v_result jsonb;
begin
  if v_actor is null then
    raise exception 'authentication_required';
  end if;

  select *
  into v_rep
  from editorial.current_artist_representation(p_artist_id);

  if v_rep.id is null
     or not v_rep.can_post_updates
  then
    raise exception 'insufficient_artist_update_privilege';
  end if;

  select slug
  into v_artist_slug
  from public.registry_artists
  where id = p_artist_id;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', managed.id,
        'artist_id', managed.artist_id,
        'body', managed.body,
        'image_url', managed.image_url,
        'link_url', managed.link_url,
        'link_label', managed.link_label,
        'status', managed.status,
        'published_at', managed.published_at,
        'withdrawn_at', managed.withdrawn_at,
        'updated_at', managed.updated_at,
        'canonical_path',
          '/artists/' || v_artist_slug || '/updates/' || managed.id::text
      )
      order by managed.published_at desc, managed.id desc
    ),
    '[]'::jsonb
  )
  into v_result
  from (
    select artist_update.*
    from public.artist_updates artist_update
    where artist_update.artist_id = p_artist_id
    order by artist_update.published_at desc, artist_update.id desc
    limit v_limit
  ) managed;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."community_get_artist_manage_updates"("p_artist_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_get_artist_music_submissions"("p_artist_id" "uuid", "p_limit" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_rep public.artist_representations%rowtype;
  v_limit integer :=
    least(
      greatest(
        coalesce(p_limit, 30),
        1
      ),
      100
    );
  v_result jsonb;
begin
  if v_actor is null then
    raise exception 'authentication_required';
  end if;

  select *
  into v_rep
  from editorial.current_artist_representation(p_artist_id);

  if v_rep.id is null
     or not v_rep.can_submit_releases
  then
    raise exception 'insufficient_artist_music_privilege';
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_strip_nulls(
        jsonb_build_object(
          'id', submission.id,
          'artist_id', submission.submitted_for_artist_id,
          'status', submission.status,
          'track_title', submission.submitted_track_title,
          'release_title', submission.provider_release_title,
          'provider_key', submission.provider_key,
          'provider_url', submission.provider_url,
          'artwork_url',
            submission.validation_snapshot
              ->> 'artwork_url',
          'created_at', submission.created_at,
          'review_due_at', submission.review_due_at,
          'reviewed_at', submission.reviewed_at,
          'sla_status',
            case
              when submission.reviewed_at is not null
                and submission.reviewed_at <= submission.review_due_at
                then 'reviewed_on_time'
              when submission.reviewed_at is not null
                then 'reviewed_late'
              when now() > submission.review_due_at
                then 'overdue'
              else 'on_time'
            end,
          'canonical_track_id',
            coalesce(
              submission.canonicalized_track_id,
              submission.canonical_track_id
            ),
          'canonical_track_title',
            canonical_track.title
        )
      )
      order by submission.created_at desc, submission.id desc
    ),
    '[]'::jsonb
  )
  into v_result
  from (
    select suggestion.*
    from public.registry_provider_track_suggestions suggestion
    where suggestion.intake_origin = 'artist_submission'
      and suggestion.submitted_for_artist_id = p_artist_id
    order by suggestion.created_at desc, suggestion.id desc
    limit v_limit
  ) submission
  left join public.registry_tracks canonical_track
    on canonical_track.id =
      coalesce(
        submission.canonicalized_track_id,
        submission.canonical_track_id
      );

  return v_result;
end;
$$;


ALTER FUNCTION "public"."community_get_artist_music_submissions"("p_artist_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_get_artist_public_presentation"("p_artist_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_result jsonb;
begin
  select jsonb_build_object(
    'artist_id', artist.id,
    'official', exists (
      select 1
      from public.artist_representations representation
      where representation.artist_id = artist.id
        and representation.status = 'active'
    ),
    'presentation', (
      select jsonb_build_object(
        'bio', presentation.bio,
        'profile_image_url', presentation.profile_image_url,
        'hero_image_url', presentation.hero_image_url,
        'website_url', presentation.website_url,
        'public_email', presentation.public_email,
        'social_links', presentation.social_links,
        'updated_at', presentation.updated_at
      )
      from public.artist_profile_presentations presentation
      where presentation.artist_id = artist.id
    )
  )
  into v_result
  from public.registry_artists artist
  where artist.id = p_artist_id
    and artist.status = 'active';

  if v_result is null then
    raise exception 'artist_not_found';
  end if;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."community_get_artist_public_presentation"("p_artist_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_get_artist_representation_state"("p_artist_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_result jsonb;
begin
  if v_actor is null then
    raise exception
      'authentication_required';
  end if;

  select jsonb_build_object(
    'artist',
      jsonb_build_object(
        'id',
          artist.id,
        'slug',
          artist.slug,
        'display_name',
          artist.display_name,
        'status',
          artist.status
      ),
    'latest_claim',
      (
        select jsonb_build_object(
          'id',
            claim.id,
          'claimant_role',
            claim.claimant_role,
          'status',
            claim.status,
          'statement',
            claim.statement,
          'submitted_at',
            claim.submitted_at,
          'decided_at',
            claim.decided_at,
          'decision_reason',
            claim.decision_reason,
          'evidence',
            (
              select coalesce(
                jsonb_agg(
                  jsonb_build_object(
                    'id',
                      evidence.id,
                    'type',
                      evidence.evidence_type,
                    'reference',
                      evidence.reference,
                    'note',
                      evidence.note
                  )
                  order by evidence.created_at
                ),
                '[]'::jsonb
              )
              from public.artist_claim_evidence evidence
              where evidence.claim_id =
                    claim.id
            )
        )
        from public.artist_claim_requests claim
        where claim.artist_id =
              artist.id
          and claim.claimant_user_id =
              v_actor
        order by claim.submitted_at desc
        limit 1
      ),
    'representation',
      (
        select jsonb_build_object(
          'id',
            representation.id,
          'role',
            representation.representation_role,
          'status',
            representation.status,
          'permissions',
            jsonb_build_object(
              'profile',
                representation.can_manage_profile,
              'releases',
                representation.can_submit_releases,
              'updates',
                representation.can_post_updates,
              'team',
                representation.can_manage_team
            ),
          'invited_at',
            representation.invited_at,
          'accepted_at',
            representation.accepted_at,
          'verified_at',
            representation.verified_at
        )
        from public.artist_representations representation
        where representation.artist_id =
              artist.id
          and representation.user_id =
              v_actor
          and representation.status in (
            'pending',
            'active'
          )
        order by representation.created_at desc
        limit 1
      ),
    'can_claim',
      (
        artist.status = 'active'
        and not exists (
          select 1
          from public.artist_representations representation
          where representation.artist_id =
                artist.id
            and representation.user_id =
                v_actor
            and representation.status in (
              'pending',
              'active'
            )
        )
        and not exists (
          select 1
          from public.artist_claim_requests claim
          where claim.artist_id =
                artist.id
            and claim.claimant_user_id =
                v_actor
            and claim.status =
                'pending'
        )
      )
  )
  into v_result
  from public.registry_artists artist
  where artist.id = p_artist_id;

  if v_result is null then
    raise exception
      'artist_not_found';
  end if;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."community_get_artist_representation_state"("p_artist_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_get_artist_team"("p_artist_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_actor_rep public.artist_representations%rowtype;
  v_result jsonb;
begin
  if v_actor is null then
    raise exception 'authentication_required';
  end if;

  select *
  into v_actor_rep
  from editorial.current_artist_representation(p_artist_id);

  if v_actor_rep.id is null
     or not v_actor_rep.can_manage_team
  then
    raise exception 'insufficient_artist_team_privilege';
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'representation_id', representation.id,
        'user_id', representation.user_id,
        'username', profile.username,
        'display_name', profile.display_name,
        'role', representation.representation_role,
        'status', representation.status,
        'permissions', jsonb_build_object(
          'profile', representation.can_manage_profile,
          'releases', representation.can_submit_releases,
          'updates', representation.can_post_updates,
          'team', representation.can_manage_team
        ),
        'invited_at', representation.invited_at,
        'accepted_at', representation.accepted_at,
        'verified_at', representation.verified_at
      )
      order by
        case representation.status
          when 'active' then 0
          else 1
        end,
        representation.created_at asc
    ),
    '[]'::jsonb
  )
  into v_result
  from public.artist_representations representation
  left join public.user_profiles profile
    on profile.user_id = representation.user_id
  where representation.artist_id = p_artist_id
    and representation.status in ('pending', 'active');

  return v_result;
end;
$$;


ALTER FUNCTION "public"."community_get_artist_team"("p_artist_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_get_artist_update"("p_update_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_result jsonb;
begin
  select jsonb_build_object(
    'id', artist_update.id,
    'artist_id', artist_update.artist_id,
    'body', artist_update.body,
    'image_url', artist_update.image_url,
    'link_url', artist_update.link_url,
    'link_label', artist_update.link_label,
    'status', artist_update.status,
    'published_at', artist_update.published_at,
    'updated_at', artist_update.updated_at,
    'canonical_path',
      '/artists/' || artist.slug || '/updates/' || artist_update.id::text,
    'artist', jsonb_build_object(
      'id', artist.id,
      'slug', artist.slug,
      'display_name', artist.display_name,
      'image_url', coalesce(
        presentation.profile_image_url,
        artist.public_image_url
      )
    )
  )
  into v_result
  from public.artist_updates artist_update
  join public.registry_artists artist
    on artist.id = artist_update.artist_id
  left join public.artist_profile_presentations presentation
    on presentation.artist_id = artist.id
  where artist_update.id = p_update_id
    and artist_update.status = 'published'
    and artist.status = 'active';

  if v_result is null then
    raise exception 'artist_update_not_found';
  end if;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."community_get_artist_update"("p_update_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_get_comment_replies"("p_parent_id" "uuid", "p_limit" integer DEFAULT 3) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  result jsonb;
BEGIN
  SELECT jsonb_agg(
    jsonb_build_object(
      'id', c.id,
      'thread_id', c.thread_id,
      'parent_id', c.parent_id,
      'root_id', c.root_id,
      'author_id', c.author_id,
      'body_markdown', c.body_markdown,
      'body_plain', c.body_plain,
      'body_html', c.body_html,
      'depth', c.depth,
      'path', c.path,
      'status', c.status,
      'is_pinned', c.is_pinned,
      'is_editor_pick', c.is_editor_pick,
      'upvote_count', c.upvote_count,
      'downvote_count', c.downvote_count,
      'reply_count', c.reply_count,
      'reaction_count', c.reaction_count,
      'report_count', c.report_count,
      'score', c.score,
      'created_at', c.created_at,
      'updated_at', c.updated_at,
      'edited_at', c.edited_at,
      'deleted_at', c.deleted_at
    ) ORDER BY c.created_at ASC
  ) INTO result
  FROM community_comments c
  WHERE c.parent_id = p_parent_id AND c.status = 'visible'
  LIMIT p_limit;

  RETURN COALESCE(result, '[]'::jsonb);
END;
$$;


ALTER FUNCTION "public"."community_get_comment_replies"("p_parent_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_get_context_anchor_comments"("p_thread_id" "uuid", "p_anchor_type" "text", "p_context_entity_type" "text" DEFAULT NULL::"text", "p_context_entity_id" "text" DEFAULT NULL::"text", "p_context_entity_slug" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 30) RETURNS TABLE("id" "uuid", "thread_id" "uuid", "parent_id" "uuid", "root_id" "uuid", "author_id" "uuid", "body_markdown" "text", "body_plain" "text", "body_html" "text", "depth" integer, "path" "text", "status" "text", "is_pinned" boolean, "is_editor_pick" boolean, "upvote_count" integer, "downvote_count" integer, "reply_count" integer, "reaction_count" integer, "report_count" integer, "score" integer, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "edited_at" timestamp with time zone, "deleted_at" timestamp with time zone, "anchor_type" "text", "anchor_time_ms" integer, "anchor_end_time_ms" integer, "anchor_label" "text", "context_entity_type" "text", "context_entity_id" "text", "context_entity_slug" "text", "context_label" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    c.id,
    c.thread_id,
    c.parent_id,
    c.root_id,
    c.author_id,
    c.body_markdown,
    c.body_plain,
    c.body_html,
    coalesce(c.depth, 0)::integer,
    c.path::text,
    c.status::text,
    coalesce(c.is_pinned, false),
    coalesce(c.is_editor_pick, false),
    coalesce(c.upvote_count, 0)::integer,
    coalesce(c.downvote_count, 0)::integer,
    coalesce(c.reply_count, 0)::integer,
    coalesce(c.reaction_count, 0)::integer,
    coalesce(c.report_count, 0)::integer,
    coalesce(c.score, 0)::integer,
    c.created_at,
    c.updated_at,
    c.edited_at,
    c.deleted_at,
    c.anchor_type,
    c.anchor_time_ms,
    c.anchor_end_time_ms,
    c.anchor_label,
    c.context_entity_type,
    c.context_entity_id,
    c.context_entity_slug,
    c.context_label
  from public.community_comments c
  where c.thread_id = p_thread_id
    and c.parent_id is null
    and c.anchor_type = p_anchor_type
    and c.deleted_at is null
    and c.status::text not in ('deleted', 'removed', 'spam')
    and (p_context_entity_type is null or c.context_entity_type = p_context_entity_type)
    and (
      p_context_entity_id is null
      or c.context_entity_id = p_context_entity_id
    )
    and (
      p_context_entity_slug is null
      or c.context_entity_slug = p_context_entity_slug
    )
  order by
    coalesce(c.score, 0) desc,
    coalesce(c.reaction_count, 0) desc,
    c.created_at desc
  limit least(greatest(coalesce(p_limit, 30), 1), 100);
$$;


ALTER FUNCTION "public"."community_get_context_anchor_comments"("p_thread_id" "uuid", "p_anchor_type" "text", "p_context_entity_type" "text", "p_context_entity_id" "text", "p_context_entity_slug" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_get_context_anchor_summary"("p_thread_id" "uuid", "p_anchor_type" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 8) RETURNS TABLE("anchor_type" "text", "context_entity_type" "text", "context_entity_id" "text", "context_entity_slug" "text", "context_label" "text", "anchor_label" "text", "comment_count" integer, "reaction_count" integer, "score" integer, "latest_comment_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    c.anchor_type,
    c.context_entity_type,
    c.context_entity_id,
    c.context_entity_slug,
    coalesce(
      c.context_label,
      c.anchor_label,
      c.context_entity_slug,
      c.context_entity_id
    ) as context_label,
    coalesce(
      c.anchor_label,
      c.context_label,
      c.context_entity_slug,
      c.context_entity_id
    ) as anchor_label,
    count(*)::integer as comment_count,
    coalesce(sum(c.reaction_count), 0)::integer as reaction_count,
    coalesce(sum(c.score), 0)::integer as score,
    max(c.created_at) as latest_comment_at
  from public.community_comments c
  where c.thread_id = p_thread_id
    and c.parent_id is null
    and c.anchor_type in (
      'release_track',
      'chart_entry',
      'playlist_track'
    )
    and (
      p_anchor_type is null
      or c.anchor_type = p_anchor_type
    )
    and c.deleted_at is null
    and c.status::text not in (
      'deleted',
      'removed',
      'spam'
    )
  group by
    c.anchor_type,
    c.context_entity_type,
    c.context_entity_id,
    c.context_entity_slug,
    coalesce(
      c.context_label,
      c.anchor_label,
      c.context_entity_slug,
      c.context_entity_id
    ),
    coalesce(
      c.anchor_label,
      c.context_label,
      c.context_entity_slug,
      c.context_entity_id
    )
  order by
    count(*) desc,
    coalesce(sum(c.reaction_count), 0) desc,
    coalesce(sum(c.score), 0) desc,
    max(c.created_at) desc
  limit least(
    greatest(
      coalesce(p_limit, 8),
      1
    ),
    40
  );
$$;


ALTER FUNCTION "public"."community_get_context_anchor_summary"("p_thread_id" "uuid", "p_anchor_type" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_get_digest"("p_limit" integer DEFAULT 20) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  result jsonb;
BEGIN
  SELECT jsonb_agg(
    jsonb_build_object(
      'id', a.id,
      'user_id', a.user_id,
      'activity_type', a.activity_type,
      'entity_type', a.entity_type,
      'entity_id', a.entity_id,
      'entity_slug', a.entity_slug,
      'entity_url', (a.metadata->>'entity_url'),
      'entity_title', (a.metadata->>'entity_title'),
      'comment_id', a.comment_id,
      'metadata', a.metadata,
      'visibility', a.visibility,
      'created_at', a.created_at
    ) ORDER BY a.created_at DESC
  ) INTO result
  FROM community_activity a
  WHERE a.visibility = 'public'
  ORDER BY a.created_at DESC
  LIMIT p_limit;

  RETURN COALESCE(result, '[]'::jsonb);
END;
$$;


ALTER FUNCTION "public"."community_get_digest"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_get_entity_contributions"("p_entity_type" "text", "p_entity_slug" "text" DEFAULT NULL::"text", "p_entity_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  result jsonb;
BEGIN
  SELECT jsonb_agg(
    jsonb_build_object(
      'id', c.id,
      'user_id', c.user_id,
      'source_comment_id', c.source_comment_id,
      'entity_type', c.entity_type,
      'entity_id', c.entity_id,
      'entity_slug', c.entity_slug,
      'contribution_type', c.contribution_type,
      'payload', c.payload,
      'status', c.status,
      'reviewed_by', c.reviewed_by,
      'reviewed_at', c.reviewed_at,
      'created_at', c.created_at,
      'updated_at', c.updated_at,
      'contributor_name', COALESCE(prof.display_name, prof.username, 'Contributor'),
      'contributor_username', prof.username
    ) ORDER BY c.created_at DESC
  ) INTO result
  FROM community_contributions c
  LEFT JOIN community_profiles prof ON prof.user_id = c.user_id
  WHERE c.entity_type = p_entity_type
    AND c.status IN ('approved', 'merged')
    AND (p_entity_slug IS NULL OR c.entity_slug = p_entity_slug)
    AND (p_entity_id IS NULL OR c.entity_id = p_entity_id);

  RETURN COALESCE(result, '[]'::jsonb);
END;
$$;


ALTER FUNCTION "public"."community_get_entity_contributions"("p_entity_type" "text", "p_entity_slug" "text", "p_entity_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_get_follow_suggestions"("p_people_limit" integer DEFAULT 4, "p_artist_limit" integer DEFAULT 12) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_user_id uuid :=
    auth.uid();

  v_people_limit integer :=
    least(
      greatest(
        coalesce(
          p_people_limit,
          4
        ),
        0
      ),
      12
    );

  v_artist_limit integer :=
    least(
      greatest(
        coalesce(
          p_artist_limit,
          12
        ),
        0
      ),
      24
    );

  v_recent_cutoff timestamp with time zone :=
    now() - interval '180 days';

  v_release_cutoff date :=
    current_date - 180;

  v_people jsonb;
  v_artists jsonb;
begin
  with existing_follows as (
    select
      follow.target_type,
      follow.target_id
    from public.community_follows
      follow
    where v_user_id is not null
      and follow.user_id =
          v_user_id
      and follow.target_type in (
        'person',
        'artist'
      )
  ),

  self_people as (
    select distinct
      link.person_resource_id
    from editorial.person_identity_links
      link
    join editorial.people
      person
      on person.resource_id =
         link.person_resource_id
     and person.person_state =
         'active'
    where v_user_id is not null
      and link.user_id =
          v_user_id
      and link.link_state =
          'active'
  ),

  person_base as (
    select
      person.resource_id
        as target_id,
      alias.path
        as canonical_path,
      editorial.resolve_person_presentation(
        person.resource_id
      ) as presentation
    from editorial.people
      person
    join editorial.resources
      resource
      on resource.id =
         person.resource_id
     and resource.resource_kind =
         'person'
     and resource.visibility =
         'public'
     and resource.lifecycle_state =
         'active'
    join editorial.resource_aliases
      alias
      on alias.resource_id =
         person.resource_id
     and alias.is_canonical
     and alias.retired_at is null
    where person.person_state =
          'active'
      and alias.path like
          '/people/%'
      and not exists (
        select 1
        from self_people
          self_person
        where self_person.person_resource_id =
              person.resource_id
      )
      and not exists (
        select 1
        from existing_follows
          existing
        where existing.target_type =
              'person'
          and existing.target_id =
              person.resource_id::text
      )
  ),

  person_candidates as (
    select
      base.target_id,
      split_part(
        base.canonical_path,
        '/',
        3
      ) as target_slug,
      base.canonical_path,
      base.presentation
        ->> 'display_name'
        as display_name,
      nullif(
        btrim(
          coalesce(
            base.presentation
              ->> 'avatar_url',
            ''
          )
        ),
        ''
      ) as image_url,
      work_stats.work_count,
      work_stats.recent_item_count,
      work_stats.latest_item_at,
      work_stats.latest_item_kind,
      work_stats.latest_item_title
    from person_base
      base
    cross join lateral (
      select
        count(*)
          as work_count,
        count(*) filter (
          where work.published_at >=
                v_recent_cutoff
        ) as recent_item_count,
        max(
          work.published_at
        ) as latest_item_at,
        (
          array_agg(
            work.resource_kind
            order by
              work.published_at desc,
              work.resource_id desc
          )
        )[1] as latest_item_kind,
        (
          array_agg(
            work.title
            order by
              work.published_at desc,
              work.resource_id desc
          )
        )[1] as latest_item_title
      from editorial.list_current_public_person_work(
        base.target_id
      ) work
    ) work_stats
    where base.presentation is not null
      and nullif(
            btrim(
              coalesce(
                base.presentation
                  ->> 'display_name',
                ''
              )
            ),
            ''
          ) is not null
      and work_stats.work_count >
          0
  ),

  person_page as (
    select
      candidate.*
    from person_candidates
      candidate
    order by
      candidate.recent_item_count desc,
      candidate.latest_item_at desc nulls last,
      candidate.display_name,
      candidate.target_id
    limit v_people_limit
  )

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'target_type',
            'person',
          'target_id',
            page.target_id,
          'target_slug',
            page.target_slug,
          'canonical_path',
            page.canonical_path,
          'display_name',
            page.display_name,
          'image_url',
            page.image_url,
          'work_count',
            page.work_count,
          'recent_item_count',
            page.recent_item_count,
          'latest_item_at',
            page.latest_item_at,
          'latest_item_kind',
            page.latest_item_kind,
          'latest_item_title',
            page.latest_item_title
        )
        order by
          page.recent_item_count desc,
          page.latest_item_at desc nulls last,
          page.display_name,
          page.target_id
      ),
      '[]'::jsonb
    )
  into v_people
  from person_page
    page;


  with existing_follows as (
    select
      follow.target_type,
      follow.target_id
    from public.community_follows
      follow
    where v_user_id is not null
      and follow.user_id =
          v_user_id
      and follow.target_type =
          'artist'
  ),

  artist_candidates_unranked as (
    select
      artist.id
        as target_id,
      artist.slug
        as target_slug,
      '/artists/'
        || artist.slug
        as canonical_path,
      artist.display_name,
      artist.public_image_url
        as image_url,
      release_stats.release_count,
      release_stats.recent_release_count,
      release_stats.latest_release_id,
      release_stats.latest_release_date,
      release_stats.latest_release_title,
      latest_credit.latest_credit_order
    from public.registry_artists
      artist
    cross join lateral (
      select
        count(*)
          as release_count,
        count(*) filter (
          where release_row.release_date >=
                v_release_cutoff
        ) as recent_release_count,
        (
          array_agg(
            release_row.id
            order by
              release_row.release_date desc,
              release_row.id desc
          )
        )[1] as latest_release_id,
        max(
          release_row.release_date
        ) as latest_release_date,
        (
          array_agg(
            release_row.title
            order by
              release_row.release_date desc,
              release_row.id desc
          )
        )[1] as latest_release_title
      from public.registry_releases
        release_row
      where release_row.status =
            'active'
        and release_row.release_date
            is not null
        and release_row.release_date <=
            current_date
        and nullif(
              btrim(
                coalesce(
                  release_row.slug,
                  ''
                )
              ),
              ''
            ) is not null
        and exists (
          select 1
          from public.registry_release_artists
            release_artist
          where release_artist.release_id =
                release_row.id
            and release_artist.artist_id =
                artist.id
            and release_artist.status =
                'active'
            and release_artist.is_primary
        )
    ) release_stats
    cross join lateral (
      select
        min(
          release_artist.credit_order
        ) as latest_credit_order
      from public.registry_release_artists
        release_artist
      where release_artist.release_id =
            release_stats.latest_release_id
        and release_artist.artist_id =
            artist.id
        and release_artist.status =
            'active'
        and release_artist.is_primary
    ) latest_credit
    where artist.status =
          'active'
      and nullif(
            btrim(
              coalesce(
                artist.slug,
                ''
              )
            ),
            ''
          ) is not null
      and nullif(
            btrim(
              coalesce(
                artist.display_name,
                ''
              )
            ),
            ''
          ) is not null
      and nullif(
            btrim(
              coalesce(
                artist.public_image_url,
                ''
              )
            ),
            ''
          ) is not null
      and release_stats.recent_release_count >
          0
      and release_stats.latest_release_id
          is not null
      and not exists (
        select 1
        from existing_follows
          existing
        where existing.target_type =
              'artist'
          and existing.target_id =
              artist.id::text
      )
  ),

  artist_candidates as (
    select
      candidate.*,
      row_number() over (
        partition by
          candidate.latest_release_id
        order by
          candidate.latest_credit_order
            asc nulls last,
          candidate.recent_release_count
            desc,
          candidate.release_count
            desc,
          candidate.display_name,
          candidate.target_id
      ) as latest_release_suggestion_rank
    from artist_candidates_unranked
      candidate
  ),

  artist_page as (
    select
      candidate.*
    from artist_candidates
      candidate
    where candidate.latest_release_suggestion_rank =
          1
    order by
      candidate.latest_release_date desc,
      candidate.recent_release_count desc,
      candidate.release_count desc,
      candidate.display_name,
      candidate.target_id
    limit v_artist_limit
  )

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'target_type',
            'artist',
          'target_id',
            page.target_id,
          'target_slug',
            page.target_slug,
          'canonical_path',
            page.canonical_path,
          'display_name',
            page.display_name,
          'image_url',
            page.image_url,
          'release_count',
            page.release_count,
          'recent_release_count',
            page.recent_release_count,
          'latest_release_date',
            page.latest_release_date,
          'latest_release_title',
            page.latest_release_title
        )
        order by
          page.latest_release_date desc,
          page.recent_release_count desc,
          page.release_count desc,
          page.display_name,
          page.target_id
      ),
      '[]'::jsonb
    )
  into v_artists
  from artist_page
    page;


  return jsonb_build_object(
    'mode',
      'starter_circle',
    'subject_types',
      jsonb_build_array(
        'person',
        'artist'
      ),
    'recent_window_days',
      180,
    'people',
      v_people,
    'artists',
      v_artists
  );
end;
$$;


ALTER FUNCTION "public"."community_get_follow_suggestions"("p_people_limit" integer, "p_artist_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_get_following_feed"("p_limit" integer DEFAULT 30, "p_before_published_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_before_item_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_limit integer :=
    least(
      greatest(
        coalesce(p_limit, 30),
        1
      ),
      50
    );
  v_recent_cutoff timestamptz :=
    now() - interval '180 days';
  v_items jsonb;
begin
  if v_user_id is null then
    raise exception 'authentication required';
  end if;

  with self_follows as (
    select
      follow.target_type,
      follow.target_id,
      follow.target_slug,
      follow.created_at as followed_at
    from public.community_follows follow
    where follow.user_id = v_user_id
      and follow.target_type in (
        'person',
        'artist'
      )
  ),
  person_candidates as (
    select
      work.resource_kind as item_type,
      work.resource_id::text as item_id,
      work.resource_kind || ':' || work.resource_id::text as item_key,
      work.canonical_path,
      work.title,
      work.summary,
      work.image_url,
      work.published_at,
      follow.target_type as reason_target_type,
      follow.target_id as reason_target_id,
      follow.target_slug as reason_target_slug,
      follow.followed_at
    from (
      select *
      from self_follows
      where target_type = 'person'
    ) follow
    cross join lateral (
      with work as (
        select current_work.*
        from editorial.list_current_public_person_work(
          follow.target_id::uuid
        ) current_work
      ),
      ranked as (
        select
          work.*,
          row_number() over (
            order by
              work.published_at desc,
              work.resource_id desc
          ) as output_rank,
          count(*) filter (
            where work.published_at >= v_recent_cutoff
          ) over () as recent_count
        from work
      )
      select ranked.*
      from ranked
      where (
        ranked.published_at >= v_recent_cutoff
        and ranked.output_rank <= 3
      )
      or (
        ranked.recent_count = 0
        and ranked.output_rank = 1
      )
    ) work
  ),
  artist_raw_outputs as (
    select
      'release'::text as item_type,
      release.id::text as item_id,
      'release:' || release.id::text as item_key,
      '/releases/' || artist.slug || '/' || release.slug
        as canonical_path,
      release.title,
      release.description as summary,
      release.artwork_url as image_url,
      (
        release.release_date::timestamp
        at time zone 'UTC'
      ) as published_at,
      follow.target_type as reason_target_type,
      follow.target_id as reason_target_id,
      artist.slug as reason_target_slug,
      follow.followed_at
    from (
      select *
      from self_follows
      where target_type = 'artist'
    ) follow
    join public.registry_artists artist
      on artist.id::text = follow.target_id
     and artist.status = 'active'
    join public.registry_releases release
      on release.status = 'active'
     and release.release_date is not null
     and release.release_date <= current_date
     and nullif(
           btrim(
             coalesce(
               release.slug,
               ''
             )
           ),
           ''
         ) is not null
     and exists (
       select 1
       from public.registry_release_artists release_artist
       where release_artist.release_id = release.id
         and release_artist.artist_id = artist.id
         and release_artist.status = 'active'
         and release_artist.is_primary
     )

    union all

    select
      'artist_update'::text as item_type,
      artist_update.id::text as item_id,
      'artist_update:' || artist_update.id::text as item_key,
      '/artists/' || artist.slug || '/updates/' || artist_update.id::text
        as canonical_path,
      'Update from ' || artist.display_name as title,
      artist_update.body as summary,
      artist_update.image_url,
      artist_update.published_at,
      follow.target_type as reason_target_type,
      follow.target_id as reason_target_id,
      artist.slug as reason_target_slug,
      follow.followed_at
    from (
      select *
      from self_follows
      where target_type = 'artist'
    ) follow
    join public.registry_artists artist
      on artist.id::text = follow.target_id
     and artist.status = 'active'
    join public.artist_updates artist_update
      on artist_update.artist_id = artist.id
     and artist_update.status = 'published'
  ),
  artist_ranked as (
    select
      candidate.*,
      row_number() over (
        partition by candidate.reason_target_id
        order by
          candidate.published_at desc,
          candidate.item_key desc
      ) as output_rank,
      count(*) filter (
        where candidate.published_at >= v_recent_cutoff
      ) over (
        partition by candidate.reason_target_id
      ) as recent_count
    from artist_raw_outputs candidate
  ),
  artist_candidates as (
    select ranked.*
    from artist_ranked ranked
    where (
      ranked.published_at >= v_recent_cutoff
      and ranked.output_rank <= 3
    )
    or (
      ranked.recent_count = 0
      and ranked.output_rank = 1
    )
  ),
  candidate_rows as (
    select
      item_type,
      item_id,
      item_key,
      canonical_path,
      title,
      summary,
      image_url,
      published_at,
      reason_target_type,
      reason_target_id,
      reason_target_slug,
      followed_at
    from person_candidates

    union all

    select
      item_type,
      item_id,
      item_key,
      canonical_path,
      title,
      summary,
      image_url,
      published_at,
      reason_target_type,
      reason_target_id,
      reason_target_slug,
      followed_at
    from artist_candidates
  ),
  distinct_reason_rows as (
    select distinct
      candidate.item_type,
      candidate.item_id,
      candidate.item_key,
      candidate.canonical_path,
      candidate.title,
      candidate.summary,
      candidate.image_url,
      candidate.published_at,
      candidate.reason_target_type,
      candidate.reason_target_id,
      candidate.reason_target_slug,
      candidate.followed_at
    from candidate_rows candidate
    where candidate.published_at is not null
      and nullif(
            btrim(
              coalesce(
                candidate.canonical_path,
                ''
              )
            ),
            ''
          ) is not null
      and nullif(
            btrim(
              coalesce(
                candidate.title,
                ''
              )
            ),
            ''
          ) is not null
  ),
  grouped_items as (
    select
      candidate.item_type,
      candidate.item_id,
      candidate.item_key,
      min(candidate.canonical_path) as canonical_path,
      candidate.title,
      candidate.summary,
      candidate.image_url,
      candidate.published_at,
      jsonb_agg(
        jsonb_build_object(
          'target_type', candidate.reason_target_type,
          'target_id', candidate.reason_target_id,
          'target_slug', candidate.reason_target_slug,
          'followed_at', candidate.followed_at
        )
        order by
          candidate.reason_target_type,
          candidate.reason_target_slug,
          candidate.reason_target_id
      ) as matched_follows
    from distinct_reason_rows candidate
    group by
      candidate.item_type,
      candidate.item_id,
      candidate.item_key,
      candidate.title,
      candidate.summary,
      candidate.image_url,
      candidate.published_at
  ),
  page as (
    select item.*
    from grouped_items item
    where p_before_published_at is null
       or item.published_at < p_before_published_at
       or (
         p_before_item_key is not null
         and item.published_at = p_before_published_at
         and item.item_key < p_before_item_key
       )
    order by
      item.published_at desc,
      item.item_key desc
    limit v_limit
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'item_type', page.item_type,
        'item_id', page.item_id,
        'item_key', page.item_key,
        'canonical_path', page.canonical_path,
        'title', page.title,
        'summary', page.summary,
        'image_url', page.image_url,
        'published_at', page.published_at,
        'matched_follows', page.matched_follows
      )
      order by
        page.published_at desc,
        page.item_key desc
    ),
    '[]'::jsonb
  )
  into v_items
  from page;

  return jsonb_build_object(
    'mode', 'current_interest',
    'subject_types', jsonb_build_array(
      'person',
      'artist'
    ),
    'recent_window_days', 180,
    'per_subject_recent_limit', 3,
    'items', v_items
  );
end;
$$;


ALTER FUNCTION "public"."community_get_following_feed"("p_limit" integer, "p_before_published_at" timestamp with time zone, "p_before_item_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_get_most_discussed"("p_limit" integer DEFAULT 6) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  result jsonb;
BEGIN
  SELECT jsonb_agg(
    jsonb_build_object(
      'id', t.id,
      'entity_type', t.entity_type,
      'entity_id', t.entity_id,
      'entity_slug', t.entity_slug,
      'entity_url', t.entity_url,
      'title', t.title,
      'status', t.status,
      'comment_count', t.comment_count,
      'root_comment_count', t.root_comment_count,
      'last_comment_at', t.last_comment_at,
      'created_at', t.created_at,
      'updated_at', t.updated_at
    ) ORDER BY t.comment_count DESC
  ) INTO result
  FROM community_threads t
  WHERE t.status = 'open'
  ORDER BY t.comment_count DESC
  LIMIT p_limit;

  RETURN COALESCE(result, '[]'::jsonb);
END;
$$;


ALTER FUNCTION "public"."community_get_most_discussed"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_get_notification_by_id"("p_notification_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'id', n.id,
    'user_id', n.user_id,
    'actor_id', n.actor_id,
    'notification_type', n.notification_type,
    'entity_type', n.entity_type,
    'entity_id', n.entity_id,
    'entity_slug', n.entity_slug,
    'comment_id', n.comment_id,
    'metadata', n.metadata,
    'read_at', n.read_at,
    'created_at', n.created_at
  ) INTO result
  FROM community_notifications n
  WHERE n.id = p_notification_id AND n.user_id = auth.uid();

  RETURN result;
END;
$$;


ALTER FUNCTION "public"."community_get_notification_by_id"("p_notification_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_get_notification_prefs"("p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_prefs public.community_notification_preferences%rowtype;
begin
  if current_user <> 'service_role'
     and (auth.uid() is null or auth.uid() <> p_user_id)
  then
    raise exception 'Permission denied' using errcode = '42501';
  end if;

  perform public.community_ensure_user_account(p_user_id);

  insert into public.community_notification_preferences (
    user_id, email_digest, chart_alerts, artist_drops,
    reply_notifications, mention_notifications, follow_notifications,
    contribution_notifications, marketing_emails, created_at, updated_at
  ) values (
    p_user_id, true, true, true, true, true, false, false, false, now(), now()
  )
  on conflict (user_id) do nothing;

  select * into v_prefs
  from public.community_notification_preferences
  where user_id = p_user_id;

  return jsonb_build_object(
    'user_id', v_prefs.user_id,
    'email_digest', coalesce(v_prefs.email_digest, true),
    'chart_alerts', coalesce(v_prefs.chart_alerts, true),
    'artist_drops', coalesce(v_prefs.artist_drops, true),
    'reply_notifications', coalesce(v_prefs.reply_notifications, true),
    'mention_notifications', coalesce(v_prefs.mention_notifications, true),
    'follow_notifications', coalesce(v_prefs.follow_notifications, false),
    'contribution_notifications', coalesce(v_prefs.contribution_notifications, false),
    'marketing_emails', coalesce(v_prefs.marketing_emails, false),
    'created_at', v_prefs.created_at,
    'updated_at', v_prefs.updated_at
  );
end;
$$;


ALTER FUNCTION "public"."community_get_notification_prefs"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_get_or_create_thread"("p_entity_type" "text", "p_entity_id" "text" DEFAULT NULL::"text", "p_entity_slug" "text" DEFAULT NULL::"text", "p_entity_url" "text" DEFAULT NULL::"text", "p_title" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_thread public.community_threads%rowtype;
  v_created boolean := false;
  v_entity_type text := nullif(trim(coalesce(p_entity_type, '')), '');
  v_entity_id text := nullif(trim(coalesce(p_entity_id, '')), '');
  v_entity_slug text := nullif(trim(coalesce(p_entity_slug, '')), '');
  v_entity_url text := nullif(trim(coalesce(p_entity_url, '')), '');
  v_title text := nullif(trim(coalesce(p_title, '')), '');
  v_lock_key text;
begin
  if current_user <> 'service_role' and auth.uid() is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;

  if v_entity_type is null then
    raise exception 'Entity type is required' using errcode = '22023';
  end if;

  if v_entity_id is null and v_entity_slug is null and v_entity_url is null then
    raise exception 'Entity id, slug, or URL is required' using errcode = '22023';
  end if;

  v_lock_key := lower(v_entity_type)
    || ':' || coalesce(v_entity_id, '')
    || ':' || coalesce(v_entity_slug, '')
    || ':' || coalesce(v_entity_url, '');

  perform pg_advisory_xact_lock(hashtextextended(v_lock_key, 20260624));

  select * into v_thread
  from public.community_threads
  where entity_type::text = v_entity_type
    and (
      (v_entity_id is not null and entity_id::text = v_entity_id)
      or (v_entity_slug is not null and entity_slug = v_entity_slug)
      or (v_entity_url is not null and entity_url = v_entity_url)
    )
  order by created_at asc
  limit 1;

  if not found then
    begin
      insert into public.community_threads (
        entity_type, entity_id, entity_slug, entity_url, title, status
      ) values (
        v_entity_type,
        v_entity_id,
        v_entity_slug,
        v_entity_url,
        coalesce(v_title, v_entity_slug, v_entity_id, v_entity_type),
        'open'
      )
      returning * into v_thread;
      v_created := true;
    exception
      when unique_violation then
        select * into v_thread
        from public.community_threads
        where entity_type::text = v_entity_type
          and (
            (v_entity_id is not null and entity_id::text = v_entity_id)
            or (v_entity_slug is not null and entity_slug = v_entity_slug)
            or (v_entity_url is not null and entity_url = v_entity_url)
          )
        order by created_at asc
        limit 1;
        v_created := false;
    end;
  end if;

  if v_thread.id is null then
    raise exception 'Could not resolve community thread' using errcode = 'P0002';
  end if;

  return jsonb_build_object('thread', to_jsonb(v_thread), 'created', v_created);
end;
$$;


ALTER FUNCTION "public"."community_get_or_create_thread"("p_entity_type" "text", "p_entity_id" "text", "p_entity_slug" "text", "p_entity_url" "text", "p_title" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_get_person_follow_state"("p_person_resource_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_user_id uuid :=
    auth.uid();
  v_person record;
  v_followed boolean;
begin
  if v_user_id is null then
    raise exception
      'Not authenticated'
      using errcode = '42501';
  end if;

  select *
  into v_person
  from editorial.resolve_person_follow_target(
    p_person_resource_id
  );

  if not v_person.followable then
    raise exception
      'Person is not publicly followable'
      using errcode = '22023';
  end if;

  select exists (
    select 1
    from public.community_follows follow
    where follow.user_id =
          v_user_id
      and follow.target_type =
          'person'
      and follow.target_id =
          v_person.person_resource_id::text
  )
  into v_followed;

  return jsonb_build_object(
    'person_id',
      v_person.person_resource_id,
    'followed',
      v_followed
  );
end;
$$;


ALTER FUNCTION "public"."community_get_person_follow_state"("p_person_resource_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_get_profile_by_username"("p_username" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_username text;
  v_profile public.user_profiles%rowtype;
begin
  v_username := public.community_normalize_username(p_username);

  if v_username is null or not public.community_username_is_valid(v_username) then
    return null;
  end if;

  select * into v_profile
  from public.user_profiles
  where username_normalized = v_username;

  if not found then
    return null;
  end if;

  if coalesce(v_profile.is_public, true) = false
    and (
      auth.uid() is null
      or (v_profile.user_id <> auth.uid() and not public.current_user_is_administrator())
    ) then
    return null;
  end if;

  return public.community_profile_json(v_profile);
end;
$$;


ALTER FUNCTION "public"."community_get_profile_by_username"("p_username" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_get_profiles_batch"("p_user_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select coalesce(jsonb_object_agg(up.user_id::text, public.community_profile_json(up)), '{}'::jsonb)
  from public.user_profiles up
  where up.user_id = any(coalesce(p_user_ids, array[]::uuid[]))
    and (
      coalesce(up.is_public, true) = true
      or up.user_id = auth.uid()
      or public.current_user_is_administrator()
    );
$$;


ALTER FUNCTION "public"."community_get_profiles_batch"("p_user_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_get_reaction_state_for_public_targets"("p_targets" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_targets jsonb := coalesce(p_targets, '[]'::jsonb);
  v_target_count integer;
  v_target jsonb;
  v_target_type text;
  v_target_id_text text;
  v_target_id uuid;
begin
  if v_user_id is null then
    raise exception
      'Not authenticated'
      using errcode = '42501';
  end if;

  if jsonb_typeof(v_targets) <> 'array' then
    raise exception
      'Reaction targets must be a JSON array'
      using errcode = '22023';
  end if;

  v_target_count := jsonb_array_length(v_targets);

  if v_target_count > 100 then
    raise exception
      'Too many reaction targets'
      using errcode = '22023';
  end if;

  for v_target in
    select value
    from jsonb_array_elements(v_targets)
  loop
    if jsonb_typeof(v_target) <> 'object' then
      raise exception
        'Each reaction target must be an object'
        using errcode = '22023';
    end if;

    v_target_type :=
      lower(
        btrim(
          coalesce(
            v_target ->> 'target_type',
            ''
          )
        )
      );

    v_target_id_text :=
      btrim(
        coalesce(
          v_target ->> 'target_id',
          ''
        )
      );

    if v_target_type not in (
      'article',
      'playlist',
      'release',
      'artist_update'
    ) then
      raise exception
        'Unsupported public reaction target type'
        using errcode = '22023';
    end if;

    if v_target_id_text = '' then
      raise exception
        'Reaction target id is required'
        using errcode = '22023';
    end if;

    begin
      v_target_id := v_target_id_text::uuid;
    exception
      when invalid_text_representation then
        raise exception
          'Reaction target id must be a UUID'
          using errcode = '22023';
    end;

    if v_target_type = 'article' then
      perform 1
      from editorial.resources resource
      where resource.id = v_target_id
        and resource.resource_kind = 'article'
        and resource.visibility = 'public'
        and resource.lifecycle_state = 'published'
        and resource.current_published_version_id is not null;

    elsif v_target_type = 'playlist' then
      perform 1
      from editorial.resources resource
      join editorial.playlist_resources playlist_resource
        on playlist_resource.resource_id = resource.id
      where resource.id = v_target_id
        and resource.resource_kind = 'playlist'
        and resource.visibility = 'public'
        and resource.lifecycle_state = 'published'
        and playlist_resource.current_published_version_id is not null;

    elsif v_target_type = 'release' then
      perform 1
      from public.registry_releases release
      where release.id = v_target_id
        and release.status = 'active'
        and release.release_date is not null
        and release.release_date <= current_date
        and nullif(
          btrim(
            coalesce(
              release.slug,
              ''
            )
          ),
          ''
        ) is not null;

    elsif v_target_type = 'artist_update' then
      perform 1
      from public.artist_updates artist_update
      join public.registry_artists artist
        on artist.id = artist_update.artist_id
      where artist_update.id = v_target_id
        and artist_update.status = 'published'
        and artist.status = 'active';
    end if;

    if not found then
      raise exception
        'Reaction target is not currently public'
        using errcode = '22023';
    end if;
  end loop;

  return (
    with requested_raw as (
      select
        lower(
          btrim(
            target.value ->> 'target_type'
          )
        ) as target_type,
        (
          btrim(
            target.value ->> 'target_id'
          )
        )::uuid as target_id,
        target.ordinality
      from jsonb_array_elements(v_targets)
      with ordinality
        as target(
          value,
          ordinality
        )
    ),
    requested as (
      select
        requested_raw.target_type,
        requested_raw.target_id,
        min(requested_raw.ordinality) as ordinality
      from requested_raw
      group by
        requested_raw.target_type,
        requested_raw.target_id
    ),
    reaction_rows as (
      select
        requested.target_type,
        requested.target_id,
        reaction.reaction_type,
        count(reaction.id)::integer as reaction_count,
        bool_or(
          reaction.user_id = v_user_id
        ) as viewer_reacted
      from requested
      join public.community_reactions reaction
        on reaction.target_type = requested.target_type
       and reaction.target_id = requested.target_id
      group by
        requested.target_type,
        requested.target_id,
        reaction.reaction_type
    ),
    target_state as (
      select
        requested.target_type,
        requested.target_id,
        requested.ordinality,
        coalesce(
          sum(reaction_rows.reaction_count),
          0
        )::integer as reaction_count,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'reaction_type', reaction_rows.reaction_type,
              'count', reaction_rows.reaction_count,
              'viewer_reacted', reaction_rows.viewer_reacted
            )
            order by
              reaction_rows.reaction_count desc,
              reaction_rows.reaction_type
          ) filter (
            where reaction_rows.reaction_type is not null
          ),
          '[]'::jsonb
        ) as reactions
      from requested
      left join reaction_rows
        on reaction_rows.target_type = requested.target_type
       and reaction_rows.target_id = requested.target_id
      group by
        requested.target_type,
        requested.target_id,
        requested.ordinality
    )
    select jsonb_build_object(
      'targets',
      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'target_type', target_state.target_type,
            'target_id', target_state.target_id,
            'reaction_count', target_state.reaction_count,
            'reactions', target_state.reactions
          )
          order by target_state.ordinality
        ),
        '[]'::jsonb
      )
    )
    from target_state
  );
end;
$$;


ALTER FUNCTION "public"."community_get_reaction_state_for_public_targets"("p_targets" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_get_registry_onboarding_artists"("p_limit" integer DEFAULT 16) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  v_limit integer :=
    least(
      greatest(
        coalesce(
          p_limit,
          16
        ),
        1
      ),
      24
    );

  v_fallback_enabled boolean :=
    true;

  v_fallback jsonb :=
    '[]'::jsonb;

  v_artists jsonb :=
    '[]'::jsonb;

  v_editorial_count integer :=
    0;

  v_fallback_used boolean :=
    false;
begin
  select
    config.fallback_enabled
  into
    v_fallback_enabled
  from private.registry_onboarding_config
    config
  where config.config_key =
        'default';

  v_fallback_enabled :=
    coalesce(
      v_fallback_enabled,
      true
    );

  select
    count(*)
  into
    v_editorial_count
  from private.registry_onboarding_editorial_artists
    editorial
  join public.registry_artists
    artist
    on artist.id =
       editorial.artist_id
  where artist.status =
        'active'
    and nullif(
          btrim(
            coalesce(
              artist.slug,
              ''
            )
          ),
          ''
        ) is not null
    and nullif(
          btrim(
            coalesce(
              artist.display_name,
              ''
            )
          ),
          ''
        ) is not null
    and nullif(
          btrim(
            coalesce(
              artist.public_image_url,
              ''
            )
          ),
          ''
        ) is not null;

  if v_fallback_enabled
     and v_editorial_count <
         v_limit
  then
    v_fallback :=
      coalesce(
        public.community_get_follow_suggestions(
          0,
          least(
            24,
            greatest(
              v_limit * 2,
              12
            )
          )
        ) -> 'artists',
        '[]'::jsonb
      );
  end if;

  with editorial_items as (
    select
      jsonb_build_object(
        'target_type',
          'artist',
        'target_id',
          artist.id,
        'target_slug',
          artist.slug,
        'canonical_path',
          '/artists/'
          || artist.slug,
        'display_name',
          artist.display_name,
        'image_url',
          artist.public_image_url,
        'source',
          'editorial'
      ) as item,
      0
        as source_order,
      editorial.display_order
        as item_order
    from private.registry_onboarding_editorial_artists
      editorial
    join public.registry_artists
      artist
      on artist.id =
         editorial.artist_id
    where artist.status =
          'active'
      and nullif(
            btrim(
              coalesce(
                artist.slug,
                ''
              )
            ),
            ''
          ) is not null
      and nullif(
            btrim(
              coalesce(
                artist.display_name,
                ''
              )
            ),
            ''
          ) is not null
      and nullif(
            btrim(
              coalesce(
                artist.public_image_url,
                ''
              )
            ),
            ''
          ) is not null
    order by
      editorial.display_order
    limit v_limit
  ),

  fallback_items as (
    select
      fallback.item
        || jsonb_build_object(
             'source',
             'system_fallback'
           )
        as item,
      1
        as source_order,
      fallback.ordinality::integer
        as item_order
    from jsonb_array_elements(
      v_fallback
    ) with ordinality
      fallback(
        item,
        ordinality
      )
    where not exists (
      select 1
      from private.registry_onboarding_editorial_artists
        editorial
      join public.registry_artists
        artist
        on artist.id =
           editorial.artist_id
       and artist.status =
           'active'
      where artist.id::text =
            fallback.item
              ->> 'target_id'
    )
  ),

  combined as (
    select
      editorial.item,
      editorial.source_order,
      editorial.item_order
    from editorial_items
      editorial

    union all

    select
      fallback.item,
      fallback.source_order,
      fallback.item_order
    from fallback_items
      fallback
  ),

  page as (
    select
      combined.item,
      combined.source_order,
      combined.item_order
    from combined
    order by
      combined.source_order,
      combined.item_order
    limit v_limit
  )

  select
    coalesce(
      jsonb_agg(
        page.item
        order by
          page.source_order,
          page.item_order
      ),
      '[]'::jsonb
    ),
    coalesce(
      bool_or(
        page.source_order = 1
      ),
      false
    )
  into
    v_artists,
    v_fallback_used
  from page;

  return jsonb_build_object(
    'mode',
      'registry_onboarding',
    'artists',
      v_artists,
    'editorial_configured_count',
      v_editorial_count,
    'fallback_enabled',
      v_fallback_enabled,
    'fallback_used',
      v_fallback_used
  );
end;
$$;


ALTER FUNCTION "public"."community_get_registry_onboarding_artists"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_get_registry_onboarding_state"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  v_user_id uuid :=
    auth.uid();

  v_status text;
  v_completed_at timestamp with time zone;
  v_skipped_at timestamp with time zone;
begin
  if v_user_id is null
  then
    raise exception
      'Not authenticated'
      using errcode = '42501';
  end if;

  select
    state.status,
    state.completed_at,
    state.skipped_at
  into
    v_status,
    v_completed_at,
    v_skipped_at
  from private.registry_onboarding_user_state
    state
  where state.user_id =
        v_user_id;

  return jsonb_build_object(
    'status',
      coalesce(
        v_status,
        'not_started'
      ),
    'completed_at',
      v_completed_at,
    'skipped_at',
      v_skipped_at
  );
end;
$$;


ALTER FUNCTION "public"."community_get_registry_onboarding_state"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_get_thread_by_entity"("p_entity_type" "text", "p_entity_id" "text" DEFAULT NULL::"text", "p_entity_slug" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'id', t.id,
    'entity_type', t.entity_type,
    'entity_id', t.entity_id,
    'entity_slug', t.entity_slug,
    'entity_url', t.entity_url,
    'title', t.title,
    'status', t.status,
    'comment_count', t.comment_count,
    'root_comment_count', t.root_comment_count,
    'last_comment_at', t.last_comment_at,
    'created_at', t.created_at,
    'updated_at', t.updated_at
  ) INTO result
  FROM community_threads t
  WHERE t.entity_type = p_entity_type
    AND (p_entity_id IS NULL OR t.entity_id = p_entity_id)
    AND (p_entity_slug IS NULL OR t.entity_slug = p_entity_slug)
  LIMIT 1;

  RETURN result;
END;
$$;


ALTER FUNCTION "public"."community_get_thread_by_entity"("p_entity_type" "text", "p_entity_id" "text", "p_entity_slug" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_get_thread_comments"("p_thread_id" "uuid", "p_sort_by" "text" DEFAULT 'best'::"text", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS TABLE("id" "uuid", "thread_id" "uuid", "parent_id" "uuid", "root_id" "uuid", "author_id" "uuid", "body_markdown" "text", "body_plain" "text", "body_html" "text", "depth" integer, "path" "text", "status" "text", "is_pinned" boolean, "is_editor_pick" boolean, "upvote_count" integer, "downvote_count" integer, "reply_count" integer, "reaction_count" integer, "report_count" integer, "score" integer, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "edited_at" timestamp with time zone, "deleted_at" timestamp with time zone, "anchor_type" "text", "anchor_time_ms" integer, "anchor_end_time_ms" integer, "anchor_label" "text", "context_entity_type" "text", "context_entity_id" "text", "context_entity_slug" "text", "context_label" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    c.id,
    c.thread_id,
    c.parent_id,
    c.root_id,
    c.author_id,
    c.body_markdown,
    c.body_plain,
    c.body_html,
    coalesce(c.depth, 0)::integer,
    c.path::text,
    c.status::text,
    coalesce(c.is_pinned, false),
    coalesce(c.is_editor_pick, false),
    coalesce(c.upvote_count, 0)::integer,
    coalesce(c.downvote_count, 0)::integer,
    coalesce(c.reply_count, 0)::integer,
    coalesce(c.reaction_count, 0)::integer,
    coalesce(c.report_count, 0)::integer,
    coalesce(c.score, 0)::integer,
    c.created_at,
    c.updated_at,
    c.edited_at,
    c.deleted_at,
    c.anchor_type,
    c.anchor_time_ms,
    c.anchor_end_time_ms,
    c.anchor_label,
    c.context_entity_type,
    c.context_entity_id,
    c.context_entity_slug,
    c.context_label
  from public.community_comments c
  where c.thread_id = p_thread_id
    and c.parent_id is null
    and c.deleted_at is null
    and c.status::text not in ('deleted', 'removed', 'spam')
    and (c.anchor_type is null or c.anchor_type = 'whole_entity')
  order by
    c.is_pinned desc,
    case when p_sort_by = 'editor_picks' then c.is_editor_pick else false end desc,
    case when p_sort_by = 'newest' then c.created_at end desc,
    case when p_sort_by = 'oldest' then c.created_at end asc,
    case when p_sort_by = 'most_replied' then coalesce(c.reply_count, 0) end desc,
    case when p_sort_by = 'best' then coalesce(c.score, 0) end desc,
    case when p_sort_by = 'best' then coalesce(c.reaction_count, 0) end desc,
    c.created_at desc
  limit least(greatest(coalesce(p_limit, 50), 1), 100)
  offset greatest(coalesce(p_offset, 0), 0);
$$;


ALTER FUNCTION "public"."community_get_thread_comments"("p_thread_id" "uuid", "p_sort_by" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_get_track_moment_comments"("p_thread_id" "uuid", "p_anchor_time_ms" integer DEFAULT NULL::integer, "p_window_ms" integer DEFAULT 2500, "p_limit" integer DEFAULT 30) RETURNS TABLE("id" "uuid", "thread_id" "uuid", "parent_id" "uuid", "root_id" "uuid", "author_id" "uuid", "body_markdown" "text", "body_plain" "text", "body_html" "text", "depth" integer, "path" "text", "status" "text", "is_pinned" boolean, "is_editor_pick" boolean, "upvote_count" integer, "downvote_count" integer, "reply_count" integer, "reaction_count" integer, "report_count" integer, "score" integer, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "edited_at" timestamp with time zone, "deleted_at" timestamp with time zone, "anchor_type" "text", "anchor_time_ms" integer, "anchor_end_time_ms" integer, "anchor_label" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    c.id,
    c.thread_id,
    c.parent_id,
    c.root_id,
    c.author_id,
    c.body_markdown,
    c.body_plain,
    c.body_html,
    coalesce(c.depth, 0)::integer,
    c.path::text,
    c.status::text,
    coalesce(c.is_pinned, false),
    coalesce(c.is_editor_pick, false),
    coalesce(c.upvote_count, 0)::integer,
    coalesce(c.downvote_count, 0)::integer,
    coalesce(c.reply_count, 0)::integer,
    coalesce(c.reaction_count, 0)::integer,
    coalesce(c.report_count, 0)::integer,
    coalesce(c.score, 0)::integer,
    c.created_at,
    c.updated_at,
    c.edited_at,
    c.deleted_at,
    c.anchor_type,
    c.anchor_time_ms,
    c.anchor_end_time_ms,
    c.anchor_label
  from public.community_comments c
  where c.thread_id = p_thread_id
    and c.parent_id is null
    and c.anchor_type in ('timestamp', 'time_range')
    and c.anchor_time_ms is not null
    and c.deleted_at is null
    and c.status::text not in ('deleted', 'removed', 'spam')
    and (
      p_anchor_time_ms is null
      or abs(c.anchor_time_ms - p_anchor_time_ms) <= greatest(coalesce(p_window_ms, 2500), 0)
    )
  order by
    case when p_anchor_time_ms is not null then abs(c.anchor_time_ms - p_anchor_time_ms) else 0 end asc,
    coalesce(c.score, 0) desc,
    coalesce(c.reaction_count, 0) desc,
    c.created_at desc
  limit least(greatest(coalesce(p_limit, 30), 1), 100);
$$;


ALTER FUNCTION "public"."community_get_track_moment_comments"("p_thread_id" "uuid", "p_anchor_time_ms" integer, "p_window_ms" integer, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_get_track_moment_summary"("p_thread_id" "uuid", "p_limit" integer DEFAULT 6) RETURNS TABLE("anchor_time_ms" integer, "anchor_label" "text", "comment_count" integer, "reaction_count" integer, "score" integer, "latest_comment_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with bucketed as (
    select
      (floor(c.anchor_time_ms::numeric / 5000) * 5000)::integer as bucket_ms,
      count(*)::integer as comment_count,
      coalesce(sum(c.reaction_count), 0)::integer as reaction_count,
      coalesce(sum(c.score), 0)::integer as score,
      max(c.created_at) as latest_comment_at
    from public.community_comments c
    where c.thread_id = p_thread_id
      and c.parent_id is null
      and c.anchor_type in ('timestamp', 'time_range')
      and c.anchor_time_ms is not null
      and c.deleted_at is null
      and c.status::text not in ('deleted', 'removed', 'spam')
    group by 1
  )
  select
    bucket_ms as anchor_time_ms,
    (floor(bucket_ms / 60000)::integer)::text || ':' ||
      lpad((floor((bucket_ms % 60000) / 1000)::integer)::text, 2, '0') as anchor_label,
    comment_count,
    reaction_count,
    score,
    latest_comment_at
  from bucketed
  order by
    comment_count desc,
    reaction_count desc,
    score desc,
    latest_comment_at desc
  limit least(greatest(coalesce(p_limit, 6), 1), 20);
$$;


ALTER FUNCTION "public"."community_get_track_moment_summary"("p_thread_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_get_unread_count"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_count integer := 0;
begin
  if auth.uid() is null then
    return jsonb_build_object('count', 0);
  end if;

  select count(*)::integer
  into v_count
  from public.community_notifications
  where user_id = auth.uid()
    and read_at is null;

  return jsonb_build_object('count', coalesce(v_count, 0));
end;
$$;


ALTER FUNCTION "public"."community_get_unread_count"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_get_user_comments"("p_user_id" "uuid", "p_limit" integer DEFAULT 20) RETURNS TABLE("id" "uuid", "thread_id" "uuid", "parent_id" "uuid", "root_id" "uuid", "author_id" "uuid", "body_markdown" "text", "body_plain" "text", "body_html" "text", "depth" integer, "path" "text", "status" "text", "is_pinned" boolean, "is_editor_pick" boolean, "upvote_count" integer, "downvote_count" integer, "reply_count" integer, "reaction_count" integer, "report_count" integer, "score" integer, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "edited_at" timestamp with time zone, "deleted_at" timestamp with time zone, "thread_title" "text", "thread_entity_type" "text", "thread_entity_id" "text", "thread_entity_slug" "text", "thread_entity_url" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if auth.uid() is null or auth.uid() <> p_user_id then
    raise exception 'Not allowed' using errcode = '42501';
  end if;

  return query
  select
    c.id,
    c.thread_id,
    c.parent_id,
    c.root_id,
    c.author_id,
    c.body_markdown,
    c.body_plain,
    c.body_html,
    coalesce(c.depth, 0)::integer,
    c.path::text,
    c.status::text,
    coalesce(c.is_pinned, false),
    coalesce(c.is_editor_pick, false),
    coalesce(c.upvote_count, 0)::integer,
    coalesce(c.downvote_count, 0)::integer,
    coalesce(c.reply_count, 0)::integer,
    coalesce(c.reaction_count, 0)::integer,
    coalesce(c.report_count, 0)::integer,
    coalesce(c.score, 0)::integer,
    c.created_at,
    c.updated_at,
    c.edited_at,
    c.deleted_at,
    t.title,
    t.entity_type::text,
    t.entity_id::text,
    t.entity_slug,
    t.entity_url
  from public.community_comments c
  left join public.community_threads t on t.id = c.thread_id
  where c.author_id = p_user_id
    and c.parent_id is null
    and c.deleted_at is null
    and c.status::text not in ('deleted', 'removed', 'spam')
  order by c.created_at desc
  limit least(greatest(coalesce(p_limit, 20), 1), 100);
end;
$$;


