  select jsonb_agg(
    jsonb_build_object(
      'id',
        follow.id,
      'user_id',
        follow.user_id,
      'target_type',
        follow.target_type,
      'target_id',
        follow.target_id,
      'target_slug',
        follow.target_slug,
      'created_at',
        follow.created_at
    )
    order by follow.created_at desc
  )
  into v_result
  from public.community_follows follow
  where follow.user_id = v_user_id;

  return coalesce(
    v_result,
    '[]'::jsonb
  );
end;
$$;


