CREATE OR REPLACE FUNCTION "public"."community_get_user_notifications"("p_user_id" "uuid", "p_limit" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_limit integer := least(greatest(coalesce(p_limit, 30), 1), 100);
  v_notifications jsonb := '[]'::jsonb;
begin
  if auth.uid() is null or auth.uid() <> p_user_id then
    return '[]'::jsonb;
  end if;

  select coalesce(jsonb_agg(to_jsonb(notification_row) order by notification_row.created_at desc), '[]'::jsonb)
  into v_notifications
  from (
    select
      n.id,
      n.user_id,
      n.actor_id,
      n.notification_type,
      n.entity_type,
      n.entity_id,
      n.entity_slug,
      n.comment_id,
      coalesce(n.metadata, '{}'::jsonb) as metadata,
      n.read_at,
      n.created_at
    from public.community_notifications n
    where n.user_id = p_user_id
    order by n.created_at desc
    limit v_limit
  ) notification_row;

  return coalesce(v_notifications, '[]'::jsonb);
end;
$$;


ALTER FUNCTION "public"."community_get_user_notifications"("p_user_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_get_user_profile"("p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_profile public.user_profiles%rowtype;
begin
  if p_user_id is null then
    return null;
  end if;

  if auth.uid() is not null and (p_user_id = auth.uid() or public.current_user_is_administrator()) then
    perform public.community_ensure_user_account(p_user_id);
  end if;

  select * into v_profile
  from public.user_profiles
  where user_id = p_user_id;

  if not found then
    return null;
  end if;

  if coalesce(v_profile.is_public, true) = false
    and (
      auth.uid() is null
      or (v_profile.user_id <> auth.uid() and not public.current_user_is_administrator())
    ) then
    return null;
  end if;

  return public.community_profile_json(v_profile);
end;
$$;


