CREATE OR REPLACE FUNCTION "public"."community_get_user_reactions"("p_user_id" "uuid", "p_target_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  result jsonb;
BEGIN
  SELECT jsonb_object_agg(
    r.target_id::text,
    jsonb_agg(r.reaction_type)
  ) INTO result
  FROM community_reactions r
  WHERE r.user_id = p_user_id AND r.target_id = ANY(p_target_ids)
  GROUP BY r.target_id;

  RETURN COALESCE(result, '{}'::jsonb);
END;
$$;


