CREATE OR REPLACE FUNCTION "public"."community_normalize_username"("p_username" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select nullif(lower(trim(both from regexp_replace(coalesce(p_username, ''), '^@+', '', 'g'))), '');
$$;


