CREATE OR REPLACE FUNCTION "public"."community_username_is_valid"("p_username" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    AS $_$
  select coalesce(p_username ~ '^[a-z0-9]([a-z0-9_]{1,28}[a-z0-9])$', false);
$_$;


