CREATE TABLE IF NOT EXISTS "public"."user_profiles" (
    "user_id" "uuid" NOT NULL,
    "email" "text",
    "display_name" "text",
    "avatar_url" "text",
    "bio" "text",
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "country" "text",
    "city" "text",
    "is_public" boolean DEFAULT true NOT NULL,
    "username" "text",
    "username_normalized" "text",
    "username_updated_at" timestamp with time zone,
    "username_change_count" integer DEFAULT 0 NOT NULL,
    "cover_url" "text",
    CONSTRAINT "user_profiles_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'pending'::"text", 'suspended'::"text", 'disabled'::"text"]))),
    CONSTRAINT "user_profiles_username_format" CHECK ((("username_normalized" IS NULL) OR "public"."community_username_is_valid"("username_normalized"))),
    CONSTRAINT "user_profiles_username_sync" CHECK ((("username_normalized" IS NULL) OR ("username_normalized" = "public"."community_normalize_username"("username"))))
);


