CREATE OR REPLACE FUNCTION "public"."community_profile_json"("p_profile" "public"."user_profiles") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select jsonb_build_object(
    'user_id', p_profile.user_id,
    'email', p_profile.email,
    'username', p_profile.username_normalized,
    'username_normalized', p_profile.username_normalized,
    'display_name', coalesce(p_profile.display_name, split_part(coalesce(p_profile.email, ''), '@', 1), 'WAKILISHA user'),
    'bio', coalesce(p_profile.bio, ''),
    'country', coalesce(p_profile.country, ''),
    'city', coalesce(p_profile.city, ''),
    'avatar_url', p_profile.avatar_url,
    'cover_url', p_profile.cover_url,
    'role_labels', coalesce((
      select array_agg(ura.role_key order by rd.priority, ura.role_key)
      from public.user_role_assignments ura
      left join public.role_definitions rd on rd.role_key = ura.role_key
      where ura.user_id = p_profile.user_id
        and ura.status = 'active'
        and (ura.expires_at is null or ura.expires_at > now())
    ), array[]::text[]),
    'trust_level', 0,
    'reputation_score', 0,
    'comment_count', 0,
    'contribution_count', 0,
    'is_public', coalesce(p_profile.is_public, true),
    'created_at', p_profile.created_at,
    'updated_at', p_profile.updated_at
  );
$$;


ALTER FUNCTION "public"."community_profile_json"("p_profile" "public"."user_profiles") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_publish_artist_update"("p_artist_id" "uuid", "p_body" "text", "p_image_url" "text" DEFAULT NULL::"text", "p_link_url" "text" DEFAULT NULL::"text", "p_link_label" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_rep public.artist_representations%rowtype;
  v_artist_slug text;
  v_body text := btrim(coalesce(p_body, ''));
  v_image_url text := nullif(btrim(coalesce(p_image_url, '')), '');
  v_link_url text := nullif(btrim(coalesce(p_link_url, '')), '');
  v_link_label text := nullif(btrim(coalesce(p_link_label, '')), '');
  v_update public.artist_updates%rowtype;
begin
  if v_actor is null then
    raise exception 'authentication_required';
  end if;

  select *
  into v_rep
  from editorial.current_artist_representation(p_artist_id);

  if v_rep.id is null
     or not v_rep.can_post_updates
  then
    raise exception 'insufficient_artist_update_privilege';
  end if;

  select artist.slug
  into v_artist_slug
  from public.registry_artists artist
  where artist.id = p_artist_id
    and artist.status = 'active';

  if v_artist_slug is null then
    raise exception 'artist_not_found';
  end if;

  if char_length(v_body) < 1
     or char_length(v_body) > 2000
  then
    raise exception 'invalid_artist_update_body';
  end if;

  if v_image_url is not null
     and (
       char_length(v_image_url) > 2048
       or v_image_url !~* '^https?://'
     )
  then
    raise exception 'invalid_artist_update_image_url';
  end if;

  if v_link_url is not null
     and (
       char_length(v_link_url) > 2048
       or v_link_url !~* '^https?://'
     )
  then
    raise exception 'invalid_artist_update_link_url';
  end if;

  if v_link_label is not null
     and (
       char_length(v_link_label) > 120
       or v_link_url is null
     )
  then
    raise exception 'invalid_artist_update_link_label';
  end if;

  insert into public.artist_updates (
    artist_id,
    representation_id,
    author_user_id,
    body,
    image_url,
    link_url,
    link_label,
    status
  )
  values (
    p_artist_id,
    v_rep.id,
    v_actor,
    v_body,
    v_image_url,
    v_link_url,
    v_link_label,
    'published'
  )
  returning *
  into v_update;

  perform editorial.record_artist_representation_event(
    p_artist_id,
    'artist_update_published',
    null,
    v_rep.id,
    v_actor,
    jsonb_build_object(
      'artist_update_id', v_update.id,
      'published_at', v_update.published_at
    )
  );

  return jsonb_build_object(
    'id', v_update.id,
    'artist_id', v_update.artist_id,
    'body', v_update.body,
    'image_url', v_update.image_url,
    'link_url', v_update.link_url,
    'link_label', v_update.link_label,
    'status', v_update.status,
    'published_at', v_update.published_at,
    'updated_at', v_update.updated_at,
    'canonical_path',
      '/artists/' || v_artist_slug || '/updates/' || v_update.id::text
  );
end;
$$;


ALTER FUNCTION "public"."community_publish_artist_update"("p_artist_id" "uuid", "p_body" "text", "p_image_url" "text", "p_link_url" "text", "p_link_label" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_react_to_target"("p_target_type" "text", "p_target_id" "uuid", "p_reaction_type" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_target_type text :=
    nullif(
      trim(
        coalesce(
          p_target_type,
          ''
        )
      ),
      ''
    );
  v_reaction_type text :=
    nullif(
      trim(
        coalesce(
          p_reaction_type,
          ''
        )
      ),
      ''
    );
  v_existing uuid;
  v_created boolean;
  v_reaction_count integer;
begin
  if v_user_id is null then
    raise exception
      'Not authenticated'
      using errcode = '42501';
  end if;

  if v_target_type is null
     or p_target_id is null
  then
    raise exception
      'Reaction target is required'
      using errcode = '22023';
  end if;

  if v_reaction_type is null
     or char_length(v_reaction_type) > 32
     or v_reaction_type ~ '[[:cntrl:]]'
     or v_reaction_type ~ '[[:space:]]'
     or (
       octet_length(v_reaction_type) =
       char_length(v_reaction_type)
       and v_reaction_type not in (
         'signal',
         'memory',
         'context',
         'fire',
         'agree'
       )
     )
  then
    raise exception
      'Unsupported reaction type'
      using errcode = '22023';
  end if;

  if v_target_type = 'artist_update' then
    perform 1
    from public.artist_updates artist_update
    join public.registry_artists artist
      on artist.id = artist_update.artist_id
    where artist_update.id = p_target_id
      and artist_update.status = 'published'
      and artist.status = 'active';

    if not found then
      raise exception
        'Reaction target is not currently public'
        using errcode = '22023';
    end if;
  end if;

  perform pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      v_user_id::text
      || '|'
      || v_target_type
      || '|'
      || p_target_id::text
      || '|'
      || v_reaction_type,
      0
    )
  );

  if v_target_type = 'comment' then
    perform 1
    from public.community_comments comment
    where comment.id = p_target_id
    for update;

    if not found then
      raise exception
        'Comment not found'
        using errcode = '22023';
    end if;
  end if;

  delete from public.community_reactions
  where user_id = v_user_id
    and target_type = v_target_type
    and target_id = p_target_id
    and reaction_type = v_reaction_type
  returning id
  into v_existing;

  if found then
    v_created := false;
  else
    insert into public.community_reactions (
      user_id,
      target_type,
      target_id,
      reaction_type
    )
    values (
      v_user_id,
      v_target_type,
      p_target_id,
      v_reaction_type
    );

    v_created := true;
  end if;

  if v_target_type = 'comment' then
    select count(*)::integer
    into v_reaction_count
    from public.community_reactions reaction
    where reaction.target_type = 'comment'
      and reaction.target_id = p_target_id;

    update public.community_comments
    set reaction_count = v_reaction_count
    where id = p_target_id;
  else
    v_reaction_count := null;
  end if;

  return jsonb_build_object(
    'created', v_created,
    'reaction_type', v_reaction_type,
    'reaction_count', v_reaction_count
  );
end;
$$;


ALTER FUNCTION "public"."community_react_to_target"("p_target_type" "text", "p_target_id" "uuid", "p_reaction_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_report_comment"("p_comment_id" "uuid", "p_reason" "text", "p_details" "text" DEFAULT ''::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();

  v_reason text :=
    nullif(
      trim(
        coalesce(
          p_reason,
          ''
        )
      ),
      ''
    );

  v_details text :=
    trim(
      coalesce(
        p_details,
        ''
      )
    );

  v_report jsonb;
  v_report_count integer;
begin
  if v_user_id is null then
    raise exception
      'Not authenticated'
      using errcode = '42501';
  end if;

  if p_comment_id is null then
    raise exception
      'Comment is required'
      using errcode = '22023';
  end if;

  if v_reason not in (
    'spam',
    'harassment',
    'hate_or_abuse',
    'misinformation',
    'privacy',
    'copyright',
    'off_topic',
    'other'
  )
  then
    raise exception
      'Unsupported report reason'
      using errcode = '22023';
  end if;

  perform 1
  from public.community_comments comment
  where comment.id = p_comment_id
  for update;

  if not found then
    raise exception
      'Comment not found'
      using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      v_user_id::text
      || '|report|'
      || p_comment_id::text
      || '|'
      || v_reason
      || '|'
      || v_details,
      0
    )
  );

  select to_jsonb(
    report.*
  )
  into v_report
  from public.community_reports report
  where report.reporter_id =
          v_user_id
    and report.comment_id =
          p_comment_id
    and report.reason =
          v_reason
    and coalesce(
          report.details,
          ''
        ) =
          v_details
    and report.status =
          'pending'
  order by report.created_at desc
  limit 1;

  if v_report is not null then
    select count(*)::integer
    into v_report_count
    from public.community_reports report
    where report.comment_id =
      p_comment_id;

    return jsonb_build_object(
      'report',
        v_report,
      'report_count',
        v_report_count,
      'created',
        false
    );
  end if;

  insert into public.community_reports (
    reporter_id,
    comment_id,
    reason,
    details
  )
  values (
    v_user_id,
    p_comment_id,
    v_reason,
    v_details
  )
  returning to_jsonb(
    community_reports.*
  )
  into v_report;

  select count(*)::integer
  into v_report_count
  from public.community_reports report
  where report.comment_id =
    p_comment_id;

  update public.community_comments
  set report_count =
    v_report_count
  where id =
    p_comment_id;

  return jsonb_build_object(
    'report',
      v_report,
    'report_count',
      v_report_count,
    'created',
      true
  );
end;
$$;


ALTER FUNCTION "public"."community_report_comment"("p_comment_id" "uuid", "p_reason" "text", "p_details" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_save_artist_profile_presentation"("p_artist_id" "uuid", "p_bio" "text" DEFAULT NULL::"text", "p_profile_image_url" "text" DEFAULT NULL::"text", "p_hero_image_url" "text" DEFAULT NULL::"text", "p_website_url" "text" DEFAULT NULL::"text", "p_public_email" "text" DEFAULT NULL::"text", "p_social_links" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_rep public.artist_representations%rowtype;
  v_bio text := nullif(trim(coalesce(p_bio, '')), '');
  v_profile_image_url text := nullif(trim(coalesce(p_profile_image_url, '')), '');
  v_hero_image_url text := nullif(trim(coalesce(p_hero_image_url, '')), '');
  v_website_url text := nullif(trim(coalesce(p_website_url, '')), '');
  v_public_email text := nullif(lower(trim(coalesce(p_public_email, ''))), '');
  v_social_links jsonb := coalesce(p_social_links, '{}'::jsonb);
  v_key text;
  v_value text;
  v_result jsonb;
begin
  if v_actor is null then
    raise exception 'authentication_required';
  end if;

  select *
  into v_rep
  from editorial.current_artist_representation(p_artist_id);

  if v_rep.id is null
     or not v_rep.can_manage_profile
  then
    raise exception 'insufficient_artist_profile_privilege';
  end if;

  if v_bio is not null
     and char_length(v_bio) > 4000
  then
    raise exception 'artist_bio_too_long';
  end if;

  if v_profile_image_url is not null
     and (
       char_length(v_profile_image_url) > 2048
       or v_profile_image_url !~* '^https?://'
     )
  then
    raise exception 'invalid_profile_image_url';
  end if;

  if v_hero_image_url is not null
     and (
       char_length(v_hero_image_url) > 2048
       or v_hero_image_url !~* '^https?://'
     )
  then
    raise exception 'invalid_hero_image_url';
  end if;

  if v_website_url is not null
     and (
       char_length(v_website_url) > 2048
       or v_website_url !~* '^https?://'
     )
  then
    raise exception 'invalid_artist_website_url';
  end if;

  if v_public_email is not null
     and (
       char_length(v_public_email) > 320
       or v_public_email !~* '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'
     )
  then
    raise exception 'invalid_public_email';
  end if;

  if jsonb_typeof(v_social_links) <> 'object' then
    raise exception 'artist_social_links_must_be_object';
  end if;

  for v_key, v_value in
    select key, value
    from jsonb_each_text(v_social_links)
  loop
    if v_key not in (
      'instagram',
      'tiktok',
      'x',
      'youtube',
      'facebook',
      'spotify',
      'soundcloud'
    ) then
      raise exception 'unsupported_artist_social_link';
    end if;

    if nullif(trim(v_value), '') is not null
       and (
         char_length(v_value) > 2048
         or v_value !~* '^https?://'
       )
    then
      raise exception 'invalid_artist_social_link';
    end if;
  end loop;

  insert into public.artist_profile_presentations (
    artist_id,
    bio,
    profile_image_url,
    hero_image_url,
    website_url,
    public_email,
    social_links,
    updated_by
  )
  values (
    p_artist_id,
    v_bio,
    v_profile_image_url,
    v_hero_image_url,
    v_website_url,
    v_public_email,
    v_social_links,
    v_actor
  )
  on conflict (artist_id)
  do update set
    bio = excluded.bio,
    profile_image_url = excluded.profile_image_url,
    hero_image_url = excluded.hero_image_url,
    website_url = excluded.website_url,
    public_email = excluded.public_email,
    social_links = excluded.social_links,
    updated_by = excluded.updated_by,
    updated_at = now()
  returning jsonb_build_object(
    'artist_id', artist_id,
    'bio', bio,
    'profile_image_url', profile_image_url,
    'hero_image_url', hero_image_url,
    'website_url', website_url,
    'public_email', public_email,
    'social_links', social_links,
    'updated_at', updated_at
  )
  into v_result;

  perform editorial.record_artist_representation_event(
    p_artist_id,
    'profile_presentation_updated',
    null,
    v_rep.id,
    v_actor,
    jsonb_build_object(
      'presentation_updated_at', now()
    )
  );

  return v_result;
end;
$_$;


ALTER FUNCTION "public"."community_save_artist_profile_presentation"("p_artist_id" "uuid", "p_bio" "text", "p_profile_image_url" "text", "p_hero_image_url" "text", "p_website_url" "text", "p_public_email" "text", "p_social_links" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_save_entity"("p_entity_type" "text", "p_entity_id" "text" DEFAULT NULL::"text", "p_entity_slug" "text" DEFAULT NULL::"text", "p_entity_url" "text" DEFAULT NULL::"text", "p_title" "text" DEFAULT NULL::"text", "p_subtitle" "text" DEFAULT NULL::"text", "p_image_url" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  v_user_id uuid :=
    auth.uid();
  v_title text :=
    nullif(
      btrim(
        coalesce(
          p_title,
          ''
        )
      ),
      ''
    );
  v_subtitle text :=
    nullif(
      btrim(
        coalesce(
          p_subtitle,
          ''
        )
      ),
      ''
    );
  v_image_url text :=
    nullif(
      btrim(
        coalesce(
          p_image_url,
          ''
        )
      ),
      ''
    );
  v_target record;
  v_save public.community_saves%rowtype;
begin
  if v_user_id is null then
    raise exception
      'Not authenticated'
      using errcode = '42501';
  end if;

  if v_title is null then
    raise exception
      'Title is required'
      using errcode = '22023';
  end if;

  select *
  into v_target
  from private.community_resolve_save_target(
    p_entity_type,
    p_entity_id,
    p_entity_slug,
    p_entity_url
  );

  if not v_target.saveable then
    raise exception
      'Target is not publicly saveable'
      using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      v_user_id::text
      || '|save|'
      || v_target.canonical_type
      || '|'
      || v_target.canonical_id,
      0
    )
  );

  select *
  into v_save
  from public.community_saves saved
  where saved.user_id =
        v_user_id
    and saved.entity_type =
        v_target.canonical_type
    and (
      saved.entity_id =
        v_target.canonical_id
      or (
        v_target.canonical_type not in (
          'track',
          'release'
        )
        and v_target.canonical_slug is not null
        and saved.entity_slug =
            v_target.canonical_slug
      )
      or (
        v_target.canonical_url is not null
        and saved.entity_url =
            v_target.canonical_url
      )
    )
  order by
    saved.created_at,
    saved.id
  limit 1;

  if found then
    update public.community_saves
    set
      entity_id =
        v_target.canonical_id,
      entity_slug =
        v_target.canonical_slug,
      entity_url =
        coalesce(
          v_target.canonical_url,
          entity_url
        ),
      title =
        v_title,
      subtitle =
        v_subtitle,
      image_url =
        v_image_url
    where id =
          v_save.id
    returning *
    into v_save;

    return jsonb_build_object(
      'saved',
        true,
      'existing',
        true,
      'save',
        to_jsonb(
          v_save
        )
    );
  end if;

  insert into public.community_saves (
    user_id,
    entity_type,
    entity_id,
    entity_slug,
    entity_url,
    title,
    subtitle,
    image_url
  )
  values (
    v_user_id,
    v_target.canonical_type,
    v_target.canonical_id,
    v_target.canonical_slug,
    coalesce(
      v_target.canonical_url,
      nullif(
        btrim(
          coalesce(
            p_entity_url,
            ''
          )
        ),
        ''
      )
    ),
    v_title,
    v_subtitle,
    v_image_url
  )
  returning *
  into v_save;

  return jsonb_build_object(
    'saved',
      true,
    'existing',
      false,
    'save',
      to_jsonb(
        v_save
      )
  );
end;
$$;


ALTER FUNCTION "public"."community_save_entity"("p_entity_type" "text", "p_entity_id" "text", "p_entity_slug" "text", "p_entity_url" "text", "p_title" "text", "p_subtitle" "text", "p_image_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_set_follow_state"("p_target_type" "text", "p_target_id" "text", "p_target_slug" "text", "p_followed" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial', 'private'
    AS $$
declare
  v_user_id uuid :=
    auth.uid();
  v_followed boolean :=
    coalesce(
      p_followed,
      false
    );
  v_target record;
begin
  if v_user_id is null then
    raise exception
      'Not authenticated'
      using errcode = '42501';
  end if;

  select *
  into v_target
  from private.community_resolve_follow_target(
    p_target_type,
    p_target_id,
    p_target_slug
  );

  if v_followed
     and not v_target.followable
  then
    raise exception
      'Target is not publicly followable'
      using errcode = '22023';
  end if;

  if v_followed
     and v_target.canonical_type =
         'person'
     and exists (
       select 1
       from editorial.person_identity_links link
       where link.person_resource_id =
             v_target.canonical_id::uuid
         and link.link_state =
             'active'
         and link.user_id =
             v_user_id
     )
  then
    raise exception
      'A user cannot follow their own Person'
      using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      v_user_id::text
      || '|follow|'
      || v_target.canonical_type
      || '|'
      || v_target.canonical_id,
      0
    )
  );

  if v_followed then
    insert into public.community_follows (
      user_id,
      target_type,
      target_id,
      target_slug
    )
    values (
      v_user_id,
      v_target.canonical_type,
      v_target.canonical_id,
      v_target.canonical_slug
    )
    on conflict (
      user_id,
      target_type,
      target_id
    )
    do update
    set target_slug =
      excluded.target_slug;
  else
    delete from public.community_follows
    where user_id =
          v_user_id
      and target_type =
          v_target.canonical_type
      and target_id =
          v_target.canonical_id;
  end if;

  return jsonb_build_object(
    'followed',
      v_followed,
    'target_type',
      v_target.canonical_type,
    'target_id',
      v_target.canonical_id,
    'target_slug',
      v_target.canonical_slug
  );
end;
$$;


ALTER FUNCTION "public"."community_set_follow_state"("p_target_type" "text", "p_target_id" "text", "p_target_slug" "text", "p_followed" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_set_registry_onboarding_state"("p_status" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  v_user_id uuid :=
    auth.uid();

  v_status text :=
    lower(
      btrim(
        coalesce(
          p_status,
          ''
        )
      )
    );

  v_completed_at timestamp with time zone;
  v_skipped_at timestamp with time zone;
begin
  if v_user_id is null
  then
    raise exception
      'Not authenticated'
      using errcode = '42501';
  end if;

  if v_status not in (
       'completed',
       'skipped'
     )
  then
    raise exception
      'Onboarding state must be completed or skipped'
      using errcode = '22023';
  end if;

  v_completed_at :=
    case
      when v_status =
           'completed'
      then now()
      else null
    end;

  v_skipped_at :=
    case
      when v_status =
           'skipped'
      then now()
      else null
    end;

  insert into
    private.registry_onboarding_user_state (
      user_id,
      status,
      completed_at,
      skipped_at,
      created_at,
      updated_at
    )
  values (
    v_user_id,
    v_status,
    v_completed_at,
    v_skipped_at,
    now(),
    now()
  )
  on conflict (
    user_id
  )
  do update
  set
    status =
      excluded.status,
    completed_at =
      excluded.completed_at,
    skipped_at =
      excluded.skipped_at,
    updated_at =
      now();

  return jsonb_build_object(
    'status',
      v_status,
    'completed_at',
      v_completed_at,
    'skipped_at',
      v_skipped_at
  );
end;
$$;


ALTER FUNCTION "public"."community_set_registry_onboarding_state"("p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_set_saved_state"("p_entity_type" "text", "p_entity_id" "text", "p_entity_slug" "text", "p_entity_url" "text", "p_title" "text", "p_subtitle" "text", "p_image_url" "text", "p_saved" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_saved boolean := coalesce(p_saved, false);
  v_type text := lower(btrim(coalesce(p_entity_type, '')));
  v_title text := nullif(btrim(coalesce(p_title, '')), '');
  v_subtitle text := nullif(btrim(coalesce(p_subtitle, '')), '');
  v_image_url text := nullif(btrim(coalesce(p_image_url, '')), '');
  v_target record;
begin
  if v_user_id is null then
    raise exception
      'Not authenticated'
      using errcode = '42501';
  end if;

  if v_type = 'artist_update' then
    select
      'artist_update'::text as canonical_type,
      artist_update.id::text as canonical_id,
      artist_update.id::text as canonical_slug,
      '/artists/' || artist.slug || '/updates/' || artist_update.id::text
        as canonical_url,
      (
        artist_update.status = 'published'
        and artist.status = 'active'
      ) as saveable
    into v_target
    from public.artist_updates artist_update
    join public.registry_artists artist
      on artist.id = artist_update.artist_id
    where artist_update.id::text =
          btrim(coalesce(p_entity_id, ''))
       or artist_update.id::text =
          btrim(coalesce(p_entity_slug, ''))
    limit 1;

    if v_target.canonical_id is null then
      raise exception
        'Artist Update Save target does not exist'
        using errcode = 'P0002';
    end if;
  else
    select *
    into v_target
    from private.community_resolve_save_target(
      p_entity_type,
      p_entity_id,
      p_entity_slug,
      p_entity_url
    );
  end if;

  if v_saved
     and not v_target.saveable
  then
    raise exception
      'Target is not publicly saveable'
      using errcode = '22023';
  end if;

  if v_saved
     and v_title is null
  then
    raise exception
      'Title is required when saving'
      using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      v_user_id::text
      || '|save|'
      || v_target.canonical_type
      || '|'
      || v_target.canonical_id,
      0
    )
  );

  if v_saved then
    insert into public.community_saves (
      user_id,
      entity_type,
      entity_id,
      entity_slug,
      entity_url,
      title,
      subtitle,
      image_url
    )
    values (
      v_user_id,
      v_target.canonical_type,
      v_target.canonical_id,
      v_target.canonical_slug,
      coalesce(
        v_target.canonical_url,
        nullif(
          btrim(
            coalesce(
              p_entity_url,
              ''
            )
          ),
          ''
        )
      ),
      v_title,
      v_subtitle,
      v_image_url
    )
    on conflict (
      user_id,
      entity_type,
      entity_id
    )
    do update
    set
      entity_slug = excluded.entity_slug,
      entity_url = excluded.entity_url,
      title = excluded.title,
      subtitle = excluded.subtitle,
      image_url = excluded.image_url;
  else
    delete from public.community_saves
    where user_id = v_user_id
      and entity_type = v_target.canonical_type
      and entity_id = v_target.canonical_id;
  end if;

  return jsonb_build_object(
    'saved', v_saved,
    'entity_type', v_target.canonical_type,
    'entity_id', v_target.canonical_id,
    'entity_slug', v_target.canonical_slug,
    'entity_url', v_target.canonical_url
  );
end;
$$;


ALTER FUNCTION "public"."community_set_saved_state"("p_entity_type" "text", "p_entity_id" "text", "p_entity_slug" "text", "p_entity_url" "text", "p_title" "text", "p_subtitle" "text", "p_image_url" "text", "p_saved" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_soft_delete_comment"("p_comment_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_comment jsonb;
BEGIN
  UPDATE community_comments
  SET status = 'deleted',
      deleted_at = now(),
      body_plain = '[deleted]',
      body_markdown = '[deleted]',
      body_html = '<p>[deleted]</p>'
  WHERE id = p_comment_id AND author_id = auth.uid()
  RETURNING to_jsonb(community_comments.*) INTO v_comment;

  IF v_comment IS NULL THEN
    RAISE EXCEPTION 'Comment not found or not owned by user';
  END IF;

  RETURN jsonb_build_object('comment', v_comment);
END;
$$;


ALTER FUNCTION "public"."community_soft_delete_comment"("p_comment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_submit_artist_claim"("p_artist_id" "uuid", "p_claimant_role" "text", "p_statement" "text", "p_evidence" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_role text :=
    lower(
      trim(
        coalesce(
          p_claimant_role,
          ''
        )
      )
    );
  v_statement text :=
    trim(
      coalesce(
        p_statement,
        ''
      )
    );
  v_claim_id uuid;
  v_evidence jsonb;
  v_type text;
  v_reference text;
  v_note text;
begin
  if v_actor is null then
    raise exception
      'authentication_required';
  end if;

  if not exists (
    select 1
    from public.registry_artists artist
    where artist.id = p_artist_id
      and artist.status = 'active'
  ) then
    raise exception
      'artist_not_claimable';
  end if;

  if v_role not in (
    'artist',
    'manager',
    'label',
    'publicist',
    'team_member',
    'other'
  ) then
    raise exception
      'invalid_claimant_role';
  end if;

  if char_length(v_statement) < 10
     or char_length(v_statement) > 4000
  then
    raise exception
      'invalid_claim_statement';
  end if;

  if coalesce(
       jsonb_typeof(
         p_evidence
       ),
       'null'
     ) <> 'array'
  then
    raise exception
      'claim_evidence_must_be_array';
  end if;

  if jsonb_array_length(
       p_evidence
     ) > 10
  then
    raise exception
      'too_many_claim_evidence_items';
  end if;

  if exists (
    select 1
    from public.artist_representations representation
    where representation.artist_id = p_artist_id
      and representation.user_id = v_actor
      and representation.status in (
        'pending',
        'active'
      )
  ) then
    raise exception
      'representation_already_exists';
  end if;

  if exists (
    select 1
    from public.artist_claim_requests claim
    where claim.artist_id = p_artist_id
      and claim.claimant_user_id = v_actor
      and claim.status = 'pending'
  ) then
    raise exception
      'claim_already_pending';
  end if;

  insert into public.artist_claim_requests (
    artist_id,
    claimant_user_id,
    claimant_role,
    statement
  )
  values (
    p_artist_id,
    v_actor,
    v_role,
    v_statement
  )
  returning id
  into v_claim_id;

  for v_evidence
  in
    select value
    from jsonb_array_elements(
      p_evidence
    )
  loop
    v_type :=
      lower(
        trim(
          coalesce(
            v_evidence->>'type',
            ''
          )
        )
      );

    v_reference :=
      nullif(
        trim(
          coalesce(
            v_evidence->>'reference',
            ''
          )
        ),
        ''
      );

    v_note :=
      nullif(
        trim(
          coalesce(
            v_evidence->>'note',
            ''
          )
        ),
        ''
      );

    if v_type not in (
      'official_website',
      'official_social',
      'business_email',
      'label_or_distributor',
      'public_announcement',
      'other'
    ) then
      raise exception
        'invalid_claim_evidence_type';
    end if;

    if v_reference is null
       and v_note is null
    then
      raise exception
        'claim_evidence_requires_content';
    end if;

    if v_reference is not null
       and char_length(
         v_reference
       ) > 2048
    then
      raise exception
        'claim_evidence_reference_too_long';
    end if;

    if v_note is not null
       and char_length(
         v_note
       ) > 2000
    then
      raise exception
        'claim_evidence_note_too_long';
    end if;

    insert into public.artist_claim_evidence (
      claim_id,
      evidence_type,
      reference,
      note
    )
    values (
      v_claim_id,
      v_type,
      v_reference,
      v_note
    );
  end loop;

  perform editorial.record_artist_representation_event(
    p_artist_id,
    'claim_submitted',
    v_claim_id,
    null,
    v_actor,
    jsonb_build_object(
      'claimant_role',
      v_role
    )
  );

  perform editorial.sync_artist_portal_roles(
    v_actor
  );

  return jsonb_build_object(
    'claim_id',
      v_claim_id,
    'artist_id',
      p_artist_id,
    'status',
      'pending',
    'claimant_role',
      v_role
  );
end;
$$;


ALTER FUNCTION "public"."community_submit_artist_claim"("p_artist_id" "uuid", "p_claimant_role" "text", "p_statement" "text", "p_evidence" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_submit_artist_music"("p_artist_id" "uuid", "p_validation_id" "uuid", "p_artist_credits" "jsonb", "p_submission_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial', 'platform_private'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_rep public.artist_representations%rowtype;
  v_artist public.registry_artists%rowtype;
  v_validation platform_private.artist_music_submission_validations%rowtype;
  v_suggestion public.registry_provider_track_suggestions%rowtype;
  v_key text :=
    nullif(
      btrim(p_submission_key),
      ''
    );
  v_submitted_at timestamptz := now();
  v_review_due_at timestamptz;
  v_credit jsonb;
  v_credit_order integer := 1;
  v_credit_role text;
  v_observed_name text;
  v_seen_names text[] := '{}'::text[];
begin
  if v_actor is null then
    raise exception 'authentication_required';
  end if;

  select *
  into v_rep
  from editorial.current_artist_representation(p_artist_id);

  if v_rep.id is null
     or not v_rep.can_submit_releases
  then
    raise exception 'insufficient_artist_music_privilege';
  end if;

  select artist.*
  into v_artist
  from public.registry_artists artist
  where artist.id = p_artist_id
    and artist.status = 'active';

  if not found then
    raise exception 'artist_not_found';
  end if;

  if v_key is null
     or length(v_key) > 200
  then
    raise exception 'invalid_artist_music_submission_key';
  end if;

  if p_artist_credits is null then
    p_artist_credits := '[]'::jsonb;
  end if;

  if jsonb_typeof(p_artist_credits) <> 'array'
     or jsonb_array_length(p_artist_credits) > 19
  then
    raise exception 'invalid_artist_music_credits';
  end if;

  perform pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      v_actor::text
      || '|artist-music|'
      || p_artist_id::text
      || '|'
      || v_key,
      0
    )
  );

  select suggestion.*
  into v_suggestion
  from public.registry_provider_track_suggestions suggestion
  where suggestion.intake_origin = 'artist_submission'
    and suggestion.requested_by = v_actor
    and suggestion.submitted_for_artist_id = p_artist_id
    and suggestion.artist_submission_key = v_key
  order by suggestion.created_at
  limit 1;

  if found then
    return jsonb_build_object(
      'id', v_suggestion.id,
      'artist_id', v_suggestion.submitted_for_artist_id,
      'status', v_suggestion.status,
      'track_title', v_suggestion.submitted_track_title,
      'release_title', v_suggestion.provider_release_title,
      'provider_key', v_suggestion.provider_key,
      'provider_url', v_suggestion.provider_url,
      'created_at', v_suggestion.created_at,
      'review_due_at', v_suggestion.review_due_at,
      'reviewed_at', v_suggestion.reviewed_at,
      'created', false
    );
  end if;

  select validation.*
  into v_validation
  from platform_private.artist_music_submission_validations validation
  where validation.id = p_validation_id
    and validation.requested_by = v_actor
    and validation.artist_id = p_artist_id
    and validation.representation_id = v_rep.id
    and validation.expires_at > now()
  for update;

  if not found then
    raise exception 'artist_music_validation_missing_or_expired';
  end if;

  v_review_due_at :=
    editorial.artist_music_submission_review_due_at(
      v_submitted_at
    );

  insert into public.registry_provider_track_suggestions (
    source_playlist_id,
    source_playlist_item_id,
    requested_by,
    canonical_track_id,
    registry_artist_id,
    artist_resolution_mode,
    provider_key,
    provider_object_id,
    provider_url,
    provider_title,
    provider_artist_names,
    provider_release_title,
    playback_kind,
    validation_snapshot,
    status,
    reserved_position,
    intake_origin,
    source_contribution_id,
    submitted_track_title,
    submitted_for_artist_id,
    submitted_by_representation_id,
    review_due_at,
    artist_submission_key,
    source_artist_validation_id,
    created_at,
    updated_at
  )
  values (
    null,
    null,
    v_actor,
    null,
    p_artist_id,
    'existing_artist',
    v_validation.provider_key,
    v_validation.provider_object_id,
    v_validation.provider_url,
    v_validation.provider_title,
    v_validation.provider_artist_names,
    v_validation.provider_release_title,
    v_validation.playback_kind,
    jsonb_strip_nulls(
      jsonb_build_object(
        'artist_submission_validation_id',
          v_validation.id,
        'validation_mode',
          'artist_submission',
        'checked_at',
          v_validation.checked_at,
        'artwork_url',
          v_validation.validation_snapshot
            #>> '{enrichment,track_artwork_url}',
        'preview_url',
          v_validation.validation_snapshot
            #>> '{enrichment,preview_url}',
        'provider_metadata',
          v_validation.validation_snapshot
      )
    ),
    'needs_review',
    null,
    'artist_submission',
    null,
    v_validation.provider_title,
    p_artist_id,
    v_rep.id,
    v_review_due_at,
    v_key,
    v_validation.id,
    v_submitted_at,
    v_submitted_at
  )
  returning *
  into v_suggestion;

  insert into public.registry_provider_track_suggestion_artists (
    suggestion_id,
    credit_order,
    credit_role,
    resolution_mode,
    registry_artist_id,
    observed_name
  )
  values (
    v_suggestion.id,
    1,
    'primary',
    'existing_artist',
    p_artist_id,
    v_artist.display_name
  );

  v_seen_names :=
    array[
      lower(
        btrim(v_artist.display_name)
      )
    ];

  for v_credit in
    select value
    from jsonb_array_elements(p_artist_credits)
  loop
    v_credit_role :=
      lower(
        btrim(
          coalesce(
            v_credit ->> 'credit_role',
            ''
          )
        )
      );

    v_observed_name :=
      nullif(
        btrim(
          v_credit ->> 'observed_name'
        ),
        ''
      );

    if v_credit_role not in (
      'primary',
      'featured'
    )
       or v_observed_name is null
       or length(v_observed_name) > 300
    then
      raise exception 'invalid_artist_music_credit';
    end if;

    if lower(v_observed_name) = any(v_seen_names) then
      raise exception 'duplicate_artist_music_credit';
    end if;

    v_seen_names :=
      array_append(
        v_seen_names,
        lower(v_observed_name)
      );

    v_credit_order := v_credit_order + 1;

    insert into public.registry_provider_track_suggestion_artists (
      suggestion_id,
      credit_order,
      credit_role,
      resolution_mode,
      registry_artist_id,
      observed_name
    )
    values (
      v_suggestion.id,
      v_credit_order,
      v_credit_role,
      'unresolved',
      null,
      v_observed_name
    );
  end loop;

  perform editorial.record_artist_representation_event(
    p_artist_id,
    'music_submission_created',
    null,
    v_rep.id,
    v_actor,
    jsonb_build_object(
      'registry_track_intake_id',
        v_suggestion.id,
      'provider_key',
        v_suggestion.provider_key,
      'provider_object_id',
        v_suggestion.provider_object_id,
      'review_due_at',
        v_suggestion.review_due_at
    )
  );

  return jsonb_build_object(
    'id', v_suggestion.id,
    'artist_id', v_suggestion.submitted_for_artist_id,
    'status', v_suggestion.status,
    'track_title', v_suggestion.submitted_track_title,
    'release_title', v_suggestion.provider_release_title,
    'provider_key', v_suggestion.provider_key,
    'provider_url', v_suggestion.provider_url,
    'artwork_url',
      v_suggestion.validation_snapshot
        ->> 'artwork_url',
    'created_at', v_suggestion.created_at,
    'review_due_at', v_suggestion.review_due_at,
    'reviewed_at', v_suggestion.reviewed_at,
    'created', true
  );
end;
$$;


ALTER FUNCTION "public"."community_submit_artist_music"("p_artist_id" "uuid", "p_validation_id" "uuid", "p_artist_credits" "jsonb", "p_submission_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_submit_artist_registry_correction"("p_artist_id" "uuid", "p_field_key" "text", "p_proposed_value" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_rep public.artist_representations%rowtype;
  v_artist_slug text;
  v_field_key text := lower(trim(coalesce(p_field_key, '')));
  v_proposed_value text := trim(coalesce(p_proposed_value, ''));
  v_reason text := trim(coalesce(p_reason, ''));
  v_result jsonb;
begin
  if v_actor is null then
    raise exception 'authentication_required';
  end if;

  select *
  into v_rep
  from editorial.current_artist_representation(p_artist_id);

  if v_rep.id is null
     or not v_rep.can_manage_profile
  then
    raise exception 'insufficient_artist_profile_privilege';
  end if;

  if v_field_key not in (
    'display_name',
    'artist_type',
    'origin_iso2',
    'discography',
    'credits',
    'other'
  ) then
    raise exception 'unsupported_registry_correction_field';
  end if;

  if char_length(v_proposed_value) < 1
     or char_length(v_proposed_value) > 4000
  then
    raise exception 'invalid_registry_correction_value';
  end if;

  if char_length(v_reason) < 10
     or char_length(v_reason) > 4000
  then
    raise exception 'invalid_registry_correction_reason';
  end if;

  select artist.slug
  into v_artist_slug
  from public.registry_artists artist
  where artist.id = p_artist_id
    and artist.status = 'active';

  if v_artist_slug is null then
    raise exception 'artist_not_found';
  end if;

  v_result := public.community_create_contribution(
    null,
    'artist',
    p_artist_id::text,
    v_artist_slug,
    'artist_registry_correction',
    jsonb_build_object(
      'field_key', v_field_key,
      'proposed_value', v_proposed_value,
      'reason', v_reason,
      'representation_id', v_rep.id
    )
  );

  return v_result;
end;
$$;


ALTER FUNCTION "public"."community_submit_artist_registry_correction"("p_artist_id" "uuid", "p_field_key" "text", "p_proposed_value" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_update_comment"("p_comment_id" "uuid", "p_body_markdown" "text", "p_body_plain" "text" DEFAULT NULL::"text", "p_body_html" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_comment public.community_comments%rowtype;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;

  if nullif(trim(coalesce(p_body_markdown, '')), '') is null then
    raise exception 'Comment body cannot be empty' using errcode = '22023';
  end if;

  select *
  into v_comment
  from public.community_comments
  where id = p_comment_id;

  if not found then
    raise exception 'Comment not found' using errcode = 'P0002';
  end if;

  if v_comment.author_id <> auth.uid() then
    raise exception 'Not allowed' using errcode = '42501';
  end if;

  if v_comment.deleted_at is not null or v_comment.status::text in ('deleted', 'removed', 'spam') then
    raise exception 'Comment is no longer editable' using errcode = 'P0003';
  end if;

  if v_comment.created_at < now() - interval '1 hour' then
    raise exception 'Comment edit window has expired' using errcode = 'P0004';
  end if;

  update public.community_comments
  set
    body_markdown = trim(p_body_markdown),
    body_plain = coalesce(nullif(trim(p_body_plain), ''), trim(p_body_markdown)),
    body_html = p_body_html,
    edited_at = now(),
    updated_at = now()
  where id = p_comment_id
  returning * into v_comment;

  return jsonb_build_object('comment', to_jsonb(v_comment));
end;
$$;


ALTER FUNCTION "public"."community_update_comment"("p_comment_id" "uuid", "p_body_markdown" "text", "p_body_plain" "text", "p_body_html" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_update_notification_prefs"("p_user_id" "uuid", "p_email_digest" boolean, "p_chart_alerts" boolean, "p_artist_drops" boolean, "p_reply_notifications" boolean, "p_mention_notifications" boolean, "p_follow_notifications" boolean, "p_contribution_notifications" boolean, "p_marketing_emails" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_prefs public.community_notification_preferences%rowtype;
begin
  if current_user <> 'service_role'
     and (auth.uid() is null or auth.uid() <> p_user_id)
  then
    raise exception 'Permission denied' using errcode = '42501';
  end if;

  perform public.community_ensure_user_account(p_user_id);

  insert into public.community_notification_preferences (
    user_id, email_digest, chart_alerts, artist_drops,
    reply_notifications, mention_notifications, follow_notifications,
    contribution_notifications, marketing_emails, created_at, updated_at
  ) values (
    p_user_id,
    coalesce(p_email_digest, true),
    coalesce(p_chart_alerts, true),
    coalesce(p_artist_drops, true),
    coalesce(p_reply_notifications, true),
    coalesce(p_mention_notifications, true),
    coalesce(p_follow_notifications, false),
    coalesce(p_contribution_notifications, false),
    coalesce(p_marketing_emails, false),
    now(), now()
  )
  on conflict (user_id) do update set
    email_digest = excluded.email_digest,
    chart_alerts = excluded.chart_alerts,
    artist_drops = excluded.artist_drops,
    reply_notifications = excluded.reply_notifications,
    mention_notifications = excluded.mention_notifications,
    follow_notifications = excluded.follow_notifications,
    contribution_notifications = excluded.contribution_notifications,
    marketing_emails = excluded.marketing_emails,
    updated_at = now();

  select * into v_prefs
  from public.community_notification_preferences
  where user_id = p_user_id;

  return jsonb_build_object(
    'user_id', v_prefs.user_id,
    'email_digest', coalesce(v_prefs.email_digest, true),
    'chart_alerts', coalesce(v_prefs.chart_alerts, true),
    'artist_drops', coalesce(v_prefs.artist_drops, true),
    'reply_notifications', coalesce(v_prefs.reply_notifications, true),
    'mention_notifications', coalesce(v_prefs.mention_notifications, true),
    'follow_notifications', coalesce(v_prefs.follow_notifications, false),
    'contribution_notifications', coalesce(v_prefs.contribution_notifications, false),
    'marketing_emails', coalesce(v_prefs.marketing_emails, false),
    'created_at', v_prefs.created_at,
    'updated_at', v_prefs.updated_at
  );
end;
$$;


ALTER FUNCTION "public"."community_update_notification_prefs"("p_user_id" "uuid", "p_email_digest" boolean, "p_chart_alerts" boolean, "p_artist_drops" boolean, "p_reply_notifications" boolean, "p_mention_notifications" boolean, "p_follow_notifications" boolean, "p_contribution_notifications" boolean, "p_marketing_emails" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_update_profile"("p_user_id" "uuid", "p_display_name" "text" DEFAULT NULL::"text", "p_avatar_url" "text" DEFAULT NULL::"text", "p_bio" "text" DEFAULT NULL::"text", "p_country" "text" DEFAULT NULL::"text", "p_city" "text" DEFAULT NULL::"text", "p_is_public" boolean DEFAULT NULL::boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  result jsonb;
BEGIN
  IF auth.uid() != p_user_id THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  UPDATE community_profiles
  SET
    display_name = COALESCE(p_display_name, display_name),
    avatar_url = COALESCE(p_avatar_url, avatar_url),
    bio = COALESCE(p_bio, bio),
    country = COALESCE(p_country, country),
    city = COALESCE(p_city, city),
    is_public = COALESCE(p_is_public, is_public),
    updated_at = NOW()
  WHERE user_id = p_user_id;

  SELECT jsonb_build_object(
    'user_id', p.user_id,
    'username', p.username,
    'display_name', p.display_name,
    'avatar_url', p.avatar_url,
    'bio', p.bio,
    'country', p.country,
    'city', p.city,
    'role_labels', p.role_labels,
    'trust_level', p.trust_level,
    'reputation_score', p.reputation_score,
    'comment_count', p.comment_count,
    'contribution_count', p.contribution_count,
    'is_public', p.is_public,
    'created_at', p.created_at,
    'updated_at', p.updated_at
  ) INTO result
  FROM community_profiles p
  WHERE p.user_id = p_user_id;

  RETURN result;
END;
$$;


ALTER FUNCTION "public"."community_update_profile"("p_user_id" "uuid", "p_display_name" "text", "p_avatar_url" "text", "p_bio" "text", "p_country" "text", "p_city" "text", "p_is_public" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_update_profile"("p_user_id" "uuid", "p_display_name" "text" DEFAULT NULL::"text", "p_bio" "text" DEFAULT NULL::"text", "p_country" "text" DEFAULT NULL::"text", "p_city" "text" DEFAULT NULL::"text", "p_is_public" boolean DEFAULT true, "p_avatar_url" "text" DEFAULT NULL::"text", "p_clear_avatar" boolean DEFAULT false, "p_cover_url" "text" DEFAULT NULL::"text", "p_clear_cover" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_profile public.user_profiles%rowtype;
begin
  if current_user <> 'service_role'
     and (auth.uid() is null or auth.uid() <> p_user_id)
  then
    raise exception 'Permission denied' using errcode = '42501';
  end if;

  perform public.community_ensure_user_account(p_user_id);

  update public.user_profiles
  set
    display_name = p_display_name,
    bio = p_bio,
    country = p_country,
    city = p_city,
    is_public = coalesce(p_is_public, true),
    avatar_url = case
      when coalesce(p_clear_avatar, false) then null
      when p_avatar_url is not null then p_avatar_url
      else avatar_url
    end,
    cover_url = case
      when coalesce(p_clear_cover, false) then null
      when p_cover_url is not null then p_cover_url
      else cover_url
    end,
    updated_at = now()
  where user_id = p_user_id
  returning * into v_profile;

  if not found then
    raise exception 'profile % not found', p_user_id;
  end if;

  return public.community_profile_json(v_profile);
end;
$$;


ALTER FUNCTION "public"."community_update_profile"("p_user_id" "uuid", "p_display_name" "text", "p_bio" "text", "p_country" "text", "p_city" "text", "p_is_public" boolean, "p_avatar_url" "text", "p_clear_avatar" boolean, "p_cover_url" "text", "p_clear_cover" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_update_username"("p_username" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_user_id uuid;
  v_username text;
  v_profile public.user_profiles%rowtype;
  v_old_username text;
  v_old_username_normalized text;
  v_is_admin boolean;
  v_person_resource_id uuid;
  v_path_holder_resource_id uuid;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception
      'authentication required';
  end if;

  perform public.community_ensure_user_account(
    v_user_id
  );

  v_username :=
    public.community_normalize_username(
      p_username
    );

  if v_username is null
     or not public.community_username_is_valid(
       v_username
     )
  then
    raise exception
      'invalid handle: use 3-30 lowercase letters, numbers, and underscores; start and end with a letter or number';
  end if;

  if public.community_username_is_reserved(
       v_username
     )
  then
    raise exception
      'handle % is reserved',
      v_username;
  end if;

  v_is_admin :=
    public.current_user_is_administrator();

  select profile.*
  into v_profile
  from public.user_profiles profile
  where profile.user_id = v_user_id
  for update;

  if not found then
    raise exception
      'profile % not found',
      v_user_id;
  end if;

  if v_profile.username_normalized =
     v_username
  then
    return jsonb_build_object(
      'changed', false,
      'profile',
        public.community_profile_json(
          v_profile
        )
    );
  end if;

  if not v_is_admin
     and coalesce(
       v_profile.username_change_count,
       0
     ) > 0
     and v_profile.username_updated_at is not null
     and v_profile.username_updated_at >
         now() - interval '14 days'
  then
    raise exception
      'handle can only be changed once every 14 days';
  end if;

  if exists (
    select 1
    from public.user_profiles profile
    where profile.username_normalized =
          v_username
      and profile.user_id <> v_user_id
  )
  then
    raise exception
      'handle % is already taken',
      v_username;
  end if;

  if exists (
    select 1
    from public.user_profile_username_history history
    where history.old_username_normalized =
          v_username
      and history.user_id <> v_user_id
      and history.created_at >
          now() - interval '30 days'
  )
  then
    raise exception
      'handle % was recently released and is temporarily protected',
      v_username;
  end if;

  select link.person_resource_id
  into v_person_resource_id
  from editorial.person_identity_links link
  where link.user_id = v_user_id
    and link.link_state = 'active'
  limit 1;

  if v_person_resource_id is not null then
    select resolved.person_resource_id
    into v_person_resource_id
    from editorial.resolve_person_follow_target(
      v_person_resource_id
    ) resolved;
  end if;

  select alias.resource_id
  into v_path_holder_resource_id
  from editorial.resource_aliases alias
  where alias.path =
        '/people/' || v_username;

  if found
     and (
       v_person_resource_id is null
       or v_path_holder_resource_id <>
          v_person_resource_id
     )
  then
    raise exception
      'handle % is permanently reserved by another Person route',
      v_username;
  end if;

  v_old_username :=
    v_profile.username;
  v_old_username_normalized :=
    v_profile.username_normalized;

  update public.user_profiles profile
  set
    username = v_username,
    username_normalized = v_username,
    username_updated_at = now(),
    username_change_count =
      coalesce(
        profile.username_change_count,
        0
      ) + 1,
    updated_at = now()
  where profile.user_id = v_user_id
  returning profile.*
  into v_profile;

  insert into public.user_profile_username_history (
    user_id,
    old_username,
    old_username_normalized,
    new_username,
    new_username_normalized,
    changed_by,
    change_reason
  )
  values (
    v_user_id,
    v_old_username,
    v_old_username_normalized,
    v_profile.username,
    v_profile.username_normalized,
    v_user_id,
    'user_update'
  );

  return jsonb_build_object(
    'changed', true,
    'profile',
      public.community_profile_json(
        v_profile
      )
  );
end;
$$;


ALTER FUNCTION "public"."community_update_username"("p_username" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_username_available"("p_username" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_username text;
  v_existing_user_id uuid;
  v_current_user_id uuid := auth.uid();
  v_current_person_resource_id uuid;
  v_path_holder_resource_id uuid;
begin
  v_username :=
    public.community_normalize_username(
      p_username
    );

  if v_username is null
     or not public.community_username_is_valid(
       v_username
     )
  then
    return jsonb_build_object(
      'available', false,
      'normalized', v_username,
      'reason', 'invalid_format',
      'message', 'Use 3-30 lowercase letters, numbers, and underscores. Start and end with a letter or number.'
    );
  end if;

  if public.community_username_is_reserved(
       v_username
     )
  then
    return jsonb_build_object(
      'available', false,
      'normalized', v_username,
      'reason', 'reserved',
      'message', 'That handle is reserved.'
    );
  end if;

  select profile.user_id
  into v_existing_user_id
  from public.user_profiles profile
  where profile.username_normalized =
        v_username;

  if found
     and v_existing_user_id = v_current_user_id
  then
    return jsonb_build_object(
      'available', true,
      'normalized', v_username,
      'reason', 'current',
      'message', 'This is your current handle.'
    );
  end if;

  if found then
    return jsonb_build_object(
      'available', false,
      'normalized', v_username,
      'reason', 'taken',
      'message', 'That handle is already taken.'
    );
  end if;

  if v_current_user_id is not null then
    select link.person_resource_id
    into v_current_person_resource_id
    from editorial.person_identity_links link
    where link.user_id = v_current_user_id
      and link.link_state = 'active'
    limit 1;

    if v_current_person_resource_id is not null then
      select resolved.person_resource_id
      into v_current_person_resource_id
      from editorial.resolve_person_follow_target(
        v_current_person_resource_id
      ) resolved;
    end if;
  end if;

  select alias.resource_id
  into v_path_holder_resource_id
  from editorial.resource_aliases alias
  where alias.path =
        '/people/' || v_username;

  if found
     and (
       v_current_person_resource_id is null
       or v_path_holder_resource_id <>
          v_current_person_resource_id
     )
  then
    return jsonb_build_object(
      'available', false,
      'normalized', v_username,
      'reason', 'person_path_reserved',
      'message', 'That handle is permanently reserved by another Person route.'
    );
  end if;

  if exists (
    select 1
    from public.user_profile_username_history history
    where history.old_username_normalized =
          v_username
      and history.user_id <>
          coalesce(
            v_current_user_id,
            '00000000-0000-0000-0000-000000000000'::uuid
          )
      and history.created_at >
          now() - interval '30 days'
  )
  then
    return jsonb_build_object(
      'available', false,
      'normalized', v_username,
      'reason', 'recently_released',
      'message', 'That handle was recently released and is temporarily protected.'
    );
  end if;

  return jsonb_build_object(
    'available', true,
    'normalized', v_username,
    'reason', 'available',
    'message', 'Handle available.'
  );
end;
$$;


ALTER FUNCTION "public"."community_username_available"("p_username" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_username_is_reserved"("p_username" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
  select
    exists (
      select 1
      from public.community_reserved_usernames reserved
      where reserved.username =
            public.community_normalize_username(
              p_username
            )
    )
    or editorial.username_is_registry_artist_reserved(
      p_username
    );
$$;


ALTER FUNCTION "public"."community_username_is_reserved"("p_username" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_username_seed"("p_seed" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $_$
declare
  v_seed text;
begin
  v_seed := lower(coalesce(p_seed, ''));
  v_seed := regexp_replace(v_seed, '[^a-z0-9_]+', '_', 'g');
  v_seed := regexp_replace(v_seed, '_+', '_', 'g');
  v_seed := trim(both '_' from v_seed);

  if length(coalesce(v_seed, '')) < 3 then
    v_seed := 'user';
  end if;

  v_seed := left(v_seed, 24);
  v_seed := trim(both '_' from v_seed);

  if length(coalesce(v_seed, '')) < 3 then
    v_seed := 'user';
  end if;

  if v_seed !~ '^[a-z0-9]' then
    v_seed := 'user' || v_seed;
  end if;

  if v_seed !~ '[a-z0-9]$' then
    v_seed := v_seed || 'user';
  end if;

  return left(v_seed, 24);
end;
$_$;


ALTER FUNCTION "public"."community_username_seed"("p_seed" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_vote_comment"("p_comment_id" "uuid", "p_vote_value" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_existing integer;
  v_current integer;
  v_upvote_count integer;
  v_downvote_count integer;
  v_score integer;
begin
  if v_user_id is null then
    raise exception
      'Not authenticated'
      using errcode = '42501';
  end if;

  if p_vote_value not in (-1, 1) then
    raise exception
      'Invalid vote value'
      using errcode = '22023';
  end if;

  perform 1
  from public.community_comments comment
  where comment.id = p_comment_id
  for update;

  if not found then
    raise exception
      'Comment not found'
      using errcode = '22023';
  end if;

  select vote.vote_value
  into v_existing
  from public.community_votes vote
  where vote.user_id = v_user_id
    and vote.comment_id = p_comment_id;

  if v_existing is null then
    insert into public.community_votes (
      user_id,
      comment_id,
      vote_value
    )
    values (
      v_user_id,
      p_comment_id,
      p_vote_value
    );

    v_current := p_vote_value;

  elsif v_existing = p_vote_value then
    delete from public.community_votes
    where user_id = v_user_id
      and comment_id = p_comment_id;

    v_current := 0;

  else
    update public.community_votes
    set
      vote_value = p_vote_value,
      updated_at = now()
    where user_id = v_user_id
      and comment_id = p_comment_id;

    v_current := p_vote_value;
  end if;

  select
    count(*) filter (
      where vote.vote_value = 1
    )::integer,
    count(*) filter (
      where vote.vote_value = -1
    )::integer,
    coalesce(
      sum(vote.vote_value),
      0
    )::integer
  into
    v_upvote_count,
    v_downvote_count,
    v_score
  from public.community_votes vote
  where vote.comment_id = p_comment_id;

  update public.community_comments
  set
    upvote_count = v_upvote_count,
    downvote_count = v_downvote_count,
    score = v_score
  where id = p_comment_id;

  return jsonb_build_object(
    'vote_value',
      v_current,
    'existing',
      v_existing,
    'delta',
      v_current - coalesce(
        v_existing,
        0
      ),
    'upvote_count',
      v_upvote_count,
    'downvote_count',
      v_downvote_count,
    'score',
      v_score
  );
end;
$$;


ALTER FUNCTION "public"."community_vote_comment"("p_comment_id" "uuid", "p_vote_value" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_withdraw_artist_claim"("p_claim_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_claim public.artist_claim_requests%rowtype;
  v_reason text :=
    nullif(
      trim(
        coalesce(
          p_reason,
          ''
        )
      ),
      ''
    );
begin
  if v_actor is null then
    raise exception
      'authentication_required';
  end if;

  select *
  into v_claim
  from public.artist_claim_requests
  where id = p_claim_id
  for update;

  if not found
     or v_claim.claimant_user_id
        is distinct from v_actor
  then
    raise exception
      'claim_not_found';
  end if;

  if v_claim.status <> 'pending' then
    raise exception
      'claim_not_pending';
  end if;

  update public.artist_claim_requests
  set
    status = 'withdrawn',
    decision_reason =
      coalesce(
        v_reason,
        'Withdrawn by claimant'
      ),
    updated_at = now()
  where id = p_claim_id;

  perform editorial.record_artist_representation_event(
    v_claim.artist_id,
    'claim_withdrawn',
    v_claim.id,
    null,
    v_actor,
    jsonb_build_object(
      'reason',
      coalesce(
        v_reason,
        'Withdrawn by claimant'
      )
    )
  );

  perform editorial.sync_artist_portal_roles(
    v_actor
  );

  return jsonb_build_object(
    'claim_id',
      p_claim_id,
    'status',
      'withdrawn'
  );
end;
$$;


ALTER FUNCTION "public"."community_withdraw_artist_claim"("p_claim_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_withdraw_artist_update"("p_update_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_rep public.artist_representations%rowtype;
  v_reason text := btrim(coalesce(p_reason, ''));
  v_update public.artist_updates%rowtype;
begin
  if v_actor is null then
    raise exception 'authentication_required';
  end if;

  select *
  into v_update
  from public.artist_updates
  where id = p_update_id
  for update;

  if not found then
    raise exception 'artist_update_not_found';
  end if;

  if v_update.status <> 'published' then
    raise exception 'artist_update_not_withdrawable';
  end if;

  select *
  into v_rep
  from editorial.current_artist_representation(v_update.artist_id);

  if v_rep.id is null
     or not v_rep.can_post_updates
  then
    raise exception 'insufficient_artist_update_privilege';
  end if;

  if char_length(v_reason) < 3
     or char_length(v_reason) > 1000
  then
    raise exception 'invalid_artist_update_withdrawal_reason';
  end if;

  update public.artist_updates
  set
    status = 'withdrawn',
    withdrawn_at = now(),
    updated_at = now()
  where id = p_update_id
  returning *
  into v_update;

  perform editorial.record_artist_representation_event(
    v_update.artist_id,
    'artist_update_withdrawn',
    null,
    v_rep.id,
    v_actor,
    jsonb_build_object(
      'artist_update_id', v_update.id,
      'reason', v_reason,
      'withdrawn_at', v_update.withdrawn_at
    )
  );

  return jsonb_build_object(
    'id', v_update.id,
    'status', v_update.status,
    'withdrawn_at', v_update.withdrawn_at
  );
end;
$$;


ALTER FUNCTION "public"."community_withdraw_artist_update"("p_update_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_media_processing_job_v1"("p_job_id" "uuid", "p_worker_id" "text", "p_result" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'auth', 'platform_private'
    AS $$
declare
  v_receipt_id uuid;
  v_event_id uuid;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception
      using
        errcode = '42501',
        message = 'Service-role access is required.';
  end if;

  if not exists (
    select 1
    from platform_private.jobs job
    where job.id = p_job_id
      and job.command_type = 'media.process_revision'
      and job.job_type = 'media.process_revision'
  ) then
    raise exception
      'Requested job is not a Media processing job.';
  end if;

  select
    command_receipt_id,
    success_event_id
  into
    v_receipt_id,
    v_event_id
  from platform_private.complete_job(
    p_job_id,
    p_worker_id,
    coalesce(p_result, '{}'::jsonb)
  );

  return jsonb_build_object(
    'job_id', p_job_id,
    'command_receipt_id', v_receipt_id,
    'success_event_id', v_event_id,
    'job_status', 'succeeded'
  );
end;
$$;


