CREATE TABLE IF NOT EXISTS "public"."registry_entity_relationships" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "source_entity_type" "text" NOT NULL,
    "source_slug" "text" NOT NULL,
    "target_entity_type" "text" NOT NULL,
    "target_slug" "text" NOT NULL,
    "relationship_type" "text" NOT NULL,
    "relationship_role" "text",
    "relationship_status" "text" DEFAULT 'active'::"text" NOT NULL,
    "source_kind" "text",
    "source_entity" "text",
    "source_record_id" "text",
    "source_staging_record_id" "uuid",
    "confidence" numeric,
    "sort_order" integer,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "source_entity_id" "uuid",
    "target_entity_id" "uuid",
    "plain_reason" "text",
    "review_status" "text" DEFAULT 'unreviewed'::"text" NOT NULL,
    "public_safe" boolean DEFAULT false NOT NULL,
    "valid_from" "date",
    "valid_to" "date",
    "reviewed_by" "uuid",
    "reviewed_at" timestamp with time zone,
    "review_note" "text",
    "status_reason" "text",
    "superseded_by_relationship_id" "uuid",
    "created_by" "uuid",
    "updated_by" "uuid",
    CONSTRAINT "registry_entity_relationships_public_safe_check" CHECK ((("public_safe" = false) OR (("review_status" = 'approved'::"text") AND ("relationship_status" = 'active'::"text") AND ("reviewed_at" IS NOT NULL)))),
    CONSTRAINT "registry_entity_relationships_review_fields_check" CHECK ((("review_status" <> ALL (ARRAY['approved'::"text", 'rejected'::"text", 'disputed'::"text", 'superseded'::"text"])) OR ("reviewed_at" IS NOT NULL))),
    CONSTRAINT "registry_entity_relationships_review_status_check" CHECK (("review_status" = ANY (ARRAY['unreviewed'::"text", 'pending_review'::"text", 'approved'::"text", 'rejected'::"text", 'disputed'::"text", 'superseded'::"text"]))),
    CONSTRAINT "registry_entity_relationships_status_check" CHECK (("relationship_status" = ANY (ARRAY['active'::"text", 'draft'::"text", 'needs_review'::"text", 'archived'::"text"]))),
    CONSTRAINT "registry_entity_relationships_supersession_check" CHECK ((("review_status" <> 'superseded'::"text") OR ("superseded_by_relationship_id" IS NOT NULL))),
    CONSTRAINT "registry_entity_relationships_valid_period_check" CHECK ((("valid_to" IS NULL) OR ("valid_from" IS NULL) OR ("valid_to" >= "valid_from")))
);


