COMMENT ON TABLE "public"."registry_entity_relationships" IS 'Registry-owned flexible cultural relationship graph. Typed structural relationships remain authoritative in their dedicated Registry join tables.';



COMMENT ON COLUMN "public"."registry_entity_relationships"."source_entity_id" IS 'Canonical Registry entity UUID where the typed source table exposes one. Slug remains for compatibility.';



COMMENT ON COLUMN "public"."registry_entity_relationships"."target_entity_id" IS 'Canonical Registry entity UUID where the typed target table exposes one. Slug remains for compatibility.';



COMMENT ON COLUMN "public"."registry_entity_relationships"."plain_reason" IS 'Plain-language explanation of why the relationship is asserted.';



COMMENT ON COLUMN "public"."registry_entity_relationships"."review_status" IS 'Human review state, separate from relationship lifecycle status.';



COMMENT ON COLUMN "public"."registry_entity_relationships"."public_safe" IS 'True only when an approved relationship may be used on public surfaces.';



CREATE OR REPLACE FUNCTION "public"."complete_registry_relationship_review"("p_relationship_id" "uuid", "p_evidence_title" "text", "p_evidence_type" "text", "p_source_url" "text", "p_evidence_summary" "text", "p_evidence_main_claim" "text", "p_reliability" "text", "p_confidence" "text", "p_plain_reason" "text", "p_review_reason" "text", "p_next_review_status" "text", "p_public_safe" boolean) RETURNS "public"."registry_entity_relationships"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$ declare v_evidence_id uuid; v_relationship public.registry_entity_relationships; v_evidence_review_status text; v_retrieval_status text; begin if not (auth.role()='service_role' or public.institute_can_review() or public.current_user_has_capability('manage_registry') or public.current_user_has_capability('manage_review_queue') or public.current_user_is_administrator()) then raise exception 'You do not have permission to review Registry relationships.'; end if; if p_next_review_status not in ('pending_review','approved','rejected','disputed') then raise exception 'Choose a supported review decision.'; end if; if nullif(btrim(p_plain_reason),'') is null then raise exception 'A plain-language explanation is required.'; end if; if nullif(btrim(p_review_reason),'') is null then raise exception 'A review reason is required.'; end if; if p_public_safe and p_next_review_status<>'approved' then raise exception 'Only approved relationships can be marked public-safe.'; end if; select * into v_relationship from public.registry_entity_relationships where id=p_relationship_id for update; if not found then raise exception 'Registry relationship not found.'; end if; if v_relationship.source_entity_id is null or v_relationship.target_entity_id is null then raise exception 'Resolve both relationship endpoints before review.'; end if; if p_next_review_status in ('approved','pending_review') then if nullif(btrim(p_evidence_title),'') is null or nullif(btrim(p_evidence_summary),'') is null then raise exception 'Evidence title and summary are required.'; end if; if p_evidence_type not in ('article','official_documentation','academic_paper','release_metadata','track_metadata','artist_metadata','interview','video','screenshot','field_note','book_reference','chart_record') then raise exception 'Choose a supported evidence type.'; end if; if p_reliability not in ('low','medium','high') or p_confidence not in ('low','medium','high') then raise exception 'Choose a valid reliability and confidence level.'; end if; v_evidence_review_status:=case when p_next_review_status='approved' then 'approved' else 'reviewed' end; v_retrieval_status:=case when p_public_safe then 'default_retrieval' else 'review_only' end; insert into public.evidence_items(title,evidence_type,source_url,summary,main_claim,why_it_matters,reliability,confidence,review_status,retrieval_status,created_by,reviewed_by,reviewed_at) values(btrim(p_evidence_title),p_evidence_type,nullif(btrim(p_source_url),''),btrim(p_evidence_summary),nullif(btrim(p_evidence_main_claim),''),'Supports the reviewed Registry relationship '||p_relationship_id::text||'.',p_reliability,p_confidence,v_evidence_review_status,v_retrieval_status,auth.uid(),auth.uid(),now()) returning id into v_evidence_id; insert into public.registry_relationship_evidence(relationship_id,evidence_id,support_type,note,created_by) values(p_relationship_id,v_evidence_id,'supports',btrim(p_review_reason),auth.uid()); end if; update public.registry_entity_relationships set plain_reason=btrim(p_plain_reason),public_safe=false,updated_by=auth.uid(),updated_at=now() where id=p_relationship_id; select * into v_relationship from public.review_registry_relationship(p_relationship_id,p_next_review_status,p_public_safe,btrim(p_review_reason)); return v_relationship; end; $$;


ALTER FUNCTION "public"."complete_registry_relationship_review"("p_relationship_id" "uuid", "p_evidence_title" "text", "p_evidence_type" "text", "p_source_url" "text", "p_evidence_summary" "text", "p_evidence_main_claim" "text", "p_reliability" "text", "p_confidence" "text", "p_plain_reason" "text", "p_review_reason" "text", "p_next_review_status" "text", "p_public_safe" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."complete_registry_relationship_review"("p_relationship_id" "uuid", "p_evidence_title" "text", "p_evidence_type" "text", "p_source_url" "text", "p_evidence_summary" "text", "p_evidence_main_claim" "text", "p_reliability" "text", "p_confidence" "text", "p_plain_reason" "text", "p_review_reason" "text", "p_next_review_status" "text", "p_public_safe" boolean) IS 'Creates reviewed supporting evidence, saves the final plain-language explanation, and records one explicit human relationship review decision.';



CREATE OR REPLACE FUNCTION "public"."confirm_playlist_playback_validation"("p_validation_id" "uuid", "p_requested_by" "uuid", "p_playlist_id" "uuid", "p_probe_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'platform_private'
    AS $$
declare
  v_validation
    platform_private.playlist_playback_validations%rowtype;
begin
  select validation.*
  into v_validation
  from platform_private.playlist_playback_validations validation
  where validation.id = p_validation_id
    and validation.requested_by = p_requested_by
    and validation.playlist_id = p_playlist_id
  for update;

  if not found then
    raise exception
      'Playback probe candidate does not exist for this editor and Playlist';
  end if;

  if v_validation.validation_status = 'playable'
     and v_validation.playable
     and v_validation.expires_at > now()
  then
    return jsonb_build_object(
      'validation_id', v_validation.id,
      'validation_status', 'playable',
      'playback_kind', v_validation.playback_kind,
      'expires_at', v_validation.expires_at,
      'idempotent_replay', true
    );
  end if;

  if v_validation.validation_status <> 'probe_required'
     or v_validation.playable
     or v_validation.expires_at <= now()
  then
    raise exception
      'Playback probe candidate is no longer confirmable';
  end if;

  if p_probe_metadata is null
     or jsonb_typeof(p_probe_metadata) <> 'object'
     or p_probe_metadata ->> 'result' <> 'iframe_cued'
  then
    raise exception
      'Confirmed browser playback probe result is required';
  end if;

  update platform_private.playlist_playback_validations validation
  set
    playable = true,
    validation_status = 'playable',
    checked_at = now(),
    expires_at = now() + interval '30 minutes',
    provider_metadata =
      coalesce(validation.provider_metadata, '{}'::jsonb)
      || jsonb_build_object(
        'browser_probe',
        p_probe_metadata
      )
  where validation.id = v_validation.id
  returning validation.*
  into v_validation;

  return jsonb_build_object(
    'validation_id', v_validation.id,
    'validation_status', v_validation.validation_status,
    'playback_kind', v_validation.playback_kind,
    'expires_at', v_validation.expires_at,
    'idempotent_replay', false
  );
end;
$$;


ALTER FUNCTION "public"."confirm_playlist_playback_validation"("p_validation_id" "uuid", "p_requested_by" "uuid", "p_playlist_id" "uuid", "p_probe_metadata" "jsonb") OWNER TO "postgres";


