CREATE OR REPLACE FUNCTION "public"."create_article"("p_title" "text", "p_slug" "text", "p_status" "text" DEFAULT 'draft'::"text", "p_author" "text" DEFAULT NULL::"text", "p_excerpt" "text" DEFAULT NULL::"text", "p_content_html" "text" DEFAULT NULL::"text", "p_hero_image_url" "text" DEFAULT NULL::"text", "p_categories" "jsonb" DEFAULT '[]'::"jsonb", "p_tags" "jsonb" DEFAULT '[]'::"jsonb", "p_seo" "jsonb" DEFAULT '{}'::"jsonb", "p_published_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("id" "uuid", "slug" "text", "title" "text", "wp_status" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "row_security" TO 'off'
    AS $$
DECLARE
  v_user_id uuid;
  v_article_id uuid;
  v_can_insert boolean;
BEGIN
  v_user_id := auth.uid();

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Check if user can create articles (admin or has edit_own_articles)
  v_can_insert := EXISTS (
    SELECT 1 FROM user_role_assignments
    WHERE user_id = v_user_id
      AND status = 'active'
      AND (expires_at IS NULL OR expires_at > now())
      AND (
        role_key = 'administrator'
        OR role_key IN (
          SELECT role_key FROM role_capabilities
          WHERE capability_key = 'edit_own_articles'
        )
      )
  );

  IF NOT v_can_insert THEN
    RAISE EXCEPTION 'Permission denied: edit_own_articles capability required';
  END IF;

  -- Check for slug collision
  IF EXISTS (SELECT 1 FROM wk_articles WHERE wk_articles.slug = p_slug) THEN
    RAISE EXCEPTION 'Slug "%" already exists', p_slug;
  END IF;

  -- Insert the article
  INSERT INTO wk_articles (
    slug, title, wp_status, author, excerpt, content_html,
    hero_image_url, categories, tags, seo, published_at,
    created_at, updated_at
  ) VALUES (
    p_slug, p_title, COALESCE(p_status, 'draft'), p_author, p_excerpt, p_content_html,
    p_hero_image_url, COALESCE(p_categories, '[]'::jsonb), COALESCE(p_tags, '[]'::jsonb), COALESCE(p_seo, '{}'::jsonb), p_published_at,
    now(), now()
  )
  RETURNING wk_articles.id INTO v_article_id;

  RETURN QUERY
  SELECT wk_articles.id, wk_articles.slug, wk_articles.title, wk_articles.wp_status, wk_articles.created_at
  FROM wk_articles
  WHERE wk_articles.id = v_article_id;
END;
$$;


ALTER FUNCTION "public"."create_article"("p_title" "text", "p_slug" "text", "p_status" "text", "p_author" "text", "p_excerpt" "text", "p_content_html" "text", "p_hero_image_url" "text", "p_categories" "jsonb", "p_tags" "jsonb", "p_seo" "jsonb", "p_published_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_article_autosave"("p_article_id" "uuid", "p_payload" "jsonb", "p_expected_draft_version" bigint) RETURNS TABLE("version_id" "uuid", "version_number" bigint, "source_draft_version" bigint, "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  current_article public.wk_articles%rowtype;
  current_resource editorial.resources%rowtype;
  new_version_id uuid;
  new_version_number bigint;
  new_created_at timestamptz;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  if p_payload is null
     or jsonb_typeof(p_payload) <> 'object'
  then
    raise exception 'Autosave payload must be a JSON object';
  end if;

  select article.*
  into current_article
  from public.wk_articles article
  where article.id = p_article_id;

  if not found then
    raise exception 'Article not found';
  end if;

  select resource.*
  into current_resource
  from editorial.article_resources binding
  join editorial.resources resource
    on resource.id = binding.resource_id
  where binding.article_id = p_article_id
  for update of resource;

  if not found then
    raise exception 'Article resource identity not found';
  end if;

  if not editorial.current_user_can_edit_article(
    current_resource.id
  ) then
    raise exception 'Permission denied';
  end if;

  if p_expected_draft_version is null
     or current_article.draft_version
        <> p_expected_draft_version
  then
    raise exception
      'STALE_ARTICLE_VERSION: expected %, current %',
      p_expected_draft_version,
      current_article.draft_version;
  end if;

  new_version_number :=
    editorial.next_article_version_number(
      current_resource.id
    );

  insert into editorial.article_versions (
    resource_id,
    article_id,
    version_number,
    version_kind,
    source_draft_version,
    title,
    slug,
    excerpt,
    content_html,
    author_display,
    owner_id,
    hero_image_id,
    hero_image_url,
    seo,
    lifecycle_state,
    wp_status,
    published_at,
    category_snapshot,
    tag_snapshot,
    created_by,
    content_fingerprint
  )
  values (
    current_resource.id,
    current_article.id,
    new_version_number,
    'autosave',
    current_article.draft_version,
    case
      when p_payload ? 'title'
        then p_payload ->> 'title'
      else current_article.title
    end,
    current_article.slug,
    case
      when p_payload ? 'excerpt'
        then p_payload ->> 'excerpt'
      else current_article.excerpt
    end,
    case
      when p_payload ? 'content_html'
        then p_payload ->> 'content_html'
      else current_article.content_html
    end,
    case
      when p_payload ? 'author'
        then p_payload ->> 'author'
      else current_article.author
    end,
    current_resource.owner_id,
    current_article.hero_image_id,
    current_article.hero_image_url,
    case
      when p_payload ? 'seo'
        then coalesce(
          p_payload -> 'seo',
          '{}'::jsonb
        )
      else current_article.seo
    end,
    current_resource.lifecycle_state,
    current_article.wp_status,
    current_article.published_at,
    current_article.categories,
    current_article.tags,
    auth.uid(),
    editorial.article_snapshot_fingerprint(
      case
        when p_payload ? 'title'
          then p_payload ->> 'title'
        else current_article.title
      end,
      current_article.slug,
      case
        when p_payload ? 'excerpt'
          then p_payload ->> 'excerpt'
        else current_article.excerpt
      end,
      case
        when p_payload ? 'content_html'
          then p_payload ->> 'content_html'
        else current_article.content_html
      end,
      case
        when p_payload ? 'author'
          then p_payload ->> 'author'
        else current_article.author
      end,
      current_article.hero_image_id,
      current_article.hero_image_url,
      case
        when p_payload ? 'seo'
          then coalesce(
            p_payload -> 'seo',
            '{}'::jsonb
          )
        else current_article.seo
      end,
      current_article.wp_status,
      current_article.published_at,
      current_article.categories,
      current_article.tags
    )
  )
  returning
    id,
    editorial.article_versions.created_at
  into
    new_version_id,
    new_created_at;

  delete from editorial.article_versions old_version
  where old_version.resource_id = current_resource.id
    and old_version.version_kind = 'autosave'
    and old_version.created_by = auth.uid()
    and old_version.id not in (
      select retained.id
      from editorial.article_versions retained
      where retained.resource_id =
        current_resource.id
        and retained.version_kind =
          'autosave'
        and retained.created_by =
          auth.uid()
      order by retained.created_at desc
      limit 20
    );

  version_id := new_version_id;
  version_number := new_version_number;
  source_draft_version :=
    current_article.draft_version;
  created_at := new_created_at;

  return next;
end;
$$;


ALTER FUNCTION "public"."create_article_autosave"("p_article_id" "uuid", "p_payload" "jsonb", "p_expected_draft_version" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_article_preview_link"("p_article_id" "uuid", "p_version_id" "uuid" DEFAULT NULL::"uuid", "p_expires_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("nonce" "text", "expires_at" timestamp with time zone, "version_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'editorial', 'pg_temp'
    AS $$
declare
  v_version editorial.article_versions%rowtype;
  v_nonce uuid := gen_random_uuid();
  v_expires_at timestamptz := coalesce(
    p_expires_at,
    now() + interval '7 days'
  );
begin
  if auth.uid() is null then
    raise exception 'authentication required';
  end if;

  if p_article_id is null then
    raise exception 'article id is required';
  end if;

  if v_expires_at <= now() then
    raise exception 'preview expiry must be in the future';
  end if;

  if p_version_id is null then
    select version.*
      into v_version
    from editorial.article_versions version
    where version.article_id = p_article_id
    order by version.version_number desc
    limit 1;
  else
    select version.*
      into v_version
    from editorial.article_versions version
    where version.id = p_version_id
      and version.article_id = p_article_id
    limit 1;
  end if;

  if v_version.id is null then
    raise exception 'article version not found';
  end if;

  insert into public.wk_article_preview_links (
    nonce,
    article_id,
    version_id,
    created_by,
    expires_at
  )
  values (
    v_nonce::text,
    p_article_id,
    v_version.id,
    auth.uid(),
    v_expires_at
  );

  update public.wk_articles article
     set preview_nonce = v_nonce,
         preview_nonce_expires_at = v_expires_at,
         updated_at = now()
   where article.id = p_article_id;

  return query
  select
    v_nonce::text,
    v_expires_at,
    v_version.id;
end;
$$;


ALTER FUNCTION "public"."create_article_preview_link"("p_article_id" "uuid", "p_version_id" "uuid", "p_expires_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_article_preview_link"("p_article_id" "uuid", "p_version_id" "uuid", "p_expires_at" timestamp with time zone) IS 'Creates a preview nonce for an immutable article version and stores the legacy article nonce as uuid.';



CREATE OR REPLACE FUNCTION "public"."create_article_suggestion"("p_article_id" "uuid", "p_target_version_id" "uuid", "p_target_version_fingerprint" "text", "p_anchor_from" integer, "p_anchor_to" integer, "p_anchor_quote" "text", "p_anchor_prefix" "text", "p_anchor_suffix" "text", "p_operation_kind" "text", "p_original_text" "text", "p_replacement_text" "text", "p_proposed_content_html" "text", "p_comment" "text" DEFAULT NULL::"text") RETURNS TABLE("created_thread_id" "uuid", "created_suggestion_id" "uuid", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_article public.wk_articles%rowtype;
  v_resource editorial.resources%rowtype;
  v_version editorial.article_versions%rowtype;
  v_thread_id uuid;
  v_suggestion_id uuid;
  v_created_at timestamptz;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  if p_proposed_content_html is null then
    raise exception 'Proposed Article content is required';
  end if;

  select article.*
  into v_article
  from public.wk_articles article
  where article.id = p_article_id;

  if not found then
    raise exception 'Article not found';
  end if;

  select resource.*
  into v_resource
  from editorial.article_resources binding
  join editorial.resources resource
    on resource.id = binding.resource_id
  where binding.article_id = p_article_id
  for update of resource;

  if not found then
    raise exception 'Article resource identity not found';
  end if;

  if not editorial.current_user_can_participate_article_review(
    v_resource.id
  ) then
    raise exception 'Permission denied';
  end if;

  if v_article.wp_status <> 'pending' then
    raise exception
      'Suggestions require an Article that is pending review';
  end if;

  if v_resource.current_submitted_version_id
     is distinct from p_target_version_id
  then
    raise exception
      'Suggestion target is not the current submitted Article version';
  end if;

  select version.*
  into v_version
  from editorial.article_versions version
  where version.id = p_target_version_id
    and version.article_id = p_article_id
    and version.resource_id = v_resource.id
    and version.version_kind = 'submitted';

  if not found then
    raise exception
      'Submitted Article version not found';
  end if;

  if v_version.content_fingerprint
     <> p_target_version_fingerprint
  then
    raise exception
      'Suggestion target fingerprint is stale';
  end if;

  insert into editorial.article_review_threads (
    resource_id,
    article_id,
    target_version_id,
    thread_kind,
    target_field,
    anchor_kind,
    anchor_from,
    anchor_to,
    anchor_quote,
    anchor_prefix,
    anchor_suffix
  )
  values (
    v_resource.id,
    p_article_id,
    p_target_version_id,
    'suggestion',
    'content_html',
    'text_range',
    p_anchor_from,
    p_anchor_to,
    coalesce(p_anchor_quote, ''),
    coalesce(p_anchor_prefix, ''),
    coalesce(p_anchor_suffix, '')
  )
  returning
    id,
    article_review_threads.created_at
  into
    v_thread_id,
    v_created_at;

  insert into editorial.article_suggestions (
    thread_id,
    operation_kind,
    original_text,
    replacement_text,
    proposed_content_html,
    target_version_fingerprint
  )
  values (
    v_thread_id,
    p_operation_kind,
    coalesce(p_original_text, ''),
    coalesce(p_replacement_text, ''),
    p_proposed_content_html,
    p_target_version_fingerprint
  )
  returning id
  into v_suggestion_id;

  if nullif(btrim(coalesce(p_comment, '')), '') is not null then
    insert into editorial.article_review_comments (
      thread_id,
      body_text
    )
    values (
      v_thread_id,
      btrim(p_comment)
    );
  end if;

  insert into editorial.article_suggestion_events (
    suggestion_id,
    action
  )
  values (
    v_suggestion_id,
    'created'
  );

  created_thread_id := v_thread_id;
  created_suggestion_id := v_suggestion_id;
  created_at := v_created_at;
  return next;
end;
$$;


ALTER FUNCTION "public"."create_article_suggestion"("p_article_id" "uuid", "p_target_version_id" "uuid", "p_target_version_fingerprint" "text", "p_anchor_from" integer, "p_anchor_to" integer, "p_anchor_quote" "text", "p_anchor_prefix" "text", "p_anchor_suffix" "text", "p_operation_kind" "text", "p_original_text" "text", "p_replacement_text" "text", "p_proposed_content_html" "text", "p_comment" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_article_suggestion"("p_article_id" "uuid", "p_target_version_id" "uuid", "p_target_version_fingerprint" "text", "p_anchor_from" integer, "p_anchor_to" integer, "p_anchor_quote" "text", "p_anchor_prefix" "text", "p_anchor_suffix" "text", "p_operation_kind" "text", "p_original_text" "text", "p_replacement_text" "text", "p_proposed_content_html" "text", "p_comment" "text") IS 'Creates a bounded Article suggestion against the current immutable submitted version.';



CREATE OR REPLACE FUNCTION "public"."create_citation"("p_source_id" "uuid", "p_source_version_id" "uuid", "p_locator_type" "text", "p_locator_data" "jsonb", "p_quotation" "text" DEFAULT NULL::"text", "p_editor_note" "text" DEFAULT NULL::"text", "p_public_label" "text" DEFAULT NULL::"text", "p_public_safe" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial', 'auth'
    AS $$
declare
  v_actor_id uuid;
  v_source editorial.sources%rowtype;
  v_citation_id uuid;
  v_public_safe boolean;
begin
  v_actor_id :=
    editorial.assert_citation_command_actor();

  v_public_safe := coalesce(p_public_safe, false);

  select *
  into v_source
  from editorial.sources source
  where source.id = p_source_id;

  if not found then
    raise exception
      'Source was not found';
  end if;

  if not exists (
    select 1
    from editorial.source_versions source_version
    where source_version.id = p_source_version_id
      and source_version.source_id = p_source_id
  ) then
    raise exception
      'Source version does not belong to the Source';
  end if;

  if not exists (
    select 1
    from editorial.citation_locator_types locator_type
    where locator_type.locator_type = p_locator_type
      and locator_type.enabled
  ) then
    raise exception
      'Choose an enabled Citation locator type';
  end if;

  perform editorial.validate_citation_locator(
    p_locator_type,
    p_locator_data
  );

  if v_public_safe then
    if v_source.source_state <> 'active' then
      raise exception
        'A withdrawn or archived Source cannot create a public-safe Citation';
    end if;

    if v_source.review_status <> 'approved'
       or v_source.current_approved_version_id
            is distinct from p_source_version_id then
      raise exception
        'A public-safe Citation requires the exact approved Source version';
    end if;

    if v_source.exposure_class not in (
      'public',
      'public_redacted'
    ) then
      raise exception
        'A public-safe Citation requires a publicly eligible Source';
    end if;
  end if;

  insert into editorial.citations (
    source_id,
    source_version_id,
    locator_type,
    locator_data,
    quotation,
    editor_note,
    public_label,
    public_safe,
    citation_state,
    created_by
  )
  values (
    p_source_id,
    p_source_version_id,
    p_locator_type,
    p_locator_data,
    nullif(btrim(p_quotation), ''),
    nullif(btrim(p_editor_note), ''),
    nullif(btrim(p_public_label), ''),
    v_public_safe,
    'active',
    v_actor_id
  )
  returning id
  into v_citation_id;

  return jsonb_build_object(
    'citation_id',
      v_citation_id,
    'source_id',
      p_source_id,
    'source_version_id',
      p_source_version_id,
    'public_safe',
      v_public_safe,
    'citation_state',
      'active'
  );
end;
$$;


ALTER FUNCTION "public"."create_citation"("p_source_id" "uuid", "p_source_version_id" "uuid", "p_locator_type" "text", "p_locator_data" "jsonb", "p_quotation" "text", "p_editor_note" "text", "p_public_label" "text", "p_public_safe" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_citation"("p_source_id" "uuid", "p_source_version_id" "uuid", "p_locator_type" "text", "p_locator_data" "jsonb", "p_quotation" "text", "p_editor_note" "text", "p_public_label" "text", "p_public_safe" boolean) IS 'Creates one immutable Citation against one exact Source version.';



CREATE OR REPLACE FUNCTION "public"."create_correction_case_from_contribution"("p_contribution_id" "uuid", "p_origin_summary" "text", "p_correction_kind" "text", "p_idempotency_key" "text", "p_correlation_id" "uuid") RETURNS TABLE("command_receipt_id" "uuid", "receipt_status" "text", "case_resource_id" "uuid", "case_revision" bigint, "result_payload" "jsonb", "idempotent_replay" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'editorial', 'platform_private'
    AS $$
declare
  v_actor uuid;
  v_contribution public.community_contributions%rowtype;
  v_context record;
  v_existing_receipt platform_private.command_receipts%rowtype;
  v_request_payload jsonb;
  v_request_fingerprint text;
  v_begin record;
  v_result jsonb;
begin
  v_actor :=
    platform_private.assert_correction_capability(
      'triage_corrections'
    );

  if p_contribution_id is null
     or p_correlation_id is null
     or nullif(btrim(p_origin_summary), '') is null
     or length(p_origin_summary) > 8000
  then
    raise exception
      using errcode = '22023',
      message = 'Contribution, summary, and correlation identity are required.';
  end if;

  if not exists (
    select 1
    from editorial.correction_kinds kind
    where kind.correction_kind = p_correction_kind
      and kind.enabled
  ) then
    raise exception
      using errcode = '22023',
      message = 'The correction kind is not enabled.';
  end if;

  select contribution.*
  into v_contribution
  from public.community_contributions contribution
  where contribution.id = p_contribution_id;

  if not found then
    raise exception
      using errcode = 'P0002',
      message = 'The contribution does not exist.';
  end if;

  v_request_payload := jsonb_build_object(
    'contribution_id', p_contribution_id,
    'origin_summary', btrim(p_origin_summary),
    'correction_kind', p_correction_kind,
    'correlation_id', p_correlation_id
  );

  select *
  into v_context
  from platform_private.correction_actor_context();

  v_request_fingerprint :=
    platform_private.correction_request_fingerprint(
      'correction.case.create_from_contribution',
      null,
      v_request_payload
    );

  select receipt.*
  into v_existing_receipt
  from platform_private.command_receipts receipt
  where receipt.principal_key =
      v_context.principal_key
    and receipt.command_type =
      'correction.case.create_from_contribution'
    and receipt.idempotency_key =
      p_idempotency_key
  for update;

  if found then
    if v_existing_receipt.request_fingerprint
         <> v_request_fingerprint
    then
      raise exception
        using
          errcode = '23505',
          message = 'The idempotency key was already used for a different request.';
    end if;

    return query
    select *
    from platform_private.read_correction_command_result(
      v_existing_receipt.id,
      true
    );
    return;
  end if;

  if exists (
    select 1
    from editorial.correction_cases correction_case
    where correction_case.origin_contribution_id =
      p_contribution_id
  ) then
    raise exception
      using errcode = '23505',
      message = 'The contribution already has a controlling correction case.';
  end if;

  select *
  into v_begin
  from platform_private.begin_correction_create_command(
    'correction.case.create_from_contribution',
    p_idempotency_key,
    v_request_payload
  );

  if v_begin.idempotent_replay then
    return query
    select *
    from platform_private.read_correction_command_result(
      v_begin.command_receipt_id,
      true
    );
    return;
  end if;

  insert into editorial.correction_cases (
    resource_id,
    origin_type,
    origin_contribution_id,
    origin_submitter_user_id,
    origin_submitted_at,
    origin_type_snapshot,
    origin_summary_snapshot,
    correction_kind,
    created_by,
    updated_by
  )
  values (
    v_begin.case_resource_id,
    'community_contribution',
    v_contribution.id,
    v_contribution.user_id,
    v_contribution.created_at,
    v_contribution.contribution_type,
    btrim(p_origin_summary),
    p_correction_kind,
    v_actor,
    v_actor
  );

  insert into editorial.correction_events (
    case_resource_id,
    event_number,
    event_type,
    case_revision_before,
    case_revision_after,
    prior_state,
    resulting_state,
    actor_id,
    reason,
    command_receipt_id,
    correlation_id,
    metadata
  )
  values (
    v_begin.case_resource_id,
    1,
    'case_created',
    1,
    1,
    null,
    'submitted',
    v_actor,
    'Created from community contribution.',
    v_begin.command_receipt_id,
    p_correlation_id,
    jsonb_build_object(
      'principal_key',
      (
        select receipt.principal_key
        from platform_private.command_receipts receipt
        where receipt.id =
          v_begin.command_receipt_id
      ),
      'origin_type',
      'community_contribution',
      'origin_contribution_id',
      v_contribution.id,
      'origin_contribution_type',
      v_contribution.contribution_type,
      'origin_entity_type',
      v_contribution.entity_type,
      'origin_entity_id',
      v_contribution.entity_id,
      'origin_entity_slug',
      v_contribution.entity_slug
    )
  );

  v_result := jsonb_build_object(
    'case_resource_id', v_begin.case_resource_id,
    'case_revision', 1,
    'case_state', 'submitted',
    'origin_contribution_id', v_contribution.id
  );

  perform platform_private.complete_resource_command(
    v_begin.command_receipt_id,
    v_result
  );

  return query
  select *
  from platform_private.read_correction_command_result(
    v_begin.command_receipt_id,
    false
  );
end;
$$;


ALTER FUNCTION "public"."create_correction_case_from_contribution"("p_contribution_id" "uuid", "p_origin_summary" "text", "p_correction_kind" "text", "p_idempotency_key" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_credit"("p_credit_role" "text", "p_user_id" "uuid" DEFAULT NULL::"uuid", "p_registry_author_id" "uuid" DEFAULT NULL::"uuid", "p_external_contributor_id" "uuid" DEFAULT NULL::"uuid", "p_role_label_override" "text" DEFAULT NULL::"text", "p_credit_note" "text" DEFAULT NULL::"text", "p_public_safe" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial', 'auth'
    AS $$
declare
  v_actor_id uuid;
  v_display_name text;
  v_registry_author_slug text;
  v_user_username text;
  v_external_contributor editorial.external_contributors%rowtype;
  v_credit_id uuid;
  v_public_safe boolean;
begin
  v_actor_id :=
    editorial.assert_credit_command_actor();

  if num_nonnulls(
       p_user_id,
       p_registry_author_id,
       p_external_contributor_id
     ) <> 1 then
    raise exception
      'Choose exactly one credited-party identity';
  end if;

  if not exists (
    select 1
    from editorial.credit_roles credit_role
    where credit_role.credit_role = p_credit_role
      and credit_role.enabled
  ) then
    raise exception
      'Choose an enabled Credit role';
  end if;

  v_public_safe := coalesce(p_public_safe, false);

  if p_user_id is not null then
    select
      nullif(btrim(profile.display_name), ''),
      nullif(btrim(profile.username), '')
    into
      v_display_name,
      v_user_username
    from public.user_profiles profile
    where profile.user_id = p_user_id
      and profile.status = 'active';

    if not found or v_display_name is null then
      raise exception
        'Active authenticated-user profile with a display name was not found';
    end if;

  elsif p_registry_author_id is not null then
    select
      nullif(btrim(author_record.name), ''),
      nullif(btrim(author_record.slug), '')
    into
      v_display_name,
      v_registry_author_slug
    from public.registry_authors author_record
    where author_record.id = p_registry_author_id;

    if not found
       or v_display_name is null
       or v_registry_author_slug is null then
      raise exception
        'Registry author was not found or is incomplete';
    end if;

  else
    select *
    into v_external_contributor
    from editorial.external_contributors contributor
    where contributor.id = p_external_contributor_id;

    if not found then
      raise exception
        'External contributor was not found';
    end if;

    if v_external_contributor.contributor_state <> 'active' then
      raise exception
        'Only active external contributors can receive new Credits';
    end if;

    v_display_name :=
      nullif(
        btrim(v_external_contributor.display_name),
        ''
      );

    if v_display_name is null then
      raise exception
        'External contributor display name is missing';
    end if;

    if v_public_safe
       and (
         not v_external_contributor.public_safe
         or v_external_contributor.consent_status
              not in (
                'granted',
                'not_required'
              )
       ) then
      raise exception
        'Public-safe external-contributor Credits require active public-safe consent';
    end if;
  end if;

  insert into editorial.credits (
    credit_role,
    user_id,
    registry_author_id,
    external_contributor_id,
    display_name_snapshot,
    role_label_snapshot,
    registry_author_slug_snapshot,
    user_username_snapshot,
    credit_note,
    created_by
  )
  values (
    p_credit_role,
    p_user_id,
    p_registry_author_id,
    p_external_contributor_id,
    v_display_name,
    nullif(btrim(p_role_label_override), ''),
    v_registry_author_slug,
    v_user_username,
    nullif(btrim(p_credit_note), ''),
    v_actor_id
  )
  returning id
  into v_credit_id;

  insert into editorial.credit_governance (
    credit_id,
    public_safe,
    credit_state,
    governance_revision,
    reason,
    updated_by,
    updated_at
  )
  values (
    v_credit_id,
    v_public_safe,
    'active',
    1,
    null,
    v_actor_id,
    now()
  );

  return jsonb_build_object(
    'credit_id',
      v_credit_id,
    'governance_revision',
      1,
    'credit_state',
      'active',
    'public_safe',
      v_public_safe,
    'display_name_snapshot',
      v_display_name,
    'registry_author_slug_snapshot',
      v_registry_author_slug,
    'user_username_snapshot',
      v_user_username
  );
end;
$$;


ALTER FUNCTION "public"."create_credit"("p_credit_role" "text", "p_user_id" "uuid", "p_registry_author_id" "uuid", "p_external_contributor_id" "uuid", "p_role_label_override" "text", "p_credit_note" "text", "p_public_safe" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_credit"("p_credit_role" "text", "p_user_id" "uuid", "p_registry_author_id" "uuid", "p_external_contributor_id" "uuid", "p_role_label_override" "text", "p_credit_note" "text", "p_public_safe" boolean) IS 'Creates one immutable Credit and governance revision 1.';



CREATE OR REPLACE FUNCTION "public"."create_external_contributor"("p_display_name" "text", "p_public_role" "text" DEFAULT NULL::"text", "p_public_url" "text" DEFAULT NULL::"text", "p_location_text" "text" DEFAULT NULL::"text", "p_contact_email" "text" DEFAULT NULL::"text", "p_contact_phone" "text" DEFAULT NULL::"text", "p_consent_status" "text" DEFAULT 'unknown'::"text", "p_public_safe" boolean DEFAULT false, "p_internal_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial', 'auth'
    AS $$
declare
  v_actor_id uuid;
  v_contributor_id uuid;
  v_consent_status text;
  v_public_safe boolean;
begin
  v_actor_id :=
    editorial.assert_credit_command_actor();

  if nullif(btrim(p_display_name), '') is null then
    raise exception
      'External contributor display name is required';
  end if;

  v_consent_status :=
    coalesce(
      nullif(btrim(p_consent_status), ''),
      'unknown'
    );

  if v_consent_status not in (
    'unknown',
    'not_required',
    'requested',
    'granted',
    'limited',
    'declined',
    'withdrawn'
  ) then
    raise exception
      'Choose a supported contributor consent status';
  end if;

  v_public_safe := coalesce(p_public_safe, false);

  if v_public_safe
     and v_consent_status not in (
       'granted',
       'not_required'
     ) then
    raise exception
      'Public-safe contributors require granted or not-required consent';
  end if;

  insert into editorial.external_contributors (
    display_name,
    public_role,
    public_url,
    location_text,
    contact_email,
    contact_phone,
    consent_status,
    public_safe,
    contributor_state,
    internal_notes,
    created_by,
    updated_by
  )
  values (
    btrim(p_display_name),
    nullif(btrim(p_public_role), ''),
    nullif(btrim(p_public_url), ''),
    nullif(btrim(p_location_text), ''),
    nullif(btrim(p_contact_email), ''),
    nullif(btrim(p_contact_phone), ''),
    v_consent_status,
    v_public_safe,
    'active',
    nullif(btrim(p_internal_notes), ''),
    v_actor_id,
    v_actor_id
  )
  returning id
  into v_contributor_id;

  return jsonb_build_object(
    'external_contributor_id',
      v_contributor_id,
    'contributor_state',
      'active',
    'consent_status',
      v_consent_status,
    'public_safe',
      v_public_safe
  );
end;
$$;


ALTER FUNCTION "public"."create_external_contributor"("p_display_name" "text", "p_public_role" "text", "p_public_url" "text", "p_location_text" "text", "p_contact_email" "text", "p_contact_phone" "text", "p_consent_status" "text", "p_public_safe" boolean, "p_internal_notes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_external_contributor"("p_display_name" "text", "p_public_role" "text", "p_public_url" "text", "p_location_text" "text", "p_contact_email" "text", "p_contact_phone" "text", "p_consent_status" "text", "p_public_safe" boolean, "p_internal_notes" "text") IS 'Creates one stable external-contributor identity.';



CREATE TABLE IF NOT EXISTS "public"."wk_ingestion_runs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "source_name" "text" NOT NULL,
    "source_kind" "text" NOT NULL,
    "source_manifest" "jsonb",
    "status" "text" DEFAULT 'queued'::"text" NOT NULL,
    "started_at" timestamp with time zone,
    "finished_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "imported_counts" "jsonb",
    "warnings" "text"[],
    "errors" "text"[]
);


ALTER TABLE "public"."wk_ingestion_runs" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_import_run"("p_source_name" "text", "p_source_kind" "text", "p_source_manifest" "jsonb", "p_status" "text" DEFAULT 'queued'::"text", "p_imported_counts" "jsonb" DEFAULT NULL::"jsonb", "p_warnings" "text"[] DEFAULT NULL::"text"[], "p_errors" "text"[] DEFAULT NULL::"text"[]) RETURNS SETOF "public"."wk_ingestion_runs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_run public.wk_ingestion_runs;
BEGIN
  INSERT INTO public.wk_ingestion_runs (source_name, source_kind, source_manifest, status, imported_counts, warnings, errors)
  VALUES (p_source_name, p_source_kind, p_source_manifest, p_status, p_imported_counts, p_warnings, p_errors)
  RETURNING * INTO v_run;
  RETURN NEXT v_run;
END;
