CREATE OR REPLACE FUNCTION "public"."create_institute_article_draft"("p_title" "text", "p_slug_base" "text", "p_excerpt" "text" DEFAULT ''::"text", "p_author" "text" DEFAULT 'WAKILISHA Contributor'::"text", "p_seo" "jsonb" DEFAULT '{}'::"jsonb", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS TABLE("article_id" "uuid", "article_slug" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  clean_base text;
  candidate_slug text;
  suffix integer := 2;
  new_article_id uuid;
begin
  if not (
    public.current_user_is_administrator()
    or public.current_user_has_capability('institute_write')
    or public.current_user_has_capability('institute_admin')
  ) then
    raise exception 'Permission denied: institute_write required';
  end if;

  clean_base := lower(trim(coalesce(p_slug_base, p_title, 'institute-article-draft')));
  clean_base := regexp_replace(clean_base, '[^a-z0-9\s-]', '', 'g');
  clean_base := regexp_replace(clean_base, '[\s_]+', '-', 'g');
  clean_base := regexp_replace(clean_base, '-+', '-', 'g');
  clean_base := regexp_replace(clean_base, '(^-|-$)', '', 'g');
  clean_base := left(nullif(clean_base, ''), 76);

  if clean_base is null then
    clean_base := 'institute-article-draft';
  end if;

  candidate_slug := clean_base;

  while exists (select 1 from public.wk_articles where slug = candidate_slug) loop
    candidate_slug := clean_base || '-' || suffix::text;
    suffix := suffix + 1;
  end loop;

  insert into public.wk_articles (
    slug,
    title,
    excerpt,
    content_html,
    author,
    published_at,
    categories,
    tags,
    seo,
    wp_status,
    hero_image_url,
    raw_meta
  )
  values (
    candidate_slug,
    nullif(trim(coalesce(p_title, 'Untitled Institute article draft')), ''),
    coalesce(p_excerpt, ''),
    '',
    coalesce(nullif(trim(p_author), ''), 'WAKILISHA Contributor'),
    null,
    '[]'::jsonb,
    '[]'::jsonb,
    coalesce(p_seo, '{}'::jsonb),
    'draft',
    null,
    jsonb_build_object(
      'source', 'institute',
      'created_from', 'institute_article_bridge'
    ) || coalesce(p_metadata, '{}'::jsonb)
  )
  returning id into new_article_id;

  article_id := new_article_id;
  article_slug := candidate_slug;
  return next;
end;
$_$;


ALTER FUNCTION "public"."create_institute_article_draft"("p_title" "text", "p_slug_base" "text", "p_excerpt" "text", "p_author" "text", "p_seo" "jsonb", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_institute_playlist_draft"("p_inquiry_id" "uuid", "p_title" "text", "p_description" "text" DEFAULT ''::"text", "p_curator_label" "text" DEFAULT 'WAKILISHA'::"text", "p_items" "jsonb" DEFAULT '[]'::"jsonb") RETURNS TABLE("playlist_id" "uuid", "playlist_slug" "text", "work_product_link_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  clean_base text;
  candidate_slug text;
  suffix integer := 2;
  new_playlist_id uuid;
  new_work_product_link_id uuid;
  item_count integer;
begin
  if not (
    public.current_user_is_administrator()
    or public.current_user_has_capability('institute_write')
    or public.current_user_has_capability('institute_admin')
  ) then
    raise exception 'Permission denied: institute_write required';
  end if;

  if p_inquiry_id is null then
    raise exception 'Inquiry ID is required';
  end if;

  if not exists (select 1 from public.institute_inquiries where id = p_inquiry_id) then
    raise exception 'Inquiry not found';
  end if;

  if nullif(trim(coalesce(p_title, '')), '') is null then
    raise exception 'Playlist title is required';
  end if;

  if jsonb_typeof(coalesce(p_items, '[]'::jsonb)) <> 'array' then
    raise exception 'Playlist items must be a JSON array';
  end if;

  item_count := jsonb_array_length(coalesce(p_items, '[]'::jsonb));

  if item_count < 1 then
    raise exception 'At least one playlist item is required';
  end if;

  clean_base := lower(trim(coalesce(p_title, 'institute-playlist-draft')));
  clean_base := regexp_replace(clean_base, '[^a-z0-9\s-]', '', 'g');
  clean_base := regexp_replace(clean_base, '[\s_]+', '-', 'g');
  clean_base := regexp_replace(clean_base, '-+', '-', 'g');
  clean_base := regexp_replace(clean_base, '(^-|-$)', '', 'g');
  clean_base := left(nullif(clean_base, ''), 76);

  if clean_base is null then
    clean_base := 'institute-playlist-draft';
  end if;

  candidate_slug := clean_base;

  while exists (select 1 from public.wk_playlists where slug = candidate_slug) loop
    candidate_slug := clean_base || '-' || suffix::text;
    suffix := suffix + 1;
  end loop;

  insert into public.wk_playlists (
    title,
    slug,
    description,
    curator_label,
    status,
    source_inquiry_id,
    metadata
  )
  values (
    trim(p_title),
    candidate_slug,
    coalesce(p_description, ''),
    coalesce(nullif(trim(p_curator_label), ''), 'WAKILISHA'),
    'draft',
    p_inquiry_id,
    jsonb_build_object(
      'source', 'institute',
      'created_from', 'institute_playlist_bridge',
      'item_count', item_count
    )
  )
  returning id into new_playlist_id;

  insert into public.wk_playlist_items (
    playlist_id,
    position,
    registry_track_id,
    registry_release_id,
    provider_key,
    provider_track_id,
    provider_url,
    title,
    artist_names,
    release_title,
    artwork_url,
    preview_url,
    duration_ms,
    isrc,
    match_status,
    match_confidence,
    normalization_payload,
    notes
  )
  select
    new_playlist_id,
    item_position::integer,
    nullif(trim(item->>'registry_track_id'), '')::uuid,
    nullif(trim(item->>'registry_release_id'), '')::uuid,
    lower(nullif(trim(item->>'provider_key'), '')),
    nullif(trim(item->>'provider_track_id'), ''),
    nullif(trim(item->>'provider_url'), ''),
    nullif(trim(item->>'title'), ''),
    coalesce(
      (
        select array_agg(trim(artist_name))
        from jsonb_array_elements_text(coalesce(item->'artist_names', '[]'::jsonb)) as artist_name
        where trim(artist_name) <> ''
      ),
      '{}'::text[]
    ),
    nullif(trim(item->>'release_title'), ''),
    nullif(trim(item->>'artwork_url'), ''),
    nullif(trim(item->>'preview_url'), ''),
    nullif(trim(item->>'duration_ms'), '')::integer,
    nullif(trim(item->>'isrc'), ''),
    case
      when nullif(trim(item->>'match_status'), '') in (
        'matched',
        'external_only',
        'missing_registry_track',
        'needs_review',
        'rejected',
        'pending'
      ) then trim(item->>'match_status')
      when nullif(trim(item->>'registry_track_id'), '') is not null then 'matched'
      when nullif(trim(item->>'provider_track_id'), '') is not null
        or nullif(trim(item->>'provider_url'), '') is not null then 'external_only'
      else 'pending'
    end,
    nullif(trim(item->>'match_confidence'), '')::numeric,
    coalesce(item->'normalization_payload', '{}'::jsonb),
    nullif(trim(item->>'notes'), '')
  from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) with ordinality as playlist_item(item, item_position);

  insert into public.institute_work_product_links (
    inquiry_id,
    product_type,
    format_label,
    product_id,
    product_slug,
    status,
    metadata
  )
  values (
    p_inquiry_id,
    'playlist',
    'Playlist',
    new_playlist_id,
    candidate_slug,
    'draft',
    jsonb_build_object(
      'source', 'institute',
      'created_from', 'institute_playlist_bridge',
      'item_count', item_count
    )
  )
  on conflict (inquiry_id, product_type, format_label)
  do update set
    product_id = excluded.product_id,
    product_slug = excluded.product_slug,
    status = excluded.status,
    metadata = public.institute_work_product_links.metadata || excluded.metadata,
    updated_at = now()
  returning id into new_work_product_link_id;

  update public.wk_playlists
  set source_work_product_link_id = new_work_product_link_id
  where id = new_playlist_id;

  playlist_id := new_playlist_id;
  playlist_slug := candidate_slug;
  work_product_link_id := new_work_product_link_id;
  return next;
end;
$_$;


ALTER FUNCTION "public"."create_institute_playlist_draft"("p_inquiry_id" "uuid", "p_title" "text", "p_description" "text", "p_curator_label" "text", "p_items" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_institute_playlist_draft"("p_inquiry_id" "uuid", "p_title" "text", "p_description" "text", "p_curator_label" "text", "p_items" "jsonb") IS 'Retired Phase 5A legacy Institute Playlist writer. Canonical Playlist writes use governed Playlist RPC commands.';



CREATE OR REPLACE FUNCTION "public"."create_internal_correction_case"("p_origin_summary" "text", "p_correction_kind" "text", "p_priority" "text", "p_idempotency_key" "text", "p_correlation_id" "uuid") RETURNS TABLE("command_receipt_id" "uuid", "receipt_status" "text", "case_resource_id" "uuid", "case_revision" bigint, "result_payload" "jsonb", "idempotent_replay" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'editorial', 'platform_private'
    AS $$
declare
  v_actor uuid;
  v_begin record;
  v_result jsonb;
begin
  v_actor :=
    platform_private.assert_correction_capability(
      'triage_corrections'
    );

  if p_correlation_id is null
     or nullif(btrim(p_origin_summary), '') is null
     or length(p_origin_summary) > 8000
     or p_priority not in (
       'low',
       'normal',
       'high',
       'urgent'
     )
  then
    raise exception
      using errcode = '22023',
      message = 'Summary, priority, and correlation identity are required.';
  end if;

  if not exists (
    select 1
    from editorial.correction_kinds kind
    where kind.correction_kind = p_correction_kind
      and kind.enabled
  ) then
    raise exception
      using errcode = '22023',
      message = 'The correction kind is not enabled.';
  end if;

  select *
  into v_begin
  from platform_private.begin_correction_create_command(
    'correction.case.create_internal',
    p_idempotency_key,
    jsonb_build_object(
      'origin_summary', btrim(p_origin_summary),
      'correction_kind', p_correction_kind,
      'priority', p_priority,
      'correlation_id', p_correlation_id
    )
  );

  if v_begin.idempotent_replay then
    return query
    select *
    from platform_private.read_correction_command_result(
      v_begin.command_receipt_id,
      true
    );
    return;
  end if;

  insert into editorial.correction_cases (
    resource_id,
    origin_type,
    origin_summary_snapshot,
    correction_kind,
    priority,
    created_by,
    updated_by
  )
  values (
    v_begin.case_resource_id,
    'internal_editorial',
    btrim(p_origin_summary),
    p_correction_kind,
    p_priority,
    v_actor,
    v_actor
  );

  insert into editorial.correction_events (
    case_resource_id,
    event_number,
    event_type,
    case_revision_before,
    case_revision_after,
    prior_state,
    resulting_state,
    actor_id,
    reason,
    command_receipt_id,
    correlation_id,
    metadata
  )
  values (
    v_begin.case_resource_id,
    1,
    'case_created',
    1,
    1,
    null,
    'submitted',
    v_actor,
    'Created through internal editorial authority.',
    v_begin.command_receipt_id,
    p_correlation_id,
    jsonb_build_object(
      'principal_key',
      (
        select receipt.principal_key
        from platform_private.command_receipts receipt
        where receipt.id =
          v_begin.command_receipt_id
      ),
      'origin_type',
      'internal_editorial'
    )
  );

  v_result := jsonb_build_object(
    'case_resource_id', v_begin.case_resource_id,
    'case_revision', 1,
    'case_state', 'submitted'
  );

  perform platform_private.complete_resource_command(
    v_begin.command_receipt_id,
    v_result
  );

  return query
  select *
  from platform_private.read_correction_command_result(
    v_begin.command_receipt_id,
    false
  );
end;
$$;


ALTER FUNCTION "public"."create_internal_correction_case"("p_origin_summary" "text", "p_correction_kind" "text", "p_priority" "text", "p_idempotency_key" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_magazine_issue"("p_id" "text", "p_slug" "text", "p_title" "text", "p_dek" "text", "p_timeframe_start" "text", "p_timeframe_end" "text", "p_issue_type" "text", "p_brief_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "row_security" TO 'off'
    AS $$
DECLARE
  v_user_id uuid;
  v_is_admin boolean;
  result jsonb;
BEGIN
  -- Get the calling user's ID from JWT
  v_user_id := auth.uid();
  
  -- Verify the user exists and is an administrator
  SELECT EXISTS (
    SELECT 1 FROM user_role_assignments
    WHERE user_id = v_user_id
      AND role_key = 'administrator'
      AND status = 'active'
      AND (expires_at IS NULL OR expires_at > now())
  ) INTO v_is_admin;
  
  IF NOT v_is_admin THEN
    RAISE EXCEPTION 'Permission denied: administrator role required' USING ERRCODE = '42501';
  END IF;
  
  -- Insert the issue
  INSERT INTO wk_magazine_issues (
    id, slug, title, dek, status,
    timeframe_start, timeframe_end, issue_type, brief_id,
    created_by, created_at, updated_at
  ) VALUES (
    p_id, p_slug, p_title, p_dek, 'draft',
    CASE WHEN p_timeframe_start = '' THEN NULL ELSE p_timeframe_start::date END,
    CASE WHEN p_timeframe_end = '' THEN NULL ELSE p_timeframe_end::date END,
    COALESCE(p_issue_type, 'standard'), 
    CASE WHEN p_brief_id = '' THEN NULL ELSE p_brief_id END,
    v_user_id::text,
    now(), now()
  )
  RETURNING to_jsonb(wk_magazine_issues.*) INTO result;
  
  RETURN result;
END;
$$;


ALTER FUNCTION "public"."create_magazine_issue"("p_id" "text", "p_slug" "text", "p_title" "text", "p_dek" "text", "p_timeframe_start" "text", "p_timeframe_end" "text", "p_issue_type" "text", "p_brief_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_media_asset"("p_asset_kind" "text", "p_asset_purpose" "text", "p_title" "text", "p_compatibility_folder_id" "uuid" DEFAULT NULL::"uuid", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("asset_id" "uuid", "governance_version_id" "uuid", "authority_revision" bigint, "correlation_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'media', 'auth'
    AS $$
declare
  v_actor_id uuid;
  v_asset_id uuid := gen_random_uuid();
  v_governance_id uuid := gen_random_uuid();
  v_correlation_id uuid := coalesce(
    p_correlation_id,
    gen_random_uuid()
  );
begin
  v_actor_id :=
    media.require_command_actor('manage_media_assets');

  if nullif(btrim(p_title), '') is null then
    raise exception 'Media asset title is required';
  end if;

  if not exists (
    select 1
    from media.asset_kinds kind
    where kind.asset_kind = p_asset_kind
      and kind.enabled
  ) then
    raise exception 'Unknown or disabled Media asset kind';
  end if;

  if not exists (
    select 1
    from media.asset_purposes purpose
    where purpose.asset_purpose = p_asset_purpose
      and purpose.enabled
  ) then
    raise exception 'Unknown or disabled Media asset purpose';
  end if;

  if p_compatibility_folder_id is not null
     and not exists (
       select 1
       from public.media_folders folder
       where folder.id = p_compatibility_folder_id
     )
  then
    raise exception 'Compatibility Media folder does not exist';
  end if;

  insert into media.assets (
    id,
    asset_kind,
    asset_purpose,
    title,
    lifecycle_state,
    compatibility_folder_id,
    current_governance_version_id,
    authority_revision,
    created_by,
    updated_by
  )
  values (
    v_asset_id,
    p_asset_kind,
    p_asset_purpose,
    btrim(p_title),
    'active',
    p_compatibility_folder_id,
    null,
    1,
    v_actor_id,
    v_actor_id
  );

  insert into media.asset_governance_versions (
    id,
    asset_id,
    version_number,
    rights_status,
    consent_status,
    sensitivity,
    embargo_state,
    source_protection_class,
    preservation_state,
    retention_state,
    public_safety_state,
    internal_reason,
    created_by
  )
  values (
    v_governance_id,
    v_asset_id,
    1,
    'unknown',
    'unknown',
    'none',
    'none',
    'internal',
    'unassessed',
    'retain',
    'internal',
    'Initial governance created with explicit unknown and internal states',
    v_actor_id
  );

  update media.assets
  set current_governance_version_id = v_governance_id
  where id = v_asset_id;

  insert into media.events (
    asset_id,
    event_type,
    actor_id,
    reason,
    resulting_state,
    correlation_id
  )
  values (
    v_asset_id,
    'asset_created',
    v_actor_id,
    'Logical Media asset created',
    jsonb_build_object(
      'asset_kind', p_asset_kind,
      'asset_purpose', p_asset_purpose,
      'authority_revision', 1
    ),
    v_correlation_id
  );

  insert into media.events (
    asset_id,
    governance_version_id,
    event_type,
    actor_id,
    reason,
    resulting_state,
    correlation_id
  )
  values (
    v_asset_id,
    v_governance_id,
    'governance_version_created',
    v_actor_id,
    'Initial Media governance created',
    jsonb_build_object(
      'version_number', 1,
      'public_safety_state', 'internal'
    ),
    v_correlation_id
  );

  return query
  select
    v_asset_id,
    v_governance_id,
    1::bigint,
    v_correlation_id;
end;
$$;


ALTER FUNCTION "public"."create_media_asset"("p_asset_kind" "text", "p_asset_purpose" "text", "p_title" "text", "p_compatibility_folder_id" "uuid", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_media_asset_revision"("p_asset_id" "uuid", "p_expected_authority_revision" bigint, "p_file_object_id" "uuid", "p_replacement_reason" "text", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("asset_revision_id" "uuid", "revision_number" bigint, "authority_revision" bigint, "correlation_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'media', 'auth'
    AS $$
declare
  v_actor_id uuid;
  v_asset media.assets%rowtype;
  v_file_state text;
  v_revision_id uuid := gen_random_uuid();
  v_revision_number bigint;
  v_previous_revision_id uuid;
  v_correlation_id uuid := coalesce(
    p_correlation_id,
    gen_random_uuid()
  );
begin
  v_actor_id :=
    media.require_command_actor('manage_media_assets');

  if nullif(btrim(p_replacement_reason), '') is null then
    raise exception 'Media replacement reason is required';
  end if;

  select *
  into v_asset
  from media.assets
  where id = p_asset_id
  for update;

  if not found then
    raise exception 'Media asset does not exist';
  end if;

  if v_asset.authority_revision <>
     p_expected_authority_revision
  then
    raise exception
      'Stale Media authority revision: expected %, current %',
      p_expected_authority_revision,
      v_asset.authority_revision;
  end if;

  if v_asset.lifecycle_state <> 'active' then
    raise exception 'Only active Media assets accept revisions';
  end if;

  select verification_state
  into v_file_state
  from media.file_objects
  where id = p_file_object_id;

  if not found or v_file_state <> 'verified' then
    raise exception 'Media revision requires a verified file object';
  end if;

  select
    coalesce(max(revision_row.revision_number), 0) + 1,
    v_asset.current_revision_id
  into
    v_revision_number,
    v_previous_revision_id
  from media.asset_revisions revision_row
  where revision_row.asset_id = p_asset_id;

  insert into media.asset_revisions (
    id,
    asset_id,
    revision_number,
    original_file_object_id,
    previous_revision_id,
    replacement_reason,
    created_by
  )
  values (
    v_revision_id,
    p_asset_id,
    v_revision_number,
    p_file_object_id,
    v_previous_revision_id,
    btrim(p_replacement_reason),
    v_actor_id
  );

  update media.assets as asset_row
  set
    current_revision_id = v_revision_id,
    authority_revision = asset_row.authority_revision + 1,
    updated_by = v_actor_id,
    updated_at = now()
  where asset_row.id = p_asset_id;

  insert into media.events (
    asset_id,
    asset_revision_id,
    file_object_id,
    event_type,
    actor_id,
    reason,
    resulting_state,
    correlation_id
  )
  values (
    p_asset_id,
    v_revision_id,
    p_file_object_id,
    'asset_revision_created',
    v_actor_id,
    btrim(p_replacement_reason),
    jsonb_build_object(
      'revision_number', v_revision_number,
      'previous_revision_id', v_previous_revision_id,
      'file_object_id', p_file_object_id
    ),
    v_correlation_id
  );

  insert into media.events (
    asset_id,
    asset_revision_id,
    file_object_id,
    event_type,
    actor_id,
    reason,
    prior_state,
    resulting_state,
    correlation_id
  )
  values (
    p_asset_id,
    v_revision_id,
    p_file_object_id,
    'asset_revision_activated',
    v_actor_id,
    btrim(p_replacement_reason),
    jsonb_build_object(
      'current_revision_id',
      v_previous_revision_id,
      'authority_revision',
      v_asset.authority_revision
    ),
    jsonb_build_object(
      'current_revision_id',
      v_revision_id,
      'authority_revision',
      v_asset.authority_revision + 1
    ),
    v_correlation_id
  );

  return query
  select
    v_revision_id,
    v_revision_number,
    v_asset.authority_revision + 1,
    v_correlation_id;
end;
$$;


ALTER FUNCTION "public"."create_media_asset_revision"("p_asset_id" "uuid", "p_expected_authority_revision" bigint, "p_file_object_id" "uuid", "p_replacement_reason" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_media_asset_write_v2"("p_asset" "jsonb", "p_file" "jsonb", "p_variant" "jsonb" DEFAULT NULL::"jsonb", "p_reason" "text" DEFAULT 'Create Media asset through operational write authority'::"text", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'media', 'auth'
    AS $$
declare
  v_actor_id uuid;
  v_correlation_id uuid := coalesce(p_correlation_id, gen_random_uuid());
  v_asset record;
  v_revision record;
  v_asset_id uuid;
  v_original_file_object_id uuid;
  v_variant_result jsonb;
  v_compatibility jsonb;
  v_slug text;
  v_title text;
  v_asset_kind text;
  v_asset_purpose text;
  v_folder_id uuid;
  v_metadata jsonb;
  v_tags text[];
  v_original_filename text;
  v_file_extension text;
begin
  v_actor_id := media.require_command_actor('manage_media_assets');

  if p_asset is null or jsonb_typeof(p_asset) <> 'object' then
    raise exception 'Media asset payload must be an object';
  end if;

  if nullif(btrim(p_reason), '') is null then
    raise exception 'Media creation reason is required';
  end if;

  v_title := nullif(btrim(p_asset ->> 'title'), '');
  v_asset_kind := coalesce(nullif(btrim(p_asset ->> 'asset_kind'), ''), 'other');
  v_asset_purpose := coalesce(nullif(btrim(p_asset ->> 'asset_purpose'), ''), 'general');
  v_folder_id := nullif(p_asset ->> 'folder_id', '')::uuid;
  v_slug := coalesce(
    nullif(btrim(p_asset ->> 'slug'), ''),
    'media-' || replace(gen_random_uuid()::text, '-', '')
  );

  if v_title is null then
    raise exception 'Media title is required';
  end if;

  select *
  into v_asset
  from public.create_media_asset(
    v_asset_kind,
    v_asset_purpose,
    v_title,
    v_folder_id,
    v_correlation_id
  );

  v_asset_id := v_asset.asset_id;
  v_original_file_object_id := media.insert_verified_file_object_v2(
    p_file,
    v_actor_id,
    v_correlation_id
  );

  select *
  into v_revision
  from public.create_media_asset_revision(
    v_asset_id,
    1,
    v_original_file_object_id,
    btrim(p_reason),
    v_correlation_id
  );

  v_variant_result := media.register_optional_variant_v2(
    v_asset_id,
    v_revision.asset_revision_id,
    v_original_file_object_id,
    p_variant,
    v_actor_id,
    v_correlation_id
  );

  v_original_filename := nullif(btrim(p_file ->> 'original_filename'), '');
  v_file_extension :=
    case
      when v_original_filename is not null
       and strpos(reverse(v_original_filename), '.') > 0
      then lower(reverse(split_part(reverse(v_original_filename), '.', 1)))
      else null
    end;

  if p_asset ? 'tags' then
    if jsonb_typeof(p_asset -> 'tags') <> 'array' then
      raise exception 'Media tags must be an array';
    end if;
    select coalesce(array_agg(value), '{}'::text[])
    into v_tags
    from jsonb_array_elements_text(p_asset -> 'tags') value;
  else
    v_tags := '{}'::text[];
  end if;

  v_metadata :=
    coalesce(p_asset -> 'metadata', '{}'::jsonb)
    || coalesce(p_file -> 'technical_metadata', '{}'::jsonb)
    || jsonb_build_object(
      'file_name', v_original_filename,
      'file_size', (p_file ->> 'byte_size')::bigint
    );

  if jsonb_typeof(v_metadata) <> 'object' then
    raise exception 'Media metadata must be an object';
  end if;

  insert into public.registry_media_assets (
    id,
    slug,
    title,
    url,
    mime_type,
    media_kind,
    status,
    source_kind,
    source_entity,
    source_record_id,
    source_staging_record_id,
    storage_bucket,
    storage_path,
    folder_id,
    file_kind,
    asset_purpose,
    display_filename,
    original_filename,
    file_extension,
    file_size_bytes,
    content_date,
    rights_status,
    credit_text,
    country_code,
    language_code,
    tags,
    internal_notes,
    metadata,
    created_at,
    updated_at
  )
  values (
    v_asset_id,
    v_slug,
    v_title,
    p_file ->> 'delivery_url',
    p_file ->> 'mime_type',
    coalesce(nullif(btrim(p_asset ->> 'media_kind'), ''), v_asset_kind),
    coalesce(nullif(btrim(p_asset ->> 'status'), ''), 'active'),
    coalesce(nullif(btrim(p_asset ->> 'source_kind'), ''), 'editor_upload'),
    nullif(btrim(p_asset ->> 'source_entity'), ''),
    nullif(btrim(p_asset ->> 'source_record_id'), ''),
    nullif(
      btrim(p_asset ->> 'source_staging_record_id'),
      ''
    )::uuid,
    coalesce(nullif(btrim(p_asset ->> 'storage_bucket'), ''), 'lightsail-media'),
    p_file ->> 'storage_path',
    v_folder_id,
    coalesce(nullif(btrim(p_asset ->> 'file_kind'), ''), v_asset_kind),
    v_asset_purpose,
    coalesce(nullif(btrim(p_asset ->> 'display_filename'), ''), v_title),
    v_original_filename,
    v_file_extension,
    (p_file ->> 'byte_size')::bigint,
    nullif(p_asset ->> 'content_date', '')::date,
    coalesce(nullif(btrim(p_asset ->> 'rights_status'), ''), 'unknown'),
    nullif(btrim(p_asset ->> 'credit_text'), ''),
    nullif(upper(btrim(p_asset ->> 'country_code')), ''),
    nullif(lower(btrim(p_asset ->> 'language_code')), ''),
    v_tags,
    nullif(btrim(p_asset ->> 'internal_notes'), ''),
    v_metadata,
    now(),
    now()
  )
  returning to_jsonb(registry_media_assets)
  into v_compatibility;

  insert into media.legacy_asset_links (
    legacy_asset_id,
    asset_id,
    mapping_reason,
    legacy_snapshot,
    created_by
  )
  values (
    v_asset_id,
    v_asset_id,
    'Phase 4A operational write authority bridge',
    v_compatibility,
    v_actor_id
  );

  insert into media.events (
    asset_id,
    event_type,
    actor_id,
    reason,
    resulting_state,
    correlation_id
  )
  values (
    v_asset_id,
    'compatibility_projection_created',
    v_actor_id,
    btrim(p_reason),
    jsonb_build_object(
      'compatibility_asset_id', v_asset_id,
      'storage_path', p_file ->> 'storage_path',
      'authority_revision', v_revision.authority_revision
    ),
    v_correlation_id
  );

  return jsonb_build_object(
    'asset_id', v_asset_id,
    'file_object_id', v_original_file_object_id,
    'asset_revision_id', v_revision.asset_revision_id,
    'revision_number', v_revision.revision_number,
    'authority_revision', v_revision.authority_revision,
    'variant', v_variant_result,
    'correlation_id', v_correlation_id
  );
end;
$$;


ALTER FUNCTION "public"."create_media_asset_write_v2"("p_asset" "jsonb", "p_file" "jsonb", "p_variant" "jsonb", "p_reason" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_media_asset_write_v2"("p_asset" "jsonb", "p_file" "jsonb", "p_variant" "jsonb", "p_reason" "text", "p_correlation_id" "uuid") IS 'Creates canonical Media identity, immutable original revision, optional derivative, compatibility projection, and bridge atomically.';



CREATE OR REPLACE FUNCTION "public"."create_media_governance_version"("p_asset_id" "uuid", "p_expected_authority_revision" bigint, "p_governance" "jsonb", "p_reason" "text", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("governance_version_id" "uuid", "version_number" bigint, "authority_revision" bigint, "correlation_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'media', 'auth'
    AS $$
declare
  v_actor_id uuid;
  v_asset media.assets%rowtype;
  v_governance_id uuid := gen_random_uuid();
  v_version_number bigint;
  v_correlation_id uuid := coalesce(
    p_correlation_id,
    gen_random_uuid()
  );
begin
  v_actor_id :=
    media.require_command_actor('review_media_governance');

  if p_governance is null
     or jsonb_typeof(p_governance) <> 'object'
     or not (
       p_governance ?& array[
         'rights_status',
         'consent_status',
         'sensitivity',
         'embargo_state',
         'source_protection_class',
         'preservation_state',
         'retention_state',
         'public_safety_state'
       ]
     )
     or exists (
       select 1
       from unnest(
         array[
           'rights_status',
           'consent_status',
           'sensitivity',
           'embargo_state',
           'source_protection_class',
           'preservation_state',
           'retention_state',
           'public_safety_state'
         ]
       ) required_key
       where nullif(
         btrim(p_governance ->> required_key),
         ''
       ) is null
     )
  then
    raise exception
      'Complete Media governance state payload is required';
  end if;

  if p_governance ->> 'retention_state'
       not in ('retain', 'review_required')
  then
    raise exception
      'Media retention actions require dedicated retention commands';
  end if;

  if nullif(btrim(p_reason), '') is null then
    raise exception 'Media governance reason is required';
  end if;

  select *
  into v_asset
  from media.assets
  where id = p_asset_id
  for update;

  if not found then
    raise exception 'Media asset does not exist';
  end if;

  if v_asset.authority_revision <>
     p_expected_authority_revision
  then
    raise exception
      'Stale Media authority revision: expected %, current %',
      p_expected_authority_revision,
      v_asset.authority_revision;
  end if;

  select
    coalesce(max(governance_row.version_number), 0) + 1
  into v_version_number
  from media.asset_governance_versions governance_row
  where governance_row.asset_id = p_asset_id;

  insert into media.asset_governance_versions (
    id,
    asset_id,
    version_number,
    rights_status,
    rights_basis,
    rights_holder,
    licence_identifier,
    licence_terms,
    consent_status,
    consent_scope,
    sensitivity,
    embargo_state,
    embargo_until,
    source_protection_class,
    preservation_state,
    retention_state,
    public_safety_state,
    internal_reason,
    approved_by,
    created_by
  )
  values (
    v_governance_id,
    p_asset_id,
    v_version_number,
    coalesce(p_governance ->> 'rights_status', 'unknown'),
    nullif(btrim(p_governance ->> 'rights_basis'), ''),
    nullif(btrim(p_governance ->> 'rights_holder'), ''),
    nullif(btrim(p_governance ->> 'licence_identifier'), ''),
    nullif(btrim(p_governance ->> 'licence_terms'), ''),
    coalesce(p_governance ->> 'consent_status', 'unknown'),
    nullif(btrim(p_governance ->> 'consent_scope'), ''),
    coalesce(p_governance ->> 'sensitivity', 'none'),
    coalesce(p_governance ->> 'embargo_state', 'none'),
    nullif(p_governance ->> 'embargo_until', '')::timestamptz,
    coalesce(
      p_governance ->> 'source_protection_class',
      'internal'
    ),
    coalesce(
      p_governance ->> 'preservation_state',
      'unassessed'
    ),
    coalesce(
      p_governance ->> 'retention_state',
      'retain'
    ),
    coalesce(
      p_governance ->> 'public_safety_state',
      'internal'
    ),
    btrim(p_reason),
    case
      when coalesce(
        p_governance ->> 'public_safety_state',
        'internal'
      ) in ('approved_public', 'approved_redacted')
        then v_actor_id
      else null
    end,
    v_actor_id
  );

  update media.assets as asset_row
  set
    current_governance_version_id = v_governance_id,
    authority_revision = asset_row.authority_revision + 1,
    updated_by = v_actor_id,
    updated_at = now()
  where asset_row.id = p_asset_id;

  insert into media.events (
    asset_id,
    governance_version_id,
    event_type,
    actor_id,
    reason,
    prior_state,
    resulting_state,
    correlation_id
  )
  values (
    p_asset_id,
    v_governance_id,
    'governance_version_created',
    v_actor_id,
    btrim(p_reason),
    jsonb_build_object(
      'current_governance_version_id',
      v_asset.current_governance_version_id,
      'authority_revision',
      v_asset.authority_revision
    ),
    jsonb_build_object(
      'current_governance_version_id',
      v_governance_id,
      'version_number',
      v_version_number,
      'authority_revision',
      v_asset.authority_revision + 1
    ),
    v_correlation_id
  );

  return query
  select
    v_governance_id,
    v_version_number,
    v_asset.authority_revision + 1,
    v_correlation_id;
end;
$$;


ALTER FUNCTION "public"."create_media_governance_version"("p_asset_id" "uuid", "p_expected_authority_revision" bigint, "p_governance" "jsonb", "p_reason" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_media_upload_session_v1"("p_idempotency_key" "text", "p_original_filename" "text", "p_mime_type" "text", "p_expected_byte_size" bigint, "p_expected_sha256" "text", "p_ttl_seconds" integer DEFAULT 86400, "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'media', 'auth'
    AS $_$
declare
  v_actor_id uuid;
  v_session_id uuid := gen_random_uuid();
  v_correlation_id uuid := coalesce(p_correlation_id, gen_random_uuid());
  v_filename text := btrim(coalesce(p_original_filename, ''));
  v_mime_type text := lower(btrim(coalesce(p_mime_type, '')));
  v_sha256 text := lower(btrim(coalesce(p_expected_sha256, '')));
  v_extension text;
  v_part_size integer := 8388608;
  v_total_parts integer;
  v_storage_path text;
  v_existing media.upload_sessions%rowtype;
begin
  v_actor_id := media.require_command_actor('manage_media_assets');

  if p_idempotency_key is null
     or p_idempotency_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,127}$'
  then
    raise exception 'Upload idempotency key is invalid';
  end if;

  if v_filename = '' or strpos(v_filename, '.') = 0 then
    raise exception 'Audio master filename with extension is required';
  end if;

  v_extension := lower(reverse(split_part(reverse(v_filename), '.', 1)));

  if v_extension not in ('mp3', 'm4a', 'aac', 'wav', 'flac', 'ogg', 'oga') then
    raise exception 'Unsupported audio master extension';
  end if;

  if v_mime_type not like 'audio/%' then
    raise exception 'Audio master MIME type is required';
  end if;

  if p_expected_byte_size is null
     or p_expected_byte_size <= 26214400
     or p_expected_byte_size > 2147483648
  then
    raise exception 'Resumable audio master must be larger than 25 MiB and no larger than 2 GiB';
  end if;

  if v_sha256 !~ '^[0-9a-f]{64}$' then
    raise exception 'Expected audio master SHA-256 is invalid';
  end if;

  if p_ttl_seconds not between 300 and 86400 then
    raise exception 'Upload session TTL must be between 300 and 86400 seconds';
  end if;

  select session_row.*
  into v_existing
  from media.upload_sessions session_row
  where session_row.actor_id = v_actor_id
    and session_row.idempotency_key = p_idempotency_key
  for update;

  if found then
    if v_existing.original_filename is distinct from v_filename
       or v_existing.mime_type is distinct from v_mime_type
       or v_existing.expected_byte_size is distinct from p_expected_byte_size
       or v_existing.expected_sha256 is distinct from v_sha256
    then
      raise exception 'Upload idempotency key is already bound to different file metadata';
    end if;

    return jsonb_build_object(
      'session_id', v_existing.id,
      'state', v_existing.state,
      'storage_path', v_existing.storage_path,
      'storage_provider', v_existing.storage_provider,
      'storage_namespace', v_existing.storage_namespace,
      'original_filename', v_existing.original_filename,
      'mime_type', v_existing.mime_type,
      'expected_byte_size', v_existing.expected_byte_size,
      'expected_sha256', v_existing.expected_sha256,
      'part_size_bytes', v_existing.part_size_bytes,
      'total_parts', v_existing.total_parts,
      'expires_at', v_existing.expires_at,
      'file_object_id', v_existing.file_object_id,
      'correlation_id', v_existing.correlation_id
    );
  end if;

  v_total_parts := ceil(
    p_expected_byte_size::numeric / v_part_size::numeric
  )::integer;

  v_storage_path :=
    'masters/audio/' ||
    to_char(now(), 'YYYY/MM') || '/' ||
    v_session_id::text || '.' ||
    v_extension;

  insert into media.upload_sessions (
    id,
    actor_id,
    idempotency_key,
    state,
    storage_path,
    original_filename,
    file_extension,
    mime_type,
    expected_byte_size,
    expected_sha256,
    part_size_bytes,
    total_parts,
    expires_at,
    correlation_id
  )
  values (
    v_session_id,
    v_actor_id,
    p_idempotency_key,
    'created',
    v_storage_path,
    v_filename,
    v_extension,
    v_mime_type,
    p_expected_byte_size,
    v_sha256,
    v_part_size,
    v_total_parts,
    now() + make_interval(secs => p_ttl_seconds),
    v_correlation_id
  );

  return jsonb_build_object(
    'session_id', v_session_id,
    'state', 'created',
    'storage_path', v_storage_path,
    'storage_provider', 'lightsail_media',
    'storage_namespace', 'lightsail-media',
    'original_filename', v_filename,
    'mime_type', v_mime_type,
    'expected_byte_size', p_expected_byte_size,
    'expected_sha256', v_sha256,
    'part_size_bytes', v_part_size,
    'total_parts', v_total_parts,
    'expires_at', now() + make_interval(secs => p_ttl_seconds),
    'file_object_id', null,
    'correlation_id', v_correlation_id
  );
end;
$_$;


ALTER FUNCTION "public"."create_media_upload_session_v1"("p_idempotency_key" "text", "p_original_filename" "text", "p_mime_type" "text", "p_expected_byte_size" bigint, "p_expected_sha256" "text", "p_ttl_seconds" integer, "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_media_upload_session_v2"("p_idempotency_key" "text", "p_original_filename" "text", "p_mime_type" "text", "p_expected_byte_size" bigint, "p_expected_sha256" "text", "p_ttl_seconds" integer DEFAULT 86400, "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'media', 'auth'
    AS $_$
declare
  v_actor_id uuid;
  v_session_id uuid := gen_random_uuid();
  v_correlation_id uuid := coalesce(
    p_correlation_id,
    gen_random_uuid()
  );
  v_filename text := btrim(
    coalesce(p_original_filename, '')
  );
  v_mime_type text := lower(
    btrim(coalesce(p_mime_type, ''))
  );
  v_sha256 text := lower(
    btrim(coalesce(p_expected_sha256, ''))
  );
  v_extension text;
  v_master_kind text;
  v_part_size integer := 8388608;
  v_total_parts integer;
  v_storage_path text;
  v_existing media.upload_sessions%rowtype;
begin
  v_actor_id :=
    media.require_command_actor('manage_media_assets');

  if p_idempotency_key is null
     or p_idempotency_key !~
       '^[A-Za-z0-9][A-Za-z0-9._:-]{7,127}$'
  then
    raise exception
      'Upload idempotency key is invalid';
  end if;

  if v_filename = ''
     or strpos(v_filename, '.') = 0
  then
    raise exception
      'Media master filename with extension is required';
  end if;

  v_extension :=
    lower(
      reverse(
        split_part(
          reverse(v_filename),
          '.',
          1
        )
      )
    );

  if v_mime_type like 'audio/%' then
    v_master_kind := 'audio';

    if v_extension not in (
      'mp3', 'm4a', 'aac', 'wav', 'flac', 'ogg', 'oga'
    ) then
      raise exception
        'Unsupported audio master extension';
    end if;
  elsif v_mime_type like 'video/%' then
    v_master_kind := 'video';

    if v_extension not in (
      'mp4', 'mov', 'm4v', 'webm', 'mkv'
    ) then
      raise exception
        'Unsupported video master extension';
    end if;
  else
    raise exception
      'Media master MIME type must be audio or video';
  end if;

  if p_expected_byte_size is null
     or p_expected_byte_size <= 0
     or p_expected_byte_size > 2147483648
  then
    raise exception
      'Resumable Media master must be larger than zero and no larger than 2 GiB';
  end if;

  if v_sha256 !~ '^[0-9a-f]{64}$' then
    raise exception
      'Expected Media master SHA-256 is invalid';
  end if;

  if p_ttl_seconds not between 300 and 86400 then
    raise exception
      'Upload session TTL must be between 300 and 86400 seconds';
  end if;

  select session_row.*
  into v_existing
  from media.upload_sessions session_row
  where session_row.actor_id = v_actor_id
    and session_row.idempotency_key = p_idempotency_key
  for update;

  if found then
    if v_existing.original_filename is distinct from v_filename
       or v_existing.mime_type is distinct from v_mime_type
       or v_existing.expected_byte_size is distinct from p_expected_byte_size
       or v_existing.expected_sha256 is distinct from v_sha256
    then
      raise exception
        'Upload idempotency key is already bound to different file metadata';
    end if;

    return jsonb_build_object(
      'session_id', v_existing.id,
      'state', v_existing.state,
      'master_kind', v_master_kind,
      'storage_path', v_existing.storage_path,
      'storage_provider', v_existing.storage_provider,
      'storage_namespace', v_existing.storage_namespace,
      'original_filename', v_existing.original_filename,
      'mime_type', v_existing.mime_type,
      'expected_byte_size', v_existing.expected_byte_size,
      'expected_sha256', v_existing.expected_sha256,
      'part_size_bytes', v_existing.part_size_bytes,
      'total_parts', v_existing.total_parts,
      'expires_at', v_existing.expires_at,
      'file_object_id', v_existing.file_object_id,
      'correlation_id', v_existing.correlation_id
    );
  end if;

  v_total_parts := greatest(
    1,
    ceil(
      p_expected_byte_size::numeric /
      v_part_size::numeric
    )::integer
  );

  v_storage_path :=
    'masters/' ||
    v_master_kind ||
    '/' ||
    to_char(now(), 'YYYY/MM') ||
    '/' ||
    v_session_id::text ||
    '.' ||
    v_extension;

  insert into media.upload_sessions (
    id,
    actor_id,
    idempotency_key,
    state,
    storage_path,
    original_filename,
    file_extension,
    mime_type,
    expected_byte_size,
    expected_sha256,
    part_size_bytes,
    total_parts,
    expires_at,
    correlation_id
  )
  values (
    v_session_id,
    v_actor_id,
    p_idempotency_key,
    'created',
    v_storage_path,
    v_filename,
    v_extension,
    v_mime_type,
    p_expected_byte_size,
    v_sha256,
    v_part_size,
    v_total_parts,
    now() + make_interval(secs => p_ttl_seconds),
    v_correlation_id
  );

  return jsonb_build_object(
    'session_id', v_session_id,
    'state', 'created',
    'master_kind', v_master_kind,
    'storage_path', v_storage_path,
    'storage_provider', 'lightsail_media',
    'storage_namespace', 'lightsail-media',
    'original_filename', v_filename,
    'mime_type', v_mime_type,
    'expected_byte_size', p_expected_byte_size,
    'expected_sha256', v_sha256,
    'part_size_bytes', v_part_size,
    'total_parts', v_total_parts,
    'expires_at', now() + make_interval(secs => p_ttl_seconds),
    'file_object_id', null,
    'correlation_id', v_correlation_id
  );
end;
$_$;


ALTER FUNCTION "public"."create_media_upload_session_v2"("p_idempotency_key" "text", "p_original_filename" "text", "p_mime_type" "text", "p_expected_byte_size" bigint, "p_expected_sha256" "text", "p_ttl_seconds" integer, "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_playlist"("p_title" "text", "p_slug" "text", "p_idempotency_key" "text", "p_description" "text" DEFAULT NULL::"text", "p_curator_label" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("command_receipt_id" "uuid", "receipt_status" "text", "playlist_id" "uuid", "resource_id" "uuid", "authority_revision" bigint, "result_payload" "jsonb", "idempotent_replay" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'editorial', 'platform_private'
    AS $_$
declare
  v_actor uuid;
  v_principal_key text;
  v_title text;
  v_slug text;
  v_description text;
  v_curator_label text;
  v_metadata jsonb;
  v_correlation_id uuid;
  v_request jsonb;
  v_existing platform_private.command_receipts%rowtype;
  v_expected_fingerprint text;
  v_resource_id uuid;
  v_begin record;
  v_read record;
  v_result jsonb;
begin
  select context.actor_user_id, context.principal_key
  into v_actor, v_principal_key
  from platform_private.command_actor_context() context;

  if not (
    public.current_user_is_administrator()
    or public.current_user_has_capability('edit_own_playlists')
    or public.current_user_has_capability('edit_others_playlists')
  ) then
    raise exception
      using errcode = '42501', message = 'Playlist creation permission is required.';
  end if;

  if p_idempotency_key is null
     or p_idempotency_key !~
       '^[A-Za-z0-9][A-Za-z0-9._:-]{7,127}$'
  then
    raise exception
      using errcode = '22023', message = 'idempotency_key is invalid.';
  end if;

  v_title := nullif(btrim(p_title), '');
  v_slug := nullif(btrim(lower(p_slug)), '');
  v_description := nullif(btrim(p_description), '');
  v_curator_label := nullif(btrim(p_curator_label), '');
  v_metadata := coalesce(p_metadata, '{}'::jsonb);
  v_correlation_id := coalesce(p_correlation_id, gen_random_uuid());

  if v_title is null or length(v_title) > 300 then
    raise exception
      using errcode = '22023', message = 'Playlist title is required and must not exceed 300 characters.';
  end if;

  if v_slug is null
     or length(v_slug) > 200
     or v_slug !~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'
  then
    raise exception
      using errcode = '22023', message = 'Playlist slug is invalid.';
  end if;

  if length(coalesce(v_description, '')) > 10000
     or length(coalesce(v_curator_label, '')) > 500
  then
    raise exception
      using errcode = '22023', message = 'Playlist description or curator label is too long.';
  end if;

  if jsonb_typeof(v_metadata) <> 'object'
     or octet_length(v_metadata::text) > 16384
  then
    raise exception
      using errcode = '22023', message = 'Playlist metadata must be an object no larger than 16 KB.';
  end if;

  v_request := jsonb_build_object(
    'title', v_title,
    'slug', v_slug,
    'description', v_description,
    'curator_label', v_curator_label,
    'metadata', v_metadata,
    'correlation_id', v_correlation_id
  );

  perform pg_advisory_xact_lock(
    hashtextextended(
      v_principal_key || ':playlist.create:' || p_idempotency_key,
      0
    )
  );

  select receipt.*
  into v_existing
  from platform_private.command_receipts receipt
  where receipt.principal_key = v_principal_key
    and receipt.command_type = 'playlist.create'
    and receipt.idempotency_key = p_idempotency_key
  for update;

  if found then
    v_expected_fingerprint :=
      platform_private.command_request_fingerprint(
        'playlist.create',
        v_existing.resource_id,
        v_request
      );

    if v_existing.request_fingerprint <> v_expected_fingerprint then
      raise exception
        using
          errcode = '23505',
          message = 'The idempotency key was already used for a different Playlist create request.';
    end if;

    select *
    into v_read
    from platform_private.read_authenticated_resource_command_result(
      v_existing.id,
      true
    );

    command_receipt_id := v_read.command_receipt_id;
    receipt_status := v_read.receipt_status;
    playlist_id := nullif(v_read.result_payload ->> 'playlist_id', '')::uuid;
    resource_id := v_read.resource_id;
    authority_revision := nullif(
      v_read.result_payload ->> 'authority_revision',
      ''
    )::bigint;
    result_payload := v_read.result_payload;
    idempotent_replay := true;
    return next;
    return;
  end if;

  if exists (
    select 1
    from public.wk_playlists playlist
    where playlist.slug = v_slug
  ) then
    raise exception
      using errcode = '23505', message = 'Playlist slug already exists.';
  end if;

  v_resource_id := gen_random_uuid();

  insert into editorial.resources (
    id,
    resource_kind,
    owner_id,
    visibility,
    lifecycle_state,
    created_by
  )
  values (
    v_resource_id,
    'playlist',
    v_actor,
    'internal',
    'active',
    v_actor
  );

  insert into public.wk_playlists (
    id,
    title,
    slug,
    description,
    curator_label,
    status,
    cover_image_url,
    canonical_url,
    source_inquiry_id,
    source_work_product_link_id,
    metadata,
    created_by,
    authority_revision
  )
  values (
    v_resource_id,
    v_title,
    v_slug,
    v_description,
    v_curator_label,
    'draft',
    null,
    null,
    null,
    null,
    v_metadata,
    v_actor,
    1
  );

  insert into editorial.playlist_resources (
    resource_id,
    resource_kind,
    playlist_id
  )
  values (
    v_resource_id,
    'playlist',
    v_resource_id
  );

  select *
  into v_begin
  from platform_private.begin_authenticated_resource_command(
    'playlist.create',
    v_resource_id,
    p_idempotency_key,
    v_request
  );

  if v_begin.idempotent_replay then
    raise exception 'Unexpected Playlist create replay after serialized preflight.';
  end if;

  v_result := jsonb_build_object(
    'playlist_id', v_resource_id,
    'resource_id', v_resource_id,
    'slug', v_slug,
    'authority_revision', 1,
    'status', 'draft',
    'correlation_id', v_correlation_id
  );

  perform platform_private.complete_resource_command(
    v_begin.command_receipt_id,
    v_result
  );

  command_receipt_id := v_begin.command_receipt_id;
  receipt_status := 'succeeded';
  playlist_id := v_resource_id;
  resource_id := v_resource_id;
  authority_revision := 1;
  result_payload := v_result;
  idempotent_replay := false;
  return next;
end;
$_$;


ALTER FUNCTION "public"."create_playlist"("p_title" "text", "p_slug" "text", "p_idempotency_key" "text", "p_description" "text", "p_curator_label" "text", "p_metadata" "jsonb", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_playlist_preview_link"("p_playlist_id" "uuid", "p_version_id" "uuid" DEFAULT NULL::"uuid", "p_expires_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("nonce" "text", "expires_at" timestamp with time zone, "version_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'editorial'
    AS $$
declare
  v_binding editorial.playlist_resources%rowtype;
  v_version editorial.playlist_versions%rowtype;
  v_version_id uuid;
  v_nonce text := gen_random_uuid()::text;
  v_expires_at timestamptz :=
    coalesce(
      p_expires_at,
      now() + interval '7 days'
    );
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  if v_expires_at <= now() then
    raise exception
      'Preview expiry must be in the future';
  end if;

  select binding.*
  into v_binding
  from editorial.playlist_resources binding
  where binding.playlist_id = p_playlist_id;

  if not found then
    raise exception
      'Playlist Resource binding does not exist';
  end if;

  if not editorial.current_user_can_participate_playlist_review(
    v_binding.resource_id
  ) then
    raise exception
      'Playlist Preview permission is required';
  end if;

  v_version_id :=
    coalesce(
      p_version_id,
      v_binding.current_working_version_id,
      v_binding.current_submitted_version_id,
      v_binding.current_approved_version_id,
      v_binding.current_published_version_id
    );

  select version.*
  into v_version
  from editorial.playlist_versions version
  where version.id = v_version_id
    and version.playlist_id = p_playlist_id
    and version.resource_id =
          v_binding.resource_id;

  if not found then
    raise exception
      'Playlist Preview requires an immutable Playlist version';
  end if;

  insert into public.wk_playlist_preview_links (
    nonce,
    playlist_id,
    version_id,
    created_by,
    expires_at
  )
  values (
    v_nonce,
    p_playlist_id,
    v_version.id,
    auth.uid(),
    v_expires_at
  );

  nonce := v_nonce;
  expires_at := v_expires_at;
  version_id := v_version.id;
  return next;
end;
$$;


ALTER FUNCTION "public"."create_playlist_preview_link"("p_playlist_id" "uuid", "p_version_id" "uuid", "p_expires_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_public_playlist_missing_track_submission"("p_user_id" "uuid", "p_playlist_id" "uuid", "p_playlist_slug" "text", "p_track_title" "text", "p_artist_names" "text"[], "p_details" "text" DEFAULT NULL::"text", "p_provider" "jsonb" DEFAULT NULL::"jsonb", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_slug text :=
    nullif(
      btrim(p_playlist_slug),
      ''
    );
  v_title text :=
    nullif(
      btrim(p_track_title),
      ''
    );
  v_details text :=
    nullif(
      btrim(p_details),
      ''
    );
  v_key text :=
    nullif(
      btrim(p_idempotency_key),
      ''
    );
  v_resource_id uuid;
  v_artist_names text[];
  v_provider jsonb :=
    coalesce(
      p_provider,
      '{}'::jsonb
    );
  v_has_provider boolean :=
    p_provider is not null
    and p_provider <> '{}'::jsonb;
  v_provider_key text;
  v_provider_object_id text;
  v_provider_url text;
  v_canonical_url text;
  v_provider_title text;
  v_provider_artist_names text[] :=
    '{}'::text[];
  v_provider_release_title text;
  v_playback_kind text;
  v_provider_metadata jsonb :=
    '{}'::jsonb;
  v_contribution_id uuid;
  v_suggestion_id uuid;
  v_existing_suggestion_id uuid;
  v_payload jsonb;
begin
  if p_user_id is null
     or not exists (
       select 1
       from auth.users account
       where account.id = p_user_id
     )
  then
    raise exception
      'A signed-in WAKILISHA account is required.';
  end if;

  if p_playlist_id is null
     or v_slug is null
  then
    raise exception
      'Playlist context is required.';
  end if;

  select snapshot.resource_id
  into v_resource_id
  from editorial.playlist_publication_snapshots snapshot
  join editorial.playlist_resources binding
    on binding.resource_id =
         snapshot.resource_id
   and binding.playlist_id =
         snapshot.playlist_id
   and binding.current_published_version_id =
         snapshot.version_id
  where snapshot.playlist_id = p_playlist_id
    and snapshot.slug = v_slug
  order by snapshot.published_at desc
  limit 1;

  if not found then
    raise exception
      'This Playlist is not publicly available.';
  end if;

  if v_title is null
     or length(v_title) > 500
  then
    raise exception
      'Track title must be between 1 and 500 characters.';
  end if;

  select coalesce(
    array_agg(
      artist_name
      order by ordinal_position
    ),
    '{}'::text[]
  )
  into v_artist_names
  from (
    select
      nullif(
        btrim(raw_artist_name),
        ''
      ) as artist_name,
      ordinal_position
    from unnest(
      coalesce(
        p_artist_names,
        '{}'::text[]
      )
    )
    with ordinality
      as submitted_artist(
        raw_artist_name,
        ordinal_position
      )
  ) normalized_artist
  where artist_name is not null;

  if cardinality(v_artist_names) < 1
     or cardinality(v_artist_names) > 20
  then
    raise exception
      'Add between 1 and 20 artist names.';
  end if;

  if exists (
    select 1
    from unnest(v_artist_names) artist_name
    where length(artist_name) > 300
  ) then
    raise exception
      'Artist names cannot exceed 300 characters.';
  end if;

  if v_details is not null
     and length(v_details) > 10000
  then
    raise exception
      'Additional details cannot exceed 10000 characters.';
  end if;

  if v_key is null
     or length(v_key) > 200
  then
    raise exception
      'Submission key is required.';
  end if;

  if jsonb_typeof(v_provider) <> 'object' then
    raise exception
      'Provider evidence must be a JSON object.';
  end if;

  perform pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      p_user_id::text
      || '|playlist-missing-track|'
      || p_playlist_id::text
      || '|'
      || v_key,
      0
    )
  );

  select contribution.id
  into v_contribution_id
  from public.community_contributions contribution
  where contribution.user_id = p_user_id
    and contribution.entity_type = 'playlist'
    and contribution.entity_id =
          v_resource_id::text
    and contribution.contribution_type =
          'missing_track'
    and contribution.payload
          ->> 'submission_key' =
          v_key
  order by contribution.created_at
  limit 1;

  if found then
    select suggestion.id
    into v_existing_suggestion_id
    from public.registry_provider_track_suggestions suggestion
    where suggestion.source_contribution_id =
          v_contribution_id
    order by suggestion.created_at
    limit 1;

    return jsonb_build_object(
      'contribution_id',
        v_contribution_id,
      'registry_suggestion_id',
        v_existing_suggestion_id,
      'registry_queued',
        v_existing_suggestion_id is not null,
      'created',
        false
    );
  end if;

  if v_has_provider then
    v_provider_key :=
      lower(
        btrim(
          coalesce(
            v_provider
              ->> 'provider_key',
            ''
          )
        )
      );

    if v_provider_key not in (
      'youtube',
      'spotify',
      'apple_music',
      'soundcloud'
    ) then
      raise exception
        'Unsupported music provider.';
    end if;

    v_provider_object_id :=
      nullif(
        btrim(
          v_provider
            ->> 'provider_object_id'
        ),
        ''
      );

    v_provider_url :=
      nullif(
        btrim(
          v_provider
            ->> 'provider_url'
        ),
        ''
      );

    v_canonical_url :=
      nullif(
        btrim(
          coalesce(
            v_provider
              ->> 'canonical_url',
            v_provider_url
          )
        ),
        ''
      );

    v_provider_title :=
      nullif(
        btrim(
          v_provider
            ->> 'provider_title'
        ),
        ''
      );

    v_provider_release_title :=
      nullif(
        btrim(
          v_provider
            ->> 'provider_release_title'
        ),
        ''
      );

    v_playback_kind :=
      lower(
        btrim(
          coalesce(
            v_provider
              ->> 'playback_kind',
            ''
          )
        )
      );

    if v_provider_object_id is null
       or v_provider_url is null
       or v_canonical_url is null
       or v_playback_kind not in (
         'audio',
         'video'
       )
    then
      raise exception
        'Complete provider evidence is required for Registry intake.';
    end if;

    select coalesce(
      array_agg(
        artist_name
        order by ordinal_position
      ),
      '{}'::text[]
    )
    into v_provider_artist_names
    from (
      select
        nullif(
          btrim(raw_artist_name),
          ''
        ) as artist_name,
        ordinal_position
      from jsonb_array_elements_text(
        case
          when jsonb_typeof(
            v_provider
              -> 'provider_artist_names'
          ) = 'array'
          then v_provider
                 -> 'provider_artist_names'
          else '[]'::jsonb
        end
      )
      with ordinality
        as observed_artist(
          raw_artist_name,
          ordinal_position
        )
    ) normalized_provider_artist
    where artist_name is not null;

    v_provider_metadata :=
      case
        when jsonb_typeof(
          v_provider
            -> 'provider_metadata'
        ) = 'object'
        then v_provider
               -> 'provider_metadata'
        else '{}'::jsonb
      end;
  else
    v_provider_url := null;
  end if;

  v_payload :=
    jsonb_strip_nulls(
      jsonb_build_object(
        'submission_key',
          v_key,
        'track_title',
          v_title,
        'artist_names',
          to_jsonb(v_artist_names),
        'track_url',
          v_provider_url,
        'details',
          v_details,
        'registry_queued',
          true
      )
    );

  insert into public.community_contributions (
    user_id,
    source_comment_id,
    entity_type,
    entity_id,
    entity_slug,
    contribution_type,
    payload,
    status
  )
  values (
    p_user_id,
    null,
    'playlist',
    v_resource_id::text,
    v_slug,
    'missing_track',
    v_payload,
    'pending'
  )
  returning id
  into v_contribution_id;

  v_suggestion_id :=
    gen_random_uuid();

  insert into public.registry_provider_track_suggestions (
    id,
    source_playlist_id,
    source_playlist_item_id,
    requested_by,
    canonical_track_id,
    registry_artist_id,
    artist_resolution_mode,
    provider_key,
    provider_object_id,
    provider_url,
    provider_title,
    provider_artist_names,
    provider_release_title,
    playback_kind,
    validation_snapshot,
    status,
    reserved_position,
    intake_origin,
    source_contribution_id,
    submitted_track_title
  )
  values (
    v_suggestion_id,
    p_playlist_id,
    null,
    p_user_id,
    null,
    null,
    'unresolved',
    v_provider_key,
    v_provider_object_id,
    v_canonical_url,
    v_provider_title,
    v_provider_artist_names,
    v_provider_release_title,
    v_playback_kind,
    jsonb_strip_nulls(
      jsonb_build_object(
        'embed_url',
          nullif(
            btrim(
              v_provider
                ->> 'embed_url'
            ),
            ''
          ),
        'preview_url',
          nullif(
            btrim(
              v_provider
                ->> 'preview_url'
            ),
            ''
          ),
        'artwork_url',
          nullif(
            btrim(
              v_provider
                ->> 'artwork_url'
            ),
            ''
          ),
        'provider_metadata',
          v_provider_metadata,
        'checked_at',
          coalesce(
            nullif(
              btrim(
                v_provider
                  ->> 'checked_at'
              ),
              ''
            ),
            now()::text
          ),
        'validation_mode',
          case
            when v_has_provider
              then 'public_missing_track_submission'
            else 'public_missing_track_manual'
          end
      )
    ),
    'needs_review',
    null,
    'public_contribution',
    v_contribution_id,
    v_title
  );

  insert into public.registry_provider_track_suggestion_artists (
    suggestion_id,
    credit_order,
    credit_role,
    resolution_mode,
    registry_artist_id,
    observed_name
  )
  select
    v_suggestion_id,
    ordinal_position::integer,
    'unresolved',
    'unresolved',
    null,
    artist_name
  from unnest(v_artist_names)
    with ordinality
      as submitted_artist(
        artist_name,
        ordinal_position
      );

  update public.community_contributions contribution
  set
    payload =
      contribution.payload
      || jsonb_build_object(
           'registry_suggestion_id',
             v_suggestion_id,
           'registry_queued',
             true
         ),
    updated_at = now()
  where contribution.id =
    v_contribution_id;

  return jsonb_build_object(
    'contribution_id',
      v_contribution_id,
    'registry_suggestion_id',
      v_suggestion_id,
    'registry_queued',
      true,
    'created',
      true
  );
end;
$$;


ALTER FUNCTION "public"."create_public_playlist_missing_track_submission"("p_user_id" "uuid", "p_playlist_id" "uuid", "p_playlist_slug" "text", "p_track_title" "text", "p_artist_names" "text"[], "p_details" "text", "p_provider" "jsonb", "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_public_playlist_missing_track_submission"("p_user_id" "uuid", "p_playlist_id" "uuid", "p_playlist_slug" "text", "p_track_title" "text", "p_artist_names" "text"[], "p_details" "text", "p_provider" "jsonb", "p_idempotency_key" "text") IS 'Service-only atomic bridge from a signed-in public Playlist missing-track submission into Community contribution authority and, when validated provider evidence exists, Registry Track Intake.';



CREATE OR REPLACE FUNCTION "public"."create_publishing_item"("p_title" "text", "p_content_kind" "text", "p_resource_id" "uuid" DEFAULT NULL::"uuid", "p_owner_id" "uuid" DEFAULT NULL::"uuid", "p_brief" "text" DEFAULT NULL::"text", "p_production_stage" "text" DEFAULT 'idea'::"text", "p_priority" "text" DEFAULT 'normal'::"text", "p_production_deadline" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_planned_publish_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_note" "text" DEFAULT NULL::"text") RETURNS TABLE("item_id" "uuid", "record_version" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_item editorial.publishing_items%rowtype;
begin
  if auth.uid() is null then
    raise exception
      using
        errcode = '42501',
        message = 'Authentication required';
  end if;

  if not editorial.current_user_can_manage_publishing() then
    raise exception
      using
        errcode = '42501',
        message = 'Permission denied';
  end if;

  if nullif(btrim(p_title), '') is null then
    raise exception 'A Publishing item title is required';
  end if;

  insert into editorial.publishing_items (
    resource_id,
    title,
    content_kind,
    brief,
    production_stage,
    priority,
    owner_id,
    production_deadline,
    planned_publish_at,
    created_by,
    updated_by
  )
  values (
    p_resource_id,
    btrim(p_title),
    p_content_kind,
    nullif(btrim(p_brief), ''),
    p_production_stage,
    p_priority,
    p_owner_id,
    p_production_deadline,
    p_planned_publish_at,
    auth.uid(),
    auth.uid()
  )
  returning *
  into v_item;

  insert into editorial.publishing_item_events (
    item_id,
    action,
    prior_record_version,
    resulting_record_version,
    resulting_values,
    note,
    actor_id
  )
  values (
    v_item.id,
    'created',
    0,
    1,
    editorial.publishing_item_snapshot(v_item),
    nullif(btrim(p_note), ''),
    auth.uid()
  );

  item_id := v_item.id;
  record_version := v_item.record_version;
  return next;
end;
$$;


ALTER FUNCTION "public"."create_publishing_item"("p_title" "text", "p_content_kind" "text", "p_resource_id" "uuid", "p_owner_id" "uuid", "p_brief" "text", "p_production_stage" "text", "p_priority" "text", "p_production_deadline" timestamp with time zone, "p_planned_publish_at" timestamp with time zone, "p_note" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."cultural_entities" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "entity_type" "text" NOT NULL,
    "source_table" "text",
    "source_id" "text",
    "name" "text" NOT NULL,
    "slug" "text",
    "description" "text",
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "canonical_source_table" "text",
    "canonical_source_id" "uuid",
    "review_status" "text" DEFAULT 'unreviewed'::"text" NOT NULL,
    "public_safe" boolean DEFAULT false NOT NULL,
    "reviewed_by" "uuid",
    "reviewed_at" timestamp with time zone,
    "review_note" "text",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    CONSTRAINT "cultural_entities_canonical_pointer_check" CHECK (((("canonical_source_table" IS NULL) AND ("canonical_source_id" IS NULL)) OR (("canonical_source_table" IS NOT NULL) AND ("canonical_source_id" IS NOT NULL)))),
    CONSTRAINT "cultural_entities_entity_type_check" CHECK (("entity_type" = ANY (ARRAY['artist'::"text", 'track'::"text", 'release'::"text", 'label'::"text", 'genre'::"text", 'person'::"text", 'scene'::"text", 'place'::"text", 'event'::"text", 'institution'::"text", 'work'::"text", 'concept'::"text", 'language'::"text", 'movement'::"text", 'publication'::"text", 'organization'::"text", 'article'::"text", 'inquiry'::"text", 'memory'::"text", 'source'::"text"]))),
    CONSTRAINT "cultural_entities_public_safe_check" CHECK ((("public_safe" = false) OR (("review_status" = 'approved'::"text") AND ("status" = 'active'::"text") AND ("reviewed_at" IS NOT NULL) AND (NULLIF("btrim"("description"), ''::"text") IS NOT NULL)))),
    CONSTRAINT "cultural_entities_review_status_check" CHECK (("review_status" = ANY (ARRAY['unreviewed'::"text", 'pending_review'::"text", 'approved'::"text", 'rejected'::"text", 'disputed'::"text", 'superseded'::"text"]))),
    CONSTRAINT "cultural_entities_source_pair" CHECK (((("source_table" IS NULL) AND ("source_id" IS NULL)) OR (("source_table" IS NOT NULL) AND ("source_id" IS NOT NULL)))),
    CONSTRAINT "cultural_entities_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'draft'::"text", 'merged'::"text", 'archived'::"text"])))
);


ALTER TABLE "public"."cultural_entities" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_registry_cultural_entity"("p_entity_type" "text", "p_name" "text", "p_slug" "text" DEFAULT NULL::"text", "p_description" "text" DEFAULT NULL::"text", "p_source_table" "text" DEFAULT NULL::"text", "p_source_id" "text" DEFAULT NULL::"text", "p_canonical_source_table" "text" DEFAULT NULL::"text", "p_canonical_source_id" "uuid" DEFAULT NULL::"uuid", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "public"."cultural_entities"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare v_created public.cultural_entities;
begin
  if not public.institute_can_manage() then raise exception 'You do not have permission to create Registry cultural entities.'; end if;
  if p_entity_type not in ('person','scene','place','event','institution','work','concept','language','movement','publication','organization','article','inquiry','memory','source') then raise exception 'This workflow only creates broader cultural entities. Use the authoritative music Registry tables for artists, tracks, releases, labels, and genres.'; end if;
  if nullif(btrim(p_name),'') is null then raise exception 'A cultural entity name is required.'; end if;
  if (p_source_table is null) <> (p_source_id is null) then raise exception 'Source table and source ID must be provided together.'; end if;
  if (p_canonical_source_table is null) <> (p_canonical_source_id is null) then raise exception 'Canonical source table and canonical source ID must be provided together.'; end if;
  insert into public.cultural_entities(entity_type,source_table,source_id,name,slug,description,status,canonical_source_table,canonical_source_id,review_status,public_safe,metadata)
  values(p_entity_type,nullif(btrim(p_source_table),''),nullif(btrim(p_source_id),''),btrim(p_name),nullif(btrim(p_slug),''),nullif(btrim(p_description),''),'draft',nullif(btrim(p_canonical_source_table),''),p_canonical_source_id,'unreviewed',false,coalesce(p_metadata,'{}'::jsonb))
  returning * into v_created;
  return v_created;
end;
$$;


ALTER FUNCTION "public"."create_registry_cultural_entity"("p_entity_type" "text", "p_name" "text", "p_slug" "text", "p_description" "text", "p_source_table" "text", "p_source_id" "text", "p_canonical_source_table" "text", "p_canonical_source_id" "uuid", "p_metadata" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_registry_cultural_entity"("p_entity_type" "text", "p_name" "text", "p_slug" "text", "p_description" "text", "p_source_table" "text", "p_source_id" "text", "p_canonical_source_table" "text", "p_canonical_source_id" "uuid", "p_metadata" "jsonb") IS 'Creates a draft broader cultural entity through the controlled Registry workflow.';



CREATE OR REPLACE FUNCTION "public"."create_registry_entity_relationship"("p_source_entity_type" "text", "p_source_entity_id" "uuid", "p_target_entity_type" "text", "p_target_entity_id" "uuid", "p_relationship_type" "text", "p_relationship_role" "text" DEFAULT NULL::"text", "p_plain_reason" "text" DEFAULT NULL::"text", "p_valid_from" "date" DEFAULT NULL::"date", "p_valid_to" "date" DEFAULT NULL::"date", "p_evidence_id" "uuid" DEFAULT NULL::"uuid", "p_evidence_support_type" "text" DEFAULT 'supports'::"text", "p_evidence_note" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "public"."registry_entity_relationships"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_source public.registry_entity_index;
  v_target public.registry_entity_index;
  v_created public.registry_entity_relationships;
begin
  if not (
    auth.role() = 'service_role'
    or public.current_user_has_capability('manage_registry')
    or public.current_user_has_capability('manage_review_queue')
    or public.current_user_is_administrator()
  ) then
    raise exception 'You do not have permission to create Registry relationships.';
  end if;

  if nullif(btrim(p_source_entity_type), '') is null
     or nullif(btrim(p_target_entity_type), '') is null then
    raise exception 'Source and target entity types are required.';
  end if;

  if nullif(btrim(p_relationship_type), '') is null then
    raise exception 'A relationship type is required.';
  end if;

  if p_source_entity_type = p_target_entity_type
     and p_source_entity_id = p_target_entity_id then
    raise exception 'A Registry entity cannot be related to itself.';
  end if;

  if p_valid_from is not null and p_valid_to is not null and p_valid_to < p_valid_from then
    raise exception 'Relationship end date cannot be earlier than its start date.';
  end if;

  if p_evidence_support_type not in ('supports', 'challenges', 'contextualizes') then
    raise exception 'Unsupported evidence relationship type.';
  end if;

  select * into v_source
  from public.registry_entity_index
  where entity_type = btrim(p_source_entity_type)
    and entity_id = p_source_entity_id
  limit 1;

  if not found then
    raise exception 'Source Registry entity was not found in the canonical entity index.';
  end if;

  select * into v_target
  from public.registry_entity_index
  where entity_type = btrim(p_target_entity_type)
    and entity_id = p_target_entity_id
  limit 1;

  if not found then
    raise exception 'Target Registry entity was not found in the canonical entity index.';
  end if;

  if exists (
    select 1
    from public.registry_entity_relationships r
    where r.source_entity_id = p_source_entity_id
      and r.target_entity_id = p_target_entity_id
      and r.source_entity_type = v_source.entity_type
      and r.target_entity_type = v_target.entity_type
      and r.relationship_type = btrim(p_relationship_type)
      and r.relationship_role is not distinct from nullif(btrim(p_relationship_role), '')
      and r.relationship_status <> 'archived'
  ) then
    raise exception 'An active Registry relationship with the same endpoints, type, and role already exists.';
  end if;

  if p_evidence_id is not null
     and not exists (select 1 from public.evidence_items where id = p_evidence_id) then
    raise exception 'Evidence item not found.';
  end if;

  insert into public.registry_entity_relationships (
    source_entity_type, source_slug, target_entity_type, target_slug,
    relationship_type, relationship_role, relationship_status,
    source_kind, source_entity, source_record_id, confidence, metadata,
    source_entity_id, target_entity_id, plain_reason, review_status,
    public_safe, valid_from, valid_to, created_by, updated_by
  ) values (
    v_source.entity_type,
    coalesce(nullif(btrim(v_source.slug), ''), v_source.entity_id::text),
    v_target.entity_type,
    coalesce(nullif(btrim(v_target.slug), ''), v_target.entity_id::text),
    btrim(p_relationship_type),
    nullif(btrim(p_relationship_role), ''),
    'draft',
    'registry_workflow',
    v_source.canonical_source_table,
    v_source.canonical_source_id::text,
    null,
    coalesce(p_metadata, '{}'::jsonb),
    p_source_entity_id,
    p_target_entity_id,
    nullif(btrim(p_plain_reason), ''),
    'unreviewed',
    false,
    p_valid_from,
    p_valid_to,
    auth.uid(),
    auth.uid()
  )
  returning * into v_created;

  if p_evidence_id is not null then
    insert into public.registry_relationship_evidence (
      relationship_id, evidence_id, support_type, note, created_by
    ) values (
      v_created.id,
      p_evidence_id,
      p_evidence_support_type,
      nullif(btrim(p_evidence_note), ''),
      auth.uid()
    );
  end if;

  return v_created;
end;
$$;


ALTER FUNCTION "public"."create_registry_entity_relationship"("p_source_entity_type" "text", "p_source_entity_id" "uuid", "p_target_entity_type" "text", "p_target_entity_id" "uuid", "p_relationship_type" "text", "p_relationship_role" "text", "p_plain_reason" "text", "p_valid_from" "date", "p_valid_to" "date", "p_evidence_id" "uuid", "p_evidence_support_type" "text", "p_evidence_note" "text", "p_metadata" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_registry_entity_relationship"("p_source_entity_type" "text", "p_source_entity_id" "uuid", "p_target_entity_type" "text", "p_target_entity_id" "uuid", "p_relationship_type" "text", "p_relationship_role" "text", "p_plain_reason" "text", "p_valid_from" "date", "p_valid_to" "date", "p_evidence_id" "uuid", "p_evidence_support_type" "text", "p_evidence_note" "text", "p_metadata" "jsonb") IS 'Creates a draft relationship between canonical Registry entities and optionally attaches evidence atomically.';



CREATE TABLE IF NOT EXISTS "public"."contributor_submissions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "contributor_id" "uuid" NOT NULL,
    "inquiry_id" "uuid",
    "entity_id" "uuid",
    "submission_type" "text" NOT NULL,
    "title" "text",
    "body" "text" NOT NULL,
    "source_url" "text",
    "source_note" "text",
    "consent_status" "text" DEFAULT 'internal_use'::"text" NOT NULL,
    "review_status" "text" DEFAULT 'submitted'::"text" NOT NULL,
    "reviewed_by" "uuid",
    "reviewed_at" timestamp with time zone,
    "review_note" "text",
    "accepted_evidence_id" "uuid",
    "accepted_relationship_id" "uuid",
    "correction_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "contributor_submissions_consent_status_check" CHECK (("consent_status" = ANY (ARRAY['private'::"text", 'internal_use'::"text", 'public_review_allowed'::"text"]))),
    CONSTRAINT "contributor_submissions_review_status_check" CHECK (("review_status" = ANY (ARRAY['submitted'::"text", 'triaged'::"text", 'needs_source'::"text", 'needs_clarification'::"text", 'accepted_as_memory'::"text", 'accepted_as_evidence'::"text", 'accepted_as_relationship_context'::"text", 'rejected'::"text", 'merged'::"text", 'archived'::"text"]))),
    CONSTRAINT "contributor_submissions_submission_type_check" CHECK (("submission_type" = ANY (ARRAY['memory'::"text", 'evidence'::"text", 'relationship_suggestion'::"text", 'correction'::"text", 'context_note'::"text"])))
);


ALTER TABLE "public"."contributor_submissions" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_registry_missing_artist_intake"("p_legacy_slug" "text", "p_display_name" "text", "p_reason" "text", "p_source_url" "text" DEFAULT NULL::"text") RETURNS "public"."contributor_submissions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $_$ declare s text:=lower(btrim(p_legacy_slug)); r public.contributor_submissions; c uuid; n text; begin if not(auth.role()='service_role' or public.current_user_has_capability('manage_registry') or public.current_user_has_capability('manage_review_queue') or public.current_user_is_administrator()) then raise exception 'You do not have permission to create Registry artist intake submissions.'; end if; if nullif(s,'') is null or s !~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' then raise exception 'A valid missing artist slug is required.'; end if; if nullif(btrim(p_display_name),'') is null then raise exception 'A proposed artist display name is required.'; end if; if nullif(btrim(p_reason),'') is null then raise exception 'An intake reason is required.'; end if; if not exists(select 1 from public.registry_relationship_endpoint_work_queue q where q.endpoint_work_state='missing_entity' and q.missing_entity_type='artist' and q.legacy_slug=s) then raise exception 'This slug is not currently required by the missing-artist endpoint queue.'; end if; if exists(select 1 from public.registry_artists a where a.slug=s) then raise exception 'A canonical Registry artist already exists for this slug.'; end if; if exists(select 1 from public.contributor_submissions x where x.source_note like 'missing_artist_slug:'||s||'%' and x.review_status not in('rejected','archived','merged')) then raise exception 'An active intake submission already exists for this missing artist.'; end if; select id into c from public.contributors where user_id=auth.uid(); if c is null then n:=coalesce(nullif(auth.jwt()->>'name',''),nullif(auth.jwt()->>'email',''),'Registry administrator'); insert into public.contributors(user_id,display_name,role_note,contributor_status,trust_level) values(auth.uid(),n,'Created automatically for internal Registry review work.','active','trusted') on conflict(user_id) where user_id is not null do update set updated_at=now() returning id into c; end if; insert into public.contributor_submissions(contributor_id,submission_type,title,body,source_url,source_note,consent_status,review_status) values(c,'context_note',btrim(p_display_name),btrim(p_reason),nullif(btrim(p_source_url),''),'missing_artist_slug:'||s||' source:registry_relationship_endpoint_work_queue','internal_use','submitted') returning * into r; return r; end; $_$;


ALTER FUNCTION "public"."create_registry_missing_artist_intake"("p_legacy_slug" "text", "p_display_name" "text", "p_reason" "text", "p_source_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_registry_track_intake_suggestion"("p_playlist_id" "uuid", "p_validation_id" "uuid", "p_artist_resolution_mode" "text", "p_registry_artist_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'auth', 'public', 'platform_private'
    AS $$
declare
  v_validation platform_private.playlist_playback_validations%rowtype;
  v_suggestion_id uuid := gen_random_uuid();
  v_mode text := lower(btrim(coalesce(p_artist_resolution_mode, '')));
begin
  if auth.uid() is null then
    raise exception
      using errcode = '42501', message = 'Authentication is required.';
  end if;

  if not public.current_user_can_edit_playlist_id(p_playlist_id) then
    raise exception
      using errcode = '42501', message = 'Playlist edit permission is required.';
  end if;

  select validation.*
  into v_validation
  from platform_private.playlist_playback_validations validation
  where validation.id = p_validation_id
    and validation.requested_by = auth.uid()
    and validation.playlist_id = p_playlist_id
    and validation.playable
    and validation.validation_status = 'playable'
    and validation.expires_at > now();

  if not found then
    raise exception
      'Playback validation is missing or expired. Check the provider link again.';
  end if;

  if v_mode not in (
    'existing_artist',
    'alias_candidate',
    'new_artist',
    'unresolved'
  ) then
    raise exception
      'Artist resolution must use Registry identity, an alias candidate, a new-artist suggestion, or remain unresolved.';
  end if;

  if v_mode in ('existing_artist', 'alias_candidate') then
    if p_registry_artist_id is null
       or not exists (
         select 1
         from public.registry_artists artist
         where artist.id = p_registry_artist_id
           and artist.status in ('active', 'draft')
       )
    then
      raise exception
        'Select a Music Registry artist for this resolution.';
    end if;
  elsif p_registry_artist_id is not null then
    raise exception
      'New-artist and unresolved suggestions cannot claim an existing Registry artist.';
  end if;

  insert into public.registry_provider_track_suggestions (
    id,
    source_playlist_id,
    requested_by,
    canonical_track_id,
    registry_artist_id,
    artist_resolution_mode,
    provider_key,
    provider_object_id,
    provider_url,
    provider_title,
    provider_artist_names,
    provider_release_title,
    playback_kind,
    validation_snapshot,
    status
  )
  values (
    v_suggestion_id,
    p_playlist_id,
    auth.uid(),
    null,
    p_registry_artist_id,
    v_mode,
    v_validation.provider_key,
    v_validation.provider_object_id,
    v_validation.canonical_url,
    v_validation.title_hint,
    v_validation.artist_names_hint,
    v_validation.release_title_hint,
    v_validation.playback_kind,
    jsonb_build_object(
      'validation_id', v_validation.id,
      'embed_url', v_validation.embed_url,
      'preview_url', v_validation.preview_url,
      'artwork_url', v_validation.artwork_url,
      'provider_metadata', v_validation.provider_metadata,
      'checked_at', v_validation.checked_at
    ),
    'needs_review'
  );

  return jsonb_build_object(
    'suggestion_id', v_suggestion_id,
    'status', 'needs_review',
    'playlist_changed', false
  );
end;
$$;


ALTER FUNCTION "public"."create_registry_track_intake_suggestion"("p_playlist_id" "uuid", "p_validation_id" "uuid", "p_artist_resolution_mode" "text", "p_registry_artist_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_source"("p_metadata" "jsonb", "p_registry_links" "jsonb" DEFAULT '[]'::"jsonb", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial', 'auth'
    AS $$
declare
  v_actor_id uuid;
  v_metadata jsonb;
  v_registry_links jsonb;
  v_fingerprint text;
  v_source_id uuid;
  v_source_version_id uuid;
begin
  v_actor_id :=
    editorial.assert_source_command_actor('manage_sources');

  v_metadata :=
    editorial.normalize_source_metadata(p_metadata);

  v_registry_links :=
    editorial.normalize_source_registry_links(p_registry_links);

  if not exists (
    select 1
    from editorial.source_types source_type
    where source_type.source_type =
            v_metadata ->> 'source_type'
      and source_type.enabled
  ) then
    raise exception
      'Choose an enabled Source type';
  end if;

  if v_metadata ? 'media_asset_id'
     and not exists (
       select 1
       from public.registry_media_assets media_asset
       where media_asset.id =
         (v_metadata ->> 'media_asset_id')::uuid
     ) then
    raise exception
      'Source Media asset was not found';
  end if;

  v_fingerprint :=
    editorial.source_content_fingerprint(
      v_metadata,
      v_registry_links
    );

  insert into editorial.sources (
    source_type,
    title,
    creator_display,
    publisher_display,
    source_url,
    media_asset_id,
    archive_identifier,
    publication_date,
    capture_date,
    retrieval_date,
    language_code,
    country_code,
    place_text,
    rights_status,
    consent_status,
    sensitivity,
    reliability_note,
    credit_line,
    internal_notes,
    review_status,
    exposure_class,
    source_state,
    working_revision,
    created_by,
    updated_by
  )
  values (
    v_metadata ->> 'source_type',
    v_metadata ->> 'title',
    v_metadata ->> 'creator_display',
    v_metadata ->> 'publisher_display',
    v_metadata ->> 'source_url',
    (v_metadata ->> 'media_asset_id')::uuid,
    v_metadata ->> 'archive_identifier',
    (v_metadata ->> 'publication_date')::date,
    (v_metadata ->> 'capture_date')::date,
    (v_metadata ->> 'retrieval_date')::date,
    v_metadata ->> 'language_code',
    v_metadata ->> 'country_code',
    v_metadata ->> 'place_text',
    coalesce(
      v_metadata ->> 'rights_status',
      'unknown'
    ),
    coalesce(
      v_metadata ->> 'consent_status',
      'unknown'
    ),
    coalesce(
      v_metadata ->> 'sensitivity',
      'none'
    ),
    v_metadata ->> 'reliability_note',
    v_metadata ->> 'credit_line',
    v_metadata ->> 'internal_notes',
    'draft',
    'internal',
    'active',
    1,
    v_actor_id,
    v_actor_id
  )
  returning id
  into v_source_id;

  insert into editorial.source_versions (
    source_id,
    version_number,
    source_type,
    title,
    creator_display,
    publisher_display,
    source_url,
    media_asset_id,
    archive_identifier,
    publication_date,
    capture_date,
    retrieval_date,
    language_code,
    country_code,
    place_text,
    rights_status,
    consent_status,
    sensitivity,
    reliability_note,
    credit_line,
    internal_notes,
    created_by,
    content_fingerprint
  )
  values (
    v_source_id,
    1,
    v_metadata ->> 'source_type',
    v_metadata ->> 'title',
    v_metadata ->> 'creator_display',
    v_metadata ->> 'publisher_display',
    v_metadata ->> 'source_url',
    (v_metadata ->> 'media_asset_id')::uuid,
    v_metadata ->> 'archive_identifier',
    (v_metadata ->> 'publication_date')::date,
    (v_metadata ->> 'capture_date')::date,
    (v_metadata ->> 'retrieval_date')::date,
    v_metadata ->> 'language_code',
    v_metadata ->> 'country_code',
    v_metadata ->> 'place_text',
    coalesce(
      v_metadata ->> 'rights_status',
      'unknown'
    ),
    coalesce(
      v_metadata ->> 'consent_status',
      'unknown'
    ),
    coalesce(
      v_metadata ->> 'sensitivity',
      'none'
    ),
    v_metadata ->> 'reliability_note',
    v_metadata ->> 'credit_line',
    v_metadata ->> 'internal_notes',
    v_actor_id,
    v_fingerprint
  )
  returning id
  into v_source_version_id;

  perform editorial.insert_source_registry_links(
    v_source_id,
    v_source_version_id,
    v_registry_links,
    v_actor_id
  );

  update editorial.sources
  set
    current_working_version_id = v_source_version_id,
    updated_by = v_actor_id,
    updated_at = now()
  where id = v_source_id;

  insert into editorial.source_review_events (
    source_id,
    source_version_id,
    actor_id,
    action,
    prior_review_status,
    resulting_review_status,
    prior_exposure_class,
    resulting_exposure_class,
    prior_source_state,
    resulting_source_state,
    correlation_id
  )
  values (
    v_source_id,
    v_source_version_id,
    v_actor_id,
    'created',
    null,
    'draft',
    null,
    'internal',
    null,
    'active',
    p_correlation_id
  );

  return jsonb_build_object(
    'source_id',
      v_source_id,
    'source_version_id',
      v_source_version_id,
    'working_revision',
      1,
    'created',
      true
  );
end;
$$;


ALTER FUNCTION "public"."create_source"("p_metadata" "jsonb", "p_registry_links" "jsonb", "p_correlation_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_source"("p_metadata" "jsonb", "p_registry_links" "jsonb", "p_correlation_id" "uuid") IS 'Creates one governed Source and immutable Source version 1.';



CREATE OR REPLACE FUNCTION "public"."create_taxonomy_term"("p_taxonomy" "text", "p_slug" "text", "p_name" "text", "p_description" "text" DEFAULT NULL::"text", "p_seo_title" "text" DEFAULT NULL::"text", "p_seo_description" "text" DEFAULT NULL::"text", "p_seo_keywords" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "slug" "text", "name" "text", "description" "text", "seo_title" "text", "seo_description" "text", "seo_keywords" "text", "source_kind" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_user_id uuid;
  v_term_id uuid;
  v_metadata jsonb;
  v_required_capability text;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception 'Not authenticated';
  end if;

  v_required_capability :=
    case p_taxonomy
      when 'category' then 'manage_categories'
      when 'post_tag' then 'manage_tags'
      else null
    end;

  if v_required_capability is null then
    raise exception
      'Unsupported taxonomy: %',
      p_taxonomy;
  end if;

  if not exists (
    select 1
    from public.user_role_assignments assignment
    where assignment.user_id = v_user_id
      and assignment.status = 'active'
      and (
        assignment.expires_at is null
        or assignment.expires_at > now()
      )
      and (
        assignment.role_key = 'administrator'
        or exists (
          select 1
          from public.role_capabilities capability
          where capability.role_key = assignment.role_key
            and capability.capability_key =
              v_required_capability
        )
      )
  ) then
    raise exception
      'Permission denied: % capability required',
      v_required_capability;
  end if;

  if exists (
    select 1
    from public.registry_taxonomy_terms existing_term
    where existing_term.slug = p_slug
      and existing_term.taxonomy = p_taxonomy
  ) then
    raise exception
      'Term with slug "%" already exists in taxonomy "%"',
      p_slug,
      p_taxonomy;
  end if;

  v_metadata := jsonb_strip_nulls(
    jsonb_build_object(
      'seo_title', p_seo_title,
      'seo_description', p_seo_description,
      'seo_keywords', p_seo_keywords
    )
  );

  insert into public.registry_taxonomy_terms as inserted_term (
    taxonomy,
    slug,
    name,
    description,
    status,
    source_kind,
    metadata,
    created_at,
    updated_at
  ) values (
    p_taxonomy,
    p_slug,
    p_name,
    p_description,
    'active',
    'editor_ui',
    v_metadata,
    now(),
    now()
  )
  returning inserted_term.id
  into v_term_id;

  return query
  select
    created_term.id,
    created_term.slug,
    created_term.name,
    created_term.description,
    created_term.metadata ->> 'seo_title',
    created_term.metadata ->> 'seo_description',
    created_term.metadata ->> 'seo_keywords',
    created_term.source_kind,
    created_term.created_at,
    created_term.updated_at
  from public.registry_taxonomy_terms created_term
  where created_term.id = v_term_id;
end;
$$;


ALTER FUNCTION "public"."create_taxonomy_term"("p_taxonomy" "text", "p_slug" "text", "p_name" "text", "p_description" "text", "p_seo_title" "text", "p_seo_description" "text", "p_seo_keywords" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_taxonomy_term"("p_taxonomy" "text", "p_slug" "text", "p_name" "text", "p_description" "text", "p_seo_title" "text", "p_seo_description" "text", "p_seo_keywords" "text") IS 'Creates one governed category or post tag with taxonomy-specific capability validation and fully qualified registry references.';



