CREATE OR REPLACE FUNCTION "public"."delete_batch_from_staging"("batch_size" integer) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "statement_timeout" TO '0'
    SET "lock_timeout" TO '0'
    AS $$
DECLARE
  deleted_count integer;
BEGIN
  DELETE FROM wk_import_staging_records
  WHERE ctid IN (
    SELECT ctid FROM wk_import_staging_records
    LIMIT batch_size
  );
  GET DIAGNOSTICS deleted_count = ROW_COUNT;
  RETURN deleted_count;
END;
$$;


ALTER FUNCTION "public"."delete_batch_from_staging"("batch_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_taxonomy_term"("p_term_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "row_security" TO 'off'
    AS $$
DECLARE
  v_user_id uuid;
BEGIN
  v_user_id := auth.uid();

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM user_role_assignments
    WHERE user_id = v_user_id
      AND status = 'active'
      AND (expires_at IS NULL OR expires_at > now())
      AND (role_key = 'administrator' OR role_key IN (
        SELECT role_key FROM role_capabilities WHERE capability_key = 'manage_categories'
      ))
  ) THEN
    RAISE EXCEPTION 'Permission denied: manage_categories capability required';
  END IF;

  DELETE FROM registry_taxonomy_terms WHERE id = p_term_id;
END;
$$;


