CREATE OR REPLACE FUNCTION "public"."detach_media_usage"("p_usage_link_id" "uuid", "p_expected_usage_revision" bigint, "p_reason" "text", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("usage_link_id" "uuid", "usage_state" "text", "usage_revision" bigint, "correlation_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'media', 'auth'
    AS $$
declare
  v_actor_id uuid;
  v_usage media.usage_links%rowtype;
  v_new_revision bigint;
  v_correlation_id uuid := coalesce(
    p_correlation_id,
    gen_random_uuid()
  );
begin
  v_actor_id :=
    media.require_command_actor('manage_media_usage');

  if nullif(btrim(p_reason), '') is null then
    raise exception
      'Media usage detachment reason is required';
  end if;

  select usage_row.*
  into v_usage
  from media.usage_links usage_row
  where usage_row.id = p_usage_link_id
  for update;

  if not found then
    raise exception
      'Media usage does not exist';
  end if;

  if v_usage.usage_revision <>
     p_expected_usage_revision
  then
    raise exception
      'Stale Media usage revision';
  end if;

  perform media.validate_usage_target(
    v_actor_id,
    v_usage.target_authority,
    v_usage.target_kind,
    v_usage.target_id,
    v_usage.target_version_kind,
    v_usage.target_version_id,
    true,
    false
  );

  if v_usage.usage_state <> 'active' then
    raise exception
      'Only an active Media usage may be detached';
  end if;

  update media.usage_links as usage_row
  set
    usage_state = 'detached',
    usage_revision =
      usage_row.usage_revision + 1,
    state_reason = btrim(p_reason),
    state_changed_by = v_actor_id,
    state_changed_at = now(),
    updated_at = now()
  where usage_row.id = p_usage_link_id
  returning usage_row.usage_revision
  into v_new_revision;

  insert into media.events (
    asset_id,
    asset_revision_id,
    usage_link_id,
    event_type,
    actor_id,
    reason,
    prior_state,
    resulting_state,
    correlation_id
  )
  values (
    v_usage.asset_id,
    v_usage.asset_revision_id,
    v_usage.id,
    'usage_detached',
    v_actor_id,
    btrim(p_reason),
    jsonb_build_object(
      'usage_state', v_usage.usage_state,
      'usage_revision', v_usage.usage_revision
    ),
    jsonb_build_object(
      'usage_state', 'detached',
      'usage_revision', v_new_revision
    ),
    v_correlation_id
  );

  return query
  select
    p_usage_link_id,
    'detached'::text,
    v_new_revision,
    v_correlation_id;
end;
$$;


ALTER FUNCTION "public"."detach_media_usage"("p_usage_link_id" "uuid", "p_expected_usage_revision" bigint, "p_reason" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."discover_unknown_artist_slugs"() RETURNS TABLE("unknown_slug" "text", "source_table" "text", "occurrence_count" bigint, "sample_display_name" "text")
    LANGUAGE "plpgsql" STABLE
    AS $$
BEGIN
  RETURN QUERY

  -- From release_artists
  SELECT
    ra.artist_slug AS unknown_slug,
    'release_artists'::text AS source_table,
    count(*) AS occurrence_count,
    max(ra.artist_name) AS sample_display_name
  FROM registry_release_artists ra
  WHERE ra.artist_slug IS NOT NULL
    AND ra.artist_slug != ''
    AND ra.artist_id IS NULL
    AND NOT EXISTS (SELECT 1 FROM registry_artist_aliases al WHERE al.alias_slug = ra.artist_slug)
    AND NOT EXISTS (SELECT 1 FROM registry_artists a WHERE a.slug = ra.artist_slug)
  GROUP BY ra.artist_slug

  UNION ALL

  -- From track_artists
  SELECT
    ta.artist_slug AS unknown_slug,
    'track_artists'::text AS source_table,
    count(*) AS occurrence_count,
    max(ta.artist_name) AS sample_display_name
  FROM registry_track_artists ta
  WHERE ta.artist_slug IS NOT NULL
    AND ta.artist_slug != ''
    AND ta.artist_id IS NULL
    AND NOT EXISTS (SELECT 1 FROM registry_artist_aliases al WHERE al.alias_slug = ta.artist_slug)
    AND NOT EXISTS (SELECT 1 FROM registry_artists a WHERE a.slug = ta.artist_slug)
  GROUP BY ta.artist_slug

  UNION ALL

  -- From entity_relationships where source or target is an artist
  SELECT
    CASE
      WHEN er.source_entity_type = 'artists' THEN er.source_slug
      ELSE er.target_slug
    END AS unknown_slug,
    'entity_relationships'::text AS source_table,
    count(*) AS occurrence_count,
    NULL::text AS sample_display_name
  FROM registry_entity_relationships er
  WHERE (
    (er.source_entity_type = 'artists' AND er.source_slug IS NOT NULL AND er.source_slug != '')
    OR (er.target_entity_type = 'artists' AND er.target_slug IS NOT NULL AND er.target_slug != '')
  )
    AND NOT EXISTS (SELECT 1 FROM registry_artist_aliases al WHERE al.alias_slug = 
      CASE WHEN er.source_entity_type = 'artists' THEN er.source_slug ELSE er.target_slug END)
    AND NOT EXISTS (SELECT 1 FROM registry_artists a WHERE a.slug = 
      CASE WHEN er.source_entity_type = 'artists' THEN er.source_slug ELSE er.target_slug END)
  GROUP BY unknown_slug

  ORDER BY occurrence_count DESC
  LIMIT 500;
END;
$$;


ALTER FUNCTION "public"."discover_unknown_artist_slugs"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."discover_unknown_artist_slugs_v2"() RETURNS TABLE("slug" "text", "source_count" bigint, "first_seen" "text", "source_type" "text", "sample_name" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    ra.artist_slug AS slug,
    COUNT(*)::bigint AS source_count,
    MIN(ra.created_at::text) AS first_seen,
    'release_artists'::text AS source_type,
    MIN(ra.artist_name_text)::text AS sample_name
  FROM registry_release_artists ra
  WHERE ra.artist_id IS NULL
    AND ra.artist_slug IS NOT NULL
    AND ra.artist_slug NOT IN (
      SELECT alias_slug FROM registry_artist_aliases
    )
  GROUP BY ra.artist_slug;

  RETURN QUERY
  SELECT
    ta.artist_slug AS slug,
    COUNT(*)::bigint AS source_count,
    MIN(ta.created_at::text) AS first_seen,
    'track_artists'::text AS source_type,
    MIN(ta.artist_name_text)::text AS sample_name
  FROM registry_track_artists ta
  WHERE ta.artist_id IS NULL
    AND ta.artist_slug IS NOT NULL
    AND ta.artist_slug NOT IN (
      SELECT alias_slug FROM registry_artist_aliases
    )
  GROUP BY ta.artist_slug;

  RETURN QUERY
  SELECT
    er.source_slug AS slug,
    COUNT(*)::bigint AS source_count,
    MIN(er.created_at::text) AS first_seen,
    'entity_relationships'::text AS source_type,
    MIN(er.source_entity)::text AS sample_name
  FROM registry_entity_relationships er
  WHERE er.source_entity_type = 'artist'
    AND er.source_slug IS NOT NULL
    AND er.source_slug NOT IN (
      SELECT alias_slug FROM registry_artist_aliases
    )
    AND NOT EXISTS (
      SELECT 1 FROM registry_artists a WHERE a.slug = er.source_slug
    )
  GROUP BY er.source_slug;

  RETURN QUERY
  SELECT
    er.target_slug AS slug,
    COUNT(*)::bigint AS source_count,
    MIN(er.created_at::text) AS first_seen,
    'entity_relationships'::text AS source_type,
    MIN(er.source_entity)::text AS sample_name
  FROM registry_entity_relationships er
  WHERE er.target_entity_type = 'artist'
    AND er.target_slug IS NOT NULL
    AND er.target_slug NOT IN (
      SELECT alias_slug FROM registry_artist_aliases
    )
    AND NOT EXISTS (
      SELECT 1 FROM registry_artists a WHERE a.slug = er.target_slug
    )
  GROUP BY er.target_slug;

  RETURN;
END;
$$;


ALTER FUNCTION "public"."discover_unknown_artist_slugs_v2"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_registry_relationship_promotion_rules"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
begin
  if new.review_status = 'approved' then
    if not exists (
      select 1
      from public.registry_relationship_evidence rre
      join public.evidence_items e on e.id = rre.evidence_id
      where rre.relationship_id = new.id
        and rre.support_type = 'supports'
        and e.review_status in ('reviewed', 'approved')
    ) then
      raise exception 'Approved relationships require at least one reviewed supporting evidence item.';
    end if;
  end if;

  if new.public_safe then
    if new.review_status <> 'approved'
       or new.relationship_status <> 'active'
       or nullif(btrim(new.plain_reason), '') is null then
      raise exception 'Public-safe relationships must be active, approved, and include a plain-language reason.';
    end if;

    if not exists (
      select 1
      from public.registry_relationship_evidence rre
      join public.evidence_items e on e.id = rre.evidence_id
      where rre.relationship_id = new.id
        and rre.support_type = 'supports'
        and e.review_status = 'approved'
        and e.retrieval_status = 'default_retrieval'
    ) then
      raise exception 'Public-safe relationships require approved supporting evidence enabled for default retrieval.';
    end if;
  end if;

  return new;
end;
$$;


