CREATE OR REPLACE FUNCTION "public"."expire_media_upload_session_v1"("p_session_id" "uuid", "p_reason" "text" DEFAULT 'Upload session expired before verification'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'media', 'auth'
    AS $$
declare
  v_session media.upload_sessions%rowtype;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception
      using
        errcode = '42501',
        message = 'Service-role access is required.';
  end if;

  if nullif(btrim(p_reason), '') is null then
    raise exception 'Upload expiry reason is required';
  end if;

  select session_row.*
  into v_session
  from media.upload_sessions session_row
  where session_row.id = p_session_id
  for update;

  if not found then
    raise exception 'Upload session does not exist';
  end if;

  if v_session.state = 'verified' then
    raise exception 'Verified upload session cannot expire';
  end if;

  if v_session.state in ('failed', 'cancelled', 'expired') then
    return jsonb_build_object(
      'session_id', v_session.id,
      'state', v_session.state,
      'expired_at', v_session.expired_at
    );
  end if;

  if v_session.expires_at > now() then
    raise exception 'Upload session has not expired';
  end if;

  update media.upload_sessions
  set
    state = 'expired',
    last_error = btrim(p_reason),
    expired_at = now(),
    updated_at = now()
  where id = v_session.id;

  return jsonb_build_object(
    'session_id', v_session.id,
    'state', 'expired',
    'expired_at', now(),
    'error', btrim(p_reason)
  );
end;
$$;


ALTER FUNCTION "public"."expire_media_upload_session_v1"("p_session_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fail_media_processing_job_v1"("p_job_id" "uuid", "p_worker_id" "text", "p_error" "text", "p_retryable" boolean DEFAULT true, "p_retry_delay_seconds" integer DEFAULT 60) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'auth', 'platform_private'
    AS $$
declare
  v_job_status text;
  v_receipt_status text;
  v_event_id uuid;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception
      using
        errcode = '42501',
        message = 'Service-role access is required.';
  end if;

  if not exists (
    select 1
    from platform_private.jobs job
    where job.id = p_job_id
      and job.command_type = 'media.process_revision'
      and job.job_type = 'media.process_revision'
  ) then
    raise exception
      'Requested job is not a Media processing job.';
  end if;

  select
    job_status,
    command_receipt_status,
    outbox_event_id
  into
    v_job_status,
    v_receipt_status,
    v_event_id
  from platform_private.fail_job(
    p_job_id,
    p_worker_id,
    p_error,
    p_retryable,
    p_retry_delay_seconds
  );

  return jsonb_build_object(
    'job_id', p_job_id,
    'job_status', v_job_status,
    'command_receipt_status', v_receipt_status,
    'outbox_event_id', v_event_id
  );
end;
$$;


ALTER FUNCTION "public"."fail_media_processing_job_v1"("p_job_id" "uuid", "p_worker_id" "text", "p_error" "text", "p_retryable" boolean, "p_retry_delay_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fail_media_upload_session_v1"("p_session_id" "uuid", "p_error" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'media', 'auth'
    AS $$
declare
  v_session media.upload_sessions%rowtype;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception
      using
        errcode = '42501',
        message = 'Service-role access is required.';
  end if;

  if nullif(btrim(p_error), '') is null then
    raise exception 'Upload-session failure reason is required';
  end if;

  select session_row.*
  into v_session
  from media.upload_sessions session_row
  where session_row.id = p_session_id
  for update;

  if not found then
    raise exception 'Upload session does not exist';
  end if;

  if v_session.state = 'verified' then
    raise exception 'Verified upload session cannot be failed';
  end if;

  if v_session.state in ('failed', 'cancelled', 'expired') then
    return jsonb_build_object(
      'session_id', v_session.id,
      'state', v_session.state,
      'error', v_session.last_error
    );
  end if;

  update media.upload_sessions
  set
    state = 'failed',
    last_error = btrim(p_error),
    updated_at = now()
  where id = v_session.id;

  return jsonb_build_object(
    'session_id', v_session.id,
    'state', 'failed',
    'error', btrim(p_error)
  );
end;
$$;


