CREATE OR REPLACE FUNCTION "public"."finalize_step_cf_chunk"("p_run_id" "uuid", "p_limit" integer, "p_min_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  WITH batch AS (
    SELECT sr.id
    FROM wk_import_staging_records sr
    WHERE sr.ingestion_run_id = p_run_id
      AND sr.target_entity = 'custom_fields'
      AND sr.target_status IN ('ready', 'needs_review')
      AND (p_min_id IS NULL OR sr.id > p_min_id)
    ORDER BY sr.id
    LIMIT p_limit
  ),
  inserted AS (
    INSERT INTO wk_import_review_artifacts (
      artifact_type, title, source_kind, source_ingestion_run_id,
      source_staging_record_id, source_record_id, raw_record, mapped_record,
      review_status, notes
    )
    SELECT sr.target_entity, sr.title, sr.source_kind, p_run_id,
           sr.id, sr.source_record_id, sr.raw_record, sr.mapped_record,
           'needs_review', 'Preserved for resolver review.'
    FROM wk_import_staging_records sr
    JOIN batch b ON sr.id = b.id
    ON CONFLICT (source_staging_record_id) DO NOTHING
    RETURNING 1
  )
  SELECT jsonb_build_object(
    'count', (SELECT count(*) FROM inserted),
    'last_id', (SELECT id FROM batch ORDER BY id DESC LIMIT 1)
  ) INTO v_result;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."finalize_step_cf_chunk"("p_run_id" "uuid", "p_limit" integer, "p_min_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_step_complete"("p_run_id" "uuid", "p_content" integer, "p_authors" integer, "p_tax" integer, "p_media" integer, "p_entities" integer, "p_review" integer, "p_errors" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
DECLARE v_total int;
BEGIN
  v_total := p_content + p_authors + p_tax + p_media + p_entities + p_review;

  UPDATE wk_ingestion_runs SET
    status = 'finalized',
    finished_at = now(),
    errors = p_errors
  WHERE id = p_run_id;

  RETURN jsonb_build_object(
    'success', true,
    'runId', p_run_id,
    'summary', jsonb_build_object(
      'content_items', p_content,
      'authors', p_authors,
      'taxonomy_terms', p_tax,
      'media_assets', p_media,
      'wakilisha_entities', p_entities,
      'review_artifacts', p_review
    ),
    'totalFinalized', v_total
  );
END;
$$;


