CREATE OR REPLACE FUNCTION "public"."finalize_step_content"("p_run_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_content int; v_authors int; v_tax int; v_errs jsonb := '[]'::jsonb;
BEGIN
  BEGIN
    WITH ins AS (
      INSERT INTO wk_content_items (content_type, slug, title, body, excerpt, status, published_at, author_name, source_url, source_kind, source_ingestion_run_id, source_staging_record_id, source_record_id, raw_record, mapped_record)
      SELECT CASE WHEN sr.target_entity = 'pages' THEN 'page' ELSE 'article' END,
        COALESCE(sr.target_slug, regexp_replace(lower(COALESCE(sr.title, sr.id::text)), '[^a-z0-9]+', '-', 'g')),
        COALESCE(sr.title, 'Untitled'), COALESCE(sr.body, ''), COALESCE(sr.excerpt, ''),
        CASE WHEN sr.mapped_record->>'source_status' = 'publish' THEN 'published' ELSE 'draft' END,
        sr.published_at, sr.author_name, sr.source_url, sr.source_kind,
        p_run_id, sr.id, sr.source_record_id, sr.raw_record, sr.mapped_record
      FROM wk_import_staging_records sr
      WHERE sr.ingestion_run_id = p_run_id AND sr.target_status = 'ready' AND sr.target_entity IN ('articles', 'pages')
      ON CONFLICT (source_staging_record_id) DO NOTHING RETURNING id
    ) SELECT count(*) INTO v_content FROM ins;
  EXCEPTION WHEN others THEN v_errs := v_errs || to_jsonb(format('content: %s', SQLERRM)); END;

  BEGIN
    WITH ins AS (
      INSERT INTO wk_authors (slug, name, email, url, source_kind, source_ingestion_run_id, source_staging_record_id, source_record_id, raw_record, mapped_record)
      SELECT COALESCE(sr.target_slug, regexp_replace(lower(COALESCE(sr.title, sr.id::text)), '[^a-z0-9]+', '-', 'g')),
        COALESCE(sr.title, 'Unknown'), sr.mapped_record->>'email', sr.mapped_record->>'url',
        sr.source_kind, p_run_id, sr.id, sr.source_record_id, sr.raw_record, sr.mapped_record
      FROM wk_import_staging_records sr
      WHERE sr.ingestion_run_id = p_run_id AND sr.target_status = 'ready' AND sr.target_entity = 'authors'
      ON CONFLICT (source_staging_record_id) DO NOTHING RETURNING id
    ) SELECT count(*) INTO v_authors FROM ins;
  EXCEPTION WHEN others THEN v_errs := v_errs || to_jsonb(format('authors: %s', SQLERRM)); END;

  BEGIN
    WITH ins AS (
      INSERT INTO wk_taxonomy_terms (taxonomy, slug, name, description, source_kind, source_ingestion_run_id, source_staging_record_id, source_record_id, raw_record, mapped_record)
      SELECT COALESCE(sr.mapped_record->>'taxonomy', 'term'),
        COALESCE(sr.target_slug, regexp_replace(lower(COALESCE(sr.title, sr.id::text)), '[^a-z0-9]+', '-', 'g')),
        COALESCE(sr.title, 'Unnamed'), sr.body, sr.source_kind,
        p_run_id, sr.id, sr.source_record_id, sr.raw_record, sr.mapped_record
      FROM wk_import_staging_records sr
      WHERE sr.ingestion_run_id = p_run_id AND sr.target_status = 'ready' AND sr.target_entity IN ('taxonomy_terms', 'artist_taxonomy_terms')
      ON CONFLICT (source_staging_record_id) DO NOTHING RETURNING id
    ) SELECT count(*) INTO v_tax FROM ins;
  EXCEPTION WHEN others THEN v_errs := v_errs || to_jsonb(format('taxonomy: %s', SQLERRM)); END;

  RETURN jsonb_build_object('content_items', v_content, 'authors', v_authors, 'taxonomy_terms', v_tax, 'errors', v_errs);
END;
$$;


ALTER FUNCTION "public"."finalize_step_content"("p_run_id" "uuid") OWNER TO "postgres";


