    WITH ins AS (
      INSERT INTO wk_wakilisha_entities (entity_type, slug, title, body, excerpt, status, published_at, source_url, source_kind, source_ingestion_run_id, source_staging_record_id, source_record_id, raw_record, mapped_record)
      SELECT sr.target_entity,
