      ON CONFLICT (source_staging_record_id) DO NOTHING RETURNING id
    ) SELECT count(*) INTO v_count FROM ins;
  EXCEPTION WHEN others THEN v_errs := v_errs || to_jsonb(format('entities: %s', SQLERRM)); END;
