CREATE OR REPLACE FUNCTION "public"."finalize_step_entities_chunk"("p_run_id" "uuid", "p_limit" integer, "p_min_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_count int;
  v_max_id text;
BEGIN
  INSERT INTO wk_wakilisha_entities (entity_type, slug, title, body, excerpt, status, published_at, source_url, source_kind, source_ingestion_run_id, source_staging_record_id, source_record_id, raw_record, mapped_record)
  SELECT sr.target_entity,
    COALESCE(sr.target_slug, regexp_replace(lower(COALESCE(sr.title, sr.id::text)), '[^a-z0-9]+', '-', 'g')),
    COALESCE(sr.title, 'Untitled'), COALESCE(sr.body, ''), COALESCE(sr.excerpt, ''),
    CASE WHEN sr.mapped_record->>'source_status' = 'publish' THEN 'published' ELSE 'draft' END,
    sr.published_at, sr.source_url, sr.source_kind,
    p_run_id, sr.id, sr.source_record_id, sr.raw_record, sr.mapped_record
  FROM wk_import_staging_records sr
  WHERE sr.ingestion_run_id = p_run_id AND sr.target_status = 'ready'
    AND sr.target_entity IN ('artists','tracks','releases','labels','genres','guides','chart_series','chart_editions','chart_programs','chart_surfaces','magazine_surfaces','magazine_issues','methodologies','corrections','play_surfaces','label_surfaces','settings_surfaces','profile_surfaces','content_entities','chart_entries','track_artists','release_tracks','release_labels','artist_genres','artist_relationships')
    AND (p_min_id IS NULL OR sr.id::text > p_min_id)
  ORDER BY sr.id
  LIMIT p_limit
  ON CONFLICT (entity_type, slug) DO NOTHING;

  GET DIAGNOSTICS v_count = ROW_COUNT;

  WITH chunk AS (
    SELECT sr.id
    FROM wk_import_staging_records sr
    WHERE sr.ingestion_run_id = p_run_id AND sr.target_status = 'ready'
      AND sr.target_entity IN ('artists','tracks','releases','labels','genres','guides','chart_series','chart_editions','chart_programs','chart_surfaces','magazine_surfaces','magazine_issues','methodologies','corrections','play_surfaces','label_surfaces','settings_surfaces','profile_surfaces','content_entities','chart_entries','track_artists','release_tracks','release_labels','artist_genres','artist_relationships')
      AND (p_min_id IS NULL OR sr.id::text > p_min_id)
    ORDER BY sr.id
    LIMIT p_limit
  )
  SELECT MAX(id::text) INTO v_max_id FROM chunk;

  RETURN jsonb_build_object('count', v_count, 'last_id', v_max_id);
END;
$$;


ALTER FUNCTION "public"."finalize_step_entities_chunk"("p_run_id" "uuid", "p_limit" integer, "p_min_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_step_entity_relationships"("p_run_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_total int := 0;
  v_batch int;
  v_batch_size int := 5000;
  v_offset int := 0;
  v_errs jsonb := '[]'::jsonb;
BEGIN
  LOOP
    BEGIN
      WITH batch AS (
        SELECT id FROM wk_import_staging_records
        WHERE ingestion_run_id = p_run_id
          AND target_entity = 'entity_relationships'
          AND target_status IN ('ready', 'needs_review')
        ORDER BY id
        LIMIT v_batch_size OFFSET v_offset
      ),
      ins AS (
        INSERT INTO wk_import_review_artifacts (artifact_type, title, source_kind, source_ingestion_run_id, source_staging_record_id, source_record_id, raw_record, mapped_record, review_status, notes)
        SELECT sr.target_entity, sr.title, sr.source_kind,
          p_run_id, sr.id, sr.source_record_id, sr.raw_record, sr.mapped_record,
          'needs_review', 'Preserved for resolver review.'
        FROM wk_import_staging_records sr
        WHERE sr.id IN (SELECT id FROM batch)
        ON CONFLICT (source_staging_record_id) DO NOTHING
        RETURNING id
      )
      SELECT count(*) INTO v_batch FROM ins;
    EXCEPTION WHEN others THEN
      v_errs := v_errs || to_jsonb(format('entity_relationships batch %s: %s', v_offset, SQLERRM));
    END;
    EXIT WHEN v_batch = 0;
    v_total := v_total + v_batch;
    v_offset := v_offset + v_batch_size;
  END LOOP;
  RETURN jsonb_build_object('entity_relationships', v_total, 'errors', v_errs);
END;
$$;


ALTER FUNCTION "public"."finalize_step_entity_relationships"("p_run_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_step_ers_all"("p_run_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_total int := 0;
  v_batch_count int;
  v_cursor uuid;
  v_prev_cursor uuid;
  v_chunk int := 0;
BEGIN
  SET LOCAL statement_timeout = '120s';

  LOOP
    v_chunk := v_chunk + 1;
    v_prev_cursor := v_cursor;

    INSERT INTO wk_import_review_artifacts (
      artifact_type, title, source_kind, source_ingestion_run_id,
      source_staging_record_id, source_record_id, raw_record, mapped_record,
      review_status, notes
    )
    SELECT sr.target_entity, sr.title, sr.source_kind, p_run_id,
           sr.id, sr.source_record_id, sr.raw_record, sr.mapped_record,
           'needs_review', 'Preserved for resolver review.'
    FROM wk_import_staging_records sr
    WHERE sr.ingestion_run_id = p_run_id
      AND sr.target_entity = 'entity_relationships'
      AND sr.target_status IN ('ready', 'needs_review')
      AND (v_cursor IS NULL OR sr.id > v_cursor)
    ORDER BY sr.id
    LIMIT 500
    ON CONFLICT (source_staging_record_id) DO NOTHING;

    GET DIAGNOSTICS v_batch_count = ROW_COUNT;
    v_total := v_total + v_batch_count;

    SELECT id INTO v_cursor
    FROM wk_import_staging_records sr
    WHERE sr.ingestion_run_id = p_run_id
      AND sr.target_entity = 'entity_relationships'
      AND sr.target_status IN ('ready', 'needs_review')
      AND (v_prev_cursor IS NULL OR sr.id > v_prev_cursor)
    ORDER BY sr.id
    OFFSET 499
    LIMIT 1;

    IF v_cursor IS NULL OR v_cursor = v_prev_cursor THEN
      EXIT;
    END IF;
  END LOOP;

  RETURN jsonb_build_object('entity_relationships', v_total, 'chunks', v_chunk);
END;
$$;


