CREATE OR REPLACE FUNCTION "public"."finalize_step_ers_chunk_v6"("p_run_id" "uuid", "p_limit" integer, "p_min_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_count int;
  v_max_id uuid;
BEGIN
  -- Only insert rows that don't already have artifacts (avoids ON CONFLICT overhead)
  INSERT INTO wk_import_review_artifacts (
    artifact_type, title, source_kind, source_ingestion_run_id,
    source_staging_record_id, source_record_id, raw_record, mapped_record,
    review_status, notes
  )
  SELECT sr.target_entity, sr.title, sr.source_kind, p_run_id,
         sr.id, sr.source_record_id, sr.raw_record, sr.mapped_record,
         'needs_review', 'Preserved for resolver review.'
  FROM wk_import_staging_records sr
  WHERE sr.ingestion_run_id = p_run_id
    AND sr.target_entity = 'entity_relationships'
    AND sr.target_status IN ('ready', 'needs_review')
    AND (p_min_id IS NULL OR sr.id > p_min_id)
    AND NOT EXISTS (
      SELECT 1 FROM wk_import_review_artifacts ra
      WHERE ra.source_staging_record_id = sr.id
    )
  ORDER BY sr.id
  LIMIT p_limit;

  GET DIAGNOSTICS v_count = ROW_COUNT;

  -- Get the max id from this batch's window for cursor tracking
  SELECT id INTO v_max_id
  FROM wk_import_staging_records sr
  WHERE sr.ingestion_run_id = p_run_id
    AND sr.target_entity = 'entity_relationships'
    AND sr.target_status IN ('ready', 'needs_review')
    AND (p_min_id IS NULL OR sr.id > p_min_id)
  ORDER BY sr.id
  OFFSET p_limit - 1
  LIMIT 1;

  RETURN jsonb_build_object('count', v_count, 'last_id', v_max_id);
END;
$$;


