CREATE OR REPLACE FUNCTION "public"."finalize_step_media"("p_run_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
DECLARE v_count int; v_errs jsonb := '[]'::jsonb;
BEGIN
  BEGIN
    WITH ins AS (
      INSERT INTO wk_media_assets (entity_type, entity_slug, role, url, alt_text, raw_meta, source)
      SELECT 'media_asset',
        COALESCE(sr.target_slug, regexp_replace(lower(COALESCE(sr.title, sr.id::text)), '[^a-z0-9]+', '-', 'g')),
        'import', sr.source_url, sr.title, sr.raw_record, sr.source_kind
      FROM wk_import_staging_records sr
      WHERE sr.ingestion_run_id = p_run_id AND sr.target_status = 'ready' AND sr.target_entity = 'media_assets' AND sr.source_url IS NOT NULL
      ON CONFLICT DO NOTHING RETURNING id
    ) SELECT count(*) INTO v_count FROM ins;
  EXCEPTION WHEN others THEN v_errs := v_errs || to_jsonb(format('media: %s', SQLERRM)); END;
  RETURN jsonb_build_object('media_assets', v_count, 'errors', v_errs);
END;
$$;


