CREATE OR REPLACE FUNCTION "public"."find_similar_artists"("search_slug" "text", "search_name" "text" DEFAULT NULL::"text", "similarity_threshold" real DEFAULT 0.15, "max_results" integer DEFAULT 8) RETURNS TABLE("artist_id" "uuid", "artist_slug" "text", "display_name" "text", "similarity_score" real, "match_reason" "text")
    LANGUAGE "plpgsql" STABLE
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    a.id AS artist_id,
    a.slug AS artist_slug,
    a.display_name,
    GREATEST(
      similarity(a.slug, search_slug),
      CASE WHEN search_name IS NOT NULL THEN similarity(LOWER(a.display_name), LOWER(search_name)) ELSE 0 END
    ) AS similarity_score,
    CASE
      WHEN a.slug = search_slug THEN 'exact_slug'
      WHEN search_name IS NOT NULL AND LOWER(a.display_name) = LOWER(search_name) THEN 'exact_name'
      WHEN similarity(a.slug, search_slug) > 0.5 THEN 'high_slug_similarity'
      WHEN search_name IS NOT NULL AND similarity(LOWER(a.display_name), LOWER(search_name)) > 0.5 THEN 'high_name_similarity'
      ELSE 'partial_match'
    END AS match_reason
  FROM registry_artists a
  WHERE a.status IS DISTINCT FROM 'inactive'
    AND (
      similarity(a.slug, search_slug) > similarity_threshold
      OR (search_name IS NOT NULL AND similarity(LOWER(a.display_name), LOWER(search_name)) > similarity_threshold)
      OR a.slug ILIKE ('%' || regexp_replace(search_slug, '[^a-zA-Z0-9]', '%', 'g') || '%')
      OR (search_name IS NOT NULL AND a.display_name ILIKE ('%' || search_name || '%'))
    )
  ORDER BY similarity_score DESC
  LIMIT max_results;
END;
$$;


ALTER FUNCTION "public"."find_similar_artists"("search_slug" "text", "search_name" "text", "similarity_threshold" real, "max_results" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."find_similar_artists"("search_slug" "text", "search_name" "text" DEFAULT NULL::"text", "similarity_threshold" numeric DEFAULT 0.15, "max_results" integer DEFAULT 6) RETURNS TABLE("artist_id" "uuid", "artist_slug" "text", "display_name" "text", "similarity_score" numeric, "match_reason" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    a.id AS artist_id,
    a.slug AS artist_slug,
    a.display_name,
    GREATEST(
      similarity(COALESCE(search_slug, ''), a.slug),
      similarity(COALESCE(search_name, ''), a.display_name)
    )::numeric AS similarity_score,
    CASE
      WHEN a.slug = search_slug THEN 'exact_slug'
      WHEN a.display_name ILIKE COALESCE(search_name, '') THEN 'exact_name'
      WHEN similarity(COALESCE(search_slug, ''), a.slug) >= 0.6 THEN 'high_slug_similarity'
      WHEN similarity(COALESCE(search_name, ''), a.display_name) >= 0.5 THEN 'high_name_similarity'
      ELSE 'partial_match'
    END::text AS match_reason
  FROM registry_artists a
  WHERE (
    a.slug % search_slug
    OR a.display_name % COALESCE(search_name, search_slug)
  )
  ORDER BY similarity_score DESC
  LIMIT max_results;
END;
$$;


ALTER FUNCTION "public"."find_similar_artists"("search_slug" "text", "search_name" "text", "similarity_threshold" numeric, "max_results" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_admin_import_runs"("p_limit" integer DEFAULT 100) RETURNS SETOF "public"."wk_ingestion_runs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
