CREATE OR REPLACE FUNCTION "public"."get_article_review_workspace"("p_article_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_resource editorial.resources%rowtype;
  v_target editorial.article_versions%rowtype;
  v_threads jsonb;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  select resource.*
  into v_resource
  from editorial.article_resources binding
  join editorial.resources resource
    on resource.id = binding.resource_id
  where binding.article_id = p_article_id;

  if not found then
    raise exception 'Article resource identity not found';
  end if;

  if not editorial.current_user_can_participate_article_review(
    v_resource.id
  ) then
    raise exception 'Permission denied';
  end if;

  if v_resource.current_submitted_version_id is not null then
    select version.*
    into v_target
    from editorial.article_versions version
    where version.id =
      v_resource.current_submitted_version_id;
  end if;

  select coalesce(
    jsonb_agg(
      rows.thread_payload
      order by rows.thread_created_at desc
    ),
    '[]'::jsonb
  )
  into v_threads
  from (
    select
      thread.created_at as thread_created_at,
      jsonb_build_object(
        'id',
        thread.id,
        'resource_id',
        thread.resource_id,
        'article_id',
        thread.article_id,
        'target_version_id',
        thread.target_version_id,
        'thread_kind',
        thread.thread_kind,
        'target_field',
        thread.target_field,
        'anchor_kind',
        thread.anchor_kind,
        'anchor_from',
        thread.anchor_from,
        'anchor_to',
        thread.anchor_to,
        'anchor_quote',
        thread.anchor_quote,
        'anchor_prefix',
        thread.anchor_prefix,
        'anchor_suffix',
        thread.anchor_suffix,
        'status',
        thread.status,
        'created_by',
        thread.created_by,
        'created_by_label',
        coalesce(
          creator.display_name,
          thread.created_by::text,
          'system'
        ),
        'resolved_by',
        thread.resolved_by,
        'resolved_by_label',
        coalesce(
          resolver.display_name,
          thread.resolved_by::text
        ),
        'resolved_at',
        thread.resolved_at,
        'created_at',
        thread.created_at,
        'updated_at',
        thread.updated_at,
        'suggestion',
        case
          when suggestion.id is null then null
          else jsonb_build_object(
            'id',
            suggestion.id,
            'operation_kind',
            suggestion.operation_kind,
            'original_text',
            suggestion.original_text,
            'replacement_text',
            suggestion.replacement_text,
            'proposed_content_html',
            suggestion.proposed_content_html,
            'target_version_fingerprint',
            suggestion.target_version_fingerprint,
            'status',
            suggestion.status,
            'decided_by',
            suggestion.decided_by,
            'decided_at',
            suggestion.decided_at,
            'decision_note',
            suggestion.decision_note,
            'applied_version_id',
            suggestion.applied_version_id,
            'created_at',
            suggestion.created_at,
            'updated_at',
            suggestion.updated_at
          )
        end,
        'comments',
        coalesce(
          (
            select jsonb_agg(
              jsonb_build_object(
                'id',
                comment.id,
                'thread_id',
                comment.thread_id,
                'body_text',
                comment.body_text,
                'created_by',
                comment.created_by,
                'created_by_label',
                coalesce(
                  comment_actor.display_name,
                  comment.created_by::text,
                  'system'
                ),
                'created_at',
                comment.created_at,
                'edited_at',
                comment.edited_at,
                'deleted_at',
                comment.deleted_at
              )
              order by comment.created_at
            )
            from editorial.article_review_comments comment
            left join public.user_profiles comment_actor
              on comment_actor.user_id = comment.created_by
            where comment.thread_id = thread.id
          ),
          '[]'::jsonb
        ),
        'events',
        coalesce(
          (
            select jsonb_agg(
              jsonb_build_object(
                'id',
                event.id,
                'suggestion_id',
                event.suggestion_id,
                'action',
                event.action,
                'actor_id',
                event.actor_id,
                'actor_label',
                coalesce(
                  event_actor.display_name,
                  event.actor_id::text,
                  'system'
                ),
                'note',
                event.note,
                'applied_version_id',
                event.applied_version_id,
                'created_at',
                event.created_at
              )
              order by event.created_at
            )
            from editorial.article_suggestion_events event
            left join public.user_profiles event_actor
              on event_actor.user_id = event.actor_id
            where event.suggestion_id = suggestion.id
          ),
          '[]'::jsonb
        )
      ) as thread_payload
    from editorial.article_review_threads thread
    left join editorial.article_suggestions suggestion
      on suggestion.thread_id = thread.id
    left join public.user_profiles creator
      on creator.user_id = thread.created_by
    left join public.user_profiles resolver
      on resolver.user_id = thread.resolved_by
    where thread.article_id = p_article_id
  ) rows;

  return jsonb_build_object(
    'article_id',
    p_article_id,
    'resource_id',
    v_resource.id,
    'current_submitted_version_id',
    v_resource.current_submitted_version_id,
    'can_review',
    editorial.current_user_can_review_article(),
    'target_version',
    case
      when v_target.id is null then null
      else jsonb_build_object(
        'id',
        v_target.id,
        'version_number',
        v_target.version_number,
        'version_kind',
        v_target.version_kind,
        'source_draft_version',
        v_target.source_draft_version,
        'title',
        v_target.title,
        'excerpt',
        v_target.excerpt,
        'content_html',
        v_target.content_html,
        'content_fingerprint',
        v_target.content_fingerprint,
        'created_by',
        v_target.created_by,
        'created_at',
        v_target.created_at
      )
    end,
    'threads',
    v_threads
  );
end;
$$;


ALTER FUNCTION "public"."get_article_review_workspace"("p_article_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_article_review_workspace"("p_article_id" "uuid") IS 'Returns the authenticated internal Article review workspace and immutable submitted target.';



CREATE OR REPLACE FUNCTION "public"."get_article_trust_citation_intake_options"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_locator_types jsonb;
begin
  if coalesce(auth.role(), '') <> 'service_role'
     and auth.uid() is null then
    raise exception
      'Not authenticated';
  end if;

  if coalesce(auth.role(), '') <> 'service_role'
     and not (
       coalesce(
         public.current_user_is_administrator(),
         false
       )
       or coalesce(
         public.current_user_has_capability(
           'manage_citations'
         ),
         false
       )
       or coalesce(
         public.current_user_has_capability(
           'view_trust_records'
         ),
         false
       )
     ) then
    raise exception
      'You do not have permission to read Citation intake options';
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'locator_type',
          locator_type.locator_type,
        'label',
          locator_type.label,
        'description',
          locator_type.description,
        'sort_order',
          locator_type.sort_order
      )
      order by
        locator_type.sort_order,
        locator_type.locator_type
    ),
    '[]'::jsonb
  )
  into v_locator_types
  from editorial.citation_locator_types
    locator_type
  where locator_type.enabled;

  return jsonb_build_object(
    'locator_types',
      v_locator_types,
    'citation_purposes',
      jsonb_build_array(
        jsonb_build_object(
          'value', 'supports',
          'label', 'Supports',
          'description',
            'The Citation supports an Article claim or passage.',
          'sort_order', 10
        ),
        jsonb_build_object(
          'value', 'challenges',
          'label', 'Challenges',
          'description',
            'The Citation challenges an Article claim or passage.',
          'sort_order', 20
        ),
        jsonb_build_object(
          'value', 'contextualizes',
          'label', 'Contextualizes',
          'description',
            'The Citation adds relevant context.',
          'sort_order', 30
        ),
        jsonb_build_object(
          'value', 'quotes',
          'label', 'Quotes',
          'description',
            'The Article directly quotes this Citation.',
          'sort_order', 40
        ),
        jsonb_build_object(
          'value', 'documents',
          'label', 'Documents',
          'description',
            'The Citation documents an event, record, or fact.',
          'sort_order', 50
        ),
        jsonb_build_object(
          'value', 'methodology',
          'label', 'Methodology',
          'description',
            'The Citation records a research or editorial method.',
          'sort_order', 60
        ),
        jsonb_build_object(
          'value', 'other',
          'label', 'Other',
          'description',
            'Another reviewed Citation purpose.',
          'sort_order', 1000
        )
      ),
    'target_anchor_types',
      jsonb_build_array(
        jsonb_build_object(
          'value', 'whole_version',
          'label', 'Whole Article version',
          'description',
            'The Citation applies to the complete Article version.',
          'sort_order', 10
        ),
        jsonb_build_object(
          'value', 'block_id',
          'label', 'Block',
          'description',
            'The Citation applies to one Article block identifier.',
          'sort_order', 20
        ),
        jsonb_build_object(
          'value', 'heading_id',
          'label', 'Heading',
          'description',
            'The Citation applies to one heading identifier.',
          'sort_order', 30
        ),
        jsonb_build_object(
          'value', 'paragraph_id',
          'label', 'Paragraph',
          'description',
            'The Citation applies to one paragraph identifier.',
          'sort_order', 40
        ),
        jsonb_build_object(
          'value', 'character_range',
          'label', 'Character range',
          'description',
            'The Citation applies to a bounded character range.',
          'sort_order', 50
        ),
        jsonb_build_object(
          'value', 'structured_node',
          'label', 'Structured node',
          'description',
            'The Citation applies to one structured content node.',
          'sort_order', 60
        )
      )
  );
end;
$$;


