CREATE OR REPLACE FUNCTION "public"."get_correction_case_workspace"("p_case_resource_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'editorial', 'platform_private'
    AS $$
declare
  v_workspace jsonb;
  v_case editorial.correction_cases%rowtype;
  v_notes jsonb;
  v_follow_up_job jsonb;
begin
  v_workspace :=
    platform_private.get_correction_case_workspace_application_base(
      p_case_resource_id
    );

  select correction_case.*
  into v_case
  from editorial.correction_cases correction_case
  where correction_case.resource_id =
    p_case_resource_id;

  if not found then
    raise exception
      using
        errcode = 'P0002',
        message = 'The correction case does not exist.';
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id',
        note.id,
        'application_id',
        note.application_id,
        'affected_resource_id',
        note.affected_resource_id,
        'affected_resource_kind',
        note.affected_resource_kind,
        'challenged_version_id',
        note.challenged_version_id,
        'corrected_version_id',
        note.corrected_version_id,
        'note_text',
        note.note_text,
        'note_fingerprint',
        note.note_fingerprint,
        'supersedes_note_id',
        note.supersedes_note_id,
        'published_by',
        note.published_by,
        'published_at',
        note.published_at,
        'is_current',
        note.application_id =
          v_case.current_application_id
        and not exists (
          select 1
          from editorial.correction_public_notes later_note
          where later_note.supersedes_note_id =
            note.id
        )
      )
      order by
        note.published_at,
        note.id
    ),
    '[]'::jsonb
  )
  into v_notes
  from editorial.correction_public_notes note
  where note.case_resource_id =
    p_case_resource_id;

  if v_case.contributor_follow_up_job_id is not null then
    select jsonb_build_object(
      'id',
      job.id,
      'command_receipt_id',
      job.command_receipt_id,
      'job_type',
      job.job_type,
      'status',
      job.status,
      'attempt_count',
      job.attempt_count,
      'max_attempts',
      job.max_attempts,
      'available_at',
      job.available_at,
      'started_at',
      job.started_at,
      'finished_at',
      job.finished_at,
      'created_at',
      job.created_at,
      'updated_at',
      job.updated_at
    )
    into v_follow_up_job
    from platform_private.jobs job
    where job.id =
      v_case.contributor_follow_up_job_id;
  end if;

  v_workspace := jsonb_set(
    v_workspace,
    '{case,public_note_disposition}',
    coalesce(
      to_jsonb(
        v_case.public_note_disposition
      ),
      'null'::jsonb
    ),
    true
  );

  v_workspace := jsonb_set(
    v_workspace,
    '{case,public_note_no_note_reason}',
    coalesce(
      to_jsonb(
        v_case.public_note_no_note_reason
      ),
      'null'::jsonb
    ),
    true
  );

  v_workspace := jsonb_set(
    v_workspace,
    '{case,contributor_follow_up_disposition}',
    coalesce(
      to_jsonb(
        v_case.contributor_follow_up_disposition
      ),
      'null'::jsonb
    ),
    true
  );

  v_workspace := jsonb_set(
    v_workspace,
    '{case,contributor_follow_up_reason}',
    coalesce(
      to_jsonb(
        v_case.contributor_follow_up_reason
      ),
      'null'::jsonb
    ),
    true
  );

  v_workspace := jsonb_set(
    v_workspace,
    '{case,contributor_follow_up_job_id}',
    coalesce(
      to_jsonb(
        v_case.contributor_follow_up_job_id
      ),
      'null'::jsonb
    ),
    true
  );

  v_workspace := jsonb_set(
    v_workspace,
    '{case,contributor_follow_up_requested_at}',
    coalesce(
      to_jsonb(
        v_case.contributor_follow_up_requested_at
      ),
      'null'::jsonb
    ),
    true
  );

  v_workspace := jsonb_set(
    v_workspace,
    '{public_notes}',
    v_notes,
    true
  );

  v_workspace := jsonb_set(
    v_workspace,
    '{contributor_follow_up_job}',
    coalesce(
      v_follow_up_job,
      'null'::jsonb
    ),
    true
  );

  return v_workspace;
end;
$$;


