CREATE OR REPLACE FUNCTION "public"."get_latest_article_autosave"("p_article_id" "uuid") RETURNS TABLE("version_id" "uuid", "version_number" bigint, "source_draft_version" bigint, "title" "text", "slug" "text", "excerpt" "text", "content_html" "text", "author_display" "text", "seo" "jsonb", "category_snapshot" "jsonb", "tag_snapshot" "jsonb", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_resource_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  select binding.resource_id
  into v_resource_id
  from editorial.article_resources binding
  where binding.article_id = p_article_id;

  if v_resource_id is null then
    raise exception 'Article resource identity not found';
  end if;

  if not editorial.current_user_can_edit_article(
    v_resource_id
  ) then
    raise exception 'Permission denied';
  end if;

  return query
  select
    version.id,
    version.version_number,
    version.source_draft_version,
    version.title,
    version.slug,
    version.excerpt,
    version.content_html,
    version.author_display,
    version.seo,
    version.category_snapshot,
    version.tag_snapshot,
    version.created_at
  from editorial.article_versions version
  where version.resource_id = v_resource_id
    and version.version_kind = 'autosave'
    and version.created_by = auth.uid()
  order by version.created_at desc
  limit 1;
end;
$$;


ALTER FUNCTION "public"."get_latest_article_autosave"("p_article_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_media_asset_v2"("p_asset_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'media', 'auth'
    AS $$
declare
  v_can_review boolean;
  v_result jsonb;
begin
  perform media.require_media_read_actor();

  v_can_review :=
    public.current_user_has_capability(
      'review_media_governance'
    )
    or public.current_user_is_administrator();

  select jsonb_build_object(
    'asset',
    jsonb_build_object(
      'id', asset_row.id,
      'asset_kind', asset_row.asset_kind,
      'asset_purpose', asset_row.asset_purpose,
      'title', asset_row.title,
      'lifecycle_state', asset_row.lifecycle_state,
      'authority_revision',
        asset_row.authority_revision,
      'current_revision_id',
        asset_row.current_revision_id,
      'current_governance_version_id',
        asset_row.current_governance_version_id,
      'created_at', asset_row.created_at,
      'updated_at', asset_row.updated_at
    ),
    'revisions',
    (
      select coalesce(
        jsonb_agg(
          jsonb_build_object(
            'id', revision_row.id,
            'revision_number',
              revision_row.revision_number,
            'previous_revision_id',
              revision_row.previous_revision_id,
            'replacement_reason',
              revision_row.replacement_reason,
            'created_by',
              revision_row.created_by,
            'created_at',
              revision_row.created_at,
            'file_object',
              jsonb_build_object(
                'id', file_row.id,
                'verification_state',
                  file_row.verification_state,
                'sha256', file_row.sha256,
                'byte_size', file_row.byte_size,
                'mime_type', file_row.mime_type,
                'delivery_url',
                  case
                    when file_row.verification_state =
                      'verified'
                      then file_row.delivery_url
                    else null
                  end,
                'technical_metadata',
                  file_row.technical_metadata
              )
          )
          order by revision_row.revision_number
        ),
        '[]'::jsonb
      )
      from media.asset_revisions revision_row
      join media.file_objects file_row
        on file_row.id =
          revision_row.original_file_object_id
      where revision_row.asset_id = asset_row.id
    ),
    'variants',
    (
      select coalesce(
        jsonb_agg(
          jsonb_build_object(
            'id', variant_row.id,
            'asset_revision_id',
              variant_row.asset_revision_id,
            'variant_role',
              variant_row.variant_role,
            'source_file_object_id',
              variant_row.source_file_object_id,
            'derived_file_object_id',
              variant_row.derived_file_object_id,
            'transformation_spec',
              variant_row.transformation_spec,
            'technical_metadata',
              variant_row.technical_metadata,
            'generator_name',
              variant_row.generator_name,
            'generator_version',
              variant_row.generator_version,
            'created_at',
              variant_row.created_at,
            'selection_revision',
              selection_row.selection_revision,
            'is_selected',
              selection_row.variant_id =
                variant_row.id
          )
          order by
            variant_row.asset_revision_id,
            variant_row.variant_role,
            variant_row.created_at,
            variant_row.id
        ),
        '[]'::jsonb
      )
      from media.variants variant_row
      left join media.variant_selections selection_row
        on selection_row.asset_revision_id =
          variant_row.asset_revision_id
       and selection_row.variant_role =
          variant_row.variant_role
      where variant_row.asset_id = asset_row.id
    ),
    'usages',
    (
      select coalesce(
        jsonb_agg(
          jsonb_build_object(
            'id', usage_row.id,
            'asset_revision_id',
              usage_row.asset_revision_id,
            'resolution_mode',
              usage_row.resolution_mode,
            'target_authority',
              usage_row.target_authority,
            'target_kind',
              usage_row.target_kind,
            'target_id',
              usage_row.target_id,
            'target_version_kind',
              usage_row.target_version_kind,
            'target_version_id',
              usage_row.target_version_id,
            'usage_role',
              usage_row.usage_role,
            'placement_data',
              usage_row.placement_data,
            'display_order',
              usage_row.display_order,
            'alt_text_snapshot',
              usage_row.alt_text_snapshot,
            'caption_snapshot',
              usage_row.caption_snapshot,
            'credit_snapshot',
              usage_row.credit_snapshot,
            'usage_state',
              usage_row.usage_state,
            'usage_revision',
              usage_row.usage_revision,
            'state_reason',
              usage_row.state_reason,
            'state_changed_at',
              usage_row.state_changed_at,
            'created_at',
              usage_row.created_at,
            'updated_at',
              usage_row.updated_at
          )
          order by
            usage_row.created_at,
            usage_row.id
        ),
        '[]'::jsonb
      )
      from media.usage_links usage_row
      where usage_row.asset_id = asset_row.id
    ),
    'governance_history',
    (
      select coalesce(
        jsonb_agg(
          jsonb_build_object(
            'id', governance_history.id,
            'version_number',
              governance_history.version_number,
            'rights_status',
              governance_history.rights_status,
            'consent_status',
              governance_history.consent_status,
            'sensitivity',
              governance_history.sensitivity,
            'embargo_state',
              governance_history.embargo_state,
            'embargo_until',
              governance_history.embargo_until,
            'source_protection_class',
              governance_history.source_protection_class,
            'preservation_state',
              governance_history.preservation_state,
            'retention_state',
              governance_history.retention_state,
            'public_safety_state',
              governance_history.public_safety_state,
            'internal_reason',
              case
                when v_can_review
                  then governance_history.internal_reason
                else null
              end,
            'created_by',
              governance_history.created_by,
            'created_at',
              governance_history.created_at
          )
          order by governance_history.version_number
        ),
        '[]'::jsonb
      )
      from media.asset_governance_versions
        governance_history
      where governance_history.asset_id =
        asset_row.id
    ),
    'compatibility',
    (
      select jsonb_build_object(
        'legacy_asset_id',
          bridge_row.legacy_asset_id,
        'mapped', true,
        'snapshot_fingerprint',
          md5(bridge_row.legacy_snapshot::text),
        'created_at',
          bridge_row.created_at
      )
      from media.legacy_asset_links bridge_row
      where bridge_row.asset_id = asset_row.id
    ),
    'events',
    (
      select coalesce(
        jsonb_agg(
          jsonb_build_object(
            'id', event_row.id,
            'event_type',
              event_row.event_type,
            'file_object_id',
              event_row.file_object_id,
            'asset_revision_id',
              event_row.asset_revision_id,
            'variant_id',
              event_row.variant_id,
            'usage_link_id',
              event_row.usage_link_id,
            'governance_version_id',
              event_row.governance_version_id,
            'actor_id',
              event_row.actor_id,
            'reason',
              event_row.reason,
            'correlation_id',
              event_row.correlation_id,
            'created_at',
              event_row.created_at
          )
          order by
            event_row.created_at,
            event_row.id
        ),
        '[]'::jsonb
      )
      from media.events event_row
      where event_row.asset_id = asset_row.id
    )
  )
  into v_result
  from media.assets asset_row
  where asset_row.id = p_asset_id;

  if v_result is null then
    raise exception
      'Media asset does not exist';
  end if;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."get_media_asset_v2"("p_asset_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_media_private_delivery_target_v1"("p_file_object_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'media'
    AS $$
declare
  v_file media.file_objects%rowtype;
begin
  if coalesce(auth.role(), '') <> 'authenticated'
     or auth.uid() is null
  then
    raise exception
      using
        errcode = '42501',
        message = 'Authenticated Media actor is required.';
  end if;

  if not (
    public.current_user_has_capability('manage_media_assets')
    or public.current_user_is_administrator()
  ) then
    raise exception
      using
        errcode = '42501',
        message = 'manage_media_assets capability is required.';
  end if;

  if p_file_object_id is null then
    raise exception
      using
        errcode = '22023',
        message = 'file_object_id is required.';
  end if;

  select *
  into v_file
  from media.file_objects
  where id = p_file_object_id;

  if not found then
    raise exception
      using
        errcode = 'P0002',
        message = 'Media file object does not exist.';
  end if;

  if v_file.verification_state <> 'verified'
     or v_file.storage_provider <> 'lightsail_media'
     or v_file.storage_path is null
     or v_file.storage_path !~
       '^(masters/(audio|video)/|derived-objects/|private-files/(transcripts|captions)/)'
  then
    raise exception
      using
        errcode = '55000',
        message = 'Only verified protected Lightsail Media files may use private delivery.';
  end if;

  if not (
    exists (
      select 1
      from media.asset_revisions revision
      where revision.original_file_object_id = v_file.id
    )
    or exists (
      select 1
      from media.variants variant
      where variant.derived_file_object_id = v_file.id
    )
  ) then
    raise exception
      using
        errcode = '55000',
        message = 'Private delivery requires a canonical Media revision or variant binding.';
  end if;

  return jsonb_build_object(
    'file_object_id', v_file.id,
    'storage_path', v_file.storage_path,
    'original_filename', v_file.original_filename,
    'mime_type', v_file.mime_type,
    'byte_size', v_file.byte_size,
    'sha256', v_file.sha256,
    'verification_state', v_file.verification_state
  );
end;
$$;


ALTER FUNCTION "public"."get_media_private_delivery_target_v1"("p_file_object_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_media_private_delivery_target_v1"("p_file_object_id" "uuid") IS 'M4 authenticated control-plane read for one verified protected canonical Media file.';



CREATE OR REPLACE FUNCTION "public"."get_media_upload_session_v1"("p_session_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'media', 'auth'
    AS $$
declare
  v_actor_id uuid;
  v_session media.upload_sessions%rowtype;
begin
  v_actor_id := media.require_command_actor('manage_media_assets');

  select session_row.*
  into v_session
  from media.upload_sessions session_row
  where session_row.id = p_session_id;

  if not found then
    raise exception 'Upload session does not exist';
  end if;

  if v_session.actor_id <> v_actor_id then
    raise exception 'Upload session belongs to another actor';
  end if;

  return jsonb_build_object(
    'session_id', v_session.id,
    'state', v_session.state,
    'storage_path', v_session.storage_path,
    'storage_provider', v_session.storage_provider,
    'storage_namespace', v_session.storage_namespace,
    'original_filename', v_session.original_filename,
    'mime_type', v_session.mime_type,
    'expected_byte_size', v_session.expected_byte_size,
    'expected_sha256', v_session.expected_sha256,
    'part_size_bytes', v_session.part_size_bytes,
    'total_parts', v_session.total_parts,
    'expires_at', v_session.expires_at,
    'verified_byte_size', v_session.verified_byte_size,
    'verified_sha256', v_session.verified_sha256,
    'verified_at', v_session.verified_at,
    'expired_at', v_session.expired_at,
    'file_object_id', v_session.file_object_id,
    'last_error', v_session.last_error,
    'correlation_id', v_session.correlation_id
  );
end;
$$;


ALTER FUNCTION "public"."get_media_upload_session_v1"("p_session_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_playlist_cover_source"("p_playlist_id" "uuid", "p_asset_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial', 'media'
    AS $$
declare
  v_asset media.assets%rowtype;
  v_file media.file_objects%rowtype;
  v_compatibility public.registry_media_assets%rowtype;
begin
  if not public.current_user_can_edit_playlist_id(p_playlist_id) then
    raise exception
      using errcode = '42501', message = 'Playlist edit permission is required.';
  end if;

  select asset.*
  into v_asset
  from media.assets asset
  where asset.id = p_asset_id
    and asset.lifecycle_state = 'active';

  if not found or v_asset.current_revision_id is null then
    raise exception 'Selected Media image is unavailable.';
  end if;

  select file_object.*
  into v_file
  from media.asset_revisions revision
  join media.file_objects file_object
    on file_object.id = revision.original_file_object_id
  where revision.id = v_asset.current_revision_id
    and revision.asset_id = p_asset_id
    and file_object.verification_state = 'verified'
    and lower(coalesce(file_object.mime_type, '')) like 'image/%';

  if not found or nullif(btrim(v_file.delivery_url), '') is null then
    raise exception 'Selected Media item does not have a reachable verified image.';
  end if;

  select compatibility.*
  into v_compatibility
  from public.registry_media_assets compatibility
  where compatibility.id = p_asset_id;

  return jsonb_build_object(
    'asset_id', p_asset_id,
    'asset_revision_id', v_asset.current_revision_id,
    'url', v_file.delivery_url,
    'mime_type', v_file.mime_type,
    'title', coalesce(v_compatibility.title, 'Playlist cover source')
  );
end;
$$;


ALTER FUNCTION "public"."get_playlist_cover_source"("p_playlist_id" "uuid", "p_asset_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_playlist_current_cover"("p_playlist_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'auth', 'public', 'editorial', 'media'
    AS $$
declare
  v_binding editorial.playlist_resources%rowtype;
  v_playlist public.wk_playlists%rowtype;
  v_usage media.usage_links%rowtype;
begin
  select *
  into v_binding
  from editorial.playlist_resources binding
  where binding.playlist_id = p_playlist_id;

  if not found then
    raise exception
      using errcode = 'P0002', message = 'Playlist was not found.';
  end if;

  if not coalesce(
    editorial.current_user_can_view_playlist(
      v_binding.resource_id
    ),
    false
  ) then
    raise exception
      using
        errcode = '42501',
        message = 'You do not have permission to view this Playlist.';
  end if;

  select *
  into v_playlist
  from public.wk_playlists playlist
  where playlist.id = p_playlist_id;

  select usage.*
  into v_usage
  from media.usage_links usage
  where usage.target_authority = 'editorial'
    and usage.target_kind = 'playlist'
    and usage.target_id = p_playlist_id
    and usage.target_version_id is null
    and usage.usage_role = 'playlist_cover'
    and usage.usage_state = 'active';

  if not found then
    return jsonb_build_object(
      'playlist_id', p_playlist_id,
      'resource_id', v_binding.resource_id,
      'cover', null
    );
  end if;

  return jsonb_build_object(
    'playlist_id', p_playlist_id,
    'resource_id', v_binding.resource_id,
    'cover',
      jsonb_build_object(
        'usage_link_id', v_usage.id,
        'usage_revision',
          v_usage.usage_revision,
        'asset_id', v_usage.asset_id,
        'asset_revision_id',
          v_usage.asset_revision_id,
        'resolution_mode',
          v_usage.resolution_mode,
        'url', v_playlist.cover_image_url,
        'placement_data',
          v_usage.placement_data,
        'alt_text',
          v_usage.alt_text_snapshot,
        'caption',
          v_usage.caption_snapshot,
        'credit',
          v_usage.credit_snapshot
      )
  );
end;
$$;


ALTER FUNCTION "public"."get_playlist_current_cover"("p_playlist_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_playlist_pending_registry_intake"("p_playlist_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_resource_id uuid;
begin
  select binding.resource_id
  into v_resource_id
  from editorial.playlist_resources binding
  where binding.playlist_id = p_playlist_id;

  if not found then
    raise exception
      using errcode = 'P0002', message = 'Playlist does not exist.';
  end if;

  if not editorial.current_user_can_view_playlist(v_resource_id) then
    raise exception
      using errcode = '42501', message = 'Playlist view permission is required.';
  end if;

  return coalesce(
    (
      select jsonb_agg(
        jsonb_build_object(
          'suggestion_id', suggestion.id,
          'reserved_position', suggestion.reserved_position,
          'status', suggestion.status,
          'provider_key', suggestion.provider_key,
          'provider_url', suggestion.provider_url,
          'provider_title', suggestion.provider_title,
          'provider_release_title', suggestion.provider_release_title,
          'playback_kind', suggestion.playback_kind,
          'artwork_url',
            suggestion.validation_snapshot ->> 'artwork_url',
          'created_at', suggestion.created_at,
          'artist_credits',
            coalesce(
              (
                select jsonb_agg(
                  jsonb_build_object(
                    'credit_order', credit.credit_order,
                    'credit_role', credit.credit_role,
                    'resolution_mode', credit.resolution_mode,
                    'registry_artist_id', credit.registry_artist_id,
                    'observed_name', credit.observed_name,
                    'display_name',
                      coalesce(
                        artist.display_name,
                        credit.observed_name
                      )
                  )
                  order by credit.credit_order
                )
                from public.registry_provider_track_suggestion_artists credit
                left join public.registry_artists artist
                  on artist.id = credit.registry_artist_id
                where credit.suggestion_id = suggestion.id
              ),
              '[]'::jsonb
            )
        )
        order by suggestion.reserved_position, suggestion.created_at
      )
      from public.registry_provider_track_suggestions suggestion
      where suggestion.source_playlist_id = p_playlist_id
        and suggestion.status = 'needs_review'
        and suggestion.source_playlist_item_id is null
        and suggestion.canonical_track_id is null
    ),
    '[]'::jsonb
  );
end;
$$;


