CREATE OR REPLACE FUNCTION "public"."get_playlist_review_workspace"("p_playlist_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'editorial'
    AS $$
declare
  v_playlist public.wk_playlists%rowtype;
  v_binding editorial.playlist_resources%rowtype;
  v_review_events jsonb;
  v_lifecycle_events jsonb;
  v_schedule jsonb;
  v_curator jsonb;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  select playlist.*
  into v_playlist
  from public.wk_playlists playlist
  where playlist.id = p_playlist_id;

  if not found then
    raise exception 'Playlist does not exist';
  end if;

  select binding.*
  into v_binding
  from editorial.playlist_resources binding
  where binding.playlist_id = p_playlist_id;

  if not found then
    raise exception
      'Playlist Resource binding does not exist';
  end if;

  if not editorial.current_user_can_participate_playlist_review(
    v_binding.resource_id
  ) then
    raise exception
      'Playlist Review participation permission is required';
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', event.id,
        'event_number', event.event_number,
        'target_version_id', event.target_version_id,
        'result_version_id', event.result_version_id,
        'action', event.action,
        'prior_status', event.prior_status,
        'resulting_status', event.resulting_status,
        'reason', event.reason,
        'actor_id', event.actor_id,
        'command_receipt_id', event.command_receipt_id,
        'correlation_id', event.correlation_id,
        'created_at', event.created_at
      )
      order by event.event_number
    ),
    '[]'::jsonb
  )
  into v_review_events
  from editorial.playlist_review_events event
  where event.resource_id =
          v_binding.resource_id;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', event.id,
        'event_number', event.event_number,
        'version_id', event.version_id,
        'action', event.action,
        'prior_status', event.prior_status,
        'resulting_status', event.resulting_status,
        'note', event.note,
        'metadata', event.metadata,
        'actor_id', event.actor_id,
        'command_receipt_id', event.command_receipt_id,
        'created_at', event.created_at
      )
      order by event.event_number
    ),
    '[]'::jsonb
  )
  into v_lifecycle_events
  from editorial.playlist_lifecycle_events event
  where event.resource_id =
          v_binding.resource_id;

  select jsonb_build_object(
    'id', scheduled.id,
    'version_id', scheduled.version_id,
    'run_after', scheduled.run_after,
    'status', scheduled.status,
    'note', scheduled.note,
    'created_by', scheduled.created_by,
    'created_at', scheduled.created_at,
    'updated_at', scheduled.updated_at,
    'published_at', scheduled.published_at,
    'failure_reason', scheduled.failure_reason
  )
  into v_schedule
  from editorial.playlist_scheduled_publications scheduled
  where scheduled.playlist_id = p_playlist_id
  order by scheduled.created_at desc
  limit 1;

  if v_playlist.curator_credit_id is not null then
    select jsonb_build_object(
      'credit_id', credit.id,
      'role', credit.credit_role,
      'display_name', credit.display_name_snapshot,
      'author_slug', credit.registry_author_slug_snapshot,
      'username', credit.user_username_snapshot,
      'registry_author_id', credit.registry_author_id,
      'user_id', credit.user_id,
      'public_safe', governance.public_safe,
      'credit_state', governance.credit_state,
      'governance_revision',
        governance.governance_revision
    )
    into v_curator
    from editorial.credits credit
    join editorial.credit_governance governance
      on governance.credit_id = credit.id
    where credit.id =
      v_playlist.curator_credit_id;
  end if;

  return jsonb_build_object(
    'playlist',
      jsonb_build_object(
        'id', v_playlist.id,
        'title', v_playlist.title,
        'slug', v_playlist.slug,
        'description', v_playlist.description,
        'curator_credit_id',
          v_playlist.curator_credit_id,
        'curator_label',
          v_playlist.curator_label,
        'status', v_playlist.status,
        'authority_revision',
          v_playlist.authority_revision,
        'metadata', v_playlist.metadata,
        'created_at', v_playlist.created_at,
        'updated_at', v_playlist.updated_at
      ),
    'resource_id',
      v_binding.resource_id,
    'current_working_version_id',
      v_binding.current_working_version_id,
    'current_submitted_version_id',
      v_binding.current_submitted_version_id,
    'current_approved_version_id',
      v_binding.current_approved_version_id,
    'current_published_version_id',
      v_binding.current_published_version_id,
    'working_version',
      editorial.playlist_version_snapshot_json(
        v_binding.current_working_version_id
      ),
    'submitted_version',
      editorial.playlist_version_snapshot_json(
        v_binding.current_submitted_version_id
      ),
    'approved_version',
      editorial.playlist_version_snapshot_json(
        v_binding.current_approved_version_id
      ),
    'published_version',
      editorial.playlist_version_snapshot_json(
        v_binding.current_published_version_id
      ),
    'curator', v_curator,
    'schedule', v_schedule,
    'review_events', v_review_events,
    'lifecycle_events', v_lifecycle_events,
    'can_edit',
      editorial.current_user_can_edit_playlist(
        v_binding.resource_id
      ),
    'can_manage_review',
      coalesce(
        public.current_user_is_administrator(),
        false
      )
      or coalesce(
        public.current_user_has_capability(
          'manage_review_queue'
        ),
        false
      ),
    'can_publish',
      editorial.current_user_can_publish_playlist(
        v_binding.resource_id
      )
  );
end;
$$;


ALTER FUNCTION "public"."get_playlist_review_workspace"("p_playlist_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_public_artist_relationships"("p_artist_id" "uuid") RETURNS TABLE("relationship_id" "uuid", "direction" "text", "related_entity_id" "uuid", "related_entity_type" "text", "related_entity_name" "text", "related_entity_slug" "text", "related_entity_image_url" "text", "related_entity_url" "text", "relationship_type" "text", "relationship_role" "text", "plain_reason" "text", "evidence_count" integer, "reviewed_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
with publishable as (
 select r.id,r.source_entity_id,r.target_entity_id,r.source_entity_type,r.target_entity_type,r.relationship_type,r.relationship_role,r.plain_reason,r.reviewed_at,(select count(*)::integer from public.registry_relationship_evidence e where e.relationship_id=r.id) evidence_count
 from public.registry_entity_relationships r
 where p_artist_id is not null
 and exists(select 1 from public.registry_artists ca where ca.id=p_artist_id and ca.status='active')
 and r.relationship_status='active' and r.review_status='approved' and r.public_safe=true
 and nullif(btrim(r.plain_reason),'') is not null
 and r.source_entity_id is not null and r.target_entity_id is not null
 and (r.source_entity_id=p_artist_id or r.target_entity_id=p_artist_id)
 and exists(select 1 from public.registry_relationship_evidence e where e.relationship_id=r.id)
), expanded as (
 select p.id relationship_id,'outgoing'::text direction,p.target_entity_id related_entity_id,p.target_entity_type related_entity_type,p.relationship_type,p.relationship_role,p.plain_reason,p.evidence_count,p.reviewed_at
 from publishable p where p.source_entity_type='artist' and p.source_entity_id=p_artist_id
 union all
 select p.id,'incoming'::text,p.source_entity_id,p.source_entity_type,p.relationship_type,p.relationship_role,p.plain_reason,p.evidence_count,p.reviewed_at
 from publishable p where p.target_entity_type='artist' and p.target_entity_id=p_artist_id
)
select x.relationship_id,x.direction,x.related_entity_id,x.related_entity_type,coalesce(a.display_name,t.title),coalesce(a.slug,t.slug),coalesce(a.public_image_url,t.artwork_url),case when x.related_entity_type='artist' then '/artists/'||a.slug else null end,x.relationship_type,x.relationship_role,x.plain_reason,x.evidence_count,x.reviewed_at
from expanded x
left join public.registry_artists a on x.related_entity_type='artist' and a.id=x.related_entity_id and a.status='active'
left join public.registry_tracks t on x.related_entity_type='track' and t.id=x.related_entity_id and t.status='active'
where coalesce(a.id,t.id) is not null
order by x.reviewed_at desc nulls last,x.relationship_id;
$$;


ALTER FUNCTION "public"."get_public_artist_relationships"("p_artist_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_public_artist_relationships"("p_artist_id" "uuid") IS 'Returns only active, approved, public-safe, explained, evidence-backed relationships for one active Registry artist page.';



CREATE OR REPLACE FUNCTION "public"."get_public_artist_structural_proximity"("p_artist_id" "uuid") RETURNS TABLE("related_artist_id" "uuid", "related_artist_slug" "text", "related_artist_name" "text", "related_artist_image_url" "text", "shared_track_count" integer, "shared_release_count" integer, "features_them" integer, "they_feature" integer, "shared_titles" "text"[], "proximity_score" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
with target as (
  select
    artist.id,
    artist.slug
  from public.registry_artists artist
  where artist.id = p_artist_id
    and artist.status = 'active'
),

target_track_credits as (
  select
    credit.track_id,
    bool_or(coalesce(credit.is_primary, false)) as is_primary,
    bool_or(
      coalesce(credit.is_featured, false)
      or lower(coalesce(credit.role, '')) in (
        'featured',
        'featured_artist',
        'feature'
      )
    ) as is_featured
  from public.registry_track_artists credit
  join target target_artist
    on (
      credit.artist_id = target_artist.id
      or (
        credit.artist_id is null
        and lower(coalesce(credit.artist_slug, '')) =
            lower(target_artist.slug)
      )
    )
  join public.registry_tracks track
    on track.id = credit.track_id
   and track.status = 'active'
  where credit.status = 'active'
  group by credit.track_id
),

track_pairs as (
  select
    related_artist.id as related_artist_id,
    target_credit.track_id,
    bool_or(
      target_credit.is_primary
      and (
        coalesce(peer_credit.is_featured, false)
        or lower(coalesce(peer_credit.role, '')) in (
          'featured',
          'featured_artist',
          'feature'
        )
      )
    ) as features_them_on_track,
    bool_or(
      target_credit.is_featured
      and coalesce(peer_credit.is_primary, false)
    ) as they_feature_on_track
  from target_track_credits target_credit
  join public.registry_track_artists peer_credit
    on peer_credit.track_id = target_credit.track_id
   and peer_credit.status = 'active'
  join public.registry_artists related_artist
    on related_artist.status = 'active'
   and (
     (
       peer_credit.artist_id is not null
       and related_artist.id = peer_credit.artist_id
     )
     or (
       peer_credit.artist_id is null
       and lower(coalesce(peer_credit.artist_slug, '')) =
           lower(related_artist.slug)
     )
   )
  where related_artist.id <> p_artist_id
  group by
    related_artist.id,
    target_credit.track_id
),

track_aggregate as (
  select
    pair.related_artist_id,
    count(*)::integer as shared_track_count,
    count(*) filter (
      where pair.features_them_on_track
    )::integer as features_them,
    count(*) filter (
      where pair.they_feature_on_track
    )::integer as they_feature,
    coalesce(
      array_agg(
        distinct track.title
        order by track.title
      ) filter (
        where nullif(btrim(coalesce(track.title, '')), '') is not null
      ),
      array[]::text[]
    ) as shared_titles
  from track_pairs pair
  join public.registry_tracks track
    on track.id = pair.track_id
  group by pair.related_artist_id
),

target_release_credits as (
  select distinct
    credit.release_id
  from public.registry_release_artists credit
  join target target_artist
    on (
      credit.artist_id = target_artist.id
      or (
        credit.artist_id is null
        and lower(coalesce(credit.artist_slug, '')) =
            lower(target_artist.slug)
      )
    )
  join public.registry_releases release
    on release.id = credit.release_id
   and release.status = 'active'
  where credit.status = 'active'
),

release_pairs as (
  select distinct
    related_artist.id as related_artist_id,
    target_credit.release_id
  from target_release_credits target_credit
  join public.registry_release_artists peer_credit
    on peer_credit.release_id = target_credit.release_id
   and peer_credit.status = 'active'
  join public.registry_artists related_artist
    on related_artist.status = 'active'
   and (
     (
       peer_credit.artist_id is not null
       and related_artist.id = peer_credit.artist_id
     )
     or (
       peer_credit.artist_id is null
       and lower(coalesce(peer_credit.artist_slug, '')) =
           lower(related_artist.slug)
     )
   )
  where related_artist.id <> p_artist_id
),

release_aggregate as (
  select
    pair.related_artist_id,
    count(*)::integer as shared_release_count
  from release_pairs pair
  group by pair.related_artist_id
),

candidate as (
  select
    coalesce(
      track.related_artist_id,
      release.related_artist_id
    ) as related_artist_id,
    coalesce(track.shared_track_count, 0) as shared_track_count,
    coalesce(release.shared_release_count, 0) as shared_release_count,
    coalesce(track.features_them, 0) as features_them,
    coalesce(track.they_feature, 0) as they_feature,
    coalesce(track.shared_titles, array[]::text[]) as shared_titles
  from track_aggregate track
  full join release_aggregate release
    on release.related_artist_id = track.related_artist_id
)

select
  artist.id as related_artist_id,
  artist.slug as related_artist_slug,
  artist.display_name as related_artist_name,
  artist.public_image_url as related_artist_image_url,
  candidate.shared_track_count,
  candidate.shared_release_count,
  candidate.features_them,
  candidate.they_feature,
  candidate.shared_titles,
  (
    candidate.shared_track_count * 100
    + candidate.shared_release_count * 20
    + candidate.features_them * 10
    + candidate.they_feature * 10
  )::integer as proximity_score
from candidate candidate
join public.registry_artists artist
  on artist.id = candidate.related_artist_id
 and artist.status = 'active'
where candidate.shared_track_count > 0
   or candidate.shared_release_count > 0
order by
  proximity_score desc,
  candidate.shared_track_count desc,
  candidate.shared_release_count desc,
  artist.display_name,
  artist.id;
$$;


ALTER FUNCTION "public"."get_public_artist_structural_proximity"("p_artist_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_public_living_memory"("p_entity_type" "text", "p_entity_id" "text" DEFAULT NULL::"text", "p_entity_slug" "text" DEFAULT NULL::"text") RETURNS TABLE("entity_type" "text", "entity_id" "uuid", "entity_slug" "text", "editorial_opener" "text", "public_prompt" "text", "editorial_label" "text", "status" "text", "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if p_entity_type = 'artist' then
    return query
    select 'artist'::text, a.id, a.slug, a.living_memory_editorial_opener,
           a.living_memory_public_prompt, a.living_memory_editorial_label,
           a.living_memory_status, a.living_memory_updated_at
    from public.registry_artists a
    where a.status = 'active'
      and a.living_memory_status = 'published'
      and nullif(trim(a.living_memory_editorial_opener), '') is not null
      and ((p_entity_id is not null and a.id::text = p_entity_id)
        or (p_entity_slug is not null and a.slug = p_entity_slug))
    limit 1;
  elsif p_entity_type = 'release' then
    return query
    select 'release'::text, r.id, r.slug, r.living_memory_editorial_opener,
           r.living_memory_public_prompt, r.living_memory_editorial_label,
           r.living_memory_status, r.living_memory_updated_at
    from public.registry_releases r
    where r.status in ('active','draft')
      and r.living_memory_status = 'published'
      and nullif(trim(r.living_memory_editorial_opener), '') is not null
      and ((p_entity_id is not null and r.id::text = p_entity_id)
        or (p_entity_slug is not null and r.slug = p_entity_slug))
    limit 1;
  elsif p_entity_type = 'track' then
    return query
    select 'track'::text, t.id, t.slug, t.living_memory_editorial_opener,
           t.living_memory_public_prompt, t.living_memory_editorial_label,
           t.living_memory_status, t.living_memory_updated_at
    from public.registry_tracks t
    where t.status in ('active','needs_review','draft')
      and t.living_memory_status = 'published'
      and nullif(trim(t.living_memory_editorial_opener), '') is not null
      and ((p_entity_id is not null and t.id::text = p_entity_id)
        or (p_entity_slug is not null and t.slug = p_entity_slug))
    limit 1;
  else
    return;
  end if;
end;
$$;


ALTER FUNCTION "public"."get_public_living_memory"("p_entity_type" "text", "p_entity_id" "text", "p_entity_slug" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_public_person"("p_slug" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $_$
declare
  v_input text;
  v_path text;
  v_requested_person_id uuid;
  v_person_id uuid;
  v_person editorial.people%rowtype;
  v_resource editorial.resources%rowtype;
  v_presentation jsonb;
  v_canonical_path text;
  v_depth integer := 0;
begin
  v_input := lower(
    btrim(
      coalesce(
        p_slug,
        ''
      )
    )
  );

  if v_input = '' then
    return null;
  end if;

  if v_input like '/people/%' then
    v_path := regexp_replace(
      v_input,
      '/+$',
      ''
    );
  else
    v_input := trim(
      both '/'
      from v_input
    );

    if v_input = '' then
      return null;
    end if;

    v_path :=
      '/people/' || v_input;
  end if;

  select alias.resource_id
  into v_requested_person_id
  from editorial.resource_aliases alias
  join editorial.resources resource
    on resource.id = alias.resource_id
   and resource.resource_kind = 'person'
  where alias.path = v_path
  order by
    alias.is_canonical desc,
    (alias.retired_at is null) desc,
    alias.created_at
  limit 1;

  if not found then
    return null;
  end if;

  v_person_id :=
    v_requested_person_id;

  loop
    v_depth := v_depth + 1;

    if v_depth > 8 then
      return null;
    end if;

    select person.*
    into v_person
    from editorial.people person
    where person.resource_id =
          v_person_id;

    if not found then
      return null;
    end if;

    exit when
      v_person.person_state <>
      'merged';

    if v_person.merged_into_person_resource_id
         is null
    then
      return null;
    end if;

    v_person_id :=
      v_person.merged_into_person_resource_id;
  end loop;

  if v_person.person_state <> 'active' then
    return null;
  end if;

  select resource.*
  into v_resource
  from editorial.resources resource
  where resource.id = v_person_id
    and resource.resource_kind = 'person';

  if not found
     or v_resource.visibility <> 'public'
     or v_resource.lifecycle_state <> 'active'
  then
    return null;
  end if;

  v_presentation :=
    editorial.resolve_person_presentation(
      v_person_id
    );

  if v_presentation is null then
    return null;
  end if;

  select alias.path
  into v_canonical_path
  from editorial.resource_aliases alias
  where alias.resource_id = v_person_id
    and alias.is_canonical
    and alias.retired_at is null;

  if v_canonical_path is null then
    return null;
  end if;

  return jsonb_strip_nulls(
    jsonb_build_object(
      'person_id',
        v_person_id,
      'canonical_path',
        v_canonical_path,
      'display_name',
        v_presentation ->> 'display_name',
      'bio',
        v_presentation ->> 'bio',
      'avatar_url',
        v_presentation ->> 'avatar_url',
      'cover_url',
        v_presentation ->> 'cover_url',
      'location',
        v_presentation ->> 'location',
      'username',
        v_presentation ->> 'username',
      'registry_author_slug',
        v_presentation
          ->> 'registry_author_slug',
      'redirect_to',
        case
          when v_requested_person_id
                 is distinct from v_person_id
            or v_path
                 is distinct from v_canonical_path
            then v_canonical_path
          else null
        end
    )
  );
end;
$_$;


