COMMENT ON FUNCTION "public"."get_public_person"("p_slug" "text") IS 'Narrow public Person identity read. Migration A intentionally excludes body-of-work roles and social Follow counts.';



CREATE OR REPLACE FUNCTION "public"."get_public_person_social_summary"("p_person_resource_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_person record;
  v_follower_count integer;
  v_following_count integer;
begin
  begin
    select *
    into v_person
    from editorial.resolve_person_follow_target(
      p_person_resource_id
    );
  exception
    when others then
      return null;
  end;

  if not v_person.followable then
    return null;
  end if;

  select count(*)::integer
  into v_follower_count
  from public.community_follows follow
  where follow.target_type =
        'person'
    and follow.target_id =
        v_person.person_resource_id::text;

  select count(
           distinct follow.target_id
         )::integer
  into v_following_count
  from public.community_follows follow
  where follow.target_type =
        'person'
    and exists (
      select 1
      from editorial.person_identity_links link
      join public.user_profiles profile
        on profile.user_id =
           link.user_id
      where link.person_resource_id =
            v_person.person_resource_id
        and link.link_state =
            'active'
        and link.user_id =
            follow.user_id
        and profile.status =
            'active'
        and profile.is_public
    );

  return jsonb_build_object(
    'person_id',
      v_person.person_resource_id,
    'follower_count',
      v_follower_count,
    'following_count',
      v_following_count
  );
end;
$$;


ALTER FUNCTION "public"."get_public_person_social_summary"("p_person_resource_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_public_person_social_summary"("p_person_resource_id" "uuid") IS 'Public Person social aggregate: stable Person id, follower count, and Person-only following count for active public linked accounts. Never returns follower/following identities or lists.';



CREATE OR REPLACE FUNCTION "public"."get_public_playlist"("p_slug" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
  with active_snapshot as (
    select snapshot.*
    from editorial.playlist_publication_snapshots snapshot
    join editorial.playlist_resources binding
      on binding.resource_id = snapshot.resource_id
     and binding.playlist_id = snapshot.playlist_id
     and binding.current_published_version_id =
           snapshot.version_id
    where snapshot.slug = p_slug
    order by snapshot.published_at desc
    limit 1
  )
  select
    snapshot.payload
    ||
    jsonb_build_object(
      'credits',
        coalesce(
          (
            select jsonb_agg(
              jsonb_build_object(
                'resource_id',
                  attachment.resource_id,
                'resource_kind',
                  attachment.resource_kind,
                'display_order',
                  attachment.display_order,
                'is_primary',
                  attachment.is_primary,
                'credit_id',
                  credit.id,
                'role',
                  credit.credit_role,
                'role_label',
                  credit.role_label_snapshot,
                'display_name',
                  credit.display_name_snapshot,
                'note',
                  credit.credit_note,
                'author_slug',
                  credit.registry_author_slug_snapshot,
                'username',
                  credit.user_username_snapshot
              )
              order by
                attachment.resource_kind,
                attachment.resource_id,
                attachment.display_order
            )
            from editorial.resource_credits attachment
            join editorial.credits credit
              on credit.id = attachment.credit_id
            join editorial.credit_governance governance
              on governance.credit_id = credit.id
            left join editorial.external_contributors contributor
              on contributor.id = credit.external_contributor_id
            where attachment.target_version_type =
                    'playlist_version'
              and attachment.target_version_id =
                    snapshot.version_id
              and attachment.public_safe
              and governance.public_safe
              and governance.credit_state = 'active'
              and (
                credit.external_contributor_id is null
                or (
                  contributor.contributor_state = 'active'
                  and contributor.public_safe
                  and contributor.consent_status in (
                    'granted',
                    'not_required'
                  )
                )
              )
          ),
          '[]'::jsonb
        ),

      'citations',
        coalesce(
          (
            select jsonb_agg(
              jsonb_build_object(
                'resource_id',
                  attachment.resource_id,
                'resource_kind',
                  attachment.resource_kind,
                'display_order',
                  attachment.display_order,
                'purpose',
                  attachment.citation_purpose,
                'anchor_type',
                  attachment.target_anchor_type,
                'anchor',
                  attachment.target_anchor_data,
                'citation_id',
                  citation.id,
                'public_label',
                  citation.public_label,
                'locator_type',
                  citation.locator_type,
                'locator',
                  citation.locator_data,
                'source',
                  jsonb_build_object(
                    'source_id',
                      source.id,
                    'source_version_id',
                      source_version.id,
                    'type',
                      source_version.source_type,
                    'title',
                      source_version.title,
                    'creator',
                      source_version.creator_display,
                    'publisher',
                      source_version.publisher_display,
                    'url',
                      case
                        when source.exposure_class = 'public'
                          then source_version.source_url
                        else null
                      end,
                    'publication_date',
                      source_version.publication_date,
                    'credit_line',
                      source_version.credit_line
                  )
              )
              order by
                attachment.resource_kind,
                attachment.resource_id,
                attachment.display_order
            )
            from editorial.resource_citations attachment
            join editorial.citations citation
              on citation.id = attachment.citation_id
            join editorial.source_versions source_version
              on source_version.id =
                   citation.source_version_id
            join editorial.sources source
              on source.id = citation.source_id
            where attachment.target_version_type =
                    'playlist_version'
              and attachment.target_version_id =
                    snapshot.version_id
              and attachment.public_safe
              and citation.public_safe
              and citation.citation_state = 'active'
              and source.source_state = 'active'
              and source.withdrawn_at is null
              and source.exposure_class in (
                'public',
                'public_redacted'
              )
              and source.current_approved_version_id =
                    citation.source_version_id
          ),
          '[]'::jsonb
        ),

      'corrections',
        coalesce(
          (
            select jsonb_agg(
              jsonb_build_object(
                'id',
                  note.id,
                'resource_id',
                  note.affected_resource_id,
                'resource_kind',
                  note.affected_resource_kind,
                'note',
                  note.note_text,
                'published_at',
                  note.published_at
              )
              order by note.published_at
            )
            from editorial.correction_public_notes note
            where (
              note.affected_resource_id =
                snapshot.resource_id
              or note.affected_resource_id in (
                select
                  nullif(
                    track
                      ->> 'playlist_item_resource_id',
                    ''
                  )::uuid
                from jsonb_array_elements(
                  snapshot.payload -> 'tracks'
                ) track
              )
            )
            and not exists (
              select 1
              from editorial.correction_public_notes newer
              where newer.supersedes_note_id = note.id
            )
          ),
          '[]'::jsonb
        )
    )
  from active_snapshot snapshot;
$$;


ALTER FUNCTION "public"."get_public_playlist"("p_slug" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_release_artists_for_anon"("p_artist_slug" "text") RETURNS TABLE("release_id" "uuid", "role" "text", "is_primary" boolean, "source" "text", "confidence" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT rra.release_id, rra.role, rra.is_primary, rra.source, rra.confidence
  FROM public.registry_release_artists rra
  WHERE rra.artist_slug = p_artist_slug;
END;
$$;


ALTER FUNCTION "public"."get_release_artists_for_anon"("p_artist_slug" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_release_artists_for_anon_v2"("p_artist_slug" "text") RETURNS TABLE("release_id" "uuid", "role" "text", "is_primary" boolean, "source" "text", "confidence" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  -- Direct release-artist links (primary and featured from ingest)
  SELECT rra.release_id, rra.role, rra.is_primary, rra.source, rra.confidence
  FROM public.registry_release_artists rra
  WHERE rra.artist_slug = p_artist_slug
  
  UNION
  
  -- Featured appearances from track-level data
  SELECT 
    rrt.release_id,
    'featured_artist'::text AS role,
    false AS is_primary,
    'apple_music_ingest'::text AS source,
    85::integer AS confidence
  FROM public.registry_track_artists rta
  JOIN public.registry_release_tracks rrt ON rrt.track_id = rta.track_id
  WHERE rta.artist_slug = p_artist_slug
    AND rta.is_primary = false
    AND rta.status = 'active'
    -- Don't duplicate releases that already have direct release-artist entries
    AND rrt.release_id NOT IN (
      SELECT rra2.release_id 
      FROM public.registry_release_artists rra2 
      WHERE rra2.artist_slug = p_artist_slug
    );
END;
$$;


