    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT t.id, t.slug, t.name, t.description, t.created_at, t.updated_at
  FROM public.registry_taxonomy_terms t
  WHERE t.taxonomy = p_taxonomy
    AND t.status = 'active'
  ORDER BY t.name ASC;
$$;


ALTER FUNCTION "public"."get_taxonomy_terms"("p_taxonomy" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_taxonomy_terms"("p_taxonomy" "text", "p_search" "text" DEFAULT NULL::"text", "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT NULL::integer) RETURNS TABLE("id" "uuid", "slug" "text", "name" "text", "description" "text", "seo_title" "text", "seo_description" "text", "seo_keywords" "text", "source_kind" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "total_count" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    AS $$
  WITH filtered AS (
    SELECT t.id, t.slug, t.name, t.description,
           t.metadata->>'seo_title' AS seo_title,
           t.metadata->>'seo_description' AS seo_description,
           t.metadata->>'seo_keywords' AS seo_keywords,
           t.source_kind, t.created_at, t.updated_at
    FROM public.registry_taxonomy_terms t
    WHERE t.taxonomy = p_taxonomy
      AND t.status = 'active'
      AND (
        p_search IS NULL
        OR p_search = ''
        OR t.name ILIKE '%' || p_search || '%'
        OR t.slug ILIKE '%' || p_search || '%'
        OR COALESCE(t.description, '') ILIKE '%' || p_search || '%'
      )
  ),
  counted AS (
    SELECT COUNT(*) AS total FROM filtered
  )
  SELECT f.id, f.slug, f.name, f.description,
         f.seo_title, f.seo_description, f.seo_keywords,
         f.source_kind, f.created_at, f.updated_at,
         c.total AS total_count
  FROM filtered f, counted c
  ORDER BY f.name ASC
  LIMIT CASE WHEN p_page_size IS NOT NULL AND p_page_size > 0 THEN p_page_size END
  OFFSET CASE WHEN p_page_size IS NOT NULL AND p_page_size > 0 THEN (p_page - 1) * p_page_size ELSE 0 END;
$$;


ALTER FUNCTION "public"."get_taxonomy_terms"("p_taxonomy" "text", "p_search" "text", "p_page" integer, "p_page_size" integer) OWNER TO "postgres";


