CREATE OR REPLACE FUNCTION "public"."increment_share_count"("p_page_url" "text", "p_platform" "text") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  RETURN increment_share_count(p_page_url, p_platform, NULL, NULL);
END;
$$;


ALTER FUNCTION "public"."increment_share_count"("p_page_url" "text", "p_platform" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."increment_share_count"("p_page_url" "text", "p_platform" "text", "p_article_slug" "text" DEFAULT NULL::"text", "p_article_title" "text" DEFAULT NULL::"text") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  new_count BIGINT;
BEGIN
  -- Upsert the aggregate counter
  INSERT INTO share_counts (page_url, platform, count)
  VALUES (p_page_url, p_platform, 1)
  ON CONFLICT (page_url, platform)
  DO UPDATE SET count = share_counts.count + 1, updated_at = now()
  RETURNING count INTO new_count;

  -- Log the individual event for daily trend analytics
  INSERT INTO share_events (page_url, platform, article_slug, article_title)
  VALUES (p_page_url, p_platform, p_article_slug, p_article_title);

  RETURN new_count;
END;
$$;


