CREATE OR REPLACE FUNCTION "public"."institute_review_contributor_submission"("p_submission_id" "uuid", "p_decision" "text", "p_decision_note" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "submission_type" "text", "review_status" "text", "reviewed_by" "uuid", "reviewed_at" timestamp with time zone, "review_note" "text", "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_submission public.contributor_submissions%rowtype;
  v_next_review_status text;
  v_review_decision text;
  v_review_note text;
begin
  if not public.institute_can_review() then
    raise exception 'Institute contributor submission review permission denied'
      using errcode = '42501';
  end if;

  select *
  into v_submission
  from public.contributor_submissions
  where contributor_submissions.id = p_submission_id
  for update;

  if not found then
    raise exception 'Contributor submission not found'
      using errcode = 'P0002';
  end if;

  v_next_review_status := v_submission.review_status;
  v_review_decision := p_decision;
  v_review_note := nullif(trim(coalesce(p_decision_note, '')), '');

  case p_decision
    when 'triaged' then
      v_next_review_status := 'triaged';
      v_review_decision := 'approved';
    when 'needs_source' then
      v_next_review_status := 'needs_source';
      v_review_decision := 'needs_more_evidence';
    when 'needs_clarification' then
      v_next_review_status := 'needs_clarification';
      v_review_decision := 'needs_more_evidence';
    when 'accepted_as_memory' then
      v_next_review_status := 'accepted_as_memory';
      v_review_decision := 'accepted_as_memory';
    when 'accepted_as_evidence' then
      v_next_review_status := 'accepted_as_evidence';
      v_review_decision := 'accepted_as_evidence';
    when 'rejected' then
      v_next_review_status := 'rejected';
      v_review_decision := 'rejected';
    when 'archived' then
      v_next_review_status := 'archived';
      v_review_decision := 'internal_only';
    else
      raise exception 'Unsupported contributor submission review decision: %', p_decision
        using errcode = '22023';
  end case;

  update public.contributor_submissions
  set
    review_status = v_next_review_status,
    reviewed_by = auth.uid(),
    reviewed_at = now(),
    review_note = coalesce(v_review_note, concat('Submission marked ', replace(p_decision, '_', ' '))),
    updated_at = now()
  where contributor_submissions.id = p_submission_id
  returning *
  into v_submission;

  insert into public.review_decisions (
    subject_type,
    subject_id,
    decision,
    reason,
    reviewer_id
  )
  values (
    'contributor_submission',
    p_submission_id,
    v_review_decision,
    coalesce(v_review_note, concat('Submission marked ', replace(p_decision, '_', ' '))),
    auth.uid()
  );

  return query
  select
    v_submission.id,
    v_submission.submission_type,
    v_submission.review_status,
    v_submission.reviewed_by,
    v_submission.reviewed_at,
    v_submission.review_note,
    v_submission.updated_at;
end;
$$;


ALTER FUNCTION "public"."institute_review_contributor_submission"("p_submission_id" "uuid", "p_decision" "text", "p_decision_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."institute_review_entity_relationship"("p_relationship_id" "uuid", "p_decision" "text", "p_decision_note" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "relationship_type" "text", "review_status" "text", "public_safe" boolean, "reviewed_by" "uuid", "reviewed_at" timestamp with time zone, "review_note" "text", "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_relationship public.entity_relationships%rowtype;
  v_next_review_status text;
  v_next_public_safe boolean;
  v_review_decision text;
  v_review_note text;
begin
  if not public.institute_can_review() then
    raise exception 'Institute relationship review permission denied'
      using errcode = '42501';
  end if;

  select *
  into v_relationship
  from public.entity_relationships
  where entity_relationships.id = p_relationship_id
  for update;

  if not found then
    raise exception 'Entity relationship not found'
      using errcode = 'P0002';
  end if;

  v_next_review_status := v_relationship.review_status;
  v_next_public_safe := v_relationship.public_safe;
  v_review_decision := p_decision;
  v_review_note := nullif(trim(coalesce(p_decision_note, '')), '');

  case p_decision
    when 'approved' then
      v_next_review_status := 'approved';
      v_review_decision := 'approved';
    when 'rejected' then
      v_next_review_status := 'rejected';
      v_next_public_safe := false;
      v_review_decision := 'rejected';
    when 'disputed' then
      v_next_review_status := 'disputed';
      v_next_public_safe := false;
      v_review_decision := 'needs_more_evidence';
    when 'needs_more_evidence' then
      v_next_review_status := 'pending_review';
      v_next_public_safe := false;
      v_review_decision := 'needs_more_evidence';
    when 'public_safe_enabled' then
      if v_relationship.review_status <> 'approved' then
        raise exception 'Public-safe relationship publishing requires approved relationship review'
          using errcode = '23514';
      end if;

      v_next_public_safe := true;
      v_review_decision := 'approved';
    when 'public_safe_disabled' then
      v_next_public_safe := false;
      v_review_decision := 'internal_only';
    else
      raise exception 'Unsupported relationship review decision: %', p_decision
        using errcode = '22023';
  end case;

  update public.entity_relationships
  set
    review_status = v_next_review_status,
    public_safe = v_next_public_safe,
    reviewed_by = auth.uid(),
    reviewed_at = now(),
    review_note = coalesce(v_review_note, concat('Relationship marked ', replace(p_decision, '_', ' '))),
    updated_at = now()
  where entity_relationships.id = p_relationship_id
  returning *
  into v_relationship;

  insert into public.review_decisions (
    subject_type,
    subject_id,
    decision,
    reason,
    reviewer_id
  )
  values (
    'relationship',
    p_relationship_id,
    v_review_decision,
    coalesce(v_review_note, concat('Relationship marked ', replace(p_decision, '_', ' '))),
    auth.uid()
  );

  return query
  select
    v_relationship.id,
    v_relationship.relationship_type,
    v_relationship.review_status,
    v_relationship.public_safe,
    v_relationship.reviewed_by,
    v_relationship.reviewed_at,
    v_relationship.review_note,
    v_relationship.updated_at;
end;
$$;


ALTER FUNCTION "public"."institute_review_entity_relationship"("p_relationship_id" "uuid", "p_decision" "text", "p_decision_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."institute_review_evidence_item"("p_evidence_id" "uuid", "p_decision" "text", "p_decision_note" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "title" "text", "review_status" "text", "retrieval_status" "text", "reviewed_by" "uuid", "reviewed_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_evidence public.evidence_items%rowtype;
  v_previous_review_status text;
  v_previous_retrieval_status text;
  v_next_review_status text;
  v_next_retrieval_status text;
  v_review_decision text;
begin
  if not public.institute_can_review() then
    raise exception 'Institute review permission denied'
      using errcode = '42501';
  end if;

  select *
  into v_evidence
  from public.evidence_items
  where evidence_items.id = p_evidence_id
  for update;

  if not found then
    raise exception 'Evidence item not found'
      using errcode = 'P0002';
  end if;

  v_previous_review_status := v_evidence.review_status;
  v_previous_retrieval_status := v_evidence.retrieval_status;
  v_next_review_status := v_evidence.review_status;
  v_next_retrieval_status := v_evidence.retrieval_status;
  v_review_decision := p_decision;

  case p_decision
    when 'reviewed' then
      v_next_review_status := 'reviewed';
      v_review_decision := 'approved';
    when 'approved' then
      v_next_review_status := 'approved';
      v_review_decision := 'approved';
    when 'rejected' then
      v_next_review_status := 'rejected';
      v_next_retrieval_status := 'excluded';
      v_review_decision := 'rejected';
    when 'disputed' then
      v_next_review_status := 'disputed';
      v_next_retrieval_status := 'review_only';
      v_review_decision := 'needs_more_evidence';
    when 'needs_more_evidence' then
      v_next_review_status := 'unreviewed';
      v_next_retrieval_status := 'review_only';
      v_review_decision := 'needs_more_evidence';
    when 'retrieval_enabled' then
      if v_evidence.review_status not in ('reviewed', 'approved') then
        raise exception 'Default retrieval requires reviewed or approved evidence'
          using errcode = '23514';
      end if;

      v_next_retrieval_status := 'default_retrieval';
      v_review_decision := 'approved';
    when 'retrieval_disabled' then
      v_next_retrieval_status := 'excluded';
      v_review_decision := 'internal_only';
    else
      raise exception 'Unsupported evidence review decision: %', p_decision
        using errcode = '22023';
  end case;

  update public.evidence_items
  set
    review_status = v_next_review_status,
    retrieval_status = v_next_retrieval_status,
    reviewed_by = auth.uid(),
    reviewed_at = now(),
    updated_at = now()
  where evidence_items.id = p_evidence_id
  returning *
  into v_evidence;

  insert into public.evidence_review_events (
    evidence_id,
    decision,
    previous_review_status,
    next_review_status,
    previous_retrieval_status,
    next_retrieval_status,
    decision_note,
    decided_by
  )
  values (
    p_evidence_id,
    p_decision,
    v_previous_review_status,
    v_next_review_status,
    v_previous_retrieval_status,
    v_next_retrieval_status,
    p_decision_note,
    auth.uid()
  );

  insert into public.review_decisions (
    subject_type,
    subject_id,
    decision,
    reason,
    reviewer_id
  )
  values (
    'evidence',
    p_evidence_id,
    v_review_decision,
    coalesce(nullif(trim(p_decision_note), ''), concat('Evidence marked ', replace(p_decision, '_', ' '))),
    auth.uid()
  );

  return query
  select
    v_evidence.id,
    v_evidence.title,
    v_evidence.review_status,
    v_evidence.retrieval_status,
    v_evidence.reviewed_by,
    v_evidence.reviewed_at,
    v_evidence.updated_at;
end;
$$;


ALTER FUNCTION "public"."institute_review_evidence_item"("p_evidence_id" "uuid", "p_decision" "text", "p_decision_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."institute_review_surface_draft"("p_draft_id" "uuid", "p_decision" "text", "p_decision_note" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "surface_type" "text", "review_status" "text", "public_safe" boolean, "reviewed_by" "uuid", "reviewed_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_draft public.surface_drafts%rowtype;
  v_next_review_status text;
  v_next_public_safe boolean;
  v_review_decision text;
  v_review_note text;
begin
  if not public.institute_can_review() then
    raise exception 'Institute surface draft review permission denied'
      using errcode = '42501';
  end if;

  select *
  into v_draft
  from public.surface_drafts
  where surface_drafts.id = p_draft_id
  for update;

  if not found then
    raise exception 'Surface draft not found'
      using errcode = 'P0002';
  end if;

  v_next_review_status := v_draft.review_status;
  v_next_public_safe := v_draft.public_safe;
  v_review_decision := p_decision;
  v_review_note := nullif(trim(coalesce(p_decision_note, '')), '');

  case p_decision
    when 'pending_review' then
      v_next_review_status := 'pending_review';
      v_next_public_safe := false;
      v_review_decision := 'approved';
    when 'approved' then
      v_next_review_status := 'approved';
      v_review_decision := 'approved';
    when 'rejected' then
      v_next_review_status := 'rejected';
      v_next_public_safe := false;
      v_review_decision := 'rejected';
    when 'needs_rewrite' then
      v_next_review_status := 'revised';
      v_next_public_safe := false;
      v_review_decision := 'needs_rewrite';
    when 'too_vague' then
      v_next_review_status := 'revised';
      v_next_public_safe := false;
      v_review_decision := 'too_vague';
    when 'overclaims' then
      v_next_review_status := 'revised';
      v_next_public_safe := false;
      v_review_decision := 'overclaims';
    when 'public_safe_enabled' then
      if v_draft.review_status <> 'approved' then
        raise exception 'Public-safe draft publishing requires approved draft review'
          using errcode = '23514';
      end if;

      v_next_public_safe := true;
      v_review_decision := 'approved';
    when 'public_safe_disabled' then
      v_next_public_safe := false;
      v_review_decision := 'internal_only';
    else
      raise exception 'Unsupported surface draft review decision: %', p_decision
        using errcode = '22023';
  end case;

  update public.surface_drafts
  set
    review_status = v_next_review_status,
    public_safe = v_next_public_safe,
    reviewed_by = auth.uid(),
    reviewed_at = now(),
    updated_at = now()
  where surface_drafts.id = p_draft_id
  returning *
  into v_draft;

  insert into public.review_decisions (
    subject_type,
    subject_id,
    decision,
    reason,
    reviewer_id
  )
  values (
    'surface_draft',
    p_draft_id,
    v_review_decision,
    coalesce(v_review_note, concat('Surface draft marked ', replace(p_decision, '_', ' '))),
    auth.uid()
  );

  return query
  select
    v_draft.id,
    v_draft.surface_type,
    v_draft.review_status,
    v_draft.public_safe,
    v_draft.reviewed_by,
    v_draft.reviewed_at,
    v_draft.updated_at;
end;
$$;


ALTER FUNCTION "public"."institute_review_surface_draft"("p_draft_id" "uuid", "p_decision" "text", "p_decision_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."institute_set_updated_at"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  new.updated_at = now();
  return new;
end;
$$;


ALTER FUNCTION "public"."institute_set_updated_at"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."is_current_user_administrator"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.user_role_assignments ura
    where ura.user_id = auth.uid()
      and ura.status = 'active'
      and ura.role_key = 'administrator'
      and (ura.expires_at is null or ura.expires_at > now())
  );
$$;


ALTER FUNCTION "public"."is_current_user_administrator"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."link_correction_evidence"("p_case_resource_id" "uuid", "p_expected_case_revision" bigint, "p_source_id" "uuid", "p_source_version_id" "uuid", "p_citation_id" "uuid", "p_evidence_role" "text", "p_internal_note" "text", "p_reason" "text", "p_idempotency_key" "text", "p_correlation_id" "uuid") RETURNS TABLE("command_receipt_id" "uuid", "receipt_status" "text", "case_resource_id" "uuid", "case_revision" bigint, "result_payload" "jsonb", "idempotent_replay" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'editorial', 'platform_private'
    AS $$
declare
  v_actor uuid;
  v_begin record;
  v_case editorial.correction_cases%rowtype;
  v_evidence_id uuid;
  v_result jsonb;
begin
  v_actor :=
    platform_private.assert_correction_capability(
      'investigate_corrections'
    );

  if p_case_resource_id is null
     or p_expected_case_revision < 1
     or p_source_id is null
     or p_source_version_id is null
     or p_correlation_id is null
     or nullif(btrim(p_reason), '') is null
     or not exists (
       select 1
       from editorial.correction_evidence_roles role_row
       where role_row.evidence_role =
         p_evidence_role
         and role_row.enabled
     )
  then
    raise exception
      using errcode = '22023',
      message = 'Case, revision, evidence identity, role, reason, and correlation identity are required.';
  end if;

  select *
  into v_begin
  from platform_private.begin_resource_command(
    'correction.evidence.link',
    p_case_resource_id,
    p_idempotency_key,
    jsonb_build_object(
      'expected_case_revision', p_expected_case_revision,
      'source_id', p_source_id,
      'source_version_id', p_source_version_id,
      'citation_id', p_citation_id,
      'evidence_role', p_evidence_role,
      'internal_note', nullif(btrim(p_internal_note), ''),
      'reason', btrim(p_reason),
      'correlation_id', p_correlation_id
    )
  );

  if v_begin.idempotent_replay then
    return query
    select *
    from platform_private.read_correction_command_result(
      v_begin.command_receipt_id,
      true
    );
    return;
  end if;

  select correction_case.*
  into v_case
  from editorial.correction_cases correction_case
  where correction_case.resource_id =
    p_case_resource_id
  for update;

  if not found then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'case_not_found',
      'The correction case does not exist.',
      jsonb_build_object('case_revision', null)
    );
  elsif v_case.current_revision <>
        p_expected_case_revision
  then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'case_revision_changed',
      'The correction case revision changed.',
      jsonb_build_object(
        'case_revision', v_case.current_revision,
        'case_state', v_case.case_state
      )
    );
  elsif v_case.case_state <> 'investigating' then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'invalid_transition',
      'Evidence may be linked only while the case is investigating.',
      jsonb_build_object(
        'case_revision', v_case.current_revision,
        'case_state', v_case.case_state
      )
    );
  elsif not exists (
    select 1
    from editorial.sources source
    join editorial.source_versions version
      on version.id = p_source_version_id
     and version.source_id = p_source_id
    where source.id = p_source_id
      and source.source_state = 'active'
      and source.review_status = 'approved'
      and source.current_approved_version_id =
        p_source_version_id
      and (
        p_citation_id is null
        or exists (
          select 1
          from editorial.citations citation
          where citation.id = p_citation_id
            and citation.source_id = p_source_id
            and citation.source_version_id =
              p_source_version_id
            and citation.citation_state = 'active'
        )
      )
  ) then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'evidence_invalid',
      'Evidence must use an active approved Source version and a matching active Citation when supplied.',
      jsonb_build_object(
        'case_revision', v_case.current_revision,
        'case_state', v_case.case_state
      )
    );
  else
    insert into editorial.correction_evidence_links (
      case_resource_id,
      source_id,
      source_version_id,
      citation_id,
      evidence_role,
      internal_note,
      created_by
    )
    values (
      p_case_resource_id,
      p_source_id,
      p_source_version_id,
      p_citation_id,
      p_evidence_role,
      nullif(btrim(p_internal_note), ''),
      v_actor
    )
    returning id
    into v_evidence_id;

    update editorial.correction_cases
    set
      current_revision =
        v_case.current_revision + 1,
      updated_by = v_actor,
      updated_at = now()
    where resource_id = p_case_resource_id;

    perform platform_private.append_correction_event(
      p_case_resource_id,
      'evidence_linked',
      v_case.current_revision,
      v_case.current_revision + 1,
      v_case.case_state,
      v_case.case_state,
      v_actor,
      btrim(p_reason),
      null,
      null,
      v_evidence_id,
      null,
      v_begin.command_receipt_id,
      p_correlation_id,
      jsonb_build_object(
        'source_id', p_source_id,
        'source_version_id', p_source_version_id,
        'citation_id', p_citation_id,
        'evidence_role', p_evidence_role
      )
    );

    v_result := jsonb_build_object(
      'case_resource_id', p_case_resource_id,
      'case_revision', v_case.current_revision + 1,
      'case_state', v_case.case_state,
      'evidence_link_id', v_evidence_id
    );

    perform platform_private.complete_resource_command(
      v_begin.command_receipt_id,
      v_result
    );
  end if;

  return query
  select *
  from platform_private.read_correction_command_result(
    v_begin.command_receipt_id,
    false
  );
end;
$$;


ALTER FUNCTION "public"."link_correction_evidence"("p_case_resource_id" "uuid", "p_expected_case_revision" bigint, "p_source_id" "uuid", "p_source_version_id" "uuid", "p_citation_id" "uuid", "p_evidence_role" "text", "p_internal_note" "text", "p_reason" "text", "p_idempotency_key" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."link_orphan_release_artists"() RETURNS TABLE("result" "jsonb")
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  rec RECORD;
  best_artist RECORD;
  linked_count integer := 0;
BEGIN
  FOR rec IN
    SELECT r.id, r.title, r.slug
    FROM registry_releases r
    WHERE NOT EXISTS (
      SELECT 1 FROM registry_release_artists ra 
      WHERE ra.release_id = r.id AND ra.status = 'active'
    )
  LOOP
    -- Try track-based deduction first: most common primary track artist
    SELECT ta.artist_slug, ta.artist_name_text, ta.artist_id, COUNT(*) as cnt
    INTO best_artist
    FROM registry_release_tracks rt
    JOIN registry_track_artists ta ON ta.track_id = rt.track_id 
      AND ta.status = 'active' AND ta.is_primary = true
    WHERE rt.release_id = rec.id AND rt.status = 'active'
    GROUP BY ta.artist_slug, ta.artist_name_text, ta.artist_id
    ORDER BY cnt DESC
    LIMIT 1;

    IF best_artist.artist_slug IS NOT NULL THEN
      -- Link primary artist from track data
      INSERT INTO registry_release_artists (release_id, artist_slug, artist_name_text, artist_id, role, is_primary, is_featured, credit_order, source, confidence, status, metadata)
      VALUES (rec.id, best_artist.artist_slug, best_artist.artist_name_text, best_artist.artist_id,
        'primary_artist', true, false, 1, 'orphan_link_repair', 70, 'active',
        jsonb_build_object('method', 'track_artist_deduction', 'track_count', best_artist.cnt, 'repaired_at', now()::text));
      
      linked_count := linked_count + 1;
    END IF;
  END LOOP;

  result := jsonb_build_object('summary', 'Complete', 'orphans_linked', linked_count);
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."link_orphan_release_artists"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."link_person_identity"("p_person_resource_id" "uuid", "p_expected_identity_revision" bigint, "p_user_id" "uuid", "p_registry_author_id" "uuid", "p_external_contributor_id" "uuid", "p_link_method" "text", "p_reason" "text", "p_idempotency_key" "text", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("command_receipt_id" "uuid", "receipt_status" "text", "person_resource_id" "uuid", "identity_revision" bigint, "identity_link_id" "uuid", "result_payload" "jsonb", "idempotent_replay" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'editorial', 'platform_private'
    AS $$
declare
  v_actor_id uuid;
  v_person editorial.people%rowtype;
  v_begin record;
  v_read record;
  v_request jsonb;
  v_result jsonb;
  v_correlation_id uuid;
  v_source_key text;
  v_source_exists boolean;
  v_existing_source_link
    editorial.person_identity_links%rowtype;
  v_conflicting_link_id uuid;
  v_new_link_id uuid;
  v_prior_revision bigint;
begin
  if p_person_resource_id is null
     or p_expected_identity_revision is null
     or p_expected_identity_revision < 1
     or num_nonnulls(
          p_user_id,
          p_registry_author_id,
          p_external_contributor_id
        ) <> 1
     or p_link_method <>
        'admin_reconciliation'
     or nullif(
          btrim(
            coalesce(
              p_reason,
              ''
            )
          ),
          ''
        ) is null
  then
    raise exception
      using
        errcode = '22023',
        message =
          'Valid Person, expected revision, one typed source, admin_reconciliation method, and reason are required.';
  end if;

  if coalesce(
       auth.role(),
       ''
     ) <> 'authenticated'
     or auth.uid() is null
     or not public.current_user_has_capability(
       'manage_people_identity'
     )
  then
    raise exception
      using
        errcode = '42501',
        message =
          'People identity management permission is required.';
  end if;

  v_actor_id :=
    auth.uid();

  if p_user_id is not null then
    v_source_key :=
      'person-source|user|' ||
      p_user_id::text;
  elsif p_registry_author_id is not null then
    v_source_key :=
      'person-source|registry-author|' ||
      p_registry_author_id::text;
  else
    v_source_key :=
      'person-source|external-contributor|' ||
      p_external_contributor_id::text;
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      v_source_key,
      0
    )
  );

  select person.*
  into v_person
  from editorial.people person
  where person.resource_id =
        p_person_resource_id
  for update;

  if not exists (
    select 1
    from editorial.resources resource
    where resource.id =
          p_person_resource_id
  ) then
    raise exception
      using
        errcode = 'P0002',
        message =
          'The Person Resource does not exist.';
  end if;

  v_request :=
    jsonb_build_object(
      'person_resource_id',
        p_person_resource_id,
      'expected_identity_revision',
        p_expected_identity_revision,
      'user_id',
        p_user_id,
      'registry_author_id',
        p_registry_author_id,
      'external_contributor_id',
        p_external_contributor_id,
      'link_method',
        p_link_method,
      'reason',
        p_reason,
      'correlation_id',
        p_correlation_id
    );

  select *
  into v_begin
  from platform_private.begin_authenticated_resource_command(
    'person.identity_link',
    p_person_resource_id,
    p_idempotency_key,
    v_request
  );

  if v_begin.idempotent_replay then
    select *
    into v_read
    from platform_private.read_authenticated_resource_command_result(
      v_begin.command_receipt_id,
      true
    );

    command_receipt_id :=
      v_read.command_receipt_id;
    receipt_status :=
      v_read.receipt_status;
    person_resource_id :=
      p_person_resource_id;
    identity_revision :=
      nullif(
        v_read.result_payload
          ->> 'identity_revision',
        ''
      )::bigint;
    identity_link_id :=
      nullif(
        v_read.result_payload
          ->> 'identity_link_id',
        ''
      )::uuid;
    result_payload :=
      v_read.result_payload;
    idempotent_replay :=
      true;
    return next;
    return;
  end if;

  v_correlation_id :=
    coalesce(
      p_correlation_id,
      gen_random_uuid()
    );

  if v_person.resource_id is null then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'person_not_found',
      'The Person does not exist.',
      jsonb_build_object(
        'person_resource_id',
          p_person_resource_id,
        'identity_revision',
          null
      )
    );

  elsif v_person.person_state <> 'active' then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'person_not_active',
      'Only an active Person may receive a reconciled identity.',
      jsonb_build_object(
        'person_resource_id',
          p_person_resource_id,
        'identity_revision',
          v_person.identity_revision,
        'person_state',
          v_person.person_state
      )
    );

  elsif v_person.identity_revision <>
        p_expected_identity_revision
  then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'person_identity_revision_changed',
      'The Person identity changed before this link could be applied.',
      jsonb_build_object(
        'person_resource_id',
          p_person_resource_id,
        'identity_revision',
          v_person.identity_revision
      )
    );

  else
    if p_user_id is not null then
      select exists (
        select 1
        from public.user_profiles profile
        where profile.user_id =
              p_user_id
      )
      into v_source_exists;

      select link.*
      into v_existing_source_link
      from editorial.person_identity_links link
      where link.user_id =
            p_user_id
        and link.link_state = 'active';

    elsif p_registry_author_id is not null then
      select exists (
        select 1
        from public.registry_authors author
        where author.id =
              p_registry_author_id
      )
      into v_source_exists;

      select link.*
      into v_existing_source_link
      from editorial.person_identity_links link
      where link.registry_author_id =
            p_registry_author_id
        and link.link_state = 'active';

    else
      select exists (
        select 1
        from editorial.external_contributors contributor
        where contributor.id =
              p_external_contributor_id
      )
      into v_source_exists;

      select link.*
      into v_existing_source_link
      from editorial.person_identity_links link
      where link.external_contributor_id =
            p_external_contributor_id
        and link.link_state = 'active';
    end if;

    if not v_source_exists then
      perform platform_private.reject_resource_command(
        v_begin.command_receipt_id,
        'person_identity_source_not_found',
        'The requested Person identity source does not exist.',
        jsonb_build_object(
          'person_resource_id',
            p_person_resource_id,
          'identity_revision',
            v_person.identity_revision
        )
      );

    elsif v_existing_source_link.id is not null
          and v_existing_source_link.person_resource_id =
              p_person_resource_id
    then
      v_result :=
        jsonb_build_object(
          'person_resource_id',
            p_person_resource_id,
          'identity_revision',
            v_person.identity_revision,
          'identity_link_id',
            v_existing_source_link.id,
          'changed',
            false,
          'correlation_id',
            v_correlation_id
        );

      perform platform_private.complete_resource_command(
        v_begin.command_receipt_id,
        v_result
      );

    elsif v_existing_source_link.id is not null then
      perform platform_private.reject_resource_command(
        v_begin.command_receipt_id,
        'person_identity_source_already_linked',
        'The identity source is already linked to another Person.',
        jsonb_build_object(
          'person_resource_id',
            p_person_resource_id,
          'identity_revision',
            v_person.identity_revision,
          'linked_person_resource_id',
            v_existing_source_link.person_resource_id
        )
      );

    else
      v_conflicting_link_id := null;

      if p_user_id is not null then
        select link.id
        into v_conflicting_link_id
        from editorial.person_identity_links link
        where link.person_resource_id =
              p_person_resource_id
          and link.link_state = 'active'
          and link.user_id is not null
        limit 1;

      elsif p_registry_author_id is not null then
        select link.id
        into v_conflicting_link_id
        from editorial.person_identity_links link
        where link.person_resource_id =
              p_person_resource_id
          and link.link_state = 'active'
          and link.registry_author_id is not null
        limit 1;
      end if;

      if v_conflicting_link_id is not null then
        perform platform_private.reject_resource_command(
          v_begin.command_receipt_id,
          'person_identity_kind_conflict',
          'The Person already has a different active identity of this kind.',
          jsonb_build_object(
            'person_resource_id',
              p_person_resource_id,
            'identity_revision',
              v_person.identity_revision,
            'conflicting_identity_link_id',
              v_conflicting_link_id
          )
        );

      else
        v_new_link_id :=
          gen_random_uuid();
        v_prior_revision :=
          v_person.identity_revision;

        insert into editorial.person_identity_links (
          id,
          person_resource_id,
          person_resource_kind,
          user_id,
          registry_author_id,
          external_contributor_id,
          link_state,
          link_method,
          link_reason,
          created_by
        )
        values (
          v_new_link_id,
          p_person_resource_id,
          'person',
          p_user_id,
          p_registry_author_id,
          p_external_contributor_id,
          'active',
          'admin_reconciliation',
          p_reason,
          v_actor_id
        );

        update editorial.people person
        set
          preferred_identity_link_id =
            coalesce(
              person.preferred_identity_link_id,
              v_new_link_id
            ),
          identity_revision =
            person.identity_revision + 1,
          updated_by =
            v_actor_id,
          updated_at =
            now()
        where person.resource_id =
              p_person_resource_id
        returning person.*
        into v_person;

        insert into editorial.person_identity_events (
          person_resource_id,
          actor_id,
          event_type,
          identity_link_id,
          prior_identity_revision,
          resulting_identity_revision,
          reason,
          correlation_id
        )
        values (
          p_person_resource_id,
          v_actor_id,
          'identity_linked',
          v_new_link_id,
          v_prior_revision,
          v_person.identity_revision,
          p_reason,
          v_correlation_id
        );

        perform editorial.refresh_person_visibility(
          p_person_resource_id
        );

        v_result :=
          jsonb_build_object(
            'person_resource_id',
              p_person_resource_id,
            'identity_revision',
              v_person.identity_revision,
            'identity_link_id',
              v_new_link_id,
            'changed',
              true,
            'correlation_id',
              v_correlation_id
          );

        perform platform_private.complete_resource_command(
          v_begin.command_receipt_id,
          v_result
        );
      end if;
    end if;
  end if;

  select *
  into v_read
  from platform_private.read_authenticated_resource_command_result(
    v_begin.command_receipt_id,
    false
  );

  command_receipt_id :=
    v_read.command_receipt_id;
  receipt_status :=
    v_read.receipt_status;
  person_resource_id :=
    p_person_resource_id;
  identity_revision :=
    nullif(
      v_read.result_payload
        ->> 'identity_revision',
      ''
    )::bigint;
  identity_link_id :=
    nullif(
      v_read.result_payload
        ->> 'identity_link_id',
      ''
    )::uuid;
  result_payload :=
    v_read.result_payload;
  idempotent_replay :=
    false;
  return next;
end;
$$;


ALTER FUNCTION "public"."link_person_identity"("p_person_resource_id" "uuid", "p_expected_identity_revision" bigint, "p_user_id" "uuid", "p_registry_author_id" "uuid", "p_external_contributor_id" "uuid", "p_link_method" "text", "p_reason" "text", "p_idempotency_key" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."link_publishing_item_resource"("p_item_id" "uuid", "p_expected_record_version" bigint, "p_resource_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS TABLE("item_id" "uuid", "record_version" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_item editorial.publishing_items%rowtype;
  v_updated editorial.publishing_items%rowtype;
begin
  if auth.uid() is null then
    raise exception
      using
        errcode = '42501',
        message = 'Authentication required';
  end if;

  if not editorial.current_user_can_manage_publishing() then
    raise exception
      using
        errcode = '42501',
        message = 'Permission denied';
  end if;

  select item.*
  into v_item
  from editorial.publishing_items item
  where item.id = p_item_id
  for update;

  if not found then
    raise exception 'Publishing item not found';
  end if;

  if v_item.record_version
     <> p_expected_record_version
  then
    raise exception
      'STALE_PUBLISHING_ITEM_VERSION: expected %, current %',
      p_expected_record_version,
      v_item.record_version;
  end if;

  if v_item.resource_id is not null then
    raise exception
      'Publishing item already has a canonical resource';
  end if;

  update editorial.publishing_items item
  set
    resource_id = p_resource_id,
    record_version = item.record_version + 1,
    updated_by = auth.uid(),
    updated_at = now()
  where item.id = p_item_id
  returning item.*
  into v_updated;

  insert into editorial.publishing_item_events (
    item_id,
    action,
    prior_record_version,
    resulting_record_version,
    prior_values,
    resulting_values,
    note,
    actor_id
  )
  values (
    v_updated.id,
    'resource_linked',
    v_item.record_version,
    v_updated.record_version,
    editorial.publishing_item_snapshot(v_item),
    editorial.publishing_item_snapshot(v_updated),
    nullif(btrim(p_note), ''),
    auth.uid()
  );

  item_id := v_updated.id;
  record_version := v_updated.record_version;
  return next;
end;
$$;


ALTER FUNCTION "public"."link_publishing_item_resource"("p_item_id" "uuid", "p_expected_record_version" bigint, "p_resource_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_article_lifecycle_events"("p_article_id" "uuid", "p_limit" integer DEFAULT 50) RETURNS TABLE("id" "uuid", "article_id" "uuid", "version_id" "uuid", "version_number" bigint, "action" "text", "prior_status" "text", "resulting_status" "text", "note" "text", "metadata" "jsonb", "actor_id" "uuid", "actor_label" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_limit integer;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  if p_article_id is null then
    raise exception 'Article id is required';
  end if;

  v_limit := least(greatest(coalesce(p_limit, 50), 1), 100);

  if not exists (
    select 1
    from public.wk_articles article
    where article.id = p_article_id
  ) then
    raise exception 'Article not found';
  end if;

  return query
  select
    event.id::uuid,
    event.article_id::uuid,
    event.version_id::uuid,
    version.version_number::bigint,
    event.action::text,
    event.prior_status::text,
    event.resulting_status::text,
    event.note::text,
    coalesce(event.metadata, '{}'::jsonb)::jsonb,
    event.actor_id::uuid,
    coalesce(actor.email, event.actor_id::text, 'system')::text as actor_label,
    event.created_at::timestamptz
  from editorial.article_lifecycle_events event
  left join editorial.article_versions version
    on version.id = event.version_id
  left join auth.users actor
    on actor.id = event.actor_id
  where event.article_id = p_article_id
  order by event.created_at desc, event.id desc
  limit v_limit;
end;
$$;


ALTER FUNCTION "public"."list_article_lifecycle_events"("p_article_id" "uuid", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."list_article_lifecycle_events"("p_article_id" "uuid", "p_limit" integer) IS 'Lists article lifecycle events for admin review history using exact result type casts.';



CREATE OR REPLACE FUNCTION "public"."list_article_trust_sources"("p_limit" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_source_types jsonb;
  v_sources jsonb;
begin
  if p_limit is null
     or p_limit < 1
     or p_limit > 100 then
    raise exception
      'Source Library limit must be between 1 and 100';
  end if;

  if coalesce(auth.role(), '') <> 'service_role'
     and auth.uid() is null then
    raise exception
      'Not authenticated';
  end if;

  if coalesce(auth.role(), '') <> 'service_role'
     and not (
       coalesce(
         public.current_user_is_administrator(),
         false
       )
       or coalesce(
         public.current_user_has_capability(
           'view_trust_records'
         ),
         false
       )
       or coalesce(
         public.current_user_has_capability(
           'manage_sources'
         ),
         false
       )
       or coalesce(
         public.current_user_has_capability(
           'review_sources'
         ),
         false
       )
       or coalesce(
         public.current_user_has_capability(
           'withdraw_sources'
         ),
         false
       )
     ) then
    raise exception
      'You do not have permission to read the Source Library';
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'source_type',
          source_type.source_type,
        'label',
          source_type.label,
        'description',
          source_type.description,
        'sort_order',
          source_type.sort_order
      )
      order by
        source_type.sort_order,
        source_type.source_type
    ),
    '[]'::jsonb
  )
  into v_source_types
  from editorial.source_types source_type
  where source_type.enabled;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id',
          source_record.id,
        'source_type',
          source_record.source_type,
        'title',
          source_record.title,
        'creator_display',
          source_record.creator_display,
        'publisher_display',
          source_record.publisher_display,
        'source_url',
          source_record.source_url,
        'archive_identifier',
          source_record.archive_identifier,
        'publication_date',
          source_record.publication_date,
        'capture_date',
          source_record.capture_date,
        'retrieval_date',
          source_record.retrieval_date,
        'language_code',
          source_record.language_code,
        'country_code',
          source_record.country_code,
        'place_text',
          source_record.place_text,
        'rights_status',
          source_record.rights_status,
        'consent_status',
          source_record.consent_status,
        'sensitivity',
          source_record.sensitivity,
        'reliability_note',
          source_record.reliability_note,
        'credit_line',
          source_record.credit_line,
        'review_status',
          source_record.review_status,
        'exposure_class',
          source_record.exposure_class,
        'source_state',
          source_record.source_state,
        'current_working_version_id',
          source_record.current_working_version_id,
        'current_submitted_version_id',
          source_record.current_submitted_version_id,
        'current_approved_version_id',
          source_record.current_approved_version_id,
        'working_revision',
          source_record.working_revision,
        'updated_at',
          source_record.updated_at
      )
      order by
        source_record.updated_at desc,
        source_record.id
    ),
    '[]'::jsonb
  )
  into v_sources
  from (
    select
      source.id,
      source.source_type,
      source.title,
      source.creator_display,
      source.publisher_display,
      source.source_url,
      source.archive_identifier,
      source.publication_date,
      source.capture_date,
      source.retrieval_date,
      source.language_code,
      source.country_code,
      source.place_text,
      source.rights_status,
      source.consent_status,
      source.sensitivity,
      source.reliability_note,
      source.credit_line,
      source.review_status,
      source.exposure_class,
      source.source_state,
      source.current_working_version_id,
      source.current_submitted_version_id,
      source.current_approved_version_id,
      source.working_revision,
      source.updated_at
    from editorial.sources source
    order by
      source.updated_at desc,
      source.id
    limit p_limit
  ) source_record;

  return jsonb_build_object(
    'source_types',
      v_source_types,
    'sources',
      v_sources
  );
end;
$$;


ALTER FUNCTION "public"."list_article_trust_sources"("p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."list_article_trust_sources"("p_limit" integer) IS 'Returns a bounded authorized Source Library and enabled Source vocabulary for Article trust workflows.';



CREATE OR REPLACE FUNCTION "public"."list_article_versions"("p_article_id" "uuid", "p_limit" integer DEFAULT 30) RETURNS TABLE("id" "uuid", "revision_number" bigint, "version_kind" "text", "created_at" timestamp with time zone, "created_by" "text", "title" "text", "slug" "text", "content_html" "text", "excerpt" "text", "author" "text", "categories" "jsonb", "tags" "jsonb", "hero_image_url" "text", "seo" "jsonb", "lifecycle_state" "text", "wp_status" "text", "published_at" timestamp with time zone, "content_fingerprint" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_resource_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  if p_article_id is null then
    raise exception 'Article id is required';
  end if;

  select binding.resource_id
  into v_resource_id
  from editorial.article_resources binding
  where binding.article_id = p_article_id;

  if v_resource_id is null then
    raise exception 'Article resource identity not found';
  end if;

  if not editorial.current_user_can_edit_article(v_resource_id) then
    raise exception 'Permission denied';
  end if;

  return query
  select
    version.id::uuid,
    version.version_number::bigint,
    version.version_kind::text,
    version.created_at::timestamptz,
    case
      when version.version_kind = 'autosave'
        then 'autosave'
      when version.created_by is null
        then 'System'
      else version.created_by::text
    end::text as created_by,
    version.title::text,
    version.slug::text,
    version.content_html::text,
    version.excerpt::text,
    version.author_display::text,
    coalesce(version.category_snapshot, '[]'::jsonb)::jsonb,
    coalesce(version.tag_snapshot, '[]'::jsonb)::jsonb,
    version.hero_image_url::text,
    coalesce(version.seo, '{}'::jsonb)::jsonb,
    version.lifecycle_state::text,
    version.wp_status::text,
    version.published_at::timestamptz,
    version.content_fingerprint::text
  from editorial.article_versions version
  where version.resource_id = v_resource_id
  order by version.version_number desc
  limit greatest(1, least(coalesce(p_limit, 30), 100));
end;
$$;


ALTER FUNCTION "public"."list_article_versions"("p_article_id" "uuid", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."list_article_versions"("p_article_id" "uuid", "p_limit" integer) IS 'Lists immutable Article versions for admin revision history, including metadata fields needed for truthful comparison.';



CREATE OR REPLACE FUNCTION "public"."list_correction_case_events"("p_case_resource_id" "uuid", "p_after_event_number" bigint DEFAULT 0, "p_limit" integer DEFAULT 200) RETURNS TABLE("event_id" "uuid", "event_number" bigint, "event_type" "text", "case_revision_before" bigint, "case_revision_after" bigint, "prior_state" "text", "resulting_state" "text", "actor_id" "uuid", "reason" "text", "decision_id" "uuid", "target_id" "uuid", "evidence_link_id" "uuid", "related_resource_review_id" "uuid", "command_receipt_id" "uuid", "correlation_id" "uuid", "metadata" "jsonb", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'editorial'
    AS $$
begin
  if p_case_resource_id is null
     or p_after_event_number < 0
     or p_limit not between 1 and 500
  then
    raise exception
      using
        errcode = '22023',
        message = 'Case, event cursor, and limit are invalid.';
  end if;

  if coalesce(auth.role(), '') <> 'service_role'
     and not coalesce(
       public.current_user_is_administrator(),
       false
     )
     and not coalesce(
       public.current_user_has_capability(
         'view_corrections'
       ),
       false
     )
  then
    raise exception
      using
        errcode = '42501',
        message = 'The caller cannot view correction cases.';
  end if;

  if not exists (
    select 1
    from editorial.correction_cases correction_case
    where correction_case.resource_id =
      p_case_resource_id
  ) then
    raise exception
      using
        errcode = 'P0002',
        message = 'The correction case does not exist.';
  end if;

  return query
  select
    event.id,
    event.event_number,
    event.event_type,
    event.case_revision_before,
    event.case_revision_after,
    event.prior_state,
    event.resulting_state,
    event.actor_id,
    event.reason,
    event.decision_id,
    event.target_id,
    event.evidence_link_id,
    event.related_resource_review_id,
    event.command_receipt_id,
    event.correlation_id,
    event.metadata,
    event.created_at
  from editorial.correction_events event
  where event.case_resource_id =
      p_case_resource_id
    and event.event_number >
      p_after_event_number
  order by event.event_number
  limit p_limit;
end;
$$;


ALTER FUNCTION "public"."list_correction_case_events"("p_case_resource_id" "uuid", "p_after_event_number" bigint, "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."list_correction_case_events"("p_case_resource_id" "uuid", "p_after_event_number" bigint, "p_limit" integer) IS 'Ordered internal correction event history.';



CREATE OR REPLACE FUNCTION "public"."list_correction_cases"("p_case_state" "text" DEFAULT NULL::"text", "p_assigned_investigator_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 100, "p_offset" integer DEFAULT 0) RETURNS TABLE("case_resource_id" "uuid", "case_reference" "text", "origin_type" "text", "correction_kind" "text", "priority" "text", "case_state" "text", "current_revision" bigint, "primary_target_resource_kind" "text", "primary_target_summary" "text", "assigned_investigator_id" "uuid", "current_decision_outcome" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "closed_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'editorial'
    AS $$
begin
  if coalesce(auth.role(), '') <> 'service_role'
     and not coalesce(
       public.current_user_is_administrator(),
       false
     )
     and not coalesce(
       public.current_user_has_capability(
         'view_corrections'
       ),
       false
     )
  then
    raise exception
      using
        errcode = '42501',
        message = 'The caller cannot view correction cases.';
  end if;

  if p_case_state is not null
     and p_case_state not in (
       'submitted',
       'triaged',
       'investigating',
       'awaiting_decision',
       'decided',
       'applied',
       'closed'
     )
  then
    raise exception
      using
        errcode = '22023',
        message = 'case_state is invalid.';
  end if;

  if p_limit not between 1 and 500
     or p_offset < 0
  then
    raise exception
      using
        errcode = '22023',
        message = 'limit must be between 1 and 500 and offset cannot be negative.';
  end if;

  return query
  select
    correction_case.resource_id,
    'COR-' ||
      lpad(
        correction_case.case_number::text,
        8,
        '0'
      ),
    correction_case.origin_type,
    correction_case.correction_kind,
    correction_case.priority,
    correction_case.case_state,
    correction_case.current_revision,
    primary_target.target_resource_kind,
    primary_target.target_summary,
    correction_case.assigned_investigator_id,
    current_decision.outcome,
    correction_case.created_at,
    correction_case.updated_at,
    correction_case.closed_at
  from editorial.correction_cases correction_case
  left join lateral (
    select
      target.target_resource_kind,
      target.target_summary
    from editorial.correction_targets target
    where target.case_resource_id =
      correction_case.resource_id
      and target.target_role = 'primary'
    order by target.created_at, target.id
    limit 1
  ) primary_target on true
  left join editorial.correction_decisions current_decision
    on current_decision.id =
      correction_case.current_decision_id
  where (
      p_case_state is null
      or correction_case.case_state =
        p_case_state
    )
    and (
      p_assigned_investigator_id is null
      or correction_case.assigned_investigator_id =
        p_assigned_investigator_id
    )
  order by
    correction_case.updated_at desc,
    correction_case.resource_id
  limit p_limit
  offset p_offset;
end;
$$;


ALTER FUNCTION "public"."list_correction_cases"("p_case_state" "text", "p_assigned_investigator_id" "uuid", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."list_correction_cases"("p_case_state" "text", "p_assigned_investigator_id" "uuid", "p_limit" integer, "p_offset" integer) IS 'Narrow internal correction queue for callers with correction read authority.';



CREATE OR REPLACE FUNCTION "public"."list_media_assets_v2"("p_search" "text" DEFAULT NULL::"text", "p_asset_kind" "text" DEFAULT NULL::"text", "p_asset_purpose" "text" DEFAULT NULL::"text", "p_lifecycle_state" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS TABLE("asset_id" "uuid", "asset_kind" "text", "asset_purpose" "text", "title" "text", "lifecycle_state" "text", "authority_revision" bigint, "current_revision_id" "uuid", "current_revision_number" bigint, "current_file_object_id" "uuid", "current_file_verification_state" "text", "current_mime_type" "text", "governance_version_id" "uuid", "rights_status" "text", "consent_status" "text", "sensitivity" "text", "public_safety_state" "text", "internal_reason" "text", "legacy_asset_id" "uuid", "active_usage_count" bigint, "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'media', 'auth'
    AS $$
declare
  v_can_review boolean;
begin
  perform media.require_media_read_actor();

  if p_limit < 1 or p_limit > 200 then
    raise exception
      'Media list limit must be between 1 and 200';
  end if;

  if p_offset < 0 then
    raise exception
      'Media list offset cannot be negative';
  end if;

  v_can_review :=
    public.current_user_has_capability(
      'review_media_governance'
    )
    or public.current_user_is_administrator();

  return query
  select
    asset_row.id,
    asset_row.asset_kind,
    asset_row.asset_purpose,
    asset_row.title,
    asset_row.lifecycle_state,
    asset_row.authority_revision,
    asset_row.current_revision_id,
    revision_row.revision_number,
    file_row.id,
    file_row.verification_state,
    file_row.mime_type,
    governance_row.id,
    governance_row.rights_status,
    governance_row.consent_status,
    governance_row.sensitivity,
    governance_row.public_safety_state,
    case
      when v_can_review
        then governance_row.internal_reason
      else null
    end,
    bridge_row.legacy_asset_id,
    coalesce(usage_count.active_count, 0),
    asset_row.created_at,
    asset_row.updated_at
  from media.assets asset_row
  join media.asset_governance_versions governance_row
    on governance_row.id =
      asset_row.current_governance_version_id
  left join media.asset_revisions revision_row
    on revision_row.id =
      asset_row.current_revision_id
  left join media.file_objects file_row
    on file_row.id =
      revision_row.original_file_object_id
  left join media.legacy_asset_links bridge_row
    on bridge_row.asset_id = asset_row.id
  left join lateral (
    select count(*)::bigint as active_count
    from media.usage_links usage_row
    where usage_row.asset_id = asset_row.id
      and usage_row.usage_state = 'active'
  ) usage_count
    on true
  where (
      nullif(btrim(p_search), '') is null
      or asset_row.title ilike
        '%' || btrim(p_search) || '%'
    )
    and (
      p_asset_kind is null
      or asset_row.asset_kind = p_asset_kind
    )
    and (
      p_asset_purpose is null
      or asset_row.asset_purpose =
        p_asset_purpose
    )
    and (
      p_lifecycle_state is null
      or asset_row.lifecycle_state =
        p_lifecycle_state
    )
  order by
    asset_row.updated_at desc,
    asset_row.id
  limit p_limit
  offset p_offset;
end;
$$;


ALTER FUNCTION "public"."list_media_assets_v2"("p_search" "text", "p_asset_kind" "text", "p_asset_purpose" "text", "p_lifecycle_state" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_public_person_community_activity"("p_person_resource_id" "uuid", "p_activity_kind" "text" DEFAULT 'comment'::"text", "p_limit" integer DEFAULT 20) RETURNS TABLE("id" "uuid", "thread_id" "uuid", "parent_id" "uuid", "root_id" "uuid", "author_id" "uuid", "body_markdown" "text", "body_plain" "text", "body_html" "text", "depth" integer, "path" "text", "status" "text", "is_pinned" boolean, "is_editor_pick" boolean, "upvote_count" integer, "downvote_count" integer, "reply_count" integer, "reaction_count" integer, "report_count" integer, "score" integer, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "edited_at" timestamp with time zone, "deleted_at" timestamp with time zone, "thread_title" "text", "thread_entity_type" "text", "thread_entity_id" "text", "thread_entity_slug" "text", "thread_entity_url" "text", "anchor_type" "text", "anchor_time_ms" integer, "anchor_end_time_ms" integer, "anchor_label" "text", "context_entity_type" "text", "context_entity_id" "text", "context_entity_slug" "text", "context_label" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_user_id uuid;
  v_activity_kind text :=
    lower(
      btrim(
        coalesce(
          p_activity_kind,
          ''
        )
      )
    );
begin
  if p_person_resource_id is null then
    raise exception
      'Person is required'
      using errcode = '22023';
  end if;

  if v_activity_kind not in (
    'comment',
    'reply'
  ) then
    raise exception
      'Activity kind must be comment or reply'
      using errcode = '22023';
  end if;

  select link.user_id
  into v_user_id
  from editorial.person_identity_links link
  join editorial.people person
    on person.resource_id =
       link.person_resource_id
  join editorial.resources resource
    on resource.id =
       person.resource_id
   and resource.resource_kind =
       'person'
  join public.user_profiles profile
    on profile.user_id =
       link.user_id
  where link.person_resource_id =
        p_person_resource_id
    and link.link_state =
        'active'
    and link.user_id is not null
    and person.person_state =
        'active'
    and resource.lifecycle_state =
        'active'
    and resource.visibility =
        'public'
    and profile.status =
        'active'
    and profile.is_public
  limit 1;

  if v_user_id is null then
    return;
  end if;

  return query
  select
    comment_row.id,
    comment_row.thread_id,
    comment_row.parent_id,
    comment_row.root_id,
    comment_row.author_id,
    comment_row.body_markdown,
    comment_row.body_plain,
    comment_row.body_html,
    coalesce(
      comment_row.depth,
      0
    )::integer,
    comment_row.path::text,
    comment_row.status::text,
    coalesce(
      comment_row.is_pinned,
      false
    ),
    coalesce(
      comment_row.is_editor_pick,
      false
    ),
    coalesce(
      comment_row.upvote_count,
      0
    )::integer,
    coalesce(
      comment_row.downvote_count,
      0
    )::integer,
    coalesce(
      comment_row.reply_count,
      0
    )::integer,
    coalesce(
      comment_row.reaction_count,
      0
    )::integer,
    coalesce(
      comment_row.report_count,
      0
    )::integer,
    coalesce(
      comment_row.score,
      0
    )::integer,
    comment_row.created_at,
    comment_row.updated_at,
    comment_row.edited_at,
    comment_row.deleted_at,
    thread.title,
    thread.entity_type::text,
    thread.entity_id::text,
    thread.entity_slug,
    thread.entity_url,
    comment_row.anchor_type,
    comment_row.anchor_time_ms,
    comment_row.anchor_end_time_ms,
    comment_row.anchor_label,
    comment_row.context_entity_type,
    comment_row.context_entity_id,
    comment_row.context_entity_slug,
    comment_row.context_label
  from public.community_comments comment_row
  join public.community_threads thread
    on thread.id =
       comment_row.thread_id
  where comment_row.author_id =
        v_user_id
    and (
      (
        v_activity_kind =
        'comment'
        and comment_row.parent_id
            is null
      )
      or
      (
        v_activity_kind =
        'reply'
        and comment_row.parent_id
            is not null
      )
    )
    and comment_row.deleted_at
        is null
    and comment_row.status::text
        not in (
          'deleted',
          'removed',
          'spam'
        )
    and thread.status::text <>
        'hidden'
  order by
    comment_row.created_at desc,
    comment_row.id desc
  limit least(
    greatest(
      coalesce(
        p_limit,
        20
      ),
      1
    ),
    50
  );
end;
$$;


