CREATE OR REPLACE FUNCTION "public"."list_public_person_work"("p_person_resource_id" "uuid", "p_limit" integer DEFAULT 24, "p_before_published_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_before_resource_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("resource_id" "uuid", "resource_kind" "text", "canonical_path" "text", "title" "text", "summary" "text", "image_url" "text", "published_at" timestamp with time zone, "roles" "jsonb", "is_primary" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'editorial'
    AS $$
  select
    work.resource_id,
    work.resource_kind,
    work.canonical_path,
    work.title,
    work.summary,
    work.image_url,
    work.published_at,
    work.roles,
    work.is_primary
  from editorial.list_current_public_person_work(
    p_person_resource_id
  ) work
  where (
    p_before_published_at is null
    or (
      work.published_at,
      work.resource_id
    ) < (
      p_before_published_at,
      coalesce(
        p_before_resource_id,
        'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid
      )
    )
  )
  order by
    work.published_at desc,
    work.resource_id desc
  limit least(
    greatest(
      coalesce(
        p_limit,
        24
      ),
      1
    ),
    50
  );
$$;


ALTER FUNCTION "public"."list_public_person_work"("p_person_resource_id" "uuid", "p_limit" integer, "p_before_published_at" timestamp with time zone, "p_before_resource_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_public_playlists"("p_limit" integer DEFAULT 24, "p_before_published_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_before_snapshot_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("snapshot_id" "uuid", "playlist_id" "uuid", "resource_id" "uuid", "version_id" "uuid", "slug" "text", "title" "text", "description" "text", "curator_label" "text", "cover_url" "text", "cover_alt_text" "text", "item_count" integer, "published_at" timestamp with time zone, "first_published_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'editorial'
    AS $$
  select
    snapshot.id,
    snapshot.playlist_id,
    snapshot.resource_id,
    snapshot.version_id,
    snapshot.slug,
    snapshot.title,
    snapshot.description,
    snapshot.curator_label,
    snapshot.cover_url,
    snapshot.cover_alt_text,
    snapshot.item_count,
    snapshot.published_at,
    snapshot.first_published_at
  from editorial.playlist_publication_snapshots snapshot
  join editorial.playlist_resources binding
    on binding.resource_id = snapshot.resource_id
   and binding.playlist_id = snapshot.playlist_id
   and binding.current_published_version_id =
         snapshot.version_id
  where (
    p_before_published_at is null
    or (
      snapshot.published_at,
      snapshot.id
    ) < (
      p_before_published_at,
      coalesce(
        p_before_snapshot_id,
        'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid
      )
    )
  )
  order by
    snapshot.published_at desc,
    snapshot.id desc
  limit least(
    greatest(coalesce(p_limit, 24), 1),
    50
  );
$$;


ALTER FUNCTION "public"."list_public_playlists"("p_limit" integer, "p_before_published_at" timestamp with time zone, "p_before_snapshot_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_publishing_assignable_users"() RETURNS TABLE("user_id" "uuid", "label" "text", "email" "text", "role_labels" "text"[])
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
begin
  if auth.uid() is null
     or not editorial.current_user_can_manage_publishing()
  then
    raise exception
      using
        errcode = '42501',
        message = 'Permission denied';
  end if;

  return query
  select
    profile.user_id,
    coalesce(
      nullif(btrim(profile.display_name), ''),
      nullif(btrim(profile.email), ''),
      nullif(btrim(profile.username), ''),
      profile.user_id::text
    ) as label,
    profile.email,
    array_agg(
      distinct role_definition.label
      order by role_definition.label
    ) as role_labels
  from public.user_profiles profile
  join public.user_role_assignments assignment
    on assignment.user_id = profile.user_id
  join public.role_definitions role_definition
    on role_definition.role_key =
      assignment.role_key
  where profile.status = 'active'
    and assignment.status = 'active'
    and (
      assignment.expires_at is null
      or assignment.expires_at > now()
    )
    and exists (
      select 1
      from public.role_capabilities capability
      where capability.role_key =
        assignment.role_key
        and capability.capability_key in (
          'manage_publishing',
          'view_dashboard',
          'view_admin_readonly',
          'edit_own_articles'
        )
    )
  group by
    profile.user_id,
    profile.display_name,
    profile.email,
    profile.username
  order by
    lower(
      coalesce(
        nullif(btrim(profile.display_name), ''),
        nullif(btrim(profile.email), ''),
        nullif(btrim(profile.username), ''),
        profile.user_id::text
      )
    ),
    profile.user_id;
end;
$$;


ALTER FUNCTION "public"."list_publishing_assignable_users"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."list_publishing_assignable_users"() IS 'Returns active internal users who may receive operational Publishing assignments.';



CREATE OR REPLACE FUNCTION "public"."list_publishing_item_events"("p_item_id" "uuid", "p_before_created_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_before_event_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 50) RETURNS TABLE("event_id" "uuid", "item_id" "uuid", "action" "text", "prior_record_version" bigint, "resulting_record_version" bigint, "note" "text", "actor_id" "uuid", "actor_label" "text", "created_at" timestamp with time zone, "prior_production_stage" "text", "resulting_production_stage" "text", "prior_planning_state" "text", "resulting_planning_state" "text", "subject_user_id" "uuid", "subject_user_label" "text", "assignment_role" "text", "channel_key" "text", "channel_label" "text", "channel_is_primary" boolean, "previous_primary_channel_key" "text", "previous_primary_channel_label" "text", "resource_id" "uuid", "changed_fields" "text"[])
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
begin
  if auth.uid() is null
     or not editorial.current_user_can_view_publishing_item(
       p_item_id
     )
  then
    raise exception
      using
        errcode = '42501',
        message = 'Permission denied';
  end if;

  if (
    p_before_created_at is null
  ) <> (
    p_before_event_id is null
  ) then
    raise exception
      'Publishing event cursor requires both created_at and event_id';
  end if;

  return query
  with event_page as (
    select
      history.id as event_id,
      history.item_id,
      history.action,
      history.prior_record_version,
      history.resulting_record_version,
      history.note,
      history.actor_id,
      history.created_at,

      nullif(
        history.prior_values
          ->> 'productionStage',
        ''
      ) as prior_production_stage,

      nullif(
        history.resulting_values
          ->> 'productionStage',
        ''
      ) as resulting_production_stage,

      nullif(
        history.prior_values
          ->> 'planningState',
        ''
      ) as prior_planning_state,

      nullif(
        history.resulting_values
          ->> 'planningState',
        ''
      ) as resulting_planning_state,

      case
        when history.action in (
          'assignee_added',
          'assignee_removed'
        )
        then nullif(
          history.metadata ->> 'userId',
          ''
        )::uuid
        else null
      end as subject_user_id,

      case
        when history.action in (
          'assignee_added',
          'assignee_removed'
        )
        then nullif(
          history.metadata
            ->> 'assignmentRole',
          ''
        )
        else null
      end as assignment_role,

      case
        when history.action in (
          'channel_added',
          'channel_removed',
          'channel_primary_changed'
        )
        then nullif(
          history.metadata ->> 'channelKey',
          ''
        )
        else null
      end as channel_key,

      case
        when history.action =
          'channel_added'
          and history.metadata ? 'isPrimary'
        then (
          history.metadata
            ->> 'isPrimary'
        )::boolean
        else null
      end as channel_is_primary,

      case
        when history.action =
          'channel_primary_changed'
        then nullif(
          history.metadata
            ->> 'previousPrimaryChannelKey',
          ''
        )
        else null
      end as previous_primary_channel_key,

      case
        when history.action =
          'resource_linked'
        then nullif(
          history.resulting_values
            ->> 'resourceId',
          ''
        )::uuid
        else null
      end as resource_id,

      case
        when history.action =
          'details_updated'
        then array_remove(
          array[
            case
              when history.prior_values
                     -> 'title'
                   is distinct from
                   history.resulting_values
                     -> 'title'
              then 'title'
            end,
            case
              when history.prior_values
                     -> 'contentKind'
                   is distinct from
                   history.resulting_values
                     -> 'contentKind'
              then 'contentKind'
            end,
            case
              when history.prior_values
                     -> 'brief'
                   is distinct from
                   history.resulting_values
                     -> 'brief'
              then 'brief'
            end,
            case
              when history.prior_values
                     -> 'productionStage'
                   is distinct from
                   history.resulting_values
                     -> 'productionStage'
              then 'productionStage'
            end,
            case
              when history.prior_values
                     -> 'planningState'
                   is distinct from
                   history.resulting_values
                     -> 'planningState'
              then 'planningState'
            end,
            case
              when history.prior_values
                     -> 'priority'
                   is distinct from
                   history.resulting_values
                     -> 'priority'
              then 'priority'
            end,
            case
              when history.prior_values
                     -> 'ownerId'
                   is distinct from
                   history.resulting_values
                     -> 'ownerId'
              then 'ownerId'
            end,
            case
              when history.prior_values
                     -> 'productionDeadline'
                   is distinct from
                   history.resulting_values
                     -> 'productionDeadline'
              then 'productionDeadline'
            end,
            case
              when history.prior_values
                     -> 'plannedPublishAt'
                   is distinct from
                   history.resulting_values
                     -> 'plannedPublishAt'
              then 'plannedPublishAt'
            end,
            case
              when history.prior_values
                     -> 'resourceId'
                   is distinct from
                   history.resulting_values
                     -> 'resourceId'
              then 'resourceId'
            end
          ]::text[],
          null
        )
        else array[]::text[]
      end as changed_fields

    from editorial.publishing_item_events
      history
    where history.item_id = p_item_id
      and (
        p_before_created_at is null
        or (
          history.created_at,
          history.id
        ) < (
          p_before_created_at,
          p_before_event_id
        )
      )
    order by
      history.created_at desc,
      history.id desc
    limit least(
      greatest(
        coalesce(p_limit, 50),
        1
      ),
      100
    )
  )

  select
    event_page.event_id,
    event_page.item_id,
    event_page.action,
    event_page.prior_record_version,
    event_page.resulting_record_version,
    event_page.note,
    event_page.actor_id,

    coalesce(
      nullif(
        btrim(actor_profile.display_name),
        ''
      ),
      nullif(
        btrim(actor_profile.email),
        ''
      ),
      nullif(
        btrim(actor_profile.username),
        ''
      ),
      event_page.actor_id::text,
      'System'
    ) as actor_label,

    event_page.created_at,
    event_page.prior_production_stage,
    event_page.resulting_production_stage,
    event_page.prior_planning_state,
    event_page.resulting_planning_state,
    event_page.subject_user_id,

    coalesce(
      nullif(
        btrim(subject_profile.display_name),
        ''
      ),
      nullif(
        btrim(subject_profile.email),
        ''
      ),
      nullif(
        btrim(subject_profile.username),
        ''
      ),
      event_page.subject_user_id::text
    ) as subject_user_label,

    event_page.assignment_role,
    event_page.channel_key,
    current_channel.label as channel_label,
    event_page.channel_is_primary,
    event_page.previous_primary_channel_key,

    previous_channel.label
      as previous_primary_channel_label,

    event_page.resource_id,
    event_page.changed_fields

  from event_page

  left join public.user_profiles
    actor_profile
    on actor_profile.user_id =
      event_page.actor_id

  left join public.user_profiles
    subject_profile
    on subject_profile.user_id =
      event_page.subject_user_id

  left join editorial.publishing_channels
    current_channel
    on current_channel.channel_key =
      event_page.channel_key

  left join editorial.publishing_channels
    previous_channel
    on previous_channel.channel_key =
      event_page.previous_primary_channel_key

  order by
    event_page.created_at desc,
    event_page.event_id desc;
end;
$$;


ALTER FUNCTION "public"."list_publishing_item_events"("p_item_id" "uuid", "p_before_created_at" timestamp with time zone, "p_before_event_id" "uuid", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."list_publishing_item_events"("p_item_id" "uuid", "p_before_created_at" timestamp with time zone, "p_before_event_id" "uuid", "p_limit" integer) IS 'Returns a bounded, readable, read-only operational history for one authorized Publishing item without exposing raw event snapshots or metadata.';



CREATE OR REPLACE FUNCTION "public"."mark_article_suggestion_stale"("p_suggestion_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS TABLE("suggestion_id" "uuid", "decision_status" "text", "decided_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_suggestion editorial.article_suggestions%rowtype;
  v_thread editorial.article_review_threads%rowtype;
  v_decided_at timestamptz := now();
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  if not editorial.current_user_can_review_article() then
    raise exception 'Permission denied';
  end if;

  select suggestion.*
  into v_suggestion
  from editorial.article_suggestions suggestion
  where suggestion.id = p_suggestion_id
  for update;

  if not found then
    raise exception 'Article suggestion not found';
  end if;

  if v_suggestion.status <> 'open' then
    raise exception 'Only open suggestions can be marked stale';
  end if;

  select thread.*
  into v_thread
  from editorial.article_review_threads thread
  where thread.id = v_suggestion.thread_id
  for update;

  update editorial.article_suggestions
  set
    status = 'stale',
    decided_by = auth.uid(),
    decided_at = v_decided_at,
    decision_note = coalesce(
      nullif(btrim(coalesce(p_note, '')), ''),
      'Suggestion no longer targets the active review state'
    )
  where id = p_suggestion_id;

  update editorial.article_review_threads
  set
    status = 'resolved',
    resolved_by = auth.uid(),
    resolved_at = v_decided_at
  where id = v_thread.id;

  insert into editorial.article_suggestion_events (
    suggestion_id,
    action,
    note
  )
  values (
    p_suggestion_id,
    'marked_stale',
    coalesce(
      nullif(btrim(coalesce(p_note, '')), ''),
      'Suggestion no longer targets the active review state'
    )
  );

  suggestion_id := p_suggestion_id;
  decision_status := 'stale';
  decided_at := v_decided_at;
  return next;
end;
$$;


ALTER FUNCTION "public"."mark_article_suggestion_stale"("p_suggestion_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."merge_people"("p_source_person_resource_id" "uuid", "p_target_person_resource_id" "uuid", "p_expected_source_identity_revision" bigint, "p_expected_target_identity_revision" bigint, "p_reason" "text", "p_idempotency_key" "text", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("command_receipt_id" "uuid", "receipt_status" "text", "source_person_resource_id" "uuid", "target_person_resource_id" "uuid", "source_identity_revision" bigint, "target_identity_revision" bigint, "merge_event_id" "uuid", "result_payload" "jsonb", "idempotent_replay" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'editorial', 'platform_private'
    AS $_$
declare
  v_actor_id uuid;
  v_source editorial.people%rowtype;
  v_target editorial.people%rowtype;
  v_source_prior_revision bigint;
  v_target_prior_revision bigint;
  v_source_user_id uuid;
  v_target_user_id uuid;
  v_source_registry_author_id uuid;
  v_target_registry_author_id uuid;
  v_begin record;
  v_read record;
  v_request jsonb;
  v_result jsonb;
  v_correlation_id uuid;
  v_source_merge_event_id uuid;
  v_target_merge_event_id uuid;
  v_target_path text;
  v_target_slug text;
  v_link editorial.person_identity_links%rowtype;
  v_new_link_id uuid;
  v_follow public.community_follows%rowtype;
  v_existing_target_follow_id uuid;
  v_moved_follow_count integer := 0;
  v_deduplicated_follow_count integer := 0;
begin
  if p_source_person_resource_id is null
     or p_target_person_resource_id is null
     or p_source_person_resource_id =
        p_target_person_resource_id
     or p_expected_source_identity_revision
        is null
     or p_expected_source_identity_revision < 1
     or p_expected_target_identity_revision
        is null
     or p_expected_target_identity_revision < 1
     or nullif(
          btrim(
            coalesce(
              p_reason,
              ''
            )
          ),
          ''
        ) is null
  then
    raise exception
      using
        errcode = '22023',
        message =
          'Distinct source and target People, expected revisions, and reason are required.';
  end if;

  if coalesce(
       auth.role(),
       ''
     ) <> 'authenticated'
     or auth.uid() is null
     or not public.current_user_has_capability(
       'merge_people_identity'
     )
  then
    raise exception
      using
        errcode = '42501',
        message =
          'People merge permission is required.';
  end if;

  v_actor_id :=
    auth.uid();

  if not exists (
    select 1
    from editorial.resources resource
    where resource.id =
          p_source_person_resource_id
  ) then
    raise exception
      using
        errcode = 'P0002',
        message =
          'The source Person Resource does not exist.';
  end if;

  perform person.resource_id
  from editorial.people person
  where person.resource_id in (
    p_source_person_resource_id,
    p_target_person_resource_id
  )
  order by person.resource_id
  for update;

  select person.*
  into v_source
  from editorial.people person
  where person.resource_id =
        p_source_person_resource_id;

  select person.*
  into v_target
  from editorial.people person
  where person.resource_id =
        p_target_person_resource_id;

  v_request :=
    jsonb_build_object(
      'source_person_resource_id',
        p_source_person_resource_id,
      'target_person_resource_id',
        p_target_person_resource_id,
      'expected_source_identity_revision',
        p_expected_source_identity_revision,
      'expected_target_identity_revision',
        p_expected_target_identity_revision,
      'reason',
        p_reason,
      'correlation_id',
        p_correlation_id
    );

  select *
  into v_begin
  from platform_private.begin_authenticated_resource_command(
    'person.merge',
    p_source_person_resource_id,
    p_idempotency_key,
    v_request
  );

  if v_begin.idempotent_replay then
    select *
    into v_read
    from platform_private.read_authenticated_resource_command_result(
      v_begin.command_receipt_id,
      true
    );

    command_receipt_id :=
      v_read.command_receipt_id;
    receipt_status :=
      v_read.receipt_status;
    source_person_resource_id :=
      p_source_person_resource_id;
    target_person_resource_id :=
      p_target_person_resource_id;
    source_identity_revision :=
      nullif(
        v_read.result_payload
          ->> 'source_identity_revision',
        ''
      )::bigint;
    target_identity_revision :=
      nullif(
        v_read.result_payload
          ->> 'target_identity_revision',
        ''
      )::bigint;
    merge_event_id :=
      nullif(
        v_read.result_payload
          ->> 'merge_event_id',
        ''
      )::uuid;
    result_payload :=
      v_read.result_payload;
    idempotent_replay :=
      true;
    return next;
    return;
  end if;

  v_correlation_id :=
    coalesce(
      p_correlation_id,
      gen_random_uuid()
    );

  if v_source.resource_id is null then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'person_merge_source_not_found',
      'The source Person does not exist.',
      jsonb_build_object(
        'source_person_resource_id',
          p_source_person_resource_id,
        'target_person_resource_id',
          p_target_person_resource_id,
        'source_identity_revision',
          null,
        'target_identity_revision',
          case
            when v_target.resource_id is null
              then null
            else v_target.identity_revision
          end
      )
    );

  elsif v_target.resource_id is null then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'person_merge_target_not_found',
      'The target Person does not exist.',
      jsonb_build_object(
        'source_person_resource_id',
          p_source_person_resource_id,
        'target_person_resource_id',
          p_target_person_resource_id,
        'source_identity_revision',
          v_source.identity_revision,
        'target_identity_revision',
          null
      )
    );

  elsif v_source.person_state <> 'active'
        or v_target.person_state <> 'active'
  then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'person_merge_state_invalid',
      'Both source and target People must be active.',
      jsonb_build_object(
        'source_person_resource_id',
          p_source_person_resource_id,
        'target_person_resource_id',
          p_target_person_resource_id,
        'source_identity_revision',
          v_source.identity_revision,
        'target_identity_revision',
          v_target.identity_revision,
        'source_person_state',
          v_source.person_state,
        'target_person_state',
          v_target.person_state
      )
    );

  elsif v_source.identity_revision <>
        p_expected_source_identity_revision
        or v_target.identity_revision <>
           p_expected_target_identity_revision
  then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'person_merge_revision_changed',
      'The source or target Person identity changed before this merge could be applied.',
      jsonb_build_object(
        'source_person_resource_id',
          p_source_person_resource_id,
        'target_person_resource_id',
          p_target_person_resource_id,
        'source_identity_revision',
          v_source.identity_revision,
        'target_identity_revision',
          v_target.identity_revision
      )
    );

  else
    select link.user_id
    into v_source_user_id
    from editorial.person_identity_links link
    where link.person_resource_id =
          p_source_person_resource_id
      and link.link_state = 'active'
      and link.user_id is not null
    limit 1;

    select link.user_id
    into v_target_user_id
    from editorial.person_identity_links link
    where link.person_resource_id =
          p_target_person_resource_id
      and link.link_state = 'active'
      and link.user_id is not null
    limit 1;

    select link.registry_author_id
    into v_source_registry_author_id
    from editorial.person_identity_links link
    where link.person_resource_id =
          p_source_person_resource_id
      and link.link_state = 'active'
      and link.registry_author_id is not null
    limit 1;

    select link.registry_author_id
    into v_target_registry_author_id
    from editorial.person_identity_links link
    where link.person_resource_id =
          p_target_person_resource_id
      and link.link_state = 'active'
      and link.registry_author_id is not null
    limit 1;

    select alias.path
    into v_target_path
    from editorial.resource_aliases alias
    where alias.resource_id =
          p_target_person_resource_id
      and alias.is_canonical
      and alias.retired_at is null;

    if v_source_user_id is not null
       and v_target_user_id is not null
       and v_source_user_id <>
           v_target_user_id
    then
      perform platform_private.reject_resource_command(
        v_begin.command_receipt_id,
        'person_merge_account_conflict',
        'Source and target People have different active account identities.',
        jsonb_build_object(
          'source_person_resource_id',
            p_source_person_resource_id,
          'target_person_resource_id',
            p_target_person_resource_id,
          'source_identity_revision',
            v_source.identity_revision,
          'target_identity_revision',
            v_target.identity_revision
        )
      );

    elsif v_source_registry_author_id is not null
          and v_target_registry_author_id is not null
          and v_source_registry_author_id <>
              v_target_registry_author_id
    then
      perform platform_private.reject_resource_command(
        v_begin.command_receipt_id,
        'person_merge_registry_author_conflict',
        'Source and target People have different active Registry Author identities.',
        jsonb_build_object(
          'source_person_resource_id',
            p_source_person_resource_id,
          'target_person_resource_id',
            p_target_person_resource_id,
          'source_identity_revision',
            v_source.identity_revision,
          'target_identity_revision',
            v_target.identity_revision
        )
      );

    elsif v_target_path is null
          or v_target_path !~ '^/people/[^/]+$'
    then
      perform platform_private.reject_resource_command(
        v_begin.command_receipt_id,
        'person_merge_target_route_invalid',
        'The target Person does not have a valid canonical Person route.',
        jsonb_build_object(
          'source_person_resource_id',
            p_source_person_resource_id,
          'target_person_resource_id',
            p_target_person_resource_id,
          'source_identity_revision',
            v_source.identity_revision,
          'target_identity_revision',
            v_target.identity_revision
        )
      );

    else
      v_target_slug :=
        split_part(
          v_target_path,
          '/',
          3
        );

      v_source_prior_revision :=
        v_source.identity_revision;
      v_target_prior_revision :=
        v_target.identity_revision;

      update editorial.people person
      set
        preferred_identity_link_id =
          null,
        identity_revision =
          person.identity_revision + 1,
        updated_by =
          v_actor_id,
        updated_at =
          now()
      where person.resource_id =
            p_source_person_resource_id
      returning person.*
      into v_source;

      for v_link in
        select link.*
        from editorial.person_identity_links link
        where link.person_resource_id =
              p_source_person_resource_id
          and link.link_state = 'active'
        order by link.id
        for update
      loop
        v_new_link_id :=
          gen_random_uuid();

        update editorial.person_identity_links link
        set
          link_state =
            'superseded',
          superseded_by_link_id =
            v_new_link_id,
          retired_by =
            v_actor_id,
          retired_at =
            now(),
          retired_reason =
            p_reason
        where link.id =
              v_link.id;

        insert into editorial.person_identity_links (
          id,
          person_resource_id,
          person_resource_kind,
          user_id,
          registry_author_id,
          external_contributor_id,
          link_state,
          link_method,
          link_reason,
          supersedes_link_id,
          created_by
        )
        values (
          v_new_link_id,
          p_target_person_resource_id,
          'person',
          v_link.user_id,
          v_link.registry_author_id,
          v_link.external_contributor_id,
          'active',
          'person_merge',
          p_reason,
          v_link.id,
          v_actor_id
        );
      end loop;

      update editorial.people person
      set
        identity_revision =
          person.identity_revision + 1,
        updated_by =
          v_actor_id,
        updated_at =
          now()
      where person.resource_id =
            p_target_person_resource_id
      returning person.*
      into v_target;

      v_source_merge_event_id :=
        gen_random_uuid();
      v_target_merge_event_id :=
        gen_random_uuid();

      insert into editorial.person_identity_events (
        id,
        person_resource_id,
        actor_id,
        event_type,
        related_person_resource_id,
        prior_identity_revision,
        resulting_identity_revision,
        reason,
        correlation_id
      )
      values
        (
          v_source_merge_event_id,
          p_source_person_resource_id,
          v_actor_id,
          'person_merged',
          p_target_person_resource_id,
          v_source_prior_revision,
          v_source.identity_revision,
          p_reason,
          v_correlation_id
        ),
        (
          v_target_merge_event_id,
          p_target_person_resource_id,
          v_actor_id,
          'person_merged',
          p_source_person_resource_id,
          v_target_prior_revision,
          v_target.identity_revision,
          p_reason,
          v_correlation_id
        );

      for v_follow in
        select follow_row.*
        from public.community_follows follow_row
        where follow_row.target_type =
              'person'
          and follow_row.target_id =
              p_source_person_resource_id::text
        order by follow_row.id
        for update
      loop
        v_existing_target_follow_id :=
          null;

        select target_follow.id
        into v_existing_target_follow_id
        from public.community_follows target_follow
        where target_follow.user_id =
              v_follow.user_id
          and target_follow.target_type =
              'person'
          and target_follow.target_id =
              p_target_person_resource_id::text
        for update;

        if v_existing_target_follow_id is not null then
          insert into editorial.person_follow_merge_transfers (
            merge_event_id,
            user_id,
            source_person_resource_id,
            target_person_resource_id,
            source_follow_id,
            target_follow_id,
            transfer_mode,
            source_follow_created_at,
            target_follow_preexisted
          )
          values (
            v_source_merge_event_id,
            v_follow.user_id,
            p_source_person_resource_id,
            p_target_person_resource_id,
            v_follow.id,
            v_existing_target_follow_id,
            'deduplicated',
            v_follow.created_at,
            true
          );

          delete from public.community_follows follow_row
          where follow_row.id =
                v_follow.id;

          v_deduplicated_follow_count :=
            v_deduplicated_follow_count + 1;

        else
          begin
            update public.community_follows follow_row
            set
              target_id =
                p_target_person_resource_id::text,
              target_slug =
                v_target_slug
            where follow_row.id =
                  v_follow.id;

            insert into editorial.person_follow_merge_transfers (
              merge_event_id,
              user_id,
              source_person_resource_id,
              target_person_resource_id,
              source_follow_id,
              target_follow_id,
              transfer_mode,
              source_follow_created_at,
              target_follow_preexisted
            )
            values (
              v_source_merge_event_id,
              v_follow.user_id,
              p_source_person_resource_id,
              p_target_person_resource_id,
              v_follow.id,
              v_follow.id,
              'moved',
              v_follow.created_at,
              false
            );

            v_moved_follow_count :=
              v_moved_follow_count + 1;

          exception
            when unique_violation then
              select target_follow.id
              into v_existing_target_follow_id
              from public.community_follows target_follow
              where target_follow.user_id =
                    v_follow.user_id
                and target_follow.target_type =
                    'person'
                and target_follow.target_id =
                    p_target_person_resource_id::text
              for update;

              if v_existing_target_follow_id is null then
                raise;
              end if;

              insert into editorial.person_follow_merge_transfers (
                merge_event_id,
                user_id,
                source_person_resource_id,
                target_person_resource_id,
                source_follow_id,
                target_follow_id,
                transfer_mode,
                source_follow_created_at,
                target_follow_preexisted
              )
              values (
                v_source_merge_event_id,
                v_follow.user_id,
                p_source_person_resource_id,
                p_target_person_resource_id,
                v_follow.id,
                v_existing_target_follow_id,
                'deduplicated',
                v_follow.created_at,
                true
              );

              delete from public.community_follows follow_row
              where follow_row.id =
                    v_follow.id;

              v_deduplicated_follow_count :=
                v_deduplicated_follow_count + 1;
          end;
        end if;
      end loop;

      update editorial.people person
      set
        person_state =
          'merged',
        merged_into_person_resource_id =
          p_target_person_resource_id,
        updated_by =
          v_actor_id,
        updated_at =
          now()
      where person.resource_id =
            p_source_person_resource_id
      returning person.*
      into v_source;

      perform editorial.refresh_person_visibility(
        p_source_person_resource_id
      );

      perform editorial.refresh_person_visibility(
        p_target_person_resource_id
      );

      v_result :=
        jsonb_build_object(
          'source_person_resource_id',
            p_source_person_resource_id,
          'target_person_resource_id',
            p_target_person_resource_id,
          'source_identity_revision',
            v_source.identity_revision,
          'target_identity_revision',
            v_target.identity_revision,
          'merge_event_id',
            v_source_merge_event_id,
          'moved_follow_count',
            v_moved_follow_count,
          'deduplicated_follow_count',
            v_deduplicated_follow_count,
          'changed',
            true,
          'correlation_id',
            v_correlation_id
        );

      perform platform_private.complete_resource_command(
        v_begin.command_receipt_id,
        v_result
      );
    end if;
  end if;

  select *
  into v_read
  from platform_private.read_authenticated_resource_command_result(
    v_begin.command_receipt_id,
    false
  );

  command_receipt_id :=
    v_read.command_receipt_id;
  receipt_status :=
    v_read.receipt_status;
  source_person_resource_id :=
    p_source_person_resource_id;
  target_person_resource_id :=
    p_target_person_resource_id;
  source_identity_revision :=
    nullif(
      v_read.result_payload
        ->> 'source_identity_revision',
      ''
    )::bigint;
  target_identity_revision :=
    nullif(
      v_read.result_payload
        ->> 'target_identity_revision',
      ''
    )::bigint;
  merge_event_id :=
    nullif(
      v_read.result_payload
        ->> 'merge_event_id',
      ''
    )::uuid;
  result_payload :=
    v_read.result_payload;
  idempotent_replay :=
    false;
  return next;
end;
$_$;


ALTER FUNCTION "public"."merge_people"("p_source_person_resource_id" "uuid", "p_target_person_resource_id" "uuid", "p_expected_source_identity_revision" bigint, "p_expected_target_identity_revision" bigint, "p_reason" "text", "p_idempotency_key" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."merge_registry_relationship_duplicate"("p_survivor_relationship_id" "uuid", "p_duplicate_relationship_id" "uuid", "p_reason" "text") RETURNS "public"."registry_entity_relationships"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$ declare v_survivor public.registry_entity_relationships; v_duplicate public.registry_entity_relationships; v_result public.registry_entity_relationships; v_survivor_source_key text; v_survivor_target_key text; v_duplicate_source_key text; v_duplicate_target_key text; begin if not (auth.role() = 'service_role' or public.current_user_has_capability('manage_registry') or public.current_user_has_capability('manage_review_queue') or public.current_user_is_administrator()) then raise exception 'You do not have permission to merge Registry relationships.'; end if; if p_survivor_relationship_id = p_duplicate_relationship_id then raise exception 'Survivor and duplicate relationships must be different.'; end if; if nullif(btrim(p_reason), '') is null then raise exception 'A merge reason is required.'; end if; select * into v_survivor from public.registry_entity_relationships where id = p_survivor_relationship_id for update; if not found then raise exception 'Survivor relationship not found.'; end if; select * into v_duplicate from public.registry_entity_relationships where id = p_duplicate_relationship_id for update; if not found then raise exception 'Duplicate relationship not found.'; end if; if v_survivor.relationship_status = 'archived' or v_duplicate.relationship_status = 'archived' then raise exception 'Archived relationships cannot be merged.'; end if; v_survivor_source_key := coalesce(v_survivor.source_entity_id::text, concat('slug:', v_survivor.source_slug)); v_survivor_target_key := coalesce(v_survivor.target_entity_id::text, concat('slug:', v_survivor.target_slug)); v_duplicate_source_key := coalesce(v_duplicate.source_entity_id::text, concat('slug:', v_duplicate.source_slug)); v_duplicate_target_key := coalesce(v_duplicate.target_entity_id::text, concat('slug:', v_duplicate.target_slug)); if v_survivor.source_entity_type <> v_duplicate.source_entity_type or v_survivor.target_entity_type <> v_duplicate.target_entity_type or v_survivor_source_key <> v_duplicate_source_key or v_survivor_target_key <> v_duplicate_target_key or v_survivor.relationship_type <> v_duplicate.relationship_type or v_survivor.relationship_role is distinct from v_duplicate.relationship_role then raise exception 'Relationships do not have matching canonical or legacy comparison keys.'; end if; insert into public.registry_relationship_evidence(relationship_id, evidence_id, support_type, note, created_by, created_at) select p_survivor_relationship_id, evidence_id, support_type, note, created_by, created_at from public.registry_relationship_evidence where relationship_id = p_duplicate_relationship_id on conflict (relationship_id, evidence_id, support_type) do nothing; delete from public.registry_relationship_evidence where relationship_id = p_duplicate_relationship_id; update public.registry_entity_relationships set public_safe = false, review_status = case when review_status = 'approved' then 'pending_review' else review_status end, status_reason = btrim(p_reason), updated_by = auth.uid(), updated_at = now() where id = p_survivor_relationship_id returning * into v_result; update public.registry_entity_relationships set relationship_status = 'archived', review_status = 'superseded', public_safe = false, superseded_by_relationship_id = p_survivor_relationship_id, status_reason = btrim(p_reason), reviewed_by = auth.uid(), reviewed_at = now(), updated_by = auth.uid(), updated_at = now() where id = p_duplicate_relationship_id; insert into public.review_decisions(subject_type, subject_id, decision, reason, reviewer_id) values ('relationship', p_duplicate_relationship_id, 'duplicate', btrim(p_reason), auth.uid()), ('relationship', p_survivor_relationship_id, 'needs_more_evidence', btrim(p_reason), auth.uid()); return v_result; end; $$;


ALTER FUNCTION "public"."merge_registry_relationship_duplicate"("p_survivor_relationship_id" "uuid", "p_duplicate_relationship_id" "uuid", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."merge_registry_relationship_duplicate"("p_survivor_relationship_id" "uuid", "p_duplicate_relationship_id" "uuid", "p_reason" "text") IS 'Archives an explicitly identified duplicate relationship, preserves its evidence on the survivor, and records both review decisions.';



CREATE OR REPLACE FUNCTION "public"."move_playlist_pending_registry_intake"("p_playlist_id" "uuid", "p_suggestion_id" "uuid", "p_expected_authority_revision" bigint, "p_direction" "text", "p_idempotency_key" "text", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'auth', 'public', 'editorial', 'platform_private'
    AS $$
declare
  v_playlist public.wk_playlists%rowtype;
  v_resource_id uuid;
  v_suggestion public.registry_provider_track_suggestions%rowtype;
  v_target_item_id uuid;
  v_target_suggestion_id uuid;
  v_target_position integer;
  v_temp_position integer;
  v_direction text := lower(btrim(coalesce(p_direction, '')));
  v_begin record;
  v_read record;
  v_request jsonb;
  v_result jsonb;
  v_changed boolean := false;
  v_correlation_id uuid := coalesce(
    p_correlation_id,
    gen_random_uuid()
  );
begin
  if p_playlist_id is null
     or p_suggestion_id is null
     or p_expected_authority_revision is null
     or p_expected_authority_revision < 1
     or v_direction not in ('up', 'down')
  then
    raise exception
      'Playlist, pending Registry track, expected revision, and move direction are required.';
  end if;

  select playlist.*
  into v_playlist
  from public.wk_playlists playlist
  where playlist.id = p_playlist_id
  for update of playlist;

  select binding.resource_id
  into v_resource_id
  from editorial.playlist_resources binding
  where binding.playlist_id = p_playlist_id;

  if not found then
    raise exception
      using errcode = 'P0002', message = 'Playlist does not exist.';
  end if;

  if not editorial.current_user_can_edit_playlist(v_resource_id) then
    raise exception
      using errcode = '42501', message = 'Playlist edit permission is required.';
  end if;

  v_request := jsonb_build_object(
    'playlist_id', p_playlist_id,
    'suggestion_id', p_suggestion_id,
    'expected_authority_revision', p_expected_authority_revision,
    'direction', v_direction,
    'correlation_id', v_correlation_id
  );

  select *
  into v_begin
  from platform_private.begin_authenticated_resource_command(
    'playlist.items.reorder',
    v_resource_id,
    p_idempotency_key,
    v_request
  );

  if v_begin.idempotent_replay then
    select *
    into v_read
    from platform_private.read_authenticated_resource_command_result(
      v_begin.command_receipt_id,
      true
    );
    return v_read.result_payload;
  end if;

  if v_playlist.authority_revision <> p_expected_authority_revision then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'playlist_revision_changed',
      'The Playlist changed before this pending track could be moved.',
      jsonb_build_object(
        'playlist_id', p_playlist_id,
        'authority_revision', v_playlist.authority_revision
      )
    );
  else
    select suggestion.*
    into v_suggestion
    from public.registry_provider_track_suggestions suggestion
    where suggestion.id = p_suggestion_id
      and suggestion.source_playlist_id = p_playlist_id
      and suggestion.status = 'needs_review'
      and suggestion.source_playlist_item_id is null
      and suggestion.canonical_track_id is null
    for update;

    if not found then
      perform platform_private.reject_resource_command(
        v_begin.command_receipt_id,
        'playlist_pending_registry_intake_missing',
        'That pending Registry track is no longer reorderable in this Playlist.',
        jsonb_build_object(
          'playlist_id', p_playlist_id,
          'authority_revision', v_playlist.authority_revision
        )
      );
    else
      v_target_position :=
        v_suggestion.reserved_position
        + case when v_direction = 'up' then -1 else 1 end;

      if v_target_position > 0 then
        select item.id
        into v_target_item_id
        from public.wk_playlist_items item
        where item.playlist_id = p_playlist_id
          and item.lifecycle_state = 'active'
          and item.position = v_target_position
        for update;

        select suggestion.id
        into v_target_suggestion_id
        from public.registry_provider_track_suggestions suggestion
        where suggestion.source_playlist_id = p_playlist_id
          and suggestion.id <> p_suggestion_id
          and suggestion.status = 'needs_review'
          and suggestion.source_playlist_item_id is null
          and suggestion.canonical_track_id is null
          and suggestion.reserved_position = v_target_position
        for update;

        if v_target_item_id is not null
           and v_target_suggestion_id is not null
        then
          raise exception
            'Playlist position authority is corrupt: two entries occupy the target position.';
        end if;

        if v_target_item_id is not null
           or v_target_suggestion_id is not null
        then
          select greatest(
            coalesce(
              (
                select max(item.position)
                from public.wk_playlist_items item
                where item.playlist_id = p_playlist_id
                  and item.lifecycle_state = 'active'
              ),
              0
            ),
            coalesce(
              (
                select max(suggestion.reserved_position)
                from public.registry_provider_track_suggestions suggestion
                where suggestion.source_playlist_id = p_playlist_id
                  and suggestion.status = 'needs_review'
                  and suggestion.source_playlist_item_id is null
                  and suggestion.canonical_track_id is null
              ),
              0
            )
          ) + 100
          into v_temp_position;

          update public.registry_provider_track_suggestions suggestion
          set reserved_position = v_temp_position
          where suggestion.id = p_suggestion_id;

          if v_target_item_id is not null then
            update public.wk_playlist_items item
            set position = v_suggestion.reserved_position
            where item.id = v_target_item_id;
          else
            update public.registry_provider_track_suggestions suggestion
            set reserved_position = v_suggestion.reserved_position
            where suggestion.id = v_target_suggestion_id;
          end if;

          update public.registry_provider_track_suggestions suggestion
          set reserved_position = v_target_position
          where suggestion.id = p_suggestion_id;

          update public.wk_playlists playlist
          set authority_revision = playlist.authority_revision + 1
          where playlist.id = p_playlist_id
          returning playlist.authority_revision
          into v_playlist.authority_revision;

          v_changed := true;
        end if;
      end if;

      v_result := jsonb_build_object(
        'playlist_id', p_playlist_id,
        'suggestion_id', p_suggestion_id,
        'authority_revision', v_playlist.authority_revision,
        'changed', v_changed,
        'reserved_position',
          case
            when v_changed then v_target_position
            else v_suggestion.reserved_position
          end,
        'correlation_id', v_correlation_id
      );

      perform platform_private.complete_resource_command(
        v_begin.command_receipt_id,
        v_result
      );
    end if;
  end if;

  select *
  into v_read
  from platform_private.read_authenticated_resource_command_result(
    v_begin.command_receipt_id,
    false
  );

  return v_read.result_payload;
end;
$$;


ALTER FUNCTION "public"."move_playlist_pending_registry_intake"("p_playlist_id" "uuid", "p_suggestion_id" "uuid", "p_expected_authority_revision" bigint, "p_direction" "text", "p_idempotency_key" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_registry_relationship_vocabulary"("p_relationship_id" "uuid", "p_relationship_type" "text", "p_relationship_role" "text" DEFAULT NULL::"text", "p_reason" "text" DEFAULT NULL::"text") RETURNS "public"."registry_entity_relationships"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_current public.registry_entity_relationships;
  v_updated public.registry_entity_relationships;
begin
  if not (
    auth.role() = 'service_role'
    or public.current_user_has_capability('manage_registry')
    or public.current_user_has_capability('manage_review_queue')
    or public.current_user_is_administrator()
  ) then
    raise exception 'You do not have permission to normalize Registry relationships.';
  end if;

  if nullif(btrim(p_relationship_type), '') is null then
    raise exception 'A relationship type is required.';
  end if;

  if btrim(p_relationship_type) not in ('features','featured_on','collaboration','popular_track') then
    raise exception 'Unsupported canonical relationship type.';
  end if;

  if nullif(btrim(p_reason), '') is null then
    raise exception 'A normalization reason is required.';
  end if;

  select * into v_current
  from public.registry_entity_relationships
  where id = p_relationship_id
  for update;

  if not found then
    raise exception 'Registry relationship not found.';
  end if;

  if exists (
    select 1
    from public.registry_entity_relationships d
    where d.id <> p_relationship_id
      and d.source_entity_type = v_current.source_entity_type
      and d.target_entity_type = v_current.target_entity_type
      and d.source_entity_id is not distinct from v_current.source_entity_id
      and d.target_entity_id is not distinct from v_current.target_entity_id
      and d.relationship_type = btrim(p_relationship_type)
      and d.relationship_role is not distinct from nullif(btrim(p_relationship_role), '')
      and d.relationship_status <> 'archived'
  ) then
    raise exception 'Normalization would create a duplicate active Registry relationship.';
  end if;

  update public.registry_entity_relationships
  set relationship_type = btrim(p_relationship_type),
      relationship_role = nullif(btrim(p_relationship_role), ''),
      review_status = case when review_status = 'approved' then 'pending_review' else review_status end,
      public_safe = false,
      status_reason = btrim(p_reason),
      updated_by = auth.uid(),
      updated_at = now()
  where id = p_relationship_id
  returning * into v_updated;

  insert into public.review_decisions (
    subject_type,
    subject_id,
    decision,
    reason,
    reviewer_id
  ) values (
    'relationship',
    p_relationship_id,
    'needs_more_evidence',
    btrim(p_reason),
    auth.uid()
  );

  return v_updated;
end;
$$;


ALTER FUNCTION "public"."normalize_registry_relationship_vocabulary"("p_relationship_id" "uuid", "p_relationship_type" "text", "p_relationship_role" "text", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."normalize_registry_relationship_vocabulary"("p_relationship_id" "uuid", "p_relationship_type" "text", "p_relationship_role" "text", "p_reason" "text") IS 'Normalizes one Registry relationship type and role, reopens review where needed, and records the decision.';



CREATE OR REPLACE FUNCTION "public"."promote_artist_split_relationship"("p_staging_record_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  inserted_count integer := 0;
begin
  if not (
    public.current_user_has_capability('manage_review_queue')
    or public.current_user_is_administrator()
  ) then
    raise exception 'Not allowed to promote artist relationships';
  end if;

  insert into public.registry_artist_relationships (
    artist_a_id,
    artist_b_id,
    artist_a_slug,
    artist_b_slug,
    relationship_type,
    relationship_status,
    source_kind,
    source_record_id,
    source_staging_record_id,
    confidence,
    metadata
  )
  select
    artist_a_id,
    artist_b_id,
    artist_a_slug,
    artist_b_slug,
    relationship_type,
    'active',
    source_kind,
    source_record_id,
    staging_record_id,
    1.0,
    jsonb_build_object(
      'composite_source_title', composite_source_title,
      'composite_slug', composite_slug,
      'artist_a_name', artist_a_name,
      'artist_b_name', artist_b_name,
      'promoted_from', 'artist_split_relationship_preview'
    )
  from public.artist_split_relationship_preview
  where staging_record_id = p_staging_record_id
    and readiness = 'ready_to_create_relationship'
  on conflict do nothing;

  get diagnostics inserted_count = row_count;

  update public.artist_review_decisions
  set
    notes = concat_ws(
      E'\n',
      nullif(notes, ''),
      'Promoted split collaboration relationship(s): ' || inserted_count::text
    ),
    updated_at = now()
  where staging_record_id = p_staging_record_id;

  return jsonb_build_object(
    'ok', true,
    'staging_record_id', p_staging_record_id,
    'inserted_relationships', inserted_count
  );
end;
$$;


ALTER FUNCTION "public"."promote_artist_split_relationship"("p_staging_record_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."public_get_article_correction_notes"("p_slug" "text") RETURNS TABLE("article_id" "uuid", "article_resource_id" "uuid", "case_reference" "text", "correction_note_id" "uuid", "challenged_version_id" "uuid", "corrected_version_id" "uuid", "note_text" "text", "note_published_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
begin
  if nullif(
       btrim(p_slug),
       ''
     ) is null
  then
    raise exception
      using
        errcode = '22023',
        message = 'Article slug is required.';
  end if;

  return query
  select
    binding.article_id,
    note.affected_resource_id,
    'COR-' ||
      lpad(
        correction_case.case_number::text,
        8,
        '0'
      ),
    note.id,
    note.challenged_version_id,
    note.corrected_version_id,
    note.note_text,
    note.published_at
  from editorial.correction_public_notes note
  join editorial.correction_cases correction_case
    on correction_case.resource_id =
      note.case_resource_id
   and correction_case.current_application_id =
      note.application_id
   and correction_case.public_note_disposition =
      'published'
  join editorial.article_resources binding
    on binding.resource_id =
      note.affected_resource_id
   and binding.resource_kind = 'article'
  join public.wk_articles article
    on article.id =
      binding.article_id
   and article.slug =
      btrim(p_slug)
  join lateral
    editorial.correction_article_publication_proof(
      note.application_id
    ) proof
    on proof.corrected_version_id =
      note.corrected_version_id
   and proof.affected_resource_id =
      note.affected_resource_id
   and proof.article_id =
      binding.article_id
   and proof.challenged_version_id =
      note.challenged_version_id
  where not exists (
    select 1
    from editorial.correction_public_notes later_note
    where later_note.supersedes_note_id =
      note.id
  )
  order by
    note.published_at,
    note.id;
end;
$$;


ALTER FUNCTION "public"."public_get_article_correction_notes"("p_slug" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."public_get_article_correction_notes"("p_slug" "text") IS 'Returns only the latest public-safe correction note for an Article slug.';



CREATE OR REPLACE FUNCTION "public"."public_get_article_trust"("p_article_slug" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_slug text;
  v_article_id uuid;
  v_resource_id uuid;
  v_published_version_id uuid;
  v_sources jsonb;
  v_credits jsonb;
begin
  v_slug := nullif(btrim(p_article_slug), '');

  if v_slug is null then
    return jsonb_build_object(
      'sources',
        '[]'::jsonb,
      'credits',
        '[]'::jsonb
    );
  end if;

  select
    article.id,
    binding.resource_id,
    resource.current_published_version_id
  into
    v_article_id,
    v_resource_id,
    v_published_version_id
  from public.wk_articles article
  join editorial.article_resources binding
    on binding.article_id = article.id
  join editorial.resources resource
    on resource.id = binding.resource_id
   and resource.resource_kind = 'article'
  where article.slug = v_slug
    and resource.visibility = 'public'
    and resource.lifecycle_state = 'published';

  if not found
     or v_published_version_id is null then
    return jsonb_build_object(
      'sources',
        '[]'::jsonb,
      'credits',
        '[]'::jsonb
    );
  end if;

  if not exists (
    select 1
    from editorial.article_versions version
    where version.id = v_published_version_id
      and version.resource_id = v_resource_id
      and version.article_id = v_article_id
  ) then
    return jsonb_build_object(
      'sources',
        '[]'::jsonb,
      'credits',
        '[]'::jsonb
    );
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_strip_nulls(
        jsonb_build_object(
          'label',
            coalesce(
              nullif(btrim(citation.public_label), ''),
              source_version.title
            ),
          'title',
            source_version.title,
          'creator',
            source_version.creator_display,
          'publisher',
            source_version.publisher_display,
          'url',
            case
              when source.exposure_class = 'public'
                then source_version.source_url
              else null
            end,
          'publication_date',
            source_version.publication_date,
          'retrieval_date',
            source_version.retrieval_date,
          'locator_type',
            citation.locator_type,
          'locator_data',
            case
              when citation.locator_type = 'quotation'
                then null
              else citation.locator_data
            end,
          'purpose',
            attachment.citation_purpose,
          'display_order',
            attachment.display_order
        )
      )
      order by
        attachment.display_order,
        attachment.created_at,
        attachment.id
    ),
    '[]'::jsonb
  )
  into v_sources
  from editorial.resource_citations attachment
  join editorial.citations citation
    on citation.id = attachment.citation_id
  join editorial.sources source
    on source.id = citation.source_id
  join editorial.source_versions source_version
    on source_version.id = citation.source_version_id
  where attachment.resource_id = v_resource_id
    and attachment.resource_kind = 'article'
    and attachment.target_version_type = 'article_version'
    and attachment.target_version_id = v_published_version_id
    and attachment.public_safe
    and citation.public_safe
    and citation.citation_state = 'active'
    and source.source_state = 'active'
    and source.withdrawn_at is null
    and source.exposure_class in (
      'public',
      'public_redacted'
    )
    and source.current_approved_version_id =
      citation.source_version_id;

  select coalesce(
    jsonb_agg(
      jsonb_strip_nulls(
        jsonb_build_object(
          'display_name',
            credit.display_name_snapshot,
          'role',
            coalesce(
              nullif(
                btrim(credit.role_label_snapshot),
                ''
              ),
              credit.credit_role
            ),
          'is_primary',
            attachment.is_primary,
          'registry_author_slug',
            credit.registry_author_slug_snapshot,
          'username',
            credit.user_username_snapshot,
          'display_order',
            attachment.display_order
        )
      )
      order by
        attachment.display_order,
        attachment.created_at,
        attachment.id
    ),
    '[]'::jsonb
  )
  into v_credits
  from editorial.resource_credits attachment
  join editorial.credits credit
    on credit.id = attachment.credit_id
  join editorial.credit_governance governance
    on governance.credit_id = credit.id
  left join editorial.external_contributors contributor
    on contributor.id = credit.external_contributor_id
  where attachment.resource_id = v_resource_id
    and attachment.resource_kind = 'article'
    and attachment.target_version_type = 'article_version'
    and attachment.target_version_id = v_published_version_id
    and attachment.public_safe
    and governance.public_safe
    and governance.credit_state = 'active'
    and (
      credit.external_contributor_id is null
      or (
        contributor.contributor_state = 'active'
        and contributor.public_safe
        and contributor.consent_status in (
          'granted',
          'not_required'
        )
      )
    );

  return jsonb_build_object(
    'sources',
      v_sources,
    'credits',
      v_credits
  );
end;
$$;


ALTER FUNCTION "public"."public_get_article_trust"("p_article_slug" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."public_get_article_trust"("p_article_slug" "text") IS 'Returns only currently eligible public Sources and Credits for the published version of one public Article.';



CREATE OR REPLACE FUNCTION "public"."public_get_articles_by_term"("p_taxonomy" "text", "p_term_name" "text", "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 12) RETURNS TABLE("id" "text", "slug" "text", "title" "text", "excerpt" "text", "author" "text", "published_at" timestamp with time zone, "hero_image_url" "text", "categories" "jsonb", "tags" "jsonb", "total_count" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  WITH matched AS (
    SELECT 
      a.id::text,
      a.slug,
      a.title,
      a.excerpt,
      a.author,
      a.published_at,
      a.hero_image_url,
      a.categories,
      a.tags
    FROM public.wk_articles a
    WHERE a.wp_status = 'publish'
      AND (
        (p_taxonomy = 'category' AND EXISTS (
          SELECT 1 FROM jsonb_array_elements(a.categories) AS cat
          WHERE cat->>'name' = p_term_name
            OR (jsonb_typeof(cat) = 'string' AND cat #>> '{}' = p_term_name)
        ))
        OR
        (p_taxonomy = 'post_tag' AND EXISTS (
          SELECT 1 FROM jsonb_array_elements(a.tags) AS tag
          WHERE tag->>'name' = p_term_name
            OR (jsonb_typeof(tag) = 'string' AND tag #>> '{}' = p_term_name)
        ))
      )
    ORDER BY a.published_at DESC NULLS LAST
  ),
  counted AS (
    SELECT COUNT(*) AS total FROM matched
  )
  SELECT 
    m.id,
    m.slug,
    m.title,
    m.excerpt,
    m.author,
    m.published_at,
    m.hero_image_url,
    m.categories,
    m.tags,
    c.total AS total_count
  FROM matched m
  CROSS JOIN counted c
  LIMIT p_page_size
  OFFSET (p_page - 1) * p_page_size;
$$;


ALTER FUNCTION "public"."public_get_articles_by_term"("p_taxonomy" "text", "p_term_name" "text", "p_page" integer, "p_page_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."public_get_taxonomy_index"("p_taxonomy" "text") RETURNS TABLE("id" "uuid", "slug" "text", "name" "text", "description" "text", "seo_title" "text", "seo_description" "text", "seo_keywords" "text", "article_count" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT 
    t.id,
    t.slug,
    t.name,
    t.description,
    t.metadata->>'seo_title' AS seo_title,
    t.metadata->>'seo_description' AS seo_description,
    t.metadata->>'seo_keywords' AS seo_keywords,
    COALESCE(
      (SELECT COUNT(*) FROM public.wk_articles a 
       WHERE a.wp_status = 'publish'
         AND (
           (p_taxonomy = 'category' AND EXISTS (
             SELECT 1 FROM jsonb_array_elements(a.categories) AS cat 
             WHERE cat->>'name' = t.name
               OR (jsonb_typeof(cat) = 'string' AND cat #>> '{}' = t.name)
           ))
           OR
           (p_taxonomy = 'post_tag' AND EXISTS (
             SELECT 1 FROM jsonb_array_elements(a.tags) AS tag 
             WHERE tag->>'name' = t.name
               OR (jsonb_typeof(tag) = 'string' AND tag #>> '{}' = t.name)
           ))
         )
      ),
      0
    ) AS article_count
  FROM public.registry_taxonomy_terms t
  WHERE t.taxonomy = p_taxonomy
    AND t.status = 'active'
  ORDER BY article_count DESC, t.name ASC;
$$;


ALTER FUNCTION "public"."public_get_taxonomy_index"("p_taxonomy" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."public_get_taxonomy_index"("p_taxonomy" "text", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS TABLE("id" "uuid", "slug" "text", "name" "text", "description" "text", "seo_title" "text", "seo_description" "text", "seo_keywords" "text", "article_count" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT
    t.id,
    t.slug,
    t.name,
    t.description,
    t.metadata->>'seo_title' AS seo_title,
    t.metadata->>'seo_description' AS seo_description,
    t.metadata->>'seo_keywords' AS seo_keywords,
    COUNT(DISTINCT articles.id) AS article_count
  FROM public.registry_taxonomy_terms t
  LEFT JOIN public.wk_articles articles ON articles.wp_status = 'publish'
    AND (
      (
        p_taxonomy = 'category'
        AND EXISTS (
          SELECT 1 FROM jsonb_array_elements(articles.categories) AS elem
          WHERE elem->>'name' = t.name
            OR (jsonb_typeof(elem) = 'string' AND elem #>> '{}' = t.name)
        )
      )
      OR (
        p_taxonomy = 'post_tag'
        AND EXISTS (
          SELECT 1 FROM jsonb_array_elements(articles.tags) AS elem
          WHERE elem->>'name' = t.name
            OR (jsonb_typeof(elem) = 'string' AND elem #>> '{}' = t.name)
        )
      )
    )
  WHERE t.taxonomy = p_taxonomy
    AND t.status = 'active'
  GROUP BY t.id, t.slug, t.name, t.description, t.metadata
  ORDER BY article_count DESC, t.name ASC
  LIMIT CASE WHEN p_limit > 0 THEN p_limit END
  OFFSET p_offset;
$$;


ALTER FUNCTION "public"."public_get_taxonomy_index"("p_taxonomy" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."public_get_taxonomy_term"("p_taxonomy" "text", "p_slug" "text") RETURNS TABLE("id" "uuid", "slug" "text", "name" "text", "description" "text", "seo_title" "text", "seo_description" "text", "seo_keywords" "text", "article_count" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    AS $$
  SELECT 
    t.id,
    t.slug,
    t.name,
    t.description,
    t.metadata->>'seo_title' AS seo_title,
    t.metadata->>'seo_description' AS seo_description,
    t.metadata->>'seo_keywords' AS seo_keywords,
    COALESCE(
      (SELECT COUNT(*) FROM public.wk_articles a 
       WHERE 
         CASE 
           WHEN p_taxonomy = 'category' THEN a.categories ? t.name
           WHEN p_taxonomy = 'post_tag' THEN a.tags ? t.name
           ELSE false
         END
      ),
      0
    ) AS article_count
  FROM public.registry_taxonomy_terms t
  WHERE t.taxonomy = p_taxonomy AND t.slug = p_slug
    AND t.status = 'active'
  LIMIT 1;
$$;


ALTER FUNCTION "public"."public_get_taxonomy_term"("p_taxonomy" "text", "p_slug" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."publish_article_version"("p_article_id" "uuid", "p_version_id" "uuid" DEFAULT NULL::"uuid", "p_published_at" timestamp with time zone DEFAULT "now"(), "p_note" "text" DEFAULT NULL::"text") RETURNS TABLE("article_id" "uuid", "article_slug" "text", "draft_version" bigint, "version_id" "uuid", "version_number" bigint, "lifecycle_status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_article public.wk_articles%rowtype;
  v_resource editorial.resources%rowtype;
  v_source_version_id uuid;
  v_version_id uuid;
  v_version_number bigint;
  v_prior_status text;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  if not editorial.current_user_can_publish_article() then
    raise exception 'Permission denied';
  end if;

  select article.*
  into v_article
  from public.wk_articles article
  where article.id = p_article_id
  for update;

  if not found then
    raise exception 'Article not found';
  end if;

  select resource.*
  into v_resource
  from editorial.article_resources binding
  join editorial.resources resource
    on resource.id = binding.resource_id
  where binding.article_id = p_article_id
  for update of resource;

  if not found then
    raise exception 'Article resource identity not found';
  end if;

  v_source_version_id := coalesce(p_version_id, v_resource.current_approved_version_id);

  if v_source_version_id is null then
    raise exception 'Article must be approved before publication';
  end if;

  if v_resource.current_approved_version_id is null
    or v_source_version_id <> v_resource.current_approved_version_id
  then
    raise exception 'Only the approved article version can be published';
  end if;

  perform 1
  from editorial.article_versions version
  where version.id = v_source_version_id
    and version.article_id = p_article_id
    and version.version_kind = 'approved';

  if not found then
    raise exception 'Only an approved article version can be published';
  end if;

  v_prior_status := v_article.wp_status;

  select copied.version_id, copied.version_number
  into v_version_id, v_version_number
  from editorial.copy_article_lifecycle_version(
    v_source_version_id,
    'published',
    'published',
    'publish',
    p_published_at
  ) copied;

  perform editorial.publish_article_snapshot(
    v_version_id,
    p_published_at,
    true
  );

  update public.wk_articles as article
  set
    wp_status = 'publish',
    published_at = p_published_at,
    updated_at = now()
  where article.id = p_article_id
  returning article.*
  into v_article;

  update editorial.resources
  set
    current_published_version_id = v_version_id,
    lifecycle_state = 'published',
    visibility = 'public',
    updated_at = now()
  where id = v_resource.id;

  insert into editorial.article_lifecycle_events (
    resource_id,
    article_id,
    version_id,
    action,
    prior_status,
    resulting_status,
    note
  )
  values (
    v_resource.id,
    p_article_id,
    v_version_id,
    'published',
    v_prior_status,
    'publish',
    p_note
  );

  article_id := p_article_id;
  article_slug := v_article.slug;
  draft_version := v_article.draft_version;
  version_id := v_version_id;
  version_number := v_version_number;
  lifecycle_status := 'published';
  return next;
end;
$$;


ALTER FUNCTION "public"."publish_article_version"("p_article_id" "uuid", "p_version_id" "uuid", "p_published_at" timestamp with time zone, "p_note" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."publish_article_version"("p_article_id" "uuid", "p_version_id" "uuid", "p_published_at" timestamp with time zone, "p_note" "text") IS 'Publishes the approved article version.';



CREATE OR REPLACE FUNCTION "public"."publish_correction_note"("p_case_resource_id" "uuid", "p_expected_case_revision" bigint, "p_expected_current_application_id" "uuid", "p_expected_current_published_article_version_id" "uuid", "p_note_text" "text", "p_supersedes_note_id" "uuid", "p_contributor_follow_up_disposition" "text", "p_contributor_follow_up_reason" "text", "p_idempotency_key" "text", "p_correlation_id" "uuid") RETURNS TABLE("command_receipt_id" "uuid", "receipt_status" "text", "case_resource_id" "uuid", "case_revision" bigint, "result_payload" "jsonb", "idempotent_replay" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'editorial', 'platform_private'
    AS $$
declare
  v_actor uuid;
  v_context record;
  v_begin record;
  v_case editorial.correction_cases%rowtype;
  v_application editorial.correction_applications%rowtype;
  v_decision_outcome text;
  v_proof record;
  v_current_note editorial.correction_public_notes%rowtype;
  v_note_id uuid;
  v_note_fingerprint text;
  v_child_receipt_id uuid;
  v_contributor_job_id uuid;
  v_result jsonb;
  v_rejection_code text;
  v_rejection_message text;
  v_new_revision bigint;
begin
  v_actor :=
    platform_private.assert_correction_capability(
      'publish_correction_notes'
    );

  select *
  into v_context
  from platform_private.correction_actor_context();

  if v_context.auth_role <> 'service_role'
     and not coalesce(
       public.current_user_is_administrator(),
       false
     )
     and not coalesce(
       public.current_user_has_capability(
         'publish_articles'
       ),
       false
     )
  then
    raise exception
      using
        errcode = '42501',
        message = 'The caller does not hold Article publication authority.';
  end if;

  if p_case_resource_id is null
     or p_expected_case_revision < 1
     or p_expected_current_application_id is null
     or p_expected_current_published_article_version_id is null
     or p_correlation_id is null
     or nullif(
       btrim(p_note_text),
       ''
     ) is null
     or length(p_note_text) > 8000
  then
    raise exception
      using
        errcode = '22023',
        message = 'Case, revision, application, published version, bounded public note, and correlation identity are required.';
  end if;

  if p_contributor_follow_up_disposition is not null
     and p_contributor_follow_up_disposition not in (
       'requested',
       'unavailable',
       'unsafe'
     )
  then
    raise exception
      using
        errcode = '22023',
        message = 'Contributor follow-up disposition is invalid.';
  end if;

  if p_contributor_follow_up_disposition = 'requested'
     and p_contributor_follow_up_reason is not null
  then
    raise exception
      using
        errcode = '22023',
        message = 'Requested contributor follow-up cannot use an exception reason.';
  end if;

  if p_contributor_follow_up_disposition in (
       'unavailable',
       'unsafe'
     )
     and (
       nullif(
         btrim(p_contributor_follow_up_reason),
         ''
       ) is null
       or length(
         p_contributor_follow_up_reason
       ) > 2000
     )
  then
    raise exception
      using
        errcode = '22023',
        message = 'Contributor follow-up exception requires a bounded reason.';
  end if;

  select *
  into v_begin
  from platform_private.begin_resource_command(
    'correction.note.publish',
    p_case_resource_id,
    p_idempotency_key,
    jsonb_build_object(
      'expected_case_revision',
      p_expected_case_revision,
      'expected_current_application_id',
      p_expected_current_application_id,
      'expected_current_published_article_version_id',
      p_expected_current_published_article_version_id,
      'note_text',
      btrim(p_note_text),
      'supersedes_note_id',
      p_supersedes_note_id,
      'contributor_follow_up_disposition',
      p_contributor_follow_up_disposition,
      'contributor_follow_up_reason',
      p_contributor_follow_up_reason,
      'correlation_id',
      p_correlation_id
    )
  );

  if v_begin.idempotent_replay then
    return query
    select *
    from platform_private.read_correction_command_result(
      v_begin.command_receipt_id,
      true
    );
    return;
  end if;

  select correction_case.*
  into v_case
  from editorial.correction_cases correction_case
  where correction_case.resource_id =
    p_case_resource_id
  for update;

  if not found then
    v_rejection_code := 'case_not_found';
    v_rejection_message :=
      'The correction case does not exist.';
  elsif v_case.current_revision <>
        p_expected_case_revision
  then
    v_rejection_code :=
      'case_revision_changed';
    v_rejection_message :=
      'The correction case revision changed.';
  elsif v_case.case_state <> 'applied'
        or v_case.current_application_id
          is distinct from
            p_expected_current_application_id
  then
    v_rejection_code :=
      'application_changed';
    v_rejection_message :=
      'The correction case is not in the expected applied state.';
  end if;

  if v_rejection_code is null then
    select application.*
    into v_application
    from editorial.correction_applications application
    where application.id =
        p_expected_current_application_id
      and application.case_resource_id =
        p_case_resource_id;

    if not found then
      v_rejection_code :=
        'application_changed';
      v_rejection_message :=
        'The current correction application changed.';
    end if;
  end if;

  if v_rejection_code is null then
    select decision.outcome
    into v_decision_outcome
    from editorial.correction_decisions decision
    where decision.id =
        v_application.decision_id
      and decision.case_resource_id =
        p_case_resource_id;

    if not found
       or v_decision_outcome <>
         'correction_required'
       or v_case.current_decision_id
         is distinct from
           v_application.decision_id
    then
      v_rejection_code :=
        'decision_changed';
      v_rejection_message :=
        'The current correction-required decision changed.';
    end if;
  end if;

  if v_rejection_code is null then
    select *
    into v_proof
    from editorial.correction_article_publication_proof(
      p_expected_current_application_id
    );

    if not found
       or v_proof.corrected_version_id
         is distinct from
           p_expected_current_published_article_version_id
    then
      v_rejection_code :=
        'publication_proof_missing';
      v_rejection_message :=
        'The corrected Article publication proof changed or is incomplete.';
    end if;
  end if;

  if v_rejection_code is null then
    select note.*
    into v_current_note
    from editorial.correction_public_notes note
    where note.case_resource_id =
        p_case_resource_id
      and note.application_id =
        p_expected_current_application_id
      and not exists (
        select 1
        from editorial.correction_public_notes later_note
        where later_note.supersedes_note_id =
          note.id
      )
    order by
      note.published_at desc,
      note.id desc
    limit 1;

    if p_supersedes_note_id is null
       and found
    then
      v_rejection_code :=
        'supersedes_note_required';
      v_rejection_message :=
        'A later public note must supersede the current note explicitly.';
    elsif p_supersedes_note_id is not null
          and (
            not found
            or v_current_note.id
              is distinct from
                p_supersedes_note_id
          )
    then
      v_rejection_code :=
        'superseded_note_changed';
      v_rejection_message :=
        'The current public note changed.';
    end if;
  end if;

  if v_rejection_code is null then
    if v_case.origin_type =
       'internal_editorial'
    then
      if p_contributor_follow_up_disposition is not null
         or p_contributor_follow_up_reason is not null
      then
        v_rejection_code :=
          'contributor_follow_up_not_applicable';
        v_rejection_message :=
          'Internal correction cases cannot request contributor follow-up.';
      end if;
    elsif v_case.origin_type =
          'community_contribution'
    then
      if p_contributor_follow_up_disposition is null then
        v_rejection_code :=
          'contributor_follow_up_required';
        v_rejection_message :=
          'Community-origin correction notes require contributor follow-up disposition.';
      elsif p_contributor_follow_up_disposition = 'requested' then
        if p_contributor_follow_up_reason is not null then
          v_rejection_code :=
            'contributor_follow_up_invalid';
          v_rejection_message :=
            'Requested contributor follow-up cannot include an exception reason.';
        end if;
      elsif nullif(
              btrim(
                p_contributor_follow_up_reason
              ),
              ''
            ) is null
            or length(
              p_contributor_follow_up_reason
            ) > 2000
      then
        v_rejection_code :=
          'contributor_follow_up_invalid';
        v_rejection_message :=
          'Contributor follow-up exception requires a bounded reason.';
      end if;
    end if;
  end if;

  if v_rejection_code is null then
    v_note_fingerprint :=
      editorial.correction_public_note_fingerprint(
        p_case_resource_id,
        p_expected_current_application_id,
        v_application.target_resource_id,
        v_application.challenged_version_id,
        p_expected_current_published_article_version_id,
        btrim(p_note_text)
      );

    if exists (
      select 1
      from editorial.correction_public_notes note
      where note.case_resource_id =
          p_case_resource_id
        and note.affected_resource_id =
          v_application.target_resource_id
        and note.corrected_version_id =
          p_expected_current_published_article_version_id
        and note.note_fingerprint =
          v_note_fingerprint
    ) then
      v_rejection_code :=
        'note_already_published';
      v_rejection_message :=
        'The same public correction note already exists.';
    end if;
  end if;

  if v_rejection_code is not null then
    v_result := jsonb_build_object(
      'case_resource_id',
      p_case_resource_id,
      'case_revision',
      v_case.current_revision,
      'case_state',
      v_case.case_state,
      'rejection_code',
      v_rejection_code
    );

    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      v_rejection_code,
      v_rejection_message,
      v_result
    );

    return query
    select *
    from platform_private.read_correction_command_result(
      v_begin.command_receipt_id,
      false
    );
    return;
  end if;

  insert into editorial.correction_public_notes (
    case_resource_id,
    application_id,
    affected_resource_id,
    affected_resource_kind,
    challenged_version_id,
    corrected_version_id,
    note_text,
    note_fingerprint,
    supersedes_note_id,
    published_by
  )
  values (
    p_case_resource_id,
    p_expected_current_application_id,
    v_application.target_resource_id,
    'article',
    v_application.challenged_version_id,
    p_expected_current_published_article_version_id,
    btrim(p_note_text),
    v_note_fingerprint,
    p_supersedes_note_id,
    v_actor
  )
  returning id
  into v_note_id;

  v_new_revision :=
    v_case.current_revision + 1;

  update editorial.correction_cases
  set
    current_revision =
      v_new_revision,
    public_note_disposition =
      'published',
    public_note_no_note_reason =
      null,
    contributor_follow_up_disposition =
      case
        when origin_type =
          'community_contribution'
          and p_contributor_follow_up_disposition in (
            'unavailable',
            'unsafe'
          )
        then p_contributor_follow_up_disposition
        when origin_type =
          'internal_editorial'
        then null
        else contributor_follow_up_disposition
      end,
    contributor_follow_up_reason =
      case
        when origin_type =
          'community_contribution'
          and p_contributor_follow_up_disposition in (
            'unavailable',
            'unsafe'
          )
        then btrim(
          p_contributor_follow_up_reason
        )
        when origin_type =
          'internal_editorial'
        then null
        else contributor_follow_up_reason
      end,
    contributor_follow_up_job_id =
      case
        when origin_type =
          'community_contribution'
          and p_contributor_follow_up_disposition in (
            'unavailable',
            'unsafe'
          )
        then null
        when origin_type =
          'internal_editorial'
        then null
        else contributor_follow_up_job_id
      end,
    contributor_follow_up_requested_at =
      case
        when origin_type =
          'community_contribution'
          and p_contributor_follow_up_disposition in (
            'unavailable',
            'unsafe'
          )
        then null
        when origin_type =
          'internal_editorial'
        then null
        else contributor_follow_up_requested_at
      end,
    updated_by = v_actor,
    updated_at = now()
  where resource_id =
    p_case_resource_id;

  if p_supersedes_note_id is not null then
    perform platform_private.append_correction_public_event(
      p_case_resource_id,
      'public_note_superseded',
      v_case.current_revision,
      v_new_revision,
      v_case.case_state,
      v_case.case_state,
      v_actor,
      'A later public-safe correction note superseded the prior note.',
      v_case.current_decision_id,
      p_expected_current_application_id,
      v_application.target_id,
      p_supersedes_note_id,
      v_begin.command_receipt_id,
      p_correlation_id,
      jsonb_build_object(
        'superseded_note_id',
        p_supersedes_note_id,
        'superseding_note_id',
        v_note_id,
        'corrected_version_id',
        p_expected_current_published_article_version_id
      )
    );
  end if;

  perform platform_private.append_correction_public_event(
    p_case_resource_id,
    'public_note_published',
    v_case.current_revision,
    v_new_revision,
    v_case.case_state,
    v_case.case_state,
    v_actor,
    btrim(p_note_text),
    v_case.current_decision_id,
    p_expected_current_application_id,
    v_application.target_id,
    v_note_id,
    v_begin.command_receipt_id,
    p_correlation_id,
    jsonb_build_object(
      'public_note_id',
      v_note_id,
      'supersedes_note_id',
      p_supersedes_note_id,
      'affected_resource_id',
      v_application.target_resource_id,
      'challenged_version_id',
      v_application.challenged_version_id,
      'corrected_version_id',
      p_expected_current_published_article_version_id,
      'note_fingerprint',
      v_note_fingerprint
    )
  );

  if v_case.origin_type =
       'community_contribution'
     and p_contributor_follow_up_disposition =
       'requested'
  then
    select
      notification.child_command_receipt_id,
      notification.contributor_job_id
    into
      v_child_receipt_id,
      v_contributor_job_id
    from platform_private.request_correction_contributor_notification(
      p_case_resource_id,
      v_case.origin_contribution_id,
      v_case.origin_submitter_user_id,
      v_case.current_decision_id,
      p_expected_current_application_id,
      v_note_id,
      'correction_published',
      'The submitted correction was applied and the corrected Article was published.',
      v_begin.command_receipt_id,
      v_actor,
      v_new_revision,
      v_case.case_state,
      p_correlation_id
    ) notification;

    update editorial.correction_cases
    set
      contributor_follow_up_disposition =
        'requested',
      contributor_follow_up_reason =
        null,
      contributor_follow_up_job_id =
        v_contributor_job_id,
      contributor_follow_up_requested_at =
        now(),
      updated_by = v_actor,
      updated_at = now()
    where resource_id =
      p_case_resource_id;
  end if;

  v_result := jsonb_build_object(
    'case_resource_id',
    p_case_resource_id,
    'case_revision',
    v_new_revision,
    'case_state',
    v_case.case_state,
    'public_note_id',
    v_note_id,
    'supersedes_note_id',
    p_supersedes_note_id,
    'application_id',
    p_expected_current_application_id,
    'affected_resource_id',
    v_application.target_resource_id,
    'challenged_version_id',
    v_application.challenged_version_id,
    'corrected_version_id',
    p_expected_current_published_article_version_id,
    'note_fingerprint',
    v_note_fingerprint,
    'contributor_follow_up_disposition',
    p_contributor_follow_up_disposition,
    'contributor_follow_up_job_id',
    v_contributor_job_id,
    'contributor_follow_up_command_receipt_id',
    v_child_receipt_id
  );

  perform platform_private.complete_resource_command(
    v_begin.command_receipt_id,
    v_result
  );

  return query
  select *
  from platform_private.read_correction_command_result(
    v_begin.command_receipt_id,
    false
  );
end;
$$;


ALTER FUNCTION "public"."publish_correction_note"("p_case_resource_id" "uuid", "p_expected_case_revision" bigint, "p_expected_current_application_id" "uuid", "p_expected_current_published_article_version_id" "uuid", "p_note_text" "text", "p_supersedes_note_id" "uuid", "p_contributor_follow_up_disposition" "text", "p_contributor_follow_up_reason" "text", "p_idempotency_key" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."publish_correction_note"("p_case_resource_id" "uuid", "p_expected_case_revision" bigint, "p_expected_current_application_id" "uuid", "p_expected_current_published_article_version_id" "uuid", "p_note_text" "text", "p_supersedes_note_id" "uuid", "p_contributor_follow_up_disposition" "text", "p_contributor_follow_up_reason" "text", "p_idempotency_key" "text", "p_correlation_id" "uuid") IS 'Publishes one immutable public-safe correction note after exact application and normal Article publication proof.';



CREATE OR REPLACE FUNCTION "public"."publish_due_article_publications"("p_limit" integer DEFAULT 25) RETURNS TABLE("article_id" "uuid", "article_slug" "text", "schedule_id" "uuid", "version_id" "uuid", "published_at" timestamp with time zone, "status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  due_schedule editorial.article_scheduled_publications%rowtype;
  v_article public.wk_articles%rowtype;
  v_resource editorial.resources%rowtype;
  v_version_id uuid;
  v_version_number bigint;
  v_limit integer;
begin
  if auth.role() <> 'service_role'
     and not editorial.current_user_can_publish_article()
  then
    raise exception 'Permission denied';
  end if;

  v_limit := least(greatest(coalesce(p_limit, 25), 1), 100);

  for due_schedule in
    select scheduled.*
    from editorial.article_scheduled_publications scheduled
    where scheduled.status = 'scheduled'
      and scheduled.run_after <= now()
    order by scheduled.run_after asc
    limit v_limit
    for update skip locked
  loop
    select article.*
    into v_article
    from public.wk_articles article
    where article.id = due_schedule.article_id
    for update;

    if not found then
      update editorial.article_scheduled_publications
      set
        status = 'failed',
        updated_at = now()
      where id = due_schedule.id;

      continue;
    end if;

    select resource.*
    into v_resource
    from editorial.resources resource
    where resource.id = due_schedule.resource_id
    for update;

    if not found then
      update editorial.article_scheduled_publications
      set
        status = 'failed',
        updated_at = now()
      where id = due_schedule.id;

      continue;
    end if;

    select copied.version_id, copied.version_number
    into v_version_id, v_version_number
    from editorial.copy_article_lifecycle_version(
      due_schedule.version_id,
      'published',
      'published',
      'publish',
      due_schedule.run_after
    ) copied;

    perform editorial.publish_article_snapshot(
      v_version_id,
      due_schedule.run_after,
      true
    );

    update public.wk_articles as article
    set
      wp_status = 'publish',
      published_at = due_schedule.run_after,
      updated_at = now()
    where article.id = due_schedule.article_id
    returning article.*
    into v_article;

    update editorial.resources
    set
      current_published_version_id = v_version_id,
      lifecycle_state = 'published',
      visibility = 'public',
      updated_at = now()
    where id = due_schedule.resource_id;

    update editorial.article_scheduled_publications
    set
      status = 'published',
      updated_at = now()
    where id = due_schedule.id;

    insert into editorial.article_lifecycle_events (
      resource_id,
      article_id,
      version_id,
      action,
      prior_status,
      resulting_status,
      note,
      metadata
    )
    values (
      due_schedule.resource_id,
      due_schedule.article_id,
      v_version_id,
      'published',
      'future',
      'publish',
      due_schedule.note,
      jsonb_build_object(
        'scheduledPublicationId',
        due_schedule.id,
        'scheduledFor',
        due_schedule.run_after
      )
    );

    article_id := due_schedule.article_id;
    article_slug := v_article.slug;
    schedule_id := due_schedule.id;
    version_id := v_version_id;
    published_at := due_schedule.run_after;
    status := 'published';
    return next;
  end loop;
end;
$$;


ALTER FUNCTION "public"."publish_due_article_publications"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."publish_due_playlist_publications"("p_limit" integer DEFAULT 25) RETURNS TABLE("playlist_id" "uuid", "playlist_slug" "text", "schedule_id" "uuid", "version_id" "uuid", "published_at" timestamp with time zone, "status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'editorial'
    AS $$
declare
  due_schedule
    editorial.playlist_scheduled_publications%rowtype;
  v_playlist public.wk_playlists%rowtype;
  v_binding editorial.playlist_resources%rowtype;
  v_scheduled editorial.playlist_versions%rowtype;
  v_published record;
  v_snapshot_id uuid;
  v_limit integer;
begin
  if auth.role() <> 'service_role'
     and not coalesce(
       public.current_user_is_administrator(),
       false
     )
     and not coalesce(
       public.current_user_has_capability(
         'publish_playlists'
       ),
       false
     )
  then
    raise exception
      'Playlist publication permission is required';
  end if;

  v_limit :=
    least(
      greatest(
        coalesce(p_limit, 25),
        1
      ),
      100
    );

  for due_schedule in
    select scheduled.*
    from editorial.playlist_scheduled_publications scheduled
    where scheduled.status = 'scheduled'
      and scheduled.run_after <= now()
    order by scheduled.run_after asc
    limit v_limit
    for update skip locked
  loop
    select playlist.*
    into v_playlist
    from public.wk_playlists playlist
    where playlist.id =
            due_schedule.playlist_id
    for update;

    if not found then
      update editorial.playlist_scheduled_publications as scheduled
      set
        status = 'failed',
        failure_reason = 'Playlist no longer exists.',
        updated_at = now()
      where scheduled.id = due_schedule.id;

      continue;
    end if;

    select binding.*
    into v_binding
    from editorial.playlist_resources binding
    where binding.playlist_id =
            due_schedule.playlist_id
      and binding.resource_id =
            due_schedule.resource_id
    for update;

    if not found then
      update editorial.playlist_scheduled_publications as scheduled
      set
        status = 'failed',
        failure_reason =
          'Playlist Resource binding no longer exists.',
        updated_at = now()
      where scheduled.id = due_schedule.id;

      continue;
    end if;

    select version.*
    into v_scheduled
    from editorial.playlist_versions version
    where version.id =
            due_schedule.version_id
      and version.resource_id =
            due_schedule.resource_id
      and version.playlist_id =
            due_schedule.playlist_id
      and version.version_kind = 'scheduled';

    if not found
       or v_playlist.status <> 'scheduled'
    then
      update editorial.playlist_scheduled_publications as scheduled
      set
        status = 'failed',
        failure_reason =
          'Scheduled Playlist lifecycle state is no longer publishable.',
        updated_at = now()
      where scheduled.id = due_schedule.id;

      continue;
    end if;

    select *
    into v_published
    from editorial.copy_playlist_lifecycle_version(
      v_scheduled.id,
      'published',
      due_schedule.created_by
    );

    update editorial.playlist_resources as binding
    set current_published_version_id =
          v_published.version_id
    where binding.playlist_id =
            due_schedule.playlist_id;

    update editorial.resources resource
    set
      lifecycle_state = 'published',
      visibility = 'public',
      updated_at = now()
    where resource.id =
            due_schedule.resource_id;

    update public.wk_playlists playlist
    set
      status = 'published',
      published_at = due_schedule.run_after,
      canonical_url =
        'https://wakilisha.africa/playlists/'
        || v_scheduled.slug,
      authority_revision =
        playlist.authority_revision + 1,
      updated_at = now()
    where playlist.id =
            due_schedule.playlist_id
    returning playlist.*
    into v_playlist;

    v_snapshot_id :=
      editorial.materialize_playlist_publication_snapshot(
        v_published.version_id,
        due_schedule.run_after,
        due_schedule.created_by,
        due_schedule.command_receipt_id
      );

    update editorial.playlist_scheduled_publications as scheduled
    set
      status = 'published',
      published_at = due_schedule.run_after,
      failure_reason = null,
      updated_at = now()
    where scheduled.id = due_schedule.id;

    playlist_id := due_schedule.playlist_id;
    playlist_slug := v_playlist.slug;
    schedule_id := due_schedule.id;
    version_id := v_published.version_id;
    published_at := due_schedule.run_after;
    status := 'published';
    return next;
  end loop;
end;
$$;


ALTER FUNCTION "public"."publish_due_playlist_publications"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."publish_playlist_version"("p_playlist_id" "uuid", "p_expected_authority_revision" bigint, "p_approved_version_id" "uuid", "p_idempotency_key" "text", "p_note" "text" DEFAULT NULL::"text", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("command_receipt_id" "uuid", "receipt_status" "text", "playlist_id" "uuid", "resource_id" "uuid", "authority_revision" bigint, "version_id" "uuid", "version_number" bigint, "lifecycle_status" "text", "result_payload" "jsonb", "idempotent_replay" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'editorial', 'platform_private'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_playlist public.wk_playlists%rowtype;
  v_binding editorial.playlist_resources%rowtype;
  v_approved editorial.playlist_versions%rowtype;
  v_published record;
  v_begin record;
  v_read record;
  v_result jsonb;
  v_snapshot_id uuid;
  v_correlation_id uuid :=
    coalesce(
      p_correlation_id,
      gen_random_uuid()
    );
  v_source_version_id uuid;
  v_published_at timestamptz := now();
begin
  if v_actor is null then
    raise exception 'Not authenticated';
  end if;

  select playlist.*
  into v_playlist
  from public.wk_playlists playlist
  where playlist.id = p_playlist_id
  for update;

  if not found then
    raise exception 'Playlist does not exist';
  end if;

  select binding.*
  into v_binding
  from editorial.playlist_resources binding
  where binding.playlist_id = p_playlist_id
  for update;

  if v_binding.resource_id is null then
    raise exception
      'Playlist Resource binding does not exist';
  end if;

  if not editorial.current_user_can_publish_playlist(
    v_binding.resource_id
  ) then
    raise exception
      'Playlist publication permission is required';
  end if;

  v_source_version_id :=
    coalesce(
      p_approved_version_id,
      v_binding.current_approved_version_id
    );

  select *
  into v_begin
  from platform_private.begin_authenticated_resource_command(
    'playlist.publish',
    v_binding.resource_id,
    p_idempotency_key,
    jsonb_build_object(
      'playlist_id',
        p_playlist_id,
      'expected_authority_revision',
        p_expected_authority_revision,
      'approved_version_id',
        v_source_version_id,
      'note',
        nullif(btrim(p_note), ''),
      'correlation_id',
        v_correlation_id
    )
  );

  if v_begin.idempotent_replay then
    select *
    into v_read
    from platform_private.read_authenticated_resource_command_result(
      v_begin.command_receipt_id,
      true
    );

    command_receipt_id :=
      v_read.command_receipt_id;
    receipt_status :=
      v_read.receipt_status;
    playlist_id := p_playlist_id;
    resource_id := v_read.resource_id;
    authority_revision :=
      nullif(
        v_read.result_payload
          ->> 'authority_revision',
        ''
      )::bigint;
    version_id :=
      nullif(
        v_read.result_payload
          ->> 'version_id',
        ''
      )::uuid;
    version_number :=
      nullif(
        v_read.result_payload
          ->> 'version_number',
        ''
      )::bigint;
    lifecycle_status :=
      v_read.result_payload
        ->> 'lifecycle_status';
    result_payload :=
      v_read.result_payload;
    idempotent_replay := true;
    return next;
    return;
  end if;

  if p_expected_authority_revision is null
     or p_expected_authority_revision < 1
     or v_playlist.authority_revision
          <> p_expected_authority_revision
  then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'playlist_revision_changed',
      'The Playlist changed before it could be published.',
      jsonb_build_object(
        'playlist_id',
          p_playlist_id,
        'authority_revision',
          v_playlist.authority_revision,
        'lifecycle_status',
          v_playlist.status
      )
    );

  elsif v_playlist.status <> 'approved'
        or v_source_version_id is null
        or v_binding.current_approved_version_id
             is distinct from v_source_version_id
  then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'playlist_not_publishable',
      'Only the exact current approved Playlist version can be published.',
      jsonb_build_object(
        'playlist_id',
          p_playlist_id,
        'authority_revision',
          v_playlist.authority_revision,
        'lifecycle_status',
          v_playlist.status,
        'current_approved_version_id',
          v_binding.current_approved_version_id
      )
    );

  else
    select approved.*
    into v_approved
    from editorial.playlist_versions approved
    where approved.id = v_source_version_id
      and approved.resource_id =
            v_binding.resource_id
      and approved.playlist_id =
            p_playlist_id
      and approved.version_kind = 'approved';

    if not found then
      perform platform_private.reject_resource_command(
        v_begin.command_receipt_id,
        'approved_version_invalid',
        'The approved Playlist version is no longer publishable.',
        jsonb_build_object(
          'playlist_id',
            p_playlist_id,
          'approved_version_id',
            v_source_version_id
        )
      );
    end if;

    if exists (
      select 1
      from platform_private.command_receipts receipt
      where receipt.id =
              v_begin.command_receipt_id
        and receipt.status = 'accepted'
    ) then
      select *
      into v_published
      from editorial.copy_playlist_published_version(
        v_approved.id,
        v_actor
      );

      update editorial.playlist_resources binding_update
      set current_published_version_id =
            v_published.version_id
      where binding_update.playlist_id =
              p_playlist_id;

      update editorial.resources resource
      set
        lifecycle_state = 'published',
        visibility = 'public',
        updated_at = now()
      where resource.id =
              v_binding.resource_id;

      update public.wk_playlists playlist
      set
        status = 'published',
        published_at = v_published_at,
        canonical_url =
          'https://wakilisha.africa/playlists/'
          || v_approved.slug,
        authority_revision =
          playlist.authority_revision + 1,
        updated_at = now()
      where playlist.id = p_playlist_id
      returning playlist.*
      into v_playlist;

      v_snapshot_id :=
        editorial.materialize_playlist_publication_snapshot(
          v_published.version_id,
          v_published_at,
          v_actor,
          v_begin.command_receipt_id
        );

      v_result := jsonb_build_object(
        'playlist_id',
          p_playlist_id,
        'resource_id',
          v_binding.resource_id,
        'authority_revision',
          v_playlist.authority_revision,
        'approved_version_id',
          v_approved.id,
        'version_id',
          v_published.version_id,
        'version_number',
          v_published.version_number,
        'publication_snapshot_id',
          v_snapshot_id,
        'published_at',
          v_published_at,
        'lifecycle_status',
          'published',
        'correlation_id',
          v_correlation_id
      );

      perform platform_private.complete_resource_command(
        v_begin.command_receipt_id,
        v_result
      );
    end if;
  end if;

  select *
  into v_read
  from platform_private.read_authenticated_resource_command_result(
    v_begin.command_receipt_id,
    false
  );

  command_receipt_id :=
    v_read.command_receipt_id;
  receipt_status :=
    v_read.receipt_status;
  playlist_id := p_playlist_id;
  resource_id := v_read.resource_id;
  authority_revision :=
    nullif(
      v_read.result_payload
        ->> 'authority_revision',
      ''
    )::bigint;
  version_id :=
    nullif(
      v_read.result_payload
        ->> 'version_id',
      ''
    )::uuid;
  version_number :=
    nullif(
      v_read.result_payload
        ->> 'version_number',
      ''
    )::bigint;
  lifecycle_status :=
    v_read.result_payload
      ->> 'lifecycle_status';
  result_payload :=
    v_read.result_payload;
  idempotent_replay := false;
  return next;
end;
$$;


ALTER FUNCTION "public"."publish_playlist_version"("p_playlist_id" "uuid", "p_expected_authority_revision" bigint, "p_approved_version_id" "uuid", "p_idempotency_key" "text", "p_note" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."purge_staging_records"("max_batches" integer DEFAULT 1000, "batch_size" integer DEFAULT 1000) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "statement_timeout" TO '0'
    SET "lock_timeout" TO '0'
    AS $$
DECLARE
  deleted_count integer;
  total_deleted integer := 0;
  batch integer := 0;
BEGIN
  LOOP
    batch := batch + 1;
    
    DELETE FROM wk_import_staging_records
    WHERE ctid IN (
      SELECT ctid FROM wk_import_staging_records
      LIMIT batch_size
    );
    GET DIAGNOSTICS deleted_count = ROW_COUNT;
    total_deleted := total_deleted + deleted_count;
    
    IF deleted_count = 0 THEN
      EXIT;
    END IF;
    
    IF batch >= max_batches THEN
      EXIT;
    END IF;
  END LOOP;
  
  RETURN total_deleted;
END;
$$;


ALTER FUNCTION "public"."purge_staging_records"("max_batches" integer, "batch_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."read_media_assets_admin_v2"("p_query" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'media', 'auth'
    AS $$
declare
  v_base jsonb;
  v_items jsonb;
begin
  perform media.require_media_read_actor();

  v_base := media.read_media_assets_admin_phase4a_v2(p_query);

  select coalesce(
    jsonb_agg(enriched.item order by enriched.ordinality),
    '[]'::jsonb
  )
  into v_items
  from (
    select
      source.ordinality,
      source.item ||
      jsonb_build_object(
        'current_file_object_id', revision.original_file_object_id,
        'upload_session_id', upload_session.id,
        'upload_session_state', upload_session.state,
        'processing_job_id', processing_job.id,
        'processing_job_status', processing_job.status,
        'processing_attempt_count', processing_job.attempt_count,
        'processing_max_attempts', processing_job.max_attempts,
        'processing_last_error', processing_job.last_error,
        'processing_profile_version',
          processing_job.input_payload ->> 'profile_version',
        'selected_derivatives',
          coalesce(derivative_selection.items, '{}'::jsonb),
        'primary_delivery_url',
          case
            when coalesce(
              source.item ->> 'file_kind',
              source.item ->> 'media_kind'
            ) = 'audio'
            then derivative_selection.items -> 'audio_preview' ->> 'url'
            when coalesce(
              source.item ->> 'file_kind',
              source.item ->> 'media_kind'
            ) = 'video'
            then derivative_selection.items -> 'video_transcode' ->> 'url'
            else source.item ->> 'url'
          end,
        'delivery_ready',
          case
            when coalesce(
              source.item ->> 'file_kind',
              source.item ->> 'media_kind'
            ) = 'audio'
            then
              coalesce(derivative_selection.items, '{}'::jsonb) ? 'audio_preview'
              and coalesce(derivative_selection.items, '{}'::jsonb) ? 'waveform_data'
            when coalesce(
              source.item ->> 'file_kind',
              source.item ->> 'media_kind'
            ) = 'video'
            then
              coalesce(derivative_selection.items, '{}'::jsonb) ? 'video_transcode'
              and coalesce(derivative_selection.items, '{}'::jsonb) ? 'poster_frame'
              and coalesce(derivative_selection.items, '{}'::jsonb) ? 'thumbnail'
            else nullif(source.item ->> 'url', '') is not null
          end
      ) as item
    from jsonb_array_elements(
      coalesce(v_base -> 'items', '[]'::jsonb)
    )
    with ordinality as source(item, ordinality)
    left join media.assets asset
      on asset.id = nullif(source.item ->> 'canonical_asset_id', '')::uuid
    left join media.asset_revisions revision
      on revision.id = asset.current_revision_id
    left join lateral (
      select session_row.*
      from media.upload_sessions session_row
      where session_row.file_object_id = revision.original_file_object_id
      order by session_row.created_at desc
      limit 1
    ) upload_session on true
    left join lateral (
      select job_row.*
      from platform_private.jobs job_row
      where job_row.command_type = 'media.process_revision'
        and job_row.resource_id = asset.id
        and job_row.input_payload ->> 'asset_revision_id' = asset.current_revision_id::text
      order by job_row.created_at desc
      limit 1
    ) processing_job on true
    left join lateral (
      select coalesce(
        jsonb_object_agg(
          selection.variant_role,
          jsonb_build_object(
            'variant_id', variant.id,
            'file_object_id', file_object.id,
            'url', file_object.delivery_url,
            'mime_type', file_object.mime_type,
            'byte_size', file_object.byte_size,
            'variant_role', selection.variant_role,
            'selection_revision', selection.selection_revision,
            'generator_name', variant.generator_name,
            'generator_version', variant.generator_version,
            'technical_metadata', variant.technical_metadata
          )
        ),
        '{}'::jsonb
      ) as items
      from media.variant_selections selection
      join media.variants variant
        on variant.id = selection.variant_id
      join media.file_objects file_object
        on file_object.id = variant.derived_file_object_id
      where selection.asset_revision_id = asset.current_revision_id
        and file_object.verification_state = 'verified'
        and file_object.delivery_url like
          'https://media.wakilisha.africa/derivatives/%'
    ) derivative_selection on true
  ) enriched;

  return jsonb_set(v_base, '{items}', v_items, true);
end;
$$;


ALTER FUNCTION "public"."read_media_assets_admin_v2"("p_query" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."read_media_assets_admin_v2"("p_query" "jsonb") IS 'Authenticated Phase 4A administrative Media read adapter. Centralizes compatibility-era read fields behind Media read authority while exposing canonical identity and usage context.';



CREATE OR REPLACE FUNCTION "public"."read_media_maintenance_manifest_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'media', 'platform_private'
    AS $$
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception
      using
        errcode = '42501',
        message = 'Service-role access is required.';
  end if;

  return jsonb_build_object(
    'generated_at', now(),
    'file_objects',
      coalesce(
        (
          select jsonb_agg(
            jsonb_build_object(
              'id', file_object.id,
              'storage_provider', file_object.storage_provider,
              'storage_path', file_object.storage_path,
              'delivery_url', file_object.delivery_url,
              'byte_size', file_object.byte_size,
              'sha256', file_object.sha256,
              'verification_state', file_object.verification_state,
              'created_at', file_object.created_at
            )
            order by file_object.created_at, file_object.id
          )
          from media.file_objects file_object
          where file_object.storage_provider = 'lightsail_media'
        ),
        '[]'::jsonb
      ),
    'selected_derivatives',
      coalesce(
        (
          select jsonb_agg(
            jsonb_build_object(
              'asset_revision_id', selection.asset_revision_id,
              'variant_role', selection.variant_role,
              'variant_id', selection.variant_id,
              'file_object_id', file_object.id,
              'storage_path', file_object.storage_path,
              'delivery_url', file_object.delivery_url,
              'byte_size', file_object.byte_size,
              'sha256', file_object.sha256,
              'verification_state', file_object.verification_state
            )
            order by
              selection.asset_revision_id,
              selection.variant_role
          )
          from media.variant_selections selection
          join media.variants variant
            on variant.id = selection.variant_id
          join media.file_objects file_object
            on file_object.id = variant.derived_file_object_id
        ),
        '[]'::jsonb
      ),
    'upload_sessions',
      coalesce(
        (
          select jsonb_agg(
            jsonb_build_object(
              'id', session.id,
              'state', session.state,
              'storage_path', session.storage_path,
              'file_object_id', session.file_object_id,
              'expires_at', session.expires_at,
              'created_at', session.created_at,
              'updated_at', session.updated_at
            )
            order by session.created_at, session.id
          )
          from media.upload_sessions session
        ),
        '[]'::jsonb
      ),
    'processing_jobs',
      coalesce(
        (
          select jsonb_agg(
            jsonb_build_object(
              'id', job.id,
              'status', job.status,
              'created_at', job.created_at,
              'updated_at', job.updated_at,
              'finished_at', job.finished_at
            )
            order by job.created_at, job.id
          )
          from platform_private.jobs job
          where job.command_type = 'media.process_revision'
            and job.job_type = 'media.process_revision'
        ),
        '[]'::jsonb
      )
  );
end;
$$;


