COMMENT ON FUNCTION "public"."read_media_maintenance_manifest_v1"() IS 'M4 service-role reconciliation manifest for repository-owned Media maintenance.';



CREATE OR REPLACE FUNCTION "public"."rebuild_discography_from_metadata"() RETURNS "text"
    LANGUAGE "plpgsql"
    AS $_$
DECLARE
  artist_record RECORD;
  album_record RECORD;
  track_record RECORD;
  top_song_record RECORD;
  v_release_id UUID;
  v_track_id UUID;
  v_release_slug TEXT;
  v_track_slug TEXT;
  v_duration_ms INTEGER;
  v_release_date DATE;
  v_empty_jsonb JSONB := jsonb_build_object();
  v_total_releases INTEGER := 0;
  v_total_tracks INTEGER := 0;
  v_total_ta_links INTEGER := 0;
  v_total_rt_links INTEGER := 0;
  v_total_ra_links INTEGER := 0;
  v_total_albums INTEGER := 0;
  v_total_top_songs INTEGER := 0;
BEGIN
  FOR artist_record IN
    SELECT id, slug, display_name, metadata FROM registry_artists WHERE metadata IS NOT NULL
  LOOP
    FOR album_record IN
      SELECT a.value->>'title' AS title, a.value->>'image' AS image, a.value->>'release_date' AS release_date, a.value->>'year' AS year, a.value->'tracks' AS tracks
      FROM jsonb_array_elements(COALESCE(artist_record.metadata->'studio_albums', artist_record.metadata->'albums', '[]'::jsonb)) AS a(value)
    LOOP
      IF album_record.title IS NULL OR album_record.tracks IS NULL THEN CONTINUE; END IF;
      v_release_slug := artist_record.slug || '--' || regexp_replace(regexp_replace(regexp_replace(lower(album_record.title), '[^a-z0-9]+', '-', 'g'), '^-+|-+$', '', 'g'), '-+', '-', 'g');
      BEGIN v_release_date := NULL; IF album_record.release_date IS NOT NULL AND album_record.release_date != '' THEN v_release_date := album_record.release_date::DATE; ELSIF album_record.year IS NOT NULL AND album_record.year != '' THEN v_release_date := (album_record.year || '-01-01')::DATE; END IF; EXCEPTION WHEN OTHERS THEN v_release_date := NULL; END;
      INSERT INTO registry_releases (slug, title, normalized_title, release_type, release_date, release_date_precision, artwork_url, metadata) VALUES (v_release_slug, album_record.title, lower(trim(album_record.title)), 'album', v_release_date, CASE WHEN v_release_date IS NOT NULL THEN 'day' ELSE NULL END, NULLIF(album_record.image, ''), jsonb_build_object('source', 'metadata_rebuild_v1')) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, normalized_title = EXCLUDED.normalized_title, artwork_url = COALESCE(EXCLUDED.artwork_url, registry_releases.artwork_url), metadata = registry_releases.metadata || EXCLUDED.metadata RETURNING id INTO v_release_id;
      v_total_releases := v_total_releases + 1;
      INSERT INTO registry_release_artists (release_id, artist_id, artist_slug, artist_name_text, role, is_primary, is_featured, credit_order, source, confidence, metadata) VALUES (v_release_id, artist_record.id, artist_record.slug, artist_record.display_name, 'primary', true, false, 0, 'metadata_rebuild_v1', 100, v_empty_jsonb) ON CONFLICT (release_id, artist_id, role) DO NOTHING;
      v_total_ra_links := v_total_ra_links + 1;
      FOR track_record IN SELECT t.value->>'title' AS title, t.value->>'duration' AS duration, row_number() OVER () AS track_num FROM jsonb_array_elements(album_record.tracks) AS t(value)
      LOOP
        IF track_record.title IS NULL THEN CONTINUE; END IF;
        v_track_slug := artist_record.slug || '--' || regexp_replace(regexp_replace(regexp_replace(lower(track_record.title), '[^a-z0-9]+', '-', 'g'), '^-+|-+$', '', 'g'), '-+', '-', 'g');
        v_duration_ms := NULL; IF track_record.duration IS NOT NULL AND track_record.duration != '' THEN BEGIN IF track_record.duration LIKE '%:%:%' THEN v_duration_ms := ((SPLIT_PART(track_record.duration, ':', 1)::INT * 3600) + (SPLIT_PART(track_record.duration, ':', 2)::INT * 60) + SPLIT_PART(track_record.duration, ':', 3)::INT) * 1000; ELSIF track_record.duration LIKE '%:%' THEN v_duration_ms := ((SPLIT_PART(track_record.duration, ':', 1)::INT * 60) + SPLIT_PART(track_record.duration, ':', 2)::INT) * 1000; END IF; EXCEPTION WHEN OTHERS THEN v_duration_ms := NULL; END; END IF;
        INSERT INTO registry_tracks (slug, title, normalized_title, duration_ms, track_number, disc_number, metadata) VALUES (v_track_slug, track_record.title, lower(trim(track_record.title)), v_duration_ms, track_record.track_num, 1, jsonb_build_object('source', 'metadata_rebuild_v1')) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, normalized_title = EXCLUDED.normalized_title, duration_ms = COALESCE(EXCLUDED.duration_ms, registry_tracks.duration_ms), track_number = COALESCE(EXCLUDED.track_number, registry_tracks.track_number), metadata = registry_tracks.metadata || EXCLUDED.metadata RETURNING id INTO v_track_id;
        v_total_tracks := v_total_tracks + 1;
        INSERT INTO registry_track_artists (track_id, artist_id, artist_slug, artist_name_text, role, is_primary, is_featured, credit_order, source, confidence, metadata) VALUES (v_track_id, artist_record.id, artist_record.slug, artist_record.display_name, 'primary', true, false, 0, 'metadata_rebuild_v1', 100, v_empty_jsonb) ON CONFLICT (track_id, artist_id, role) DO NOTHING;
        v_total_ta_links := v_total_ta_links + 1;
        INSERT INTO registry_release_tracks (release_id, track_id, disc_number, track_number, source, confidence, metadata) VALUES (v_release_id, v_track_id, 1, track_record.track_num, 'metadata_rebuild_v1', 100, v_empty_jsonb) ON CONFLICT (release_id, track_id) DO NOTHING;
        v_total_rt_links := v_total_rt_links + 1;
      END LOOP;
      v_total_albums := v_total_albums + 1;
    END LOOP;

    FOR album_record IN
      SELECT a.value->>'title' AS title, a.value->>'image' AS image, a.value->>'release_date' AS release_date, a.value->>'year' AS year, a.value->'tracks' AS tracks
      FROM jsonb_array_elements(COALESCE(artist_record.metadata->'eps_compilations', '[]'::jsonb)) AS a(value)
    LOOP
      IF album_record.title IS NULL OR album_record.tracks IS NULL THEN CONTINUE; END IF;
      v_release_slug := artist_record.slug || '--' || regexp_replace(regexp_replace(regexp_replace(lower(album_record.title), '[^a-z0-9]+', '-', 'g'), '^-+|-+$', '', 'g'), '-+', '-', 'g');
      BEGIN v_release_date := NULL; IF album_record.release_date IS NOT NULL AND album_record.release_date != '' THEN v_release_date := album_record.release_date::DATE; ELSIF album_record.year IS NOT NULL AND album_record.year != '' THEN v_release_date := (album_record.year || '-01-01')::DATE; END IF; EXCEPTION WHEN OTHERS THEN v_release_date := NULL; END;
      INSERT INTO registry_releases (slug, title, normalized_title, release_type, release_date, release_date_precision, artwork_url, metadata) VALUES (v_release_slug, album_record.title, lower(trim(album_record.title)), 'album', v_release_date, CASE WHEN v_release_date IS NOT NULL THEN 'day' ELSE NULL END, NULLIF(album_record.image, ''), jsonb_build_object('source', 'metadata_rebuild_v1')) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, normalized_title = EXCLUDED.normalized_title, artwork_url = COALESCE(EXCLUDED.artwork_url, registry_releases.artwork_url), metadata = registry_releases.metadata || EXCLUDED.metadata RETURNING id INTO v_release_id;
      v_total_releases := v_total_releases + 1;
      INSERT INTO registry_release_artists (release_id, artist_id, artist_slug, artist_name_text, role, is_primary, is_featured, credit_order, source, confidence, metadata) VALUES (v_release_id, artist_record.id, artist_record.slug, artist_record.display_name, 'primary', true, false, 0, 'metadata_rebuild_v1', 100, v_empty_jsonb) ON CONFLICT (release_id, artist_id, role) DO NOTHING;
      v_total_ra_links := v_total_ra_links + 1;
      FOR track_record IN SELECT t.value->>'title' AS title, t.value->>'duration' AS duration, row_number() OVER () AS track_num FROM jsonb_array_elements(album_record.tracks) AS t(value)
      LOOP
        IF track_record.title IS NULL THEN CONTINUE; END IF;
        v_track_slug := artist_record.slug || '--' || regexp_replace(regexp_replace(regexp_replace(lower(track_record.title), '[^a-z0-9]+', '-', 'g'), '^-+|-+$', '', 'g'), '-+', '-', 'g');
        v_duration_ms := NULL; IF track_record.duration IS NOT NULL AND track_record.duration != '' THEN BEGIN IF track_record.duration LIKE '%:%:%' THEN v_duration_ms := ((SPLIT_PART(track_record.duration, ':', 1)::INT * 3600) + (SPLIT_PART(track_record.duration, ':', 2)::INT * 60) + SPLIT_PART(track_record.duration, ':', 3)::INT) * 1000; ELSIF track_record.duration LIKE '%:%' THEN v_duration_ms := ((SPLIT_PART(track_record.duration, ':', 1)::INT * 60) + SPLIT_PART(track_record.duration, ':', 2)::INT) * 1000; END IF; EXCEPTION WHEN OTHERS THEN v_duration_ms := NULL; END; END IF;
        INSERT INTO registry_tracks (slug, title, normalized_title, duration_ms, track_number, disc_number, metadata) VALUES (v_track_slug, track_record.title, lower(trim(track_record.title)), v_duration_ms, track_record.track_num, 1, jsonb_build_object('source', 'metadata_rebuild_v1')) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, normalized_title = EXCLUDED.normalized_title, duration_ms = COALESCE(EXCLUDED.duration_ms, registry_tracks.duration_ms), metadata = registry_tracks.metadata || EXCLUDED.metadata RETURNING id INTO v_track_id;
        v_total_tracks := v_total_tracks + 1;
        INSERT INTO registry_track_artists (track_id, artist_id, artist_slug, artist_name_text, role, is_primary, is_featured, credit_order, source, confidence, metadata) VALUES (v_track_id, artist_record.id, artist_record.slug, artist_record.display_name, 'primary', true, false, 0, 'metadata_rebuild_v1', 100, v_empty_jsonb) ON CONFLICT (track_id, artist_id, role) DO NOTHING;
        v_total_ta_links := v_total_ta_links + 1;
        INSERT INTO registry_release_tracks (release_id, track_id, disc_number, track_number, source, confidence, metadata) VALUES (v_release_id, v_track_id, 1, track_record.track_num, 'metadata_rebuild_v1', 100, v_empty_jsonb) ON CONFLICT (release_id, track_id) DO NOTHING;
        v_total_rt_links := v_total_rt_links + 1;
      END LOOP;
      v_total_albums := v_total_albums + 1;
    END LOOP;

    FOR top_song_record IN
      SELECT t.value->>'title' AS title, t.value->>'artwork' AS artwork, t.value->>'duration' AS duration, t.value->>'song_url' AS song_url
      FROM jsonb_array_elements(COALESCE(artist_record.metadata->'top_songs', '[]'::jsonb)) AS t(value)
    LOOP
      IF top_song_record.title IS NULL THEN CONTINUE; END IF;
      v_track_slug := artist_record.slug || '--' || regexp_replace(regexp_replace(regexp_replace(lower(top_song_record.title), '[^a-z0-9]+', '-', 'g'), '^-+|-+$', '', 'g'), '-+', '-', 'g');
      v_duration_ms := NULL; IF top_song_record.duration IS NOT NULL AND top_song_record.duration != '' THEN BEGIN IF top_song_record.duration LIKE '%:%:%' THEN v_duration_ms := ((SPLIT_PART(top_song_record.duration, ':', 1)::INT * 3600) + (SPLIT_PART(top_song_record.duration, ':', 2)::INT * 60) + SPLIT_PART(top_song_record.duration, ':', 3)::INT) * 1000; ELSIF top_song_record.duration LIKE '%:%' THEN v_duration_ms := ((SPLIT_PART(top_song_record.duration, ':', 1)::INT * 60) + SPLIT_PART(top_song_record.duration, ':', 2)::INT) * 1000; END IF; EXCEPTION WHEN OTHERS THEN v_duration_ms := NULL; END; END IF;
      INSERT INTO registry_tracks (slug, title, normalized_title, duration_ms, track_number, disc_number, artwork_url, preview_url, metadata) VALUES (v_track_slug, top_song_record.title, lower(trim(top_song_record.title)), v_duration_ms, 1, 1, NULLIF(top_song_record.artwork, ''), NULLIF(top_song_record.song_url, ''), jsonb_build_object('source', 'metadata_rebuild_v1', 'is_top_song', true)) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, normalized_title = EXCLUDED.normalized_title, artwork_url = COALESCE(EXCLUDED.artwork_url, registry_tracks.artwork_url), preview_url = COALESCE(EXCLUDED.preview_url, registry_tracks.preview_url), metadata = registry_tracks.metadata || EXCLUDED.metadata RETURNING id INTO v_track_id;
      v_total_tracks := v_total_tracks + 1;
      INSERT INTO registry_track_artists (track_id, artist_id, artist_slug, artist_name_text, role, is_primary, is_featured, credit_order, source, confidence, metadata) VALUES (v_track_id, artist_record.id, artist_record.slug, artist_record.display_name, 'primary', true, false, 0, 'metadata_rebuild_v1', 100, v_empty_jsonb) ON CONFLICT (track_id, artist_id, role) DO NOTHING;
      v_total_ta_links := v_total_ta_links + 1;
      v_total_top_songs := v_total_top_songs + 1;
    END LOOP;
  END LOOP;
  RETURN format('OK: %s releases, %s tracks, %s ta_links, %s rt_links, %s ra_links, %s albums, %s top_songs', v_total_releases, v_total_tracks, v_total_ta_links, v_total_rt_links, v_total_ra_links, v_total_albums, v_total_top_songs);
END;
$_$;


ALTER FUNCTION "public"."rebuild_discography_from_metadata"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_admin_audit"("event_type" "text", "target_table" "text" DEFAULT NULL::"text", "target_record_id" "text" DEFAULT NULL::"text", "target_user_id" "uuid" DEFAULT NULL::"uuid", "message" "text" DEFAULT NULL::"text", "metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  event_id uuid;
begin
  insert into public.admin_audit_events (actor_user_id, target_user_id, event_type, target_table, target_record_id, message, metadata, created_at)
  values (auth.uid(), target_user_id, event_type, target_table, target_record_id, message, coalesce(metadata, '{}'::jsonb), now())
  returning id into event_id;
  return event_id;
end;
$$;


ALTER FUNCTION "public"."record_admin_audit"("event_type" "text", "target_table" "text", "target_record_id" "text", "target_user_id" "uuid", "message" "text", "metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_artist_music_submission_validation"("p_requested_by" "uuid", "p_artist_id" "uuid", "p_provider_key" "text", "p_provider_object_id" "text", "p_provider_url" "text", "p_provider_title" "text", "p_provider_artist_names" "text"[], "p_provider_release_title" "text", "p_playback_kind" "text", "p_validation_snapshot" "jsonb", "p_expires_at" timestamp with time zone) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'platform_private'
    AS $$
declare
  v_rep public.artist_representations%rowtype;
  v_provider text :=
    lower(
      btrim(
        coalesce(
          p_provider_key,
          ''
        )
      )
    );
  v_object_id text :=
    nullif(
      btrim(p_provider_object_id),
      ''
    );
  v_url text :=
    nullif(
      btrim(p_provider_url),
      ''
    );
  v_title text :=
    nullif(
      btrim(p_provider_title),
      ''
    );
  v_id uuid := gen_random_uuid();
begin
  if p_requested_by is null
     or p_artist_id is null
  then
    raise exception
      'Artist submission validation requires a user and Artist.';
  end if;

  select representation.*
  into v_rep
  from public.artist_representations representation
  where representation.artist_id = p_artist_id
    and representation.user_id = p_requested_by
    and representation.status = 'active'
    and representation.can_submit_releases
  order by representation.created_at desc
  limit 1;

  if v_rep.id is null then
    raise exception
      'Artist music submission permission is required.';
  end if;

  if not exists (
    select 1
    from public.registry_artists artist
    where artist.id = p_artist_id
      and artist.status = 'active'
  ) then
    raise exception
      'Artist is unavailable for music submission.';
  end if;

  if v_provider not in (
    'apple_music',
    'spotify'
  )
     or v_object_id is null
     or v_url is null
     or v_title is null
     or p_playback_kind <> 'audio'
     or p_validation_snapshot is null
     or jsonb_typeof(p_validation_snapshot) <> 'object'
     or p_expires_at is null
     or p_expires_at <= now()
     or p_expires_at > now() + interval '1 hour'
  then
    raise exception
      'Complete provider evidence is required for Artist music submission.';
  end if;

  insert into platform_private.artist_music_submission_validations (
    id,
    requested_by,
    artist_id,
    representation_id,
    provider_key,
    provider_object_id,
    provider_url,
    provider_title,
    provider_artist_names,
    provider_release_title,
    playback_kind,
    validation_snapshot,
    checked_at,
    expires_at
  )
  values (
    v_id,
    p_requested_by,
    p_artist_id,
    v_rep.id,
    v_provider,
    v_object_id,
    v_url,
    v_title,
    coalesce(
      p_provider_artist_names,
      '{}'::text[]
    ),
    nullif(
      btrim(p_provider_release_title),
      ''
    ),
    p_playback_kind,
    p_validation_snapshot,
    now(),
    p_expires_at
  );

  return v_id;
end;
$$;


ALTER FUNCTION "public"."record_artist_music_submission_validation"("p_requested_by" "uuid", "p_artist_id" "uuid", "p_provider_key" "text", "p_provider_object_id" "text", "p_provider_url" "text", "p_provider_title" "text", "p_provider_artist_names" "text"[], "p_provider_release_title" "text", "p_playback_kind" "text", "p_validation_snapshot" "jsonb", "p_expires_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_correction_decision"("p_case_resource_id" "uuid", "p_expected_case_revision" bigint, "p_outcome" "text", "p_reason" "text", "p_private_analysis" "text", "p_public_safe_explanation" "text", "p_target_state_observed" "jsonb", "p_duplicate_of_case_resource_id" "uuid", "p_idempotency_key" "text", "p_correlation_id" "uuid") RETURNS TABLE("command_receipt_id" "uuid", "receipt_status" "text", "case_resource_id" "uuid", "case_revision" bigint, "result_payload" "jsonb", "idempotent_replay" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'editorial', 'platform_private'
    AS $$
declare
  v_actor uuid;
  v_begin record;
  v_case editorial.correction_cases%rowtype;
  v_prior_decision_id uuid;
  v_decision_id uuid;
  v_decision_number bigint;
  v_result jsonb;
begin
  v_actor :=
    platform_private.assert_correction_capability(
      'decide_corrections'
    );

  if p_case_resource_id is null
     or p_expected_case_revision < 1
     or p_correlation_id is null
     or nullif(btrim(p_reason), '') is null
     or p_outcome not in (
       'correction_required',
       'no_change_required',
       'insufficient_evidence',
       'duplicate',
       'out_of_scope'
     )
     or (
       p_outcome = 'duplicate'
       and p_duplicate_of_case_resource_id is null
     )
     or (
       p_outcome <> 'duplicate'
       and p_duplicate_of_case_resource_id is not null
     )
     or p_target_state_observed is null
     or jsonb_typeof(p_target_state_observed) <> 'object'
     or octet_length(p_target_state_observed::text) > 32768
  then
    raise exception
      using errcode = '22023',
      message = 'Case, revision, decision, reason, target state, and correlation identity are required.';
  end if;

  select *
  into v_begin
  from platform_private.begin_resource_command(
    'correction.decision.record',
    p_case_resource_id,
    p_idempotency_key,
    jsonb_build_object(
      'expected_case_revision', p_expected_case_revision,
      'outcome', p_outcome,
      'reason', btrim(p_reason),
      'private_analysis',
      nullif(btrim(p_private_analysis), ''),
      'public_safe_explanation',
      nullif(btrim(p_public_safe_explanation), ''),
      'target_state_observed', p_target_state_observed,
      'duplicate_of_case_resource_id',
      p_duplicate_of_case_resource_id,
      'correlation_id', p_correlation_id
    )
  );

  if v_begin.idempotent_replay then
    return query
    select *
    from platform_private.read_correction_command_result(
      v_begin.command_receipt_id,
      true
    );
    return;
  end if;

  select correction_case.*
  into v_case
  from editorial.correction_cases correction_case
  where correction_case.resource_id =
    p_case_resource_id
  for update;

  if not found then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'case_not_found',
      'The correction case does not exist.',
      jsonb_build_object('case_revision', null)
    );
  elsif v_case.current_revision <>
        p_expected_case_revision
  then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'case_revision_changed',
      'The correction case revision changed.',
      jsonb_build_object(
        'case_revision', v_case.current_revision,
        'case_state', v_case.case_state
      )
    );
  elsif v_case.case_state not in (
    'awaiting_decision',
    'decided'
  ) then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'invalid_transition',
      'Decisions may be recorded only from awaiting_decision or decided.',
      jsonb_build_object(
        'case_revision', v_case.current_revision,
        'case_state', v_case.case_state
      )
    );
  elsif p_duplicate_of_case_resource_id =
        p_case_resource_id
  then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'invalid_duplicate_case',
      'A correction case cannot duplicate itself.',
      jsonb_build_object(
        'case_revision', v_case.current_revision,
        'case_state', v_case.case_state
      )
    );
  elsif p_duplicate_of_case_resource_id
        is not null
        and not exists (
          select 1
          from editorial.correction_cases duplicate_case
          where duplicate_case.resource_id =
            p_duplicate_of_case_resource_id
        )
  then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'duplicate_case_not_found',
      'The controlling duplicate correction case does not exist.',
      jsonb_build_object(
        'case_revision', v_case.current_revision,
        'case_state', v_case.case_state
      )
    );
  else
    v_prior_decision_id :=
      v_case.current_decision_id;

    select coalesce(
      max(decision.decision_number),
      0
    ) + 1
    into v_decision_number
    from editorial.correction_decisions decision
    where decision.case_resource_id =
      p_case_resource_id;

    insert into editorial.correction_decisions (
      case_resource_id,
      decision_number,
      outcome,
      reason,
      private_analysis,
      public_safe_explanation,
      case_revision_observed,
      target_state_observed,
      duplicate_of_case_resource_id,
      supersedes_decision_id,
      decided_by,
      correlation_id
    )
    values (
      p_case_resource_id,
      v_decision_number,
      p_outcome,
      btrim(p_reason),
      nullif(btrim(p_private_analysis), ''),
      nullif(
        btrim(p_public_safe_explanation),
        ''
      ),
      v_case.current_revision,
      p_target_state_observed,
      p_duplicate_of_case_resource_id,
      v_prior_decision_id,
      v_actor,
      p_correlation_id
    )
    returning id
    into v_decision_id;

    update editorial.correction_cases
    set
      case_state = 'decided',
      current_revision =
        v_case.current_revision + 1,
      current_decision_id = v_decision_id,
      updated_by = v_actor,
      updated_at = now()
    where resource_id = p_case_resource_id;

    if v_prior_decision_id is not null then
      perform platform_private.append_correction_event(
        p_case_resource_id,
        'decision_superseded',
        v_case.current_revision,
        v_case.current_revision + 1,
        v_case.case_state,
        'decided',
        v_actor,
        btrim(p_reason),
        v_decision_id,
        null,
        null,
        null,
        v_begin.command_receipt_id,
        p_correlation_id,
        jsonb_build_object(
          'prior_decision_id',
          v_prior_decision_id,
          'new_decision_id',
          v_decision_id
        )
      );
    end if;

    perform platform_private.append_correction_event(
      p_case_resource_id,
      'decision_recorded',
      v_case.current_revision,
      v_case.current_revision + 1,
      v_case.case_state,
      'decided',
      v_actor,
      btrim(p_reason),
      v_decision_id,
      null,
      null,
      null,
      v_begin.command_receipt_id,
      p_correlation_id,
      jsonb_build_object(
        'decision_id', v_decision_id,
        'decision_number', v_decision_number,
        'outcome', p_outcome,
        'supersedes_decision_id',
        v_prior_decision_id
      )
    );

    v_result := jsonb_build_object(
      'case_resource_id', p_case_resource_id,
      'case_revision', v_case.current_revision + 1,
      'case_state', 'decided',
      'decision_id', v_decision_id,
      'decision_number', v_decision_number,
      'outcome', p_outcome
    );

    perform platform_private.complete_resource_command(
      v_begin.command_receipt_id,
      v_result
    );
  end if;

  return query
  select *
  from platform_private.read_correction_command_result(
    v_begin.command_receipt_id,
    false
  );
end;
$$;


