CREATE OR REPLACE FUNCTION "public"."record_playlist_playback_probe_candidate"("p_requested_by" "uuid", "p_playlist_id" "uuid", "p_provider_key" "text", "p_provider_object_id" "text", "p_provider_url" "text", "p_canonical_url" "text", "p_playback_kind" "text", "p_embed_url" "text", "p_title_hint" "text", "p_artist_names_hint" "text"[], "p_artwork_url" "text", "p_provider_metadata" "jsonb", "p_expires_at" timestamp with time zone, "p_correlation_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'platform_private'
    AS $$
declare
  v_id uuid := gen_random_uuid();
begin
  if p_requested_by is null
     or p_playlist_id is null
     or nullif(btrim(p_provider_key), '') is null
     or nullif(btrim(p_provider_object_id), '') is null
     or nullif(btrim(p_provider_url), '') is null
     or nullif(btrim(p_canonical_url), '') is null
     or p_playback_kind not in ('audio', 'video')
     or p_expires_at is null
     or p_expires_at <= now()
  then
    raise exception
      'Complete browser playback probe metadata is required';
  end if;

  if not exists (
    select 1
    from public.wk_playlists playlist
    where playlist.id = p_playlist_id
  ) then
    raise exception 'Playlist does not exist';
  end if;

  insert into platform_private.playlist_playback_validations (
    id,
    requested_by,
    playlist_id,
    provider_key,
    provider_object_id,
    provider_url,
    canonical_url,
    playback_kind,
    embed_url,
    preview_url,
    playable,
    validation_status,
    title_hint,
    artist_names_hint,
    release_title_hint,
    artwork_url,
    provider_metadata,
    checked_at,
    expires_at,
    correlation_id
  )
  values (
    v_id,
    p_requested_by,
    p_playlist_id,
    lower(btrim(p_provider_key)),
    btrim(p_provider_object_id),
    btrim(p_provider_url),
    btrim(p_canonical_url),
    p_playback_kind,
    nullif(btrim(p_embed_url), ''),
    null,
    false,
    'probe_required',
    nullif(btrim(p_title_hint), ''),
    coalesce(p_artist_names_hint, '{}'::text[]),
    null,
    nullif(btrim(p_artwork_url), ''),
    coalesce(p_provider_metadata, '{}'::jsonb),
    now(),
    p_expires_at,
    coalesce(p_correlation_id, gen_random_uuid())
  );

  return v_id;
end;
$$;


