CREATE OR REPLACE FUNCTION "public"."recover_expired_media_processing_jobs_v1"("p_limit" integer DEFAULT 10, "p_retry_delay_seconds" integer DEFAULT 30) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'auth', 'platform_private'
    AS $$
declare
  v_job platform_private.jobs%rowtype;
  v_event_id uuid;
  v_event_type text;
  v_count integer := 0;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception
      using
        errcode = '42501',
        message = 'Service-role access is required.';
  end if;

  if p_limit not between 1 and 100 then
    raise exception
      using
        errcode = '22023',
        message = 'limit must be between 1 and 100.';
  end if;

  if p_retry_delay_seconds not between 1 and 3600 then
    raise exception
      using
        errcode = '22023',
        message = 'retry delay must be between 1 and 3600 seconds.';
  end if;

  for v_job in
    select job.*
    from platform_private.jobs job
    where job.command_type = 'media.process_revision'
      and job.job_type = 'media.process_revision'
      and job.status = 'running'
      and job.lease_expires_at is not null
      and job.lease_expires_at <= now()
    order by
      job.lease_expires_at,
      job.created_at
    for update skip locked
    limit p_limit
  loop
    if v_job.attempt_count >= v_job.max_attempts then
      update platform_private.jobs
      set
        status = 'dead_letter',
        locked_by = null,
        locked_at = null,
        lease_expires_at = null,
        finished_at = now(),
        last_error =
          'Media processing worker lease expired after the final allowed attempt.'
      where id = v_job.id;

      update platform_private.command_receipts
      set
        status = 'failed',
        error_code = 'job_failed',
        error_message =
          'Media processing worker lease expired after the final allowed attempt.',
        completed_at = now()
      where id = v_job.command_receipt_id;

      select command_types.failure_event_type
      into v_event_type
      from platform_private.command_types
      where command_type = v_job.command_type;

      insert into platform_private.outbox_events (
        event_key,
        command_receipt_id,
        job_id,
        command_type,
        aggregate_id,
        event_type,
        payload
      )
      values (
        'command:' ||
          v_job.command_receipt_id::text ||
          ':failed',
        v_job.command_receipt_id,
        v_job.id,
        v_job.command_type,
        v_job.resource_id,
        v_event_type,
        jsonb_build_object(
          'command_receipt_id', v_job.command_receipt_id,
          'job_id', v_job.id,
          'resource_id', v_job.resource_id,
          'error',
            'Media processing worker lease expired after the final allowed attempt.',
          'failed_at', now()
        )
      )
      on conflict (event_key)
      do nothing
      returning id
      into v_event_id;
    else
      update platform_private.jobs
      set
        status = 'retry_wait',
        available_at =
          now() +
          make_interval(
            secs => p_retry_delay_seconds
          ),
        locked_by = null,
        locked_at = null,
        lease_expires_at = null,
        last_error =
          'Media processing worker lease expired before completion.'
      where id = v_job.id;

      select command_types.retry_event_type
      into v_event_type
      from platform_private.command_types
      where command_type = v_job.command_type;

      insert into platform_private.outbox_events (
        event_key,
        command_receipt_id,
        job_id,
        command_type,
        aggregate_id,
        event_type,
        payload
      )
      values (
        'job:' ||
          v_job.id::text ||
          ':retry:' ||
          v_job.attempt_count::text,
        v_job.command_receipt_id,
        v_job.id,
        v_job.command_type,
        v_job.resource_id,
        v_event_type,
        jsonb_build_object(
          'command_receipt_id', v_job.command_receipt_id,
          'job_id', v_job.id,
          'resource_id', v_job.resource_id,
          'attempt_count', v_job.attempt_count,
          'error',
            'Media processing worker lease expired before completion.',
          'available_at',
            now() +
            make_interval(
              secs => p_retry_delay_seconds
            )
        )
      )
      on conflict (event_key)
      do nothing
      returning id
      into v_event_id;
    end if;

    v_count := v_count + 1;
  end loop;

  return v_count;
end;
$$;


ALTER FUNCTION "public"."recover_expired_media_processing_jobs_v1"("p_limit" integer, "p_retry_delay_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."register_media_file_object"("p_storage_provider" "text", "p_storage_namespace" "text", "p_storage_path" "text", "p_delivery_url" "text", "p_original_filename" "text", "p_mime_type" "text" DEFAULT NULL::"text", "p_byte_size" bigint DEFAULT NULL::bigint, "p_technical_metadata" "jsonb" DEFAULT '{}'::"jsonb", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("file_object_id" "uuid", "verification_state" "text", "correlation_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'media', 'auth'
    AS $$
declare
  v_actor_id uuid;
  v_file_object_id uuid := gen_random_uuid();
  v_correlation_id uuid := coalesce(
    p_correlation_id,
    gen_random_uuid()
  );
  v_extension text;
begin
  v_actor_id :=
    media.require_command_actor('register_media_files');

  if not exists (
    select 1
    from media.storage_providers provider
    where provider.storage_provider = p_storage_provider
      and provider.enabled
  ) then
    raise exception 'Unknown or disabled Media storage provider';
  end if;

  if nullif(btrim(p_storage_path), '') is null
     and nullif(btrim(p_delivery_url), '') is null
  then
    raise exception 'Media file object requires a path or delivery URL';
  end if;

  if p_byte_size is not null and p_byte_size < 0 then
    raise exception 'Media byte size cannot be negative';
  end if;

  if p_technical_metadata is null
     or jsonb_typeof(p_technical_metadata) <> 'object'
  then
    raise exception 'Media technical metadata must be an object';
  end if;

  if nullif(btrim(p_storage_path), '') is not null
     and exists (
       select 1
       from media.file_objects object_row
       where object_row.storage_provider = p_storage_provider
         and coalesce(object_row.storage_namespace, '') =
           coalesce(nullif(btrim(p_storage_namespace), ''), '')
         and object_row.storage_path = btrim(p_storage_path)
     )
  then
    raise exception 'Media storage locator is already registered';
  end if;

  v_extension :=
    case
      when nullif(btrim(p_original_filename), '') is not null
       and strpos(reverse(btrim(p_original_filename)), '.') > 0
      then lower(
        reverse(
          split_part(
            reverse(btrim(p_original_filename)),
            '.',
            1
          )
        )
      )
      else null
    end;

  insert into media.file_objects (
    id,
    sha256,
    byte_size,
    mime_type,
    original_filename,
    file_extension,
    storage_provider,
    storage_namespace,
    storage_path,
    delivery_url,
    technical_metadata,
    verification_state,
    ingested_by
  )
  values (
    v_file_object_id,
    null,
    p_byte_size,
    nullif(btrim(p_mime_type), ''),
    nullif(btrim(p_original_filename), ''),
    v_extension,
    p_storage_provider,
    nullif(btrim(p_storage_namespace), ''),
    nullif(btrim(p_storage_path), ''),
    nullif(btrim(p_delivery_url), ''),
    p_technical_metadata,
    'unverified',
    v_actor_id
  );

  insert into media.events (
    file_object_id,
    event_type,
    actor_id,
    reason,
    resulting_state,
    correlation_id
  )
  values (
    v_file_object_id,
    'file_object_registered',
    v_actor_id,
    'Candidate Media file object registered',
    jsonb_build_object(
      'storage_provider', p_storage_provider,
      'storage_namespace',
        nullif(btrim(p_storage_namespace), ''),
      'storage_path',
        nullif(btrim(p_storage_path), ''),
      'delivery_url',
        nullif(btrim(p_delivery_url), ''),
      'verification_state', 'unverified'
    ),
    v_correlation_id
  );

  return query
  select
    v_file_object_id,
    'unverified'::text,
    v_correlation_id;
end;
$$;


ALTER FUNCTION "public"."register_media_file_object"("p_storage_provider" "text", "p_storage_namespace" "text", "p_storage_path" "text", "p_delivery_url" "text", "p_original_filename" "text", "p_mime_type" "text", "p_byte_size" bigint, "p_technical_metadata" "jsonb", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."register_media_processing_outputs_v1"("p_job_id" "uuid", "p_worker_id" "text", "p_outputs" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'media', 'platform_private'
    AS $_$
declare
  v_job platform_private.jobs%rowtype;
  v_receipt platform_private.command_receipts%rowtype;
  v_actor_id uuid;
  v_asset_id uuid;
  v_revision_id uuid;
  v_source_file_id uuid;
  v_correlation_id uuid;
  v_profile_version text;
  v_output jsonb;
  v_file jsonb;
  v_role text;
  v_storage_provider text;
  v_storage_namespace text;
  v_storage_path text;
  v_delivery_url text;
  v_sha256 text;
  v_byte_size bigint;
  v_mime_type text;
  v_file_object_id uuid;
  v_existing_file media.file_objects%rowtype;
  v_variant_id uuid;
  v_selection_variant_id uuid;
  v_selection_revision bigint;
  v_transformation_spec jsonb;
  v_technical_metadata jsonb;
  v_generator_name text;
  v_generator_version text;
  v_seen_roles text[] := array[]::text[];
  v_results jsonb := '[]'::jsonb;
  v_new_variant boolean;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception
      using
        errcode = '42501',
        message = 'Service-role access is required.';
  end if;

  if p_job_id is null
     or p_worker_id is null
     or p_worker_id !~
       '^[A-Za-z0-9][A-Za-z0-9._:-]{2,127}$'
  then
    raise exception
      using
        errcode = '22023',
        message = 'job_id and valid worker_id are required.';
  end if;

  if p_outputs is null
     or jsonb_typeof(p_outputs) <> 'array'
     or jsonb_array_length(p_outputs) not between 1 and 5
  then
    raise exception
      using
        errcode = '22023',
        message = 'outputs must be a JSON array containing 1 to 5 derivatives.';
  end if;

  select job.*
  into v_job
  from platform_private.jobs job
  where job.id = p_job_id
  for update;

  if not found
     or v_job.command_type <> 'media.process_revision'
     or v_job.job_type <> 'media.process_revision'
     or v_job.status <> 'running'
     or v_job.locked_by is distinct from p_worker_id
     or v_job.lease_expires_at is null
     or v_job.lease_expires_at <= now()
  then
    raise exception
      using
        errcode = '55000',
        message = 'The Media processing job is not actively leased to this worker.';
  end if;

  select receipt.*
  into v_receipt
  from platform_private.command_receipts receipt
  where receipt.id = v_job.command_receipt_id;

  if not found
     or v_receipt.actor_user_id is null
     or v_receipt.status <> 'accepted'
  then
    raise exception
      using
        errcode = '55000',
        message = 'Media processing receipt actor or state is invalid.';
  end if;

  v_actor_id := v_receipt.actor_user_id;
  v_asset_id :=
    nullif(v_job.input_payload ->> 'asset_id', '')::uuid;
  v_revision_id :=
    nullif(v_job.input_payload ->> 'asset_revision_id', '')::uuid;
  v_source_file_id :=
    nullif(v_job.input_payload ->> 'source_file_object_id', '')::uuid;
  v_correlation_id :=
    nullif(v_job.input_payload ->> 'correlation_id', '')::uuid;
  v_profile_version :=
    nullif(v_job.input_payload ->> 'profile_version', '');

  if v_asset_id is null
     or v_revision_id is null
     or v_source_file_id is null
     or v_correlation_id is null
  then
    raise exception
      'Media processing job input identity is incomplete.';
  end if;

  if not exists (
    select 1
    from media.asset_revisions revision
    join media.file_objects source_file
      on source_file.id = revision.original_file_object_id
    where revision.id = v_revision_id
      and revision.asset_id = v_asset_id
      and revision.original_file_object_id = v_source_file_id
      and source_file.verification_state = 'verified'
  ) then
    raise exception
      'Media processing source authority changed or is invalid.';
  end if;

  for v_output in
    select value
    from jsonb_array_elements(p_outputs)
  loop
    if jsonb_typeof(v_output) <> 'object'
       or jsonb_typeof(v_output -> 'file') <> 'object'
    then
      raise exception
        'Every Media processing output must include a file object.';
    end if;

    v_role := nullif(
      btrim(v_output ->> 'variant_role'),
      ''
    );

    if v_role is null
       or v_role = any(v_seen_roles)
    then
      raise exception
        'Media processing variant roles must be present and unique.';
    end if;

    v_seen_roles := array_append(
      v_seen_roles,
      v_role
    );

    if (
      v_profile_version = 'audio-v1'
      and v_role not in (
        'audio_preview',
        'waveform_data'
      )
    ) or (
      v_profile_version = 'video-v1'
      and v_role not in (
        'video_transcode',
        'poster_frame',
        'thumbnail'
      )
    ) then
      raise exception
        'Variant role % is not permitted for processing profile %.',
        v_role,
        v_profile_version;
    end if;

    v_file := v_output -> 'file';
    v_storage_provider :=
      nullif(btrim(v_file ->> 'storage_provider'), '');
    v_storage_namespace :=
      nullif(btrim(v_file ->> 'storage_namespace'), '');
    v_storage_path :=
      nullif(btrim(v_file ->> 'storage_path'), '');
    v_delivery_url :=
      nullif(btrim(v_file ->> 'delivery_url'), '');
    v_sha256 :=
      lower(nullif(btrim(v_file ->> 'sha256'), ''));
    v_byte_size :=
      nullif(v_file ->> 'byte_size', '')::bigint;
    v_mime_type :=
      nullif(btrim(v_file ->> 'mime_type'), '');

    if v_storage_provider <> 'lightsail_media'
       or coalesce(v_storage_namespace, '') <> 'lightsail-media'
       or v_storage_path is null
       or v_storage_path !~ '^derived-objects/'
       or v_delivery_url is null
       or v_delivery_url !~
         '^https://media[.]wakilisha[.]africa/derivatives/'
       or v_sha256 is null
       or v_sha256 !~ '^[0-9a-f]{64}$'
       or v_byte_size is null
       or v_byte_size < 1
       or v_mime_type is null
    then
      raise exception
        'Media processing output file authority is invalid.';
    end if;

    select file_object.*
    into v_existing_file
    from media.file_objects file_object
    where file_object.storage_provider = v_storage_provider
      and coalesce(file_object.storage_namespace, '') =
        coalesce(v_storage_namespace, '')
      and file_object.storage_path = v_storage_path;

    if found then
      if v_existing_file.verification_state <> 'verified'
         or v_existing_file.sha256 <> v_sha256
         or v_existing_file.byte_size <> v_byte_size
         or v_existing_file.mime_type <> v_mime_type
         or v_existing_file.delivery_url <> v_delivery_url
      then
        raise exception
          'Immutable derivative storage collision does not match registered bytes.';
      end if;

      v_file_object_id := v_existing_file.id;
    else
      v_file_object_id :=
        media.insert_verified_file_object_v2(
          v_file,
          v_actor_id,
          v_correlation_id
        );
    end if;

    v_transformation_spec :=
      coalesce(
        v_output -> 'transformation_spec',
        '{}'::jsonb
      );
    v_technical_metadata :=
      coalesce(
        v_output -> 'technical_metadata',
        '{}'::jsonb
      );
    v_generator_name :=
      nullif(
        btrim(v_output ->> 'generator_name'),
        ''
      );
    v_generator_version :=
      nullif(
        btrim(v_output ->> 'generator_version'),
        ''
      );

    if jsonb_typeof(v_transformation_spec) <> 'object'
       or jsonb_typeof(v_technical_metadata) <> 'object'
    then
      raise exception
        'Media processing transformation and technical metadata must be objects.';
    end if;

    select variant.id
    into v_variant_id
    from media.variants variant
    where variant.asset_revision_id = v_revision_id
      and variant.source_file_object_id = v_source_file_id
      and variant.derived_file_object_id = v_file_object_id
      and variant.variant_role = v_role;

    v_new_variant := not found;

    if v_new_variant then
      v_variant_id := gen_random_uuid();

      insert into media.variants (
        id,
        asset_id,
        asset_revision_id,
        source_file_object_id,
        derived_file_object_id,
        variant_role,
        transformation_spec,
        technical_metadata,
        generator_name,
        generator_version,
        created_by
      )
      values (
        v_variant_id,
        v_asset_id,
        v_revision_id,
        v_source_file_id,
        v_file_object_id,
        v_role,
        v_transformation_spec,
        v_technical_metadata,
        v_generator_name,
        v_generator_version,
        v_actor_id
      );

      insert into media.events (
        asset_id,
        asset_revision_id,
        variant_id,
        file_object_id,
        event_type,
        actor_id,
        reason,
        resulting_state,
        correlation_id
      )
      values (
        v_asset_id,
        v_revision_id,
        v_variant_id,
        v_file_object_id,
        'variant_registered',
        v_actor_id,
        'Immutable Media processing derivative registered',
        jsonb_build_object(
          'variant_role', v_role,
          'source_file_object_id', v_source_file_id,
          'derived_file_object_id', v_file_object_id,
          'processing_profile', v_profile_version
        ),
        v_correlation_id
      );
    end if;

    select
      selection.variant_id,
      selection.selection_revision
    into
      v_selection_variant_id,
      v_selection_revision
    from media.variant_selections selection
    where selection.asset_revision_id = v_revision_id
      and selection.variant_role = v_role
    for update;

    if not found then
      v_selection_revision := 1;

      insert into media.variant_selections (
        asset_revision_id,
        variant_role,
        variant_id,
        selection_revision,
        selected_by
      )
      values (
        v_revision_id,
        v_role,
        v_variant_id,
        v_selection_revision,
        v_actor_id
      );

      insert into media.events (
        asset_id,
        asset_revision_id,
        variant_id,
        file_object_id,
        event_type,
        actor_id,
        reason,
        resulting_state,
        correlation_id
      )
      values (
        v_asset_id,
        v_revision_id,
        v_variant_id,
        v_file_object_id,
        'variant_activated',
        v_actor_id,
        'Media processing derivative activated',
        jsonb_build_object(
          'variant_role', v_role,
          'selection_revision', v_selection_revision
        ),
        v_correlation_id
      );
    elsif v_selection_variant_id <> v_variant_id then
      v_selection_revision :=
        v_selection_revision + 1;

      update media.variant_selections
      set
        variant_id = v_variant_id,
        selection_revision = v_selection_revision,
        selected_by = v_actor_id,
        selected_at = now(),
        updated_at = now()
      where asset_revision_id = v_revision_id
        and variant_role = v_role;

      insert into media.events (
        asset_id,
        asset_revision_id,
        variant_id,
        file_object_id,
        event_type,
        actor_id,
        reason,
        resulting_state,
        correlation_id
      )
      values (
        v_asset_id,
        v_revision_id,
        v_variant_id,
        v_file_object_id,
        'variant_activated',
        v_actor_id,
        'Media processing derivative activation advanced',
        jsonb_build_object(
          'variant_role', v_role,
          'selection_revision', v_selection_revision
        ),
        v_correlation_id
      );
    end if;

    v_results :=
      v_results ||
      jsonb_build_array(
        jsonb_build_object(
          'variant_role', v_role,
          'file_object_id', v_file_object_id,
          'variant_id', v_variant_id,
          'selection_revision', v_selection_revision,
          'storage_path', v_storage_path,
          'delivery_url', v_delivery_url
        )
      );
  end loop;

  if (
    v_profile_version = 'audio-v1'
    and (
      cardinality(v_seen_roles) <> 2
      or not ('audio_preview' = any(v_seen_roles))
      or not ('waveform_data' = any(v_seen_roles))
    )
  ) or (
    v_profile_version = 'video-v1'
    and (
      cardinality(v_seen_roles) <> 3
      or not ('video_transcode' = any(v_seen_roles))
      or not ('poster_frame' = any(v_seen_roles))
      or not ('thumbnail' = any(v_seen_roles))
    )
  ) then
    raise exception
      'Processing output set is incomplete for profile %.',
      v_profile_version;
  end if;

  return jsonb_build_object(
    'job_id', p_job_id,
    'asset_id', v_asset_id,
    'asset_revision_id', v_revision_id,
    'source_file_object_id', v_source_file_id,
    'profile_version', v_profile_version,
    'correlation_id', v_correlation_id,
    'outputs', v_results
  );
end;
$_$;


ALTER FUNCTION "public"."register_media_processing_outputs_v1"("p_job_id" "uuid", "p_worker_id" "text", "p_outputs" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."register_media_variant"("p_asset_id" "uuid", "p_asset_revision_id" "uuid", "p_source_file_object_id" "uuid", "p_derived_file_object_id" "uuid", "p_variant_role" "text", "p_transformation_spec" "jsonb" DEFAULT '{}'::"jsonb", "p_technical_metadata" "jsonb" DEFAULT '{}'::"jsonb", "p_generator_name" "text" DEFAULT NULL::"text", "p_generator_version" "text" DEFAULT NULL::"text", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("variant_id" "uuid", "correlation_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'media', 'auth'
    AS $$
declare
  v_actor_id uuid;
  v_variant_id uuid := gen_random_uuid();
  v_correlation_id uuid := coalesce(
    p_correlation_id,
    gen_random_uuid()
  );
begin
  v_actor_id :=
    media.require_command_actor('manage_media_assets');

  if p_transformation_spec is null
     or jsonb_typeof(p_transformation_spec) <> 'object'
     or p_technical_metadata is null
     or jsonb_typeof(p_technical_metadata) <> 'object'
  then
    raise exception 'Media variant metadata must be objects';
  end if;

  if not exists (
    select 1
    from media.variant_roles role_row
    where role_row.variant_role = p_variant_role
      and role_row.enabled
  ) then
    raise exception 'Unknown or disabled Media variant role';
  end if;

  if exists (
    select 1
    from media.variants variant
    where variant.asset_revision_id = p_asset_revision_id
      and variant.source_file_object_id =
        p_source_file_object_id
      and variant.derived_file_object_id =
        p_derived_file_object_id
      and variant.variant_role = p_variant_role
  ) then
    raise exception 'Media variant relationship already exists';
  end if;

  insert into media.variants (
    id,
    asset_id,
    asset_revision_id,
    source_file_object_id,
    derived_file_object_id,
    variant_role,
    transformation_spec,
    technical_metadata,
    generator_name,
    generator_version,
    created_by
  )
  values (
    v_variant_id,
    p_asset_id,
    p_asset_revision_id,
    p_source_file_object_id,
    p_derived_file_object_id,
    p_variant_role,
    p_transformation_spec,
    p_technical_metadata,
    nullif(btrim(p_generator_name), ''),
    nullif(btrim(p_generator_version), ''),
    v_actor_id
  );

  insert into media.events (
    asset_id,
    asset_revision_id,
    variant_id,
    file_object_id,
    event_type,
    actor_id,
    reason,
    resulting_state,
    correlation_id
  )
  values (
    p_asset_id,
    p_asset_revision_id,
    v_variant_id,
    p_derived_file_object_id,
    'variant_registered',
    v_actor_id,
    'Immutable Media variant registered',
    jsonb_build_object(
      'variant_role', p_variant_role,
      'source_file_object_id',
        p_source_file_object_id,
      'derived_file_object_id',
        p_derived_file_object_id
    ),
    v_correlation_id
  );

  return query
  select v_variant_id, v_correlation_id;
end;
$$;


ALTER FUNCTION "public"."register_media_variant"("p_asset_id" "uuid", "p_asset_revision_id" "uuid", "p_source_file_object_id" "uuid", "p_derived_file_object_id" "uuid", "p_variant_role" "text", "p_transformation_spec" "jsonb", "p_technical_metadata" "jsonb", "p_generator_name" "text", "p_generator_version" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."registry_get_public_track_playback_providers"("p_track_ids" "uuid"[], "p_provider_key" "text" DEFAULT 'apple_music'::"text") RETURNS TABLE("track_id" "uuid", "provider_key" "text", "provider_track_id" "text", "provider_release_id" "text", "isrc" "text", "upc" "text", "preview_url" "text", "artwork_url" "text", "duration_ms" integer, "storefront" "text", "match_method" "text", "match_confidence" numeric, "last_checked_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select distinct on (l.track_id)
    l.track_id,
    l.provider_key,
    l.provider_track_id,
    l.provider_release_id,
    l.isrc,
    l.upc,
    l.preview_url,
    l.artwork_url,
    l.duration_ms,
    l.storefront,
    l.match_method,
    l.match_confidence,
    l.last_checked_at
  from public.registry_track_provider_links l
  where l.track_id = any(coalesce(p_track_ids, '{}'::uuid[]))
    and l.provider_key = lower(coalesce(nullif(trim(p_provider_key), ''), 'apple_music'))
    and l.match_status = 'matched'
  order by
    l.track_id,
    l.match_confidence desc,
    l.last_checked_at desc,
    l.created_at desc;
$$;


ALTER FUNCTION "public"."registry_get_public_track_playback_providers"("p_track_ids" "uuid"[], "p_provider_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."registry_get_track_provider_links"("p_track_id" "uuid" DEFAULT NULL::"uuid", "p_provider_key" "text" DEFAULT NULL::"text", "p_provider_track_id" "text" DEFAULT NULL::"text", "p_isrc" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 50) RETURNS TABLE("id" "uuid", "track_id" "uuid", "provider_key" "text", "provider_track_id" "text", "provider_release_id" "text", "provider_artist_ids" "text"[], "isrc" "text", "upc" "text", "preview_url" "text", "artwork_url" "text", "duration_ms" integer, "storefront" "text", "match_method" "text", "match_confidence" numeric, "match_status" "text", "raw_payload" "jsonb", "last_checked_at" timestamp with time zone, "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if coalesce(auth.role(), '') <> 'service_role'
     and not public.current_user_has_capability('manage_registry') then
    raise exception 'Not allowed' using errcode = '42501';
  end if;

  return query
  select
    l.id,
    l.track_id,
    l.provider_key,
    l.provider_track_id,
    l.provider_release_id,
    l.provider_artist_ids,
    l.isrc,
    l.upc,
    l.preview_url,
    l.artwork_url,
    l.duration_ms,
    l.storefront,
    l.match_method,
    l.match_confidence,
    l.match_status,
    l.raw_payload,
    l.last_checked_at,
    l.created_at,
    l.updated_at
  from public.registry_track_provider_links l
  where (p_track_id is null or l.track_id = p_track_id)
    and (p_provider_key is null or l.provider_key = lower(p_provider_key))
    and (p_provider_track_id is null or l.provider_track_id = p_provider_track_id)
    and (p_isrc is null or l.isrc = p_isrc)
  order by l.updated_at desc
  limit least(greatest(coalesce(p_limit, 50), 1), 250);
end;
$$;


ALTER FUNCTION "public"."registry_get_track_provider_links"("p_track_id" "uuid", "p_provider_key" "text", "p_provider_track_id" "text", "p_isrc" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."registry_resolve_artist_slug_for_public"("p_slug" "text") RETURNS TABLE("input_slug" "text", "canonical_artist_id" "uuid", "canonical_slug" "text", "canonical_display_name" "text", "resolved_via" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with normalized as (
    select public.wk_slugify_text(p_slug) as slug
  ),
  alias_match as (
    select
      n.slug,
      ra.id,
      ra.slug,
      ra.display_name,
      'alias'::text
    from normalized n
    join public.registry_artist_aliases a
      on lower(a.alias_slug) = n.slug
     and coalesce(a.status, 'active') = 'active'
    join public.registry_artists ra
      on ra.id = a.canonical_artist_id
     and ra.status = 'active'
    limit 1
  ),
  direct_match as (
    select
      n.slug,
      ra.id,
      ra.slug,
      ra.display_name,
      'active_artist'::text
    from normalized n
    join public.registry_artists ra
      on lower(ra.slug) = n.slug
     and ra.status = 'active'
    where not exists (select 1 from alias_match)
    limit 1
  )
  select * from alias_match
  union all
  select * from direct_match;
$$;


ALTER FUNCTION "public"."registry_resolve_artist_slug_for_public"("p_slug" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."registry_upsert_track_provider_link"("p_track_id" "uuid", "p_provider_key" "text", "p_provider_track_id" "text", "p_provider_release_id" "text" DEFAULT NULL::"text", "p_provider_artist_ids" "text"[] DEFAULT NULL::"text"[], "p_isrc" "text" DEFAULT NULL::"text", "p_upc" "text" DEFAULT NULL::"text", "p_preview_url" "text" DEFAULT NULL::"text", "p_artwork_url" "text" DEFAULT NULL::"text", "p_duration_ms" integer DEFAULT NULL::integer, "p_storefront" "text" DEFAULT NULL::"text", "p_match_method" "text" DEFAULT 'unknown'::"text", "p_match_confidence" numeric DEFAULT 0, "p_match_status" "text" DEFAULT 'matched'::"text", "p_raw_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_provider_key text := lower(nullif(trim(coalesce(p_provider_key, '')), ''));
  v_provider_track_id text := nullif(trim(coalesce(p_provider_track_id, '')), '');
  v_link public.registry_track_provider_links%rowtype;
begin
  if coalesce(auth.role(), '') <> 'service_role'
     and not public.current_user_has_capability('manage_registry') then
    raise exception 'Not allowed' using errcode = '42501';
  end if;

  if p_track_id is null then
    raise exception 'track_id is required' using errcode = '22023';
  end if;

  if v_provider_key is null then
    raise exception 'provider_key is required' using errcode = '22023';
  end if;

  if v_provider_track_id is null then
    raise exception 'provider_track_id is required' using errcode = '22023';
  end if;

  if not exists (select 1 from public.registry_tracks where id = p_track_id) then
    raise exception 'Track not found' using errcode = 'P0002';
  end if;

  insert into public.registry_track_provider_links (
    track_id,
    provider_key,
    provider_track_id,
    provider_release_id,
    provider_artist_ids,
    isrc,
    upc,
    preview_url,
    artwork_url,
    duration_ms,
    storefront,
    match_method,
    match_confidence,
    match_status,
    raw_payload,
    last_checked_at,
    updated_at
  )
  values (
    p_track_id,
    v_provider_key,
    v_provider_track_id,
    nullif(trim(coalesce(p_provider_release_id, '')), ''),
    coalesce(p_provider_artist_ids, '{}'::text[]),
    nullif(trim(coalesce(p_isrc, '')), ''),
    nullif(trim(coalesce(p_upc, '')), ''),
    nullif(trim(coalesce(p_preview_url, '')), ''),
    nullif(trim(coalesce(p_artwork_url, '')), ''),
    p_duration_ms,
    lower(nullif(trim(coalesce(p_storefront, '')), '')),
    coalesce(nullif(trim(p_match_method), ''), 'unknown'),
    least(greatest(coalesce(p_match_confidence, 0), 0), 1),
    coalesce(nullif(trim(p_match_status), ''), 'matched'),
    coalesce(p_raw_payload, '{}'::jsonb),
    now(),
    now()
  )
  on conflict (track_id, provider_key, provider_track_id)
  do update set
    provider_release_id = excluded.provider_release_id,
    provider_artist_ids = excluded.provider_artist_ids,
    isrc = excluded.isrc,
    upc = excluded.upc,
    preview_url = excluded.preview_url,
    artwork_url = excluded.artwork_url,
    duration_ms = excluded.duration_ms,
    storefront = excluded.storefront,
    match_method = excluded.match_method,
    match_confidence = excluded.match_confidence,
    match_status = excluded.match_status,
    raw_payload = excluded.raw_payload,
    last_checked_at = now(),
    updated_at = now()
  returning * into v_link;

  return to_jsonb(v_link);
end;
$$;


ALTER FUNCTION "public"."registry_upsert_track_provider_link"("p_track_id" "uuid", "p_provider_key" "text", "p_provider_track_id" "text", "p_provider_release_id" "text", "p_provider_artist_ids" "text"[], "p_isrc" "text", "p_upc" "text", "p_preview_url" "text", "p_artwork_url" "text", "p_duration_ms" integer, "p_storefront" "text", "p_match_method" "text", "p_match_confidence" numeric, "p_match_status" "text", "p_raw_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reject_article_suggestion"("p_suggestion_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS TABLE("suggestion_id" "uuid", "decision_status" "text", "decided_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_suggestion editorial.article_suggestions%rowtype;
  v_thread editorial.article_review_threads%rowtype;
  v_decided_at timestamptz := now();
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  if not editorial.current_user_can_review_article() then
    raise exception 'Permission denied';
  end if;

  select suggestion.*
  into v_suggestion
  from editorial.article_suggestions suggestion
  where suggestion.id = p_suggestion_id
  for update;

  if not found then
    raise exception 'Article suggestion not found';
  end if;

  if v_suggestion.status <> 'open' then
    raise exception 'Only open suggestions can be rejected';
  end if;

  select thread.*
  into v_thread
  from editorial.article_review_threads thread
  where thread.id = v_suggestion.thread_id
  for update;

  update editorial.article_suggestions
  set
    status = 'rejected',
    decided_by = auth.uid(),
    decided_at = v_decided_at,
    decision_note = nullif(btrim(coalesce(p_note, '')), '')
  where id = p_suggestion_id;

  update editorial.article_review_threads
  set
    status = 'resolved',
    resolved_by = auth.uid(),
    resolved_at = v_decided_at
  where id = v_thread.id;

  insert into editorial.article_suggestion_events (
    suggestion_id,
    action,
    note
  )
  values (
    p_suggestion_id,
    'rejected',
    nullif(btrim(coalesce(p_note, '')), '')
  );

  suggestion_id := p_suggestion_id;
  decision_status := 'rejected';
  decided_at := v_decided_at;
  return next;
end;
$$;


ALTER FUNCTION "public"."reject_article_suggestion"("p_suggestion_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_playlist_item"("p_playlist_id" "uuid", "p_playlist_item_id" "uuid", "p_expected_authority_revision" bigint, "p_idempotency_key" "text", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("command_receipt_id" "uuid", "receipt_status" "text", "playlist_id" "uuid", "resource_id" "uuid", "playlist_item_id" "uuid", "authority_revision" bigint, "result_payload" "jsonb", "idempotent_replay" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'editorial', 'platform_private'
    AS $$
declare
  v_playlist public.wk_playlists%rowtype;
  v_item public.wk_playlist_items%rowtype;
  v_resource_id uuid;
  v_offset integer;
  v_count integer;
  v_begin record;
  v_read record;
  v_request jsonb;
  v_result jsonb;
  v_correlation_id uuid := coalesce(p_correlation_id, gen_random_uuid());
begin
  if p_playlist_id is null
     or p_playlist_item_id is null
     or p_expected_authority_revision is null
     or p_expected_authority_revision < 1
  then
    raise exception
      using
        errcode = '22023',
        message = 'Playlist, item, and expected authority revision are required.';
  end if;

  select playlist.*
  into v_playlist
  from public.wk_playlists playlist
  where playlist.id = p_playlist_id
  for update of playlist;

  select binding.resource_id
  into v_resource_id
  from editorial.playlist_resources binding
  where binding.playlist_id = p_playlist_id;

  if not found then
    raise exception using errcode = 'P0002', message = 'Playlist does not exist.';
  end if;

  if not editorial.current_user_can_edit_playlist(v_resource_id) then
    raise exception using errcode = '42501', message = 'Playlist edit permission is required.';
  end if;

  v_request := jsonb_build_object(
    'playlist_id', p_playlist_id,
    'playlist_item_id', p_playlist_item_id,
    'expected_authority_revision', p_expected_authority_revision,
    'correlation_id', v_correlation_id
  );

  select *
  into v_begin
  from platform_private.begin_authenticated_resource_command(
    'playlist.item.remove',
    v_resource_id,
    p_idempotency_key,
    v_request
  );

  if not v_begin.idempotent_replay then
    if v_playlist.authority_revision <> p_expected_authority_revision then
      perform platform_private.reject_resource_command(
        v_begin.command_receipt_id,
        'playlist_revision_changed',
        'The Playlist changed before this item could be removed.',
        jsonb_build_object(
          'playlist_id', p_playlist_id,
          'authority_revision', v_playlist.authority_revision
        )
      );
    else
      select item.*
      into v_item
      from public.wk_playlist_items item
      where item.id = p_playlist_item_id
        and item.playlist_id = p_playlist_id
        and item.lifecycle_state = 'active'
      for update;

      if not found then
        perform platform_private.reject_resource_command(
          v_begin.command_receipt_id,
          'playlist_item_not_active',
          'The Playlist item is missing or no longer active.',
          jsonb_build_object(
            'playlist_id', p_playlist_id,
            'authority_revision', v_playlist.authority_revision
          )
        );
      else
        update public.wk_playlist_items item
        set
          lifecycle_state = 'removed',
          position = null,
          removed_at = now(),
          removed_by = auth.uid()
        where item.id = p_playlist_item_id;

        select count(*), coalesce(max(item.position), 0)
        into v_count, v_offset
        from public.wk_playlist_items item
        where item.playlist_id = p_playlist_id
          and item.lifecycle_state = 'active';

        v_offset := v_offset + v_count + 1;

        if v_count > 0 then
          update public.wk_playlist_items item
          set position = item.position + v_offset
          where item.playlist_id = p_playlist_id
            and item.lifecycle_state = 'active';

          with ordered as (
            select
              item.id,
              row_number() over (
                order by item.position, item.id
              )::integer as new_position
            from public.wk_playlist_items item
            where item.playlist_id = p_playlist_id
              and item.lifecycle_state = 'active'
          )
          update public.wk_playlist_items item
          set position = ordered.new_position
          from ordered
          where item.id = ordered.id;
        end if;

        update public.wk_playlists playlist
        set authority_revision = playlist.authority_revision + 1
        where playlist.id = p_playlist_id
        returning playlist.authority_revision
        into v_playlist.authority_revision;

        v_result := jsonb_build_object(
          'playlist_id', p_playlist_id,
          'playlist_item_id', p_playlist_item_id,
          'active_item_count', v_count,
          'authority_revision', v_playlist.authority_revision,
          'correlation_id', v_correlation_id
        );

        perform platform_private.complete_resource_command(
          v_begin.command_receipt_id,
          v_result
        );
      end if;
    end if;
  end if;

  select *
  into v_read
  from platform_private.read_authenticated_resource_command_result(
    v_begin.command_receipt_id,
    v_begin.idempotent_replay
  );

  command_receipt_id := v_read.command_receipt_id;
  receipt_status := v_read.receipt_status;
  playlist_id := p_playlist_id;
  resource_id := v_read.resource_id;
  playlist_item_id := p_playlist_item_id;
  authority_revision := nullif(v_read.result_payload ->> 'authority_revision', '')::bigint;
  result_payload := v_read.result_payload;
  idempotent_replay := v_read.idempotent_replay;
  return next;
end;
$$;


ALTER FUNCTION "public"."remove_playlist_item"("p_playlist_id" "uuid", "p_playlist_item_id" "uuid", "p_expected_authority_revision" bigint, "p_idempotency_key" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_playlist_item_with_intake_slots"("p_playlist_id" "uuid", "p_playlist_item_id" "uuid", "p_expected_authority_revision" bigint, "p_idempotency_key" "text", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'auth', 'public', 'editorial', 'platform_private'
    AS $$
declare
  v_playlist public.wk_playlists%rowtype;
  v_resource_id uuid;
  v_item public.wk_playlist_items%rowtype;
  v_begin record;
  v_read record;
  v_request jsonb;
  v_result jsonb;
  v_correlation_id uuid := coalesce(
    p_correlation_id,
    gen_random_uuid()
  );
begin
  if p_playlist_id is null
     or p_playlist_item_id is null
     or p_expected_authority_revision is null
     or p_expected_authority_revision < 1
  then
    raise exception
      'Playlist, item, and expected revision are required.';
  end if;

  select playlist.*
  into v_playlist
  from public.wk_playlists playlist
  where playlist.id = p_playlist_id
  for update of playlist;

  select binding.resource_id
  into v_resource_id
  from editorial.playlist_resources binding
  where binding.playlist_id = p_playlist_id;

  if not found then
    raise exception
      using errcode = 'P0002', message = 'Playlist does not exist.';
  end if;

  if not editorial.current_user_can_edit_playlist(v_resource_id) then
    raise exception
      using errcode = '42501', message = 'Playlist edit permission is required.';
  end if;

  v_request := jsonb_build_object(
    'playlist_id', p_playlist_id,
    'playlist_item_id', p_playlist_item_id,
    'expected_authority_revision',
      p_expected_authority_revision,
    'correlation_id', v_correlation_id
  );

  select *
  into v_begin
  from platform_private.begin_authenticated_resource_command(
    'playlist.item.remove',
    v_resource_id,
    p_idempotency_key,
    v_request
  );

  if v_begin.idempotent_replay then
    select *
    into v_read
    from platform_private.read_authenticated_resource_command_result(
      v_begin.command_receipt_id,
      true
    );
    return v_read.result_payload;
  end if;

  if v_playlist.authority_revision <>
     p_expected_authority_revision
  then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'playlist_revision_changed',
      'The Playlist changed before this item could be removed.',
      jsonb_build_object(
        'playlist_id', p_playlist_id,
        'authority_revision', v_playlist.authority_revision
      )
    );
  else
    select item.*
    into v_item
    from public.wk_playlist_items item
    where item.id = p_playlist_item_id
      and item.playlist_id = p_playlist_id
      and item.lifecycle_state = 'active'
    for update;

    if not found then
      perform platform_private.reject_resource_command(
        v_begin.command_receipt_id,
        'playlist_item_not_active',
        'The Playlist item is missing or no longer active.',
        jsonb_build_object(
          'playlist_id', p_playlist_id,
          'authority_revision', v_playlist.authority_revision
        )
      );
    else
      update public.wk_playlist_items item
      set
        lifecycle_state = 'removed',
        position = null,
        removed_at = now(),
        removed_by = auth.uid()
      where item.id = p_playlist_item_id;

      perform editorial.resequence_playlist_with_registry_intake(
        p_playlist_id
      );

      update public.wk_playlists playlist
      set authority_revision =
        playlist.authority_revision + 1
      where playlist.id = p_playlist_id
      returning playlist.authority_revision
      into v_playlist.authority_revision;

      v_result := jsonb_build_object(
        'playlist_id', p_playlist_id,
        'playlist_item_id', p_playlist_item_id,
        'authority_revision', v_playlist.authority_revision,
        'correlation_id', v_correlation_id
      );

      perform platform_private.complete_resource_command(
        v_begin.command_receipt_id,
        v_result
      );
    end if;
  end if;

  select *
  into v_read
  from platform_private.read_authenticated_resource_command_result(
    v_begin.command_receipt_id,
    false
  );

  return v_read.result_payload;
end;
$$;


