CREATE OR REPLACE FUNCTION "public"."remove_publishing_item_assignee"("p_item_id" "uuid", "p_expected_record_version" bigint, "p_user_id" "uuid", "p_assignment_role" "text", "p_note" "text" DEFAULT NULL::"text") RETURNS TABLE("item_id" "uuid", "record_version" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_item editorial.publishing_items%rowtype;
  v_updated editorial.publishing_items%rowtype;
begin
  if auth.uid() is null
     or not editorial.current_user_can_manage_publishing()
  then
    raise exception
      using
        errcode = '42501',
        message = 'Permission denied';
  end if;

  select item.*
  into v_item
  from editorial.publishing_items item
  where item.id = p_item_id
  for update;

  if not found then
    raise exception 'Publishing item not found';
  end if;

  if v_item.record_version
     <> p_expected_record_version
  then
    raise exception
      'STALE_PUBLISHING_ITEM_VERSION: expected %, current %',
      p_expected_record_version,
      v_item.record_version;
  end if;

  delete from editorial.publishing_item_assignees
    as assignee
  where assignee.item_id = p_item_id
    and assignee.user_id = p_user_id
    and assignee.assignment_role =
      p_assignment_role;

  if not found then
    raise exception
      'Publishing assignment not found';
  end if;

  update editorial.publishing_items item
  set
    record_version =
      item.record_version + 1,
    updated_by = auth.uid(),
    updated_at = now()
  where item.id = p_item_id
  returning item.*
  into v_updated;

  insert into editorial.publishing_item_events (
    item_id,
    action,
    prior_record_version,
    resulting_record_version,
    prior_values,
    resulting_values,
    note,
    metadata,
    actor_id
  )
  values (
    p_item_id,
    'assignee_removed',
    v_item.record_version,
    v_updated.record_version,
    editorial.publishing_item_snapshot(
      v_item
    ),
    editorial.publishing_item_snapshot(
      v_updated
    ),
    nullif(btrim(p_note), ''),
    jsonb_build_object(
      'userId',
      p_user_id,
      'assignmentRole',
      p_assignment_role
    ),
    auth.uid()
  );

  item_id := v_updated.id;
  record_version :=
    v_updated.record_version;

  return next;
end;
$$;


