CREATE OR REPLACE FUNCTION "public"."renew_media_processing_lease_v1"("p_job_id" "uuid", "p_worker_id" "text", "p_lease_seconds" integer DEFAULT 3600) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'auth', 'platform_private'
    AS $_$
declare
  v_expires_at timestamptz;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception
      using
        errcode = '42501',
        message = 'Service-role access is required.';
  end if;

  if p_job_id is null
     or p_worker_id is null
     or p_worker_id !~
       '^[A-Za-z0-9][A-Za-z0-9._:-]{2,127}$'
  then
    raise exception
      using
        errcode = '22023',
        message = 'job_id and valid worker_id are required.';
  end if;

  if p_lease_seconds not between 60 and 3600 then
    raise exception
      using
        errcode = '22023',
        message = 'lease_seconds must be between 60 and 3600.';
  end if;

  update platform_private.jobs job
  set
    lease_expires_at =
      now() +
      make_interval(
        secs => p_lease_seconds
      )
  where job.id = p_job_id
    and job.command_type = 'media.process_revision'
    and job.job_type = 'media.process_revision'
    and job.status = 'running'
    and job.locked_by = p_worker_id
    and job.lease_expires_at is not null
    and job.lease_expires_at > now()
  returning job.lease_expires_at
  into v_expires_at;

  if v_expires_at is null then
    raise exception
      using
        errcode = '55000',
        message =
          'The Media processing job is not actively leased to this worker.';
  end if;

  return v_expires_at;
end;
$_$;


ALTER FUNCTION "public"."renew_media_processing_lease_v1"("p_job_id" "uuid", "p_worker_id" "text", "p_lease_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reopen_correction_case"("p_case_resource_id" "uuid", "p_expected_case_revision" bigint, "p_reason" "text", "p_idempotency_key" "text", "p_correlation_id" "uuid") RETURNS TABLE("command_receipt_id" "uuid", "receipt_status" "text", "case_resource_id" "uuid", "case_revision" bigint, "result_payload" "jsonb", "idempotent_replay" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'editorial', 'platform_private'
    AS $$
declare
  v_actor uuid;
  v_begin record;
  v_case editorial.correction_cases%rowtype;
  v_outcome text;
  v_resulting_state text;
  v_result jsonb;
begin
  v_actor :=
    platform_private.assert_correction_capability(
      'decide_corrections'
    );

  if p_case_resource_id is null
     or p_expected_case_revision < 1
     or p_correlation_id is null
     or nullif(
       btrim(p_reason),
       ''
     ) is null
  then
    raise exception
      using
        errcode = '22023',
        message = 'Case, revision, reason, and correlation identity are required.';
  end if;

  select *
  into v_begin
  from platform_private.begin_resource_command(
    'correction.case.reopen',
    p_case_resource_id,
    p_idempotency_key,
    jsonb_build_object(
      'expected_case_revision',
      p_expected_case_revision,
      'reason',
      btrim(p_reason),
      'correlation_id',
      p_correlation_id
    )
  );

  if v_begin.idempotent_replay then
    return query
    select *
    from platform_private.read_correction_command_result(
      v_begin.command_receipt_id,
      true
    );
    return;
  end if;

  select correction_case.*
  into v_case
  from editorial.correction_cases correction_case
  where correction_case.resource_id =
    p_case_resource_id
  for update;

  if not found then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'case_not_found',
      'The correction case does not exist.',
      jsonb_build_object(
        'case_revision',
        null
      )
    );
  elsif v_case.current_revision <>
        p_expected_case_revision
  then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'case_revision_changed',
      'The correction case revision changed.',
      jsonb_build_object(
        'case_revision',
        v_case.current_revision,
        'case_state',
        v_case.case_state
      )
    );
  elsif v_case.case_state <> 'closed' then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'invalid_transition',
      'Only closed correction cases may reopen.',
      jsonb_build_object(
        'case_revision',
        v_case.current_revision,
        'case_state',
        v_case.case_state
      )
    );
  elsif v_case.assigned_investigator_id is null then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'investigator_required',
      'A reopened correction case must retain an investigator.',
      jsonb_build_object(
        'case_revision',
        v_case.current_revision,
        'case_state',
        v_case.case_state
      )
    );
  else
    select decision.outcome
    into v_outcome
    from editorial.correction_decisions decision
    where decision.id =
        v_case.current_decision_id
      and decision.case_resource_id =
        p_case_resource_id;

    if not found then
      perform platform_private.reject_resource_command(
        v_begin.command_receipt_id,
        'decision_changed',
        'The current correction decision changed.',
        jsonb_build_object(
          'case_revision',
          v_case.current_revision,
          'case_state',
          v_case.case_state
        )
      );
    else
      v_resulting_state :=
        case
          when v_outcome =
            'correction_required'
            and v_case.current_application_id
              is not null
          then 'applied'
          else 'investigating'
        end;

      update editorial.correction_cases
      set
        case_state =
          v_resulting_state,
        current_revision =
          v_case.current_revision + 1,
        current_application_id =
          case
            when v_resulting_state =
              'applied'
            then v_case.current_application_id
            else null
          end,
        submitted_for_decision_by =
          case
            when v_resulting_state =
              'applied'
            then v_case.submitted_for_decision_by
            else null
          end,
        submitted_for_decision_at =
          case
            when v_resulting_state =
              'applied'
            then v_case.submitted_for_decision_at
            else null
          end,
        evidence_ready =
          case
            when v_resulting_state =
              'applied'
            then v_case.evidence_ready
            else false
          end,
        public_note_disposition = null,
        public_note_no_note_reason = null,
        contributor_follow_up_disposition = null,
        contributor_follow_up_reason = null,
        contributor_follow_up_job_id = null,
        contributor_follow_up_requested_at = null,
        closed_reason = null,
        closed_by = null,
        closed_at = null,
        updated_by = v_actor,
        updated_at = now()
      where resource_id =
        p_case_resource_id;

      perform platform_private.append_correction_public_event(
        p_case_resource_id,
        'case_reopened',
        v_case.current_revision,
        v_case.current_revision + 1,
        v_case.case_state,
        v_resulting_state,
        v_actor,
        btrim(p_reason),
        v_case.current_decision_id,
        v_case.current_application_id,
        null,
        null,
        v_begin.command_receipt_id,
        p_correlation_id,
        jsonb_build_object(
          'decision_outcome',
          v_outcome,
          'prior_application_id',
          v_case.current_application_id,
          'current_application_retained',
          v_resulting_state = 'applied',
          'prior_public_note_disposition',
          v_case.public_note_disposition,
          'prior_contributor_follow_up_disposition',
          v_case.contributor_follow_up_disposition,
          'historical_notes_preserved',
          true
        )
      );

      v_result := jsonb_build_object(
        'case_resource_id',
        p_case_resource_id,
        'case_revision',
        v_case.current_revision + 1,
        'case_state',
        v_resulting_state,
        'current_decision_id',
        v_case.current_decision_id,
        'current_application_id',
        case
          when v_resulting_state =
            'applied'
          then v_case.current_application_id
          else null
        end,
        'historical_notes_preserved',
        true
      );

      perform platform_private.complete_resource_command(
        v_begin.command_receipt_id,
        v_result
      );
    end if;
  end if;

  return query
  select *
  from platform_private.read_correction_command_result(
    v_begin.command_receipt_id,
    false
  );
end;
$$;


ALTER FUNCTION "public"."reopen_correction_case"("p_case_resource_id" "uuid", "p_expected_case_revision" bigint, "p_reason" "text", "p_idempotency_key" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reorder_playlist_items"("p_playlist_id" "uuid", "p_expected_authority_revision" bigint, "p_ordered_item_ids" "uuid"[], "p_idempotency_key" "text", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("command_receipt_id" "uuid", "receipt_status" "text", "playlist_id" "uuid", "resource_id" "uuid", "authority_revision" bigint, "result_payload" "jsonb", "idempotent_replay" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'editorial', 'platform_private'
    AS $$
declare
  v_playlist public.wk_playlists%rowtype;
  v_resource_id uuid;
  v_active_count integer;
  v_distinct_count integer;
  v_offset integer;
  v_current_order uuid[];
  v_begin record;
  v_read record;
  v_request jsonb;
  v_result jsonb;
  v_correlation_id uuid := coalesce(p_correlation_id, gen_random_uuid());
begin
  if p_playlist_id is null
     or p_expected_authority_revision is null
     or p_expected_authority_revision < 1
  then
    raise exception
      using
        errcode = '22023',
        message = 'Playlist and expected authority revision are required.';
  end if;

  if p_ordered_item_ids is null then
    raise exception
      using errcode = '22023', message = 'Complete ordered Playlist item identity is required.';
  end if;

  select playlist.*
  into v_playlist
  from public.wk_playlists playlist
  where playlist.id = p_playlist_id
  for update of playlist;

  select binding.resource_id
  into v_resource_id
  from editorial.playlist_resources binding
  where binding.playlist_id = p_playlist_id;

  if not found then
    raise exception using errcode = 'P0002', message = 'Playlist does not exist.';
  end if;

  if not editorial.current_user_can_edit_playlist(v_resource_id) then
    raise exception using errcode = '42501', message = 'Playlist edit permission is required.';
  end if;

  v_request := jsonb_build_object(
    'playlist_id', p_playlist_id,
    'expected_authority_revision', p_expected_authority_revision,
    'ordered_item_ids', to_jsonb(p_ordered_item_ids),
    'correlation_id', v_correlation_id
  );

  select *
  into v_begin
  from platform_private.begin_authenticated_resource_command(
    'playlist.items.reorder',
    v_resource_id,
    p_idempotency_key,
    v_request
  );

  if not v_begin.idempotent_replay then
    if v_playlist.authority_revision <> p_expected_authority_revision then
      perform platform_private.reject_resource_command(
        v_begin.command_receipt_id,
        'playlist_revision_changed',
        'The Playlist changed before this order could be applied.',
        jsonb_build_object(
          'playlist_id', p_playlist_id,
          'authority_revision', v_playlist.authority_revision
        )
      );
    else
      select
        count(*),
        coalesce(max(item.position), 0),
        coalesce(array_agg(item.id order by item.position), '{}'::uuid[])
      into
        v_active_count,
        v_offset,
        v_current_order
      from public.wk_playlist_items item
      where item.playlist_id = p_playlist_id
        and item.lifecycle_state = 'active';

      select count(distinct item_id)
      into v_distinct_count
      from unnest(p_ordered_item_ids) item_id;

      if cardinality(p_ordered_item_ids) <> v_active_count
         or v_distinct_count <> v_active_count
         or exists (
           select 1
           from unnest(p_ordered_item_ids) requested(item_id)
           where not exists (
             select 1
             from public.wk_playlist_items item
             where item.id = requested.item_id
               and item.playlist_id = p_playlist_id
               and item.lifecycle_state = 'active'
           )
         )
      then
        perform platform_private.reject_resource_command(
          v_begin.command_receipt_id,
          'invalid_playlist_order',
          'Reorder must contain every active Playlist item exactly once.',
          jsonb_build_object(
            'playlist_id', p_playlist_id,
            'authority_revision', v_playlist.authority_revision,
            'active_item_count', v_active_count
          )
        );
      elsif v_current_order = p_ordered_item_ids then
        v_result := jsonb_build_object(
          'playlist_id', p_playlist_id,
          'authority_revision', v_playlist.authority_revision,
          'active_item_count', v_active_count,
          'changed', false,
          'correlation_id', v_correlation_id
        );

        perform platform_private.complete_resource_command(
          v_begin.command_receipt_id,
          v_result
        );
      else
        v_offset := v_offset + v_active_count + 1;

        update public.wk_playlist_items item
        set position = item.position + v_offset
        where item.playlist_id = p_playlist_id
          and item.lifecycle_state = 'active';

        with requested as (
          select
            requested.item_id,
            requested.ordinality::integer as new_position
          from unnest(p_ordered_item_ids)
            with ordinality as requested(item_id, ordinality)
        )
        update public.wk_playlist_items item
        set position = requested.new_position
        from requested
        where item.id = requested.item_id
          and item.playlist_id = p_playlist_id
          and item.lifecycle_state = 'active';

        if exists (
          select 1
          from (
            select
              item.position,
              row_number() over (
                order by item.position
              )::integer as expected_position
            from public.wk_playlist_items item
            where item.playlist_id = p_playlist_id
              and item.lifecycle_state = 'active'
          ) ordered
          where ordered.position <> ordered.expected_position
        ) then
          raise exception 'Playlist reorder did not converge to a continuous position sequence.';
        end if;

        update public.wk_playlists playlist
        set authority_revision = playlist.authority_revision + 1
        where playlist.id = p_playlist_id
        returning playlist.authority_revision
        into v_playlist.authority_revision;

        v_result := jsonb_build_object(
          'playlist_id', p_playlist_id,
          'authority_revision', v_playlist.authority_revision,
          'active_item_count', v_active_count,
          'changed', true,
          'correlation_id', v_correlation_id
        );

        perform platform_private.complete_resource_command(
          v_begin.command_receipt_id,
          v_result
        );
      end if;
    end if;
  end if;

  select *
  into v_read
  from platform_private.read_authenticated_resource_command_result(
    v_begin.command_receipt_id,
    v_begin.idempotent_replay
  );

  command_receipt_id := v_read.command_receipt_id;
  receipt_status := v_read.receipt_status;
  playlist_id := p_playlist_id;
  resource_id := v_read.resource_id;
  authority_revision := nullif(v_read.result_payload ->> 'authority_revision', '')::bigint;
  result_payload := v_read.result_payload;
  idempotent_replay := v_read.idempotent_replay;
  return next;
end;
$$;


ALTER FUNCTION "public"."reorder_playlist_items"("p_playlist_id" "uuid", "p_expected_authority_revision" bigint, "p_ordered_item_ids" "uuid"[], "p_idempotency_key" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reorder_playlist_items_with_intake_slots"("p_playlist_id" "uuid", "p_expected_authority_revision" bigint, "p_ordered_item_ids" "uuid"[], "p_idempotency_key" "text", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial', 'platform_private'
    AS $$
declare
  v_playlist public.wk_playlists%rowtype;
  v_resource_id uuid;
  v_begin record;
  v_read record;
  v_request jsonb;
  v_result jsonb;
  v_current_order uuid[];
  v_available_positions integer[];
  v_active_count integer;
  v_distinct_count integer;
  v_offset integer;
  v_correlation_id uuid := coalesce(
    p_correlation_id,
    gen_random_uuid()
  );
begin
  if p_playlist_id is null
     or p_expected_authority_revision is null
     or p_expected_authority_revision < 1
     or p_ordered_item_ids is null
  then
    raise exception
      'Playlist, expected revision, and complete track order are required.';
  end if;

  select playlist.*
  into v_playlist
  from public.wk_playlists playlist
  where playlist.id = p_playlist_id
  for update of playlist;

  select binding.resource_id
  into v_resource_id
  from editorial.playlist_resources binding
  where binding.playlist_id = p_playlist_id;

  if not found then
    raise exception
      using errcode = 'P0002', message = 'Playlist does not exist.';
  end if;

  if not editorial.current_user_can_edit_playlist(v_resource_id) then
    raise exception
      using errcode = '42501', message = 'Playlist edit permission is required.';
  end if;

  select
    count(*)::integer,
    coalesce(
      array_agg(item.id order by item.position),
      '{}'::uuid[]
    ),
    coalesce(
      array_agg(item.position order by item.position),
      '{}'::integer[]
    )
  into
    v_active_count,
    v_current_order,
    v_available_positions
  from public.wk_playlist_items item
  where item.playlist_id = p_playlist_id
    and item.lifecycle_state = 'active';

  select count(distinct item_id)
  into v_distinct_count
  from unnest(p_ordered_item_ids) item_id;

  if cardinality(p_ordered_item_ids) <> v_active_count
     or v_distinct_count <> v_active_count
     or exists (
       select 1
       from unnest(p_ordered_item_ids) requested(item_id)
       where not exists (
         select 1
         from public.wk_playlist_items item
         where item.id = requested.item_id
           and item.playlist_id = p_playlist_id
           and item.lifecycle_state = 'active'
       )
     )
  then
    raise exception
      'Reorder must contain every active Playlist track exactly once.';
  end if;

  v_request := jsonb_build_object(
    'playlist_id', p_playlist_id,
    'expected_authority_revision',
      p_expected_authority_revision,
    'ordered_item_ids', to_jsonb(p_ordered_item_ids),
    'correlation_id', v_correlation_id
  );

  select *
  into v_begin
  from platform_private.begin_authenticated_resource_command(
    'playlist.items.reorder',
    v_resource_id,
    p_idempotency_key,
    v_request
  );

  if v_begin.idempotent_replay then
    select *
    into v_read
    from platform_private.read_authenticated_resource_command_result(
      v_begin.command_receipt_id,
      true
    );
    return v_read.result_payload;
  end if;

  if v_playlist.authority_revision <>
     p_expected_authority_revision
  then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'playlist_revision_changed',
      'The Playlist changed before this order could be applied.',
      jsonb_build_object(
        'playlist_id', p_playlist_id,
        'authority_revision', v_playlist.authority_revision
      )
    );
  elsif v_current_order = p_ordered_item_ids then
    v_result := jsonb_build_object(
      'playlist_id', p_playlist_id,
      'authority_revision', v_playlist.authority_revision,
      'changed', false,
      'correlation_id', v_correlation_id
    );

    perform platform_private.complete_resource_command(
      v_begin.command_receipt_id,
      v_result
    );
  else
    select
      greatest(
        coalesce(max(item.position), 0),
        coalesce(
          (
            select max(suggestion.reserved_position)
            from public.registry_provider_track_suggestions suggestion
            where suggestion.source_playlist_id = p_playlist_id
              and suggestion.status = 'needs_review'
              and suggestion.source_playlist_item_id is null
              and suggestion.canonical_track_id is null
          ),
          0
        )
      )
      + v_active_count
      + 100
    into v_offset
    from public.wk_playlist_items item
    where item.playlist_id = p_playlist_id
      and item.lifecycle_state = 'active';

    update public.wk_playlist_items item
    set position = item.position + v_offset
    where item.playlist_id = p_playlist_id
      and item.lifecycle_state = 'active';

    with requested as (
      select
        requested.item_id,
        requested.ordinality::integer as ordinal
      from unnest(p_ordered_item_ids)
        with ordinality as requested(item_id, ordinality)
    )
    update public.wk_playlist_items item
    set position = v_available_positions[requested.ordinal]
    from requested
    where item.id = requested.item_id;

    update public.wk_playlists playlist
    set authority_revision =
      playlist.authority_revision + 1
    where playlist.id = p_playlist_id
    returning playlist.authority_revision
    into v_playlist.authority_revision;

    v_result := jsonb_build_object(
      'playlist_id', p_playlist_id,
      'authority_revision', v_playlist.authority_revision,
      'changed', true,
      'correlation_id', v_correlation_id
    );

    perform platform_private.complete_resource_command(
      v_begin.command_receipt_id,
      v_result
    );
  end if;

  select *
  into v_read
  from platform_private.read_authenticated_resource_command_result(
    v_begin.command_receipt_id,
    false
  );

  return v_read.result_payload;
end;
$$;


ALTER FUNCTION "public"."reorder_playlist_items_with_intake_slots"("p_playlist_id" "uuid", "p_expected_authority_revision" bigint, "p_ordered_item_ids" "uuid"[], "p_idempotency_key" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."replace_article_version_citations"("p_article_version_id" "uuid", "p_attachments" "jsonb", "p_expected_citation_revision" bigint, "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial', 'auth'
    AS $$
declare
  v_actor_id uuid;
  v_article_version editorial.article_versions%rowtype;
  v_resource editorial.resources%rowtype;
  v_revision editorial.article_version_trust_revisions%rowtype;
  v_requested_count integer;
  v_resulting_revision bigint;
  v_attachments jsonb;
begin
  v_actor_id :=
    editorial.assert_citation_command_actor();

  if p_attachments is null
     or jsonb_typeof(p_attachments) <> 'array' then
    raise exception
      'Citation attachments must be a JSON array';
  end if;

  if p_expected_citation_revision is null
     or p_expected_citation_revision < 1 then
    raise exception
      'Expected Citation revision must be one or greater';
  end if;

  select *
  into v_article_version
  from editorial.article_versions article_version
  where article_version.id = p_article_version_id;

  if not found then
    raise exception
      'Article version was not found';
  end if;

  select *
  into v_resource
  from editorial.resources resource
  where resource.id = v_article_version.resource_id
    and resource.resource_kind = 'article';

  if not found then
    raise exception
      'Article resource was not found';
  end if;

  if auth.role() <> 'service_role'
     and not editorial.current_user_can_edit_article(
       v_resource.id
     ) then
    raise exception
      'You do not have authority to edit this Article';
  end if;

  insert into editorial.article_version_trust_revisions (
    article_version_id,
    citation_revision,
    credit_revision,
    updated_by,
    updated_at
  )
  values (
    p_article_version_id,
    1,
    1,
    v_actor_id,
    now()
  )
  on conflict (article_version_id) do nothing;

  select *
  into v_revision
  from editorial.article_version_trust_revisions revision
  where revision.article_version_id =
    p_article_version_id
  for update;

  if v_revision.citation_revision <>
       p_expected_citation_revision then
    raise exception
      'Citation revision conflict. Expected %, found %',
      p_expected_citation_revision,
      v_revision.citation_revision;
  end if;

  v_requested_count := jsonb_array_length(p_attachments);

  if exists (
    select 1
    from jsonb_array_elements(p_attachments) item(value)
    where jsonb_typeof(item.value) <> 'object'
       or not item.value ? 'citation_id'
       or not item.value ? 'citation_purpose'
       or not item.value ? 'target_anchor_type'
       or not item.value ? 'target_anchor_data'
       or not item.value ? 'display_order'
       or not item.value ? 'public_safe'
       or jsonb_typeof(
            item.value -> 'target_anchor_data'
          ) <> 'object'
       or jsonb_typeof(
            item.value -> 'public_safe'
          ) <> 'boolean'
       or jsonb_typeof(
            item.value -> 'display_order'
          ) <> 'number'
  ) then
    raise exception
      'Every Citation attachment requires a complete valid object';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(p_attachments) as requested(
      citation_id uuid,
      citation_purpose text,
      target_anchor_type text,
      target_anchor_data jsonb,
      display_order integer,
      public_safe boolean
    )
    where requested.citation_id is null
       or requested.citation_purpose is null
       or requested.target_anchor_type is null
       or requested.target_anchor_data is null
       or requested.display_order is null
       or requested.public_safe is null
       or requested.display_order < 0
       or requested.citation_purpose not in (
            'supports',
            'challenges',
            'contextualizes',
            'quotes',
            'documents',
            'methodology',
            'other'
          )
  ) then
    raise exception
      'Citation attachment contains an invalid required value';
  end if;

  if exists (
    select 1
    from (
      select
        requested.citation_id,
        count(*) as duplicate_count
      from jsonb_to_recordset(p_attachments) as requested(
        citation_id uuid,
        citation_purpose text,
        target_anchor_type text,
        target_anchor_data jsonb,
        display_order integer,
        public_safe boolean
      )
      group by requested.citation_id
      having count(*) > 1
    ) duplicate_citations
  ) then
    raise exception
      'Citation attachments contain duplicate Citation identities';
  end if;

  if exists (
    select 1
    from (
      select
        requested.display_order,
        count(*) as duplicate_count
      from jsonb_to_recordset(p_attachments) as requested(
        citation_id uuid,
        citation_purpose text,
        target_anchor_type text,
        target_anchor_data jsonb,
        display_order integer,
        public_safe boolean
      )
      group by requested.display_order
      having count(*) > 1
    ) duplicate_orders
  ) then
    raise exception
      'Citation attachments contain duplicate display orders';
  end if;

  if v_requested_count > 0
     and (
       (
         select min(requested.display_order)
         from jsonb_to_recordset(p_attachments) as requested(
           citation_id uuid,
           citation_purpose text,
           target_anchor_type text,
           target_anchor_data jsonb,
           display_order integer,
           public_safe boolean
         )
       ) <> 0
       or
       (
         select max(requested.display_order)
         from jsonb_to_recordset(p_attachments) as requested(
           citation_id uuid,
           citation_purpose text,
           target_anchor_type text,
           target_anchor_data jsonb,
           display_order integer,
           public_safe boolean
         )
       ) <> v_requested_count - 1
     ) then
    raise exception
      'Citation display order must be zero-based and contiguous';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(p_attachments) as requested(
      citation_id uuid,
      citation_purpose text,
      target_anchor_type text,
      target_anchor_data jsonb,
      display_order integer,
      public_safe boolean
    )
    where not exists (
      select 1
      from editorial.citations citation
      where citation.id = requested.citation_id
        and citation.citation_state = 'active'
    )
  ) then
    raise exception
      'Every attached Citation must exist and be active';
  end if;

  perform editorial.validate_citation_target_anchor(
    requested.target_anchor_type,
    requested.target_anchor_data
  )
  from jsonb_to_recordset(p_attachments) as requested(
    citation_id uuid,
    citation_purpose text,
    target_anchor_type text,
    target_anchor_data jsonb,
    display_order integer,
    public_safe boolean
  );

  if exists (
    select 1
    from jsonb_to_recordset(p_attachments) as requested(
      citation_id uuid,
      citation_purpose text,
      target_anchor_type text,
      target_anchor_data jsonb,
      display_order integer,
      public_safe boolean
    )
    join editorial.citations citation
      on citation.id = requested.citation_id
    join editorial.sources source
      on source.id = citation.source_id
    where requested.public_safe
      and (
        not citation.public_safe
        or source.source_state <> 'active'
        or source.review_status <> 'approved'
        or source.current_approved_version_id
             is distinct from
             citation.source_version_id
        or source.exposure_class not in (
             'public',
             'public_redacted'
           )
      )
  ) then
    raise exception
      'A requested public Citation attachment is not publicly eligible';
  end if;

  delete from editorial.resource_citations attachment
  where attachment.target_version_id =
    p_article_version_id;

  insert into editorial.resource_citations (
    resource_id,
    resource_kind,
    target_version_type,
    target_version_id,
    citation_id,
    citation_purpose,
    target_anchor_type,
    target_anchor_data,
    display_order,
    public_safe,
    created_by
  )
  select
    v_resource.id,
    'article',
    'article_version',
    p_article_version_id,
    requested.citation_id,
    requested.citation_purpose,
    requested.target_anchor_type,
    requested.target_anchor_data,
    requested.display_order,
    requested.public_safe,
    v_actor_id
  from jsonb_to_recordset(p_attachments) as requested(
    citation_id uuid,
    citation_purpose text,
    target_anchor_type text,
    target_anchor_data jsonb,
    display_order integer,
    public_safe boolean
  )
  order by requested.display_order;

  v_resulting_revision :=
    v_revision.citation_revision + 1;

  update editorial.article_version_trust_revisions
  set
    citation_revision = v_resulting_revision,
    updated_by = v_actor_id,
    updated_at = now()
  where article_version_id = p_article_version_id;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'attachment_id',
          attachment.id,
        'citation_id',
          attachment.citation_id,
        'citation_purpose',
          attachment.citation_purpose,
        'target_anchor_type',
          attachment.target_anchor_type,
        'target_anchor_data',
          attachment.target_anchor_data,
        'display_order',
          attachment.display_order,
        'public_safe',
          attachment.public_safe
      )
      order by attachment.display_order
    ),
    '[]'::jsonb
  )
  into v_attachments
  from editorial.resource_citations attachment
  where attachment.target_version_id =
    p_article_version_id;

  return jsonb_build_object(
    'article_version_id',
      p_article_version_id,
    'citation_revision',
      v_resulting_revision,
    'correlation_id',
      p_correlation_id,
    'attachments',
      v_attachments
  );
end;
$$;


ALTER FUNCTION "public"."replace_article_version_citations"("p_article_version_id" "uuid", "p_attachments" "jsonb", "p_expected_citation_revision" bigint, "p_correlation_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."replace_article_version_citations"("p_article_version_id" "uuid", "p_attachments" "jsonb", "p_expected_citation_revision" bigint, "p_correlation_id" "uuid") IS 'Atomically replaces the complete ordered Citation set for one Article version.';



CREATE OR REPLACE FUNCTION "public"."replace_article_version_credits"("p_article_version_id" "uuid", "p_attachments" "jsonb", "p_expected_credit_revision" bigint, "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial', 'auth'
    AS $$
declare
  v_actor_id uuid;
  v_article_version editorial.article_versions%rowtype;
  v_resource editorial.resources%rowtype;
  v_revision editorial.article_version_trust_revisions%rowtype;
  v_requested_count integer;
  v_resulting_revision bigint;
  v_attachments jsonb;
begin
  v_actor_id :=
    editorial.assert_credit_command_actor();

  if p_attachments is null
     or jsonb_typeof(p_attachments) <> 'array' then
    raise exception
      'Credit attachments must be a JSON array';
  end if;

  if p_expected_credit_revision is null
     or p_expected_credit_revision < 1 then
    raise exception
      'Expected Credit revision must be one or greater';
  end if;

  select *
  into v_article_version
  from editorial.article_versions article_version
  where article_version.id = p_article_version_id;

  if not found then
    raise exception
      'Article version was not found';
  end if;

  select *
  into v_resource
  from editorial.resources resource
  where resource.id = v_article_version.resource_id
    and resource.resource_kind = 'article';

  if not found then
    raise exception
      'Article resource was not found';
  end if;

  if auth.role() <> 'service_role'
     and not editorial.current_user_can_edit_article(
       v_resource.id
     ) then
    raise exception
      'You do not have authority to edit this Article';
  end if;

  insert into editorial.article_version_trust_revisions (
    article_version_id,
    citation_revision,
    credit_revision,
    updated_by,
    updated_at
  )
  values (
    p_article_version_id,
    1,
    1,
    v_actor_id,
    now()
  )
  on conflict (article_version_id) do nothing;

  select *
  into v_revision
  from editorial.article_version_trust_revisions revision
  where revision.article_version_id =
    p_article_version_id
  for update;

  if v_revision.credit_revision <>
       p_expected_credit_revision then
    raise exception
      'Credit revision conflict. Expected %, found %',
      p_expected_credit_revision,
      v_revision.credit_revision;
  end if;

  v_requested_count := jsonb_array_length(p_attachments);

  if exists (
    select 1
    from jsonb_array_elements(p_attachments) item(value)
    where jsonb_typeof(item.value) <> 'object'
       or not item.value ? 'credit_id'
       or not item.value ? 'display_order'
       or not item.value ? 'is_primary'
       or not item.value ? 'public_safe'
       or jsonb_typeof(
            item.value -> 'display_order'
          ) <> 'number'
       or jsonb_typeof(
            item.value -> 'is_primary'
          ) <> 'boolean'
       or jsonb_typeof(
            item.value -> 'public_safe'
          ) <> 'boolean'
  ) then
    raise exception
      'Every Credit attachment requires a complete valid object';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(p_attachments) as requested(
      credit_id uuid,
      display_order integer,
      is_primary boolean,
      public_safe boolean
    )
    where requested.credit_id is null
       or requested.display_order is null
       or requested.is_primary is null
       or requested.public_safe is null
       or requested.display_order < 0
  ) then
    raise exception
      'Credit attachment contains an invalid required value';
  end if;

  if exists (
    select 1
    from (
      select
        requested.credit_id,
        count(*) as duplicate_count
      from jsonb_to_recordset(p_attachments) as requested(
        credit_id uuid,
        display_order integer,
        is_primary boolean,
        public_safe boolean
      )
      group by requested.credit_id
      having count(*) > 1
    ) duplicate_credits
  ) then
    raise exception
      'Credit attachments contain duplicate Credit identities';
  end if;

  if exists (
    select 1
    from (
      select
        requested.display_order,
        count(*) as duplicate_count
      from jsonb_to_recordset(p_attachments) as requested(
        credit_id uuid,
        display_order integer,
        is_primary boolean,
        public_safe boolean
      )
      group by requested.display_order
      having count(*) > 1
    ) duplicate_orders
  ) then
    raise exception
      'Credit attachments contain duplicate display orders';
  end if;

  if v_requested_count > 0
     and (
       (
         select min(requested.display_order)
         from jsonb_to_recordset(p_attachments) as requested(
           credit_id uuid,
           display_order integer,
           is_primary boolean,
           public_safe boolean
         )
       ) <> 0
       or
       (
         select max(requested.display_order)
         from jsonb_to_recordset(p_attachments) as requested(
           credit_id uuid,
           display_order integer,
           is_primary boolean,
           public_safe boolean
         )
       ) <> v_requested_count - 1
     ) then
    raise exception
      'Credit display order must be zero-based and contiguous';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(p_attachments) as requested(
      credit_id uuid,
      display_order integer,
      is_primary boolean,
      public_safe boolean
    )
    where not exists (
      select 1
      from editorial.credits credit
      join editorial.credit_governance governance
        on governance.credit_id = credit.id
      where credit.id = requested.credit_id
        and governance.credit_state = 'active'
    )
  ) then
    raise exception
      'Every attached Credit must exist and be active';
  end if;

  if (
    select count(*)
    from jsonb_to_recordset(p_attachments) as requested(
      credit_id uuid,
      display_order integer,
      is_primary boolean,
      public_safe boolean
    )
    join editorial.credits credit
      on credit.id = requested.credit_id
    where requested.is_primary
      and credit.credit_role = 'author'
  ) > 1 then
    raise exception
      'An Article version can have at most one primary author Credit';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(p_attachments) as requested(
      credit_id uuid,
      display_order integer,
      is_primary boolean,
      public_safe boolean
    )
    join editorial.credits credit
      on credit.id = requested.credit_id
    join editorial.credit_governance governance
      on governance.credit_id = credit.id
    left join editorial.external_contributors contributor
      on contributor.id =
        credit.external_contributor_id
    where requested.public_safe
      and (
        governance.credit_state <> 'active'
        or not governance.public_safe
        or (
          credit.external_contributor_id is not null
          and (
            contributor.id is null
            or contributor.contributor_state <> 'active'
            or not contributor.public_safe
            or contributor.consent_status not in (
              'granted',
              'not_required'
            )
          )
        )
      )
  ) then
    raise exception
      'A requested public Credit attachment is not publicly eligible';
  end if;

  delete from editorial.resource_credits attachment
  where attachment.target_version_id =
    p_article_version_id;

  insert into editorial.resource_credits (
    resource_id,
    resource_kind,
    target_version_type,
    target_version_id,
    credit_id,
    display_order,
    is_primary,
    public_safe,
    created_by
  )
  select
    v_resource.id,
    'article',
    'article_version',
    p_article_version_id,
    requested.credit_id,
    requested.display_order,
    requested.is_primary,
    requested.public_safe,
    v_actor_id
  from jsonb_to_recordset(p_attachments) as requested(
    credit_id uuid,
    display_order integer,
    is_primary boolean,
    public_safe boolean
  )
  order by requested.display_order;

  v_resulting_revision :=
    v_revision.credit_revision + 1;

  update editorial.article_version_trust_revisions
  set
    credit_revision = v_resulting_revision,
    updated_by = v_actor_id,
    updated_at = now()
  where article_version_id = p_article_version_id;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'attachment_id',
          attachment.id,
        'credit_id',
          attachment.credit_id,
        'display_order',
          attachment.display_order,
        'is_primary',
          attachment.is_primary,
        'public_safe',
          attachment.public_safe
      )
      order by attachment.display_order
    ),
    '[]'::jsonb
  )
  into v_attachments
  from editorial.resource_credits attachment
  where attachment.target_version_id =
    p_article_version_id;

  return jsonb_build_object(
    'article_version_id',
      p_article_version_id,
    'credit_revision',
      v_resulting_revision,
    'correlation_id',
      p_correlation_id,
    'attachments',
      v_attachments
  );
end;
$$;


ALTER FUNCTION "public"."replace_article_version_credits"("p_article_version_id" "uuid", "p_attachments" "jsonb", "p_expected_credit_revision" bigint, "p_correlation_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."replace_article_version_credits"("p_article_version_id" "uuid", "p_attachments" "jsonb", "p_expected_credit_revision" bigint, "p_correlation_id" "uuid") IS 'Atomically replaces the complete ordered Credit set for one Article version.';



CREATE OR REPLACE FUNCTION "public"."replace_media_asset_file_v2"("p_asset_id" "uuid", "p_expected_authority_revision" bigint, "p_file" "jsonb", "p_variant" "jsonb" DEFAULT NULL::"jsonb", "p_reason" "text" DEFAULT 'Replace Media file with immutable revision'::"text", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'media', 'auth'
    AS $$
declare
  v_actor_id uuid;
  v_correlation_id uuid := coalesce(p_correlation_id, gen_random_uuid());
  v_asset media.assets%rowtype;
  v_compatibility public.registry_media_assets%rowtype;
  v_original_file_object_id uuid;
  v_revision record;
  v_variant_result jsonb;
  v_original_filename text;
  v_file_extension text;
begin
  v_actor_id := media.require_command_actor('manage_media_assets');

  if nullif(btrim(p_reason), '') is null then
    raise exception 'Media replacement reason is required';
  end if;

  select *
  into v_asset
  from media.assets
  where id = p_asset_id
  for update;

  if not found then
    raise exception 'Media asset does not exist';
  end if;

  if v_asset.lifecycle_state <> 'active' then
    raise exception 'Only an active Media asset may receive a replacement revision';
  end if;

  if v_asset.authority_revision <> p_expected_authority_revision then
    raise exception 'Stale Media authority revision';
  end if;

  select *
  into v_compatibility
  from public.registry_media_assets
  where id = p_asset_id
  for update;

  if not found then
    raise exception 'Media compatibility projection does not exist';
  end if;

  if not exists (
    select 1
    from media.legacy_asset_links bridge_row
    where bridge_row.legacy_asset_id = p_asset_id
      and bridge_row.asset_id = p_asset_id
  ) then
    raise exception 'Media compatibility bridge does not exist';
  end if;

  v_original_file_object_id := media.insert_verified_file_object_v2(
    p_file,
    v_actor_id,
    v_correlation_id
  );

  select *
  into v_revision
  from public.create_media_asset_revision(
    p_asset_id,
    p_expected_authority_revision,
    v_original_file_object_id,
    btrim(p_reason),
    v_correlation_id
  );

  v_variant_result := media.register_optional_variant_v2(
    p_asset_id,
    v_revision.asset_revision_id,
    v_original_file_object_id,
    p_variant,
    v_actor_id,
    v_correlation_id
  );

  v_original_filename := nullif(btrim(p_file ->> 'original_filename'), '');
  v_file_extension :=
    case
      when v_original_filename is not null
       and strpos(reverse(v_original_filename), '.') > 0
      then lower(reverse(split_part(reverse(v_original_filename), '.', 1)))
      else null
    end;

  update public.registry_media_assets
  set
    url = p_file ->> 'delivery_url',
    mime_type = p_file ->> 'mime_type',
    storage_bucket = coalesce(storage_bucket, 'lightsail-media'),
    storage_path = p_file ->> 'storage_path',
    original_filename = coalesce(v_original_filename, original_filename),
    file_extension = coalesce(v_file_extension, file_extension),
    file_size_bytes = (p_file ->> 'byte_size')::bigint,
    metadata =
      coalesce(metadata, '{}'::jsonb)
      || coalesce(p_file -> 'technical_metadata', '{}'::jsonb)
      || jsonb_build_object(
        'file_name', coalesce(v_original_filename, metadata ->> 'file_name'),
        'file_size', (p_file ->> 'byte_size')::bigint
      ),
    updated_at = now()
  where id = p_asset_id;

  insert into media.events (
    asset_id,
    asset_revision_id,
    event_type,
    actor_id,
    reason,
    prior_state,
    resulting_state,
    correlation_id
  )
  values (
    p_asset_id,
    v_revision.asset_revision_id,
    'compatibility_projection_updated',
    v_actor_id,
    btrim(p_reason),
    jsonb_build_object(
      'url', v_compatibility.url,
      'storage_path', v_compatibility.storage_path,
      'current_revision_id', v_asset.current_revision_id,
      'authority_revision', v_asset.authority_revision
    ),
    jsonb_build_object(
      'url', p_file ->> 'delivery_url',
      'storage_path', p_file ->> 'storage_path',
      'current_revision_id', v_revision.asset_revision_id,
      'authority_revision', v_revision.authority_revision
    ),
    v_correlation_id
  );

  return jsonb_build_object(
    'asset_id', p_asset_id,
    'file_object_id', v_original_file_object_id,
    'asset_revision_id', v_revision.asset_revision_id,
    'revision_number', v_revision.revision_number,
    'authority_revision', v_revision.authority_revision,
    'variant', v_variant_result,
    'correlation_id', v_correlation_id
  );
end;
$$;


ALTER FUNCTION "public"."replace_media_asset_file_v2"("p_asset_id" "uuid", "p_expected_authority_revision" bigint, "p_file" "jsonb", "p_variant" "jsonb", "p_reason" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."replace_media_asset_file_v2"("p_asset_id" "uuid", "p_expected_authority_revision" bigint, "p_file" "jsonb", "p_variant" "jsonb", "p_reason" "text", "p_correlation_id" "uuid") IS 'Creates a new immutable Media revision and optional derivative without overwriting a registered storage path.';



CREATE OR REPLACE FUNCTION "public"."replace_playlist_version_citations"("p_playlist_version_id" "uuid", "p_target_resource_id" "uuid", "p_attachments" "jsonb", "p_expected_citation_revision" bigint, "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial', 'auth'
    AS $$
declare
  v_actor_id uuid;
  v_target record;
  v_revision
    editorial.playlist_version_trust_revisions%rowtype;
  v_requested_count integer;
  v_resulting_revision bigint;
  v_attachments jsonb;
begin
  v_actor_id :=
    editorial.assert_citation_command_actor();

  if p_attachments is null
     or jsonb_typeof(p_attachments) <> 'array'
  then
    raise exception
      'Citation attachments must be a JSON array';
  end if;

  if p_expected_citation_revision is null
     or p_expected_citation_revision < 1
  then
    raise exception
      'Expected Citation revision must be one or greater';
  end if;

  select *
  into v_target
  from editorial.playlist_working_trust_target(
    p_playlist_version_id,
    p_target_resource_id
  );

  if auth.role() <> 'service_role'
     and not editorial.current_user_can_edit_playlist(
       v_target.root_resource_id
     )
  then
    raise exception
      'You do not have authority to edit this Playlist';
  end if;

  insert into editorial.playlist_version_trust_revisions (
    playlist_version_id,
    citation_revision,
    credit_revision,
    updated_by,
    updated_at
  )
  values (
    p_playlist_version_id,
    1,
    1,
    v_actor_id,
    now()
  )
  on conflict (playlist_version_id)
  do nothing;

  select *
  into v_revision
  from editorial.playlist_version_trust_revisions revision
  where revision.playlist_version_id =
          p_playlist_version_id
  for update;

  if v_revision.citation_revision <>
       p_expected_citation_revision
  then
    raise exception
      'Citation revision conflict. Expected %, found %',
      p_expected_citation_revision,
      v_revision.citation_revision;
  end if;

  v_requested_count :=
    jsonb_array_length(p_attachments);

  if exists (
    select 1
    from jsonb_array_elements(p_attachments) item(value)
    where jsonb_typeof(item.value) <> 'object'
       or not item.value ? 'citation_id'
       or not item.value ? 'citation_purpose'
       or not item.value ? 'target_anchor_type'
       or not item.value ? 'target_anchor_data'
       or not item.value ? 'display_order'
       or not item.value ? 'public_safe'
       or jsonb_typeof(
            item.value -> 'target_anchor_data'
          ) <> 'object'
       or jsonb_typeof(
            item.value -> 'public_safe'
          ) <> 'boolean'
       or jsonb_typeof(
            item.value -> 'display_order'
          ) <> 'number'
  ) then
    raise exception
      'Every Citation attachment requires a complete valid object';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(p_attachments) as requested(
      citation_id uuid,
      citation_purpose text,
      target_anchor_type text,
      target_anchor_data jsonb,
      display_order integer,
      public_safe boolean
    )
    where requested.citation_id is null
       or requested.citation_purpose not in (
            'supports',
            'challenges',
            'contextualizes',
            'quotes',
            'documents',
            'methodology',
            'other'
          )
       or requested.target_anchor_type is null
       or requested.target_anchor_data is null
       or requested.display_order is null
       or requested.display_order < 0
       or requested.public_safe is null
  ) then
    raise exception
      'Citation attachment contains an invalid required value';
  end if;

  if exists (
    select 1
    from (
      select requested.citation_id
      from jsonb_to_recordset(p_attachments) as requested(
        citation_id uuid,
        citation_purpose text,
        target_anchor_type text,
        target_anchor_data jsonb,
        display_order integer,
        public_safe boolean
      )
      group by requested.citation_id
      having count(*) > 1
    ) duplicate_citations
  ) then
    raise exception
      'Citation attachments contain duplicate Citation identities';
  end if;

  if exists (
    select 1
    from (
      select requested.display_order
      from jsonb_to_recordset(p_attachments) as requested(
        citation_id uuid,
        citation_purpose text,
        target_anchor_type text,
        target_anchor_data jsonb,
        display_order integer,
        public_safe boolean
      )
      group by requested.display_order
      having count(*) > 1
    ) duplicate_orders
  ) then
    raise exception
      'Citation attachments contain duplicate display orders';
  end if;

  if v_requested_count > 0
     and (
       (
         select min(requested.display_order)
         from jsonb_to_recordset(p_attachments) as requested(
           citation_id uuid,
           citation_purpose text,
           target_anchor_type text,
           target_anchor_data jsonb,
           display_order integer,
           public_safe boolean
         )
       ) <> 0
       or
       (
         select max(requested.display_order)
         from jsonb_to_recordset(p_attachments) as requested(
           citation_id uuid,
           citation_purpose text,
           target_anchor_type text,
           target_anchor_data jsonb,
           display_order integer,
           public_safe boolean
         )
       ) <> v_requested_count - 1
     )
  then
    raise exception
      'Citation display order must be zero-based and contiguous per Playlist target';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(p_attachments) as requested(
      citation_id uuid,
      citation_purpose text,
      target_anchor_type text,
      target_anchor_data jsonb,
      display_order integer,
      public_safe boolean
    )
    where not exists (
      select 1
      from editorial.citations citation
      where citation.id = requested.citation_id
        and citation.citation_state = 'active'
    )
  ) then
    raise exception
      'Every attached Citation must exist and be active';
  end if;

  perform editorial.validate_citation_target_anchor(
    requested.target_anchor_type,
    requested.target_anchor_data
  )
  from jsonb_to_recordset(p_attachments) as requested(
    citation_id uuid,
    citation_purpose text,
    target_anchor_type text,
    target_anchor_data jsonb,
    display_order integer,
    public_safe boolean
  );

  if exists (
    select 1
    from jsonb_to_recordset(p_attachments) as requested(
      citation_id uuid,
      citation_purpose text,
      target_anchor_type text,
      target_anchor_data jsonb,
      display_order integer,
      public_safe boolean
    )
    join editorial.citations citation
      on citation.id = requested.citation_id
    join editorial.sources source
      on source.id = citation.source_id
    where requested.public_safe
      and (
        not citation.public_safe
        or source.source_state <> 'active'
        or source.review_status <> 'approved'
        or source.current_approved_version_id
             is distinct from
             citation.source_version_id
        or source.exposure_class not in (
             'public',
             'public_redacted'
           )
      )
  ) then
    raise exception
      'A requested public Citation attachment is not publicly eligible';
  end if;

  delete from editorial.resource_citations attachment
  where attachment.target_version_type =
          'playlist_version'
    and attachment.target_version_id =
          p_playlist_version_id
    and attachment.resource_id =
          p_target_resource_id;

  insert into editorial.resource_citations (
    resource_id,
    resource_kind,
    target_version_type,
    target_version_id,
    citation_id,
    citation_purpose,
    target_anchor_type,
    target_anchor_data,
    display_order,
    public_safe,
    created_by
  )
  select
    p_target_resource_id,
    v_target.target_resource_kind,
    'playlist_version',
    p_playlist_version_id,
    requested.citation_id,
    requested.citation_purpose,
    requested.target_anchor_type,
    requested.target_anchor_data,
    requested.display_order,
    requested.public_safe,
    v_actor_id
  from jsonb_to_recordset(p_attachments) as requested(
    citation_id uuid,
    citation_purpose text,
    target_anchor_type text,
    target_anchor_data jsonb,
    display_order integer,
    public_safe boolean
  )
  order by requested.display_order;

  v_resulting_revision :=
    v_revision.citation_revision + 1;

  update editorial.playlist_version_trust_revisions
  set
    citation_revision =
      v_resulting_revision,
    updated_by = v_actor_id,
    updated_at = now()
  where playlist_version_id =
          p_playlist_version_id;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'attachment_id',
          attachment.id,
        'resource_id',
          attachment.resource_id,
        'resource_kind',
          attachment.resource_kind,
        'citation_id',
          attachment.citation_id,
        'citation_purpose',
          attachment.citation_purpose,
        'target_anchor_type',
          attachment.target_anchor_type,
        'target_anchor_data',
          attachment.target_anchor_data,
        'display_order',
          attachment.display_order,
        'public_safe',
          attachment.public_safe
      )
      order by attachment.display_order
    ),
    '[]'::jsonb
  )
  into v_attachments
  from editorial.resource_citations attachment
  where attachment.target_version_type =
          'playlist_version'
    and attachment.target_version_id =
          p_playlist_version_id
    and attachment.resource_id =
          p_target_resource_id;

  return jsonb_build_object(
    'playlist_version_id',
      p_playlist_version_id,
    'target_resource_id',
      p_target_resource_id,
    'target_resource_kind',
      v_target.target_resource_kind,
    'citation_revision',
      v_resulting_revision,
    'correlation_id',
      p_correlation_id,
    'attachments',
      v_attachments
  );
end;
$$;


ALTER FUNCTION "public"."replace_playlist_version_citations"("p_playlist_version_id" "uuid", "p_target_resource_id" "uuid", "p_attachments" "jsonb", "p_expected_citation_revision" bigint, "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."replace_playlist_version_credits"("p_playlist_version_id" "uuid", "p_target_resource_id" "uuid", "p_attachments" "jsonb", "p_expected_credit_revision" bigint, "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial', 'auth'
    AS $$
declare
  v_actor_id uuid;
  v_target record;
  v_revision
    editorial.playlist_version_trust_revisions%rowtype;
  v_requested_count integer;
  v_resulting_revision bigint;
  v_attachments jsonb;
begin
  v_actor_id :=
    editorial.assert_credit_command_actor();

  if p_attachments is null
     or jsonb_typeof(p_attachments) <> 'array'
  then
    raise exception
      'Credit attachments must be a JSON array';
  end if;

  if p_expected_credit_revision is null
     or p_expected_credit_revision < 1
  then
    raise exception
      'Expected Credit revision must be one or greater';
  end if;

  select *
  into v_target
  from editorial.playlist_working_trust_target(
    p_playlist_version_id,
    p_target_resource_id
  );

  if auth.role() <> 'service_role'
     and not editorial.current_user_can_edit_playlist(
       v_target.root_resource_id
     )
  then
    raise exception
      'You do not have authority to edit this Playlist';
  end if;

  insert into editorial.playlist_version_trust_revisions (
    playlist_version_id,
    citation_revision,
    credit_revision,
    updated_by,
    updated_at
  )
  values (
    p_playlist_version_id,
    1,
    1,
    v_actor_id,
    now()
  )
  on conflict (playlist_version_id)
  do nothing;

  select *
  into v_revision
  from editorial.playlist_version_trust_revisions revision
  where revision.playlist_version_id =
          p_playlist_version_id
  for update;

  if v_revision.credit_revision <>
       p_expected_credit_revision
  then
    raise exception
      'Credit revision conflict. Expected %, found %',
      p_expected_credit_revision,
      v_revision.credit_revision;
  end if;

  v_requested_count :=
    jsonb_array_length(p_attachments);

  if exists (
    select 1
    from jsonb_array_elements(p_attachments) item(value)
    where jsonb_typeof(item.value) <> 'object'
       or not item.value ? 'credit_id'
       or not item.value ? 'display_order'
       or not item.value ? 'is_primary'
       or not item.value ? 'public_safe'
       or jsonb_typeof(
            item.value -> 'display_order'
          ) <> 'number'
       or jsonb_typeof(
            item.value -> 'is_primary'
          ) <> 'boolean'
       or jsonb_typeof(
            item.value -> 'public_safe'
          ) <> 'boolean'
  ) then
    raise exception
      'Every Credit attachment requires a complete valid object';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(p_attachments) as requested(
      credit_id uuid,
      display_order integer,
      is_primary boolean,
      public_safe boolean
    )
    where requested.credit_id is null
       or requested.display_order is null
       or requested.display_order < 0
       or requested.is_primary is null
       or requested.public_safe is null
  ) then
    raise exception
      'Credit attachment contains an invalid required value';
  end if;

  if exists (
    select 1
    from (
      select requested.credit_id
      from jsonb_to_recordset(p_attachments) as requested(
        credit_id uuid,
        display_order integer,
        is_primary boolean,
        public_safe boolean
      )
      group by requested.credit_id
      having count(*) > 1
    ) duplicate_credits
  ) then
    raise exception
      'Credit attachments contain duplicate Credit identities';
  end if;

  if exists (
    select 1
    from (
      select requested.display_order
      from jsonb_to_recordset(p_attachments) as requested(
        credit_id uuid,
        display_order integer,
        is_primary boolean,
        public_safe boolean
      )
      group by requested.display_order
      having count(*) > 1
    ) duplicate_orders
  ) then
    raise exception
      'Credit attachments contain duplicate display orders';
  end if;

  if v_requested_count > 0
     and (
       (
         select min(requested.display_order)
         from jsonb_to_recordset(p_attachments) as requested(
           credit_id uuid,
           display_order integer,
           is_primary boolean,
           public_safe boolean
         )
       ) <> 0
       or
       (
         select max(requested.display_order)
         from jsonb_to_recordset(p_attachments) as requested(
           credit_id uuid,
           display_order integer,
           is_primary boolean,
           public_safe boolean
         )
       ) <> v_requested_count - 1
     )
  then
    raise exception
      'Credit display order must be zero-based and contiguous per Playlist target';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(p_attachments) as requested(
      credit_id uuid,
      display_order integer,
      is_primary boolean,
      public_safe boolean
    )
    where not exists (
      select 1
      from editorial.credits credit
      join editorial.credit_governance governance
        on governance.credit_id = credit.id
      where credit.id = requested.credit_id
        and governance.credit_state = 'active'
    )
  ) then
    raise exception
      'Every attached Credit must exist and be active';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(p_attachments) as requested(
      credit_id uuid,
      display_order integer,
      is_primary boolean,
      public_safe boolean
    )
    join editorial.credits credit
      on credit.id = requested.credit_id
    join editorial.credit_governance governance
      on governance.credit_id = credit.id
    left join editorial.external_contributors contributor
      on contributor.id =
        credit.external_contributor_id
    where requested.public_safe
      and (
        governance.credit_state <> 'active'
        or not governance.public_safe
        or (
          credit.external_contributor_id is not null
          and (
            contributor.id is null
            or contributor.contributor_state <> 'active'
            or not contributor.public_safe
            or contributor.consent_status not in (
              'granted',
              'not_required'
            )
          )
        )
      )
  ) then
    raise exception
      'A requested public Credit attachment is not publicly eligible';
  end if;

  delete from editorial.resource_credits attachment
  where attachment.target_version_type =
          'playlist_version'
    and attachment.target_version_id =
          p_playlist_version_id
    and attachment.resource_id =
          p_target_resource_id;

  insert into editorial.resource_credits (
    resource_id,
    resource_kind,
    target_version_type,
    target_version_id,
    credit_id,
    display_order,
    is_primary,
    public_safe,
    created_by
  )
  select
    p_target_resource_id,
    v_target.target_resource_kind,
    'playlist_version',
    p_playlist_version_id,
    requested.credit_id,
    requested.display_order,
    requested.is_primary,
    requested.public_safe,
    v_actor_id
  from jsonb_to_recordset(p_attachments) as requested(
    credit_id uuid,
    display_order integer,
    is_primary boolean,
    public_safe boolean
  )
  order by requested.display_order;

  v_resulting_revision :=
    v_revision.credit_revision + 1;

  update editorial.playlist_version_trust_revisions
  set
    credit_revision =
      v_resulting_revision,
    updated_by = v_actor_id,
    updated_at = now()
  where playlist_version_id =
          p_playlist_version_id;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'attachment_id',
          attachment.id,
        'resource_id',
          attachment.resource_id,
        'resource_kind',
          attachment.resource_kind,
        'credit_id',
          attachment.credit_id,
        'display_order',
          attachment.display_order,
        'is_primary',
          attachment.is_primary,
        'public_safe',
          attachment.public_safe
      )
      order by attachment.display_order
    ),
    '[]'::jsonb
  )
  into v_attachments
  from editorial.resource_credits attachment
  where attachment.target_version_type =
          'playlist_version'
    and attachment.target_version_id =
          p_playlist_version_id
    and attachment.resource_id =
          p_target_resource_id;

  return jsonb_build_object(
    'playlist_version_id',
      p_playlist_version_id,
    'target_resource_id',
      p_target_resource_id,
    'target_resource_kind',
      v_target.target_resource_kind,
    'credit_revision',
      v_resulting_revision,
    'correlation_id',
      p_correlation_id,
    'attachments',
      v_attachments
  );
end;
$$;


ALTER FUNCTION "public"."replace_playlist_version_credits"("p_playlist_version_id" "uuid", "p_target_resource_id" "uuid", "p_attachments" "jsonb", "p_expected_credit_revision" bigint, "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_article_changes"("p_article_id" "uuid", "p_version_id" "uuid" DEFAULT NULL::"uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS TABLE("article_id" "uuid", "article_slug" "text", "draft_version" bigint, "version_id" "uuid", "version_number" bigint, "lifecycle_status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_article public.wk_articles%rowtype;
  v_resource editorial.resources%rowtype;
  v_target_version_id uuid;
  v_target_number bigint;
  v_prior_status text;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  if nullif(btrim(p_note), '') is null then
    raise exception 'Requested changes note is required';
  end if;

  if not editorial.current_user_can_review_article() then
    raise exception 'Permission denied';
  end if;

  select article.*
  into v_article
  from public.wk_articles article
  where article.id = p_article_id
  for update;

  if not found then
    raise exception 'Article not found';
  end if;

  select resource.*
  into v_resource
  from editorial.article_resources binding
  join editorial.resources resource
    on resource.id = binding.resource_id
  where binding.article_id = p_article_id
  for update of resource;

  if not found then
    raise exception 'Article resource identity not found';
  end if;

  v_target_version_id :=
    coalesce(
      p_version_id,
      v_resource.current_submitted_version_id,
      v_resource.current_working_version_id
    );

  select version.version_number
  into v_target_number
  from editorial.article_versions version
  where version.id = v_target_version_id
    and version.article_id = p_article_id;

  if not found then
    raise exception 'Article version not found';
  end if;

  v_prior_status := v_article.wp_status;

  update public.wk_articles as article
  set
    wp_status = 'draft',
    draft_version = article.draft_version + 1,
    updated_at = now(),
    modified_at = now()
  where article.id = p_article_id
  returning article.*
  into v_article;

  update editorial.resources
  set
    lifecycle_state = 'draft',
    visibility = 'private',
    updated_at = now()
  where id = v_resource.id;

  insert into editorial.article_lifecycle_events (
    resource_id,
    article_id,
    version_id,
    action,
    prior_status,
    resulting_status,
    note
  )
  values (
    v_resource.id,
    p_article_id,
    v_target_version_id,
    'changes_requested',
    v_prior_status,
    'draft',
    p_note
  );

  article_id := p_article_id;
  article_slug := v_article.slug;
  draft_version := v_article.draft_version;
  version_id := v_target_version_id;
  version_number := v_target_number;
  lifecycle_status := 'changes_requested';
  return next;
end;
$$;


ALTER FUNCTION "public"."request_article_changes"("p_article_id" "uuid", "p_version_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_article_preview_nonce"("p_nonce" "text") RETURNS TABLE("id" "uuid", "slug" "text", "title" "text", "excerpt" "text", "content_html" "text", "author" "text", "published_at" timestamp with time zone, "categories" "jsonb", "tags" "jsonb", "hero_image_url" "text", "seo" "jsonb", "wp_status" "text", "raw_meta" "jsonb", "version_id" "uuid", "version_number" integer, "preview_expires_at" timestamp with time zone, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "draft_version" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'editorial', 'pg_temp'
    AS $$
  select
    article.id,
    version.slug,
    version.title,
    version.excerpt,
    version.content_html,
    coalesce(version.author_display, article.author) as author,
    version.published_at,
    version.category_snapshot as categories,
    version.tag_snapshot as tags,
    version.hero_image_url,
    version.seo,
    coalesce(version.wp_status, article.wp_status, 'draft') as wp_status,
    article.raw_meta,
    version.id as version_id,
    version.version_number,
    link.expires_at as preview_expires_at,
    article.created_at,
    article.updated_at,
    article.draft_version
  from public.wk_article_preview_links link
  join editorial.article_versions version
    on version.id = link.version_id
  join public.wk_articles article
    on article.id = link.article_id
  where link.nonce = p_nonce
    and link.revoked_at is null
    and link.expires_at > now()
  limit 1;
$$;


ALTER FUNCTION "public"."resolve_article_preview_nonce"("p_nonce" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resolve_article_preview_nonce"("p_nonce" "text") IS 'Resolves a preview nonce to immutable article version content.';



CREATE OR REPLACE FUNCTION "public"."resolve_legacy_media_asset_lite_batch"("p_asset_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_urls" "text"[] DEFAULT NULL::"text"[]) RETURNS TABLE("requested_asset_id" "uuid", "requested_url" "text", "id" "uuid", "slug" "text", "title" "text", "url" "text", "mime_type" "text", "media_kind" "text", "metadata" "jsonb", "usage_link_id" "uuid", "resolved_mode" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'media'
    AS $$
declare
  v_asset_ids uuid[];
  v_urls text[];
  v_lookup_by_id boolean;
  v_lookup_by_url boolean;
  v_candidate record;
  v_resolved record;
begin
  select coalesce(
    array_agg(distinct value_row.asset_id),
    array[]::uuid[]
  )
  into v_asset_ids
  from unnest(
    coalesce(p_asset_ids, array[]::uuid[])
  ) as value_row(asset_id)
  where value_row.asset_id is not null;

  select coalesce(
    array_agg(distinct btrim(value_row.url)),
    array[]::text[]
  )
  into v_urls
  from unnest(
    coalesce(p_urls, array[]::text[])
  ) as value_row(url)
  where nullif(btrim(value_row.url), '') is not null;

  v_lookup_by_id :=
    cardinality(v_asset_ids) > 0;
  v_lookup_by_url :=
    cardinality(v_urls) > 0;

  if v_lookup_by_id = v_lookup_by_url then
    raise exception
      'Media lite batch requires exactly one lookup set';
  end if;

  if greatest(
    cardinality(v_asset_ids),
    cardinality(v_urls)
  ) > 1000 then
    raise exception
      'Media lite batch exceeds 1000 unique lookup values';
  end if;

  for v_candidate in
    select
      compatibility_row.id,
      compatibility_row.slug,
      compatibility_row.title,
      compatibility_row.url
        as compatibility_url,
      compatibility_row.mime_type,
      compatibility_row.media_kind,
      compatibility_row.metadata,
      usage_choice.usage_link_id
    from public.registry_media_assets
      compatibility_row
    join lateral (
      select usage_row.id as usage_link_id
      from media.usage_links usage_row
      where usage_row.asset_id =
        compatibility_row.id
        and usage_row.usage_state = 'active'
        and usage_row.resolution_mode =
          'legacy_snapshot'
      order by
        usage_row.created_at,
        usage_row.id
      limit 1
    ) usage_choice
      on true
    where compatibility_row.status = 'active'
      and (
        (
          v_lookup_by_id
          and compatibility_row.id =
            any(v_asset_ids)
        )
        or
        (
          v_lookup_by_url
          and compatibility_row.url =
            any(v_urls)
        )
      )
    order by compatibility_row.id
  loop
    begin
      select resolved_row.*
      into v_resolved
      from public.resolve_media_asset_delivery(
        v_candidate.id,
        v_candidate.usage_link_id,
        null,
        null
      ) resolved_row;

      if found then
        return query
        select
          case
            when v_lookup_by_id
              then v_candidate.id
            else null::uuid
          end,
          case
            when v_lookup_by_url
              then v_candidate.compatibility_url
            else null::text
          end,
          v_candidate.id,
          v_candidate.slug,
          v_candidate.title,
          v_resolved.safe_delivery_url,
          coalesce(
            v_resolved.resolved_mime_type,
            v_candidate.mime_type
          ),
          v_candidate.media_kind,
          v_candidate.metadata,
          v_candidate.usage_link_id,
          v_resolved.resolved_mode;
      end if;
    exception
      when raise_exception then
        continue;
    end;
  end loop;
end;
$$;


ALTER FUNCTION "public"."resolve_legacy_media_asset_lite_batch"("p_asset_ids" "uuid"[], "p_urls" "text"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resolve_legacy_media_asset_lite_batch"("p_asset_ids" "uuid"[], "p_urls" "text"[]) IS 'Phase 4A transitional batch read adapter. Returns the existing lightweight Media shape only for active legacy usages accepted by the governed delivery resolver.';



CREATE OR REPLACE FUNCTION "public"."resolve_media_asset_delivery"("p_asset_id" "uuid", "p_usage_link_id" "uuid" DEFAULT NULL::"uuid", "p_exact_asset_revision_id" "uuid" DEFAULT NULL::"uuid", "p_requested_variant_role" "text" DEFAULT NULL::"text") RETURNS TABLE("logical_asset_id" "uuid", "resolved_mode" "text", "resolved_asset_revision_id" "uuid", "resolved_file_object_id" "uuid", "safe_delivery_url" "text", "resolved_mime_type" "text", "width" integer, "height" integer, "duration_seconds" numeric, "approved_alt_text" "text", "approved_caption" "text", "approved_credit" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'media'
    AS $_$
declare
  v_usage media.usage_links%rowtype;
  v_asset_lifecycle text;
  v_current_revision_id uuid;
  v_governance_version_number bigint;
  v_rights_status text;
  v_consent_status text;
  v_sensitivity text;
  v_embargo_state text;
  v_embargo_until timestamptz;
  v_source_protection_class text;
  v_preservation_state text;
  v_retention_state text;
  v_public_safety_state text;
  v_internal_reason text;
  v_resolution_mode text;
  v_revision_id uuid;
  v_file_object_id uuid;
  v_delivery_url text;
  v_mime_type text;
  v_technical_metadata jsonb;
  v_legacy_snapshot jsonb;
  v_compatibility_status text;
  v_compatibility_url text;
  v_alt_text text;
  v_caption text;
  v_credit text;
  v_width integer;
  v_height integer;
  v_duration numeric;
  v_is_approved_public boolean;
  v_is_legacy_compatibility boolean;
begin
  if p_asset_id is null then
    raise exception
      'Media resolver requires a logical asset identity';
  end if;

  select
    asset_row.lifecycle_state,
    asset_row.current_revision_id,
    governance_row.version_number,
    governance_row.rights_status,
    governance_row.consent_status,
    governance_row.sensitivity,
    governance_row.embargo_state,
    governance_row.embargo_until,
    governance_row.source_protection_class,
    governance_row.preservation_state,
    governance_row.retention_state,
    governance_row.public_safety_state,
    governance_row.internal_reason
  into
    v_asset_lifecycle,
    v_current_revision_id,
    v_governance_version_number,
    v_rights_status,
    v_consent_status,
    v_sensitivity,
    v_embargo_state,
    v_embargo_until,
    v_source_protection_class,
    v_preservation_state,
    v_retention_state,
    v_public_safety_state,
    v_internal_reason
  from media.assets asset_row
  join media.asset_governance_versions governance_row
    on governance_row.id =
      asset_row.current_governance_version_id
  where asset_row.id = p_asset_id;

  if not found then
    raise exception
      'Media resolver asset does not exist or lacks current governance';
  end if;

  if p_usage_link_id is not null then
    select usage_row.*
    into v_usage
    from media.usage_links usage_row
    where usage_row.id = p_usage_link_id;

    if not found
       or v_usage.usage_state <> 'active'
    then
      raise exception
        'Active Media usage does not exist';
    end if;

    if v_usage.asset_id <> p_asset_id then
      raise exception
        'Media usage does not belong to the supplied asset';
    end if;

    if p_exact_asset_revision_id is not null
       and p_exact_asset_revision_id is distinct from
         v_usage.asset_revision_id
    then
      raise exception
        'Supplied Media revision does not match the usage';
    end if;

    v_resolution_mode := v_usage.resolution_mode;
    v_revision_id := v_usage.asset_revision_id;
    v_alt_text := v_usage.alt_text_snapshot;
    v_caption := v_usage.caption_snapshot;
    v_credit := v_usage.credit_snapshot;

    if v_resolution_mode = 'current_revision'
       and media.usage_role_requires_stability(
         v_usage.usage_role
       )
    then
      raise exception
        'Publication-stable Media usage cannot resolve through current revision';
    end if;

  elsif p_exact_asset_revision_id is not null then
    v_resolution_mode := 'exact_revision';
    v_revision_id := p_exact_asset_revision_id;

  else
    v_resolution_mode := 'current_revision';
    v_revision_id := v_current_revision_id;
  end if;

  v_is_approved_public := coalesce(
    v_asset_lifecycle = 'active'
    and v_public_safety_state in (
      'approved_public',
      'approved_redacted'
    )
    and v_rights_status in (
      'owned',
      'licensed',
      'public_domain',
      'fair_use'
    )
    and v_consent_status in (
      'granted',
      'not_required'
    )
    and v_source_protection_class in (
      'public',
      'public_redacted'
    )
    and v_retention_state in (
      'retain',
      'review_required'
    )
    and v_embargo_state <> 'active'
    and not (
      v_embargo_state = 'scheduled'
      and v_embargo_until is not null
      and v_embargo_until > now()
    ),
    false
  );

  v_is_legacy_compatibility := coalesce(
    v_asset_lifecycle = 'active'
    and v_governance_version_number = 1
    and v_rights_status = 'unknown'
    and v_consent_status = 'unknown'
    and v_sensitivity = 'none'
    and v_embargo_state = 'none'
    and v_embargo_until is null
    and v_source_protection_class = 'internal'
    and v_preservation_state = 'unassessed'
    and v_retention_state = 'retain'
    and v_public_safety_state = 'internal'
    and v_internal_reason =
      'Initial governance copied without inference from registry_media_assets',
    false
  );

  if v_resolution_mode = 'legacy_snapshot' then
    if p_usage_link_id is null then
      raise exception
        'Legacy-snapshot delivery requires a usage link';
    end if;

    if p_requested_variant_role is not null then
      raise exception
        'Legacy-snapshot delivery cannot resolve a variant';
    end if;

    if v_revision_id is not null then
      raise exception
        'Legacy-snapshot usage cannot bind a revision';
    end if;

    select
      bridge_row.legacy_snapshot,
      compatibility_row.status,
      compatibility_row.url
    into
      v_legacy_snapshot,
      v_compatibility_status,
      v_compatibility_url
    from media.legacy_asset_links bridge_row
    join public.registry_media_assets compatibility_row
      on compatibility_row.id =
        bridge_row.legacy_asset_id
    where bridge_row.asset_id = p_asset_id
      and bridge_row.legacy_asset_id =
        p_asset_id;

    if not found
       or nullif(
         btrim(v_legacy_snapshot ->> 'url'),
         ''
       ) is null
    then
      raise exception
        'Legacy-snapshot delivery requires one immutable captured URL';
    end if;

    if v_compatibility_status <> 'active' then
      raise exception
        'Legacy Media compatibility row is not active';
    end if;

    if btrim(v_compatibility_url) is distinct from
       btrim(v_legacy_snapshot ->> 'url')
    then
      raise exception
        'Legacy Media compatibility URL changed after capture';
    end if;

    if not (
      v_is_approved_public
      or v_is_legacy_compatibility
    ) then
      raise exception
        'Media delivery is blocked by current governance';
    end if;

    v_delivery_url :=
      btrim(v_legacy_snapshot ->> 'url');
    v_mime_type :=
      nullif(
        btrim(v_legacy_snapshot ->> 'mime_type'),
        ''
      );

    v_width :=
      case
        when coalesce(
          v_legacy_snapshot #>> '{metadata,width}',
          ''
        ) ~ '^[0-9]+$'
          then (
            v_legacy_snapshot #>>
              '{metadata,width}'
          )::integer
        else null
      end;

    v_height :=
      case
        when coalesce(
          v_legacy_snapshot #>> '{metadata,height}',
          ''
        ) ~ '^[0-9]+$'
          then (
            v_legacy_snapshot #>>
              '{metadata,height}'
          )::integer
        else null
      end;

    v_duration :=
      case
        when coalesce(
          v_legacy_snapshot #>> '{metadata,duration}',
          ''
        ) ~ '^[0-9]+([.][0-9]+)?$'
          then (
            v_legacy_snapshot #>>
              '{metadata,duration}'
          )::numeric
        else null
      end;

    return query
    select
      p_asset_id,
      v_resolution_mode,
      null::uuid,
      null::uuid,
      v_delivery_url,
      v_mime_type,
      v_width,
      v_height,
      v_duration,
      v_alt_text,
      v_caption,
      v_credit;

    return;
  end if;

  if not v_is_approved_public then
    raise exception
      'Media delivery is blocked by current governance';
  end if;

  if v_revision_id is null then
    raise exception
      'Media delivery has no valid asset revision';
  end if;

  if not exists (
    select 1
    from media.asset_revisions revision_row
    where revision_row.id = v_revision_id
      and revision_row.asset_id = p_asset_id
  ) then
    raise exception
      'Media delivery revision does not belong to the asset';
  end if;

  if p_requested_variant_role is null then
    select revision_row.original_file_object_id
    into v_file_object_id
    from media.asset_revisions revision_row
    where revision_row.id = v_revision_id;
  else
    select variant_row.derived_file_object_id
    into v_file_object_id
    from media.variant_selections selection_row
    join media.variants variant_row
      on variant_row.id = selection_row.variant_id
    where selection_row.asset_revision_id =
      v_revision_id
      and selection_row.variant_role =
        p_requested_variant_role
      and variant_row.asset_revision_id =
        v_revision_id
      and variant_row.variant_role =
        p_requested_variant_role;

    if not found then
      raise exception
        'Requested Media variant has no governed selection';
    end if;
  end if;

  select
    file_row.delivery_url,
    file_row.mime_type,
    file_row.technical_metadata
  into
    v_delivery_url,
    v_mime_type,
    v_technical_metadata
  from media.file_objects file_row
  where file_row.id = v_file_object_id
    and file_row.verification_state = 'verified';

  if not found
     or nullif(btrim(v_delivery_url), '') is null
  then
    raise exception
      'Media delivery requires one verified file object with a safe URL';
  end if;

  v_width :=
    case
      when jsonb_typeof(
        v_technical_metadata -> 'width'
      ) = 'number'
        then (
          v_technical_metadata ->> 'width'
        )::numeric::integer
      else null
    end;

  v_height :=
    case
      when jsonb_typeof(
        v_technical_metadata -> 'height'
      ) = 'number'
        then (
          v_technical_metadata ->> 'height'
        )::numeric::integer
      else null
    end;

  v_duration :=
    case
      when jsonb_typeof(
        v_technical_metadata -> 'duration'
      ) = 'number'
        then (
          v_technical_metadata ->> 'duration'
        )::numeric
      else null
    end;

  return query
  select
    p_asset_id,
    v_resolution_mode,
    v_revision_id,
    v_file_object_id,
    v_delivery_url,
    v_mime_type,
    v_width,
    v_height,
    v_duration,
    v_alt_text,
    v_caption,
    v_credit;
end;
$_$;


ALTER FUNCTION "public"."resolve_media_asset_delivery"("p_asset_id" "uuid", "p_usage_link_id" "uuid", "p_exact_asset_revision_id" "uuid", "p_requested_variant_role" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resolve_media_asset_delivery"("p_asset_id" "uuid", "p_usage_link_id" "uuid", "p_exact_asset_revision_id" "uuid", "p_requested_variant_role" "text") IS 'Phase 4A Media resolver with exact approved delivery and a narrow untouched-legacy compatibility lane.';



CREATE OR REPLACE FUNCTION "public"."resolve_playlist_item_match"("p_playlist_id" "uuid", "p_playlist_item_id" "uuid", "p_expected_authority_revision" bigint, "p_match_status" "text", "p_idempotency_key" "text", "p_registry_track_id" "uuid" DEFAULT NULL::"uuid", "p_match_confidence" numeric DEFAULT NULL::numeric, "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("command_receipt_id" "uuid", "receipt_status" "text", "playlist_id" "uuid", "resource_id" "uuid", "playlist_item_id" "uuid", "authority_revision" bigint, "result_payload" "jsonb", "idempotent_replay" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'editorial', 'platform_private'
    AS $$
declare
  v_playlist public.wk_playlists%rowtype;
  v_item public.wk_playlist_items%rowtype;
  v_resource_id uuid;
  v_registry_release_id uuid;
  v_title text;
  v_artist_names text[];
  v_release_title text;
  v_artwork_url text;
  v_preview_url text;
  v_duration_ms integer;
  v_isrc text;
  v_duplicate_ids uuid[];
  v_begin record;
  v_read record;
  v_request jsonb;
  v_result jsonb;
  v_correlation_id uuid := coalesce(p_correlation_id, gen_random_uuid());
begin
  if p_playlist_id is null
     or p_playlist_item_id is null
     or p_expected_authority_revision is null
     or p_expected_authority_revision < 1
  then
    raise exception
      using
        errcode = '22023',
        message = 'Playlist, item, and expected authority revision are required.';
  end if;

  if p_match_status not in (
    'matched',
    'external_only',
    'missing_registry_track',
    'needs_review',
    'rejected',
    'pending'
  ) then
    raise exception using errcode = '22023', message = 'Playlist-item match status is invalid.';
  end if;

  if p_match_confidence is not null
     and (p_match_confidence < 0 or p_match_confidence > 1)
  then
    raise exception using errcode = '22023', message = 'Match confidence must be between 0 and 1.';
  end if;

  if p_match_status = 'matched' and p_registry_track_id is null then
    raise exception using errcode = '22023', message = 'A matched Playlist item requires a Registry track.';
  end if;

  if p_match_status <> 'matched' and p_registry_track_id is not null then
    raise exception using errcode = '22023', message = 'Only matched Playlist items may bind canonical Registry track identity.';
  end if;

  select playlist.*
  into v_playlist
  from public.wk_playlists playlist
  where playlist.id = p_playlist_id
  for update of playlist;

  select binding.resource_id
  into v_resource_id
  from editorial.playlist_resources binding
  where binding.playlist_id = p_playlist_id;

  if not found then
    raise exception using errcode = 'P0002', message = 'Playlist does not exist.';
  end if;

  if not editorial.current_user_can_edit_playlist(v_resource_id) then
    raise exception using errcode = '42501', message = 'Playlist edit permission is required.';
  end if;

  v_request := jsonb_build_object(
    'playlist_id', p_playlist_id,
    'playlist_item_id', p_playlist_item_id,
    'expected_authority_revision', p_expected_authority_revision,
    'match_status', p_match_status,
    'registry_track_id', p_registry_track_id,
    'match_confidence', p_match_confidence,
    'correlation_id', v_correlation_id
  );

  select *
  into v_begin
  from platform_private.begin_authenticated_resource_command(
    'playlist.item.match.resolve',
    v_resource_id,
    p_idempotency_key,
    v_request
  );

  if not v_begin.idempotent_replay then
    if v_playlist.authority_revision <> p_expected_authority_revision then
      perform platform_private.reject_resource_command(
        v_begin.command_receipt_id,
        'playlist_revision_changed',
        'The Playlist changed before this match could be resolved.',
        jsonb_build_object(
          'playlist_id', p_playlist_id,
          'authority_revision', v_playlist.authority_revision
        )
      );
    else
      select item.*
      into v_item
      from public.wk_playlist_items item
      where item.id = p_playlist_item_id
        and item.playlist_id = p_playlist_id
        and item.lifecycle_state = 'active'
      for update;

      if not found then
        perform platform_private.reject_resource_command(
          v_begin.command_receipt_id,
          'playlist_item_not_active',
          'The Playlist item is missing or no longer active.',
          jsonb_build_object(
            'playlist_id', p_playlist_id,
            'authority_revision', v_playlist.authority_revision
          )
        );
      else
        if p_match_status = 'matched' then
          select
            track.title,
            track.release_id,
            release.title,
            track.artwork_url,
            track.preview_url,
            track.duration_ms,
            track.isrc,
            coalesce(
              array_agg(
                coalesce(artist.display_name, link.artist_name_text)
                order by link.credit_order, link.id
              ) filter (
                where coalesce(artist.display_name, link.artist_name_text) is not null
              ),
              '{}'::text[]
            )
          into
            v_title,
            v_registry_release_id,
            v_release_title,
            v_artwork_url,
            v_preview_url,
            v_duration_ms,
            v_isrc,
            v_artist_names
          from public.registry_tracks track
          left join public.registry_releases release
            on release.id = track.release_id
          left join public.registry_track_artists link
            on link.track_id = track.id
            and link.status = 'active'
          left join public.registry_artists artist
            on artist.id = link.artist_id
          where track.id = p_registry_track_id
            and track.status = 'active'
          group by
            track.id,
            track.title,
            track.release_id,
            release.title,
            track.artwork_url,
            track.preview_url,
            track.duration_ms,
            track.isrc;

          if not found then
            perform platform_private.reject_resource_command(
              v_begin.command_receipt_id,
              'registry_track_unavailable',
              'The selected Registry track is not active.',
              jsonb_build_object(
                'playlist_id', p_playlist_id,
                'authority_revision', v_playlist.authority_revision
              )
            );
          end if;
        end if;

        if exists (
          select 1
          from platform_private.command_receipts receipt
          where receipt.id = v_begin.command_receipt_id
            and receipt.status = 'accepted'
        ) then
          update public.wk_playlist_items item
          set
            registry_track_id = case
              when p_match_status = 'matched' then p_registry_track_id
              else null
            end,
            registry_release_id = case
              when p_match_status = 'matched' then v_registry_release_id
              else null
            end,
            title = case
              when p_match_status = 'matched' then v_title
              else item.title
            end,
            artist_names = case
              when p_match_status = 'matched' then v_artist_names
              else item.artist_names
            end,
            release_title = case
              when p_match_status = 'matched' then v_release_title
              else item.release_title
            end,
            artwork_url = case
              when p_match_status = 'matched' then coalesce(v_artwork_url, item.artwork_url)
              else item.artwork_url
            end,
            preview_url = case
              when p_match_status = 'matched' then coalesce(v_preview_url, item.preview_url)
              else item.preview_url
            end,
            duration_ms = case
              when p_match_status = 'matched' then coalesce(v_duration_ms, item.duration_ms)
              else item.duration_ms
            end,
            isrc = case
              when p_match_status = 'matched' then coalesce(v_isrc, item.isrc)
              else item.isrc
            end,
            match_status = p_match_status,
            match_confidence = case
              when p_match_status in ('matched', 'needs_review')
                then p_match_confidence
              else null
            end,
            normalization_payload = case
              when p_match_status = 'matched'
                then jsonb_build_object('resolved_by', auth.uid())
              else item.normalization_payload
            end
          where item.id = p_playlist_item_id
          returning item.*
          into v_item;

          v_duplicate_ids := editorial.playlist_duplicate_item_ids(
            p_playlist_id,
            p_playlist_item_id,
            v_item.registry_track_id,
            v_item.provider_key,
            v_item.provider_track_id,
            v_item.title,
            v_item.artist_names
          );

          update public.wk_playlists playlist
          set authority_revision = playlist.authority_revision + 1
          where playlist.id = p_playlist_id
          returning playlist.authority_revision
          into v_playlist.authority_revision;

          v_result := jsonb_build_object(
            'playlist_id', p_playlist_id,
            'playlist_item_id', p_playlist_item_id,
            'match_status', p_match_status,
            'registry_track_id', v_item.registry_track_id,
            'duplicate_warning', cardinality(v_duplicate_ids) > 0,
            'duplicate_item_ids', to_jsonb(v_duplicate_ids),
            'authority_revision', v_playlist.authority_revision,
            'correlation_id', v_correlation_id
          );

          perform platform_private.complete_resource_command(
            v_begin.command_receipt_id,
            v_result
          );
        end if;
      end if;
    end if;
  end if;

  select *
  into v_read
  from platform_private.read_authenticated_resource_command_result(
    v_begin.command_receipt_id,
    v_begin.idempotent_replay
  );

  command_receipt_id := v_read.command_receipt_id;
  receipt_status := v_read.receipt_status;
  playlist_id := p_playlist_id;
  resource_id := v_read.resource_id;
  playlist_item_id := p_playlist_item_id;
  authority_revision := nullif(v_read.result_payload ->> 'authority_revision', '')::bigint;
  result_payload := v_read.result_payload;
  idempotent_replay := v_read.idempotent_replay;
  return next;
end;
$$;


ALTER FUNCTION "public"."resolve_playlist_item_match"("p_playlist_id" "uuid", "p_playlist_item_id" "uuid", "p_expected_authority_revision" bigint, "p_match_status" "text", "p_idempotency_key" "text", "p_registry_track_id" "uuid", "p_match_confidence" numeric, "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_playlist_preview_nonce"("p_nonce" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_link public.wk_playlist_preview_links%rowtype;
  v_payload jsonb;
begin
  select link.*
  into v_link
  from public.wk_playlist_preview_links link
  where link.nonce = p_nonce
    and link.revoked_at is null
    and link.expires_at > now()
  limit 1;

  if not found then
    return null;
  end if;

  v_payload :=
    editorial.playlist_version_public_presentation_json(
      v_link.version_id
    );

  if v_payload is null then
    return null;
  end if;

  return
    v_payload
    ||
    jsonb_build_object(
      'preview_nonce', v_link.nonce,
      'preview_expires_at', v_link.expires_at
    );
end;
$$;


ALTER FUNCTION "public"."resolve_playlist_preview_nonce"("p_nonce" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_registry_relationship_endpoint"("p_relationship_id" "uuid", "p_endpoint_side" "text", "p_entity_type" "text", "p_entity_id" "uuid", "p_reason" "text") RETURNS "public"."registry_entity_relationships"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_entity public.registry_entity_index;
  v_updated public.registry_entity_relationships;
begin
  if not (
    auth.role() = 'service_role'
    or public.current_user_has_capability('manage_registry')
    or public.current_user_has_capability('manage_review_queue')
    or public.current_user_is_administrator()
  ) then
    raise exception 'You do not have permission to resolve Registry relationship endpoints.';
  end if;

  if p_endpoint_side not in ('source','target') then
    raise exception 'Endpoint side must be source or target.';
  end if;

  if nullif(btrim(p_reason), '') is null then
    raise exception 'A resolution reason is required.';
  end if;

  select * into v_entity
  from public.registry_entity_index
  where entity_type = btrim(p_entity_type)
    and entity_id = p_entity_id
  limit 1;

  if not found then
    raise exception 'Canonical Registry entity not found.';
  end if;

  if p_endpoint_side = 'source' then
    update public.registry_entity_relationships
    set source_entity_type = v_entity.entity_type,
        source_entity_id = v_entity.entity_id,
        source_slug = coalesce(nullif(btrim(v_entity.slug), ''), v_entity.entity_id::text),
        updated_by = auth.uid(),
        updated_at = now(),
        review_status = case when review_status = 'approved' then 'pending_review' else review_status end,
        public_safe = false,
        status_reason = btrim(p_reason)
    where id = p_relationship_id
    returning * into v_updated;
  else
    update public.registry_entity_relationships
    set target_entity_type = v_entity.entity_type,
        target_entity_id = v_entity.entity_id,
        target_slug = coalesce(nullif(btrim(v_entity.slug), ''), v_entity.entity_id::text),
        updated_by = auth.uid(),
        updated_at = now(),
        review_status = case when review_status = 'approved' then 'pending_review' else review_status end,
        public_safe = false,
        status_reason = btrim(p_reason)
    where id = p_relationship_id
    returning * into v_updated;
  end if;

  if not found then
    raise exception 'Registry relationship not found.';
  end if;

  insert into public.review_decisions (
    subject_type,
    subject_id,
    decision,
    reason,
    reviewer_id
  ) values (
    'relationship',
    p_relationship_id,
    'needs_more_evidence',
    btrim(p_reason),
    auth.uid()
  );

  return v_updated;
end;
$$;


ALTER FUNCTION "public"."resolve_registry_relationship_endpoint"("p_relationship_id" "uuid", "p_endpoint_side" "text", "p_entity_type" "text", "p_entity_id" "uuid", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resolve_registry_relationship_endpoint"("p_relationship_id" "uuid", "p_endpoint_side" "text", "p_entity_type" "text", "p_entity_id" "uuid", "p_reason" "text") IS 'Resolves one legacy relationship endpoint to a reviewed canonical Registry entity and records the decision.';



CREATE OR REPLACE FUNCTION "public"."resolve_registry_relationship_endpoint_from_alias"("p_relationship_id" "uuid", "p_endpoint_side" "text", "p_reason" "text") RETURNS "public"."registry_entity_relationships"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$ declare v_relationship public.registry_entity_relationships; v_slug text; v_candidate_id uuid; v_match_count integer; v_result public.registry_entity_relationships; begin if not (auth.role()='service_role' or public.current_user_has_capability('manage_registry') or public.current_user_has_capability('manage_review_queue') or public.current_user_is_administrator()) then raise exception 'You do not have permission to resolve Registry relationship endpoints.'; end if; if p_endpoint_side not in ('source','target') then raise exception 'Endpoint side must be source or target.'; end if; if nullif(btrim(p_reason),'') is null then raise exception 'A resolution reason is required.'; end if; select * into v_relationship from public.registry_entity_relationships where id=p_relationship_id for update; if not found then raise exception 'Registry relationship not found.'; end if; v_slug:=case when p_endpoint_side='source' then v_relationship.source_slug else v_relationship.target_slug end; select count(*)::integer,min(a.canonical_artist_id::text)::uuid into v_match_count,v_candidate_id from public.registry_artist_aliases a where a.alias_slug=v_slug and coalesce(a.status,'active')<>'rejected'; if v_match_count=0 then raise exception 'No active canonical artist alias match was found.'; end if; if v_match_count>1 then raise exception 'The artist alias is ambiguous and requires manual review.'; end if; select public.resolve_registry_relationship_endpoint(p_relationship_id,p_endpoint_side,'artist',v_candidate_id,p_reason) into v_result; return v_result; end; $$;


ALTER FUNCTION "public"."resolve_registry_relationship_endpoint_from_alias"("p_relationship_id" "uuid", "p_endpoint_side" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."restore_article_from_archive"("p_article_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS TABLE("article_id" "uuid", "article_slug" "text", "draft_version" bigint, "version_id" "uuid", "version_number" bigint, "lifecycle_status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_article public.wk_articles%rowtype;
  v_resource editorial.resources%rowtype;
  v_prior_status text;
  v_target_version_id uuid;
  v_target_number bigint;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  select article.*
  into v_article
  from public.wk_articles article
  where article.id = p_article_id
  for update;

  if not found then
    raise exception 'Article not found';
  end if;

  select resource.*
  into v_resource
  from editorial.article_resources binding
  join editorial.resources resource
    on resource.id = binding.resource_id
  where binding.article_id = p_article_id
  for update of resource;

  if not found then
    raise exception 'Article resource identity not found';
  end if;

  if not editorial.current_user_can_edit_article(v_resource.id) then
    raise exception 'Permission denied';
  end if;

  v_prior_status := v_article.wp_status;
  v_target_version_id :=
    coalesce(
      v_resource.current_working_version_id,
      v_resource.current_published_version_id
    );

  select version.version_number
  into v_target_number
  from editorial.article_versions version
  where version.id = v_target_version_id;

  update public.wk_articles as article
  set
    wp_status = 'draft',
    draft_version = article.draft_version + 1,
    updated_at = now(),
    modified_at = now()
  where article.id = p_article_id
  returning article.*
  into v_article;

  update editorial.resources
  set
    lifecycle_state = 'draft',
    visibility = 'private',
    updated_at = now()
  where id = v_resource.id;

  insert into editorial.article_lifecycle_events (
    resource_id,
    article_id,
    version_id,
    action,
    prior_status,
    resulting_status,
    note
  )
  values (
    v_resource.id,
    p_article_id,
    v_target_version_id,
    'restored',
    v_prior_status,
    'draft',
    p_note
  );

  article_id := p_article_id;
  article_slug := v_article.slug;
  draft_version := v_article.draft_version;
  version_id := v_target_version_id;
  version_number := coalesce(v_target_number, 0);
  lifecycle_status := 'restored';
  return next;
end;
$$;


ALTER FUNCTION "public"."restore_article_from_archive"("p_article_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."restore_media_asset"("p_asset_id" "uuid", "p_expected_authority_revision" bigint, "p_reason" "text", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("asset_id" "uuid", "lifecycle_state" "text", "authority_revision" bigint, "correlation_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'media', 'auth'
    AS $$
declare
  v_actor_id uuid;
  v_asset media.assets%rowtype;
  v_correlation_id uuid := coalesce(
    p_correlation_id,
    gen_random_uuid()
  );
begin
  v_actor_id :=
    media.require_command_actor('archive_media_assets');

  if nullif(btrim(p_reason), '') is null then
    raise exception 'Media restore reason is required';
  end if;

  select *
  into v_asset
  from media.assets
  where id = p_asset_id
  for update;

  if not found then
    raise exception 'Media asset does not exist';
  end if;

  if v_asset.authority_revision <>
     p_expected_authority_revision
  then
    raise exception
      'Stale Media authority revision: expected %, current %',
      p_expected_authority_revision,
      v_asset.authority_revision;
  end if;

  if v_asset.lifecycle_state <> 'archived' then
    raise exception 'Only archived Media assets may be restored';
  end if;

  update media.assets as asset_row
  set
    lifecycle_state = 'active',
    authority_revision = asset_row.authority_revision + 1,
    archived_by = null,
    archived_at = null,
    archive_reason = null,
    updated_by = v_actor_id,
    updated_at = now()
  where asset_row.id = p_asset_id;

  insert into media.events (
    asset_id,
    event_type,
    actor_id,
    reason,
    prior_state,
    resulting_state,
    correlation_id
  )
  values (
    p_asset_id,
    'asset_restored',
    v_actor_id,
    btrim(p_reason),
    jsonb_build_object(
      'lifecycle_state', v_asset.lifecycle_state,
      'authority_revision', v_asset.authority_revision
    ),
    jsonb_build_object(
      'lifecycle_state', 'active',
      'authority_revision',
      v_asset.authority_revision + 1
    ),
    v_correlation_id
  );

  return query
  select
    p_asset_id,
    'active'::text,
    v_asset.authority_revision + 1,
    v_correlation_id;
end;
$$;


ALTER FUNCTION "public"."restore_media_asset"("p_asset_id" "uuid", "p_expected_authority_revision" bigint, "p_reason" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."restore_playlist_from_archive"("p_playlist_id" "uuid", "p_expected_authority_revision" bigint, "p_idempotency_key" "text", "p_note" "text" DEFAULT NULL::"text", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("command_receipt_id" "uuid", "receipt_status" "text", "playlist_id" "uuid", "resource_id" "uuid", "authority_revision" bigint, "version_id" "uuid", "version_number" bigint, "lifecycle_status" "text", "result_payload" "jsonb", "idempotent_replay" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'editorial', 'platform_private'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_playlist public.wk_playlists%rowtype;
  v_binding editorial.playlist_resources%rowtype;
  v_target editorial.playlist_versions%rowtype;
  v_begin record;
  v_read record;
  v_result jsonb;
  v_correlation_id uuid :=
    coalesce(
      p_correlation_id,
      gen_random_uuid()
    );
begin
  if v_actor is null then
    raise exception 'Not authenticated';
  end if;

  select playlist.*
  into v_playlist
  from public.wk_playlists playlist
  where playlist.id = p_playlist_id
  for update;

  if not found then
    raise exception 'Playlist does not exist';
  end if;

  select binding.*
  into v_binding
  from editorial.playlist_resources binding
  where binding.playlist_id = p_playlist_id
  for update;

  if not found then
    raise exception
      'Playlist Resource binding does not exist';
  end if;

  if not editorial.current_user_can_edit_playlist(
    v_binding.resource_id
  ) then
    raise exception
      'Playlist edit permission is required';
  end if;

  select version.*
  into v_target
  from editorial.playlist_versions version
  where version.id = coalesce(
    v_binding.current_working_version_id,
    v_binding.current_submitted_version_id,
    v_binding.current_approved_version_id,
    v_binding.current_published_version_id
  );

  select *
  into v_begin
  from platform_private.begin_authenticated_resource_command(
    'playlist.restore',
    v_binding.resource_id,
    p_idempotency_key,
    jsonb_build_object(
      'playlist_id',
        p_playlist_id,
      'expected_authority_revision',
        p_expected_authority_revision,
      'note',
        nullif(btrim(p_note), ''),
      'correlation_id',
        v_correlation_id
    )
  );

  if v_begin.idempotent_replay then
    select *
    into v_read
    from platform_private.read_authenticated_resource_command_result(
      v_begin.command_receipt_id,
      true
    );

    command_receipt_id := v_read.command_receipt_id;
    receipt_status := v_read.receipt_status;
    playlist_id := p_playlist_id;
    resource_id := v_read.resource_id;
    authority_revision :=
      nullif(
        v_read.result_payload ->> 'authority_revision',
        ''
      )::bigint;
    version_id :=
      nullif(
        v_read.result_payload ->> 'version_id',
        ''
      )::uuid;
    version_number :=
      nullif(
        v_read.result_payload ->> 'version_number',
        ''
      )::bigint;
    lifecycle_status :=
      v_read.result_payload ->> 'lifecycle_status';
    result_payload := v_read.result_payload;
    idempotent_replay := true;
    return next;
    return;
  end if;

  if p_expected_authority_revision is null
     or p_expected_authority_revision < 1
     or v_playlist.authority_revision <>
          p_expected_authority_revision
  then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'playlist_revision_changed',
      'The Playlist changed before it could be restored.',
      jsonb_build_object(
        'playlist_id',
          p_playlist_id,
        'authority_revision',
          v_playlist.authority_revision
      )
    );

  elsif v_playlist.status <> 'archived'
  then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'playlist_not_archived',
      'Only an archived Playlist can be restored.',
      jsonb_build_object(
        'playlist_id',
          p_playlist_id,
        'lifecycle_status',
          v_playlist.status
      )
    );

  else
    update editorial.resources resource
    set
      lifecycle_state = 'draft',
      visibility = 'private',
      updated_at = now()
    where resource.id =
            v_binding.resource_id;

    update public.wk_playlists playlist
    set
      status = 'draft',
      authority_revision =
        playlist.authority_revision + 1,
      updated_at = now()
    where playlist.id = p_playlist_id
    returning playlist.*
    into v_playlist;

    perform editorial.append_playlist_lifecycle_event(
      v_binding.resource_id,
      p_playlist_id,
      v_target.id,
      'restored',
      'archived',
      'draft',
      p_note,
      v_actor,
      v_begin.command_receipt_id,
      jsonb_build_object(
        'correlation_id',
          v_correlation_id
      )
    );

    v_result := jsonb_build_object(
      'playlist_id',
        p_playlist_id,
      'resource_id',
        v_binding.resource_id,
      'authority_revision',
        v_playlist.authority_revision,
      'version_id',
        v_target.id,
      'version_number',
        v_target.version_number,
      'lifecycle_status',
        'draft',
      'correlation_id',
        v_correlation_id
    );

    perform platform_private.complete_resource_command(
      v_begin.command_receipt_id,
      v_result
    );
  end if;

  select *
  into v_read
  from platform_private.read_authenticated_resource_command_result(
    v_begin.command_receipt_id,
    false
  );

  command_receipt_id := v_read.command_receipt_id;
  receipt_status := v_read.receipt_status;
  playlist_id := p_playlist_id;
  resource_id := v_read.resource_id;
  authority_revision :=
    nullif(
      v_read.result_payload ->> 'authority_revision',
      ''
    )::bigint;
  version_id :=
    nullif(
      v_read.result_payload ->> 'version_id',
      ''
    )::uuid;
  version_number :=
    nullif(
      v_read.result_payload ->> 'version_number',
      ''
    )::bigint;
  lifecycle_status :=
    v_read.result_payload ->> 'lifecycle_status';
  result_payload := v_read.result_payload;
  idempotent_replay := false;
  return next;
end;
$$;


ALTER FUNCTION "public"."restore_playlist_from_archive"("p_playlist_id" "uuid", "p_expected_authority_revision" bigint, "p_idempotency_key" "text", "p_note" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."restore_source"("p_source_id" "uuid", "p_reason" "text", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial', 'auth'
    AS $$
declare
  v_actor_id uuid;
  v_source editorial.sources%rowtype;
begin
  v_actor_id :=
    editorial.assert_source_command_actor('withdraw_sources');

  if nullif(btrim(p_reason), '') is null then
    raise exception
      'A Source restoration reason is required';
  end if;

  select *
  into v_source
  from editorial.sources source
  where source.id = p_source_id
  for update;

  if not found then
    raise exception
      'Source was not found';
  end if;

  if v_source.source_state <> 'withdrawn' then
    raise exception
      'Only a withdrawn Source can be restored';
  end if;

  update editorial.sources
  set
    source_state = 'active',
    review_status = 'changes_requested',
    exposure_class = 'internal',
    current_submitted_version_id = null,
    current_approved_version_id = null,
    reviewed_by = null,
    reviewed_at = null,
    withdrawn_by = null,
    withdrawn_at = null,
    withdrawal_reason = null,
    withdrawal_public_mode = 'hide_public_reference',
    updated_by = v_actor_id,
    updated_at = now()
  where id = p_source_id;

  insert into editorial.source_review_events (
    source_id,
    source_version_id,
    actor_id,
    action,
    reason,
    prior_review_status,
    resulting_review_status,
    prior_exposure_class,
    resulting_exposure_class,
    prior_source_state,
    resulting_source_state,
    correlation_id
  )
  values (
    p_source_id,
    v_source.current_working_version_id,
    v_actor_id,
    'restored',
    btrim(p_reason),
    v_source.review_status,
    'changes_requested',
    v_source.exposure_class,
    'internal',
    v_source.source_state,
    'active',
    p_correlation_id
  );

  return jsonb_build_object(
    'source_id',
      p_source_id,
    'source_state',
      'active',
    'review_status',
      'changes_requested',
    'exposure_class',
      'internal',
    'working_revision',
      v_source.working_revision
  );
end;
$$;


ALTER FUNCTION "public"."restore_source"("p_source_id" "uuid", "p_reason" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."restore_source"("p_source_id" "uuid", "p_reason" "text", "p_correlation_id" "uuid") IS 'Restores a withdrawn Source to an internal changes-requested state.';



CREATE OR REPLACE FUNCTION "public"."return_correction_to_investigation"("p_case_resource_id" "uuid", "p_expected_case_revision" bigint, "p_reason" "text", "p_idempotency_key" "text", "p_correlation_id" "uuid") RETURNS TABLE("command_receipt_id" "uuid", "receipt_status" "text", "case_resource_id" "uuid", "case_revision" bigint, "result_payload" "jsonb", "idempotent_replay" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'editorial', 'platform_private'
    AS $$
declare
  v_actor uuid;
  v_begin record;
  v_case editorial.correction_cases%rowtype;
  v_result jsonb;
begin
  v_actor :=
    platform_private.assert_correction_capability(
      'investigate_corrections'
    );

  if p_case_resource_id is null
     or p_expected_case_revision < 1
     or p_correlation_id is null
     or nullif(btrim(p_reason), '') is null
  then
    raise exception
      using errcode = '22023',
      message = 'Case, revision, reason, and correlation identity are required.';
  end if;

  select *
  into v_begin
  from platform_private.begin_resource_command(
    'correction.case.return_to_investigation',
    p_case_resource_id,
    p_idempotency_key,
    jsonb_build_object(
      'expected_case_revision', p_expected_case_revision,
      'reason', btrim(p_reason),
      'correlation_id', p_correlation_id
    )
  );

  if v_begin.idempotent_replay then
    return query
    select *
    from platform_private.read_correction_command_result(
      v_begin.command_receipt_id,
      true
    );
    return;
  end if;

  select correction_case.*
  into v_case
  from editorial.correction_cases correction_case
  where correction_case.resource_id =
    p_case_resource_id
  for update;

  if not found then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'case_not_found',
      'The correction case does not exist.',
      jsonb_build_object('case_revision', null)
    );
  elsif v_case.current_revision <>
        p_expected_case_revision
  then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'case_revision_changed',
      'The correction case revision changed.',
      jsonb_build_object(
        'case_revision', v_case.current_revision,
        'case_state', v_case.case_state
      )
    );
  elsif v_case.case_state <>
        'awaiting_decision'
  then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'invalid_transition',
      'Only awaiting-decision cases may return to investigation.',
      jsonb_build_object(
        'case_revision', v_case.current_revision,
        'case_state', v_case.case_state
      )
    );
  else
    update editorial.correction_cases
    set
      case_state = 'investigating',
      current_revision =
        v_case.current_revision + 1,
      submitted_for_decision_by = null,
      submitted_for_decision_at = null,
      evidence_ready = false,
      updated_by = v_actor,
      updated_at = now()
    where resource_id = p_case_resource_id;

    perform platform_private.append_correction_event(
      p_case_resource_id,
      'returned_to_investigation',
      v_case.current_revision,
      v_case.current_revision + 1,
      v_case.case_state,
      'investigating',
      v_actor,
      btrim(p_reason),
      null,
      null,
      null,
      null,
      v_begin.command_receipt_id,
      p_correlation_id,
      '{}'::jsonb
    );

    v_result := jsonb_build_object(
      'case_resource_id', p_case_resource_id,
      'case_revision', v_case.current_revision + 1,
      'case_state', 'investigating'
    );

    perform platform_private.complete_resource_command(
      v_begin.command_receipt_id,
      v_result
    );
  end if;

  return query
  select *
  from platform_private.read_correction_command_result(
    v_begin.command_receipt_id,
    false
  );
end;
$$;


ALTER FUNCTION "public"."return_correction_to_investigation"("p_case_resource_id" "uuid", "p_expected_case_revision" bigint, "p_reason" "text", "p_idempotency_key" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."evidence_items" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "title" "text" NOT NULL,
    "evidence_type" "text" NOT NULL,
    "source_url" "text",
    "source_file" "text",
    "source_note" "text",
    "summary" "text" NOT NULL,
    "main_claim" "text",
    "why_it_matters" "text",
    "reliability" "text" DEFAULT 'medium'::"text" NOT NULL,
    "confidence" "text" DEFAULT 'medium'::"text" NOT NULL,
    "review_status" "text" DEFAULT 'unreviewed'::"text" NOT NULL,
    "retrieval_status" "text" DEFAULT 'excluded'::"text" NOT NULL,
    "created_by" "uuid" DEFAULT "auth"."uid"(),
    "reviewed_by" "uuid",
    "reviewed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "evidence_default_retrieval_requires_review" CHECK ((("retrieval_status" <> 'default_retrieval'::"text") OR ("review_status" = ANY (ARRAY['reviewed'::"text", 'approved'::"text"])))),
    CONSTRAINT "evidence_items_confidence_check" CHECK (("confidence" = ANY (ARRAY['low'::"text", 'medium'::"text", 'high'::"text"]))),
    CONSTRAINT "evidence_items_evidence_type_check" CHECK (("evidence_type" = ANY (ARRAY['internal_memory'::"text", 'book_reference'::"text", 'field_note'::"text", 'article'::"text", 'official_documentation'::"text", 'academic_paper'::"text", 'chart_record'::"text", 'release_metadata'::"text", 'track_metadata'::"text", 'artist_metadata'::"text", 'contributor_memory'::"text", 'correction'::"text", 'interview'::"text", 'video'::"text", 'screenshot'::"text", 'product_test'::"text", 'technical_test'::"text"]))),
    CONSTRAINT "evidence_items_reliability_check" CHECK (("reliability" = ANY (ARRAY['low'::"text", 'medium'::"text", 'high'::"text"]))),
    CONSTRAINT "evidence_items_retrieval_status_check" CHECK (("retrieval_status" = ANY (ARRAY['excluded'::"text", 'review_only'::"text", 'default_retrieval'::"text"]))),
    CONSTRAINT "evidence_items_review_status_check" CHECK (("review_status" = ANY (ARRAY['unreviewed'::"text", 'reviewed'::"text", 'approved'::"text", 'disputed'::"text", 'rejected'::"text"]))),
    CONSTRAINT "evidence_reviewed_states_require_reviewer" CHECK ((("review_status" = 'unreviewed'::"text") OR (("reviewed_by" IS NOT NULL) AND ("reviewed_at" IS NOT NULL))))
);


ALTER TABLE "public"."evidence_items" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."review_evidence_item"("p_evidence_id" "uuid", "p_decision" "text", "p_next_review_status" "text", "p_next_retrieval_status" "text", "p_decision_note" "text" DEFAULT NULL::"text") RETURNS "public"."evidence_items"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_current public.evidence_items;
  v_updated public.evidence_items;
begin
  if not public.institute_can_review() then
    raise exception 'You do not have permission to review evidence.';
  end if;

  if p_decision not in ('reviewed','approved','rejected','disputed','needs_more_evidence','retrieval_enabled','retrieval_disabled') then
    raise exception 'Unsupported evidence review decision.';
  end if;

  if p_next_review_status not in ('unreviewed','reviewed','approved','disputed','rejected') then
    raise exception 'Unsupported next review status.';
  end if;

  if p_next_retrieval_status not in ('excluded','review_only','default_retrieval') then
    raise exception 'Unsupported next retrieval status.';
  end if;

  if p_next_retrieval_status = 'default_retrieval'
     and p_next_review_status not in ('reviewed','approved') then
    raise exception 'Default retrieval requires reviewed or approved evidence.';
  end if;

  if p_next_review_status in ('rejected','disputed')
     and p_next_retrieval_status = 'default_retrieval' then
    raise exception 'Rejected or disputed evidence cannot be enabled for default retrieval.';
  end if;

  select * into v_current
  from public.evidence_items
  where id = p_evidence_id
  for update;

  if not found then
    raise exception 'Evidence item not found.';
  end if;

  insert into public.evidence_review_events (
    evidence_id, decision, previous_review_status, next_review_status,
    previous_retrieval_status, next_retrieval_status, decision_note, decided_by
  ) values (
    p_evidence_id, p_decision, v_current.review_status, p_next_review_status,
    v_current.retrieval_status, p_next_retrieval_status,
    nullif(btrim(p_decision_note), ''), auth.uid()
  );

  update public.evidence_items
  set review_status = p_next_review_status,
      retrieval_status = p_next_retrieval_status,
      reviewed_by = auth.uid(),
      reviewed_at = now(),
      updated_at = now()
  where id = p_evidence_id
  returning * into v_updated;

  return v_updated;
end;
$$;


ALTER FUNCTION "public"."review_evidence_item"("p_evidence_id" "uuid", "p_decision" "text", "p_next_review_status" "text", "p_next_retrieval_status" "text", "p_decision_note" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."review_evidence_item"("p_evidence_id" "uuid", "p_decision" "text", "p_next_review_status" "text", "p_next_retrieval_status" "text", "p_decision_note" "text") IS 'Atomically records an evidence review event and applies the approved review and retrieval state transition.';



CREATE OR REPLACE FUNCTION "public"."review_playlist"("p_playlist_id" "uuid", "p_expected_authority_revision" bigint, "p_submitted_version_id" "uuid", "p_decision" "text", "p_idempotency_key" "text", "p_note" "text" DEFAULT NULL::"text", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("command_receipt_id" "uuid", "receipt_status" "text", "playlist_id" "uuid", "resource_id" "uuid", "authority_revision" bigint, "version_id" "uuid", "version_number" bigint, "lifecycle_status" "text", "result_payload" "jsonb", "idempotent_replay" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'editorial', 'platform_private'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_playlist public.wk_playlists%rowtype;
  v_binding editorial.playlist_resources%rowtype;
  v_submitted editorial.playlist_versions%rowtype;
  v_approved record;
  v_begin record;
  v_read record;
  v_result jsonb;
  v_event_number bigint;
  v_prior_status text;
  v_result_status text;
  v_action text;
  v_result_version_id uuid;
  v_result_version_number bigint;
  v_correlation_id uuid :=
    coalesce(
      p_correlation_id,
      gen_random_uuid()
    );
begin
  if v_actor is null then
    raise exception 'Not authenticated';
  end if;

  if not (
    coalesce(
      public.current_user_is_administrator(),
      false
    )
    or coalesce(
      public.current_user_has_capability(
        'manage_review_queue'
      ),
      false
    )
  ) then
    raise exception
      'Review queue management permission is required';
  end if;

  if p_decision not in (
    'start_review',
    'request_changes',
    'approve'
  ) then
    raise exception
      'Choose a supported Playlist review decision';
  end if;

  if p_decision = 'request_changes'
     and nullif(
           btrim(p_note),
           ''
         ) is null
  then
    raise exception
      'Requested changes require a review note';
  end if;

  select playlist.*
  into v_playlist
  from public.wk_playlists playlist
  where playlist.id = p_playlist_id
  for update;

  if not found then
    raise exception 'Playlist does not exist';
  end if;

  select binding.*
  into v_binding
  from editorial.playlist_resources binding
  where binding.playlist_id = p_playlist_id
  for update;

  if v_binding.resource_id is null then
    raise exception
      'Playlist Resource binding does not exist';
  end if;

  select submitted.*
  into v_submitted
  from editorial.playlist_versions submitted
  where submitted.id = p_submitted_version_id
    and submitted.resource_id =
          v_binding.resource_id
    and submitted.playlist_id =
          p_playlist_id
    and submitted.version_kind =
          'submitted';

  select *
  into v_begin
  from platform_private.begin_authenticated_resource_command(
    'playlist.review.decide',
    v_binding.resource_id,
    p_idempotency_key,
    jsonb_build_object(
      'playlist_id',
        p_playlist_id,
      'expected_authority_revision',
        p_expected_authority_revision,
      'submitted_version_id',
        p_submitted_version_id,
      'decision',
        p_decision,
      'note',
        nullif(
          btrim(p_note),
          ''
        ),
      'correlation_id',
        v_correlation_id
    )
  );

  if v_begin.idempotent_replay then
    select *
    into v_read
    from platform_private.read_authenticated_resource_command_result(
      v_begin.command_receipt_id,
      true
    );

    command_receipt_id :=
      v_read.command_receipt_id;
    receipt_status :=
      v_read.receipt_status;
    playlist_id := p_playlist_id;
    resource_id := v_read.resource_id;
    authority_revision :=
      nullif(
        v_read.result_payload
          ->> 'authority_revision',
        ''
      )::bigint;
    version_id :=
      nullif(
        v_read.result_payload
          ->> 'version_id',
        ''
      )::uuid;
    version_number :=
      nullif(
        v_read.result_payload
          ->> 'version_number',
        ''
      )::bigint;
    lifecycle_status :=
      v_read.result_payload
        ->> 'lifecycle_status';
    result_payload :=
      v_read.result_payload;
    idempotent_replay := true;
    return next;
    return;
  end if;

  if p_expected_authority_revision is null
     or p_expected_authority_revision < 1
     or v_playlist.authority_revision
          <> p_expected_authority_revision
  then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'playlist_revision_changed',
      'The Playlist changed before the review decision could be applied.',
      jsonb_build_object(
        'playlist_id',
          p_playlist_id,
        'authority_revision',
          v_playlist.authority_revision,
        'lifecycle_status',
          v_playlist.status
      )
    );

  elsif v_binding.current_submitted_version_id
          is distinct from p_submitted_version_id
        or v_submitted.id is null
  then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'submitted_version_changed',
      'Review must target the exact current submitted Playlist version.',
      jsonb_build_object(
        'playlist_id',
          p_playlist_id,
        'authority_revision',
          v_playlist.authority_revision,
        'current_submitted_version_id',
          v_binding.current_submitted_version_id
      )
    );

  else
    v_prior_status := v_playlist.status;

    if p_decision = 'start_review' then
      if v_playlist.status <> 'ready_for_review' then
        perform platform_private.reject_resource_command(
          v_begin.command_receipt_id,
          'invalid_review_transition',
          'Only a ready Playlist can enter Review.',
          jsonb_build_object(
            'playlist_id',
              p_playlist_id,
            'authority_revision',
              v_playlist.authority_revision,
            'lifecycle_status',
              v_playlist.status
          )
        );
      else
        v_result_status := 'in_review';
        v_action := 'review_started';
        v_result_version_id :=
          v_submitted.id;
        v_result_version_number :=
          v_submitted.version_number;
      end if;

    elsif p_decision = 'request_changes' then
      if v_playlist.status not in (
        'ready_for_review',
        'in_review'
      ) then
        perform platform_private.reject_resource_command(
          v_begin.command_receipt_id,
          'invalid_review_transition',
          'The Playlist is not currently reviewable.',
          jsonb_build_object(
            'playlist_id',
              p_playlist_id,
            'authority_revision',
              v_playlist.authority_revision,
            'lifecycle_status',
              v_playlist.status
          )
        );
      else
        v_result_status :=
          'changes_requested';
        v_action :=
          'changes_requested';
        v_result_version_id :=
          v_submitted.id;
        v_result_version_number :=
          v_submitted.version_number;
      end if;

    else
      if v_playlist.status not in (
        'ready_for_review',
        'in_review'
      ) then
        perform platform_private.reject_resource_command(
          v_begin.command_receipt_id,
          'invalid_review_transition',
          'The Playlist is not currently reviewable.',
          jsonb_build_object(
            'playlist_id',
              p_playlist_id,
            'authority_revision',
              v_playlist.authority_revision,
            'lifecycle_status',
              v_playlist.status
          )
        );
      else
        select *
        into v_approved
        from editorial.copy_playlist_version_snapshot(
          v_submitted.id,
          v_actor
        );

        v_result_status := 'approved';
        v_action := 'approved';
        v_result_version_id :=
          v_approved.version_id;
        v_result_version_number :=
          v_approved.version_number;
      end if;
    end if;

    if exists (
      select 1
      from platform_private.command_receipts receipt
      where receipt.id =
              v_begin.command_receipt_id
        and receipt.status = 'accepted'
    )
    then
      if p_decision = 'approve' then
        update editorial.playlist_resources binding_update
        set current_approved_version_id =
              v_result_version_id
        where binding_update.playlist_id = p_playlist_id;

      elsif p_decision = 'request_changes' then
        update editorial.playlist_resources binding_update
        set current_approved_version_id = null
        where binding_update.playlist_id = p_playlist_id;
      end if;

      update public.wk_playlists playlist
      set
        status = v_result_status,
        authority_revision =
          playlist.authority_revision + 1
      where playlist.id = p_playlist_id
      returning playlist.*
      into v_playlist;

      select coalesce(
        max(event.event_number),
        0
      ) + 1
      into v_event_number
      from editorial.playlist_review_events event
      where event.resource_id =
              v_binding.resource_id;

      insert into editorial.playlist_review_events (
        resource_id,
        playlist_id,
        event_number,
        target_version_id,
        result_version_id,
        action,
        prior_status,
        resulting_status,
        reason,
        actor_id,
        command_receipt_id,
        correlation_id
      )
      values (
        v_binding.resource_id,
        p_playlist_id,
        v_event_number,
        v_submitted.id,
        case
          when p_decision = 'approve'
            then v_result_version_id
          else null
        end,
        v_action,
        v_prior_status,
        v_result_status,
        nullif(
          btrim(p_note),
          ''
        ),
        v_actor,
        v_begin.command_receipt_id,
        v_correlation_id
      );

      v_result := jsonb_build_object(
        'playlist_id',
          p_playlist_id,
        'resource_id',
          v_binding.resource_id,
        'authority_revision',
          v_playlist.authority_revision,
        'submitted_version_id',
          v_submitted.id,
        'version_id',
          v_result_version_id,
        'version_number',
          v_result_version_number,
        'lifecycle_status',
          v_result_status,
        'decision',
          p_decision,
        'correlation_id',
          v_correlation_id
      );

      perform platform_private.complete_resource_command(
        v_begin.command_receipt_id,
        v_result
      );
    end if;
  end if;

  select *
  into v_read
  from platform_private.read_authenticated_resource_command_result(
    v_begin.command_receipt_id,
    false
  );

  command_receipt_id :=
    v_read.command_receipt_id;
  receipt_status :=
    v_read.receipt_status;
  playlist_id := p_playlist_id;
  resource_id := v_read.resource_id;
  authority_revision :=
    nullif(
      v_read.result_payload
        ->> 'authority_revision',
      ''
    )::bigint;
  version_id :=
    nullif(
      v_read.result_payload
        ->> 'version_id',
      ''
    )::uuid;
  version_number :=
    nullif(
      v_read.result_payload
        ->> 'version_number',
      ''
    )::bigint;
  lifecycle_status :=
    v_read.result_payload
      ->> 'lifecycle_status';
  result_payload :=
    v_read.result_payload;
  idempotent_replay := false;
  return next;
end;
$$;


ALTER FUNCTION "public"."review_playlist"("p_playlist_id" "uuid", "p_expected_authority_revision" bigint, "p_submitted_version_id" "uuid", "p_decision" "text", "p_idempotency_key" "text", "p_note" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."review_registry_cultural_entity"("p_entity_id" "uuid", "p_next_review_status" "text", "p_next_status" "text", "p_public_safe" boolean, "p_reason" "text") RETURNS "public"."cultural_entities"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare v_current public.cultural_entities; v_updated public.cultural_entities; v_decision text;
begin
if not public.institute_can_review() then raise exception 'You do not have permission to review Registry cultural entities.'; end if;
if p_next_review_status not in ('pending_review','approved','rejected','disputed') then raise exception 'Unsupported cultural entity review status.'; end if;
if p_next_status not in ('draft','active','archived') then raise exception 'Unsupported cultural entity status.'; end if;
if nullif(btrim(p_reason),'') is null then raise exception 'A review reason is required.'; end if;
select * into v_current from public.cultural_entities where id=p_entity_id for update;
if not found then raise exception 'Registry cultural entity not found.'; end if;
if v_current.entity_type in ('artist','track','release','label','genre') then raise exception 'Music entities must be reviewed in their authoritative Registry tables.'; end if;
if p_public_safe and (p_next_review_status<>'approved' or p_next_status<>'active' or nullif(btrim(v_current.description),'') is null) then raise exception 'Public-safe cultural entities must be active, approved, and described.'; end if;
v_decision:=case when p_next_review_status='approved' then 'approved' when p_next_review_status='rejected' then 'rejected' else 'needs_more_evidence' end;
update public.cultural_entities set review_status=p_next_review_status,status=p_next_status,public_safe=p_public_safe,reviewed_by=auth.uid(),reviewed_at=now(),review_note=btrim(p_reason),updated_at=now() where id=p_entity_id returning * into v_updated;
insert into public.review_decisions(subject_type,subject_id,decision,reason,reviewer_id) values('cultural_entity',p_entity_id,v_decision,btrim(p_reason),auth.uid());
return v_updated;
end;$$;


ALTER FUNCTION "public"."review_registry_cultural_entity"("p_entity_id" "uuid", "p_next_review_status" "text", "p_next_status" "text", "p_public_safe" boolean, "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."review_registry_cultural_entity"("p_entity_id" "uuid", "p_next_review_status" "text", "p_next_status" "text", "p_public_safe" boolean, "p_reason" "text") IS 'Reviews a broader cultural entity, controls publication state, and records the shared review decision.';



CREATE OR REPLACE FUNCTION "public"."review_registry_relationship"("p_relationship_id" "uuid", "p_next_review_status" "text", "p_public_safe" boolean, "p_reason" "text") RETURNS "public"."registry_entity_relationships"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_current public.registry_entity_relationships;
  v_updated public.registry_entity_relationships;
  v_decision text;
begin
  if not public.institute_can_review() then
    raise exception 'You do not have permission to review Registry relationships.';
  end if;

  if p_next_review_status not in (
    'unreviewed',
    'pending_review',
    'approved',
    'rejected',
    'disputed'
  ) then
    raise exception 'Unsupported relationship review status.';
  end if;

  if nullif(btrim(p_reason), '') is null then
    raise exception 'A review reason is required.';
  end if;

  if p_public_safe and p_next_review_status <> 'approved' then
    raise exception 'Only approved relationships can be marked public-safe.';
  end if;

  select *
  into v_current
  from public.registry_entity_relationships
  where id = p_relationship_id
  for update;

  if not found then
    raise exception 'Registry relationship not found.';
  end if;

  v_decision := case
    when p_next_review_status = 'approved' then 'approved'
    when p_next_review_status = 'rejected' then 'rejected'
    else 'needs_more_evidence'
  end;

  update public.registry_entity_relationships
  set review_status = p_next_review_status,
      public_safe = p_public_safe,
      reviewed_by = auth.uid(),
      reviewed_at = now(),
      review_note = btrim(p_reason),
      status_reason = btrim(p_reason),
      updated_by = auth.uid(),
      updated_at = now()
  where id = p_relationship_id
  returning * into v_updated;

  insert into public.review_decisions (
    subject_type,
    subject_id,
    decision,
    reason,
    reviewer_id
  ) values (
    'relationship',
    p_relationship_id,
    v_decision,
    btrim(p_reason),
    auth.uid()
  );

  return v_updated;
end;
$$;


ALTER FUNCTION "public"."review_registry_relationship"("p_relationship_id" "uuid", "p_next_review_status" "text", "p_public_safe" boolean, "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."review_registry_relationship"("p_relationship_id" "uuid", "p_next_review_status" "text", "p_public_safe" boolean, "p_reason" "text") IS 'Atomically reviews a Registry relationship, enforces evidence requirements, and records the shared review decision.';



CREATE OR REPLACE FUNCTION "public"."review_source_version"("p_source_id" "uuid", "p_source_version_id" "uuid", "p_decision" "text", "p_reason" "text" DEFAULT NULL::"text", "p_exposure_class" "text" DEFAULT NULL::"text", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial', 'auth'
    AS $$
declare
  v_actor_id uuid;
  v_source editorial.sources%rowtype;
  v_resulting_status text;
  v_resulting_exposure text;
  v_action text;
begin
  v_actor_id :=
    editorial.assert_source_command_actor('review_sources');

  if p_decision not in (
    'start_review',
    'request_changes',
    'approve',
    'reject'
  ) then
    raise exception
      'Choose a supported Source review decision';
  end if;

  if p_decision in (
       'request_changes',
       'reject'
     )
     and nullif(btrim(p_reason), '') is null then
    raise exception
      'A review reason is required';
  end if;

  select *
  into v_source
  from editorial.sources source
  where source.id = p_source_id
  for update;

  if not found then
    raise exception
      'Source was not found';
  end if;

  if v_source.source_state <> 'active' then
    raise exception
      'Only active Sources can be reviewed';
  end if;

  if v_source.current_submitted_version_id
       is distinct from p_source_version_id then
    raise exception
      'Review must target the exact submitted Source version';
  end if;

  if not exists (
    select 1
    from editorial.source_versions source_version
    where source_version.id = p_source_version_id
      and source_version.source_id = p_source_id
  ) then
    raise exception
      'Source version does not belong to the Source';
  end if;

  if p_decision = 'start_review' then
    if v_source.review_status <> 'ready_for_review' then
      raise exception
        'Only a ready Source can enter review';
    end if;

    v_resulting_status := 'in_review';
    v_resulting_exposure := 'internal';
    v_action := 'review_started';

    update editorial.sources
    set
      review_status = v_resulting_status,
      exposure_class = v_resulting_exposure,
      updated_by = v_actor_id,
      updated_at = now()
    where id = p_source_id;

  elsif p_decision = 'request_changes' then
    if v_source.review_status not in (
      'ready_for_review',
      'in_review'
    ) then
      raise exception
        'Source is not currently reviewable';
    end if;

    v_resulting_status := 'changes_requested';
    v_resulting_exposure := 'internal';
    v_action := 'changes_requested';

    update editorial.sources
    set
      review_status = v_resulting_status,
      exposure_class = v_resulting_exposure,
      current_submitted_version_id = null,
      current_approved_version_id = null,
      reviewed_by = v_actor_id,
      reviewed_at = now(),
      updated_by = v_actor_id,
      updated_at = now()
    where id = p_source_id;

  elsif p_decision = 'approve' then
    if v_source.review_status not in (
      'ready_for_review',
      'in_review'
    ) then
      raise exception
        'Source is not currently reviewable';
    end if;

    if p_exposure_class not in (
      'public',
      'public_redacted',
      'internal'
    ) then
      raise exception
        'Approval requires public, public_redacted, or internal exposure';
    end if;

    v_resulting_status := 'approved';
    v_resulting_exposure := p_exposure_class;
    v_action := 'approved';

    update editorial.sources
    set
      review_status = v_resulting_status,
      exposure_class = v_resulting_exposure,
      current_approved_version_id = p_source_version_id,
      reviewed_by = v_actor_id,
      reviewed_at = now(),
      updated_by = v_actor_id,
      updated_at = now()
    where id = p_source_id;

  else
    if v_source.review_status not in (
      'ready_for_review',
      'in_review'
    ) then
      raise exception
        'Source is not currently reviewable';
    end if;

    v_resulting_status := 'rejected';
    v_resulting_exposure := 'internal';
    v_action := 'rejected';

    update editorial.sources
    set
      review_status = v_resulting_status,
      exposure_class = v_resulting_exposure,
      current_approved_version_id = null,
      reviewed_by = v_actor_id,
      reviewed_at = now(),
      updated_by = v_actor_id,
      updated_at = now()
    where id = p_source_id;
  end if;

  insert into editorial.source_review_events (
    source_id,
    source_version_id,
    actor_id,
    action,
    reason,
    prior_review_status,
    resulting_review_status,
    prior_exposure_class,
    resulting_exposure_class,
    prior_source_state,
    resulting_source_state,
    correlation_id
  )
  values (
    p_source_id,
    p_source_version_id,
    v_actor_id,
    v_action,
    nullif(btrim(p_reason), ''),
    v_source.review_status,
    v_resulting_status,
    v_source.exposure_class,
    v_resulting_exposure,
    v_source.source_state,
    v_source.source_state,
    p_correlation_id
  );

  return jsonb_build_object(
    'source_id',
      p_source_id,
    'source_version_id',
      p_source_version_id,
    'decision',
      p_decision,
    'review_status',
      v_resulting_status,
    'exposure_class',
      v_resulting_exposure,
    'working_revision',
      v_source.working_revision
  );
end;
$$;


ALTER FUNCTION "public"."review_source_version"("p_source_id" "uuid", "p_source_version_id" "uuid", "p_decision" "text", "p_reason" "text", "p_exposure_class" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."review_source_version"("p_source_id" "uuid", "p_source_version_id" "uuid", "p_decision" "text", "p_reason" "text", "p_exposure_class" "text", "p_correlation_id" "uuid") IS 'Applies a governed review decision to the exact submitted Source version.';



CREATE OR REPLACE FUNCTION "public"."revoke_user_role_admin"("target_user_id" "uuid", "target_role_key" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not public.current_user_is_administrator() then
    raise exception 'Only administrators can revoke roles.' using errcode = '42501';
  end if;

  update public.user_role_assignments
  set status = 'revoked', updated_at = now()
  where user_id = target_user_id and role_key = target_role_key;

  perform public.record_admin_audit('role_revoked', 'user_role_assignments', target_user_id::text || ':' || target_role_key, target_user_id, 'Role revoked from admin users console.', jsonb_build_object('role_key', target_role_key));
  return true;
end;
$$;


ALTER FUNCTION "public"."revoke_user_role_admin"("target_user_id" "uuid", "target_role_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."revoke_user_scope_admin"("scope_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  target_user uuid;
  payload jsonb;
begin
  if not public.current_user_is_administrator() then
    raise exception 'Only administrators can revoke user scopes.' using errcode = '42501';
  end if;

  select user_id, jsonb_build_object('role_key', role_key, 'scope_type', scope_type, 'scope_value', scope_value)
  into target_user, payload
  from public.user_access_scopes
  where id = scope_id;

  update public.user_access_scopes set status = 'revoked', updated_at = now() where id = scope_id;
  perform public.record_admin_audit('scope_revoked', 'user_access_scopes', scope_id::text, target_user, 'Scope revoked from admin users console.', payload);
  return true;
end;
$$;


ALTER FUNCTION "public"."revoke_user_scope_admin"("scope_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rls_auto_enable"() RETURNS "event_trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."rls_auto_enable"() OWNER TO "postgres";


