CREATE OR REPLACE FUNCTION "public"."run_artist_intake_matching"("p_intake_run_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_exact_matches int := 0;
  v_fuzzy_matches int := 0;
  v_no_matches int := 0;
  v_conflicts int := 0;
BEGIN
  -- Step 1: Exact match on normalized_name
  UPDATE provider_intake_artist_staging s
  SET 
    match_status = 'exact_match',
    matched_registry_artist_id = a.id,
    matched_registry_artist_name = a.display_name,
    match_confidence = 1.0,
    match_reason = 'Exact normalized name match',
    updated_at = now()
  FROM registry_artists a
  WHERE s.intake_run_id = p_intake_run_id
    AND s.match_status = 'pending'
    AND s.source_normalized_name = a.normalized_name
    AND a.status = 'active';
  
  GET DIAGNOSTICS v_exact_matches = ROW_COUNT;
  
  -- Step 2: Match via artist aliases (exact alias match)
  UPDATE provider_intake_artist_staging s
  SET 
    match_status = 'exact_match',
    matched_registry_artist_id = al.canonical_artist_id,
    matched_registry_artist_name = a.display_name,
    match_confidence = 0.95,
    match_reason = 'Exact alias match: ' || al.alias_display_name,
    updated_at = now()
  FROM registry_artist_aliases al
  JOIN registry_artists a ON al.canonical_artist_id = a.id
  WHERE s.intake_run_id = p_intake_run_id
    AND s.match_status = 'pending'
    AND s.source_normalized_name = lower(al.alias_display_name)
    AND a.status = 'active';
  
  -- Step 3: Fuzzy match - levenshtein distance <= 2 on normalized names
  -- Only for names with length >= 5 to avoid false positives
  UPDATE provider_intake_artist_staging s
  SET 
    match_status = 'fuzzy_match',
    matched_registry_artist_id = a.id,
    matched_registry_artist_name = a.display_name,
    match_confidence = 0.7,
    match_reason = 'Fuzzy name match (Levenshtein distance <= 2)',
    updated_at = now()
  FROM registry_artists a
  WHERE s.intake_run_id = p_intake_run_id
    AND s.match_status = 'pending'
    AND length(s.source_normalized_name) >= 5
    AND length(a.normalized_name) >= 5
    AND a.status = 'active'
    AND levenshtein(s.source_normalized_name, a.normalized_name) <= 2;
  
  GET DIAGNOSTICS v_fuzzy_matches = ROW_COUNT;
  
  -- Step 4: Flag conflicts where multiple staging records match the same artist
  -- This is rare but possible (e.g. "Doja Cat" vs "doja cat")
  UPDATE provider_intake_artist_staging s
  SET 
    match_status = 'conflict',
    match_reason = 'Multiple source records match this registry artist',
    updated_at = now()
  WHERE s.intake_run_id = p_intake_run_id
    AND s.matched_registry_artist_id IN (
      SELECT matched_registry_artist_id
      FROM provider_intake_artist_staging
      WHERE intake_run_id = p_intake_run_id
        AND match_status IN ('exact_match', 'fuzzy_match')
      GROUP BY matched_registry_artist_id
      HAVING COUNT(*) > 1
    );
  
  GET DIAGNOSTICS v_conflicts = ROW_COUNT;
  
  -- Step 5: Mark remaining as no_match (new artists)
  UPDATE provider_intake_artist_staging s
  SET 
    match_status = 'no_match',
    match_reason = 'No matching registry artist found',
    updated_at = now()
  WHERE s.intake_run_id = p_intake_run_id
    AND s.match_status = 'pending';
  
  GET DIAGNOSTICS v_no_matches = ROW_COUNT;
  
  RETURN jsonb_build_object(
    'exact_matches', v_exact_matches,
    'fuzzy_matches', v_fuzzy_matches,
    'no_matches', v_no_matches,
    'conflicts', v_conflicts
  );
END;
$$;


ALTER FUNCTION "public"."run_artist_intake_matching"("p_intake_run_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_article_versioned"("p_article_id" "uuid", "p_payload" "jsonb", "p_expected_draft_version" bigint, "p_version_kind" "text" DEFAULT 'manual_save'::"text", "p_taxonomy_term_ids" "uuid"[] DEFAULT '{}'::"uuid"[]) RETURNS TABLE("article_id" "uuid", "article_slug" "text", "draft_version" bigint, "version_id" "uuid", "version_number" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $_$
declare
  current_article public.wk_articles%rowtype;
  current_resource editorial.resources%rowtype;
  new_version_id uuid;
  new_version_number bigint;
  new_slug text;
  new_categories jsonb;
  new_tags jsonb;
  effective_wp_status text;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  if p_version_kind not in (
    'manual_save',
    'submitted'
  ) then
    raise exception
      'Unsupported Article version kind: %',
      p_version_kind;
  end if;

  if p_payload is null
     or jsonb_typeof(p_payload) <> 'object'
  then
    raise exception 'Article payload must be a JSON object';
  end if;

  if p_payload - array[
    'title',
    'slug',
    'excerpt',
    'content_html',
    'author',
    'published_at',
    'seo',
    'wp_status',
    'hero_image_id',
    'hero_image_url'
  ] <> '{}'::jsonb
  then
    raise exception
      'Article payload contains unsupported fields';
  end if;

  select article.*
  into current_article
  from public.wk_articles article
  where article.id = p_article_id
  for update;

  if not found then
    raise exception 'Article not found';
  end if;

  select resource.*
  into current_resource
  from editorial.article_resources binding
  join editorial.resources resource
    on resource.id = binding.resource_id
  where binding.article_id = p_article_id
  for update of resource;

  if not found then
    raise exception 'Article resource identity not found';
  end if;

  if not editorial.current_user_can_edit_article(
    current_resource.id
  ) then
    raise exception 'Permission denied';
  end if;

  if p_expected_draft_version is null then
    raise exception
      'Expected draft version is required';
  end if;

  if current_article.draft_version
     <> p_expected_draft_version
  then
    raise exception
      'STALE_ARTICLE_VERSION: expected %, current %',
      p_expected_draft_version,
      current_article.draft_version;
  end if;

  /*
   * Saving a working version must not perform a publication transition.
   * Dedicated lifecycle commands own publish, schedule, unpublish and archive.
   */
  effective_wp_status := current_article.wp_status;

  new_slug := case
    when p_payload ? 'slug'
      then nullif(
        btrim(p_payload ->> 'slug'),
        ''
      )
    else current_article.slug
  end;

  if new_slug is null then
    raise exception 'Article slug cannot be blank';
  end if;

  if new_slug !~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' then
    raise exception 'Article slug is invalid';
  end if;

  if new_slug <> current_article.slug
     and exists (
       select 1
       from public.wk_articles other_article
       where other_article.slug = new_slug
         and other_article.id <> p_article_id
     )
  then
    raise exception
      'Article slug already exists: %',
      new_slug;
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'name',
        term.name,
        'slug',
        term.slug
      )
      order by term.name
    ),
    '[]'::jsonb
  )
  into new_categories
  from public.registry_taxonomy_terms term
  where term.id = any(
    coalesce(
      p_taxonomy_term_ids,
      '{}'::uuid[]
    )
  )
    and term.taxonomy = 'category'
    and term.status = 'active';

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'name',
        term.name,
        'slug',
        term.slug
      )
      order by term.name
    ),
    '[]'::jsonb
  )
  into new_tags
  from public.registry_taxonomy_terms term
  where term.id = any(
    coalesce(
      p_taxonomy_term_ids,
      '{}'::uuid[]
    )
  )
    and term.taxonomy = 'post_tag'
    and term.status = 'active';

  if new_slug <> current_article.slug then
    insert into public.wk_slug_redirects (
      old_slug,
      new_slug,
      entity_type,
      created_by,
      old_path,
      new_path,
      redirect_status,
      updated_at
    )
    values (
      current_article.slug,
      new_slug,
      'article',
      auth.uid()::text,
      '/magazine/' || current_article.slug,
      '/magazine/' || new_slug,
      308,
      now()
    );
  end if;

  update public.wk_articles as article
  set
    title = case
      when p_payload ? 'title'
        then p_payload ->> 'title'
      else article.title
    end,
    slug = new_slug,
    excerpt = case
      when p_payload ? 'excerpt'
        then p_payload ->> 'excerpt'
      else article.excerpt
    end,
    content_html = case
      when p_payload ? 'content_html'
        then p_payload ->> 'content_html'
      else article.content_html
    end,
    author = case
      when p_payload ? 'author'
        then p_payload ->> 'author'
      else article.author
    end,
    published_at = case
      when p_payload ? 'published_at'
        then nullif(
          p_payload ->> 'published_at',
          ''
        )::timestamptz
      else article.published_at
    end,
    seo = case
      when p_payload ? 'seo'
        then coalesce(
          p_payload -> 'seo',
          '{}'::jsonb
        )
      else article.seo
    end,
    wp_status = effective_wp_status,
    hero_image_id = case
      when p_payload ? 'hero_image_id'
        then nullif(
          p_payload ->> 'hero_image_id',
          ''
        )::uuid
      else article.hero_image_id
    end,
    hero_image_url = case
      when p_payload ? 'hero_image_url'
        then p_payload ->> 'hero_image_url'
      else article.hero_image_url
    end,
    categories = new_categories,
    tags = new_tags,
    draft_version = article.draft_version + 1,
    modified_at = now(),
    updated_at = now()
  where article.id = p_article_id
  returning article.*
  into current_article;

  delete from editorial.article_taxonomy_terms
  where resource_id = current_resource.id;

  insert into editorial.article_taxonomy_terms (
    resource_id,
    term_id,
    taxonomy,
    created_by
  )
  select
    current_resource.id,
    term.id,
    term.taxonomy,
    auth.uid()
  from public.registry_taxonomy_terms term
  where term.id = any(
    coalesce(
      p_taxonomy_term_ids,
      '{}'::uuid[]
    )
  )
    and term.taxonomy in (
      'category',
      'post_tag'
    )
    and term.status = 'active'
  on conflict do nothing;

  new_version_number :=
    editorial.next_article_version_number(
      current_resource.id
    );

  insert into editorial.article_versions (
    resource_id,
    article_id,
    version_number,
    version_kind,
    source_draft_version,
    title,
    slug,
    excerpt,
    content_html,
    author_display,
    owner_id,
    hero_image_id,
    hero_image_url,
    seo,
    lifecycle_state,
    wp_status,
    published_at,
    category_snapshot,
    tag_snapshot,
    created_by,
    content_fingerprint
  )
  values (
    current_resource.id,
    current_article.id,
    new_version_number,
    p_version_kind,
    current_article.draft_version,
    current_article.title,
    current_article.slug,
    current_article.excerpt,
    current_article.content_html,
    current_article.author,
    current_resource.owner_id,
    current_article.hero_image_id,
    current_article.hero_image_url,
    current_article.seo,
    current_resource.lifecycle_state,
    current_article.wp_status,
    current_article.published_at,
    current_article.categories,
    current_article.tags,
    auth.uid(),
    editorial.article_snapshot_fingerprint(
      current_article.title,
      current_article.slug,
      current_article.excerpt,
      current_article.content_html,
      current_article.author,
      current_article.hero_image_id,
      current_article.hero_image_url,
      current_article.seo,
      current_article.wp_status,
      current_article.published_at,
      current_article.categories,
      current_article.tags
    )
  )
  returning id
  into new_version_id;

  update editorial.resources
  set
    current_working_version_id = new_version_id,
    current_submitted_version_id = case
      when p_version_kind = 'submitted'
        then new_version_id
      else current_submitted_version_id
    end,
    updated_at = now()
  where id = current_resource.id;

  delete from editorial.article_versions old_version
  where old_version.resource_id = current_resource.id
    and old_version.version_kind = 'manual_save'
    and old_version.id not in (
      select retained.id
      from editorial.article_versions retained
      where retained.resource_id =
        current_resource.id
        and retained.version_kind =
          'manual_save'
      order by retained.created_at desc
      limit 20
    );

  article_id := current_article.id;
  article_slug := current_article.slug;
  draft_version := current_article.draft_version;
  version_id := new_version_id;
  version_number := new_version_number;

  return next;
end;
$_$;


ALTER FUNCTION "public"."save_article_versioned"("p_article_id" "uuid", "p_payload" "jsonb", "p_expected_draft_version" bigint, "p_version_kind" "text", "p_taxonomy_term_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."save_article_versioned"("p_article_id" "uuid", "p_payload" "jsonb", "p_expected_draft_version" bigint, "p_version_kind" "text", "p_taxonomy_term_ids" "uuid"[]) IS 'Creates an immutable Article working or submitted version without changing publication status, visibility, or lifecycle state. Publication transitions remain owned by dedicated lifecycle commands.';



CREATE OR REPLACE FUNCTION "public"."save_playlist_item_note"("p_playlist_id" "uuid", "p_playlist_item_id" "uuid", "p_expected_authority_revision" bigint, "p_note" "text", "p_idempotency_key" "text", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("command_receipt_id" "uuid", "receipt_status" "text", "playlist_id" "uuid", "resource_id" "uuid", "playlist_item_id" "uuid", "authority_revision" bigint, "result_payload" "jsonb", "idempotent_replay" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'editorial', 'platform_private'
    AS $$
declare
  v_playlist public.wk_playlists%rowtype;
  v_resource_id uuid;
  v_note text := nullif(btrim(p_note), '');
  v_begin record;
  v_read record;
  v_request jsonb;
  v_result jsonb;
  v_correlation_id uuid := coalesce(p_correlation_id, gen_random_uuid());
begin
  if p_playlist_id is null
     or p_playlist_item_id is null
     or p_expected_authority_revision is null
     or p_expected_authority_revision < 1
  then
    raise exception
      using
        errcode = '22023',
        message = 'Playlist, item, and expected authority revision are required.';
  end if;

  if length(coalesce(v_note, '')) > 12000 then
    raise exception
      using errcode = '22023', message = 'Playlist-item note must not exceed 12000 characters.';
  end if;

  select playlist.*
  into v_playlist
  from public.wk_playlists playlist
  where playlist.id = p_playlist_id
  for update of playlist;

  select binding.resource_id
  into v_resource_id
  from editorial.playlist_resources binding
  where binding.playlist_id = p_playlist_id;

  if not found then
    raise exception using errcode = 'P0002', message = 'Playlist does not exist.';
  end if;

  if not editorial.current_user_can_edit_playlist(v_resource_id) then
    raise exception using errcode = '42501', message = 'Playlist edit permission is required.';
  end if;

  v_request := jsonb_build_object(
    'playlist_id', p_playlist_id,
    'playlist_item_id', p_playlist_item_id,
    'expected_authority_revision', p_expected_authority_revision,
    'note', v_note,
    'correlation_id', v_correlation_id
  );

  select *
  into v_begin
  from platform_private.begin_authenticated_resource_command(
    'playlist.item.note.save',
    v_resource_id,
    p_idempotency_key,
    v_request
  );

  if not v_begin.idempotent_replay then
    if v_playlist.authority_revision <> p_expected_authority_revision then
      perform platform_private.reject_resource_command(
        v_begin.command_receipt_id,
        'playlist_revision_changed',
        'The Playlist changed before this note could be saved.',
        jsonb_build_object(
          'playlist_id', p_playlist_id,
          'authority_revision', v_playlist.authority_revision
        )
      );
    elsif not exists (
      select 1
      from public.wk_playlist_items item
      where item.id = p_playlist_item_id
        and item.playlist_id = p_playlist_id
        and item.lifecycle_state = 'active'
    ) then
      perform platform_private.reject_resource_command(
        v_begin.command_receipt_id,
        'playlist_item_not_active',
        'The Playlist item is missing or no longer active.',
        jsonb_build_object(
          'playlist_id', p_playlist_id,
          'authority_revision', v_playlist.authority_revision
        )
      );
    else
      update public.wk_playlist_items item
      set notes = v_note
      where item.id = p_playlist_item_id;

      update public.wk_playlists playlist
      set authority_revision = playlist.authority_revision + 1
      where playlist.id = p_playlist_id
      returning playlist.authority_revision
      into v_playlist.authority_revision;

      v_result := jsonb_build_object(
        'playlist_id', p_playlist_id,
        'playlist_item_id', p_playlist_item_id,
        'has_note', v_note is not null,
        'authority_revision', v_playlist.authority_revision,
        'correlation_id', v_correlation_id
      );

      perform platform_private.complete_resource_command(
        v_begin.command_receipt_id,
        v_result
      );
    end if;
  end if;

  select *
  into v_read
  from platform_private.read_authenticated_resource_command_result(
    v_begin.command_receipt_id,
    v_begin.idempotent_replay
  );

  command_receipt_id := v_read.command_receipt_id;
  receipt_status := v_read.receipt_status;
  playlist_id := p_playlist_id;
  resource_id := v_read.resource_id;
  playlist_item_id := p_playlist_item_id;
  authority_revision := nullif(v_read.result_payload ->> 'authority_revision', '')::bigint;
  result_payload := v_read.result_payload;
  idempotent_replay := v_read.idempotent_replay;
  return next;
end;
$$;


ALTER FUNCTION "public"."save_playlist_item_note"("p_playlist_id" "uuid", "p_playlist_item_id" "uuid", "p_expected_authority_revision" bigint, "p_note" "text", "p_idempotency_key" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_playlist_pending_registry_note"("p_playlist_id" "uuid", "p_suggestion_id" "uuid", "p_expected_authority_revision" bigint, "p_note" "text", "p_idempotency_key" "text", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'auth', 'public', 'editorial', 'platform_private'
    AS $$
declare
  v_playlist public.wk_playlists%rowtype;
  v_resource_id uuid;
  v_suggestion public.registry_provider_track_suggestions%rowtype;
  v_begin record;
  v_read record;
  v_request jsonb;
  v_result jsonb;
  v_note text := nullif(btrim(p_note), '');
  v_changed boolean := false;
  v_correlation_id uuid := coalesce(
    p_correlation_id,
    gen_random_uuid()
  );
begin
  if p_playlist_id is null
     or p_suggestion_id is null
     or p_expected_authority_revision is null
     or p_expected_authority_revision < 1
  then
    raise exception
      'Playlist, Registry intake suggestion, and expected revision are required.';
  end if;

  if length(coalesce(v_note, '')) > 10000 then
    raise exception
      'Playlist track notes cannot exceed 10,000 characters.';
  end if;

  select playlist.*
  into v_playlist
  from public.wk_playlists playlist
  where playlist.id = p_playlist_id
  for update of playlist;

  select binding.resource_id
  into v_resource_id
  from editorial.playlist_resources binding
  where binding.playlist_id = p_playlist_id;

  if not found then
    raise exception
      using errcode = 'P0002', message = 'Playlist does not exist.';
  end if;

  if not editorial.current_user_can_edit_playlist(v_resource_id) then
    raise exception
      using errcode = '42501', message = 'Playlist edit permission is required.';
  end if;

  v_request := jsonb_build_object(
    'playlist_id', p_playlist_id,
    'suggestion_id', p_suggestion_id,
    'expected_authority_revision', p_expected_authority_revision,
    'note', v_note,
    'correlation_id', v_correlation_id
  );

  select *
  into v_begin
  from platform_private.begin_authenticated_resource_command(
    'playlist.item.note.save',
    v_resource_id,
    p_idempotency_key,
    v_request
  );

  if v_begin.idempotent_replay then
    select *
    into v_read
    from platform_private.read_authenticated_resource_command_result(
      v_begin.command_receipt_id,
      true
    );
    return v_read.result_payload;
  end if;

  if v_playlist.authority_revision <> p_expected_authority_revision then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'playlist_revision_changed',
      'The Playlist changed before this pending track note could be saved.',
      jsonb_build_object(
        'playlist_id', p_playlist_id,
        'authority_revision', v_playlist.authority_revision
      )
    );
  else
    select suggestion.*
    into v_suggestion
    from public.registry_provider_track_suggestions suggestion
    where suggestion.id = p_suggestion_id
      and suggestion.source_playlist_id = p_playlist_id
      and suggestion.status = 'needs_review'
      and suggestion.source_playlist_item_id is null
      and suggestion.canonical_track_id is null
    for update;

    if not found then
      perform platform_private.reject_resource_command(
        v_begin.command_receipt_id,
        'playlist_pending_registry_intake_missing',
        'That pending Registry track is no longer editable in this Playlist.',
        jsonb_build_object(
          'playlist_id', p_playlist_id,
          'authority_revision', v_playlist.authority_revision
        )
      );
    else
      v_changed :=
        v_suggestion.playlist_note is distinct from v_note;

      if v_changed then
        update public.registry_provider_track_suggestions suggestion
        set playlist_note = v_note
        where suggestion.id = p_suggestion_id;

        update public.wk_playlists playlist
        set authority_revision = playlist.authority_revision + 1
        where playlist.id = p_playlist_id
        returning playlist.authority_revision
        into v_playlist.authority_revision;
      end if;

      v_result := jsonb_build_object(
        'playlist_id', p_playlist_id,
        'suggestion_id', p_suggestion_id,
        'authority_revision', v_playlist.authority_revision,
        'changed', v_changed,
        'notes', v_note,
        'correlation_id', v_correlation_id
      );

      perform platform_private.complete_resource_command(
        v_begin.command_receipt_id,
        v_result
      );
    end if;
  end if;

  select *
  into v_read
  from platform_private.read_authenticated_resource_command_result(
    v_begin.command_receipt_id,
    false
  );

  return v_read.result_payload;
end;
$$;


ALTER FUNCTION "public"."save_playlist_pending_registry_note"("p_playlist_id" "uuid", "p_suggestion_id" "uuid", "p_expected_authority_revision" bigint, "p_note" "text", "p_idempotency_key" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_source_version"("p_source_id" "uuid", "p_expected_working_revision" bigint, "p_metadata" "jsonb", "p_registry_links" "jsonb" DEFAULT '[]'::"jsonb", "p_reason" "text" DEFAULT NULL::"text", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial', 'auth'
    AS $$
declare
  v_actor_id uuid;
  v_source editorial.sources%rowtype;
  v_metadata jsonb;
  v_registry_links jsonb;
  v_fingerprint text;
  v_current_fingerprint text;
  v_next_version_number bigint;
  v_source_version_id uuid;
  v_resulting_review_status text;
  v_has_prior_review boolean;
begin
  v_actor_id :=
    editorial.assert_source_command_actor('manage_sources');

  select *
  into v_source
  from editorial.sources source
  where source.id = p_source_id
  for update;

  if not found then
    raise exception
      'Source was not found';
  end if;

  if v_source.working_revision <>
       p_expected_working_revision then
    raise exception
      'Source working revision conflict. Expected %, found %',
      p_expected_working_revision,
      v_source.working_revision;
  end if;

  if v_source.source_state = 'withdrawn' then
    raise exception
      'Restore the withdrawn Source before editing it';
  end if;

  if v_source.source_state = 'archived' then
    raise exception
      'Archived Sources cannot be edited';
  end if;

  v_metadata :=
    editorial.normalize_source_metadata(p_metadata);

  v_registry_links :=
    editorial.normalize_source_registry_links(p_registry_links);

  if not exists (
    select 1
    from editorial.source_types source_type
    where source_type.source_type =
            v_metadata ->> 'source_type'
      and source_type.enabled
  ) then
    raise exception
      'Choose an enabled Source type';
  end if;

  if v_metadata ? 'media_asset_id'
     and not exists (
       select 1
       from public.registry_media_assets media_asset
       where media_asset.id =
         (v_metadata ->> 'media_asset_id')::uuid
     ) then
    raise exception
      'Source Media asset was not found';
  end if;

  v_fingerprint :=
    editorial.source_content_fingerprint(
      v_metadata,
      v_registry_links
    );

  select source_version.content_fingerprint
  into v_current_fingerprint
  from editorial.source_versions source_version
  where source_version.id =
    v_source.current_working_version_id;

  if v_current_fingerprint = v_fingerprint then
    return jsonb_build_object(
      'source_id',
        v_source.id,
      'source_version_id',
        v_source.current_working_version_id,
      'working_revision',
        v_source.working_revision,
      'created',
        false
    );
  end if;

  select coalesce(max(source_version.version_number), 0) + 1
  into v_next_version_number
  from editorial.source_versions source_version
  where source_version.source_id = v_source.id;

  insert into editorial.source_versions (
    source_id,
    version_number,
    source_type,
    title,
    creator_display,
    publisher_display,
    source_url,
    media_asset_id,
    archive_identifier,
    publication_date,
    capture_date,
    retrieval_date,
    language_code,
    country_code,
    place_text,
    rights_status,
    consent_status,
    sensitivity,
    reliability_note,
    credit_line,
    internal_notes,
    created_by,
    content_fingerprint
  )
  values (
    v_source.id,
    v_next_version_number,
    v_metadata ->> 'source_type',
    v_metadata ->> 'title',
    v_metadata ->> 'creator_display',
    v_metadata ->> 'publisher_display',
    v_metadata ->> 'source_url',
    (v_metadata ->> 'media_asset_id')::uuid,
    v_metadata ->> 'archive_identifier',
    (v_metadata ->> 'publication_date')::date,
    (v_metadata ->> 'capture_date')::date,
    (v_metadata ->> 'retrieval_date')::date,
    v_metadata ->> 'language_code',
    v_metadata ->> 'country_code',
    v_metadata ->> 'place_text',
    coalesce(
      v_metadata ->> 'rights_status',
      'unknown'
    ),
    coalesce(
      v_metadata ->> 'consent_status',
      'unknown'
    ),
    coalesce(
      v_metadata ->> 'sensitivity',
      'none'
    ),
    v_metadata ->> 'reliability_note',
    v_metadata ->> 'credit_line',
    v_metadata ->> 'internal_notes',
    v_actor_id,
    v_fingerprint
  )
  returning id
  into v_source_version_id;

  perform editorial.insert_source_registry_links(
    v_source.id,
    v_source_version_id,
    v_registry_links,
    v_actor_id
  );

  select exists (
    select 1
    from editorial.source_review_events event
    where event.source_id = v_source.id
      and event.action in (
        'review_started',
        'changes_requested',
        'approved',
        'rejected'
      )
  )
  into v_has_prior_review;

  v_resulting_review_status :=
    case
      when v_has_prior_review then 'changes_requested'
      else 'draft'
    end;

  update editorial.sources
  set
    source_type = v_metadata ->> 'source_type',
    title = v_metadata ->> 'title',
    creator_display = v_metadata ->> 'creator_display',
    publisher_display = v_metadata ->> 'publisher_display',
    source_url = v_metadata ->> 'source_url',
    media_asset_id =
      (v_metadata ->> 'media_asset_id')::uuid,
    archive_identifier =
      v_metadata ->> 'archive_identifier',
    publication_date =
      (v_metadata ->> 'publication_date')::date,
    capture_date =
      (v_metadata ->> 'capture_date')::date,
    retrieval_date =
      (v_metadata ->> 'retrieval_date')::date,
    language_code =
      v_metadata ->> 'language_code',
    country_code =
      v_metadata ->> 'country_code',
    place_text =
      v_metadata ->> 'place_text',
    rights_status =
      coalesce(
        v_metadata ->> 'rights_status',
        'unknown'
      ),
    consent_status =
      coalesce(
        v_metadata ->> 'consent_status',
        'unknown'
      ),
    sensitivity =
      coalesce(
        v_metadata ->> 'sensitivity',
        'none'
      ),
    reliability_note =
      v_metadata ->> 'reliability_note',
    credit_line =
      v_metadata ->> 'credit_line',
    internal_notes =
      v_metadata ->> 'internal_notes',
    review_status = v_resulting_review_status,
    exposure_class = 'internal',
    current_working_version_id = v_source_version_id,
    current_submitted_version_id = null,
    current_approved_version_id = null,
    reviewed_by = null,
    reviewed_at = null,
    working_revision = v_source.working_revision + 1,
    updated_by = v_actor_id,
    updated_at = now()
  where id = v_source.id;

  insert into editorial.source_review_events (
    source_id,
    source_version_id,
    actor_id,
    action,
    reason,
    prior_review_status,
    resulting_review_status,
    prior_exposure_class,
    resulting_exposure_class,
    prior_source_state,
    resulting_source_state,
    correlation_id
  )
  values (
    v_source.id,
    v_source_version_id,
    v_actor_id,
    'version_saved',
    nullif(btrim(p_reason), ''),
    v_source.review_status,
    v_resulting_review_status,
    v_source.exposure_class,
    'internal',
    v_source.source_state,
    v_source.source_state,
    p_correlation_id
  );

  return jsonb_build_object(
    'source_id',
      v_source.id,
    'source_version_id',
      v_source_version_id,
    'working_revision',
      v_source.working_revision + 1,
    'created',
      true
  );
end;
$$;


ALTER FUNCTION "public"."save_source_version"("p_source_id" "uuid", "p_expected_working_revision" bigint, "p_metadata" "jsonb", "p_registry_links" "jsonb", "p_reason" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."save_source_version"("p_source_id" "uuid", "p_expected_working_revision" bigint, "p_metadata" "jsonb", "p_registry_links" "jsonb", "p_reason" "text", "p_correlation_id" "uuid") IS 'Creates a new immutable Source version only when Source content materially changes.';



CREATE OR REPLACE FUNCTION "public"."schedule_article_publication"("p_article_id" "uuid", "p_version_id" "uuid" DEFAULT NULL::"uuid", "p_publish_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_note" "text" DEFAULT NULL::"text") RETURNS TABLE("article_id" "uuid", "article_slug" "text", "draft_version" bigint, "version_id" "uuid", "version_number" bigint, "lifecycle_status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_article public.wk_articles%rowtype;
  v_resource editorial.resources%rowtype;
  v_publish_at timestamptz;
  v_source_version_id uuid;
  v_version_id uuid;
  v_version_number bigint;
  v_prior_status text;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  if not editorial.current_user_can_publish_article() then
    raise exception 'Permission denied';
  end if;

  v_publish_at := coalesce(p_publish_at, now());

  if v_publish_at <= now() then
    raise exception 'Scheduled publish time must be in the future';
  end if;

  select article.*
  into v_article
  from public.wk_articles article
  where article.id = p_article_id
  for update;

  if not found then
    raise exception 'Article not found';
  end if;

  select resource.*
  into v_resource
  from editorial.article_resources binding
  join editorial.resources resource
    on resource.id = binding.resource_id
  where binding.article_id = p_article_id
  for update of resource;

  if not found then
    raise exception 'Article resource identity not found';
  end if;

  v_source_version_id := coalesce(p_version_id, v_resource.current_approved_version_id);

  if v_source_version_id is null then
    raise exception 'Article must be approved before scheduling';
  end if;

  if v_resource.current_approved_version_id is null
    or v_source_version_id <> v_resource.current_approved_version_id
  then
    raise exception 'Only the approved article version can be scheduled';
  end if;

  perform 1
  from editorial.article_versions version
  where version.id = v_source_version_id
    and version.article_id = p_article_id
    and version.kind = 'approved';

  if not found then
    raise exception 'Only an approved article version can be scheduled';
  end if;

  v_prior_status := v_article.wp_status;

  select copied.version_id, copied.version_number
  into v_version_id, v_version_number
  from editorial.copy_article_lifecycle_version(
    v_source_version_id,
    'scheduled',
    'scheduled',
    'future',
    v_publish_at
  ) copied;

  insert into editorial.article_scheduled_publications (
    resource_id,
    article_id,
    version_id,
    run_after,
    note
  )
  values (
    v_resource.id,
    p_article_id,
    v_version_id,
    v_publish_at,
    p_note
  );

  update public.wk_articles as article
  set
    wp_status = 'future',
    published_at = v_publish_at,
    updated_at = now()
  where article.id = p_article_id
  returning article.*
  into v_article;

  update editorial.resources
  set
    current_approved_version_id = v_source_version_id,
    lifecycle_state = 'active',
    visibility = 'private',
    updated_at = now()
  where id = v_resource.id;

  insert into editorial.article_lifecycle_events (
    resource_id,
    article_id,
    version_id,
    action,
    prior_status,
    resulting_status,
    note,
    metadata
  )
  values (
    v_resource.id,
    p_article_id,
    v_version_id,
    'scheduled',
    v_prior_status,
    'future',
    p_note,
    jsonb_build_object(
      'publishAt',
      v_publish_at
    )
  );

  article_id := p_article_id;
  article_slug := v_article.slug;
  draft_version := v_article.draft_version;
  version_id := v_version_id;
  version_number := v_version_number;
  lifecycle_status := 'scheduled';
  return next;
end;
$$;


ALTER FUNCTION "public"."schedule_article_publication"("p_article_id" "uuid", "p_version_id" "uuid", "p_publish_at" timestamp with time zone, "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."schedule_playlist_publication"("p_playlist_id" "uuid", "p_expected_authority_revision" bigint, "p_approved_version_id" "uuid", "p_publish_at" timestamp with time zone, "p_idempotency_key" "text", "p_note" "text" DEFAULT NULL::"text", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("command_receipt_id" "uuid", "receipt_status" "text", "playlist_id" "uuid", "resource_id" "uuid", "authority_revision" bigint, "version_id" "uuid", "version_number" bigint, "lifecycle_status" "text", "result_payload" "jsonb", "idempotent_replay" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'editorial', 'platform_private'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_playlist public.wk_playlists%rowtype;
  v_binding editorial.playlist_resources%rowtype;
  v_approved editorial.playlist_versions%rowtype;
  v_scheduled record;
  v_schedule_id uuid;
  v_source_version_id uuid;
  v_begin record;
  v_read record;
  v_result jsonb;
  v_correlation_id uuid :=
    coalesce(
      p_correlation_id,
      gen_random_uuid()
    );
begin
  if v_actor is null then
    raise exception 'Not authenticated';
  end if;

  if p_publish_at is null
     or p_publish_at <= now()
  then
    raise exception
      'Scheduled publish time must be in the future';
  end if;

  select playlist.*
  into v_playlist
  from public.wk_playlists playlist
  where playlist.id = p_playlist_id
  for update;

  if not found then
    raise exception 'Playlist does not exist';
  end if;

  select binding.*
  into v_binding
  from editorial.playlist_resources binding
  where binding.playlist_id = p_playlist_id
  for update;

  if not found then
    raise exception
      'Playlist Resource binding does not exist';
  end if;

  if not editorial.current_user_can_publish_playlist(
    v_binding.resource_id
  ) then
    raise exception
      'Playlist publication permission is required';
  end if;

  v_source_version_id :=
    coalesce(
      p_approved_version_id,
      v_binding.current_approved_version_id
    );

  select *
  into v_begin
  from platform_private.begin_authenticated_resource_command(
    'playlist.schedule',
    v_binding.resource_id,
    p_idempotency_key,
    jsonb_build_object(
      'playlist_id',
        p_playlist_id,
      'expected_authority_revision',
        p_expected_authority_revision,
      'approved_version_id',
        v_source_version_id,
      'publish_at',
        p_publish_at,
      'note',
        nullif(btrim(p_note), ''),
      'correlation_id',
        v_correlation_id
    )
  );

  if v_begin.idempotent_replay then
    select *
    into v_read
    from platform_private.read_authenticated_resource_command_result(
      v_begin.command_receipt_id,
      true
    );

    command_receipt_id := v_read.command_receipt_id;
    receipt_status := v_read.receipt_status;
    playlist_id := p_playlist_id;
    resource_id := v_read.resource_id;
    authority_revision :=
      nullif(
        v_read.result_payload ->> 'authority_revision',
        ''
      )::bigint;
    version_id :=
      nullif(
        v_read.result_payload ->> 'version_id',
        ''
      )::uuid;
    version_number :=
      nullif(
        v_read.result_payload ->> 'version_number',
        ''
      )::bigint;
    lifecycle_status :=
      v_read.result_payload ->> 'lifecycle_status';
    result_payload := v_read.result_payload;
    idempotent_replay := true;
    return next;
    return;
  end if;

  if p_expected_authority_revision is null
     or p_expected_authority_revision < 1
     or v_playlist.authority_revision <>
          p_expected_authority_revision
  then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'playlist_revision_changed',
      'The Playlist changed before publication could be scheduled.',
      jsonb_build_object(
        'playlist_id',
          p_playlist_id,
        'authority_revision',
          v_playlist.authority_revision,
        'lifecycle_status',
          v_playlist.status
      )
    );

  elsif v_playlist.status <> 'approved'
        or v_source_version_id is null
        or v_binding.current_approved_version_id
             is distinct from
             v_source_version_id
  then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'playlist_not_schedulable',
      'Only the exact current approved Playlist version can be scheduled.',
      jsonb_build_object(
        'playlist_id',
          p_playlist_id,
        'lifecycle_status',
          v_playlist.status,
        'current_approved_version_id',
          v_binding.current_approved_version_id
      )
    );

  elsif exists (
    select 1
    from editorial.playlist_scheduled_publications scheduled
    where scheduled.playlist_id = p_playlist_id
      and scheduled.status = 'scheduled'
  )
  then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'playlist_schedule_exists',
      'This Playlist already has an active publication schedule.',
      jsonb_build_object(
        'playlist_id',
          p_playlist_id
      )
    );

  else
    select approved.*
    into v_approved
    from editorial.playlist_versions approved
    where approved.id = v_source_version_id
      and approved.resource_id =
            v_binding.resource_id
      and approved.playlist_id =
            p_playlist_id
      and approved.version_kind = 'approved';

    if not found then
      perform platform_private.reject_resource_command(
        v_begin.command_receipt_id,
        'approved_version_invalid',
        'The approved Playlist version is no longer schedulable.',
        jsonb_build_object(
          'playlist_id',
            p_playlist_id,
          'approved_version_id',
            v_source_version_id
        )
      );
    end if;

    if exists (
      select 1
      from platform_private.command_receipts receipt
      where receipt.id =
              v_begin.command_receipt_id
        and receipt.status = 'accepted'
    ) then
      select *
      into v_scheduled
      from editorial.copy_playlist_lifecycle_version(
        v_approved.id,
        'scheduled',
        v_actor
      );

      insert into editorial.playlist_scheduled_publications (
        resource_id,
        playlist_id,
        version_id,
        command_receipt_id,
        run_after,
        note,
        created_by
      )
      values (
        v_binding.resource_id,
        p_playlist_id,
        v_scheduled.version_id,
        v_begin.command_receipt_id,
        p_publish_at,
        nullif(btrim(p_note), ''),
        v_actor
      )
      returning id
      into v_schedule_id;

      update public.wk_playlists playlist
      set
        status = 'scheduled',
        authority_revision =
          playlist.authority_revision + 1
      where playlist.id = p_playlist_id
      returning playlist.*
      into v_playlist;

      perform editorial.append_playlist_lifecycle_event(
        v_binding.resource_id,
        p_playlist_id,
        v_scheduled.version_id,
        'scheduled',
        'approved',
        'scheduled',
        p_note,
        v_actor,
        v_begin.command_receipt_id,
        jsonb_build_object(
          'scheduled_publication_id',
            v_schedule_id,
          'publish_at',
            p_publish_at,
          'correlation_id',
            v_correlation_id
        )
      );

      v_result := jsonb_build_object(
        'playlist_id',
          p_playlist_id,
        'resource_id',
          v_binding.resource_id,
        'authority_revision',
          v_playlist.authority_revision,
        'approved_version_id',
          v_approved.id,
        'version_id',
          v_scheduled.version_id,
        'version_number',
          v_scheduled.version_number,
        'scheduled_publication_id',
          v_schedule_id,
        'publish_at',
          p_publish_at,
        'lifecycle_status',
          'scheduled',
        'correlation_id',
          v_correlation_id
      );

      perform platform_private.complete_resource_command(
        v_begin.command_receipt_id,
        v_result
      );
    end if;
  end if;

  select *
  into v_read
  from platform_private.read_authenticated_resource_command_result(
    v_begin.command_receipt_id,
    false
  );

  command_receipt_id := v_read.command_receipt_id;
  receipt_status := v_read.receipt_status;
  playlist_id := p_playlist_id;
  resource_id := v_read.resource_id;
  authority_revision :=
    nullif(
      v_read.result_payload ->> 'authority_revision',
      ''
    )::bigint;
  version_id :=
    nullif(
      v_read.result_payload ->> 'version_id',
      ''
    )::uuid;
  version_number :=
    nullif(
      v_read.result_payload ->> 'version_number',
      ''
    )::bigint;
  lifecycle_status :=
    v_read.result_payload ->> 'lifecycle_status';
  result_payload := v_read.result_payload;
  idempotent_replay := false;
  return next;
end;
$$;


ALTER FUNCTION "public"."schedule_playlist_publication"("p_playlist_id" "uuid", "p_expected_authority_revision" bigint, "p_approved_version_id" "uuid", "p_publish_at" timestamp with time zone, "p_idempotency_key" "text", "p_note" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."seed_taxonomy_terms_from_articles"() RETURNS TABLE("taxonomy" "text", "term_name" "text", "term_slug" "text", "article_count" bigint)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  WITH all_terms AS (
    -- Categories
    SELECT 
      'category' AS taxonomy,
      elem->>'name' AS term_name,
      elem->>'slug' AS term_slug,
      a.id AS article_id
    FROM public.wk_articles a,
         LATERAL jsonb_array_elements(a.categories) AS elem
    WHERE a.wp_status = 'publish'
    UNION ALL
    -- Tags
    SELECT 
      'post_tag' AS taxonomy,
      elem->>'name' AS term_name,
      elem->>'slug' AS term_slug,
      a.id AS article_id
    FROM public.wk_articles a,
         LATERAL jsonb_array_elements(a.tags) AS elem
    WHERE a.wp_status = 'publish'
  ),
  aggregated AS (
    SELECT 
      taxonomy,
      term_name,
      MAX(term_slug) AS term_slug,
      COUNT(DISTINCT article_id) AS article_count
    FROM all_terms
    WHERE term_name IS NOT NULL AND term_name != ''
    GROUP BY taxonomy, term_name
  )
  SELECT a.taxonomy, a.term_name, a.term_slug, a.article_count
  FROM aggregated a
  ORDER BY a.taxonomy, a.article_count DESC;
$$;


ALTER FUNCTION "public"."seed_taxonomy_terms_from_articles"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_credit_governance"("p_credit_id" "uuid", "p_credit_state" "text", "p_public_safe" boolean, "p_expected_governance_revision" bigint, "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial', 'auth'
    AS $$
declare
  v_actor_id uuid;
  v_credit editorial.credits%rowtype;
  v_governance editorial.credit_governance%rowtype;
  v_external_contributor editorial.external_contributors%rowtype;
  v_public_safe boolean;
begin
  v_actor_id :=
    editorial.assert_credit_command_actor();

  if p_credit_state not in (
    'active',
    'withdrawn',
    'archived'
  ) then
    raise exception
      'Choose a supported Credit state';
  end if;

  if p_expected_governance_revision is null
     or p_expected_governance_revision < 1 then
    raise exception
      'Expected governance revision must be one or greater';
  end if;

  if p_credit_state in (
       'withdrawn',
       'archived'
     )
     and nullif(btrim(p_reason), '') is null then
    raise exception
      'A reason is required for Credit withdrawal or archival';
  end if;

  v_public_safe := coalesce(p_public_safe, false);

  if v_public_safe
     and p_credit_state <> 'active' then
    raise exception
      'Only active Credits can be public-safe';
  end if;

  select *
  into v_credit
  from editorial.credits credit
  where credit.id = p_credit_id;

  if not found then
    raise exception
      'Credit was not found';
  end if;

  select *
  into v_governance
  from editorial.credit_governance governance
  where governance.credit_id = p_credit_id
  for update;

  if not found then
    raise exception
      'Credit governance was not found';
  end if;

  if v_governance.governance_revision <>
       p_expected_governance_revision then
    raise exception
      'Credit governance revision conflict. Expected %, found %',
      p_expected_governance_revision,
      v_governance.governance_revision;
  end if;

  if v_public_safe
     and v_credit.external_contributor_id is not null then
    select *
    into v_external_contributor
    from editorial.external_contributors contributor
    where contributor.id =
      v_credit.external_contributor_id;

    if not found
       or v_external_contributor.contributor_state <> 'active'
       or not v_external_contributor.public_safe
       or v_external_contributor.consent_status
            not in (
              'granted',
              'not_required'
            ) then
      raise exception
        'Public-safe external-contributor Credits require active public-safe consent';
    end if;
  end if;

  update editorial.credit_governance
  set
    public_safe = v_public_safe,
    credit_state = p_credit_state,
    governance_revision =
      v_governance.governance_revision + 1,
    reason =
      case
        when p_credit_state = 'active'
          then nullif(btrim(p_reason), '')
        else btrim(p_reason)
      end,
    updated_by = v_actor_id,
    updated_at = now()
  where credit_id = p_credit_id;

  return jsonb_build_object(
    'credit_id',
      p_credit_id,
    'credit_state',
      p_credit_state,
    'public_safe',
      v_public_safe,
    'governance_revision',
      v_governance.governance_revision + 1
  );
end;
$$;


ALTER FUNCTION "public"."set_credit_governance"("p_credit_id" "uuid", "p_credit_state" "text", "p_public_safe" boolean, "p_expected_governance_revision" bigint, "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_credit_governance"("p_credit_id" "uuid", "p_credit_state" "text", "p_public_safe" boolean, "p_expected_governance_revision" bigint, "p_reason" "text") IS 'Updates Credit lifecycle and public-safety governance with revision control.';



CREATE OR REPLACE FUNCTION "public"."set_playlist_cover"("p_playlist_id" "uuid", "p_expected_authority_revision" bigint, "p_asset_id" "uuid", "p_idempotency_key" "text", "p_placement_data" "jsonb" DEFAULT '{}'::"jsonb", "p_alt_text_snapshot" "text" DEFAULT NULL::"text", "p_caption_snapshot" "text" DEFAULT NULL::"text", "p_credit_snapshot" "text" DEFAULT NULL::"text", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("command_receipt_id" "uuid", "receipt_status" "text", "playlist_id" "uuid", "resource_id" "uuid", "authority_revision" bigint, "cover_usage_link_id" "uuid", "cover_asset_id" "uuid", "cover_asset_revision_id" "uuid", "cover_url" "text", "result_payload" "jsonb", "idempotent_replay" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'auth', 'public', 'editorial', 'media', 'platform_private'
    AS $$
declare
  v_actor record;
  v_playlist public.wk_playlists%rowtype;
  v_binding editorial.playlist_resources%rowtype;
  v_begin record;
  v_read record;
  v_current_usage media.usage_links%rowtype;
  v_current_count bigint;
  v_asset media.assets%rowtype;
  v_governance media.asset_governance_versions%rowtype;
  v_file media.file_objects%rowtype;
  v_compatibility public.registry_media_assets%rowtype;
  v_is_prepared_variant boolean := false;
  v_correlation_id uuid :=
    coalesce(p_correlation_id, gen_random_uuid());
  v_token uuid := gen_random_uuid();
  v_usage_id uuid;
  v_cover_url text;
  v_request jsonb;
  v_result jsonb;
  v_same boolean := false;
begin
  if p_playlist_id is null then
    raise exception
      using errcode = '22023', message = 'playlist_id is required.';
  end if;

  if p_expected_authority_revision is null
     or p_expected_authority_revision < 1
  then
    raise exception
      using
        errcode = '22023',
        message = 'expected Playlist revision must be positive.';
  end if;

  if p_placement_data is null
     or jsonb_typeof(p_placement_data) <> 'object'
  then
    raise exception
      using
        errcode = '22023',
        message = 'Playlist cover placement data must be a JSON object.';
  end if;

  if length(coalesce(p_alt_text_snapshot, '')) > 2000
     or length(coalesce(p_caption_snapshot, '')) > 4000
     or length(coalesce(p_credit_snapshot, '')) > 2000
  then
    raise exception
      using
        errcode = '22023',
        message = 'Playlist cover presentation text is too long.';
  end if;

  select *
  into v_playlist
  from public.wk_playlists playlist
  where playlist.id = p_playlist_id
  for update;

  if not found then
    raise exception
      using errcode = 'P0002', message = 'Playlist was not found.';
  end if;

  select *
  into v_binding
  from editorial.playlist_resources binding
  where binding.playlist_id = p_playlist_id;

  if not found then
    raise exception
      'Playlist Resource binding is missing';
  end if;

  if not coalesce(
    editorial.current_user_can_edit_playlist(
      v_binding.resource_id
    ),
    false
  ) then
    raise exception
      using
        errcode = '42501',
        message = 'You do not have permission to edit this Playlist.';
  end if;

  select *
  into v_actor
  from platform_private.command_actor_context();

  if p_asset_id is not null then
    perform media.validate_usage_target(
      v_actor.actor_user_id,
      'editorial',
      'playlist',
      p_playlist_id,
      null,
      null,
      true,
      true
    );

    select asset.*
    into v_asset
    from media.assets asset
    where asset.id = p_asset_id;

    if not found then
      raise exception
        using
          errcode = 'P0002',
          message = 'Selected Media asset was not found.';
    end if;

    if v_asset.lifecycle_state <> 'active'
       or v_asset.current_revision_id is null
    then
      raise exception
        'Selected Media asset is not ready for Playlist cover use';
    end if;

    select file_object.*
    into v_file
    from media.asset_revisions revision
    join media.file_objects file_object
      on file_object.id = revision.original_file_object_id
    where revision.id = v_asset.current_revision_id
      and revision.asset_id = p_asset_id
      and file_object.verification_state = 'verified'
      and lower(coalesce(file_object.mime_type, '')) like 'image/%';

    if not found then
      raise exception
        'Playlist cover requires a verified image revision';
    end if;

    select compatibility.*
    into v_compatibility
    from public.registry_media_assets compatibility
    where compatibility.id = p_asset_id;

    if not found then
      raise exception
        'Playlist cover requires canonical Media compatibility identity';
    end if;

    v_is_prepared_variant :=
      v_compatibility.asset_purpose = 'playlist_cover'
      and v_compatibility.source_entity = 'playlist_cover_variant'
      and v_compatibility.source_record_id is not null;

    if not v_is_prepared_variant then
      if v_asset.current_governance_version_id is null then
        raise exception
          'Selected Media asset is not ready for Playlist cover use';
      end if;

      select governance.*
      into v_governance
      from media.asset_governance_versions governance
      where governance.id = v_asset.current_governance_version_id
        and governance.asset_id = p_asset_id;

      if not found then
        raise exception
          'Selected Media asset current governance is invalid';
      end if;

      if v_governance.public_safety_state not in (
           'approved_public',
           'approved_redacted'
         )
         or v_governance.rights_status not in (
           'owned',
           'licensed',
           'public_domain',
           'fair_use'
         )
         or v_governance.consent_status not in (
           'granted',
           'not_required'
         )
         or v_governance.source_protection_class not in (
           'public',
           'public_redacted'
         )
         or v_governance.retention_state not in (
           'retain',
           'review_required'
         )
         or v_governance.embargo_state = 'active'
         or (
           v_governance.embargo_state = 'scheduled'
           and v_governance.embargo_until is not null
           and v_governance.embargo_until > now()
         )
      then
        raise exception
          'Current Media governance does not permit Playlist cover use';
      end if;
    end if;

    v_cover_url := v_file.delivery_url;
  end if;

  v_request := jsonb_build_object(
    'playlist_id', p_playlist_id,
    'expected_authority_revision',
      p_expected_authority_revision,
    'asset_id', p_asset_id,
    'placement_data', p_placement_data,
    'alt_text_snapshot',
      nullif(btrim(p_alt_text_snapshot), ''),
    'caption_snapshot',
      nullif(btrim(p_caption_snapshot), ''),
    'credit_snapshot',
      nullif(btrim(p_credit_snapshot), ''),
    'correlation_id', v_correlation_id
  );

  select *
  into v_begin
  from platform_private.begin_authenticated_resource_command(
    'playlist.cover.set',
    v_binding.resource_id,
    p_idempotency_key,
    v_request
  );

  if v_begin.idempotent_replay then
    select *
    into v_read
    from platform_private.read_authenticated_resource_command_result(
      v_begin.command_receipt_id,
      true
    );

    command_receipt_id := v_read.command_receipt_id;
    receipt_status := v_read.receipt_status;
    playlist_id := p_playlist_id;
    resource_id := v_binding.resource_id;
    authority_revision :=
      nullif(
        v_read.result_payload ->> 'authority_revision',
        ''
      )::bigint;
    cover_usage_link_id :=
      nullif(
        v_read.result_payload ->> 'cover_usage_link_id',
        ''
      )::uuid;
    cover_asset_id :=
      nullif(
        v_read.result_payload ->> 'cover_asset_id',
        ''
      )::uuid;
    cover_asset_revision_id :=
      nullif(
        v_read.result_payload
          ->> 'cover_asset_revision_id',
        ''
      )::uuid;
    cover_url :=
      v_read.result_payload ->> 'cover_url';
    result_payload := v_read.result_payload;
    idempotent_replay := true;
    return next;
    return;
  end if;

  if v_playlist.authority_revision <>
       p_expected_authority_revision
  then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'playlist_revision_changed',
      'The Playlist changed before its cover could be updated.',
      jsonb_build_object(
        'playlist_id', p_playlist_id,
        'authority_revision',
          v_playlist.authority_revision,
        'lifecycle_status', v_playlist.status
      )
    );

    select *
    into v_read
    from platform_private.read_authenticated_resource_command_result(
      v_begin.command_receipt_id,
      false
    );

    command_receipt_id := v_read.command_receipt_id;
    receipt_status := v_read.receipt_status;
    playlist_id := p_playlist_id;
    resource_id := v_binding.resource_id;
    authority_revision := v_playlist.authority_revision;
    cover_usage_link_id := null;
    cover_asset_id := null;
    cover_asset_revision_id := null;
    cover_url := v_playlist.cover_image_url;
    result_payload := v_read.result_payload;
    idempotent_replay := false;
    return next;
    return;
  end if;

  select count(*)
  into v_current_count
  from media.usage_links usage
  where usage.target_authority = 'editorial'
    and usage.target_kind = 'playlist'
    and usage.target_id = p_playlist_id
    and usage.target_version_id is null
    and usage.usage_role = 'playlist_cover'
    and usage.usage_state = 'active';

  if v_current_count > 1 then
    raise exception
      'Playlist has more than one active canonical cover';
  end if;

  if v_current_count = 1 then
    select usage.*
    into v_current_usage
    from media.usage_links usage
    where usage.target_authority = 'editorial'
      and usage.target_kind = 'playlist'
      and usage.target_id = p_playlist_id
      and usage.target_version_id is null
      and usage.usage_role = 'playlist_cover'
      and usage.usage_state = 'active'
    for update;

    v_same :=
      p_asset_id is not null
      and v_current_usage.asset_id = p_asset_id
      and v_current_usage.asset_revision_id =
            v_asset.current_revision_id
      and v_current_usage.resolution_mode =
            'exact_revision'
      and v_current_usage.placement_data =
            p_placement_data
      and coalesce(
            v_current_usage.alt_text_snapshot,
            ''
          ) =
          coalesce(
            nullif(btrim(p_alt_text_snapshot), ''),
            ''
          )
      and coalesce(
            v_current_usage.caption_snapshot,
            ''
          ) =
          coalesce(
            nullif(btrim(p_caption_snapshot), ''),
            ''
          )
      and coalesce(
            v_current_usage.credit_snapshot,
            ''
          ) =
          coalesce(
            nullif(btrim(p_credit_snapshot), ''),
            ''
          );

    v_usage_id := v_current_usage.id;
  else
    v_same := p_asset_id is null;
  end if;

  if not v_same then
    insert into
      platform_private.playlist_cover_mutation_authorizations (
        token,
        actor_id,
        playlist_id,
        command_receipt_id
      )
    values (
      v_token,
      v_actor.actor_user_id,
      p_playlist_id,
      v_begin.command_receipt_id
    );

    perform set_config(
      'wakilisha.playlist_cover_mutation_token',
      v_token::text,
      true
    );

    if v_current_count = 1 then
      update media.usage_links
      set
        usage_state = 'archived',
        usage_revision = usage_revision + 1,
        state_reason = 'Replaced by Playlist cover command',
        state_changed_by = v_actor.actor_user_id,
        state_changed_at = now(),
        updated_at = now()
      where id = v_current_usage.id;

      insert into media.events (
        asset_id,
        asset_revision_id,
        usage_link_id,
        event_type,
        actor_id,
        reason,
        prior_state,
        resulting_state,
        correlation_id
      )
      values (
        v_current_usage.asset_id,
        v_current_usage.asset_revision_id,
        v_current_usage.id,
        'usage_archived',
        v_actor.actor_user_id,
        'Playlist cover replaced or cleared',
        jsonb_build_object(
          'usage_state', 'active',
          'usage_revision',
            v_current_usage.usage_revision
        ),
        jsonb_build_object(
          'usage_state', 'archived',
          'usage_revision',
            v_current_usage.usage_revision + 1
        ),
        v_correlation_id
      );
    end if;

    if p_asset_id is not null then
      v_usage_id := gen_random_uuid();

      insert into media.usage_links (
        id,
        asset_id,
        asset_revision_id,
        resolution_mode,
        target_authority,
        target_kind,
        target_id,
        target_version_kind,
        target_version_id,
        usage_role,
        placement_data,
        display_order,
        alt_text_snapshot,
        caption_snapshot,
        credit_snapshot,
        usage_state,
        usage_revision,
        created_by
      )
      values (
        v_usage_id,
        p_asset_id,
        v_asset.current_revision_id,
        'exact_revision',
        'editorial',
        'playlist',
        p_playlist_id,
        null,
        null,
        'playlist_cover',
        p_placement_data,
        0,
        nullif(btrim(p_alt_text_snapshot), ''),
        nullif(btrim(p_caption_snapshot), ''),
        nullif(btrim(p_credit_snapshot), ''),
        'active',
        1,
        v_actor.actor_user_id
      );

      insert into media.events (
        asset_id,
        asset_revision_id,
        usage_link_id,
        event_type,
        actor_id,
        reason,
        resulting_state,
        correlation_id
      )
      values (
        p_asset_id,
        v_asset.current_revision_id,
        v_usage_id,
        'usage_attached',
        v_actor.actor_user_id,
        'Governed Playlist cover attached',
        jsonb_build_object(
          'usage_state', 'active',
          'usage_revision', 1,
          'target_authority', 'editorial',
          'target_kind', 'playlist',
          'target_id', p_playlist_id,
          'usage_role', 'playlist_cover'
        ),
        v_correlation_id
      );
    else
      v_usage_id := null;
      v_cover_url := null;
    end if;

    delete from
      platform_private.playlist_cover_mutation_authorizations
    where token = v_token;

    perform set_config(
      'wakilisha.playlist_cover_mutation_token',
      '',
      true
    );

    update public.wk_playlists playlist
    set
      authority_revision =
        playlist.authority_revision + 1,
      cover_image_url = v_cover_url
    where playlist.id = p_playlist_id
    returning playlist.*
    into v_playlist;
  end if;

  v_result := jsonb_build_object(
    'playlist_id', p_playlist_id,
    'resource_id', v_binding.resource_id,
    'authority_revision',
      v_playlist.authority_revision,
    'lifecycle_status', v_playlist.status,
    'cover_usage_link_id', v_usage_id,
    'cover_asset_id', p_asset_id,
    'cover_asset_revision_id',
      case
        when p_asset_id is null
          then null
        else v_asset.current_revision_id
      end,
    'cover_url', v_cover_url,
    'cover_changed', not v_same,
    'correlation_id', v_correlation_id
  );

  perform platform_private.complete_resource_command(
    v_begin.command_receipt_id,
    v_result
  );

  select *
  into v_read
  from platform_private.read_authenticated_resource_command_result(
    v_begin.command_receipt_id,
    false
  );

  command_receipt_id := v_read.command_receipt_id;
  receipt_status := v_read.receipt_status;
  playlist_id := p_playlist_id;
  resource_id := v_binding.resource_id;
  authority_revision := v_playlist.authority_revision;
  cover_usage_link_id := v_usage_id;
  cover_asset_id := p_asset_id;
  cover_asset_revision_id :=
    case
      when p_asset_id is null
        then null
      else v_asset.current_revision_id
    end;
  cover_url := v_cover_url;
  result_payload := v_read.result_payload;
  idempotent_replay := false;
  return next;
end;
$$;


ALTER FUNCTION "public"."set_playlist_cover"("p_playlist_id" "uuid", "p_expected_authority_revision" bigint, "p_asset_id" "uuid", "p_idempotency_key" "text", "p_placement_data" "jsonb", "p_alt_text_snapshot" "text", "p_caption_snapshot" "text", "p_credit_snapshot" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_playlist_cover"("p_playlist_id" "uuid", "p_expected_authority_revision" bigint, "p_asset_id" "uuid", "p_idempotency_key" "text", "p_placement_data" "jsonb", "p_alt_text_snapshot" "text", "p_caption_snapshot" "text", "p_credit_snapshot" "text", "p_correlation_id" "uuid") IS 'Governed Playlist cover command. M213 accepts prepared playlist_cover variants during draft authoring while retaining strict governance for direct non-derived cover assets.';



CREATE OR REPLACE FUNCTION "public"."set_playlist_curator"("p_playlist_id" "uuid", "p_expected_authority_revision" bigint, "p_registry_author_id" "uuid", "p_user_id" "uuid", "p_idempotency_key" "text", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("command_receipt_id" "uuid", "receipt_status" "text", "playlist_id" "uuid", "resource_id" "uuid", "authority_revision" bigint, "curator_credit_id" "uuid", "curator_label" "text", "lifecycle_status" "text", "result_payload" "jsonb", "idempotent_replay" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'editorial', 'platform_private'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_playlist public.wk_playlists%rowtype;
  v_resource_id uuid;
  v_curator record;
  v_credit_id uuid;
  v_display_name text;
  v_changed boolean := false;
  v_begin record;
  v_read record;
  v_result jsonb;
  v_correlation_id uuid :=
    coalesce(
      p_correlation_id,
      gen_random_uuid()
    );
begin
  if v_actor is null then
    raise exception 'Not authenticated';
  end if;

  if num_nonnulls(
       p_registry_author_id,
       p_user_id
     ) > 1
  then
    raise exception
      'Choose one Curator identity';
  end if;

  select playlist.*
  into v_playlist
  from public.wk_playlists playlist
  where playlist.id = p_playlist_id
  for update;

  if not found then
    raise exception 'Playlist does not exist';
  end if;

  select binding.resource_id
  into v_resource_id
  from editorial.playlist_resources binding
  where binding.playlist_id = p_playlist_id;

  if v_resource_id is null then
    raise exception
      'Playlist Resource binding does not exist';
  end if;

  if not editorial.current_user_can_edit_playlist(
    v_resource_id
  ) then
    raise exception
      'Playlist edit permission is required';
  end if;

  select *
  into v_begin
  from platform_private.begin_authenticated_resource_command(
    'playlist.curator.set',
    v_resource_id,
    p_idempotency_key,
    jsonb_build_object(
      'playlist_id',
        p_playlist_id,
      'expected_authority_revision',
        p_expected_authority_revision,
      'registry_author_id',
        p_registry_author_id,
      'user_id',
        p_user_id,
      'correlation_id',
        v_correlation_id
    )
  );

  if v_begin.idempotent_replay then
    select *
    into v_read
    from platform_private.read_authenticated_resource_command_result(
      v_begin.command_receipt_id,
      true
    );

    command_receipt_id :=
      v_read.command_receipt_id;
    receipt_status :=
      v_read.receipt_status;
    playlist_id := p_playlist_id;
    resource_id := v_read.resource_id;
    authority_revision :=
      nullif(
        v_read.result_payload
          ->> 'authority_revision',
        ''
      )::bigint;
    curator_credit_id :=
      nullif(
        v_read.result_payload
          ->> 'curator_credit_id',
        ''
      )::uuid;
    curator_label :=
      nullif(
        v_read.result_payload
          ->> 'curator_label',
        ''
      );
    lifecycle_status :=
      v_read.result_payload
        ->> 'lifecycle_status';
    result_payload :=
      v_read.result_payload;
    idempotent_replay := true;
    return next;
    return;
  end if;

  if p_expected_authority_revision is null
     or p_expected_authority_revision < 1
     or v_playlist.authority_revision
          <> p_expected_authority_revision
  then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'playlist_revision_changed',
      'The Playlist changed before the Curator could be updated.',
      jsonb_build_object(
        'playlist_id',
          p_playlist_id,
        'authority_revision',
          v_playlist.authority_revision,
        'lifecycle_status',
          v_playlist.status
      )
    );
  else
    if num_nonnulls(
         p_registry_author_id,
         p_user_id
       ) = 1
    then
      select *
      into v_curator
      from editorial.resolve_playlist_curator_credit(
        p_registry_author_id,
        p_user_id,
        v_actor
      );

      v_credit_id := v_curator.credit_id;
      v_display_name := v_curator.display_name;
    else
      v_credit_id := null;
      v_display_name := null;
    end if;

    v_changed :=
      v_playlist.curator_credit_id
        is distinct from v_credit_id
      or v_playlist.curator_label
        is distinct from v_display_name;

    if v_changed then
      update public.wk_playlists playlist
      set
        curator_credit_id = v_credit_id,
        curator_label = v_display_name,
        authority_revision =
          playlist.authority_revision + 1
      where playlist.id = p_playlist_id
      returning playlist.*
      into v_playlist;
    end if;

    v_result := jsonb_build_object(
      'playlist_id',
        p_playlist_id,
      'resource_id',
        v_resource_id,
      'authority_revision',
        v_playlist.authority_revision,
      'curator_credit_id',
        v_playlist.curator_credit_id,
      'curator_label',
        v_playlist.curator_label,
      'lifecycle_status',
        v_playlist.status,
      'changed',
        v_changed,
      'correlation_id',
        v_correlation_id
    );

    perform platform_private.complete_resource_command(
      v_begin.command_receipt_id,
      v_result
    );
  end if;

  select *
  into v_read
  from platform_private.read_authenticated_resource_command_result(
    v_begin.command_receipt_id,
    false
  );

  command_receipt_id :=
    v_read.command_receipt_id;
  receipt_status :=
    v_read.receipt_status;
  playlist_id := p_playlist_id;
  resource_id := v_read.resource_id;
  authority_revision :=
    nullif(
      v_read.result_payload
        ->> 'authority_revision',
      ''
    )::bigint;
  curator_credit_id :=
    nullif(
      v_read.result_payload
        ->> 'curator_credit_id',
      ''
    )::uuid;
  curator_label :=
    nullif(
      v_read.result_payload
        ->> 'curator_label',
      ''
    );
  lifecycle_status :=
    v_read.result_payload
      ->> 'lifecycle_status';
  result_payload :=
    v_read.result_payload;
  idempotent_replay := false;
  return next;
end;
$$;


ALTER FUNCTION "public"."set_playlist_curator"("p_playlist_id" "uuid", "p_expected_authority_revision" bigint, "p_registry_author_id" "uuid", "p_user_id" "uuid", "p_idempotency_key" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_publishing_item_primary_channel"("p_item_id" "uuid", "p_expected_record_version" bigint, "p_channel_key" "text", "p_note" "text" DEFAULT NULL::"text") RETURNS TABLE("item_id" "uuid", "record_version" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_item editorial.publishing_items%rowtype;
  v_updated editorial.publishing_items%rowtype;
  v_previous_primary_channel_key text;
begin
  if auth.uid() is null
     or not editorial.current_user_can_manage_publishing()
  then
    raise exception
      using
        errcode = '42501',
        message = 'Permission denied';
  end if;

  select item.*
  into v_item
  from editorial.publishing_items item
  where item.id = p_item_id
  for update;

  if not found then
    raise exception 'Publishing item not found';
  end if;

  if v_item.record_version
     <> p_expected_record_version
  then
    raise exception
      'STALE_PUBLISHING_ITEM_VERSION: expected %, current %',
      p_expected_record_version,
      v_item.record_version;
  end if;

  if not exists (
    select 1
    from editorial.publishing_item_channels item_channel
    where item_channel.item_id = p_item_id
      and item_channel.channel_key =
        p_channel_key
  ) then
    raise exception
      'Publishing channel attachment not found';
  end if;

  select item_channel.channel_key
  into v_previous_primary_channel_key
  from editorial.publishing_item_channels item_channel
  where item_channel.item_id = p_item_id
    and item_channel.is_primary = true
  limit 1;

  if v_previous_primary_channel_key =
     p_channel_key
  then
    raise exception
      'Publishing channel is already primary';
  end if;

  update editorial.publishing_item_channels
    as item_channel
  set is_primary = false
  where item_channel.item_id = p_item_id
    and item_channel.is_primary = true;

  update editorial.publishing_item_channels
    as item_channel
  set is_primary = true
  where item_channel.item_id = p_item_id
    and item_channel.channel_key =
      p_channel_key;

  if not found then
    raise exception
      'Publishing channel attachment not found';
  end if;

  update editorial.publishing_items item
  set
    record_version =
      item.record_version + 1,
    updated_by = auth.uid(),
    updated_at = now()
  where item.id = p_item_id
  returning item.*
  into v_updated;

  insert into editorial.publishing_item_events (
    item_id,
    action,
    prior_record_version,
    resulting_record_version,
    prior_values,
    resulting_values,
    note,
    metadata,
    actor_id
  )
  values (
    p_item_id,
    'channel_primary_changed',
    v_item.record_version,
    v_updated.record_version,
    editorial.publishing_item_snapshot(
      v_item
    ),
    editorial.publishing_item_snapshot(
      v_updated
    ),
    nullif(btrim(p_note), ''),
    jsonb_strip_nulls(
      jsonb_build_object(
        'channelKey',
        p_channel_key,
        'previousPrimaryChannelKey',
        v_previous_primary_channel_key
      )
    ),
    auth.uid()
  );

  item_id := v_updated.id;
  record_version :=
    v_updated.record_version;

  return next;
end;
$$;


ALTER FUNCTION "public"."set_publishing_item_primary_channel"("p_item_id" "uuid", "p_expected_record_version" bigint, "p_channel_key" "text", "p_note" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_publishing_item_primary_channel"("p_item_id" "uuid", "p_expected_record_version" bigint, "p_channel_key" "text", "p_note" "text") IS 'Marks one attached Publishing channel as primary through optimistic concurrency and append-only history.';



