CREATE OR REPLACE FUNCTION "public"."signal_os_label_for_score"("p_score" integer) RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case
    when p_score >= 85 then 'Breaking'
    when p_score >= 70 then 'Moving'
    when p_score >= 50 then 'Warming'
    when p_score >= 30 then 'Quiet heat'
    else 'Quiet'
  end;
$$;


ALTER FUNCTION "public"."signal_os_label_for_score"("p_score" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."signal_os_path_from_url"("p_page_url" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case
    when coalesce(
      nullif(
        split_part(
          regexp_replace(coalesce(p_page_url, ''), '^https?://[^/]+', ''),
          '?',
          1
        ),
        ''
      ),
      '/'
    ) like '/artist/%'
      then regexp_replace(
        coalesce(
          nullif(
            split_part(
              regexp_replace(coalesce(p_page_url, ''), '^https?://[^/]+', ''),
              '?',
              1
            ),
            ''
          ),
          '/'
        ),
        '^/artist/',
        '/artists/'
      )
    else coalesce(
      nullif(
        split_part(
          regexp_replace(coalesce(p_page_url, ''), '^https?://[^/]+', ''),
          '?',
          1
        ),
        ''
      ),
      '/'
    )
  end;
$$;


ALTER FUNCTION "public"."signal_os_path_from_url"("p_page_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."signal_os_slug_from_path"("p_page_url" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select nullif(
    regexp_replace(
      split_part(
        regexp_replace(coalesce(p_page_url, ''), '^https?://[^/]+', ''),
        '?',
        1
      ),
      '^.*/',
      ''
    ),
    ''
  );
$$;


ALTER FUNCTION "public"."signal_os_slug_from_path"("p_page_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."snapshot_playlist_working_version"("p_playlist_id" "uuid", "p_expected_authority_revision" bigint, "p_idempotency_key" "text", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("command_receipt_id" "uuid", "receipt_status" "text", "playlist_id" "uuid", "resource_id" "uuid", "authority_revision" bigint, "version_id" "uuid", "version_number" bigint, "lifecycle_status" "text", "result_payload" "jsonb", "idempotent_replay" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'editorial', 'platform_private'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_playlist public.wk_playlists%rowtype;
  v_binding editorial.playlist_resources%rowtype;
  v_current editorial.playlist_versions%rowtype;
  v_snapshot record;
  v_fingerprint text;
  v_begin record;
  v_read record;
  v_result jsonb;
  v_reused boolean := false;
  v_correlation_id uuid :=
    coalesce(
      p_correlation_id,
      gen_random_uuid()
    );
begin
  if v_actor is null then
    raise exception 'Not authenticated';
  end if;

  select playlist.*
  into v_playlist
  from public.wk_playlists playlist
  where playlist.id = p_playlist_id
  for update;

  if not found then
    raise exception 'Playlist does not exist';
  end if;

  select binding.*
  into v_binding
  from editorial.playlist_resources binding
  where binding.playlist_id = p_playlist_id
  for update;

  if v_binding.resource_id is null then
    raise exception
      'Playlist Resource binding does not exist';
  end if;

  if not editorial.current_user_can_edit_playlist(
    v_binding.resource_id
  ) then
    raise exception
      'Playlist edit permission is required';
  end if;

  v_fingerprint :=
    editorial.playlist_current_content_fingerprint(
      p_playlist_id
    );

  select *
  into v_begin
  from platform_private.begin_authenticated_resource_command(
    'playlist.version.snapshot_working',
    v_binding.resource_id,
    p_idempotency_key,
    jsonb_build_object(
      'playlist_id',
        p_playlist_id,
      'expected_authority_revision',
        p_expected_authority_revision,
      'content_fingerprint',
        v_fingerprint,
      'correlation_id',
        v_correlation_id
    )
  );

  if v_begin.idempotent_replay then
    select *
    into v_read
    from platform_private.read_authenticated_resource_command_result(
      v_begin.command_receipt_id,
      true
    );

    command_receipt_id :=
      v_read.command_receipt_id;
    receipt_status :=
      v_read.receipt_status;
    playlist_id := p_playlist_id;
    resource_id := v_read.resource_id;
    authority_revision :=
      nullif(
        v_read.result_payload
          ->> 'authority_revision',
        ''
      )::bigint;
    version_id :=
      nullif(
        v_read.result_payload
          ->> 'version_id',
        ''
      )::uuid;
    version_number :=
      nullif(
        v_read.result_payload
          ->> 'version_number',
        ''
      )::bigint;
    lifecycle_status :=
      v_read.result_payload
        ->> 'lifecycle_status';
    result_payload :=
      v_read.result_payload;
    idempotent_replay := true;
    return next;
    return;
  end if;

  if p_expected_authority_revision is null
     or p_expected_authority_revision < 1
     or v_playlist.authority_revision
          <> p_expected_authority_revision
  then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'playlist_revision_changed',
      'The Playlist changed before the working snapshot could be created.',
      jsonb_build_object(
        'playlist_id',
          p_playlist_id,
        'authority_revision',
          v_playlist.authority_revision
      )
    );
  else
    if v_binding.current_working_version_id
         is not null
    then
      select version.*
      into v_current
      from editorial.playlist_versions version
      where version.id =
        v_binding.current_working_version_id;

      if found
         and v_current.version_kind =
               'working'
         and v_current.content_fingerprint =
               v_fingerprint
      then
        select
          v_current.id as version_id,
          v_current.version_number as version_number,
          v_current.content_fingerprint as content_fingerprint,
          v_current.item_count as item_count
        into v_snapshot;

        v_reused := true;
      end if;
    end if;

    if not v_reused then
      select *
      into v_snapshot
      from editorial.insert_playlist_current_snapshot(
        p_playlist_id,
        v_playlist.authority_revision,
        'working',
        v_playlist.status,
        v_actor
      );

      update editorial.playlist_resources binding_update
      set current_working_version_id =
            v_snapshot.version_id
      where binding_update.playlist_id = p_playlist_id;
    end if;

    v_result := jsonb_build_object(
      'playlist_id',
        p_playlist_id,
      'resource_id',
        v_binding.resource_id,
      'authority_revision',
        v_playlist.authority_revision,
      'version_id',
        v_snapshot.version_id,
      'version_number',
        v_snapshot.version_number,
      'content_fingerprint',
        v_snapshot.content_fingerprint,
      'item_count',
        v_snapshot.item_count,
      'lifecycle_status',
        v_playlist.status,
      'reused_existing_snapshot',
        v_reused,
      'correlation_id',
        v_correlation_id
    );

    perform platform_private.complete_resource_command(
      v_begin.command_receipt_id,
      v_result
    );
  end if;

  select *
  into v_read
  from platform_private.read_authenticated_resource_command_result(
    v_begin.command_receipt_id,
    false
  );

  command_receipt_id :=
    v_read.command_receipt_id;
  receipt_status :=
    v_read.receipt_status;
  playlist_id := p_playlist_id;
  resource_id := v_read.resource_id;
  authority_revision :=
    nullif(
      v_read.result_payload
        ->> 'authority_revision',
      ''
    )::bigint;
  version_id :=
    nullif(
      v_read.result_payload
        ->> 'version_id',
      ''
    )::uuid;
  version_number :=
    nullif(
      v_read.result_payload
        ->> 'version_number',
      ''
    )::bigint;
  lifecycle_status :=
    v_read.result_payload
      ->> 'lifecycle_status';
  result_payload :=
    v_read.result_payload;
  idempotent_replay := false;
  return next;
end;
$$;


ALTER FUNCTION "public"."snapshot_playlist_working_version"("p_playlist_id" "uuid", "p_expected_authority_revision" bigint, "p_idempotency_key" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."split_multi_release_tracks"() RETURNS TABLE("result" "jsonb")
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  rec RECORD;
  keeper_id uuid;
  extra RECORD;
  new_id uuid;
  new_slug text;
  artist_row RECORD;
  total_new integer := 0;
BEGIN
  FOR rec IN
    SELECT t.id as track_id, t.title, t.slug, t.release_id as current_release_id,
           t.normalized_title, t.isrc, t.duration_ms, t.disc_number, t.artwork_url, t.metadata
    FROM registry_tracks t
    WHERE t.id IN (
      SELECT rt.track_id FROM registry_release_tracks rt WHERE rt.status = 'active'
      GROUP BY rt.track_id HAVING COUNT(DISTINCT rt.release_id) > 1
    )
  LOOP
    SELECT rt.release_id INTO keeper_id
    FROM registry_release_tracks rt
    WHERE rt.track_id = rec.track_id AND rt.status = 'active' AND rt.release_id = rec.current_release_id
    LIMIT 1;
    
    IF keeper_id IS NULL THEN
      SELECT rt.release_id INTO keeper_id
      FROM registry_release_tracks rt
      JOIN registry_releases r ON r.id = rt.release_id
      WHERE rt.track_id = rec.track_id AND rt.status = 'active'
      ORDER BY r.title
      LIMIT 1;
    END IF;

    FOR extra IN
      SELECT rt.release_id, rt.track_number, r.slug as release_slug
      FROM registry_release_tracks rt
      JOIN registry_releases r ON r.id = rt.release_id
      WHERE rt.track_id = rec.track_id AND rt.status = 'active' AND rt.release_id != keeper_id
    LOOP
      new_id := gen_random_uuid();
      new_slug := substring(rec.slug || '-' || extra.release_slug, 1, 160);
      
      INSERT INTO registry_tracks (id, slug, title, normalized_title, isrc, release_id, duration_ms, track_number, disc_number, artwork_url, status, metadata)
      VALUES (new_id, new_slug, rec.title, rec.normalized_title, NULL, extra.release_id, rec.duration_ms, extra.track_number, COALESCE(rec.disc_number, 1), rec.artwork_url, 'active',
        jsonb_build_object('source', 'multi_release_split', 'split_from', rec.track_id, 'split_at', now()::text, 'original_isrc', rec.isrc));
      
      UPDATE registry_release_tracks 
      SET track_id = new_id, metadata = jsonb_build_object('source', 'multi_release_split', 'original_track_id', rec.track_id)
      WHERE release_id = extra.release_id AND track_id = rec.track_id AND status = 'active';
      
      FOR artist_row IN
        SELECT * FROM registry_track_artists WHERE track_id = rec.track_id AND status = 'active'
      LOOP
        INSERT INTO registry_track_artists (track_id, artist_slug, artist_name_text, artist_id, role, is_primary, is_featured, credit_order, source, confidence, status, metadata)
        VALUES (new_id, artist_row.artist_slug, artist_row.artist_name_text, artist_row.artist_id, artist_row.role, artist_row.is_primary, artist_row.is_featured, artist_row.credit_order,
          'multi_release_split', artist_row.confidence, 'active',
          jsonb_build_object('split_from_track_id', rec.track_id, 'split_at', now()::text));
      END LOOP;
      
      total_new := total_new + 1;
    END LOOP;
    
    result := jsonb_build_object('track', rec.title, 'track_id', rec.track_id, 'done', true);
    RETURN NEXT;
  END LOOP;
  
  result := jsonb_build_object('summary', 'Complete', 'new_tracks_created', total_new);
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."split_multi_release_tracks"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_article_for_review"("p_article_id" "uuid", "p_expected_draft_version" bigint, "p_note" "text" DEFAULT NULL::"text") RETURNS TABLE("article_id" "uuid", "article_slug" "text", "draft_version" bigint, "version_id" "uuid", "version_number" bigint, "lifecycle_status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_article public.wk_articles%rowtype;
  v_resource editorial.resources%rowtype;
  v_prior_status text;
  v_version_id uuid;
  v_version_number bigint;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  select article.*
  into v_article
  from public.wk_articles article
  where article.id = p_article_id
  for update;

  if not found then
    raise exception 'Article not found';
  end if;

  select resource.*
  into v_resource
  from editorial.article_resources binding
  join editorial.resources resource
    on resource.id = binding.resource_id
  where binding.article_id = p_article_id
  for update of resource;

  if not found then
    raise exception 'Article resource identity not found';
  end if;

  if not editorial.current_user_can_edit_article(v_resource.id) then
    raise exception 'Permission denied';
  end if;

  if v_article.draft_version <> p_expected_draft_version then
    raise exception
      'STALE_ARTICLE_VERSION: expected %, current %',
      p_expected_draft_version,
      v_article.draft_version;
  end if;

  v_prior_status := v_article.wp_status;

  update public.wk_articles as article
  set
    wp_status = 'pending',
    draft_version = article.draft_version + 1,
    updated_at = now(),
    modified_at = now()
  where article.id = p_article_id
  returning article.*
  into v_article;

  select created.version_id, created.version_number
  into v_version_id, v_version_number
  from editorial.insert_article_lifecycle_version_from_article(
    v_resource,
    v_article,
    'submitted',
    'submitted'
  ) created;

  update editorial.resources
  set
    current_submitted_version_id = v_version_id,
    lifecycle_state = 'active',
    visibility = 'private',
    updated_at = now()
  where id = v_resource.id;

  insert into editorial.article_lifecycle_events (
    resource_id,
    article_id,
    version_id,
    action,
    prior_status,
    resulting_status,
    note
  )
  values (
    v_resource.id,
    p_article_id,
    v_version_id,
    'submitted',
    v_prior_status,
    'pending',
    p_note
  );

  article_id := p_article_id;
  article_slug := v_article.slug;
  draft_version := v_article.draft_version;
  version_id := v_version_id;
  version_number := v_version_number;
  lifecycle_status := 'submitted';
  return next;
end;
$$;


ALTER FUNCTION "public"."submit_article_for_review"("p_article_id" "uuid", "p_expected_draft_version" bigint, "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_correction_for_decision"("p_case_resource_id" "uuid", "p_expected_case_revision" bigint, "p_reason" "text", "p_idempotency_key" "text", "p_correlation_id" "uuid") RETURNS TABLE("command_receipt_id" "uuid", "receipt_status" "text", "case_resource_id" "uuid", "case_revision" bigint, "result_payload" "jsonb", "idempotent_replay" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'editorial', 'platform_private'
    AS $$
declare
  v_actor uuid;
  v_begin record;
  v_case editorial.correction_cases%rowtype;
  v_result jsonb;
begin
  v_actor :=
    platform_private.assert_correction_capability(
      'investigate_corrections'
    );

  if p_case_resource_id is null
     or p_expected_case_revision < 1
     or p_correlation_id is null
     or nullif(btrim(p_reason), '') is null
  then
    raise exception
      using errcode = '22023',
      message = 'Case, revision, reason, and correlation identity are required.';
  end if;

  select *
  into v_begin
  from platform_private.begin_resource_command(
    'correction.case.submit_for_decision',
    p_case_resource_id,
    p_idempotency_key,
    jsonb_build_object(
      'expected_case_revision', p_expected_case_revision,
      'reason', btrim(p_reason),
      'correlation_id', p_correlation_id
    )
  );

  if v_begin.idempotent_replay then
    return query
    select *
    from platform_private.read_correction_command_result(
      v_begin.command_receipt_id,
      true
    );
    return;
  end if;

  select correction_case.*
  into v_case
  from editorial.correction_cases correction_case
  where correction_case.resource_id =
    p_case_resource_id
  for update;

  if not found then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'case_not_found',
      'The correction case does not exist.',
      jsonb_build_object('case_revision', null)
    );
  elsif v_case.current_revision <>
        p_expected_case_revision
  then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'case_revision_changed',
      'The correction case revision changed.',
      jsonb_build_object(
        'case_revision', v_case.current_revision,
        'case_state', v_case.case_state
      )
    );
  elsif v_case.case_state <> 'investigating' then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'invalid_transition',
      'Only investigating cases may be submitted for decision.',
      jsonb_build_object(
        'case_revision', v_case.current_revision,
        'case_state', v_case.case_state
      )
    );
  elsif v_case.assigned_investigator_id is null
        or nullif(
          btrim(v_case.investigation_summary),
          ''
        ) is null
        or nullif(
          btrim(v_case.investigator_recommendation),
          ''
        ) is null
        or not v_case.evidence_ready
  then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'investigation_incomplete',
      'The case is not ready for institutional decision.',
      jsonb_build_object(
        'case_revision', v_case.current_revision,
        'case_state', v_case.case_state
      )
    );
  else
    update editorial.correction_cases
    set
      case_state = 'awaiting_decision',
      current_revision =
        v_case.current_revision + 1,
      submitted_for_decision_by = v_actor,
      submitted_for_decision_at = now(),
      updated_by = v_actor,
      updated_at = now()
    where resource_id = p_case_resource_id;

    perform platform_private.append_correction_event(
      p_case_resource_id,
      'submitted_for_decision',
      v_case.current_revision,
      v_case.current_revision + 1,
      v_case.case_state,
      'awaiting_decision',
      v_actor,
      btrim(p_reason),
      null,
      null,
      null,
      null,
      v_begin.command_receipt_id,
      p_correlation_id,
      '{}'::jsonb
    );

    v_result := jsonb_build_object(
      'case_resource_id', p_case_resource_id,
      'case_revision', v_case.current_revision + 1,
      'case_state', 'awaiting_decision'
    );

    perform platform_private.complete_resource_command(
      v_begin.command_receipt_id,
      v_result
    );
  end if;

  return query
  select *
  from platform_private.read_correction_command_result(
    v_begin.command_receipt_id,
    false
  );
end;
$$;


ALTER FUNCTION "public"."submit_correction_for_decision"("p_case_resource_id" "uuid", "p_expected_case_revision" bigint, "p_reason" "text", "p_idempotency_key" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_media_processing_command_v1"("p_asset_id" "uuid", "p_asset_revision_id" "uuid", "p_idempotency_key" "text", "p_profile_version" "text", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("command_receipt_id" "uuid", "job_id" "uuid", "accepted_event_id" "uuid", "receipt_status" "text", "idempotent_replay" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'editorial', 'media', 'platform_private', 'extensions'
    AS $_$
declare
  v_command_type constant text := 'media.process_revision';
  v_actor_id uuid;
  v_principal_key text;
  v_asset media.assets%rowtype;
  v_revision media.asset_revisions%rowtype;
  v_source media.file_objects%rowtype;
  v_profile_version text;
  v_correlation_id uuid := coalesce(
    p_correlation_id,
    gen_random_uuid()
  );
  v_request_payload jsonb;
  v_request_fingerprint text;
  v_receipt_id uuid;
  v_existing_fingerprint text;
  v_receipt_status text;
  v_job_id uuid;
  v_event_id uuid;
  v_created boolean;
  v_resource_kind text;
begin
  if auth.role() <> 'authenticated'
     or auth.uid() is null
  then
    raise exception
      using
        errcode = '42501',
        message = 'Authenticated Media processing actor is required.';
  end if;

  v_actor_id := auth.uid();

  if not (
    public.current_user_has_capability('manage_media_assets')
    or public.current_user_is_administrator()
  ) then
    raise exception
      using
        errcode = '42501',
        message = 'manage_media_assets capability is required.';
  end if;

  if p_asset_id is null
     or p_asset_revision_id is null
  then
    raise exception
      using
        errcode = '22023',
        message = 'asset_id and asset_revision_id are required.';
  end if;

  if p_idempotency_key is null
     or p_idempotency_key !~
       '^[A-Za-z0-9][A-Za-z0-9._:-]{7,127}$'
  then
    raise exception
      using
        errcode = '22023',
        message = 'idempotency_key is invalid.';
  end if;

  v_profile_version := nullif(
    btrim(p_profile_version),
    ''
  );

  select *
  into v_asset
  from media.assets
  where id = p_asset_id;

  if not found then
    raise exception
      using
        errcode = 'P0002',
        message = 'Media asset does not exist.';
  end if;

  if v_asset.lifecycle_state <> 'active' then
    raise exception
      using
        errcode = '55000',
        message = 'Only an active Media asset may be processed.';
  end if;

  if (
    v_asset.asset_kind = 'audio'
    and v_profile_version <> 'audio-v1'
  ) or (
    v_asset.asset_kind = 'video'
    and v_profile_version <> 'video-v1'
  ) or v_asset.asset_kind not in ('audio', 'video')
  then
    raise exception
      using
        errcode = '22023',
        message = 'Processing profile does not match the Media asset kind.';
  end if;

  select *
  into v_revision
  from media.asset_revisions
  where id = p_asset_revision_id
    and asset_id = p_asset_id;

  if not found then
    raise exception
      using
        errcode = 'P0002',
        message = 'Media revision does not belong to the requested asset.';
  end if;

  select *
  into v_source
  from media.file_objects
  where id = v_revision.original_file_object_id;

  if not found
     or v_source.verification_state <> 'verified'
     or v_source.storage_provider <> 'lightsail_media'
     or v_source.storage_path is null
     or v_source.storage_path !~ '^masters/(audio|video)/'
     or v_source.sha256 is null
     or v_source.byte_size is null
  then
    raise exception
      using
        errcode = '55000',
        message = 'M2 processing requires a verified protected Lightsail master.';
  end if;

  select resource_kind
  into v_resource_kind
  from editorial.resources
  where id = p_asset_id;

  if not found then
    insert into editorial.resources (
      id,
      resource_kind,
      owner_id,
      visibility,
      lifecycle_state,
      created_by
    )
    values (
      p_asset_id,
      'media_asset',
      v_actor_id,
      'internal',
      'active',
      v_actor_id
    );

    insert into editorial.media_asset_resources (
      resource_id,
      asset_id
    )
    values (
      p_asset_id,
      p_asset_id
    );
  else
    if v_resource_kind <> 'media_asset' then
      raise exception
        'Media asset UUID collides with another resource kind.';
    end if;

    if not exists (
      select 1
      from editorial.media_asset_resources
      where resource_id = p_asset_id
        and asset_id = p_asset_id
    ) then
      raise exception
        'Existing media_asset resource is missing its immutable binding.';
    end if;
  end if;

  v_principal_key := 'user:' || v_actor_id::text;

  v_request_payload := jsonb_build_object(
    'asset_id', p_asset_id,
    'asset_revision_id', p_asset_revision_id,
    'source_file_object_id', v_source.id,
    'source_storage_path', v_source.storage_path,
    'source_sha256', v_source.sha256,
    'source_byte_size', v_source.byte_size,
    'source_mime_type', v_source.mime_type,
    'asset_kind', v_asset.asset_kind,
    'profile_version', v_profile_version,
    'correlation_id', v_correlation_id
  );

  v_request_fingerprint := encode(
    extensions.digest(
      convert_to(
        jsonb_build_object(
          'command_type', v_command_type,
          'asset_id', p_asset_id,
          'asset_revision_id', p_asset_revision_id,
          'source_file_object_id', v_source.id,
          'source_sha256', v_source.sha256,
          'source_byte_size', v_source.byte_size,
          'profile_version', v_profile_version
        )::text,
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );

  insert into platform_private.command_receipts (
    command_type,
    resource_id,
    principal_key,
    actor_user_id,
    idempotency_key,
    request_fingerprint,
    request_payload
  )
  values (
    v_command_type,
    p_asset_id,
    v_principal_key,
    v_actor_id,
    p_idempotency_key,
    v_request_fingerprint,
    v_request_payload
  )
  on conflict (
    principal_key,
    command_type,
    idempotency_key
  )
  do nothing
  returning
    id,
    status
  into
    v_receipt_id,
    v_receipt_status;

  v_created := found;

  if not v_created then
    select
      receipt.id,
      receipt.request_fingerprint,
      receipt.status
    into
      v_receipt_id,
      v_existing_fingerprint,
      v_receipt_status
    from platform_private.command_receipts receipt
    where receipt.principal_key = v_principal_key
      and receipt.command_type = v_command_type
      and receipt.idempotency_key = p_idempotency_key
    for update;

    if not found then
      raise exception
        'Media processing idempotency receipt disappeared.';
    end if;

    if v_existing_fingerprint <> v_request_fingerprint then
      raise exception
        using
          errcode = '23505',
          message = 'The idempotency key was already used for a different processing request.';
    end if;

    select job.id
    into v_job_id
    from platform_private.jobs job
    where job.command_receipt_id = v_receipt_id
      and job.job_key = 'primary';

    select event.id
    into v_event_id
    from platform_private.outbox_events event
    where event.event_key =
      'command:' ||
      v_receipt_id::text ||
      ':accepted';

    if v_job_id is null
       or v_event_id is null
    then
      raise exception
        'Accepted Media processing command is missing its durable job or event.';
    end if;

    return query
    select
      v_receipt_id,
      v_job_id,
      v_event_id,
      v_receipt_status,
      true;

    return;
  end if;

  insert into platform_private.jobs (
    command_receipt_id,
    resource_id,
    command_type,
    job_key,
    job_type,
    max_attempts,
    input_payload
  )
  values (
    v_receipt_id,
    p_asset_id,
    v_command_type,
    'primary',
    'media.process_revision',
    4,
    v_request_payload
  )
  returning id
  into v_job_id;

  insert into platform_private.outbox_events (
    event_key,
    command_receipt_id,
    job_id,
    command_type,
    aggregate_id,
    event_type,
    payload
  )
  values (
    'command:' ||
      v_receipt_id::text ||
      ':accepted',
    v_receipt_id,
    v_job_id,
    v_command_type,
    p_asset_id,
    'media.processing.accepted',
    jsonb_build_object(
      'command_receipt_id', v_receipt_id,
      'job_id', v_job_id,
      'resource_id', p_asset_id,
      'asset_id', p_asset_id,
      'asset_revision_id', p_asset_revision_id,
      'source_file_object_id', v_source.id,
      'profile_version', v_profile_version,
      'principal_key', v_principal_key,
      'correlation_id', v_correlation_id,
      'accepted_at', now()
    )
  )
  returning id
  into v_event_id;

  return query
  select
    v_receipt_id,
    v_job_id,
    v_event_id,
    'accepted'::text,
    false;
end;
$_$;


ALTER FUNCTION "public"."submit_media_processing_command_v1"("p_asset_id" "uuid", "p_asset_revision_id" "uuid", "p_idempotency_key" "text", "p_profile_version" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_playlist_for_review"("p_playlist_id" "uuid", "p_expected_authority_revision" bigint, "p_idempotency_key" "text", "p_note" "text" DEFAULT NULL::"text", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("command_receipt_id" "uuid", "receipt_status" "text", "playlist_id" "uuid", "resource_id" "uuid", "authority_revision" bigint, "version_id" "uuid", "version_number" bigint, "lifecycle_status" "text", "result_payload" "jsonb", "idempotent_replay" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'editorial', 'platform_private'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_playlist public.wk_playlists%rowtype;
  v_binding editorial.playlist_resources%rowtype;
  v_working editorial.playlist_versions%rowtype;
  v_snapshot record;
  v_fingerprint text;
  v_begin record;
  v_read record;
  v_result jsonb;
  v_prior_status text;
  v_event_number bigint;
  v_trust_count bigint := 0;
  v_copy_working_trust boolean := false;
  v_active_item_count bigint;
  v_correlation_id uuid :=
    coalesce(
      p_correlation_id,
      gen_random_uuid()
    );
begin
  if v_actor is null then
    raise exception 'Not authenticated';
  end if;

  select playlist.*
  into v_playlist
  from public.wk_playlists playlist
  where playlist.id = p_playlist_id
  for update;

  if not found then
    raise exception 'Playlist does not exist';
  end if;

  select binding.*
  into v_binding
  from editorial.playlist_resources binding
  where binding.playlist_id = p_playlist_id
  for update;

  if v_binding.resource_id is null then
    raise exception
      'Playlist Resource binding does not exist';
  end if;

  if not editorial.current_user_can_edit_playlist(
    v_binding.resource_id
  ) then
    raise exception
      'Playlist edit permission is required';
  end if;

  v_fingerprint :=
    editorial.playlist_current_content_fingerprint(
      p_playlist_id
    );

  select *
  into v_begin
  from platform_private.begin_authenticated_resource_command(
    'playlist.review.submit',
    v_binding.resource_id,
    p_idempotency_key,
    jsonb_build_object(
      'playlist_id',
        p_playlist_id,
      'expected_authority_revision',
        p_expected_authority_revision,
      'content_fingerprint',
        v_fingerprint,
      'note',
        nullif(
          btrim(p_note),
          ''
        ),
      'correlation_id',
        v_correlation_id
    )
  );

  if v_begin.idempotent_replay then
    select *
    into v_read
    from platform_private.read_authenticated_resource_command_result(
      v_begin.command_receipt_id,
      true
    );

    command_receipt_id :=
      v_read.command_receipt_id;
    receipt_status :=
      v_read.receipt_status;
    playlist_id := p_playlist_id;
    resource_id := v_read.resource_id;
    authority_revision :=
      nullif(
        v_read.result_payload
          ->> 'authority_revision',
        ''
      )::bigint;
    version_id :=
      nullif(
        v_read.result_payload
          ->> 'version_id',
        ''
      )::uuid;
    version_number :=
      nullif(
        v_read.result_payload
          ->> 'version_number',
        ''
      )::bigint;
    lifecycle_status :=
      v_read.result_payload
        ->> 'lifecycle_status';
    result_payload :=
      v_read.result_payload;
    idempotent_replay := true;
    return next;
    return;
  end if;

  if p_expected_authority_revision is null
     or p_expected_authority_revision < 1
     or v_playlist.authority_revision
          <> p_expected_authority_revision
  then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'playlist_revision_changed',
      'The Playlist changed before it could be submitted.',
      jsonb_build_object(
        'playlist_id',
          p_playlist_id,
        'authority_revision',
          v_playlist.authority_revision,
        'lifecycle_status',
          v_playlist.status
      )
    );

  elsif v_playlist.status not in (
    'draft',
    'changes_requested',
    'published'
  ) then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'playlist_not_submittable',
      'Only a draft, changes-requested, or published Playlist can be submitted.',
      jsonb_build_object(
        'playlist_id',
          p_playlist_id,
        'authority_revision',
          v_playlist.authority_revision,
        'lifecycle_status',
          v_playlist.status
      )
    );

  elsif v_playlist.status = 'published'
        and v_binding.current_published_version_id is null
  then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'playlist_published_version_missing',
      'The published Playlist does not have a current published version.',
      jsonb_build_object(
        'playlist_id',
          p_playlist_id,
        'authority_revision',
          v_playlist.authority_revision,
        'lifecycle_status',
          v_playlist.status
      )
    );

  elsif v_playlist.status = 'published'
        and exists (
          select 1
          from editorial.playlist_versions published
          where published.id =
                  v_binding.current_published_version_id
            and published.resource_id =
                  v_binding.resource_id
            and published.playlist_id =
                  p_playlist_id
            and published.version_kind =
                  'published'
            and published.content_fingerprint =
                  v_fingerprint
        )
  then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'playlist_published_update_unchanged',
      'The published Playlist has no saved content change to submit.',
      jsonb_build_object(
        'playlist_id',
          p_playlist_id,
        'authority_revision',
          v_playlist.authority_revision,
        'lifecycle_status',
          v_playlist.status,
        'current_published_version_id',
          v_binding.current_published_version_id
      )
    );

  elsif v_playlist.status = 'published'
        and (
          v_binding.current_working_version_id is null
          or not exists (
            select 1
            from editorial.playlist_versions working
            where working.id =
                    v_binding.current_working_version_id
              and working.resource_id =
                    v_binding.resource_id
              and working.playlist_id =
                    p_playlist_id
              and working.version_kind =
                    'working'
              and working.content_fingerprint =
                    v_fingerprint
          )
        )
  then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'playlist_published_update_not_saved',
      'Save the published Playlist update before submitting it for Review.',
      jsonb_build_object(
        'playlist_id',
          p_playlist_id,
        'authority_revision',
          v_playlist.authority_revision,
        'lifecycle_status',
          v_playlist.status,
        'current_working_version_id',
          v_binding.current_working_version_id,
        'current_published_version_id',
          v_binding.current_published_version_id
      )
    );

  else
    select count(*)
    into v_active_item_count
    from public.wk_playlist_items item
    where item.playlist_id = p_playlist_id
      and item.lifecycle_state = 'active';

    if v_active_item_count = 0 then
      perform platform_private.reject_resource_command(
        v_begin.command_receipt_id,
        'playlist_empty',
        'A Playlist needs at least one track before Review.',
        jsonb_build_object(
          'playlist_id',
            p_playlist_id,
          'authority_revision',
            v_playlist.authority_revision
        )
      );
    end if;

    if exists (
      select 1
      from platform_private.command_receipts receipt
      where receipt.id =
              v_begin.command_receipt_id
        and receipt.status = 'accepted'
    )
       and v_binding.current_working_version_id
             is not null
    then
      select version.*
      into v_working
      from editorial.playlist_versions version
      where version.id =
        v_binding.current_working_version_id;

      if found
         and v_working.content_fingerprint =
               v_fingerprint
      then
        v_copy_working_trust := true;
      elsif found then
        select
          (
            select count(*)
            from editorial.resource_citations citation
            where citation.target_version_type =
                    'playlist_version'
              and citation.target_version_id =
                    v_working.id
          )
          +
          (
            select count(*)
            from editorial.resource_credits credit
            where credit.target_version_type =
                    'playlist_version'
              and credit.target_version_id =
                    v_working.id
          )
        into v_trust_count;

        if v_trust_count > 0 then
          perform platform_private.reject_resource_command(
            v_begin.command_receipt_id,
            'playlist_working_trust_stale',
            'Version-bound Playlist Trust is attached to an older working snapshot.',
            jsonb_build_object(
              'playlist_id',
                p_playlist_id,
              'authority_revision',
                v_playlist.authority_revision,
              'working_version_id',
                v_working.id,
              'working_source_authority_revision',
                v_working.source_authority_revision,
              'trust_binding_count',
                v_trust_count
            )
          );
        end if;
      end if;
    end if;

    if exists (
      select 1
      from platform_private.command_receipts receipt
      where receipt.id =
              v_begin.command_receipt_id
        and receipt.status = 'accepted'
    )
    then
      v_prior_status := v_playlist.status;

      select *
      into v_snapshot
      from editorial.insert_playlist_current_snapshot(
        p_playlist_id,
        v_playlist.authority_revision,
        'submitted',
        'ready_for_review',
        v_actor
      );

      if v_copy_working_trust then
        perform
          editorial.copy_playlist_working_trust_to_version(
            v_binding.resource_id,
            v_working.id,
            v_snapshot.version_id
          );
      end if;

      update editorial.playlist_resources binding_update
      set
        current_submitted_version_id =
          v_snapshot.version_id,
        current_approved_version_id = null
      where binding_update.playlist_id = p_playlist_id;

      update public.wk_playlists playlist
      set
        status = 'ready_for_review',
        authority_revision =
          playlist.authority_revision + 1
      where playlist.id = p_playlist_id
      returning playlist.*
      into v_playlist;

      select coalesce(
        max(event.event_number),
        0
      ) + 1
      into v_event_number
      from editorial.playlist_review_events event
      where event.resource_id =
              v_binding.resource_id;

      insert into editorial.playlist_review_events (
        resource_id,
        playlist_id,
        event_number,
        target_version_id,
        result_version_id,
        action,
        prior_status,
        resulting_status,
        reason,
        actor_id,
        command_receipt_id,
        correlation_id
      )
      values (
        v_binding.resource_id,
        p_playlist_id,
        v_event_number,
        v_snapshot.version_id,
        null,
        'submitted',
        v_prior_status,
        'ready_for_review',
        nullif(
          btrim(p_note),
          ''
        ),
        v_actor,
        v_begin.command_receipt_id,
        v_correlation_id
      );

      v_result := jsonb_build_object(
        'playlist_id',
          p_playlist_id,
        'resource_id',
          v_binding.resource_id,
        'authority_revision',
          v_playlist.authority_revision,
        'version_id',
          v_snapshot.version_id,
        'version_number',
          v_snapshot.version_number,
        'content_fingerprint',
          v_snapshot.content_fingerprint,
        'item_count',
          v_snapshot.item_count,
        'lifecycle_status',
          'ready_for_review',
        'correlation_id',
          v_correlation_id
      );

      perform platform_private.complete_resource_command(
        v_begin.command_receipt_id,
        v_result
      );
    end if;
  end if;

  select *
  into v_read
  from platform_private.read_authenticated_resource_command_result(
    v_begin.command_receipt_id,
    false
  );

  command_receipt_id :=
    v_read.command_receipt_id;
  receipt_status :=
    v_read.receipt_status;
  playlist_id := p_playlist_id;
  resource_id := v_read.resource_id;
  authority_revision :=
    nullif(
      v_read.result_payload
        ->> 'authority_revision',
      ''
    )::bigint;
  version_id :=
    nullif(
      v_read.result_payload
        ->> 'version_id',
      ''
    )::uuid;
  version_number :=
    nullif(
      v_read.result_payload
        ->> 'version_number',
      ''
    )::bigint;
  lifecycle_status :=
    v_read.result_payload
      ->> 'lifecycle_status';
  result_payload :=
    v_read.result_payload;
  idempotent_replay := false;
  return next;
end;
$$;


ALTER FUNCTION "public"."submit_playlist_for_review"("p_playlist_id" "uuid", "p_expected_authority_revision" bigint, "p_idempotency_key" "text", "p_note" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."submit_playlist_for_review"("p_playlist_id" "uuid", "p_expected_authority_revision" bigint, "p_idempotency_key" "text", "p_note" "text", "p_correlation_id" "uuid") IS 'Submits draft, changes-requested, or genuinely changed saved published Playlist content into immutable Review while the current published snapshot remains public.';



CREATE OR REPLACE FUNCTION "public"."submit_playlist_registry_intake"("p_playlist_id" "uuid", "p_expected_authority_revision" bigint, "p_validation_id" "uuid", "p_artist_credits" "jsonb", "p_idempotency_key" "text", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'auth', 'public', 'editorial', 'platform_private'
    AS $$
declare
  v_playlist public.wk_playlists%rowtype;
  v_resource_id uuid;
  v_validation platform_private.playlist_playback_validations%rowtype;
  v_begin record;
  v_read record;
  v_request jsonb;
  v_result jsonb;
  v_suggestion_id uuid := gen_random_uuid();
  v_reserved_position integer;
  v_credit jsonb;
  v_credit_order integer := 0;
  v_credit_role text;
  v_resolution_mode text;
  v_registry_artist_id uuid;
  v_observed_name text;
  v_registry_display_name text;
  v_primary_count integer := 0;
  v_legacy_mode text;
  v_legacy_artist_id uuid;
  v_correlation_id uuid := coalesce(
    p_correlation_id,
    gen_random_uuid()
  );
begin
  if auth.uid() is null then
    raise exception
      using errcode = '42501', message = 'Authentication is required.';
  end if;

  if p_playlist_id is null
     or p_expected_authority_revision is null
     or p_expected_authority_revision < 1
     or p_validation_id is null
  then
    raise exception
      'Playlist, expected revision, and playback validation are required.';
  end if;

  if p_artist_credits is null
     or jsonb_typeof(p_artist_credits) <> 'array'
     or jsonb_array_length(p_artist_credits) < 1
     or jsonb_array_length(p_artist_credits) > 20
  then
    raise exception
      'Add between 1 and 20 primary or featured artist credits before Registry intake.';
  end if;

  select playlist.*
  into v_playlist
  from public.wk_playlists playlist
  where playlist.id = p_playlist_id
  for update of playlist;

  select binding.resource_id
  into v_resource_id
  from editorial.playlist_resources binding
  where binding.playlist_id = p_playlist_id;

  if not found then
    raise exception
      using errcode = 'P0002', message = 'Playlist does not exist.';
  end if;

  if not editorial.current_user_can_edit_playlist(v_resource_id) then
    raise exception
      using errcode = '42501', message = 'Playlist edit permission is required.';
  end if;

  select validation.*
  into v_validation
  from platform_private.playlist_playback_validations validation
  where validation.id = p_validation_id
    and validation.requested_by = auth.uid()
    and validation.playlist_id = p_playlist_id
    and validation.playable
    and validation.validation_status = 'playable'
    and validation.expires_at > now();

  if not found then
    raise exception
      'Playback validation is missing or expired. Check the provider link again.';
  end if;

  v_request := jsonb_build_object(
    'playlist_id', p_playlist_id,
    'expected_authority_revision', p_expected_authority_revision,
    'validation_id', p_validation_id,
    'artist_credits', p_artist_credits,
    'correlation_id', v_correlation_id
  );

  select *
  into v_begin
  from platform_private.begin_authenticated_resource_command(
    'playlist.item.add',
    v_resource_id,
    p_idempotency_key,
    v_request
  );

  if v_begin.idempotent_replay then
    select *
    into v_read
    from platform_private.read_authenticated_resource_command_result(
      v_begin.command_receipt_id,
      true
    );
    return v_read.result_payload;
  end if;

  if v_playlist.authority_revision <> p_expected_authority_revision then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'playlist_revision_changed',
      'The Playlist changed before Registry intake could reserve its position.',
      jsonb_build_object(
        'playlist_id', p_playlist_id,
        'authority_revision', v_playlist.authority_revision
      )
    );

    select *
    into v_read
    from platform_private.read_authenticated_resource_command_result(
      v_begin.command_receipt_id,
      false
    );

    return v_read.result_payload;
  end if;

  for v_credit in
    select value
    from jsonb_array_elements(p_artist_credits)
  loop
    v_credit_order := v_credit_order + 1;
    v_credit_role := lower(
      btrim(coalesce(v_credit ->> 'credit_role', ''))
    );
    v_resolution_mode := lower(
      btrim(coalesce(v_credit ->> 'resolution_mode', ''))
    );
    v_observed_name := nullif(
      btrim(v_credit ->> 'observed_name'),
      ''
    );

    if v_credit_role not in ('primary', 'featured') then
      raise exception
        'Every Registry intake artist credit must be Primary or Featured.';
    end if;

    if v_resolution_mode not in (
      'existing_artist',
      'alias_candidate',
      'new_artist'
    ) then
      raise exception
        'Each Registry intake artist must be a Registry artist, an alias candidate, or a new-artist suggestion.';
    end if;

    v_registry_artist_id := null;

    if v_resolution_mode in (
      'existing_artist',
      'alias_candidate'
    ) then
      if nullif(
           btrim(v_credit ->> 'registry_artist_id'),
           ''
         ) is null
      then
        raise exception
          'Select a Music Registry artist for an existing or alias artist credit.';
      end if;

      v_registry_artist_id :=
        (v_credit ->> 'registry_artist_id')::uuid;

      select artist.display_name
      into v_registry_display_name
      from public.registry_artists artist
      where artist.id = v_registry_artist_id
        and artist.status in ('active', 'draft');

      if not found then
        raise exception
          'One selected Music Registry artist is unavailable.';
      end if;

      if v_resolution_mode = 'alias_candidate'
         and v_observed_name is null
      then
        raise exception
          'An alias candidate needs the provider-observed artist name.';
      end if;

      v_observed_name := coalesce(
        v_observed_name,
        v_registry_display_name
      );
    else
      if nullif(
           btrim(v_credit ->> 'registry_artist_id'),
           ''
         ) is not null
      then
        raise exception
          'A new-artist suggestion cannot claim canonical Registry identity.';
      end if;

      if v_observed_name is null then
        raise exception
          'A new-artist suggestion needs the observed artist name.';
      end if;
    end if;

    if v_credit_role = 'primary' then
      v_primary_count := v_primary_count + 1;

      if v_legacy_mode is null then
        v_legacy_mode := v_resolution_mode;
        v_legacy_artist_id := v_registry_artist_id;
      end if;
    end if;
  end loop;

  if v_primary_count < 1 then
    raise exception
      'Registry intake needs at least one Primary artist credit.';
  end if;

  if exists (
    select 1
    from (
      select
        coalesce(
          nullif(btrim(value ->> 'registry_artist_id'), ''),
          lower(btrim(value ->> 'observed_name'))
        ) as artist_identity,
        count(*) as duplicate_count
      from jsonb_array_elements(p_artist_credits)
      group by 1
    ) duplicate
    where duplicate.artist_identity is not null
      and duplicate.duplicate_count > 1
  ) then
    raise exception
      'The same artist cannot be added to Registry intake more than once.';
  end if;

  v_reserved_position :=
    editorial.next_playlist_position_with_registry_intake(
      p_playlist_id,
      null
    );

  insert into public.registry_provider_track_suggestions (
    id,
    source_playlist_id,
    source_playlist_item_id,
    requested_by,
    canonical_track_id,
    registry_artist_id,
    artist_resolution_mode,
    provider_key,
    provider_object_id,
    provider_url,
    provider_title,
    provider_artist_names,
    provider_release_title,
    playback_kind,
    validation_snapshot,
    status,
    reserved_position
  )
  values (
    v_suggestion_id,
    p_playlist_id,
    null,
    auth.uid(),
    null,
    v_legacy_artist_id,
    coalesce(v_legacy_mode, 'unresolved'),
    v_validation.provider_key,
    v_validation.provider_object_id,
    v_validation.canonical_url,
    v_validation.title_hint,
    v_validation.artist_names_hint,
    v_validation.release_title_hint,
    v_validation.playback_kind,
    jsonb_build_object(
      'validation_id', v_validation.id,
      'embed_url', v_validation.embed_url,
      'preview_url', v_validation.preview_url,
      'artwork_url', v_validation.artwork_url,
      'provider_metadata', v_validation.provider_metadata,
      'checked_at', v_validation.checked_at
    ),
    'needs_review',
    v_reserved_position
  );

  v_credit_order := 0;

  for v_credit in
    select value
    from jsonb_array_elements(p_artist_credits)
  loop
    v_credit_order := v_credit_order + 1;
    v_credit_role := lower(
      btrim(v_credit ->> 'credit_role')
    );
    v_resolution_mode := lower(
      btrim(v_credit ->> 'resolution_mode')
    );
    v_observed_name := nullif(
      btrim(v_credit ->> 'observed_name'),
      ''
    );
    v_registry_artist_id := null;

    if v_resolution_mode in (
      'existing_artist',
      'alias_candidate'
    ) then
      v_registry_artist_id :=
        (v_credit ->> 'registry_artist_id')::uuid;

      select artist.display_name
      into v_registry_display_name
      from public.registry_artists artist
      where artist.id = v_registry_artist_id;

      v_observed_name := coalesce(
        v_observed_name,
        v_registry_display_name
      );
    end if;

    insert into public.registry_provider_track_suggestion_artists (
      suggestion_id,
      credit_order,
      credit_role,
      resolution_mode,
      registry_artist_id,
      observed_name
    )
    values (
      v_suggestion_id,
      v_credit_order,
      v_credit_role,
      v_resolution_mode,
      v_registry_artist_id,
      v_observed_name
    );
  end loop;

  update public.wk_playlists playlist
  set authority_revision = playlist.authority_revision + 1
  where playlist.id = p_playlist_id
  returning playlist.authority_revision
  into v_playlist.authority_revision;

  v_result := jsonb_build_object(
    'suggestion_id', v_suggestion_id,
    'status', 'needs_review',
    'reserved_position', v_reserved_position,
    'authority_revision', v_playlist.authority_revision,
    'artist_credit_count', jsonb_array_length(p_artist_credits),
    'playlist_changed', true,
    'correlation_id', v_correlation_id
  );

  perform platform_private.complete_resource_command(
    v_begin.command_receipt_id,
    v_result
  );

  return v_result;
end;
$$;


ALTER FUNCTION "public"."submit_playlist_registry_intake"("p_playlist_id" "uuid", "p_expected_authority_revision" bigint, "p_validation_id" "uuid", "p_artist_credits" "jsonb", "p_idempotency_key" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_resource_reconciliation_command"("p_resource_id" "uuid", "p_idempotency_key" "text", "p_reason" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS TABLE("command_receipt_id" "uuid", "job_id" "uuid", "accepted_event_id" "uuid", "receipt_status" "text", "idempotent_replay" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'editorial', 'platform_private'
    AS $_$
declare
  v_command_type constant text :=
    'resource.reconcile_identity';
  v_actor_user_id uuid;
  v_auth_role text;
  v_principal_key text;
  v_resource_kind text;
  v_reason text;
  v_metadata jsonb;
  v_request_payload jsonb;
  v_request_fingerprint text;
  v_receipt_id uuid;
  v_existing_fingerprint text;
  v_receipt_status text;
  v_job_id uuid;
  v_event_id uuid;
  v_created boolean;
  v_authorized boolean := false;
begin
  if p_resource_id is null then
    raise exception
      using
        errcode = '22023',
        message = 'resource_id is required.';
  end if;

  if p_idempotency_key is null
    or p_idempotency_key !~
      '^[A-Za-z0-9][A-Za-z0-9._:-]{7,127}$'
  then
    raise exception
      using
        errcode = '22023',
        message =
          'idempotency_key must contain 8 to 128 permitted characters.';
  end if;

  v_metadata := coalesce(
    p_metadata,
    '{}'::jsonb
  );

  if jsonb_typeof(v_metadata) <> 'object'
    or octet_length(v_metadata::text) > 16384
  then
    raise exception
      using
        errcode = '22023',
        message =
          'metadata must be a JSON object no larger than 16 KB.';
  end if;

  v_reason := nullif(
    btrim(p_reason),
    ''
  );

  if length(coalesce(v_reason, '')) > 1000 then
    raise exception
      using
        errcode = '22023',
        message = 'reason must not exceed 1000 characters.';
  end if;

  v_auth_role := coalesce(
    auth.role(),
    ''
  );

  v_actor_user_id := auth.uid();

  if v_auth_role = 'service_role' then
    v_principal_key := 'service:service_role';
  elsif v_auth_role = 'authenticated'
    and v_actor_user_id is not null
  then
    v_principal_key :=
      'user:' || v_actor_user_id::text;
  else
    raise exception
      using
        errcode = '42501',
        message =
          'Authentication is required to submit a resource command.';
  end if;

  select resources.resource_kind
  into v_resource_kind
  from editorial.resources
  where resources.id = p_resource_id;

  if not found then
    raise exception
      using
        errcode = 'P0002',
        message = 'The requested resource does not exist.';
  end if;

  if v_auth_role = 'service_role' then
    v_authorized := true;
  else
    v_authorized :=
      public.current_user_is_administrator();

    if not v_authorized then
      case v_resource_kind
        when 'article' then
          v_authorized :=
            public.current_user_has_capability(
              'edit_others_articles'
            );

        when 'playlist' then
          v_authorized :=
            public.current_user_has_capability(
              'institute_write'
            )
            or public.current_user_has_capability(
              'institute_admin'
            );

        when 'registry_artist' then
          v_authorized :=
            public.current_user_has_capability(
              'manage_registry'
            );

        else
          v_authorized := false;
      end case;
    end if;
  end if;

  if not v_authorized then
    raise exception
      using
        errcode = '42501',
        message =
          'The caller cannot submit this command for the resource kind.';
  end if;

  v_request_payload := jsonb_build_object(
    'resource_id',
    p_resource_id,
    'reason',
    v_reason,
    'metadata',
    v_metadata
  );

  v_request_fingerprint := encode(
    extensions.digest(
      convert_to(
        jsonb_build_object(
          'command_type',
          v_command_type,
          'resource_id',
          p_resource_id,
          'reason',
          v_reason,
          'metadata',
          v_metadata
        )::text,
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );

  insert into platform_private.command_receipts (
    command_type,
    resource_id,
    principal_key,
    actor_user_id,
    idempotency_key,
    request_fingerprint,
    request_payload
  )
  values (
    v_command_type,
    p_resource_id,
    v_principal_key,
    v_actor_user_id,
    p_idempotency_key,
    v_request_fingerprint,
    v_request_payload
  )
  on conflict (
    principal_key,
    command_type,
    idempotency_key
  )
  do nothing
  returning
    id,
    status
  into
    v_receipt_id,
    v_receipt_status;

  v_created := found;

  if not v_created then
    select
      command_receipts.id,
      command_receipts.request_fingerprint,
      command_receipts.status
    into
      v_receipt_id,
      v_existing_fingerprint,
      v_receipt_status
    from platform_private.command_receipts
    where command_receipts.principal_key =
        v_principal_key
      and command_receipts.command_type =
        v_command_type
      and command_receipts.idempotency_key =
        p_idempotency_key
    for update;

    if not found then
      raise exception
        'The idempotency record disappeared during command submission.';
    end if;

    if v_existing_fingerprint <>
      v_request_fingerprint
    then
      raise exception
        using
          errcode = '23505',
          message =
            'The idempotency key was already used for a different request.';
    end if;

    select jobs.id
    into v_job_id
    from platform_private.jobs
    where jobs.command_receipt_id =
        v_receipt_id
      and jobs.job_key = 'primary';

    select outbox_events.id
    into v_event_id
    from platform_private.outbox_events
    where outbox_events.event_key =
      'command:' ||
      v_receipt_id::text ||
      ':accepted';

    if v_job_id is null
      or v_event_id is null
    then
      raise exception
        'The accepted command is missing its durable job or outbox event.';
    end if;

    return query
    select
      v_receipt_id,
      v_job_id,
      v_event_id,
      v_receipt_status,
      true;

    return;
  end if;

  insert into platform_private.jobs (
    command_receipt_id,
    resource_id,
    command_type,
    job_key,
    job_type,
    input_payload
  )
  select
    v_receipt_id,
    p_resource_id,
    command_types.command_type,
    'primary',
    command_types.job_type,
    v_request_payload
  from platform_private.command_types
  where command_types.command_type =
      v_command_type
    and command_types.enabled
  returning id
  into v_job_id;

  if v_job_id is null then
    raise exception
      'The controlled command type is missing or disabled.';
  end if;

  insert into platform_private.outbox_events (
    event_key,
    command_receipt_id,
    job_id,
    command_type,
    aggregate_id,
    event_type,
    payload
  )
  select
    'command:' ||
      v_receipt_id::text ||
      ':accepted',
    v_receipt_id,
    v_job_id,
    command_types.command_type,
    p_resource_id,
    command_types.accepted_event_type,
    jsonb_build_object(
      'command_receipt_id',
      v_receipt_id,
      'job_id',
      v_job_id,
      'command_type',
      command_types.command_type,
      'resource_id',
      p_resource_id,
      'principal_key',
      v_principal_key,
      'accepted_at',
      now()
    )
  from platform_private.command_types
  where command_types.command_type =
      v_command_type
  returning id
  into v_event_id;

  return query
  select
    v_receipt_id,
    v_job_id,
    v_event_id,
    'accepted'::text,
    false;
end
$_$;


ALTER FUNCTION "public"."submit_resource_reconciliation_command"("p_resource_id" "uuid", "p_idempotency_key" "text", "p_reason" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_source_version_for_review"("p_source_id" "uuid", "p_source_version_id" "uuid", "p_expected_working_revision" bigint, "p_reason" "text" DEFAULT NULL::"text", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial', 'auth'
    AS $$
declare
  v_actor_id uuid;
  v_source editorial.sources%rowtype;
begin
  v_actor_id :=
    editorial.assert_source_command_actor('manage_sources');

  select *
  into v_source
  from editorial.sources source
  where source.id = p_source_id
  for update;

  if not found then
    raise exception
      'Source was not found';
  end if;

  if v_source.working_revision <>
       p_expected_working_revision then
    raise exception
      'Source working revision conflict. Expected %, found %',
      p_expected_working_revision,
      v_source.working_revision;
  end if;

  if v_source.source_state <> 'active' then
    raise exception
      'Only active Sources can be submitted';
  end if;

  if v_source.current_working_version_id
       is distinct from p_source_version_id then
    raise exception
      'Only the current working Source version can be submitted';
  end if;

  if not exists (
    select 1
    from editorial.source_versions source_version
    where source_version.id = p_source_version_id
      and source_version.source_id = p_source_id
  ) then
    raise exception
      'Source version does not belong to the Source';
  end if;

  update editorial.sources
  set
    current_submitted_version_id = p_source_version_id,
    review_status = 'ready_for_review',
    exposure_class = 'internal',
    updated_by = v_actor_id,
    updated_at = now()
  where id = p_source_id;

  insert into editorial.source_review_events (
    source_id,
    source_version_id,
    actor_id,
    action,
    reason,
    prior_review_status,
    resulting_review_status,
    prior_exposure_class,
    resulting_exposure_class,
    prior_source_state,
    resulting_source_state,
    correlation_id
  )
  values (
    p_source_id,
    p_source_version_id,
    v_actor_id,
    'review_started',
    nullif(btrim(p_reason), ''),
    v_source.review_status,
    'ready_for_review',
    v_source.exposure_class,
    'internal',
    v_source.source_state,
    v_source.source_state,
    p_correlation_id
  );

  return jsonb_build_object(
    'source_id',
      p_source_id,
    'source_version_id',
      p_source_version_id,
    'working_revision',
      v_source.working_revision,
    'review_status',
      'ready_for_review'
  );
end;
$$;


ALTER FUNCTION "public"."submit_source_version_for_review"("p_source_id" "uuid", "p_source_version_id" "uuid", "p_expected_working_revision" bigint, "p_reason" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."submit_source_version_for_review"("p_source_id" "uuid", "p_source_version_id" "uuid", "p_expected_working_revision" bigint, "p_reason" "text", "p_correlation_id" "uuid") IS 'Submits the exact current working Source version for review.';



CREATE OR REPLACE FUNCTION "public"."suspend_user_access_admin"("target_user_id" "uuid", "reason" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not public.current_user_is_administrator() then
    raise exception 'Only administrators can suspend users.' using errcode = '42501';
  end if;

  update public.user_profiles set status = 'suspended', updated_at = now() where user_id = target_user_id;
  update public.user_role_assignments set status = 'suspended', updated_at = now() where user_id = target_user_id and status = 'active';
  update public.user_access_scopes set status = 'suspended', updated_at = now() where user_id = target_user_id and status = 'active';
  perform public.record_admin_audit('user_suspended', 'user_profiles', target_user_id::text, target_user_id, coalesce(reason, 'User suspended from admin users console.'), jsonb_build_object('reason', reason));
  return true;
end;
$$;


ALTER FUNCTION "public"."suspend_user_access_admin"("target_user_id" "uuid", "reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_registry_track_intake_artist_credits"("p_suggestion_id" "uuid", "p_registry_track_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_suggestion public.registry_provider_track_suggestions%rowtype;
  v_track public.registry_tracks%rowtype;
  v_credit record;
  v_existing_id uuid;
  v_existing_count integer;
  v_target_collision_count integer;
  v_expected_role text;
  v_expected_primary boolean;
  v_expected_featured boolean;
  v_inserted integer := 0;
  v_updated integer := 0;
  v_unchanged integer := 0;
  v_reviewed integer := 0;
begin
  select suggestion.*
  into v_suggestion
  from public.registry_provider_track_suggestions suggestion
  where suggestion.id = p_suggestion_id;

  if not found then
    raise exception 'Track Intake item does not exist.';
  end if;

  if v_suggestion.status not in ('needs_review', 'canonicalized') then
    raise exception
      'Track Intake artist synchronization requires a reviewable or canonicalized suggestion.';
  end if;

  select track.*
  into v_track
  from public.registry_tracks track
  where track.id = p_registry_track_id
    and track.status = 'active';

  if not found then
    raise exception 'Selected Music Registry track is unavailable.';
  end if;

  for v_credit in
    select
      credit.id as source_credit_id,
      credit.credit_order,
      credit.credit_role,
      credit.observed_name,
      credit.registry_artist_id,
      artist.id as artist_id,
      artist.slug as artist_slug,
      artist.display_name as artist_name
    from public.registry_provider_track_suggestion_artists credit
    join public.registry_artists artist
      on artist.id = credit.registry_artist_id
     and artist.status = 'active'
    where credit.suggestion_id = p_suggestion_id
      and credit.resolution_mode = 'existing_artist'
      and credit.credit_role in ('primary', 'featured')
    order by credit.credit_order, credit.id
  loop
    v_reviewed := v_reviewed + 1;

    v_expected_role :=
      case
        when v_credit.credit_role = 'featured'
          then 'featured_artist'
        else 'primary_artist'
      end;

    v_expected_primary := v_credit.credit_role = 'primary';
    v_expected_featured := v_credit.credit_role = 'featured';

    select count(*)::integer
    into v_existing_count
    from public.registry_track_artists track_artist
    where track_artist.track_id = p_registry_track_id
      and (
        track_artist.artist_id = v_credit.artist_id
        or lower(coalesce(track_artist.artist_slug, '')) =
           lower(v_credit.artist_slug)
      )
      and track_artist.status = 'active';

    if v_existing_count > 1 then
      raise exception
        'Registry Track has more than one active relationship for reviewed artist %.',
        v_credit.artist_name;
    end if;

    v_existing_id := null;

    select track_artist.id
    into v_existing_id
    from public.registry_track_artists track_artist
    where track_artist.track_id = p_registry_track_id
      and (
        track_artist.artist_id = v_credit.artist_id
        or lower(coalesce(track_artist.artist_slug, '')) =
           lower(v_credit.artist_slug)
      )
    order by
      case
        when track_artist.status = 'active' then 0
        when track_artist.status = 'needs_review' then 1
        else 2
      end,
      case
        when track_artist.artist_id = v_credit.artist_id then 0
        else 1
      end,
      track_artist.created_at,
      track_artist.id
    limit 1
    for update;

    select count(*)::integer
    into v_target_collision_count
    from public.registry_track_artists track_artist
    where track_artist.track_id = p_registry_track_id
      and track_artist.artist_id = v_credit.artist_id
      and track_artist.role = v_expected_role
      and track_artist.credit_order = v_credit.credit_order
      and (
        v_existing_id is null
        or track_artist.id <> v_existing_id
      );

    if v_target_collision_count > 0 then
      raise exception
        'Registry Track artist synchronization would collide with an existing reviewed target key for %.',
        v_credit.artist_name;
    end if;

    if v_existing_id is null then
      insert into public.registry_track_artists (
        track_id,
        artist_id,
        artist_slug,
        artist_name_text,
        role,
        is_primary,
        is_featured,
        credit_order,
        display_credit,
        source,
        confidence,
        status,
        metadata,
        created_at,
        updated_at
      )
      values (
        p_registry_track_id,
        v_credit.artist_id,
        v_credit.artist_slug,
        v_credit.artist_name,
        v_expected_role,
        v_expected_primary,
        v_expected_featured,
        v_credit.credit_order,
        v_credit.artist_name,
        'track_intake_review',
        100,
        'active',
        jsonb_build_object(
          'source_suggestion_id', p_suggestion_id::text,
          'source_credit_id', v_credit.source_credit_id::text,
          'observed_name', v_credit.observed_name,
          'sync_contract', 'phase5b_registry_artist_credit_parity_v2'
        ),
        now(),
        now()
      );

      v_inserted := v_inserted + 1;
    elsif exists (
      select 1
      from public.registry_track_artists track_artist
      where track_artist.id = v_existing_id
        and track_artist.artist_id is not distinct from v_credit.artist_id
        and track_artist.artist_slug is not distinct from v_credit.artist_slug
        and track_artist.artist_name_text is not distinct from v_credit.artist_name
        and track_artist.role = v_expected_role
        and track_artist.is_primary = v_expected_primary
        and track_artist.is_featured = v_expected_featured
        and track_artist.credit_order = v_credit.credit_order
        and track_artist.display_credit is not distinct from v_credit.artist_name
        and track_artist.status = 'active'
    ) then
      v_unchanged := v_unchanged + 1;
    else
      update public.registry_track_artists track_artist
      set
        artist_id = v_credit.artist_id,
        artist_slug = v_credit.artist_slug,
        artist_name_text = v_credit.artist_name,
        role = v_expected_role,
        is_primary = v_expected_primary,
        is_featured = v_expected_featured,
        credit_order = v_credit.credit_order,
        display_credit = v_credit.artist_name,
        source = 'track_intake_review',
        confidence = 100,
        status = 'active',
        metadata =
          coalesce(track_artist.metadata, '{}'::jsonb)
          || jsonb_build_object(
            'source_suggestion_id', p_suggestion_id::text,
            'source_credit_id', v_credit.source_credit_id::text,
            'observed_name', v_credit.observed_name,
            'sync_contract', 'phase5b_registry_artist_credit_parity_v2'
          ),
        updated_at = now()
      where track_artist.id = v_existing_id;

      v_updated := v_updated + 1;
    end if;
  end loop;

  return jsonb_build_object(
    'suggestion_id', p_suggestion_id,
    'registry_track_id', p_registry_track_id,
    'reviewed_artist_credits', v_reviewed,
    'inserted_artist_credits', v_inserted,
    'updated_artist_credits', v_updated,
    'unchanged_artist_credits', v_unchanged
  );
end;
$$;


ALTER FUNCTION "public"."sync_registry_track_intake_artist_credits"("p_suggestion_id" "uuid", "p_registry_track_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."track_analytics_event"("p_event_name" "text", "p_page_url" "text", "p_page_type" "text" DEFAULT NULL::"text", "p_entity_slug" "text" DEFAULT NULL::"text", "p_entity_type" "text" DEFAULT NULL::"text", "p_context" "jsonb" DEFAULT '{}'::"jsonb", "p_session_id" "text" DEFAULT NULL::"text", "p_user_id" "uuid" DEFAULT NULL::"uuid", "p_referrer" "text" DEFAULT NULL::"text") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_id BIGINT;
BEGIN
  INSERT INTO analytics_events (
    event_name, page_url, page_type, entity_slug, entity_type,
    context, session_id, user_id, referrer
  ) VALUES (
    p_event_name, p_page_url, p_page_type, p_entity_slug, p_entity_type,
    p_context, p_session_id, p_user_id, p_referrer
  ) RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."track_analytics_event"("p_event_name" "text", "p_page_url" "text", "p_page_type" "text", "p_entity_slug" "text", "p_entity_type" "text", "p_context" "jsonb", "p_session_id" "text", "p_user_id" "uuid", "p_referrer" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."triage_correction_case"("p_case_resource_id" "uuid", "p_expected_case_revision" bigint, "p_correction_kind" "text", "p_priority" "text", "p_target_resource_id" "uuid", "p_target_version_id" "uuid", "p_target_summary" "text", "p_reason" "text", "p_idempotency_key" "text", "p_correlation_id" "uuid") RETURNS TABLE("command_receipt_id" "uuid", "receipt_status" "text", "case_resource_id" "uuid", "case_revision" bigint, "result_payload" "jsonb", "idempotent_replay" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'editorial', 'platform_private'
    AS $$
declare
  v_actor uuid;
  v_begin record;
  v_case editorial.correction_cases%rowtype;
  v_target_id uuid;
  v_result jsonb;
begin
  v_actor :=
    platform_private.assert_correction_capability(
      'triage_corrections'
    );

  if p_case_resource_id is null
     or p_expected_case_revision < 1
     or p_target_resource_id is null
     or p_target_version_id is null
     or p_correlation_id is null
     or p_priority not in (
       'low',
       'normal',
       'high',
       'urgent'
     )
     or nullif(btrim(p_reason), '') is null
  then
    raise exception
      using errcode = '22023',
      message = 'Case, revision, target, priority, reason, and correlation identity are required.';
  end if;

  if not exists (
    select 1
    from editorial.correction_kinds kind
    where kind.correction_kind = p_correction_kind
      and kind.enabled
  ) then
    raise exception
      using errcode = '22023',
      message = 'The correction kind is not enabled.';
  end if;

  select *
  into v_begin
  from platform_private.begin_resource_command(
    'correction.case.triage',
    p_case_resource_id,
    p_idempotency_key,
    jsonb_build_object(
      'expected_case_revision', p_expected_case_revision,
      'correction_kind', p_correction_kind,
      'priority', p_priority,
      'target_resource_id', p_target_resource_id,
      'target_version_id', p_target_version_id,
      'target_summary', nullif(btrim(p_target_summary), ''),
      'reason', btrim(p_reason),
      'correlation_id', p_correlation_id
    )
  );

  if v_begin.idempotent_replay then
    return query
    select *
    from platform_private.read_correction_command_result(
      v_begin.command_receipt_id,
      true
    );
    return;
  end if;

  select correction_case.*
  into v_case
  from editorial.correction_cases correction_case
  where correction_case.resource_id =
    p_case_resource_id
  for update;

  if not found then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'case_not_found',
      'The correction case does not exist.',
      jsonb_build_object(
        'case_revision', null
      )
    );

    return query
    select *
    from platform_private.read_correction_command_result(
      v_begin.command_receipt_id,
      false
    );
    return;
  end if;

  if v_case.current_revision <>
     p_expected_case_revision
  then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'case_revision_changed',
      'The correction case revision changed.',
      jsonb_build_object(
        'case_revision', v_case.current_revision,
        'case_state', v_case.case_state
      )
    );

    return query
    select *
    from platform_private.read_correction_command_result(
      v_begin.command_receipt_id,
      false
    );
    return;
  end if;

  if v_case.case_state <> 'submitted' then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'invalid_transition',
      'Only submitted correction cases may be triaged.',
      jsonb_build_object(
        'case_revision', v_case.current_revision,
        'case_state', v_case.case_state
      )
    );

    return query
    select *
    from platform_private.read_correction_command_result(
      v_begin.command_receipt_id,
      false
    );
    return;
  end if;

  if not exists (
    select 1
    from editorial.resources resource
    join editorial.article_versions version
      on version.id = p_target_version_id
     and version.resource_id =
       p_target_resource_id
    where resource.id = p_target_resource_id
      and resource.resource_kind = 'article'
      and resource.current_published_version_id =
        p_target_version_id
  ) then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'target_changed',
      'The primary target must identify the current published Article version.',
      jsonb_build_object(
        'case_revision', v_case.current_revision,
        'case_state', v_case.case_state
      )
    );

    return query
    select *
    from platform_private.read_correction_command_result(
      v_begin.command_receipt_id,
      false
    );
    return;
  end if;

  update editorial.correction_cases
  set
    correction_kind = p_correction_kind,
    priority = p_priority,
    case_state = 'triaged',
    current_revision =
      v_case.current_revision + 1,
    triage_reason = btrim(p_reason),
    triaged_by = v_actor,
    triaged_at = now(),
    updated_by = v_actor,
    updated_at = now()
  where resource_id = p_case_resource_id;

  insert into editorial.correction_targets (
    case_resource_id,
    target_resource_id,
    target_resource_kind,
    target_version_type,
    target_version_id,
    target_role,
    target_summary,
    created_by
  )
  values (
    p_case_resource_id,
    p_target_resource_id,
    'article',
    'article_version',
    p_target_version_id,
    'primary',
    nullif(btrim(p_target_summary), ''),
    v_actor
  )
  returning id
  into v_target_id;

  perform platform_private.append_correction_event(
    p_case_resource_id,
    'case_triaged',
    v_case.current_revision,
    v_case.current_revision + 1,
    v_case.case_state,
    'triaged',
    v_actor,
    btrim(p_reason),
    null,
    v_target_id,
    null,
    null,
    v_begin.command_receipt_id,
    p_correlation_id,
    jsonb_build_object(
      'correction_kind', p_correction_kind,
      'priority', p_priority
    )
  );

  perform platform_private.append_correction_event(
    p_case_resource_id,
    'target_attached',
    v_case.current_revision,
    v_case.current_revision + 1,
    v_case.case_state,
    'triaged',
    v_actor,
    btrim(p_reason),
    null,
    v_target_id,
    null,
    null,
    v_begin.command_receipt_id,
    p_correlation_id,
    jsonb_build_object(
      'target_resource_id', p_target_resource_id,
      'target_resource_kind', 'article',
      'target_version_type', 'article_version',
      'target_version_id', p_target_version_id,
      'target_role', 'primary'
    )
  );

  v_result := jsonb_build_object(
    'case_resource_id', p_case_resource_id,
    'case_revision', v_case.current_revision + 1,
    'case_state', 'triaged',
    'target_id', v_target_id
  );

  perform platform_private.complete_resource_command(
    v_begin.command_receipt_id,
    v_result
  );

  return query
  select *
  from platform_private.read_correction_command_result(
    v_begin.command_receipt_id,
    false
  );
end;
$$;


ALTER FUNCTION "public"."triage_correction_case"("p_case_resource_id" "uuid", "p_expected_case_revision" bigint, "p_correction_kind" "text", "p_priority" "text", "p_target_resource_id" "uuid", "p_target_version_id" "uuid", "p_target_summary" "text", "p_reason" "text", "p_idempotency_key" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."unlink_correction_evidence"("p_case_resource_id" "uuid", "p_expected_case_revision" bigint, "p_evidence_link_id" "uuid", "p_reason" "text", "p_idempotency_key" "text", "p_correlation_id" "uuid") RETURNS TABLE("command_receipt_id" "uuid", "receipt_status" "text", "case_resource_id" "uuid", "case_revision" bigint, "result_payload" "jsonb", "idempotent_replay" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'editorial', 'platform_private'
    AS $$
declare
  v_actor uuid;
  v_begin record;
  v_case editorial.correction_cases%rowtype;
  v_link editorial.correction_evidence_links%rowtype;
  v_result jsonb;
begin
  v_actor :=
    platform_private.assert_correction_capability(
      'investigate_corrections'
    );

  if p_case_resource_id is null
     or p_expected_case_revision < 1
     or p_evidence_link_id is null
     or p_correlation_id is null
     or nullif(btrim(p_reason), '') is null
  then
    raise exception
      using errcode = '22023',
      message = 'Case, revision, evidence link, reason, and correlation identity are required.';
  end if;

  select *
  into v_begin
  from platform_private.begin_resource_command(
    'correction.evidence.unlink',
    p_case_resource_id,
    p_idempotency_key,
    jsonb_build_object(
      'expected_case_revision', p_expected_case_revision,
      'evidence_link_id', p_evidence_link_id,
      'reason', btrim(p_reason),
      'correlation_id', p_correlation_id
    )
  );

  if v_begin.idempotent_replay then
    return query
    select *
    from platform_private.read_correction_command_result(
      v_begin.command_receipt_id,
      true
    );
    return;
  end if;

  select correction_case.*
  into v_case
  from editorial.correction_cases correction_case
  where correction_case.resource_id =
    p_case_resource_id
  for update;

  if not found then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'case_not_found',
      'The correction case does not exist.',
      jsonb_build_object('case_revision', null)
    );
  elsif v_case.current_revision <>
        p_expected_case_revision
  then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'case_revision_changed',
      'The correction case revision changed.',
      jsonb_build_object(
        'case_revision', v_case.current_revision,
        'case_state', v_case.case_state
      )
    );
  elsif v_case.case_state <> 'investigating' then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'invalid_transition',
      'Evidence may be unlinked only while the case is investigating.',
      jsonb_build_object(
        'case_revision', v_case.current_revision,
        'case_state', v_case.case_state
      )
    );
  else
    select evidence.*
    into v_link
    from editorial.correction_evidence_links evidence
    where evidence.id = p_evidence_link_id
      and evidence.case_resource_id =
        p_case_resource_id
    for update;

    if not found then
      perform platform_private.reject_resource_command(
        v_begin.command_receipt_id,
        'evidence_link_not_found',
        'The correction evidence link does not exist.',
        jsonb_build_object(
          'case_revision', v_case.current_revision,
          'case_state', v_case.case_state
        )
      );
    else
      delete from editorial.correction_evidence_links
      where id = p_evidence_link_id;

      update editorial.correction_cases
      set
        current_revision =
          v_case.current_revision + 1,
        updated_by = v_actor,
        updated_at = now()
      where resource_id = p_case_resource_id;

      perform platform_private.append_correction_event(
        p_case_resource_id,
        'evidence_unlinked',
        v_case.current_revision,
        v_case.current_revision + 1,
        v_case.case_state,
        v_case.case_state,
        v_actor,
        btrim(p_reason),
        null,
        null,
        v_link.id,
        null,
        v_begin.command_receipt_id,
        p_correlation_id,
        jsonb_build_object(
          'evidence_link_id', v_link.id,
          'case_resource_id', v_link.case_resource_id,
          'source_id', v_link.source_id,
          'source_version_id', v_link.source_version_id,
          'citation_id', v_link.citation_id,
          'evidence_role', v_link.evidence_role,
          'link_created_by', v_link.created_by,
          'link_created_at', v_link.created_at,
          'unlinking_actor_id', v_actor,
          'unlink_reason', btrim(p_reason),
          'command_receipt_id',
          v_begin.command_receipt_id,
          'correlation_id', p_correlation_id
        )
      );

      v_result := jsonb_build_object(
        'case_resource_id', p_case_resource_id,
        'case_revision', v_case.current_revision + 1,
        'case_state', v_case.case_state,
        'evidence_link_id', v_link.id
      );

      perform platform_private.complete_resource_command(
        v_begin.command_receipt_id,
        v_result
      );
    end if;
  end if;

  return query
  select *
  from platform_private.read_correction_command_result(
    v_begin.command_receipt_id,
    false
  );
end;
$$;


ALTER FUNCTION "public"."unlink_correction_evidence"("p_case_resource_id" "uuid", "p_expected_case_revision" bigint, "p_evidence_link_id" "uuid", "p_reason" "text", "p_idempotency_key" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."unlink_person_identity"("p_person_resource_id" "uuid", "p_expected_identity_revision" bigint, "p_identity_link_id" "uuid", "p_reason" "text", "p_idempotency_key" "text", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("command_receipt_id" "uuid", "receipt_status" "text", "person_resource_id" "uuid", "identity_revision" bigint, "identity_link_id" "uuid", "result_payload" "jsonb", "idempotent_replay" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'editorial', 'platform_private'
    AS $$
declare
  v_actor_id uuid;
  v_person editorial.people%rowtype;
  v_link editorial.person_identity_links%rowtype;
  v_begin record;
  v_read record;
  v_request jsonb;
  v_result jsonb;
  v_correlation_id uuid;
  v_prior_revision bigint;
begin
  if p_person_resource_id is null
     or p_expected_identity_revision is null
     or p_expected_identity_revision < 1
     or p_identity_link_id is null
     or nullif(
          btrim(
            coalesce(
              p_reason,
              ''
            )
          ),
          ''
        ) is null
  then
    raise exception
      using
        errcode = '22023',
        message =
          'Valid Person, expected revision, identity link, and reason are required.';
  end if;

  if coalesce(
       auth.role(),
       ''
     ) <> 'authenticated'
     or auth.uid() is null
     or not public.current_user_has_capability(
       'manage_people_identity'
     )
  then
    raise exception
      using
        errcode = '42501',
        message =
          'People identity management permission is required.';
  end if;

  v_actor_id :=
    auth.uid();

  select person.*
  into v_person
  from editorial.people person
  where person.resource_id =
        p_person_resource_id
  for update;

  if not exists (
    select 1
    from editorial.resources resource
    where resource.id =
          p_person_resource_id
  ) then
    raise exception
      using
        errcode = 'P0002',
        message =
          'The Person Resource does not exist.';
  end if;

  v_request :=
    jsonb_build_object(
      'person_resource_id',
        p_person_resource_id,
      'expected_identity_revision',
        p_expected_identity_revision,
      'identity_link_id',
        p_identity_link_id,
      'reason',
        p_reason,
      'correlation_id',
        p_correlation_id
    );

  select *
  into v_begin
  from platform_private.begin_authenticated_resource_command(
    'person.identity_unlink',
    p_person_resource_id,
    p_idempotency_key,
    v_request
  );

  if v_begin.idempotent_replay then
    select *
    into v_read
    from platform_private.read_authenticated_resource_command_result(
      v_begin.command_receipt_id,
      true
    );

    command_receipt_id :=
      v_read.command_receipt_id;
    receipt_status :=
      v_read.receipt_status;
    person_resource_id :=
      p_person_resource_id;
    identity_revision :=
      nullif(
        v_read.result_payload
          ->> 'identity_revision',
        ''
      )::bigint;
    identity_link_id :=
      p_identity_link_id;
    result_payload :=
      v_read.result_payload;
    idempotent_replay :=
      true;
    return next;
    return;
  end if;

  v_correlation_id :=
    coalesce(
      p_correlation_id,
      gen_random_uuid()
    );

  if v_person.resource_id is null then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'person_not_found',
      'The Person does not exist.',
      jsonb_build_object(
        'person_resource_id',
          p_person_resource_id,
        'identity_revision',
          null,
        'identity_link_id',
          p_identity_link_id
      )
    );

  elsif v_person.person_state <> 'active' then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'person_not_active',
      'Only an active Person may unlink an identity.',
      jsonb_build_object(
        'person_resource_id',
          p_person_resource_id,
        'identity_revision',
          v_person.identity_revision,
        'identity_link_id',
          p_identity_link_id,
        'person_state',
          v_person.person_state
      )
    );

  elsif v_person.identity_revision <>
        p_expected_identity_revision
  then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'person_identity_revision_changed',
      'The Person identity changed before this unlink could be applied.',
      jsonb_build_object(
        'person_resource_id',
          p_person_resource_id,
        'identity_revision',
          v_person.identity_revision,
        'identity_link_id',
          p_identity_link_id
      )
    );

  else
    select link.*
    into v_link
    from editorial.person_identity_links link
    where link.id =
          p_identity_link_id
      and link.person_resource_id =
          p_person_resource_id
    for update;

    if v_link.id is null then
      perform platform_private.reject_resource_command(
        v_begin.command_receipt_id,
        'person_identity_link_not_found',
        'The Person identity link does not exist.',
        jsonb_build_object(
          'person_resource_id',
            p_person_resource_id,
          'identity_revision',
            v_person.identity_revision,
          'identity_link_id',
            p_identity_link_id
        )
      );

    elsif v_link.link_state <> 'active' then
      perform platform_private.reject_resource_command(
        v_begin.command_receipt_id,
        'person_identity_link_not_active',
        'Only an active Person identity link may be unlinked.',
        jsonb_build_object(
          'person_resource_id',
            p_person_resource_id,
          'identity_revision',
            v_person.identity_revision,
          'identity_link_id',
            p_identity_link_id,
          'link_state',
            v_link.link_state
        )
      );

    else
      v_prior_revision :=
        v_person.identity_revision;

      update editorial.people person
      set
        preferred_identity_link_id =
          case
            when person.preferred_identity_link_id =
                 p_identity_link_id
              then null
            else person.preferred_identity_link_id
          end,
        identity_revision =
          person.identity_revision + 1,
        updated_by =
          v_actor_id,
        updated_at =
          now()
      where person.resource_id =
            p_person_resource_id
      returning person.*
      into v_person;

      update editorial.person_identity_links link
      set
        link_state =
          'retired',
        retired_by =
          v_actor_id,
        retired_at =
          now(),
        retired_reason =
          p_reason
      where link.id =
            p_identity_link_id;

      insert into editorial.person_identity_events (
        person_resource_id,
        actor_id,
        event_type,
        identity_link_id,
        prior_identity_revision,
        resulting_identity_revision,
        reason,
        correlation_id
      )
      values (
        p_person_resource_id,
        v_actor_id,
        'identity_unlinked',
        p_identity_link_id,
        v_prior_revision,
        v_person.identity_revision,
        p_reason,
        v_correlation_id
      );

      perform editorial.refresh_person_visibility(
        p_person_resource_id
      );

      v_result :=
        jsonb_build_object(
          'person_resource_id',
            p_person_resource_id,
          'identity_revision',
            v_person.identity_revision,
          'identity_link_id',
            p_identity_link_id,
          'changed',
            true,
          'correlation_id',
            v_correlation_id
        );

      perform platform_private.complete_resource_command(
        v_begin.command_receipt_id,
        v_result
      );
    end if;
  end if;

  select *
  into v_read
  from platform_private.read_authenticated_resource_command_result(
    v_begin.command_receipt_id,
    false
  );

  command_receipt_id :=
    v_read.command_receipt_id;
  receipt_status :=
    v_read.receipt_status;
  person_resource_id :=
    p_person_resource_id;
  identity_revision :=
    nullif(
      v_read.result_payload
        ->> 'identity_revision',
      ''
    )::bigint;
  identity_link_id :=
    p_identity_link_id;
  result_payload :=
    v_read.result_payload;
  idempotent_replay :=
    false;
  return next;
end;
$$;


ALTER FUNCTION "public"."unlink_person_identity"("p_person_resource_id" "uuid", "p_expected_identity_revision" bigint, "p_identity_link_id" "uuid", "p_reason" "text", "p_idempotency_key" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."unpublish_article"("p_article_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS TABLE("article_id" "uuid", "article_slug" "text", "draft_version" bigint, "version_id" "uuid", "version_number" bigint, "lifecycle_status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_article public.wk_articles%rowtype;
  v_resource editorial.resources%rowtype;
  v_prior_status text;
  v_target_version_id uuid;
  v_target_number bigint;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  if not editorial.current_user_can_publish_article() then
    raise exception 'Permission denied';
  end if;

  select article.*
  into v_article
  from public.wk_articles article
  where article.id = p_article_id
  for update;

  if not found then
    raise exception 'Article not found';
  end if;

  select resource.*
  into v_resource
  from editorial.article_resources binding
  join editorial.resources resource
    on resource.id = binding.resource_id
  where binding.article_id = p_article_id
  for update of resource;

  if not found then
    raise exception 'Article resource identity not found';
  end if;

  v_prior_status := v_article.wp_status;
  v_target_version_id :=
    coalesce(
      v_resource.current_published_version_id,
      v_resource.current_working_version_id
    );

  select version.version_number
  into v_target_number
  from editorial.article_versions version
  where version.id = v_target_version_id;

  update public.wk_article_publication_snapshots snapshot
  set
    is_active = false,
    updated_at = now()
  where snapshot.article_id = p_article_id
    and snapshot.is_active = true;

  update public.wk_articles as article
  set
    wp_status = 'draft',
    draft_version = article.draft_version + 1,
    updated_at = now(),
    modified_at = now()
  where article.id = p_article_id
  returning article.*
  into v_article;

  update editorial.resources
  set
    lifecycle_state = 'draft',
    visibility = 'private',
    updated_at = now()
  where id = v_resource.id;

  insert into editorial.article_lifecycle_events (
    resource_id,
    article_id,
    version_id,
    action,
    prior_status,
    resulting_status,
    note
  )
  values (
    v_resource.id,
    p_article_id,
    v_target_version_id,
    'unpublished',
    v_prior_status,
    'draft',
    p_note
  );

  article_id := p_article_id;
  article_slug := v_article.slug;
  draft_version := v_article.draft_version;
  version_id := v_target_version_id;
  version_number := coalesce(v_target_number, 0);
  lifecycle_status := 'unpublished';
  return next;
end;
$$;


ALTER FUNCTION "public"."unpublish_article"("p_article_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."unpublish_playlist"("p_playlist_id" "uuid", "p_expected_authority_revision" bigint, "p_idempotency_key" "text", "p_note" "text" DEFAULT NULL::"text", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("command_receipt_id" "uuid", "receipt_status" "text", "playlist_id" "uuid", "resource_id" "uuid", "authority_revision" bigint, "version_id" "uuid", "version_number" bigint, "lifecycle_status" "text", "result_payload" "jsonb", "idempotent_replay" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'editorial', 'platform_private'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_playlist public.wk_playlists%rowtype;
  v_binding editorial.playlist_resources%rowtype;
  v_published editorial.playlist_versions%rowtype;
  v_approved editorial.playlist_versions%rowtype;
  v_current_fingerprint text;
  v_prior_status text;
  v_result_status text;
  v_begin record;
  v_read record;
  v_result jsonb;
  v_correlation_id uuid :=
    coalesce(
      p_correlation_id,
      gen_random_uuid()
    );
begin
  if v_actor is null then
    raise exception 'Not authenticated';
  end if;

  select playlist.*
  into v_playlist
  from public.wk_playlists playlist
  where playlist.id = p_playlist_id
  for update;

  if not found then
    raise exception 'Playlist does not exist';
  end if;

  v_prior_status := v_playlist.status;

  select binding.*
  into v_binding
  from editorial.playlist_resources binding
  where binding.playlist_id = p_playlist_id
  for update;

  if not found then
    raise exception
      'Playlist Resource binding does not exist';
  end if;

  if not editorial.current_user_can_publish_playlist(
    v_binding.resource_id
  ) then
    raise exception
      'Playlist publication permission is required';
  end if;

  if v_binding.current_published_version_id
       is not null
  then
    select version.*
    into v_published
    from editorial.playlist_versions version
    where version.id =
      v_binding.current_published_version_id;
  end if;

  if v_binding.current_approved_version_id
       is not null
  then
    select version.*
    into v_approved
    from editorial.playlist_versions version
    where version.id =
      v_binding.current_approved_version_id;
  end if;

  select *
  into v_begin
  from platform_private.begin_authenticated_resource_command(
    'playlist.unpublish',
    v_binding.resource_id,
    p_idempotency_key,
    jsonb_build_object(
      'playlist_id',
        p_playlist_id,
      'expected_authority_revision',
        p_expected_authority_revision,
      'published_version_id',
        v_binding.current_published_version_id,
      'note',
        nullif(btrim(p_note), ''),
      'correlation_id',
        v_correlation_id
    )
  );

  if v_begin.idempotent_replay then
    select *
    into v_read
    from platform_private.read_authenticated_resource_command_result(
      v_begin.command_receipt_id,
      true
    );

    command_receipt_id := v_read.command_receipt_id;
    receipt_status := v_read.receipt_status;
    playlist_id := p_playlist_id;
    resource_id := v_read.resource_id;
    authority_revision :=
      nullif(
        v_read.result_payload ->> 'authority_revision',
        ''
      )::bigint;
    version_id :=
      nullif(
        v_read.result_payload ->> 'version_id',
        ''
      )::uuid;
    version_number :=
      nullif(
        v_read.result_payload ->> 'version_number',
        ''
      )::bigint;
    lifecycle_status :=
      v_read.result_payload ->> 'lifecycle_status';
    result_payload := v_read.result_payload;
    idempotent_replay := true;
    return next;
    return;
  end if;

  if p_expected_authority_revision is null
     or p_expected_authority_revision < 1
     or v_playlist.authority_revision <>
          p_expected_authority_revision
  then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'playlist_revision_changed',
      'The Playlist changed before it could be unpublished.',
      jsonb_build_object(
        'playlist_id',
          p_playlist_id,
        'authority_revision',
          v_playlist.authority_revision
      )
    );

  elsif v_binding.current_published_version_id is null
  then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'playlist_not_published',
      'This Playlist does not have a public version to unpublish.',
      jsonb_build_object(
        'playlist_id',
          p_playlist_id,
        'lifecycle_status',
          v_playlist.status
      )
    );

  else
    v_current_fingerprint :=
      editorial.playlist_current_content_fingerprint(
        p_playlist_id
      );

    v_result_status :=
      case
        when v_approved.id is not null
         and v_current_fingerprint =
               v_approved.content_fingerprint
          then 'approved'
        else 'draft'
      end;

    if v_result_status = 'draft' then
      update editorial.playlist_resources as binding
      set current_approved_version_id = null
      where binding.playlist_id = p_playlist_id;
    end if;

    update editorial.playlist_resources as binding
    set current_published_version_id = null
    where binding.playlist_id = p_playlist_id;

    update editorial.resources resource
    set
      lifecycle_state =
        case
          when v_result_status = 'approved'
            then 'active'
          else 'draft'
        end,
      visibility = 'private',
      updated_at = now()
    where resource.id =
            v_binding.resource_id;

    update public.wk_playlists playlist
    set
      status = v_result_status,
      authority_revision =
        playlist.authority_revision + 1,
      updated_at = now()
    where playlist.id = p_playlist_id
    returning playlist.*
    into v_playlist;

    perform editorial.append_playlist_lifecycle_event(
      v_binding.resource_id,
      p_playlist_id,
      v_published.id,
      'unpublished',
      v_prior_status,
      v_result_status,
      p_note,
      v_actor,
      v_begin.command_receipt_id,
      jsonb_build_object(
        'correlation_id',
          v_correlation_id
      )
    );

    v_result := jsonb_build_object(
      'playlist_id',
        p_playlist_id,
      'resource_id',
        v_binding.resource_id,
      'authority_revision',
        v_playlist.authority_revision,
      'version_id',
        v_published.id,
      'version_number',
        v_published.version_number,
      'lifecycle_status',
        v_result_status,
      'correlation_id',
        v_correlation_id
    );

    perform platform_private.complete_resource_command(
      v_begin.command_receipt_id,
      v_result
    );
  end if;

  select *
  into v_read
  from platform_private.read_authenticated_resource_command_result(
    v_begin.command_receipt_id,
    false
  );

  command_receipt_id := v_read.command_receipt_id;
  receipt_status := v_read.receipt_status;
  playlist_id := p_playlist_id;
  resource_id := v_read.resource_id;
  authority_revision :=
    nullif(
      v_read.result_payload ->> 'authority_revision',
      ''
    )::bigint;
  version_id :=
    nullif(
      v_read.result_payload ->> 'version_id',
      ''
    )::uuid;
  version_number :=
    nullif(
      v_read.result_payload ->> 'version_number',
      ''
    )::bigint;
  lifecycle_status :=
    v_read.result_payload ->> 'lifecycle_status';
  result_payload := v_read.result_payload;
  idempotent_replay := false;
  return next;
end;
$$;


ALTER FUNCTION "public"."unpublish_playlist"("p_playlist_id" "uuid", "p_expected_authority_revision" bigint, "p_idempotency_key" "text", "p_note" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."unschedule_playlist_publication"("p_playlist_id" "uuid", "p_expected_authority_revision" bigint, "p_idempotency_key" "text", "p_note" "text" DEFAULT NULL::"text", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("command_receipt_id" "uuid", "receipt_status" "text", "playlist_id" "uuid", "resource_id" "uuid", "authority_revision" bigint, "version_id" "uuid", "version_number" bigint, "lifecycle_status" "text", "result_payload" "jsonb", "idempotent_replay" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'editorial', 'platform_private'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_playlist public.wk_playlists%rowtype;
  v_binding editorial.playlist_resources%rowtype;
  v_schedule editorial.playlist_scheduled_publications%rowtype;
  v_scheduled_version editorial.playlist_versions%rowtype;
  v_current_fingerprint text;
  v_result_status text;
  v_begin record;
  v_read record;
  v_result jsonb;
  v_correlation_id uuid :=
    coalesce(
      p_correlation_id,
      gen_random_uuid()
    );
begin
  if v_actor is null then
    raise exception 'Not authenticated';
  end if;

  select playlist.*
  into v_playlist
  from public.wk_playlists playlist
  where playlist.id = p_playlist_id
  for update;

  if not found then
    raise exception 'Playlist does not exist';
  end if;

  select binding.*
  into v_binding
  from editorial.playlist_resources binding
  where binding.playlist_id = p_playlist_id
  for update;

  if not found then
    raise exception
      'Playlist Resource binding does not exist';
  end if;

  if not editorial.current_user_can_publish_playlist(
    v_binding.resource_id
  ) then
    raise exception
      'Playlist publication permission is required';
  end if;

  select scheduled.*
  into v_schedule
  from editorial.playlist_scheduled_publications scheduled
  where scheduled.playlist_id = p_playlist_id
    and scheduled.status = 'scheduled'
  order by scheduled.created_at desc
  limit 1
  for update;

  select *
  into v_begin
  from platform_private.begin_authenticated_resource_command(
    'playlist.unschedule',
    v_binding.resource_id,
    p_idempotency_key,
    jsonb_build_object(
      'playlist_id',
        p_playlist_id,
      'expected_authority_revision',
        p_expected_authority_revision,
      'scheduled_publication_id',
        v_schedule.id,
      'note',
        nullif(btrim(p_note), ''),
      'correlation_id',
        v_correlation_id
    )
  );

  if v_begin.idempotent_replay then
    select *
    into v_read
    from platform_private.read_authenticated_resource_command_result(
      v_begin.command_receipt_id,
      true
    );

    command_receipt_id := v_read.command_receipt_id;
    receipt_status := v_read.receipt_status;
    playlist_id := p_playlist_id;
    resource_id := v_read.resource_id;
    authority_revision :=
      nullif(
        v_read.result_payload ->> 'authority_revision',
        ''
      )::bigint;
    version_id :=
      nullif(
        v_read.result_payload ->> 'version_id',
        ''
      )::uuid;
    version_number :=
      nullif(
        v_read.result_payload ->> 'version_number',
        ''
      )::bigint;
    lifecycle_status :=
      v_read.result_payload ->> 'lifecycle_status';
    result_payload := v_read.result_payload;
    idempotent_replay := true;
    return next;
    return;
  end if;

  if p_expected_authority_revision is null
     or p_expected_authority_revision < 1
     or v_playlist.authority_revision <>
          p_expected_authority_revision
  then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'playlist_revision_changed',
      'The Playlist changed before the schedule could be removed.',
      jsonb_build_object(
        'playlist_id',
          p_playlist_id,
        'authority_revision',
          v_playlist.authority_revision
      )
    );

  elsif v_schedule.id is null
        or v_playlist.status <> 'scheduled'
  then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'playlist_not_scheduled',
      'This Playlist does not have an active publication schedule.',
      jsonb_build_object(
        'playlist_id',
          p_playlist_id,
        'lifecycle_status',
          v_playlist.status
      )
    );

  else
    select version.*
    into v_scheduled_version
    from editorial.playlist_versions version
    where version.id = v_schedule.version_id
      and version.playlist_id = p_playlist_id
      and version.resource_id =
            v_binding.resource_id
      and version.version_kind = 'scheduled';

    if not found then
      perform platform_private.reject_resource_command(
        v_begin.command_receipt_id,
        'scheduled_version_invalid',
        'The scheduled Playlist version is no longer valid.',
        jsonb_build_object(
          'playlist_id',
            p_playlist_id,
          'scheduled_publication_id',
            v_schedule.id
        )
      );
    end if;

    if exists (
      select 1
      from platform_private.command_receipts receipt
      where receipt.id =
              v_begin.command_receipt_id
        and receipt.status = 'accepted'
    ) then
      v_current_fingerprint :=
        editorial.playlist_current_content_fingerprint(
          p_playlist_id
        );

      v_result_status :=
        case
          when v_current_fingerprint =
               v_scheduled_version.content_fingerprint
            then 'approved'
          else 'draft'
        end;

      update editorial.playlist_scheduled_publications as scheduled
      set
        status = 'cancelled',
        updated_at = now()
      where scheduled.id = v_schedule.id;

      if v_result_status = 'draft' then
        update editorial.playlist_resources as binding
        set current_approved_version_id = null
        where binding.playlist_id = p_playlist_id;
      end if;

      update public.wk_playlists playlist
      set
        status = v_result_status,
        authority_revision =
          playlist.authority_revision + 1
      where playlist.id = p_playlist_id
      returning playlist.*
      into v_playlist;

      perform editorial.append_playlist_lifecycle_event(
        v_binding.resource_id,
        p_playlist_id,
        v_scheduled_version.id,
        'unscheduled',
        'scheduled',
        v_result_status,
        p_note,
        v_actor,
        v_begin.command_receipt_id,
        jsonb_build_object(
          'scheduled_publication_id',
            v_schedule.id,
          'content_still_matches_approved',
            v_result_status = 'approved',
          'correlation_id',
            v_correlation_id
        )
      );

      v_result := jsonb_build_object(
        'playlist_id',
          p_playlist_id,
        'resource_id',
          v_binding.resource_id,
        'authority_revision',
          v_playlist.authority_revision,
        'version_id',
          v_scheduled_version.id,
        'version_number',
          v_scheduled_version.version_number,
        'scheduled_publication_id',
          v_schedule.id,
        'lifecycle_status',
          v_result_status,
        'correlation_id',
          v_correlation_id
      );

      perform platform_private.complete_resource_command(
        v_begin.command_receipt_id,
        v_result
      );
    end if;
  end if;

  select *
  into v_read
  from platform_private.read_authenticated_resource_command_result(
    v_begin.command_receipt_id,
    false
  );

  command_receipt_id := v_read.command_receipt_id;
  receipt_status := v_read.receipt_status;
  playlist_id := p_playlist_id;
  resource_id := v_read.resource_id;
  authority_revision :=
    nullif(
      v_read.result_payload ->> 'authority_revision',
      ''
    )::bigint;
  version_id :=
    nullif(
      v_read.result_payload ->> 'version_id',
      ''
    )::uuid;
  version_number :=
    nullif(
      v_read.result_payload ->> 'version_number',
      ''
    )::bigint;
  lifecycle_status :=
    v_read.result_payload ->> 'lifecycle_status';
  result_payload := v_read.result_payload;
  idempotent_replay := false;
  return next;
end;
$$;


ALTER FUNCTION "public"."unschedule_playlist_publication"("p_playlist_id" "uuid", "p_expected_authority_revision" bigint, "p_idempotency_key" "text", "p_note" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_article"("article_id" "uuid", "payload" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "row_security" TO 'off'
    AS $$
DECLARE
  v_user_id uuid;
BEGIN
  v_user_id := auth.uid();
  
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  
  -- Check for edit_own_articles capability OR administrator role (not admin-only!)
  IF NOT EXISTS (
    SELECT 1 FROM user_role_assignments ura
    JOIN role_capabilities rc ON rc.role_key = ura.role_key
    WHERE ura.user_id = v_user_id
      AND ura.status = 'active'
      AND (ura.expires_at IS NULL OR ura.expires_at > now())
      AND rc.capability_key = 'edit_own_articles'
  ) AND NOT EXISTS (
    SELECT 1 FROM user_role_assignments
    WHERE user_id = v_user_id
      AND role_key = 'administrator'
      AND status = 'active'
      AND (expires_at IS NULL OR expires_at > now())
  ) THEN
    RAISE EXCEPTION 'Permission required: edit_own_articles capability or administrator role';
  END IF;
  
  UPDATE wk_articles
  SET 
    title = CASE WHEN payload ? 'title' THEN payload->>'title' ELSE title END,
    excerpt = CASE WHEN payload ? 'excerpt' THEN payload->>'excerpt' ELSE excerpt END,
    content_html = CASE WHEN payload ? 'content_html' THEN payload->>'content_html' ELSE content_html END,
    author = CASE WHEN payload ? 'author' THEN payload->>'author' ELSE author END,
    categories = CASE WHEN payload ? 'categories' THEN (payload->>'categories')::jsonb ELSE categories END,
    tags = CASE WHEN payload ? 'tags' THEN (payload->>'tags')::jsonb ELSE tags END,
    published_at = CASE WHEN payload ? 'published_at' THEN (payload->>'published_at')::timestamptz ELSE published_at END,
    seo = CASE WHEN payload ? 'seo' THEN payload->'seo' ELSE seo END,
    wp_status = CASE WHEN payload ? 'wp_status' THEN payload->>'wp_status' ELSE wp_status END,
    hero_image_url = CASE WHEN payload ? 'hero_image_url' THEN payload->>'hero_image_url' ELSE hero_image_url END,
    slug = CASE WHEN payload ? 'slug' THEN payload->>'slug' ELSE slug END,
    updated_at = now()
  WHERE id = article_id;
END;
$$;


ALTER FUNCTION "public"."update_article"("article_id" "uuid", "payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_article"("article_id" "uuid", "payload" "jsonb", "expected_updated_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "row_security" TO 'off'
    AS $$
DECLARE
  v_user_id uuid;
  v_current_updated_at timestamptz;
BEGIN
  v_user_id := auth.uid();
  
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  
  -- Permission check: edit_own_articles capability OR administrator role
  IF NOT EXISTS (
    SELECT 1 FROM user_role_assignments ura
    JOIN role_capabilities rc ON rc.role_key = ura.role_key
    WHERE ura.user_id = v_user_id
      AND ura.status = 'active'
      AND (ura.expires_at IS NULL OR ura.expires_at > now())
      AND rc.capability_key = 'edit_own_articles'
  ) AND NOT EXISTS (
    SELECT 1 FROM user_role_assignments
    WHERE user_id = v_user_id
      AND role_key = 'administrator'
      AND status = 'active'
      AND (expires_at IS NULL OR expires_at > now())
  ) THEN
    RAISE EXCEPTION 'Permission required: edit_own_articles capability or administrator role';
  END IF;

  -- Optimistic locking: reject if someone else modified the article since we loaded it
  IF expected_updated_at IS NOT NULL THEN
    SELECT updated_at INTO v_current_updated_at
    FROM wk_articles
    WHERE id = article_id;

    IF v_current_updated_at IS DISTINCT FROM expected_updated_at THEN
      RAISE EXCEPTION 'STALE_UPDATE: This article was modified by another user or process since you opened it. Please reload the page to get the latest version, then re-apply your changes.';
    END IF;
  END IF;
  
  UPDATE wk_articles
  SET 
    title = CASE WHEN payload ? 'title' THEN payload->>'title' ELSE title END,
    excerpt = CASE WHEN payload ? 'excerpt' THEN payload->>'excerpt' ELSE excerpt END,
    content_html = CASE WHEN payload ? 'content_html' THEN payload->>'content_html' ELSE content_html END,
    author = CASE WHEN payload ? 'author' THEN payload->>'author' ELSE author END,
    categories = CASE WHEN payload ? 'categories' THEN (payload->>'categories')::jsonb ELSE categories END,
    tags = CASE WHEN payload ? 'tags' THEN (payload->>'tags')::jsonb ELSE tags END,
    published_at = CASE WHEN payload ? 'published_at' THEN (payload->>'published_at')::timestamptz ELSE published_at END,
    seo = CASE WHEN payload ? 'seo' THEN payload->'seo' ELSE seo END,
    wp_status = CASE WHEN payload ? 'wp_status' THEN payload->>'wp_status' ELSE wp_status END,
    hero_image_url = CASE WHEN payload ? 'hero_image_url' THEN payload->>'hero_image_url' ELSE hero_image_url END,
    slug = CASE WHEN payload ? 'slug' THEN payload->>'slug' ELSE slug END,
    updated_at = now()
  WHERE id = article_id;
END;
$$;


ALTER FUNCTION "public"."update_article"("article_id" "uuid", "payload" "jsonb", "expected_updated_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_article_hero_image"("article_id" "uuid", "hero_url" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "row_security" TO 'off'
    AS $$
DECLARE
  v_user_id uuid;
BEGIN
  v_user_id := auth.uid();
  
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  
  -- Verify admin role
  IF NOT EXISTS (
    SELECT 1 FROM user_role_assignments
    WHERE user_id = v_user_id
      AND role_key = 'administrator'
      AND status = 'active'
      AND (expires_at IS NULL OR expires_at > now())
  ) THEN
    RAISE EXCEPTION 'Admin permission required';
  END IF;
  
  UPDATE wk_articles
  SET hero_image_url = hero_url,
      updated_at = now()
  WHERE id = article_id;
END;
$$;


ALTER FUNCTION "public"."update_article_hero_image"("article_id" "uuid", "hero_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_correction_investigation"("p_case_resource_id" "uuid", "p_expected_case_revision" bigint, "p_investigation_summary" "text", "p_investigator_recommendation" "text", "p_evidence_ready" boolean, "p_reason" "text", "p_idempotency_key" "text", "p_correlation_id" "uuid") RETURNS TABLE("command_receipt_id" "uuid", "receipt_status" "text", "case_resource_id" "uuid", "case_revision" bigint, "result_payload" "jsonb", "idempotent_replay" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'editorial', 'platform_private'
    AS $$
declare
  v_actor uuid;
  v_begin record;
  v_case editorial.correction_cases%rowtype;
  v_result jsonb;
begin
  v_actor :=
    platform_private.assert_correction_capability(
      'investigate_corrections'
    );

  if p_case_resource_id is null
     or p_expected_case_revision < 1
     or p_correlation_id is null
     or nullif(btrim(p_reason), '') is null
     or length(coalesce(p_investigation_summary, '')) > 16000
     or length(coalesce(p_investigator_recommendation, '')) > 8000
  then
    raise exception
      using errcode = '22023',
      message = 'Case, revision, reason, and correlation identity are required.';
  end if;

  select *
  into v_begin
  from platform_private.begin_resource_command(
    'correction.investigation.update',
    p_case_resource_id,
    p_idempotency_key,
    jsonb_build_object(
      'expected_case_revision', p_expected_case_revision,
      'investigation_summary',
      nullif(btrim(p_investigation_summary), ''),
      'investigator_recommendation',
      nullif(btrim(p_investigator_recommendation), ''),
      'evidence_ready', p_evidence_ready,
      'reason', btrim(p_reason),
      'correlation_id', p_correlation_id
    )
  );

  if v_begin.idempotent_replay then
    return query
    select *
    from platform_private.read_correction_command_result(
      v_begin.command_receipt_id,
      true
    );
    return;
  end if;

  select correction_case.*
  into v_case
  from editorial.correction_cases correction_case
  where correction_case.resource_id =
    p_case_resource_id
  for update;

  if not found then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'case_not_found',
      'The correction case does not exist.',
      jsonb_build_object('case_revision', null)
    );
  elsif v_case.current_revision <>
        p_expected_case_revision
  then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'case_revision_changed',
      'The correction case revision changed.',
      jsonb_build_object(
        'case_revision', v_case.current_revision,
        'case_state', v_case.case_state
      )
    );
  elsif v_case.case_state <> 'investigating' then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'invalid_transition',
      'Investigation updates require an investigating case.',
      jsonb_build_object(
        'case_revision', v_case.current_revision,
        'case_state', v_case.case_state
      )
    );
  elsif p_evidence_ready
        and (
          nullif(btrim(p_investigation_summary), '')
            is null
          or nullif(
            btrim(p_investigator_recommendation),
            ''
          ) is null
          or not exists (
            select 1
            from editorial.correction_evidence_links evidence
            where evidence.case_resource_id =
              p_case_resource_id
          )
        )
  then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'investigation_incomplete',
      'Evidence-ready investigations require a summary and recommendation.',
      jsonb_build_object(
        'case_revision', v_case.current_revision,
        'case_state', v_case.case_state
      )
    );
  else
    update editorial.correction_cases
    set
      current_revision =
        v_case.current_revision + 1,
      investigation_summary =
        nullif(btrim(p_investigation_summary), ''),
      investigator_recommendation =
        nullif(
          btrim(p_investigator_recommendation),
          ''
        ),
      evidence_ready = p_evidence_ready,
      updated_by = v_actor,
      updated_at = now()
    where resource_id = p_case_resource_id;

    perform platform_private.append_correction_event(
      p_case_resource_id,
      'investigation_updated',
      v_case.current_revision,
      v_case.current_revision + 1,
      v_case.case_state,
      v_case.case_state,
      v_actor,
      btrim(p_reason),
      null,
      null,
      null,
      null,
      v_begin.command_receipt_id,
      p_correlation_id,
      jsonb_build_object(
        'evidence_ready', p_evidence_ready
      )
    );

    v_result := jsonb_build_object(
      'case_resource_id', p_case_resource_id,
      'case_revision', v_case.current_revision + 1,
      'case_state', v_case.case_state,
      'evidence_ready', p_evidence_ready
    );

    perform platform_private.complete_resource_command(
      v_begin.command_receipt_id,
      v_result
    );
  end if;

  return query
  select *
  from platform_private.read_correction_command_result(
    v_begin.command_receipt_id,
    false
  );
end;
$$;


ALTER FUNCTION "public"."update_correction_investigation"("p_case_resource_id" "uuid", "p_expected_case_revision" bigint, "p_investigation_summary" "text", "p_investigator_recommendation" "text", "p_evidence_ready" boolean, "p_reason" "text", "p_idempotency_key" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_external_contributor"("p_external_contributor_id" "uuid", "p_display_name" "text", "p_public_role" "text" DEFAULT NULL::"text", "p_public_url" "text" DEFAULT NULL::"text", "p_location_text" "text" DEFAULT NULL::"text", "p_contact_email" "text" DEFAULT NULL::"text", "p_contact_phone" "text" DEFAULT NULL::"text", "p_consent_status" "text" DEFAULT 'unknown'::"text", "p_public_safe" boolean DEFAULT false, "p_contributor_state" "text" DEFAULT 'active'::"text", "p_internal_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial', 'auth'
    AS $$
declare
  v_actor_id uuid;
  v_existing editorial.external_contributors%rowtype;
  v_consent_status text;
  v_contributor_state text;
  v_public_safe boolean;
begin
  v_actor_id :=
    editorial.assert_credit_command_actor();

  if nullif(btrim(p_display_name), '') is null then
    raise exception
      'External contributor display name is required';
  end if;

  v_consent_status :=
    coalesce(
      nullif(btrim(p_consent_status), ''),
      'unknown'
    );

  if v_consent_status not in (
    'unknown',
    'not_required',
    'requested',
    'granted',
    'limited',
    'declined',
    'withdrawn'
  ) then
    raise exception
      'Choose a supported contributor consent status';
  end if;

  v_contributor_state :=
    coalesce(
      nullif(btrim(p_contributor_state), ''),
      'active'
    );

  if v_contributor_state not in (
    'active',
    'withdrawn',
    'archived'
  ) then
    raise exception
      'Choose a supported contributor state';
  end if;

  v_public_safe := coalesce(p_public_safe, false);

  if v_public_safe
     and (
       v_contributor_state <> 'active'
       or v_consent_status not in (
            'granted',
            'not_required'
          )
     ) then
    raise exception
      'Public-safe contributors must be active with granted or not-required consent';
  end if;

  select *
  into v_existing
  from editorial.external_contributors contributor
  where contributor.id = p_external_contributor_id
  for update;

  if not found then
    raise exception
      'External contributor was not found';
  end if;

  update editorial.external_contributors
  set
    display_name = btrim(p_display_name),
    public_role = nullif(btrim(p_public_role), ''),
    public_url = nullif(btrim(p_public_url), ''),
    location_text = nullif(btrim(p_location_text), ''),
    contact_email = nullif(btrim(p_contact_email), ''),
    contact_phone = nullif(btrim(p_contact_phone), ''),
    consent_status = v_consent_status,
    public_safe = v_public_safe,
    contributor_state = v_contributor_state,
    internal_notes = nullif(btrim(p_internal_notes), ''),
    updated_by = v_actor_id,
    updated_at = now()
  where id = p_external_contributor_id;

  return jsonb_build_object(
    'external_contributor_id',
      p_external_contributor_id,
    'contributor_state',
      v_contributor_state,
    'consent_status',
      v_consent_status,
    'public_safe',
      v_public_safe
  );
end;
$$;


ALTER FUNCTION "public"."update_external_contributor"("p_external_contributor_id" "uuid", "p_display_name" "text", "p_public_role" "text", "p_public_url" "text", "p_location_text" "text", "p_contact_email" "text", "p_contact_phone" "text", "p_consent_status" "text", "p_public_safe" boolean, "p_contributor_state" "text", "p_internal_notes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_external_contributor"("p_external_contributor_id" "uuid", "p_display_name" "text", "p_public_role" "text", "p_public_url" "text", "p_location_text" "text", "p_contact_email" "text", "p_contact_phone" "text", "p_consent_status" "text", "p_public_safe" boolean, "p_contributor_state" "text", "p_internal_notes" "text") IS 'Updates one external-contributor profile without rewriting historical Credits.';



CREATE OR REPLACE FUNCTION "public"."update_import_run"("p_id" "uuid", "p_status" "text" DEFAULT NULL::"text", "p_errors" "text"[] DEFAULT NULL::"text"[], "p_finished_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_imported_counts" "jsonb" DEFAULT NULL::"jsonb", "p_warnings" "text"[] DEFAULT NULL::"text"[]) RETURNS SETOF "public"."wk_ingestion_runs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  UPDATE public.wk_ingestion_runs SET
    status = COALESCE(p_status, status),
    errors = COALESCE(p_errors, errors),
    finished_at = COALESCE(p_finished_at, finished_at),
    imported_counts = COALESCE(p_imported_counts, imported_counts),
    warnings = COALESCE(p_warnings, warnings)
  WHERE id = p_id;
  RETURN QUERY SELECT * FROM public.wk_ingestion_runs WHERE id = p_id;
END;
$$;


ALTER FUNCTION "public"."update_import_run"("p_id" "uuid", "p_status" "text", "p_errors" "text"[], "p_finished_at" timestamp with time zone, "p_imported_counts" "jsonb", "p_warnings" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_media_asset_record_v2"("p_asset_id" "uuid", "p_expected_authority_revision" bigint, "p_patch" "jsonb", "p_reason" "text", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'media', 'auth'
    AS $$
declare
  v_actor_id uuid;
  v_correlation_id uuid := coalesce(p_correlation_id, gen_random_uuid());
  v_asset media.assets%rowtype;
  v_compatibility public.registry_media_assets%rowtype;
  v_new_title text;
  v_new_asset_kind text;
  v_new_asset_purpose text;
  v_new_folder_id uuid;
  v_new_status text;
  v_new_lifecycle_state text;
  v_new_revision bigint;
  v_tags text[];
begin
  v_actor_id := media.require_command_actor('manage_media_assets');

  if p_patch is null or jsonb_typeof(p_patch) <> 'object' then
    raise exception 'Media update patch must be an object';
  end if;

  if nullif(btrim(p_reason), '') is null then
    raise exception 'Media update reason is required';
  end if;

  select *
  into v_asset
  from media.assets
  where id = p_asset_id
  for update;

  if not found then
    raise exception 'Media asset does not exist';
  end if;

  if v_asset.authority_revision <> p_expected_authority_revision then
    raise exception 'Stale Media authority revision';
  end if;

  select *
  into v_compatibility
  from public.registry_media_assets
  where id = p_asset_id
  for update;

  if not found then
    raise exception 'Media compatibility projection does not exist';
  end if;

  v_new_title :=
    case when p_patch ? 'title'
      then nullif(btrim(p_patch ->> 'title'), '')
      else v_asset.title
    end;

  if v_new_title is null then
    raise exception 'Media title is required';
  end if;

  v_new_asset_kind :=
    case when p_patch ? 'file_kind'
      then coalesce(nullif(btrim(p_patch ->> 'file_kind'), ''), v_asset.asset_kind)
      else v_asset.asset_kind
    end;

  v_new_asset_purpose :=
    case when p_patch ? 'asset_purpose'
      then coalesce(nullif(btrim(p_patch ->> 'asset_purpose'), ''), 'general')
      else v_asset.asset_purpose
    end;

  v_new_folder_id :=
    case when p_patch ? 'folder_id'
      then nullif(p_patch ->> 'folder_id', '')::uuid
      else v_asset.compatibility_folder_id
    end;

  v_new_status :=
    case when p_patch ? 'status'
      then coalesce(nullif(btrim(p_patch ->> 'status'), ''), v_compatibility.status)
      else v_compatibility.status
    end;

  if v_new_status not in ('active', 'archived', 'needs_review', 'rejected') then
    raise exception 'Unsupported Media status';
  end if;

  v_new_lifecycle_state :=
    case when v_new_status = 'archived' then 'archived' else 'active' end;

  if not exists (
    select 1 from media.asset_kinds kind_row
    where kind_row.asset_kind = v_new_asset_kind and kind_row.enabled
  ) then
    raise exception 'Unknown or disabled Media asset kind';
  end if;

  if not exists (
    select 1 from media.asset_purposes purpose_row
    where purpose_row.asset_purpose = v_new_asset_purpose and purpose_row.enabled
  ) then
    raise exception 'Unknown or disabled Media asset purpose';
  end if;

  if v_new_folder_id is not null
     and not exists (
       select 1 from public.media_folders folder_row
       where folder_row.id = v_new_folder_id
     )
  then
    raise exception 'Compatibility Media folder does not exist';
  end if;

  if p_patch ? 'metadata'
     and jsonb_typeof(p_patch -> 'metadata') <> 'object'
  then
    raise exception 'Media metadata patch must be an object';
  end if;

  if p_patch ? 'tags' then
    if jsonb_typeof(p_patch -> 'tags') <> 'array' then
      raise exception 'Media tags must be an array';
    end if;
    select coalesce(array_agg(value), '{}'::text[])
    into v_tags
    from jsonb_array_elements_text(p_patch -> 'tags') value;
  else
    v_tags := v_compatibility.tags;
  end if;

  v_new_revision := v_asset.authority_revision + 1;

  update media.assets
  set
    asset_kind = v_new_asset_kind,
    asset_purpose = v_new_asset_purpose,
    title = v_new_title,
    lifecycle_state = v_new_lifecycle_state,
    compatibility_folder_id = v_new_folder_id,
    authority_revision = v_new_revision,
    updated_by = v_actor_id,
    archived_by = case when v_new_lifecycle_state = 'archived' then v_actor_id else null end,
    archived_at = case when v_new_lifecycle_state = 'archived' then now() else null end,
    archive_reason = case when v_new_lifecycle_state = 'archived' then btrim(p_reason) else null end,
    updated_at = now()
  where id = p_asset_id;

  update public.registry_media_assets
  set
    title = v_new_title,
    status = v_new_status,
    folder_id = v_new_folder_id,
    file_kind = v_new_asset_kind,
    asset_purpose = v_new_asset_purpose,
    display_filename = case when p_patch ? 'display_filename' then nullif(btrim(p_patch ->> 'display_filename'), '') else display_filename end,
    original_filename = case when p_patch ? 'original_filename' then nullif(btrim(p_patch ->> 'original_filename'), '') else original_filename end,
    content_date = case when p_patch ? 'content_date' then nullif(p_patch ->> 'content_date', '')::date else content_date end,
    rights_status = case when p_patch ? 'rights_status' then coalesce(nullif(btrim(p_patch ->> 'rights_status'), ''), 'unknown') else rights_status end,
    credit_text = case when p_patch ? 'credit_text' then nullif(btrim(p_patch ->> 'credit_text'), '') else credit_text end,
    country_code = case when p_patch ? 'country_code' then nullif(upper(btrim(p_patch ->> 'country_code')), '') else country_code end,
    language_code = case when p_patch ? 'language_code' then nullif(lower(btrim(p_patch ->> 'language_code')), '') else language_code end,
    tags = v_tags,
    internal_notes = case when p_patch ? 'internal_notes' then nullif(btrim(p_patch ->> 'internal_notes'), '') else internal_notes end,
    metadata = case when p_patch ? 'metadata' then coalesce(metadata, '{}'::jsonb) || (p_patch -> 'metadata') else metadata end,
    updated_at = now()
  where id = p_asset_id;

  insert into media.events (
    asset_id,
    event_type,
    actor_id,
    reason,
    prior_state,
    resulting_state,
    correlation_id
  )
  values (
    p_asset_id,
    'asset_metadata_updated',
    v_actor_id,
    btrim(p_reason),
    jsonb_build_object(
      'title', v_asset.title,
      'asset_kind', v_asset.asset_kind,
      'asset_purpose', v_asset.asset_purpose,
      'lifecycle_state', v_asset.lifecycle_state,
      'compatibility_status', v_compatibility.status,
      'authority_revision', v_asset.authority_revision
    ),
    jsonb_build_object(
      'title', v_new_title,
      'asset_kind', v_new_asset_kind,
      'asset_purpose', v_new_asset_purpose,
      'lifecycle_state', v_new_lifecycle_state,
      'compatibility_status', v_new_status,
      'authority_revision', v_new_revision
    ),
    v_correlation_id
  );

  return jsonb_build_object(
    'asset_id', p_asset_id,
    'status', v_new_status,
    'lifecycle_state', v_new_lifecycle_state,
    'authority_revision', v_new_revision,
    'correlation_id', v_correlation_id
  );
end;
$$;


ALTER FUNCTION "public"."update_media_asset_record_v2"("p_asset_id" "uuid", "p_expected_authority_revision" bigint, "p_patch" "jsonb", "p_reason" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_media_asset_record_v2"("p_asset_id" "uuid", "p_expected_authority_revision" bigint, "p_patch" "jsonb", "p_reason" "text", "p_correlation_id" "uuid") IS 'Updates canonical Media metadata, compatibility projection, and lifecycle with optimistic concurrency.';



CREATE OR REPLACE FUNCTION "public"."update_media_asset_status_batch_v2"("p_asset_ids" "uuid"[], "p_status" "text", "p_reason" "text", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'media', 'auth'
    AS $$
declare
  v_actor_id uuid;
  v_correlation_id uuid := coalesce(p_correlation_id, gen_random_uuid());
  v_asset_id uuid;
  v_authority_revision bigint;
  v_count integer := 0;
begin
  v_actor_id := media.require_command_actor('manage_media_assets');

  if p_asset_ids is null or cardinality(p_asset_ids) = 0 then
    raise exception 'Media status batch requires at least one asset';
  end if;

  if cardinality(p_asset_ids) > 200 then
    raise exception 'Media status batch may contain at most 200 assets';
  end if;

  if p_status not in ('active', 'archived', 'needs_review', 'rejected') then
    raise exception 'Unsupported Media status';
  end if;

  if nullif(btrim(p_reason), '') is null then
    raise exception 'Media status reason is required';
  end if;

  for v_asset_id in
    select distinct unnest(p_asset_ids)
    order by 1
  loop
    select authority_revision
    into v_authority_revision
    from media.assets
    where id = v_asset_id
    for update;

    if not found then
      raise exception 'Media asset does not exist: %', v_asset_id;
    end if;

    perform public.update_media_asset_record_v2(
      v_asset_id,
      v_authority_revision,
      jsonb_build_object('status', p_status),
      btrim(p_reason),
      v_correlation_id
    );

    v_count := v_count + 1;
  end loop;

  return jsonb_build_object(
    'updated_count', v_count,
    'status', p_status,
    'correlation_id', v_correlation_id
  );
end;
$$;


ALTER FUNCTION "public"."update_media_asset_status_batch_v2"("p_asset_ids" "uuid"[], "p_status" "text", "p_reason" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_media_asset_status_batch_v2"("p_asset_ids" "uuid"[], "p_status" "text", "p_reason" "text", "p_correlation_id" "uuid") IS 'Applies a governed Media status change to at most 200 assets in one transaction.';



CREATE OR REPLACE FUNCTION "public"."update_playlist_item"("p_playlist_id" "uuid", "p_playlist_item_id" "uuid", "p_expected_authority_revision" bigint, "p_payload" "jsonb", "p_idempotency_key" "text", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("command_receipt_id" "uuid", "receipt_status" "text", "playlist_id" "uuid", "resource_id" "uuid", "playlist_item_id" "uuid", "authority_revision" bigint, "result_payload" "jsonb", "idempotent_replay" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'editorial', 'platform_private'
    AS $$
declare
  v_playlist public.wk_playlists%rowtype;
  v_item public.wk_playlist_items%rowtype;
  v_resource_id uuid;
  v_begin record;
  v_read record;
  v_request jsonb;
  v_result jsonb;
  v_artist_names text[];
  v_correlation_id uuid := coalesce(p_correlation_id, gen_random_uuid());
begin
  if p_playlist_id is null
     or p_playlist_item_id is null
     or p_expected_authority_revision is null
     or p_expected_authority_revision < 1
  then
    raise exception
      using
        errcode = '22023',
        message = 'Playlist, item, and expected authority revision are required.';
  end if;

  if p_payload is null
     or jsonb_typeof(p_payload) <> 'object'
     or p_payload = '{}'::jsonb
     or p_payload - array[
       'title',
       'artist_names',
       'release_title',
       'provider_url'
     ] <> '{}'::jsonb
  then
    raise exception
      using errcode = '22023', message = 'Playlist-item update payload is invalid.';
  end if;

  if p_payload ? 'artist_names'
     and jsonb_typeof(p_payload -> 'artist_names') <> 'array'
  then
    raise exception
      using errcode = '22023', message = 'artist_names must be an array.';
  end if;

  select playlist.*
  into v_playlist
  from public.wk_playlists playlist
  where playlist.id = p_playlist_id
  for update of playlist;

  select binding.resource_id
  into v_resource_id
  from editorial.playlist_resources binding
  where binding.playlist_id = p_playlist_id;

  if not found then
    raise exception using errcode = 'P0002', message = 'Playlist does not exist.';
  end if;

  if not editorial.current_user_can_edit_playlist(v_resource_id) then
    raise exception using errcode = '42501', message = 'Playlist edit permission is required.';
  end if;

  v_request := jsonb_build_object(
    'playlist_id', p_playlist_id,
    'playlist_item_id', p_playlist_item_id,
    'expected_authority_revision', p_expected_authority_revision,
    'payload', p_payload,
    'correlation_id', v_correlation_id
  );

  select *
  into v_begin
  from platform_private.begin_authenticated_resource_command(
    'playlist.item.update',
    v_resource_id,
    p_idempotency_key,
    v_request
  );

  if not v_begin.idempotent_replay then
    if v_playlist.authority_revision <> p_expected_authority_revision then
      perform platform_private.reject_resource_command(
        v_begin.command_receipt_id,
        'playlist_revision_changed',
        'The Playlist changed before this item update could be applied.',
        jsonb_build_object(
          'playlist_id', p_playlist_id,
          'authority_revision', v_playlist.authority_revision
        )
      );
    else
      select item.*
      into v_item
      from public.wk_playlist_items item
      where item.id = p_playlist_item_id
        and item.playlist_id = p_playlist_id
        and item.lifecycle_state = 'active'
      for update;

      if not found then
        perform platform_private.reject_resource_command(
          v_begin.command_receipt_id,
          'playlist_item_not_active',
          'The Playlist item is missing or no longer active.',
          jsonb_build_object(
            'playlist_id', p_playlist_id,
            'authority_revision', v_playlist.authority_revision
          )
        );
      else
        if v_item.registry_track_id is not null
           and (
             p_payload ? 'title'
             or p_payload ? 'artist_names'
             or p_payload ? 'release_title'
           )
        then
          raise exception
            using
              errcode = '22023',
              message = 'Matched Playlist track presentation is owned by Registry.';
        end if;

        if p_payload ? 'artist_names' then
          select coalesce(array_agg(value), '{}'::text[])
          into v_artist_names
          from jsonb_array_elements_text(
            p_payload -> 'artist_names'
          ) value;
        else
          v_artist_names := v_item.artist_names;
        end if;

        update public.wk_playlist_items item
        set
          title = case
            when p_payload ? 'title'
              then nullif(btrim(p_payload ->> 'title'), '')
            else item.title
          end,
          artist_names = v_artist_names,
          release_title = case
            when p_payload ? 'release_title'
              then nullif(btrim(p_payload ->> 'release_title'), '')
            else item.release_title
          end,
          provider_url = case
            when p_payload ? 'provider_url'
              then nullif(btrim(p_payload ->> 'provider_url'), '')
            else item.provider_url
          end
        where item.id = p_playlist_item_id
        returning item.*
        into v_item;

        if v_item.registry_track_id is null
           and v_item.provider_key is null
           and (
             nullif(btrim(coalesce(v_item.title, '')), '') is null
             or cardinality(v_item.artist_names) = 0
           )
        then
          raise exception
            using
              errcode = '22023',
              message = 'External Playlist items must retain a title and artist.';
        end if;

        update public.wk_playlists playlist
        set authority_revision = playlist.authority_revision + 1
        where playlist.id = p_playlist_id
        returning playlist.authority_revision
        into v_playlist.authority_revision;

        v_result := jsonb_build_object(
          'playlist_id', p_playlist_id,
          'playlist_item_id', p_playlist_item_id,
          'authority_revision', v_playlist.authority_revision,
          'correlation_id', v_correlation_id
        );

        perform platform_private.complete_resource_command(
          v_begin.command_receipt_id,
          v_result
        );
      end if;
    end if;
  end if;

  select *
  into v_read
  from platform_private.read_authenticated_resource_command_result(
    v_begin.command_receipt_id,
    v_begin.idempotent_replay
  );

  command_receipt_id := v_read.command_receipt_id;
  receipt_status := v_read.receipt_status;
  playlist_id := p_playlist_id;
  resource_id := v_read.resource_id;
  playlist_item_id := p_playlist_item_id;
  authority_revision := nullif(v_read.result_payload ->> 'authority_revision', '')::bigint;
  result_payload := v_read.result_payload;
  idempotent_replay := v_read.idempotent_replay;
  return next;
end;
$$;


ALTER FUNCTION "public"."update_playlist_item"("p_playlist_id" "uuid", "p_playlist_item_id" "uuid", "p_expected_authority_revision" bigint, "p_payload" "jsonb", "p_idempotency_key" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_playlist_metadata"("p_playlist_id" "uuid", "p_expected_authority_revision" bigint, "p_payload" "jsonb", "p_idempotency_key" "text", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("command_receipt_id" "uuid", "receipt_status" "text", "playlist_id" "uuid", "resource_id" "uuid", "authority_revision" bigint, "result_payload" "jsonb", "idempotent_replay" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'editorial', 'platform_private'
    AS $_$
declare
  v_playlist public.wk_playlists%rowtype;
  v_resource_id uuid;
  v_begin record;
  v_read record;
  v_request jsonb;
  v_result jsonb;
  v_new_title text;
  v_new_slug text;
  v_new_description text;
  v_new_curator_label text;
  v_new_metadata jsonb;
  v_correlation_id uuid := coalesce(p_correlation_id, gen_random_uuid());
begin
  if p_playlist_id is null
     or p_expected_authority_revision is null
     or p_expected_authority_revision < 1
  then
    raise exception
      using errcode = '22023', message = 'Playlist and expected authority revision are required.';
  end if;

  if p_payload is null
     or jsonb_typeof(p_payload) <> 'object'
     or p_payload = '{}'::jsonb
     or p_payload - array[
       'title',
       'slug',
       'description',
       'curator_label',
       'metadata'
     ] <> '{}'::jsonb
  then
    raise exception
      using errcode = '22023', message = 'Playlist metadata payload is invalid.';
  end if;

  select playlist.*
  into v_playlist
  from public.wk_playlists playlist
  where playlist.id = p_playlist_id
  for update of playlist;

  select binding.resource_id
  into v_resource_id
  from editorial.playlist_resources binding
  where binding.playlist_id = p_playlist_id;

  if not found then
    raise exception
      using errcode = 'P0002', message = 'Playlist does not exist.';
  end if;

  if not editorial.current_user_can_edit_playlist(v_resource_id) then
    raise exception
      using errcode = '42501', message = 'Playlist edit permission is required.';
  end if;

  v_request := jsonb_build_object(
    'playlist_id', p_playlist_id,
    'expected_authority_revision', p_expected_authority_revision,
    'payload', p_payload,
    'correlation_id', v_correlation_id
  );

  select *
  into v_begin
  from platform_private.begin_authenticated_resource_command(
    'playlist.metadata.update',
    v_resource_id,
    p_idempotency_key,
    v_request
  );

  if v_begin.idempotent_replay then
    select *
    into v_read
    from platform_private.read_authenticated_resource_command_result(
      v_begin.command_receipt_id,
      true
    );

    command_receipt_id := v_read.command_receipt_id;
    receipt_status := v_read.receipt_status;
    playlist_id := p_playlist_id;
    resource_id := v_read.resource_id;
    authority_revision := nullif(
      v_read.result_payload ->> 'authority_revision',
      ''
    )::bigint;
    result_payload := v_read.result_payload;
    idempotent_replay := true;
    return next;
    return;
  end if;

  if v_playlist.authority_revision <> p_expected_authority_revision then
    perform platform_private.reject_resource_command(
      v_begin.command_receipt_id,
      'playlist_revision_changed',
      'The Playlist changed before this metadata update could be applied.',
      jsonb_build_object(
        'playlist_id', p_playlist_id,
        'authority_revision', v_playlist.authority_revision
      )
    );
  else
    v_new_title := case
      when p_payload ? 'title'
        then nullif(btrim(p_payload ->> 'title'), '')
      else v_playlist.title
    end;

    v_new_slug := case
      when p_payload ? 'slug'
        then nullif(btrim(lower(p_payload ->> 'slug')), '')
      else v_playlist.slug
    end;

    v_new_description := case
      when p_payload ? 'description'
        then nullif(btrim(p_payload ->> 'description'), '')
      else v_playlist.description
    end;

    v_new_curator_label := case
      when p_payload ? 'curator_label'
        then nullif(btrim(p_payload ->> 'curator_label'), '')
      else v_playlist.curator_label
    end;

    v_new_metadata := case
      when p_payload ? 'metadata'
        then coalesce(p_payload -> 'metadata', '{}'::jsonb)
      else v_playlist.metadata
    end;

    if v_new_title is null or length(v_new_title) > 300 then
      raise exception
        using errcode = '22023', message = 'Playlist title is invalid.';
    end if;

    if v_new_slug is null
       or length(v_new_slug) > 200
       or v_new_slug !~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'
    then
      raise exception
        using errcode = '22023', message = 'Playlist slug is invalid.';
    end if;

    if length(coalesce(v_new_description, '')) > 10000
       or length(coalesce(v_new_curator_label, '')) > 500
       or jsonb_typeof(v_new_metadata) <> 'object'
       or octet_length(v_new_metadata::text) > 16384
    then
      raise exception
        using errcode = '22023', message = 'Playlist metadata values are invalid.';
    end if;

    if v_new_slug <> v_playlist.slug
       and exists (
         select 1
         from public.wk_playlists other_playlist
         where other_playlist.slug = v_new_slug
           and other_playlist.id <> p_playlist_id
       )
    then
      raise exception
        using errcode = '23505', message = 'Playlist slug already exists.';
    end if;

    update public.wk_playlists playlist
    set
      title = v_new_title,
      slug = v_new_slug,
      description = v_new_description,
      curator_label = v_new_curator_label,
      metadata = v_new_metadata,
      authority_revision = playlist.authority_revision + 1
    where playlist.id = p_playlist_id
    returning playlist.*
    into v_playlist;

    v_result := jsonb_build_object(
      'playlist_id', p_playlist_id,
      'resource_id', v_resource_id,
      'slug', v_playlist.slug,
      'authority_revision', v_playlist.authority_revision,
      'correlation_id', v_correlation_id
    );

    perform platform_private.complete_resource_command(
      v_begin.command_receipt_id,
      v_result
    );
  end if;

  select *
  into v_read
  from platform_private.read_authenticated_resource_command_result(
    v_begin.command_receipt_id,
    false
  );

  command_receipt_id := v_read.command_receipt_id;
  receipt_status := v_read.receipt_status;
  playlist_id := p_playlist_id;
  resource_id := v_read.resource_id;
  authority_revision := nullif(
    v_read.result_payload ->> 'authority_revision',
    ''
  )::bigint;
  result_payload := v_read.result_payload;
  idempotent_replay := false;
  return next;
end;
$_$;


ALTER FUNCTION "public"."update_playlist_metadata"("p_playlist_id" "uuid", "p_expected_authority_revision" bigint, "p_payload" "jsonb", "p_idempotency_key" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_publishing_item"("p_item_id" "uuid", "p_expected_record_version" bigint, "p_title" "text", "p_content_kind" "text", "p_owner_id" "uuid", "p_brief" "text", "p_production_stage" "text", "p_planning_state" "text", "p_priority" "text", "p_production_deadline" timestamp with time zone, "p_planned_publish_at" timestamp with time zone, "p_note" "text" DEFAULT NULL::"text") RETURNS TABLE("item_id" "uuid", "record_version" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_item editorial.publishing_items%rowtype;
  v_updated editorial.publishing_items%rowtype;
  v_action text;
begin
  if auth.uid() is null then
    raise exception
      using
        errcode = '42501',
        message = 'Authentication required';
  end if;

  if not editorial.current_user_can_manage_publishing() then
    raise exception
      using
        errcode = '42501',
        message = 'Permission denied';
  end if;

  select item.*
  into v_item
  from editorial.publishing_items item
  where item.id = p_item_id
  for update;

  if not found then
    raise exception
      using
        errcode = 'P0002',
        message = 'Publishing item not found';
  end if;

  if v_item.record_version
     <> p_expected_record_version
  then
    raise exception
      using
        errcode = '40001',
        message = format(
          'STALE_PUBLISHING_ITEM_VERSION: expected %s, current %s',
          p_expected_record_version,
          v_item.record_version
        );
  end if;

  if nullif(btrim(p_title), '') is null then
    raise exception 'A Publishing item title is required';
  end if;

  if not (
    v_item.title
      is distinct from btrim(p_title)
    or v_item.content_kind
      is distinct from p_content_kind
    or v_item.owner_id
      is distinct from p_owner_id
    or v_item.brief
      is distinct from nullif(btrim(p_brief), '')
    or v_item.production_stage
      is distinct from p_production_stage
    or v_item.planning_state
      is distinct from p_planning_state
    or v_item.priority
      is distinct from p_priority
    or v_item.production_deadline
      is distinct from p_production_deadline
    or v_item.planned_publish_at
      is distinct from p_planned_publish_at
  ) then
    raise exception
      'Publishing item update made no changes';
  end if;

  if v_item.production_stage
       is distinct from p_production_stage
     and v_item.planning_state
       is not distinct from p_planning_state
  then
    v_action := 'production_stage_changed';
  elsif v_item.planning_state
       is distinct from p_planning_state
     and v_item.production_stage
       is not distinct from p_production_stage
  then
    v_action := 'planning_state_changed';
  else
    v_action := 'details_updated';
  end if;

  update editorial.publishing_items item
  set
    title = btrim(p_title),
    content_kind = p_content_kind,
    owner_id = p_owner_id,
    brief = nullif(btrim(p_brief), ''),
    production_stage = p_production_stage,
    planning_state = p_planning_state,
    priority = p_priority,
    production_deadline = p_production_deadline,
    planned_publish_at = p_planned_publish_at,
    record_version = item.record_version + 1,
    updated_by = auth.uid(),
    updated_at = now()
  where item.id = p_item_id
  returning item.*
  into v_updated;

  insert into editorial.publishing_item_events (
    item_id,
    action,
    prior_record_version,
    resulting_record_version,
    prior_values,
    resulting_values,
    note,
    actor_id
  )
  values (
    v_updated.id,
    v_action,
    v_item.record_version,
    v_updated.record_version,
    editorial.publishing_item_snapshot(v_item),
    editorial.publishing_item_snapshot(v_updated),
    nullif(btrim(p_note), ''),
    auth.uid()
  );

  item_id := v_updated.id;
  record_version := v_updated.record_version;
  return next;
end;
$$;


