CREATE OR REPLACE FUNCTION "public"."update_taxonomy_term"("p_term_id" "uuid", "p_name" "text" DEFAULT NULL::"text", "p_slug" "text" DEFAULT NULL::"text", "p_description" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_user_id uuid;
BEGIN
  v_user_id := auth.uid();

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM user_role_assignments
    WHERE user_id = v_user_id
      AND status = 'active'
      AND (expires_at IS NULL OR expires_at > now())
      AND (role_key = 'administrator' OR role_key IN (
        SELECT role_key FROM role_capabilities WHERE capability_key = 'manage_categories'
      ))
  ) THEN
    RAISE EXCEPTION 'Permission denied: manage_categories capability required';
  END IF;

  UPDATE registry_taxonomy_terms
  SET
    name = COALESCE(p_name, name),
    slug = COALESCE(p_slug, slug),
    description = COALESCE(p_description, description),
    updated_at = now()
  WHERE id = p_term_id;
END;
$$;


ALTER FUNCTION "public"."update_taxonomy_term"("p_term_id" "uuid", "p_name" "text", "p_slug" "text", "p_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_taxonomy_term"("p_term_id" "uuid", "p_name" "text" DEFAULT NULL::"text", "p_slug" "text" DEFAULT NULL::"text", "p_description" "text" DEFAULT NULL::"text", "p_seo_title" "text" DEFAULT NULL::"text", "p_seo_description" "text" DEFAULT NULL::"text", "p_seo_keywords" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_user_id uuid;
  v_update jsonb;
BEGIN
  v_user_id := auth.uid();

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM user_role_assignments
    WHERE user_id = v_user_id
      AND status = 'active'
      AND (expires_at IS NULL OR expires_at > now())
      AND (role_key = 'administrator' OR role_key IN (
        SELECT role_key FROM role_capabilities WHERE capability_key = 'manage_categories'
      ))
  ) THEN
    RAISE EXCEPTION 'Permission denied: manage_categories capability required';
  END IF;

  v_update := jsonb_strip_nulls(jsonb_build_object(
    'seo_title', CASE WHEN p_seo_title IS NOT NULL THEN to_jsonb(p_seo_title) END,
    'seo_description', CASE WHEN p_seo_description IS NOT NULL THEN to_jsonb(p_seo_description) END,
    'seo_keywords', CASE WHEN p_seo_keywords IS NOT NULL THEN to_jsonb(p_seo_keywords) END
  ));

  UPDATE registry_taxonomy_terms
  SET
    name = COALESCE(p_name, name),
    slug = COALESCE(p_slug, slug),
    description = COALESCE(p_description, description),
    metadata = CASE WHEN v_update != ''::jsonb THEN COALESCE(metadata, ''::jsonb) || v_update ELSE metadata END,
    updated_at = now()
  WHERE id = p_term_id;
END;
$$;


ALTER FUNCTION "public"."update_taxonomy_term"("p_term_id" "uuid", "p_name" "text", "p_slug" "text", "p_description" "text", "p_seo_title" "text", "p_seo_description" "text", "p_seo_keywords" "text") OWNER TO "postgres";


