CREATE OR REPLACE FUNCTION "public"."upsert_user_scope_admin"("target_user_id" "uuid", "target_role_key" "text", "target_scope_type" "text", "target_scope_value" "text", "target_can_view" boolean DEFAULT true, "target_can_edit" boolean DEFAULT false, "target_can_publish" boolean DEFAULT false) RETURNS "public"."user_access_scopes"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  scoped public.user_access_scopes;
begin
  if not public.current_user_is_administrator() then
    raise exception 'Only administrators can manage user scopes.' using errcode = '42501';
  end if;

  insert into public.user_access_scopes (user_id, role_key, scope_type, scope_value, can_view, can_edit, can_publish, status, assigned_by, assigned_at, created_at, updated_at)
  values (target_user_id, target_role_key, target_scope_type, target_scope_value, target_can_view, target_can_edit, target_can_publish, 'active', auth.uid(), now(), now(), now())
  on conflict (user_id, role_key, scope_type, scope_value) do update set
    can_view = excluded.can_view,
    can_edit = excluded.can_edit,
    can_publish = excluded.can_publish,
    status = 'active',
    assigned_by = auth.uid(),
    assigned_at = now(),
    updated_at = now()
  returning * into scoped;

  perform public.record_admin_audit('scope_assigned', 'user_access_scopes', scoped.id::text, target_user_id, 'Scope assigned from admin users console.', jsonb_build_object('role_key', target_role_key, 'scope_type', target_scope_type, 'scope_value', target_scope_value, 'can_view', target_can_view, 'can_edit', target_can_edit, 'can_publish', target_can_publish));
  return scoped;
end;
$$;


ALTER FUNCTION "public"."upsert_user_scope_admin"("target_user_id" "uuid", "target_role_key" "text", "target_scope_type" "text", "target_scope_value" "text", "target_can_view" boolean, "target_can_edit" boolean, "target_can_publish" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_slug_encoding"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  -- Reject URL-encoded characters (%xx patterns like %c2%b3)
  if new.slug ~ '%[0-9a-fA-F]{2}' then
    raise exception 'Slug contains URL-encoded characters: %', new.slug;
  end if;

  -- Reject literal Unicode escape sequences like \u00e9.
  -- Do not reject ordinary words like "kudade".
  if new.slug ~ E'\\\\u[0-9a-fA-F]{4}' then
    raise exception 'Slug contains Unicode escape sequences: %', new.slug;
  end if;

  -- Reject any raw bytes / non-printable characters.
  if new.slug ~ '[\x00-\x1F\x7F]' then
    raise exception 'Slug contains control characters: %', new.slug;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_slug_encoding"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."verify_media_file_object"("p_file_object_id" "uuid", "p_result_state" "text", "p_sha256" "text" DEFAULT NULL::"text", "p_byte_size" bigint DEFAULT NULL::bigint, "p_mime_type" "text" DEFAULT NULL::"text", "p_technical_metadata" "jsonb" DEFAULT '{}'::"jsonb", "p_failure_detail" "text" DEFAULT NULL::"text", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("file_object_id" "uuid", "verification_state" "text", "correlation_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'media', 'auth'
    AS $_$
declare
  v_actor_id uuid;
  v_object media.file_objects%rowtype;
  v_correlation_id uuid := coalesce(
    p_correlation_id,
    gen_random_uuid()
  );
  v_event_type text;
begin
  v_actor_id :=
    media.require_command_actor('verify_media_files');

  select *
  into v_object
  from media.file_objects
  where id = p_file_object_id
  for update;

  if not found then
    raise exception 'Media file object does not exist';
  end if;

  if v_object.verification_state <> 'unverified' then
    raise exception 'Media file verification is already finalized';
  end if;

  if p_result_state not in (
    'verified',
    'failed',
    'unreachable'
  ) then
    raise exception 'Invalid Media verification result state';
  end if;

  if p_technical_metadata is null
     or jsonb_typeof(p_technical_metadata) <> 'object'
  then
    raise exception 'Media technical metadata must be an object';
  end if;

  if p_result_state = 'verified' then
    if p_sha256 is null
       or p_sha256 !~ '^[0-9a-f]{64}$'
       or p_byte_size is null
       or p_byte_size < 0
       or nullif(btrim(p_mime_type), '') is null
       or v_object.storage_path is null
    then
      raise exception
        'Verified Media requires checksum, byte size, MIME type, and immutable storage path';
    end if;

    if nullif(btrim(p_failure_detail), '') is not null then
      raise exception 'Verified Media cannot include failure detail';
    end if;

    v_event_type := 'file_object_verified';
  else
    if nullif(btrim(p_failure_detail), '') is null then
      raise exception 'Failed or unreachable Media requires failure detail';
    end if;

    v_event_type :=
      case p_result_state
        when 'failed' then
          'file_object_verification_failed'
        else
          'file_object_unreachable'
      end;
  end if;

  perform set_config(
    'media.verifying_file_object_id',
    p_file_object_id::text,
    true
  );

  update media.file_objects
  set
    sha256 =
      case
        when p_result_state = 'verified'
          then p_sha256
        else sha256
      end,
    byte_size =
      case
        when p_result_state = 'verified'
          then p_byte_size
        else byte_size
      end,
    mime_type =
      case
        when p_result_state = 'verified'
          then btrim(p_mime_type)
        else mime_type
      end,
    technical_metadata =
      technical_metadata || p_technical_metadata,
    verification_state = p_result_state,
    verified_by = v_actor_id,
    verified_at = now(),
    verification_error =
      case
        when p_result_state = 'verified'
          then null
        else btrim(p_failure_detail)
      end
  where id = p_file_object_id;

  perform set_config(
    'media.verifying_file_object_id',
    '',
    true
  );

  insert into media.events (
    file_object_id,
    event_type,
    actor_id,
    reason,
    prior_state,
    resulting_state,
    correlation_id
  )
  values (
    p_file_object_id,
    v_event_type,
    v_actor_id,
    coalesce(
      nullif(btrim(p_failure_detail), ''),
      'Media file object verified'
    ),
    jsonb_build_object(
      'verification_state',
      v_object.verification_state
    ),
    jsonb_build_object(
      'verification_state',
      p_result_state,
      'sha256',
      case
        when p_result_state = 'verified'
          then p_sha256
        else null
      end,
      'byte_size',
      case
        when p_result_state = 'verified'
          then p_byte_size
        else null
      end,
      'mime_type',
      case
        when p_result_state = 'verified'
          then btrim(p_mime_type)
        else null
      end
    ),
    v_correlation_id
  );

  return query
  select
    p_file_object_id,
    p_result_state,
    v_correlation_id;
end;
$_$;


ALTER FUNCTION "public"."verify_media_file_object"("p_file_object_id" "uuid", "p_result_state" "text", "p_sha256" "text", "p_byte_size" bigint, "p_mime_type" "text", "p_technical_metadata" "jsonb", "p_failure_detail" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."verify_media_upload_session_v1"("p_session_id" "uuid", "p_storage_path" "text", "p_byte_size" bigint, "p_sha256" "text", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'media', 'auth'
    AS $$
declare
  v_session media.upload_sessions%rowtype;
  v_file_object_id uuid;
  v_correlation_id uuid;
  v_file jsonb;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception
      using
        errcode = '42501',
        message = 'Service-role access is required.';
  end if;

  select session_row.*
  into v_session
  from media.upload_sessions session_row
  where session_row.id = p_session_id
  for update;

  if not found then
    raise exception 'Upload session does not exist';
  end if;

  if v_session.state = 'verified' then
    if v_session.storage_path is distinct from p_storage_path
       or v_session.verified_byte_size is distinct from p_byte_size
       or v_session.verified_sha256 is distinct from lower(btrim(p_sha256))
       or v_session.file_object_id is null
    then
      raise exception 'Verified upload session evidence does not match retry';
    end if;

    return jsonb_build_object(
      'session_id', v_session.id,
      'state', v_session.state,
      'storage_path', v_session.storage_path,
      'byte_size', v_session.verified_byte_size,
      'sha256', v_session.verified_sha256,
      'file_object_id', v_session.file_object_id,
      'correlation_id', v_session.correlation_id
    );
  end if;

  if v_session.state <> 'created' then
    raise exception 'Upload session is not eligible for verification';
  end if;

  if v_session.expires_at <= now() then
    raise exception 'Upload session has expired';
  end if;

  if v_session.storage_path is distinct from nullif(btrim(p_storage_path), '')
     or v_session.expected_byte_size is distinct from p_byte_size
     or v_session.expected_sha256 is distinct from lower(btrim(p_sha256))
  then
    raise exception 'Receiver verification evidence does not match upload session';
  end if;

  v_correlation_id := coalesce(p_correlation_id, v_session.correlation_id);

  v_file := jsonb_build_object(
    'storage_provider', v_session.storage_provider,
    'storage_namespace', v_session.storage_namespace,
    'storage_path', v_session.storage_path,
    'delivery_url',
      'https://media.wakilisha.africa/__private/media-master/' ||
      v_session.id::text,
    'original_filename', v_session.original_filename,
    'mime_type', v_session.mime_type,
    'byte_size', v_session.expected_byte_size,
    'sha256', v_session.expected_sha256,
    'technical_metadata', jsonb_build_object(
      'upload_session_id', v_session.id,
      'transfer_kind', 'resumable_parts',
      'protected_original', true,
      'part_size_bytes', v_session.part_size_bytes,
      'total_parts', v_session.total_parts
    )
  );

  v_file_object_id := media.insert_verified_file_object_v2(
    v_file,
    v_session.actor_id,
    v_correlation_id
  );

  update media.upload_sessions
  set
    state = 'verified',
    verified_byte_size = p_byte_size,
    verified_sha256 = lower(btrim(p_sha256)),
    verified_at = now(),
    file_object_id = v_file_object_id,
    last_error = null,
    updated_at = now()
  where id = v_session.id;

  return jsonb_build_object(
    'session_id', v_session.id,
    'state', 'verified',
    'storage_path', v_session.storage_path,
    'byte_size', p_byte_size,
    'sha256', lower(btrim(p_sha256)),
    'file_object_id', v_file_object_id,
    'correlation_id', v_correlation_id
  );
end;
$$;


ALTER FUNCTION "public"."verify_media_upload_session_v1"("p_session_id" "uuid", "p_storage_path" "text", "p_byte_size" bigint, "p_sha256" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."withdraw_article_suggestion"("p_suggestion_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS TABLE("suggestion_id" "uuid", "decision_status" "text", "decided_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial'
    AS $$
declare
  v_suggestion editorial.article_suggestions%rowtype;
  v_thread editorial.article_review_threads%rowtype;
  v_decided_at timestamptz := now();
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  select suggestion.*
  into v_suggestion
  from editorial.article_suggestions suggestion
  where suggestion.id = p_suggestion_id
  for update;

  if not found then
    raise exception 'Article suggestion not found';
  end if;

  select thread.*
  into v_thread
  from editorial.article_review_threads thread
  where thread.id = v_suggestion.thread_id
  for update;

  if v_thread.created_by is distinct from auth.uid() then
    raise exception
      'Only the suggestion creator can withdraw it';
  end if;

  if v_suggestion.status <> 'open' then
    raise exception 'Only open suggestions can be withdrawn';
  end if;

  update editorial.article_suggestions
  set
    status = 'withdrawn',
    decided_by = auth.uid(),
    decided_at = v_decided_at,
    decision_note = nullif(btrim(coalesce(p_note, '')), '')
  where id = p_suggestion_id;

  update editorial.article_review_threads
  set
    status = 'resolved',
    resolved_by = auth.uid(),
    resolved_at = v_decided_at
  where id = v_thread.id;

  insert into editorial.article_suggestion_events (
    suggestion_id,
    action,
    note
  )
  values (
    p_suggestion_id,
    'withdrawn',
    nullif(btrim(coalesce(p_note, '')), '')
  );

  suggestion_id := p_suggestion_id;
  decision_status := 'withdrawn';
  decided_at := v_decided_at;
  return next;
end;
$$;


ALTER FUNCTION "public"."withdraw_article_suggestion"("p_suggestion_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."withdraw_source"("p_source_id" "uuid", "p_reason" "text", "p_withdrawal_public_mode" "text" DEFAULT NULL::"text", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'editorial', 'auth'
    AS $$
declare
  v_actor_id uuid;
  v_source editorial.sources%rowtype;
  v_public_mode text;
begin
  v_actor_id :=
    editorial.assert_source_command_actor('withdraw_sources');

  if nullif(btrim(p_reason), '') is null then
    raise exception
      'A Source withdrawal reason is required';
  end if;

  v_public_mode :=
    coalesce(
      nullif(btrim(p_withdrawal_public_mode), ''),
      'hide_public_reference'
    );

  if v_public_mode not in (
    'retain_public_reference',
    'redact_public_reference',
    'hide_public_reference'
  ) then
    raise exception
      'Choose a supported withdrawal public mode';
  end if;

  select *
  into v_source
  from editorial.sources source
  where source.id = p_source_id
  for update;

  if not found then
    raise exception
      'Source was not found';
  end if;

  if v_source.source_state = 'withdrawn' then
    raise exception
      'Source is already withdrawn';
  end if;

  if v_source.source_state = 'archived' then
    raise exception
      'Archived Sources cannot be withdrawn';
  end if;

  update editorial.sources
  set
    source_state = 'withdrawn',
    withdrawn_by = v_actor_id,
    withdrawn_at = now(),
    withdrawal_reason = btrim(p_reason),
    withdrawal_public_mode = v_public_mode,
    updated_by = v_actor_id,
    updated_at = now()
  where id = p_source_id;

  insert into editorial.source_review_events (
    source_id,
    source_version_id,
    actor_id,
    action,
    reason,
    prior_review_status,
    resulting_review_status,
    prior_exposure_class,
    resulting_exposure_class,
    prior_source_state,
    resulting_source_state,
    correlation_id
  )
  values (
    p_source_id,
    v_source.current_working_version_id,
    v_actor_id,
    'withdrawn',
    btrim(p_reason),
    v_source.review_status,
    v_source.review_status,
    v_source.exposure_class,
    v_source.exposure_class,
    v_source.source_state,
    'withdrawn',
    p_correlation_id
  );

  return jsonb_build_object(
    'source_id',
      p_source_id,
    'source_state',
      'withdrawn',
    'withdrawal_public_mode',
      v_public_mode
  );
end;
$$;


ALTER FUNCTION "public"."withdraw_source"("p_source_id" "uuid", "p_reason" "text", "p_withdrawal_public_mode" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."withdraw_source"("p_source_id" "uuid", "p_reason" "text", "p_withdrawal_public_mode" "text", "p_correlation_id" "uuid") IS 'Withdraws a Source without deleting historical Source identity.';



