CREATE OR REPLACE FUNCTION "public"."wk_chart_entries_apply_artist_alias"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_source_slug text;
  v_resolved record;
begin
  v_source_slug := public.wk_slugify_text(
    coalesce(
      nullif(new.artist_slug, ''),
      split_part(coalesce(new.artist_name, ''), ',', 1)
    )
  );

  if v_source_slug = '' then
    return new;
  end if;

  new.artist_slug := v_source_slug;

  select *
  into v_resolved
  from public.registry_resolve_artist_slug_for_public(v_source_slug)
  limit 1;

  if v_resolved.canonical_slug is not null then
    new.artist_slug := v_resolved.canonical_slug;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."wk_chart_entries_apply_artist_alias"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."wk_first_jsonb_text"("a" "jsonb", "b" "jsonb", VARIADIC "keys" "text"[]) RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    AS $$
declare
  k text;
  v text;
begin
  foreach k in array keys loop
    v := nullif(a ->> k, '');
    if v is not null then
      return v;
    end if;
    v := nullif(b ->> k, '');
    if v is not null then
      return v;
    end if;
  end loop;
  return null;
end;
$$;


ALTER FUNCTION "public"."wk_first_jsonb_text"("a" "jsonb", "b" "jsonb", VARIADIC "keys" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."wk_jsonb_text"("payload" "jsonb", VARIADIC "keys" "text"[]) RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    AS $$
declare
  k text;
  v text;
begin
  if payload is null then
    return null;
  end if;
  foreach k in array keys loop
    v := nullif(payload ->> k, '');
    if v is not null then
      return v;
    end if;
  end loop;
  return null;
end;
$$;


ALTER FUNCTION "public"."wk_jsonb_text"("payload" "jsonb", VARIADIC "keys" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."wk_legacy_uuid"("scope" "text", "legacy_id" "text") RETURNS "uuid"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select (
    substr(md5(scope || ':' || coalesce(legacy_id, '')), 1, 8) || '-' ||
    substr(md5(scope || ':' || coalesce(legacy_id, '')), 9, 4) || '-' ||
    substr(md5(scope || ':' || coalesce(legacy_id, '')), 13, 4) || '-' ||
    substr(md5(scope || ':' || coalesce(legacy_id, '')), 17, 4) || '-' ||
    substr(md5(scope || ':' || coalesce(legacy_id, '')), 21, 12)
  )::uuid;
$$;


