CREATE OR REPLACE FUNCTION "public"."wk_norm"("value" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select lower(regexp_replace(trim(coalesce(value, '')), '\s+', ' ', 'g'));
$$;


ALTER FUNCTION "public"."wk_norm"("value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."wk_safe_bigint"("value" "text") RETURNS bigint
    LANGUAGE "plpgsql" STABLE
    AS $$
begin
  if value is null or btrim(value) = '' then return null; end if;
  return value::bigint;
exception when others then
  return null;
end;
$$;


ALTER FUNCTION "public"."wk_safe_bigint"("value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."wk_safe_bool"("value" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    AS $$
begin
  if value is null or btrim(value) = '' then return null; end if;
  return lower(value) in ('1', 'true', 't', 'yes', 'y');
end;
$$;


ALTER FUNCTION "public"."wk_safe_bool"("value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."wk_safe_date"("value" "text") RETURNS "date"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
begin
  if value is null or trim(value) = '' then
    return null;
  end if;

  begin
    return value::date;
  exception when others then
    return null;
  end;
end;
$$;


ALTER FUNCTION "public"."wk_safe_date"("value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."wk_safe_int"("value" "text") RETURNS integer
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
begin
  if value is null or trim(value) = '' then
    return null;
  end if;

  begin
    return value::integer;
  exception when others then
    return null;
  end;
end;
$$;


ALTER FUNCTION "public"."wk_safe_int"("value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."wk_safe_timestamptz"("value" "text") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" STABLE
    AS $$
begin
  if value is null or btrim(value) = '' or value = '0000-00-00 00:00:00' then return null; end if;
  return value::timestamptz;
exception when others then
  return null;
end;
$$;


ALTER FUNCTION "public"."wk_safe_timestamptz"("value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."wk_slug_fallback"("value" "text", "fallback" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $_$
  select lower(
    regexp_replace(
      regexp_replace(
        trim(coalesce(nullif(value, ''), nullif(fallback, ''), 'unknown')),
        '[^a-zA-Z0-9]+',
        '-',
        'g'
      ),
      '(^-|-$)',
      '',
      'g'
    )
  );
$_$;


ALTER FUNCTION "public"."wk_slug_fallback"("value" "text", "fallback" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."wk_slugify"("value" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
select coalesce(nullif(trim(both '-' from regexp_replace(lower(coalesce(value, 'untitled')), '[^a-z0-9]+', '-', 'g')), ''), 'untitled');
$$;


ALTER FUNCTION "public"."wk_slugify"("value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."wk_slugify_text"("p_value" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $_$
  select regexp_replace(
    regexp_replace(
      lower(coalesce(nullif(trim(p_value), ''), '')),
      '[^a-z0-9]+',
      '-',
      'g'
    ),
    '(^-|-$)',
    '',
    'g'
  );
$_$;


ALTER FUNCTION "public"."wk_slugify_text"("p_value" "text") OWNER TO "postgres";


