    CONSTRAINT "correction_applications_summary_check" CHECK (((NULLIF("btrim"("application_summary"), ''::"text") IS NOT NULL) AND ("length"("application_summary") <= 8000))),
    CONSTRAINT "correction_applications_version_identity_check" CHECK ((("expected_published_version_id" = "challenged_version_id") AND ("resulting_version_id" <> "challenged_version_id") AND (("expected_working_version_id" IS NULL) OR ("resulting_version_id" <> "expected_working_version_id")))),
    CONSTRAINT "correction_applications_working_fingerprint_check" CHECK (((("expected_working_version_id" IS NULL) AND ("expected_working_fingerprint" IS NULL)) OR (("expected_working_version_id" IS NOT NULL) AND ("expected_working_fingerprint" ~ '^[0-9a-f]{64}$'::"text"))))
);


