CREATE TABLE IF NOT EXISTS "editorial"."correction_cases" (
    "resource_id" "uuid" NOT NULL,
    "resource_kind" "text" DEFAULT 'correction_case'::"text" NOT NULL,
    "case_number" bigint NOT NULL,
    "origin_type" "text" NOT NULL,
