    "origin_type_snapshot" "text",
    "origin_summary_snapshot" "text" NOT NULL,
    "correction_kind" "text" NOT NULL,
    "priority" "text" DEFAULT 'normal'::"text" NOT NULL,
    "case_state" "text" DEFAULT 'submitted'::"text" NOT NULL,
    "current_revision" bigint DEFAULT 1 NOT NULL,
    "assigned_investigator_id" "uuid",
    "assignment_reason" "text",
    "assigned_at" timestamp with time zone,
    "triage_reason" "text",
    "triaged_by" "uuid",
    "triaged_at" timestamp with time zone,
    "investigation_summary" "text",
    "investigator_recommendation" "text",
    "evidence_ready" boolean DEFAULT false NOT NULL,
    "submitted_for_decision_by" "uuid",
    "submitted_for_decision_at" timestamp with time zone,
    "public_note_disposition" "text",
    "public_note_no_note_reason" "text",
    "closed_reason" "text",
    "closed_by" "uuid",
    "closed_at" timestamp with time zone,
    "created_by" "uuid",
    "updated_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "current_decision_id" "uuid",
    "current_application_id" "uuid",
    "contributor_follow_up_disposition" "text",
    "contributor_follow_up_reason" "text",
    "contributor_follow_up_job_id" "uuid",
    "contributor_follow_up_requested_at" timestamp with time zone,
    CONSTRAINT "correction_cases_assignment_reason_check" CHECK ((("assignment_reason" IS NULL) OR (NULLIF("btrim"("assignment_reason"), ''::"text") IS NOT NULL))),
    CONSTRAINT "correction_cases_closed_reason_check" CHECK ((("closed_reason" IS NULL) OR (NULLIF("btrim"("closed_reason"), ''::"text") IS NOT NULL))),
    CONSTRAINT "correction_cases_contributor_follow_up_contract_check" CHECK (((("origin_type" = 'internal_editorial'::"text") AND ("contributor_follow_up_disposition" IS NULL) AND ("contributor_follow_up_reason" IS NULL) AND ("contributor_follow_up_job_id" IS NULL) AND ("contributor_follow_up_requested_at" IS NULL)) OR (("origin_type" = 'community_contribution'::"text") AND ((("contributor_follow_up_disposition" IS NULL) AND ("contributor_follow_up_reason" IS NULL) AND ("contributor_follow_up_job_id" IS NULL) AND ("contributor_follow_up_requested_at" IS NULL)) OR (("contributor_follow_up_disposition" = 'requested'::"text") AND ("contributor_follow_up_reason" IS NULL) AND ("contributor_follow_up_job_id" IS NOT NULL) AND ("contributor_follow_up_requested_at" IS NOT NULL)) OR (("contributor_follow_up_disposition" = ANY (ARRAY['unavailable'::"text", 'unsafe'::"text"])) AND ("contributor_follow_up_reason" IS NOT NULL) AND ("contributor_follow_up_job_id" IS NULL) AND ("contributor_follow_up_requested_at" IS NULL)))))),
    CONSTRAINT "correction_cases_contributor_follow_up_disposition_check" CHECK ((("contributor_follow_up_disposition" IS NULL) OR ("contributor_follow_up_disposition" = ANY (ARRAY['requested'::"text", 'unavailable'::"text", 'unsafe'::"text"])))),
    CONSTRAINT "correction_cases_contributor_follow_up_reason_check" CHECK ((("contributor_follow_up_reason" IS NULL) OR ((NULLIF("btrim"("contributor_follow_up_reason"), ''::"text") IS NOT NULL) AND ("length"("contributor_follow_up_reason") <= 2000)))),
    CONSTRAINT "correction_cases_investigation_summary_check" CHECK ((("investigation_summary" IS NULL) OR (NULLIF("btrim"("investigation_summary"), ''::"text") IS NOT NULL))),
    CONSTRAINT "correction_cases_origin_contract_check" CHECK (((("origin_type" = 'community_contribution'::"text") AND ("origin_contribution_id" IS NOT NULL) AND ("origin_submitter_user_id" IS NOT NULL) AND ("origin_submitted_at" IS NOT NULL) AND (NULLIF("btrim"("origin_type_snapshot"), ''::"text") IS NOT NULL)) OR (("origin_type" = 'internal_editorial'::"text") AND ("origin_contribution_id" IS NULL) AND ("origin_submitter_user_id" IS NULL) AND ("origin_submitted_at" IS NULL) AND ("created_by" IS NOT NULL)))),
    CONSTRAINT "correction_cases_origin_summary_check" CHECK ((NULLIF("btrim"("origin_summary_snapshot"), ''::"text") IS NOT NULL)),
    CONSTRAINT "correction_cases_origin_type_check" CHECK (("origin_type" = ANY (ARRAY['community_contribution'::"text", 'internal_editorial'::"text"]))),
    CONSTRAINT "correction_cases_origin_type_snapshot_check" CHECK ((("origin_type_snapshot" IS NULL) OR (NULLIF("btrim"("origin_type_snapshot"), ''::"text") IS NOT NULL))),
    CONSTRAINT "correction_cases_priority_check" CHECK (("priority" = ANY (ARRAY['low'::"text", 'normal'::"text", 'high'::"text", 'urgent'::"text"]))),
    CONSTRAINT "correction_cases_public_note_contract_check" CHECK (((("public_note_disposition" IS NULL) AND ("public_note_no_note_reason" IS NULL)) OR (("public_note_disposition" = 'published'::"text") AND ("public_note_no_note_reason" IS NULL)) OR (("public_note_disposition" = 'not_required'::"text") AND (NULLIF("btrim"("public_note_no_note_reason"), ''::"text") IS NOT NULL) AND ("length"("public_note_no_note_reason") <= 2000)))),
    CONSTRAINT "correction_cases_recommendation_check" CHECK ((("investigator_recommendation" IS NULL) OR (NULLIF("btrim"("investigator_recommendation"), ''::"text") IS NOT NULL))),
    CONSTRAINT "correction_cases_resource_kind_check" CHECK (("resource_kind" = 'correction_case'::"text")),
    CONSTRAINT "correction_cases_revision_check" CHECK (("current_revision" >= 1)),
    CONSTRAINT "correction_cases_state_check" CHECK (("case_state" = ANY (ARRAY['submitted'::"text", 'triaged'::"text", 'investigating'::"text", 'awaiting_decision'::"text", 'decided'::"text", 'applied'::"text", 'closed'::"text"]))),
    CONSTRAINT "correction_cases_triage_reason_check" CHECK ((("triage_reason" IS NULL) OR (NULLIF("btrim"("triage_reason"), ''::"text") IS NOT NULL)))
);


