CREATE TABLE IF NOT EXISTS "editorial"."correction_decisions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "case_resource_id" "uuid" NOT NULL,
    "decision_number" bigint NOT NULL,
    "outcome" "text" NOT NULL,
    "reason" "text" NOT NULL,
    "private_analysis" "text",
    "public_safe_explanation" "text",
    "case_revision_observed" bigint NOT NULL,
    "target_state_observed" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "duplicate_of_case_resource_id" "uuid",
    "supersedes_decision_id" "uuid",
    "decided_by" "uuid" NOT NULL,
    "correlation_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "correction_decisions_duplicate_contract_check" CHECK (((("outcome" = 'duplicate'::"text") AND ("duplicate_of_case_resource_id" IS NOT NULL) AND ("duplicate_of_case_resource_id" <> "case_resource_id")) OR (("outcome" <> 'duplicate'::"text") AND ("duplicate_of_case_resource_id" IS NULL)))),
    CONSTRAINT "correction_decisions_number_check" CHECK (("decision_number" >= 1)),
    CONSTRAINT "correction_decisions_outcome_check" CHECK (("outcome" = ANY (ARRAY['correction_required'::"text", 'no_change_required'::"text", 'insufficient_evidence'::"text", 'duplicate'::"text", 'out_of_scope'::"text"]))),
    CONSTRAINT "correction_decisions_private_analysis_check" CHECK ((("private_analysis" IS NULL) OR ("length"("private_analysis") <= 16000))),
    CONSTRAINT "correction_decisions_public_explanation_check" CHECK ((("public_safe_explanation" IS NULL) OR ("length"("public_safe_explanation") <= 8000))),
    CONSTRAINT "correction_decisions_reason_check" CHECK (((NULLIF("btrim"("reason"), ''::"text") IS NOT NULL) AND ("length"("reason") <= 8000))),
    CONSTRAINT "correction_decisions_revision_check" CHECK (("case_revision_observed" >= 1)),
    CONSTRAINT "correction_decisions_supersedes_self_check" CHECK ((("supersedes_decision_id" IS NULL) OR ("supersedes_decision_id" <> "id"))),
    CONSTRAINT "correction_decisions_target_state_check" CHECK ((("jsonb_typeof"("target_state_observed") = 'object'::"text") AND ("octet_length"(("target_state_observed")::"text") <= 32768)))
);


