    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "correction_events_creation_contract_check" CHECK (((("event_type" = 'case_created'::"text") AND ("event_number" = 1) AND ("case_revision_before" = 1) AND ("case_revision_after" = 1) AND ("prior_state" IS NULL) AND ("resulting_state" = 'submitted'::"text") AND ("actor_id" IS NOT NULL)) OR (("event_type" <> 'case_created'::"text") AND ("event_number" > 1)))),
    CONSTRAINT "correction_events_metadata_check" CHECK ((("jsonb_typeof"("metadata") = 'object'::"text") AND ("octet_length"(("metadata")::"text") <= 32768))),
    CONSTRAINT "correction_events_number_check" CHECK (("event_number" >= 1)),
    CONSTRAINT "correction_events_prior_state_check" CHECK ((("prior_state" IS NULL) OR ("prior_state" = ANY (ARRAY['submitted'::"text", 'triaged'::"text", 'investigating'::"text", 'awaiting_decision'::"text", 'decided'::"text", 'applied'::"text", 'closed'::"text"])))),
    CONSTRAINT "correction_events_reason_check" CHECK ((("reason" IS NULL) OR (NULLIF("btrim"("reason"), ''::"text") IS NOT NULL))),
    CONSTRAINT "correction_events_resulting_state_check" CHECK ((("resulting_state" IS NULL) OR ("resulting_state" = ANY (ARRAY['submitted'::"text", 'triaged'::"text", 'investigating'::"text", 'awaiting_decision'::"text", 'decided'::"text", 'applied'::"text", 'closed'::"text"])))),
    CONSTRAINT "correction_events_revision_check" CHECK ((("case_revision_before" >= 1) AND (("case_revision_after" = "case_revision_before") OR ("case_revision_after" = ("case_revision_before" + 1)))))
);


