    "replacement_alias_id" "uuid",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "resource_aliases_active_canonical_check" CHECK (((NOT "is_canonical") OR ("retired_at" IS NULL))),
    CONSTRAINT "resource_aliases_path_leading_slash_check" CHECK (("path" ~~ '/%'::"text")),
    CONSTRAINT "resource_aliases_path_lowercase_check" CHECK (("path" = "lower"("path"))),
    CONSTRAINT "resource_aliases_path_no_double_slash_check" CHECK (("path" !~ '//'::"text")),
    CONSTRAINT "resource_aliases_path_no_query_check" CHECK (((POSITION(('?'::"text") IN ("path")) = 0) AND (POSITION(('#'::"text") IN ("path")) = 0))),
    CONSTRAINT "resource_aliases_path_no_trailing_slash_check" CHECK ((("path" = '/'::"text") OR ("right"("path", 1) <> '/'::"text"))),
    CONSTRAINT "resource_aliases_redirect_status_check" CHECK (("redirect_status" = ANY (ARRAY[301, 308]))),
    CONSTRAINT "resource_aliases_replacement_check" CHECK ((("replacement_alias_id" IS NULL) OR ("replacement_alias_id" <> "id")))
);


