    CONSTRAINT "resource_citations_target_type_check" CHECK (((("resource_kind" = 'article'::"text") AND ("target_version_type" = 'article_version'::"text")) OR (("resource_kind" = ANY (ARRAY['playlist'::"text", 'playlist_item'::"text"])) AND ("target_version_type" = 'playlist_version'::"text"))))
);


