CREATE TABLE IF NOT EXISTS "editorial"."sources" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "source_type" "text" NOT NULL,
    "title" "text" NOT NULL,
    "creator_display" "text",
    "publisher_display" "text",
    "source_url" "text",
    "media_asset_id" "uuid",
    "archive_identifier" "text",
    "publication_date" "date",
    "capture_date" "date",
    "retrieval_date" "date",
    "language_code" "text",
    "country_code" "text",
    "place_text" "text",
    "rights_status" "text" DEFAULT 'unknown'::"text" NOT NULL,
    "consent_status" "text" DEFAULT 'unknown'::"text" NOT NULL,
    "sensitivity" "text" DEFAULT 'none'::"text" NOT NULL,
    "reliability_note" "text",
    "credit_line" "text",
    "internal_notes" "text",
    "review_status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "exposure_class" "text" DEFAULT 'internal'::"text" NOT NULL,
    "source_state" "text" DEFAULT 'active'::"text" NOT NULL,
    "current_working_version_id" "uuid",
    "current_submitted_version_id" "uuid",
    "current_approved_version_id" "uuid",
    "working_revision" bigint DEFAULT 1 NOT NULL,
    "created_by" "uuid",
    "updated_by" "uuid",
    "reviewed_by" "uuid",
    "reviewed_at" timestamp with time zone,
    "withdrawn_by" "uuid",
    "withdrawn_at" timestamp with time zone,
    "withdrawal_reason" "text",
    "withdrawal_public_mode" "text" DEFAULT 'hide_public_reference'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "sources_consent_status_check" CHECK (("consent_status" = ANY (ARRAY['unknown'::"text", 'not_required'::"text", 'requested'::"text", 'granted'::"text", 'limited'::"text", 'declined'::"text", 'withdrawn'::"text"]))),
    CONSTRAINT "sources_exposure_class_check" CHECK (("exposure_class" = ANY (ARRAY['public'::"text", 'public_redacted'::"text", 'internal'::"text", 'restricted'::"text", 'confidential'::"text"]))),
    CONSTRAINT "sources_review_exposure_check" CHECK ((("review_status" = 'approved'::"text") OR ("exposure_class" <> ALL (ARRAY['public'::"text", 'public_redacted'::"text"])))),
    CONSTRAINT "sources_review_status_check" CHECK (("review_status" = ANY (ARRAY['draft'::"text", 'ready_for_review'::"text", 'in_review'::"text", 'changes_requested'::"text", 'approved'::"text", 'rejected'::"text"]))),
    CONSTRAINT "sources_rights_status_check" CHECK (("rights_status" = ANY (ARRAY['unknown'::"text", 'owned'::"text", 'licensed'::"text", 'public_domain'::"text", 'fair_use'::"text", 'needs_clearance'::"text", 'restricted'::"text"]))),
    CONSTRAINT "sources_sensitivity_check" CHECK (("sensitivity" = ANY (ARRAY['none'::"text", 'low'::"text", 'moderate'::"text", 'high'::"text", 'extreme'::"text"]))),
    CONSTRAINT "sources_source_state_check" CHECK (("source_state" = ANY (ARRAY['active'::"text", 'withdrawn'::"text", 'archived'::"text"]))),
    CONSTRAINT "sources_title_check" CHECK ((NULLIF("btrim"("title"), ''::"text") IS NOT NULL)),
    CONSTRAINT "sources_withdrawal_public_mode_check" CHECK (("withdrawal_public_mode" = ANY (ARRAY['retain_public_reference'::"text", 'redact_public_reference'::"text", 'hide_public_reference'::"text"]))),
    CONSTRAINT "sources_withdrawal_state_check" CHECK (((("source_state" = 'withdrawn'::"text") AND ("withdrawn_by" IS NOT NULL) AND ("withdrawn_at" IS NOT NULL) AND (NULLIF("btrim"("withdrawal_reason"), ''::"text") IS NOT NULL)) OR (("source_state" <> 'withdrawn'::"text") AND ("withdrawn_by" IS NULL) AND ("withdrawn_at" IS NULL) AND ("withdrawal_reason" IS NULL)))),
    CONSTRAINT "sources_working_revision_check" CHECK (("working_revision" >= 1))
);


