CREATE TABLE IF NOT EXISTS "media"."asset_governance_versions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "asset_id" "uuid" NOT NULL,
    "version_number" bigint NOT NULL,
    "rights_status" "text" DEFAULT 'unknown'::"text" NOT NULL,
    "rights_basis" "text",
    "rights_holder" "text",
    "licence_identifier" "text",
    "licence_terms" "text",
    "consent_status" "text" DEFAULT 'unknown'::"text" NOT NULL,
    "consent_scope" "text",
    "sensitivity" "text" DEFAULT 'none'::"text" NOT NULL,
    "embargo_state" "text" DEFAULT 'none'::"text" NOT NULL,
    "embargo_until" timestamp with time zone,
    "source_protection_class" "text" DEFAULT 'internal'::"text" NOT NULL,
    "preservation_state" "text" DEFAULT 'unassessed'::"text" NOT NULL,
    "retention_state" "text" DEFAULT 'retain'::"text" NOT NULL,
    "public_safety_state" "text" DEFAULT 'internal'::"text" NOT NULL,
    "internal_reason" "text",
    "approved_by" "uuid",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "asset_governance_versions_confidential_check" CHECK ((("source_protection_class" <> 'confidential'::"text") OR ("public_safety_state" <> ALL (ARRAY['approved_public'::"text", 'approved_redacted'::"text"])))),
    CONSTRAINT "asset_governance_versions_consent_status_check" CHECK (("consent_status" = ANY (ARRAY['unknown'::"text", 'not_required'::"text", 'requested'::"text", 'granted'::"text", 'limited'::"text", 'declined'::"text", 'withdrawn'::"text"]))),
    CONSTRAINT "asset_governance_versions_embargo_state_check" CHECK (("embargo_state" = ANY (ARRAY['none'::"text", 'scheduled'::"text", 'active'::"text", 'released'::"text"]))),
    CONSTRAINT "asset_governance_versions_embargo_time_check" CHECK ((("embargo_state" <> ALL (ARRAY['scheduled'::"text", 'active'::"text"])) OR ("embargo_until" IS NOT NULL))),
    CONSTRAINT "asset_governance_versions_number_check" CHECK (("version_number" >= 1)),
    CONSTRAINT "asset_governance_versions_preservation_state_check" CHECK (("preservation_state" = ANY (ARRAY['unassessed'::"text", 'working_copy'::"text", 'preservation_candidate'::"text", 'preserved'::"text", 'at_risk'::"text", 'lost'::"text"]))),
    CONSTRAINT "asset_governance_versions_public_consent_check" CHECK ((("public_safety_state" <> ALL (ARRAY['approved_public'::"text", 'approved_redacted'::"text"])) OR ("consent_status" = ANY (ARRAY['granted'::"text", 'not_required'::"text"])))),
    CONSTRAINT "asset_governance_versions_public_rights_check" CHECK ((("public_safety_state" <> ALL (ARRAY['approved_public'::"text", 'approved_redacted'::"text"])) OR ("rights_status" <> 'restricted'::"text"))),
    CONSTRAINT "asset_governance_versions_public_safety_check" CHECK (("public_safety_state" = ANY (ARRAY['internal'::"text", 'review_required'::"text", 'approved_public'::"text", 'approved_redacted'::"text", 'blocked'::"text"]))),
    CONSTRAINT "asset_governance_versions_retention_state_check" CHECK (("retention_state" = ANY (ARRAY['retain'::"text", 'review_required'::"text", 'purge_requested'::"text", 'purge_approved'::"text", 'purged'::"text"]))),
    CONSTRAINT "asset_governance_versions_rights_status_check" CHECK (("rights_status" = ANY (ARRAY['unknown'::"text", 'owned'::"text", 'licensed'::"text", 'public_domain'::"text", 'fair_use'::"text", 'needs_clearance'::"text", 'restricted'::"text"]))),
    CONSTRAINT "asset_governance_versions_sensitivity_check" CHECK (("sensitivity" = ANY (ARRAY['none'::"text", 'low'::"text", 'moderate'::"text", 'high'::"text", 'extreme'::"text"]))),
    CONSTRAINT "asset_governance_versions_source_protection_check" CHECK (("source_protection_class" = ANY (ARRAY['public'::"text", 'public_redacted'::"text", 'internal'::"text", 'restricted'::"text", 'confidential'::"text"])))
);


