    CONSTRAINT "file_objects_verification_integrity_check" CHECK (((("verification_state" = 'unverified'::"text") AND ("verified_by" IS NULL) AND ("verified_at" IS NULL) AND ("verification_error" IS NULL)) OR (("verification_state" = 'verified'::"text") AND ("sha256" IS NOT NULL) AND ("byte_size" IS NOT NULL) AND (NULLIF("btrim"("mime_type"), ''::"text") IS NOT NULL) AND ("storage_path" IS NOT NULL) AND ("verified_by" IS NOT NULL) AND ("verified_at" IS NOT NULL) AND ("verification_error" IS NULL)) OR (("verification_state" = ANY (ARRAY['failed'::"text", 'unreachable'::"text"])) AND (NULLIF("btrim"("verification_error"), ''::"text") IS NOT NULL) AND ((("verified_by" IS NULL) AND ("verified_at" IS NULL)) OR (("verified_by" IS NOT NULL) AND ("verified_at" IS NOT NULL)))))),
    CONSTRAINT "file_objects_verification_state_check" CHECK (("verification_state" = ANY (ARRAY['unverified'::"text", 'verified'::"text", 'failed'::"text", 'unreachable'::"text"])))
