CREATE TABLE IF NOT EXISTS "media"."upload_sessions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "actor_id" "uuid" NOT NULL,
    "idempotency_key" "text" NOT NULL,
    "state" "text" DEFAULT 'created'::"text" NOT NULL,
    "storage_provider" "text" DEFAULT 'lightsail_media'::"text" NOT NULL,
    "storage_namespace" "text" DEFAULT 'lightsail-media'::"text" NOT NULL,
    "storage_path" "text" NOT NULL,
    "original_filename" "text" NOT NULL,
    "file_extension" "text" NOT NULL,
    "mime_type" "text" NOT NULL,
    "expected_byte_size" bigint NOT NULL,
    "expected_sha256" "text" NOT NULL,
    "part_size_bytes" integer NOT NULL,
    "total_parts" integer NOT NULL,
    "expires_at" timestamp with time zone NOT NULL,
    "verified_byte_size" bigint,
    "verified_sha256" "text",
    "verified_at" timestamp with time zone,
    "file_object_id" "uuid",
    "correlation_id" "uuid" NOT NULL,
    "last_error" "text",
    "cancelled_at" timestamp with time zone,
    "expired_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "upload_sessions_expiry_check" CHECK (("expires_at" > "created_at")),
    CONSTRAINT "upload_sessions_extension_check" CHECK (("file_extension" = ANY (ARRAY['mp3'::"text", 'm4a'::"text", 'aac'::"text", 'wav'::"text", 'flac'::"text", 'ogg'::"text", 'oga'::"text", 'mp4'::"text", 'mov'::"text", 'm4v'::"text", 'webm'::"text", 'mkv'::"text"]))),
    CONSTRAINT "upload_sessions_filename_check" CHECK ((NULLIF("btrim"("original_filename"), ''::"text") IS NOT NULL)),
    CONSTRAINT "upload_sessions_idempotency_check" CHECK (("idempotency_key" ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,127}$'::"text")),
    CONSTRAINT "upload_sessions_mime_check" CHECK ((("mime_type" = "lower"("mime_type")) AND (("mime_type" ~~ 'audio/%'::"text") OR ("mime_type" ~~ 'video/%'::"text")))),
    CONSTRAINT "upload_sessions_namespace_check" CHECK (("storage_namespace" = 'lightsail-media'::"text")),
    CONSTRAINT "upload_sessions_part_size_check" CHECK ((("part_size_bytes" >= 1048576) AND ("part_size_bytes" <= 16777216))),
    CONSTRAINT "upload_sessions_path_check" CHECK (("storage_path" ~ '^masters/(audio|video)/[0-9]{4}/[0-9]{2}/[0-9a-f-]{36}\.[a-z0-9]{2,5}$'::"text")),
    CONSTRAINT "upload_sessions_provider_check" CHECK (("storage_provider" = 'lightsail_media'::"text")),
    CONSTRAINT "upload_sessions_sha_check" CHECK (("expected_sha256" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "upload_sessions_size_check" CHECK ((("expected_byte_size" > 0) AND ("expected_byte_size" <= '2147483648'::bigint))),
    CONSTRAINT "upload_sessions_state_check" CHECK (("state" = ANY (ARRAY['created'::"text", 'verified'::"text", 'failed'::"text", 'cancelled'::"text", 'expired'::"text"]))),
    CONSTRAINT "upload_sessions_total_parts_check" CHECK (("total_parts" >= 1)),
    CONSTRAINT "upload_sessions_verified_integrity_check" CHECK (((("state" = 'verified'::"text") AND ("verified_byte_size" = "expected_byte_size") AND ("verified_sha256" = "expected_sha256") AND ("verified_at" IS NOT NULL) AND ("file_object_id" IS NOT NULL) AND ("last_error" IS NULL) AND ("cancelled_at" IS NULL) AND ("expired_at" IS NULL)) OR (("state" = 'failed'::"text") AND (NULLIF("btrim"("last_error"), ''::"text") IS NOT NULL) AND ("verified_byte_size" IS NULL) AND ("verified_sha256" IS NULL) AND ("file_object_id" IS NULL) AND ("verified_at" IS NULL) AND ("cancelled_at" IS NULL) AND ("expired_at" IS NULL)) OR (("state" = 'cancelled'::"text") AND (NULLIF("btrim"("last_error"), ''::"text") IS NOT NULL) AND ("cancelled_at" IS NOT NULL) AND ("verified_byte_size" IS NULL) AND ("verified_sha256" IS NULL) AND ("file_object_id" IS NULL) AND ("verified_at" IS NULL) AND ("expired_at" IS NULL)) OR (("state" = 'expired'::"text") AND ("expired_at" IS NOT NULL) AND (NULLIF("btrim"("last_error"), ''::"text") IS NOT NULL) AND ("verified_byte_size" IS NULL) AND ("verified_sha256" IS NULL) AND ("file_object_id" IS NULL) AND ("verified_at" IS NULL) AND ("cancelled_at" IS NULL)) OR (("state" = 'created'::"text") AND ("last_error" IS NULL) AND ("verified_byte_size" IS NULL) AND ("verified_sha256" IS NULL) AND ("file_object_id" IS NULL) AND ("verified_at" IS NULL) AND ("cancelled_at" IS NULL) AND ("expired_at" IS NULL))))
);


