    CONSTRAINT "command_receipts_result_payload_check" CHECK ((("jsonb_typeof"("result_payload") = 'object'::"text") AND ("octet_length"(("result_payload")::"text") <= 32768))),
    CONSTRAINT "command_receipts_status_check" CHECK (("status" = ANY (ARRAY['accepted'::"text", 'succeeded'::"text", 'failed'::"text", 'rejected'::"text"])))
);


