CREATE TABLE IF NOT EXISTS "platform_private"."jobs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "command_receipt_id" "uuid" NOT NULL,
    "resource_id" "uuid" NOT NULL,
    "command_type" "text" NOT NULL,
    "job_key" "text" NOT NULL,
    "job_type" "text" NOT NULL,
    "status" "text" DEFAULT 'queued'::"text" NOT NULL,
    "priority" smallint DEFAULT 100 NOT NULL,
    "available_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "attempt_count" integer DEFAULT 0 NOT NULL,
    "max_attempts" integer DEFAULT 5 NOT NULL,
    "locked_by" "text",
    "locked_at" timestamp with time zone,
    "lease_expires_at" timestamp with time zone,
    "input_payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "result_payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "last_error" "text",
    "started_at" timestamp with time zone,
    "finished_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "jobs_attempt_count_check" CHECK ((("attempt_count" >= 0) AND (("max_attempts" >= 1) AND ("max_attempts" <= 25)) AND ("attempt_count" <= "max_attempts"))),
    CONSTRAINT "jobs_input_payload_check" CHECK ((("jsonb_typeof"("input_payload") = 'object'::"text") AND ("octet_length"(("input_payload")::"text") <= 65536))),
    CONSTRAINT "jobs_job_key_check" CHECK (("job_key" ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'::"text")),
    CONSTRAINT "jobs_lease_check" CHECK (((("locked_by" IS NULL) AND ("locked_at" IS NULL) AND ("lease_expires_at" IS NULL)) OR (("locked_by" IS NOT NULL) AND ("locked_at" IS NOT NULL) AND ("lease_expires_at" IS NOT NULL) AND ("lease_expires_at" > "locked_at")))),
    CONSTRAINT "jobs_priority_check" CHECK ((("priority" >= 1) AND ("priority" <= 1000))),
    CONSTRAINT "jobs_result_payload_check" CHECK ((("jsonb_typeof"("result_payload") = 'object'::"text") AND ("octet_length"(("result_payload")::"text") <= 65536))),
    CONSTRAINT "jobs_status_check" CHECK (("status" = ANY (ARRAY['queued'::"text", 'running'::"text", 'retry_wait'::"text", 'succeeded'::"text", 'dead_letter'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "jobs_terminal_time_check" CHECK (((("status" = ANY (ARRAY['succeeded'::"text", 'dead_letter'::"text", 'cancelled'::"text"])) AND ("finished_at" IS NOT NULL)) OR (("status" = ANY (ARRAY['queued'::"text", 'running'::"text", 'retry_wait'::"text"])) AND ("finished_at" IS NULL)))),
    CONSTRAINT "jobs_worker_identity_check" CHECK ((("locked_by" IS NULL) OR ("locked_by" ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{2,127}$'::"text")))
);


