CREATE TABLE IF NOT EXISTS "platform_private"."outbox_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "event_key" "text" NOT NULL,
    "command_receipt_id" "uuid" NOT NULL,
    "job_id" "uuid",
    "command_type" "text" NOT NULL,
    "aggregate_type" "text" DEFAULT 'resource'::"text" NOT NULL,
    "aggregate_id" "uuid" NOT NULL,
    "event_type" "text" NOT NULL,
    "event_version" integer DEFAULT 1 NOT NULL,
    "payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "headers" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "available_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "attempt_count" integer DEFAULT 0 NOT NULL,
    "max_attempts" integer DEFAULT 10 NOT NULL,
    "claimed_by" "text",
    "claimed_at" timestamp with time zone,
    "lease_expires_at" timestamp with time zone,
    "published_at" timestamp with time zone,
    "last_error" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "outbox_events_aggregate_type_check" CHECK (("aggregate_type" = 'resource'::"text")),
    CONSTRAINT "outbox_events_attempt_count_check" CHECK ((("attempt_count" >= 0) AND (("max_attempts" >= 1) AND ("max_attempts" <= 50)) AND ("attempt_count" <= "max_attempts"))),
    CONSTRAINT "outbox_events_claim_identity_check" CHECK ((("claimed_by" IS NULL) OR ("claimed_by" ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{2,127}$'::"text"))),
    CONSTRAINT "outbox_events_event_key_check" CHECK (("event_key" ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,255}$'::"text")),
    CONSTRAINT "outbox_events_event_type_check" CHECK (("event_type" ~ '^[a-z][a-z0-9_.]*$'::"text")),
    CONSTRAINT "outbox_events_event_version_check" CHECK ((("event_version" >= 1) AND ("event_version" <= 100))),
    CONSTRAINT "outbox_events_headers_check" CHECK ((("jsonb_typeof"("headers") = 'object'::"text") AND ("octet_length"(("headers")::"text") <= 16384))),
    CONSTRAINT "outbox_events_lease_check" CHECK (((("claimed_by" IS NULL) AND ("claimed_at" IS NULL) AND ("lease_expires_at" IS NULL)) OR (("claimed_by" IS NOT NULL) AND ("claimed_at" IS NOT NULL) AND ("lease_expires_at" IS NOT NULL) AND ("lease_expires_at" > "claimed_at")))),
    CONSTRAINT "outbox_events_payload_check" CHECK ((("jsonb_typeof"("payload") = 'object'::"text") AND ("octet_length"(("payload")::"text") <= 65536))),
    CONSTRAINT "outbox_events_publication_check" CHECK (((("status" = 'published'::"text") AND ("published_at" IS NOT NULL)) OR (("status" <> 'published'::"text") AND ("published_at" IS NULL)))),
    CONSTRAINT "outbox_events_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'claimed'::"text", 'retry_wait'::"text", 'published'::"text", 'dead_letter'::"text"])))
);


