CREATE TABLE IF NOT EXISTS "public"."artist_claim_evidence" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "claim_id" "uuid" NOT NULL,
    "evidence_type" "text" NOT NULL,
    "reference" "text",
    "note" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "artist_claim_evidence_evidence_type_check" CHECK (("evidence_type" = ANY (ARRAY['official_website'::"text", 'official_social'::"text", 'business_email'::"text", 'label_or_distributor'::"text", 'public_announcement'::"text", 'other'::"text"]))),
    CONSTRAINT "artist_claim_evidence_has_content" CHECK (((NULLIF(TRIM(BOTH FROM COALESCE("reference", ''::"text")), ''::"text") IS NOT NULL) OR (NULLIF(TRIM(BOTH FROM COALESCE("note", ''::"text")), ''::"text") IS NOT NULL))),
    CONSTRAINT "artist_claim_evidence_note_length" CHECK ((("note" IS NULL) OR ("char_length"("note") <= 2000))),
    CONSTRAINT "artist_claim_evidence_reference_length" CHECK ((("reference" IS NULL) OR ("char_length"("reference") <= 2048)))
);


ALTER TABLE "public"."artist_claim_evidence" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."artist_claim_requests" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "artist_id" "uuid" NOT NULL,
    "claimant_user_id" "uuid",
    "claimant_role" "text" NOT NULL,
