    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "artist_claim_decision_consistency" CHECK (((("status" = 'pending'::"text") AND ("decided_at" IS NULL) AND ("decided_by" IS NULL)) OR (("status" = ANY (ARRAY['verified'::"text", 'rejected'::"text", 'revoked'::"text"])) AND ("decided_at" IS NOT NULL) AND ("decision_reason" IS NOT NULL)) OR ("status" = 'withdrawn'::"text"))),
    CONSTRAINT "artist_claim_requests_claimant_role_check" CHECK (("claimant_role" = ANY (ARRAY['artist'::"text", 'manager'::"text", 'label'::"text", 'publicist'::"text", 'team_member'::"text", 'other'::"text"]))),
    CONSTRAINT "artist_claim_requests_statement_check" CHECK ((("char_length"("statement") >= 10) AND ("char_length"("statement") <= 4000))),
    CONSTRAINT "artist_claim_requests_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'verified'::"text", 'rejected'::"text", 'withdrawn'::"text", 'revoked'::"text"])))
);


ALTER TABLE "public"."artist_claim_requests" OWNER TO "postgres";


