CREATE TABLE IF NOT EXISTS "public"."audience_interests" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "subscriber_id" "uuid" NOT NULL,
    "entity_type" "text" NOT NULL,
    "entity_slug" "text" NOT NULL,
    "entity_name" "text",
    "entity_id" "uuid",
    "interest_kind" "text" DEFAULT 'follow'::"text" NOT NULL,
    "source_form" "text" DEFAULT 'unknown'::"text" NOT NULL,
    "source_page" "text",
    "source_context" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "interest_strength" integer DEFAULT 1 NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "first_seen_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "last_seen_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "audience_interests_entity_type_check" CHECK (("entity_type" = ANY (ARRAY['artist'::"text", 'track'::"text", 'release'::"text", 'guide'::"text", 'chart'::"text", 'genre'::"text", 'label'::"text", 'article'::"text", 'briefing'::"text"]))),
    CONSTRAINT "audience_interests_interest_kind_check" CHECK (("interest_kind" = ANY (ARRAY['follow'::"text", 'subscribe'::"text", 'download'::"text", 'save'::"text", 'click'::"text", 'read'::"text", 'manual'::"text"]))),
    CONSTRAINT "audience_interests_interest_strength_check" CHECK ((("interest_strength" >= 1) AND ("interest_strength" <= 100))),
    CONSTRAINT "audience_interests_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'suppressed'::"text", 'unsubscribed'::"text"])))
);


ALTER TABLE "public"."audience_interests" OWNER TO "postgres";


COMMENT ON TABLE "public"."audience_interests" IS 'Normalized audience interests attached to briefing subscribers. Used for fan/artist/topic segmentation without scraping raw form JSON.';



COMMENT ON COLUMN "public"."audience_interests"."entity_type" IS 'Audience entity type: artist, track, release, guide, chart, genre, label, article, or briefing.';



COMMENT ON COLUMN "public"."audience_interests"."entity_slug" IS 'Stable public slug for targeting, e.g. v-be for /artists/v-be.';



COMMENT ON COLUMN "public"."audience_interests"."interest_strength" IS '1 to 100 score. Future forms can score stronger actions like follow/download higher than passive clicks.';



