    CONSTRAINT "surface_draft_has_scope" CHECK ((("inquiry_id" IS NOT NULL) OR ("entity_id" IS NOT NULL))),
    CONSTRAINT "surface_drafts_review_status_check" CHECK (("review_status" = ANY (ARRAY['draft'::"text", 'pending_review'::"text", 'approved'::"text", 'rejected'::"text", 'revised'::"text"]))),
    CONSTRAINT "surface_drafts_surface_type_check" CHECK (("surface_type" = ANY (ARRAY['artist_orientation'::"text", 'start_here'::"text", 'relationship_reason'::"text", 'community_question'::"text"])))
);


ALTER TABLE "public"."surface_drafts" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."institute_review_queue_items" WITH ("security_invoker"='true') AS
 SELECT 'evidence'::"text" AS "subject_type",
    "evidence_items"."id" AS "subject_id",
    "evidence_items"."title",
    "evidence_items"."summary",
    "evidence_items"."review_status",
        CASE
            WHEN ("evidence_items"."review_status" = 'unreviewed'::"text") THEN 'Needs first review'::"text"
            WHEN ("evidence_items"."review_status" = 'disputed'::"text") THEN 'Disputed evidence needs review'::"text"
            WHEN ("evidence_items"."retrieval_status" = 'review_only'::"text") THEN 'Review-only evidence needs retrieval decision'::"text"
            ELSE 'Evidence needs review'::"text"
        END AS "review_reason",
        CASE
            WHEN ("evidence_items"."review_status" = 'disputed'::"text") THEN 90
            WHEN ("evidence_items"."review_status" = 'unreviewed'::"text") THEN 70
            WHEN ("evidence_items"."retrieval_status" = 'review_only'::"text") THEN 60
            ELSE 40
        END AS "priority_weight",
    NULL::"uuid" AS "inquiry_id",
    NULL::"uuid" AS "entity_id",
    "evidence_items"."created_by" AS "submitted_by",
    "evidence_items"."created_at",
    "evidence_items"."updated_at",
    "jsonb_build_object"('evidence_type', "evidence_items"."evidence_type", 'retrieval_status', "evidence_items"."retrieval_status", 'confidence', "evidence_items"."confidence", 'reliability', "evidence_items"."reliability") AS "metadata"
   FROM "public"."evidence_items"
  WHERE (("evidence_items"."review_status" = ANY (ARRAY['unreviewed'::"text", 'disputed'::"text"])) OR ("evidence_items"."retrieval_status" = 'review_only'::"text"))
UNION ALL
 SELECT 'relationship'::"text" AS "subject_type",
    "entity_relationships"."id" AS "subject_id",
    "concat"("entity_relationships"."relationship_type", ': ', COALESCE("source_entity"."name", 'Unknown source'::"text"), ' → ', COALESCE("target_entity"."name", 'Unknown target'::"text")) AS "title",
    "entity_relationships"."reason" AS "summary",
    "entity_relationships"."review_status",
        CASE
            WHEN ("entity_relationships"."review_status" = 'suggested'::"text") THEN 'Suggested relationship needs review'::"text"
            WHEN ("entity_relationships"."review_status" = 'pending_review'::"text") THEN 'Relationship is pending review'::"text"
            WHEN ("entity_relationships"."review_status" = 'disputed'::"text") THEN 'Disputed relationship needs review'::"text"
            WHEN (("entity_relationships"."review_status" = 'approved'::"text") AND ("entity_relationships"."public_safe" = false)) THEN 'Approved relationship needs public-safe decision'::"text"
            ELSE 'Relationship needs review'::"text"
        END AS "review_reason",
        CASE
            WHEN ("entity_relationships"."review_status" = 'disputed'::"text") THEN 90
            WHEN ("entity_relationships"."review_status" = 'pending_review'::"text") THEN 75
            WHEN ("entity_relationships"."review_status" = 'suggested'::"text") THEN 65
            WHEN (("entity_relationships"."review_status" = 'approved'::"text") AND ("entity_relationships"."public_safe" = false)) THEN 55
            ELSE 40
        END AS "priority_weight",
    NULL::"uuid" AS "inquiry_id",
    "entity_relationships"."source_entity_id" AS "entity_id",
    "entity_relationships"."created_by" AS "submitted_by",
    "entity_relationships"."created_at",
    "entity_relationships"."updated_at",
    "jsonb_build_object"('relationship_type', "entity_relationships"."relationship_type", 'confidence', "entity_relationships"."confidence", 'public_safe', "entity_relationships"."public_safe", 'source_entity_id', "entity_relationships"."source_entity_id", 'target_entity_id', "entity_relationships"."target_entity_id") AS "metadata"
   FROM (("public"."entity_relationships"
     LEFT JOIN "public"."cultural_entities" "source_entity" ON (("source_entity"."id" = "entity_relationships"."source_entity_id")))
     LEFT JOIN "public"."cultural_entities" "target_entity" ON (("target_entity"."id" = "entity_relationships"."target_entity_id")))
  WHERE (("entity_relationships"."review_status" = ANY (ARRAY['suggested'::"text", 'pending_review'::"text", 'disputed'::"text"])) OR (("entity_relationships"."review_status" = 'approved'::"text") AND ("entity_relationships"."public_safe" = false)))
UNION ALL
 SELECT 'contributor_submission'::"text" AS "subject_type",
    "contributor_submissions"."id" AS "subject_id",
    COALESCE("contributor_submissions"."title", "concat"('Contributor ', "contributor_submissions"."submission_type")) AS "title",
    "contributor_submissions"."body" AS "summary",
    "contributor_submissions"."review_status",
        CASE
            WHEN ("contributor_submissions"."review_status" = 'submitted'::"text") THEN 'New contributor submission'::"text"
            WHEN ("contributor_submissions"."review_status" = 'triaged'::"text") THEN 'Triaged submission needs next step'::"text"
            WHEN ("contributor_submissions"."review_status" = 'needs_source'::"text") THEN 'Submission needs source review'::"text"
            WHEN ("contributor_submissions"."review_status" = 'needs_clarification'::"text") THEN 'Submission needs clarification'::"text"
            ELSE 'Contributor submission needs review'::"text"
        END AS "review_reason",
        CASE
            WHEN ("contributor_submissions"."review_status" = 'needs_clarification'::"text") THEN 85
            WHEN ("contributor_submissions"."review_status" = 'needs_source'::"text") THEN 80
            WHEN ("contributor_submissions"."review_status" = 'submitted'::"text") THEN 70
            WHEN ("contributor_submissions"."review_status" = 'triaged'::"text") THEN 60
            ELSE 40
        END AS "priority_weight",
    "contributor_submissions"."inquiry_id",
    "contributor_submissions"."entity_id",
    "contributors"."user_id" AS "submitted_by",
    "contributor_submissions"."created_at",
    "contributor_submissions"."updated_at",
    "jsonb_build_object"('submission_type', "contributor_submissions"."submission_type", 'consent_status', "contributor_submissions"."consent_status", 'contributor_id', "contributor_submissions"."contributor_id") AS "metadata"
   FROM ("public"."contributor_submissions"
     LEFT JOIN "public"."contributors" ON (("contributors"."id" = "contributor_submissions"."contributor_id")))
  WHERE ("contributor_submissions"."review_status" = ANY (ARRAY['submitted'::"text", 'triaged'::"text", 'needs_source'::"text", 'needs_clarification'::"text"]))
UNION ALL
 SELECT 'surface_draft'::"text" AS "subject_type",
    "surface_drafts"."id" AS "subject_id",
    COALESCE("surface_drafts"."draft_title", "concat"('Surface draft: ', "surface_drafts"."surface_type")) AS "title",
    "surface_drafts"."draft_body" AS "summary",
    "surface_drafts"."review_status",
        CASE
            WHEN ("surface_drafts"."review_status" = 'pending_review'::"text") THEN 'Surface draft is pending review'::"text"
            WHEN ("surface_drafts"."review_status" = 'draft'::"text") THEN 'Surface draft needs editorial review'::"text"
            WHEN ("surface_drafts"."review_status" = 'revised'::"text") THEN 'Revised draft needs review'::"text"
            WHEN (("surface_drafts"."review_status" = 'approved'::"text") AND ("surface_drafts"."public_safe" = false)) THEN 'Approved draft needs public-safe decision'::"text"
            ELSE 'Surface draft needs review'::"text"
        END AS "review_reason",
        CASE
            WHEN ("surface_drafts"."review_status" = 'pending_review'::"text") THEN 80
            WHEN ("surface_drafts"."review_status" = 'revised'::"text") THEN 70
            WHEN ("surface_drafts"."review_status" = 'draft'::"text") THEN 50
            WHEN (("surface_drafts"."review_status" = 'approved'::"text") AND ("surface_drafts"."public_safe" = false)) THEN 55
            ELSE 40
        END AS "priority_weight",
    "surface_drafts"."inquiry_id",
    "surface_drafts"."entity_id",
    "surface_drafts"."created_by" AS "submitted_by",
    "surface_drafts"."created_at",
    "surface_drafts"."updated_at",
    "jsonb_build_object"('surface_type', "surface_drafts"."surface_type", 'public_safe', "surface_drafts"."public_safe", 'ai_run_id', "surface_drafts"."ai_run_id") AS "metadata"
   FROM "public"."surface_drafts"
  WHERE (("surface_drafts"."review_status" = ANY (ARRAY['draft'::"text", 'pending_review'::"text", 'revised'::"text"])) OR (("surface_drafts"."review_status" = 'approved'::"text") AND ("surface_drafts"."public_safe" = false)))
UNION ALL
 SELECT 'correction'::"text" AS "subject_type",
    "corrections"."id" AS "subject_id",
    "concat"('Correction: ', "corrections"."subject_type") AS "title",
    "corrections"."correction_text" AS "summary",
    "corrections"."correction_status" AS "review_status",
        CASE
            WHEN ("corrections"."correction_status" = 'submitted'::"text") THEN 'New correction needs review'::"text"
            WHEN ("corrections"."correction_status" = 'unresolved'::"text") THEN 'Unresolved correction needs decision'::"text"
            ELSE 'Correction needs review'::"text"
        END AS "review_reason",
        CASE
            WHEN ("corrections"."correction_status" = 'unresolved'::"text") THEN 85
            WHEN ("corrections"."correction_status" = 'submitted'::"text") THEN 75
            ELSE 40
        END AS "priority_weight",
    NULL::"uuid" AS "inquiry_id",
        CASE
            WHEN ("corrections"."subject_type" = 'entity'::"text") THEN "corrections"."subject_id"
            ELSE NULL::"uuid"
        END AS "entity_id",
    "corrections"."submitted_by",
    "corrections"."created_at",
    "corrections"."created_at" AS "updated_at",
    "jsonb_build_object"('correction_subject_type', "corrections"."subject_type", 'correction_subject_id', "corrections"."subject_id") AS "metadata"
   FROM "public"."corrections"
  WHERE ("corrections"."correction_status" = ANY (ARRAY['submitted'::"text", 'unresolved'::"text"]));


ALTER VIEW "public"."institute_review_queue_items" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."institute_admin_overview_counts" WITH ("security_invoker"='true') AS
 SELECT 'review_queue_items'::"text" AS "metric_key",
    "count"(*) AS "metric_value",
    "now"() AS "measured_at"
   FROM "public"."institute_review_queue_items"
UNION ALL
 SELECT 'active_inquiries'::"text" AS "metric_key",
    "count"(*) AS "metric_value",
    "now"() AS "measured_at"
   FROM "public"."inquiries"
  WHERE ("inquiries"."status" = ANY (ARRAY['open'::"text", 'active'::"text"]))
UNION ALL
 SELECT 'retrieval_ready_evidence'::"text" AS "metric_key",
    "count"(*) AS "metric_value",
    "now"() AS "measured_at"
   FROM "public"."evidence_items"
  WHERE (("evidence_items"."review_status" = ANY (ARRAY['reviewed'::"text", 'approved'::"text"])) AND ("evidence_items"."retrieval_status" = 'default_retrieval'::"text"))
UNION ALL
 SELECT 'approved_relationships'::"text" AS "metric_key",
    "count"(*) AS "metric_value",
    "now"() AS "measured_at"
   FROM "public"."entity_relationships"
  WHERE ("entity_relationships"."review_status" = 'approved'::"text")
UNION ALL
 SELECT 'pending_contributor_submissions'::"text" AS "metric_key",
    "count"(*) AS "metric_value",
    "now"() AS "measured_at"
   FROM "public"."contributor_submissions"
  WHERE ("contributor_submissions"."review_status" = ANY (ARRAY['submitted'::"text", 'triaged'::"text", 'needs_source'::"text", 'needs_clarification'::"text"]));


ALTER VIEW "public"."institute_admin_overview_counts" OWNER TO "postgres";


