CREATE TABLE IF NOT EXISTS "public"."institute_question_versions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "inquiry_id" "uuid" NOT NULL,
    "version_number" integer NOT NULL,
