    CONSTRAINT "institute_relationships_target_entity_label_check" CHECK (("length"(TRIM(BOTH FROM "target_entity_label")) > 0)),
    CONSTRAINT "institute_relationships_target_entity_type_check" CHECK (("target_entity_type" = ANY (ARRAY['artist'::"text", 'track'::"text", 'release'::"text", 'label'::"text", 'genre'::"text", 'scene'::"text", 'place'::"text", 'event'::"text", 'institution'::"text", 'person'::"text", 'work'::"text", 'contributor_memory'::"text", 'evidence_item'::"text", 'claim'::"text", 'inquiry'::"text"])))
