CREATE OR REPLACE VIEW "public"."registry_entity_index" WITH ("security_invoker"='true') AS
 SELECT "a"."id" AS "entity_id",
    'artist'::"text" AS "entity_type",
    "a"."display_name" AS "name",
    "a"."slug",
    "a"."bio" AS "description",
    "a"."status",
    'registry_artists'::"text" AS "canonical_source_table",
    "a"."id" AS "canonical_source_id",
    ("a"."status" = 'active'::"text") AS "public_safe",
    'authoritative'::"text" AS "review_status"
   FROM "public"."registry_artists" "a"
UNION ALL
 SELECT "t"."id" AS "entity_id",
    'track'::"text" AS "entity_type",
    "t"."title" AS "name",
    "t"."slug",
    NULL::"text" AS "description",
    "t"."status",
    'registry_tracks'::"text" AS "canonical_source_table",
    "t"."id" AS "canonical_source_id",
    ("t"."status" = 'active'::"text") AS "public_safe",
    'authoritative'::"text" AS "review_status"
   FROM "public"."registry_tracks" "t"
UNION ALL
 SELECT "r"."id" AS "entity_id",
    'release'::"text" AS "entity_type",
    "r"."title" AS "name",
    "r"."slug",
    "r"."description",
    "r"."status",
    'registry_releases'::"text" AS "canonical_source_table",
    "r"."id" AS "canonical_source_id",
    ("r"."status" = 'active'::"text") AS "public_safe",
    'authoritative'::"text" AS "review_status"
   FROM "public"."registry_releases" "r"
UNION ALL
 SELECT "l"."id" AS "entity_id",
    'label'::"text" AS "entity_type",
    "l"."name",
    "l"."slug",
    "l"."description",
    "l"."status",
    'registry_labels'::"text" AS "canonical_source_table",
    "l"."id" AS "canonical_source_id",
    ("l"."status" = 'active'::"text") AS "public_safe",
    'authoritative'::"text" AS "review_status"
   FROM "public"."registry_labels" "l"
UNION ALL
 SELECT "g"."id" AS "entity_id",
    'genre'::"text" AS "entity_type",
    "g"."name",
    "g"."slug",
    "g"."description",
    "g"."status",
    'registry_genres'::"text" AS "canonical_source_table",
    "g"."id" AS "canonical_source_id",
    ("g"."status" = 'active'::"text") AS "public_safe",
    'authoritative'::"text" AS "review_status"
   FROM "public"."registry_genres" "g"
UNION ALL
 SELECT "c"."id" AS "entity_id",
    "c"."entity_type",
    "c"."name",
    "c"."slug",
    "c"."description",
    "c"."status",
    COALESCE("c"."canonical_source_table", 'cultural_entities'::"text") AS "canonical_source_table",
    COALESCE("c"."canonical_source_id", "c"."id") AS "canonical_source_id",
    "c"."public_safe",
    "c"."review_status"
   FROM "public"."cultural_entities" "c"
  WHERE ("c"."status" <> 'merged'::"text");


ALTER VIEW "public"."registry_entity_index" OWNER TO "postgres";


COMMENT ON VIEW "public"."registry_entity_index" IS 'Canonical read index across music Registry entities and broader reviewed cultural entities. Source tables remain authoritative.';



