    CONSTRAINT "registry_media_assets_file_kind_check" CHECK ((("file_kind" IS NULL) OR ("file_kind" = ANY (ARRAY['image'::"text", 'document'::"text", 'audio'::"text", 'video'::"text", 'archive'::"text", 'transcript'::"text", 'caption'::"text", 'other'::"text"])))),
    CONSTRAINT "registry_media_assets_file_size_bytes_check" CHECK ((("file_size_bytes" IS NULL) OR ("file_size_bytes" >= 0))),
    CONSTRAINT "registry_media_assets_rights_status_check" CHECK (("rights_status" = ANY (ARRAY['unknown'::"text", 'owned'::"text", 'licensed'::"text", 'public_domain'::"text", 'fair_use'::"text", 'needs_clearance'::"text", 'restricted'::"text"]))),
    CONSTRAINT "registry_media_assets_slug_not_blank" CHECK (("btrim"("slug") <> ''::"text")),
    CONSTRAINT "registry_media_assets_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'needs_review'::"text", 'archived'::"text"]))),
