COMMENT ON COLUMN "public"."registry_media_assets"."storage_bucket" IS 'Supabase Storage bucket name (e.g. article-media, cms-media)';



COMMENT ON COLUMN "public"."registry_media_assets"."storage_path" IS 'Path within the storage bucket (e.g. uploads/1781796140917-wrqg4o.jpg)';



COMMENT ON COLUMN "public"."registry_media_assets"."folder_id" IS 'Logical admin folder. Moving folders must not break public file URLs.';



COMMENT ON COLUMN "public"."registry_media_assets"."file_kind" IS 'Broad file class used for filtering: image, document, audio, video, archive, other.';



COMMENT ON COLUMN "public"."registry_media_assets"."asset_purpose" IS 'Editorial/admin purpose such as article_hero, chart_artwork, artist_photo, downloadable, press_kit.';



COMMENT ON COLUMN "public"."registry_media_assets"."content_date" IS 'The date the asset is culturally/editorially about, separate from upload date.';



COMMENT ON COLUMN "public"."registry_media_assets"."tags" IS 'Admin search tags for media discoverability.';



COMMENT ON CONSTRAINT "registry_media_assets_asset_purpose_check" ON "public"."registry_media_assets" IS 'Legacy Media compatibility projection mirrors enabled canonical Media purposes, including playlist_cover.';



CREATE OR REPLACE VIEW "public"."registry_missing_artist_latest_submission" WITH ("security_invoker"='true') AS
 SELECT DISTINCT ON (("split_part"("source_note", ' '::"text", 1))) "split_part"("split_part"("source_note", ' '::"text", 1), ':'::"text", 2) AS "legacy_slug",
    "id" AS "submission_id",
    "review_status" AS "submission_review_status",
    "created_at" AS "submission_created_at",
    "reviewed_at" AS "submission_reviewed_at"
   FROM "public"."contributor_submissions"
  WHERE ("source_note" ~~ 'missing_artist_slug:%'::"text")
  ORDER BY ("split_part"("source_note", ' '::"text", 1)), "created_at" DESC;


ALTER VIEW "public"."registry_missing_artist_latest_submission" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."registry_unresolved_relationship_endpoints" WITH ("security_invoker"='true') AS
 SELECT "id" AS "relationship_id",
        CASE
            WHEN ("source_entity_id" IS NULL) THEN 'source'::"text"
            ELSE 'target'::"text"
        END AS "missing_side",
        CASE
            WHEN ("source_entity_id" IS NULL) THEN "source_entity_type"
            ELSE "target_entity_type"
        END AS "missing_entity_type",
        CASE
            WHEN ("source_entity_id" IS NULL) THEN "source_slug"
            ELSE "target_slug"
        END AS "legacy_slug",
    "relationship_type",
    "relationship_role",
    "source_entity_id",
    "target_entity_id"
   FROM "public"."registry_entity_relationships"
  WHERE (("relationship_status" <> 'archived'::"text") AND (("source_entity_id" IS NULL) OR ("target_entity_id" IS NULL)));


ALTER VIEW "public"."registry_unresolved_relationship_endpoints" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."registry_relationship_endpoint_work_queue" WITH ("security_invoker"='true') AS
 SELECT "u"."relationship_id",
    "u"."missing_side",
    "u"."missing_entity_type",
    "u"."legacy_slug",
    "u"."relationship_type",
    "u"."relationship_role",
    "u"."source_entity_id",
    "u"."target_entity_id",
    ("count"("a"."canonical_artist_id"))::integer AS "alias_match_count",
    ("min"(("a"."canonical_artist_id")::"text"))::"uuid" AS "alias_candidate_id",
        CASE
            WHEN ("count"("a"."canonical_artist_id") = 1) THEN 'ready_to_resolve'::"text"
            WHEN ("count"("a"."canonical_artist_id") > 1) THEN 'ambiguous_alias'::"text"
            ELSE 'missing_entity'::"text"
        END AS "endpoint_work_state"
   FROM ("public"."registry_unresolved_relationship_endpoints" "u"
     LEFT JOIN "public"."registry_artist_aliases" "a" ON ((("u"."missing_entity_type" = 'artist'::"text") AND ("a"."alias_slug" = "u"."legacy_slug") AND (COALESCE("a"."status", 'active'::"text") <> 'rejected'::"text"))))
  GROUP BY "u"."relationship_id", "u"."missing_side", "u"."missing_entity_type", "u"."legacy_slug", "u"."relationship_type", "u"."relationship_role", "u"."source_entity_id", "u"."target_entity_id";


ALTER VIEW "public"."registry_relationship_endpoint_work_queue" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."registry_missing_artist_intake_queue" WITH ("security_invoker"='true') AS
 WITH "missing" AS (
         SELECT "registry_relationship_endpoint_work_queue"."legacy_slug",
            ("count"(DISTINCT "registry_relationship_endpoint_work_queue"."relationship_id"))::integer AS "affected_relationship_count",
            ("count"(*) FILTER (WHERE ("registry_relationship_endpoint_work_queue"."missing_side" = 'source'::"text")))::integer AS "missing_source_count",
            ("count"(*) FILTER (WHERE ("registry_relationship_endpoint_work_queue"."missing_side" = 'target'::"text")))::integer AS "missing_target_count",
            "array_agg"(DISTINCT "registry_relationship_endpoint_work_queue"."relationship_type" ORDER BY "registry_relationship_endpoint_work_queue"."relationship_type") AS "relationship_types"
           FROM "public"."registry_relationship_endpoint_work_queue"
          WHERE (("registry_relationship_endpoint_work_queue"."endpoint_work_state" = 'missing_entity'::"text") AND ("registry_relationship_endpoint_work_queue"."missing_entity_type" = 'artist'::"text"))
          GROUP BY "registry_relationship_endpoint_work_queue"."legacy_slug"
        )
 SELECT "m"."legacy_slug",
    "initcap"("replace"("m"."legacy_slug", '-'::"text", ' '::"text")) AS "suggested_display_name",
    "m"."affected_relationship_count",
    "m"."missing_source_count",
    "m"."missing_target_count",
    "m"."relationship_types",
    "s"."submission_id",
    "s"."submission_review_status",
    "s"."submission_created_at",
    "s"."submission_reviewed_at",
        CASE
            WHEN ("s"."submission_id" IS NULL) THEN 'needs_intake'::"text"
            WHEN ("s"."submission_review_status" = ANY (ARRAY['rejected'::"text", 'archived'::"text", 'merged'::"text"])) THEN 'needs_reassessment'::"text"
            WHEN ("s"."submission_review_status" = ANY (ARRAY['accepted_as_memory'::"text", 'accepted_as_evidence'::"text", 'accepted_as_relationship_context'::"text"])) THEN 'review_completed'::"text"
            ELSE 'intake_in_progress'::"text"
        END AS "intake_state"
   FROM ("missing" "m"
     LEFT JOIN "public"."registry_missing_artist_latest_submission" "s" USING ("legacy_slug"));


ALTER VIEW "public"."registry_missing_artist_intake_queue" OWNER TO "postgres";


