    CONSTRAINT "registry_provider_track_suggestion_artists_name_check" CHECK ((("length"("btrim"("observed_name")) >= 1) AND ("length"("btrim"("observed_name")) <= 300))),
    CONSTRAINT "registry_provider_track_suggestion_artists_order_check" CHECK (("credit_order" > 0)),
    CONSTRAINT "registry_provider_track_suggestion_artists_resolution_check" CHECK (((("resolution_mode" = ANY (ARRAY['existing_artist'::"text", 'alias_candidate'::"text"])) AND ("registry_artist_id" IS NOT NULL)) OR (("resolution_mode" = ANY (ARRAY['new_artist'::"text", 'unresolved'::"text"])) AND ("registry_artist_id" IS NULL)))),
    CONSTRAINT "registry_provider_track_suggestion_artists_role_check" CHECK (("credit_role" = ANY (ARRAY['primary'::"text", 'featured'::"text", 'unresolved'::"text"])))
);


ALTER TABLE "public"."registry_provider_track_suggestion_artists" OWNER TO "postgres";


