CREATE TABLE IF NOT EXISTS "public"."registry_provider_track_suggestions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "source_playlist_id" "uuid",
    "source_playlist_item_id" "uuid",
    "requested_by" "uuid",
    "canonical_track_id" "uuid",
    "registry_artist_id" "uuid",
    "artist_resolution_mode" "text" DEFAULT 'unresolved'::"text" NOT NULL,
    "provider_key" "text",
    "provider_object_id" "text",
    "provider_url" "text",
    "provider_title" "text",
    "provider_artist_names" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "provider_release_title" "text",
    "playback_kind" "text",
    "validation_snapshot" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "status" "text" DEFAULT 'needs_review'::"text" NOT NULL,
    "canonicalized_track_id" "uuid",
    "reviewed_by" "uuid",
    "reviewed_at" timestamp with time zone,
    "review_note" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "reserved_position" integer,
    "playlist_note" "text",
    "intake_origin" "text" DEFAULT 'playlist_editor'::"text" NOT NULL,
    "source_contribution_id" "uuid",
    "submitted_track_title" "text",
    "submitted_for_artist_id" "uuid",
    "submitted_by_representation_id" "uuid",
    "review_due_at" timestamp with time zone,
    "artist_submission_key" "text",
    "source_artist_validation_id" "uuid",
    CONSTRAINT "registry_provider_track_suggestions_artist_mode_check" CHECK (("artist_resolution_mode" = ANY (ARRAY['existing_track'::"text", 'existing_artist'::"text", 'alias_candidate'::"text", 'new_artist'::"text", 'unresolved'::"text"]))),
    CONSTRAINT "registry_provider_track_suggestions_artist_submission_context_c" CHECK (((("intake_origin" = 'artist_submission'::"text") AND ("source_playlist_id" IS NULL) AND ("source_playlist_item_id" IS NULL) AND ("source_contribution_id" IS NULL) AND ("reserved_position" IS NULL) AND ("submitted_for_artist_id" IS NOT NULL) AND ("submitted_by_representation_id" IS NOT NULL) AND ("review_due_at" IS NOT NULL) AND ("source_artist_validation_id" IS NOT NULL) AND (NULLIF("btrim"("artist_submission_key"), ''::"text") IS NOT NULL) AND ("length"("artist_submission_key") <= 200)) OR (("intake_origin" <> 'artist_submission'::"text") AND ("submitted_for_artist_id" IS NULL) AND ("submitted_by_representation_id" IS NULL) AND ("review_due_at" IS NULL) AND ("source_artist_validation_id" IS NULL) AND ("artist_submission_key" IS NULL)))),
    CONSTRAINT "registry_provider_track_suggestions_artist_submission_due_check" CHECK ((("review_due_at" IS NULL) OR ("review_due_at" > "created_at"))),
    CONSTRAINT "registry_provider_track_suggestions_contribution_origin_check" CHECK ((("intake_origin" = 'public_contribution'::"text") OR ("source_contribution_id" IS NULL))),
    CONSTRAINT "registry_provider_track_suggestions_intake_origin_check" CHECK (("intake_origin" = ANY (ARRAY['playlist_editor'::"text", 'public_contribution'::"text", 'artist_submission'::"text"]))),
    CONSTRAINT "registry_provider_track_suggestions_pending_slot_check" CHECK (((NOT (("status" = 'needs_review'::"text") AND ("source_playlist_item_id" IS NULL) AND ("canonical_track_id" IS NULL))) OR ("intake_origin" = ANY (ARRAY['public_contribution'::"text", 'artist_submission'::"text"])) OR ("reserved_position" IS NOT NULL))),
    CONSTRAINT "registry_provider_track_suggestions_playback_kind_check" CHECK (("playback_kind" = ANY (ARRAY['audio'::"text", 'video'::"text"]))),
    CONSTRAINT "registry_provider_track_suggestions_playlist_note_check" CHECK ((("playlist_note" IS NULL) OR ("length"("playlist_note") <= 10000))),
    CONSTRAINT "registry_provider_track_suggestions_provider_evidence_check" CHECK (((("intake_origin" = 'playlist_editor'::"text") AND ("provider_key" IS NOT NULL) AND ("provider_object_id" IS NOT NULL) AND ("provider_url" IS NOT NULL) AND ("playback_kind" IS NOT NULL)) OR (("intake_origin" = 'public_contribution'::"text") AND ((("provider_key" IS NULL) AND ("provider_object_id" IS NULL) AND ("provider_url" IS NULL) AND ("playback_kind" IS NULL)) OR (("provider_key" IS NOT NULL) AND ("provider_object_id" IS NOT NULL) AND ("provider_url" IS NOT NULL) AND ("playback_kind" IS NOT NULL)))) OR (("intake_origin" = 'artist_submission'::"text") AND ("provider_key" IS NOT NULL) AND ("provider_object_id" IS NOT NULL) AND ("provider_url" IS NOT NULL) AND ("playback_kind" IS NOT NULL)))),
    CONSTRAINT "registry_provider_track_suggestions_public_title_check" CHECK ((("intake_origin" <> ALL (ARRAY['public_contribution'::"text", 'artist_submission'::"text"])) OR (NULLIF("btrim"("submitted_track_title"), ''::"text") IS NOT NULL))),
    CONSTRAINT "registry_provider_track_suggestions_reserved_position_check" CHECK ((("reserved_position" IS NULL) OR ("reserved_position" > 0))),
    CONSTRAINT "registry_provider_track_suggestions_snapshot_check" CHECK (("jsonb_typeof"("validation_snapshot") = 'object'::"text")),
    CONSTRAINT "registry_provider_track_suggestions_status_check" CHECK (("status" = ANY (ARRAY['needs_review'::"text", 'accepted'::"text", 'rejected'::"text", 'canonicalized'::"text"])))
);


ALTER TABLE "public"."registry_provider_track_suggestions" OWNER TO "postgres";


COMMENT ON TABLE "public"."registry_provider_track_suggestions" IS 'Registry-owned intake queue for provider evidence surfaced by Playlist editors. Suggestions are not canonical Registry identity.';



COMMENT ON COLUMN "public"."registry_provider_track_suggestions"."playlist_note" IS 'Mutable Playlist curator note retained while Registry identity is pending. It is carried into the canonical Playlist item when Registry resolves the track.';



COMMENT ON COLUMN "public"."registry_provider_track_suggestions"."intake_origin" IS 'Distinguishes editor-decided Playlist intake from public contributions that require Registry review without Playlist insertion.';



COMMENT ON COLUMN "public"."registry_provider_track_suggestions"."source_contribution_id" IS 'Optional Community contribution that supplied public missing-track evidence.';



COMMENT ON COLUMN "public"."registry_provider_track_suggestions"."submitted_track_title" IS 'Contributor-supplied track title preserved separately from provider-observed title evidence.';



CREATE OR REPLACE VIEW "public"."registry_relationship_duplicate_keys" AS
SELECT
    NULL::"uuid" AS "relationship_id",
    NULL::"text" AS "source_entity_type",
    NULL::"uuid" AS "source_entity_id",
    NULL::"text" AS "source_slug",
    NULL::"text" AS "source_comparison_key",
    NULL::"text" AS "target_entity_type",
    NULL::"uuid" AS "target_entity_id",
    NULL::"text" AS "target_slug",
    NULL::"text" AS "target_comparison_key",
    NULL::"text" AS "relationship_type",
    NULL::"text" AS "relationship_role",
    NULL::"text" AS "relationship_status",
    NULL::"text" AS "review_status",
    NULL::boolean AS "public_safe",
    NULL::"text" AS "plain_reason",
    NULL::integer AS "evidence_count";


ALTER VIEW "public"."registry_relationship_duplicate_keys" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."registry_relationship_consolidation_queue" WITH ("security_invoker"='true') AS
 WITH "classified" AS (
         SELECT "k"."relationship_id",
            "k"."source_entity_type",
            "k"."source_entity_id",
            "k"."source_slug",
            "k"."source_comparison_key",
            "k"."target_entity_type",
            "k"."target_entity_id",
            "k"."target_slug",
            "k"."target_comparison_key",
            "k"."relationship_type",
            "k"."relationship_role",
            "k"."relationship_status",
            "k"."review_status",
            "k"."public_safe",
            "k"."plain_reason",
            "k"."evidence_count",
            ("count"(*) OVER (PARTITION BY "k"."source_entity_type", "k"."source_comparison_key", "k"."target_entity_type", "k"."target_comparison_key", "k"."relationship_type", COALESCE("k"."relationship_role", ''::"text")))::integer AS "duplicate_group_size"
           FROM "public"."registry_relationship_duplicate_keys" "k"
          WHERE ("k"."relationship_status" <> 'archived'::"text")
        )
 SELECT "relationship_id",
    "source_entity_type",
    "source_entity_id",
    "source_slug",
    "source_comparison_key",
    "target_entity_type",
    "target_entity_id",
    "target_slug",
    "target_comparison_key",
    "relationship_type",
    "relationship_role",
    "relationship_status",
    "review_status",
    "public_safe",
    "plain_reason",
    "evidence_count",
        CASE
            WHEN (("source_entity_id" IS NULL) OR ("target_entity_id" IS NULL)) THEN 'resolve_endpoints'::"text"
            WHEN ("evidence_count" = 0) THEN 'attach_evidence'::"text"
            WHEN (NULLIF("btrim"("plain_reason"), ''::"text") IS NULL) THEN 'add_plain_reason'::"text"
            WHEN ("review_status" = ANY (ARRAY['unreviewed'::"text", 'pending_review'::"text", 'disputed'::"text"])) THEN 'review_required'::"text"
            WHEN (("review_status" = 'approved'::"text") AND ("public_safe" = false)) THEN 'publication_review'::"text"
            ELSE 'ready'::"text"
        END AS "consolidation_state",
    ("relationship_type" = ANY (ARRAY['features'::"text", 'featured_on'::"text", 'collaboration'::"text", 'popular_track'::"text"])) AS "vocabulary_supported",
    "duplicate_group_size",
    ("duplicate_group_size" > 1) AS "duplicate_candidate"
   FROM "classified";


ALTER VIEW "public"."registry_relationship_consolidation_queue" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."registry_relationship_endpoint_resolution_queue" WITH ("security_invoker"='true') AS
 SELECT "r"."id" AS "relationship_id",
    'source'::"text" AS "endpoint_side",
    "r"."source_entity_type" AS "legacy_entity_type",
    "r"."source_slug" AS "legacy_slug",
    "r"."source_entity_id" AS "current_entity_id",
        CASE
            WHEN ("r"."source_entity_id" IS NOT NULL) THEN 'resolved'::"text"
            WHEN ("r"."source_entity_type" = ANY (ARRAY['chart_entries'::"text", 'media_assets'::"text"])) THEN 'provenance_only'::"text"
            WHEN ("x"."match_count" = 0) THEN 'unresolved'::"text"
            WHEN ("x"."match_count" = 1) THEN 'unique_candidate'::"text"
            ELSE 'ambiguous'::"text"
        END AS "resolution_state",
    "x"."match_count",
    "x"."candidate_entity_id",
    "x"."candidate_entity_type",
    "x"."candidate_slug"
   FROM ("public"."registry_entity_relationships" "r"
     LEFT JOIN LATERAL ( SELECT ("count"(*))::integer AS "match_count",
            ("min"(("i"."entity_id")::"text"))::"uuid" AS "candidate_entity_id",
            "min"("i"."entity_type") AS "candidate_entity_type",
            "min"("i"."slug") AS "candidate_slug"
           FROM "public"."registry_entity_index" "i"
          WHERE (("i"."entity_type" = "r"."source_entity_type") AND ("i"."slug" = "r"."source_slug"))) "x" ON (true))
UNION ALL
 SELECT "r"."id" AS "relationship_id",
    'target'::"text" AS "endpoint_side",
    "r"."target_entity_type" AS "legacy_entity_type",
    "r"."target_slug" AS "legacy_slug",
    "r"."target_entity_id" AS "current_entity_id",
        CASE
            WHEN ("r"."target_entity_id" IS NOT NULL) THEN 'resolved'::"text"
            WHEN ("r"."target_entity_type" = ANY (ARRAY['chart_entries'::"text", 'media_assets'::"text"])) THEN 'provenance_only'::"text"
            WHEN ("x"."match_count" = 0) THEN 'unresolved'::"text"
            WHEN ("x"."match_count" = 1) THEN 'unique_candidate'::"text"
            ELSE 'ambiguous'::"text"
        END AS "resolution_state",
    "x"."match_count",
    "x"."candidate_entity_id",
    "x"."candidate_entity_type",
    "x"."candidate_slug"
   FROM ("public"."registry_entity_relationships" "r"
     LEFT JOIN LATERAL ( SELECT ("count"(*))::integer AS "match_count",
            ("min"(("i"."entity_id")::"text"))::"uuid" AS "candidate_entity_id",
            "min"("i"."entity_type") AS "candidate_entity_type",
            "min"("i"."slug") AS "candidate_slug"
           FROM "public"."registry_entity_index" "i"
          WHERE (("i"."entity_type" = "r"."target_entity_type") AND ("i"."slug" = "r"."target_slug"))) "x" ON (true));


ALTER VIEW "public"."registry_relationship_endpoint_resolution_queue" OWNER TO "postgres";


COMMENT ON VIEW "public"."registry_relationship_endpoint_resolution_queue" IS 'Read-only queue classifying canonical, provenance-only, unresolved, and ambiguous legacy relationship endpoints.';



