CREATE OR REPLACE VIEW "public"."registry_release_tracklists" WITH ("security_invoker"='true') AS
 WITH "release_rows" AS (
         SELECT COALESCE(NULLIF(("to_jsonb"("r".*) ->> 'slug'::"text"), ''::"text"), NULLIF(("to_jsonb"("r".*) ->> 'source_slug'::"text"), ''::"text"), NULLIF((("to_jsonb"("r".*) -> 'mapped_record'::"text") ->> 'slug'::"text"), ''::"text"), NULLIF((("to_jsonb"("r".*) -> 'raw_record'::"text") ->> 'post_name'::"text"), ''::"text")) AS "release_slug",
            COALESCE(NULLIF(("to_jsonb"("r".*) ->> 'title'::"text"), ''::"text"), NULLIF(("to_jsonb"("r".*) ->> 'name'::"text"), ''::"text"), NULLIF((("to_jsonb"("r".*) -> 'mapped_record'::"text") ->> 'title'::"text"), ''::"text"), NULLIF((("to_jsonb"("r".*) -> 'raw_record'::"text") ->> 'post_title'::"text"), ''::"text")) AS "release_title",
            "to_jsonb"("r".*) AS "release_record"
           FROM "public"."registry_releases" "r"
        ), "track_rows" AS (
         SELECT COALESCE(NULLIF(("to_jsonb"("t".*) ->> 'slug'::"text"), ''::"text"), NULLIF(("to_jsonb"("t".*) ->> 'source_slug'::"text"), ''::"text"), NULLIF((("to_jsonb"("t".*) -> 'mapped_record'::"text") ->> 'slug'::"text"), ''::"text"), NULLIF((("to_jsonb"("t".*) -> 'raw_record'::"text") ->> 'post_name'::"text"), ''::"text")) AS "track_slug",
            COALESCE(NULLIF(("to_jsonb"("t".*) ->> 'title'::"text"), ''::"text"), NULLIF(("to_jsonb"("t".*) ->> 'name'::"text"), ''::"text"), NULLIF((("to_jsonb"("t".*) -> 'mapped_record'::"text") ->> 'title'::"text"), ''::"text"), NULLIF((("to_jsonb"("t".*) -> 'raw_record'::"text") ->> 'post_title'::"text"), ''::"text")) AS "track_title",
            "to_jsonb"("t".*) AS "track_record"
           FROM "public"."registry_tracks" "t"
        )
 SELECT "rr"."release_slug",
    "rr"."release_title",
    ("count"("tr"."track_slug"))::integer AS "track_count",
    "jsonb_agg"("jsonb_build_object"('slug', "tr"."track_slug", 'title', "tr"."track_title", 'sort_order', "rel"."sort_order", 'relationship_type', "rel"."relationship_type", 'relationship_role', "rel"."relationship_role", 'record', "tr"."track_record") ORDER BY "rel"."sort_order", "tr"."track_title", "tr"."track_slug") FILTER (WHERE ("tr"."track_slug" IS NOT NULL)) AS "tracks"
   FROM (("release_rows" "rr"
     LEFT JOIN "public"."registry_entity_relationships" "rel" ON ((("rel"."target_slug" = "rr"."release_slug") AND ("rel"."relationship_type" = 'track_release'::"text") AND ("rel"."relationship_role" = 'tracklist_item'::"text") AND ("rel"."source_entity_type" = 'tracks'::"text") AND ("rel"."target_entity_type" = 'releases'::"text") AND (COALESCE("rel"."relationship_status", 'active'::"text") = 'active'::"text"))))
     LEFT JOIN "track_rows" "tr" ON (("tr"."track_slug" = "rel"."source_slug")))
  GROUP BY "rr"."release_slug", "rr"."release_title";


ALTER VIEW "public"."registry_release_tracklists" OWNER TO "postgres";


