CREATE OR REPLACE VIEW "public"."wk_guides" WITH ("security_invoker"='true') AS
 SELECT "slug",
    "title",
    COALESCE("excerpt", "dek", ''::"text") AS "excerpt",
    'publish'::"text" AS "wp_status",
    COALESCE("published_at", "created_at") AS "created_at",
    "id",
    "source_wp_post_id",
    "content",
    "updated_at",
    "hero_url",
    "download_url",
    "download_label",
    COALESCE("downloadables", '[]'::"jsonb") AS "downloadables",
    COALESCE("metadata", '{}'::"jsonb") AS "metadata"
   FROM "public"."guides" "g"
  WHERE (("status" = 'published'::"text") AND (("metadata" ->> 'post_type'::"text") = 'wk_field_guide'::"text"));


