    "removed_by" "uuid",
    CONSTRAINT "wk_playlist_items_duration_ms_check" CHECK ((("duration_ms" IS NULL) OR ("duration_ms" > 0))),
    CONSTRAINT "wk_playlist_items_lifecycle_integrity_check" CHECK (((("lifecycle_state" = 'active'::"text") AND ("position" IS NOT NULL) AND ("position" > 0) AND ("removed_at" IS NULL) AND ("removed_by" IS NULL)) OR (("lifecycle_state" = 'removed'::"text") AND ("position" IS NULL) AND ("removed_at" IS NOT NULL)))),
    CONSTRAINT "wk_playlist_items_lifecycle_state_check" CHECK (("lifecycle_state" = ANY (ARRAY['active'::"text", 'removed'::"text"]))),
    CONSTRAINT "wk_playlist_items_match_confidence_check" CHECK ((("match_confidence" IS NULL) OR (("match_confidence" >= (0)::numeric) AND ("match_confidence" <= (1)::numeric)))),
    CONSTRAINT "wk_playlist_items_match_status_check" CHECK (("match_status" = ANY (ARRAY['matched'::"text", 'external_only'::"text", 'missing_registry_track'::"text", 'needs_review'::"text", 'rejected'::"text", 'pending'::"text"]))),
    CONSTRAINT "wk_playlist_items_provider_key_check" CHECK ((("provider_key" IS NULL) OR (("provider_key" = "lower"("provider_key")) AND ("provider_key" ~ '^[a-z0-9_]+$'::"text"))))
);


