    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "expires_at" timestamp with time zone NOT NULL,
    "revoked_at" timestamp with time zone,
    CONSTRAINT "wk_playlist_preview_links_expiry_check" CHECK (("expires_at" > "created_at")),
    CONSTRAINT "wk_playlist_preview_links_nonce_check" CHECK ((NULLIF("btrim"("nonce"), ''::"text") IS NOT NULL))
);


