CREATE OR REPLACE VIEW "public"."wk_publishing_workspace_items" WITH ("security_invoker"='true', "security_barrier"='true') AS
 SELECT "item"."id",
    "item"."resource_id",
    "resource"."resource_kind",
    "item"."title",
    "item"."content_kind",
    "kind"."label" AS "content_kind_label",
    "item"."brief",
    "item"."production_stage",
    "item"."planning_state",
    "editorial"."derive_publishing_editorial_state"("item"."resource_id") AS "editorial_state",
    "editorial"."derive_publishing_publication_state"("item"."id") AS "publication_state",
    "item"."priority",
    "item"."owner_id",
    COALESCE("owner_profile"."display_name", ("item"."owner_id")::"text") AS "owner_label",
    "item"."production_deadline",
    "item"."planned_publish_at",
    "item"."record_version",
    "resource"."current_working_version_id",
    "resource"."current_submitted_version_id",
    "resource"."current_approved_version_id",
    "resource"."current_published_version_id",
    COALESCE(( SELECT "jsonb_agg"("jsonb_build_object"('userId', "assignee"."user_id", 'label', COALESCE("assignee_profile"."display_name", ("assignee"."user_id")::"text"), 'role', "assignee"."assignment_role", 'assignedBy', "assignee"."assigned_by", 'createdAt', "assignee"."created_at") ORDER BY "assignee"."assignment_role", "assignee"."created_at") AS "jsonb_agg"
           FROM ("editorial"."publishing_item_assignees" "assignee"
             LEFT JOIN "public"."user_profiles" "assignee_profile" ON (("assignee_profile"."user_id" = "assignee"."user_id")))
          WHERE ("assignee"."item_id" = "item"."id")), '[]'::"jsonb") AS "assignees",
    COALESCE(( SELECT "jsonb_agg"("jsonb_build_object"('key', "item_channel"."channel_key", 'label', "channel"."label", 'isPrimary', "item_channel"."is_primary", 'createdAt', "item_channel"."created_at") ORDER BY "item_channel"."is_primary" DESC, "channel"."sort_order", "channel"."label") AS "jsonb_agg"
           FROM ("editorial"."publishing_item_channels" "item_channel"
             JOIN "editorial"."publishing_channels" "channel" ON (("channel"."channel_key" = "item_channel"."channel_key")))
          WHERE ("item_channel"."item_id" = "item"."id")), '[]'::"jsonb") AS "channels",
    "item"."created_by",
    COALESCE("creator_profile"."display_name", ("item"."created_by")::"text") AS "created_by_label",
    "item"."updated_by",
    COALESCE("updater_profile"."display_name", ("item"."updated_by")::"text") AS "updated_by_label",
    "item"."created_at",
    "item"."updated_at"
   FROM ((((("editorial"."publishing_items" "item"
     JOIN "editorial"."publishing_content_kinds" "kind" ON (("kind"."kind" = "item"."content_kind")))
     LEFT JOIN "editorial"."resources" "resource" ON (("resource"."id" = "item"."resource_id")))
     LEFT JOIN "public"."user_profiles" "owner_profile" ON (("owner_profile"."user_id" = "item"."owner_id")))
     LEFT JOIN "public"."user_profiles" "creator_profile" ON (("creator_profile"."user_id" = "item"."created_by")))
     LEFT JOIN "public"."user_profiles" "updater_profile" ON (("updater_profile"."user_id" = "item"."updated_by")));


ALTER VIEW "public"."wk_publishing_workspace_items" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."wk_resource_index" WITH ("security_invoker"='true', "security_barrier"='true') AS
 SELECT "resources"."id" AS "resource_id",
    "resources"."resource_kind",
    "article_resources"."article_id" AS "canonical_record_id",
    "canonical_alias"."path" AS "canonical_path",
    "resources"."visibility",
    "resources"."lifecycle_state",
    "resources"."created_at",
    "resources"."updated_at"
   FROM (("editorial"."resources"
     JOIN "editorial"."article_resources" ON (("article_resources"."resource_id" = "resources"."id")))
     LEFT JOIN "editorial"."resource_aliases" "canonical_alias" ON ((("canonical_alias"."resource_id" = "resources"."id") AND "canonical_alias"."is_canonical" AND ("canonical_alias"."retired_at" IS NULL))))
UNION ALL
 SELECT "resources"."id" AS "resource_id",
    "resources"."resource_kind",
    "playlist_resources"."playlist_id" AS "canonical_record_id",
    "canonical_alias"."path" AS "canonical_path",
    "resources"."visibility",
    "resources"."lifecycle_state",
    "resources"."created_at",
    "resources"."updated_at"
   FROM (("editorial"."resources"
     JOIN "editorial"."playlist_resources" ON (("playlist_resources"."resource_id" = "resources"."id")))
     LEFT JOIN "editorial"."resource_aliases" "canonical_alias" ON ((("canonical_alias"."resource_id" = "resources"."id") AND "canonical_alias"."is_canonical" AND ("canonical_alias"."retired_at" IS NULL))))
UNION ALL
 SELECT "resources"."id" AS "resource_id",
    "resources"."resource_kind",
    "registry_artist_resources"."artist_id" AS "canonical_record_id",
    "canonical_alias"."path" AS "canonical_path",
    "resources"."visibility",
    "resources"."lifecycle_state",
    "resources"."created_at",
    "resources"."updated_at"
   FROM (("editorial"."resources"
     JOIN "editorial"."registry_artist_resources" ON (("registry_artist_resources"."resource_id" = "resources"."id")))
     LEFT JOIN "editorial"."resource_aliases" "canonical_alias" ON ((("canonical_alias"."resource_id" = "resources"."id") AND "canonical_alias"."is_canonical" AND ("canonical_alias"."retired_at" IS NULL))))
UNION ALL
 SELECT "resources"."id" AS "resource_id",
    "resources"."resource_kind",
    "resources"."id" AS "canonical_record_id",
    "canonical_alias"."path" AS "canonical_path",
    "resources"."visibility",
    "resources"."lifecycle_state",
    "resources"."created_at",
    "resources"."updated_at"
   FROM ("editorial"."resources"
     LEFT JOIN "editorial"."resource_aliases" "canonical_alias" ON ((("canonical_alias"."resource_id" = "resources"."id") AND "canonical_alias"."is_canonical" AND ("canonical_alias"."retired_at" IS NULL))))
  WHERE ("resources"."resource_kind" = 'person'::"text");


ALTER VIEW "public"."wk_resource_index" OWNER TO "postgres";


COMMENT ON VIEW "public"."wk_resource_index" IS 'Narrow stable public resource reference index. Person uses Resource UUID as canonical record identity without exposing internal Person governance tables.';



CREATE OR REPLACE VIEW "public"."wk_resource_owner_index" WITH ("security_invoker"='true', "security_barrier"='true') AS
 SELECT "resources"."id" AS "resource_id",
    "resources"."resource_kind",
    "article_resources"."article_id" AS "canonical_record_id",
    "resources"."owner_id"
   FROM ("editorial"."resources"
     JOIN "editorial"."article_resources" ON (("article_resources"."resource_id" = "resources"."id")))
UNION ALL
 SELECT "resources"."id" AS "resource_id",
    "resources"."resource_kind",
    "playlist_resources"."playlist_id" AS "canonical_record_id",
    "resources"."owner_id"
   FROM ("editorial"."resources"
     JOIN "editorial"."playlist_resources" ON (("playlist_resources"."resource_id" = "resources"."id")))
UNION ALL
 SELECT "resources"."id" AS "resource_id",
    "resources"."resource_kind",
    "registry_artist_resources"."artist_id" AS "canonical_record_id",
    "resources"."owner_id"
   FROM ("editorial"."resources"
     JOIN "editorial"."registry_artist_resources" ON (("registry_artist_resources"."resource_id" = "resources"."id")))
UNION ALL
 SELECT "resources"."id" AS "resource_id",
    "resources"."resource_kind",
    "resources"."id" AS "canonical_record_id",
    "resources"."owner_id"
   FROM "editorial"."resources"
  WHERE ("resources"."resource_kind" = 'person'::"text");


ALTER VIEW "public"."wk_resource_owner_index" OWNER TO "postgres";


COMMENT ON VIEW "public"."wk_resource_owner_index" IS 'Authenticated canonical account ownership read model for resource authority checks, including Person ownership without exposing Person governance tables.';



