CREATE OR REPLACE VIEW "public"."registry_relationship_duplicate_keys" WITH ("security_invoker"='true') AS
 SELECT "r"."id" AS "relationship_id",
    "r"."source_entity_type",
    "r"."source_entity_id",
    "r"."source_slug",
    COALESCE(("r"."source_entity_id")::"text", "concat"('slug:', "r"."source_slug")) AS "source_comparison_key",
    "r"."target_entity_type",
    "r"."target_entity_id",
    "r"."target_slug",
    COALESCE(("r"."target_entity_id")::"text", "concat"('slug:', "r"."target_slug")) AS "target_comparison_key",
    "r"."relationship_type",
    "r"."relationship_role",
    "r"."relationship_status",
    "r"."review_status",
    "r"."public_safe",
    "r"."plain_reason",
    ("count"("re"."evidence_id"))::integer AS "evidence_count"
   FROM ("public"."registry_entity_relationships" "r"
     LEFT JOIN "public"."registry_relationship_evidence" "re" ON (("re"."relationship_id" = "r"."id")))
  GROUP BY "r"."id";



CREATE OR REPLACE VIEW "public"."registry_relationship_evidence_readiness_queue" WITH ("security_invoker"='true') AS
 SELECT "r"."id" AS "relationship_id",
    "r"."source_entity_type",
    "r"."source_entity_id",
    "r"."source_slug",
    "r"."target_entity_type",
    "r"."target_entity_id",
    "r"."target_slug",
    "r"."relationship_type",
    "r"."relationship_role",
    ("count"("re"."evidence_id"))::integer AS "evidence_count",
    (NULLIF("btrim"("r"."plain_reason"), ''::"text") IS NOT NULL) AS "has_plain_reason",
        CASE
            WHEN (("r"."source_entity_id" IS NULL) OR ("r"."target_entity_id" IS NULL)) THEN 'resolve_endpoints'::"text"
            WHEN ("count"("re"."evidence_id") = 0) THEN 'attach_evidence'::"text"
            WHEN (NULLIF("btrim"("r"."plain_reason"), ''::"text") IS NULL) THEN 'add_plain_reason'::"text"
            ELSE 'ready_for_review'::"text"
        END AS "evidence_work_state"
   FROM ("public"."registry_entity_relationships" "r"
     LEFT JOIN "public"."registry_relationship_evidence" "re" ON (("re"."relationship_id" = "r"."id")))
  WHERE ("r"."relationship_status" <> 'archived'::"text")
  GROUP BY "r"."id";



