CREATE POLICY "Article review participants can read comments" ON "editorial"."article_review_comments" FOR SELECT TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM "editorial"."article_review_threads" "thread"
  WHERE (("thread"."id" = "article_review_comments"."thread_id") AND "editorial"."current_user_can_participate_article_review"("thread"."resource_id")))));



CREATE POLICY "Article review participants can read suggestion events" ON "editorial"."article_suggestion_events" FOR SELECT TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM ("editorial"."article_suggestions" "suggestion"
     JOIN "editorial"."article_review_threads" "thread" ON (("thread"."id" = "suggestion"."thread_id")))
  WHERE (("suggestion"."id" = "article_suggestion_events"."suggestion_id") AND "editorial"."current_user_can_participate_article_review"("thread"."resource_id")))));



CREATE POLICY "Article review participants can read suggestions" ON "editorial"."article_suggestions" FOR SELECT TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM "editorial"."article_review_threads" "thread"
  WHERE (("thread"."id" = "article_suggestions"."thread_id") AND "editorial"."current_user_can_participate_article_review"("thread"."resource_id")))));



CREATE POLICY "Article review participants can read threads" ON "editorial"."article_review_threads" FOR SELECT TO "authenticated" USING ("editorial"."current_user_can_participate_article_review"("resource_id"));



